INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'family', 'Talk about your family. Who is in your family?', '{"te":{"word":"కుటుంబం","question":"మీ కుటుంబం గురించి మాట్లాడండి. మీ కుటుంబంలో ఎవరెవరు ఉన్నారు?","examples":[{"en":"There are four people in my family.","native":"మా కుటుంబంలో నలుగురు ఉన్నారు."},{"en":"My father is a farmer and my mother is a teacher.","native":"మా నాన్న రైతు, మా అమ్మ ఉపాధ్యాయురాలు."},{"en":"I have a younger brother and a younger sister.","native":"నాకు ఒక తమ్ముడు మరియు ఒక చెల్లెలు ఉన్నారు."}]},"hi":{"word":"परिवार","question":"अपने परिवार के बारे में बताइए। आपके परिवार में कौन-कौन है?","examples":[{"en":"There are four people in my family.","native":"मेरे परिवार में चार लोग हैं।"},{"en":"My father is a farmer and my mother is a teacher.","native":"मेरे पिता किसान हैं और मेरी माँ शिक्षिका हैं।"},{"en":"I have a younger brother and a younger sister.","native":"मेरा एक छोटा भाई और एक छोटी बहन है।"}]},"es":{"word":"familia","question":"Habla de tu familia. ¿Quiénes están en tu familia?","examples":[{"en":"There are four people in my family.","native":"En mi familia hay cuatro personas."},{"en":"My father is a farmer and my mother is a teacher.","native":"Mi padre es agricultor y mi madre es profesora."},{"en":"I have a younger brother and a younger sister.","native":"Tengo un hermano menor y una hermana menor."}]},"zh":{"word":"家庭","question":"谈谈你的家庭。你家里都有谁？","examples":[{"en":"There are four people in my family.","native":"我家有四口人。"},{"en":"My father is a farmer and my mother is a teacher.","native":"我爸爸是农民，我妈妈是老师。"},{"en":"I have a younger brother and a younger sister.","native":"我有一个弟弟和一个妹妹。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'food', 'What food do you like?', '{"te":{"word":"ఆహారం","question":"మీకు ఏ ఆహారం ఇష్టం?","examples":[{"en":"I like rice and vegetables.","native":"నాకు అన్నం మరియు కూరగాయలు ఇష్టం."},{"en":"My favourite food is chicken curry.","native":"నా ఇష్టమైన ఆహారం చికెన్ కరీ."},{"en":"I do not like very spicy food.","native":"నాకు చాలా కారమైన ఆహారం ఇష్టం లేదు."}]},"hi":{"word":"भोजन","question":"आपको कौन सा भोजन पसंद है?","examples":[{"en":"I like rice and vegetables.","native":"मुझे चावल और सब्ज़ियाँ पसंद हैं।"},{"en":"My favourite food is chicken curry.","native":"मेरा पसंदीदा भोजन चिकन करी है।"},{"en":"I do not like very spicy food.","native":"मुझे बहुत मसालेदार भोजन पसंद नहीं है।"}]},"es":{"word":"comida","question":"¿Qué comida te gusta?","examples":[{"en":"I like rice and vegetables.","native":"Me gustan el arroz y las verduras."},{"en":"My favourite food is chicken curry.","native":"Mi comida favorita es el pollo al curry."},{"en":"I do not like very spicy food.","native":"No me gusta la comida muy picante."}]},"zh":{"word":"食物","question":"你喜欢什么食物？","examples":[{"en":"I like rice and vegetables.","native":"我喜欢米饭和蔬菜。"},{"en":"My favourite food is chicken curry.","native":"我最喜欢的食物是咖喱鸡。"},{"en":"I do not like very spicy food.","native":"我不喜欢很辣的食物。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'home', 'Describe your home.', '{"te":{"word":"ఇల్లు","question":"మీ ఇంటిని వివరించండి.","examples":[{"en":"I live in a small house with my parents.","native":"నేను నా తల్లిదండ్రులతో ఒక చిన్న ఇంట్లో నివసిస్తాను."},{"en":"My home has two bedrooms and a kitchen.","native":"నా ఇంట్లో రెండు పడకగదులు మరియు ఒక వంటగది ఉన్నాయి."},{"en":"There is a small garden in front of my house.","native":"నా ఇంటి ముందు ఒక చిన్న తోట ఉంది."}]},"hi":{"word":"घर","question":"अपने घर का वर्णन कीजिए।","examples":[{"en":"I live in a small house with my parents.","native":"मैं अपने माता-पिता के साथ एक छोटे घर में रहता हूँ।"},{"en":"My home has two bedrooms and a kitchen.","native":"मेरे घर में दो शयनकक्ष और एक रसोई हैं।"},{"en":"There is a small garden in front of my house.","native":"मेरे घर के सामने एक छोटा बगीचा है।"}]},"es":{"word":"hogar","question":"Describe tu casa.","examples":[{"en":"I live in a small house with my parents.","native":"Vivo en una casa pequeña con mis padres."},{"en":"My home has two bedrooms and a kitchen.","native":"Mi casa tiene dos dormitorios y una cocina."},{"en":"There is a small garden in front of my house.","native":"Hay un jardín pequeño frente a mi casa."}]},"zh":{"word":"家","question":"描述一下你的家。","examples":[{"en":"I live in a small house with my parents.","native":"我和父母住在一所小房子里。"},{"en":"My home has two bedrooms and a kitchen.","native":"我家有两间卧室和一间厨房。"},{"en":"There is a small garden in front of my house.","native":"我家门前有一个小花园。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'friend', 'Talk about your best friend.', '{"te":{"word":"స్నేహితుడు","question":"మీ అత్యంత స్నేహితుడి గురించి మాట్లాడండి.","examples":[{"en":"My best friend is Ravi.","native":"నా అత్యంత స్నేహితుడు రవి."},{"en":"He is kind and always helps me.","native":"అతను దయగలవాడు మరియు ఎల్లప్పుడూ నాకు సహాయం చేస్తాడు."},{"en":"We play cricket together every Sunday.","native":"మేము ప్రతి ఆదివారం కలిసి క్రికెట్ ఆడుతాము."}]},"hi":{"word":"दोस्त","question":"अपने सबसे अच्छे दोस्त के बारे में बताइए।","examples":[{"en":"My best friend is Ravi.","native":"मेरा सबसे अच्छा दोस्त रवि है।"},{"en":"He is kind and always helps me.","native":"वह दयालु है और हमेशा मेरी मदद करता है।"},{"en":"We play cricket together every Sunday.","native":"हम हर रविवार साथ में क्रिकेट खेलते हैं।"}]},"es":{"word":"amigo","question":"Habla de tu mejor amigo.","examples":[{"en":"My best friend is Ravi.","native":"Mi mejor amigo es Ravi."},{"en":"He is kind and always helps me.","native":"Él es amable y siempre me ayuda."},{"en":"We play cricket together every Sunday.","native":"Jugamos al críquet juntos todos los domingos."}]},"zh":{"word":"朋友","question":"谈谈你最好的朋友。","examples":[{"en":"My best friend is Ravi.","native":"我最好的朋友是拉维。"},{"en":"He is kind and always helps me.","native":"他很友善，总是帮助我。"},{"en":"We play cricket together every Sunday.","native":"我们每个星期天一起打板球。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'day', 'What do you do every day?', '{"te":{"word":"రోజు","question":"మీరు ప్రతిరోజూ ఏమి చేస్తారు?","examples":[{"en":"I wake up at six o''clock every morning.","native":"నేను ప్రతి రోజు ఉదయం ఆరు గంటలకు నిద్ర లేస్తాను."},{"en":"I go to work by bus.","native":"నేను బస్సులో పనికి వెళ్తాను."},{"en":"In the evening, I watch television with my family.","native":"సాయంత్రం, నేను నా కుటుంబంతో కలిసి టీవీ చూస్తాను."}]},"hi":{"word":"दिन","question":"आप रोज़ क्या करते हैं?","examples":[{"en":"I wake up at six o''clock every morning.","native":"मैं हर सुबह छह बजे उठता हूँ।"},{"en":"I go to work by bus.","native":"मैं बस से काम पर जाता हूँ।"},{"en":"In the evening, I watch television with my family.","native":"शाम को, मैं अपने परिवार के साथ टीवी देखता हूँ।"}]},"es":{"word":"día","question":"¿Qué haces todos los días?","examples":[{"en":"I wake up at six o''clock every morning.","native":"Me despierto a las seis todas las mañanas."},{"en":"I go to work by bus.","native":"Voy al trabajo en autobús."},{"en":"In the evening, I watch television with my family.","native":"Por la tarde, veo la televisión con mi familia."}]},"zh":{"word":"一天","question":"你每天做什么？","examples":[{"en":"I wake up at six o''clock every morning.","native":"我每天早上六点起床。"},{"en":"I go to work by bus.","native":"我坐公交车去上班。"},{"en":"In the evening, I watch television with my family.","native":"晚上，我和家人一起看电视。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'hobby', 'What do you like to do in your free time?', '{"te":{"word":"అభిరుచి","question":"మీరు ఖాళీ సమయంలో ఏమి చేయడానికి ఇష్టపడతారు?","examples":[{"en":"I like reading books in my free time.","native":"నా ఖాళీ సమయంలో పుస్తకాలు చదవడం నాకు ఇష్టం."},{"en":"Sometimes I listen to music.","native":"కొన్నిసార్లు నేను సంగీతం వింటాను."},{"en":"My hobby is painting pictures of nature.","native":"నా అభిరుచి ప్రకృతి చిత్రాలు గీయడం."}]},"hi":{"word":"शौक","question":"आप खाली समय में क्या करना पसंद करते हैं?","examples":[{"en":"I like reading books in my free time.","native":"मुझे खाली समय में किताबें पढ़ना पसंद है।"},{"en":"Sometimes I listen to music.","native":"कभी-कभी मैं संगीत सुनता हूँ।"},{"en":"My hobby is painting pictures of nature.","native":"मेरा शौक प्रकृति के चित्र बनाना है।"}]},"es":{"word":"pasatiempo","question":"¿Qué te gusta hacer en tu tiempo libre?","examples":[{"en":"I like reading books in my free time.","native":"Me gusta leer libros en mi tiempo libre."},{"en":"Sometimes I listen to music.","native":"A veces escucho música."},{"en":"My hobby is painting pictures of nature.","native":"Mi pasatiempo es pintar cuadros de la naturaleza."}]},"zh":{"word":"爱好","question":"你空闲时喜欢做什么？","examples":[{"en":"I like reading books in my free time.","native":"我空闲时喜欢读书。"},{"en":"Sometimes I listen to music.","native":"有时我听音乐。"},{"en":"My hobby is painting pictures of nature.","native":"我的爱好是画自然风景。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'morning', 'Talk about your morning. What do you do every morning?', '{"te":{"word":"ఉదయం","question":"మీ ఉదయం గురించి మాట్లాడండి. మీరు ప్రతి ఉదయం ఏమి చేస్తారు?","examples":[{"en":"I wake up at six o''clock every day.","native":"నేను ప్రతిరోజూ ఆరు గంటలకు లేస్తాను."},{"en":"I brush my teeth and wash my face.","native":"నేను పళ్లు తోముకుని ముఖం కడుక్కుంటాను."},{"en":"Then I eat breakfast with my family.","native":"తర్వాత నేను నా కుటుంబంతో అల్పాహారం తింటాను."}]},"hi":{"word":"सुबह","question":"अपनी सुबह के बारे में बताइए। आप हर सुबह क्या करते हैं?","examples":[{"en":"I wake up at six o''clock every day.","native":"मैं रोज़ छह बजे उठता हूँ।"},{"en":"I brush my teeth and wash my face.","native":"मैं दाँत साफ़ करता हूँ और चेहरा धोता हूँ।"},{"en":"Then I eat breakfast with my family.","native":"फिर मैं अपने परिवार के साथ नाश्ता खाता हूँ।"}]},"es":{"word":"mañana","question":"Habla de tu mañana. ¿Qué haces cada mañana?","examples":[{"en":"I wake up at six o''clock every day.","native":"Me despierto a las seis todos los días."},{"en":"I brush my teeth and wash my face.","native":"Me cepillo los dientes y me lavo la cara."},{"en":"Then I eat breakfast with my family.","native":"Luego desayuno con mi familia."}]},"zh":{"word":"早晨","question":"谈谈你的早晨。你每天早上做什么？","examples":[{"en":"I wake up at six o''clock every day.","native":"我每天六点起床。"},{"en":"I brush my teeth and wash my face.","native":"我刷牙洗脸。"},{"en":"Then I eat breakfast with my family.","native":"然后我和家人一起吃早餐。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'evening', 'What do you do in the evening?', '{"te":{"word":"సాయంత్రం","question":"మీరు సాయంత్రం ఏమి చేస్తారు?","examples":[{"en":"I come home at five o''clock.","native":"నేను ఐదు గంటలకు ఇంటికి వస్తాను."},{"en":"I drink tea with my mother.","native":"నేను నా అమ్మతో టీ తాగుతాను."},{"en":"We eat dinner together at eight.","native":"మేము ఎనిమిది గంటలకు కలిసి రాత్రి భోజనం చేస్తాము."}]},"hi":{"word":"शाम","question":"आप शाम को क्या करते हैं?","examples":[{"en":"I come home at five o''clock.","native":"मैं पाँच बजे घर आता हूँ।"},{"en":"I drink tea with my mother.","native":"मैं अपनी माँ के साथ चाय पीता हूँ।"},{"en":"We eat dinner together at eight.","native":"हम आठ बजे साथ में रात का खाना खाते हैं।"}]},"es":{"word":"tarde","question":"¿Qué haces por la tarde?","examples":[{"en":"I come home at five o''clock.","native":"Llego a casa a las cinco."},{"en":"I drink tea with my mother.","native":"Tomo té con mi madre."},{"en":"We eat dinner together at eight.","native":"Cenamos juntos a las ocho."}]},"zh":{"word":"傍晚","question":"你傍晚做什么？","examples":[{"en":"I come home at five o''clock.","native":"我五点回家。"},{"en":"I drink tea with my mother.","native":"我和妈妈一起喝茶。"},{"en":"We eat dinner together at eight.","native":"我们八点一起吃晚饭。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'night', 'Talk about your night. When do you go to bed?', '{"te":{"word":"రాత్రి","question":"మీ రాత్రి గురించి మాట్లాడండి. మీరు ఎప్పుడు పడుకుంటారు?","examples":[{"en":"I go to bed at ten o''clock.","native":"నేను పది గంటలకు పడుకుంటాను."},{"en":"I read a book before I sleep.","native":"నేను నిద్రపోయే ముందు పుస్తకం చదువుతాను."},{"en":"My family sleeps early at night.","native":"నా కుటుంబం రాత్రి త్వరగా పడుకుంటుంది."}]},"hi":{"word":"रात","question":"अपनी रात के बारे में बताइए। आप कब सोते हैं?","examples":[{"en":"I go to bed at ten o''clock.","native":"मैं दस बजे सोता हूँ।"},{"en":"I read a book before I sleep.","native":"मैं सोने से पहले किताब पढ़ता हूँ।"},{"en":"My family sleeps early at night.","native":"मेरा परिवार रात में जल्दी सोता है।"}]},"es":{"word":"noche","question":"Habla de tu noche. ¿Cuándo te acuestas?","examples":[{"en":"I go to bed at ten o''clock.","native":"Me acuesto a las diez."},{"en":"I read a book before I sleep.","native":"Leo un libro antes de dormir."},{"en":"My family sleeps early at night.","native":"Mi familia duerme temprano por la noche."}]},"zh":{"word":"夜晚","question":"谈谈你的夜晚。你什么时候睡觉？","examples":[{"en":"I go to bed at ten o''clock.","native":"我十点睡觉。"},{"en":"I read a book before I sleep.","native":"我睡前看书。"},{"en":"My family sleeps early at night.","native":"我家人晚上睡得早。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'breakfast', 'What do you eat for breakfast?', '{"te":{"word":"అల్పాహారం","question":"మీరు అల్పాహారంగా ఏమి తింటారు?","examples":[{"en":"I eat bread and eggs for breakfast.","native":"నేను అల్పాహారంగా బ్రెడ్ మరియు గుడ్లు తింటాను."},{"en":"My mother makes breakfast every morning.","native":"నా అమ్మ ప్రతి ఉదయం అల్పాహారం తయారు చేస్తుంది."},{"en":"I drink a glass of milk.","native":"నేను ఒక గ్లాసు పాలు తాగుతాను."}]},"hi":{"word":"नाश्ता","question":"आप नाश्ते में क्या खाते हैं?","examples":[{"en":"I eat bread and eggs for breakfast.","native":"मैं नाश्ते में ब्रेड और अंडे खाता हूँ।"},{"en":"My mother makes breakfast every morning.","native":"मेरी माँ हर सुबह नाश्ता बनाती हैं।"},{"en":"I drink a glass of milk.","native":"मैं एक गिलास दूध पीता हूँ।"}]},"es":{"word":"desayuno","question":"¿Qué desayunas?","examples":[{"en":"I eat bread and eggs for breakfast.","native":"Desayuno pan y huevos."},{"en":"My mother makes breakfast every morning.","native":"Mi madre prepara el desayuno cada mañana."},{"en":"I drink a glass of milk.","native":"Bebo un vaso de leche."}]},"zh":{"word":"早餐","question":"你早餐吃什么？","examples":[{"en":"I eat bread and eggs for breakfast.","native":"我早餐吃面包和鸡蛋。"},{"en":"My mother makes breakfast every morning.","native":"我妈妈每天早上做早餐。"},{"en":"I drink a glass of milk.","native":"我喝一杯牛奶。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'lunch', 'What do you eat for lunch?', '{"te":{"word":"మధ్యాహ్న భోజనం","question":"మీరు మధ్యాహ్న భోజనంగా ఏమి తింటారు?","examples":[{"en":"I eat rice and vegetables for lunch.","native":"నేను మధ్యాహ్న భోజనంగా అన్నం మరియు కూరగాయలు తింటాను."},{"en":"I have lunch at one o''clock.","native":"నేను ఒకటి గంటలకు మధ్యాహ్న భోజనం చేస్తాను."},{"en":"I eat lunch with my friends.","native":"నేను నా స్నేహితులతో మధ్యాహ్న భోజనం తింటాను."}]},"hi":{"word":"दोपहर का भोजन","question":"आप दोपहर के भोजन में क्या खाते हैं?","examples":[{"en":"I eat rice and vegetables for lunch.","native":"मैं दोपहर के भोजन में चावल और सब्ज़ियाँ खाता हूँ।"},{"en":"I have lunch at one o''clock.","native":"मैं एक बजे दोपहर का भोजन करता हूँ।"},{"en":"I eat lunch with my friends.","native":"मैं अपने दोस्तों के साथ दोपहर का भोजन खाता हूँ।"}]},"es":{"word":"almuerzo","question":"¿Qué almuerzas?","examples":[{"en":"I eat rice and vegetables for lunch.","native":"Almuerzo arroz y verduras."},{"en":"I have lunch at one o''clock.","native":"Almuerzo a la una."},{"en":"I eat lunch with my friends.","native":"Almuerzo con mis amigos."}]},"zh":{"word":"午餐","question":"你午餐吃什么？","examples":[{"en":"I eat rice and vegetables for lunch.","native":"我午餐吃米饭和蔬菜。"},{"en":"I have lunch at one o''clock.","native":"我一点吃午饭。"},{"en":"I eat lunch with my friends.","native":"我和朋友们一起吃午饭。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'dinner', 'Talk about your dinner. What do you eat?', '{"te":{"word":"రాత్రి భోజనం","question":"మీ రాత్రి భోజనం గురించి మాట్లాడండి. మీరు ఏమి తింటారు?","examples":[{"en":"We eat dinner at eight o''clock.","native":"మేము ఎనిమిది గంటలకు రాత్రి భోజనం చేస్తాము."},{"en":"I like soup and bread for dinner.","native":"రాత్రి భోజనంగా నాకు సూప్ మరియు బ్రెడ్ ఇష్టం."},{"en":"My family eats dinner together.","native":"నా కుటుంబం కలిసి రాత్రి భోజనం చేస్తుంది."}]},"hi":{"word":"रात का खाना","question":"अपने रात के खाने के बारे में बताइए। आप क्या खाते हैं?","examples":[{"en":"We eat dinner at eight o''clock.","native":"हम आठ बजे रात का खाना खाते हैं।"},{"en":"I like soup and bread for dinner.","native":"मुझे रात के खाने में सूप और ब्रेड पसंद है।"},{"en":"My family eats dinner together.","native":"मेरा परिवार साथ में रात का खाना खाता है।"}]},"es":{"word":"cena","question":"Habla de tu cena. ¿Qué cenas?","examples":[{"en":"We eat dinner at eight o''clock.","native":"Cenamos a las ocho."},{"en":"I like soup and bread for dinner.","native":"Me gusta la sopa y el pan para la cena."},{"en":"My family eats dinner together.","native":"Mi familia cena junta."}]},"zh":{"word":"晚餐","question":"谈谈你的晚餐。你吃什么？","examples":[{"en":"We eat dinner at eight o''clock.","native":"我们八点吃晚饭。"},{"en":"I like soup and bread for dinner.","native":"我晚餐喜欢喝汤、吃面包。"},{"en":"My family eats dinner together.","native":"我家人一起吃晚饭。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'water', 'Do you drink enough water every day?', '{"te":{"word":"నీరు","question":"మీరు ప్రతిరోజూ తగినంత నీరు తాగుతారా?","examples":[{"en":"I drink eight glasses of water every day.","native":"నేను ప్రతిరోజూ ఎనిమిది గ్లాసుల నీరు తాగుతాను."},{"en":"I carry a water bottle to class.","native":"నేను తరగతికి నీటి బాటిల్ తీసుకువెళ్తాను."},{"en":"Cold water is good on hot days.","native":"వేడి రోజుల్లో చల్లని నీరు మంచిది."}]},"hi":{"word":"पानी","question":"क्या आप रोज़ पर्याप्त पानी पीते हैं?","examples":[{"en":"I drink eight glasses of water every day.","native":"मैं रोज़ आठ गिलास पानी पीता हूँ।"},{"en":"I carry a water bottle to class.","native":"मैं कक्षा में पानी की बोतल ले जाता हूँ।"},{"en":"Cold water is good on hot days.","native":"गर्म दिनों में ठंडा पानी अच्छा होता है।"}]},"es":{"word":"agua","question":"¿Bebes suficiente agua todos los días?","examples":[{"en":"I drink eight glasses of water every day.","native":"Bebo ocho vasos de agua todos los días."},{"en":"I carry a water bottle to class.","native":"Llevo una botella de agua a clase."},{"en":"Cold water is good on hot days.","native":"El agua fría es buena en días calurosos."}]},"zh":{"word":"水","question":"你每天喝足够的水吗？","examples":[{"en":"I drink eight glasses of water every day.","native":"我每天喝八杯水。"},{"en":"I carry a water bottle to class.","native":"我带水瓶去上课。"},{"en":"Cold water is good on hot days.","native":"热天喝凉水很好。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'milk', 'Do you like milk? When do you drink it?', '{"te":{"word":"పాలు","question":"మీకు పాలు ఇష్టమా? మీరు ఎప్పుడు తాగుతారు?","examples":[{"en":"I drink a glass of milk every morning.","native":"నేను ప్రతి ఉదయం ఒక గ్లాసు పాలు తాగుతాను."},{"en":"My little sister likes warm milk.","native":"నా చిన్న చెల్లెలకు వెచ్చని పాలు ఇష్టం."},{"en":"We buy milk from the shop.","native":"మేము దుకాణం నుండి పాలు కొంటాము."}]},"hi":{"word":"दूध","question":"क्या आपको दूध पसंद है? आप इसे कब पीते हैं?","examples":[{"en":"I drink a glass of milk every morning.","native":"मैं हर सुबह एक गिलास दूध पीता हूँ।"},{"en":"My little sister likes warm milk.","native":"मेरी छोटी बहन को गर्म दूध पसंद है।"},{"en":"We buy milk from the shop.","native":"हम दुकान से दूध खरीदते हैं।"}]},"es":{"word":"leche","question":"¿Te gusta la leche? ¿Cuándo la bebes?","examples":[{"en":"I drink a glass of milk every morning.","native":"Bebo un vaso de leche cada mañana."},{"en":"My little sister likes warm milk.","native":"A mi hermana pequeña le gusta la leche caliente."},{"en":"We buy milk from the shop.","native":"Compramos leche en la tienda."}]},"zh":{"word":"牛奶","question":"你喜欢牛奶吗？你什么时候喝？","examples":[{"en":"I drink a glass of milk every morning.","native":"我每天早上喝一杯牛奶。"},{"en":"My little sister likes warm milk.","native":"我妹妹喜欢喝热牛奶。"},{"en":"We buy milk from the shop.","native":"我们从商店买牛奶。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'tea', 'Talk about tea. Do you drink tea?', '{"te":{"word":"టీ","question":"టీ గురించి మాట్లాడండి. మీరు టీ తాగుతారా?","examples":[{"en":"My father drinks tea every morning.","native":"నా నాన్న ప్రతి ఉదయం టీ తాగుతారు."},{"en":"I like tea with milk and sugar.","native":"నాకు పాలు, చక్కెర కలిపిన టీ ఇష్టం."},{"en":"We make tea for our guests.","native":"మేము మా అతిథుల కోసం టీ తయారు చేస్తాము."}]},"hi":{"word":"चाय","question":"चाय के बारे में बताइए। क्या आप चाय पीते हैं?","examples":[{"en":"My father drinks tea every morning.","native":"मेरे पिता हर सुबह चाय पीते हैं।"},{"en":"I like tea with milk and sugar.","native":"मुझे दूध और चीनी वाली चाय पसंद है।"},{"en":"We make tea for our guests.","native":"हम अपने मेहमानों के लिए चाय बनाते हैं।"}]},"es":{"word":"té","question":"Habla del té. ¿Bebes té?","examples":[{"en":"My father drinks tea every morning.","native":"Mi padre bebe té cada mañana."},{"en":"I like tea with milk and sugar.","native":"Me gusta el té con leche y azúcar."},{"en":"We make tea for our guests.","native":"Preparamos té para nuestros invitados."}]},"zh":{"word":"茶","question":"谈谈茶。你喝茶吗？","examples":[{"en":"My father drinks tea every morning.","native":"我爸爸每天早上喝茶。"},{"en":"I like tea with milk and sugar.","native":"我喜欢加牛奶和糖的茶。"},{"en":"We make tea for our guests.","native":"我们为客人泡茶。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'coffee', 'Do you like coffee? Why or why not?', '{"te":{"word":"కాఫీ","question":"మీకు కాఫీ ఇష్టమా? ఎందుకు లేదా ఎందుకు కాదు?","examples":[{"en":"I drink coffee in the morning.","native":"నేను ఉదయం కాఫీ తాగుతాను."},{"en":"My mother does not drink coffee.","native":"నా అమ్మ కాఫీ తాగదు."},{"en":"This coffee is hot and sweet.","native":"ఈ కాఫీ వేడిగా మరియు తీపిగా ఉంది."}]},"hi":{"word":"कॉफ़ी","question":"क्या आपको कॉफ़ी पसंद है? क्यों या क्यों नहीं?","examples":[{"en":"I drink coffee in the morning.","native":"मैं सुबह कॉफ़ी पीता हूँ।"},{"en":"My mother does not drink coffee.","native":"मेरी माँ कॉफ़ी नहीं पीतीं।"},{"en":"This coffee is hot and sweet.","native":"यह कॉफ़ी गर्म और मीठी है।"}]},"es":{"word":"café","question":"¿Te gusta el café? ¿Por qué sí o por qué no?","examples":[{"en":"I drink coffee in the morning.","native":"Bebo café por la mañana."},{"en":"My mother does not drink coffee.","native":"Mi madre no bebe café."},{"en":"This coffee is hot and sweet.","native":"Este café está caliente y dulce."}]},"zh":{"word":"咖啡","question":"你喜欢咖啡吗？为什么喜欢或不喜欢？","examples":[{"en":"I drink coffee in the morning.","native":"我早上喝咖啡。"},{"en":"My mother does not drink coffee.","native":"我妈妈不喝咖啡。"},{"en":"This coffee is hot and sweet.","native":"这咖啡又热又甜。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'juice', 'What juice do you like?', '{"te":{"word":"జ్యూస్","question":"మీకు ఏ జ్యూస్ ఇష్టం?","examples":[{"en":"I like orange juice very much.","native":"నాకు ఆరెంజ్ జ్యూస్ చాలా ఇష్టం."},{"en":"My mother makes fresh juice at home.","native":"నా అమ్మ ఇంట్లో తాజా జ్యూస్ తయారు చేస్తుంది."},{"en":"We drink juice after lunch.","native":"మేము మధ్యాహ్న భోజనం తర్వాత జ్యూస్ తాగుతాము."}]},"hi":{"word":"जूस","question":"आपको कौन सा जूस पसंद है?","examples":[{"en":"I like orange juice very much.","native":"मुझे संतरे का जूस बहुत पसंद है।"},{"en":"My mother makes fresh juice at home.","native":"मेरी माँ घर पर ताज़ा जूस बनाती हैं।"},{"en":"We drink juice after lunch.","native":"हम दोपहर के भोजन के बाद जूस पीते हैं।"}]},"es":{"word":"zumo","question":"¿Qué zumo te gusta?","examples":[{"en":"I like orange juice very much.","native":"Me gusta mucho el zumo de naranja."},{"en":"My mother makes fresh juice at home.","native":"Mi madre hace zumo fresco en casa."},{"en":"We drink juice after lunch.","native":"Bebemos zumo después del almuerzo."}]},"zh":{"word":"果汁","question":"你喜欢什么果汁？","examples":[{"en":"I like orange juice very much.","native":"我非常喜欢橙汁。"},{"en":"My mother makes fresh juice at home.","native":"我妈妈在家做新鲜果汁。"},{"en":"We drink juice after lunch.","native":"我们午饭后喝果汁。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'fruit', 'What fruit do you like?', '{"te":{"word":"పండు","question":"మీకు ఏ పండు ఇష్టం?","examples":[{"en":"I like mangoes and bananas.","native":"నాకు మామిడి పండ్లు మరియు అరటి పండ్లు ఇష్టం."},{"en":"Fruit is good for our health.","native":"పండ్లు మన ఆరోగ్యానికి మంచివి."},{"en":"We buy fruit at the market.","native":"మేము మార్కెట్లో పండ్లు కొంటాము."}]},"hi":{"word":"फल","question":"आपको कौन सा फल पसंद है?","examples":[{"en":"I like mangoes and bananas.","native":"मुझे आम और केले पसंद हैं।"},{"en":"Fruit is good for our health.","native":"फल हमारे स्वास्थ्य के लिए अच्छा होता है।"},{"en":"We buy fruit at the market.","native":"हम बाज़ार से फल खरीदते हैं।"}]},"es":{"word":"fruta","question":"¿Qué fruta te gusta?","examples":[{"en":"I like mangoes and bananas.","native":"Me gustan los mangos y los plátanos."},{"en":"Fruit is good for our health.","native":"La fruta es buena para nuestra salud."},{"en":"We buy fruit at the market.","native":"Compramos fruta en el mercado."}]},"zh":{"word":"水果","question":"你喜欢什么水果？","examples":[{"en":"I like mangoes and bananas.","native":"我喜欢芒果和香蕉。"},{"en":"Fruit is good for our health.","native":"水果对我们的健康有好处。"},{"en":"We buy fruit at the market.","native":"我们在市场买水果。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'apple', 'Do you like apples? Why?', '{"te":{"word":"యాపిల్","question":"మీకు యాపిల్ పండ్లు ఇష్టమా? ఎందుకు?","examples":[{"en":"I eat an apple every day.","native":"నేను ప్రతిరోజూ ఒక యాపిల్ తింటాను."},{"en":"The red apple is sweet.","native":"ఎర్రటి యాపిల్ తీపిగా ఉంటుంది."},{"en":"My brother likes green apples.","native":"నా తమ్ముడికి ఆకుపచ్చ యాపిల్స్ ఇష్టం."}]},"hi":{"word":"सेब","question":"क्या आपको सेब पसंद हैं? क्यों?","examples":[{"en":"I eat an apple every day.","native":"मैं रोज़ एक सेब खाता हूँ।"},{"en":"The red apple is sweet.","native":"लाल सेब मीठा होता है।"},{"en":"My brother likes green apples.","native":"मेरे भाई को हरे सेब पसंद हैं।"}]},"es":{"word":"manzana","question":"¿Te gustan las manzanas? ¿Por qué?","examples":[{"en":"I eat an apple every day.","native":"Como una manzana todos los días."},{"en":"The red apple is sweet.","native":"La manzana roja es dulce."},{"en":"My brother likes green apples.","native":"A mi hermano le gustan las manzanas verdes."}]},"zh":{"word":"苹果","question":"你喜欢苹果吗？为什么？","examples":[{"en":"I eat an apple every day.","native":"我每天吃一个苹果。"},{"en":"The red apple is sweet.","native":"红苹果很甜。"},{"en":"My brother likes green apples.","native":"我哥哥喜欢青苹果。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'banana', 'Talk about bananas. Do you eat them often?', '{"te":{"word":"అరటి పండు","question":"అరటి పండ్ల గురించి మాట్లాడండి. మీరు వాటిని తరచుగా తింటారా?","examples":[{"en":"Bananas are yellow and sweet.","native":"అరటి పండ్లు పసుపు రంగులో మరియు తీపిగా ఉంటాయి."},{"en":"I eat a banana after lunch.","native":"నేను మధ్యాహ్న భోజనం తర్వాత అరటి పండు తింటాను."},{"en":"Monkeys like to eat bananas.","native":"కోతులు అరటి పండ్లు తినడానికి ఇష్టపడతాయి."}]},"hi":{"word":"केला","question":"केलों के बारे में बताइए। क्या आप उन्हें अक्सर खाते हैं?","examples":[{"en":"Bananas are yellow and sweet.","native":"केले पीले और मीठे होते हैं।"},{"en":"I eat a banana after lunch.","native":"मैं दोपहर के भोजन के बाद एक केला खाता हूँ।"},{"en":"Monkeys like to eat bananas.","native":"बंदरों को केले खाना पसंद है।"}]},"es":{"word":"plátano","question":"Habla de los plátanos. ¿Los comes a menudo?","examples":[{"en":"Bananas are yellow and sweet.","native":"Los plátanos son amarillos y dulces."},{"en":"I eat a banana after lunch.","native":"Como un plátano después del almuerzo."},{"en":"Monkeys like to eat bananas.","native":"A los monos les gusta comer plátanos."}]},"zh":{"word":"香蕉","question":"谈谈香蕉。你经常吃吗？","examples":[{"en":"Bananas are yellow and sweet.","native":"香蕉又黄又甜。"},{"en":"I eat a banana after lunch.","native":"我午饭后吃一根香蕉。"},{"en":"Monkeys like to eat bananas.","native":"猴子喜欢吃香蕉。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'mango', 'Do you like mangoes? When do you eat them?', '{"te":{"word":"మామిడి పండు","question":"మీకు మామిడి పండ్లు ఇష్టమా? మీరు వాటిని ఎప్పుడు తింటారు?","examples":[{"en":"The mango is my favourite fruit.","native":"మామిడి పండు నా ఇష్టమైన పండు."},{"en":"We eat mangoes in summer.","native":"మేము వేసవిలో మామిడి పండ్లు తింటాము."},{"en":"My grandfather has a mango tree.","native":"నా తాతయ్యకు ఒక మామిడి చెట్టు ఉంది."}]},"hi":{"word":"आम","question":"क्या आपको आम पसंद हैं? आप उन्हें कब खाते हैं?","examples":[{"en":"The mango is my favourite fruit.","native":"आम मेरा पसंदीदा फल है।"},{"en":"We eat mangoes in summer.","native":"हम गर्मियों में आम खाते हैं।"},{"en":"My grandfather has a mango tree.","native":"मेरे दादा के पास एक आम का पेड़ है।"}]},"es":{"word":"mango","question":"¿Te gustan los mangos? ¿Cuándo los comes?","examples":[{"en":"The mango is my favourite fruit.","native":"El mango es mi fruta favorita."},{"en":"We eat mangoes in summer.","native":"Comemos mangos en verano."},{"en":"My grandfather has a mango tree.","native":"Mi abuelo tiene un árbol de mango."}]},"zh":{"word":"芒果","question":"你喜欢芒果吗？你什么时候吃？","examples":[{"en":"The mango is my favourite fruit.","native":"芒果是我最喜欢的水果。"},{"en":"We eat mangoes in summer.","native":"我们夏天吃芒果。"},{"en":"My grandfather has a mango tree.","native":"我爷爷有一棵芒果树。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'orange', 'Do you like oranges?', '{"te":{"word":"ఆరెంజ్","question":"మీకు ఆరెంజ్ పండ్లు ఇష్టమా?","examples":[{"en":"I like sweet oranges.","native":"నాకు తీపి ఆరెంజ్ పండ్లు ఇష్టం."},{"en":"An orange has a lot of juice.","native":"ఆరెంజ్ పండులో చాలా రసం ఉంటుంది."},{"en":"She eats an orange every morning.","native":"ఆమె ప్రతి ఉదయం ఒక ఆరెంజ్ తింటుంది."}]},"hi":{"word":"संतरा","question":"क्या आपको संतरे पसंद हैं?","examples":[{"en":"I like sweet oranges.","native":"मुझे मीठे संतरे पसंद हैं।"},{"en":"An orange has a lot of juice.","native":"संतरे में बहुत रस होता है।"},{"en":"She eats an orange every morning.","native":"वह हर सुबह एक संतरा खाती है।"}]},"es":{"word":"naranja","question":"¿Te gustan las naranjas?","examples":[{"en":"I like sweet oranges.","native":"Me gustan las naranjas dulces."},{"en":"An orange has a lot of juice.","native":"Una naranja tiene mucho zumo."},{"en":"She eats an orange every morning.","native":"Ella come una naranja cada mañana."}]},"zh":{"word":"橙子","question":"你喜欢橙子吗？","examples":[{"en":"I like sweet oranges.","native":"我喜欢甜橙子。"},{"en":"An orange has a lot of juice.","native":"橙子有很多汁。"},{"en":"She eats an orange every morning.","native":"她每天早上吃一个橙子。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'vegetable', 'What vegetables do you like?', '{"te":{"word":"కూరగాయ","question":"మీకు ఏ కూరగాయలు ఇష్టం?","examples":[{"en":"I like carrots and beans.","native":"నాకు క్యారెట్లు మరియు బీన్స్ ఇష్టం."},{"en":"My mother cooks fresh vegetables.","native":"నా అమ్మ తాజా కూరగాయలు వంటుంది."},{"en":"Vegetables are good for us.","native":"కూరగాయలు మనకు మంచివి."}]},"hi":{"word":"सब्ज़ी","question":"आपको कौन सी सब्ज़ियाँ पसंद हैं?","examples":[{"en":"I like carrots and beans.","native":"मुझे गाजर और बीन्स पसंद हैं।"},{"en":"My mother cooks fresh vegetables.","native":"मेरी माँ ताज़ी सब्ज़ियाँ पकाती हैं।"},{"en":"Vegetables are good for us.","native":"सब्ज़ियाँ हमारे लिए अच्छी होती हैं।"}]},"es":{"word":"verdura","question":"¿Qué verduras te gustan?","examples":[{"en":"I like carrots and beans.","native":"Me gustan las zanahorias y las judías."},{"en":"My mother cooks fresh vegetables.","native":"Mi madre cocina verduras frescas."},{"en":"Vegetables are good for us.","native":"Las verduras son buenas para nosotros."}]},"zh":{"word":"蔬菜","question":"你喜欢什么蔬菜？","examples":[{"en":"I like carrots and beans.","native":"我喜欢胡萝卜和豆角。"},{"en":"My mother cooks fresh vegetables.","native":"我妈妈做新鲜的蔬菜。"},{"en":"Vegetables are good for us.","native":"蔬菜对我们有好处。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'rice', 'Do you eat rice every day?', '{"te":{"word":"అన్నం","question":"మీరు ప్రతిరోజూ అన్నం తింటారా?","examples":[{"en":"I eat rice with curry every day.","native":"నేను ప్రతిరోజూ కూరతో అన్నం తింటాను."},{"en":"Rice grows in the fields.","native":"వరి పొలాల్లో పెరుగుతుంది."},{"en":"My grandmother cooks tasty rice.","native":"నా అమ్మమ్మ రుచికరమైన అన్నం వంటుంది."}]},"hi":{"word":"चावल","question":"क्या आप रोज़ चावल खाते हैं?","examples":[{"en":"I eat rice with curry every day.","native":"मैं रोज़ करी के साथ चावल खाता हूँ।"},{"en":"Rice grows in the fields.","native":"चावल खेतों में उगता है।"},{"en":"My grandmother cooks tasty rice.","native":"मेरी दादी स्वादिष्ट चावल पकाती हैं।"}]},"es":{"word":"arroz","question":"¿Comes arroz todos los días?","examples":[{"en":"I eat rice with curry every day.","native":"Como arroz con curry todos los días."},{"en":"Rice grows in the fields.","native":"El arroz crece en los campos."},{"en":"My grandmother cooks tasty rice.","native":"Mi abuela cocina arroz sabroso."}]},"zh":{"word":"米饭","question":"你每天吃米饭吗？","examples":[{"en":"I eat rice with curry every day.","native":"我每天吃米饭配咖喱。"},{"en":"Rice grows in the fields.","native":"水稻长在田里。"},{"en":"My grandmother cooks tasty rice.","native":"我奶奶做的米饭很好吃。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'bread', 'Talk about bread. When do you eat it?', '{"te":{"word":"బ్రెడ్","question":"బ్రెడ్ గురించి మాట్లాడండి. మీరు దానిని ఎప్పుడు తింటారు?","examples":[{"en":"I eat bread with butter for breakfast.","native":"నేను అల్పాహారంగా వెన్నతో బ్రెడ్ తింటాను."},{"en":"We buy bread from the bakery.","native":"మేము బేకరీ నుండి బ్రెడ్ కొంటాము."},{"en":"This bread is soft and fresh.","native":"ఈ బ్రెడ్ మెత్తగా మరియు తాజాగా ఉంది."}]},"hi":{"word":"ब्रेड","question":"ब्रेड के बारे में बताइए। आप इसे कब खाते हैं?","examples":[{"en":"I eat bread with butter for breakfast.","native":"मैं नाश्ते में मक्खन के साथ ब्रेड खाता हूँ।"},{"en":"We buy bread from the bakery.","native":"हम बेकरी से ब्रेड खरीदते हैं।"},{"en":"This bread is soft and fresh.","native":"यह ब्रेड नरम और ताज़ा है।"}]},"es":{"word":"pan","question":"Habla del pan. ¿Cuándo lo comes?","examples":[{"en":"I eat bread with butter for breakfast.","native":"Desayuno pan con mantequilla."},{"en":"We buy bread from the bakery.","native":"Compramos pan en la panadería."},{"en":"This bread is soft and fresh.","native":"Este pan es blando y fresco."}]},"zh":{"word":"面包","question":"谈谈面包。你什么时候吃？","examples":[{"en":"I eat bread with butter for breakfast.","native":"我早餐吃黄油面包。"},{"en":"We buy bread from the bakery.","native":"我们从面包店买面包。"},{"en":"This bread is soft and fresh.","native":"这个面包又软又新鲜。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'egg', 'Do you like eggs? How do you eat them?', '{"te":{"word":"గుడ్డు","question":"మీకు గుడ్లు ఇష్టమా? మీరు వాటిని ఎలా తింటారు?","examples":[{"en":"I eat two boiled eggs for breakfast.","native":"నేను అల్పాహారంగా రెండు ఉడికించిన గుడ్లు తింటాను."},{"en":"My mother makes an egg curry.","native":"నా అమ్మ గుడ్ల కూర తయారు చేస్తుంది."},{"en":"Eggs are good for children.","native":"గుడ్లు పిల్లలకు మంచివి."}]},"hi":{"word":"अंडा","question":"क्या आपको अंडे पसंद हैं? आप उन्हें कैसे खाते हैं?","examples":[{"en":"I eat two boiled eggs for breakfast.","native":"मैं नाश्ते में दो उबले अंडे खाता हूँ।"},{"en":"My mother makes an egg curry.","native":"मेरी माँ अंडे की करी बनाती हैं।"},{"en":"Eggs are good for children.","native":"अंडे बच्चों के लिए अच्छे होते हैं।"}]},"es":{"word":"huevo","question":"¿Te gustan los huevos? ¿Cómo los comes?","examples":[{"en":"I eat two boiled eggs for breakfast.","native":"Desayuno dos huevos cocidos."},{"en":"My mother makes an egg curry.","native":"Mi madre hace un curry de huevo."},{"en":"Eggs are good for children.","native":"Los huevos son buenos para los niños."}]},"zh":{"word":"鸡蛋","question":"你喜欢鸡蛋吗？你怎么吃？","examples":[{"en":"I eat two boiled eggs for breakfast.","native":"我早餐吃两个煮鸡蛋。"},{"en":"My mother makes an egg curry.","native":"我妈妈做鸡蛋咖喱。"},{"en":"Eggs are good for children.","native":"鸡蛋对孩子有好处。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'sugar', 'Do you like sugar in your tea?', '{"te":{"word":"చక్కెర","question":"మీ టీలో చక్కెర ఇష్టమా?","examples":[{"en":"I like one spoon of sugar in my tea.","native":"నా టీలో ఒక స్పూన్ చక్కెర ఇష్టం."},{"en":"Sugar makes food sweet.","native":"చక్కెర ఆహారాన్ని తీపిగా చేస్తుంది."},{"en":"We keep sugar in a box.","native":"మేము చక్కెరను ఒక డబ్బాలో ఉంచుతాము."}]},"hi":{"word":"चीनी","question":"क्या आपको अपनी चाय में चीनी पसंद है?","examples":[{"en":"I like one spoon of sugar in my tea.","native":"मुझे अपनी चाय में एक चम्मच चीनी पसंद है।"},{"en":"Sugar makes food sweet.","native":"चीनी खाने को मीठा बनाती है।"},{"en":"We keep sugar in a box.","native":"हम चीनी एक डिब्बे में रखते हैं।"}]},"es":{"word":"azúcar","question":"¿Te gusta el azúcar en tu té?","examples":[{"en":"I like one spoon of sugar in my tea.","native":"Me gusta una cucharada de azúcar en mi té."},{"en":"Sugar makes food sweet.","native":"El azúcar hace la comida dulce."},{"en":"We keep sugar in a box.","native":"Guardamos el azúcar en una caja."}]},"zh":{"word":"糖","question":"你喜欢茶里放糖吗？","examples":[{"en":"I like one spoon of sugar in my tea.","native":"我喜欢茶里放一勺糖。"},{"en":"Sugar makes food sweet.","native":"糖让食物变甜。"},{"en":"We keep sugar in a box.","native":"我们把糖放在盒子里。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'soup', 'Do you like soup? What soup do you like?', '{"te":{"word":"సూప్","question":"మీకు సూప్ ఇష్టమా? మీకు ఏ సూప్ ఇష్టం?","examples":[{"en":"I like tomato soup very much.","native":"నాకు టమాటా సూప్ చాలా ఇష్టం."},{"en":"We drink hot soup in winter.","native":"మేము చలికాలంలో వేడి సూప్ తాగుతాము."},{"en":"My grandmother makes chicken soup.","native":"నా అమ్మమ్మ చికెన్ సూప్ తయారు చేస్తుంది."}]},"hi":{"word":"सूप","question":"क्या आपको सूप पसंद है? आपको कौन सा सूप पसंद है?","examples":[{"en":"I like tomato soup very much.","native":"मुझे टमाटर का सूप बहुत पसंद है।"},{"en":"We drink hot soup in winter.","native":"हम सर्दियों में गर्म सूप पीते हैं।"},{"en":"My grandmother makes chicken soup.","native":"मेरी दादी चिकन सूप बनाती हैं।"}]},"es":{"word":"sopa","question":"¿Te gusta la sopa? ¿Qué sopa te gusta?","examples":[{"en":"I like tomato soup very much.","native":"Me gusta mucho la sopa de tomate."},{"en":"We drink hot soup in winter.","native":"Bebemos sopa caliente en invierno."},{"en":"My grandmother makes chicken soup.","native":"Mi abuela hace sopa de pollo."}]},"zh":{"word":"汤","question":"你喜欢汤吗？你喜欢什么汤？","examples":[{"en":"I like tomato soup very much.","native":"我非常喜欢西红柿汤。"},{"en":"We drink hot soup in winter.","native":"我们冬天喝热汤。"},{"en":"My grandmother makes chicken soup.","native":"我奶奶做鸡汤。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'kitchen', 'Describe your kitchen.', '{"te":{"word":"వంటగది","question":"మీ వంటగదిని వివరించండి.","examples":[{"en":"Our kitchen is small and clean.","native":"మా వంటగది చిన్నది మరియు శుభ్రంగా ఉంటుంది."},{"en":"My mother cooks in the kitchen.","native":"నా అమ్మ వంటగదిలో వంట చేస్తుంది."},{"en":"There is a big window in our kitchen.","native":"మా వంటగదిలో ఒక పెద్ద కిటికీ ఉంది."}]},"hi":{"word":"रसोई","question":"अपनी रसोई का वर्णन कीजिए।","examples":[{"en":"Our kitchen is small and clean.","native":"हमारी रसोई छोटी और साफ़ है।"},{"en":"My mother cooks in the kitchen.","native":"मेरी माँ रसोई में खाना बनाती हैं।"},{"en":"There is a big window in our kitchen.","native":"हमारी रसोई में एक बड़ी खिड़की है।"}]},"es":{"word":"cocina","question":"Describe tu cocina.","examples":[{"en":"Our kitchen is small and clean.","native":"Nuestra cocina es pequeña y limpia."},{"en":"My mother cooks in the kitchen.","native":"Mi madre cocina en la cocina."},{"en":"There is a big window in our kitchen.","native":"Hay una ventana grande en nuestra cocina."}]},"zh":{"word":"厨房","question":"描述一下你的厨房。","examples":[{"en":"Our kitchen is small and clean.","native":"我们的厨房又小又干净。"},{"en":"My mother cooks in the kitchen.","native":"我妈妈在厨房做饭。"},{"en":"There is a big window in our kitchen.","native":"我们厨房有一扇大窗户。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'cooking', 'Do you like cooking? What can you cook?', '{"te":{"word":"వంట","question":"మీకు వంట చేయడం ఇష్టమా? మీరు ఏమి వంటగలరు?","examples":[{"en":"I like cooking with my mother.","native":"నాకు నా అమ్మతో కలిసి వంట చేయడం ఇష్టం."},{"en":"I can cook rice and eggs.","native":"నేను అన్నం మరియు గుడ్లు వంటగలను."},{"en":"My father cooks dinner on Sundays.","native":"నా నాన్న ఆదివారాలు రాత్రి భోజనం వంటుతారు."}]},"hi":{"word":"खाना बनाना","question":"क्या आपको खाना बनाना पसंद है? आप क्या बना सकते हैं?","examples":[{"en":"I like cooking with my mother.","native":"मुझे अपनी माँ के साथ खाना बनाना पसंद है।"},{"en":"I can cook rice and eggs.","native":"मैं चावल और अंडे बना सकता हूँ।"},{"en":"My father cooks dinner on Sundays.","native":"मेरे पिता रविवार को रात का खाना बनाते हैं।"}]},"es":{"word":"cocinar","question":"¿Te gusta cocinar? ¿Qué puedes cocinar?","examples":[{"en":"I like cooking with my mother.","native":"Me gusta cocinar con mi madre."},{"en":"I can cook rice and eggs.","native":"Puedo cocinar arroz y huevos."},{"en":"My father cooks dinner on Sundays.","native":"Mi padre cocina la cena los domingos."}]},"zh":{"word":"做饭","question":"你喜欢做饭吗？你会做什么？","examples":[{"en":"I like cooking with my mother.","native":"我喜欢和妈妈一起做饭。"},{"en":"I can cook rice and eggs.","native":"我会做米饭和鸡蛋。"},{"en":"My father cooks dinner on Sundays.","native":"我爸爸星期天做晚饭。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'cup', 'What do you drink from a cup?', '{"te":{"word":"కప్పు","question":"మీరు కప్పులో ఏమి తాగుతారు?","examples":[{"en":"I drink tea from a cup.","native":"నేను కప్పులో టీ తాగుతాను."},{"en":"There are six cups on the table.","native":"బల్ల మీద ఆరు కప్పులు ఉన్నాయి."},{"en":"This blue cup is mine.","native":"ఈ నీలం కప్పు నాది."}]},"hi":{"word":"कप","question":"आप कप में क्या पीते हैं?","examples":[{"en":"I drink tea from a cup.","native":"मैं कप में चाय पीता हूँ।"},{"en":"There are six cups on the table.","native":"मेज़ पर छह कप हैं।"},{"en":"This blue cup is mine.","native":"यह नीला कप मेरा है।"}]},"es":{"word":"taza","question":"¿Qué bebes en una taza?","examples":[{"en":"I drink tea from a cup.","native":"Bebo té en una taza."},{"en":"There are six cups on the table.","native":"Hay seis tazas en la mesa."},{"en":"This blue cup is mine.","native":"Esta taza azul es mía."}]},"zh":{"word":"杯子","question":"你用杯子喝什么？","examples":[{"en":"I drink tea from a cup.","native":"我用杯子喝茶。"},{"en":"There are six cups on the table.","native":"桌子上有六个杯子。"},{"en":"This blue cup is mine.","native":"这个蓝色的杯子是我的。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'plate', 'Talk about plates in your home.', '{"te":{"word":"పళ్ళెం","question":"మీ ఇంట్లోని పళ్ళెముల గురించి మాట్లాడండి.","examples":[{"en":"We eat rice from big plates.","native":"మేము పెద్ద పళ్ళెముల్లో అన్నం తింటాము."},{"en":"I wash the plates after dinner.","native":"నేను రాత్రి భోజనం తర్వాత పళ్ళెములు కడుగుతాను."},{"en":"There are many plates in the kitchen.","native":"వంటగదిలో చాలా పళ్ళెములు ఉన్నాయి."}]},"hi":{"word":"प्लेट","question":"अपने घर की प्लेटों के बारे में बताइए।","examples":[{"en":"We eat rice from big plates.","native":"हम बड़ी प्लेटों में चावल खाते हैं।"},{"en":"I wash the plates after dinner.","native":"मैं रात के खाने के बाद प्लेटें धोता हूँ।"},{"en":"There are many plates in the kitchen.","native":"रसोई में बहुत सारी प्लेटें हैं।"}]},"es":{"word":"plato","question":"Habla de los platos de tu casa.","examples":[{"en":"We eat rice from big plates.","native":"Comemos arroz en platos grandes."},{"en":"I wash the plates after dinner.","native":"Lavo los platos después de la cena."},{"en":"There are many plates in the kitchen.","native":"Hay muchos platos en la cocina."}]},"zh":{"word":"盘子","question":"谈谈你家里的盘子。","examples":[{"en":"We eat rice from big plates.","native":"我们用大盘子吃米饭。"},{"en":"I wash the plates after dinner.","native":"我晚饭后洗盘子。"},{"en":"There are many plates in the kitchen.","native":"厨房里有很多盘子。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'spoon', 'What do you do with a spoon?', '{"te":{"word":"చెంచా","question":"మీరు చెంచాతో ఏమి చేస్తారు?","examples":[{"en":"I eat soup with a spoon.","native":"నేను చెంచాతో సూప్ తింటాను."},{"en":"The baby has a small spoon.","native":"పాపకు ఒక చిన్న చెంచా ఉంది."},{"en":"There is a spoon next to the plate.","native":"పళ్ళెం పక్కన ఒక చెంచా ఉంది."}]},"hi":{"word":"चम्मच","question":"आप चम्मच से क्या करते हैं?","examples":[{"en":"I eat soup with a spoon.","native":"मैं चम्मच से सूप खाता हूँ।"},{"en":"The baby has a small spoon.","native":"बच्चे के पास एक छोटा चम्मच है।"},{"en":"There is a spoon next to the plate.","native":"प्लेट के पास एक चम्मच है।"}]},"es":{"word":"cuchara","question":"¿Qué haces con una cuchara?","examples":[{"en":"I eat soup with a spoon.","native":"Como la sopa con una cuchara."},{"en":"The baby has a small spoon.","native":"El bebé tiene una cuchara pequeña."},{"en":"There is a spoon next to the plate.","native":"Hay una cuchara junto al plato."}]},"zh":{"word":"勺子","question":"你用勺子做什么？","examples":[{"en":"I eat soup with a spoon.","native":"我用勺子喝汤。"},{"en":"The baby has a small spoon.","native":"宝宝有一把小勺子。"},{"en":"There is a spoon next to the plate.","native":"盘子旁边有一把勺子。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'hand', 'Talk about your hands. What can you do with them?', '{"te":{"word":"చేయి","question":"మీ చేతుల గురించి మాట్లాడండి. మీరు వాటితో ఏమి చేయగలరు?","examples":[{"en":"I wash my hands before eating.","native":"నేను తినడానికి ముందు చేతులు కడుక్కుంటాను."},{"en":"I write with my right hand.","native":"నేను నా కుడి చేతితో వ్రాస్తాను."},{"en":"She claps her hands in the game.","native":"ఆమె ఆటలో చేతులు చప్పట్లు కొడుతుంది."}]},"hi":{"word":"हाथ","question":"अपने हाथों के बारे में बताइए। आप उनसे क्या कर सकते हैं?","examples":[{"en":"I wash my hands before eating.","native":"मैं खाने से पहले अपने हाथ धोता हूँ।"},{"en":"I write with my right hand.","native":"मैं अपने दाएँ हाथ से लिखता हूँ।"},{"en":"She claps her hands in the game.","native":"वह खेल में अपने हाथों से ताली बजाती है।"}]},"es":{"word":"mano","question":"Habla de tus manos. ¿Qué puedes hacer con ellas?","examples":[{"en":"I wash my hands before eating.","native":"Me lavo las manos antes de comer."},{"en":"I write with my right hand.","native":"Escribo con la mano derecha."},{"en":"She claps her hands in the game.","native":"Ella aplaude en el juego."}]},"zh":{"word":"手","question":"谈谈你的手。你能用它们做什么？","examples":[{"en":"I wash my hands before eating.","native":"我吃饭前洗手。"},{"en":"I write with my right hand.","native":"我用右手写字。"},{"en":"She claps her hands in the game.","native":"她在游戏中拍手。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'eye', 'Talk about your eyes. What colour are they?', '{"te":{"word":"కన్ను","question":"మీ కళ్ల గురించి మాట్లాడండి. అవి ఏ రంగులో ఉన్నాయి?","examples":[{"en":"My eyes are black.","native":"నా కళ్లు నల్లగా ఉన్నాయి."},{"en":"I can see birds with my eyes.","native":"నేను నా కళ్లతో పక్షులను చూడగలను."},{"en":"She closes her eyes and sleeps.","native":"ఆమె కళ్లు మూసుకుని నిద్రపోతుంది."}]},"hi":{"word":"आँख","question":"अपनी आँखों के बारे में बताइए। वे किस रंग की हैं?","examples":[{"en":"My eyes are black.","native":"मेरी आँखें काली हैं।"},{"en":"I can see birds with my eyes.","native":"मैं अपनी आँखों से पक्षियों को देख सकता हूँ।"},{"en":"She closes her eyes and sleeps.","native":"वह अपनी आँखें बंद करके सोती है।"}]},"es":{"word":"ojo","question":"Habla de tus ojos. ¿De qué color son?","examples":[{"en":"My eyes are black.","native":"Mis ojos son negros."},{"en":"I can see birds with my eyes.","native":"Puedo ver pájaros con mis ojos."},{"en":"She closes her eyes and sleeps.","native":"Ella cierra los ojos y duerme."}]},"zh":{"word":"眼睛","question":"谈谈你的眼睛。它们是什么颜色的？","examples":[{"en":"My eyes are black.","native":"我的眼睛是黑色的。"},{"en":"I can see birds with my eyes.","native":"我能用眼睛看鸟。"},{"en":"She closes her eyes and sleeps.","native":"她闭上眼睛睡觉。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'hair', 'Talk about your hair. Is it long or short?', '{"te":{"word":"జుట్టు","question":"మీ జుట్టు గురించి మాట్లాడండి. అది పొడవుగా ఉందా లేదా పొట్టిగా ఉందా?","examples":[{"en":"My hair is black and long.","native":"నా జుట్టు నల్లగా మరియు పొడవుగా ఉంది."},{"en":"I comb my hair every morning.","native":"నేను ప్రతి ఉదయం జుట్టు దువ్వుకుంటాను."},{"en":"My brother has short hair.","native":"నా తమ్ముడికి పొట్టి జుట్టు ఉంది."}]},"hi":{"word":"बाल","question":"अपने बालों के बारे में बताइए। वे लंबे हैं या छोटे?","examples":[{"en":"My hair is black and long.","native":"मेरे बाल काले और लंबे हैं।"},{"en":"I comb my hair every morning.","native":"मैं हर सुबह अपने बालों में कंघी करता हूँ।"},{"en":"My brother has short hair.","native":"मेरे भाई के बाल छोटे हैं।"}]},"es":{"word":"pelo","question":"Habla de tu pelo. ¿Es largo o corto?","examples":[{"en":"My hair is black and long.","native":"Mi pelo es negro y largo."},{"en":"I comb my hair every morning.","native":"Me peino cada mañana."},{"en":"My brother has short hair.","native":"Mi hermano tiene el pelo corto."}]},"zh":{"word":"头发","question":"谈谈你的头发。是长还是短？","examples":[{"en":"My hair is black and long.","native":"我的头发又黑又长。"},{"en":"I comb my hair every morning.","native":"我每天早上梳头。"},{"en":"My brother has short hair.","native":"我哥哥留短发。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'face', 'Talk about your face. What can you do with it?', '{"te":{"word":"ముఖం","question":"మీ ముఖం గురించి మాట్లాడండి. మీరు దానితో ఏమి చేయగలరు?","examples":[{"en":"I wash my face with cold water.","native":"నేను చల్లని నీటితో ముఖం కడుక్కుంటాను."},{"en":"She smiles with her happy face.","native":"ఆమె తన సంతోషమైన ముఖంతో నవ్వుతుంది."},{"en":"The baby has a round face.","native":"పాపకు గుండ్రని ముఖం ఉంది."}]},"hi":{"word":"चेहरा","question":"अपने चेहरे के बारे में बताइए। आप इससे क्या कर सकते हैं?","examples":[{"en":"I wash my face with cold water.","native":"मैं ठंडे पानी से अपना चेहरा धोता हूँ।"},{"en":"She smiles with her happy face.","native":"वह अपने खुश चेहरे से मुस्कुराती है।"},{"en":"The baby has a round face.","native":"बच्चे का चेहरा गोल है।"}]},"es":{"word":"cara","question":"Habla de tu cara. ¿Qué puedes hacer con ella?","examples":[{"en":"I wash my face with cold water.","native":"Me lavo la cara con agua fría."},{"en":"She smiles with her happy face.","native":"Ella sonríe con su cara feliz."},{"en":"The baby has a round face.","native":"El bebé tiene la cara redonda."}]},"zh":{"word":"脸","question":"谈谈你的脸。你能用它做什么？","examples":[{"en":"I wash my face with cold water.","native":"我用冷水洗脸。"},{"en":"She smiles with her happy face.","native":"她用开心的脸微笑。"},{"en":"The baby has a round face.","native":"宝宝有一张圆圆的脸。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'teeth', 'How do you keep your teeth clean?', '{"te":{"word":"పళ్లు","question":"మీరు మీ పళ్లను ఎలా శుభ్రంగా ఉంచుతారు?","examples":[{"en":"I brush my teeth two times a day.","native":"నేను రోజుకు రెండుసార్లు పళ్లు తోముకుంటాను."},{"en":"My teeth are white and strong.","native":"నా పళ్లు తెల్లగా మరియు బలంగా ఉన్నాయి."},{"en":"The dentist checks my teeth.","native":"దంతవైద్యుడు నా పళ్లను పరిశీలిస్తారు."}]},"hi":{"word":"दाँत","question":"आप अपने दाँतों को कैसे साफ़ रखते हैं?","examples":[{"en":"I brush my teeth two times a day.","native":"मैं दिन में दो बार दाँत साफ़ करता हूँ।"},{"en":"My teeth are white and strong.","native":"मेरे दाँत सफ़ेद और मज़बूत हैं।"},{"en":"The dentist checks my teeth.","native":"दंतचिकित्सक मेरे दाँतों की जाँच करते हैं।"}]},"es":{"word":"dientes","question":"¿Cómo mantienes limpios tus dientes?","examples":[{"en":"I brush my teeth two times a day.","native":"Me cepillo los dientes dos veces al día."},{"en":"My teeth are white and strong.","native":"Mis dientes son blancos y fuertes."},{"en":"The dentist checks my teeth.","native":"El dentista revisa mis dientes."}]},"zh":{"word":"牙齿","question":"你怎么保持牙齿清洁？","examples":[{"en":"I brush my teeth two times a day.","native":"我每天刷两次牙。"},{"en":"My teeth are white and strong.","native":"我的牙齿又白又结实。"},{"en":"The dentist checks my teeth.","native":"牙医检查我的牙齿。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'leg', 'Talk about your legs. What can you do with them?', '{"te":{"word":"కాలు","question":"మీ కాళ్ల గురించి మాట్లాడండి. మీరు వాటితో ఏమి చేయగలరు?","examples":[{"en":"I walk to school on my legs.","native":"నేను నడిచి పాఠశాలకు వెళ్తాను."},{"en":"He runs fast with his long legs.","native":"అతను తన పొడవైన కాళ్లతో వేగంగా పరుగెత్తుతాడు."},{"en":"My leg hurts after the game.","native":"ఆట తర్వాత నా కాలు నొప్పిస్తుంది."}]},"hi":{"word":"टाँग","question":"अपनी टाँगों के बारे में बताइए। आप उनसे क्या कर सकते हैं?","examples":[{"en":"I walk to school on my legs.","native":"मैं अपनी टाँगों से स्कूल चलकर जाता हूँ।"},{"en":"He runs fast with his long legs.","native":"वह अपनी लंबी टाँगों से तेज़ दौड़ता है।"},{"en":"My leg hurts after the game.","native":"खेल के बाद मेरी टाँग में दर्द होता है।"}]},"es":{"word":"pierna","question":"Habla de tus piernas. ¿Qué puedes hacer con ellas?","examples":[{"en":"I walk to school on my legs.","native":"Camino a la escuela con mis piernas."},{"en":"He runs fast with his long legs.","native":"Él corre rápido con sus piernas largas."},{"en":"My leg hurts after the game.","native":"Me duele la pierna después del partido."}]},"zh":{"word":"腿","question":"谈谈你的腿。你能用它们做什么？","examples":[{"en":"I walk to school on my legs.","native":"我用腿走路去学校。"},{"en":"He runs fast with his long legs.","native":"他用长腿跑得很快。"},{"en":"My leg hurts after the game.","native":"比赛后我的腿疼。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'shirt', 'Describe your favourite shirt.', '{"te":{"word":"చొక్కా","question":"మీకు ఇష్టమైన చొక్కాను వివరించండి.","examples":[{"en":"My favourite shirt is blue.","native":"నాకు ఇష్టమైన చొక్కా నీలం రంగులో ఉంటుంది."},{"en":"This shirt has white buttons.","native":"ఈ చొక్కాకు తెల్లని బటన్లు ఉన్నాయి."},{"en":"I wear a clean shirt every day.","native":"నేను ప్రతిరోజూ శుభ్రమైన చొక్కా ధరిస్తాను."}]},"hi":{"word":"कमीज़","question":"अपनी पसंदीदा कमीज़ का वर्णन कीजिए।","examples":[{"en":"My favourite shirt is blue.","native":"मेरी पसंदीदा कमीज़ नीली है।"},{"en":"This shirt has white buttons.","native":"इस कमीज़ में सफ़ेद बटन हैं।"},{"en":"I wear a clean shirt every day.","native":"मैं रोज़ साफ़ कमीज़ पहनता हूँ।"}]},"es":{"word":"camisa","question":"Describe tu camisa favorita.","examples":[{"en":"My favourite shirt is blue.","native":"Mi camisa favorita es azul."},{"en":"This shirt has white buttons.","native":"Esta camisa tiene botones blancos."},{"en":"I wear a clean shirt every day.","native":"Llevo una camisa limpia todos los días."}]},"zh":{"word":"衬衫","question":"描述一下你最喜欢的衬衫。","examples":[{"en":"My favourite shirt is blue.","native":"我最喜欢的衬衫是蓝色的。"},{"en":"This shirt has white buttons.","native":"这件衬衫有白色的扣子。"},{"en":"I wear a clean shirt every day.","native":"我每天穿干净的衬衫。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'dress', 'Describe a dress you like.', '{"te":{"word":"ఫ్రాక్","question":"మీకు నచ్చిన ఫ్రాక్‌ను వివరించండి.","examples":[{"en":"My sister has a red dress.","native":"నా చెల్లెలకు ఎరుపు రంగు ఫ్రాక్ ఉంది."},{"en":"She wears the dress on her birthday.","native":"ఆమె తన పుట్టినరోజున ఆ ఫ్రాక్ ధరిస్తుంది."},{"en":"This dress is very pretty.","native":"ఈ ఫ్రాక్ చాలా అందంగా ఉంది."}]},"hi":{"word":"पोशाक","question":"अपनी पसंदीदा पोशाक का वर्णन कीजिए।","examples":[{"en":"My sister has a red dress.","native":"मेरी बहन के पास एक लाल पोशाक है।"},{"en":"She wears the dress on her birthday.","native":"वह अपने जन्मदिन पर यह पोशाक पहनती है।"},{"en":"This dress is very pretty.","native":"यह पोशाक बहुत सुंदर है।"}]},"es":{"word":"vestido","question":"Describe un vestido que te gusta.","examples":[{"en":"My sister has a red dress.","native":"Mi hermana tiene un vestido rojo."},{"en":"She wears the dress on her birthday.","native":"Ella lleva el vestido en su cumpleaños."},{"en":"This dress is very pretty.","native":"Este vestido es muy bonito."}]},"zh":{"word":"连衣裙","question":"描述一件你喜欢的连衣裙。","examples":[{"en":"My sister has a red dress.","native":"我妹妹有一条红色的连衣裙。"},{"en":"She wears the dress on her birthday.","native":"她生日时穿这条裙子。"},{"en":"This dress is very pretty.","native":"这条连衣裙很漂亮。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'shoes', 'Talk about your shoes. What colour are they?', '{"te":{"word":"బూట్లు","question":"మీ బూట్ల గురించి మాట్లాడండి. అవి ఏ రంగులో ఉన్నాయి?","examples":[{"en":"My shoes are black.","native":"నా బూట్లు నల్లగా ఉన్నాయి."},{"en":"I wear shoes when I go out.","native":"నేను బయటకు వెళ్లినప్పుడు బూట్లు ధరిస్తాను."},{"en":"These shoes are new and soft.","native":"ఈ బూట్లు కొత్తవి మరియు మెత్తగా ఉన్నాయి."}]},"hi":{"word":"जूते","question":"अपने जूतों के बारे में बताइए। वे किस रंग के हैं?","examples":[{"en":"My shoes are black.","native":"मेरे जूते काले हैं।"},{"en":"I wear shoes when I go out.","native":"मैं बाहर जाते समय जूते पहनता हूँ।"},{"en":"These shoes are new and soft.","native":"ये जूते नए और नरम हैं।"}]},"es":{"word":"zapatos","question":"Habla de tus zapatos. ¿De qué color son?","examples":[{"en":"My shoes are black.","native":"Mis zapatos son negros."},{"en":"I wear shoes when I go out.","native":"Me pongo los zapatos cuando salgo."},{"en":"These shoes are new and soft.","native":"Estos zapatos son nuevos y blandos."}]},"zh":{"word":"鞋子","question":"谈谈你的鞋子。它们是什么颜色的？","examples":[{"en":"My shoes are black.","native":"我的鞋子是黑色的。"},{"en":"I wear shoes when I go out.","native":"我出门时穿鞋。"},{"en":"These shoes are new and soft.","native":"这双鞋又新又软。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'hat', 'Do you like hats? When do you wear one?', '{"te":{"word":"టోపీ","question":"మీకు టోపీలు ఇష్టమా? మీరు ఎప్పుడు ధరిస్తారు?","examples":[{"en":"I wear a hat in the sun.","native":"నేను ఎండలో టోపీ ధరిస్తాను."},{"en":"My grandfather has an old hat.","native":"నా తాతయ్యకు ఒక పాత టోపీ ఉంది."},{"en":"This yellow hat is for the beach.","native":"ఈ పసుపు టోపీ బీచ్ కోసం."}]},"hi":{"word":"टोपी","question":"क्या आपको टोपियाँ पसंद हैं? आप कब पहनते हैं?","examples":[{"en":"I wear a hat in the sun.","native":"मैं धूप में टोपी पहनता हूँ।"},{"en":"My grandfather has an old hat.","native":"मेरे दादा के पास एक पुरानी टोपी है।"},{"en":"This yellow hat is for the beach.","native":"यह पीली टोपी समुद्र तट के लिए है।"}]},"es":{"word":"sombrero","question":"¿Te gustan los sombreros? ¿Cuándo llevas uno?","examples":[{"en":"I wear a hat in the sun.","native":"Llevo un sombrero bajo el sol."},{"en":"My grandfather has an old hat.","native":"Mi abuelo tiene un sombrero viejo."},{"en":"This yellow hat is for the beach.","native":"Este sombrero amarillo es para la playa."}]},"zh":{"word":"帽子","question":"你喜欢帽子吗？你什么时候戴？","examples":[{"en":"I wear a hat in the sun.","native":"我在太阳下戴帽子。"},{"en":"My grandfather has an old hat.","native":"我爷爷有一顶旧帽子。"},{"en":"This yellow hat is for the beach.","native":"这顶黄帽子是去海滩戴的。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'socks', 'Talk about your socks.', '{"te":{"word":"మోజాళ్లు","question":"మీ మోజాళ్ల గురించి మాట్లాడండి.","examples":[{"en":"I wear white socks to school.","native":"నేను పాఠశాలకు తెల్లని మోజాళ్లు ధరిస్తాను."},{"en":"My socks are in the box.","native":"నా మోజాళ్లు పెట్టెలో ఉన్నాయి."},{"en":"She buys warm socks in winter.","native":"ఆమె చలికాలంలో వెచ్చని మోజాళ్లు కొంటుంది."}]},"hi":{"word":"मोज़े","question":"अपने मोज़ों के बारे में बताइए।","examples":[{"en":"I wear white socks to school.","native":"मैं स्कूल में सफ़ेद मोज़े पहनता हूँ।"},{"en":"My socks are in the box.","native":"मेरे मोज़े डिब्बे में हैं।"},{"en":"She buys warm socks in winter.","native":"वह सर्दियों में गर्म मोज़े खरीदती है।"}]},"es":{"word":"calcetines","question":"Habla de tus calcetines.","examples":[{"en":"I wear white socks to school.","native":"Llevo calcetines blancos a la escuela."},{"en":"My socks are in the box.","native":"Mis calcetines están en la caja."},{"en":"She buys warm socks in winter.","native":"Ella compra calcetines calientes en invierno."}]},"zh":{"word":"袜子","question":"谈谈你的袜子。","examples":[{"en":"I wear white socks to school.","native":"我穿白袜子去上学。"},{"en":"My socks are in the box.","native":"我的袜子在盒子里。"},{"en":"She buys warm socks in winter.","native":"她冬天买保暖的袜子。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'jacket', 'Describe your jacket.', '{"te":{"word":"జాకెట్","question":"మీ జాకెట్‌ను వివరించండి.","examples":[{"en":"My jacket is green and warm.","native":"నా జాకెట్ ఆకుపచ్చ రంగులో మరియు వెచ్చగా ఉంటుంది."},{"en":"I wear my jacket in winter.","native":"నేను చలికాలంలో నా జాకెట్ ధరిస్తాను."},{"en":"This jacket has two big pockets.","native":"ఈ జాకెట్‌కు రెండు పెద్ద జేబులు ఉన్నాయి."}]},"hi":{"word":"जैकेट","question":"अपनी जैकेट का वर्णन कीजिए।","examples":[{"en":"My jacket is green and warm.","native":"मेरी जैकेट हरी और गर्म है।"},{"en":"I wear my jacket in winter.","native":"मैं सर्दियों में अपनी जैकेट पहनता हूँ।"},{"en":"This jacket has two big pockets.","native":"इस जैकेट में दो बड़ी जेबें हैं।"}]},"es":{"word":"chaqueta","question":"Describe tu chaqueta.","examples":[{"en":"My jacket is green and warm.","native":"Mi chaqueta es verde y caliente."},{"en":"I wear my jacket in winter.","native":"Me pongo la chaqueta en invierno."},{"en":"This jacket has two big pockets.","native":"Esta chaqueta tiene dos bolsillos grandes."}]},"zh":{"word":"夹克","question":"描述一下你的夹克。","examples":[{"en":"My jacket is green and warm.","native":"我的夹克是绿色的，很暖和。"},{"en":"I wear my jacket in winter.","native":"我冬天穿夹克。"},{"en":"This jacket has two big pockets.","native":"这件夹克有两个大口袋。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'clothes', 'What clothes do you like to wear?', '{"te":{"word":"బట్టలు","question":"మీరు ఏ బట్టలు ధరించడానికి ఇష్టపడతారు?","examples":[{"en":"I like to wear simple clothes.","native":"నాకు సాధారణ బట్టలు ధరించడం ఇష్టం."},{"en":"My mother washes our clothes.","native":"నా అమ్మ మా బట్టలు ఉతుకుతుంది."},{"en":"We buy new clothes for the festival.","native":"మేము పండుగకు కొత్త బట్టలు కొంటాము."}]},"hi":{"word":"कपड़े","question":"आप कैसे कपड़े पहनना पसंद करते हैं?","examples":[{"en":"I like to wear simple clothes.","native":"मुझे साधारण कपड़े पहनना पसंद है।"},{"en":"My mother washes our clothes.","native":"मेरी माँ हमारे कपड़े धोती हैं।"},{"en":"We buy new clothes for the festival.","native":"हम त्योहार के लिए नए कपड़े खरीदते हैं।"}]},"es":{"word":"ropa","question":"¿Qué ropa te gusta llevar?","examples":[{"en":"I like to wear simple clothes.","native":"Me gusta llevar ropa sencilla."},{"en":"My mother washes our clothes.","native":"Mi madre lava nuestra ropa."},{"en":"We buy new clothes for the festival.","native":"Compramos ropa nueva para la fiesta."}]},"zh":{"word":"衣服","question":"你喜欢穿什么衣服？","examples":[{"en":"I like to wear simple clothes.","native":"我喜欢穿简单的衣服。"},{"en":"My mother washes our clothes.","native":"我妈妈洗我们的衣服。"},{"en":"We buy new clothes for the festival.","native":"我们为节日买新衣服。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'dog', 'Do you have a dog? Describe it.', '{"te":{"word":"కుక్క","question":"మీకు కుక్క ఉందా? దానిని వివరించండి.","examples":[{"en":"I have a small brown dog.","native":"నాకు ఒక చిన్న గోధుమ రంగు కుక్క ఉంది."},{"en":"My dog runs and plays with me.","native":"నా కుక్క నాతో పరుగెత్తి ఆడుతుంది."},{"en":"The dog eats meat and rice.","native":"కుక్క మాంసం మరియు అన్నం తింటుంది."}]},"hi":{"word":"कुत्ता","question":"क्या आपके पास कुत्ता है? उसका वर्णन कीजिए।","examples":[{"en":"I have a small brown dog.","native":"मेरे पास एक छोटा भूरा कुत्ता है।"},{"en":"My dog runs and plays with me.","native":"मेरा कुत्ता मेरे साथ दौड़ता और खेलता है।"},{"en":"The dog eats meat and rice.","native":"कुत्ता मांस और चावल खाता है।"}]},"es":{"word":"perro","question":"¿Tienes un perro? Descríbelo.","examples":[{"en":"I have a small brown dog.","native":"Tengo un perro pequeño y marrón."},{"en":"My dog runs and plays with me.","native":"Mi perro corre y juega conmigo."},{"en":"The dog eats meat and rice.","native":"El perro come carne y arroz."}]},"zh":{"word":"狗","question":"你有狗吗？描述一下它。","examples":[{"en":"I have a small brown dog.","native":"我有一只棕色的小狗。"},{"en":"My dog runs and plays with me.","native":"我的狗和我一起跑和玩。"},{"en":"The dog eats meat and rice.","native":"狗吃肉和米饭。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'cat', 'Talk about cats. Do you like them?', '{"te":{"word":"పిల్లి","question":"పిల్లుల గురించి మాట్లాడండి. మీకు అవి ఇష్టమా?","examples":[{"en":"My cat is white and small.","native":"నా పిల్లి తెల్లగా మరియు చిన్నగా ఉంటుంది."},{"en":"The cat drinks milk every day.","native":"పిల్లి ప్రతిరోజూ పాలు తాగుతుంది."},{"en":"Cats sleep in the afternoon.","native":"పిల్లులు మధ్యాహ్నం నిద్రపోతాయి."}]},"hi":{"word":"बिल्ली","question":"बिल्लियों के बारे में बताइए। क्या आपको वे पसंद हैं?","examples":[{"en":"My cat is white and small.","native":"मेरी बिल्ली सफ़ेद और छोटी है।"},{"en":"The cat drinks milk every day.","native":"बिल्ली रोज़ दूध पीती है।"},{"en":"Cats sleep in the afternoon.","native":"बिल्लियाँ दोपहर में सोती हैं।"}]},"es":{"word":"gato","question":"Habla de los gatos. ¿Te gustan?","examples":[{"en":"My cat is white and small.","native":"Mi gato es blanco y pequeño."},{"en":"The cat drinks milk every day.","native":"El gato bebe leche todos los días."},{"en":"Cats sleep in the afternoon.","native":"Los gatos duermen por la tarde."}]},"zh":{"word":"猫","question":"谈谈猫。你喜欢它们吗？","examples":[{"en":"My cat is white and small.","native":"我的猫又白又小。"},{"en":"The cat drinks milk every day.","native":"猫每天喝牛奶。"},{"en":"Cats sleep in the afternoon.","native":"猫在下午睡觉。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'cow', 'Talk about cows. What do they give us?', '{"te":{"word":"ఆవు","question":"ఆవుల గురించి మాట్లాడండి. అవి మనకు ఏమి ఇస్తాయి?","examples":[{"en":"The cow gives us milk.","native":"ఆవు మనకు పాలు ఇస్తుంది."},{"en":"Cows eat grass in the field.","native":"ఆవులు పొలంలో గడ్డి తింటాయి."},{"en":"My uncle has two white cows.","native":"నా మామయ్యకు రెండు తెల్లని ఆవులు ఉన్నాయి."}]},"hi":{"word":"गाय","question":"गायों के बारे में बताइए। वे हमें क्या देती हैं?","examples":[{"en":"The cow gives us milk.","native":"गाय हमें दूध देती है।"},{"en":"Cows eat grass in the field.","native":"गायें खेत में घास खाती हैं।"},{"en":"My uncle has two white cows.","native":"मेरे चाचा के पास दो सफ़ेद गायें हैं।"}]},"es":{"word":"vaca","question":"Habla de las vacas. ¿Qué nos dan?","examples":[{"en":"The cow gives us milk.","native":"La vaca nos da leche."},{"en":"Cows eat grass in the field.","native":"Las vacas comen hierba en el campo."},{"en":"My uncle has two white cows.","native":"Mi tío tiene dos vacas blancas."}]},"zh":{"word":"奶牛","question":"谈谈奶牛。它们给我们什么？","examples":[{"en":"The cow gives us milk.","native":"奶牛给我们牛奶。"},{"en":"Cows eat grass in the field.","native":"奶牛在田里吃草。"},{"en":"My uncle has two white cows.","native":"我叔叔有两头白奶牛。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'horse', 'Have you seen a horse? Describe it.', '{"te":{"word":"గుర్రం","question":"మీరు గుర్రాన్ని చూశారా? దానిని వివరించండి.","examples":[{"en":"The horse is big and strong.","native":"గుర్రం పెద్దగా మరియు బలంగా ఉంటుంది."},{"en":"Horses can run very fast.","native":"గుర్రాలు చాలా వేగంగా పరుగెత్తగలవు."},{"en":"I saw a black horse on the farm.","native":"నేను పొలంలో ఒక నల్లని గుర్రాన్ని చూశాను."}]},"hi":{"word":"घोड़ा","question":"क्या आपने घोड़ा देखा है? उसका वर्णन कीजिए।","examples":[{"en":"The horse is big and strong.","native":"घोड़ा बड़ा और मज़बूत होता है।"},{"en":"Horses can run very fast.","native":"घोड़े बहुत तेज़ दौड़ सकते हैं।"},{"en":"I saw a black horse on the farm.","native":"मैंने खेत में एक काला घोड़ा देखा।"}]},"es":{"word":"caballo","question":"¿Has visto un caballo? Descríbelo.","examples":[{"en":"The horse is big and strong.","native":"El caballo es grande y fuerte."},{"en":"Horses can run very fast.","native":"Los caballos pueden correr muy rápido."},{"en":"I saw a black horse on the farm.","native":"Vi un caballo negro en la granja."}]},"zh":{"word":"马","question":"你见过马吗？描述一下它。","examples":[{"en":"The horse is big and strong.","native":"马又大又壮。"},{"en":"Horses can run very fast.","native":"马能跑得很快。"},{"en":"I saw a black horse on the farm.","native":"我在农场看到一匹黑马。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'bird', 'Talk about birds. Which birds do you see?', '{"te":{"word":"పక్షి","question":"పక్షుల గురించి మాట్లాడండి. మీరు ఏ పక్షులను చూస్తారు?","examples":[{"en":"I see small birds in the garden.","native":"నేను తోటలో చిన్న పక్షులను చూస్తాను."},{"en":"Birds can fly in the sky.","native":"పక్షులు ఆకాశంలో ఎగరగలవు."},{"en":"The parrot is a green bird.","native":"చిలుక ఆకుపచ్చ పక్షి."}]},"hi":{"word":"पक्षी","question":"पक्षियों के बारे में बताइए। आप कौन से पक्षी देखते हैं?","examples":[{"en":"I see small birds in the garden.","native":"मैं बगीचे में छोटे पक्षी देखता हूँ।"},{"en":"Birds can fly in the sky.","native":"पक्षी आसमान में उड़ सकते हैं।"},{"en":"The parrot is a green bird.","native":"तोता एक हरा पक्षी है।"}]},"es":{"word":"pájaro","question":"Habla de los pájaros. ¿Qué pájaros ves?","examples":[{"en":"I see small birds in the garden.","native":"Veo pájaros pequeños en el jardín."},{"en":"Birds can fly in the sky.","native":"Los pájaros pueden volar en el cielo."},{"en":"The parrot is a green bird.","native":"El loro es un pájaro verde."}]},"zh":{"word":"鸟","question":"谈谈鸟。你看到什么鸟？","examples":[{"en":"I see small birds in the garden.","native":"我在花园里看到小鸟。"},{"en":"Birds can fly in the sky.","native":"鸟能在天上飞。"},{"en":"The parrot is a green bird.","native":"鹦鹉是一种绿色的鸟。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'elephant', 'Describe an elephant.', '{"te":{"word":"ఏనుగు","question":"ఏనుగును వివరించండి.","examples":[{"en":"The elephant is a very big animal.","native":"ఏనుగు చాలా పెద్ద జంతువు."},{"en":"It has a long trunk and big ears.","native":"దానికి పొడవైన తుండం మరియు పెద్ద చెవులు ఉన్నాయి."},{"en":"Elephants eat leaves and fruit.","native":"ఏనుగులు ఆకులు మరియు పండ్లు తింటాయి."}]},"hi":{"word":"हाथी","question":"हाथी का वर्णन कीजिए।","examples":[{"en":"The elephant is a very big animal.","native":"हाथी एक बहुत बड़ा जानवर है।"},{"en":"It has a long trunk and big ears.","native":"उसकी लंबी सूंड और बड़े कान होते हैं।"},{"en":"Elephants eat leaves and fruit.","native":"हाथी पत्ते और फल खाते हैं।"}]},"es":{"word":"elefante","question":"Describe un elefante.","examples":[{"en":"The elephant is a very big animal.","native":"El elefante es un animal muy grande."},{"en":"It has a long trunk and big ears.","native":"Tiene una trompa larga y orejas grandes."},{"en":"Elephants eat leaves and fruit.","native":"Los elefantes comen hojas y fruta."}]},"zh":{"word":"大象","question":"描述一下大象。","examples":[{"en":"The elephant is a very big animal.","native":"大象是非常大的动物。"},{"en":"It has a long trunk and big ears.","native":"它有长鼻子和大耳朵。"},{"en":"Elephants eat leaves and fruit.","native":"大象吃树叶和水果。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'monkey', 'Talk about monkeys. What do they do?', '{"te":{"word":"కోతి","question":"కోతుల గురించి మాట్లాడండి. అవి ఏమి చేస్తాయి?","examples":[{"en":"Monkeys jump from tree to tree.","native":"కోతులు చెట్టు నుండి చెట్టుకు దూకుతాయి."},{"en":"The monkey eats a banana.","native":"కోతి అరటి పండు తింటుంది."},{"en":"Monkeys are funny and clever.","native":"కోతులు చాలా సరదాగా మరియు తెలివిగా ఉంటాయి."}]},"hi":{"word":"बंदर","question":"बंदरों के बारे में बताइए। वे क्या करते हैं?","examples":[{"en":"Monkeys jump from tree to tree.","native":"बंदर पेड़ से पेड़ पर कूदते हैं।"},{"en":"The monkey eats a banana.","native":"बंदर केला खाता है।"},{"en":"Monkeys are funny and clever.","native":"बंदर मज़ेदार और चालाक होते हैं।"}]},"es":{"word":"mono","question":"Habla de los monos. ¿Qué hacen?","examples":[{"en":"Monkeys jump from tree to tree.","native":"Los monos saltan de árbol en árbol."},{"en":"The monkey eats a banana.","native":"El mono come un plátano."},{"en":"Monkeys are funny and clever.","native":"Los monos son graciosos y listos."}]},"zh":{"word":"猴子","question":"谈谈猴子。它们做什么？","examples":[{"en":"Monkeys jump from tree to tree.","native":"猴子在树之间跳来跳去。"},{"en":"The monkey eats a banana.","native":"猴子吃香蕉。"},{"en":"Monkeys are funny and clever.","native":"猴子又滑稽又聪明。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'rabbit', 'Describe a rabbit.', '{"te":{"word":"కుందేలు","question":"కుందేలును వివరించండి.","examples":[{"en":"The rabbit has long ears.","native":"కుందేలుకు పొడవైన చెవులు ఉంటాయి."},{"en":"Rabbits like to eat carrots.","native":"కుందేలులు క్యారెట్లు తినడానికి ఇష్టపడతాయి."},{"en":"My rabbit is soft and white.","native":"నా కుందేలు మెత్తగా మరియు తెల్లగా ఉంటుంది."}]},"hi":{"word":"खरगोश","question":"खरगोश का वर्णन कीजिए।","examples":[{"en":"The rabbit has long ears.","native":"खरगोश के कान लंबे होते हैं।"},{"en":"Rabbits like to eat carrots.","native":"खरगोशों को गाजर खाना पसंद है।"},{"en":"My rabbit is soft and white.","native":"मेरा खरगोश नरम और सफ़ेद है।"}]},"es":{"word":"conejo","question":"Describe un conejo.","examples":[{"en":"The rabbit has long ears.","native":"El conejo tiene las orejas largas."},{"en":"Rabbits like to eat carrots.","native":"A los conejos les gusta comer zanahorias."},{"en":"My rabbit is soft and white.","native":"Mi conejo es suave y blanco."}]},"zh":{"word":"兔子","question":"描述一下兔子。","examples":[{"en":"The rabbit has long ears.","native":"兔子有长长的耳朵。"},{"en":"Rabbits like to eat carrots.","native":"兔子喜欢吃胡萝卜。"},{"en":"My rabbit is soft and white.","native":"我的兔子又软又白。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'pet', 'Do you have a pet? Talk about it.', '{"te":{"word":"సాకుజంతువు","question":"మీకు సాకుజంతువు ఉందా? దాని గురించి మాట్లాడండి.","examples":[{"en":"I have a pet dog at home.","native":"నేను ఇంట్లో ఒక కుక్కను సాకుతాను."},{"en":"My pet sleeps next to my bed.","native":"నా సాకుజంతువు నా మంచం పక్కన నిద్రపోతుంది."},{"en":"I give food to my pet every day.","native":"నేను ప్రతిరోజూ నా సాకుజంతువుకు ఆహారం ఇస్తాను."}]},"hi":{"word":"पालतू जानवर","question":"क्या आपके पास पालतू जानवर है? उसके बारे में बताइए।","examples":[{"en":"I have a pet dog at home.","native":"मेरे घर में एक पालतू कुत्ता है।"},{"en":"My pet sleeps next to my bed.","native":"मेरा पालतू जानवर मेरे बिस्तर के पास सोता है।"},{"en":"I give food to my pet every day.","native":"मैं रोज़ अपने पालतू जानवर को खाना देता हूँ।"}]},"es":{"word":"mascota","question":"¿Tienes una mascota? Habla de ella.","examples":[{"en":"I have a pet dog at home.","native":"Tengo un perro mascota en casa."},{"en":"My pet sleeps next to my bed.","native":"Mi mascota duerme junto a mi cama."},{"en":"I give food to my pet every day.","native":"Le doy comida a mi mascota todos los días."}]},"zh":{"word":"宠物","question":"你有宠物吗？谈谈它。","examples":[{"en":"I have a pet dog at home.","native":"我家里有一只宠物狗。"},{"en":"My pet sleeps next to my bed.","native":"我的宠物睡在我的床边。"},{"en":"I give food to my pet every day.","native":"我每天给我的宠物喂食。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'red', 'Talk about the colour red. What things are red?', '{"te":{"word":"ఎరుపు","question":"ఎరుపు రంగు గురించి మాట్లాడండి. ఏ వస్తువులు ఎరుపు రంగులో ఉంటాయి?","examples":[{"en":"The apple is red.","native":"యాపిల్ ఎరుపు రంగులో ఉంటుంది."},{"en":"My bag is red and black.","native":"నా బ్యాగ్ ఎరుపు మరియు నలుపు రంగులో ఉంది."},{"en":"She likes the red rose.","native":"ఆమెకు ఎర్రని గులాబీ ఇష్టం."}]},"hi":{"word":"लाल","question":"लाल रंग के बारे में बताइए। कौन सी चीज़ें लाल होती हैं?","examples":[{"en":"The apple is red.","native":"सेब लाल होता है।"},{"en":"My bag is red and black.","native":"मेरा बैग लाल और काला है।"},{"en":"She likes the red rose.","native":"उसे लाल गुलाब पसंद है।"}]},"es":{"word":"rojo","question":"Habla del color rojo. ¿Qué cosas son rojas?","examples":[{"en":"The apple is red.","native":"La manzana es roja."},{"en":"My bag is red and black.","native":"Mi bolso es rojo y negro."},{"en":"She likes the red rose.","native":"A ella le gusta la rosa roja."}]},"zh":{"word":"红色","question":"谈谈红色。什么东西是红色的？","examples":[{"en":"The apple is red.","native":"苹果是红色的。"},{"en":"My bag is red and black.","native":"我的包是红黑相间的。"},{"en":"She likes the red rose.","native":"她喜欢红玫瑰。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'blue', 'What blue things do you like?', '{"te":{"word":"నీలం","question":"మీకు ఏ నీలం వస్తువులు ఇష్టం?","examples":[{"en":"The sky is blue.","native":"ఆకాశం నీలం రంగులో ఉంటుంది."},{"en":"I have a blue pen.","native":"నాకు ఒక నీలం పెన్ను ఉంది."},{"en":"My sister likes her blue dress.","native":"నా చెల్లెలకు తన నీలం ఫ్రాక్ ఇష్టం."}]},"hi":{"word":"नीला","question":"आपको कौन सी नीली चीज़ें पसंद हैं?","examples":[{"en":"The sky is blue.","native":"आसमान नीला होता है।"},{"en":"I have a blue pen.","native":"मेरे पास एक नीला पेन है।"},{"en":"My sister likes her blue dress.","native":"मेरी बहन को उसकी नीली पोशाक पसंद है।"}]},"es":{"word":"azul","question":"¿Qué cosas azules te gustan?","examples":[{"en":"The sky is blue.","native":"El cielo es azul."},{"en":"I have a blue pen.","native":"Tengo un bolígrafo azul."},{"en":"My sister likes her blue dress.","native":"A mi hermana le gusta su vestido azul."}]},"zh":{"word":"蓝色","question":"你喜欢什么蓝色的东西？","examples":[{"en":"The sky is blue.","native":"天空是蓝色的。"},{"en":"I have a blue pen.","native":"我有一支蓝色的笔。"},{"en":"My sister likes her blue dress.","native":"我妹妹喜欢她的蓝色连衣裙。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'green', 'Talk about the colour green. What things are green?', '{"te":{"word":"ఆకుపచ్చ","question":"ఆకుపచ్చ రంగు గురించి మాట్లాడండి. ఏ వస్తువులు ఆకుపచ్చ రంగులో ఉంటాయి?","examples":[{"en":"The leaves of the tree are green.","native":"చెట్టు ఆకులు ఆకుపచ్చగా ఉంటాయి."},{"en":"I like green vegetables.","native":"నాకు ఆకుపచ్చ కూరగాయలు ఇష్టం."},{"en":"Our garden is green and beautiful.","native":"మా తోట ఆకుపచ్చగా మరియు అందంగా ఉంటుంది."}]},"hi":{"word":"हरा","question":"हरे रंग के बारे में बताइए। कौन सी चीज़ें हरी होती हैं?","examples":[{"en":"The leaves of the tree are green.","native":"पेड़ के पत्ते हरे होते हैं।"},{"en":"I like green vegetables.","native":"मुझे हरी सब्ज़ियाँ पसंद हैं।"},{"en":"Our garden is green and beautiful.","native":"हमारा बगीचा हरा और सुंदर है।"}]},"es":{"word":"verde","question":"Habla del color verde. ¿Qué cosas son verdes?","examples":[{"en":"The leaves of the tree are green.","native":"Las hojas del árbol son verdes."},{"en":"I like green vegetables.","native":"Me gustan las verduras verdes."},{"en":"Our garden is green and beautiful.","native":"Nuestro jardín es verde y bonito."}]},"zh":{"word":"绿色","question":"谈谈绿色。什么东西是绿色的？","examples":[{"en":"The leaves of the tree are green.","native":"树叶是绿色的。"},{"en":"I like green vegetables.","native":"我喜欢绿色蔬菜。"},{"en":"Our garden is green and beautiful.","native":"我们的花园又绿又美。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'yellow', 'What yellow things can you name?', '{"te":{"word":"పసుపు","question":"మీరు ఏ పసుపు వస్తువుల పేర్లు చెప్పగలరు?","examples":[{"en":"The sun is yellow.","native":"సూర్యుడు పసుపు రంగులో ఉంటాడు."},{"en":"A banana is yellow and sweet.","native":"అరటి పండు పసుపు రంగులో మరియు తీపిగా ఉంటుంది."},{"en":"She has a yellow flower in her hand.","native":"ఆమె చేతిలో ఒక పసుపు పువ్వు ఉంది."}]},"hi":{"word":"पीला","question":"आप कौन सी पीली चीज़ों के नाम बता सकते हैं?","examples":[{"en":"The sun is yellow.","native":"सूरज पीला होता है।"},{"en":"A banana is yellow and sweet.","native":"केला पीला और मीठा होता है।"},{"en":"She has a yellow flower in her hand.","native":"उसके हाथ में एक पीला फूल है।"}]},"es":{"word":"amarillo","question":"¿Qué cosas amarillas puedes nombrar?","examples":[{"en":"The sun is yellow.","native":"El sol es amarillo."},{"en":"A banana is yellow and sweet.","native":"Un plátano es amarillo y dulce."},{"en":"She has a yellow flower in her hand.","native":"Ella tiene una flor amarilla en la mano."}]},"zh":{"word":"黄色","question":"你能说出什么黄色的东西？","examples":[{"en":"The sun is yellow.","native":"太阳是黄色的。"},{"en":"A banana is yellow and sweet.","native":"香蕉又黄又甜。"},{"en":"She has a yellow flower in her hand.","native":"她手里拿着一朵黄花。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'color', 'What is your favourite color? Why?', '{"te":{"word":"రంగు","question":"మీకు ఇష్టమైన రంగు ఏది? ఎందుకు?","examples":[{"en":"My favourite color is blue.","native":"నాకు ఇష్టమైన రంగు నీలం."},{"en":"I like all the colors of the rainbow.","native":"నాకు ఇంద్రధనుస్సు రంగులన్నీ ఇష్టం."},{"en":"This flower has many colors.","native":"ఈ పువ్వుకు చాలా రంగులు ఉన్నాయి."}]},"hi":{"word":"रंग","question":"आपका पसंदीदा रंग कौन सा है? क्यों?","examples":[{"en":"My favourite color is blue.","native":"मेरा पसंदीदा रंग नीला है।"},{"en":"I like all the colors of the rainbow.","native":"मुझे इंद्रधनुष के सभी रंग पसंद हैं।"},{"en":"This flower has many colors.","native":"इस फूल में कई रंग हैं।"}]},"es":{"word":"color","question":"¿Cuál es tu color favorito? ¿Por qué?","examples":[{"en":"My favourite color is blue.","native":"Mi color favorito es el azul."},{"en":"I like all the colors of the rainbow.","native":"Me gustan todos los colores del arcoíris."},{"en":"This flower has many colors.","native":"Esta flor tiene muchos colores."}]},"zh":{"word":"颜色","question":"你最喜欢什么颜色？为什么？","examples":[{"en":"My favourite color is blue.","native":"我最喜欢的颜色是蓝色。"},{"en":"I like all the colors of the rainbow.","native":"我喜欢彩虹的所有颜色。"},{"en":"This flower has many colors.","native":"这朵花有很多颜色。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'number', 'Can you count from one to ten?', '{"te":{"word":"సంఖ్య","question":"మీరు ఒకటి నుండి పది వరకు లెక్కపెట్టగలరా?","examples":[{"en":"I can count from one to ten.","native":"నేను ఒకటి నుండి పది వరకు లెక్కపెట్టగలను."},{"en":"Seven is my lucky number.","native":"ఏడు నా అదృష్ట సంఖ్య."},{"en":"My house number is twelve.","native":"నా ఇంటి నంబరు పన్నెండు."}]},"hi":{"word":"संख्या","question":"क्या आप एक से दस तक गिन सकते हैं?","examples":[{"en":"I can count from one to ten.","native":"मैं एक से दस तक गिन सकता हूँ।"},{"en":"Seven is my lucky number.","native":"सात मेरा भाग्यशाली अंक है।"},{"en":"My house number is twelve.","native":"मेरे घर का नंबर बारह है।"}]},"es":{"word":"número","question":"¿Puedes contar de uno a diez?","examples":[{"en":"I can count from one to ten.","native":"Puedo contar de uno a diez."},{"en":"Seven is my lucky number.","native":"El siete es mi número de la suerte."},{"en":"My house number is twelve.","native":"El número de mi casa es doce."}]},"zh":{"word":"数字","question":"你能从一数到十吗？","examples":[{"en":"I can count from one to ten.","native":"我能从一数到十。"},{"en":"Seven is my lucky number.","native":"七是我的幸运数字。"},{"en":"My house number is twelve.","native":"我家的门牌号是十二。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'age', 'How old are you? Talk about your age.', '{"te":{"word":"వయస్సు","question":"మీ వయస్సు ఎంత? మీ వయస్సు గురించి మాట్లాడండి.","examples":[{"en":"I am ten years old.","native":"నా వయస్సు పదేళ్లు."},{"en":"My brother is older than me.","native":"నా సోదరుడు నా కంటే పెద్దవాడు."},{"en":"My grandmother is sixty years old.","native":"నా అమ్మమ్మ వయస్సు అరవై ఏళ్లు."}]},"hi":{"word":"उम्र","question":"आपकी उम्र क्या है? अपनी उम्र के बारे में बताइए।","examples":[{"en":"I am ten years old.","native":"मैं दस साल का हूँ।"},{"en":"My brother is older than me.","native":"मेरा भाई मुझसे बड़ा है।"},{"en":"My grandmother is sixty years old.","native":"मेरी दादी साठ साल की हैं।"}]},"es":{"word":"edad","question":"¿Cuántos años tienes? Habla de tu edad.","examples":[{"en":"I am ten years old.","native":"Tengo diez años."},{"en":"My brother is older than me.","native":"Mi hermano es mayor que yo."},{"en":"My grandmother is sixty years old.","native":"Mi abuela tiene sesenta años."}]},"zh":{"word":"年龄","question":"你多大了？谈谈你的年龄。","examples":[{"en":"I am ten years old.","native":"我十岁了。"},{"en":"My brother is older than me.","native":"我哥哥比我大。"},{"en":"My grandmother is sixty years old.","native":"我奶奶六十岁了。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'money', 'What do you do with your money?', '{"te":{"word":"డబ్బు","question":"మీరు మీ డబ్బుతో ఏమి చేస్తారు?","examples":[{"en":"I keep my money in a box.","native":"నేను నా డబ్బును ఒక పెట్టెలో ఉంచుతాను."},{"en":"I buy books with my money.","native":"నేను నా డబ్బుతో పుస్తకాలు కొంటాను."},{"en":"My father gives me money on my birthday.","native":"నా నాన్న నా పుట్టినరోజున నాకు డబ్బు ఇస్తారు."}]},"hi":{"word":"पैसा","question":"आप अपने पैसों से क्या करते हैं?","examples":[{"en":"I keep my money in a box.","native":"मैं अपने पैसे एक डिब्बे में रखता हूँ।"},{"en":"I buy books with my money.","native":"मैं अपने पैसों से किताबें खरीदता हूँ।"},{"en":"My father gives me money on my birthday.","native":"मेरे पिता मुझे मेरे जन्मदिन पर पैसे देते हैं।"}]},"es":{"word":"dinero","question":"¿Qué haces con tu dinero?","examples":[{"en":"I keep my money in a box.","native":"Guardo mi dinero en una caja."},{"en":"I buy books with my money.","native":"Compro libros con mi dinero."},{"en":"My father gives me money on my birthday.","native":"Mi padre me da dinero en mi cumpleaños."}]},"zh":{"word":"钱","question":"你用你的钱做什么？","examples":[{"en":"I keep my money in a box.","native":"我把钱放在盒子里。"},{"en":"I buy books with my money.","native":"我用钱买书。"},{"en":"My father gives me money on my birthday.","native":"我爸爸在我生日时给我钱。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'room', 'Describe your room.', '{"te":{"word":"గది","question":"మీ గదిని వివరించండి.","examples":[{"en":"My room is small and clean.","native":"నా గది చిన్నది మరియు శుభ్రంగా ఉంటుంది."},{"en":"There is a bed and a table in my room.","native":"నా గదిలో ఒక మంచం మరియు ఒక బల్ల ఉన్నాయి."},{"en":"I study in my room every evening.","native":"నేను ప్రతి సాయంత్రం నా గదిలో చదువుకుంటాను."}]},"hi":{"word":"कमरा","question":"अपने कमरे का वर्णन कीजिए।","examples":[{"en":"My room is small and clean.","native":"मेरा कमरा छोटा और साफ़ है।"},{"en":"There is a bed and a table in my room.","native":"मेरे कमरे में एक बिस्तर और एक मेज़ है।"},{"en":"I study in my room every evening.","native":"मैं हर शाम अपने कमरे में पढ़ता हूँ।"}]},"es":{"word":"habitación","question":"Describe tu habitación.","examples":[{"en":"My room is small and clean.","native":"Mi habitación es pequeña y limpia."},{"en":"There is a bed and a table in my room.","native":"Hay una cama y una mesa en mi habitación."},{"en":"I study in my room every evening.","native":"Estudio en mi habitación cada tarde."}]},"zh":{"word":"房间","question":"描述一下你的房间。","examples":[{"en":"My room is small and clean.","native":"我的房间又小又干净。"},{"en":"There is a bed and a table in my room.","native":"我的房间里有一张床和一张桌子。"},{"en":"I study in my room every evening.","native":"我每天晚上在房间里学习。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'door', 'Talk about the doors in your house.', '{"te":{"word":"తలుపు","question":"మీ ఇంట్లోని తలుపుల గురించి మాట్లాడండి.","examples":[{"en":"Our front door is big and brown.","native":"మా ముందు తలుపు పెద్దది మరియు గోధుమ రంగులో ఉంటుంది."},{"en":"Please close the door behind you.","native":"దయచేసి మీ వెనుక తలుపు మూయండి."},{"en":"There are four doors in my house.","native":"నా ఇంట్లో నాలుగు తలుపులు ఉన్నాయి."}]},"hi":{"word":"दरवाज़ा","question":"अपने घर के दरवाज़ों के बारे में बताइए।","examples":[{"en":"Our front door is big and brown.","native":"हमारा सामने का दरवाज़ा बड़ा और भूरा है।"},{"en":"Please close the door behind you.","native":"कृपया अपने पीछे दरवाज़ा बंद कर दीजिए।"},{"en":"There are four doors in my house.","native":"मेरे घर में चार दरवाज़े हैं।"}]},"es":{"word":"puerta","question":"Habla de las puertas de tu casa.","examples":[{"en":"Our front door is big and brown.","native":"Nuestra puerta principal es grande y marrón."},{"en":"Please close the door behind you.","native":"Por favor, cierra la puerta detrás de ti."},{"en":"There are four doors in my house.","native":"Hay cuatro puertas en mi casa."}]},"zh":{"word":"门","question":"谈谈你家的门。","examples":[{"en":"Our front door is big and brown.","native":"我们家的前门又大又棕色。"},{"en":"Please close the door behind you.","native":"请随手关门。"},{"en":"There are four doors in my house.","native":"我家有四扇门。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'window', 'Describe a window in your home.', '{"te":{"word":"కిటికీ","question":"మీ ఇంట్లోని ఒక కిటికీని వివరించండి.","examples":[{"en":"The window in my room is big.","native":"నా గదిలోని కిటికీ పెద్దది."},{"en":"I see birds from my window.","native":"నేను నా కిటికీ నుండి పక్షులను చూస్తాను."},{"en":"Please open the window; it is hot.","native":"దయచేసి కిటికీ తెరవండి; వేడిగా ఉంది."}]},"hi":{"word":"खिड़की","question":"अपने घर की एक खिड़की का वर्णन कीजिए।","examples":[{"en":"The window in my room is big.","native":"मेरे कमरे की खिड़की बड़ी है।"},{"en":"I see birds from my window.","native":"मैं अपनी खिड़की से पक्षी देखता हूँ।"},{"en":"Please open the window; it is hot.","native":"कृपया खिड़की खोलिए; गर्मी है।"}]},"es":{"word":"ventana","question":"Describe una ventana de tu casa.","examples":[{"en":"The window in my room is big.","native":"La ventana de mi habitación es grande."},{"en":"I see birds from my window.","native":"Veo pájaros desde mi ventana."},{"en":"Please open the window; it is hot.","native":"Por favor, abre la ventana; hace calor."}]},"zh":{"word":"窗户","question":"描述一下你家的一扇窗户。","examples":[{"en":"The window in my room is big.","native":"我房间的窗户很大。"},{"en":"I see birds from my window.","native":"我从窗户看鸟。"},{"en":"Please open the window; it is hot.","native":"请打开窗户；很热。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'bed', 'Describe your bed.', '{"te":{"word":"మంచం","question":"మీ మంచాన్ని వివరించండి.","examples":[{"en":"My bed is big and soft.","native":"నా మంచం పెద్దది మరియు మెత్తగా ఉంటుంది."},{"en":"I sleep in my bed at night.","native":"నేను రాత్రి నా మంచంలో నిద్రపోతాను."},{"en":"There are two pillows on my bed.","native":"నా మంచం మీద రెండు దిండ్లు ఉన్నాయి."}]},"hi":{"word":"बिस्तर","question":"अपने बिस्तर का वर्णन कीजिए।","examples":[{"en":"My bed is big and soft.","native":"मेरा बिस्तर बड़ा और नरम है।"},{"en":"I sleep in my bed at night.","native":"मैं रात में अपने बिस्तर पर सोता हूँ।"},{"en":"There are two pillows on my bed.","native":"मेरे बिस्तर पर दो तकिए हैं।"}]},"es":{"word":"cama","question":"Describe tu cama.","examples":[{"en":"My bed is big and soft.","native":"Mi cama es grande y blanda."},{"en":"I sleep in my bed at night.","native":"Duermo en mi cama por la noche."},{"en":"There are two pillows on my bed.","native":"Hay dos almohadas en mi cama."}]},"zh":{"word":"床","question":"描述一下你的床。","examples":[{"en":"My bed is big and soft.","native":"我的床又大又软。"},{"en":"I sleep in my bed at night.","native":"我晚上睡在床上。"},{"en":"There are two pillows on my bed.","native":"我的床上有两个枕头。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'table', 'Talk about the table in your home.', '{"te":{"word":"బల్ల","question":"మీ ఇంట్లోని బల్ల గురించి మాట్లాడండి.","examples":[{"en":"We eat dinner at the table.","native":"మేము బల్ల వద్ద రాత్రి భోజనం చేస్తాము."},{"en":"My books are on the table.","native":"నా పుస్తకాలు బల్ల మీద ఉన్నాయి."},{"en":"The table has four legs.","native":"బల్లకు నాలుగు కాళ్లు ఉన్నాయి."}]},"hi":{"word":"मेज़","question":"अपने घर की मेज़ के बारे में बताइए।","examples":[{"en":"We eat dinner at the table.","native":"हम मेज़ पर रात का खाना खाते हैं।"},{"en":"My books are on the table.","native":"मेरी किताबें मेज़ पर हैं।"},{"en":"The table has four legs.","native":"मेज़ के चार पैर हैं।"}]},"es":{"word":"mesa","question":"Habla de la mesa de tu casa.","examples":[{"en":"We eat dinner at the table.","native":"Cenamos en la mesa."},{"en":"My books are on the table.","native":"Mis libros están sobre la mesa."},{"en":"The table has four legs.","native":"La mesa tiene cuatro patas."}]},"zh":{"word":"桌子","question":"谈谈你家的桌子。","examples":[{"en":"We eat dinner at the table.","native":"我们在桌子旁吃晚饭。"},{"en":"My books are on the table.","native":"我的书在桌子上。"},{"en":"The table has four legs.","native":"桌子有四条腿。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'chair', 'Talk about chairs. Where do you sit?', '{"te":{"word":"కుర్చీ","question":"కుర్చీల గురించి మాట్లాడండి. మీరు ఎక్కడ కూర్చుంటారు?","examples":[{"en":"I sit on a chair in my class.","native":"నేను నా తరగతిలో కుర్చీ మీద కూర్చుంటాను."},{"en":"The old chair is made of wood.","native":"పాత కుర్చీ చెక్కతో తయారు చేయబడింది."},{"en":"My father reads the newspaper on his chair.","native":"నా నాన్న తన కుర్చీలో పత్రిక చదువుతారు."}]},"hi":{"word":"कुर्सी","question":"कुर्सियों के बारे में बताइए। आप कहाँ बैठते हैं?","examples":[{"en":"I sit on a chair in my class.","native":"मैं अपनी कक्षा में कुर्सी पर बैठता हूँ।"},{"en":"The old chair is made of wood.","native":"पुरानी कुर्सी लकड़ी की बनी है।"},{"en":"My father reads the newspaper on his chair.","native":"मेरे पिता अपनी कुर्सी पर अख़बार पढ़ते हैं।"}]},"es":{"word":"silla","question":"Habla de las sillas. ¿Dónde te sientas?","examples":[{"en":"I sit on a chair in my class.","native":"Me siento en una silla en mi clase."},{"en":"The old chair is made of wood.","native":"La silla vieja es de madera."},{"en":"My father reads the newspaper on his chair.","native":"Mi padre lee el periódico en su silla."}]},"zh":{"word":"椅子","question":"谈谈椅子。你坐在哪里？","examples":[{"en":"I sit on a chair in my class.","native":"我坐在教室的椅子上。"},{"en":"The old chair is made of wood.","native":"那把旧椅子是木头做的。"},{"en":"My father reads the newspaper on his chair.","native":"我爸爸坐在他的椅子上看报纸。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'garden', 'Describe your garden.', '{"te":{"word":"తోట","question":"మీ తోటను వివరించండి.","examples":[{"en":"Our garden has many flowers.","native":"మా తోటలో చాలా పువ్వులు ఉన్నాయి."},{"en":"I water the plants every morning.","native":"నేను ప్రతి ఉదయం మొక్కలకు నీరు పోస్తాను."},{"en":"Butterflies fly in our garden.","native":"మా తోటలో సీతాకోకచిలుకలు ఎగురుతాయి."}]},"hi":{"word":"बगीचा","question":"अपने बगीचे का वर्णन कीजिए।","examples":[{"en":"Our garden has many flowers.","native":"हमारे बगीचे में बहुत सारे फूल हैं।"},{"en":"I water the plants every morning.","native":"मैं हर सुबह पौधों को पानी देता हूँ।"},{"en":"Butterflies fly in our garden.","native":"हमारे बगीचे में तितलियाँ उड़ती हैं।"}]},"es":{"word":"jardín","question":"Describe tu jardín.","examples":[{"en":"Our garden has many flowers.","native":"Nuestro jardín tiene muchas flores."},{"en":"I water the plants every morning.","native":"Riego las plantas cada mañana."},{"en":"Butterflies fly in our garden.","native":"Las mariposas vuelan en nuestro jardín."}]},"zh":{"word":"花园","question":"描述一下你的花园。","examples":[{"en":"Our garden has many flowers.","native":"我们的花园里有很多花。"},{"en":"I water the plants every morning.","native":"我每天早上给植物浇水。"},{"en":"Butterflies fly in our garden.","native":"蝴蝶在我们的花园里飞。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'tree', 'Talk about trees. Do you like them?', '{"te":{"word":"చెట్టు","question":"చెట్ల గురించి మాట్లాడండి. మీకు అవి ఇష్టమా?","examples":[{"en":"The mango tree is very tall.","native":"మామిడి చెట్టు చాలా ఎత్తుగా ఉంటుంది."},{"en":"Trees give us fruit and shade.","native":"చెట్లు మనకు పండ్లు మరియు నీడ ఇస్తాయి."},{"en":"Birds make nests in the tree.","native":"పక్షులు చెట్టులో గూళ్లు కడతాయి."}]},"hi":{"word":"पेड़","question":"पेड़ों के बारे में बताइए। क्या आपको वे पसंद हैं?","examples":[{"en":"The mango tree is very tall.","native":"आम का पेड़ बहुत ऊँचा है।"},{"en":"Trees give us fruit and shade.","native":"पेड़ हमें फल और छाया देते हैं।"},{"en":"Birds make nests in the tree.","native":"पक्षी पेड़ पर घोंसले बनाते हैं।"}]},"es":{"word":"árbol","question":"Habla de los árboles. ¿Te gustan?","examples":[{"en":"The mango tree is very tall.","native":"El árbol de mango es muy alto."},{"en":"Trees give us fruit and shade.","native":"Los árboles nos dan fruta y sombra."},{"en":"Birds make nests in the tree.","native":"Los pájaros hacen nidos en el árbol."}]},"zh":{"word":"树","question":"谈谈树。你喜欢它们吗？","examples":[{"en":"The mango tree is very tall.","native":"芒果树很高。"},{"en":"Trees give us fruit and shade.","native":"树给我们水果和树荫。"},{"en":"Birds make nests in the tree.","native":"鸟在树上筑巢。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'flower', 'What flowers do you like?', '{"te":{"word":"పువ్వు","question":"మీకు ఏ పువ్వులు ఇష్టం?","examples":[{"en":"I like the red rose very much.","native":"నాకు ఎర్రని గులాబీ చాలా ఇష్టం."},{"en":"The jasmine flower smells very good.","native":"మల్లెపూవు చాలా మంచి వాసన కలిగి ఉంటుంది."},{"en":"We give flowers to our teacher.","native":"మేము మా ఉపాధ్యాయుడికి పువ్వులు ఇస్తాము."}]},"hi":{"word":"फूल","question":"आपको कौन से फूल पसंद हैं?","examples":[{"en":"I like the red rose very much.","native":"मुझे लाल गुलाब बहुत पसंद है।"},{"en":"The jasmine flower smells very good.","native":"चमेली का फूल बहुत अच्छी खुशबू देता है।"},{"en":"We give flowers to our teacher.","native":"हम अपने शिक्षक को फूल देते हैं।"}]},"es":{"word":"flor","question":"¿Qué flores te gustan?","examples":[{"en":"I like the red rose very much.","native":"Me gusta mucho la rosa roja."},{"en":"The jasmine flower smells very good.","native":"La flor de jazmín huele muy bien."},{"en":"We give flowers to our teacher.","native":"Le damos flores a nuestro maestro."}]},"zh":{"word":"花","question":"你喜欢什么花？","examples":[{"en":"I like the red rose very much.","native":"我非常喜欢红玫瑰。"},{"en":"The jasmine flower smells very good.","native":"茉莉花很香。"},{"en":"We give flowers to our teacher.","native":"我们给老师送花。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'classroom', 'Describe your classroom.', '{"te":{"word":"తరగతి గది","question":"మీ తరగతి గదిని వివరించండి.","examples":[{"en":"My classroom is big and bright.","native":"నా తరగతి గది పెద్దది మరియు వెలుతురుగా ఉంటుంది."},{"en":"There are thirty students in my class.","native":"నా తరగతిలో ముప్పై మంది విద్యార్థులు ఉన్నారు."},{"en":"Our teacher writes on the blackboard.","native":"మా ఉపాధ్యాయుడు బలపం పలక మీద వ్రాస్తారు."}]},"hi":{"word":"कक्षा","question":"अपनी कक्षा का वर्णन कीजिए।","examples":[{"en":"My classroom is big and bright.","native":"मेरी कक्षा बड़ी और रोशन है।"},{"en":"There are thirty students in my class.","native":"मेरी कक्षा में तीस छात्र हैं।"},{"en":"Our teacher writes on the blackboard.","native":"हमारे शिक्षक ब्लैकबोर्ड पर लिखते हैं।"}]},"es":{"word":"aula","question":"Describe tu aula.","examples":[{"en":"My classroom is big and bright.","native":"Mi aula es grande y luminosa."},{"en":"There are thirty students in my class.","native":"Hay treinta estudiantes en mi clase."},{"en":"Our teacher writes on the blackboard.","native":"Nuestra maestra escribe en la pizarra."}]},"zh":{"word":"教室","question":"描述一下你的教室。","examples":[{"en":"My classroom is big and bright.","native":"我的教室又大又明亮。"},{"en":"There are thirty students in my class.","native":"我班上有三十个学生。"},{"en":"Our teacher writes on the blackboard.","native":"我们的老师在黑板上写字。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'teacher', 'Talk about your teacher.', '{"te":{"word":"ఉపాధ్యాయుడు","question":"మీ ఉపాధ్యాయుడి గురించి మాట్లాడండి.","examples":[{"en":"My teacher is very kind.","native":"నా ఉపాధ్యాయుడు చాలా దయగలవారు."},{"en":"She teaches us English every day.","native":"ఆమె ప్రతిరోజూ మాకు ఇంగ్లీషు నేర్పుతుంది."},{"en":"Our teacher helps us with our homework.","native":"మా ఉపాధ్యాయుడు గృహపాఠంలో మాకు సహాయం చేస్తారు."}]},"hi":{"word":"शिक्षक","question":"अपने शिक्षक के बारे में बताइए।","examples":[{"en":"My teacher is very kind.","native":"मेरे शिक्षक बहुत दयालु हैं।"},{"en":"She teaches us English every day.","native":"वह हमें रोज़ अंग्रेज़ी पढ़ाती हैं।"},{"en":"Our teacher helps us with our homework.","native":"हमारे शिक्षक गृहकार्य में हमारी मदद करते हैं।"}]},"es":{"word":"maestro","question":"Habla de tu maestro.","examples":[{"en":"My teacher is very kind.","native":"Mi maestra es muy amable."},{"en":"She teaches us English every day.","native":"Ella nos enseña inglés todos los días."},{"en":"Our teacher helps us with our homework.","native":"Nuestra maestra nos ayuda con los deberes."}]},"zh":{"word":"老师","question":"谈谈你的老师。","examples":[{"en":"My teacher is very kind.","native":"我的老师非常和蔼。"},{"en":"She teaches us English every day.","native":"她每天教我们英语。"},{"en":"Our teacher helps us with our homework.","native":"我们的老师帮助我们做家庭作业。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'book', 'Do you like books? Which book do you like?', '{"te":{"word":"పుస్తకం","question":"మీకు పుస్తకాలు ఇష్టమా? మీకు ఏ పుస్తకం ఇష్టం?","examples":[{"en":"I read a story book every night.","native":"నేను ప్రతి రాత్రి కథా పుస్తకం చదువుతాను."},{"en":"This book has many pictures.","native":"ఈ పుస్తకంలో చాలా చిత్రాలు ఉన్నాయి."},{"en":"My favourite book is about animals.","native":"నాకు ఇష్టమైన పుస్తకం జంతువుల గురించి."}]},"hi":{"word":"किताब","question":"क्या आपको किताबें पसंद हैं? आपको कौन सी किताब पसंद है?","examples":[{"en":"I read a story book every night.","native":"मैं हर रात एक कहानी की किताब पढ़ता हूँ।"},{"en":"This book has many pictures.","native":"इस किताब में बहुत सारी तस्वीरें हैं।"},{"en":"My favourite book is about animals.","native":"मेरी पसंदीदा किताब जानवरों के बारे में है।"}]},"es":{"word":"libro","question":"¿Te gustan los libros? ¿Qué libro te gusta?","examples":[{"en":"I read a story book every night.","native":"Leo un libro de cuentos cada noche."},{"en":"This book has many pictures.","native":"Este libro tiene muchas imágenes."},{"en":"My favourite book is about animals.","native":"Mi libro favorito trata sobre animales."}]},"zh":{"word":"书","question":"你喜欢书吗？你喜欢哪本书？","examples":[{"en":"I read a story book every night.","native":"我每天晚上读一本故事书。"},{"en":"This book has many pictures.","native":"这本书有很多图片。"},{"en":"My favourite book is about animals.","native":"我最喜欢的书是关于动物的。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'pen', 'Talk about your pen.', '{"te":{"word":"పెన్ను","question":"మీ పెన్ను గురించి మాట్లాడండి.","examples":[{"en":"I write with a blue pen.","native":"నేను నీలం పెన్నుతో వ్రాస్తాను."},{"en":"My pen is in my bag.","native":"నా పెన్ను నా బ్యాగులో ఉంది."},{"en":"This pen was a gift from my uncle.","native":"ఈ పెన్ను నా మామయ్య ఇచ్చిన బహుమతి."}]},"hi":{"word":"पेन","question":"अपने पेन के बारे में बताइए।","examples":[{"en":"I write with a blue pen.","native":"मैं नीले पेन से लिखता हूँ।"},{"en":"My pen is in my bag.","native":"मेरा पेन मेरे बैग में है।"},{"en":"This pen was a gift from my uncle.","native":"यह पेन मेरे चाचा का तोहफ़ा था।"}]},"es":{"word":"bolígrafo","question":"Habla de tu bolígrafo.","examples":[{"en":"I write with a blue pen.","native":"Escribo con un bolígrafo azul."},{"en":"My pen is in my bag.","native":"Mi bolígrafo está en mi mochila."},{"en":"This pen was a gift from my uncle.","native":"Este bolígrafo fue un regalo de mi tío."}]},"zh":{"word":"钢笔","question":"谈谈你的钢笔。","examples":[{"en":"I write with a blue pen.","native":"我用蓝色的钢笔写字。"},{"en":"My pen is in my bag.","native":"我的钢笔在我的书包里。"},{"en":"This pen was a gift from my uncle.","native":"这支钢笔是我叔叔送的礼物。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'bag', 'Describe your bag.', '{"te":{"word":"బ్యాగు","question":"మీ బ్యాగును వివరించండి.","examples":[{"en":"My bag is red and heavy.","native":"నా బ్యాగు ఎరుపు రంగులో మరియు బరువుగా ఉంటుంది."},{"en":"I keep my books in my bag.","native":"నేను నా పుస్తకాలు బ్యాగులో ఉంచుతాను."},{"en":"I carry my bag to school every day.","native":"నేను ప్రతిరోజూ నా బ్యాగును పాఠశాలకు మోసుకువెళ్తాను."}]},"hi":{"word":"बैग","question":"अपने बैग का वर्णन कीजिए।","examples":[{"en":"My bag is red and heavy.","native":"मेरा बैग लाल और भारी है।"},{"en":"I keep my books in my bag.","native":"मैं अपनी किताबें अपने बैग में रखता हूँ।"},{"en":"I carry my bag to school every day.","native":"मैं रोज़ अपना बैग स्कूल ले जाता हूँ।"}]},"es":{"word":"mochila","question":"Describe tu mochila.","examples":[{"en":"My bag is red and heavy.","native":"Mi mochila es roja y pesada."},{"en":"I keep my books in my bag.","native":"Guardo mis libros en mi mochila."},{"en":"I carry my bag to school every day.","native":"Llevo mi mochila a la escuela todos los días."}]},"zh":{"word":"书包","question":"描述一下你的书包。","examples":[{"en":"My bag is red and heavy.","native":"我的书包是红色的，很重。"},{"en":"I keep my books in my bag.","native":"我把书放在书包里。"},{"en":"I carry my bag to school every day.","native":"我每天背着书包去上学。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'homework', 'Do you do your homework every day?', '{"te":{"word":"గృహపాఠం","question":"మీరు ప్రతిరోజూ గృహపాఠం చేస్తారా?","examples":[{"en":"I do my homework in the evening.","native":"నేను సాయంత్రం గృహపాఠం చేస్తాను."},{"en":"My homework is easy today.","native":"ఈరోజు నా గృహపాఠం సులభం."},{"en":"I finish my homework before dinner.","native":"నేను రాత్రి భోజనానికి ముందు గృహపాఠం పూర్తి చేస్తాను."}]},"hi":{"word":"गृहकार्य","question":"क्या आप रोज़ अपना गृहकार्य करते हैं?","examples":[{"en":"I do my homework in the evening.","native":"मैं शाम को अपना गृहकार्य करता हूँ।"},{"en":"My homework is easy today.","native":"आज मेरा गृहकार्य आसान है।"},{"en":"I finish my homework before dinner.","native":"मैं रात के खाने से पहले अपना गृहकार्य पूरा करता हूँ।"}]},"es":{"word":"deberes","question":"¿Haces tus deberes todos los días?","examples":[{"en":"I do my homework in the evening.","native":"Hago mis deberes por la tarde."},{"en":"My homework is easy today.","native":"Mis deberes son fáciles hoy."},{"en":"I finish my homework before dinner.","native":"Termino mis deberes antes de la cena."}]},"zh":{"word":"家庭作业","question":"你每天做家庭作业吗？","examples":[{"en":"I do my homework in the evening.","native":"我晚上做家庭作业。"},{"en":"My homework is easy today.","native":"我今天的家庭作业很简单。"},{"en":"I finish my homework before dinner.","native":"我晚饭前完成家庭作业。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'bus', 'Do you travel by bus? Talk about it.', '{"te":{"word":"బస్సు","question":"మీరు బస్సులో ప్రయాణిస్తారా? దాని గురించి మాట్లాడండి.","examples":[{"en":"I go to school by bus.","native":"నేను బస్సులో పాఠశాలకు వెళ్తాను."},{"en":"The bus stops near my house.","native":"బస్సు నా ఇంటి దగ్గర ఆగుతుంది."},{"en":"The bus is full of people in the morning.","native":"ఉదయం బస్సు జనాలతో నిండి ఉంటుంది."}]},"hi":{"word":"बस","question":"क्या आप बस से यात्रा करते हैं? उसके बारे में बताइए।","examples":[{"en":"I go to school by bus.","native":"मैं बस से स्कूल जाता हूँ।"},{"en":"The bus stops near my house.","native":"बस मेरे घर के पास रुकती है।"},{"en":"The bus is full of people in the morning.","native":"सुबह बस लोगों से भरी होती है।"}]},"es":{"word":"autobús","question":"¿Viajas en autobús? Habla de ello.","examples":[{"en":"I go to school by bus.","native":"Voy a la escuela en autobús."},{"en":"The bus stops near my house.","native":"El autobús para cerca de mi casa."},{"en":"The bus is full of people in the morning.","native":"El autobús está lleno de gente por la mañana."}]},"zh":{"word":"公交车","question":"你坐公交车出行吗？谈谈它。","examples":[{"en":"I go to school by bus.","native":"我坐公交车去上学。"},{"en":"The bus stops near my house.","native":"公交车在我家附近停。"},{"en":"The bus is full of people in the morning.","native":"早上公交车挤满了人。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'train', 'Have you travelled by train? Describe it.', '{"te":{"word":"రైలు","question":"మీరు రైలులో ప్రయాణించారా? దానిని వివరించండి.","examples":[{"en":"The train is long and fast.","native":"రైలు పొడవుగా మరియు వేగంగా ఉంటుంది."},{"en":"I went to my village by train.","native":"నేను రైలులో నా ఊరికి వెళ్లాను."},{"en":"We buy tickets at the station.","native":"మేము స్టేషన్లో టిక్కెట్లు కొంటాము."}]},"hi":{"word":"ट्रेन","question":"क्या आपने ट्रेन से यात्रा की है? उसका वर्णन कीजिए।","examples":[{"en":"The train is long and fast.","native":"ट्रेन लंबी और तेज़ होती है।"},{"en":"I went to my village by train.","native":"मैं ट्रेन से अपने गाँव गया।"},{"en":"We buy tickets at the station.","native":"हम स्टेशन पर टिकट खरीदते हैं।"}]},"es":{"word":"tren","question":"¿Has viajado en tren? Descríbelo.","examples":[{"en":"The train is long and fast.","native":"El tren es largo y rápido."},{"en":"I went to my village by train.","native":"Fui a mi pueblo en tren."},{"en":"We buy tickets at the station.","native":"Compramos billetes en la estación."}]},"zh":{"word":"火车","question":"你坐过火车吗？描述一下。","examples":[{"en":"The train is long and fast.","native":"火车又长又快。"},{"en":"I went to my village by train.","native":"我坐火车去了我的村子。"},{"en":"We buy tickets at the station.","native":"我们在车站买票。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'car', 'Talk about cars. Do you like them?', '{"te":{"word":"కారు","question":"కార్ల గురించి మాట్లాడండి. మీకు అవి ఇష్టమా?","examples":[{"en":"My father drives a red car.","native":"నా నాన్న ఎరుపు రంగు కారు నడుపుతారు."},{"en":"We go to the market by car.","native":"మేము కారులో మార్కెట్కు వెళ్తాము."},{"en":"The car has four wheels.","native":"కారుకు నాలుగు చక్రాలు ఉంటాయి."}]},"hi":{"word":"कार","question":"कारों के बारे में बताइए। क्या आपको वे पसंद हैं?","examples":[{"en":"My father drives a red car.","native":"मेरे पिता लाल कार चलाते हैं।"},{"en":"We go to the market by car.","native":"हम कार से बाज़ार जाते हैं।"},{"en":"The car has four wheels.","native":"कार के चार पहिए होते हैं।"}]},"es":{"word":"coche","question":"Habla de los coches. ¿Te gustan?","examples":[{"en":"My father drives a red car.","native":"Mi padre conduce un coche rojo."},{"en":"We go to the market by car.","native":"Vamos al mercado en coche."},{"en":"The car has four wheels.","native":"El coche tiene cuatro ruedas."}]},"zh":{"word":"汽车","question":"谈谈汽车。你喜欢它们吗？","examples":[{"en":"My father drives a red car.","native":"我爸爸开一辆红色的汽车。"},{"en":"We go to the market by car.","native":"我们开车去市场。"},{"en":"The car has four wheels.","native":"汽车有四个轮子。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'bicycle', 'Can you ride a bicycle?', '{"te":{"word":"సైకిల్","question":"మీరు సైకిల్ తొక్కగలరా?","examples":[{"en":"I ride my bicycle in the park.","native":"నేను పార్కులో నా సైకిల్ తొక్కుతాను."},{"en":"My bicycle is blue and new.","native":"నా సైకిల్ నీలం రంగులో మరియు కొత్తది."},{"en":"My brother taught me to ride.","native":"నా అన్నయ్య నాకు తొక్కడం నేర్పాడు."}]},"hi":{"word":"साइकिल","question":"क्या आप साइकिल चला सकते हैं?","examples":[{"en":"I ride my bicycle in the park.","native":"मैं पार्क में अपनी साइकिल चलाता हूँ।"},{"en":"My bicycle is blue and new.","native":"मेरी साइकिल नीली और नई है।"},{"en":"My brother taught me to ride.","native":"मेरे भाई ने मुझे चलाना सिखाया।"}]},"es":{"word":"bicicleta","question":"¿Sabes montar en bicicleta?","examples":[{"en":"I ride my bicycle in the park.","native":"Monto mi bicicleta en el parque."},{"en":"My bicycle is blue and new.","native":"Mi bicicleta es azul y nueva."},{"en":"My brother taught me to ride.","native":"Mi hermano me enseñó a montar."}]},"zh":{"word":"自行车","question":"你会骑自行车吗？","examples":[{"en":"I ride my bicycle in the park.","native":"我在公园里骑自行车。"},{"en":"My bicycle is blue and new.","native":"我的自行车是蓝色的，很新。"},{"en":"My brother taught me to ride.","native":"我哥哥教我骑车。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'ticket', 'When do you buy a ticket?', '{"te":{"word":"టిక్కెట్","question":"మీరు ఎప్పుడు టిక్కెట్ కొంటారు?","examples":[{"en":"I buy a ticket before the movie.","native":"నేను సినిమాకు ముందు టిక్కెట్ కొంటాను."},{"en":"The bus ticket costs ten rupees.","native":"బస్సు టిక్కెట్ పది రూపాయలు అవుతుంది."},{"en":"She keeps the ticket in her bag.","native":"ఆమె టిక్కెట్ను తన బ్యాగులో ఉంచుతుంది."}]},"hi":{"word":"टिकट","question":"आप कब टिकट खरीदते हैं?","examples":[{"en":"I buy a ticket before the movie.","native":"मैं फ़िल्म से पहले टिकट खरीदता हूँ।"},{"en":"The bus ticket costs ten rupees.","native":"बस का टिकट दस रुपये का है।"},{"en":"She keeps the ticket in her bag.","native":"वह टिकट अपने बैग में रखती है।"}]},"es":{"word":"billete","question":"¿Cuándo compras un billete?","examples":[{"en":"I buy a ticket before the movie.","native":"Compro una entrada antes de la película."},{"en":"The bus ticket costs ten rupees.","native":"El billete de autobús cuesta diez rupias."},{"en":"She keeps the ticket in her bag.","native":"Ella guarda el billete en su bolso."}]},"zh":{"word":"票","question":"你什么时候买票？","examples":[{"en":"I buy a ticket before the movie.","native":"我在看电影前买票。"},{"en":"The bus ticket costs ten rupees.","native":"公交车票十卢比。"},{"en":"She keeps the ticket in her bag.","native":"她把票放在包里。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'station', 'Describe a bus or train station.', '{"te":{"word":"స్టేషన్","question":"బస్సు లేదా రైలు స్టేషన్‌ను వివరించండి.","examples":[{"en":"The station is full of people.","native":"స్టేషన్ జనాలతో నిండి ఉంటుంది."},{"en":"We wait for the train at the station.","native":"మేము స్టేషన్లో రైలు కోసం ఎదురుచూస్తాము."},{"en":"There is a small shop at the station.","native":"స్టేషన్లో ఒక చిన్న దుకాణం ఉంది."}]},"hi":{"word":"स्टेशन","question":"बस या ट्रेन स्टेशन का वर्णन कीजिए।","examples":[{"en":"The station is full of people.","native":"स्टेशन लोगों से भरा होता है।"},{"en":"We wait for the train at the station.","native":"हम स्टेशन पर ट्रेन का इंतज़ार करते हैं।"},{"en":"There is a small shop at the station.","native":"स्टेशन पर एक छोटी दुकान है।"}]},"es":{"word":"estación","question":"Describe una estación de autobús o de tren.","examples":[{"en":"The station is full of people.","native":"La estación está llena de gente."},{"en":"We wait for the train at the station.","native":"Esperamos el tren en la estación."},{"en":"There is a small shop at the station.","native":"Hay una tienda pequeña en la estación."}]},"zh":{"word":"车站","question":"描述一个公交车站或火车站。","examples":[{"en":"The station is full of people.","native":"车站挤满了人。"},{"en":"We wait for the train at the station.","native":"我们在车站等火车。"},{"en":"There is a small shop at the station.","native":"车站里有一家小商店。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'rain', 'Do you like rain? Why?', '{"te":{"word":"వర్షం","question":"మీకు వర్షం ఇష్టమా? ఎందుకు?","examples":[{"en":"I like to play in the rain.","native":"నాకు వర్షంలో ఆడుకోవడం ఇష్టం."},{"en":"The rain makes the trees green.","native":"వర్షం చెట్లను పచ్చగా చేస్తుంది."},{"en":"We stay inside when it rains.","native":"వర్షం పడినప్పుడు మేము లోపలే ఉంటాము."}]},"hi":{"word":"बारिश","question":"क्या आपको बारिश पसंद है? क्यों?","examples":[{"en":"I like to play in the rain.","native":"मुझे बारिश में खेलना पसंद है।"},{"en":"The rain makes the trees green.","native":"बारिश पेड़ों को हरा बनाती है।"},{"en":"We stay inside when it rains.","native":"बारिश होने पर हम अंदर रहते हैं।"}]},"es":{"word":"lluvia","question":"¿Te gusta la lluvia? ¿Por qué?","examples":[{"en":"I like to play in the rain.","native":"Me gusta jugar bajo la lluvia."},{"en":"The rain makes the trees green.","native":"La lluvia hace verdes los árboles."},{"en":"We stay inside when it rains.","native":"Nos quedamos dentro cuando llueve."}]},"zh":{"word":"雨","question":"你喜欢雨吗？为什么？","examples":[{"en":"I like to play in the rain.","native":"我喜欢在雨中玩。"},{"en":"The rain makes the trees green.","native":"雨让树变绿。"},{"en":"We stay inside when it rains.","native":"下雨时我们待在屋里。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'sun', 'Talk about the sun. When do you see it?', '{"te":{"word":"సూర్యుడు","question":"సూర్యుడి గురించి మాట్లాడండి. మీరు అతనిని ఎప్పుడు చూస్తారు?","examples":[{"en":"The sun rises in the morning.","native":"సూర్యుడు ఉదయం ఉదయిస్తాడు."},{"en":"The sun is big and hot.","native":"సూర్యుడు పెద్దవాడు మరియు వేడిగా ఉంటాడు."},{"en":"We dry our clothes in the sun.","native":"మేము ఎండలో మా బట్టలు ఆరబెడతాము."}]},"hi":{"word":"सूरज","question":"सूरज के बारे में बताइए। आप इसे कब देखते हैं?","examples":[{"en":"The sun rises in the morning.","native":"सूरज सुबह निकलता है।"},{"en":"The sun is big and hot.","native":"सूरज बड़ा और गर्म होता है।"},{"en":"We dry our clothes in the sun.","native":"हम धूप में अपने कपड़े सुखाते हैं।"}]},"es":{"word":"sol","question":"Habla del sol. ¿Cuándo lo ves?","examples":[{"en":"The sun rises in the morning.","native":"El sol sale por la mañana."},{"en":"The sun is big and hot.","native":"El sol es grande y caliente."},{"en":"We dry our clothes in the sun.","native":"Secamos nuestra ropa al sol."}]},"zh":{"word":"太阳","question":"谈谈太阳。你什么时候看到它？","examples":[{"en":"The sun rises in the morning.","native":"太阳早上升起。"},{"en":"The sun is big and hot.","native":"太阳又大又热。"},{"en":"We dry our clothes in the sun.","native":"我们在太阳下晒衣服。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'cloud', 'Talk about clouds. What do they look like?', '{"te":{"word":"మేఘం","question":"మేఘాల గురించి మాట్లాడండి. అవి ఎలా కనిపిస్తాయి?","examples":[{"en":"The clouds are white and soft.","native":"మేఘాలు తెల్లగా మరియు మెత్తగా ఉంటాయి."},{"en":"Black clouds bring rain.","native":"నల్లని మేఘాలు వర్షం తెస్తాయి."},{"en":"I see clouds in the blue sky.","native":"నేను నీలి ఆకాశంలో మేఘాలను చూస్తాను."}]},"hi":{"word":"बादल","question":"बादलों के बारे में बताइए। वे कैसे दिखते हैं?","examples":[{"en":"The clouds are white and soft.","native":"बादल सफ़ेद और नरम होते हैं।"},{"en":"Black clouds bring rain.","native":"काले बादल बारिश लाते हैं।"},{"en":"I see clouds in the blue sky.","native":"मैं नीले आसमान में बादल देखता हूँ।"}]},"es":{"word":"nube","question":"Habla de las nubes. ¿Cómo son?","examples":[{"en":"The clouds are white and soft.","native":"Las nubes son blancas y suaves."},{"en":"Black clouds bring rain.","native":"Las nubes negras traen lluvia."},{"en":"I see clouds in the blue sky.","native":"Veo nubes en el cielo azul."}]},"zh":{"word":"云","question":"谈谈云。它们看起来什么样？","examples":[{"en":"The clouds are white and soft.","native":"云又白又软。"},{"en":"Black clouds bring rain.","native":"乌云带来雨。"},{"en":"I see clouds in the blue sky.","native":"我看到蓝天中的云。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'summer', 'Do you like summer? What do you do?', '{"te":{"word":"వేసవి","question":"మీకు వేసవి ఇష్టమా? మీరు ఏమి చేస్తారు?","examples":[{"en":"Summer days are long and hot.","native":"వేసవి రోజులు పొడవుగా మరియు వేడిగా ఉంటాయి."},{"en":"We eat ice cream in summer.","native":"మేము వేసవిలో ఐస్ క్రీం తింటాము."},{"en":"I drink cold water in summer.","native":"నేను వేసవిలో చల్లని నీరు తాగుతాను."}]},"hi":{"word":"गर्मी","question":"क्या आपको गर्मी पसंद है? आप क्या करते हैं?","examples":[{"en":"Summer days are long and hot.","native":"गर्मी के दिन लंबे और गर्म होते हैं।"},{"en":"We eat ice cream in summer.","native":"हम गर्मियों में आइसक्रीम खाते हैं।"},{"en":"I drink cold water in summer.","native":"मैं गर्मियों में ठंडा पानी पीता हूँ।"}]},"es":{"word":"verano","question":"¿Te gusta el verano? ¿Qué haces?","examples":[{"en":"Summer days are long and hot.","native":"Los días de verano son largos y calurosos."},{"en":"We eat ice cream in summer.","native":"Comemos helado en verano."},{"en":"I drink cold water in summer.","native":"Bebo agua fría en verano."}]},"zh":{"word":"夏天","question":"你喜欢夏天吗？你做什么？","examples":[{"en":"Summer days are long and hot.","native":"夏天的白天又长又热。"},{"en":"We eat ice cream in summer.","native":"我们夏天吃冰淇淋。"},{"en":"I drink cold water in summer.","native":"我夏天喝凉水。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'winter', 'Do you like winter? What do you wear?', '{"te":{"word":"చలికాలం","question":"మీకు చలికాలం ఇష్టమా? మీరు ఏమి ధరిస్తారు?","examples":[{"en":"Winter mornings are cold and foggy.","native":"చలికాలం ఉదయాలు చల్లగా మరియు పొగమంచుగా ఉంటాయి."},{"en":"I wear a warm jacket in winter.","native":"నేను చలికాలంలో వెచ్చని జాకెట్ ధరిస్తాను."},{"en":"We drink hot tea in winter.","native":"మేము చలికాలంలో వేడి టీ తాగుతాము."}]},"hi":{"word":"सर्दी","question":"क्या आपको सर्दी पसंद है? आप क्या पहनते हैं?","examples":[{"en":"Winter mornings are cold and foggy.","native":"सर्दी की सुबहें ठंडी और कोहरे वाली होती हैं।"},{"en":"I wear a warm jacket in winter.","native":"मैं सर्दियों में गर्म जैकेट पहनता हूँ।"},{"en":"We drink hot tea in winter.","native":"हम सर्दियों में गर्म चाय पीते हैं।"}]},"es":{"word":"invierno","question":"¿Te gusta el invierno? ¿Qué llevas?","examples":[{"en":"Winter mornings are cold and foggy.","native":"Las mañanas de invierno son frías y con niebla."},{"en":"I wear a warm jacket in winter.","native":"Llevo una chaqueta caliente en invierno."},{"en":"We drink hot tea in winter.","native":"Bebemos té caliente en invierno."}]},"zh":{"word":"冬天","question":"你喜欢冬天吗？你穿什么？","examples":[{"en":"Winter mornings are cold and foggy.","native":"冬天的早晨又冷又有雾。"},{"en":"I wear a warm jacket in winter.","native":"我冬天穿暖和的夹克。"},{"en":"We drink hot tea in winter.","native":"我们冬天喝热茶。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'market', 'What do you buy at the market?', '{"te":{"word":"మార్కెట్","question":"మీరు మార్కెట్లో ఏమి కొంటారు?","examples":[{"en":"We buy vegetables at the market.","native":"మేము మార్కెట్లో కూరగాయలు కొంటాము."},{"en":"The market is busy on Sundays.","native":"ఆదివారాలు మార్కెట్ రద్దీగా ఉంటుంది."},{"en":"My mother buys fresh fruit there.","native":"నా అమ్మ అక్కడ తాజా పండ్లు కొంటుంది."}]},"hi":{"word":"बाज़ार","question":"आप बाज़ार से क्या खरीदते हैं?","examples":[{"en":"We buy vegetables at the market.","native":"हम बाज़ार से सब्ज़ियाँ खरीदते हैं।"},{"en":"The market is busy on Sundays.","native":"रविवार को बाज़ार भीड़भाड़ वाला होता है।"},{"en":"My mother buys fresh fruit there.","native":"मेरी माँ वहाँ से ताज़े फल खरीदती हैं।"}]},"es":{"word":"mercado","question":"¿Qué compras en el mercado?","examples":[{"en":"We buy vegetables at the market.","native":"Compramos verduras en el mercado."},{"en":"The market is busy on Sundays.","native":"El mercado está ocupado los domingos."},{"en":"My mother buys fresh fruit there.","native":"Mi madre compra fruta fresca allí."}]},"zh":{"word":"市场","question":"你在市场买什么？","examples":[{"en":"We buy vegetables at the market.","native":"我们在市场买蔬菜。"},{"en":"The market is busy on Sundays.","native":"星期天市场很热闹。"},{"en":"My mother buys fresh fruit there.","native":"我妈妈在那里买新鲜水果。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'park', 'What do you do in the park?', '{"te":{"word":"పార్కు","question":"మీరు పార్కులో ఏమి చేస్తారు?","examples":[{"en":"I play with my friends in the park.","native":"నేను పార్కులో నా స్నేహితులతో ఆడుకుంటాను."},{"en":"The park has many green trees.","native":"పార్కులో చాలా పచ్చని చెట్లు ఉన్నాయి."},{"en":"Old people walk in the park every morning.","native":"ముసలి వారు ప్రతి ఉదయం పార్కులో నడుస్తారు."}]},"hi":{"word":"पार्क","question":"आप पार्क में क्या करते हैं?","examples":[{"en":"I play with my friends in the park.","native":"मैं पार्क में अपने दोस्तों के साथ खेलता हूँ।"},{"en":"The park has many green trees.","native":"पार्क में बहुत सारे हरे पेड़ हैं।"},{"en":"Old people walk in the park every morning.","native":"बुज़ुर्ग लोग हर सुबह पार्क में टहलते हैं।"}]},"es":{"word":"parque","question":"¿Qué haces en el parque?","examples":[{"en":"I play with my friends in the park.","native":"Juego con mis amigos en el parque."},{"en":"The park has many green trees.","native":"El parque tiene muchos árboles verdes."},{"en":"Old people walk in the park every morning.","native":"Los ancianos caminan en el parque cada mañana."}]},"zh":{"word":"公园","question":"你在公园做什么？","examples":[{"en":"I play with my friends in the park.","native":"我和朋友们在公园里玩。"},{"en":"The park has many green trees.","native":"公园里有很多绿树。"},{"en":"Old people walk in the park every morning.","native":"老人们每天早上在公园散步。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'doctor', 'When do you go to the doctor?', '{"te":{"word":"వైద్యుడు","question":"మీరు ఎప్పుడు వైద్యుడి దగ్గరికి వెళ్తారు?","examples":[{"en":"I go to the doctor when I am sick.","native":"నేను జబ్బు పడినప్పుడు వైద్యుడి దగ్గరికి వెళ్తాను."},{"en":"The doctor gives me medicine.","native":"వైద్యుడు నాకు మందులు ఇస్తారు."},{"en":"My aunt is a doctor in the hospital.","native":"నా అత్తయ్య ఆసుపత్రిలో వైద్యురాలు."}]},"hi":{"word":"डॉक्टर","question":"आप कब डॉक्टर के पास जाते हैं?","examples":[{"en":"I go to the doctor when I am sick.","native":"मैं बीमार होने पर डॉक्टर के पास जाता हूँ।"},{"en":"The doctor gives me medicine.","native":"डॉक्टर मुझे दवा देते हैं।"},{"en":"My aunt is a doctor in the hospital.","native":"मेरी चाची अस्पताल में डॉक्टर हैं।"}]},"es":{"word":"médico","question":"¿Cuándo vas al médico?","examples":[{"en":"I go to the doctor when I am sick.","native":"Voy al médico cuando estoy enfermo."},{"en":"The doctor gives me medicine.","native":"El médico me da medicina."},{"en":"My aunt is a doctor in the hospital.","native":"Mi tía es médica en el hospital."}]},"zh":{"word":"医生","question":"你什么时候去看医生？","examples":[{"en":"I go to the doctor when I am sick.","native":"我生病时去看医生。"},{"en":"The doctor gives me medicine.","native":"医生给我药。"},{"en":"My aunt is a doctor in the hospital.","native":"我姑姑是医院里的医生。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'village', 'Describe your village.', '{"te":{"word":"గ్రామం","question":"మీ గ్రామాన్ని వివరించండి.","examples":[{"en":"My village is small and quiet.","native":"నా గ్రామం చిన్నది మరియు ప్రశాంతంగా ఉంటుంది."},{"en":"There are green fields near my village.","native":"నా గ్రామం దగ్గర పచ్చని పొలాలు ఉన్నాయి."},{"en":"My grandparents live in the village.","native":"నా తాతయ్య, అమ్మమ్మ గ్రామంలో నివసిస్తారు."}]},"hi":{"word":"गाँव","question":"अपने गाँव का वर्णन कीजिए।","examples":[{"en":"My village is small and quiet.","native":"मेरा गाँव छोटा और शांत है।"},{"en":"There are green fields near my village.","native":"मेरे गाँव के पास हरे खेत हैं।"},{"en":"My grandparents live in the village.","native":"मेरे दादा-दादी गाँव में रहते हैं।"}]},"es":{"word":"pueblo","question":"Describe tu pueblo.","examples":[{"en":"My village is small and quiet.","native":"Mi pueblo es pequeño y tranquilo."},{"en":"There are green fields near my village.","native":"Hay campos verdes cerca de mi pueblo."},{"en":"My grandparents live in the village.","native":"Mis abuelos viven en el pueblo."}]},"zh":{"word":"村庄","question":"描述一下你的村庄。","examples":[{"en":"My village is small and quiet.","native":"我的村庄又小又安静。"},{"en":"There are green fields near my village.","native":"我村附近有绿色的田野。"},{"en":"My grandparents live in the village.","native":"我的爷爷奶奶住在村子里。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'city', 'Do you like the city? Why?', '{"te":{"word":"నగరం","question":"మీకు నగరం ఇష్టమా? ఎందుకు?","examples":[{"en":"The city is big and busy.","native":"నగరం పెద్దది మరియు రద్దీగా ఉంటుంది."},{"en":"There are many shops in the city.","native":"నగరంలో చాలా దుకాణాలు ఉన్నాయి."},{"en":"I like the lights of the city at night.","native":"రాత్రి నగరపు వెలుగులు నాకు ఇష్టం."}]},"hi":{"word":"शहर","question":"क्या आपको शहर पसंद है? क्यों?","examples":[{"en":"The city is big and busy.","native":"शहर बड़ा और व्यस्त है।"},{"en":"There are many shops in the city.","native":"शहर में बहुत सारी दुकानें हैं।"},{"en":"I like the lights of the city at night.","native":"मुझे रात में शहर की रोशनी पसंद है।"}]},"es":{"word":"ciudad","question":"¿Te gusta la ciudad? ¿Por qué?","examples":[{"en":"The city is big and busy.","native":"La ciudad es grande y ocupada."},{"en":"There are many shops in the city.","native":"Hay muchas tiendas en la ciudad."},{"en":"I like the lights of the city at night.","native":"Me gustan las luces de la ciudad de noche."}]},"zh":{"word":"城市","question":"你喜欢城市吗？为什么？","examples":[{"en":"The city is big and busy.","native":"城市又大又繁忙。"},{"en":"There are many shops in the city.","native":"城市里有很多商店。"},{"en":"I like the lights of the city at night.","native":"我喜欢城市夜晚的灯光。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'farm', 'What do you see on a farm?', '{"te":{"word":"ఫారం","question":"మీరు ఫారంలో ఏమి చూస్తారు?","examples":[{"en":"I see cows and hens on the farm.","native":"నేను ఫారంలో ఆవులు మరియు కోళ్లను చూస్తాను."},{"en":"The farmer grows rice and wheat.","native":"రైతు వరి మరియు గోధుమలు పండిస్తాడు."},{"en":"There is a big tree on the farm.","native":"ఫారంలో ఒక పెద్ద చెట్టు ఉంది."}]},"hi":{"word":"खेत","question":"आप खेत में क्या देखते हैं?","examples":[{"en":"I see cows and hens on the farm.","native":"मैं खेत में गायें और मुर्गियाँ देखता हूँ।"},{"en":"The farmer grows rice and wheat.","native":"किसान चावल और गेहूँ उगाता है।"},{"en":"There is a big tree on the farm.","native":"खेत पर एक बड़ा पेड़ है।"}]},"es":{"word":"granja","question":"¿Qué ves en una granja?","examples":[{"en":"I see cows and hens on the farm.","native":"Veo vacas y gallinas en la granja."},{"en":"The farmer grows rice and wheat.","native":"El granjero cultiva arroz y trigo."},{"en":"There is a big tree on the farm.","native":"Hay un árbol grande en la granja."}]},"zh":{"word":"农场","question":"你在农场看到什么？","examples":[{"en":"I see cows and hens on the farm.","native":"我在农场看到奶牛和母鸡。"},{"en":"The farmer grows rice and wheat.","native":"农民种水稻和小麦。"},{"en":"There is a big tree on the farm.","native":"农场上有一棵大树。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'beach', 'Do you like the beach? What do you do there?', '{"te":{"word":"బీచ్","question":"మీకు బీచ్ ఇష్టమా? మీరు అక్కడ ఏమి చేస్తారు?","examples":[{"en":"I play with the sand on the beach.","native":"నేను బీచులో ఇసుకతో ఆడుకుంటాను."},{"en":"The sea is blue and beautiful.","native":"సముద్రం నీలం రంగులో మరియు అందంగా ఉంటుంది."},{"en":"We eat snacks near the beach.","native":"మేము బీచ్ దగ్గర స్నాక్స్ తింటాము."}]},"hi":{"word":"समुद्र तट","question":"क्या आपको समुद्र तट पसंद है? आप वहाँ क्या करते हैं?","examples":[{"en":"I play with the sand on the beach.","native":"मैं समुद्र तट पर रेत से खेलता हूँ।"},{"en":"The sea is blue and beautiful.","native":"समुद्र नीला और सुंदर है।"},{"en":"We eat snacks near the beach.","native":"हम समुद्र तट के पास नाश्ता खाते हैं।"}]},"es":{"word":"playa","question":"¿Te gusta la playa? ¿Qué haces allí?","examples":[{"en":"I play with the sand on the beach.","native":"Juego con la arena en la playa."},{"en":"The sea is blue and beautiful.","native":"El mar es azul y bonito."},{"en":"We eat snacks near the beach.","native":"Comemos aperitivos cerca de la playa."}]},"zh":{"word":"海滩","question":"你喜欢海滩吗？你在那里做什么？","examples":[{"en":"I play with the sand on the beach.","native":"我在海滩上玩沙子。"},{"en":"The sea is blue and beautiful.","native":"大海又蓝又美。"},{"en":"We eat snacks near the beach.","native":"我们在海滩附近吃小吃。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'mother', 'Talk about your mother.', '{"te":{"word":"అమ్మ","question":"మీ అమ్మ గురించి మాట్లాడండి.","examples":[{"en":"My mother cooks tasty food.","native":"నా అమ్మ రుచికరమైన ఆహారం వంటుంది."},{"en":"She helps me with my homework.","native":"ఆమె గృహపాఠంలో నాకు సహాయం చేస్తుంది."},{"en":"I love my mother very much.","native":"నేను నా అమ్మను చాలా ప్రేమిస్తాను."}]},"hi":{"word":"माँ","question":"अपनी माँ के बारे में बताइए।","examples":[{"en":"My mother cooks tasty food.","native":"मेरी माँ स्वादिष्ट खाना बनाती हैं।"},{"en":"She helps me with my homework.","native":"वह गृहकार्य में मेरी मदद करती हैं।"},{"en":"I love my mother very much.","native":"मैं अपनी माँ से बहुत प्यार करता हूँ।"}]},"es":{"word":"madre","question":"Habla de tu madre.","examples":[{"en":"My mother cooks tasty food.","native":"Mi madre cocina comida sabrosa."},{"en":"She helps me with my homework.","native":"Ella me ayuda con mis deberes."},{"en":"I love my mother very much.","native":"Quiero mucho a mi madre."}]},"zh":{"word":"妈妈","question":"谈谈你的妈妈。","examples":[{"en":"My mother cooks tasty food.","native":"我妈妈做美味的饭菜。"},{"en":"She helps me with my homework.","native":"她帮助我做家庭作业。"},{"en":"I love my mother very much.","native":"我非常爱我的妈妈。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'birthday', 'When is your birthday? What do you do?', '{"te":{"word":"పుట్టినరోజు","question":"మీ పుట్టినరోజు ఎప్పుడు? మీరు ఏమి చేస్తారు?","examples":[{"en":"My birthday is in June.","native":"నా పుట్టినరోజు జూన్ నెలలో."},{"en":"We cut a cake on my birthday.","native":"మేము నా పుట్టినరోజున కేక్ కోస్తాము."},{"en":"My friends give me gifts.","native":"నా స్నేహితులు నాకు బహుమతులు ఇస్తారు."}]},"hi":{"word":"जन्मदिन","question":"आपका जन्मदिन कब है? आप क्या करते हैं?","examples":[{"en":"My birthday is in June.","native":"मेरा जन्मदिन जून में है।"},{"en":"We cut a cake on my birthday.","native":"हम मेरे जन्मदिन पर केक काटते हैं।"},{"en":"My friends give me gifts.","native":"मेरे दोस्त मुझे तोहफ़े देते हैं।"}]},"es":{"word":"cumpleaños","question":"¿Cuándo es tu cumpleaños? ¿Qué haces?","examples":[{"en":"My birthday is in June.","native":"Mi cumpleaños es en junio."},{"en":"We cut a cake on my birthday.","native":"Cortamos un pastel en mi cumpleaños."},{"en":"My friends give me gifts.","native":"Mis amigos me dan regalos."}]},"zh":{"word":"生日","question":"你的生日是什么时候？你做什么？","examples":[{"en":"My birthday is in June.","native":"我的生日在六月。"},{"en":"We cut a cake on my birthday.","native":"我们在我生日时切蛋糕。"},{"en":"My friends give me gifts.","native":"我的朋友们送我礼物。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'game', 'What games do you like to play?', '{"te":{"word":"ఆట","question":"మీరు ఏ ఆటలు ఆడడానికి ఇష్టపడతారు?","examples":[{"en":"I like to play hide and seek.","native":"నాకు దాగుడుమూతలు ఆడడం ఇష్టం."},{"en":"We play cricket after class.","native":"మేము తరగతి తర్వాత క్రికెట్ ఆడుతాము."},{"en":"My sister plays with her dolls.","native":"నా చెల్లెలు తన బొమ్మలతో ఆడుకుంటుంది."}]},"hi":{"word":"खेल","question":"आप कौन से खेल खेलना पसंद करते हैं?","examples":[{"en":"I like to play hide and seek.","native":"मुझे लुका-छिपी खेलना पसंद है।"},{"en":"We play cricket after class.","native":"हम कक्षा के बाद क्रिकेट खेलते हैं।"},{"en":"My sister plays with her dolls.","native":"मेरी बहन अपनी गुड़ियों से खेलती है।"}]},"es":{"word":"juego","question":"¿Qué juegos te gusta jugar?","examples":[{"en":"I like to play hide and seek.","native":"Me gusta jugar al escondite."},{"en":"We play cricket after class.","native":"Jugamos al críquet después de clase."},{"en":"My sister plays with her dolls.","native":"Mi hermana juega con sus muñecas."}]},"zh":{"word":"游戏","question":"你喜欢玩什么游戏？","examples":[{"en":"I like to play hide and seek.","native":"我喜欢玩捉迷藏。"},{"en":"We play cricket after class.","native":"我们下课后打板球。"},{"en":"My sister plays with her dolls.","native":"我妹妹玩她的洋娃娃。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A1', 'snow', 'Have you seen snow? Describe it.', '{"te":{"word":"మంచు","question":"మీరు మంచును చూశారా? దానిని వివరించండి.","examples":[{"en":"Snow is white and cold.","native":"మంచు తెల్లగా మరియు చల్లగా ఉంటుంది."},{"en":"Children play in the snow.","native":"పిల్లలు మంచులో ఆడుకుంటారు."},{"en":"It snows a lot in the mountains.","native":"పర్వతాల్లో చాలా మంచు కురుస్తుంది."}]},"hi":{"word":"बर्फ़","question":"क्या आपने बर्फ़ देखी है? उसका वर्णन कीजिए।","examples":[{"en":"Snow is white and cold.","native":"बर्फ़ सफ़ेद और ठंडी होती है।"},{"en":"Children play in the snow.","native":"बच्चे बर्फ़ में खेलते हैं।"},{"en":"It snows a lot in the mountains.","native":"पहाड़ों में बहुत बर्फ़बारी होती है।"}]},"es":{"word":"nieve","question":"¿Has visto la nieve? Descríbela.","examples":[{"en":"Snow is white and cold.","native":"La nieve es blanca y fría."},{"en":"Children play in the snow.","native":"Los niños juegan en la nieve."},{"en":"It snows a lot in the mountains.","native":"Nieva mucho en las montañas."}]},"zh":{"word":"雪","question":"你见过雪吗？描述一下它。","examples":[{"en":"Snow is white and cold.","native":"雪又白又冷。"},{"en":"Children play in the snow.","native":"孩子们在雪里玩。"},{"en":"It snows a lot in the mountains.","native":"山上经常下大雪。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'weekend', 'What did you do last weekend?', '{"te":{"word":"వారాంతం","question":"గత వారాంతంలో మీరు ఏమి చేశారు?","examples":[{"en":"Last weekend, I visited a village with my family.","native":"గత వారాంతంలో, నేను నా కుటుంబంతో కలిసి ఒక గ్రామాన్ని సందర్శించాను."},{"en":"I watched a film with my friends on Saturday.","native":"శనివారం నేను నా స్నేహితులతో కలిసి ఒక సినిమా చూశాను."},{"en":"On Sunday, I cleaned my room and cooked dinner.","native":"ఆదివారం, నేను నా గదిని శుభ్రం చేసి రాత్రి భోజనం వండాను."}]},"hi":{"word":"सप्ताहांत","question":"पिछले सप्ताहांत आपने क्या किया?","examples":[{"en":"Last weekend, I visited a village with my family.","native":"पिछले सप्ताहांत, मैंने अपने परिवार के साथ एक गाँव की यात्रा की।"},{"en":"I watched a film with my friends on Saturday.","native":"शनिवार को मैंने अपने दोस्तों के साथ एक फ़िल्म देखी।"},{"en":"On Sunday, I cleaned my room and cooked dinner.","native":"रविवार को, मैंने अपना कमरा साफ़ किया और रात का खाना बनाया।"}]},"es":{"word":"fin de semana","question":"¿Qué hiciste el fin de semana pasado?","examples":[{"en":"Last weekend, I visited a village with my family.","native":"El fin de semana pasado visité un pueblo con mi familia."},{"en":"I watched a film with my friends on Saturday.","native":"Vi una película con mis amigos el sábado."},{"en":"On Sunday, I cleaned my room and cooked dinner.","native":"El domingo limpié mi habitación y cociné la cena."}]},"zh":{"word":"周末","question":"上个周末你做了什么？","examples":[{"en":"Last weekend, I visited a village with my family.","native":"上个周末，我和家人一起去了一个村庄。"},{"en":"I watched a film with my friends on Saturday.","native":"星期六我和朋友们一起看了一部电影。"},{"en":"On Sunday, I cleaned my room and cooked dinner.","native":"星期天，我打扫了房间，还做了晚饭。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'travel', 'Talk about a place you visited.', '{"te":{"word":"ప్రయాణం","question":"మీరు సందర్శించిన ఒక ప్రదేశం గురించి మాట్లాడండి.","examples":[{"en":"Last year, I visited the mountains with my family.","native":"గత సంవత్సరం, నేను నా కుటుంబంతో కలిసి పర్వతాలకు వెళ్లాను."},{"en":"The air was fresh and the views were beautiful.","native":"అక్కడ గాలి స్వచ్ఛంగా ఉంది మరియు దృశ్యాలు అందంగా ఉన్నాయి."},{"en":"We stayed there for three days and took many photos.","native":"మేము అక్కడ మూడు రోజులు ఉండి చాలా ఫోటోలు తీశాము."}]},"hi":{"word":"यात्रा","question":"आपके द्वारा घुमी गई किसी जगह के बारे में बताइए।","examples":[{"en":"Last year, I visited the mountains with my family.","native":"पिछले साल, मैं अपने परिवार के साथ पहाड़ों पर गया।"},{"en":"The air was fresh and the views were beautiful.","native":"वहाँ हवा ताज़ा थी और नज़ारे खूबसूरत थे।"},{"en":"We stayed there for three days and took many photos.","native":"हम वहाँ तीन दिन रहे और बहुत सी तस्वीरें लीं।"}]},"es":{"word":"viaje","question":"Habla de un lugar que visitaste.","examples":[{"en":"Last year, I visited the mountains with my family.","native":"El año pasado visité las montañas con mi familia."},{"en":"The air was fresh and the views were beautiful.","native":"El aire era fresco y las vistas eran hermosas."},{"en":"We stayed there for three days and took many photos.","native":"Nos quedamos allí tres días y tomamos muchas fotos."}]},"zh":{"word":"旅行","question":"谈谈你去过的一个地方。","examples":[{"en":"Last year, I visited the mountains with my family.","native":"去年，我和家人一起去了山区。"},{"en":"The air was fresh and the views were beautiful.","native":"那里空气清新，风景优美。"},{"en":"We stayed there for three days and took many photos.","native":"我们在那里待了三天，拍了很多照片。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'job', 'Describe your job or daily work.', '{"te":{"word":"ఉద్యోగం","question":"మీ ఉద్యోగం లేదా రోజువారీ పనిని వివరించండి.","examples":[{"en":"I work in an office in the city centre.","native":"నేను నగర మధ్యలో ఒక ఆఫీసులో పని చేస్తాను."},{"en":"My job starts at nine and finishes at five.","native":"నా పని తొమ్మిది గంటలకు మొదలై ఐదు గంటలకు ముగుస్తుంది."},{"en":"I answer emails and talk to customers every day.","native":"నేను ప్రతిరోజూ ఇమెయిల్‌లకు సమాధానం ఇస్తాను మరియు కస్టమర్లతో మాట్లాడతాను."}]},"hi":{"word":"नौकरी","question":"अपनी नौकरी या रोज़ के काम का वर्णन कीजिए।","examples":[{"en":"I work in an office in the city centre.","native":"मैं शहर के केंद्र में एक दफ़्तर में काम करता हूँ।"},{"en":"My job starts at nine and finishes at five.","native":"मेरा काम नौ बजे शुरू होता है और पाँच बजे ख़त्म होता है।"},{"en":"I answer emails and talk to customers every day.","native":"मैं रोज़ ईमेल के जवाब देता हूँ और ग्राहकों से बात करता हूँ।"}]},"es":{"word":"trabajo","question":"Describe tu trabajo o tus tareas diarias.","examples":[{"en":"I work in an office in the city centre.","native":"Trabajo en una oficina en el centro de la ciudad."},{"en":"My job starts at nine and finishes at five.","native":"Mi trabajo empieza a las nueve y termina a las cinco."},{"en":"I answer emails and talk to customers every day.","native":"Todos los días respondo correos y hablo con clientes."}]},"zh":{"word":"工作","question":"描述一下你的工作或日常工作。","examples":[{"en":"I work in an office in the city centre.","native":"我在市中心的一间办公室工作。"},{"en":"My job starts at nine and finishes at five.","native":"我九点上班，五点下班。"},{"en":"I answer emails and talk to customers every day.","native":"我每天回复邮件，和客户交谈。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'weather', 'What is the weather like today? What do you do on rainy days?', '{"te":{"word":"వాతావరణం","question":"ఈరోజు వాతావరణం ఎలా ఉంది? వర్షం పడే రోజుల్లో మీరు ఏమి చేస్తారు?","examples":[{"en":"Today the weather is hot and sunny.","native":"ఈరోజు వాతావరణం వేడిగా మరియు ఎండగా ఉంది."},{"en":"On rainy days, I stay at home and read.","native":"వర్షం పడే రోజుల్లో, నేను ఇంట్లో ఉండి చదువుతాను."},{"en":"I like drinking hot tea when it rains.","native":"వర్షం పడినప్పుడు వేడి టీ తాగడం నాకు ఇష్టం."}]},"hi":{"word":"मौसम","question":"आज मौसम कैसा है? बारिश के दिनों में आप क्या करते हैं?","examples":[{"en":"Today the weather is hot and sunny.","native":"आज मौसम गर्म और धूप वाला है।"},{"en":"On rainy days, I stay at home and read.","native":"बारिश के दिनों में, मैं घर पर रहकर पढ़ता हूँ।"},{"en":"I like drinking hot tea when it rains.","native":"बारिश होने पर मुझे गर्म चाय पीना पसंद है।"}]},"es":{"word":"clima","question":"¿Cómo está el clima hoy? ¿Qué haces en los días de lluvia?","examples":[{"en":"Today the weather is hot and sunny.","native":"Hoy el clima es caluroso y soleado."},{"en":"On rainy days, I stay at home and read.","native":"En los días de lluvia, me quedo en casa y leo."},{"en":"I like drinking hot tea when it rains.","native":"Me gusta tomar té caliente cuando llueve."}]},"zh":{"word":"天气","question":"今天天气怎么样？下雨天你做什么？","examples":[{"en":"Today the weather is hot and sunny.","native":"今天天气炎热，阳光灿烂。"},{"en":"On rainy days, I stay at home and read.","native":"下雨天，我待在家里看书。"},{"en":"I like drinking hot tea when it rains.","native":"下雨时我喜欢喝热茶。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'shopping', 'Talk about shopping. What do you like to buy?', '{"te":{"word":"షాపింగ్","question":"షాపింగ్ గురించి మాట్లాడండి. మీరు ఏమి కొనడానికి ఇష్టపడతారు?","examples":[{"en":"I usually buy clothes and shoes at the market.","native":"నేను సాధారణంగా మార్కెట్లో బట్టలు మరియు బూట్లు కొంటాను."},{"en":"I like buying fresh fruit every week.","native":"ప్రతి వారం తాజా పండ్లు కొనడం నాకు ఇష్టం."},{"en":"Sometimes I shop online because it is easy.","native":"కొన్నిసార్లు నేను ఆన్‌లైన్‌లో కొంటాను ఎందుకంటే అది సులభం."}]},"hi":{"word":"खरीदारी","question":"खरीदारी के बारे में बताइए। आप क्या खरीदना पसंद करते हैं?","examples":[{"en":"I usually buy clothes and shoes at the market.","native":"मैं आमतौर पर बाज़ार से कपड़े और जूते खरीदता हूँ।"},{"en":"I like buying fresh fruit every week.","native":"मुझे हर हफ़्ते ताज़े फल खरीदना पसंद है।"},{"en":"Sometimes I shop online because it is easy.","native":"कभी-कभी मैं ऑनलाइन खरीदारी करता हूँ क्योंकि यह आसान है।"}]},"es":{"word":"compras","question":"Habla de las compras. ¿Qué te gusta comprar?","examples":[{"en":"I usually buy clothes and shoes at the market.","native":"Normalmente compro ropa y zapatos en el mercado."},{"en":"I like buying fresh fruit every week.","native":"Me gusta comprar fruta fresca cada semana."},{"en":"Sometimes I shop online because it is easy.","native":"A veces compro en línea porque es fácil."}]},"zh":{"word":"购物","question":"谈谈购物。你喜欢买什么？","examples":[{"en":"I usually buy clothes and shoes at the market.","native":"我通常在市场买衣服和鞋子。"},{"en":"I like buying fresh fruit every week.","native":"我喜欢每周买新鲜水果。"},{"en":"Sometimes I shop online because it is easy.","native":"有时我在网上购物，因为很方便。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'school', 'Talk about your school days or your studies.', '{"te":{"word":"పాఠశాల","question":"మీ పాఠశాల రోజులు లేదా మీ చదువు గురించి మాట్లాడండి.","examples":[{"en":"I studied in a school near my village.","native":"నేను మా ఊరి దగ్గర ఉన్న పాఠశాలలో చదివాను."},{"en":"My favourite subject was mathematics.","native":"నా ఇష్టమైన సబ్జెక్ట్ గణితం."},{"en":"I walked to school with my friends every morning.","native":"ప్రతి ఉదయం నేను నా స్నేహితులతో కలిసి పాఠశాలకు నడిచి వెళ్లేవాణ్ణి."}]},"hi":{"word":"विद्यालय","question":"अपने स्कूल के दिनों या अपनी पढ़ाई के बारे में बताइए।","examples":[{"en":"I studied in a school near my village.","native":"मैंने अपने गाँव के पास के एक स्कूल में पढ़ाई की।"},{"en":"My favourite subject was mathematics.","native":"मेरा पसंदीदा विषय गणित था।"},{"en":"I walked to school with my friends every morning.","native":"मैं हर सुबह अपने दोस्तों के साथ स्कूल पैदल जाता था।"}]},"es":{"word":"escuela","question":"Habla de tus días de escuela o de tus estudios.","examples":[{"en":"I studied in a school near my village.","native":"Estudié en una escuela cerca de mi pueblo."},{"en":"My favourite subject was mathematics.","native":"Mi materia favorita era matemáticas."},{"en":"I walked to school with my friends every morning.","native":"Caminaba a la escuela con mis amigos todas las mañanas."}]},"zh":{"word":"学校","question":"谈谈你的学生时代或你的学习。","examples":[{"en":"I studied in a school near my village.","native":"我在村子附近的一所学校上学。"},{"en":"My favourite subject was mathematics.","native":"我最喜欢的科目是数学。"},{"en":"I walked to school with my friends every morning.","native":"我每天早上和朋友们一起步行去上学。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'holiday', 'Talk about your last holiday. Where did you go and what did you do?', '{"te":{"word":"సెలవు","question":"మీ చివరి సెలవు గురించి మాట్లాడండి. మీరు ఎక్కడికి వెళ్ళారు, ఏమి చేశారు?","examples":[{"en":"Last holiday I went to the beach with my family.","native":"చివరి సెలవులో నేను నా కుటుంబంతో బీచ్‌కి వెళ్ళాను."},{"en":"We swam in the sea and ate fresh fish.","native":"మేము సముద్రంలో ఈత కొట్టాము, తాజా చేపలు తిన్నాము."},{"en":"Next year I am going to visit the mountains.","native":"వచ్చే సంవత్సరం నేను పర్వతాలను సందర్శించబోతున్నాను."}]},"hi":{"word":"छुट्टी","question":"अपनी पिछली छुट्टी के बारे में बताइए। आप कहाँ गए और क्या किया?","examples":[{"en":"Last holiday I went to the beach with my family.","native":"पिछली छुट्टी में मैं अपने परिवार के साथ समुद्र तट गया।"},{"en":"We swam in the sea and ate fresh fish.","native":"हमने समुद्र में तैराकी की और ताज़ी मछली खाई।"},{"en":"Next year I am going to visit the mountains.","native":"अगले साल मैं पहाड़ों पर जाने वाला हूँ।"}]},"es":{"word":"vacaciones","question":"Habla de tus últimas vacaciones. ¿Adónde fuiste y qué hiciste?","examples":[{"en":"Last holiday I went to the beach with my family.","native":"En mis últimas vacaciones fui a la playa con mi familia."},{"en":"We swam in the sea and ate fresh fish.","native":"Nadamos en el mar y comimos pescado fresco."},{"en":"Next year I am going to visit the mountains.","native":"El próximo año voy a visitar las montañas."}]},"zh":{"word":"假期","question":"谈谈你的上一个假期。你去了哪里，做了什么？","examples":[{"en":"Last holiday I went to the beach with my family.","native":"上个假期我和家人一起去了海滩。"},{"en":"We swam in the sea and ate fresh fish.","native":"我们在海里游泳，还吃了新鲜的鱼。"},{"en":"Next year I am going to visit the mountains.","native":"明年我打算去山区游览。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'birthday', 'Talk about your last birthday. How did you celebrate it?', '{"te":{"word":"పుట్టినరోజు","question":"మీ చివరి పుట్టినరోజు గురించి మాట్లాడండి. మీరు దానిని ఎలా జరుపుకున్నారు?","examples":[{"en":"My last birthday was on a Saturday in June.","native":"నా చివరి పుట్టినరోజు జూన్‌లో ఒక శనివారం వచ్చింది."},{"en":"My friends came to my house and we ate cake.","native":"నా స్నేహితులు మా ఇంటికి వచ్చారు, మేము కేకు తిన్నాము."},{"en":"I got a new watch as a birthday present.","native":"నాకు పుట్టినరోజు బహుమతిగా ఒక కొత్త గడియారం వచ్చింది."}]},"hi":{"word":"जन्मदिन","question":"अपने पिछले जन्मदिन के बारे में बताइए। आपने उसे कैसे मनाया?","examples":[{"en":"My last birthday was on a Saturday in June.","native":"मेरा पिछला जन्मदिन जून के एक शनिवार को था।"},{"en":"My friends came to my house and we ate cake.","native":"मेरे दोस्त मेरे घर आए और हमने केक खाया।"},{"en":"I got a new watch as a birthday present.","native":"मुझे जन्मदिन के तोहफ़े में एक नई घड़ी मिली।"}]},"es":{"word":"cumpleaños","question":"Habla de tu último cumpleaños. ¿Cómo lo celebraste?","examples":[{"en":"My last birthday was on a Saturday in June.","native":"Mi último cumpleaños fue un sábado de junio."},{"en":"My friends came to my house and we ate cake.","native":"Mis amigos vinieron a mi casa y comimos pastel."},{"en":"I got a new watch as a birthday present.","native":"Recibí un reloj nuevo como regalo de cumpleaños."}]},"zh":{"word":"生日","question":"谈谈你的上一个生日。你是怎么庆祝的？","examples":[{"en":"My last birthday was on a Saturday in June.","native":"我的上一个生日是六月的一个星期六。"},{"en":"My friends came to my house and we ate cake.","native":"朋友们来到我家，我们一起吃了蛋糕。"},{"en":"I got a new watch as a birthday present.","native":"我收到了一块新手表作为生日礼物。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'breakfast', 'What do you usually eat for breakfast?', '{"te":{"word":"అల్పాహారం","question":"మీరు సాధారణంగా అల్పాహారంలో ఏమి తింటారు?","examples":[{"en":"I usually eat bread and eggs for breakfast.","native":"నేను సాధారణంగా అల్పాహారంలో బ్రెడ్ మరియు గుడ్లు తింటాను."},{"en":"Sometimes I drink a glass of milk in the morning.","native":"కొన్నిసార్లు నేను ఉదయం ఒక గ్లాసు పాలు తాగుతాను."},{"en":"On Sundays, my mother cooks a big breakfast.","native":"ఆదివారాల్లో, మా అమ్మ పెద్ద అల్పాహారం వంటుతుంది."}]},"hi":{"word":"नाश्ता","question":"आप नाश्ते में आमतौर पर क्या खाते हैं?","examples":[{"en":"I usually eat bread and eggs for breakfast.","native":"मैं नाश्ते में आमतौर पर ब्रेड और अंडे खाता हूँ।"},{"en":"Sometimes I drink a glass of milk in the morning.","native":"कभी-कभी मैं सुबह एक गिलास दूध पीता हूँ।"},{"en":"On Sundays, my mother cooks a big breakfast.","native":"रविवार को, मेरी माँ बड़ा नाश्ता बनाती है।"}]},"es":{"word":"desayuno","question":"¿Qué sueles desayunar?","examples":[{"en":"I usually eat bread and eggs for breakfast.","native":"Normalmente desayuno pan y huevos."},{"en":"Sometimes I drink a glass of milk in the morning.","native":"A veces bebo un vaso de leche por la mañana."},{"en":"On Sundays, my mother cooks a big breakfast.","native":"Los domingos, mi madre cocina un desayuno grande."}]},"zh":{"word":"早餐","question":"你早餐通常吃什么？","examples":[{"en":"I usually eat bread and eggs for breakfast.","native":"我早餐通常吃面包和鸡蛋。"},{"en":"Sometimes I drink a glass of milk in the morning.","native":"有时我早上喝一杯牛奶。"},{"en":"On Sundays, my mother cooks a big breakfast.","native":"星期天，我妈妈会做一顿丰盛的早餐。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'dinner', 'What time do you eat dinner? What do you like to eat?', '{"te":{"word":"రాత్రి భోజనం","question":"మీరు ఏ సమయానికి రాత్రి భోజనం తింటారు? మీరు ఏమి తినడానికి ఇష్టపడతారు?","examples":[{"en":"We eat dinner at eight o''clock every evening.","native":"మేము ప్రతి రోజు సాయంత్రం ఎనిమిది గంటలకు భోజనం తింటాము."},{"en":"For dinner, I like rice with vegetables and chicken.","native":"రాత్రి భోజనానికి, నాకు కూరగాయలు మరియు చికెన్‌తో అన్నం ఇష్టం."},{"en":"Yesterday we ate dinner in a small restaurant.","native":"నిన్న మేము ఒక చిన్న రెస్టారెంట్‌లో భోజనం తిన్నాము."}]},"hi":{"word":"रात का खाना","question":"आप रात का खाना कितने बजे खाते हैं? आप क्या खाना पसंद करते हैं?","examples":[{"en":"We eat dinner at eight o''clock every evening.","native":"हम हर शाम आठ बजे खाना खाते हैं।"},{"en":"For dinner, I like rice with vegetables and chicken.","native":"रात के खाने में, मुझे सब्ज़ियों और चिकन के साथ चावल पसंद है।"},{"en":"Yesterday we ate dinner in a small restaurant.","native":"कल हमने एक छोटे रेस्तराँ में खाना खाया।"}]},"es":{"word":"cena","question":"¿A qué hora cenas? ¿Qué te gusta comer?","examples":[{"en":"We eat dinner at eight o''clock every evening.","native":"Cenamos a las ocho todas las noches."},{"en":"For dinner, I like rice with vegetables and chicken.","native":"Para la cena, me gusta el arroz con verduras y pollo."},{"en":"Yesterday we ate dinner in a small restaurant.","native":"Ayer cenamos en un restaurante pequeño."}]},"zh":{"word":"晚餐","question":"你几点吃晚饭？你喜欢吃什么？","examples":[{"en":"We eat dinner at eight o''clock every evening.","native":"我们每天晚上八点吃晚饭。"},{"en":"For dinner, I like rice with vegetables and chicken.","native":"晚餐我喜欢吃米饭配蔬菜和鸡肉。"},{"en":"Yesterday we ate dinner in a small restaurant.","native":"昨天我们在一家小餐馆吃了晚饭。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'cooking', 'Do you like cooking? What dishes can you cook?', '{"te":{"word":"వంట","question":"మీకు వంట చేయడం ఇష్టమా? మీరు ఏ వంటకాలు వండగలరు?","examples":[{"en":"I like cooking simple meals at home on weekends.","native":"వారాంతాల్లో ఇంట్లో సరళమైన భోజనం వండడం నాకు ఇష్టం."},{"en":"I can cook rice, eggs, and vegetable curry.","native":"నేను అన్నం, గుడ్లు, కూరగాయల కూర వండగలను."},{"en":"Last week I cooked soup for my grandmother.","native":"గత వారం నేను నా అమ్మమ్మ కోసం సూప్ వండాను."}]},"hi":{"word":"खाना बनाना","question":"क्या आपको खाना बनाना पसंद है? आप कौन से पकवान बना सकते हैं?","examples":[{"en":"I like cooking simple meals at home on weekends.","native":"मुझे सप्ताहांत में घर पर सादा खाना बनाना पसंद है।"},{"en":"I can cook rice, eggs, and vegetable curry.","native":"मैं चावल, अंडे और सब्ज़ी की करी बना सकता हूँ।"},{"en":"Last week I cooked soup for my grandmother.","native":"पिछले हफ़्ते मैंने अपनी दादी के लिए सूप बनाया।"}]},"es":{"word":"cocinar","question":"¿Te gusta cocinar? ¿Qué platos sabes cocinar?","examples":[{"en":"I like cooking simple meals at home on weekends.","native":"Me gusta cocinar comidas sencillas en casa los fines de semana."},{"en":"I can cook rice, eggs, and vegetable curry.","native":"Sé cocinar arroz, huevos y curry de verduras."},{"en":"Last week I cooked soup for my grandmother.","native":"La semana pasada cociné sopa para mi abuela."}]},"zh":{"word":"做饭","question":"你喜欢做饭吗？你会做哪些菜？","examples":[{"en":"I like cooking simple meals at home on weekends.","native":"我喜欢周末在家做简单的饭菜。"},{"en":"I can cook rice, eggs, and vegetable curry.","native":"我会做米饭、鸡蛋和蔬菜咖喱。"},{"en":"Last week I cooked soup for my grandmother.","native":"上周我给奶奶做了汤。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'restaurant', 'Talk about a restaurant you like. What food do you eat there?', '{"te":{"word":"రెస్టారెంట్","question":"మీకు ఇష్టమైన రెస్టారెంట్ గురించి మాట్లాడండి. మీరు అక్కడ ఏ ఆహారం తింటారు?","examples":[{"en":"My favourite restaurant is near the bus station.","native":"నా ఇష్టమైన రెస్టారెంట్ బస్ స్టేషన్ దగ్గర ఉంది."},{"en":"I usually eat noodles and drink fresh juice there.","native":"నేను సాధారణంగా అక్కడ నూడుల్స్ తిని తాజా జ్యూస్ తాగుతాను."},{"en":"Last month I went there with my whole family.","native":"గత నెల నేను నా మొత్తం కుటుంబంతో అక్కడికి వెళ్ళాను."}]},"hi":{"word":"रेस्तराँ","question":"अपने पसंदीदा रेस्तराँ के बारे में बताइए। आप वहाँ क्या खाते हैं?","examples":[{"en":"My favourite restaurant is near the bus station.","native":"मेरा पसंदीदा रेस्तराँ बस स्टेशन के पास है।"},{"en":"I usually eat noodles and drink fresh juice there.","native":"मैं वहाँ आमतौर पर नूडल्स खाता हूँ और ताज़ा जूस पीता हूँ।"},{"en":"Last month I went there with my whole family.","native":"पिछले महीने मैं अपने पूरे परिवार के साथ वहाँ गया।"}]},"es":{"word":"restaurante","question":"Habla de un restaurante que te gusta. ¿Qué comes allí?","examples":[{"en":"My favourite restaurant is near the bus station.","native":"Mi restaurante favorito está cerca de la estación de autobuses."},{"en":"I usually eat noodles and drink fresh juice there.","native":"Normalmente como fideos y bebo jugo fresco allí."},{"en":"Last month I went there with my whole family.","native":"El mes pasado fui allí con toda mi familia."}]},"zh":{"word":"餐馆","question":"谈谈你喜欢的一家餐馆。你在那里吃什么？","examples":[{"en":"My favourite restaurant is near the bus station.","native":"我最喜欢的餐馆在公交车站附近。"},{"en":"I usually eat noodles and drink fresh juice there.","native":"我通常在那里吃面条，喝新鲜的果汁。"},{"en":"Last month I went there with my whole family.","native":"上个月我和全家人一起去了那里。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'pet', 'Do you have a pet? Talk about it, or a pet you want.', '{"te":{"word":"పెంపుడు జంతువు","question":"మీకు పెంపుడు జంతువు ఉందా? దాని గురించి లేదా మీకు కావాల్సిన పెంపుడు జంతువు గురించి మాట్లాడండి.","examples":[{"en":"I have a small white cat at home.","native":"మా ఇంట్లో నాకు ఒక చిన్న తెల్ల పిల్లి ఉంది."},{"en":"She sleeps on my bed and plays with string.","native":"అది నా మంచంపై నిద్రిస్తుంది మరియు దారంతో ఆడుకుంటుంది."},{"en":"I am going to buy a fish tank next month.","native":"వచ్చే నెల నేను ఒక చేపల ట్యాంక్ కొనబోతున్నాను."}]},"hi":{"word":"पालतू जानवर","question":"क्या आपके पास कोई पालतू जानवर है? उसके बारे में बताइए, या किसी ऐसे जानवर के बारे में जो आप चाहते हैं।","examples":[{"en":"I have a small white cat at home.","native":"मेरे घर पर एक छोटी सफ़ेद बिल्ली है।"},{"en":"She sleeps on my bed and plays with string.","native":"वह मेरे बिस्तर पर सोती है और डोरी से खेलती है।"},{"en":"I am going to buy a fish tank next month.","native":"मैं अगले महीने एक मछलीघर खरीदने वाला हूँ।"}]},"es":{"word":"mascota","question":"¿Tienes una mascota? Habla de ella, o de una mascota que quieras.","examples":[{"en":"I have a small white cat at home.","native":"Tengo un pequeño gato blanco en casa."},{"en":"She sleeps on my bed and plays with string.","native":"Ella duerme en mi cama y juega con un cordón."},{"en":"I am going to buy a fish tank next month.","native":"Voy a comprar una pecera el mes que viene."}]},"zh":{"word":"宠物","question":"你有宠物吗？谈谈它，或者你想要的宠物。","examples":[{"en":"I have a small white cat at home.","native":"我家里有一只白色的小猫。"},{"en":"She sleeps on my bed and plays with string.","native":"它睡在我的床上，还喜欢玩绳子。"},{"en":"I am going to buy a fish tank next month.","native":"下个月我打算买一个鱼缸。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'dog', 'Do you like dogs? Talk about a dog you know.', '{"te":{"word":"కుక్క","question":"మీకు కుక్కలు ఇష్టమా? మీకు తెలిసిన ఒక కుక్క గురించి మాట్లాడండి.","examples":[{"en":"My uncle has a big brown dog called Tommy.","native":"మా మామయ్యకు టామీ అనే ఒక పెద్ద గోధుమ రంగు కుక్క ఉంది."},{"en":"He runs in the garden and likes to swim.","native":"అది తోటలో పరుగెత్తుతుంది మరియు ఈత కొట్టడం ఇష్టపడుతుంది."},{"en":"Every evening I take him for a walk.","native":"ప్రతి సాయంత్రం నేను దానిని నడవడానికి తీసుకెళ్తాను."}]},"hi":{"word":"कुत्ता","question":"क्या आपको कुत्ते पसंद हैं? किसी जानने वाले कुत्ते के बारे में बताइए।","examples":[{"en":"My uncle has a big brown dog called Tommy.","native":"मेरे चाचा के पास टॉमी नाम का एक बड़ा भूरा कुत्ता है।"},{"en":"He runs in the garden and likes to swim.","native":"वह बगीचे में दौड़ता है और तैरना पसंद करता है।"},{"en":"Every evening I take him for a walk.","native":"हर शाम मैं उसे घूमने ले जाता हूँ।"}]},"es":{"word":"perro","question":"¿Te gustan los perros? Habla de un perro que conoces.","examples":[{"en":"My uncle has a big brown dog called Tommy.","native":"Mi tío tiene un perro marrón grande llamado Tommy."},{"en":"He runs in the garden and likes to swim.","native":"Él corre en el jardín y le gusta nadar."},{"en":"Every evening I take him for a walk.","native":"Cada tarde lo saco a pasear."}]},"zh":{"word":"狗","question":"你喜欢狗吗？谈谈你认识的一只狗。","examples":[{"en":"My uncle has a big brown dog called Tommy.","native":"我叔叔有一只叫汤米的棕色大狗。"},{"en":"He runs in the garden and likes to swim.","native":"它在花园里跑来跑去，还喜欢游泳。"},{"en":"Every evening I take him for a walk.","native":"每天傍晚我都带它去散步。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'bus', 'How do you travel to work or school? Do you take the bus?', '{"te":{"word":"బస్సు","question":"మీరు పనికి లేదా పాఠశాలకు ఎలా వెళ్తారు? మీరు బస్సు తీసుకుంటారా?","examples":[{"en":"I take the bus to work every morning.","native":"నేను ప్రతి ఉదయం పనికి బస్సులో వెళ్తాను."},{"en":"The bus stop is near my house, so it is easy.","native":"బస్ స్టాప్ మా ఇంటి దగ్గర ఉంది, కాబట్టి అది సులభం."},{"en":"Yesterday the bus was late, so I walked.","native":"నిన్న బస్సు ఆలస్యమైంది, కాబట్టి నేను నడిచి వెళ్ళాను."}]},"hi":{"word":"बस","question":"आप काम या स्कूल कैसे जाते हैं? क्या आप बस लेते हैं?","examples":[{"en":"I take the bus to work every morning.","native":"मैं हर सुबह काम पर बस से जाता हूँ।"},{"en":"The bus stop is near my house, so it is easy.","native":"बस स्टॉप मेरे घर के पास है, इसलिए यह आसान है।"},{"en":"Yesterday the bus was late, so I walked.","native":"कल बस देर से आई, इसलिए मैं पैदल गया।"}]},"es":{"word":"autobús","question":"¿Cómo vas al trabajo o a la escuela? ¿Tomas el autobús?","examples":[{"en":"I take the bus to work every morning.","native":"Tomo el autobús al trabajo todas las mañanas."},{"en":"The bus stop is near my house, so it is easy.","native":"La parada de autobús está cerca de mi casa, así que es fácil."},{"en":"Yesterday the bus was late, so I walked.","native":"Ayer el autobús llegó tarde, así que caminé."}]},"zh":{"word":"公交车","question":"你怎么去上班或上学？你坐公交车吗？","examples":[{"en":"I take the bus to work every morning.","native":"我每天早上坐公交车去上班。"},{"en":"The bus stop is near my house, so it is easy.","native":"公交车站就在我家附近，所以很方便。"},{"en":"Yesterday the bus was late, so I walked.","native":"昨天公交车晚点了，所以我走路去的。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'train', 'Do you like travelling by train? Talk about a train journey.', '{"te":{"word":"రైలు","question":"మీకు రైలులో ప్రయాణించడం ఇష్టమా? ఒక రైలు ప్రయాణం గురించి మాట్లాడండి.","examples":[{"en":"I like travelling by train because it is comfortable.","native":"రైలులో ప్రయాణించడం నాకు ఇష్టం ఎందుకంటే అది సౌకర్యవంతంగా ఉంటుంది."},{"en":"Last summer I took a train to the mountains.","native":"గత వేసవిలో నేను పర్వతాలకు రైలు తీసుకున్నాను."},{"en":"The journey was long, but the views were beautiful.","native":"ప్రయాణం పొడవుగా ఉంది, కానీ దృశ్యాలు అందంగా ఉన్నాయి."}]},"hi":{"word":"ट्रेन","question":"क्या आपको ट्रेन से यात्रा करना पसंद है? किसी ट्रेन यात्रा के बारे में बताइए।","examples":[{"en":"I like travelling by train because it is comfortable.","native":"मुझे ट्रेन से यात्रा करना पसंद है क्योंकि यह आरामदायक है।"},{"en":"Last summer I took a train to the mountains.","native":"पिछली गर्मी में मैंने पहाड़ों के लिए ट्रेन ली।"},{"en":"The journey was long, but the views were beautiful.","native":"यात्रा लंबी थी, लेकिन नज़ारे खूबसूरत थे।"}]},"es":{"word":"tren","question":"¿Te gusta viajar en tren? Habla de un viaje en tren.","examples":[{"en":"I like travelling by train because it is comfortable.","native":"Me gusta viajar en tren porque es cómodo."},{"en":"Last summer I took a train to the mountains.","native":"El verano pasado tomé un tren a las montañas."},{"en":"The journey was long, but the views were beautiful.","native":"El viaje fue largo, pero las vistas eran hermosas."}]},"zh":{"word":"火车","question":"你喜欢坐火车旅行吗？谈谈一次火车旅行。","examples":[{"en":"I like travelling by train because it is comfortable.","native":"我喜欢坐火车旅行，因为很舒服。"},{"en":"Last summer I took a train to the mountains.","native":"去年夏天我坐火车去了山区。"},{"en":"The journey was long, but the views were beautiful.","native":"旅程很长，但风景很美。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'bicycle', 'Do you have a bicycle? Where do you like to ride it?', '{"te":{"word":"సైకిల్","question":"మీకు సైకిల్ ఉందా? మీరు దానిని ఎక్కడ తొక్కడానికి ఇష్టపడతారు?","examples":[{"en":"I have a red bicycle and I ride it every day.","native":"నాకు ఒక ఎర్రటి సైకిల్ ఉంది, నేను దానిని ప్రతిరోజూ తొక్కుతాను."},{"en":"Last Sunday I rode my bicycle to the lake.","native":"గత ఆదివారం నేను నా సైకిల్‌ను సరస్సు దగ్గరికి తొక్కాను."},{"en":"I am going to buy a new helmet next week.","native":"వచ్చే వారం నేను ఒక కొత్త హెల్మెట్ కొనబోతున్నాను."}]},"hi":{"word":"साइकिल","question":"क्या आपके पास साइकिल है? आप इसे कहाँ चलाना पसंद करते हैं?","examples":[{"en":"I have a red bicycle and I ride it every day.","native":"मेरे पास एक लाल साइकिल है और मैं इसे रोज़ चलाता हूँ।"},{"en":"Last Sunday I rode my bicycle to the lake.","native":"पिछले रविवार मैं अपनी साइकिल से झील तक गया।"},{"en":"I am going to buy a new helmet next week.","native":"मैं अगले हफ़्ते एक नया हेलमेट खरीदने वाला हूँ।"}]},"es":{"word":"bicicleta","question":"¿Tienes bicicleta? ¿Dónde te gusta montarla?","examples":[{"en":"I have a red bicycle and I ride it every day.","native":"Tengo una bicicleta roja y la monto todos los días."},{"en":"Last Sunday I rode my bicycle to the lake.","native":"El domingo pasado fui en bicicleta hasta el lago."},{"en":"I am going to buy a new helmet next week.","native":"Voy a comprar un casco nuevo la semana que viene."}]},"zh":{"word":"自行车","question":"你有自行车吗？你喜欢骑它去哪里？","examples":[{"en":"I have a red bicycle and I ride it every day.","native":"我有一辆红色的自行车，我每天都骑它。"},{"en":"Last Sunday I rode my bicycle to the lake.","native":"上个星期天我骑自行车去了湖边。"},{"en":"I am going to buy a new helmet next week.","native":"下周我打算买一个新头盔。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'car', 'Does your family have a car? Talk about a trip by car.', '{"te":{"word":"కారు","question":"మీ కుటుంబానికి కారు ఉందా? కారులో చేసిన ఒక ప్రయాణం గురించి మాట్లాడండి.","examples":[{"en":"My father drives an old blue car to work.","native":"మా నాన్న పనికి పాత నీలిరంగు కారు నడుపుతారు."},{"en":"Last month we drove to the beach in our car.","native":"గత నెల మేము మా కారులో బీచ్‌కి వెళ్ళాము."},{"en":"I am going to learn to drive next year.","native":"వచ్చే సంవత్సరం నేను డ్రైవింగ్ నేర్చుకోబోతున్నాను."}]},"hi":{"word":"कार","question":"क्या आपके परिवार के पास कार है? कार की किसी यात्रा के बारे में बताइए।","examples":[{"en":"My father drives an old blue car to work.","native":"मेरे पिता काम पर पुरानी नीली कार चलाते हैं।"},{"en":"Last month we drove to the beach in our car.","native":"पिछले महीने हम अपनी कार से समुद्र तट गए।"},{"en":"I am going to learn to drive next year.","native":"मैं अगले साल गाड़ी चलाना सीखने वाला हूँ।"}]},"es":{"word":"coche","question":"¿Tu familia tiene coche? Habla de un viaje en coche.","examples":[{"en":"My father drives an old blue car to work.","native":"Mi padre conduce un viejo coche azul al trabajo."},{"en":"Last month we drove to the beach in our car.","native":"El mes pasado fuimos a la playa en nuestro coche."},{"en":"I am going to learn to drive next year.","native":"Voy a aprender a conducir el año que viene."}]},"zh":{"word":"汽车","question":"你家有汽车吗？谈谈一次坐汽车的旅行。","examples":[{"en":"My father drives an old blue car to work.","native":"我爸爸开着一辆旧的蓝色汽车去上班。"},{"en":"Last month we drove to the beach in our car.","native":"上个月我们开车去了海滩。"},{"en":"I am going to learn to drive next year.","native":"明年我打算学开车。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'music', 'What kind of music do you like? When do you listen to music?', '{"te":{"word":"సంగీతం","question":"మీకు ఎలాంటి సంగీతం ఇష్టం? మీరు ఎప్పుడు సంగీతం వింటారు?","examples":[{"en":"I like pop music and old film songs.","native":"నాకు పాప్ మ్యూజిక్ మరియు పాత సినిమా పాటలు ఇష్టం."},{"en":"I listen to music when I cook dinner.","native":"నేను రాత్రి భోజనం వంట చేసేటప్పుడు సంగీతం వింటాను."},{"en":"Yesterday my brother played the guitar for us.","native":"నిన్న నా సోదరుడు మా కోసం గిటార్ వాయించాడు."}]},"hi":{"word":"संगीत","question":"आपको किस तरह का संगीत पसंद है? आप कब संगीत सुनते हैं?","examples":[{"en":"I like pop music and old film songs.","native":"मुझे पॉप संगीत और पुराने फ़िल्मी गाने पसंद हैं।"},{"en":"I listen to music when I cook dinner.","native":"मैं खाना बनाते समय संगीत सुनता हूँ।"},{"en":"Yesterday my brother played the guitar for us.","native":"कल मेरे भाई ने हमारे लिए गिटार बजाया।"}]},"es":{"word":"música","question":"¿Qué tipo de música te gusta? ¿Cuándo escuchas música?","examples":[{"en":"I like pop music and old film songs.","native":"Me gusta la música pop y las canciones viejas de películas."},{"en":"I listen to music when I cook dinner.","native":"Escucho música cuando cocino la cena."},{"en":"Yesterday my brother played the guitar for us.","native":"Ayer mi hermano tocó la guitarra para nosotros."}]},"zh":{"word":"音乐","question":"你喜欢什么样的音乐？你什么时候听音乐？","examples":[{"en":"I like pop music and old film songs.","native":"我喜欢流行音乐和老的影视歌曲。"},{"en":"I listen to music when I cook dinner.","native":"我做晚饭的时候听音乐。"},{"en":"Yesterday my brother played the guitar for us.","native":"昨天我哥哥为我们弹了吉他。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'dance', 'Can you dance? Talk about a time you danced.', '{"te":{"word":"నృత్యం","question":"మీకు డ్యాన్స్ చేయడం వస్తుందా? మీరు డ్యాన్స్ చేసిన ఒక సందర్భం గురించి మాట్లాడండి.","examples":[{"en":"I can dance a little, but not very well.","native":"నేను కొంచెం డ్యాన్స్ చేయగలను, కానీ బాగా చేయలేను."},{"en":"At my cousin''s wedding, everyone danced all night.","native":"నా కజిన్ పెళ్ళిలో, అందరూ రాత్రిఅంతా డ్యాన్స్ చేశారు."},{"en":"I am going to join a dance class soon.","native":"నేను త్వరలో ఒక డ్యాన్స్ క్లాసులో చేరబోతున్నాను."}]},"hi":{"word":"नृत्य","question":"क्या आप नाच सकते हैं? किसी ऐसे समय के बारे में बताइए जब आप नाचे।","examples":[{"en":"I can dance a little, but not very well.","native":"मैं थोड़ा नाच सकता हूँ, लेकिन बहुत अच्छा नहीं।"},{"en":"At my cousin''s wedding, everyone danced all night.","native":"मेरे चचेरे भाई की शादी में, सभी लोग रात भर नाचे।"},{"en":"I am going to join a dance class soon.","native":"मैं जल्द ही एक डांस क्लास में शामिल होने वाला हूँ।"}]},"es":{"word":"baile","question":"¿Sabes bailar? Habla de una vez que bailaste.","examples":[{"en":"I can dance a little, but not very well.","native":"Sé bailar un poco, pero no muy bien."},{"en":"At my cousin''s wedding, everyone danced all night.","native":"En la boda de mi primo, todos bailaron toda la noche."},{"en":"I am going to join a dance class soon.","native":"Voy a apuntarme a una clase de baile pronto."}]},"zh":{"word":"舞蹈","question":"你会跳舞吗？谈谈你跳舞的一次经历。","examples":[{"en":"I can dance a little, but not very well.","native":"我会跳一点舞，但跳得不太好。"},{"en":"At my cousin''s wedding, everyone danced all night.","native":"在我表哥的婚礼上，大家跳了一整夜。"},{"en":"I am going to join a dance class soon.","native":"我很快要参加一个舞蹈班。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'sport', 'What sports do you like? Do you play or watch them?', '{"te":{"word":"క్రీడ","question":"మీకు ఏ క్రీడలు ఇష్టం? మీరు వాటిని ఆడతారా లేదా చూస్తారా?","examples":[{"en":"My favourite sport is cricket because it is exciting.","native":"నా ఇష్టమైన క్రీడ క్రికెట్ ఎందుకంటే అది ఉత్తేజకరంగా ఉంటుంది."},{"en":"I play badminton with my friends on Sundays.","native":"నేను ఆదివారాల్లో నా స్నేహితులతో బ్యాడ్మింటన్ ఆడతాను."},{"en":"Last night we watched a football match on television.","native":"నిన్న రాత్రి మేము టెలివిజన్‌లో ఫుట్‌బాల్ మ్యాచ్ చూశాము."}]},"hi":{"word":"खेल","question":"आपको कौन से खेल पसंद हैं? आप उन्हें खेलते हैं या देखते हैं?","examples":[{"en":"My favourite sport is cricket because it is exciting.","native":"मेरा पसंदीदा खेल क्रिकेट है क्योंकि यह रोमांचक है।"},{"en":"I play badminton with my friends on Sundays.","native":"मैं रविवार को अपने दोस्तों के साथ बैडमिंटन खेलता हूँ।"},{"en":"Last night we watched a football match on television.","native":"कल रात हमने टेलीविज़न पर फ़ुटबॉल मैच देखा।"}]},"es":{"word":"deporte","question":"¿Qué deportes te gustan? ¿Los practicas o los ves?","examples":[{"en":"My favourite sport is cricket because it is exciting.","native":"Mi deporte favorito es el críquet porque es emocionante."},{"en":"I play badminton with my friends on Sundays.","native":"Juego al bádminton con mis amigos los domingos."},{"en":"Last night we watched a football match on television.","native":"Anoche vimos un partido de fútbol en la televisión."}]},"zh":{"word":"运动","question":"你喜欢什么运动？你是亲自参与还是观看？","examples":[{"en":"My favourite sport is cricket because it is exciting.","native":"我最喜欢的运动是板球，因为它很刺激。"},{"en":"I play badminton with my friends on Sundays.","native":"我星期天和朋友们一起打羽毛球。"},{"en":"Last night we watched a football match on television.","native":"昨晚我们在电视上看了一场足球比赛。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'football', 'Do you like football? Talk about a match you saw or played.', '{"te":{"word":"ఫుట్‌బాల్","question":"మీకు ఫుట్‌బాల్ ఇష్టమా? మీరు చూసిన లేదా ఆడిన ఒక మ్యాచ్ గురించి మాట్లాడండి.","examples":[{"en":"I play football with my classmates after school.","native":"నేను పాఠశాల తర్వాత నా క్లాస్‌మేట్స్‌తో ఫుట్‌బాల్ ఆడతాను."},{"en":"Last week our team won the school match.","native":"గత వారం మా జట్టు పాఠశాల మ్యాచ్‌లో గెలిచింది."},{"en":"I am going to watch the final with my father.","native":"నేను నా నాన్నతో కలిసి ఫైనల్ చూడబోతున్నాను."}]},"hi":{"word":"फ़ुटबॉल","question":"क्या आपको फ़ुटबॉल पसंद है? किसी मैच के बारे में बताइए जो आपने देखा या खेला।","examples":[{"en":"I play football with my classmates after school.","native":"मैं स्कूल के बाद अपने सहपाठियों के साथ फ़ुटबॉल खेलता हूँ।"},{"en":"Last week our team won the school match.","native":"पिछले हफ़्ते हमारी टीम ने स्कूल का मैच जीता।"},{"en":"I am going to watch the final with my father.","native":"मैं अपने पिता के साथ फ़ाइनल देखने वाला हूँ।"}]},"es":{"word":"fútbol","question":"¿Te gusta el fútbol? Habla de un partido que viste o jugaste.","examples":[{"en":"I play football with my classmates after school.","native":"Juego al fútbol con mis compañeros después de clase."},{"en":"Last week our team won the school match.","native":"La semana pasada nuestro equipo ganó el partido del colegio."},{"en":"I am going to watch the final with my father.","native":"Voy a ver la final con mi padre."}]},"zh":{"word":"足球","question":"你喜欢足球吗？谈谈你看过或踢过的一场比赛。","examples":[{"en":"I play football with my classmates after school.","native":"放学后我和同学们一起踢足球。"},{"en":"Last week our team won the school match.","native":"上周我们队赢了学校的比赛。"},{"en":"I am going to watch the final with my father.","native":"我打算和爸爸一起看决赛。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'swimming', 'Can you swim? Where do you like to swim?', '{"te":{"word":"ఈత","question":"మీకు ఈత వస్తుందా? మీరు ఎక్కడ ఈత కొట్టడం ఇష్టపడతారు?","examples":[{"en":"I learned to swim when I was ten.","native":"నాకు పది సంవత్సరాల వయసులో ఈత నేర్చుకున్నాను."},{"en":"In summer I swim in the river near my village.","native":"వేసవిలో నేను మా ఊరి దగ్గర నదిలో ఈత కొడతాను."},{"en":"Next month I am going to join a swimming pool.","native":"వచ్చే నెల నేను ఒక స్విమ్మింగ్ పూల్‌లో చేరబోతున్నాను."}]},"hi":{"word":"तैराकी","question":"क्या आप तैर सकते हैं? आप कहाँ तैरना पसंद करते हैं?","examples":[{"en":"I learned to swim when I was ten.","native":"मैंने दस साल की उम्र में तैरना सीखा।"},{"en":"In summer I swim in the river near my village.","native":"गर्मियों में मैं अपने गाँव के पास की नदी में तैरता हूँ।"},{"en":"Next month I am going to join a swimming pool.","native":"मैं अगले महीने एक स्विमिंग पूल में शामिल होने वाला हूँ।"}]},"es":{"word":"natación","question":"¿Sabes nadar? ¿Dónde te gusta nadar?","examples":[{"en":"I learned to swim when I was ten.","native":"Aprendí a nadar cuando tenía diez años."},{"en":"In summer I swim in the river near my village.","native":"En verano nado en el río cerca de mi pueblo."},{"en":"Next month I am going to join a swimming pool.","native":"El mes que viene voy a apuntarme a una piscina."}]},"zh":{"word":"游泳","question":"你会游泳吗？你喜欢在哪里游泳？","examples":[{"en":"I learned to swim when I was ten.","native":"我十岁的时候学会了游泳。"},{"en":"In summer I swim in the river near my village.","native":"夏天我在村子附近的河里游泳。"},{"en":"Next month I am going to join a swimming pool.","native":"下个月我打算去游泳馆报名。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'game', 'What games do you play? Who do you play with?', '{"te":{"word":"ఆట","question":"మీరు ఏ ఆటలు ఆడతారు? మీరు ఎవరితో ఆడతారు?","examples":[{"en":"I play chess with my grandfather every evening.","native":"నేను ప్రతి సాయంత్రం నా తాతయ్యతో చదరంగం ఆడతాను."},{"en":"My little sister likes to play card games.","native":"నా చిన్న చెల్లెలు పేకాట ఆడడం ఇష్టపడుతుంది."},{"en":"Yesterday we played a new game on the phone.","native":"నిన్న మేము ఫోన్‌లో ఒక కొత్త గేమ్ ఆడాము."}]},"hi":{"word":"खेल","question":"आप कौन से खेल खेलते हैं? आप किसके साथ खेलते हैं?","examples":[{"en":"I play chess with my grandfather every evening.","native":"मैं हर शाम अपने दादा के साथ शतरंज खेलता हूँ।"},{"en":"My little sister likes to play card games.","native":"मेरी छोटी बहन को ताश के खेल खेलना पसंद है।"},{"en":"Yesterday we played a new game on the phone.","native":"कल हमने फ़ोन पर एक नया गेम खेला।"}]},"es":{"word":"juego","question":"¿A qué juegos juegas? ¿Con quién juegas?","examples":[{"en":"I play chess with my grandfather every evening.","native":"Juego al ajedrez con mi abuelo todas las tardes."},{"en":"My little sister likes to play card games.","native":"A mi hermana pequeña le gusta jugar a juegos de cartas."},{"en":"Yesterday we played a new game on the phone.","native":"Ayer jugamos a un juego nuevo en el teléfono."}]},"zh":{"word":"游戏","question":"你玩什么游戏？你和谁一起玩？","examples":[{"en":"I play chess with my grandfather every evening.","native":"我每天傍晚和爷爷一起下国际象棋。"},{"en":"My little sister likes to play card games.","native":"我妹妹喜欢玩纸牌游戏。"},{"en":"Yesterday we played a new game on the phone.","native":"昨天我们在手机上玩了一个新游戏。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'book', 'Do you like reading books? Talk about a book you enjoyed.', '{"te":{"word":"పుస్తకం","question":"మీకు పుస్తకాలు చదవడం ఇష్టమా? మీరు ఆస్వాదించిన ఒక పుస్తకం గురించి మాట్లాడండి.","examples":[{"en":"I read storybooks before I go to sleep.","native":"నేను నిద్రపోయే ముందు కథా పుస్తకాలు చదువుతాను."},{"en":"Last month I read a long book about the sea.","native":"గత నెల నేను సముద్రం గురించి ఒక పొడవైన పుస్తకం చదివాను."},{"en":"I am going to buy a new book this weekend.","native":"ఈ వారాంతంలో నేను ఒక కొత్త పుస్తకం కొనబోతున్నాను."}]},"hi":{"word":"किताब","question":"क्या आपको किताबें पढ़ना पसंद है? किसी पसंद आई किताब के बारे में बताइए।","examples":[{"en":"I read storybooks before I go to sleep.","native":"मैं सोने से पहले कहानियों की किताबें पढ़ता हूँ।"},{"en":"Last month I read a long book about the sea.","native":"पिछले महीने मैंने समुद्र के बारे में एक लंबी किताब पढ़ी।"},{"en":"I am going to buy a new book this weekend.","native":"मैं इस सप्ताहांत एक नई किताब खरीदने वाला हूँ।"}]},"es":{"word":"libro","question":"¿Te gusta leer libros? Habla de un libro que disfrutaste.","examples":[{"en":"I read storybooks before I go to sleep.","native":"Leo cuentos antes de dormirme."},{"en":"Last month I read a long book about the sea.","native":"El mes pasado leí un libro largo sobre el mar."},{"en":"I am going to buy a new book this weekend.","native":"Voy a comprar un libro nuevo este fin de semana."}]},"zh":{"word":"书","question":"你喜欢读书吗？谈谈你喜欢的一本书。","examples":[{"en":"I read storybooks before I go to sleep.","native":"我睡觉前读故事书。"},{"en":"Last month I read a long book about the sea.","native":"上个月我读了一本关于大海的书。"},{"en":"I am going to buy a new book this weekend.","native":"这个周末我打算买一本新书。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'reading', 'Do you like reading? What do you usually read?', '{"te":{"word":"చదవడం","question":"మీకు చదవడం ఇష్టమా? మీరు సాధారణంగా ఏమి చదువుతారు?","examples":[{"en":"I like reading the newspaper in the morning.","native":"ఉదయం వార్తాపత్రిక చదవడం నాకు ఇష్టం."},{"en":"My little sister reads comics on her phone.","native":"నా చిన్న చెల్లెలు తన ఫోన్‌లో కామిక్స్ చదువుతుంది."},{"en":"Last week I read an interesting story about animals.","native":"గత వారం నేను జంతువుల గురించి ఒక ఆసక్తికరమైన కథ చదివాను."}]},"hi":{"word":"पढ़ना","question":"क्या आपको पढ़ना पसंद है? आप आमतौर पर क्या पढ़ते हैं?","examples":[{"en":"I like reading the newspaper in the morning.","native":"मुझे सुबह अख़बार पढ़ना पसंद है।"},{"en":"My little sister reads comics on her phone.","native":"मेरी छोटी बहन अपने फ़ोन पर कॉमिक्स पढ़ती है।"},{"en":"Last week I read an interesting story about animals.","native":"पिछले हफ़्ते मैंने जानवरों के बारे में एक रोचक कहानी पढ़ी।"}]},"es":{"word":"lectura","question":"¿Te gusta leer? ¿Qué sueles leer?","examples":[{"en":"I like reading the newspaper in the morning.","native":"Me gusta leer el periódico por la mañana."},{"en":"My little sister reads comics on her phone.","native":"Mi hermana pequeña lee cómics en su teléfono."},{"en":"Last week I read an interesting story about animals.","native":"La semana pasada leí una historia interesante sobre animales."}]},"zh":{"word":"阅读","question":"你喜欢阅读吗？你通常读什么？","examples":[{"en":"I like reading the newspaper in the morning.","native":"我喜欢早上读报纸。"},{"en":"My little sister reads comics on her phone.","native":"我妹妹在手机上看漫画。"},{"en":"Last week I read an interesting story about animals.","native":"上周我读了一个关于动物的有趣故事。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'television', 'How often do you watch television? What programmes do you like?', '{"te":{"word":"టెలివిజన్","question":"మీరు ఎంత తరచుగా టెలివిజన్ చూస్తారు? మీకు ఏ కార్యక్రమాలు ఇష్టం?","examples":[{"en":"I watch television for an hour after dinner.","native":"నేను రాత్రి భోజనం తర్వాత ఒక గంట టెలివిజన్ చూస్తాను."},{"en":"My favourite programme is a comedy show on Saturdays.","native":"నా ఇష్టమైన కార్యక్రమం శనివారాల్లో వచ్చే ఒక హాస్య షో."},{"en":"Yesterday we watched a film together at home.","native":"నిన్న మేము ఇంట్లో కలిసి ఒక సినిమా చూశాము."}]},"hi":{"word":"टेलीविज़न","question":"आप कितनी बार टेलीविज़न देखते हैं? आपको कौन से कार्यक्रम पसंद हैं?","examples":[{"en":"I watch television for an hour after dinner.","native":"मैं रात के खाने के बाद एक घंटा टेलीविज़न देखता हूँ।"},{"en":"My favourite programme is a comedy show on Saturdays.","native":"मेरा पसंदीदा कार्यक्रम शनिवार को आने वाला एक कॉमेडी शो है।"},{"en":"Yesterday we watched a film together at home.","native":"कल हमने घर पर साथ मिलकर एक फ़िल्म देखी।"}]},"es":{"word":"televisión","question":"¿Con qué frecuencia ves la televisión? ¿Qué programas te gustan?","examples":[{"en":"I watch television for an hour after dinner.","native":"Veo la televisión una hora después de cenar."},{"en":"My favourite programme is a comedy show on Saturdays.","native":"Mi programa favorito es un programa de comedia de los sábados."},{"en":"Yesterday we watched a film together at home.","native":"Ayer vimos una película juntos en casa."}]},"zh":{"word":"电视","question":"你多久看一次电视？你喜欢什么节目？","examples":[{"en":"I watch television for an hour after dinner.","native":"我晚饭后看一个小时的电视。"},{"en":"My favourite programme is a comedy show on Saturdays.","native":"我最喜欢的节目是星期六播出的一个喜剧节目。"},{"en":"Yesterday we watched a film together at home.","native":"昨天我们一起在家看了一部电影。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'phone', 'How do you use your phone every day?', '{"te":{"word":"ఫోన్","question":"మీరు ప్రతిరోజూ మీ ఫోన్‌ను ఎలా ఉపయోగిస్తారు?","examples":[{"en":"I use my phone to call my mother every day.","native":"నేను ప్రతిరోజూ నా అమ్మకు కాల్ చేయడానికి నా ఫోన్ వాడతాను."},{"en":"I also take photos and listen to songs.","native":"నేను ఫోటోలు కూడా తీస్తాను, పాటలు కూడా వింటాను."},{"en":"Yesterday I spoke to my friend for an hour.","native":"నిన్న నేను నా స్నేహితుడితో ఒక గంట మాట్లాడాను."}]},"hi":{"word":"फ़ोन","question":"आप रोज़ अपना फ़ोन कैसे इस्तेमाल करते हैं?","examples":[{"en":"I use my phone to call my mother every day.","native":"मैं रोज़ अपनी माँ को फ़ोन करने के लिए अपना फ़ोन इस्तेमाल करता हूँ।"},{"en":"I also take photos and listen to songs.","native":"मैं तस्वीरें भी लेता हूँ और गाने भी सुनता हूँ।"},{"en":"Yesterday I spoke to my friend for an hour.","native":"कल मैंने अपने दोस्त से एक घंटा बात की।"}]},"es":{"word":"teléfono","question":"¿Cómo usas tu teléfono todos los días?","examples":[{"en":"I use my phone to call my mother every day.","native":"Uso mi teléfono para llamar a mi madre todos los días."},{"en":"I also take photos and listen to songs.","native":"También hago fotos y escucho canciones."},{"en":"Yesterday I spoke to my friend for an hour.","native":"Ayer hablé con mi amigo durante una hora."}]},"zh":{"word":"手机","question":"你每天怎么使用手机？","examples":[{"en":"I use my phone to call my mother every day.","native":"我每天用手机给妈妈打电话。"},{"en":"I also take photos and listen to songs.","native":"我还用它拍照、听歌。"},{"en":"Yesterday I spoke to my friend for an hour.","native":"昨天我和朋友聊了一个小时。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'computer', 'Do you use a computer? What do you do with it?', '{"te":{"word":"కంప్యూటర్","question":"మీరు కంప్యూటర్ వాడతారా? మీరు దానితో ఏమి చేస్తారు?","examples":[{"en":"I use a computer at work every day.","native":"నేను పనిలో ప్రతిరోజూ కంప్యూటర్ వాడతాను."},{"en":"At home, I watch videos and write emails.","native":"ఇంట్లో, నేను వీడియోలు చూస్తాను, ఇమెయిల్స్ రాస్తాను."},{"en":"I am going to buy a new laptop next month.","native":"వచ్చే నెల నేను ఒక కొత్త ల్యాప్‌టాప్ కొనబోతున్నాను."}]},"hi":{"word":"कंप्यूटर","question":"क्या आप कंप्यूटर इस्तेमाल करते हैं? आप उससे क्या करते हैं?","examples":[{"en":"I use a computer at work every day.","native":"मैं काम पर रोज़ कंप्यूटर इस्तेमाल करता हूँ।"},{"en":"At home, I watch videos and write emails.","native":"घर पर, मैं वीडियो देखता हूँ और ईमेल लिखता हूँ।"},{"en":"I am going to buy a new laptop next month.","native":"मैं अगले महीने एक नया लैपटॉप खरीदने वाला हूँ।"}]},"es":{"word":"computadora","question":"¿Usas una computadora? ¿Qué haces con ella?","examples":[{"en":"I use a computer at work every day.","native":"Uso una computadora en el trabajo todos los días."},{"en":"At home, I watch videos and write emails.","native":"En casa, veo vídeos y escribo correos."},{"en":"I am going to buy a new laptop next month.","native":"Voy a comprar un portátil nuevo el mes que viene."}]},"zh":{"word":"电脑","question":"你使用电脑吗？你用它做什么？","examples":[{"en":"I use a computer at work every day.","native":"我上班每天都用电脑。"},{"en":"At home, I watch videos and write emails.","native":"在家里，我看视频、写邮件。"},{"en":"I am going to buy a new laptop next month.","native":"下个月我打算买一台新笔记本电脑。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'internet', 'How often do you use the internet? What do you do online?', '{"te":{"word":"ఇంటర్నెట్","question":"మీరు ఎంత తరచుగా ఇంటర్నెట్ వాడతారు? మీరు ఆన్‌లైన్‌లో ఏమి చేస్తారు?","examples":[{"en":"I use the internet every evening at home.","native":"నేను ప్రతి సాయంత్రం ఇంట్లో ఇంటర్నెట్ వాడతాను."},{"en":"I watch videos and talk to my friends online.","native":"నేను ఆన్‌లైన్‌లో వీడియోలు చూస్తాను, నా స్నేహితులతో మాట్లాడతాను."},{"en":"Yesterday I bought a shirt on the internet.","native":"నిన్న నేను ఇంటర్నెట్‌లో ఒక చొక్కా కొన్నాను."}]},"hi":{"word":"इंटरनेट","question":"आप कितनी बार इंटरनेट इस्तेमाल करते हैं? आप ऑनलाइन क्या करते हैं?","examples":[{"en":"I use the internet every evening at home.","native":"मैं हर शाम घर पर इंटरनेट इस्तेमाल करता हूँ।"},{"en":"I watch videos and talk to my friends online.","native":"मैं ऑनलाइन वीडियो देखता हूँ और अपने दोस्तों से बात करता हूँ।"},{"en":"Yesterday I bought a shirt on the internet.","native":"कल मैंने इंटरनेट पर एक कमीज़ खरीदी।"}]},"es":{"word":"internet","question":"¿Con qué frecuencia usas internet? ¿Qué haces en línea?","examples":[{"en":"I use the internet every evening at home.","native":"Uso internet todas las tardes en casa."},{"en":"I watch videos and talk to my friends online.","native":"Veo vídeos y hablo con mis amigos en línea."},{"en":"Yesterday I bought a shirt on the internet.","native":"Ayer compré una camisa por internet."}]},"zh":{"word":"互联网","question":"你多久上一次网？你在网上做什么？","examples":[{"en":"I use the internet every evening at home.","native":"我每天傍晚在家上网。"},{"en":"I watch videos and talk to my friends online.","native":"我在网上看视频、和朋友聊天。"},{"en":"Yesterday I bought a shirt on the internet.","native":"昨天我在网上买了一件衬衫。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'photo', 'Do you like taking photos? Talk about a photo you like.', '{"te":{"word":"ఫోటో","question":"మీకు ఫోటోలు తీయడం ఇష్టమా? మీకు నచ్చిన ఒక ఫోటో గురించి మాట్లాడండి.","examples":[{"en":"I like taking photos of flowers and birds.","native":"నాకు పువ్వులు, పక్షుల ఫోటోలు తీయడం ఇష్టం."},{"en":"My favourite photo is from my sister''s wedding.","native":"నా ఇష్టమైన ఫోటో నా అక్కయ్య పెళ్ళిలో తీసినది."},{"en":"Last week I took photos at the beach.","native":"గత వారం నేను బీచ్‌లో ఫోటోలు తీశాను."}]},"hi":{"word":"तस्वीर","question":"क्या आपको तस्वीरें लेना पसंद है? किसी पसंदीदा तस्वीर के बारे में बताइए।","examples":[{"en":"I like taking photos of flowers and birds.","native":"मुझे फूलों और पक्षियों की तस्वीरें लेना पसंद है।"},{"en":"My favourite photo is from my sister''s wedding.","native":"मेरी पसंदीदा तस्वीर मेरी बहन की शादी की है।"},{"en":"Last week I took photos at the beach.","native":"पिछले हफ़्ते मैंने समुद्र तट पर तस्वीरें लीं।"}]},"es":{"word":"foto","question":"¿Te gusta hacer fotos? Habla de una foto que te gusta.","examples":[{"en":"I like taking photos of flowers and birds.","native":"Me gusta hacer fotos de flores y pájaros."},{"en":"My favourite photo is from my sister''s wedding.","native":"Mi foto favorita es de la boda de mi hermana."},{"en":"Last week I took photos at the beach.","native":"La semana pasada hice fotos en la playa."}]},"zh":{"word":"照片","question":"你喜欢拍照吗？谈谈你喜欢的一张照片。","examples":[{"en":"I like taking photos of flowers and birds.","native":"我喜欢拍花和鸟的照片。"},{"en":"My favourite photo is from my sister''s wedding.","native":"我最喜欢的照片是在我姐姐的婚礼上拍的。"},{"en":"Last week I took photos at the beach.","native":"上周我在海滩拍了照片。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'garden', 'Do you have a garden? What grows there?', '{"te":{"word":"తోట","question":"మీకు తోట ఉందా? అక్కడ ఏమి పెరుగుతాయి?","examples":[{"en":"We have a small garden behind our house.","native":"మా ఇంటి వెనుక ఒక చిన్న తోట ఉంది."},{"en":"My grandmother grows tomatoes and green beans there.","native":"నా అమ్మమ్మ అక్కడ టమాటాలు, గ్రీన్ బీన్స్ పెంచుతుంది."},{"en":"In spring, many colourful flowers open in our garden.","native":"వసంతకాలంలో, మా తోటలో చాలా రంగురంగుల పువ్వులు వికసిస్తాయి."}]},"hi":{"word":"बगीचा","question":"क्या आपके पास बगीचा है? वहाँ क्या उगता है?","examples":[{"en":"We have a small garden behind our house.","native":"हमारे घर के पीछे एक छोटा बगीचा है।"},{"en":"My grandmother grows tomatoes and green beans there.","native":"मेरी दादी वहाँ टमाटर और हरी बीन्स उगाती हैं।"},{"en":"In spring, many colourful flowers open in our garden.","native":"वसंत में, हमारे बगीचे में कई रंगीन फूल खिलते हैं।"}]},"es":{"word":"jardín","question":"¿Tienes jardín? ¿Qué crece allí?","examples":[{"en":"We have a small garden behind our house.","native":"Tenemos un pequeño jardín detrás de nuestra casa."},{"en":"My grandmother grows tomatoes and green beans there.","native":"Mi abuela cultiva tomates y judías verdes allí."},{"en":"In spring, many colourful flowers open in our garden.","native":"En primavera, muchas flores de colores se abren en nuestro jardín."}]},"zh":{"word":"花园","question":"你有花园吗？那里种了什么？","examples":[{"en":"We have a small garden behind our house.","native":"我们房子后面有一个小花园。"},{"en":"My grandmother grows tomatoes and green beans there.","native":"我奶奶在那里种西红柿和青豆。"},{"en":"In spring, many colourful flowers open in our garden.","native":"春天，我们花园里开出许多五颜六色的花。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'flower', 'What is your favourite flower? Do you grow flowers?', '{"te":{"word":"పువ్వు","question":"మీ ఇష్టమైన పువ్వు ఏది? మీరు పువ్వులు పెంచుతారా?","examples":[{"en":"My favourite flower is the bright yellow sunflower.","native":"నా ఇష్టమైన పువ్వు ప్రకాశవంతమైన పసుపు పొద్దుతిరుగుడు పువ్వు."},{"en":"My mother grows roses in front of our house.","native":"మా అమ్మ మా ఇంటి ముందు గులాబీలు పెంచుతుంది."},{"en":"I gave my teacher some flowers on her birthday.","native":"నేను నా టీచర్ పుట్టినరోజున ఆమెకు కొన్ని పువ్వులు ఇచ్చాను."}]},"hi":{"word":"फूल","question":"आपका पसंदीदा फूल कौन सा है? क्या आप फूल उगाते हैं?","examples":[{"en":"My favourite flower is the bright yellow sunflower.","native":"मेरा पसंदीदा फूल चमकीला पीला सूरजमुखी है।"},{"en":"My mother grows roses in front of our house.","native":"मेरी माँ हमारे घर के सामने गुलाब उगाती है।"},{"en":"I gave my teacher some flowers on her birthday.","native":"मैंने अपनी टीचर के जन्मदिन पर उन्हें कुछ फूल दिए।"}]},"es":{"word":"flor","question":"¿Cuál es tu flor favorita? ¿Cultivas flores?","examples":[{"en":"My favourite flower is the bright yellow sunflower.","native":"Mi flor favorita es el brillante girasol amarillo."},{"en":"My mother grows roses in front of our house.","native":"Mi madre cultiva rosas delante de nuestra casa."},{"en":"I gave my teacher some flowers on her birthday.","native":"Le regalé unas flores a mi maestra en su cumpleaños."}]},"zh":{"word":"花","question":"你最喜欢的花是什么？你种花吗？","examples":[{"en":"My favourite flower is the bright yellow sunflower.","native":"我最喜欢的花是鲜艳的黄色向日葵。"},{"en":"My mother grows roses in front of our house.","native":"我妈妈在我们家门前种玫瑰。"},{"en":"I gave my teacher some flowers on her birthday.","native":"老师生日那天我送了她一些花。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'park', 'Is there a park near your home? What do you do there?', '{"te":{"word":"పార్క్","question":"మీ ఇంటి దగ్గర పార్క్ ఉందా? మీరు అక్కడ ఏమి చేస్తారు?","examples":[{"en":"There is a big park near my house.","native":"మా ఇంటి దగ్గర ఒక పెద్ద పార్క్ ఉంది."},{"en":"I walk there with my dog every morning.","native":"నేను ప్రతి ఉదయం నా కుక్కతో అక్కడ నడుస్తాను."},{"en":"Children play football in the park on Sundays.","native":"ఆదివారాల్లో పిల్లలు పార్కులో ఫుట్‌బాల్ ఆడతారు."}]},"hi":{"word":"पार्क","question":"क्या आपके घर के पास कोई पार्क है? आप वहाँ क्या करते हैं?","examples":[{"en":"There is a big park near my house.","native":"मेरे घर के पास एक बड़ा पार्क है।"},{"en":"I walk there with my dog every morning.","native":"मैं हर सुबह अपने कुत्ते के साथ वहाँ घूमता हूँ।"},{"en":"Children play football in the park on Sundays.","native":"रविवार को बच्चे पार्क में फ़ुटबॉल खेलते हैं।"}]},"es":{"word":"parque","question":"¿Hay un parque cerca de tu casa? ¿Qué haces allí?","examples":[{"en":"There is a big park near my house.","native":"Hay un parque grande cerca de mi casa."},{"en":"I walk there with my dog every morning.","native":"Paseo allí con mi perro todas las mañanas."},{"en":"Children play football in the park on Sundays.","native":"Los niños juegan al fútbol en el parque los domingos."}]},"zh":{"word":"公园","question":"你家附近有公园吗？你在那里做什么？","examples":[{"en":"There is a big park near my house.","native":"我家附近有一个大公园。"},{"en":"I walk there with my dog every morning.","native":"我每天早上带着我的狗在那里散步。"},{"en":"Children play football in the park on Sundays.","native":"星期天孩子们在公园里踢足球。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'beach', 'Do you like the beach? Talk about a day at the beach.', '{"te":{"word":"బీచ్","question":"మీకు బీచ్ ఇష్టమా? బీచ్‌లో గడిపిన ఒక రోజు గురించి మాట్లాడండి.","examples":[{"en":"I love walking on the sand in the evening.","native":"సాయంత్రం ఇసుకపై నడవడం నాకు చాలా ఇష్టం."},{"en":"Last year we spent a whole day at the beach.","native":"గత సంవత్సరం మేము బీచ్‌లో మొత్తం రోజు గడిపాము."},{"en":"I am going to visit the beach again this summer.","native":"ఈ వేసవిలో నేను మళ్ళీ బీచ్‌ను సందర్శించబోతున్నాను."}]},"hi":{"word":"समुद्र तट","question":"क्या आपको समुद्र तट पसंद है? समुद्र तट पर बिताए एक दिन के बारे में बताइए।","examples":[{"en":"I love walking on the sand in the evening.","native":"मुझे शाम को रेत पर घूमना बहुत पसंद है।"},{"en":"Last year we spent a whole day at the beach.","native":"पिछले साल हमने समुद्र तट पर पूरा दिन बिताया।"},{"en":"I am going to visit the beach again this summer.","native":"मैं इस गर्मी में फिर से समुद्र तट जाने वाला हूँ।"}]},"es":{"word":"playa","question":"¿Te gusta la playa? Habla de un día en la playa.","examples":[{"en":"I love walking on the sand in the evening.","native":"Me encanta caminar por la arena por la tarde."},{"en":"Last year we spent a whole day at the beach.","native":"El año pasado pasamos un día entero en la playa."},{"en":"I am going to visit the beach again this summer.","native":"Voy a visitar la playa otra vez este verano."}]},"zh":{"word":"海滩","question":"你喜欢海滩吗？谈谈在海滩度过的一天。","examples":[{"en":"I love walking on the sand in the evening.","native":"我喜欢傍晚在沙滩上散步。"},{"en":"Last year we spent a whole day at the beach.","native":"去年我们在海滩上玩了一整天。"},{"en":"I am going to visit the beach again this summer.","native":"今年夏天我打算再去一次海滩。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'rain', 'Do you like rain? What do you do on rainy days?', '{"te":{"word":"వర్షం","question":"మీకు వర్షం ఇష్టమా? వర్షం పడే రోజుల్లో మీరు ఏమి చేస్తారు?","examples":[{"en":"I like sitting near the window when it rains.","native":"వర్షం పడినప్పుడు కిటికీ దగ్గర కూర్చోవడం నాకు ఇష్టం."},{"en":"On rainy days I drink hot tea at home.","native":"వర్షం పడే రోజుల్లో నేను ఇంట్లో వేడి టీ తాగుతాను."},{"en":"Yesterday it rained, so I stayed at home.","native":"నిన్న వర్షం పడింది, కాబట్టి నేను ఇంట్లోనే ఉండిపోయాను."}]},"hi":{"word":"बारिश","question":"क्या आपको बारिश पसंद है? बारिश के दिनों में आप क्या करते हैं?","examples":[{"en":"I like sitting near the window when it rains.","native":"बारिश होने पर मुझे खिड़की के पास बैठना पसंद है।"},{"en":"On rainy days I drink hot tea at home.","native":"बारिश के दिनों में मैं घर पर गर्म चाय पीता हूँ।"},{"en":"Yesterday it rained, so I stayed at home.","native":"कल बारिश हुई, इसलिए मैं घर पर ही रहा।"}]},"es":{"word":"lluvia","question":"¿Te gusta la lluvia? ¿Qué haces en los días de lluvia?","examples":[{"en":"I like sitting near the window when it rains.","native":"Me gusta sentarme junto a la ventana cuando llueve."},{"en":"On rainy days I drink hot tea at home.","native":"En los días de lluvia tomo té caliente en casa."},{"en":"Yesterday it rained, so I stayed at home.","native":"Ayer llovió, así que me quedé en casa."}]},"zh":{"word":"雨","question":"你喜欢下雨吗？下雨天你做什么？","examples":[{"en":"I like sitting near the window when it rains.","native":"下雨时我喜欢坐在窗边。"},{"en":"On rainy days I drink hot tea at home.","native":"下雨天我在家喝热茶。"},{"en":"Yesterday it rained, so I stayed at home.","native":"昨天下了雨，所以我待在家里。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'snow', 'Have you ever seen snow? Talk about it.', '{"te":{"word":"మంచు","question":"మీరు ఎప్పుడైనా మంచు చూశారా? దాని గురించి మాట్లాడండి.","examples":[{"en":"I saw snow for the first time last winter.","native":"గత శీతాకాలంలో నేను మొదటిసారి మంచు చూశాను."},{"en":"The children made a small snowman in the garden.","native":"పిల్లలు తోటలో ఒక చిన్న మంచు మనిషిని చేశారు."},{"en":"It was very cold, but we were happy.","native":"చాలా చల్లగా ఉంది, కానీ మేము సంతోషంగా ఉన్నాము."}]},"hi":{"word":"बर्फ़","question":"क्या आपने कभी बर्फ़ देखी है? इसके बारे में बताइए।","examples":[{"en":"I saw snow for the first time last winter.","native":"पिछली सर्दी में मैंने पहली बार बर्फ़ देखी।"},{"en":"The children made a small snowman in the garden.","native":"बच्चों ने बगीचे में एक छोटा स्नोमैन बनाया।"},{"en":"It was very cold, but we were happy.","native":"बहुत ठंड थी, लेकिन हम खुश थे।"}]},"es":{"word":"nieve","question":"¿Has visto la nieve alguna vez? Háblame de ello.","examples":[{"en":"I saw snow for the first time last winter.","native":"Vi nieve por primera vez el invierno pasado."},{"en":"The children made a small snowman in the garden.","native":"Los niños hicieron un pequeño muñeco de nieve en el jardín."},{"en":"It was very cold, but we were happy.","native":"Hacía mucho frío, pero estábamos felices."}]},"zh":{"word":"雪","question":"你见过雪吗？谈谈你的经历。","examples":[{"en":"I saw snow for the first time last winter.","native":"去年冬天我第一次见到了雪。"},{"en":"The children made a small snowman in the garden.","native":"孩子们在花园里堆了一个小雪人。"},{"en":"It was very cold, but we were happy.","native":"天气很冷，但我们很开心。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'summer', 'What do you do in summer? Do you like hot weather?', '{"te":{"word":"వేసవి","question":"వేసవిలో మీరు ఏమి చేస్తారు? మీకు వేడి వాతావరణం ఇష్టమా?","examples":[{"en":"In summer I eat mangoes and drink cold juice.","native":"వేసవిలో నేను మామిడి పండ్లు తింటాను, చల్లటి జ్యూస్ తాగుతాను."},{"en":"We often visit our grandparents in the village.","native":"మేము తరచుగా ఊరిలో మా తాతయ్య, అమ్మమ్మను కలుస్తాము."},{"en":"Last summer I learned to swim in the river.","native":"గత వేసవిలో నేను నదిలో ఈత నేర్చుకున్నాను."}]},"hi":{"word":"गर्मी","question":"गर्मियों में आप क्या करते हैं? क्या आपको गर्म मौसम पसंद है?","examples":[{"en":"In summer I eat mangoes and drink cold juice.","native":"गर्मियों में मैं आम खाता हूँ और ठंडा जूस पीता हूँ।"},{"en":"We often visit our grandparents in the village.","native":"हम अक्सर गाँव में अपने दादा-दादी से मिलने जाते हैं।"},{"en":"Last summer I learned to swim in the river.","native":"पिछली गर्मी में मैंने नदी में तैरना सीखा।"}]},"es":{"word":"verano","question":"¿Qué haces en verano? ¿Te gusta el calor?","examples":[{"en":"In summer I eat mangoes and drink cold juice.","native":"En verano como mangos y bebo jugo frío."},{"en":"We often visit our grandparents in the village.","native":"A menudo visitamos a nuestros abuelos en el pueblo."},{"en":"Last summer I learned to swim in the river.","native":"El verano pasado aprendí a nadar en el río."}]},"zh":{"word":"夏天","question":"夏天你做什么？你喜欢炎热的天气吗？","examples":[{"en":"In summer I eat mangoes and drink cold juice.","native":"夏天我吃芒果，喝冰镇果汁。"},{"en":"We often visit our grandparents in the village.","native":"我们经常去村里看望爷爷奶奶。"},{"en":"Last summer I learned to swim in the river.","native":"去年夏天我在河里学会了游泳。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'winter', 'What is winter like in your town? What do you wear?', '{"te":{"word":"శీతాకాలం","question":"మీ పట్టణంలో శీతాకాలం ఎలా ఉంటుంది? మీరు ఏమి ధరిస్తారు?","examples":[{"en":"Winter in my town is cold and foggy.","native":"మా పట్టణంలో శీతాకాలం చల్లగా, పొగమంచుతో ఉంటుంది."},{"en":"I wear a warm coat and a woollen hat.","native":"నేను వెచ్చని కోటు, ఉన్ని టోపీ ధరిస్తాను."},{"en":"Last winter we sat near the fire every evening.","native":"గత శీతాకాలంలో మేము ప్రతి సాయంత్రం మంట దగ్గర కూర్చునేవాళ్ళం."}]},"hi":{"word":"सर्दी","question":"आपके शहर में सर्दी कैसी होती है? आप क्या पहनते हैं?","examples":[{"en":"Winter in my town is cold and foggy.","native":"मेरे शहर में सर्दी ठंडी और कोहरे वाली होती है।"},{"en":"I wear a warm coat and a woollen hat.","native":"मैं गर्म कोट और ऊनी टोपी पहनता हूँ।"},{"en":"Last winter we sat near the fire every evening.","native":"पिछली सर्दी में हम हर शाम आग के पास बैठते थे।"}]},"es":{"word":"invierno","question":"¿Cómo es el invierno en tu ciudad? ¿Qué ropa llevas?","examples":[{"en":"Winter in my town is cold and foggy.","native":"El invierno en mi ciudad es frío y con niebla."},{"en":"I wear a warm coat and a woollen hat.","native":"Llevo un abrigo caliente y un gorro de lana."},{"en":"Last winter we sat near the fire every evening.","native":"El invierno pasado nos sentábamos junto al fuego todas las tardes."}]},"zh":{"word":"冬天","question":"你所在城市的冬天是什么样的？你穿什么？","examples":[{"en":"Winter in my town is cold and foggy.","native":"我城市的冬天又冷又多雾。"},{"en":"I wear a warm coat and a woollen hat.","native":"我穿暖和的大衣，戴毛线帽。"},{"en":"Last winter we sat near the fire every evening.","native":"去年冬天我们每天傍晚都围坐在火炉旁。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'morning', 'What do you usually do in the morning?', '{"te":{"word":"ఉదయం","question":"మీరు సాధారణంగా ఉదయం ఏమి చేస్తారు?","examples":[{"en":"I wake up at six and drink warm water.","native":"నేను ఆరు గంటలకు మేల్కొని గోరువెచ్చని నీరు తాగుతాను."},{"en":"Then I take a walk near my house.","native":"తర్వాత నేను మా ఇంటి దగ్గర నడుస్తాను."},{"en":"This morning I ate bread and drank tea.","native":"ఈ ఉదయం నేను బ్రెడ్ తిన్నాను, టీ తాగాను."}]},"hi":{"word":"सुबह","question":"आप सुबह आमतौर पर क्या करते हैं?","examples":[{"en":"I wake up at six and drink warm water.","native":"मैं छह बजे उठता हूँ और गुनगुना पानी पीता हूँ।"},{"en":"Then I take a walk near my house.","native":"फिर मैं अपने घर के पास घूमने जाता हूँ।"},{"en":"This morning I ate bread and drank tea.","native":"आज सुबह मैंने ब्रेड खाई और चाय पी।"}]},"es":{"word":"mañana","question":"¿Qué sueles hacer por la mañana?","examples":[{"en":"I wake up at six and drink warm water.","native":"Me despierto a las seis y bebo agua tibia."},{"en":"Then I take a walk near my house.","native":"Luego paseo cerca de mi casa."},{"en":"This morning I ate bread and drank tea.","native":"Esta mañana comí pan y bebí té."}]},"zh":{"word":"早晨","question":"你早上通常做什么？","examples":[{"en":"I wake up at six and drink warm water.","native":"我六点起床，喝一杯温水。"},{"en":"Then I take a walk near my house.","native":"然后我在家附近散步。"},{"en":"This morning I ate bread and drank tea.","native":"今天早上我吃了面包，喝了茶。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'evening', 'What do you usually do in the evening?', '{"te":{"word":"సాయంత్రం","question":"మీరు సాధారణంగా సాయంత్రం ఏమి చేస్తారు?","examples":[{"en":"In the evening I finish my work and rest.","native":"సాయంత్రం నేను నా పనిని ముగించి విశ్రాంతి తీసుకుంటాను."},{"en":"I watch television with my family after dinner.","native":"రాత్రి భోజనం తర్వాత నా కుటుంబంతో టెలివిజన్ చూస్తాను."},{"en":"Yesterday evening I met my old friend in town.","native":"నిన్న సాయంత్రం నేను పట్టణంలో నా పాత స్నేహితుడిని కలిశాను."}]},"hi":{"word":"शाम","question":"आप शाम को आमतौर पर क्या करते हैं?","examples":[{"en":"In the evening I finish my work and rest.","native":"शाम को मैं अपना काम ख़त्म करके आराम करता हूँ।"},{"en":"I watch television with my family after dinner.","native":"रात के खाने के बाद मैं अपने परिवार के साथ टेलीविज़न देखता हूँ।"},{"en":"Yesterday evening I met my old friend in town.","native":"कल शाम मैं शहर में अपने पुराने दोस्त से मिला।"}]},"es":{"word":"tarde","question":"¿Qué sueles hacer por la tarde?","examples":[{"en":"In the evening I finish my work and rest.","native":"Por la tarde termino mi trabajo y descanso."},{"en":"I watch television with my family after dinner.","native":"Veo la televisión con mi familia después de cenar."},{"en":"Yesterday evening I met my old friend in town.","native":"Ayer por la tarde me encontré con mi viejo amigo en la ciudad."}]},"zh":{"word":"傍晚","question":"你傍晚通常做什么？","examples":[{"en":"In the evening I finish my work and rest.","native":"傍晚我完成工作，然后休息。"},{"en":"I watch television with my family after dinner.","native":"晚饭后我和家人一起看电视。"},{"en":"Yesterday evening I met my old friend in town.","native":"昨天傍晚我在城里见到了一位老朋友。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'sleep', 'How many hours do you sleep? Do you sleep well?', '{"te":{"word":"నిద్ర","question":"మీరు ఎన్ని గంటలు నిద్రపోతారు? మీకు నిద్ర బాగా పడుతుందా?","examples":[{"en":"I usually sleep for eight hours every night.","native":"నేను సాధారణంగా ప్రతి రాత్రి ఎనిమిది గంటలు నిద్రపోతాను."},{"en":"I go to bed at ten and wake at six.","native":"నేను పది గంటలకు పడుకుంటాను, ఆరు గంటలకు మేల్కొంటాను."},{"en":"Last night I slept badly because it was hot.","native":"నిన్న రాత్రి వేడిగా ఉండడంతో నాకు నిద్ర బాగా పట్టలేదు."}]},"hi":{"word":"नींद","question":"आप कितने घंटे सोते हैं? क्या आपकी नींद अच्छी आती है?","examples":[{"en":"I usually sleep for eight hours every night.","native":"मैं आमतौर पर हर रात आठ घंटे सोता हूँ।"},{"en":"I go to bed at ten and wake at six.","native":"मैं दस बजे सोता हूँ और छह बजे उठता हूँ।"},{"en":"Last night I slept badly because it was hot.","native":"कल रात गर्मी के कारण मेरी नींद ख़राब रही।"}]},"es":{"word":"sueño","question":"¿Cuántas horas duermes? ¿Duermes bien?","examples":[{"en":"I usually sleep for eight hours every night.","native":"Normalmente duermo ocho horas cada noche."},{"en":"I go to bed at ten and wake at six.","native":"Me acuesto a las diez y me despierto a las seis."},{"en":"Last night I slept badly because it was hot.","native":"Anoche dormí mal porque hacía calor."}]},"zh":{"word":"睡眠","question":"你睡几个小时？你睡得好吗？","examples":[{"en":"I usually sleep for eight hours every night.","native":"我通常每晚睡八个小时。"},{"en":"I go to bed at ten and wake at six.","native":"我十点睡觉，六点起床。"},{"en":"Last night I slept badly because it was hot.","native":"昨晚因为天热，我没睡好。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'clothes', 'What clothes do you like to wear? Talk about your favourite clothes.', '{"te":{"word":"బట్టలు","question":"మీరు ఏ బట్టలు ధరించడం ఇష్టపడతారు? మీ ఇష్టమైన బట్టల గురించి మాట్లాడండి.","examples":[{"en":"I like wearing simple cotton clothes in summer.","native":"వేసవిలో సరళమైన పత్తి బట్టలు ధరించడం నాకు ఇష్టం."},{"en":"My favourite shirt is light blue and white.","native":"నా ఇష్టమైన చొక్కా లేత నీలం మరియు తెలుపు రంగులో ఉంటుంది."},{"en":"Last week I bought a new jacket for winter.","native":"గత వారం నేను శీతాకాలం కోసం ఒక కొత్త జాకెట్ కొన్నాను."}]},"hi":{"word":"कपड़े","question":"आप कैसे कपड़े पहनना पसंद करते हैं? अपने पसंदीदा कपड़ों के बारे में बताइए।","examples":[{"en":"I like wearing simple cotton clothes in summer.","native":"मुझे गर्मियों में सादे सूती कपड़े पहनना पसंद है।"},{"en":"My favourite shirt is light blue and white.","native":"मेरी पसंदीदा कमीज़ हल्के नीले और सफ़ेद रंग की है।"},{"en":"Last week I bought a new jacket for winter.","native":"पिछले हफ़्ते मैंने सर्दियों के लिए एक नई जैकेट खरीदी।"}]},"es":{"word":"ropa","question":"¿Qué ropa te gusta llevar? Habla de tu ropa favorita.","examples":[{"en":"I like wearing simple cotton clothes in summer.","native":"Me gusta llevar ropa sencilla de algodón en verano."},{"en":"My favourite shirt is light blue and white.","native":"Mi camisa favorita es azul claro y blanca."},{"en":"Last week I bought a new jacket for winter.","native":"La semana pasada compré una chaqueta nueva para el invierno."}]},"zh":{"word":"衣服","question":"你喜欢穿什么样的衣服？谈谈你最喜欢的衣服。","examples":[{"en":"I like wearing simple cotton clothes in summer.","native":"夏天我喜欢穿简单的棉质衣服。"},{"en":"My favourite shirt is light blue and white.","native":"我最喜欢的衬衫是浅蓝色和白色的。"},{"en":"Last week I bought a new jacket for winter.","native":"上周我为冬天买了一件新夹克。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'shoes', 'How many pairs of shoes do you have? Talk about them.', '{"te":{"word":"బూట్లు","question":"మీకు ఎన్ని జతల బూట్లు ఉన్నాయి? వాటి గురించి మాట్లాడండి.","examples":[{"en":"I have three pairs of shoes at home.","native":"మా ఇంట్లో నాకు మూడు జతల బూట్లు ఉన్నాయి."},{"en":"My black shoes are for work, and my sandals for home.","native":"నా నల్ల బూట్లు పనికి, నా చెప్పులు ఇంటికి."},{"en":"Yesterday I bought new sports shoes in the market.","native":"నిన్న నేను మార్కెట్లో కొత్త స్పోర్ట్స్ షూస్ కొన్నాను."}]},"hi":{"word":"जूते","question":"आपके पास कितनी जोड़ी जूते हैं? उनके बारे में बताइए।","examples":[{"en":"I have three pairs of shoes at home.","native":"मेरे घर पर तीन जोड़ी जूते हैं।"},{"en":"My black shoes are for work, and my sandals for home.","native":"मेरे काले जूते काम के लिए हैं, और मेरी चप्पलें घर के लिए।"},{"en":"Yesterday I bought new sports shoes in the market.","native":"कल मैंने बाज़ार से नए स्पोर्ट्स जूते खरीदे।"}]},"es":{"word":"zapatos","question":"¿Cuántos pares de zapatos tienes? Habla de ellos.","examples":[{"en":"I have three pairs of shoes at home.","native":"Tengo tres pares de zapatos en casa."},{"en":"My black shoes are for work, and my sandals for home.","native":"Mis zapatos negros son para el trabajo, y mis sandalias para casa."},{"en":"Yesterday I bought new sports shoes in the market.","native":"Ayer compré zapatillas de deporte nuevas en el mercado."}]},"zh":{"word":"鞋子","question":"你有几双鞋？谈谈你的鞋子。","examples":[{"en":"I have three pairs of shoes at home.","native":"我家里有三双鞋。"},{"en":"My black shoes are for work, and my sandals for home.","native":"我的黑皮鞋是上班穿的，凉鞋是在家穿的。"},{"en":"Yesterday I bought new sports shoes in the market.","native":"昨天我在市场买了新的运动鞋。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'money', 'How do you save money? What do you like to buy?', '{"te":{"word":"డబ్బు","question":"మీరు డబ్బును ఎలా ఆదా చేస్తారు? మీరు ఏమి కొనడానికి ఇష్టపడతారు?","examples":[{"en":"I save some money every month in the bank.","native":"నేను ప్రతి నెల కొంత డబ్బు బ్యాంకులో ఆదా చేస్తాను."},{"en":"I like buying books more than new clothes.","native":"కొత్త బట్టల కంటే పుస్తకాలు కొనడం నాకు ఎక్కువ ఇష్టం."},{"en":"Last week I saved money by cooking at home.","native":"గత వారం నేను ఇంట్లో వంట చేసుకొని డబ్బు ఆదా చేశాను."}]},"hi":{"word":"पैसा","question":"आप पैसे कैसे बचाते हैं? आप क्या खरीदना पसंद करते हैं?","examples":[{"en":"I save some money every month in the bank.","native":"मैं हर महीने कुछ पैसे बैंक में बचाता हूँ।"},{"en":"I like buying books more than new clothes.","native":"मुझे नए कपड़ों से ज़्यादा किताबें खरीदना पसंद है।"},{"en":"Last week I saved money by cooking at home.","native":"पिछले हफ़्ते मैंने घर पर खाना बनाकर पैसे बचाए।"}]},"es":{"word":"dinero","question":"¿Cómo ahorras dinero? ¿Qué te gusta comprar?","examples":[{"en":"I save some money every month in the bank.","native":"Ahorro algo de dinero cada mes en el banco."},{"en":"I like buying books more than new clothes.","native":"Me gusta comprar libros más que ropa nueva."},{"en":"Last week I saved money by cooking at home.","native":"La semana pasada ahorré dinero cocinando en casa."}]},"zh":{"word":"钱","question":"你怎么存钱？你喜欢买什么？","examples":[{"en":"I save some money every month in the bank.","native":"我每个月在银行存一些钱。"},{"en":"I like buying books more than new clothes.","native":"比起买新衣服，我更喜欢买书。"},{"en":"Last week I saved money by cooking at home.","native":"上周我在家做饭省下了钱。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'bank', 'Do you go to the bank often? What do you do there?', '{"te":{"word":"బ్యాంకు","question":"మీరు తరచుగా బ్యాంకుకు వెళ్తారా? మీరు అక్కడ ఏమి చేస్తారు?","examples":[{"en":"I go to the bank once every month.","native":"నేను నెలకు ఒకసారి బ్యాంకుకు వెళ్తాను."},{"en":"The bank near my house opens at nine.","native":"మా ఇంటి దగ్గర ఉన్న బ్యాంకు తొమ్మిది గంటలకు తెరుస్తుంది."},{"en":"Yesterday I put money into my new account.","native":"నిన్న నేను నా కొత్త ఖాతాలో డబ్బు జమ చేశాను."}]},"hi":{"word":"बैंक","question":"क्या आप अक्सर बैंक जाते हैं? आप वहाँ क्या करते हैं?","examples":[{"en":"I go to the bank once every month.","native":"मैं महीने में एक बार बैंक जाता हूँ।"},{"en":"The bank near my house opens at nine.","native":"मेरे घर के पास का बैंक नौ बजे खुलता है।"},{"en":"Yesterday I put money into my new account.","native":"कल मैंने अपने नए खाते में पैसे डाले।"}]},"es":{"word":"banco","question":"¿Vas al banco a menudo? ¿Qué haces allí?","examples":[{"en":"I go to the bank once every month.","native":"Voy al banco una vez al mes."},{"en":"The bank near my house opens at nine.","native":"El banco cerca de mi casa abre a las nueve."},{"en":"Yesterday I put money into my new account.","native":"Ayer puse dinero en mi nueva cuenta."}]},"zh":{"word":"银行","question":"你经常去银行吗？你在那里做什么？","examples":[{"en":"I go to the bank once every month.","native":"我每个月去一次银行。"},{"en":"The bank near my house opens at nine.","native":"我家附近的银行九点开门。"},{"en":"Yesterday I put money into my new account.","native":"昨天我把钱存进了我的新账户。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'market', 'Do you shop at the market? What do you buy there?', '{"te":{"word":"మార్కెట్","question":"మీరు మార్కెట్లో కొనుగోలు చేస్తారా? మీరు అక్కడ ఏమి కొంటారు?","examples":[{"en":"I buy fresh vegetables at the market every Sunday.","native":"నేను ప్రతి ఆదివారం మార్కెట్లో తాజా కూరగాయలు కొంటాను."},{"en":"The market is busy, but the prices are good.","native":"మార్కెట్ రద్దీగా ఉంటుంది, కానీ ధరలు బాగుంటాయి."},{"en":"Yesterday I bought sweet mangoes at the market.","native":"నిన్న నేను మార్కెట్లో తీపి మామిడి పండ్లు కొన్నాను."}]},"hi":{"word":"बाज़ार","question":"क्या आप बाज़ार से खरीदारी करते हैं? आप वहाँ क्या खरीदते हैं?","examples":[{"en":"I buy fresh vegetables at the market every Sunday.","native":"मैं हर रविवार बाज़ार से ताज़ी सब्ज़ियाँ खरीदता हूँ।"},{"en":"The market is busy, but the prices are good.","native":"बाज़ार भीड़भाड़ वाला होता है, लेकिन दाम अच्छे होते हैं।"},{"en":"Yesterday I bought sweet mangoes at the market.","native":"कल मैंने बाज़ार से मीठे आम खरीदे।"}]},"es":{"word":"mercado","question":"¿Compras en el mercado? ¿Qué compras allí?","examples":[{"en":"I buy fresh vegetables at the market every Sunday.","native":"Compro verduras frescas en el mercado cada domingo."},{"en":"The market is busy, but the prices are good.","native":"El mercado está lleno, pero los precios son buenos."},{"en":"Yesterday I bought sweet mangoes at the market.","native":"Ayer compré mangos dulces en el mercado."}]},"zh":{"word":"市场","question":"你在市场买东西吗？你在那里买什么？","examples":[{"en":"I buy fresh vegetables at the market every Sunday.","native":"我每个星期天在市场买新鲜蔬菜。"},{"en":"The market is busy, but the prices are good.","native":"市场很拥挤，但价格很好。"},{"en":"Yesterday I bought sweet mangoes at the market.","native":"昨天我在市场买了甜芒果。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'supermarket', 'Do you like supermarkets? What do you usually buy there?', '{"te":{"word":"సూపర్ మార్కెట్","question":"మీకు సూపర్ మార్కెట్లు ఇష్టమా? మీరు సాధారణంగా అక్కడ ఏమి కొంటారు?","examples":[{"en":"I go to the supermarket twice a week.","native":"నేను వారానికి రెండుసార్లు సూపర్ మార్కెట్‌కు వెళ్తాను."},{"en":"I usually buy milk, bread, and eggs there.","native":"నేను సాధారణంగా అక్కడ పాలు, బ్రెడ్, గుడ్లు కొంటాను."},{"en":"The supermarket was very crowded last Saturday evening.","native":"గత శనివారం సాయంత్రం సూపర్ మార్కెట్ చాలా రద్దీగా ఉంది."}]},"hi":{"word":"सुपरमार्केट","question":"क्या आपको सुपरमार्केट पसंद हैं? आप वहाँ आमतौर पर क्या खरीदते हैं?","examples":[{"en":"I go to the supermarket twice a week.","native":"मैं हफ़्ते में दो बार सुपरमार्केट जाता हूँ।"},{"en":"I usually buy milk, bread, and eggs there.","native":"मैं वहाँ आमतौर पर दूध, ब्रेड और अंडे खरीदता हूँ।"},{"en":"The supermarket was very crowded last Saturday evening.","native":"पिछले शनिवार शाम को सुपरमार्केट बहुत भीड़भाड़ वाला था।"}]},"es":{"word":"supermercado","question":"¿Te gustan los supermercados? ¿Qué sueles comprar allí?","examples":[{"en":"I go to the supermarket twice a week.","native":"Voy al supermercado dos veces por semana."},{"en":"I usually buy milk, bread, and eggs there.","native":"Normalmente compro leche, pan y huevos allí."},{"en":"The supermarket was very crowded last Saturday evening.","native":"El supermercado estaba muy lleno el sábado pasado por la tarde."}]},"zh":{"word":"超市","question":"你喜欢超市吗？你通常在那里买什么？","examples":[{"en":"I go to the supermarket twice a week.","native":"我每周去两次超市。"},{"en":"I usually buy milk, bread, and eggs there.","native":"我通常在那里买牛奶、面包和鸡蛋。"},{"en":"The supermarket was very crowded last Saturday evening.","native":"上周六傍晚超市里人很多。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'gift', 'Talk about a gift you gave or received.', '{"te":{"word":"బహుమతి","question":"మీరు ఇచ్చిన లేదా అందుకున్న ఒక బహుమతి గురించి మాట్లాడండి.","examples":[{"en":"My best gift was a bicycle from my father.","native":"నా అత్యుత్తమ బహుమతి నా నాన్న ఇచ్చిన సైకిల్."},{"en":"I gave my mother a scarf on her birthday.","native":"నేను నా అమ్మ పుట్టినరోజున ఆమెకు ఒక స్కార్ఫ్ ఇచ్చాను."},{"en":"Next week I am going to buy a gift for my friend.","native":"వచ్చే వారం నేను నా స్నేహితుడి కోసం ఒక బహుమతి కొనబోతున్నాను."}]},"hi":{"word":"तोहफ़ा","question":"किसी ऐसे तोहफ़े के बारे में बताइए जो आपने दिया या पाया।","examples":[{"en":"My best gift was a bicycle from my father.","native":"मेरा सबसे अच्छा तोहफ़ा मेरे पिता की ओर से एक साइकिल थी।"},{"en":"I gave my mother a scarf on her birthday.","native":"मैंने अपनी माँ के जन्मदिन पर उन्हें एक स्कार्फ़ दिया।"},{"en":"Next week I am going to buy a gift for my friend.","native":"मैं अगले हफ़्ते अपने दोस्त के लिए एक तोहफ़ा खरीदने वाला हूँ।"}]},"es":{"word":"regalo","question":"Habla de un regalo que diste o recibiste.","examples":[{"en":"My best gift was a bicycle from my father.","native":"Mi mejor regalo fue una bicicleta de mi padre."},{"en":"I gave my mother a scarf on her birthday.","native":"Le regalé una bufanda a mi madre en su cumpleaños."},{"en":"Next week I am going to buy a gift for my friend.","native":"La semana que viene voy a comprar un regalo para mi amigo."}]},"zh":{"word":"礼物","question":"谈谈你送出或收到的一份礼物。","examples":[{"en":"My best gift was a bicycle from my father.","native":"我最好的礼物是爸爸送我的一辆自行车。"},{"en":"I gave my mother a scarf on her birthday.","native":"妈妈生日那天我送了她一条围巾。"},{"en":"Next week I am going to buy a gift for my friend.","native":"下周我打算给朋友买一份礼物。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'party', 'Do you like parties? Talk about a party you enjoyed.', '{"te":{"word":"పార్టీ","question":"మీకు పార్టీలు ఇష్టమా? మీరు ఆస్వాదించిన ఒక పార్టీ గురించి మాట్లాడండి.","examples":[{"en":"I like small parties with my close friends.","native":"నా సన్నిహిత స్నేహితులతో చిన్న పార్టీలు నాకు ఇష్టం."},{"en":"Last month we had a party for my brother''s birthday.","native":"గత నెల నా సోదరుడి పుట్టినరోజు కోసం మేము ఒక పార్టీ చేశాము."},{"en":"We danced, ate cake, and sang many old songs.","native":"మేము డ్యాన్స్ చేశాము, కేకు తిన్నాము, చాలా పాత పాటలు పాడాము."}]},"hi":{"word":"पार्टी","question":"क्या आपको पार्टियाँ पसंद हैं? किसी मज़ेदार पार्टी के बारे में बताइए।","examples":[{"en":"I like small parties with my close friends.","native":"मुझे अपने अच्छे दोस्तों के साथ छोटी पार्टियाँ पसंद हैं।"},{"en":"Last month we had a party for my brother''s birthday.","native":"पिछले महीने हमने मेरे भाई के जन्मदिन की पार्टी की।"},{"en":"We danced, ate cake, and sang many old songs.","native":"हम नाचे, केक खाया और कई पुराने गाने गाए।"}]},"es":{"word":"fiesta","question":"¿Te gustan las fiestas? Habla de una fiesta que disfrutaste.","examples":[{"en":"I like small parties with my close friends.","native":"Me gustan las fiestas pequeñas con mis amigos cercanos."},{"en":"Last month we had a party for my brother''s birthday.","native":"El mes pasado hicimos una fiesta para el cumpleaños de mi hermano."},{"en":"We danced, ate cake, and sang many old songs.","native":"Bailamos, comimos pastel y cantamos muchas canciones viejas."}]},"zh":{"word":"聚会","question":"你喜欢聚会吗？谈谈你玩得很开心的一次聚会。","examples":[{"en":"I like small parties with my close friends.","native":"我喜欢和亲近的朋友一起的小型聚会。"},{"en":"Last month we had a party for my brother''s birthday.","native":"上个月我们为哥哥的生日办了一次聚会。"},{"en":"We danced, ate cake, and sang many old songs.","native":"我们跳了舞，吃了蛋糕，还唱了很多老歌。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'wedding', 'Talk about a wedding you attended.', '{"te":{"word":"పెళ్ళి","question":"మీరు హాజరైన ఒక వివాహం గురించి మాట్లాడండి.","examples":[{"en":"Last year I attended my cousin''s wedding in the city.","native":"గత సంవత్సరం నేను నగరంలో నా కజిన్ వివాహానికి హాజరయ్యాను."},{"en":"The bride wore a very beautiful red dress.","native":"వధువు చాలా అందమైన ఎరుపు రంగు దుస్తులు ధరించింది."},{"en":"We ate nice food and took many photos.","native":"మేము రుచికరమైన భోజనం తిన్నాము, చాలా ఫోటోలు తీశాము."}]},"hi":{"word":"शादी","question":"किसी ऐसी शादी के बारे में बताइए जिसमें आप शामिल हुए।","examples":[{"en":"Last year I attended my cousin''s wedding in the city.","native":"पिछले साल मैं शहर में अपने चचेरे भाई की शादी में शामिल हुआ।"},{"en":"The bride wore a very beautiful red dress.","native":"दुल्हन ने बहुत सुंदर लाल पोशाक पहनी थी।"},{"en":"We ate nice food and took many photos.","native":"हमने अच्छा खाना खाया और बहुत सी तस्वीरें लीं।"}]},"es":{"word":"boda","question":"Habla de una boda a la que asististe.","examples":[{"en":"Last year I attended my cousin''s wedding in the city.","native":"El año pasado asistí a la boda de mi primo en la ciudad."},{"en":"The bride wore a very beautiful red dress.","native":"La novia llevaba un vestido rojo muy bonito."},{"en":"We ate nice food and took many photos.","native":"Comimos comida rica e hicimos muchas fotos."}]},"zh":{"word":"婚礼","question":"谈谈你参加过的一场婚礼。","examples":[{"en":"Last year I attended my cousin''s wedding in the city.","native":"去年我在城里参加了表哥的婚礼。"},{"en":"The bride wore a very beautiful red dress.","native":"新娘穿着一条非常漂亮的红色裙子。"},{"en":"We ate nice food and took many photos.","native":"我们吃了美味的食物，拍了很多照片。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'neighbor', 'Do you know your neighbors? Talk about them.', '{"te":{"word":"పొరుగువారు","question":"మీకు మీ పొరుగువారు తెలుసా? వారి గురించి మాట్లాడండి.","examples":[{"en":"My neighbors are very kind and helpful people.","native":"నా పొరుగువారు చాలా మంచి, సహాయకరమైన వ్యక్తులు."},{"en":"They often give us fruits from their garden.","native":"వారు తరచుగా తమ తోటలోని పండ్లు మాకు ఇస్తారు."},{"en":"Last Sunday we drank tea together at their house.","native":"గత ఆదివారం మేము వారి ఇంట్లో కలిసి టీ తాగాము."}]},"hi":{"word":"पड़ोसी","question":"क्या आप अपने पड़ोसियों को जानते हैं? उनके बारे में बताइए।","examples":[{"en":"My neighbors are very kind and helpful people.","native":"मेरे पड़ोसी बहुत दयालु और मददगार लोग हैं।"},{"en":"They often give us fruits from their garden.","native":"वे अक्सर हमें अपने बगीचे के फल देते हैं।"},{"en":"Last Sunday we drank tea together at their house.","native":"पिछले रविवार हमने उनके घर पर साथ चाय पी।"}]},"es":{"word":"vecino","question":"¿Conoces a tus vecinos? Habla de ellos.","examples":[{"en":"My neighbors are very kind and helpful people.","native":"Mis vecinos son personas muy amables y serviciales."},{"en":"They often give us fruits from their garden.","native":"A menudo nos dan fruta de su jardín."},{"en":"Last Sunday we drank tea together at their house.","native":"El domingo pasado tomamos té juntos en su casa."}]},"zh":{"word":"邻居","question":"你认识你的邻居吗？谈谈他们。","examples":[{"en":"My neighbors are very kind and helpful people.","native":"我的邻居们都是非常友善、乐于助人的人。"},{"en":"They often give us fruits from their garden.","native":"他们经常把花园里的水果送给我们。"},{"en":"Last Sunday we drank tea together at their house.","native":"上个星期天我们在他们家一起喝了茶。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'city', 'Do you live in a city? What do you like about it?', '{"te":{"word":"నగరం","question":"మీరు నగరంలో నివసిస్తున్నారా? దాని గురించి మీకు ఏమి ఇష్టం?","examples":[{"en":"I live in a big city with many people.","native":"నేను చాలా మంది ఉండే ఒక పెద్ద నగరంలో నివసిస్తాను."},{"en":"I like the parks, cinemas, and big markets.","native":"నాకు పార్కులు, సినిమాలు, పెద్ద మార్కెట్లు ఇష్టం."},{"en":"But the traffic is heavy in the morning.","native":"కానీ ఉదయం ట్రాఫిక్ ఎక్కువగా ఉంటుంది."}]},"hi":{"word":"शहर","question":"क्या आप किसी शहर में रहते हैं? आपको उसकी क्या बात पसंद है?","examples":[{"en":"I live in a big city with many people.","native":"मैं बहुत से लोगों वाले एक बड़े शहर में रहता हूँ।"},{"en":"I like the parks, cinemas, and big markets.","native":"मुझे पार्क, सिनेमा और बड़े बाज़ार पसंद हैं।"},{"en":"But the traffic is heavy in the morning.","native":"लेकिन सुबह ट्रैफ़िक बहुत होता है।"}]},"es":{"word":"ciudad","question":"¿Vives en una ciudad? ¿Qué te gusta de ella?","examples":[{"en":"I live in a big city with many people.","native":"Vivo en una ciudad grande con mucha gente."},{"en":"I like the parks, cinemas, and big markets.","native":"Me gustan los parques, los cines y los mercados grandes."},{"en":"But the traffic is heavy in the morning.","native":"Pero el tráfico es pesado por la mañana."}]},"zh":{"word":"城市","question":"你住在城市里吗？你喜欢它什么？","examples":[{"en":"I live in a big city with many people.","native":"我住在一个有很多人的大城市。"},{"en":"I like the parks, cinemas, and big markets.","native":"我喜欢公园、电影院和大市场。"},{"en":"But the traffic is heavy in the morning.","native":"但是早上交通很拥堵。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'village', 'Talk about a village you know or visited.', '{"te":{"word":"గ్రామం","question":"మీకు తెలిసిన లేదా మీరు సందర్శించిన ఒక గ్రామం గురించి మాట్లాడండి.","examples":[{"en":"My grandparents live in a small, quiet village.","native":"నా తాతయ్య, అమ్మమ్మ ఒక చిన్న, ప్రశాంతమైన గ్రామంలో నివసిస్తారు."},{"en":"The air is fresh and people are friendly there.","native":"అక్కడ గాలి స్వచ్ఛంగా ఉంటుంది, ప్రజలు స్నేహపూర్వకంగా ఉంటారు."},{"en":"Last summer I spent two weeks in that village.","native":"గత వేసవిలో నేను ఆ గ్రామంలో రెండు వారాలు గడిపాను."}]},"hi":{"word":"गाँव","question":"किसी ऐसे गाँव के बारे में बताइए जिसे आप जानते हैं या घूमे हैं।","examples":[{"en":"My grandparents live in a small, quiet village.","native":"मेरे दादा-दादी एक छोटे, शांत गाँव में रहते हैं।"},{"en":"The air is fresh and people are friendly there.","native":"वहाँ हवा ताज़ा है और लोग दोस्ताना हैं।"},{"en":"Last summer I spent two weeks in that village.","native":"पिछली गर्मी में मैंने उस गाँव में दो हफ़्ते बिताए।"}]},"es":{"word":"pueblo","question":"Habla de un pueblo que conoces o visitaste.","examples":[{"en":"My grandparents live in a small, quiet village.","native":"Mis abuelos viven en un pueblo pequeño y tranquilo."},{"en":"The air is fresh and people are friendly there.","native":"El aire es fresco y la gente es amable allí."},{"en":"Last summer I spent two weeks in that village.","native":"El verano pasado pasé dos semanas en ese pueblo."}]},"zh":{"word":"村庄","question":"谈谈你了解或去过的一个村庄。","examples":[{"en":"My grandparents live in a small, quiet village.","native":"我的爷爷奶奶住在一个安静的小村庄里。"},{"en":"The air is fresh and people are friendly there.","native":"那里空气清新，人们很友好。"},{"en":"Last summer I spent two weeks in that village.","native":"去年夏天我在那个村庄住了两个星期。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'house', 'Describe your house. How many rooms does it have?', '{"te":{"word":"ఇల్లు","question":"మీ ఇంటిని వివరించండి. దానిలో ఎన్ని గదులు ఉన్నాయి?","examples":[{"en":"My house has four rooms and a small garden.","native":"నా ఇంట్లో నాలుగు గదులు, ఒక చిన్న తోట ఉన్నాయి."},{"en":"The kitchen is big and full of light.","native":"వంటగది పెద్దగా, వెలుతురుతో నిండి ఉంటుంది."},{"en":"We painted the whole house white last year.","native":"గత సంవత్సరం మేము మొత్తం ఇంటికి తెలుపు రంగు వేశాము."}]},"hi":{"word":"घर","question":"अपने घर का वर्णन कीजिए। उसमें कितने कमरे हैं?","examples":[{"en":"My house has four rooms and a small garden.","native":"मेरे घर में चार कमरे और एक छोटा बगीचा है।"},{"en":"The kitchen is big and full of light.","native":"रसोई बड़ी और रोशनी से भरी है।"},{"en":"We painted the whole house white last year.","native":"पिछले साल हमने पूरे घर में सफ़ेद रंग करवाया।"}]},"es":{"word":"casa","question":"Describe tu casa. ¿Cuántas habitaciones tiene?","examples":[{"en":"My house has four rooms and a small garden.","native":"Mi casa tiene cuatro habitaciones y un jardín pequeño."},{"en":"The kitchen is big and full of light.","native":"La cocina es grande y está llena de luz."},{"en":"We painted the whole house white last year.","native":"Pintamos toda la casa de blanco el año pasado."}]},"zh":{"word":"房子","question":"描述一下你的房子。它有几个房间？","examples":[{"en":"My house has four rooms and a small garden.","native":"我的房子有四个房间和一个小花园。"},{"en":"The kitchen is big and full of light.","native":"厨房很大，光线充足。"},{"en":"We painted the whole house white last year.","native":"去年我们把整座房子刷成了白色。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'room', 'Describe your room. What things are in it?', '{"te":{"word":"గది","question":"మీ గదిని వివరించండి. దానిలో ఏ వస్తువులు ఉన్నాయి?","examples":[{"en":"My room is small but always very clean.","native":"నా గది చిన్నది కానీ ఎల్లప్పుడూ చాలా శుభ్రంగా ఉంటుంది."},{"en":"There is a bed, a table, and a chair.","native":"అందులో ఒక మంచం, ఒక టేబుల్, ఒక కుర్చీ ఉన్నాయి."},{"en":"I keep my books on a shelf near the window.","native":"నేను నా పుస్తకాలను కిటికీ దగ్గర ఉన్న అరలో ఉంచుతాను."}]},"hi":{"word":"कमरा","question":"अपने कमरे का वर्णन कीजिए। उसमें क्या-क्या चीज़ें हैं?","examples":[{"en":"My room is small but always very clean.","native":"मेरा कमरा छोटा है लेकिन हमेशा बहुत साफ़ रहता है।"},{"en":"There is a bed, a table, and a chair.","native":"उसमें एक बिस्तर, एक मेज़ और एक कुर्सी है।"},{"en":"I keep my books on a shelf near the window.","native":"मैं अपनी किताबें खिड़की के पास की अलमारी में रखता हूँ।"}]},"es":{"word":"habitación","question":"Describe tu habitación. ¿Qué cosas hay en ella?","examples":[{"en":"My room is small but always very clean.","native":"Mi habitación es pequeña pero siempre está muy limpia."},{"en":"There is a bed, a table, and a chair.","native":"Hay una cama, una mesa y una silla."},{"en":"I keep my books on a shelf near the window.","native":"Guardo mis libros en un estante cerca de la ventana."}]},"zh":{"word":"房间","question":"描述一下你的房间。里面有什么东西？","examples":[{"en":"My room is small but always very clean.","native":"我的房间很小，但总是非常干净。"},{"en":"There is a bed, a table, and a chair.","native":"里面有一张床、一张桌子和一把椅子。"},{"en":"I keep my books on a shelf near the window.","native":"我把书放在窗边的一个架子上。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'kitchen', 'Do you like your kitchen? What do you cook there?', '{"te":{"word":"వంటగది","question":"మీకు మీ వంటగది ఇష్టమా? మీరు అక్కడ ఏమి వంట చేస్తారు?","examples":[{"en":"Our kitchen is small but very clean and useful.","native":"మా వంటగది చిన్నది కానీ చాలా శుభ్రంగా, ఉపయోగకరంగా ఉంటుంది."},{"en":"I cook rice and vegetables there every day.","native":"నేను ప్రతిరోజూ అక్కడ అన్నం, కూరగాయలు వంట చేస్తాను."},{"en":"My mother always keeps the kitchen very tidy.","native":"మా అమ్మ వంటగదిని ఎల్లప్పుడూ చాలా క్రమంగా ఉంచుతుంది."}]},"hi":{"word":"रसोई","question":"क्या आपको अपनी रसोई पसंद है? आप वहाँ क्या बनाते हैं?","examples":[{"en":"Our kitchen is small but very clean and useful.","native":"हमारी रसोई छोटी है लेकिन बहुत साफ़ और उपयोगी है।"},{"en":"I cook rice and vegetables there every day.","native":"मैं वहाँ रोज़ चावल और सब्ज़ियाँ बनाता हूँ।"},{"en":"My mother always keeps the kitchen very tidy.","native":"मेरी माँ रसोई को हमेशा बहुत साफ़-सुथरा रखती है।"}]},"es":{"word":"cocina","question":"¿Te gusta tu cocina? ¿Qué cocinas allí?","examples":[{"en":"Our kitchen is small but very clean and useful.","native":"Nuestra cocina es pequeña pero muy limpia y útil."},{"en":"I cook rice and vegetables there every day.","native":"Cocino arroz y verduras allí todos los días."},{"en":"My mother always keeps the kitchen very tidy.","native":"Mi madre siempre mantiene la cocina muy ordenada."}]},"zh":{"word":"厨房","question":"你喜欢你的厨房吗？你在那里做什么菜？","examples":[{"en":"Our kitchen is small but very clean and useful.","native":"我们的厨房很小，但非常干净实用。"},{"en":"I cook rice and vegetables there every day.","native":"我每天在那里做米饭和蔬菜。"},{"en":"My mother always keeps the kitchen very tidy.","native":"我妈妈总是把厨房收拾得很整洁。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'doctor', 'When did you last visit a doctor? Talk about it.', '{"te":{"word":"డాక్టర్","question":"మీరు చివరిగా ఎప్పుడు డాక్టర్‌ను సంప్రదించారు? దాని గురించి మాట్లాడండి.","examples":[{"en":"I visited the doctor last month for a fever.","native":"గత నెల నేను జ్వరం కోసం డాక్టర్‌ను సంప్రదించాను."},{"en":"The doctor was kind and gave me some medicine.","native":"డాక్టర్ మంచివారు, నాకు కొంత మందు ఇచ్చారు."},{"en":"I felt better after two days of rest.","native":"రెండు రోజుల విశ్రాంతి తర్వాత నేను కోలుకున్నాను."}]},"hi":{"word":"डॉक्टर","question":"आप आख़िरी बार डॉक्टर के पास कब गए? इसके बारे में बताइए।","examples":[{"en":"I visited the doctor last month for a fever.","native":"पिछले महीने मैं बुख़ार के कारण डॉक्टर के पास गया।"},{"en":"The doctor was kind and gave me some medicine.","native":"डॉक्टर दयालु थे और उन्होंने मुझे कुछ दवा दी।"},{"en":"I felt better after two days of rest.","native":"दो दिन के आराम के बाद मैं ठीक महसूस करने लगा।"}]},"es":{"word":"médico","question":"¿Cuándo fue la última vez que fuiste al médico? Háblame de ello.","examples":[{"en":"I visited the doctor last month for a fever.","native":"Fui al médico el mes pasado por una fiebre."},{"en":"The doctor was kind and gave me some medicine.","native":"El médico fue amable y me dio algunas medicinas."},{"en":"I felt better after two days of rest.","native":"Me sentí mejor después de dos días de descanso."}]},"zh":{"word":"医生","question":"你上一次看医生是什么时候？谈谈那次经历。","examples":[{"en":"I visited the doctor last month for a fever.","native":"上个月我因为发烧去看了医生。"},{"en":"The doctor was kind and gave me some medicine.","native":"医生很和蔼，给我开了一些药。"},{"en":"I felt better after two days of rest.","native":"休息了两天之后我感觉好多了。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'hospital', 'Is there a hospital near your home? Talk about a visit there.', '{"te":{"word":"ఆసుపత్రి","question":"మీ ఇంటి దగ్గర ఆసుపత్రి ఉందా? అక్కడి ఒక సందర్శన గురించి మాట్లాడండి.","examples":[{"en":"There is a big hospital near the bus station.","native":"బస్ స్టేషన్ దగ్గర ఒక పెద్ద ఆసుపత్రి ఉంది."},{"en":"My uncle works in that hospital as a nurse.","native":"నా మామయ్య ఆ ఆసుపత్రిలో నర్సుగా పని చేస్తారు."},{"en":"Last year my grandmother stayed there for a week.","native":"గత సంవత్సరం నా అమ్మమ్మ అక్కడ ఒక వారం ఉంది."}]},"hi":{"word":"अस्पताल","question":"क्या आपके घर के पास कोई अस्पताल है? वहाँ की किसी विज़िट के बारे में बताइए।","examples":[{"en":"There is a big hospital near the bus station.","native":"बस स्टेशन के पास एक बड़ा अस्पताल है।"},{"en":"My uncle works in that hospital as a nurse.","native":"मेरे चाचा उस अस्पताल में नर्स के रूप में काम करते हैं।"},{"en":"Last year my grandmother stayed there for a week.","native":"पिछले साल मेरी दादी एक हफ़्ते वहाँ रहीं।"}]},"es":{"word":"hospital","question":"¿Hay un hospital cerca de tu casa? Habla de una visita allí.","examples":[{"en":"There is a big hospital near the bus station.","native":"Hay un hospital grande cerca de la estación de autobuses."},{"en":"My uncle works in that hospital as a nurse.","native":"Mi tío trabaja en ese hospital como enfermero."},{"en":"Last year my grandmother stayed there for a week.","native":"El año pasado mi abuela estuvo allí una semana."}]},"zh":{"word":"医院","question":"你家附近有医院吗？谈谈去那里的一次经历。","examples":[{"en":"There is a big hospital near the bus station.","native":"公交车站附近有一家大医院。"},{"en":"My uncle works in that hospital as a nurse.","native":"我叔叔在那家医院当护士。"},{"en":"Last year my grandmother stayed there for a week.","native":"去年我奶奶在那里住了一个星期。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'teacher', 'Talk about a teacher you liked at school.', '{"te":{"word":"ఉపాధ్యాయుడు","question":"పాఠశాలలో మీకు ఇష్టమైన ఒక ఉపాధ్యాయుడు గురించి మాట్లాడండి.","examples":[{"en":"My favourite teacher taught us English in school.","native":"నా ఇష్టమైన ఉపాధ్యాయిని పాఠశాలలో మాకు ఇంగ్లీష్ నేర్పించారు."},{"en":"She was very patient and explained everything clearly.","native":"ఆమె చాలా సహనంతో ఉండేవారు, ప్రతిదీ స్పష్టంగా వివరించేవారు."},{"en":"She told us many interesting stories every Friday.","native":"ఆమె ప్రతి శుక్రవారం మాకు చాలా ఆసక్తికరమైన కథలు చెప్పేవారు."}]},"hi":{"word":"शिक्षक","question":"स्कूल में अपने किसी पसंदीदा शिक्षक के बारे में बताइए।","examples":[{"en":"My favourite teacher taught us English in school.","native":"मेरी पसंदीदा शिक्षिका ने स्कूल में हमें अंग्रेज़ी पढ़ाया।"},{"en":"She was very patient and explained everything clearly.","native":"वे बहुत धैर्यवान थीं और हर बात स्पष्ट समझाती थीं।"},{"en":"She told us many interesting stories every Friday.","native":"वे हर शुक्रवार हमें कई रोचक कहानियाँ सुनाती थीं।"}]},"es":{"word":"maestro","question":"Habla de un maestro que te gustaba en la escuela.","examples":[{"en":"My favourite teacher taught us English in school.","native":"Mi maestra favorita nos enseñaba inglés en la escuela."},{"en":"She was very patient and explained everything clearly.","native":"Era muy paciente y explicaba todo con claridad."},{"en":"She told us many interesting stories every Friday.","native":"Nos contaba muchas historias interesantes cada viernes."}]},"zh":{"word":"老师","question":"谈谈你在学校喜欢的一位老师。","examples":[{"en":"My favourite teacher taught us English in school.","native":"我最喜欢的老师在学校教我们英语。"},{"en":"She was very patient and explained everything clearly.","native":"她非常有耐心，把每件事都讲得很清楚。"},{"en":"She told us many interesting stories every Friday.","native":"她每个星期五都给我们讲很多有趣的故事。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'exam', 'How do you prepare for exams? Talk about your last exam.', '{"te":{"word":"పరీక్ష","question":"మీరు పరీక్షలకు ఎలా సిద్ధమవుతారు? మీ చివరి పరీక్ష గురించి మాట్లాడండి.","examples":[{"en":"I study for two hours every evening before exams.","native":"పరీక్షల ముందు నేను ప్రతి సాయంత్రం రెండు గంటలు చదువుతాను."},{"en":"My last exam was difficult, but I passed it.","native":"నా చివరి పరీక్ష కష్టంగా ఉంది, కానీ నేను ఉత్తీర్ణుడనయ్యాను."},{"en":"Next week I am going to take my English exam.","native":"వచ్చే వారం నేను నా ఇంగ్లీష్ పరీక్ష రాయబోతున్నాను."}]},"hi":{"word":"परीक्षा","question":"आप परीक्षाओं की तैयारी कैसे करते हैं? अपनी पिछली परीक्षा के बारे में बताइए।","examples":[{"en":"I study for two hours every evening before exams.","native":"परीक्षाओं से पहले मैं हर शाम दो घंटे पढ़ता हूँ।"},{"en":"My last exam was difficult, but I passed it.","native":"मेरी पिछली परीक्षा कठिन थी, लेकिन मैं उत्तीर्ण हो गया।"},{"en":"Next week I am going to take my English exam.","native":"मैं अगले हफ़्ते अपनी अंग्रेज़ी की परीक्षा देने वाला हूँ।"}]},"es":{"word":"examen","question":"¿Cómo te preparas para los exámenes? Habla de tu último examen.","examples":[{"en":"I study for two hours every evening before exams.","native":"Estudio dos horas cada tarde antes de los exámenes."},{"en":"My last exam was difficult, but I passed it.","native":"Mi último examen fue difícil, pero lo aprobé."},{"en":"Next week I am going to take my English exam.","native":"La semana que viene voy a hacer mi examen de inglés."}]},"zh":{"word":"考试","question":"你怎么准备考试？谈谈你上一次考试。","examples":[{"en":"I study for two hours every evening before exams.","native":"考试前我每天傍晚学习两个小时。"},{"en":"My last exam was difficult, but I passed it.","native":"我上一次考试很难，但我通过了。"},{"en":"Next week I am going to take my English exam.","native":"下周我要参加英语考试。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'homework', 'How much homework do you get? When do you do it?', '{"te":{"word":"ఇంటిపని","question":"మీకు ఎంత ఇంటిపని ఇస్తారు? మీరు దానిని ఎప్పుడు చేస్తారు?","examples":[{"en":"I get some homework from school every day.","native":"నాకు పాఠశాల నుండి ప్రతిరోజూ కొంత ఇంటిపని వస్తుంది."},{"en":"I do my homework after dinner at my table.","native":"నేను రాత్రి భోజనం తర్వాత నా టేబుల్ వద్ద ఇంటిపని చేస్తాను."},{"en":"Yesterday I finished all my homework before eight.","native":"నిన్న నేను ఎనిమిది గంటల లోపు నా ఇంటిపని అంతా పూర్తి చేశాను."}]},"hi":{"word":"होमवर्क","question":"आपको कितना होमवर्क मिलता है? आप उसे कब करते हैं?","examples":[{"en":"I get some homework from school every day.","native":"मुझे स्कूल से रोज़ कुछ होमवर्क मिलता है।"},{"en":"I do my homework after dinner at my table.","native":"मैं रात के खाने के बाद अपनी मेज़ पर होमवर्क करता हूँ।"},{"en":"Yesterday I finished all my homework before eight.","native":"कल मैंने आठ बजे से पहले अपना सारा होमवर्क ख़त्म किया।"}]},"es":{"word":"tarea","question":"¿Cuánta tarea te dan? ¿Cuándo la haces?","examples":[{"en":"I get some homework from school every day.","native":"Me dan algo de tarea del colegio todos los días."},{"en":"I do my homework after dinner at my table.","native":"Hago mi tarea después de cenar en mi mesa."},{"en":"Yesterday I finished all my homework before eight.","native":"Ayer terminé toda mi tarea antes de las ocho."}]},"zh":{"word":"家庭作业","question":"你有多少家庭作业？你什么时候做？","examples":[{"en":"I get some homework from school every day.","native":"学校每天都给我布置一些家庭作业。"},{"en":"I do my homework after dinner at my table.","native":"我晚饭后在自己的书桌上做作业。"},{"en":"Yesterday I finished all my homework before eight.","native":"昨天我在八点之前做完了所有作业。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'language', 'What languages do you speak? Which language do you want to learn?', '{"te":{"word":"భాష","question":"మీరు ఏ భాషలు మాట్లాడతారు? మీరు ఏ భాష నేర్చుకోవాలనుకుంటున్నారు?","examples":[{"en":"I speak two languages at home and outside.","native":"నేను ఇంట్లోను, బయటను రెండు భాషలు మాట్లాడతాను."},{"en":"I want to learn English for my job.","native":"నా ఉద్యోగం కోసం నేను ఇంగ్లీష్ నేర్చుకోవాలనుకుంటున్నాను."},{"en":"My friend is going to teach me French words.","native":"నా స్నేహితుడు నాకు ఫ్రెంచ్ పదాలు నేర్పబోతున్నాడు."}]},"hi":{"word":"भाषा","question":"आप कौन-कौन सी भाषाएँ बोलते हैं? आप कौन सी भाषा सीखना चाहते हैं?","examples":[{"en":"I speak two languages at home and outside.","native":"मैं घर और बाहर दो भाषाएँ बोलता हूँ।"},{"en":"I want to learn English for my job.","native":"मैं अपनी नौकरी के लिए अंग्रेज़ी सीखना चाहता हूँ।"},{"en":"My friend is going to teach me French words.","native":"मेरा दोस्त मुझे फ़्रांसीसी शब्द सिखाने वाला है।"}]},"es":{"word":"idioma","question":"¿Qué idiomas hablas? ¿Qué idioma quieres aprender?","examples":[{"en":"I speak two languages at home and outside.","native":"Hablo dos idiomas en casa y fuera."},{"en":"I want to learn English for my job.","native":"Quiero aprender inglés para mi trabajo."},{"en":"My friend is going to teach me French words.","native":"Mi amigo me va a enseñar palabras en francés."}]},"zh":{"word":"语言","question":"你会说哪些语言？你想学哪种语言？","examples":[{"en":"I speak two languages at home and outside.","native":"我在家里和外面说两种语言。"},{"en":"I want to learn English for my job.","native":"为了工作我想学英语。"},{"en":"My friend is going to teach me French words.","native":"我的朋友要教我法语单词。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'coffee', 'Do you drink coffee? When do you drink it?', '{"te":{"word":"కాఫీ","question":"మీరు కాఫీ తాగుతారా? మీరు దానిని ఎప్పుడు తాగుతారు?","examples":[{"en":"I drink one cup of coffee every morning.","native":"నేను ప్రతి ఉదయం ఒక కప్పు కాఫీ తాగుతాను."},{"en":"I like hot coffee with milk and sugar.","native":"నాకు పాలు, చక్కెర కలిపిన వేడి కాఫీ ఇష్టం."},{"en":"Yesterday I drank coffee with my friend in town.","native":"నిన్న నేను పట్టణంలో నా స్నేహితుడితో కాఫీ తాగాను."}]},"hi":{"word":"कॉफ़ी","question":"क्या आप कॉफ़ी पीते हैं? आप इसे कब पीते हैं?","examples":[{"en":"I drink one cup of coffee every morning.","native":"मैं हर सुबह एक कप कॉफ़ी पीता हूँ।"},{"en":"I like hot coffee with milk and sugar.","native":"मुझे दूध और चीनी वाली गर्म कॉफ़ी पसंद है।"},{"en":"Yesterday I drank coffee with my friend in town.","native":"कल मैंने शहर में अपने दोस्त के साथ कॉफ़ी पी।"}]},"es":{"word":"café","question":"¿Tomas café? ¿Cuándo lo tomas?","examples":[{"en":"I drink one cup of coffee every morning.","native":"Tomo una taza de café cada mañana."},{"en":"I like hot coffee with milk and sugar.","native":"Me gusta el café caliente con leche y azúcar."},{"en":"Yesterday I drank coffee with my friend in town.","native":"Ayer tomé un café con mi amigo en la ciudad."}]},"zh":{"word":"咖啡","question":"你喝咖啡吗？你什么时候喝？","examples":[{"en":"I drink one cup of coffee every morning.","native":"我每天早上喝一杯咖啡。"},{"en":"I like hot coffee with milk and sugar.","native":"我喜欢加牛奶和糖的热咖啡。"},{"en":"Yesterday I drank coffee with my friend in town.","native":"昨天我和朋友在城里喝了咖啡。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'tea', 'Do you like tea? How do you make it?', '{"te":{"word":"టీ","question":"మీకు టీ ఇష్టమా? మీరు దానిని ఎలా తయారు చేస్తారు?","examples":[{"en":"I drink two cups of tea every day.","native":"నేను ప్రతిరోజూ రెండు కప్పుల టీ తాగుతాను."},{"en":"I make tea with milk, sugar, and ginger.","native":"నేను పాలు, చక్కెర, అల్లం కలిపి టీ తయారు చేస్తాను."},{"en":"My grandfather always drinks tea without any sugar.","native":"నా తాతయ్య ఎల్లప్పుడూ చక్కెర లేకుండా టీ తాగుతారు."}]},"hi":{"word":"चाय","question":"क्या आपको चाय पसंद है? आप इसे कैसे बनाते हैं?","examples":[{"en":"I drink two cups of tea every day.","native":"मैं रोज़ दो कप चाय पीता हूँ।"},{"en":"I make tea with milk, sugar, and ginger.","native":"मैं दूध, चीनी और अदरक डालकर चाय बनाता हूँ।"},{"en":"My grandfather always drinks tea without any sugar.","native":"मेरे दादा हमेशा बिना चीनी की चाय पीते हैं।"}]},"es":{"word":"té","question":"¿Te gusta el té? ¿Cómo lo preparas?","examples":[{"en":"I drink two cups of tea every day.","native":"Tomo dos tazas de té todos los días."},{"en":"I make tea with milk, sugar, and ginger.","native":"Preparo el té con leche, azúcar y jengibre."},{"en":"My grandfather always drinks tea without any sugar.","native":"Mi abuelo siempre toma el té sin azúcar."}]},"zh":{"word":"茶","question":"你喜欢喝茶吗？你怎么泡茶？","examples":[{"en":"I drink two cups of tea every day.","native":"我每天喝两杯茶。"},{"en":"I make tea with milk, sugar, and ginger.","native":"我用牛奶、糖和姜来煮茶。"},{"en":"My grandfather always drinks tea without any sugar.","native":"我爷爷总是喝不加糖的茶。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'fruit', 'What fruits do you like? How often do you eat fruit?', '{"te":{"word":"పండు","question":"మీకు ఏ పండ్లు ఇష్టం? మీరు ఎంత తరచుగా పండ్లు తింటారు?","examples":[{"en":"My favourite fruit is the sweet summer mango.","native":"నా ఇష్టమైన పండు తీయటి వేసవి మామిడి పండు."},{"en":"I eat one apple or banana every day.","native":"నేను ప్రతిరోజూ ఒక ఆపిల్ లేదా అరటి పండు తింటాను."},{"en":"Yesterday I bought fresh oranges from the market.","native":"నిన్న నేను మార్కెట్ నుండి తాజా ఆరెంజులు కొన్నాను."}]},"hi":{"word":"फल","question":"आपको कौन से फल पसंद हैं? आप कितनी बार फल खाते हैं?","examples":[{"en":"My favourite fruit is the sweet summer mango.","native":"मेरा पसंदीदा फल मीठा गर्मियों वाला आम है।"},{"en":"I eat one apple or banana every day.","native":"मैं रोज़ एक सेब या केला खाता हूँ।"},{"en":"Yesterday I bought fresh oranges from the market.","native":"कल मैंने बाज़ार से ताज़े संतरे खरीदे।"}]},"es":{"word":"fruta","question":"¿Qué frutas te gustan? ¿Con qué frecuencia comes fruta?","examples":[{"en":"My favourite fruit is the sweet summer mango.","native":"Mi fruta favorita es el dulce mango de verano."},{"en":"I eat one apple or banana every day.","native":"Como una manzana o un plátano todos los días."},{"en":"Yesterday I bought fresh oranges from the market.","native":"Ayer compré naranjas frescas en el mercado."}]},"zh":{"word":"水果","question":"你喜欢什么水果？你多久吃一次水果？","examples":[{"en":"My favourite fruit is the sweet summer mango.","native":"我最喜欢的水果是夏天香甜的芒果。"},{"en":"I eat one apple or banana every day.","native":"我每天吃一个苹果或一根香蕉。"},{"en":"Yesterday I bought fresh oranges from the market.","native":"昨天我在市场买了新鲜的橙子。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'vegetable', 'What vegetables do you eat? Do you like green vegetables?', '{"te":{"word":"కూరగాయ","question":"మీరు ఏ కూరగాయలు తింటారు? మీకు ఆకుకూరలు ఇష్టమా?","examples":[{"en":"I eat fresh vegetables with rice every day.","native":"నేను ప్రతిరోజూ అన్నంతో తాజా కూరగాయలు తింటాను."},{"en":"My favourite vegetables are carrots and green beans.","native":"నా ఇష్టమైన కూరగాయలు క్యారెట్లు, గ్రీన్ బీన్స్."},{"en":"My mother cooks potatoes in many different ways.","native":"మా అమ్మ బంగాళాదుంపలను పలు విధాలుగా వంటుతుంది."}]},"hi":{"word":"सब्ज़ी","question":"आप कौन सी सब्ज़ियाँ खाते हैं? क्या आपको हरी सब्ज़ियाँ पसंद हैं?","examples":[{"en":"I eat fresh vegetables with rice every day.","native":"मैं रोज़ चावल के साथ ताज़ी सब्ज़ियाँ खाता हूँ।"},{"en":"My favourite vegetables are carrots and green beans.","native":"मेरी पसंदीदा सब्ज़ियाँ गाजर और हरी बीन्स हैं।"},{"en":"My mother cooks potatoes in many different ways.","native":"मेरी माँ आलू को कई तरीकों से बनाती है।"}]},"es":{"word":"verdura","question":"¿Qué verduras comes? ¿Te gustan las verduras verdes?","examples":[{"en":"I eat fresh vegetables with rice every day.","native":"Como verduras frescas con arroz todos los días."},{"en":"My favourite vegetables are carrots and green beans.","native":"Mis verduras favoritas son las zanahorias y las judías verdes."},{"en":"My mother cooks potatoes in many different ways.","native":"Mi madre cocina las patatas de muchas formas diferentes."}]},"zh":{"word":"蔬菜","question":"你吃哪些蔬菜？你喜欢绿色蔬菜吗？","examples":[{"en":"I eat fresh vegetables with rice every day.","native":"我每天吃米饭配新鲜蔬菜。"},{"en":"My favourite vegetables are carrots and green beans.","native":"我最喜欢的蔬菜是胡萝卜和青豆。"},{"en":"My mother cooks potatoes in many different ways.","native":"我妈妈会用很多不同的方法做土豆。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'rice', 'Do you eat rice often? What do you eat with it?', '{"te":{"word":"అన్నం","question":"మీరు తరచుగా అన్నం తింటారా? మీరు దానితో ఏమి తింటారు?","examples":[{"en":"I eat rice for lunch and for dinner.","native":"నేను మధ్యాహ్నం, రాత్రి భోజనానికి అన్నం తింటాను."},{"en":"I like rice with dal and vegetable curry.","native":"నాకు పప్పు, కూరగాయల కూరతో అన్నం ఇష్టం."},{"en":"Yesterday my mother made fried rice for us.","native":"నిన్న మా అమ్మ మా కోసం ఫ్రైడ్ రైస్ చేసింది."}]},"hi":{"word":"चावल","question":"क्या आप अक्सर चावल खाते हैं? आप उनके साथ क्या खाते हैं?","examples":[{"en":"I eat rice for lunch and for dinner.","native":"मैं दोपहर और रात के खाने में चावल खाता हूँ।"},{"en":"I like rice with dal and vegetable curry.","native":"मुझे दाल और सब्ज़ी की करी के साथ चावल पसंद हैं।"},{"en":"Yesterday my mother made fried rice for us.","native":"कल मेरी माँ ने हमारे लिए फ्राइड राइस बनाए।"}]},"es":{"word":"arroz","question":"¿Comes arroz a menudo? ¿Con qué lo comes?","examples":[{"en":"I eat rice for lunch and for dinner.","native":"Como arroz en la comida y en la cena."},{"en":"I like rice with dal and vegetable curry.","native":"Me gusta el arroz con dal y curry de verduras."},{"en":"Yesterday my mother made fried rice for us.","native":"Ayer mi madre nos hizo arroz frito."}]},"zh":{"word":"米饭","question":"你经常吃米饭吗？你配什么吃？","examples":[{"en":"I eat rice for lunch and for dinner.","native":"我午餐和晚餐都吃米饭。"},{"en":"I like rice with dal and vegetable curry.","native":"我喜欢米饭配豆汤和蔬菜咖喱。"},{"en":"Yesterday my mother made fried rice for us.","native":"昨天我妈妈给我们做了炒饭。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'bread', 'Do you eat bread? What do you put on it?', '{"te":{"word":"బ్రెడ్","question":"మీరు బ్రెడ్ తింటారా? మీరు దానిపై ఏమి వేసుకుంటారు?","examples":[{"en":"I eat bread with butter every morning for breakfast.","native":"నేను ప్రతి ఉదయం అల్పాహారానికి వెన్నతో బ్రెడ్ తింటాను."},{"en":"My father likes bread with jam and honey.","native":"నా నాన్నకు జామ్, తేనెతో బ్రెడ్ ఇష్టం."},{"en":"Yesterday I bought fresh bread from the bakery.","native":"నిన్న నేను బేకరీ నుండి తాజా బ్రెడ్ కొన్నాను."}]},"hi":{"word":"ब्रेड","question":"क्या आप ब्रेड खाते हैं? आप उस पर क्या लगाते हैं?","examples":[{"en":"I eat bread with butter every morning for breakfast.","native":"मैं हर सुबह नाश्ते में मक्खन के साथ ब्रेड खाता हूँ।"},{"en":"My father likes bread with jam and honey.","native":"मेरे पिता को जाम और शहद के साथ ब्रेड पसंद है।"},{"en":"Yesterday I bought fresh bread from the bakery.","native":"कल मैंने बेकरी से ताज़ी ब्रेड खरीदी।"}]},"es":{"word":"pan","question":"¿Comes pan? ¿Qué le pones?","examples":[{"en":"I eat bread with butter every morning for breakfast.","native":"Como pan con mantequilla cada mañana en el desayuno."},{"en":"My father likes bread with jam and honey.","native":"A mi padre le gusta el pan con mermelada y miel."},{"en":"Yesterday I bought fresh bread from the bakery.","native":"Ayer compré pan fresco en la panadería."}]},"zh":{"word":"面包","question":"你吃面包吗？你在上面涂什么？","examples":[{"en":"I eat bread with butter every morning for breakfast.","native":"我每天早餐吃涂黄油的面包。"},{"en":"My father likes bread with jam and honey.","native":"我爸爸喜欢涂果酱和蜂蜜的面包。"},{"en":"Yesterday I bought fresh bread from the bakery.","native":"昨天我在面包店买了新鲜面包。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'milk', 'Do you drink milk? Do you like milk products?', '{"te":{"word":"పాలు","question":"మీరు పాలు తాగుతారా? మీకు పాల ఉత్పత్తులు ఇష్టమా?","examples":[{"en":"I drink a glass of warm milk before bed.","native":"నేను పడుకునే ముందు ఒక గ్లాసు గోరువెచ్చని పాలు తాగుతాను."},{"en":"My little brother drinks milk with chocolate every morning.","native":"నా తమ్ముడు ప్రతి ఉదయం చాక్లెట్ కలిపిన పాలు తాగుతాడు."},{"en":"We also eat curd and butter at home.","native":"మేము ఇంట్లో పెరుగు, వెన్న కూడా తింటాము."}]},"hi":{"word":"दूध","question":"क्या आप दूध पीते हैं? क्या आपको दूध से बनी चीज़ें पसंद हैं?","examples":[{"en":"I drink a glass of warm milk before bed.","native":"मैं सोने से पहले एक गिलास गुनगुना दूध पीता हूँ।"},{"en":"My little brother drinks milk with chocolate every morning.","native":"मेरा छोटा भाई हर सुबह चॉकलेट वाला दूध पीता है।"},{"en":"We also eat curd and butter at home.","native":"हम घर पर दही और मक्खन भी खाते हैं।"}]},"es":{"word":"leche","question":"¿Bebes leche? ¿Te gustan los productos lácteos?","examples":[{"en":"I drink a glass of warm milk before bed.","native":"Bebo un vaso de leche tibia antes de acostarme."},{"en":"My little brother drinks milk with chocolate every morning.","native":"Mi hermano pequeño bebe leche con chocolate cada mañana."},{"en":"We also eat curd and butter at home.","native":"También comemos yogur y mantequilla en casa."}]},"zh":{"word":"牛奶","question":"你喝牛奶吗？你喜欢奶制品吗？","examples":[{"en":"I drink a glass of warm milk before bed.","native":"我睡前喝一杯温牛奶。"},{"en":"My little brother drinks milk with chocolate every morning.","native":"我弟弟每天早上喝巧克力牛奶。"},{"en":"We also eat curd and butter at home.","native":"我们在家也吃酸奶和黄油。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'picnic', 'Talk about a picnic you had with your family or friends.', '{"te":{"word":"పిక్నిక్","question":"మీరు కుటుంబంతో లేదా స్నేహితులతో చేసిన ఒక పిక్నిక్ గురించి మాట్లాడండి.","examples":[{"en":"Last month we had a picnic near the lake.","native":"గత నెల మేము సరస్సు దగ్గర పిక్నిక్ చేశాము."},{"en":"We took sandwiches, fruits, and cold drinks with us.","native":"మేము శాండ్‌విచ్‌లు, పండ్లు, చల్లటి పానీయాలు తీసుకెళ్ళాము."},{"en":"We played games and sang songs all afternoon.","native":"మేము మధ్యాహ్నాంతం ఆటలు ఆడాము, పాటలు పాడాము."}]},"hi":{"word":"पिकनिक","question":"अपने परिवार या दोस्तों के साथ की गई किसी पिकनिक के बारे में बताइए।","examples":[{"en":"Last month we had a picnic near the lake.","native":"पिछले महीने हमने झील के पास पिकनिक की।"},{"en":"We took sandwiches, fruits, and cold drinks with us.","native":"हम अपने साथ सैंडविच, फल और ठंडे पेय ले गए।"},{"en":"We played games and sang songs all afternoon.","native":"हमने पूरा दोपहर बाद खेल खेले और गाने गाए।"}]},"es":{"word":"picnic","question":"Habla de un picnic que hiciste con tu familia o amigos.","examples":[{"en":"Last month we had a picnic near the lake.","native":"El mes pasado hicimos un picnic cerca del lago."},{"en":"We took sandwiches, fruits, and cold drinks with us.","native":"Llevamos sándwiches, fruta y bebidas frías con nosotros."},{"en":"We played games and sang songs all afternoon.","native":"Jugamos a juegos y cantamos canciones toda la tarde."}]},"zh":{"word":"野餐","question":"谈谈你和家人或朋友的一次野餐。","examples":[{"en":"Last month we had a picnic near the lake.","native":"上个月我们在湖边野餐了。"},{"en":"We took sandwiches, fruits, and cold drinks with us.","native":"我们带了三明治、水果和冷饮。"},{"en":"We played games and sang songs all afternoon.","native":"我们整个下午做游戏、唱歌。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'cinema', 'Do you like going to the cinema? Talk about the last film you saw.', '{"te":{"word":"సినిమా","question":"మీకు సినిమాకు వెళ్లడం ఇష్టమా? మీరు చివరిగా చూసిన సినిమా గురించి మాట్లాడండి.","examples":[{"en":"I go to the cinema once every month.","native":"నేను నెలకు ఒకసారి సినిమాకు వెళ్తాను."},{"en":"Last week I saw a funny film with my friends.","native":"గత వారం నేను నా స్నేహితులతో ఒక హాస్య సినిమా చూశాను."},{"en":"The tickets were cheap and the seats were comfortable.","native":"టికెట్లు చౌకగా ఉన్నాయి, సీట్లు సౌకర్యవంతంగా ఉన్నాయి."}]},"hi":{"word":"सिनेमा","question":"क्या आपको सिनेमा जाना पसंद है? अपनी पिछली देखी फ़िल्म के बारे में बताइए।","examples":[{"en":"I go to the cinema once every month.","native":"मैं महीने में एक बार सिनेमा जाता हूँ।"},{"en":"Last week I saw a funny film with my friends.","native":"पिछले हफ़्ते मैंने अपने दोस्तों के साथ एक मज़ेदार फ़िल्म देखी।"},{"en":"The tickets were cheap and the seats were comfortable.","native":"टिकटें सस्ती थीं और सीटें आरामदायक थीं।"}]},"es":{"word":"cine","question":"¿Te gusta ir al cine? Habla de la última película que viste.","examples":[{"en":"I go to the cinema once every month.","native":"Voy al cine una vez al mes."},{"en":"Last week I saw a funny film with my friends.","native":"La semana pasada vi una película divertida con mis amigos."},{"en":"The tickets were cheap and the seats were comfortable.","native":"Las entradas eran baratas y los asientos eran cómodos."}]},"zh":{"word":"电影院","question":"你喜欢去电影院吗？谈谈你最近看的一部电影。","examples":[{"en":"I go to the cinema once every month.","native":"我每个月去一次电影院。"},{"en":"Last week I saw a funny film with my friends.","native":"上周我和朋友们看了一部有趣的电影。"},{"en":"The tickets were cheap and the seats were comfortable.","native":"票很便宜，座位也很舒服。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'museum', 'Have you visited a museum? What did you see there?', '{"te":{"word":"మ్యూజియం","question":"మీరు మ్యూజియం సందర్శించారా? మీరు అక్కడ ఏమి చూశారు?","examples":[{"en":"I visited the city museum with my class.","native":"నేను నా క్లాస్‌తో నగర మ్యూజియం సందర్శించాను."},{"en":"I saw old coins, paintings, and wooden boats there.","native":"నేను అక్కడ పాత నాణేలు, పెయింటింగులు, చెక్క పడవలు చూశాను."},{"en":"I am going to visit the science museum next month.","native":"వచ్చే నెల నేను సైన్స్ మ్యూజియం సందర్శించబోతున్నాను."}]},"hi":{"word":"संग्रहालय","question":"क्या आप किसी संग्रहालय में गए हैं? आपने वहाँ क्या देखा?","examples":[{"en":"I visited the city museum with my class.","native":"मैं अपनी कक्षा के साथ शहर का संग्रहालय देखने गया।"},{"en":"I saw old coins, paintings, and wooden boats there.","native":"मैंने वहाँ पुराने सिक्के, चित्र और लकड़ी की नावें देखीं।"},{"en":"I am going to visit the science museum next month.","native":"मैं अगले महीने विज्ञान संग्रहालय जाने वाला हूँ।"}]},"es":{"word":"museo","question":"¿Has visitado un museo? ¿Qué viste allí?","examples":[{"en":"I visited the city museum with my class.","native":"Visité el museo de la ciudad con mi clase."},{"en":"I saw old coins, paintings, and wooden boats there.","native":"Vi monedas antiguas, cuadros y barcos de madera allí."},{"en":"I am going to visit the science museum next month.","native":"Voy a visitar el museo de ciencias el mes que viene."}]},"zh":{"word":"博物馆","question":"你参观过博物馆吗？你在那里看到了什么？","examples":[{"en":"I visited the city museum with my class.","native":"我和同学们一起参观了城市博物馆。"},{"en":"I saw old coins, paintings, and wooden boats there.","native":"我在那里看到了古钱币、绘画和木船。"},{"en":"I am going to visit the science museum next month.","native":"下个月我打算去参观科学博物馆。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'zoo', 'Do you like the zoo? What animals did you see there?', '{"te":{"word":"జూ","question":"మీకు జూ ఇష్టమా? మీరు అక్కడ ఏ జంతువులు చూశారు?","examples":[{"en":"I went to the zoo with my family last winter.","native":"గత శీతాకాలంలో నేను నా కుటుంబంతో జూకి వెళ్ళాను."},{"en":"We saw lions, elephants, and colourful birds there.","native":"మేము అక్కడ సింహాలు, ఏనుగులు, రంగురంగుల పక్షులు చూశాము."},{"en":"My little sister liked the monkeys the most.","native":"నా చిన్న చెల్లెలికి కోతులు అంటే అత్యంత ఇష్టం."}]},"hi":{"word":"चिड़ियाघर","question":"क्या आपको चिड़ियाघर पसंद है? आपने वहाँ कौन से जानवर देखे?","examples":[{"en":"I went to the zoo with my family last winter.","native":"पिछली सर्दी में मैं अपने परिवार के साथ चिड़ियाघर गया।"},{"en":"We saw lions, elephants, and colourful birds there.","native":"हमने वहाँ शेर, हाथी और रंगीन पक्षी देखे।"},{"en":"My little sister liked the monkeys the most.","native":"मेरी छोटी बहन को बंदर सबसे ज़्यादा पसंद आए।"}]},"es":{"word":"zoológico","question":"¿Te gusta el zoológico? ¿Qué animales viste allí?","examples":[{"en":"I went to the zoo with my family last winter.","native":"Fui al zoológico con mi familia el invierno pasado."},{"en":"We saw lions, elephants, and colourful birds there.","native":"Vimos leones, elefantes y pájaros de colores allí."},{"en":"My little sister liked the monkeys the most.","native":"A mi hermana pequeña le gustaron más los monos."}]},"zh":{"word":"动物园","question":"你喜欢动物园吗？你在那里看到了什么动物？","examples":[{"en":"I went to the zoo with my family last winter.","native":"去年冬天我和家人一起去了动物园。"},{"en":"We saw lions, elephants, and colourful birds there.","native":"我们在那里看到了狮子、大象和五颜六色的鸟。"},{"en":"My little sister liked the monkeys the most.","native":"我妹妹最喜欢猴子。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'animal', 'What is your favourite animal? Talk about it.', '{"te":{"word":"జంతువు","question":"మీ ఇష్టమైన జంతువు ఏది? దాని గురించి మాట్లాడండి.","examples":[{"en":"My favourite animal is the big grey elephant.","native":"నా ఇష్టమైన జంతువు పెద్ద బూడిద రంగు ఏనుగు."},{"en":"It is strong, intelligent, and also very friendly.","native":"అది బలంగా, తెలివిగా, అలాగే చాలా స్నేహపూర్వకంగా ఉంటుంది."},{"en":"I saw elephants at the zoo last year.","native":"గత సంవత్సరం నేను జూలో ఏనుగులు చూశాను."}]},"hi":{"word":"जानवर","question":"आपका पसंदीदा जानवर कौन सा है? उसके बारे में बताइए।","examples":[{"en":"My favourite animal is the big grey elephant.","native":"मेरा पसंदीदा जानवर बड़ा स्लेटी हाथी है।"},{"en":"It is strong, intelligent, and also very friendly.","native":"यह मज़बूत, समझदार और बहुत दोस्ताना भी है।"},{"en":"I saw elephants at the zoo last year.","native":"पिछले साल मैंने चिड़ियाघर में हाथी देखे।"}]},"es":{"word":"animal","question":"¿Cuál es tu animal favorito? Habla de él.","examples":[{"en":"My favourite animal is the big grey elephant.","native":"Mi animal favorito es el gran elefante gris."},{"en":"It is strong, intelligent, and also very friendly.","native":"Es fuerte, inteligente y también muy amigable."},{"en":"I saw elephants at the zoo last year.","native":"Vi elefantes en el zoológico el año pasado."}]},"zh":{"word":"动物","question":"你最喜欢的动物是什么？谈谈它。","examples":[{"en":"My favourite animal is the big grey elephant.","native":"我最喜欢的动物是灰色的大象。"},{"en":"It is strong, intelligent, and also very friendly.","native":"它强壮、聪明，而且非常友好。"},{"en":"I saw elephants at the zoo last year.","native":"去年我在动物园看到了大象。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'exercise', 'Do you exercise every day? What exercise do you like?', '{"te":{"word":"వ్యాయామం","question":"మీరు ప్రతిరోజూ వ్యాయామం చేస్తారా? మీకు ఏ వ్యాయామం ఇష్టం?","examples":[{"en":"I walk for thirty minutes in the park every morning.","native":"నేను ప్రతి ఉదయం పార్కులో మూప్పై నిమిషాలు నడుస్తాను."},{"en":"I like doing simple stretching exercises at home.","native":"ఇంట్లో సరళమైన స్ట్రెచింగ్ వ్యాయామాలు చేయడం నాకు ఇష్టం."},{"en":"My father does yoga in the park on Sundays.","native":"నా నాన్న ఆదివారాల్లో పార్కులో యోగా చేస్తారు."}]},"hi":{"word":"व्यायाम","question":"क्या आप रोज़ व्यायाम करते हैं? आपको कौन सा व्यायाम पसंद है?","examples":[{"en":"I walk for thirty minutes in the park every morning.","native":"मैं हर सुबह पार्क में तीस मिनट घूमता हूँ।"},{"en":"I like doing simple stretching exercises at home.","native":"मुझे घर पर साधारण स्ट्रेचिंग व्यायाम करना पसंद है।"},{"en":"My father does yoga in the park on Sundays.","native":"मेरे पिता रविवार को पार्क में योग करते हैं।"}]},"es":{"word":"ejercicio","question":"¿Haces ejercicio todos los días? ¿Qué ejercicio te gusta?","examples":[{"en":"I walk for thirty minutes in the park every morning.","native":"Camino treinta minutos en el parque cada mañana."},{"en":"I like doing simple stretching exercises at home.","native":"Me gusta hacer ejercicios sencillos de estiramiento en casa."},{"en":"My father does yoga in the park on Sundays.","native":"Mi padre hace yoga en el parque los domingos."}]},"zh":{"word":"锻炼","question":"你每天都锻炼吗？你喜欢什么运动？","examples":[{"en":"I walk for thirty minutes in the park every morning.","native":"我每天早上去公园走三十分钟。"},{"en":"I like doing simple stretching exercises at home.","native":"我喜欢在家做简单的拉伸运动。"},{"en":"My father does yoga in the park on Sundays.","native":"我爸爸星期天在公园里练瑜伽。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'haircut', 'How often do you get a haircut? Talk about your last one.', '{"te":{"word":"హెయిర్ కట్","question":"మీరు ఎంత తరచుగా జుట్టు కత్తిరించుకుంటారు? మీ చివరిదాని గురించి మాట్లాడండి.","examples":[{"en":"I get a haircut once every two months.","native":"నేను ప్రతి రెండు నెలలకు ఒకసారి జుట్టు కత్తిరించుకుంటాను."},{"en":"The barber near my house cuts hair very well.","native":"మా ఇంటి దగ్గర ఉన్న నాపితుడు జుట్టును చాలా బాగా కత్తిరిస్తాడు."},{"en":"Last week I got a short haircut for summer.","native":"గత వారం నేను వేసవి కోసం పొట్టిగా జుట్టు కత్తిరించుకున్నాను."}]},"hi":{"word":"हेयरकट","question":"आप कितनी बार बाल कटवाते हैं? अपने पिछले हेयरकट के बारे में बताइए।","examples":[{"en":"I get a haircut once every two months.","native":"मैं हर दो महीने में एक बार बाल कटवाता हूँ।"},{"en":"The barber near my house cuts hair very well.","native":"मेरे घर के पास का नाई बाल बहुत अच्छे काटता है।"},{"en":"Last week I got a short haircut for summer.","native":"पिछले हफ़्ते मैंने गर्मियों के लिए छोटे बाल कटवाए।"}]},"es":{"word":"corte de pelo","question":"¿Con qué frecuencia te cortas el pelo? Habla del último.","examples":[{"en":"I get a haircut once every two months.","native":"Me corto el pelo una vez cada dos meses."},{"en":"The barber near my house cuts hair very well.","native":"El peluquero cerca de mi casa corta el pelo muy bien."},{"en":"Last week I got a short haircut for summer.","native":"La semana pasada me corté el pelo corto para el verano."}]},"zh":{"word":"理发","question":"你多久理一次发？谈谈你上一次理发。","examples":[{"en":"I get a haircut once every two months.","native":"我每两个月理一次发。"},{"en":"The barber near my house cuts hair very well.","native":"我家附近的理发师剪得非常好。"},{"en":"Last week I got a short haircut for summer.","native":"上周我为了夏天剪了短发。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'radio', 'Do you listen to the radio? What programmes do you like?', '{"te":{"word":"రేడియో","question":"మీరు రేడియో వింటారా? మీకు ఏ కార్యక్రమాలు ఇష్టం?","examples":[{"en":"My grandfather listens to the radio every morning.","native":"నా తాతయ్య ప్రతి ఉదయం రేడియో వింటారు."},{"en":"I like music programmes and the sports news.","native":"నాకు సంగీత కార్యక్రమాలు, క్రీడా వార్తలు ఇష్టం."},{"en":"We heard the news on the radio yesterday.","native":"నిన్న మేము రేడియోలో వార్తలు విన్నాము."}]},"hi":{"word":"रेडियो","question":"क्या आप रेडियो सुनते हैं? आपको कौन से कार्यक्रम पसंद हैं?","examples":[{"en":"My grandfather listens to the radio every morning.","native":"मेरे दादा हर सुबह रेडियो सुनते हैं।"},{"en":"I like music programmes and the sports news.","native":"मुझे संगीत कार्यक्रम और खेल समाचार पसंद हैं।"},{"en":"We heard the news on the radio yesterday.","native":"कल हमने रेडियो पर ख़बरें सुनीं।"}]},"es":{"word":"radio","question":"¿Escuchas la radio? ¿Qué programas te gustan?","examples":[{"en":"My grandfather listens to the radio every morning.","native":"Mi abuelo escucha la radio cada mañana."},{"en":"I like music programmes and the sports news.","native":"Me gustan los programas de música y las noticias deportivas."},{"en":"We heard the news on the radio yesterday.","native":"Ayer escuchamos las noticias en la radio."}]},"zh":{"word":"广播","question":"你听广播吗？你喜欢什么节目？","examples":[{"en":"My grandfather listens to the radio every morning.","native":"我爷爷每天早上听广播。"},{"en":"I like music programmes and the sports news.","native":"我喜欢音乐节目和体育新闻。"},{"en":"We heard the news on the radio yesterday.","native":"昨天我们在广播里听了新闻。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'newspaper', 'Do you read the newspaper? What do you read first?', '{"te":{"word":"వార్తాపత్రిక","question":"మీరు వార్తాపత్రిక చదువుతారా? మీరు ముందు ఏమి చదువుతారు?","examples":[{"en":"My father reads the newspaper every morning with tea.","native":"నా నాన్న ప్రతి ఉదయం టీతో వార్తాపత్రిక చదువుతారు."},{"en":"I read the sports page and the local news.","native":"నేను క్రీడా పేజీ, స్థానిక వార్తలు చదువుతాను."},{"en":"Yesterday I read an interesting story about our town.","native":"నిన్న నేను మా పట్టణం గురించి ఒక ఆసక్తికరమైన కథనం చదివాను."}]},"hi":{"word":"अख़बार","question":"क्या आप अख़बार पढ़ते हैं? आप सबसे पहले क्या पढ़ते हैं?","examples":[{"en":"My father reads the newspaper every morning with tea.","native":"मेरे पिता हर सुबह चाय के साथ अख़बार पढ़ते हैं।"},{"en":"I read the sports page and the local news.","native":"मैं खेल पृष्ठ और स्थानीय ख़बरें पढ़ता हूँ।"},{"en":"Yesterday I read an interesting story about our town.","native":"कल मैंने हमारे शहर के बारे में एक रोचक ख़बर पढ़ी।"}]},"es":{"word":"periódico","question":"¿Lees el periódico? ¿Qué lees primero?","examples":[{"en":"My father reads the newspaper every morning with tea.","native":"Mi padre lee el periódico cada mañana con el té."},{"en":"I read the sports page and the local news.","native":"Leo la página de deportes y las noticias locales."},{"en":"Yesterday I read an interesting story about our town.","native":"Ayer leí una noticia interesante sobre nuestra ciudad."}]},"zh":{"word":"报纸","question":"你读报纸吗？你最先读什么？","examples":[{"en":"My father reads the newspaper every morning with tea.","native":"我爸爸每天早上边喝茶边看报纸。"},{"en":"I read the sports page and the local news.","native":"我读体育版和本地新闻。"},{"en":"Yesterday I read an interesting story about our town.","native":"昨天我读了一条关于我们城市的有趣新闻。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'umbrella', 'Do you carry an umbrella? Talk about a rainy day.', '{"te":{"word":"గొడుగు","question":"మీరు గొడుగు తీసుకెళ్తారా? ఒక వర్షం పడిన రోజు గురించి మాట్లాడండి.","examples":[{"en":"I always carry an umbrella in the rainy season.","native":"వర్షాకాలంలో నేను ఎల్లప్పుడూ గొడుగు తీసుకెళ్తాను."},{"en":"My umbrella is big, black, and very old.","native":"నా గొడుగు పెద్దది, నల్లది, చాలా పాతది."},{"en":"Last week it saved me from heavy rain.","native":"గత వారం అది నన్ను భారీ వర్షం నుండి కాపాడింది."}]},"hi":{"word":"छाता","question":"क्या आप छाता लेकर चलते हैं? किसी बारिश वाले दिन के बारे में बताइए।","examples":[{"en":"I always carry an umbrella in the rainy season.","native":"बारिश के मौसम में मैं हमेशा छाता लेकर चलता हूँ।"},{"en":"My umbrella is big, black, and very old.","native":"मेरा छाता बड़ा, काला और बहुत पुराना है।"},{"en":"Last week it saved me from heavy rain.","native":"पिछले हफ़्ते उसने मुझे मूसलाधार बारिश से बचाया।"}]},"es":{"word":"paraguas","question":"¿Llevas paraguas? Habla de un día de lluvia.","examples":[{"en":"I always carry an umbrella in the rainy season.","native":"Siempre llevo un paraguas en la temporada de lluvias."},{"en":"My umbrella is big, black, and very old.","native":"Mi paraguas es grande, negro y muy viejo."},{"en":"Last week it saved me from heavy rain.","native":"La semana pasada me salvó de una lluvia fuerte."}]},"zh":{"word":"雨伞","question":"你带雨伞吗？谈谈一个下雨天。","examples":[{"en":"I always carry an umbrella in the rainy season.","native":"雨季我总是随身带伞。"},{"en":"My umbrella is big, black, and very old.","native":"我的伞又大又黑，而且非常旧。"},{"en":"Last week it saved me from heavy rain.","native":"上周它帮我躲过了大雨。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'taxi', 'Do you ever take a taxi? Talk about a taxi ride.', '{"te":{"word":"టాక్సీ","question":"మీరు ఎప్పుడైనా టాక్సీ తీసుకుంటారా? ఒక టాక్సీ ప్రయాణం గురించి మాట్లాడండి.","examples":[{"en":"I take a taxi when it rains heavily.","native":"భారీ వర్షం పడినప్పుడు నేను టాక్సీ తీసుకుంటాను."},{"en":"Last night I took a taxi home from the station.","native":"నిన్న రాత్రి నేను స్టేషన్ నుండి టాక్సీలో ఇంటికి వచ్చాను."},{"en":"The driver was friendly and drove very safely.","native":"డ్రైవర్ స్నేహపూర్వకంగా, చాలా జాగ్రత్తగా డ్రైవ్ చేశాడు."}]},"hi":{"word":"टैक्सी","question":"क्या आप कभी टैक्सी लेते हैं? किसी टैक्सी सफ़र के बारे में बताइए।","examples":[{"en":"I take a taxi when it rains heavily.","native":"जब तेज़ बारिश होती है तो मैं टैक्सी लेता हूँ।"},{"en":"Last night I took a taxi home from the station.","native":"कल रात मैं स्टेशन से टैक्सी से घर आया।"},{"en":"The driver was friendly and drove very safely.","native":"ड्राइवर दोस्ताना था और बहुत सावधानी से गाड़ी चला रहा था।"}]},"es":{"word":"taxi","question":"¿Tomas algún taxi alguna vez? Habla de un viaje en taxi.","examples":[{"en":"I take a taxi when it rains heavily.","native":"Tomo un taxi cuando llueve mucho."},{"en":"Last night I took a taxi home from the station.","native":"Anoche tomé un taxi a casa desde la estación."},{"en":"The driver was friendly and drove very safely.","native":"El conductor era amable y conducía con mucho cuidado."}]},"zh":{"word":"出租车","question":"你坐过出租车吗？谈谈一次坐出租车的经历。","examples":[{"en":"I take a taxi when it rains heavily.","native":"下大雨的时候我会坐出租车。"},{"en":"Last night I took a taxi home from the station.","native":"昨晚我从车站坐出租车回家。"},{"en":"The driver was friendly and drove very safely.","native":"司机很友好，开车非常稳。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'airport', 'Have you been to an airport? Talk about it.', '{"te":{"word":"విమానాశ్రయం","question":"మీరు విమానాశ్రయానికి వెళ్లారా? దాని గురించి మాట్లాడండి.","examples":[{"en":"I went to the airport to receive my uncle.","native":"నేను నా మామయ్యను రిసీవ్ చేసుకోవడానికి విమానాశ్రయానికి వెళ్ళాను."},{"en":"The airport was big, clean, and very busy.","native":"విమానాశ్రయం పెద్దగా, శుభ్రంగా, చాలా రద్దీగా ఉంది."},{"en":"We watched the planes take off and land.","native":"మేము విమానాలు టేకాఫ్ అవ్వడం, ల్యాండ్ అవ్వడం చూశాము."}]},"hi":{"word":"हवाई अड्डा","question":"क्या आप किसी हवाई अड्डे पर गए हैं? इसके बारे में बताइए।","examples":[{"en":"I went to the airport to receive my uncle.","native":"मैं अपने चाचा को लेने हवाई अड्डे पर गया।"},{"en":"The airport was big, clean, and very busy.","native":"हवाई अड्डा बड़ा, साफ़ और बहुत भीड़भाड़ वाला था।"},{"en":"We watched the planes take off and land.","native":"हमने हवाई जहाज़ उड़ान भरते और उतरते देखे।"}]},"es":{"word":"aeropuerto","question":"¿Has estado en un aeropuerto? Háblame de ello.","examples":[{"en":"I went to the airport to receive my uncle.","native":"Fui al aeropuerto a recibir a mi tío."},{"en":"The airport was big, clean, and very busy.","native":"El aeropuerto era grande, limpio y muy concurrido."},{"en":"We watched the planes take off and land.","native":"Vimos los aviones despegar y aterrizar."}]},"zh":{"word":"机场","question":"你去过机场吗？谈谈那次经历。","examples":[{"en":"I went to the airport to receive my uncle.","native":"我去机场接我叔叔。"},{"en":"The airport was big, clean, and very busy.","native":"机场又大又干净，人很多。"},{"en":"We watched the planes take off and land.","native":"我们看了飞机起飞和降落。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'ticket', 'Talk about a time you bought a ticket for travel or a show.', '{"te":{"word":"టికెట్","question":"ప్రయాణం లేదా షో కోసం మీరు టికెట్ కొన్న ఒక సందర్భం గురించి మాట్లాడండి.","examples":[{"en":"I bought a train ticket online last week.","native":"గత వారం నేను ఆన్‌లైన్‌లో రైలు టికెట్ కొన్నాను."},{"en":"The ticket was cheap because I booked early.","native":"నేను ముందుగానే బుక్ చేశాను కాబట్టి టికెట్ చౌకగా వచ్చింది."},{"en":"I kept the ticket safely in my bag.","native":"నేను టికెట్‌ను నా బ్యాగులో జాగ్రత్తగా ఉంచాను."}]},"hi":{"word":"टिकट","question":"किसी यात्रा या शो के लिए टिकट खरीदने के किसी मौके के बारे में बताइए।","examples":[{"en":"I bought a train ticket online last week.","native":"पिछले हफ़्ते मैंने ऑनलाइन ट्रेन की टिकट खरीदी।"},{"en":"The ticket was cheap because I booked early.","native":"टिकट सस्ती थी क्योंकि मैंने जल्दी बुक कराई थी।"},{"en":"I kept the ticket safely in my bag.","native":"मैंने टिकट अपने बैग में सुरक्षित रखी।"}]},"es":{"word":"billete","question":"Habla de una vez que compraste un billete para un viaje o un espectáculo.","examples":[{"en":"I bought a train ticket online last week.","native":"Compré un billete de tren por internet la semana pasada."},{"en":"The ticket was cheap because I booked early.","native":"El billete era barato porque reservé temprano."},{"en":"I kept the ticket safely in my bag.","native":"Guardé el billete con cuidado en mi bolsa."}]},"zh":{"word":"票","question":"谈谈你买旅行票或演出票的一次经历。","examples":[{"en":"I bought a train ticket online last week.","native":"上周我在网上买了一张火车票。"},{"en":"The ticket was cheap because I booked early.","native":"票很便宜，因为我订得早。"},{"en":"I kept the ticket safely in my bag.","native":"我把票小心地放在包里。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'hotel', 'Talk about a hotel where you stayed.', '{"te":{"word":"హోటల్","question":"మీరు బస చేసిన ఒక హోటల్ గురించి మాట్లాడండి.","examples":[{"en":"Last year we stayed in a small hotel near the sea.","native":"గత సంవత్సరం మేము సముద్రం దగ్గర ఒక చిన్న హోటల్లో బస చేశాము."},{"en":"My room was clean and had a nice view.","native":"నా గది శుభ్రంగా ఉంది, మంచి దృశ్యం కనిపించింది."},{"en":"The hotel served a good breakfast every morning.","native":"హోటల్ ప్రతి ఉదయం మంచి అల్పాహారం అందించింది."}]},"hi":{"word":"होटल","question":"किसी ऐसे होटल के बारे में बताइए जहाँ आप ठहरे।","examples":[{"en":"Last year we stayed in a small hotel near the sea.","native":"पिछले साल हम समुद्र के पास एक छोटे होटल में ठहरे।"},{"en":"My room was clean and had a nice view.","native":"मेरा कमरा साफ़ था और वहाँ से अच्छा नज़ारा दिखता था।"},{"en":"The hotel served a good breakfast every morning.","native":"होटल हर सुबह अच्छा नाश्ता परोसता था।"}]},"es":{"word":"hotel","question":"Habla de un hotel donde te alojaste.","examples":[{"en":"Last year we stayed in a small hotel near the sea.","native":"El año pasado nos alojamos en un hotel pequeño cerca del mar."},{"en":"My room was clean and had a nice view.","native":"Mi habitación estaba limpia y tenía una vista bonita."},{"en":"The hotel served a good breakfast every morning.","native":"El hotel servía un buen desayuno cada mañana."}]},"zh":{"word":"酒店","question":"谈谈你住过的一家酒店。","examples":[{"en":"Last year we stayed in a small hotel near the sea.","native":"去年我们住在海边的一家小酒店。"},{"en":"My room was clean and had a nice view.","native":"我的房间很干净，景色也不错。"},{"en":"The hotel served a good breakfast every morning.","native":"酒店每天早上提供美味的早餐。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'camping', 'Have you ever been camping? Would you like to try it?', '{"te":{"word":"క్యాంపింగ్","question":"మీరు ఎప్పుడైనా క్యాంపింగ్ చేశారా? మీరు దానిని ప్రయత్నించాలనుకుంటున్నారా?","examples":[{"en":"I went camping in the forest with my friends.","native":"నేను నా స్నేహితులతో అడవిలో క్యాంపింగ్ చేశాను."},{"en":"We slept in a tent and cooked on a fire.","native":"మేము టెంటులో పడుకున్నాము, మంటపై వంట చేశాము."},{"en":"Next summer I am going to camp near the river.","native":"వచ్చే వేసవిలో నేను నది దగ్గర క్యాంపింగ్ చేయబోతున్నాను."}]},"hi":{"word":"कैंपिंग","question":"क्या आप कभी कैंपिंग पर गए हैं? क्या आप इसे आज़माना चाहेंगे?","examples":[{"en":"I went camping in the forest with my friends.","native":"मैं अपने दोस्तों के साथ जंगल में कैंपिंग पर गया।"},{"en":"We slept in a tent and cooked on a fire.","native":"हम तंबू में सोए और आग पर खाना बनाया।"},{"en":"Next summer I am going to camp near the river.","native":"अगली गर्मी में मैं नदी के पास कैंपिंग करने वाला हूँ।"}]},"es":{"word":"acampada","question":"¿Has ido de acampada alguna vez? ¿Te gustaría probarlo?","examples":[{"en":"I went camping in the forest with my friends.","native":"Fui de acampada al bosque con mis amigos."},{"en":"We slept in a tent and cooked on a fire.","native":"Dormimos en una tienda y cocinamos en una hoguera."},{"en":"Next summer I am going to camp near the river.","native":"El próximo verano voy a acampar cerca del río."}]},"zh":{"word":"露营","question":"你露营过吗？你想试试吗？","examples":[{"en":"I went camping in the forest with my friends.","native":"我和朋友们去森林里露营过。"},{"en":"We slept in a tent and cooked on a fire.","native":"我们睡在帐篷里，在篝火上做饭。"},{"en":"Next summer I am going to camp near the river.","native":"明年夏天我打算去河边露营。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'cake', 'Do you like cake? When do you eat cake?', '{"te":{"word":"కేకు","question":"మీకు కేకు ఇష్టమా? మీరు ఎప్పుడు కేకు తింటారు?","examples":[{"en":"I love chocolate cake with cold vanilla ice cream.","native":"చల్లటి వెనిలా ఐస్ క్రీంతో చాక్లెట్ కేకు నాకు చాలా ఇష్టం."},{"en":"We eat cake at birthdays and family parties.","native":"పుట్టినరోజులు, కుటుంబ వేడుకల్లో మేము కేకు తింటాము."},{"en":"My sister baked a cake for me last Sunday.","native":"గత ఆదివారం నా అక్కయ్య నా కోసం కేకు బేక్ చేసింది."}]},"hi":{"word":"केक","question":"क्या आपको केक पसंद है? आप कब केक खाते हैं?","examples":[{"en":"I love chocolate cake with cold vanilla ice cream.","native":"मुझे ठंडी वनीला आइसक्रीम के साथ चॉकलेट केक बहुत पसंद है।"},{"en":"We eat cake at birthdays and family parties.","native":"हम जन्मदिनों और पारिवारिक पार्टियों में केक खाते हैं।"},{"en":"My sister baked a cake for me last Sunday.","native":"पिछले रविवार मेरी बहन ने मेरे लिए केक बेक किया।"}]},"es":{"word":"pastel","question":"¿Te gusta el pastel? ¿Cuándo comes pastel?","examples":[{"en":"I love chocolate cake with cold vanilla ice cream.","native":"Me encanta el pastel de chocolate con helado de vainilla frío."},{"en":"We eat cake at birthdays and family parties.","native":"Comemos pastel en cumpleaños y fiestas familiares."},{"en":"My sister baked a cake for me last Sunday.","native":"Mi hermana me horneó un pastel el domingo pasado."}]},"zh":{"word":"蛋糕","question":"你喜欢蛋糕吗？你什么时候吃蛋糕？","examples":[{"en":"I love chocolate cake with cold vanilla ice cream.","native":"我非常喜欢巧克力蛋糕配冰的香草冰淇淋。"},{"en":"We eat cake at birthdays and family parties.","native":"我们在生日和家庭聚会上吃蛋糕。"},{"en":"My sister baked a cake for me last Sunday.","native":"上个星期天我姐姐为我烤了一个蛋糕。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'juice', 'What is your favourite juice? How often do you drink it?', '{"te":{"word":"జ్యూస్","question":"మీ ఇష్టమైన జ్యూస్ ఏది? మీరు దానిని ఎంత తరచుగా తాగుతారు?","examples":[{"en":"My favourite juice is fresh sweet orange juice.","native":"నా ఇష్టమైన జ్యూస్ తాజా, తీయటి ఆరెంజ్ జ్యూస్."},{"en":"I drink fruit juice after my evening walk.","native":"సాయంత్రం నడక తర్వాత నేను పండ్ల జ్యూస్ తాగుతాను."},{"en":"In summer I make cold mango juice at home.","native":"వేసవిలో నేను ఇంట్లో చల్లటి మామిడి జ్యూస్ తయారు చేస్తాను."}]},"hi":{"word":"जूस","question":"आपका पसंदीदा जूस कौन सा है? आप इसे कितनी बार पीते हैं?","examples":[{"en":"My favourite juice is fresh sweet orange juice.","native":"मेरा पसंदीदा जूस ताज़ा, मीठा संतरे का जूस है।"},{"en":"I drink fruit juice after my evening walk.","native":"शाम की सैर के बाद मैं फलों का जूस पीता हूँ।"},{"en":"In summer I make cold mango juice at home.","native":"गर्मियों में मैं घर पर ठंडा आम का जूस बनाता हूँ।"}]},"es":{"word":"jugo","question":"¿Cuál es tu jugo favorito? ¿Con qué frecuencia lo bebes?","examples":[{"en":"My favourite juice is fresh sweet orange juice.","native":"Mi jugo favorito es el jugo de naranja fresco y dulce."},{"en":"I drink fruit juice after my evening walk.","native":"Bebo jugo de fruta después de mi paseo de la tarde."},{"en":"In summer I make cold mango juice at home.","native":"En verano hago jugo de mango frío en casa."}]},"zh":{"word":"果汁","question":"你最喜欢的果汁是什么？你多久喝一次？","examples":[{"en":"My favourite juice is fresh sweet orange juice.","native":"我最喜欢的果汁是新鲜香甜的橙汁。"},{"en":"I drink fruit juice after my evening walk.","native":"傍晚散步后我喝果汁。"},{"en":"In summer I make cold mango juice at home.","native":"夏天我在家做冰镇芒果汁。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'chocolate', 'Do you like chocolate? How often do you eat it?', '{"te":{"word":"చాక్లెట్","question":"మీకు చాక్లెట్ ఇష్టమా? మీరు దానిని ఎంత తరచుగా తింటారు?","examples":[{"en":"I like dark chocolate more than milk chocolate.","native":"మిల్క్ చాక్లెట్ కంటే డార్క్ చాక్లెట్ నాకు ఎక్కువ ఇష్టం."},{"en":"I eat a little chocolate on special days.","native":"ప్రత్యేక రోజుల్లో నేను కొద్దిగా చాక్లెట్ తింటాను."},{"en":"My friend gave me a box of chocolates yesterday.","native":"నిన్న నా స్నేహితుడు నాకు ఒక పెట్టె చాక్లెట్లు ఇచ్చాడు."}]},"hi":{"word":"चॉकलेट","question":"क्या आपको चॉकलेट पसंद है? आप इसे कितनी बार खाते हैं?","examples":[{"en":"I like dark chocolate more than milk chocolate.","native":"मुझे मिल्क चॉकलेट से ज़्यादा डार्क चॉकलेट पसंद है।"},{"en":"I eat a little chocolate on special days.","native":"ख़ास दिनों में मैं थोड़ी चॉकलेट खाता हूँ।"},{"en":"My friend gave me a box of chocolates yesterday.","native":"कल मेरे दोस्त ने मुझे चॉकलेट का एक डिब्बा दिया।"}]},"es":{"word":"chocolate","question":"¿Te gusta el chocolate? ¿Con qué frecuencia lo comes?","examples":[{"en":"I like dark chocolate more than milk chocolate.","native":"Me gusta más el chocolate negro que el chocolate con leche."},{"en":"I eat a little chocolate on special days.","native":"Como un poco de chocolate en días especiales."},{"en":"My friend gave me a box of chocolates yesterday.","native":"Mi amigo me regaló una caja de bombones ayer."}]},"zh":{"word":"巧克力","question":"你喜欢巧克力吗？你多久吃一次？","examples":[{"en":"I like dark chocolate more than milk chocolate.","native":"比起牛奶巧克力，我更喜欢黑巧克力。"},{"en":"I eat a little chocolate on special days.","native":"我在特殊的日子里吃一点巧克力。"},{"en":"My friend gave me a box of chocolates yesterday.","native":"昨天我的朋友送了我一盒巧克力。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'driver', 'Do you know a driver? Talk about driving in your town.', '{"te":{"word":"డ్రైవర్","question":"మీకు డ్రైవర్ తెలుసా? మీ పట్టణంలో డ్రైవింగ్ గురించి మాట్లాడండి.","examples":[{"en":"My neighbour is a bus driver in the city.","native":"నా పొరుగువాడు నగరంలో బస్ డ్రైవర్."},{"en":"He drives carefully and knows all the routes.","native":"అతను జాగ్రత్తగా డ్రైవ్ చేస్తాడు, అన్ని మార్గాలు తెలుసు."},{"en":"Drivers must be careful in the heavy rain.","native":"భారీ వర్షంలో డ్రైవర్లు జాగ్రత్తగా ఉండాలి."}]},"hi":{"word":"ड्राइवर","question":"क्या आप किसी ड्राइवर को जानते हैं? अपने शहर में गाड़ी चलाने के बारे में बताइए।","examples":[{"en":"My neighbour is a bus driver in the city.","native":"मेरा पड़ोसी शहर में बस ड्राइवर है।"},{"en":"He drives carefully and knows all the routes.","native":"वह सावधानी से गाड़ी चलाता है और सारे रास्ते जानता है।"},{"en":"Drivers must be careful in the heavy rain.","native":"तेज़ बारिश में ड्राइवरों को सावधान रहना चाहिए।"}]},"es":{"word":"conductor","question":"¿Conoces a un conductor? Habla de conducir en tu ciudad.","examples":[{"en":"My neighbour is a bus driver in the city.","native":"Mi vecino es conductor de autobús en la ciudad."},{"en":"He drives carefully and knows all the routes.","native":"Conduce con cuidado y conoce todas las rutas."},{"en":"Drivers must be careful in the heavy rain.","native":"Los conductores deben tener cuidado con la lluvia fuerte."}]},"zh":{"word":"司机","question":"你认识司机吗？谈谈你所在城市的开车情况。","examples":[{"en":"My neighbour is a bus driver in the city.","native":"我的邻居是城里的公交车司机。"},{"en":"He drives carefully and knows all the routes.","native":"他开车很小心，认识所有的路线。"},{"en":"Drivers must be careful in the heavy rain.","native":"下大雨时司机们必须小心。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'farmer', 'Do you know a farmer? Talk about a farmer''s work.', '{"te":{"word":"రైతు","question":"మీకు రైతు తెలుసా? రైతు పని గురించి మాట్లాడండి.","examples":[{"en":"My grandfather is a farmer in our village.","native":"నా తాతయ్య మా గ్రామంలో రైతు."},{"en":"He grows rice, vegetables, and sugarcane in his fields.","native":"ఆయన తన పొలాల్లో వరి, కూరగాయలు, చెరకు పండిస్తారు."},{"en":"Farmers work hard from early morning every day.","native":"రైతులు ప్రతిరోజూ తెల్లవారుఝామున నుండి కష్టపడి పని చేస్తారు."}]},"hi":{"word":"किसान","question":"क्या आप किसी किसान को जानते हैं? किसान के काम के बारे में बताइए।","examples":[{"en":"My grandfather is a farmer in our village.","native":"मेरे दादा हमारे गाँव में किसान हैं।"},{"en":"He grows rice, vegetables, and sugarcane in his fields.","native":"वे अपने खेतों में धान, सब्ज़ियाँ और गन्ना उगाते हैं।"},{"en":"Farmers work hard from early morning every day.","native":"किसान रोज़ सुबह-सुबह से कड़ी मेहनत करते हैं।"}]},"es":{"word":"agricultor","question":"¿Conoces a un agricultor? Habla del trabajo de un agricultor.","examples":[{"en":"My grandfather is a farmer in our village.","native":"Mi abuelo es agricultor en nuestro pueblo."},{"en":"He grows rice, vegetables, and sugarcane in his fields.","native":"Cultiva arroz, verduras y caña de azúcar en sus campos."},{"en":"Farmers work hard from early morning every day.","native":"Los agricultores trabajan duro desde temprano cada día."}]},"zh":{"word":"农民","question":"你认识农民吗？谈谈农民的工作。","examples":[{"en":"My grandfather is a farmer in our village.","native":"我爷爷是我们村里的农民。"},{"en":"He grows rice, vegetables, and sugarcane in his fields.","native":"他在田里种水稻、蔬菜和甘蔗。"},{"en":"Farmers work hard from early morning every day.","native":"农民每天一大早就辛勤劳动。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'uncle', 'Talk about your uncle. What does he do?', '{"te":{"word":"మేనమామ","question":"మీ మేనమామ గురించి మాట్లాడండి. ఆయన ఏమి చేస్తారు?","examples":[{"en":"My uncle lives in a flat near the market.","native":"నా మేనమామ మార్కెట్ దగ్గర ఒక ఫ్లాట్‌లో నివసిస్తారు."},{"en":"He works in a bank and likes gardening.","native":"ఆయన బ్యాంకులో పని చేస్తారు, తోట పని ఇష్టపడతారు."},{"en":"He visited us last week and brought sweets.","native":"ఆయన గత వారం మమ్మల్ని కలిసి తీపిపదార్థాలు తెచ్చారు."}]},"hi":{"word":"चाचा","question":"अपने चाचा के बारे में बताइए। वे क्या करते हैं?","examples":[{"en":"My uncle lives in a flat near the market.","native":"मेरे चाचा बाज़ार के पास एक फ़्लैट में रहते हैं।"},{"en":"He works in a bank and likes gardening.","native":"वे बैंक में काम करते हैं और बाग़बानी पसंद करते हैं।"},{"en":"He visited us last week and brought sweets.","native":"वे पिछले हफ़्ते हमसे मिले और मिठाइयाँ लाए।"}]},"es":{"word":"tío","question":"Habla de tu tío. ¿A qué se dedica?","examples":[{"en":"My uncle lives in a flat near the market.","native":"Mi tío vive en un piso cerca del mercado."},{"en":"He works in a bank and likes gardening.","native":"Trabaja en un banco y le gusta la jardinería."},{"en":"He visited us last week and brought sweets.","native":"Nos visitó la semana pasada y trajo dulces."}]},"zh":{"word":"叔叔","question":"谈谈你的叔叔。他是做什么的？","examples":[{"en":"My uncle lives in a flat near the market.","native":"我叔叔住在市场附近的一套公寓里。"},{"en":"He works in a bank and likes gardening.","native":"他在银行工作，喜欢园艺。"},{"en":"He visited us last week and brought sweets.","native":"他上周来看我们，还带了糖果。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'aunt', 'Talk about your aunt. What is she like?', '{"te":{"word":"పిన్ని","question":"మీ పిన్ని గురించి మాట్లాడండి. ఆమె ఎలా ఉంటారు?","examples":[{"en":"My aunt is a teacher in a primary school.","native":"నా పిన్ని ఒక ప్రాథమిక పాఠశాలలో ఉపాధ్యాయిని."},{"en":"She is kind and tells us funny stories.","native":"ఆమె మంచిది, మాకు ఫన్నీ కథలు చెబుతుంది."},{"en":"She cooked a special dinner for us yesterday.","native":"ఆమె నిన్న మా కోసం ప్రత్యేకమైన భోజనం వండింది."}]},"hi":{"word":"चाची","question":"अपनी चाची के बारे में बताइए। वे कैसी हैं?","examples":[{"en":"My aunt is a teacher in a primary school.","native":"मेरी चाची एक प्राथमिक विद्यालय में शिक्षिका हैं।"},{"en":"She is kind and tells us funny stories.","native":"वे दयालु हैं और हमें मज़ेदार कहानियाँ सुनाती हैं।"},{"en":"She cooked a special dinner for us yesterday.","native":"उन्होंने कल हमारे लिए ख़ास खाना बनाया।"}]},"es":{"word":"tía","question":"Habla de tu tía. ¿Cómo es?","examples":[{"en":"My aunt is a teacher in a primary school.","native":"Mi tía es maestra en una escuela primaria."},{"en":"She is kind and tells us funny stories.","native":"Es amable y nos cuenta historias divertidas."},{"en":"She cooked a special dinner for us yesterday.","native":"Nos cocinó una cena especial ayer."}]},"zh":{"word":"姑姑","question":"谈谈你的姑姑。她是什么样的人？","examples":[{"en":"My aunt is a teacher in a primary school.","native":"我姑姑是一所小学的老师。"},{"en":"She is kind and tells us funny stories.","native":"她很和蔼，给我们讲有趣的故事。"},{"en":"She cooked a special dinner for us yesterday.","native":"她昨天为我们做了一顿特别的晚餐。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'cousin', 'Talk about one of your cousins. What do you do together?', '{"te":{"word":"కజిన్","question":"మీ కజిన్ గురించి మాట్లాడండి. మీరు కలిసి ఏమి చేస్తారు?","examples":[{"en":"My cousin Ravi is the same age as me.","native":"నా కజిన్ రవి నాతో ఒకే వయసు ఉన్నాడు."},{"en":"We play cricket and watch films together on Sundays.","native":"మేము ఆదివారాల్లో కలిసి క్రికెట్ ఆడతాము, సినిమాలు చూస్తాము."},{"en":"He is going to visit me during the holidays.","native":"అతను సెలవుల్లో నన్ను కలవడానికి రాబోతున్నాడు."}]},"hi":{"word":"कज़िन","question":"अपने किसी कज़िन के बारे में बताइए। आप साथ में क्या करते हैं?","examples":[{"en":"My cousin Ravi is the same age as me.","native":"मेरा कज़िन रवि मुझ जितनी ही उम्र का है।"},{"en":"We play cricket and watch films together on Sundays.","native":"हम रविवार को साथ क्रिकेट खेलते हैं और फ़िल्में देखते हैं।"},{"en":"He is going to visit me during the holidays.","native":"वह छुट्टियों में मुझसे मिलने आने वाला है।"}]},"es":{"word":"primo","question":"Habla de uno de tus primos. ¿Qué hacéis juntos?","examples":[{"en":"My cousin Ravi is the same age as me.","native":"Mi primo Ravi tiene la misma edad que yo."},{"en":"We play cricket and watch films together on Sundays.","native":"Jugamos al críquet y vemos películas juntos los domingos."},{"en":"He is going to visit me during the holidays.","native":"Va a visitarme durante las vacaciones."}]},"zh":{"word":"表兄弟","question":"谈谈你的一个表兄弟。你们一起做什么？","examples":[{"en":"My cousin Ravi is the same age as me.","native":"我的表哥拉维和我同岁。"},{"en":"We play cricket and watch films together on Sundays.","native":"我们星期天一起打板球、看电影。"},{"en":"He is going to visit me during the holidays.","native":"假期里他要来看我。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'grandfather', 'Talk about your grandfather. What do you like about him?', '{"te":{"word":"తాతయ్య","question":"మీ తాతయ్య గురించి మాట్లాడండి. ఆయన గురించి మీకు ఏమి ఇష్టం?","examples":[{"en":"My grandfather is seventy years old and healthy.","native":"నా తాతయ్యకు డెబ్బై సంవత్సరాలు, ఆయన ఆరోగ్యంగా ఉన్నారు."},{"en":"He tells me stories about his childhood days.","native":"ఆయన నాకు తన బాల్యం గురించి కథలు చెబుతారు."},{"en":"Every morning he walks to the temple near home.","native":"ప్రతి ఉదయం ఆయన ఇంటి దగ్గర ఉన్న దేవాలయానికి నడిచి వెళ్తారు."}]},"hi":{"word":"दादा","question":"अपने दादा के बारे में बताइए। आपको उनकी क्या बात पसंद है?","examples":[{"en":"My grandfather is seventy years old and healthy.","native":"मेरे दादा सत्तर साल के हैं और स्वस्थ हैं।"},{"en":"He tells me stories about his childhood days.","native":"वे मुझे अपने बचपन की कहानियाँ सुनाते हैं।"},{"en":"Every morning he walks to the temple near home.","native":"हर सुबह वे घर के पास के मंदिर पैदल जाते हैं।"}]},"es":{"word":"abuelo","question":"Habla de tu abuelo. ¿Qué te gusta de él?","examples":[{"en":"My grandfather is seventy years old and healthy.","native":"Mi abuelo tiene setenta años y está sano."},{"en":"He tells me stories about his childhood days.","native":"Me cuenta historias sobre su infancia."},{"en":"Every morning he walks to the temple near home.","native":"Cada mañana camina hasta el templo cerca de casa."}]},"zh":{"word":"爷爷","question":"谈谈你的爷爷。你喜欢他什么？","examples":[{"en":"My grandfather is seventy years old and healthy.","native":"我爷爷七十岁了，身体很健康。"},{"en":"He tells me stories about his childhood days.","native":"他给我讲他童年的故事。"},{"en":"Every morning he walks to the temple near home.","native":"每天早上他步行去家附近的寺庙。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'grandmother', 'Talk about your grandmother. What does she do?', '{"te":{"word":"అమ్మమ్మ","question":"మీ అమ్మమ్మ గురించి మాట్లాడండి. ఆమె ఏమి చేస్తుంది?","examples":[{"en":"My grandmother lives with us in our house.","native":"నా అమ్మమ్మ మా ఇంట్లో మాతో నివసిస్తుంది."},{"en":"She cooks very tasty food for the family.","native":"ఆమె కుటుంబం కోసం చాలా రుచికరమైన భోజనం వంటుతుంది."},{"en":"She tells us many old stories at night.","native":"ఆమె రాత్రి మాకు చాలా పాత కథలు చెబుతుంది."}]},"hi":{"word":"दादी","question":"अपनी दादी के बारे में बताइए। वे क्या करती हैं?","examples":[{"en":"My grandmother lives with us in our house.","native":"मेरी दादी हमारे घर में हमारे साथ रहती हैं।"},{"en":"She cooks very tasty food for the family.","native":"वे परिवार के लिए बहुत स्वादिष्ट खाना बनाती हैं।"},{"en":"She tells us many old stories at night.","native":"वे रात में हमें कई पुरानी कहानियाँ सुनाती हैं।"}]},"es":{"word":"abuela","question":"Habla de tu abuela. ¿Qué hace ella?","examples":[{"en":"My grandmother lives with us in our house.","native":"Mi abuela vive con nosotros en nuestra casa."},{"en":"She cooks very tasty food for the family.","native":"Cocina comida muy rica para la familia."},{"en":"She tells us many old stories at night.","native":"Nos cuenta muchos cuentos antiguos por la noche."}]},"zh":{"word":"奶奶","question":"谈谈你的奶奶。她做些什么？","examples":[{"en":"My grandmother lives with us in our house.","native":"我奶奶和我们一起住在家里。"},{"en":"She cooks very tasty food for the family.","native":"她为家人做非常可口的饭菜。"},{"en":"She tells us many old stories at night.","native":"晚上她给我们讲很多古老的故事。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'baby', 'Is there a baby in your family? Talk about the baby.', '{"te":{"word":"పాప","question":"మీ కుటుంబంలో పాప ఉందా? ఆ పాప గురించి మాట్లాడండి.","examples":[{"en":"My sister has a cute little baby boy.","native":"నా అక్కయ్యకు ఒక అందమైన చిన్న మగపిల్లాడు ఉన్నాడు."},{"en":"The baby smiles at everyone and sleeps a lot.","native":"ఆ పాప అందరిని చూసి నవ్వుతుంది, చాలా నిద్రపోతుంది."},{"en":"I played with the baby all day yesterday.","native":"నిన్న నేను పాపతో రోజంతా ఆడుకున్నాను."}]},"hi":{"word":"शिशु","question":"क्या आपके परिवार में कोई बच्चा है? उस बच्चे के बारे में बताइए।","examples":[{"en":"My sister has a cute little baby boy.","native":"मेरी बहन का एक प्यारा छोटा बेटा है।"},{"en":"The baby smiles at everyone and sleeps a lot.","native":"बच्चा सबको देखकर मुस्कुराता है और बहुत सोता है।"},{"en":"I played with the baby all day yesterday.","native":"कल मैं बच्चे के साथ पूरा दिन खेला।"}]},"es":{"word":"bebé","question":"¿Hay un bebé en tu familia? Habla del bebé.","examples":[{"en":"My sister has a cute little baby boy.","native":"Mi hermana tiene un bebé pequeño y bonito."},{"en":"The baby smiles at everyone and sleeps a lot.","native":"El bebé sonríe a todos y duerme mucho."},{"en":"I played with the baby all day yesterday.","native":"Ayer jugué con el bebé todo el día."}]},"zh":{"word":"宝宝","question":"你家里有宝宝吗？谈谈这个宝宝。","examples":[{"en":"My sister has a cute little baby boy.","native":"我姐姐有一个可爱的小男孩宝宝。"},{"en":"The baby smiles at everyone and sleeps a lot.","native":"宝宝见谁都笑，而且睡得很多。"},{"en":"I played with the baby all day yesterday.","native":"昨天我和宝宝玩了一整天。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'brother', 'Talk about your brother. What does he do?', '{"te":{"word":"సోదరుడు","question":"మీ సోదరుడు గురించి మాట్లాడండి. అతను ఏమి చేస్తాడు?","examples":[{"en":"My elder brother works in a big office.","native":"నా అన్నయ్య ఒక పెద్ద ఆఫీసులో పని చేస్తాడు."},{"en":"He likes playing cricket and watching old films.","native":"అతను క్రికెట్ ఆడడం, పాత సినిమాలు చూడడం ఇష్టపడతాడు."},{"en":"He helped me with my maths homework yesterday.","native":"నిన్న అతను నా గణిత ఇంటిపనిలో నాకు సహాయం చేశాడు."}]},"hi":{"word":"भाई","question":"अपने भाई के बारे में बताइए। वह क्या करता है?","examples":[{"en":"My elder brother works in a big office.","native":"मेरा बड़ा भाई एक बड़े दफ़्तर में काम करता है।"},{"en":"He likes playing cricket and watching old films.","native":"उसे क्रिकेट खेलना और पुरानी फ़िल्में देखना पसंद है।"},{"en":"He helped me with my maths homework yesterday.","native":"कल उसने मेरे गणित के होमवर्क में मेरी मदद की।"}]},"es":{"word":"hermano","question":"Habla de tu hermano. ¿Qué hace?","examples":[{"en":"My elder brother works in a big office.","native":"Mi hermano mayor trabaja en una oficina grande."},{"en":"He likes playing cricket and watching old films.","native":"Le gusta jugar al críquet y ver películas viejas."},{"en":"He helped me with my maths homework yesterday.","native":"Me ayudó con mi tarea de matemáticas ayer."}]},"zh":{"word":"哥哥","question":"谈谈你的哥哥。他是做什么的？","examples":[{"en":"My elder brother works in a big office.","native":"我哥哥在一间大办公室工作。"},{"en":"He likes playing cricket and watching old films.","native":"他喜欢打板球和看老电影。"},{"en":"He helped me with my maths homework yesterday.","native":"昨天他帮我辅导了数学作业。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'sister', 'Talk about your sister. What do you do together?', '{"te":{"word":"చెల్లెలు","question":"మీ చెల్లెలు గురించి మాట్లాడండి. మీరు కలిసి ఏమి చేస్తారు?","examples":[{"en":"My younger sister studies in class eight now.","native":"నా చెల్లెలు ఇప్పుడు ఎనిమిదో తరగతి చదువుతుంది."},{"en":"We cook together and share our small secrets.","native":"మేము కలిసి వంట చేస్తాము, మా చిన్న రహస్యాలు పంచుకుంటాము."},{"en":"She is going to learn swimming this summer.","native":"ఆమె ఈ వేసవిలో ఈత నేర్చుకోబోతుంది."}]},"hi":{"word":"बहन","question":"अपनी बहन के बारे में बताइए। आप साथ में क्या करते हैं?","examples":[{"en":"My younger sister studies in class eight now.","native":"मेरी छोटी बहन अब आठवीं कक्षा में पढ़ती है।"},{"en":"We cook together and share our small secrets.","native":"हम साथ खाना बनाते हैं और अपने छोटे राज़ बाँटते हैं।"},{"en":"She is going to learn swimming this summer.","native":"वह इस गर्मी में तैरना सीखने वाली है।"}]},"es":{"word":"hermana","question":"Habla de tu hermana. ¿Qué hacéis juntas?","examples":[{"en":"My younger sister studies in class eight now.","native":"Mi hermana pequeña estudia ahora en octavo curso."},{"en":"We cook together and share our small secrets.","native":"Cocinamos juntas y compartimos nuestros pequeños secretos."},{"en":"She is going to learn swimming this summer.","native":"Va a aprender a nadar este verano."}]},"zh":{"word":"妹妹","question":"谈谈你的妹妹。你们一起做什么？","examples":[{"en":"My younger sister studies in class eight now.","native":"我妹妹现在上八年级。"},{"en":"We cook together and share our small secrets.","native":"我们一起做饭，分享彼此的小秘密。"},{"en":"She is going to learn swimming this summer.","native":"今年夏天她打算学游泳。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'mother', 'Talk about your mother. What do you like about her?', '{"te":{"word":"అమ్మ","question":"మీ అమ్మ గురించి మాట్లాడండి. ఆమె గురించి మీకు ఏమి ఇష్టం?","examples":[{"en":"My mother gets up early and cooks for us.","native":"నా అమ్మ త్వరగా లేచి మా కోసం వంట చేస్తుంది."},{"en":"She sings very beautifully while she works at home.","native":"ఆమె ఇంట్లో పని చేసేటప్పుడు చాలా అందంగా పాటలు పాడుతుంది."},{"en":"I am going to buy her a gift next week.","native":"వచ్చే వారం నేను ఆమెకు ఒక బహుమతి కొనబోతున్నాను."}]},"hi":{"word":"माँ","question":"अपनी माँ के बारे में बताइए। आपको उनकी क्या बात पसंद है?","examples":[{"en":"My mother gets up early and cooks for us.","native":"मेरी माँ जल्दी उठती है और हमारे लिए खाना बनाती है।"},{"en":"She sings very beautifully while she works at home.","native":"वे घर में काम करते समय बहुत सुंदर गाती है।"},{"en":"I am going to buy her a gift next week.","native":"मैं अगले हफ़्ते उनके लिए एक तोहफ़ा खरीदने वाला हूँ।"}]},"es":{"word":"madre","question":"Habla de tu madre. ¿Qué te gusta de ella?","examples":[{"en":"My mother gets up early and cooks for us.","native":"Mi madre se levanta temprano y cocina para nosotros."},{"en":"She sings very beautifully while she works at home.","native":"Canta muy bonito mientras trabaja en casa."},{"en":"I am going to buy her a gift next week.","native":"Voy a comprarle un regalo la semana que viene."}]},"zh":{"word":"妈妈","question":"谈谈你的妈妈。你喜欢她什么？","examples":[{"en":"My mother gets up early and cooks for us.","native":"我妈妈起得很早，为我们做饭。"},{"en":"She sings very beautifully while she works at home.","native":"她在家干活时唱歌非常好听。"},{"en":"I am going to buy her a gift next week.","native":"下周我打算给她买一份礼物。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('A2', 'father', 'Talk about your father. What does he do every day?', '{"te":{"word":"నాన్న","question":"మీ నాన్న గురించి మాట్లాడండి. ఆయన ప్రతిరోజూ ఏమి చేస్తారు?","examples":[{"en":"My father is a shopkeeper in our town.","native":"నా నాన్న మా పట్టణంలో దుకాణదారు."},{"en":"He works hard and comes home at night.","native":"ఆయన కష్టపడి పని చేసి రాత్రి ఇంటికి వస్తారు."},{"en":"On Sundays he takes us to the park.","native":"ఆదివారాల్లో ఆయన మమ్మల్ని పార్కుకు తీసుకెళ్తారు."}]},"hi":{"word":"पिता","question":"अपने पिता के बारे में बताइए। वे रोज़ क्या करते हैं?","examples":[{"en":"My father is a shopkeeper in our town.","native":"मेरे पिता हमारे शहर में दुकानदार हैं।"},{"en":"He works hard and comes home at night.","native":"वे कड़ी मेहनत करते हैं और रात में घर आते हैं।"},{"en":"On Sundays he takes us to the park.","native":"रविवार को वे हमें पार्क ले जाते हैं।"}]},"es":{"word":"padre","question":"Habla de tu padre. ¿Qué hace todos los días?","examples":[{"en":"My father is a shopkeeper in our town.","native":"Mi padre es tendero en nuestro pueblo."},{"en":"He works hard and comes home at night.","native":"Trabaja duro y vuelve a casa por la noche."},{"en":"On Sundays he takes us to the park.","native":"Los domingos nos lleva al parque."}]},"zh":{"word":"爸爸","question":"谈谈你的爸爸。他每天做什么？","examples":[{"en":"My father is a shopkeeper in our town.","native":"我爸爸是我们镇上的一位店主。"},{"en":"He works hard and comes home at night.","native":"他辛勤工作，晚上才回家。"},{"en":"On Sundays he takes us to the park.","native":"星期天他带我们去公园。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'habit', 'Talk about a habit you want to change.', '{"te":{"word":"అలవాటు","question":"మీరు మార్చుకోవాలనుకుంటున్న ఒక అలవాటు గురించి మాట్లాడండి.","examples":[{"en":"I want to stop using my phone late at night.","native":"నేను రాత్రి ఆలస్యంగా ఫోన్ వాడడం ఆపాలనుకుంటున్నాను."},{"en":"This habit makes me tired the next morning.","native":"ఈ అలవాటు వల్ల మరుసటి రోజు ఉదయం నేను అలసిపోతాను."},{"en":"I plan to read a book before sleeping instead.","native":"బదులుగా నేను పడుకునే ముందు పుస్తకం చదవాలని ప్లాన్ చేస్తున్నాను."}]},"hi":{"word":"आदत","question":"किसी ऐसी आदत के बारे में बताइए जिसे आप बदलना चाहते हैं।","examples":[{"en":"I want to stop using my phone late at night.","native":"मैं देर रात तक फ़ोन इस्तेमाल करना बंद करना चाहता हूँ।"},{"en":"This habit makes me tired the next morning.","native":"इस आदत से मैं अगली सुबह थका हुआ महसूस करता हूँ।"},{"en":"I plan to read a book before sleeping instead.","native":"मैं इसके बजाय सोने से पहले किताब पढ़ने की योजना बना रहा हूँ।"}]},"es":{"word":"hábito","question":"Habla de un hábito que quieres cambiar.","examples":[{"en":"I want to stop using my phone late at night.","native":"Quiero dejar de usar el teléfono hasta tarde por la noche."},{"en":"This habit makes me tired the next morning.","native":"Este hábito me hace sentir cansado a la mañana siguiente."},{"en":"I plan to read a book before sleeping instead.","native":"Planeo leer un libro antes de dormir en su lugar."}]},"zh":{"word":"习惯","question":"谈谈你想改变的一个习惯。","examples":[{"en":"I want to stop using my phone late at night.","native":"我想改掉深夜玩手机的习惯。"},{"en":"This habit makes me tired the next morning.","native":"这个习惯让我第二天早上感到疲惫。"},{"en":"I plan to read a book before sleeping instead.","native":"我打算睡前改为读书。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'movie', 'Describe a movie you enjoyed and explain why.', '{"te":{"word":"సినిమా","question":"మీరు ఆస్వాదించిన ఒక సినిమాను వివరించండి మరియు ఎందుకు నచ్చిందో వివరించండి.","examples":[{"en":"I recently watched a film about a young musician.","native":"నేను ఇటీవల ఒక యువ సంగీతకారుడి గురించి ఒక సినిమా చూశాను."},{"en":"The story was touching and the music was wonderful.","native":"కథ హృదయాన్ని తాకేలా ఉంది మరియు సంగీతం అద్భుతంగా ఉంది."},{"en":"I liked it because it taught me to follow my dreams.","native":"నా కలలను అనుసరించాలని నాకు నేర్పింది కాబట్టి నాకు అది నచ్చింది."}]},"hi":{"word":"फ़िल्म","question":"आपको पसंद आई किसी फ़िल्म का वर्णन कीजिए और बताइए कि क्यों।","examples":[{"en":"I recently watched a film about a young musician.","native":"मैंने हाल ही में एक युवा संगीतकार के बारे में एक फ़िल्म देखी।"},{"en":"The story was touching and the music was wonderful.","native":"कहानी भावुक थी और संगीत अद्भुत था।"},{"en":"I liked it because it taught me to follow my dreams.","native":"मुझे यह इसलिए पसंद आई क्योंकि इसने मुझे अपने सपनों का पीछा करना सिखाया।"}]},"es":{"word":"película","question":"Describe una película que disfrutaste y explica por qué.","examples":[{"en":"I recently watched a film about a young musician.","native":"Hace poco vi una película sobre un músico joven."},{"en":"The story was touching and the music was wonderful.","native":"La historia fue conmovedora y la música fue maravillosa."},{"en":"I liked it because it taught me to follow my dreams.","native":"Me gustó porque me enseñó a seguir mis sueños."}]},"zh":{"word":"电影","question":"描述一部你喜欢的电影并解释原因。","examples":[{"en":"I recently watched a film about a young musician.","native":"我最近看了一部关于一位年轻音乐家的电影。"},{"en":"The story was touching and the music was wonderful.","native":"故事感人，音乐也很棒。"},{"en":"I liked it because it taught me to follow my dreams.","native":"我喜欢它，因为它教会了我追随梦想。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'health', 'What do you do to stay healthy?', '{"te":{"word":"ఆరోగ్యం","question":"ఆరోగ్యంగా ఉండటానికి మీరు ఏమి చేస్తారు?","examples":[{"en":"I exercise for thirty minutes every morning.","native":"నేను ప్రతి ఉదయం ముప్పై నిమిషాలు వ్యాయామం చేస్తాను."},{"en":"I try to eat more fruit and less junk food.","native":"నేను ఎక్కువ పండ్లు తినడానికి మరియు తక్కువ జంక్ ఫుడ్ తినడానికి ప్రయత్నిస్తాను."},{"en":"Sleeping eight hours a night keeps me energetic.","native":"రాత్రికి ఎనిమిది గంటలు నిద్రపోవడం నన్ను శక్తివంతంగా ఉంచుతుంది."}]},"hi":{"word":"स्वास्थ्य","question":"स्वस्थ रहने के लिए आप क्या करते हैं?","examples":[{"en":"I exercise for thirty minutes every morning.","native":"मैं हर सुबह तीस मिनट व्यायाम करता हूँ।"},{"en":"I try to eat more fruit and less junk food.","native":"मैं ज़्यादा फल और कम जंक फ़ूड खाने की कोशिश करता हूँ।"},{"en":"Sleeping eight hours a night keeps me energetic.","native":"रात में आठ घंटे सोना मुझे ऊर्जावान रखता है।"}]},"es":{"word":"salud","question":"¿Qué haces para mantenerte saludable?","examples":[{"en":"I exercise for thirty minutes every morning.","native":"Hago ejercicio treinta minutos cada mañana."},{"en":"I try to eat more fruit and less junk food.","native":"Intento comer más fruta y menos comida chatarra."},{"en":"Sleeping eight hours a night keeps me energetic.","native":"Dormir ocho horas por noche me mantiene con energía."}]},"zh":{"word":"健康","question":"你做什么来保持健康？","examples":[{"en":"I exercise for thirty minutes every morning.","native":"我每天早上锻炼三十分钟。"},{"en":"I try to eat more fruit and less junk food.","native":"我尽量多吃水果，少吃垃圾食品。"},{"en":"Sleeping eight hours a night keeps me energetic.","native":"每晚睡八个小时让我精力充沛。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'festival', 'Describe a festival you celebrate with your family.', '{"te":{"word":"పండుగ","question":"మీరు మీ కుటుంబంతో జరుపుకునే ఒక పండుగను వివరించండి.","examples":[{"en":"My favourite festival is Diwali, the festival of lights.","native":"నా ఇష్టమైన పండుగ దీపావళి, వెలుగుల పండుగ."},{"en":"We decorate our house and share sweets with neighbours.","native":"మేము మా ఇంటిని అలంకరిస్తాము మరియు పక్కింటి వారితో స్వీట్లు పంచుకుంటాము."},{"en":"In the evening, the whole family eats together and laughs a lot.","native":"సాయంత్రం, కుటుంబం మొత్తం కలిసి భోజనం చేసి చాలా నవ్వుకుంటుంది."}]},"hi":{"word":"त्योहार","question":"उस त्योहार का वर्णन कीजिए जो आप अपने परिवार के साथ मनाते हैं।","examples":[{"en":"My favourite festival is Diwali, the festival of lights.","native":"मेरा पसंदीदा त्योहार दीवाली है, रोशनी का त्योहार।"},{"en":"We decorate our house and share sweets with neighbours.","native":"हम अपना घर सजाते हैं और पड़ोसियों के साथ मिठाइयाँ बाँटते हैं।"},{"en":"In the evening, the whole family eats together and laughs a lot.","native":"शाम को, पूरा परिवार साथ खाना खाता है और खूब हँसता है।"}]},"es":{"word":"fiesta","question":"Describe una fiesta que celebras con tu familia.","examples":[{"en":"My favourite festival is Diwali, the festival of lights.","native":"Mi fiesta favorita es Diwali, el festival de las luces."},{"en":"We decorate our house and share sweets with neighbours.","native":"Decoramos nuestra casa y compartimos dulces con los vecinos."},{"en":"In the evening, the whole family eats together and laughs a lot.","native":"Por la noche, toda la familia cena junta y se ríe mucho."}]},"zh":{"word":"节日","question":"描述一个你和家人一起庆祝的节日。","examples":[{"en":"My favourite festival is Diwali, the festival of lights.","native":"我最喜欢的节日是排灯节，灯之节。"},{"en":"We decorate our house and share sweets with neighbours.","native":"我们装饰房子，和邻居分享糖果。"},{"en":"In the evening, the whole family eats together and laughs a lot.","native":"晚上，全家人一起吃饭，欢声笑语。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'technology', 'How does technology help you in your daily life?', '{"te":{"word":"సాంకేతికత","question":"మీ దైనందిన జీవితంలో సాంకేతికత మీకు ఎలా సహాయపడుతుంది?","examples":[{"en":"Technology helps me talk to family members who live far away.","native":"దూరంగా నివసించే నా కుటుంబ సభ్యులతో మాట్లాడటానికి సాంకేతికత నాకు సహాయపడుతుంది."},{"en":"I use my phone to pay bills and learn new things.","native":"బిల్లులు చెల్లించడానికి మరియు కొత్త విషయాలు నేర్చుకోవడానికి నేను నా ఫోన్ వాడతాను."},{"en":"Online maps help me find new places easily.","native":"ఆన్‌లైన్ మ్యాప్‌లు కొత్త ప్రదేశాలను సులభంగా కనుగొనడానికి నాకు సహాయపడతాయి."}]},"hi":{"word":"तकनीक","question":"तकनीक आपके दैनिक जीवन में आपकी कैसे मदद करती है?","examples":[{"en":"Technology helps me talk to family members who live far away.","native":"दूर रहने वाले मेरे परिवार के सदस्यों से बात करने में तकनीक मेरी मदद करती है।"},{"en":"I use my phone to pay bills and learn new things.","native":"मैं बिल भरने और नई चीज़ें सीखने के लिए अपना फ़ोन इस्तेमाल करता हूँ।"},{"en":"Online maps help me find new places easily.","native":"ऑनलाइन नक्शे मुझे आसानी से नई जगहें खोजने में मदद करते हैं।"}]},"es":{"word":"tecnología","question":"¿Cómo te ayuda la tecnología en tu vida diaria?","examples":[{"en":"Technology helps me talk to family members who live far away.","native":"La tecnología me ayuda a hablar con familiares que viven lejos."},{"en":"I use my phone to pay bills and learn new things.","native":"Uso mi teléfono para pagar facturas y aprender cosas nuevas."},{"en":"Online maps help me find new places easily.","native":"Los mapas en línea me ayudan a encontrar lugares nuevos fácilmente."}]},"zh":{"word":"科技","question":"科技如何帮助你的日常生活？","examples":[{"en":"Technology helps me talk to family members who live far away.","native":"科技帮助我与住在远方的家人交流。"},{"en":"I use my phone to pay bills and learn new things.","native":"我用手机支付账单和学习新知识。"},{"en":"Online maps help me find new places easily.","native":"在线地图帮助我轻松找到新地方。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'childhood', 'Talk about a happy memory from your childhood.', '{"te":{"word":"బాల్యం","question":"మీ బాల్యంలోని ఒక సంతోషకరమైన జ్ఞాపకం గురించి మాట్లాడండి.","examples":[{"en":"I remember flying kites on the roof with my relatives.","native":"నా బంధువులతో కలిసి పైకప్పు మీద పతంగులు ఎగరవేసిన విషయం నాకు గుర్తుంది."},{"en":"During holidays, we visited our relatives'' farm.","native":"సెలవుల్లో, మేము మా బంధువుల పొలానికి వెళ్లాము."},{"en":"Those simple days taught me the value of family.","native":"ఆ సాధారణ రోజులు నాకు కుటుంబం విలువను నేర్పాయి."}]},"hi":{"word":"बचपन","question":"अपने बचपन की किसी खुशहाल याद के बारे में बताइए।","examples":[{"en":"I remember flying kites on the roof with my relatives.","native":"मुझे अपने रिश्तेदारों के साथ छत पर पतंग उड़ाना याद है।"},{"en":"During holidays, we visited our relatives'' farm.","native":"छुट्टियों में, हम अपने रिश्तेदारों के खेत जाते थे।"},{"en":"Those simple days taught me the value of family.","native":"उन साधारण दिनों ने मुझे परिवार का महत्व सिखाया।"}]},"es":{"word":"infancia","question":"Habla de un recuerdo feliz de tu infancia.","examples":[{"en":"I remember flying kites on the roof with my relatives.","native":"Recuerdo volar cometas en el tejado con mis familiares."},{"en":"During holidays, we visited our relatives'' farm.","native":"Durante las vacaciones, visitábamos la granja de nuestros familiares."},{"en":"Those simple days taught me the value of family.","native":"Esos días sencillos me enseñaron el valor de la familia."}]},"zh":{"word":"童年","question":"谈谈你童年的一段快乐回忆。","examples":[{"en":"I remember flying kites on the roof with my relatives.","native":"我记得和亲戚们在屋顶上放风筝。"},{"en":"During holidays, we visited our relatives'' farm.","native":"假期里，我们会去亲戚家的农场。"},{"en":"Those simple days taught me the value of family.","native":"那些简单的日子教会了我家庭的价值。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'teamwork', 'Talk about a time you worked in a team. What went well and what was difficult?', '{"te":{"word":"జట్టు కృషి","question":"మీరు జట్టులో పనిచేసిన ఒక సందర్భం గురించి మాట్లాడండి. ఏమి బాగా జరిగింది, ఏమి కష్టంగా ఉంది?","examples":[{"en":"I worked in a team of five people on a college project last year.","native":"గత సంవత్సరం నేను కాలేజీ ప్రాజెక్టులో ఐదుగురితో జట్టులో పనిచేశాను."},{"en":"We finished on time because everyone helped each other.","native":"ప్రతి ఒక్కరు ఒకరికొకరు సహాయం చేసుకున్నందున మేము సమయానికి పూర్తి చేశాము."},{"en":"It was difficult when two members disagreed, but we talked and solved it.","native":"ఇద్దరు సభ్యులు భిన్నాభిప్రాయం పడినప్పుడు కష్టంగా ఉంది, కానీ మేము మాట్లాడి పరిష్కరించుకున్నాము."}]},"hi":{"word":"टीमवर्क","question":"किसी ऐसे समय के बारे में बताइए जब आपने टीम में काम किया। क्या अच्छा हुआ और क्या कठिन था?","examples":[{"en":"I worked in a team of five people on a college project last year.","native":"पिछले साल मैंने एक कॉलेज प्रोजेक्ट में पाँच लोगों की टीम में काम किया।"},{"en":"We finished on time because everyone helped each other.","native":"हम समय पर काम पूरा कर पाए क्योंकि सबने एक-दूसरे की मदद की।"},{"en":"It was difficult when two members disagreed, but we talked and solved it.","native":"जब दो सदस्यों में मतभेद हुआ तो कठिन था, लेकिन हमने बात करके इसे सुलझा लिया।"}]},"es":{"word":"trabajo en equipo","question":"Habla de una ocasión en la que trabajaste en equipo. ¿Qué salió bien y qué fue difícil?","examples":[{"en":"I worked in a team of five people on a college project last year.","native":"El año pasado trabajé en un equipo de cinco personas en un proyecto de la universidad."},{"en":"We finished on time because everyone helped each other.","native":"Terminamos a tiempo porque todos nos ayudamos unos a otros."},{"en":"It was difficult when two members disagreed, but we talked and solved it.","native":"Fue difícil cuando dos miembros no estaban de acuerdo, pero hablamos y lo resolvimos."}]},"zh":{"word":"团队合作","question":"谈谈你曾经在团队中工作的一次经历。什么进展顺利，什么比较困难？","examples":[{"en":"I worked in a team of five people on a college project last year.","native":"去年我在一个大学项目中与五个人组成的团队一起工作。"},{"en":"We finished on time because everyone helped each other.","native":"我们按时完成了，因为每个人都互相帮助。"},{"en":"It was difficult when two members disagreed, but we talked and solved it.","native":"当两名成员意见不合时很困难，但我们通过沟通解决了问题。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'sport', 'What is your favourite sport, and why do you like it?', '{"te":{"word":"క్రీడ","question":"మీకు ఇష్టమైన క్రీడ ఏది, మరియు మీకు అది ఎందుకు నచ్చుతుంది?","examples":[{"en":"My favourite sport is badminton because it is fast and exciting.","native":"నా ఇష్టమైన క్రీడ బ్యాడ్మింటన్, ఎందుకంటే అది వేగంగా మరియు ఉత్కంఠభరితంగా ఉంటుంది."},{"en":"I have played it with my friends every weekend since I was ten.","native":"నేను పది సంవత్సరాల వయస్సు నుండి ప్రతి వారాంతం నా స్నేహితులతో అది ఆడుతున్నాను."},{"en":"Playing sport keeps me fitter than sitting at home.","native":"ఇంట్లో కూర్చోవడం కంటే క్రీడ ఆడటం నన్ను ఎక్కువ ఫిట్‌గా ఉంచుతుంది."}]},"hi":{"word":"खेल","question":"आपका पसंदीदा खेल कौन सा है, और आपको यह क्यों पसंद है?","examples":[{"en":"My favourite sport is badminton because it is fast and exciting.","native":"मेरा पसंदीदा खेल बैडमिंटन है क्योंकि यह तेज़ और रोमांचक है।"},{"en":"I have played it with my friends every weekend since I was ten.","native":"जब से मैं दस साल का था, मैं हर सप्ताह के अंत में अपने दोस्तों के साथ इसे खेलता आया हूँ।"},{"en":"Playing sport keeps me fitter than sitting at home.","native":"घर बैठने की तुलना में खेल खेलना मुझे ज़्यादा तंदुरुस्त रखता है।"}]},"es":{"word":"deporte","question":"¿Cuál es tu deporte favorito y por qué te gusta?","examples":[{"en":"My favourite sport is badminton because it is fast and exciting.","native":"Mi deporte favorito es el bádminton porque es rápido y emocionante."},{"en":"I have played it with my friends every weekend since I was ten.","native":"Juego con mis amigos todos los fines de semana desde que tenía diez años."},{"en":"Playing sport keeps me fitter than sitting at home.","native":"Hacer deporte me mantiene más en forma que quedarme sentado en casa."}]},"zh":{"word":"运动","question":"你最喜欢的运动是什么？你为什么喜欢它？","examples":[{"en":"My favourite sport is badminton because it is fast and exciting.","native":"我最喜欢的运动是羽毛球，因为它又快又刺激。"},{"en":"I have played it with my friends every weekend since I was ten.","native":"从我十岁起，我每个周末都和朋友们打羽毛球。"},{"en":"Playing sport keeps me fitter than sitting at home.","native":"运动比坐在家里让我更健康。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'music', 'What kind of music do you enjoy listening to, and when do you listen to it?', '{"te":{"word":"సంగీతం","question":"మీరు ఏ రకమైన సంగీతం వినడానికి ఇష్టపడతారు, మరియు ఎప్పుడు వింటారు?","examples":[{"en":"I enjoy soft music because it helps me relax after a long day.","native":"నేను మధురమైన సంగీతం ఇష్టపడతాను, ఎందుకంటే అది సుదీర్ఘ రోజు తర్వాత నాకు విశ్రాంతిని ఇస్తుంది."},{"en":"I usually listen to songs while I am travelling on the bus.","native":"నేను సాధారణంగా బస్సులో ప్రయాణిస్తున్నప్పుడు పాటలు వింటాను."},{"en":"Music makes boring work feel shorter and more enjoyable.","native":"సంగీతం విసుగు పనిని తక్కువగా మరియు ఆనందంగా అనిపించేలా చేస్తుంది."}]},"hi":{"word":"संगीत","question":"आप किस तरह का संगीत सुनना पसंद करते हैं, और आप इसे कब सुनते हैं?","examples":[{"en":"I enjoy soft music because it helps me relax after a long day.","native":"मुझे शांत संगीत पसंद है क्योंकि लंबे दिन के बाद इससे मुझे आराम मिलता है।"},{"en":"I usually listen to songs while I am travelling on the bus.","native":"मैं आमतौर पर बस में यात्रा करते समय गाने सुनता हूँ।"},{"en":"Music makes boring work feel shorter and more enjoyable.","native":"संगीत उबाऊ काम को छोटा और ज़्यादा मज़ेदार महसूस कराता है।"}]},"es":{"word":"música","question":"¿Qué tipo de música te gusta escuchar y cuándo la escuchas?","examples":[{"en":"I enjoy soft music because it helps me relax after a long day.","native":"Me gusta la música suave porque me ayuda a relajarme después de un día largo."},{"en":"I usually listen to songs while I am travelling on the bus.","native":"Normalmente escucho canciones mientras viajo en el autobús."},{"en":"Music makes boring work feel shorter and more enjoyable.","native":"La música hace que el trabajo aburrido parezca más corto y agradable."}]},"zh":{"word":"音乐","question":"你喜欢听什么类型的音乐？你什么时候听？","examples":[{"en":"I enjoy soft music because it helps me relax after a long day.","native":"我喜欢轻音乐，因为它能帮助我在漫长的一天后放松。"},{"en":"I usually listen to songs while I am travelling on the bus.","native":"我通常在乘公交车时听歌。"},{"en":"Music makes boring work feel shorter and more enjoyable.","native":"音乐让枯燥的工作感觉更短、更有趣。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'reading', 'Do you like reading books? What kind of books do you prefer?', '{"te":{"word":"చదవడం","question":"మీకు పుస్తకాలు చదవడం ఇష్టమా? మీరు ఏ రకమైన పుస్తకాలను ఇష్టపడతారు?","examples":[{"en":"I prefer story books because they take me to different worlds.","native":"నేను కథా పుస్తకాలను ఇష్టపడతాను, ఎందుకంటే అవి నన్ను వేర్వేరు ప్రపంచాలకు తీసుకువెళ్తాయి."},{"en":"I have read three novels this month, which is more than usual.","native":"ఈ నెల నేను మూడు నవలలు చదివాను, ఇది సాధారణం కంటే ఎక్కువ."},{"en":"Reading before bed is better for me than watching videos.","native":"వీడియోలు చూడటం కంటే పడుకునే ముందు చదవడం నాకు మేలు."}]},"hi":{"word":"पढ़ना","question":"क्या आपको किताबें पढ़ना पसंद है? आप किस तरह की किताबें पसंद करते हैं?","examples":[{"en":"I prefer story books because they take me to different worlds.","native":"मुझे कहानियों वाली किताबें पसंद हैं क्योंकि वे मुझे अलग-अलग दुनिया में ले जाती हैं।"},{"en":"I have read three novels this month, which is more than usual.","native":"इस महीने मैंने तीन उपन्यास पढ़े हैं, जो सामान्य से ज़्यादा है।"},{"en":"Reading before bed is better for me than watching videos.","native":"वीडियो देखने की तुलना में सोने से पहले पढ़ना मेरे लिए बेहतर है।"}]},"es":{"word":"lectura","question":"¿Te gusta leer libros? ¿Qué tipo de libros prefieres?","examples":[{"en":"I prefer story books because they take me to different worlds.","native":"Prefiero los libros de historias porque me llevan a mundos diferentes."},{"en":"I have read three novels this month, which is more than usual.","native":"He leído tres novelas este mes, más de lo habitual."},{"en":"Reading before bed is better for me than watching videos.","native":"Leer antes de dormir es mejor para mí que ver vídeos."}]},"zh":{"word":"阅读","question":"你喜欢读书吗？你更喜欢哪类书？","examples":[{"en":"I prefer story books because they take me to different worlds.","native":"我更喜欢故事书，因为它们带我去不同的世界。"},{"en":"I have read three novels this month, which is more than usual.","native":"这个月我读了三本小说，比平时多。"},{"en":"Reading before bed is better for me than watching videos.","native":"对我来说，睡前读书比看视频更好。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'social media', 'How do you use social media, and do you think it is good or bad for young people?', '{"te":{"word":"సోషల్ మీడియా","question":"మీరు సోషల్ మీడియాను ఎలా వాడతారు, మరియు అది యువతకు మంచిదా కాదా అని మీరు అనుకుంటున్నారు?","examples":[{"en":"I use social media to share photos and talk with my friends.","native":"ఫోటోలు పంచుకోవడానికి మరియు నా స్నేహితులతో మాట్లాడటానికి నేను సోషల్ మీడియా వాడతాను."},{"en":"It is useful, but spending too much time on it is a problem.","native":"అది ఉపయోగకరమే, కానీ దానిపై ఎక్కువ సమయం గడపడం ఒక సమస్య."},{"en":"I have stopped checking my phone first thing in the morning.","native":"ఉదయం లేచిన వెంటనే ఫోన్ చూడటం నేను ఆపేశాను."}]},"hi":{"word":"सोशल मीडिया","question":"आप सोशल मीडिया का इस्तेमाल कैसे करते हैं, और क्या आपको लगता है कि यह युवाओं के लिए अच्छा है या बुरा?","examples":[{"en":"I use social media to share photos and talk with my friends.","native":"मैं तस्वीरें साझा करने और दोस्तों से बात करने के लिए सोशल मीडिया का इस्तेमाल करता हूँ।"},{"en":"It is useful, but spending too much time on it is a problem.","native":"यह उपयोगी है, लेकिन इस पर बहुत ज़्यादा समय बिताना एक समस्या है।"},{"en":"I have stopped checking my phone first thing in the morning.","native":"मैंने सुबह उठते ही सबसे पहले फ़ोन देखना बंद कर दिया है।"}]},"es":{"word":"redes sociales","question":"¿Cómo usas las redes sociales y crees que son buenas o malas para los jóvenes?","examples":[{"en":"I use social media to share photos and talk with my friends.","native":"Uso las redes sociales para compartir fotos y hablar con mis amigos."},{"en":"It is useful, but spending too much time on it is a problem.","native":"Son útiles, pero pasar demasiado tiempo en ellas es un problema."},{"en":"I have stopped checking my phone first thing in the morning.","native":"He dejado de mirar el teléfono nada más despertarme por la mañana."}]},"zh":{"word":"社交媒体","question":"你如何使用社交媒体？你认为它对年轻人是好还是坏？","examples":[{"en":"I use social media to share photos and talk with my friends.","native":"我用社交媒体分享照片并与朋友聊天。"},{"en":"It is useful, but spending too much time on it is a problem.","native":"它很有用，但花太多时间在上面是个问题。"},{"en":"I have stopped checking my phone first thing in the morning.","native":"我已经不再早上一醒来就看手机了。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'money', 'How do you manage your money, and what do you like to spend it on?', '{"te":{"word":"డబ్బు","question":"మీరు మీ డబ్బును ఎలా నిర్వహిస్తారు, మరియు దానిని దేనిపై ఖర్చు చేయడానికి ఇష్టపడతారు?","examples":[{"en":"I save some money every month because I want to buy a laptop.","native":"నేను ల్యాప్‌టాప్ కొనాలనుకుంటున్నాను కాబట్టి ప్రతి నెల కొంత డబ్బు ఆదా చేస్తాను."},{"en":"I spend more on books than on clothes these days.","native":"ఈ రోజుల్లో నేను దుస్తుల కంటే పుస్తకాలపై ఎక్కువ ఖర్చు చేస్తాను."},{"en":"When I plan my budget, I never worry at the end of the month.","native":"నేను నా బడ్జెట్ ప్లాన్ చేసుకున్నప్పుడు, నెల చివరిలో ఎప్పుడూ టెన్షన్ పడను."}]},"hi":{"word":"पैसा","question":"आप अपने पैसे का प्रबंधन कैसे करते हैं, और आप इसे किस पर खर्च करना पसंद करते हैं?","examples":[{"en":"I save some money every month because I want to buy a laptop.","native":"मैं हर महीने कुछ पैसे बचाता हूँ क्योंकि मैं एक लैपटॉप खरीदना चाहता हूँ।"},{"en":"I spend more on books than on clothes these days.","native":"इन दिनों मैं कपड़ों से ज़्यादा किताबों पर खर्च करता हूँ।"},{"en":"When I plan my budget, I never worry at the end of the month.","native":"जब मैं अपना बजट बनाता हूँ, तो महीने के अंत में कभी चिंता नहीं करता।"}]},"es":{"word":"dinero","question":"¿Cómo administras tu dinero y en qué te gusta gastarlo?","examples":[{"en":"I save some money every month because I want to buy a laptop.","native":"Ahorro algo de dinero cada mes porque quiero comprar un portátil."},{"en":"I spend more on books than on clothes these days.","native":"Últimamente gasto más en libros que en ropa."},{"en":"When I plan my budget, I never worry at the end of the month.","native":"Cuando planifico mi presupuesto, nunca me preocupo a fin de mes."}]},"zh":{"word":"金钱","question":"你如何管理自己的钱？你喜欢把钱花在什么上？","examples":[{"en":"I save some money every month because I want to buy a laptop.","native":"我每个月存一些钱，因为我想买一台笔记本电脑。"},{"en":"I spend more on books than on clothes these days.","native":"这些天我在书上花的钱比在衣服上多。"},{"en":"When I plan my budget, I never worry at the end of the month.","native":"当我做好预算时，月底就从不发愁。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'friendship', 'What makes a good friend, and how do you keep your friendships strong?', '{"te":{"word":"స్నేహం","question":"మంచి స్నేహితుడికి ఏ లక్షణాలు ఉండాలి, మరియు మీరు మీ స్నేహాలను ఎలా బలంగా ఉంచుతారు?","examples":[{"en":"A good friend listens when you have a problem and never judges you.","native":"మీకు సమస్య ఉన్నప్పుడు విని, ఎప్పుడూ తీర్పు చెప్పని వ్యక్తే మంచి స్నేహితుడు."},{"en":"I have known my best friend since we were in school together.","native":"మేము ఇద్దరం స్కూల్లో చదువుతున్నప్పటి నుండి నా పక్కా స్నేహితుడికి నాకు పరిచయం."},{"en":"We meet every week because friendship needs time and care.","native":"మేము ప్రతి వారం కలుస్తాము, ఎందుకంటే స్నేహానికి సమయం మరియు శ్రద్ధ అవసరం."}]},"hi":{"word":"दोस्ती","question":"एक अच्छे दोस्त में क्या खूबियाँ होती हैं, और आप अपनी दोस्ती को कैसे मज़बूत रखते हैं?","examples":[{"en":"A good friend listens when you have a problem and never judges you.","native":"अच्छा दोस्त वही है जो आपकी परेशानी में आपकी बात सुने और कभी आपको आँके नहीं।"},{"en":"I have known my best friend since we were in school together.","native":"मैं अपने सबसे अच्छे दोस्त को तब से जानता हूँ जब से हम साथ स्कूल में थे।"},{"en":"We meet every week because friendship needs time and care.","native":"हम हर हफ़्ते मिलते हैं क्योंकि दोस्ती को समय और देखभाल चाहिए।"}]},"es":{"word":"amistad","question":"¿Qué hace a un buen amigo y cómo mantienes fuertes tus amistades?","examples":[{"en":"A good friend listens when you have a problem and never judges you.","native":"Un buen amigo te escucha cuando tienes un problema y nunca te juzga."},{"en":"I have known my best friend since we were in school together.","native":"Conozco a mi mejor amigo desde que estábamos juntos en el colegio."},{"en":"We meet every week because friendship needs time and care.","native":"Nos vemos cada semana porque la amistad necesita tiempo y cuidado."}]},"zh":{"word":"友谊","question":"什么样的朋友才是好朋友？你如何维系友谊？","examples":[{"en":"A good friend listens when you have a problem and never judges you.","native":"好朋友会在你遇到困难时倾听，而且从不评判你。"},{"en":"I have known my best friend since we were in school together.","native":"我和我最好的朋友从一起上学时就认识了。"},{"en":"We meet every week because friendship needs time and care.","native":"我们每周都见面，因为友谊需要时间和用心。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'cooking', 'Do you enjoy cooking? Describe a dish you can make well.', '{"te":{"word":"వంట","question":"మీకు వంట చేయడం ఇష్టమా? మీరు బాగా చేయగల ఒక వంటకాన్ని వివరించండి.","examples":[{"en":"I enjoy cooking because it relaxes me after work.","native":"నాకు వంట చేయడం ఇష్టం, ఎందుకంటే పని తర్వాత అది నాకు ఉపశమనం ఇస్తుంది."},{"en":"I can make vegetable rice, and my family says it tastes wonderful.","native":"నేను వెజిటబుల్ రైస్ చేయగలను, నా కుటుంబం దాని రుచి అద్భుతంగా ఉందని అంటుంది."},{"en":"Cooking at home is cheaper and healthier than eating outside.","native":"బయట తినడం కంటే ఇంట్లో వంట చేసుకోవడం చౌకగా మరియు ఆరోగ్యంగా ఉంటుంది."}]},"hi":{"word":"खाना बनाना","question":"क्या आपको खाना बनाना पसंद है? किसी ऐसे व्यंजन का वर्णन कीजिए जो आप अच्छा बना लेते हैं।","examples":[{"en":"I enjoy cooking because it relaxes me after work.","native":"मुझे खाना बनाना पसंद है क्योंकि काम के बाद इससे मुझे सुकून मिलता है।"},{"en":"I can make vegetable rice, and my family says it tastes wonderful.","native":"मैं वेजिटेबल राइस बना लेता हूँ, और मेरा परिवार कहता है कि इसका स्वाद बहुत अच्छा है।"},{"en":"Cooking at home is cheaper and healthier than eating outside.","native":"बाहर खाने की तुलना में घर पर खाना बनाना सस्ता और सेहतमंद है।"}]},"es":{"word":"cocinar","question":"¿Te gusta cocinar? Describe un plato que preparas bien.","examples":[{"en":"I enjoy cooking because it relaxes me after work.","native":"Me gusta cocinar porque me relaja después del trabajo."},{"en":"I can make vegetable rice, and my family says it tastes wonderful.","native":"Sé preparar arroz con verduras, y mi familia dice que está delicioso."},{"en":"Cooking at home is cheaper and healthier than eating outside.","native":"Cocinar en casa es más barato y más sano que comer fuera."}]},"zh":{"word":"烹饪","question":"你喜欢做饭吗？描述一道你做得好的菜。","examples":[{"en":"I enjoy cooking because it relaxes me after work.","native":"我喜欢做饭，因为下班后做饭能让我放松。"},{"en":"I can make vegetable rice, and my family says it tastes wonderful.","native":"我会做蔬菜炒饭，我家人说味道很棒。"},{"en":"Cooking at home is cheaper and healthier than eating outside.","native":"在家做饭比在外面吃更便宜、更健康。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'exam', 'How do you prepare for exams, and how do you feel before them?', '{"te":{"word":"పరీక్ష","question":"మీరు పరీక్షలకు ఎలా సిద్ధమవుతారు, మరియు వాటికి ముందు మీకు ఎలా అనిపిస్తుంది?","examples":[{"en":"I make a study plan two weeks before every exam because it keeps me calm.","native":"ప్రతి పరీక్షకు రెండు వారాల ముందు నేను స్టడీ ప్లాన్ తయారు చేస్తాను, ఎందుకంటే అది నన్ను ప్రశాంతంగా ఉంచుతుంది."},{"en":"I feel nervous before exams, but breathing slowly helps me relax.","native":"పరీక్షల ముందు నాకు టెన్షన్‌గా అనిపిస్తుంది, కానీ నెమ్మదిగా ఊపిరి పీల్చుకోవడం నాకు రిలాక్స్ అవ్వడానికి సహాయపడుతుంది."},{"en":"Studying with friends is more fun than studying alone.","native":"ఒంటరిగా చదవడం కంటే స్నేహితులతో చదవడం ఎక్కువ సరదాగా ఉంటుంది."}]},"hi":{"word":"परीक्षा","question":"आप परीक्षाओं की तैयारी कैसे करते हैं, और उनसे पहले आप कैसा महसूस करते हैं?","examples":[{"en":"I make a study plan two weeks before every exam because it keeps me calm.","native":"मैं हर परीक्षा से दो हफ़्ते पहले पढ़ने की योजना बनाता हूँ क्योंकि इससे मैं शांत रहता हूँ।"},{"en":"I feel nervous before exams, but breathing slowly helps me relax.","native":"परीक्षा से पहले मैं घबरा जाता हूँ, लेकिन धीरे-धीरे साँस लेने से मुझे आराम मिलता है।"},{"en":"Studying with friends is more fun than studying alone.","native":"अकेले पढ़ने की तुलना में दोस्तों के साथ पढ़ना ज़्यादा मज़ेदार है।"}]},"es":{"word":"examen","question":"¿Cómo te preparas para los exámenes y cómo te sientes antes de ellos?","examples":[{"en":"I make a study plan two weeks before every exam because it keeps me calm.","native":"Hago un plan de estudio dos semanas antes de cada examen porque me mantiene tranquilo."},{"en":"I feel nervous before exams, but breathing slowly helps me relax.","native":"Me pongo nervioso antes de los exámenes, pero respirar despacio me ayuda a relajarme."},{"en":"Studying with friends is more fun than studying alone.","native":"Estudiar con amigos es más divertido que estudiar solo."}]},"zh":{"word":"考试","question":"你如何准备考试？考试前你感觉如何？","examples":[{"en":"I make a study plan two weeks before every exam because it keeps me calm.","native":"我会在每次考试前两周制定学习计划，因为这能让我保持冷静。"},{"en":"I feel nervous before exams, but breathing slowly helps me relax.","native":"考试前我会紧张，但慢慢呼吸能帮助我放松。"},{"en":"Studying with friends is more fun than studying alone.","native":"和朋友一起学习比独自学习更有趣。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'volunteering', 'Have you ever done volunteer work? Why do you think people volunteer?', '{"te":{"word":"స్వచ్ఛంద సేవ","question":"మీరు ఎప్పుడైనా స్వచ్ఛంద సేవ చేశారా? ప్రజలు ఎందుకు స్వచ్ఛందంగా సేవ చేస్తారని మీరు అనుకుంటున్నారు?","examples":[{"en":"I volunteered at an animal shelter last summer, and I loved it.","native":"గత వేసవిలో నేను ఒక జంతు ఆశ్రమంలో స్వచ్ఛంద సేవ చేశాను, నాకు అది చాలా నచ్చింది."},{"en":"People volunteer because they want to help others and learn new skills.","native":"ఇతరులకు సహాయం చేయాలని మరియు కొత్త నైపుణ్యాలు నేర్చుకోవాలని ప్రజలు స్వచ్ఛంద సేవ చేస్తారు."},{"en":"Helping others has made me happier than buying new things.","native":"కొత్త వస్తువులు కొనడం కంటే ఇతరులకు సహాయం చేయడం నన్ను ఎక్కువ సంతోషపెట్టింది."}]},"hi":{"word":"स्वयंसेवा","question":"क्या आपने कभी स्वयंसेवक का काम किया है? आपके अनुसार लोग स्वयंसेवा क्यों करते हैं?","examples":[{"en":"I volunteered at an animal shelter last summer, and I loved it.","native":"पिछली गर्मियों में मैंने एक पशु आश्रय स्थल में स्वयंसेवा की, और मुझे यह बहुत पसंद आया।"},{"en":"People volunteer because they want to help others and learn new skills.","native":"लोग स्वयंसेवा करते हैं क्योंकि वे दूसरों की मदद करना और नए कौशल सीखना चाहते हैं।"},{"en":"Helping others has made me happier than buying new things.","native":"नई चीज़ें खरीदने की तुलना में दूसरों की मदद करना मुझे ज़्यादा खुश करता है।"}]},"es":{"word":"voluntariado","question":"¿Has hecho alguna vez trabajo voluntario? ¿Por qué crees que la gente hace voluntariado?","examples":[{"en":"I volunteered at an animal shelter last summer, and I loved it.","native":"Hice voluntariado en un refugio de animales el verano pasado y me encantó."},{"en":"People volunteer because they want to help others and learn new skills.","native":"La gente hace voluntariado porque quiere ayudar a los demás y aprender nuevas habilidades."},{"en":"Helping others has made me happier than buying new things.","native":"Ayudar a los demás me ha hecho más feliz que comprar cosas nuevas."}]},"zh":{"word":"志愿服务","question":"你做过志愿工作吗？你认为人们为什么做志愿者？","examples":[{"en":"I volunteered at an animal shelter last summer, and I loved it.","native":"去年夏天我在一个动物收容所做志愿者，我非常喜欢。"},{"en":"People volunteer because they want to help others and learn new skills.","native":"人们做志愿者是因为他们想帮助别人并学习新技能。"},{"en":"Helping others has made me happier than buying new things.","native":"帮助别人比买新东西让我更快乐。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'fitness', 'What do you do to keep fit, and how often do you exercise?', '{"te":{"word":"శారీరక దృఢత్వం","question":"ఫిట్‌గా ఉండటానికి మీరు ఏమి చేస్తారు, మరియు ఎంత తరచుగా వ్యాయామం చేస్తారు?","examples":[{"en":"I go jogging three times a week because it gives me energy.","native":"వారానికి మూడుసార్లు జాగింగ్ చేస్తాను, ఎందుకంటే అది నాకు శక్తిని ఇస్తుంది."},{"en":"Walking to work is easier for me than going to a gym.","native":"జిమ్‌కు వెళ్లడం కంటే పనికి నడచి వెళ్లడం నాకు సులభం."},{"en":"Since I started exercising, I have slept much better at night.","native":"నేను వ్యాయామం ప్రారంభించినప్పటి నుండి, రాత్రి చాలా బాగా నిద్రపోతున్నాను."}]},"hi":{"word":"फ़िटनेस","question":"फ़िट रहने के लिए आप क्या करते हैं, और आप कितनी बार व्यायाम करते हैं?","examples":[{"en":"I go jogging three times a week because it gives me energy.","native":"मैं हफ़्ते में तीन बार जॉगिंग करता हूँ क्योंकि इससे मुझे ऊर्जा मिलती है।"},{"en":"Walking to work is easier for me than going to a gym.","native":"जिम जाने की तुलना में पैदल काम पर जाना मेरे लिए आसान है।"},{"en":"Since I started exercising, I have slept much better at night.","native":"जब से मैंने व्यायाम शुरू किया है, मैं रात में काफ़ी बेहतर नींद ले रहा हूँ।"}]},"es":{"word":"forma física","question":"¿Qué haces para mantenerte en forma y con qué frecuencia haces ejercicio?","examples":[{"en":"I go jogging three times a week because it gives me energy.","native":"Salgo a correr tres veces por semana porque me da energía."},{"en":"Walking to work is easier for me than going to a gym.","native":"Ir caminando al trabajo me resulta más fácil que ir al gimnasio."},{"en":"Since I started exercising, I have slept much better at night.","native":"Desde que empecé a hacer ejercicio, duermo mucho mejor por la noche."}]},"zh":{"word":"健身","question":"你做什么来保持健康体态？你多久锻炼一次？","examples":[{"en":"I go jogging three times a week because it gives me energy.","native":"我每周慢跑三次，因为这让我精力充沛。"},{"en":"Walking to work is easier for me than going to a gym.","native":"对我来说，走路去上班比去健身房更容易坚持。"},{"en":"Since I started exercising, I have slept much better at night.","native":"自从开始锻炼以来，我晚上睡得好多了。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'dream', 'What is your dream for the future, and what are you doing to achieve it?', '{"te":{"word":"కల","question":"మీ భవిష్యత్తు కల ఏమిటి, మరియు దానిని సాధించడానికి మీరు ఏమి చేస్తున్నారు?","examples":[{"en":"My dream is to become a nurse because I want to care for people.","native":"నా కల నర్సు అవ్వడం, ఎందుకంటే నేను ప్రజలను చూసుకోవాలనుకుంటున్నాను."},{"en":"I study hard every day so that I can pass the entrance test.","native":"ప్రవేశ పరీక్ష ఉత్తీర్ణత పొందడానికి నేను ప్రతిరోజూ కష్టపడి చదువుతున్నాను."},{"en":"Dreams are important, but hard work makes them real.","native":"కలలు ముఖ్యమే, కానీ కష్టపడి పనిచేస్తేనే అవి నిజమవుతాయి."}]},"hi":{"word":"सपना","question":"भविष्य के लिए आपका सपना क्या है, और उसे पाने के लिए आप क्या कर रहे हैं?","examples":[{"en":"My dream is to become a nurse because I want to care for people.","native":"मेरा सपना नर्स बनना है क्योंकि मैं लोगों की देखभाल करना चाहता हूँ।"},{"en":"I study hard every day so that I can pass the entrance test.","native":"मैं हर दिन मेहनत से पढ़ता हूँ ताकि प्रवेश परीक्षा पास कर सकूँ।"},{"en":"Dreams are important, but hard work makes them real.","native":"सपने ज़रूरी हैं, लेकिन कड़ी मेहनत ही उन्हें सच बनाती है।"}]},"es":{"word":"sueño","question":"¿Cuál es tu sueño para el futuro y qué estás haciendo para lograrlo?","examples":[{"en":"My dream is to become a nurse because I want to care for people.","native":"Mi sueño es ser enfermera porque quiero cuidar a la gente."},{"en":"I study hard every day so that I can pass the entrance test.","native":"Estudio mucho todos los días para poder aprobar el examen de acceso."},{"en":"Dreams are important, but hard work makes them real.","native":"Los sueños son importantes, pero el trabajo duro los hace realidad."}]},"zh":{"word":"梦想","question":"你对未来的梦想是什么？你正在为实现它做什么？","examples":[{"en":"My dream is to become a nurse because I want to care for people.","native":"我的梦想是成为一名护士，因为我想照顾别人。"},{"en":"I study hard every day so that I can pass the entrance test.","native":"我每天努力学习，以便通过入学考试。"},{"en":"Dreams are important, but hard work makes them real.","native":"梦想很重要，但只有努力才能让它们成真。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'gift', 'Describe a special gift you have given or received.', '{"te":{"word":"బహుమతి","question":"మీరు ఇచ్చిన లేదా అందుకున్న ఒక ప్రత్యేకమైన బహుమతిని వివరించండి.","examples":[{"en":"The best gift I have received is a watch from my grandfather.","native":"నేను అందుకున్న అత్యుత్తమ బహుమతి నా తాతయ్య ఇచ్చిన వాచ్."},{"en":"I gave my mother a handmade card because she loves personal gifts.","native":"నా అమ్మకు నేను చేతితో తయారుచేసిన కార్డ్ ఇచ్చాను, ఎందుకంటే ఆమెకు వ్యక్తిగత బహుమతులు ఇష్టం."},{"en":"A thoughtful gift is more valuable than an expensive one.","native":"ఖరీదైన బహుమతి కంటే ఆలోచనతో ఇచ్చే బహుమతి ఎక్కువ విలువైనది."}]},"hi":{"word":"उपहार","question":"किसी खास उपहार का वर्णन कीजिए जो आपने दिया हो या पाया हो।","examples":[{"en":"The best gift I have received is a watch from my grandfather.","native":"मुझे मिला सबसे अच्छा उपहार मेरे दादाजी की ओर से एक घड़ी है।"},{"en":"I gave my mother a handmade card because she loves personal gifts.","native":"मैंने अपनी माँ को हाथ से बना कार्ड दिया क्योंकि उन्हें निजी उपहार पसंद हैं।"},{"en":"A thoughtful gift is more valuable than an expensive one.","native":"महँगे उपहार से ज़्यादा कीमती होता है सोच-समझकर दिया गया उपहार।"}]},"es":{"word":"regalo","question":"Describe un regalo especial que hayas dado o recibido.","examples":[{"en":"The best gift I have received is a watch from my grandfather.","native":"El mejor regalo que he recibido es un reloj de mi abuelo."},{"en":"I gave my mother a handmade card because she loves personal gifts.","native":"Le regalé a mi madre una tarjeta hecha a mano porque le encantan los regalos personales."},{"en":"A thoughtful gift is more valuable than an expensive one.","native":"Un regalo pensado es más valioso que uno caro."}]},"zh":{"word":"礼物","question":"描述一份你送出或收到的特别礼物。","examples":[{"en":"The best gift I have received is a watch from my grandfather.","native":"我收到过最好的礼物是祖父送我的一块手表。"},{"en":"I gave my mother a handmade card because she loves personal gifts.","native":"我送给妈妈一张手工制作的卡片，因为她喜欢有心意的礼物。"},{"en":"A thoughtful gift is more valuable than an expensive one.","native":"用心的礼物比昂贵的礼物更有价值。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'transport', 'How do you usually travel around your town or city, and what do you think of public transport?', '{"te":{"word":"రవాణా","question":"మీరు మీ పట్టణం లేదా నగరంలో సాధారణంగా ఎలా ప్రయాణిస్తారు, మరియు ప్రజా రవాణా గురించి మీ అభిప్రాయం ఏమిటి?","examples":[{"en":"I usually take the metro because it is faster than the bus.","native":"నేను సాధారణంగా మెట్రో తీసుకుంటాను, ఎందుకంటే అది బస్సు కంటే వేగంగా ఉంటుంది."},{"en":"Public transport in my city is cheap, but it is often crowded.","native":"నా నగరంలో ప్రజా రవాణా చౌకగా ఉంటుంది, కానీ తరచుగా రద్దీగా ఉంటుంది."},{"en":"I have recently started cycling to work to save money.","native":"డబ్బు ఆదా చేయడానికి నేను ఇటీవల పనికి సైకిల్ తొక్కడం ప్రారంభించాను."}]},"hi":{"word":"परिवहन","question":"आप अपने शहर या कस्बे में आमतौर पर कैसे घूमते हैं, और सार्वजनिक परिवहन के बारे में आपकी क्या राय है?","examples":[{"en":"I usually take the metro because it is faster than the bus.","native":"मैं आमतौर पर मेट्रो लेता हूँ क्योंकि यह बस से तेज़ है।"},{"en":"Public transport in my city is cheap, but it is often crowded.","native":"मेरे शहर में सार्वजनिक परिवहन सस्ता है, लेकिन अक्सर भीड़भाड़ रहती है।"},{"en":"I have recently started cycling to work to save money.","native":"पैसे बचाने के लिए मैंने हाल ही में काम पर साइकिल से जाना शुरू किया है।"}]},"es":{"word":"transporte","question":"¿Cómo sueles desplazarte por tu pueblo o ciudad y qué opinas del transporte público?","examples":[{"en":"I usually take the metro because it is faster than the bus.","native":"Normalmente cojo el metro porque es más rápido que el autobús."},{"en":"Public transport in my city is cheap, but it is often crowded.","native":"El transporte público de mi ciudad es barato, pero a menudo va lleno."},{"en":"I have recently started cycling to work to save money.","native":"Hace poco empecé a ir al trabajo en bicicleta para ahorrar dinero."}]},"zh":{"word":"交通","question":"你通常如何在城镇或城市里出行？你对公共交通有什么看法？","examples":[{"en":"I usually take the metro because it is faster than the bus.","native":"我通常坐地铁，因为它比公交车快。"},{"en":"Public transport in my city is cheap, but it is often crowded.","native":"我所在城市的公共交通很便宜，但经常很拥挤。"},{"en":"I have recently started cycling to work to save money.","native":"为了省钱，我最近开始骑自行车上班。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'fashion', 'Do you follow fashion trends? How important are clothes to you?', '{"te":{"word":"ఫ్యాషన్","question":"మీరు ఫ్యాషన్ ట్రెండ్‌లను అనుసరిస్తారా? మీకు దుస్తులు ఎంత ముఖ్యం?","examples":[{"en":"I do not follow fashion closely because comfort is more important to me.","native":"నేను ఫ్యాషన్‌ను దగ్గరగా అనుసరించను, ఎందుకంటే నాకు సౌకర్యం ఎక్కువ ముఖ్యం."},{"en":"My sister buys new clothes every month, but I prefer simple styles.","native":"నా సోదరి ప్రతి నెల కొత్త దుస్తులు కొంటుంది, కానీ నాకు సాధారణ శైలులు ఇష్టం."},{"en":"Fashion changes quickly, so I buy clothes that last longer.","native":"ఫ్యాషన్ త్వరగా మారుతుంది, కాబట్టి నేను ఎక్కువ కాలం ఉండే దుస్తులు కొంటాను."}]},"hi":{"word":"फ़ैशन","question":"क्या आप फ़ैशन के रुझानों का पालन करते हैं? कपड़े आपके लिए कितने ज़रूरी हैं?","examples":[{"en":"I do not follow fashion closely because comfort is more important to me.","native":"मैं फ़ैशन का बारीकी से पालन नहीं करता क्योंकि मेरे लिए आराम ज़्यादा ज़रूरी है।"},{"en":"My sister buys new clothes every month, but I prefer simple styles.","native":"मेरी बहन हर महीने नए कपड़े खरीदती है, लेकिन मुझे सादगी भरे कपड़े पसंद हैं।"},{"en":"Fashion changes quickly, so I buy clothes that last longer.","native":"फ़ैशन जल्दी बदलता है, इसलिए मैं ऐसे कपड़े खरीदता हूँ जो लंबे समय तक चलें।"}]},"es":{"word":"moda","question":"¿Sigues las tendencias de la moda? ¿Qué importancia tiene la ropa para ti?","examples":[{"en":"I do not follow fashion closely because comfort is more important to me.","native":"No sigo mucho la moda porque la comodidad es más importante para mí."},{"en":"My sister buys new clothes every month, but I prefer simple styles.","native":"Mi hermana compra ropa nueva cada mes, pero yo prefiero los estilos sencillos."},{"en":"Fashion changes quickly, so I buy clothes that last longer.","native":"La moda cambia rápido, así que compro ropa que dura más."}]},"zh":{"word":"时尚","question":"你关注时尚潮流吗？衣服对你有多重要？","examples":[{"en":"I do not follow fashion closely because comfort is more important to me.","native":"我不太追随时尚，因为舒适对我更重要。"},{"en":"My sister buys new clothes every month, but I prefer simple styles.","native":"我姐姐每个月都买新衣服，但我更喜欢简单的风格。"},{"en":"Fashion changes quickly, so I buy clothes that last longer.","native":"时尚变化很快，所以我买耐穿的衣服。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'holiday', 'Describe a memorable holiday you have had. Where did you go and what did you do?', '{"te":{"word":"సెలవు","question":"మీకు జ్ఞాపకంగా ఉన్న ఒక సెలవును వివరించండి. మీరు ఎక్కడికి వెళ్లారు మరియు ఏమి చేశారు?","examples":[{"en":"Last year, my family and I went to a small village near the sea.","native":"గత సంవత్సరం, నా కుటుంబం మరియు నేను సముద్రం దగ్గర ఉన్న ఒక చిన్న గ్రామానికి వెళ్లాము."},{"en":"We swam every morning and ate fresh fish in the evening.","native":"మేము ప్రతి ఉదయం ఈత కొట్టాము మరియు సాయంత్రం తాజా చేపలు తిన్నాము."},{"en":"It was the most relaxing holiday I have ever had.","native":"ఇది నేను ఇప్పటివరకు గడిపిన అత్యంత ప్రశాంతమైన సెలవు."}]},"hi":{"word":"छुट्टी","question":"अपनी किसी यादगार छुट्टी का वर्णन कीजिए। आप कहाँ गए थे और आपने क्या किया?","examples":[{"en":"Last year, my family and I went to a small village near the sea.","native":"पिछले साल, मैं और मेरा परिवार समुद्र के पास एक छोटे से गाँव गए।"},{"en":"We swam every morning and ate fresh fish in the evening.","native":"हम हर सुबह तैरते थे और शाम को ताज़ी मछली खाते थे।"},{"en":"It was the most relaxing holiday I have ever had.","native":"यह मेरी अब तक की सबसे आरामदायक छुट्टी थी।"}]},"es":{"word":"vacaciones","question":"Describe unas vacaciones memorables que hayas tenido. ¿Adónde fuiste y qué hiciste?","examples":[{"en":"Last year, my family and I went to a small village near the sea.","native":"El año pasado, mi familia y yo fuimos a un pueblo pequeño cerca del mar."},{"en":"We swam every morning and ate fresh fish in the evening.","native":"Nadábamos cada mañana y comíamos pescado fresco por la noche."},{"en":"It was the most relaxing holiday I have ever had.","native":"Fueron las vacaciones más relajantes que he tenido nunca."}]},"zh":{"word":"假期","question":"描述一次难忘的假期。你去了哪里，做了什么？","examples":[{"en":"Last year, my family and I went to a small village near the sea.","native":"去年，我和家人去了海边的一个小村庄。"},{"en":"We swam every morning and ate fresh fish in the evening.","native":"我们每天早上去游泳，晚上吃新鲜的鱼。"},{"en":"It was the most relaxing holiday I have ever had.","native":"那是我度过最放松的一次假期。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'pet', 'Do you have a pet, or would you like to have one? Why or why not?', '{"te":{"word":"పెంపుడు జంతువు","question":"మీ దగ్గర పెంపుడు జంతువు ఉందా, లేదా పెంచుకోవాలనుకుంటున్నారా? ఎందుకు లేదా ఎందుకు కాదు?","examples":[{"en":"I have a small dog that follows me everywhere in the house.","native":"నా దగ్గర ఒక చిన్న కుక్క ఉంది, అది ఇంట్లో ప్రతిచోటా నా వెంట వస్తుంది."},{"en":"Pets are wonderful friends, but they need a lot of care.","native":"పెంపుడు జంతువులు అద్భుతమైన స్నేహితులు, కానీ వాటికి చాలా శ్రద్ధ అవసరం."},{"en":"Playing with my dog makes me forget a stressful day.","native":"నా కుక్కతో ఆడటం వల్ల ఒత్తిడితో కూడిన రోజును మర్చిపోతాను."}]},"hi":{"word":"पालतू जानवर","question":"क्या आपके पास कोई पालतू जानवर है, या आप एक रखना चाहेंगे? क्यों या क्यों नहीं?","examples":[{"en":"I have a small dog that follows me everywhere in the house.","native":"मेरे पास एक छोटा कुत्ता है जो घर में हर जगह मेरे पीछे चलता है।"},{"en":"Pets are wonderful friends, but they need a lot of care.","native":"पालतू जानवर अद्भुत दोस्त होते हैं, लेकिन उन्हें बहुत देखभाल चाहिए।"},{"en":"Playing with my dog makes me forget a stressful day.","native":"अपने कुत्ते के साथ खेलने से मैं तनाव भरा दिन भूल जाता हूँ।"}]},"es":{"word":"mascota","question":"¿Tienes una mascota o te gustaría tener una? ¿Por qué sí o por qué no?","examples":[{"en":"I have a small dog that follows me everywhere in the house.","native":"Tengo un perro pequeño que me sigue por toda la casa."},{"en":"Pets are wonderful friends, but they need a lot of care.","native":"Las mascotas son amigos maravillosos, pero necesitan mucho cuidado."},{"en":"Playing with my dog makes me forget a stressful day.","native":"Jugar con mi perro me hace olvidar un día estresante."}]},"zh":{"word":"宠物","question":"你有宠物吗，或者你想养一只吗？为什么？","examples":[{"en":"I have a small dog that follows me everywhere in the house.","native":"我有一只小狗，它在屋子里到处跟着我。"},{"en":"Pets are wonderful friends, but they need a lot of care.","native":"宠物是很好的朋友，但它们需要很多照顾。"},{"en":"Playing with my dog makes me forget a stressful day.","native":"和我的狗玩耍让我忘记有压力的一天。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'teacher', 'Describe a teacher who has influenced you. What did you learn from them?', '{"te":{"word":"ఉపాధ్యాయుడు","question":"మిమ్మల్ని ప్రభావితం చేసిన ఒక ఉపాధ్యాయుణ్ణి వివరించండి. వారి నుండి మీరు ఏమి నేర్చుకున్నారు?","examples":[{"en":"My English teacher in school always encouraged me to speak without fear.","native":"స్కూల్లో నా ఇంగ్లీష్ టీచరు భయం లేకుండా మాట్లాడమని ఎల్లప్పుడూ నన్ను ప్రోత్సహించారు."},{"en":"She explained difficult ideas with simple stories, which I still remember.","native":"ఆమె కష్టమైన భావనలను సాధారణ కథలతో వివరించేది, అవి నాకు ఇప్పటికీ గుర్తున్నాయి."},{"en":"Because of her, I have become more confident in front of people.","native":"ఆమె వల్ల, నేను ప్రజల ముందు మరింత ఆత్మవిశ్వాసంతో మారాను."}]},"hi":{"word":"शिक्षक","question":"किसी ऐसे शिक्षक का वर्णन कीजिए जिन्होंने आपको प्रभावित किया। आपने उनसे क्या सीखा?","examples":[{"en":"My English teacher in school always encouraged me to speak without fear.","native":"स्कूल में मेरी अंग्रेज़ी की शिक्षिका ने हमेशा मुझे बिना डर के बोलने के लिए प्रोत्साहित किया।"},{"en":"She explained difficult ideas with simple stories, which I still remember.","native":"वह कठिन बातों को साधारण कहानियों से समझाती थीं, जिन्हें मैं आज भी याद करता हूँ।"},{"en":"Because of her, I have become more confident in front of people.","native":"उन्हीं की वजह से मैं लोगों के सामने ज़्यादा आत्मविश्वासी हो गया हूँ।"}]},"es":{"word":"profesor","question":"Describe a un profesor que te haya influido. ¿Qué aprendiste de él o de ella?","examples":[{"en":"My English teacher in school always encouraged me to speak without fear.","native":"Mi profesora de inglés del colegio siempre me animaba a hablar sin miedo."},{"en":"She explained difficult ideas with simple stories, which I still remember.","native":"Explicaba las ideas difíciles con historias sencillas que todavía recuerdo."},{"en":"Because of her, I have become more confident in front of people.","native":"Gracias a ella, me he vuelto más seguro al hablar delante de la gente."}]},"zh":{"word":"老师","question":"描述一位影响过你的老师。你从他们身上学到了什么？","examples":[{"en":"My English teacher in school always encouraged me to speak without fear.","native":"我的学校英语老师总是鼓励我不要害怕开口说话。"},{"en":"She explained difficult ideas with simple stories, which I still remember.","native":"她用简单的故事解释难懂的概念，我至今还记得。"},{"en":"Because of her, I have become more confident in front of people.","native":"因为她，我在众人面前变得更自信了。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'neighbor', 'Do you know your neighbors well? What makes a good neighbor?', '{"te":{"word":"పొరుగువాడు","question":"మీకు మీ పొరుగువారిని బాగా తెలుసా? మంచి పొరుగువాడికి ఏ లక్షణాలు ఉండాలి?","examples":[{"en":"I know my neighbors well because we greet each other every morning.","native":"మా పొరుగువారిని నాకు బాగా తెలుసు, ఎందుకంటే మేము ప్రతి ఉదయం ఒకరినొకరు పలకరించుకుంటాము."},{"en":"A good neighbor helps you when you are in trouble.","native":"మీరు ఇబ్బందిలో ఉన్నప్పుడు సహాయం చేసేవాడే మంచి పొరుగువాడు."},{"en":"Last winter, our neighbors looked after our plants while we travelled.","native":"గత శీతాకాలంలో, మేము ప్రయాణంలో ఉన్నప్పుడు మా పొరుగువారు మా మొక్కలను చూసుకున్నారు."}]},"hi":{"word":"पड़ोसी","question":"क्या आप अपने पड़ोसियों को अच्छी तरह जानते हैं? एक अच्छा पड़ोसी कैसा होता है?","examples":[{"en":"I know my neighbors well because we greet each other every morning.","native":"मैं अपने पड़ोसियों को अच्छी तरह जानता हूँ क्योंकि हम हर सुबह एक-दूसरे को नमस्ते करते हैं।"},{"en":"A good neighbor helps you when you are in trouble.","native":"अच्छा पड़ोसी वही है जो मुसीबत में आपकी मदद करे।"},{"en":"Last winter, our neighbors looked after our plants while we travelled.","native":"पिछली सर्दियों में, जब हम यात्रा पर थे, हमारे पड़ोसियों ने हमारे पौधों की देखभाल की।"}]},"es":{"word":"vecino","question":"¿Conoces bien a tus vecinos? ¿Qué hace a un buen vecino?","examples":[{"en":"I know my neighbors well because we greet each other every morning.","native":"Conozco bien a mis vecinos porque nos saludamos cada mañana."},{"en":"A good neighbor helps you when you are in trouble.","native":"Un buen vecino te ayuda cuando estás en un apuro."},{"en":"Last winter, our neighbors looked after our plants while we travelled.","native":"El invierno pasado, nuestros vecinos cuidaron nuestras plantas mientras viajábamos."}]},"zh":{"word":"邻居","question":"你熟悉你的邻居吗？什么样的邻居才是好邻居？","examples":[{"en":"I know my neighbors well because we greet each other every morning.","native":"我和邻居很熟，因为我们每天早上互相打招呼。"},{"en":"A good neighbor helps you when you are in trouble.","native":"好邻居会在你有困难时帮助你。"},{"en":"Last winter, our neighbors looked after our plants while we travelled.","native":"去年冬天，我们外出旅行时，邻居帮我们照看花草。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'smartphone', 'How much time do you spend on your smartphone each day? Do you think it is too much?', '{"te":{"word":"స్మార్ట్‌ఫోన్","question":"మీరు ప్రతిరోజూ మీ స్మార్ట్‌ఫోన్‌పై ఎంత సమయం గడుపుతారు? అది ఎక్కువేమో అని మీరు అనుకుంటున్నారా?","examples":[{"en":"I spend about three hours a day on my smartphone, mostly on messages.","native":"నేను రోజుకు సుమారు మూడు గంటలు నా స్మార్ట్‌ఫోన్‌పై గడుపుతాను, ఎక్కువగా మెసేజ్‌లపై."},{"en":"I think it is too much, so I have set a timer for social apps.","native":"అది ఎక్కువేమో అని నేను అనుకుంటున్నాను, కాబట్టి సోషల్ యాప్‌లకు టైమర్ పెట్టాను."},{"en":"My phone is useful for studying, but it also wastes my time.","native":"నా ఫోన్ చదువుకు ఉపయోగపడుతుంది, కానీ అది నా సమయాన్ని కూడా వృథా చేస్తుంది."}]},"hi":{"word":"स्मार्टफ़ोन","question":"आप हर दिन अपने स्मार्टफ़ोन पर कितना समय बिताते हैं? क्या आपको लगता है कि यह बहुत ज़्यादा है?","examples":[{"en":"I spend about three hours a day on my smartphone, mostly on messages.","native":"मैं दिन में लगभग तीन घंटे अपने स्मार्टफ़ोन पर बिताता हूँ, ज़्यादातर मैसेज पर।"},{"en":"I think it is too much, so I have set a timer for social apps.","native":"मुझे लगता है कि यह बहुत ज़्यादा है, इसलिए मैंने सोशल ऐप्स के लिए टाइमर लगाया है।"},{"en":"My phone is useful for studying, but it also wastes my time.","native":"मेरा फ़ोन पढ़ाई में उपयोगी है, लेकिन यह मेरा समय भी बर्बाद करता है।"}]},"es":{"word":"teléfono inteligente","question":"¿Cuánto tiempo pasas al día con tu teléfono inteligente? ¿Crees que es demasiado?","examples":[{"en":"I spend about three hours a day on my smartphone, mostly on messages.","native":"Paso unas tres horas al día con el teléfono, sobre todo en mensajes."},{"en":"I think it is too much, so I have set a timer for social apps.","native":"Creo que es demasiado, así que he puesto un temporizador en las redes sociales."},{"en":"My phone is useful for studying, but it also wastes my time.","native":"Mi teléfono es útil para estudiar, pero también me hace perder el tiempo."}]},"zh":{"word":"智能手机","question":"你每天花多少时间在智能手机上？你觉得太多了吗？","examples":[{"en":"I spend about three hours a day on my smartphone, mostly on messages.","native":"我每天大约花三个小时在智能手机上，主要是发消息。"},{"en":"I think it is too much, so I have set a timer for social apps.","native":"我觉得太多了，所以我给社交软件设了使用时间限制。"},{"en":"My phone is useful for studying, but it also wastes my time.","native":"我的手机对学习有用，但也浪费我的时间。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'internet', 'How has the internet changed the way you learn and communicate?', '{"te":{"word":"ఇంటర్నెట్","question":"మీరు నేర్చుకునే మరియు కమ్యూనికేట్ చేసే విధానాన్ని ఇంటర్నెట్ ఎలా మార్చింది?","examples":[{"en":"The internet has made learning easier because everything is one search away.","native":"ప్రతిదీ ఒక సెర్చ్ దూరంలో ఉన్నందున ఇంటర్నెట్ నేర్చుకోవడాన్ని సులభం చేసింది."},{"en":"I video-call my cousins every week, although they live in another country.","native":"నా కజిన్స్ మరో దేశంలో ఉన్నప్పటికీ, వారితో ప్రతి వారం వీడియో కాల్ చేస్తాను."},{"en":"Before the internet, finding information took much longer than today.","native":"ఇంటర్నెట్ రాకముందు, సమాచారం కనుగొనడం నేటి కంటే చాలా ఎక్కువ సమయం పట్టేది."}]},"hi":{"word":"इंटरनेट","question":"इंटरनेट ने आपके सीखने और संवाद करने के तरीके को कैसे बदला है?","examples":[{"en":"The internet has made learning easier because everything is one search away.","native":"इंटरनेट ने सीखना आसान बना दिया है क्योंकि हर चीज़ एक खोज की दूरी पर है।"},{"en":"I video-call my cousins every week, although they live in another country.","native":"मैं हर हफ़्ते अपने चचेरे भाइयों से वीडियो कॉल करता हूँ, भले ही वे दूसरे देश में रहते हैं।"},{"en":"Before the internet, finding information took much longer than today.","native":"इंटरनेट से पहले, जानकारी खोजने में आज की तुलना में बहुत ज़्यादा समय लगता था।"}]},"es":{"word":"internet","question":"¿Cómo ha cambiado internet tu forma de aprender y comunicarte?","examples":[{"en":"The internet has made learning easier because everything is one search away.","native":"Internet ha hecho que aprender sea más fácil porque todo está a una búsqueda de distancia."},{"en":"I video-call my cousins every week, although they live in another country.","native":"Hago videollamadas con mis primos cada semana, aunque viven en otro país."},{"en":"Before the internet, finding information took much longer than today.","native":"Antes de internet, encontrar información llevaba mucho más tiempo que hoy."}]},"zh":{"word":"互联网","question":"互联网如何改变了你学习和交流的方式？","examples":[{"en":"The internet has made learning easier because everything is one search away.","native":"互联网让学习变得更容易，因为一切都只需一次搜索。"},{"en":"I video-call my cousins every week, although they live in another country.","native":"我每周都和住在另一个国家的表亲们视频通话。"},{"en":"Before the internet, finding information took much longer than today.","native":"在互联网出现之前，查找信息比今天花的时间长得多。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'television', 'Do you watch television often? What programs do you like and why?', '{"te":{"word":"టెలివిజన్","question":"మీరు తరచుగా టెలివిజన్ చూస్తారా? మీకు ఏ ప్రోగ్రామ్‌లు ఇష్టం మరియు ఎందుకు?","examples":[{"en":"I watch television every evening with my family after dinner.","native":"నేను ప్రతి సాయంత్రం భోజనం తర్వాత నా కుటుంబంతో టెలివిజన్ చూస్తాను."},{"en":"I like nature programs because they show places I have never seen.","native":"నాకు ప్రకృతి ప్రోగ్రామ్‌లు ఇష్టం, ఎందుకంటే అవి నేను ఎప్పుడూ చూడని ప్రదేశాలను చూపిస్తాయి."},{"en":"Watching too much television is worse than reading, in my opinion.","native":"నా అభిప్రాయం ప్రకారం, టెలివిజన్ ఎక్కువగా చూడటం చదవడం కంటే చెత్తది."}]},"hi":{"word":"टेलीविज़न","question":"क्या आप अक्सर टेलीविज़न देखते हैं? आपको कौन से कार्यक्रम पसंद हैं और क्यों?","examples":[{"en":"I watch television every evening with my family after dinner.","native":"मैं हर शाम रात के खाने के बाद अपने परिवार के साथ टेलीविज़न देखता हूँ।"},{"en":"I like nature programs because they show places I have never seen.","native":"मुझे प्रकृति पर आधारित कार्यक्रम पसंद हैं क्योंकि वे ऐसी जगहें दिखाते हैं जिन्हें मैंने कभी नहीं देखा।"},{"en":"Watching too much television is worse than reading, in my opinion.","native":"मेरी राय में, बहुत ज़्यादा टेलीविज़न देखना पढ़ने से बुरा है।"}]},"es":{"word":"televisión","question":"¿Ves la televisión a menudo? ¿Qué programas te gustan y por qué?","examples":[{"en":"I watch television every evening with my family after dinner.","native":"Veo la televisión cada noche con mi familia después de cenar."},{"en":"I like nature programs because they show places I have never seen.","native":"Me gustan los programas de naturaleza porque muestran lugares que nunca he visto."},{"en":"Watching too much television is worse than reading, in my opinion.","native":"En mi opinión, ver demasiada televisión es peor que leer."}]},"zh":{"word":"电视","question":"你经常看电视吗？你喜欢什么节目，为什么？","examples":[{"en":"I watch television every evening with my family after dinner.","native":"我每天晚饭后和家人一起看电视。"},{"en":"I like nature programs because they show places I have never seen.","native":"我喜欢自然节目，因为它们展示我从未见过的地方。"},{"en":"Watching too much television is worse than reading, in my opinion.","native":"在我看来，看太多电视比读书更糟糕。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'game', 'What games did you play as a child, and what games do you play now?', '{"te":{"word":"ఆట","question":"మీరు చిన్నప్పుడు ఏ ఆటలు ఆడేవారు, మరియు ఇప్పుడు ఏ ఆటలు ఆడుతున్నారు?","examples":[{"en":"As a child, I played hide and seek with my friends in the street.","native":"చిన్నప్పుడు, నేను వీధిలో నా స్నేహితులతో దాగుడుమూతలు ఆడేవాడిని."},{"en":"Now I play chess on my phone because it keeps my mind sharp.","native":"ఇప్పుడు నేను ఫోన్‌లో చెస్ ఆడుతాను, ఎందుకంటే అది నా మనస్సును పదునుగా ఉంచుతుంది."},{"en":"Outdoor games are healthier than video games, but both are fun.","native":"వీడియో గేమ్‌ల కంటే బహిరంగ ఆటలు ఆరోగ్యకరం, కానీ రెండూ సరదాగానే ఉంటాయి."}]},"hi":{"word":"खेल","question":"बचपन में आप कौन से खेल खेलते थे, और अब आप कौन से खेल खेलते हैं?","examples":[{"en":"As a child, I played hide and seek with my friends in the street.","native":"बचपन में, मैं गली में अपने दोस्तों के साथ छुपन-छुपाई खेलता था।"},{"en":"Now I play chess on my phone because it keeps my mind sharp.","native":"अब मैं अपने फ़ोन पर शतरंज खेलता हूँ क्योंकि इससे मेरा दिमाग तेज़ रहता है।"},{"en":"Outdoor games are healthier than video games, but both are fun.","native":"वीडियो गेम की तुलना में बाहर के खेल सेहत के लिए बेहतर हैं, लेकिन दोनों मज़ेदार हैं।"}]},"es":{"word":"juego","question":"¿A qué juegos jugabas de niño y a cuáles juegas ahora?","examples":[{"en":"As a child, I played hide and seek with my friends in the street.","native":"De niño, jugaba al escondite con mis amigos en la calle."},{"en":"Now I play chess on my phone because it keeps my mind sharp.","native":"Ahora juego al ajedrez en el móvil porque mantiene mi mente ágil."},{"en":"Outdoor games are healthier than video games, but both are fun.","native":"Los juegos al aire libre son más sanos que los videojuegos, pero ambos son divertidos."}]},"zh":{"word":"游戏","question":"你小时候玩什么游戏？现在玩什么游戏？","examples":[{"en":"As a child, I played hide and seek with my friends in the street.","native":"小时候，我和朋友们在街上玩捉迷藏。"},{"en":"Now I play chess on my phone because it keeps my mind sharp.","native":"现在我在手机上下国际象棋，因为它能让我保持思维敏捷。"},{"en":"Outdoor games are healthier than video games, but both are fun.","native":"户外游戏比电子游戏更健康，但两者都很有趣。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'dance', 'Do you like dancing? When do people dance in your culture?', '{"te":{"word":"నృత్యం","question":"మీకు డాన్స్ చేయడం ఇష్టమా? మీ సంస్కృతిలో ప్రజలు ఎప్పుడు డాన్స్ చేస్తారు?","examples":[{"en":"I like dancing at weddings because everyone is happy and relaxed.","native":"పెళ్లిళ్లలో డాన్స్ చేయడం నాకు ఇష్టం, ఎందుకంటే అందరూ సంతోషంగా మరియు రిలాక్స్‌గా ఉంటారు."},{"en":"In my culture, people dance during festivals and family celebrations.","native":"మా సంస్కృతిలో, పండుగలు మరియు కుటుంబ వేడుకల సమయంలో ప్రజలు డాన్స్ చేస్తారు."},{"en":"I have never taken dance lessons, but I enjoy moving to music.","native":"నేను ఎప్పుడూ డాన్స్ క్లాస్‌లు తీసుకోలేదు, కానీ సంగీతానికి అడుగులు వేయడం నాకు ఇష్టం."}]},"hi":{"word":"नृत्य","question":"क्या आपको नाचना पसंद है? आपकी संस्कृति में लोग कब नाचते हैं?","examples":[{"en":"I like dancing at weddings because everyone is happy and relaxed.","native":"मुझे शादियों में नाचना पसंद है क्योंकि सब खुश और बेफ़िक्र होते हैं।"},{"en":"In my culture, people dance during festivals and family celebrations.","native":"मेरी संस्कृति में, लोग त्योहारों और पारिवारिक समारोहों में नाचते हैं।"},{"en":"I have never taken dance lessons, but I enjoy moving to music.","native":"मैंने कभी नृत्य की कक्षाएँ नहीं लीं, लेकिन मुझे संगीत पर झूमना अच्छा लगता है।"}]},"es":{"word":"baile","question":"¿Te gusta bailar? ¿Cuándo baila la gente en tu cultura?","examples":[{"en":"I like dancing at weddings because everyone is happy and relaxed.","native":"Me gusta bailar en las bodas porque todos están felices y relajados."},{"en":"In my culture, people dance during festivals and family celebrations.","native":"En mi cultura, la gente baila durante las fiestas y las celebraciones familiares."},{"en":"I have never taken dance lessons, but I enjoy moving to music.","native":"Nunca he tomado clases de baile, pero disfruto moviéndome al ritmo de la música."}]},"zh":{"word":"舞蹈","question":"你喜欢跳舞吗？在你们文化中人们什么时候跳舞？","examples":[{"en":"I like dancing at weddings because everyone is happy and relaxed.","native":"我喜欢在婚礼上跳舞，因为每个人都很开心、很放松。"},{"en":"In my culture, people dance during festivals and family celebrations.","native":"在我们的文化中，人们在节日和家庭庆典上跳舞。"},{"en":"I have never taken dance lessons, but I enjoy moving to music.","native":"我从未上过舞蹈课，但我喜欢随着音乐舞动。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'swimming', 'Can you swim? Talk about your experiences with swimming.', '{"te":{"word":"ఈత","question":"మీకు ఈత తెలుసా? ఈతతో మీ అనుభవాల గురించి మాట్లాడండి.","examples":[{"en":"I learned to swim when I was eight years old at a local pool.","native":"నాకు ఎనిమిది సంవత్సరాల వయస్సులో స్థానిక స్విమ్మింగ్ పూల్‌లో ఈత నేర్చుకున్నాను."},{"en":"Swimming is my favourite exercise because it is gentle on the body.","native":"ఈత నా ఇష్టమైన వ్యాయామం, ఎందుకంటే అది శరీరానికి సున్నితమైనది."},{"en":"Last summer, I swam in the sea for the first time, and I felt free.","native":"గత వేసవిలో, నేను మొదటిసారి సముద్రంలో ఈత కొట్టాను, నాకు స్వేచ్ఛగా అనిపించింది."}]},"hi":{"word":"तैरना","question":"क्या आपको तैरना आता है? तैरने से जुड़े अपने अनुभवों के बारे में बताइए।","examples":[{"en":"I learned to swim when I was eight years old at a local pool.","native":"मैंने आठ साल की उम्र में स्थानीय पूल में तैरना सीखा था।"},{"en":"Swimming is my favourite exercise because it is gentle on the body.","native":"तैरना मेरा पसंदीदा व्यायाम है क्योंकि यह शरीर के लिए हल्का होता है।"},{"en":"Last summer, I swam in the sea for the first time, and I felt free.","native":"पिछली गर्मियों में, मैं पहली बार समुद्र में तैरा, और मुझे आज़ादी महसूस हुई।"}]},"es":{"word":"natación","question":"¿Sabes nadar? Habla de tus experiencias con la natación.","examples":[{"en":"I learned to swim when I was eight years old at a local pool.","native":"Aprendí a nadar a los ocho años en una piscina local."},{"en":"Swimming is my favourite exercise because it is gentle on the body.","native":"La natación es mi ejercicio favorito porque es suave para el cuerpo."},{"en":"Last summer, I swam in the sea for the first time, and I felt free.","native":"El verano pasado nadé en el mar por primera vez y me sentí libre."}]},"zh":{"word":"游泳","question":"你会游泳吗？谈谈你与游泳有关的经历。","examples":[{"en":"I learned to swim when I was eight years old at a local pool.","native":"我八岁时在当地的游泳池学会了游泳。"},{"en":"Swimming is my favourite exercise because it is gentle on the body.","native":"游泳是我最喜欢的运动，因为它对身体很温和。"},{"en":"Last summer, I swam in the sea for the first time, and I felt free.","native":"去年夏天，我第一次在海里游泳，感觉非常自由。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'bicycle', 'Do you ride a bicycle? What are the advantages of cycling?', '{"te":{"word":"సైకిల్","question":"మీరు సైకిల్ తొక్కుతారా? సైక్లింగ్ యొక్క ప్రయోజనాలు ఏమిటి?","examples":[{"en":"I ride my bicycle to college because it is cheaper than the bus.","native":"నేను కాలేజీకి సైకిల్ తొక్కుతాను, ఎందుకంటే అది బస్సు కంటే చౌక."},{"en":"Cycling keeps me healthy and does not pollute the air.","native":"సైక్లింగ్ నన్ను ఆరోగ్యంగా ఉంచుతుంది మరియు గాలిని కలుషితం చేయదు."},{"en":"When I was younger, I fell off my bicycle but got up and tried again.","native":"నేను చిన్నప్పుడు సైకిల్ నుండి పడిపోయాను, కానీ లేచి మళ్లీ ప్రయత్నించాను."}]},"hi":{"word":"साइकिल","question":"क्या आप साइकिल चलाते हैं? साइकिल चलाने के क्या फ़ायदे हैं?","examples":[{"en":"I ride my bicycle to college because it is cheaper than the bus.","native":"मैं कॉलेज साइकिल से जाता हूँ क्योंकि यह बस से सस्ता है।"},{"en":"Cycling keeps me healthy and does not pollute the air.","native":"साइकिल चलाने से मैं स्वस्थ रहता हूँ और हवा प्रदूषित नहीं होती।"},{"en":"When I was younger, I fell off my bicycle but got up and tried again.","native":"जब मैं छोटा था, मैं साइकिल से गिर गया था, लेकिन उठकर फिर कोशिश की।"}]},"es":{"word":"bicicleta","question":"¿Montas en bicicleta? ¿Cuáles son las ventajas de ir en bicicleta?","examples":[{"en":"I ride my bicycle to college because it is cheaper than the bus.","native":"Voy a la universidad en bicicleta porque es más barato que el autobús."},{"en":"Cycling keeps me healthy and does not pollute the air.","native":"Ir en bicicleta me mantiene sano y no contamina el aire."},{"en":"When I was younger, I fell off my bicycle but got up and tried again.","native":"Cuando era más joven, me caí de la bicicleta, pero me levanté y lo intenté de nuevo."}]},"zh":{"word":"自行车","question":"你骑自行车吗？骑自行车有什么好处？","examples":[{"en":"I ride my bicycle to college because it is cheaper than the bus.","native":"我骑自行车上大学，因为比坐公交车便宜。"},{"en":"Cycling keeps me healthy and does not pollute the air.","native":"骑自行车让我保持健康，而且不污染空气。"},{"en":"When I was younger, I fell off my bicycle but got up and tried again.","native":"我小时候从自行车上摔下来过，但我爬起来再试了一次。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'park', 'Is there a park near your home? What do people do there?', '{"te":{"word":"పార్కు","question":"మీ ఇంటి దగ్గర పార్కు ఉందా? అక్కడ ప్రజలు ఏమి చేస్తారు?","examples":[{"en":"There is a small park near my house with many trees and benches.","native":"నా ఇంటి దగ్గర చాలా చెట్లు మరియు బెంచీలతో ఒక చిన్న పార్కు ఉంది."},{"en":"In the morning, people walk and do yoga there.","native":"ఉదయం, ప్రజలు అక్కడ నడుస్తారు మరియు యోగా చేస్తారు."},{"en":"I often sit in the park and read because it is quiet and green.","native":"అది ప్రశాంతంగా మరియు పచ్చగా ఉన్నందున నేను తరచుగా పార్కులో కూర్చుని చదువుతాను."}]},"hi":{"word":"पार्क","question":"क्या आपके घर के पास कोई पार्क है? लोग वहाँ क्या करते हैं?","examples":[{"en":"There is a small park near my house with many trees and benches.","native":"मेरे घर के पास कई पेड़ों और बेंचों वाला एक छोटा पार्क है।"},{"en":"In the morning, people walk and do yoga there.","native":"सुबह, लोग वहाँ घूमते हैं और योग करते हैं।"},{"en":"I often sit in the park and read because it is quiet and green.","native":"मैं अक्सर पार्क में बैठकर पढ़ता हूँ क्योंकि वहाँ शांत और हरियाली है।"}]},"es":{"word":"parque","question":"¿Hay un parque cerca de tu casa? ¿Qué hace la gente allí?","examples":[{"en":"There is a small park near my house with many trees and benches.","native":"Hay un parque pequeño cerca de mi casa con muchos árboles y bancos."},{"en":"In the morning, people walk and do yoga there.","native":"Por la mañana, la gente pasea y hace yoga allí."},{"en":"I often sit in the park and read because it is quiet and green.","native":"A menudo me siento en el parque a leer porque es tranquilo y verde."}]},"zh":{"word":"公园","question":"你家附近有公园吗？人们在那里做什么？","examples":[{"en":"There is a small park near my house with many trees and benches.","native":"我家附近有一个小公园，里面有很多树和长椅。"},{"en":"In the morning, people walk and do yoga there.","native":"早上，人们在那里散步、做瑜伽。"},{"en":"I often sit in the park and read because it is quiet and green.","native":"我经常坐在公园里看书，因为那里安静又充满绿色。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'city', 'Do you prefer living in a city or in the countryside? Why?', '{"te":{"word":"నగరం","question":"నగరంలో నివసించడానికా లేదా గ్రామీణ ప్రాంతంలో నివసించడానికా మీరు ఇష్టపడతారు? ఎందుకు?","examples":[{"en":"I prefer city life because everything is close and easy to reach.","native":"ప్రతిదీ దగ్గరగా మరియు సులభంగా అందుబాటులో ఉన్నందున నాకు నగర జీవితం ఇష్టం."},{"en":"However, the countryside is quieter and the air is cleaner.","native":"అయితే, గ్రామీణ ప్రాంతం ప్రశాంతంగా ఉంటుంది మరియు గాలి శుద్ధంగా ఉంటుంది."},{"en":"Cities are more exciting, but they are also more expensive.","native":"నగరాలు మరింత ఉత్సాహంగా ఉంటాయి, కానీ అవి ఖరీదైనవి కూడా."}]},"hi":{"word":"शहर","question":"आप शहर में रहना पसंद करेंगे या गाँव में? क्यों?","examples":[{"en":"I prefer city life because everything is close and easy to reach.","native":"मुझे शहर की ज़िंदगी पसंद है क्योंकि हर चीज़ पास और आसानी से उपलब्ध होती है।"},{"en":"However, the countryside is quieter and the air is cleaner.","native":"हालांकि, गाँव ज़्यादा शांत होता है और हवा वहाँ ज़्यादा साफ़ होती है।"},{"en":"Cities are more exciting, but they are also more expensive.","native":"शहर ज़्यादा रोमांचक होते हैं, लेकिन वे ज़्यादा महँगे भी होते हैं।"}]},"es":{"word":"ciudad","question":"¿Prefieres vivir en la ciudad o en el campo? ¿Por qué?","examples":[{"en":"I prefer city life because everything is close and easy to reach.","native":"Prefiero la vida en la ciudad porque todo está cerca y es fácil de alcanzar."},{"en":"However, the countryside is quieter and the air is cleaner.","native":"Sin embargo, el campo es más tranquilo y el aire es más limpio."},{"en":"Cities are more exciting, but they are also more expensive.","native":"Las ciudades son más emocionantes, pero también más caras."}]},"zh":{"word":"城市","question":"你更喜欢住在城市还是乡村？为什么？","examples":[{"en":"I prefer city life because everything is close and easy to reach.","native":"我更喜欢城市生活，因为一切都近在咫尺、方便快捷。"},{"en":"However, the countryside is quieter and the air is cleaner.","native":"不过，乡村更安静，空气也更清新。"},{"en":"Cities are more exciting, but they are also more expensive.","native":"城市更令人兴奋，但生活成本也更高。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'village', 'Talk about a village you have visited. How is life there different from city life?', '{"te":{"word":"గ్రామం","question":"మీరు సందర్శించిన ఒక గ్రామం గురించి మాట్లాడండి. అక్కడి జీవితం నగర జీవితం నుండి ఎలా భిన్నంగా ఉంటుంది?","examples":[{"en":"My grandparents live in a village surrounded by green fields.","native":"నా తాతయ్య, అమ్మమ్మ పచ్చని పొలాల మధ్య ఉన్న ఒక గ్రామంలో నివసిస్తారు."},{"en":"Life there is slower and more peaceful than in the city.","native":"అక్కడి జీవితం నగరం కంటే నెమ్మదిగా మరియు ప్రశాంతంగా ఉంటుంది."},{"en":"People in the village know each other, which makes it feel like one family.","native":"గ్రామంలోని ప్రజలు ఒకరినొకరు తెలుసుకుంటారు, అది ఒకే కుటుంబంలా అనిపిస్తుంది."}]},"hi":{"word":"गाँव","question":"किसी ऐसे गाँव के बारे में बताइए जहाँ आप गए हों। वहाँ की ज़िंदगी शहर से कैसे अलग है?","examples":[{"en":"My grandparents live in a village surrounded by green fields.","native":"मेरे दादा-दादी हरे-भरे खेतों से घिरे एक गाँव में रहते हैं।"},{"en":"Life there is slower and more peaceful than in the city.","native":"वहाँ की ज़िंदगी शहर की तुलना में धीमी और ज़्यादा शांतिपूर्ण है।"},{"en":"People in the village know each other, which makes it feel like one family.","native":"गाँव के लोग एक-दूसरे को जानते हैं, जिससे वहाँ एक परिवार जैसा माहौल लगता है।"}]},"es":{"word":"pueblo","question":"Habla de un pueblo que hayas visitado. ¿En qué se diferencia la vida allí de la vida en la ciudad?","examples":[{"en":"My grandparents live in a village surrounded by green fields.","native":"Mis abuelos viven en un pueblo rodeado de campos verdes."},{"en":"Life there is slower and more peaceful than in the city.","native":"La vida allí es más lenta y tranquila que en la ciudad."},{"en":"People in the village know each other, which makes it feel like one family.","native":"La gente del pueblo se conoce entre sí, lo que hace que parezca una sola familia."}]},"zh":{"word":"村庄","question":"谈谈你去过的一个村庄。那里的生活和城市生活有什么不同？","examples":[{"en":"My grandparents live in a village surrounded by green fields.","native":"我的祖父母住在一个被绿色田野环绕的村庄里。"},{"en":"Life there is slower and more peaceful than in the city.","native":"那里的生活比城市慢，也更宁静。"},{"en":"People in the village know each other, which makes it feel like one family.","native":"村里的人互相都认识，让人感觉像一个大家庭。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'restaurant', 'What is your favourite restaurant? What do you usually order there?', '{"te":{"word":"రెస్టారెంట్","question":"మీకు ఇష్టమైన రెస్టారెంట్ ఏది? మీరు అక్కడ సాధారణంగా ఏమి ఆర్డర్ చేస్తారు?","examples":[{"en":"My favourite restaurant is a small family place near the station.","native":"నా ఇష్టమైన రెస్టారెంట్ స్టేషన్ దగ్గర ఉన్న ఒక చిన్న కుటుంబ రెస్టారెంట్."},{"en":"I usually order their special curry because it is spicy and fresh.","native":"నేను సాధారణంగా వారి స్పెషల్ కర్రీ ఆర్డర్ చేస్తాను, ఎందుకంటే అది కారంగా మరియు తాజాగా ఉంటుంది."},{"en":"Eating there reminds me of celebrations with my family.","native":"అక్కడ భోజనం చేయడం నాకు నా కుటుంబంతో వేడుకల గుర్తు చేస్తుంది."}]},"hi":{"word":"रेस्तराँ","question":"आपका पसंदीदा रेस्तराँ कौन सा है? आप वहाँ आमतौर पर क्या मंगवाते हैं?","examples":[{"en":"My favourite restaurant is a small family place near the station.","native":"मेरा पसंदीदा रेस्तराँ स्टेशन के पास एक छोटा पारिवारिक रेस्तराँ है।"},{"en":"I usually order their special curry because it is spicy and fresh.","native":"मैं आमतौर पर वहाँ की स्पेशल करी मंगवाता हूँ क्योंकि वह मसालेदार और ताज़ी होती है।"},{"en":"Eating there reminds me of celebrations with my family.","native":"वहाँ खाना खाने से मुझे परिवार के साथ मनाए गए जश्न की याद आती है।"}]},"es":{"word":"restaurante","question":"¿Cuál es tu restaurante favorito? ¿Qué sueles pedir allí?","examples":[{"en":"My favourite restaurant is a small family place near the station.","native":"Mi restaurante favorito es un pequeño lugar familiar cerca de la estación."},{"en":"I usually order their special curry because it is spicy and fresh.","native":"Normalmente pido su curry especial porque es picante y fresco."},{"en":"Eating there reminds me of celebrations with my family.","native":"Comer allí me recuerda a las celebraciones con mi familia."}]},"zh":{"word":"餐厅","question":"你最喜欢的餐厅是哪家？你通常在那里点什么？","examples":[{"en":"My favourite restaurant is a small family place near the station.","native":"我最喜欢的餐厅是车站附近的一家小型家庭餐馆。"},{"en":"I usually order their special curry because it is spicy and fresh.","native":"我通常点他们的特色咖喱，因为又辣又新鲜。"},{"en":"Eating there reminds me of celebrations with my family.","native":"在那里吃饭让我想起和家人一起庆祝的时光。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'birthday', 'How do you usually celebrate your birthday?', '{"te":{"word":"పుట్టినరోజు","question":"మీరు మీ పుట్టినరోజును సాధారణంగా ఎలా జరుపుకుంటారు?","examples":[{"en":"I usually celebrate my birthday with a small dinner at home.","native":"నేను సాధారణంగా ఇంట్లో చిన్న విందుతో నా పుట్టినరోజును జరుపుకుంటాను."},{"en":"My friends call me at midnight, which always makes me smile.","native":"నా స్నేహితులు అర్ధరాత్రి నాకు కాల్ చేస్తారు, అది ఎప్పుడూ నన్ను నవ్విస్తుంది."},{"en":"Birthdays are special because they bring people together.","native":"పుట్టినరోజులు ప్రత్యేకమైనవి, ఎందుకంటే అవి ప్రజలను ఒకచోట చేరుస్తాయి."}]},"hi":{"word":"जन्मदिन","question":"आप आमतौर पर अपना जन्मदिन कैसे मनाते हैं?","examples":[{"en":"I usually celebrate my birthday with a small dinner at home.","native":"मैं आमतौर पर घर पर छोटे डिनर के साथ अपना जन्मदिन मनाता हूँ।"},{"en":"My friends call me at midnight, which always makes me smile.","native":"मेरे दोस्त आधी रात को मुझे फ़ोन करते हैं, जिससे मुझे हमेशा खुशी होती है।"},{"en":"Birthdays are special because they bring people together.","native":"जन्मदिन खास होते हैं क्योंकि वे लोगों को एक साथ लाते हैं।"}]},"es":{"word":"cumpleaños","question":"¿Cómo sueles celebrar tu cumpleaños?","examples":[{"en":"I usually celebrate my birthday with a small dinner at home.","native":"Normalmente celebro mi cumpleaños con una cena pequeña en casa."},{"en":"My friends call me at midnight, which always makes me smile.","native":"Mis amigos me llaman a medianoche, lo que siempre me hace sonreír."},{"en":"Birthdays are special because they bring people together.","native":"Los cumpleaños son especiales porque unen a la gente."}]},"zh":{"word":"生日","question":"你通常怎么庆祝生日？","examples":[{"en":"I usually celebrate my birthday with a small dinner at home.","native":"我通常在家用一顿简单的晚餐庆祝生日。"},{"en":"My friends call me at midnight, which always makes me smile.","native":"我的朋友们会在午夜给我打电话，这总能让我开心。"},{"en":"Birthdays are special because they bring people together.","native":"生日很特别，因为它把人们聚在一起。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'wedding', 'Describe a wedding you have attended. What was it like?', '{"te":{"word":"వివాహం","question":"మీరు హాజరైన ఒక వివాహాన్ని వివరించండి. అది ఎలా ఉంది?","examples":[{"en":"Last year, I attended my cousin''s wedding in a big hall.","native":"గత సంవత్సరం, నేను ఒక పెద్ద హాలులో నా కజిన్ వివాహానికి హాజరయ్యాను."},{"en":"The bride wore a beautiful red dress, and everyone took photos.","native":"వధువు అందమైన ఎరుపు రంగు దుస్తులు ధరించింది, అందరూ ఫోటోలు తీశారు."},{"en":"The food was delicious, and we danced until late at night.","native":"భోజనం రుచిగా ఉంది, మేము రాత్రి ఆలస్యం వరకు డాన్స్ చేశాము."}]},"hi":{"word":"शादी","question":"किसी ऐसी शादी का वर्णन कीजिए जिसमें आप शामिल हुए हों। वह कैसी थी?","examples":[{"en":"Last year, I attended my cousin''s wedding in a big hall.","native":"पिछले साल, मैं एक बड़े हॉल में अपने चचेरे भाई की शादी में शामिल हुआ।"},{"en":"The bride wore a beautiful red dress, and everyone took photos.","native":"दुल्हन ने सुंदर लाल पोशाक पहनी थी, और सबने तस्वीरें लीं।"},{"en":"The food was delicious, and we danced until late at night.","native":"खाना स्वादिष्ट था, और हम देर रात तक नाचते रहे।"}]},"es":{"word":"boda","question":"Describe una boda a la que hayas asistido. ¿Cómo fue?","examples":[{"en":"Last year, I attended my cousin''s wedding in a big hall.","native":"El año pasado asistí a la boda de mi primo en un gran salón."},{"en":"The bride wore a beautiful red dress, and everyone took photos.","native":"La novia llevaba un precioso vestido rojo y todos hicieron fotos."},{"en":"The food was delicious, and we danced until late at night.","native":"La comida estaba deliciosa y bailamos hasta altas horas de la noche."}]},"zh":{"word":"婚礼","question":"描述一场你参加过的婚礼。它是什么样的？","examples":[{"en":"Last year, I attended my cousin''s wedding in a big hall.","native":"去年，我在一个大厅里参加了表哥的婚礼。"},{"en":"The bride wore a beautiful red dress, and everyone took photos.","native":"新娘穿着漂亮的红色礼服，大家都拍了照片。"},{"en":"The food was delicious, and we danced until late at night.","native":"食物很美味，我们跳舞跳到深夜。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'library', 'Do you use libraries? What are the benefits of reading in a library?', '{"te":{"word":"గ్రంథాలయం","question":"మీరు గ్రంథాలయాలను వాడతారా? గ్రంథాలయంలో చదవడం వల్ల ఏమి ప్రయోజనాలు ఉన్నాయి?","examples":[{"en":"I visit the city library twice a month to borrow novels.","native":"నవలలు అప్పుగా తీసుకోవడానికి నేను నెలకు రెండుసార్లు సిటీ లైబ్రరీకి వెళ్తాను."},{"en":"Libraries are quiet, so I can concentrate better than at home.","native":"గ్రంథాలయాలు ప్రశాంతంగా ఉంటాయి, కాబట్టి ఇంటి కంటే నేను బాగా కాన్సన్ట్రేట్ చేయగలను."},{"en":"Our library also offers free classes, which helps many students.","native":"మా లైబ్రరీ ఉచిత క్లాస్‌లు కూడా అందిస్తుంది, ఇది చాలా మంది విద్యార్థులకు సహాయపడుతుంది."}]},"hi":{"word":"पुस्तकालय","question":"क्या आप पुस्तकालयों का उपयोग करते हैं? पुस्तकालय में पढ़ने के क्या लाभ हैं?","examples":[{"en":"I visit the city library twice a month to borrow novels.","native":"मैं उपन्यास उधार लेने के लिए महीने में दो बार शहर के पुस्तकालय जाता हूँ।"},{"en":"Libraries are quiet, so I can concentrate better than at home.","native":"पुस्तकालय शांत होते हैं, इसलिए मैं घर की तुलना में वहाँ बेहतर ध्यान लगा सकता हूँ।"},{"en":"Our library also offers free classes, which helps many students.","native":"हमारा पुस्तकालय मुफ़्त कक्षाएँ भी देता है, जिससे कई छात्रों को मदद मिलती है।"}]},"es":{"word":"biblioteca","question":"¿Usas las bibliotecas? ¿Cuáles son las ventajas de leer en una biblioteca?","examples":[{"en":"I visit the city library twice a month to borrow novels.","native":"Voy a la biblioteca de la ciudad dos veces al mes para pedir novelas prestadas."},{"en":"Libraries are quiet, so I can concentrate better than at home.","native":"Las bibliotecas son tranquilas, así que puedo concentrarme mejor que en casa."},{"en":"Our library also offers free classes, which helps many students.","native":"Nuestra biblioteca también ofrece clases gratuitas, lo que ayuda a muchos estudiantes."}]},"zh":{"word":"图书馆","question":"你使用图书馆吗？在图书馆读书有什么好处？","examples":[{"en":"I visit the city library twice a month to borrow novels.","native":"我每月去市图书馆两次借小说。"},{"en":"Libraries are quiet, so I can concentrate better than at home.","native":"图书馆很安静，所以我能比在家更专注。"},{"en":"Our library also offers free classes, which helps many students.","native":"我们的图书馆还提供免费课程，帮助了许多学生。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'museum', 'Have you visited a museum? What did you see and learn there?', '{"te":{"word":"మ్యూజియం","question":"మీరు ఎప్పుడైనా మ్యూజియం సందర్శించారా? అక్కడ మీరు ఏమి చూశారు మరియు ఏమి నేర్చుకున్నారు?","examples":[{"en":"I visited the history museum last month with my classmates.","native":"గత నెల నేను నా క్లాస్‌మేట్‌లతో చరిత్ర మ్యూజియాన్ని సందర్శించాను."},{"en":"We saw old coins and tools that were hundreds of years old.","native":"మేము వందల సంవత్సరాల పురాతనమైన నాణేలు మరియు పనిముట్లు చూశాము."},{"en":"I learned more from the museum than from my textbook.","native":"నా పుస్తకం కంటే మ్యూజియం నుండి నేను ఎక్కువ నేర్చుకున్నాను."}]},"hi":{"word":"संग्रहालय","question":"क्या आपने कभी कोई संग्रहालय देखा है? वहाँ आपने क्या देखा और क्या सीखा?","examples":[{"en":"I visited the history museum last month with my classmates.","native":"पिछले महीने मैं अपने सहपाठियों के साथ इतिहास संग्रहालय गया था।"},{"en":"We saw old coins and tools that were hundreds of years old.","native":"हमने वहाँ सैकड़ों साल पुराने सिक्के और औज़ार देखे।"},{"en":"I learned more from the museum than from my textbook.","native":"मैंने अपनी पाठ्यपुस्तक से ज़्यादा संग्रहालय से सीखा।"}]},"es":{"word":"museo","question":"¿Has visitado un museo? ¿Qué viste y qué aprendiste allí?","examples":[{"en":"I visited the history museum last month with my classmates.","native":"Visité el museo de historia el mes pasado con mis compañeros de clase."},{"en":"We saw old coins and tools that were hundreds of years old.","native":"Vimos monedas y herramientas antiguas de cientos de años."},{"en":"I learned more from the museum than from my textbook.","native":"Aprendí más en el museo que en mi libro de texto."}]},"zh":{"word":"博物馆","question":"你参观过博物馆吗？你在那里看到了什么、学到了什么？","examples":[{"en":"I visited the history museum last month with my classmates.","native":"上个月我和同学们参观了历史博物馆。"},{"en":"We saw old coins and tools that were hundreds of years old.","native":"我们看到了有数百年历史的古钱币和工具。"},{"en":"I learned more from the museum than from my textbook.","native":"我从博物馆学到的东西比从课本上学到的还多。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'beach', 'Do you like going to the beach? What do you do there?', '{"te":{"word":"బీచ్","question":"మీకు బీచ్‌కు వెళ్లడం ఇష్టమా? అక్కడ మీరు ఏమి చేస్తారు?","examples":[{"en":"I love walking on the beach because the sound of waves relaxes me.","native":"అలల శబ్దం నాకు ఉపశమనం ఇస్తుంది కాబట్టి బీచ్‌లో నడవడం నాకు చాలా ఇష్టం."},{"en":"My friends and I play volleyball and collect shells there.","native":"నేను మరియు నా స్నేహితులు అక్కడ వాలీబాల్ ఆడుతాము మరియు గుల్లలు సేకరిస్తాము."},{"en":"The beach is more beautiful in the evening than at noon.","native":"మధ్యాహ్నం కంటే సాయంత్రం బీచ్ మరింత అందంగా ఉంటుంది."}]},"hi":{"word":"समुद्र तट","question":"क्या आपको समुद्र तट पर जाना पसंद है? आप वहाँ क्या करते हैं?","examples":[{"en":"I love walking on the beach because the sound of waves relaxes me.","native":"मुझे समुद्र तट पर चलना बहुत पसंद है क्योंकि लहरों की आवाज़ मुझे सुकून देती है।"},{"en":"My friends and I play volleyball and collect shells there.","native":"मैं और मेरे दोस्त वहाँ वॉलीबॉल खेलते हैं और शंख इकट्ठा करते हैं।"},{"en":"The beach is more beautiful in the evening than at noon.","native":"दोपहर की तुलना में शाम को समुद्र तट ज़्यादा खूबसूरत लगता है।"}]},"es":{"word":"playa","question":"¿Te gusta ir a la playa? ¿Qué haces allí?","examples":[{"en":"I love walking on the beach because the sound of waves relaxes me.","native":"Me encanta caminar por la playa porque el sonido de las olas me relaja."},{"en":"My friends and I play volleyball and collect shells there.","native":"Mis amigos y yo jugamos al voleibol y recogemos conchas allí."},{"en":"The beach is more beautiful in the evening than at noon.","native":"La playa es más bonita por la tarde que al mediodía."}]},"zh":{"word":"海滩","question":"你喜欢去海滩吗？你在那里做什么？","examples":[{"en":"I love walking on the beach because the sound of waves relaxes me.","native":"我喜欢在海滩上散步，因为海浪的声音让我放松。"},{"en":"My friends and I play volleyball and collect shells there.","native":"我和朋友们在那里打排球、捡贝壳。"},{"en":"The beach is more beautiful in the evening than at noon.","native":"傍晚的海滩比中午更美丽。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'mountain', 'Have you ever climbed a mountain? Would you like to? Why?', '{"te":{"word":"పర్వతం","question":"మీరు ఎప్పుడైనా పర్వతం ఎక్కారా? ఎక్కాలనుకుంటున్నారా? ఎందుకు?","examples":[{"en":"I climbed a small mountain with my uncle two years ago.","native":"రెండు సంవత్సరాల క్రితం నేను నా మామయ్యతో ఒక చిన్న పర్వతం ఎక్కాను."},{"en":"The climb was hard, but the view from the top was worth it.","native":"ఎక్కడం కష్టం, కానీ పైనుండి కనిపించే దృశ్యం దానికి తగినది."},{"en":"I would like to climb a higher one when I become fitter.","native":"నేను మరింత ఫిట్‌గా మారినప్పుడు ఎత్తైన దాన్ని ఎక్కాలనుకుంటున్నాను."}]},"hi":{"word":"पहाड़","question":"क्या आपने कभी कोई पहाड़ चढ़ा है? क्या आप चढ़ना चाहेंगे? क्यों?","examples":[{"en":"I climbed a small mountain with my uncle two years ago.","native":"दो साल पहले मैं अपने चाचा के साथ एक छोटे पहाड़ पर चढ़ा था।"},{"en":"The climb was hard, but the view from the top was worth it.","native":"चढ़ाई कठिन थी, लेकिन चोटी से दिखने वाला नज़ारा उसके लायक था।"},{"en":"I would like to climb a higher one when I become fitter.","native":"जब मैं और फ़िट हो जाऊँगा, तब ऊँचा पहाड़ चढ़ना चाहूँगा।"}]},"es":{"word":"montaña","question":"¿Has escalado alguna vez una montaña? ¿Te gustaría? ¿Por qué?","examples":[{"en":"I climbed a small mountain with my uncle two years ago.","native":"Escalé una montaña pequeña con mi tío hace dos años."},{"en":"The climb was hard, but the view from the top was worth it.","native":"La subida fue dura, pero la vista desde arriba valió la pena."},{"en":"I would like to climb a higher one when I become fitter.","native":"Me gustaría escalar una más alta cuando esté más en forma."}]},"zh":{"word":"山","question":"你爬过山吗？你想爬山吗？为什么？","examples":[{"en":"I climbed a small mountain with my uncle two years ago.","native":"两年前我和叔叔爬过一座小山。"},{"en":"The climb was hard, but the view from the top was worth it.","native":"攀登很辛苦，但山顶的景色值得。"},{"en":"I would like to climb a higher one when I become fitter.","native":"等我身体更好时，我想爬一座更高的山。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'rain', 'Do you like rainy days? What do you usually do when it rains?', '{"te":{"word":"వర్షం","question":"మీకు వర్షం రోజులు ఇష్టమా? వర్షం పడినప్పుడు మీరు సాధారణంగా ఏమి చేస్తారు?","examples":[{"en":"I enjoy rainy days because the weather becomes cool and fresh.","native":"వాతావరణం చల్లగా మరియు తాజాగా మారుతుంది కాబట్టి వర్షం రోజులు నాకు ఇష్టం."},{"en":"When it rains, I drink hot tea and watch the drops from my window.","native":"వర్షం పడినప్పుడు, నేను వేడి టీ తాగి కిటికీ నుండి జల్లులు చూస్తాను."},{"en":"Heavy rain is beautiful, but it makes travelling difficult.","native":"భారీ వర్షం అందంగా ఉంటుంది, కానీ ప్రయాణాన్ని కష్టతరం చేస్తుంది."}]},"hi":{"word":"बारिश","question":"क्या आपको बारिश के दिन पसंद हैं? बारिश होने पर आप आमतौर पर क्या करते हैं?","examples":[{"en":"I enjoy rainy days because the weather becomes cool and fresh.","native":"मुझे बारिश के दिन पसंद हैं क्योंकि मौसम ठंडा और ताज़ा हो जाता है।"},{"en":"When it rains, I drink hot tea and watch the drops from my window.","native":"जब बारिश होती है, मैं गर्म चाय पीता हूँ और खिड़की से बूँदें देखता हूँ।"},{"en":"Heavy rain is beautiful, but it makes travelling difficult.","native":"तेज़ बारिश सुंदर होती है, लेकिन इससे यात्रा करना कठिन हो जाता है।"}]},"es":{"word":"lluvia","question":"¿Te gustan los días de lluvia? ¿Qué sueles hacer cuando llueve?","examples":[{"en":"I enjoy rainy days because the weather becomes cool and fresh.","native":"Disfruto los días de lluvia porque el clima se vuelve fresco y agradable."},{"en":"When it rains, I drink hot tea and watch the drops from my window.","native":"Cuando llueve, bebo té caliente y miro las gotas desde mi ventana."},{"en":"Heavy rain is beautiful, but it makes travelling difficult.","native":"La lluvia fuerte es hermosa, pero hace difícil viajar."}]},"zh":{"word":"雨","question":"你喜欢下雨天吗？下雨时你通常做什么？","examples":[{"en":"I enjoy rainy days because the weather becomes cool and fresh.","native":"我喜欢下雨天，因为天气变得凉爽清新。"},{"en":"When it rains, I drink hot tea and watch the drops from my window.","native":"下雨时，我喝热茶，看着窗外的雨滴。"},{"en":"Heavy rain is beautiful, but it makes travelling difficult.","native":"大雨很美，但会让出行变得困难。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'garden', 'Do you have a garden or grow plants? Why do people enjoy gardening?', '{"te":{"word":"తోట","question":"మీకు తోట ఉందా లేదా మొక్కలు పెంచుతారా? ప్రజలు తోటపనిని ఎందుకు ఇష్టపడతారు?","examples":[{"en":"We have a small garden behind our house with roses and herbs.","native":"మా ఇంటి వెనుక గులాబీలు మరియు మూలికలతో ఒక చిన్న తోట ఉంది."},{"en":"I water the plants every morning before I leave for work.","native":"నేను పనికి బయలుదేరే ముందు ప్రతి ఉదయం మొక్కలకు నీళ్లు పోస్తాను."},{"en":"Gardening is relaxing because it connects people with nature.","native":"తోటపని ప్రజలను ప్రకృతితో కలుపుతుంది కాబట్టి అది ఉపశమనకరం."}]},"hi":{"word":"बगीचा","question":"क्या आपके पास कोई बगीचा है या आप पौधे उगाते हैं? लोगों को बागवानी क्यों पसंद है?","examples":[{"en":"We have a small garden behind our house with roses and herbs.","native":"हमारे घर के पीछे गुलाब और जड़ी-बूटियों वाला एक छोटा बगीचा है।"},{"en":"I water the plants every morning before I leave for work.","native":"मैं काम पर जाने से पहले हर सुबह पौधों को पानी देता हूँ।"},{"en":"Gardening is relaxing because it connects people with nature.","native":"बागवानी आरामदायक है क्योंकि यह लोगों को प्रकृति से जोड़ती है।"}]},"es":{"word":"jardín","question":"¿Tienes un jardín o cultivas plantas? ¿Por qué disfruta la gente de la jardinería?","examples":[{"en":"We have a small garden behind our house with roses and herbs.","native":"Tenemos un pequeño jardín detrás de casa con rosas y hierbas."},{"en":"I water the plants every morning before I leave for work.","native":"Riego las plantas cada mañana antes de salir al trabajo."},{"en":"Gardening is relaxing because it connects people with nature.","native":"La jardinería es relajante porque conecta a la gente con la naturaleza."}]},"zh":{"word":"花园","question":"你有花园或种植物吗？人们为什么喜欢园艺？","examples":[{"en":"We have a small garden behind our house with roses and herbs.","native":"我们房子后面有一个小花园，种着玫瑰和香草。"},{"en":"I water the plants every morning before I leave for work.","native":"我每天上班前都给植物浇水。"},{"en":"Gardening is relaxing because it connects people with nature.","native":"园艺让人放松，因为它把人们与自然联系在一起。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'photography', 'Do you like taking photos? What do you usually photograph?', '{"te":{"word":"ఛాయాచిత్రకళ","question":"మీకు ఫోటోలు తీయడం ఇష్టమా? మీరు సాధారణంగా దేని ఫోటోలు తీస్తారు?","examples":[{"en":"I like taking photos of sunsets because the colours are amazing.","native":"రంగులు అద్భుతంగా ఉంటాయి కాబట్టి సూర్యాస్తమయం ఫోటోలు తీయడం నాకు ఇష్టం."},{"en":"I have taken hundreds of photos on my phone this year.","native":"ఈ సంవత్సరం నా ఫోన్‌లో వందలాది ఫోటోలు తీశాను."},{"en":"Photos help me remember good moments better than my memory does.","native":"నా జ్ఞాపకశక్తి కంటే ఫోటోలు మంచి క్షణాలను గుర్తు చేసుకోవడానికి నాకు బాగా సహాయపడతాయి."}]},"hi":{"word":"फ़ोटोग्राफ़ी","question":"क्या आपको तस्वीरें खींचना पसंद है? आप आमतौर पर किसकी तस्वीरें लेते हैं?","examples":[{"en":"I like taking photos of sunsets because the colours are amazing.","native":"मुझे सूर्यास्त की तस्वीरें लेना पसंद है क्योंकि रंग अद्भुत होते हैं।"},{"en":"I have taken hundreds of photos on my phone this year.","native":"इस साल मैंने अपने फ़ोन पर सैकड़ों तस्वीरें ली हैं।"},{"en":"Photos help me remember good moments better than my memory does.","native":"तस्वीरें मुझे अपनी याददाश्त से बेहतर अच्छे पल याद रखने में मदद करती हैं।"}]},"es":{"word":"fotografía","question":"¿Te gusta hacer fotos? ¿Qué sueles fotografiar?","examples":[{"en":"I like taking photos of sunsets because the colours are amazing.","native":"Me gusta fotografiar atardeceres porque los colores son increíbles."},{"en":"I have taken hundreds of photos on my phone this year.","native":"Este año he hecho cientos de fotos con mi teléfono."},{"en":"Photos help me remember good moments better than my memory does.","native":"Las fotos me ayudan a recordar los buenos momentos mejor que mi memoria."}]},"zh":{"word":"摄影","question":"你喜欢拍照吗？你通常拍什么？","examples":[{"en":"I like taking photos of sunsets because the colours are amazing.","native":"我喜欢拍日落，因为颜色非常美。"},{"en":"I have taken hundreds of photos on my phone this year.","native":"今年我用手机拍了数百张照片。"},{"en":"Photos help me remember good moments better than my memory does.","native":"照片比我的记忆更能帮我记住美好的时刻。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'painting', 'Have you ever tried painting or drawing? Do you think art is important?', '{"te":{"word":"చిత్రలేఖనం","question":"మీరు ఎప్పుడైనా పెయింటింగ్ లేదా డ్రాయింగ్ ప్రయత్నించారా? కళ ముఖ్యమని మీరు అనుకుంటున్నారా?","examples":[{"en":"I painted a picture of my village when I was in school.","native":"నేను స్కూల్లో ఉన్నప్పుడు నా గ్రామం యొక్క చిత్రాన్ని గీశాను."},{"en":"I am not very good at drawing, but I find it calming.","native":"నాకు డ్రాయింగ్ అంతగా రాదు, కానీ అది నాకు ప్రశాంతంగా అనిపిస్తుంది."},{"en":"Art is important because it lets people express their feelings.","native":"కళ ముఖ్యం, ఎందుకంటే అది ప్రజలు తమ భావాలను వ్యక్తం చేసుకోవడానికి వీలు కల్పిస్తుంది."}]},"hi":{"word":"चित्रकारी","question":"क्या आपने कभी चित्रकारी या ड्रॉइंग की कोशिश की है? क्या आपको लगता है कि कला ज़रूरी है?","examples":[{"en":"I painted a picture of my village when I was in school.","native":"जब मैं स्कूल में था, मैंने अपने गाँव का एक चित्र बनाया था।"},{"en":"I am not very good at drawing, but I find it calming.","native":"मैं ड्रॉइंग में बहुत अच्छा नहीं हूँ, लेकिन मुझे इससे शांति मिलती है।"},{"en":"Art is important because it lets people express their feelings.","native":"कला ज़रूरी है क्योंकि इससे लोग अपनी भावनाओं को व्यक्त कर पाते हैं।"}]},"es":{"word":"pintura","question":"¿Has probado alguna vez a pintar o dibujar? ¿Crees que el arte es importante?","examples":[{"en":"I painted a picture of my village when I was in school.","native":"Pinté un cuadro de mi pueblo cuando estaba en el colegio."},{"en":"I am not very good at drawing, but I find it calming.","native":"No se me da muy bien dibujar, pero me resulta relajante."},{"en":"Art is important because it lets people express their feelings.","native":"El arte es importante porque permite a la gente expresar sus sentimientos."}]},"zh":{"word":"绘画","question":"你尝试过绘画或素描吗？你认为艺术重要吗？","examples":[{"en":"I painted a picture of my village when I was in school.","native":"我在上学时画过一幅我村庄的画。"},{"en":"I am not very good at drawing, but I find it calming.","native":"我不太擅长画画，但我觉得它能让我平静。"},{"en":"Art is important because it lets people express their feelings.","native":"艺术很重要，因为它让人们表达自己的情感。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'language', 'Why are you learning English, and how do you practise it?', '{"te":{"word":"భాష","question":"మీరు ఇంగ్లీష్ ఎందుకు నేర్చుకుంటున్నారు, మరియు దానిని ఎలా అభ్యసిస్తున్నారు?","examples":[{"en":"I am learning English because it helps me find better jobs.","native":"ఇంగ్లీష్ నాకు మెరుగైన ఉద్యోగాలు కనుగొనడంలో సహాయపడుతుంది కాబట్టి నేను నేర్చుకుంటున్నాను."},{"en":"I practise speaking with a partner every evening for twenty minutes.","native":"నేను ప్రతి సాయంత్రం ఇరవై నిమిషాలు ఒక భాగస్వామితో మాట్లాడటం అభ్యసిస్తాను."},{"en":"Learning a language is easier when you use it every day.","native":"ప్రతిరోజూ వాడినప్పుడు భాష నేర్చుకోవడం సులభం."}]},"hi":{"word":"भाषा","question":"आप अंग्रेज़ी क्यों सीख रहे हैं, और आप इसका अभ्यास कैसे करते हैं?","examples":[{"en":"I am learning English because it helps me find better jobs.","native":"मैं अंग्रेज़ी इसलिए सीख रहा हूँ क्योंकि इससे मुझे बेहतर नौकरियाँ मिलने में मदद मिलती है।"},{"en":"I practise speaking with a partner every evening for twenty minutes.","native":"मैं हर शाम किसी साथी के साथ बीस मिनट बोलने का अभ्यास करता हूँ।"},{"en":"Learning a language is easier when you use it every day.","native":"जब आप किसी भाषा का रोज़ उपयोग करते हैं, तो उसे सीखना आसान हो जाता है।"}]},"es":{"word":"idioma","question":"¿Por qué estás aprendiendo inglés y cómo lo practicas?","examples":[{"en":"I am learning English because it helps me find better jobs.","native":"Estoy aprendiendo inglés porque me ayuda a encontrar mejores trabajos."},{"en":"I practise speaking with a partner every evening for twenty minutes.","native":"Practico hablando con un compañero cada tarde durante veinte minutos."},{"en":"Learning a language is easier when you use it every day.","native":"Aprender un idioma es más fácil cuando lo usas todos los días."}]},"zh":{"word":"语言","question":"你为什么学英语？你如何练习它？","examples":[{"en":"I am learning English because it helps me find better jobs.","native":"我学英语是因为它能帮我找到更好的工作。"},{"en":"I practise speaking with a partner every evening for twenty minutes.","native":"我每天晚上和搭档练习口语二十分钟。"},{"en":"Learning a language is easier when you use it every day.","native":"当你每天使用一门语言时，学起来就更容易。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'homework', 'Do you think homework is useful for students? How much is too much?', '{"te":{"word":"హోంవర్క్","question":"హోంవర్క్ విద్యార్థులకు ఉపయోగకరమని మీరు అనుకుంటున్నారా? ఎంత అయితే ఎక్కువ?","examples":[{"en":"Homework is useful because it helps students remember their lessons.","native":"హోంవర్క్ విద్యార్థులు తమ పాఠాలను గుర్తుంచుకోవడానికి సహాయపడుతుంది కాబట్టి అది ఉపయోగకరం."},{"en":"However, too much homework leaves no time for play or rest.","native":"అయితే, ఎక్కువ హోంవర్క్ ఆటకు లేదా విశ్రాంతికి సమయం ఇవ్వదు."},{"en":"When I was a student, I finished my homework before dinner.","native":"నేను విద్యార్థిగా ఉన్నప్పుడు, భోజనానికి ముందే నా హోంవర్క్ పూర్తి చేసేవాడిని."}]},"hi":{"word":"होमवर्क","question":"क्या आपको लगता है कि होमवर्क छात्रों के लिए उपयोगी है? कितना होमवर्क बहुत ज़्यादा है?","examples":[{"en":"Homework is useful because it helps students remember their lessons.","native":"होमवर्क उपयोगी है क्योंकि इससे छात्रों को अपने पाठ याद रहते हैं।"},{"en":"However, too much homework leaves no time for play or rest.","native":"हालांकि, बहुत ज़्यादा होमवर्क खेलने या आराम करने का समय नहीं छोड़ता।"},{"en":"When I was a student, I finished my homework before dinner.","native":"जब मैं छात्र था, मैं रात के खाने से पहले अपना होमवर्क खत्म कर लेता था।"}]},"es":{"word":"deberes","question":"¿Crees que los deberes son útiles para los estudiantes? ¿Cuánto es demasiado?","examples":[{"en":"Homework is useful because it helps students remember their lessons.","native":"Los deberes son útiles porque ayudan a los estudiantes a recordar las lecciones."},{"en":"However, too much homework leaves no time for play or rest.","native":"Sin embargo, demasiados deberes no dejan tiempo para jugar ni descansar."},{"en":"When I was a student, I finished my homework before dinner.","native":"Cuando era estudiante, terminaba mis deberes antes de cenar."}]},"zh":{"word":"家庭作业","question":"你认为家庭作业对学生有用吗？多少才算太多？","examples":[{"en":"Homework is useful because it helps students remember their lessons.","native":"家庭作业很有用，因为它帮助学生记住课程内容。"},{"en":"However, too much homework leaves no time for play or rest.","native":"然而，作业太多就没有玩耍和休息的时间了。"},{"en":"When I was a student, I finished my homework before dinner.","native":"当我是学生时，我总是在晚饭前完成作业。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'interview', 'Talk about how you prepare for a job interview and how you feel during it.', '{"te":{"word":"ఇంటర్వ్యూ","question":"ఉద్యోగ ఇంటర్వ్యూకు మీరు ఎలా సిద్ధమవుతారు మరియు అప్పుడు మీకు ఎలా అనిపిస్తుందో మాట్లాడండి.","examples":[{"en":"Before my last interview, I read about the company and practised answers.","native":"నా చివరి ఇంటర్వ్యూకు ముందు, నేను కంపెనీ గురించి చదివి సమాధానాలు అభ్యసించాను."},{"en":"I felt nervous at first, but the interviewer was friendly and calm.","native":"మొదట నాకు టెన్షన్‌గా అనిపించింది, కానీ ఇంటర్వ్యూ చేసినవారు స్నేహపూర్వకంగా మరియు ప్రశాంతంగా ఉన్నారు."},{"en":"Arriving early always makes me more confident than rushing.","native":"త్వరపడటం కంటే ముందుగా చేరుకోవడం వల్ల నాకు ఎల్లప్పుడూ ఎక్కువ ఆత్మవిశ్వాసం వస్తుంది."}]},"hi":{"word":"साक्षात्कार","question":"नौकरी के साक्षात्कार की तैयारी आप कैसे करते हैं और उस दौरान आप कैसा महसूस करते हैं, इस बारे में बताइए।","examples":[{"en":"Before my last interview, I read about the company and practised answers.","native":"अपने पिछले साक्षात्कार से पहले, मैंने कंपनी के बारे में पढ़ा और जवाबों का अभ्यास किया।"},{"en":"I felt nervous at first, but the interviewer was friendly and calm.","native":"शुरू में मैं घबराया हुआ था, लेकिन साक्षात्कारकर्ता दोस्ताना और शांत था।"},{"en":"Arriving early always makes me more confident than rushing.","native":"जल्दबाज़ी करने की तुलना में जल्दी पहुँचने से मुझे हमेशा ज़्यादा आत्मविश्वास होता है।"}]},"es":{"word":"entrevista","question":"Habla de cómo te preparas para una entrevista de trabajo y cómo te sientes durante ella.","examples":[{"en":"Before my last interview, I read about the company and practised answers.","native":"Antes de mi última entrevista, leí sobre la empresa y practiqué respuestas."},{"en":"I felt nervous at first, but the interviewer was friendly and calm.","native":"Al principio estaba nervioso, pero el entrevistador fue amable y tranquilo."},{"en":"Arriving early always makes me more confident than rushing.","native":"Llegar temprano siempre me da más confianza que ir con prisa."}]},"zh":{"word":"面试","question":"谈谈你如何准备求职面试，以及面试时的感受。","examples":[{"en":"Before my last interview, I read about the company and practised answers.","native":"在上次面试之前，我了解了公司情况并练习了回答。"},{"en":"I felt nervous at first, but the interviewer was friendly and calm.","native":"一开始我很紧张，但面试官很友好、很沉着。"},{"en":"Arriving early always makes me more confident than rushing.","native":"提前到达总是比匆忙赶路让我更自信。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'salary', 'What would you do with your first salary? Is saving or spending more important to you?', '{"te":{"word":"జీతం","question":"మీ మొదటి జీతంతో మీరు ఏమి చేస్తారు? మీకు ఆదా చేయడమా ఖర్చు చేయడమా ఏది ముఖ్యం?","examples":[{"en":"With my first salary, I want to buy a gift for my parents.","native":"నా మొదటి జీతంతో, నా తల్లిదండ్రుల కోసం ఒక బహుమతి కొనాలనుకుంటున్నాను."},{"en":"Saving is more important to me because it gives me security.","native":"ఆదా చేయడం నాకు భద్రత ఇస్తుంది కాబట్టి అది నాకు ముఖ్యం."},{"en":"Some people spend everything at once, but I prefer to plan.","native":"కొందరు వెంటనే అంతా ఖర్చు చేస్తారు, కానీ నాకు ప్లాన్ చేసుకోవడం ఇష్టం."}]},"hi":{"word":"वेतन","question":"अपनी पहली सैलरी से आप क्या करेंगे? आपके लिए बचत ज़्यादा ज़रूरी है या खर्च?","examples":[{"en":"With my first salary, I want to buy a gift for my parents.","native":"अपनी पहली सैलरी से मैं अपने माता-पिता के लिए उपहार खरीदना चाहता हूँ।"},{"en":"Saving is more important to me because it gives me security.","native":"मेरे लिए बचत ज़्यादा ज़रूरी है क्योंकि इससे मुझे सुरक्षा मिलती है।"},{"en":"Some people spend everything at once, but I prefer to plan.","native":"कुछ लोग एक साथ सब कुछ खर्च कर देते हैं, लेकिन मैं योजना बनाना पसंद करता हूँ।"}]},"es":{"word":"salario","question":"¿Qué harías con tu primer sueldo? ¿Qué es más importante para ti, ahorrar o gastar?","examples":[{"en":"With my first salary, I want to buy a gift for my parents.","native":"Con mi primer sueldo, quiero comprar un regalo para mis padres."},{"en":"Saving is more important to me because it gives me security.","native":"Ahorrar es más importante para mí porque me da seguridad."},{"en":"Some people spend everything at once, but I prefer to plan.","native":"Algunas personas lo gastan todo de golpe, pero yo prefiero planificar."}]},"zh":{"word":"工资","question":"你会用第一份工资做什么？对你来说存钱和花钱哪个更重要？","examples":[{"en":"With my first salary, I want to buy a gift for my parents.","native":"我想用第一份工资给父母买一份礼物。"},{"en":"Saving is more important to me because it gives me security.","native":"对我来说存钱更重要，因为它给我安全感。"},{"en":"Some people spend everything at once, but I prefer to plan.","native":"有些人会一次花光所有钱，但我更喜欢做好计划。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'savings', 'Do you save money regularly? What are you saving for?', '{"te":{"word":"పొదుపు","question":"మీరు క్రమం తప్పకుండా డబ్బు ఆదా చేస్తారా? మీరు దేని కోసం ఆదా చేస్తున్నారు?","examples":[{"en":"I save a small amount every month for my future studies.","native":"నా భవిష్యత్తు చదువుల కోసం నేను ప్రతి నెల కొంత మొత్తాన్ని ఆదా చేస్తాను."},{"en":"It is hard to save when prices keep rising.","native":"ధరలు పెరుగుతూనే ఉన్నప్పుడు ఆదా చేయడం కష్టం."},{"en":"My grandmother taught me that small savings become big over time.","native":"చిన్న పొదుపులు కాలక్రమే పెద్దవి అవుతాయని నా అమ్మమ్మ నాకు నేర్పింది."}]},"hi":{"word":"बचत","question":"क्या आप नियमित रूप से पैसे बचाते हैं? आप किस लिए बचत कर रहे हैं?","examples":[{"en":"I save a small amount every month for my future studies.","native":"मैं अपनी आगे की पढ़ाई के लिए हर महीने थोड़ी रकम बचाता हूँ।"},{"en":"It is hard to save when prices keep rising.","native":"जब कीमतें लगातार बढ़ती रहें, तो बचत करना कठिन होता है।"},{"en":"My grandmother taught me that small savings become big over time.","native":"मेरी दादी ने मुझे सिखाया कि छोटी बचतें समय के साथ बड़ी हो जाती हैं।"}]},"es":{"word":"ahorros","question":"¿Ahorras dinero regularmente? ¿Para qué estás ahorrando?","examples":[{"en":"I save a small amount every month for my future studies.","native":"Ahorro una pequeña cantidad cada mes para mis estudios futuros."},{"en":"It is hard to save when prices keep rising.","native":"Es difícil ahorrar cuando los precios no dejan de subir."},{"en":"My grandmother taught me that small savings become big over time.","native":"Mi abuela me enseñó que los pequeños ahorros crecen con el tiempo."}]},"zh":{"word":"储蓄","question":"你定期存钱吗？你在为什么存钱？","examples":[{"en":"I save a small amount every month for my future studies.","native":"我每个月存一小笔钱，为将来的学习做准备。"},{"en":"It is hard to save when prices keep rising.","native":"物价不断上涨时，存钱很难。"},{"en":"My grandmother taught me that small savings become big over time.","native":"我的祖母告诉我，小额储蓄日积月累会变成大钱。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'bank', 'Do you prefer using a bank or cash? How do banks help people?', '{"te":{"word":"బ్యాంకు","question":"మీకు బ్యాంకు వాడడమా లేదా నగదు వాడడమా ఏది ఇష్టం? బ్యాంకులు ప్రజలకు ఎలా సహాయపడతాయి?","examples":[{"en":"I prefer my bank card because carrying cash is less safe.","native":"నగదు మోసుకువెళ్లడం తక్కువ భద్రమైనది కాబట్టి నాకు నా బ్యాంకు కార్డే ఇష్టం."},{"en":"Banks help people save money and pay for big things slowly.","native":"బ్యాంకులు ప్రజలు డబ్బు ఆదా చేయడానికి మరియు పెద్ద వస్తువుల కోసం నెమ్మదిగా చెల్లించడానికి సహాయపడతాయి."},{"en":"I opened my first bank account when I started college.","native":"నేను కాలేజీలో చేరినప్పుడు నా మొదటి బ్యాంకు ఖాతా తెరిచాను."}]},"hi":{"word":"बैंक","question":"आप बैंक का उपयोग करना पसंद करते हैं या नकद? बैंक लोगों की कैसे मदद करते हैं?","examples":[{"en":"I prefer my bank card because carrying cash is less safe.","native":"मैं अपना बैंक कार्ड पसंद करता हूँ क्योंकि नकद रखना कम सुरक्षित है।"},{"en":"Banks help people save money and pay for big things slowly.","native":"बैंक लोगों को पैसे बचाने और बड़ी चीज़ों के लिए धीरे-धीरे भुगतान करने में मदद करते हैं।"},{"en":"I opened my first bank account when I started college.","native":"कॉलेज शुरू करते ही मैंने अपना पहला बैंक खाता खुलवाया था।"}]},"es":{"word":"banco","question":"¿Prefieres usar el banco o el efectivo? ¿Cómo ayudan los bancos a la gente?","examples":[{"en":"I prefer my bank card because carrying cash is less safe.","native":"Prefiero mi tarjeta bancaria porque llevar efectivo es menos seguro."},{"en":"Banks help people save money and pay for big things slowly.","native":"Los bancos ayudan a la gente a ahorrar dinero y pagar cosas grandes poco a poco."},{"en":"I opened my first bank account when I started college.","native":"Abrí mi primera cuenta bancaria cuando empecé la universidad."}]},"zh":{"word":"银行","question":"你更喜欢用银行还是现金？银行如何帮助人们？","examples":[{"en":"I prefer my bank card because carrying cash is less safe.","native":"我更喜欢用银行卡，因为带现金不太安全。"},{"en":"Banks help people save money and pay for big things slowly.","native":"银行帮助人们存钱，并能分期购买大件物品。"},{"en":"I opened my first bank account when I started college.","native":"我开始上大学时开了第一个银行账户。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'market', 'Do you like shopping at local markets? How are they different from supermarkets?', '{"te":{"word":"మార్కెట్","question":"మీకు స్థానిక మార్కెట్లలో షాపింగ్ చేయడం ఇష్టమా? అవి సూపర్ మార్కెట్ల నుండి ఎలా భిన్నంగా ఉంటాయి?","examples":[{"en":"I like the local market because the fruit is fresh and cheap.","native":"పండ్లు తాజాగా మరియు చౌకగా ఉంటాయి కాబట్టి స్థానిక మార్కెట్ నాకు ఇష్టం."},{"en":"At the market, you can talk to sellers and bargain a little.","native":"మార్కెట్‌లో, మీరు అమ్మకందార్లతో మాట్లాడవచ్చు మరియు కొంచెం రేటు సర్దుబాటు చేయవచ్చు."},{"en":"Supermarkets are faster, but markets feel more alive.","native":"సూపర్ మార్కెట్లు వేగంగా ఉంటాయి, కానీ మార్కెట్లు మరింత జీవంగా అనిపిస్తాయి."}]},"hi":{"word":"बाज़ार","question":"क्या आपको स्थानीय बाज़ारों में खरीदारी करना पसंद है? वे सुपरमार्केट से कैसे अलग हैं?","examples":[{"en":"I like the local market because the fruit is fresh and cheap.","native":"मुझे स्थानीय बाज़ार पसंद है क्योंकि वहाँ फल ताज़े और सस्ते मिलते हैं।"},{"en":"At the market, you can talk to sellers and bargain a little.","native":"बाज़ार में, आप विक्रेताओं से बात कर सकते हैं और थोड़ा मोलभाव कर सकते हैं।"},{"en":"Supermarkets are faster, but markets feel more alive.","native":"सुपरमार्केट तेज़ होते हैं, लेकिन बाज़ार ज़्यादा जीवंत लगते हैं।"}]},"es":{"word":"mercado","question":"¿Te gusta comprar en los mercados locales? ¿En qué se diferencian de los supermercados?","examples":[{"en":"I like the local market because the fruit is fresh and cheap.","native":"Me gusta el mercado local porque la fruta es fresca y barata."},{"en":"At the market, you can talk to sellers and bargain a little.","native":"En el mercado puedes hablar con los vendedores y regatear un poco."},{"en":"Supermarkets are faster, but markets feel more alive.","native":"Los supermercados son más rápidos, pero los mercados se sienten más vivos."}]},"zh":{"word":"市场","question":"你喜欢在本地市场购物吗？它们和超市有什么不同？","examples":[{"en":"I like the local market because the fruit is fresh and cheap.","native":"我喜欢本地市场，因为水果新鲜又便宜。"},{"en":"At the market, you can talk to sellers and bargain a little.","native":"在市场上，你可以和摊主聊天，还能稍微讨价还价。"},{"en":"Supermarkets are faster, but markets feel more alive.","native":"超市更快，但市场感觉更有生气。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'clothes', 'What kind of clothes do you like to wear? Do you choose comfort or style?', '{"te":{"word":"దుస్తులు","question":"మీరు ఏ రకమైన దుస్తులు ధరించడానికి ఇష్టపడతారు? మీరు సౌకర్యాన్నా లేదా స్టైల్‌నా ఎంచుకుంటారు?","examples":[{"en":"I like simple clothes in dark colours because they match everything.","native":"ముదురు రంగుల్లో సాధారణ దుస్తులు నాకు ఇష్టం, ఎందుకంటే అవి అన్నింటితో సరిపోతాయి."},{"en":"I choose comfort over style when I travel for long hours.","native":"ఎక్కువ గంటలు ప్రయాణించేటప్పుడు నేను స్టైల్ కంటే సౌకర్యాన్నే ఎంచుకుంటాను."},{"en":"For special events, I wear traditional clothes that look elegant.","native":"ప్రత్యేక కార్యక్రమాల్లో, నేను శోభాయమానంగా కనిపించే సాంప్రదాయ దుస్తులు ధరిస్తాను."}]},"hi":{"word":"कपड़े","question":"आप किस तरह के कपड़े पहनना पसंद करते हैं? आप आराम चुनते हैं या स्टाइल?","examples":[{"en":"I like simple clothes in dark colours because they match everything.","native":"मुझे गहरे रंगों के सादे कपड़े पसंद हैं क्योंकि वे हर चीज़ से मेल खाते हैं।"},{"en":"I choose comfort over style when I travel for long hours.","native":"जब मैं लंबी यात्रा करता हूँ, तो स्टाइल की जगह आराम चुनता हूँ।"},{"en":"For special events, I wear traditional clothes that look elegant.","native":"खास मौकों पर, मैं पारंपरिक कपड़े पहनता हूँ जो सुंदर दिखते हैं।"}]},"es":{"word":"ropa","question":"¿Qué tipo de ropa te gusta llevar? ¿Eliges comodidad o estilo?","examples":[{"en":"I like simple clothes in dark colours because they match everything.","native":"Me gusta la ropa sencilla de colores oscuros porque combina con todo."},{"en":"I choose comfort over style when I travel for long hours.","native":"Elijo la comodidad antes que el estilo cuando viajo muchas horas."},{"en":"For special events, I wear traditional clothes that look elegant.","native":"Para eventos especiales, llevo ropa tradicional que se ve elegante."}]},"zh":{"word":"服装","question":"你喜欢穿什么样的衣服？你会选择舒适还是时尚？","examples":[{"en":"I like simple clothes in dark colours because they match everything.","native":"我喜欢深色的简单衣服，因为它们百搭。"},{"en":"I choose comfort over style when I travel for long hours.","native":"长途旅行时，我选择舒适而不是时尚。"},{"en":"For special events, I wear traditional clothes that look elegant.","native":"在特殊场合，我穿看起来很优雅的传统服装。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'shoes', 'How many pairs of shoes do you own? What do you look for when buying shoes?', '{"te":{"word":"బూట్లు","question":"మీ దగ్గర ఎన్ని జోడీ బూట్లు ఉన్నాయి? బూట్లు కొనేటప్పుడు మీరు దేన్ని చూస్తారు?","examples":[{"en":"I own four pairs of shoes for different occasions and weather.","native":"వేర్వేరు సందర్భాలు మరియు వాతావరణం కోసం నా దగ్గర నాలుగు జోడీ బూట్లు ఉన్నాయి."},{"en":"When I buy shoes, comfort matters more to me than brand names.","native":"బూట్లు కొనేటప్పుడు, బ్రాండ్ పేర్ల కంటే సౌకర్యం నాకు ఎక్కువ ముఖ్యం."},{"en":"Good shoes are expensive, but they last much longer.","native":"మంచి బూట్లు ఖరీదైనవి, కానీ అవి చాలా కాలం ఉంటాయి."}]},"hi":{"word":"जूते","question":"आपके पास कितनी जोड़ी जूते हैं? जूते खरीदते समय आप क्या देखते हैं?","examples":[{"en":"I own four pairs of shoes for different occasions and weather.","native":"अलग-अलग मौकों और मौसम के लिए मेरे पास चार जोड़ी जूते हैं।"},{"en":"When I buy shoes, comfort matters more to me than brand names.","native":"जूते खरीदते समय, मेरे लिए ब्रांड के नाम से ज़्यादा आराम मायने रखता है।"},{"en":"Good shoes are expensive, but they last much longer.","native":"अच्छे जूते महँगे होते हैं, लेकिन वे बहुत लंबे समय तक चलते हैं।"}]},"es":{"word":"zapatos","question":"¿Cuántos pares de zapatos tienes? ¿Qué buscas al comprar zapatos?","examples":[{"en":"I own four pairs of shoes for different occasions and weather.","native":"Tengo cuatro pares de zapatos para distintas ocasiones y climas."},{"en":"When I buy shoes, comfort matters more to me than brand names.","native":"Al comprar zapatos, la comodidad me importa más que las marcas."},{"en":"Good shoes are expensive, but they last much longer.","native":"Los buenos zapatos son caros, pero duran mucho más."}]},"zh":{"word":"鞋子","question":"你有几双鞋？买鞋时你看重什么？","examples":[{"en":"I own four pairs of shoes for different occasions and weather.","native":"我有四双鞋，适合不同场合和天气。"},{"en":"When I buy shoes, comfort matters more to me than brand names.","native":"买鞋时，舒适对我来说比品牌更重要。"},{"en":"Good shoes are expensive, but they last much longer.","native":"好鞋很贵，但耐穿得多。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'haircut', 'How often do you get a haircut? Do you like trying new styles?', '{"te":{"word":"జుట్టు కత్తిరింపు","question":"మీరు ఎంత తరచుగా జుట్టు కత్తిరించుకుంటారు? కొత్త స్టైల్‌లు ప్రయత్నించడం మీకు ఇష్టమా?","examples":[{"en":"I get a haircut every six weeks at the same small salon.","native":"నేను ప్రతి ఆరు వారాలకు అదే చిన్న సెలూన్‌లో జుట్టు కత్తిరించుకుంటాను."},{"en":"I once tried a very short style, but I did not like it.","native":"ఒకసారి నేను చాలా పొట్టి స్టైల్ ప్రయత్నించాను, కానీ నాకు నచ్చలేదు."},{"en":"My barber knows exactly how I want my hair, so I trust him.","native":"నాకు జుట్టు ఎలా కావాలో నా బార్బర్‌కు సరిగ్గా తెలుసు, కాబట్టి నేను అతనిని నమ్ముతాను."}]},"hi":{"word":"बाल कटवाना","question":"आप कितनी बार बाल कटवाते हैं? क्या आपको नई स्टाइल आज़माना पसंद है?","examples":[{"en":"I get a haircut every six weeks at the same small salon.","native":"मैं हर छह हफ़्ते में उसी छोटे सैलून में बाल कटवाता हूँ।"},{"en":"I once tried a very short style, but I did not like it.","native":"मैंने एक बार बहुत छोटी स्टाइल आज़माई थी, लेकिन मुझे पसंद नहीं आई।"},{"en":"My barber knows exactly how I want my hair, so I trust him.","native":"मेरे नाई को पता है कि मुझे बाल कैसे चाहिए, इसलिए मैं उस पर भरोसा करता हूँ।"}]},"es":{"word":"corte de pelo","question":"¿Con qué frecuencia te cortas el pelo? ¿Te gusta probar nuevos estilos?","examples":[{"en":"I get a haircut every six weeks at the same small salon.","native":"Me corto el pelo cada seis semanas en la misma peluquería pequeña."},{"en":"I once tried a very short style, but I did not like it.","native":"Una vez probé un estilo muy corto, pero no me gustó."},{"en":"My barber knows exactly how I want my hair, so I trust him.","native":"Mi peluquero sabe exactamente cómo quiero el pelo, así que confío en él."}]},"zh":{"word":"理发","question":"你多久理一次发？你喜欢尝试新发型吗？","examples":[{"en":"I get a haircut every six weeks at the same small salon.","native":"我每六周在同一家小理发店理发。"},{"en":"I once tried a very short style, but I did not like it.","native":"我曾经试过一次很短的发型，但我不喜欢。"},{"en":"My barber knows exactly how I want my hair, so I trust him.","native":"我的理发师很清楚我想要什么发型，所以我很信任他。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'doctor', 'When did you last visit a doctor? How can people take better care of their health?', '{"te":{"word":"డాక్టర్","question":"మీరు చివరిసారిగా ఎప్పుడు డాక్టర్ దగ్గరికి వెళ్లారు? ప్రజలు తమ ఆరోగ్యాన్ని ఎలా బాగు చేసుకోవచ్చు?","examples":[{"en":"I last visited a doctor six months ago for a bad cold.","native":"నేను ఆరు నెలల క్రితం తీవ్రమైన జలుబు కోసం చివరిసారిగా డాక్టర్ దగ్గరికి వెళ్లాను."},{"en":"People can stay healthier by eating well and sleeping enough.","native":"బాగా తినడం మరియు సరిపోయేంత నిద్రపోవడం ద్వారా ప్రజలు మరింత ఆరోగ్యంగా ఉండవచ్చు."},{"en":"My doctor advised me to drink more water and walk daily.","native":"నా డాక్టర్ ఎక్కువ నీళ్లు తాగమని మరియు ప్రతిరోజూ నడవమని నాకు సలహా ఇచ్చారు."}]},"hi":{"word":"डॉक्टर","question":"आप आख़िरी बार डॉक्टर के पास कब गए थे? लोग अपने स्वास्थ्य की बेहतर देखभाल कैसे कर सकते हैं?","examples":[{"en":"I last visited a doctor six months ago for a bad cold.","native":"मैं आख़िरी बार छह महीने पहले ज़ुकाम के कारण डॉक्टर के पास गया था।"},{"en":"People can stay healthier by eating well and sleeping enough.","native":"लोग अच्छा खाकर और पर्याप्त नींद लेकर ज़्यादा स्वस्थ रह सकते हैं।"},{"en":"My doctor advised me to drink more water and walk daily.","native":"मेरे डॉक्टर ने मुझे ज़्यादा पानी पीने और रोज़ टहलने की सलाह दी।"}]},"es":{"word":"médico","question":"¿Cuándo fue la última vez que fuiste al médico? ¿Cómo puede la gente cuidar mejor su salud?","examples":[{"en":"I last visited a doctor six months ago for a bad cold.","native":"La última vez que fui al médico fue hace seis meses por un resfriado fuerte."},{"en":"People can stay healthier by eating well and sleeping enough.","native":"La gente puede estar más sana comiendo bien y durmiendo lo suficiente."},{"en":"My doctor advised me to drink more water and walk daily.","native":"Mi médico me aconsejó beber más agua y caminar a diario."}]},"zh":{"word":"医生","question":"你上次看医生是什么时候？人们如何更好地照顾自己的健康？","examples":[{"en":"I last visited a doctor six months ago for a bad cold.","native":"我上次看医生是六个月前，因为重感冒。"},{"en":"People can stay healthier by eating well and sleeping enough.","native":"人们可以通过吃得好、睡得足来保持健康。"},{"en":"My doctor advised me to drink more water and walk daily.","native":"我的医生建议我多喝水、每天散步。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'hospital', 'Have you ever stayed in a hospital or visited someone there? Describe the experience.', '{"te":{"word":"ఆసుపత్రి","question":"మీరు ఎప్పుడైనా ఆసుపత్రిలో ఉన్నారా లేదా అక్కడ ఎవరినైనా సందర్శించారా? ఆ అనుభవాన్ని వివరించండి.","examples":[{"en":"I visited my grandmother in hospital when she broke her leg.","native":"నా అమ్మమ్మ కాలు విరిగినప్పుడు ఆసుపత్రిలో ఆమెను సందర్శించాను."},{"en":"The nurses were kind, and they explained everything to our family.","native":"నర్సులు దయగా ఉండి, ప్రతిదీ మా కుటుంబానికి వివరించారు."},{"en":"Hospitals can feel scary, but the workers there help people every day.","native":"ఆసుపత్రులు భయంకరంగా అనిపించవచ్చు, కానీ అక్కడి సిబ్బంది ప్రతిరోజూ ప్రజలకు సహాయపడతారు."}]},"hi":{"word":"अस्पताल","question":"क्या आप कभी अस्पताल में रहे हैं या वहाँ किसी से मिलने गए हैं? उस अनुभव का वर्णन कीजिए।","examples":[{"en":"I visited my grandmother in hospital when she broke her leg.","native":"जब मेरी दादी के पैर में फ्रैक्चर हुआ, तब मैं उन्हें अस्पताल में देखने गया।"},{"en":"The nurses were kind, and they explained everything to our family.","native":"नर्सें बहुत दयालु थीं, और उन्होंने हमारे परिवार को सब कुछ समझाया।"},{"en":"Hospitals can feel scary, but the workers there help people every day.","native":"अस्पताल डरावने लग सकते हैं, लेकिन वहाँ के कर्मचारी रोज़ लोगों की मदद करते हैं।"}]},"es":{"word":"hospital","question":"¿Has estado alguna vez en un hospital o has visitado a alguien allí? Describe la experiencia.","examples":[{"en":"I visited my grandmother in hospital when she broke her leg.","native":"Visité a mi abuela en el hospital cuando se rompió la pierna."},{"en":"The nurses were kind, and they explained everything to our family.","native":"Las enfermeras fueron amables y nos explicaron todo a la familia."},{"en":"Hospitals can feel scary, but the workers there help people every day.","native":"Los hospitales pueden dar miedo, pero quienes trabajan allí ayudan a la gente cada día."}]},"zh":{"word":"医院","question":"你住过医院或去那里探望过病人吗？描述一下那次经历。","examples":[{"en":"I visited my grandmother in hospital when she broke her leg.","native":"祖母摔断腿时，我去医院探望过她。"},{"en":"The nurses were kind, and they explained everything to our family.","native":"护士们很亲切，向我们全家解释了所有情况。"},{"en":"Hospitals can feel scary, but the workers there help people every day.","native":"医院可能让人觉得害怕，但那里的工作人员每天都在帮助人们。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'medicine', 'Do you take medicine when you are ill, or do you prefer home remedies? Why?', '{"te":{"word":"ఔషధం","question":"మీకు జబ్బు చేసినప్పుడు మందులు తీసుకుంటారా లేదా ఇంటి వైద్యం ఇష్టపడతారా? ఎందుకు?","examples":[{"en":"For a normal cold, I prefer hot soup and rest instead of medicine.","native":"సాధారణ జలుబుకు, మందుల బదులు వేడి సూప్ మరియు విశ్రాంతిని నేను ఇష్టపడతాను."},{"en":"But when I have a high fever, I always see a doctor.","native":"కానీ నాకు తీవ్రమైన జ్వరం వచ్చినప్పుడు, నేను ఎల్లప్పుడూ డాక్టర్‌ను చూస్తాను."},{"en":"My mother makes a special ginger drink that works better than tablets.","native":"నా అమ్మ ట్యాబ్లెట్ల కంటే బాగా పనిచేసే ప్రత్యేక అల్లం డ్రింక్ తయారుచేస్తుంది."}]},"hi":{"word":"दवा","question":"बीमार होने पर आप दवा लेते हैं या घरेलू नुस्खे पसंद करते हैं? क्यों?","examples":[{"en":"For a normal cold, I prefer hot soup and rest instead of medicine.","native":"सामान्य ज़ुकाम के लिए, मैं दवा के बजाय गर्म सूप और आराम पसंद करता हूँ।"},{"en":"But when I have a high fever, I always see a doctor.","native":"लेकिन जब मुझे तेज़ बुखार होता है, मैं हमेशा डॉक्टर को दिखाता हूँ।"},{"en":"My mother makes a special ginger drink that works better than tablets.","native":"मेरी माँ एक खास अदरक का पेय बनाती है जो गोलियों से बेहतर काम करता है।"}]},"es":{"word":"medicina","question":"¿Tomas medicinas cuando estás enfermo o prefieres remedios caseros? ¿Por qué?","examples":[{"en":"For a normal cold, I prefer hot soup and rest instead of medicine.","native":"Para un resfriado normal, prefiero sopa caliente y descanso en lugar de medicinas."},{"en":"But when I have a high fever, I always see a doctor.","native":"Pero cuando tengo fiebre alta, siempre voy al médico."},{"en":"My mother makes a special ginger drink that works better than tablets.","native":"Mi madre prepara una bebida especial de jengibre que funciona mejor que las pastillas."}]},"zh":{"word":"药物","question":"生病时你吃药还是更喜欢家庭疗法？为什么？","examples":[{"en":"For a normal cold, I prefer hot soup and rest instead of medicine.","native":"普通感冒时，我更喜欢喝热汤和休息，而不是吃药。"},{"en":"But when I have a high fever, I always see a doctor.","native":"但发高烧时，我总是去看医生。"},{"en":"My mother makes a special ginger drink that works better than tablets.","native":"我妈妈会泡一种特别的姜茶，比药片还管用。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'exercise', 'What is your favourite way to exercise, and how do you stay motivated?', '{"te":{"word":"వ్యాయామం","question":"వ్యాయామం చేయడానికి మీకు ఇష్టమైన మార్గం ఏది, మరియు మీరు ఎలా ప్రేరణ పొందుతారు?","examples":[{"en":"My favourite exercise is swimming because it uses the whole body.","native":"నా ఇష్టమైన వ్యాయామం ఈత, ఎందుకంటే అది శరీరం మొత్తాన్ని వాడుతుంది."},{"en":"I stay motivated by exercising with a friend every morning.","native":"ప్రతి ఉదయం ఒక స్నేహితుడితో వ్యాయామం చేయడం ద్వారా నేను ప్రేరణ పొందుతాను."},{"en":"When I skip exercise for a week, I feel slower and less happy.","native":"ఒక వారం వ్యాయామం మానేసినప్పుడు, నాకు నెమ్మదిగా మరియు తక్కువ సంతోషంగా అనిపిస్తుంది."}]},"hi":{"word":"व्यायाम","question":"व्यायाम करने का आपका पसंदीदा तरीका क्या है, और आप प्रेरित कैसे रहते हैं?","examples":[{"en":"My favourite exercise is swimming because it uses the whole body.","native":"मेरा पसंदीदा व्यायाम तैरना है क्योंकि इससे पूरे शरीर की कसरत होती है।"},{"en":"I stay motivated by exercising with a friend every morning.","native":"मैं हर सुबह एक दोस्त के साथ व्यायाम करके प्रेरित रहता हूँ।"},{"en":"When I skip exercise for a week, I feel slower and less happy.","native":"जब मैं एक हफ़्ते के लिए व्यायाम छोड़ देता हूँ, तो मैं सुस्त और कम खुश महसूस करता हूँ।"}]},"es":{"word":"ejercicio","question":"¿Cuál es tu forma favorita de hacer ejercicio y cómo te mantienes motivado?","examples":[{"en":"My favourite exercise is swimming because it uses the whole body.","native":"Mi ejercicio favorito es nadar porque usa todo el cuerpo."},{"en":"I stay motivated by exercising with a friend every morning.","native":"Me mantengo motivado haciendo ejercicio con un amigo cada mañana."},{"en":"When I skip exercise for a week, I feel slower and less happy.","native":"Cuando dejo de hacer ejercicio una semana, me siento más lento y menos feliz."}]},"zh":{"word":"锻炼","question":"你最喜欢的锻炼方式是什么？你如何保持动力？","examples":[{"en":"My favourite exercise is swimming because it uses the whole body.","native":"我最喜欢的锻炼方式是游泳，因为它锻炼全身。"},{"en":"I stay motivated by exercising with a friend every morning.","native":"我通过每天早上和朋友一起锻炼来保持动力。"},{"en":"When I skip exercise for a week, I feel slower and less happy.","native":"当我一周不锻炼时，我会感觉更迟钝、更不开心。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'running', 'Do you enjoy running? Where and when do you usually run?', '{"te":{"word":"పరుగు","question":"మీకు పరుగెత్తడం ఇష్టమా? మీరు సాధారణంగా ఎక్కడ మరియు ఎప్పుడు పరుగెత్తుతారు?","examples":[{"en":"I run in the park every morning before the sun gets too hot.","native":"ఎండ ఎక్కువగా ముందు నేను ప్రతి ఉదయం పార్కులో పరుగెత్తుతాను."},{"en":"Running is cheaper than a gym because you only need good shoes.","native":"మంచి బూట్లు మాత్రమే అవసరం కాబట్టి పరుగెత్తడం జిమ్ కంటే చౌక."},{"en":"At first I could only run one kilometre, but now I run five.","native":"మొదట నేను ఒక కిలోమీటరు మాత్రమే పరుగెత్తగలిగేవాడిని, కానీ ఇప్పుడు ఐదు పరుగెత్తుతాను."}]},"hi":{"word":"दौड़ना","question":"क्या आपको दौड़ना पसंद है? आप आमतौर पर कहाँ और कब दौड़ते हैं?","examples":[{"en":"I run in the park every morning before the sun gets too hot.","native":"धूप तेज़ होने से पहले मैं हर सुबह पार्क में दौड़ता हूँ।"},{"en":"Running is cheaper than a gym because you only need good shoes.","native":"दौड़ना जिम से सस्ता है क्योंकि इसके लिए बस अच्छे जूते चाहिए।"},{"en":"At first I could only run one kilometre, but now I run five.","native":"शुरू में मैं सिर्फ़ एक किलोमीटर दौड़ पाता था, लेकिन अब पाँच दौड़ता हूँ।"}]},"es":{"word":"correr","question":"¿Te gusta correr? ¿Dónde y cuándo sueles correr?","examples":[{"en":"I run in the park every morning before the sun gets too hot.","native":"Corro en el parque cada mañana antes de que el sol caliente demasiado."},{"en":"Running is cheaper than a gym because you only need good shoes.","native":"Correr es más barato que un gimnasio porque solo necesitas buenos zapatos."},{"en":"At first I could only run one kilometre, but now I run five.","native":"Al principio solo podía correr un kilómetro, pero ahora corro cinco."}]},"zh":{"word":"跑步","question":"你喜欢跑步吗？你通常在哪里、什么时候跑步？","examples":[{"en":"I run in the park every morning before the sun gets too hot.","native":"我每天早晨趁太阳不太热时在公园跑步。"},{"en":"Running is cheaper than a gym because you only need good shoes.","native":"跑步比去健身房便宜，因为只需要一双好鞋。"},{"en":"At first I could only run one kilometre, but now I run five.","native":"起初我只能跑一公里，但现在我能跑五公里。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'football', 'Do you watch or play football? Why is it so popular around the world?', '{"te":{"word":"ఫుట్‌బాల్","question":"మీరు ఫుట్‌బాల్ చూస్తారా లేదా ఆడతారా? అది ప్రపంచవ్యాప్తంగా ఎందుకు అంత ప్రసిద్ధం?","examples":[{"en":"I play football with my friends every Saturday in the field.","native":"నేను ప్రతి శనివారం మైదానంలో నా స్నేహితులతో ఫుట్‌బాల్ ఆడుతాను."},{"en":"Football is popular because anyone can play it with just a ball.","native":"కేవలం ఒక బంతితో ఎవరైనా ఆడగలరు కాబట్టి ఫుట్‌బాల్ ప్రసిద్ధం."},{"en":"When my team scores a goal, the whole crowd shouts with joy.","native":"నా జట్టు గోల్ చేసినప్పుడు, జనం మొత్తం ఆనందంతో అరుస్తారు."}]},"hi":{"word":"फ़ुटबॉल","question":"क्या आप फ़ुटबॉल देखते हैं या खेलते हैं? यह दुनिया भर में इतना लोकप्रिय क्यों है?","examples":[{"en":"I play football with my friends every Saturday in the field.","native":"मैं हर शनिवार मैदान में अपने दोस्तों के साथ फ़ुटबॉल खेलता हूँ।"},{"en":"Football is popular because anyone can play it with just a ball.","native":"फ़ुटबॉल लोकप्रिय है क्योंकि सिर्फ़ एक गेंद से कोई भी इसे खेल सकता है।"},{"en":"When my team scores a goal, the whole crowd shouts with joy.","native":"जब मेरी टीम गोल करती है, तो पूरी भीड़ खुशी से चिल्लाती है।"}]},"es":{"word":"fútbol","question":"¿Ves o juegas al fútbol? ¿Por qué es tan popular en todo el mundo?","examples":[{"en":"I play football with my friends every Saturday in the field.","native":"Juego al fútbol con mis amigos todos los sábados en el campo."},{"en":"Football is popular because anyone can play it with just a ball.","native":"El fútbol es popular porque cualquiera puede jugarlo solo con un balón."},{"en":"When my team scores a goal, the whole crowd shouts with joy.","native":"Cuando mi equipo marca un gol, toda la multitud grita de alegría."}]},"zh":{"word":"足球","question":"你看足球还是踢足球？为什么它在全世界如此受欢迎？","examples":[{"en":"I play football with my friends every Saturday in the field.","native":"我每周六都和朋友们在球场上踢足球。"},{"en":"Football is popular because anyone can play it with just a ball.","native":"足球很受欢迎，因为只要有一个球，任何人都能踢。"},{"en":"When my team scores a goal, the whole crowd shouts with joy.","native":"当我的球队进球时，全场观众都会欢呼。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'cricket', 'Is cricket popular in your country? Talk about a match you remember.', '{"te":{"word":"క్రికెట్","question":"మీ దేశంలో క్రికెట్ ప్రసిద్ధమా? మీకు గుర్తున్న ఒక మ్యాచ్ గురించి మాట్లాడండి.","examples":[{"en":"Cricket is the most loved sport in my country.","native":"క్రికెట్ నా దేశంలో అత్యంత ప్రియమైన క్రీడ."},{"en":"I remember a match where our team won in the last over.","native":"మా జట్టు చివరి ఓవర్‌లో గెలిచిన ఒక మ్యాచ్ నాకు గుర్తుంది."},{"en":"During big matches, the streets are empty because everyone is watching.","native":"పెద్ద మ్యాచ్‌ల సమయంలో, అందరూ చూస్తున్నారు కాబట్టి వీధులు ఖాళీగా ఉంటాయి."}]},"hi":{"word":"क्रिकेट","question":"क्या आपके देश में क्रिकेट लोकप्रिय है? किसी यादगार मैच के बारे में बताइए।","examples":[{"en":"Cricket is the most loved sport in my country.","native":"क्रिकेट मेरे देश में सबसे पसंद किया जाने वाला खेल है।"},{"en":"I remember a match where our team won in the last over.","native":"मुझे एक ऐसा मैच याद है जिसमें हमारी टीम आख़िरी ओवर में जीती थी।"},{"en":"During big matches, the streets are empty because everyone is watching.","native":"बड़े मैचों के दौरान सड़कें खाली रहती हैं क्योंकि सब मैच देख रहे होते हैं।"}]},"es":{"word":"críquet","question":"¿Es popular el críquet en tu país? Habla de un partido que recuerdes.","examples":[{"en":"Cricket is the most loved sport in my country.","native":"El críquet es el deporte más querido de mi país."},{"en":"I remember a match where our team won in the last over.","native":"Recuerdo un partido en el que nuestro equipo ganó en el último over."},{"en":"During big matches, the streets are empty because everyone is watching.","native":"Durante los grandes partidos, las calles están vacías porque todos están mirando."}]},"zh":{"word":"板球","question":"板球在你的国家流行吗？谈谈你记得的一场比赛。","examples":[{"en":"Cricket is the most loved sport in my country.","native":"板球是我国最受欢迎的运动。"},{"en":"I remember a match where our team won in the last over.","native":"我记得有一场比赛，我们队在最后一局获胜。"},{"en":"During big matches, the streets are empty because everyone is watching.","native":"大赛期间，街道上空无一人，因为大家都在看比赛。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'yoga', 'Have you ever tried yoga? Why do so many people practise it?', '{"te":{"word":"యోగా","question":"మీరు ఎప్పుడైనా యోగా ప్రయత్నించారా? చాలా మంది దానిని ఎందుకు అభ్యసిస్తారు?","examples":[{"en":"I tried yoga last year, and now I practise it twice a week.","native":"నేను గత సంవత్సరం యోగా ప్రయత్నించాను, ఇప్పుడు వారానికి రెండుసార్లు అభ్యసిస్తాను."},{"en":"People do yoga because it makes the body strong and the mind calm.","native":"యోగా శరీరాన్ని బలంగా మరియు మనస్సును ప్రశాంతంగా చేస్తుంది కాబట్టి ప్రజలు దాన్ని చేస్తారు."},{"en":"Yoga is slower than other sports, but it is harder than it looks.","native":"యోగా ఇతర క్రీడల కంటే నెమ్మదిగా ఉంటుంది, కానీ అది కనిపించినంత సులభం కాదు."}]},"hi":{"word":"योग","question":"क्या आपने कभी योग किया है? इतने सारे लोग इसे क्यों करते हैं?","examples":[{"en":"I tried yoga last year, and now I practise it twice a week.","native":"मैंने पिछले साल योग आज़माया, और अब मैं हफ़्ते में दो बार इसका अभ्यास करता हूँ।"},{"en":"People do yoga because it makes the body strong and the mind calm.","native":"लोग योग करते हैं क्योंकि इससे शरीर मज़बूत और मन शांत होता है।"},{"en":"Yoga is slower than other sports, but it is harder than it looks.","native":"योग अन्य खेलों से धीमा है, लेकिन यह दिखने में जितना आसान लगता है, उतना आसान नहीं है।"}]},"es":{"word":"yoga","question":"¿Has probado el yoga alguna vez? ¿Por qué tanta gente lo practica?","examples":[{"en":"I tried yoga last year, and now I practise it twice a week.","native":"Probé el yoga el año pasado y ahora lo practico dos veces por semana."},{"en":"People do yoga because it makes the body strong and the mind calm.","native":"La gente hace yoga porque fortalece el cuerpo y calma la mente."},{"en":"Yoga is slower than other sports, but it is harder than it looks.","native":"El yoga es más lento que otros deportes, pero es más difícil de lo que parece."}]},"zh":{"word":"瑜伽","question":"你试过瑜伽吗？为什么这么多人练习瑜伽？","examples":[{"en":"I tried yoga last year, and now I practise it twice a week.","native":"我去年开始尝试瑜伽，现在每周练习两次。"},{"en":"People do yoga because it makes the body strong and the mind calm.","native":"人们练瑜伽是因为它能让身体强壮、心灵平静。"},{"en":"Yoga is slower than other sports, but it is harder than it looks.","native":"瑜伽比其他运动慢，但比看起来要难。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'meditation', 'Do you meditate or take quiet time for yourself? How does it help?', '{"te":{"word":"ధ్యానం","question":"మీరు ధ్యానం చేస్తారా లేదా మీ కోసం ప్రశాంతమైన సమయం కేటాయిస్తారా? అది ఎలా సహాయపడుతుంది?","examples":[{"en":"I sit quietly for ten minutes every morning before I start work.","native":"నేను పని ప్రారంభించే ముందు ప్రతి ఉదయం పది నిమిషాలు ప్రశాంతంగా కూర్చుంటాను."},{"en":"Meditation helps me worry less and sleep better at night.","native":"ధ్యానం నాకు తక్కువ ఆందోళన చెందడానికి మరియు రాత్రి బాగా నిద్రపోవడానికి సహాయపడుతుంది."},{"en":"It was boring at first, but now I look forward to it.","native":"మొదట అది విసుగ్గా అనిపించింది, కానీ ఇప్పుడు నేను దాని కోసం ఎదురుచూస్తాను."}]},"hi":{"word":"ध्यान","question":"क्या आप ध्यान करते हैं या अपने लिए शांत समय निकालते हैं? इससे कैसे मदद मिलती है?","examples":[{"en":"I sit quietly for ten minutes every morning before I start work.","native":"मैं काम शुरू करने से पहले हर सुबह दस मिनट शांति से बैठता हूँ।"},{"en":"Meditation helps me worry less and sleep better at night.","native":"ध्यान से मैं कम चिंता करता हूँ और रात में बेहतर नींद आती है।"},{"en":"It was boring at first, but now I look forward to it.","native":"शुरू में यह उबाऊ लगता था, लेकिन अब मैं इसका इंतज़ार करता हूँ।"}]},"es":{"word":"meditación","question":"¿Meditas o te tomas un tiempo tranquilo para ti? ¿Cómo te ayuda?","examples":[{"en":"I sit quietly for ten minutes every morning before I start work.","native":"Me siento en silencio diez minutos cada mañana antes de empezar a trabajar."},{"en":"Meditation helps me worry less and sleep better at night.","native":"La meditación me ayuda a preocuparme menos y a dormir mejor por la noche."},{"en":"It was boring at first, but now I look forward to it.","native":"Al principio era aburrido, pero ahora lo espero con ganas."}]},"zh":{"word":"冥想","question":"你冥想或给自己留安静的时间吗？这有什么帮助？","examples":[{"en":"I sit quietly for ten minutes every morning before I start work.","native":"我每天开始工作前安静地坐十分钟。"},{"en":"Meditation helps me worry less and sleep better at night.","native":"冥想帮助我减少焦虑，晚上睡得更好。"},{"en":"It was boring at first, but now I look forward to it.","native":"一开始很无聊，但现在我很期待这段时间。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'sleep', 'How many hours do you sleep each night? What helps you sleep well?', '{"te":{"word":"నిద్ర","question":"మీరు ప్రతి రాత్రి ఎన్ని గంటలు నిద్రపోతారు? బాగా నిద్రపోవడానికి ఏమి సహాయపడుతుంది?","examples":[{"en":"I sleep about seven hours a night, which is enough for me.","native":"నేను రాత్రికి సుమారు ఏడు గంటలు నిద్రపోతాను, అది నాకు సరిపోతుంది."},{"en":"Reading a book helps me fall asleep faster than watching my phone.","native":"ఫోన్ చూడటం కంటే పుస్తకం చదవడం నాకు త్వరగా నిద్రపట్టడానికి సహాయపడుతుంది."},{"en":"When I sleep badly, I cannot concentrate the next day.","native":"నేను బాగా నిద్రపోనప్పుడు, మరుసటి రోజు కాన్సన్ట్రేట్ చేయలేను."}]},"hi":{"word":"नींद","question":"आप हर रात कितने घंटे सोते हैं? अच्छी नींद के लिए क्या मदद करता है?","examples":[{"en":"I sleep about seven hours a night, which is enough for me.","native":"मैं रात में लगभग सात घंटे सोता हूँ, जो मेरे लिए काफ़ी है।"},{"en":"Reading a book helps me fall asleep faster than watching my phone.","native":"फ़ोन देखने की तुलना में किताब पढ़ने से मुझे जल्दी नींद आती है।"},{"en":"When I sleep badly, I cannot concentrate the next day.","native":"जब मैं ठीक से नहीं सोता, तो अगले दिन मैं ध्यान नहीं लगा पाता।"}]},"es":{"word":"sueño","question":"¿Cuántas horas duermes cada noche? ¿Qué te ayuda a dormir bien?","examples":[{"en":"I sleep about seven hours a night, which is enough for me.","native":"Duermo unas siete horas por noche, lo que es suficiente para mí."},{"en":"Reading a book helps me fall asleep faster than watching my phone.","native":"Leer un libro me ayuda a dormirme más rápido que mirar el teléfono."},{"en":"When I sleep badly, I cannot concentrate the next day.","native":"Cuando duermo mal, no puedo concentrarme al día siguiente."}]},"zh":{"word":"睡眠","question":"你每晚睡几个小时？什么能帮助你睡得好？","examples":[{"en":"I sleep about seven hours a night, which is enough for me.","native":"我每晚大约睡七个小时，这对我来说足够了。"},{"en":"Reading a book helps me fall asleep faster than watching my phone.","native":"读书比看手机更能帮我快速入睡。"},{"en":"When I sleep badly, I cannot concentrate the next day.","native":"睡不好时，我第二天就无法集中注意力。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'breakfast', 'What do you usually eat for breakfast? Do you think it is an important meal?', '{"te":{"word":"అల్పాహారం","question":"మీరు సాధారణంగా అల్పాహారంగా ఏమి తింటారు? అది ముఖ్యమైన భోజనమని మీరు అనుకుంటున్నారా?","examples":[{"en":"I usually eat eggs and bread with a glass of milk for breakfast.","native":"నేను సాధారణంగా అల్పాహారంగా గుడ్లు మరియు బ్రెడ్ తో పాటు ఒక గ్లాసు పాలు తింటాను."},{"en":"Breakfast is important because it gives me energy for the morning.","native":"అల్పాహారం నాకు ఉదయం శక్తిని ఇస్తుంది కాబట్టి అది ముఖ్యం."},{"en":"When I skip breakfast, I feel hungry and tired before lunch.","native":"నేను అల్పాహారం మానేసినప్పుడు, మధ్యాహ్నానికి ముందే ఆకలిగా మరియు అలసటగా అనిపిస్తుంది."}]},"hi":{"word":"नाश्ता","question":"आप नाश्ते में आमतौर पर क्या खाते हैं? क्या आपको लगता है कि यह एक ज़रूरी भोजन है?","examples":[{"en":"I usually eat eggs and bread with a glass of milk for breakfast.","native":"मैं नाश्ते में आमतौर पर अंडे और ब्रेड के साथ एक गिलास दूध खाता हूँ।"},{"en":"Breakfast is important because it gives me energy for the morning.","native":"नाश्ता ज़रूरी है क्योंकि इससे मुझे सुबह के लिए ऊर्जा मिलती है।"},{"en":"When I skip breakfast, I feel hungry and tired before lunch.","native":"जब मैं नाश्ता छोड़ देता हूँ, तो दोपहर के खाने से पहले ही भूख और थकान महसूस होती है।"}]},"es":{"word":"desayuno","question":"¿Qué desayunas normalmente? ¿Crees que es una comida importante?","examples":[{"en":"I usually eat eggs and bread with a glass of milk for breakfast.","native":"Normalmente desayuno huevos con pan y un vaso de leche."},{"en":"Breakfast is important because it gives me energy for the morning.","native":"El desayuno es importante porque me da energía para la mañana."},{"en":"When I skip breakfast, I feel hungry and tired before lunch.","native":"Cuando me salto el desayuno, tengo hambre y me siento cansado antes de comer."}]},"zh":{"word":"早餐","question":"你早餐通常吃什么？你认为这是一顿重要的饭吗？","examples":[{"en":"I usually eat eggs and bread with a glass of milk for breakfast.","native":"我早餐通常吃鸡蛋和面包，配一杯牛奶。"},{"en":"Breakfast is important because it gives me energy for the morning.","native":"早餐很重要，因为它给我上午的能量。"},{"en":"When I skip breakfast, I feel hungry and tired before lunch.","native":"当我不吃早餐时，午饭前就会感到又饿又累。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'tea', 'Do you drink tea? How is tea prepared and enjoyed in your region?', '{"te":{"word":"టీ","question":"మీరు టీ తాగుతారా? మీ ప్రాంతంలో టీ ఎలా తయారుచేసి ఆస్వాదిస్తారు?","examples":[{"en":"I drink two cups of tea every day, one in the morning and one at five.","native":"నేను రోజుకు రెండు కప్పుల టీ తాగుతాను, ఒకటి ఉదయం మరియు ఒకటి ఐదు గంటలకు."},{"en":"In my region, tea is made with milk, sugar, and strong spices.","native":"మా ప్రాంతంలో, టీని పాలు, చక్కెర మరియు గట్టి మసాలాలతో తయారుచేస్తారు."},{"en":"Drinking tea with my colleagues is the best break at work.","native":"నా సహోద్యోగులతో టీ తాగటం పనిలో అత్యుత్తమ విరామం."}]},"hi":{"word":"चाय","question":"क्या आप चाय पीते हैं? आपके क्षेत्र में चाय कैसे बनाई और पी जाती है?","examples":[{"en":"I drink two cups of tea every day, one in the morning and one at five.","native":"मैं दिन में दो कप चाय पीता हूँ, एक सुबह और एक शाम पाँच बजे।"},{"en":"In my region, tea is made with milk, sugar, and strong spices.","native":"मेरे क्षेत्र में, चाय दूध, चीनी और तेज़ मसालों के साथ बनाई जाती है।"},{"en":"Drinking tea with my colleagues is the best break at work.","native":"सहकर्मियों के साथ चाय पीना काम पर सबसे अच्छा ब्रेक है।"}]},"es":{"word":"té","question":"¿Bebes té? ¿Cómo se prepara y se disfruta el té en tu región?","examples":[{"en":"I drink two cups of tea every day, one in the morning and one at five.","native":"Bebo dos tazas de té al día, una por la mañana y otra a las cinco."},{"en":"In my region, tea is made with milk, sugar, and strong spices.","native":"En mi región, el té se prepara con leche, azúcar y especias fuertes."},{"en":"Drinking tea with my colleagues is the best break at work.","native":"Tomar té con mis compañeros es el mejor descanso del trabajo."}]},"zh":{"word":"茶","question":"你喝茶吗？在你的地区，茶是如何冲泡和享用的？","examples":[{"en":"I drink two cups of tea every day, one in the morning and one at five.","native":"我每天喝两杯茶，早上一杯，下午五点一杯。"},{"en":"In my region, tea is made with milk, sugar, and strong spices.","native":"在我的地区，茶是用牛奶、糖和浓香料煮的。"},{"en":"Drinking tea with my colleagues is the best break at work.","native":"和同事一起喝茶是工作中最好的休息。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'coffee', 'Do you prefer coffee or tea? When do you usually drink it?', '{"te":{"word":"కాఫీ","question":"మీకు కాఫీనా లేదా టీనా ఇష్టం? మీరు దాన్ని సాధారణంగా ఎప్పుడు తాగుతారు?","examples":[{"en":"I prefer coffee because its smell wakes me up in the morning.","native":"దాని వాసన ఉదయం నన్ను మేల్కొలుపుతుంది కాబట్టి నాకు కాఫీ ఇష్టం."},{"en":"I drink one cup before work and never drink it at night.","native":"నేను పనికి ముందు ఒక కప్పు తాగుతాను, రాత్రి ఎప్పుడూ తాగను."},{"en":"Coffee tastes better when I share it with a friend.","native":"ఒక స్నేహితుడితో పంచుకున్నప్పుడు కాఫీ రుచి మరింత బాగుంటుంది."}]},"hi":{"word":"कॉफ़ी","question":"आपको कॉफ़ी पसंद है या चाय? आप इसे आमतौर पर कब पीते हैं?","examples":[{"en":"I prefer coffee because its smell wakes me up in the morning.","native":"मुझे कॉफ़ी पसंद है क्योंकि इसकी खुशबू सुबह मुझे जगा देती है।"},{"en":"I drink one cup before work and never drink it at night.","native":"मैं काम से पहले एक कप पीता हूँ और रात में कभी नहीं पीता।"},{"en":"Coffee tastes better when I share it with a friend.","native":"जब मैं किसी दोस्त के साथ कॉफ़ी पीता हूँ, तो इसका स्वाद और अच्छा लगता है।"}]},"es":{"word":"café","question":"¿Prefieres café o té? ¿Cuándo sueles tomarlo?","examples":[{"en":"I prefer coffee because its smell wakes me up in the morning.","native":"Prefiero el café porque su olor me despierta por la mañana."},{"en":"I drink one cup before work and never drink it at night.","native":"Tomo una taza antes del trabajo y nunca lo bebo por la noche."},{"en":"Coffee tastes better when I share it with a friend.","native":"El café sabe mejor cuando lo comparto con un amigo."}]},"zh":{"word":"咖啡","question":"你喜欢咖啡还是茶？你通常什么时候喝？","examples":[{"en":"I prefer coffee because its smell wakes me up in the morning.","native":"我更喜欢咖啡，因为它的香味能在早上唤醒我。"},{"en":"I drink one cup before work and never drink it at night.","native":"我上班前喝一杯，晚上从不喝。"},{"en":"Coffee tastes better when I share it with a friend.","native":"和朋友分享时，咖啡的味道更好。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'picnic', 'Have you ever been on a picnic? What did you take and where did you go?', '{"te":{"word":"వనభోజనం","question":"మీరు ఎప్పుడైనా వనభోజనానికి వెళ్లారా? మీరు ఏమి తీసుకువెళ్లారు మరియు ఎక్కడికి వెళ్లారు?","examples":[{"en":"Last spring, my class went on a picnic to a lake near the town.","native":"గత వసంతకాలంలో, నా క్లాస్ పట్టణం దగ్గర ఉన్న ఒక సరస్సుకు వనభోజనానికి వెళ్లింది."},{"en":"We took sandwiches, fruit, and juice in a big basket.","native":"మేము ఒక పెద్ద బుట్టలో శాండ్‌విచ్‌లు, పండ్లు మరియు జ్యూస్ తీసుకువెళ్లాము."},{"en":"The picnic was fun, although it started raining in the afternoon.","native":"మధ్యాహ్నం వర్షం మొదలయినప్పటికీ, వనభోజనం సరదాగా ఉంది."}]},"hi":{"word":"पिकनिक","question":"क्या आप कभी पिकनिक पर गए हैं? आप क्या लेकर गए और कहाँ गए?","examples":[{"en":"Last spring, my class went on a picnic to a lake near the town.","native":"पिछली बसंत में, मेरी कक्षा शहर के पास एक झील पर पिकनिक पर गई।"},{"en":"We took sandwiches, fruit, and juice in a big basket.","native":"हम एक बड़ी टोकरी में सैंडविच, फल और जूस लेकर गए।"},{"en":"The picnic was fun, although it started raining in the afternoon.","native":"पिकनिक मज़ेदार थी, भले ही दोपहर में बारिश शुरू हो गई।"}]},"es":{"word":"pícnic","question":"¿Has ido alguna vez de pícnic? ¿Qué llevaste y adónde fuiste?","examples":[{"en":"Last spring, my class went on a picnic to a lake near the town.","native":"La primavera pasada, mi clase fue de pícnic a un lago cerca del pueblo."},{"en":"We took sandwiches, fruit, and juice in a big basket.","native":"Llevamos sándwiches, fruta y zumo en una cesta grande."},{"en":"The picnic was fun, although it started raining in the afternoon.","native":"El pícnic fue divertido, aunque empezó a llover por la tarde."}]},"zh":{"word":"野餐","question":"你去野餐过吗？你带了什么，去了哪里？","examples":[{"en":"Last spring, my class went on a picnic to a lake near the town.","native":"去年春天，我们班去城镇附近的湖边野餐。"},{"en":"We took sandwiches, fruit, and juice in a big basket.","native":"我们用一个大篮子带了三明治、水果和果汁。"},{"en":"The picnic was fun, although it started raining in the afternoon.","native":"野餐很有趣，尽管下午开始下雨了。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'camping', 'Would you like to go camping? What are the good and bad things about sleeping outdoors?', '{"te":{"word":"క్యాంపింగ్","question":"మీరు క్యాంపింగ్‌కు వెళ్లాలనుకుంటున్నారా? బహిరంగంగా పడుకోవడంలో మంచి మరియు చెడు విషయాలు ఏమిటి?","examples":[{"en":"I went camping in the hills with my cousins two years ago.","native":"రెండు సంవత్సరాల క్రితం నేను నా కజిన్స్‌తో కొండల్లో క్యాంపింగ్‌కు వెళ్లాను."},{"en":"The stars were beautiful, but the ground was hard and cold.","native":"నక్షత్రాలు అందంగా ఉన్నాయి, కానీ నేల గట్టిగా మరియు చల్లగా ఉంది."},{"en":"Camping teaches you to enjoy simple things like fire and food.","native":"క్యాంపింగ్ మంట మరియు ఆహారం వంటి సాధారణ విషయాలను ఆస్వాదించడం నేర్పుతుంది."}]},"hi":{"word":"कैम्पिंग","question":"क्या आप कैम्पिंग पर जाना चाहेंगे? खुली जगह में सोने की अच्छी और बुरी बातें क्या हैं?","examples":[{"en":"I went camping in the hills with my cousins two years ago.","native":"दो साल पहले मैं अपने चचेरे भाइयों के साथ पहाड़ों पर कैम्पिंग गया था।"},{"en":"The stars were beautiful, but the ground was hard and cold.","native":"तारे बहुत सुंदर थे, लेकिन ज़मीन कड़ी और ठंडी थी।"},{"en":"Camping teaches you to enjoy simple things like fire and food.","native":"कैम्पिंग आपको आग और खाने जैसी साधारण चीज़ों का आनंद लेना सिखाती है।"}]},"es":{"word":"acampada","question":"¿Te gustaría ir de acampada? ¿Qué cosas buenas y malas tiene dormir al aire libre?","examples":[{"en":"I went camping in the hills with my cousins two years ago.","native":"Fui de acampada a las colinas con mis primos hace dos años."},{"en":"The stars were beautiful, but the ground was hard and cold.","native":"Las estrellas eran preciosas, pero el suelo estaba duro y frío."},{"en":"Camping teaches you to enjoy simple things like fire and food.","native":"Acampar te enseña a disfrutar de cosas sencillas como el fuego y la comida."}]},"zh":{"word":"露营","question":"你想去露营吗？在户外睡觉有什么好处和坏处？","examples":[{"en":"I went camping in the hills with my cousins two years ago.","native":"两年前我和表亲们去山里露营。"},{"en":"The stars were beautiful, but the ground was hard and cold.","native":"星星很美，但地面又硬又冷。"},{"en":"Camping teaches you to enjoy simple things like fire and food.","native":"露营教会你享受火堆和食物这样简单的东西。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'train', 'Do you like travelling by train? Describe a train journey you remember.', '{"te":{"word":"రైలు","question":"మీకు రైలులో ప్రయాణించడం ఇష్టమా? మీకు గుర్తున్న ఒక రైలు ప్రయాణాన్ని వివరించండి.","examples":[{"en":"I like trains because I can walk around and watch the landscape.","native":"నేను తిరిగి నడవవచ్చు మరియు ప్రకృతి దృశ్యాన్ని చూడవచ్చు కాబట్టి రైళ్లు నాకు ఇష్టం."},{"en":"Last year, I took a night train to visit my aunt in the city.","native":"గత సంవత్సరం, నగరంలోని నా అత్తయ్యను చూడటానికి నేను రాత్రి రైలు ఎక్కాను."},{"en":"The journey was long, but talking with other passengers made it short.","native":"ప్రయాణం సుదీర్ఘంగా ఉంది, కానీ ఇతర ప్రయాణికులతో మాట్లాడటం దాన్ని తక్కువగా అనిపించేలా చేసింది."}]},"hi":{"word":"ट्रेन","question":"क्या आपको ट्रेन से यात्रा करना पसंद है? किसी यादगार ट्रेन यात्रा का वर्णन कीजिए।","examples":[{"en":"I like trains because I can walk around and watch the landscape.","native":"मुझे ट्रेनें पसंद हैं क्योंकि मैं घूम-घामकर बाहर का नज़ारा देख सकता हूँ।"},{"en":"Last year, I took a night train to visit my aunt in the city.","native":"पिछले साल, मैं शहर में अपनी मौसी से मिलने रात की ट्रेन से गया।"},{"en":"The journey was long, but talking with other passengers made it short.","native":"यात्रा लंबी थी, लेकिन दूसरे यात्रियों से बात करने से वह छोटी लगने लगी।"}]},"es":{"word":"tren","question":"¿Te gusta viajar en tren? Describe un viaje en tren que recuerdes.","examples":[{"en":"I like trains because I can walk around and watch the landscape.","native":"Me gustan los trenes porque puedo moverme y ver el paisaje."},{"en":"Last year, I took a night train to visit my aunt in the city.","native":"El año pasado tomé un tren nocturno para visitar a mi tía en la ciudad."},{"en":"The journey was long, but talking with other passengers made it short.","native":"El viaje era largo, pero hablar con otros pasajeros lo hizo corto."}]},"zh":{"word":"火车","question":"你喜欢坐火车旅行吗？描述一次你记得的火车之旅。","examples":[{"en":"I like trains because I can walk around and watch the landscape.","native":"我喜欢火车，因为我可以走动并欣赏风景。"},{"en":"Last year, I took a night train to visit my aunt in the city.","native":"去年，我坐夜车去城里看望我的阿姨。"},{"en":"The journey was long, but talking with other passengers made it short.","native":"旅程很长，但和其他乘客聊天让它变短了。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'bus', 'How often do you take the bus? What are the good and bad points of bus travel?', '{"te":{"word":"బస్సు","question":"మీరు ఎంత తరచుగా బస్సు తీసుకుంటారు? బస్సు ప్రయాణంలో మంచి మరియు చెడు విషయాలు ఏమిటి?","examples":[{"en":"I take the bus to work every day because it is cheap and direct.","native":"అది చౌకగా మరియు నేరుగా ఉంటుంది కాబట్టి నేను ప్రతిరోజూ పనికి బస్సు తీసుకుంటాను."},{"en":"Buses are slower than cars, but they cost much less.","native":"బస్సులు కార్ల కంటే నెమ్మదిగా ఉంటాయి, కానీ అవి చాలా తక్కువ ఖర్చవుతాయి."},{"en":"The worst thing is waiting in the rain when the bus is late.","native":"బస్సు ఆలస్యమైనప్పుడు వర్షంలో వేచి ఉండటమే అత్యంత చెత్త విషయం."}]},"hi":{"word":"बस","question":"आप कितनी बार बस लेते हैं? बस यात्रा की अच्छी और बुरी बातें क्या हैं?","examples":[{"en":"I take the bus to work every day because it is cheap and direct.","native":"मैं हर दिन काम पर बस से जाता हूँ क्योंकि यह सस्ती और सीधी है।"},{"en":"Buses are slower than cars, but they cost much less.","native":"बसें कारों से धीमी होती हैं, लेकिन इनका खर्च बहुत कम होता है।"},{"en":"The worst thing is waiting in the rain when the bus is late.","native":"सबसे बुरी बात यह है कि बस देर से आए तो बारिश में इंतज़ार करना पड़ता है।"}]},"es":{"word":"autobús","question":"¿Con qué frecuencia tomas el autobús? ¿Cuáles son los puntos buenos y malos de viajar en autobús?","examples":[{"en":"I take the bus to work every day because it is cheap and direct.","native":"Cojo el autobús al trabajo cada día porque es barato y directo."},{"en":"Buses are slower than cars, but they cost much less.","native":"Los autobuses son más lentos que los coches, pero cuestan mucho menos."},{"en":"The worst thing is waiting in the rain when the bus is late.","native":"Lo peor es esperar bajo la lluvia cuando el autobús llega tarde."}]},"zh":{"word":"公交车","question":"你多久坐一次公交车？乘公交车旅行有什么优点和缺点？","examples":[{"en":"I take the bus to work every day because it is cheap and direct.","native":"我每天坐公交车上班，因为便宜又直达。"},{"en":"Buses are slower than cars, but they cost much less.","native":"公交车比汽车慢，但费用低得多。"},{"en":"The worst thing is waiting in the rain when the bus is late.","native":"最糟糕的是公交车晚点时在雨中等车。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'airplane', 'Have you ever flown in an airplane? Describe your first flight or one you would like to take.', '{"te":{"word":"విమానం","question":"మీరు ఎప్పుడైనా విమానంలో ప్రయాణించారా? మీ మొదటి విమాన ప్రయాణాన్ని లేదా మీరు చేయాలనుకుంటున్న ప్రయాణాన్ని వివరించండి.","examples":[{"en":"My first flight was from my city to the capital last winter.","native":"నా మొదటి విమాన ప్రయాణం గత శీతాకాలంలో నా నగరం నుండి రాజధానికి."},{"en":"I felt excited when the plane lifted off the ground.","native":"విమానం నేల నుండి ఎగిరినప్పుడు నాకు ఉత్సాహంగా అనిపించింది."},{"en":"Flying is faster than any other transport, but airports are stressful.","native":"ఎగరడం మిగతా రవాణా కంటే వేగంగా ఉంటుంది, కానీ విమానాశ్రయాలు ఒత్తిడిని ఇస్తాయి."}]},"hi":{"word":"हवाई जहाज़","question":"क्या आपने कभी हवाई यात्रा की है? अपनी पहली उड़ान या वह उड़ान बताइए जो आप लेना चाहते हैं।","examples":[{"en":"My first flight was from my city to the capital last winter.","native":"मेरी पहली उड़ान पिछली सर्दियों में मेरे शहर से राजधानी तक थी।"},{"en":"I felt excited when the plane lifted off the ground.","native":"जब हवाई जहाज़ ज़मीन से उठा, तो मुझे बहुत उत्साह महसूस हुआ।"},{"en":"Flying is faster than any other transport, but airports are stressful.","native":"उड़ान किसी भी दूसरे परिवहन से तेज़ है, लेकिन हवाई अड्डे तनावपूर्ण होते हैं।"}]},"es":{"word":"avión","question":"¿Has volado alguna vez en avión? Describe tu primer vuelo o uno que te gustaría hacer.","examples":[{"en":"My first flight was from my city to the capital last winter.","native":"Mi primer vuelo fue de mi ciudad a la capital el invierno pasado."},{"en":"I felt excited when the plane lifted off the ground.","native":"Me sentí emocionado cuando el avión despegó del suelo."},{"en":"Flying is faster than any other transport, but airports are stressful.","native":"Volar es más rápido que cualquier otro transporte, pero los aeropuertos son estresantes."}]},"zh":{"word":"飞机","question":"你坐过飞机吗？描述你的第一次飞行或你想乘坐的一次飞行。","examples":[{"en":"My first flight was from my city to the capital last winter.","native":"我的第一次飞行是去年冬天从我的城市飞往首都。"},{"en":"I felt excited when the plane lifted off the ground.","native":"当飞机离开地面时，我感到很兴奋。"},{"en":"Flying is faster than any other transport, but airports are stressful.","native":"飞行比任何其他交通工具都快，但机场让人有压力。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'driving', 'Can you drive a car? What are the most important rules for safe driving?', '{"te":{"word":"డ్రైవింగ్","question":"మీకు కారు డ్రైవ్ చేయడం తెలుసా? సురక్షిత డ్రైవింగ్ కోసం అతి ముఖ్యమైన నియమాలు ఏమిటి?","examples":[{"en":"I learned to drive when I was twenty, with my father as my teacher.","native":"నాకు ఇరవై సంవత్సరాల వయస్సులో, నా నాన్నగారే టీచర్‌గా డ్రైవింగ్ నేర్పించారు."},{"en":"Safe drivers never use their phones while the car is moving.","native":"కారు కదులుతున్నప్పుడు సురక్షిత డ్రైవర్లు ఎప్పుడూ ఫోన్ వాడరు."},{"en":"Driving in heavy rain is more dangerous than driving at night.","native":"రాత్రి డ్రైవ్ చేయడం కంటే భారీ వర్షంలో డ్రైవ్ చేయడం ప్రమాదకరం."}]},"hi":{"word":"ड्राइविंग","question":"क्या आपको कार चलाना आता है? सुरक्षित ड्राइविंग के सबसे ज़रूरी नियम क्या हैं?","examples":[{"en":"I learned to drive when I was twenty, with my father as my teacher.","native":"मैंने बीस साल की उम्र में गाड़ी चलाना सीखा, और मेरे पिता मेरे शिक्षक थे।"},{"en":"Safe drivers never use their phones while the car is moving.","native":"सुरक्षित ड्राइवर गाड़ी चलाते समय कभी फ़ोन इस्तेमाल नहीं करते।"},{"en":"Driving in heavy rain is more dangerous than driving at night.","native":"रात में गाड़ी चलाने की तुलना में तेज़ बारिश में गाड़ी चलाना ज़्यादा खतरनाक है।"}]},"es":{"word":"conducir","question":"¿Sabes conducir un coche? ¿Cuáles son las normas más importantes para conducir con seguridad?","examples":[{"en":"I learned to drive when I was twenty, with my father as my teacher.","native":"Aprendí a conducir a los veinte años, con mi padre como profesor."},{"en":"Safe drivers never use their phones while the car is moving.","native":"Los conductores seguros nunca usan el teléfono mientras el coche está en movimiento."},{"en":"Driving in heavy rain is more dangerous than driving at night.","native":"Conducir bajo lluvia intensa es más peligroso que conducir de noche."}]},"zh":{"word":"驾驶","question":"你会开车吗？安全驾驶最重要的规则是什么？","examples":[{"en":"I learned to drive when I was twenty, with my father as my teacher.","native":"我二十岁时学会开车，父亲是我的老师。"},{"en":"Safe drivers never use their phones while the car is moving.","native":"安全的司机在车行驶时从不用手机。"},{"en":"Driving in heavy rain is more dangerous than driving at night.","native":"在大雨中开车比夜间开车更危险。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'traffic', 'How is the traffic in your town or city? What could improve it?', '{"te":{"word":"ట్రాఫిక్","question":"మీ పట్టణం లేదా నగరంలో ట్రాఫిక్ ఎలా ఉంది? దాన్ని మెరుగుపరచడానికి ఏమి చేయవచ్చు?","examples":[{"en":"The traffic in my city is heavy, especially in the morning.","native":"నా నగరంలో ట్రాఫిక్ భారీగా ఉంటుంది, ముఖ్యంగా ఉదయం."},{"en":"More buses and bicycle lanes could make the roads less crowded.","native":"ఎక్కువ బస్సులు మరియు సైకిల్ మార్గాలు రోడ్ల రద్దీని తగ్గించవచ్చు."},{"en":"I leave home early because the traffic gets worse after eight.","native":"ఎనిమిది గంటల తర్వాత ట్రాఫిక్ పెరుగుతుంది కాబట్టి నేను ఇంటి నుండి త్వరగా బయలుదేరుతాను."}]},"hi":{"word":"यातायात","question":"आपके शहर या कस्बे में यातायात कैसा है? इसे बेहतर बनाने के लिए क्या किया जा सकता है?","examples":[{"en":"The traffic in my city is heavy, especially in the morning.","native":"मेरे शहर में यातायात भारी है, खासकर सुबह के समय।"},{"en":"More buses and bicycle lanes could make the roads less crowded.","native":"ज़्यादा बसें और साइकिल लेन सड़कों को कम भीड़भाड़ वाली बना सकती हैं।"},{"en":"I leave home early because the traffic gets worse after eight.","native":"मैं घर से जल्दी निकलता हूँ क्योंकि आठ बजे के बाद यातायात बिगड़ जाता है।"}]},"es":{"word":"tráfico","question":"¿Cómo es el tráfico en tu pueblo o ciudad? ¿Qué podría mejorarlo?","examples":[{"en":"The traffic in my city is heavy, especially in the morning.","native":"El tráfico en mi ciudad es pesado, sobre todo por la mañana."},{"en":"More buses and bicycle lanes could make the roads less crowded.","native":"Más autobuses y carriles para bicicletas podrían descongestionar las calles."},{"en":"I leave home early because the traffic gets worse after eight.","native":"Salgo de casa temprano porque el tráfico empeora después de las ocho."}]},"zh":{"word":"交通","question":"你所在城镇或城市的交通状况如何？怎样才能改善？","examples":[{"en":"The traffic in my city is heavy, especially in the morning.","native":"我所在城市的交通很拥堵，尤其是早上。"},{"en":"More buses and bicycle lanes could make the roads less crowded.","native":"更多公交车和自行车道可以缓解道路拥挤。"},{"en":"I leave home early because the traffic gets worse after eight.","native":"我提前出门，因为八点以后交通会更糟。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'apartment', 'Do you live in an apartment or a house? What do you like about your home?', '{"te":{"word":"అపార్ట్‌మెంట్","question":"మీరు అపార్ట్‌మెంట్‌లో నివసిస్తారా లేదా ఇంట్లోనా? మీ ఇంటి గురించి మీకు నచ్చినది ఏమిటి?","examples":[{"en":"I live in a small apartment on the third floor with my family.","native":"నేను నా కుటుంబంతో మూడో అంతస్తులో ఒక చిన్న అపార్ట్‌మెంట్‌లో నివసిస్తాను."},{"en":"I like my balcony because I grow flowers and drink tea there.","native":"నాకు నా బాల్కనీ ఇష్టం, ఎందుకంటే నేను అక్కడ పూలు పెంచుతాను మరియు టీ తాగుతాను."},{"en":"Our apartment is smaller than a house, but it is easy to clean.","native":"మా అపార్ట్‌మెంట్ ఇల్లు కంటే చిన్నది, కానీ శుభ్రం చేయడం సులభం."}]},"hi":{"word":"फ़्लैट","question":"क्या आप फ़्लैट में रहते हैं या घर में? आपके घर के बारे में आपको क्या पसंद है?","examples":[{"en":"I live in a small apartment on the third floor with my family.","native":"मैं अपने परिवार के साथ तीसरी मंज़िल पर एक छोटे फ़्लैट में रहता हूँ।"},{"en":"I like my balcony because I grow flowers and drink tea there.","native":"मुझे अपनी बालकनी पसंद है क्योंकि मैं वहाँ फूल उगाता हूँ और चाय पीता हूँ।"},{"en":"Our apartment is smaller than a house, but it is easy to clean.","native":"हमारा फ़्लैट घर से छोटा है, लेकिन इसे साफ़ करना आसान है।"}]},"es":{"word":"apartamento","question":"¿Vives en un apartamento o en una casa? ¿Qué te gusta de tu hogar?","examples":[{"en":"I live in a small apartment on the third floor with my family.","native":"Vivo en un apartamento pequeño en el tercer piso con mi familia."},{"en":"I like my balcony because I grow flowers and drink tea there.","native":"Me gusta mi balcón porque cultivo flores y tomo té allí."},{"en":"Our apartment is smaller than a house, but it is easy to clean.","native":"Nuestro apartamento es más pequeño que una casa, pero es fácil de limpiar."}]},"zh":{"word":"公寓","question":"你住在公寓还是独栋房子里？你喜欢你家的什么？","examples":[{"en":"I live in a small apartment on the third floor with my family.","native":"我和家人住在三楼的一套小公寓里。"},{"en":"I like my balcony because I grow flowers and drink tea there.","native":"我喜欢我的阳台，因为我在那里种花、喝茶。"},{"en":"Our apartment is smaller than a house, but it is easy to clean.","native":"我们的公寓比独栋房子小，但容易打扫。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'furniture', 'What is your favourite piece of furniture at home? Why is it special to you?', '{"te":{"word":"ఫర్నిచర్","question":"మీ ఇంట్లో మీకు ఇష్టమైన ఫర్నిచర్ ముక్క ఏది? అది మీకు ఎందుకు ప్రత్యేకం?","examples":[{"en":"My favourite furniture is an old wooden chair from my grandfather.","native":"నా ఇష్టమైన ఫర్నిచర్ నా తాతయ్యదైన ఒక పాత చెక్క కుర్చీ."},{"en":"I sit in it every evening to read or listen to music.","native":"నేను ప్రతి సాయంత్రం చదవడానికి లేదా సంగీతం వినడానికి అందులో కూర్చుంటాను."},{"en":"It is not comfortable or modern, but it carries family memories.","native":"అది సౌకర్యంగా లేదా ఆధునికంగా లేదు, కానీ అది కుటుంబ జ్ఞాపకాలను మోస్తుంది."}]},"hi":{"word":"फ़र्नीचर","question":"आपके घर का आपका पसंदीदा फ़र्नीचर कौन सा है? यह आपके लिए खास क्यों है?","examples":[{"en":"My favourite furniture is an old wooden chair from my grandfather.","native":"मेरा पसंदीदा फ़र्नीचर मेरे दादाजी की एक पुरानी लकड़ी की कुर्सी है।"},{"en":"I sit in it every evening to read or listen to music.","native":"मैं हर शाम उसमें बैठकर पढ़ता हूँ या संगीत सुनता हूँ।"},{"en":"It is not comfortable or modern, but it carries family memories.","native":"यह न आरामदायक है न आधुनिक, लेकिन इसमें परिवार की यादें बसी हैं।"}]},"es":{"word":"mueble","question":"¿Cuál es tu mueble favorito en casa? ¿Por qué es especial para ti?","examples":[{"en":"My favourite furniture is an old wooden chair from my grandfather.","native":"Mi mueble favorito es una vieja silla de madera de mi abuelo."},{"en":"I sit in it every evening to read or listen to music.","native":"Me siento en ella cada tarde para leer o escuchar música."},{"en":"It is not comfortable or modern, but it carries family memories.","native":"No es cómoda ni moderna, pero guarda recuerdos familiares."}]},"zh":{"word":"家具","question":"你家里最喜欢的一件家具是什么？为什么它对你很特别？","examples":[{"en":"My favourite furniture is an old wooden chair from my grandfather.","native":"我最喜欢的家具是祖父留下的一把旧木椅。"},{"en":"I sit in it every evening to read or listen to music.","native":"我每天晚上坐在上面读书或听音乐。"},{"en":"It is not comfortable or modern, but it carries family memories.","native":"它既不舒适也不现代，但它承载着家庭的回忆。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'cleaning', 'How do you share cleaning and housework in your home?', '{"te":{"word":"శుభ్రం చేయడం","question":"మీ ఇంట్లో శుభ్రం చేయడం మరియు ఇంటి పనులను మీరు ఎలా పంచుకుంటారు?","examples":[{"en":"In my home, everyone cleans their own room every Saturday.","native":"మా ఇంట్లో, ప్రతి ఒక్కరు ప్రతి శనివారం తమ గదిని తామే శుభ్రం చేసుకుంటారు."},{"en":"I wash the dishes while my brother sweeps the floor.","native":"నా సోదరుడు నేల తుడుస్తుండగా నేను గిన్నెలు కడుగుతాను."},{"en":"Sharing housework is fairer than leaving it to one person.","native":"ఒక్కరిపై వదిలేయడం కంటే ఇంటి పనులను పంచుకోవడం న్యాయం."}]},"hi":{"word":"सफ़ाई","question":"आपके घर में सफ़ाई और घर के काम कैसे बँटे होते हैं?","examples":[{"en":"In my home, everyone cleans their own room every Saturday.","native":"मेरे घर में, हर कोई हर शनिवार अपना कमरा खुद साफ़ करता है।"},{"en":"I wash the dishes while my brother sweeps the floor.","native":"मैं बर्तन धोता हूँ जबकि मेरा भाई फ़र्श झाड़ता है।"},{"en":"Sharing housework is fairer than leaving it to one person.","native":"घर के काम एक ही व्यक्ति पर छोड़ने से बेहतर है उन्हें बाँटना।"}]},"es":{"word":"limpieza","question":"¿Cómo repartís la limpieza y las tareas del hogar en tu casa?","examples":[{"en":"In my home, everyone cleans their own room every Saturday.","native":"En mi casa, cada uno limpia su propia habitación todos los sábados."},{"en":"I wash the dishes while my brother sweeps the floor.","native":"Yo lavo los platos mientras mi hermano barre el suelo."},{"en":"Sharing housework is fairer than leaving it to one person.","native":"Repartir las tareas es más justo que dejárselas a una sola persona."}]},"zh":{"word":"打扫","question":"你们在家里如何分担清洁和家务？","examples":[{"en":"In my home, everyone cleans their own room every Saturday.","native":"在我家，每个人每周六打扫自己的房间。"},{"en":"I wash the dishes while my brother sweeps the floor.","native":"我洗碗时，我哥哥扫地。"},{"en":"Sharing housework is fairer than leaving it to one person.","native":"分担家务比把家务都留给一个人更公平。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'washing', 'Do you wash clothes by hand or use a machine? Talk about laundry in your family.', '{"te":{"word":"బట్టలు తోమడం","question":"మీరు బట్టలు చేత్తో తోముతారా లేదా మెషిన్ వాడతారా? మీ కుటుంబంలో బట్టలు తోమడం గురించి మాట్లాడండి.","examples":[{"en":"We use a washing machine, but I wash my shirts by hand.","native":"మేము వాషింగ్ మెషిన్ వాడుతాము, కానీ నా చొక్కాలను నేను చేత్తో తోముతాను."},{"en":"My mother taught me to separate dark and light colours.","native":"ముదురు మరియు లేత రంగులను విడదీయమని నా అమ్మ నాకు నేర్పింది."},{"en":"Clothes dry faster in summer than in the rainy season.","native":"వర్షాకాలం కంటే వేసవిలో బట్టలు త్వరగా ఆరిపోతాయి."}]},"hi":{"word":"कपड़े धोना","question":"आप कपड़े हाथ से धोते हैं या मशीन का उपयोग करते हैं? अपने घर में कपड़े धोने के बारे में बताइए।","examples":[{"en":"We use a washing machine, but I wash my shirts by hand.","native":"हम वॉशिंग मशीन का उपयोग करते हैं, लेकिन मैं अपनी कमीज़ें हाथ से धोता हूँ।"},{"en":"My mother taught me to separate dark and light colours.","native":"मेरी माँ ने मुझे गहरे और हलके रंगों को अलग करना सिखाया।"},{"en":"Clothes dry faster in summer than in the rainy season.","native":"बरसात के मौसम की तुलना में गर्मियों में कपड़े जल्दी सूखते हैं।"}]},"es":{"word":"lavar la ropa","question":"¿Lavas la ropa a mano o usas lavadora? Habla de la colada en tu familia.","examples":[{"en":"We use a washing machine, but I wash my shirts by hand.","native":"Usamos lavadora, pero lavo mis camisas a mano."},{"en":"My mother taught me to separate dark and light colours.","native":"Mi madre me enseñó a separar los colores oscuros de los claros."},{"en":"Clothes dry faster in summer than in the rainy season.","native":"La ropa se seca más rápido en verano que en la época de lluvias."}]},"zh":{"word":"洗衣","question":"你手洗衣服还是用洗衣机？谈谈你家里的洗衣情况。","examples":[{"en":"We use a washing machine, but I wash my shirts by hand.","native":"我们用洗衣机，但我手洗我的衬衫。"},{"en":"My mother taught me to separate dark and light colours.","native":"我妈妈教我把深色和浅色衣服分开洗。"},{"en":"Clothes dry faster in summer than in the rainy season.","native":"夏天衣服比雨季干得快。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'newspaper', 'Do you read newspapers? How do you prefer to get your news?', '{"te":{"word":"వార్తాపత్రిక","question":"మీరు వార్తాపత్రికలు చదువుతారా? మీరు వార్తలు ఎలా పొందడానికి ఇష్టపడతారు?","examples":[{"en":"My father reads the newspaper every morning with his tea.","native":"నా నాన్నగారు ప్రతి ఉదయం టీతో పాటు వార్తాపత్రిక చదువుతారు."},{"en":"I prefer reading news on my phone because it is faster.","native":"అది వేగంగా ఉంటుంది కాబట్టి ఫోన్‌లో వార్తలు చదవడానికి నేను ఇష్టపడతాను."},{"en":"Newspapers give more details than short videos on the internet.","native":"ఇంటర్నెట్‌లోని చిన్న వీడియోల కంటే వార్తాపత్రికలు ఎక్కువ వివరాలు ఇస్తాయి."}]},"hi":{"word":"अख़बार","question":"क्या आप अख़बार पढ़ते हैं? आप समाचार कैसे प्राप्त करना पसंद करते हैं?","examples":[{"en":"My father reads the newspaper every morning with his tea.","native":"मेरे पिता हर सुबह चाय के साथ अख़बार पढ़ते हैं।"},{"en":"I prefer reading news on my phone because it is faster.","native":"मैं फ़ोन पर समाचार पढ़ना पसंद करता हूँ क्योंकि यह तेज़ है।"},{"en":"Newspapers give more details than short videos on the internet.","native":"अख़बार इंटरनेट के छोटे वीडियो से ज़्यादा जानकारी देते हैं।"}]},"es":{"word":"periódico","question":"¿Lees periódicos? ¿Cómo prefieres informarte?","examples":[{"en":"My father reads the newspaper every morning with his tea.","native":"Mi padre lee el periódico cada mañana con su té."},{"en":"I prefer reading news on my phone because it is faster.","native":"Prefiero leer las noticias en el teléfono porque es más rápido."},{"en":"Newspapers give more details than short videos on the internet.","native":"Los periódicos dan más detalles que los vídeos cortos de internet."}]},"zh":{"word":"报纸","question":"你读报纸吗？你更喜欢怎样获取新闻？","examples":[{"en":"My father reads the newspaper every morning with his tea.","native":"我父亲每天早上边喝茶边看报纸。"},{"en":"I prefer reading news on my phone because it is faster.","native":"我更喜欢在手机上看新闻，因为更快。"},{"en":"Newspapers give more details than short videos on the internet.","native":"报纸比互联网上的短视频提供更多细节。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'magazine', 'What kind of magazines do you enjoy reading? Are they still popular today?', '{"te":{"word":"పత్రిక","question":"మీరు ఏ రకమైన పత్రికలు చదవడానికి ఇష్టపడతారు? అవి ఇంకా నేడు ప్రసిద్ధంగా ఉన్నాయా?","examples":[{"en":"I enjoy sports magazines because they have interviews with players.","native":"ఆటగాళ్ల ఇంటర్వ్యూలు ఉంటాయి కాబట్టి నాకు క్రీడా పత్రికలు ఇష్టం."},{"en":"I used to buy a music magazine every month when I was younger.","native":"నేను చిన్నప్పుడు ప్రతి నెల ఒక సంగీత పత్రిక కొనేవాడిని."},{"en":"Today most people read magazines online instead of buying paper ones.","native":"నేడు చాలా మంది కాగితం పత్రికలు కొనడం కంటే ఆన్‌లైన్‌లో చదువుతారు."}]},"hi":{"word":"पत्रिका","question":"आप किस तरह की पत्रिकाएँ पढ़ना पसंद करते हैं? क्या वे आज भी लोकप्रिय हैं?","examples":[{"en":"I enjoy sports magazines because they have interviews with players.","native":"मुझे खेल पत्रिकाएँ पसंद हैं क्योंकि उनमें खिलाड़ियों के इंटरव्यू होते हैं।"},{"en":"I used to buy a music magazine every month when I was younger.","native":"जब मैं छोटा था, मैं हर महीने एक संगीत पत्रिका खरीदता था।"},{"en":"Today most people read magazines online instead of buying paper ones.","native":"आज ज़्यादातर लोग कागज़ की पत्रिकाएँ खरीदने के बजाय ऑनलाइन पढ़ते हैं।"}]},"es":{"word":"revista","question":"¿Qué tipo de revistas te gusta leer? ¿Siguen siendo populares hoy en día?","examples":[{"en":"I enjoy sports magazines because they have interviews with players.","native":"Me gustan las revistas de deportes porque tienen entrevistas con jugadores."},{"en":"I used to buy a music magazine every month when I was younger.","native":"Antes compraba una revista de música cada mes cuando era más joven."},{"en":"Today most people read magazines online instead of buying paper ones.","native":"Hoy la mayoría de la gente lee revistas en línea en lugar de comprarlas en papel."}]},"zh":{"word":"杂志","question":"你喜欢读什么类型的杂志？它们今天还流行吗？","examples":[{"en":"I enjoy sports magazines because they have interviews with players.","native":"我喜欢体育杂志，因为里面有运动员访谈。"},{"en":"I used to buy a music magazine every month when I was younger.","native":"我年轻时每个月都买一本音乐杂志。"},{"en":"Today most people read magazines online instead of buying paper ones.","native":"如今大多数人在线阅读杂志，而不是购买纸质杂志。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'podcast', 'Do you listen to podcasts? What kind of shows would you recommend?', '{"te":{"word":"పాడ్‌కాస్ట్","question":"మీరు పాడ్‌కాస్ట్‌లు వింటారా? మీరు ఏ రకమైన షోలను సిఫార్సు చేస్తారు?","examples":[{"en":"I listen to podcasts while I walk to work in the morning.","native":"ఉదయం పనికి నడుస్తూ వెళ్లేటప్పుడు నేను పాడ్‌కాస్ట్‌లు వింటాను."},{"en":"My favourite show teaches English with short, funny stories.","native":"నా ఇష్టమైన షో చిన్న, ఫన్నీ కథలతో ఇంగ్లీష్ నేర్పుతుంది."},{"en":"Podcasts are better than music when I want to learn something new.","native":"కొత్తది నేర్చుకోవాలనుకున్నప్పుడు పాడ్‌కాస్ట్‌లు సంగీతం కంటే మెరుగైనవి."}]},"hi":{"word":"पॉडकास्ट","question":"क्या आप पॉडकास्ट सुनते हैं? आप किस तरह के शो की सिफ़ारिश करेंगे?","examples":[{"en":"I listen to podcasts while I walk to work in the morning.","native":"मैं सुबह काम पर पैदल जाते समय पॉडकास्ट सुनता हूँ।"},{"en":"My favourite show teaches English with short, funny stories.","native":"मेरा पसंदीदा शो छोटी, मज़ेदार कहानियों से अंग्रेज़ी सिखाता है।"},{"en":"Podcasts are better than music when I want to learn something new.","native":"जब मुझे कुछ नया सीखना होता है, तो पॉडकास्ट संगीत से बेहतर होते हैं।"}]},"es":{"word":"pódcast","question":"¿Escuchas pódcasts? ¿Qué tipo de programas recomendarías?","examples":[{"en":"I listen to podcasts while I walk to work in the morning.","native":"Escucho pódcasts mientras camino al trabajo por la mañana."},{"en":"My favourite show teaches English with short, funny stories.","native":"Mi programa favorito enseña inglés con historias cortas y divertidas."},{"en":"Podcasts are better than music when I want to learn something new.","native":"Los pódcasts son mejores que la música cuando quiero aprender algo nuevo."}]},"zh":{"word":"播客","question":"你听播客吗？你会推荐什么类型的节目？","examples":[{"en":"I listen to podcasts while I walk to work in the morning.","native":"我早上走路去上班时听播客。"},{"en":"My favourite show teaches English with short, funny stories.","native":"我最喜欢的节目用简短有趣的故事教英语。"},{"en":"Podcasts are better than music when I want to learn something new.","native":"当我想学新东西时，播客比音乐更好。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'radio', 'Do you still listen to the radio? Who listens to it in your family?', '{"te":{"word":"రేడియో","question":"మీరు ఇంకా రేడియో వింటారా? మీ కుటుంబంలో ఎవరు వింటారు?","examples":[{"en":"My grandfather listens to the radio every evening after dinner.","native":"నా తాతయ్య ప్రతి సాయంత్రం భోజనం తర్వాత రేడియో వింటారు."},{"en":"I sometimes listen to the radio in the car because it is easy.","native":"అది సులభం కాబట్టి నేను కొన్నిసార్లు కారులో రేడియో వింటాను."},{"en":"Radio is old technology, but it still reaches remote villages.","native":"రేడియో పాత సాంకేతికత, కానీ అది ఇంకా మారుమూల గ్రామాలను చేరుతుంది."}]},"hi":{"word":"रेडियो","question":"क्या आप अब भी रेडियो सुनते हैं? आपके परिवार में कौन इसे सुनता है?","examples":[{"en":"My grandfather listens to the radio every evening after dinner.","native":"मेरे दादाजी हर शाम खाने के बाद रेडियो सुनते हैं।"},{"en":"I sometimes listen to the radio in the car because it is easy.","native":"मैं कभी-कभी कार में रेडियो सुनता हूँ क्योंकि यह आसान है।"},{"en":"Radio is old technology, but it still reaches remote villages.","native":"रेडियो पुरानी तकनीक है, लेकिन यह अब भी दूर-दराज़ के गाँवों तक पहुँचता है।"}]},"es":{"word":"radio","question":"¿Todavía escuchas la radio? ¿Quién la escucha en tu familia?","examples":[{"en":"My grandfather listens to the radio every evening after dinner.","native":"Mi abuelo escucha la radio cada noche después de cenar."},{"en":"I sometimes listen to the radio in the car because it is easy.","native":"A veces escucho la radio en el coche porque es fácil."},{"en":"Radio is old technology, but it still reaches remote villages.","native":"La radio es tecnología antigua, pero todavía llega a pueblos remotos."}]},"zh":{"word":"广播","question":"你还听广播吗？你家里谁听广播？","examples":[{"en":"My grandfather listens to the radio every evening after dinner.","native":"我祖父每天晚饭后听广播。"},{"en":"I sometimes listen to the radio in the car because it is easy.","native":"我有时在车里听广播，因为很方便。"},{"en":"Radio is old technology, but it still reaches remote villages.","native":"广播是老技术，但它仍然能传到偏远的村庄。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'concert', 'Have you ever been to a live concert? Describe the atmosphere.', '{"te":{"word":"కచేరీ","question":"మీరు ఎప్పుడైనా ప్రత్యక్ష కచేరీకి వెళ్లారా? అక్కడి వాతావరణాన్ని వివరించండి.","examples":[{"en":"I went to a concert last year with three of my friends.","native":"గత సంవత్సరం నేను నా ముగ్గురు స్నేహితులతో ఒక కచేరీకి వెళ్లాను."},{"en":"The crowd sang every song, and the lights were amazing.","native":"జనం ప్రతి పాట పాడారు, లైట్లు అద్భుతంగా ఉన్నాయి."},{"en":"Live music sounds louder and more emotional than recordings.","native":"ప్రత్యక్ష సంగీతం రికార్డింగ్‌ల కంటే గట్టిగా మరియు భావోద్వేగంగా ఉంటుంది."}]},"hi":{"word":"संगीत कार्यक्रम","question":"क्या आप कभी किसी लाइव कॉन्सर्ट में गए हैं? वहाँ के माहौल का वर्णन कीजिए।","examples":[{"en":"I went to a concert last year with three of my friends.","native":"पिछले साल मैं अपने तीन दोस्तों के साथ एक कॉन्सर्ट में गया था।"},{"en":"The crowd sang every song, and the lights were amazing.","native":"भीड़ हर गाना गा रही थी, और लाइटें अद्भुत थीं।"},{"en":"Live music sounds louder and more emotional than recordings.","native":"लाइव संगीत रिकॉर्डिंग से ज़्यादा ऊँचा और भावुक लगता है।"}]},"es":{"word":"concierto","question":"¿Has ido alguna vez a un concierto en directo? Describe el ambiente.","examples":[{"en":"I went to a concert last year with three of my friends.","native":"Fui a un concierto el año pasado con tres de mis amigos."},{"en":"The crowd sang every song, and the lights were amazing.","native":"La multitud cantaba cada canción y las luces eran increíbles."},{"en":"Live music sounds louder and more emotional than recordings.","native":"La música en directo suena más fuerte y más emocionante que las grabaciones."}]},"zh":{"word":"音乐会","question":"你去过现场音乐会吗？描述一下那里的气氛。","examples":[{"en":"I went to a concert last year with three of my friends.","native":"去年我和三个朋友去听了一场音乐会。"},{"en":"The crowd sang every song, and the lights were amazing.","native":"观众唱着每一首歌，灯光非常震撼。"},{"en":"Live music sounds louder and more emotional than recordings.","native":"现场音乐比录音更响亮、更有感染力。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'theater', 'Have you ever watched a play at a theater? How is it different from watching a film?', '{"te":{"word":"నాటకశాల","question":"మీరు ఎప్పుడైనా థియేటర్‌లో నాటకం చూశారా? అది సినిమా చూడటం నుండి ఎలా భిన్నం?","examples":[{"en":"I watched a comedy play at the city theater with my parents.","native":"నేను నా తల్లిదండ్రులతో సిటీ థియేటర్‌లో ఒక హాస్య నాటకం చూశాను."},{"en":"The actors were just a few metres away from us.","native":"నటులు మాకు కేవలం కొద్ది మీటర్ల దూరంలో ఉన్నారు."},{"en":"Theater feels more alive because anything can happen on stage.","native":"వేదికపై ఏమైనా జరగవచ్చు కాబట్టి థియేటర్ మరింత జీవంగా అనిపిస్తుంది."}]},"hi":{"word":"रंगमंच","question":"क्या आपने कभी थिएटर में कोई नाटक देखा है? यह फ़िल्म देखने से कैसे अलग है?","examples":[{"en":"I watched a comedy play at the city theater with my parents.","native":"मैंने अपने माता-पिता के साथ शहर के थिएटर में एक कॉमेडी नाटक देखा।"},{"en":"The actors were just a few metres away from us.","native":"कलाकार हमसे बस कुछ ही मीटर की दूरी पर थे।"},{"en":"Theater feels more alive because anything can happen on stage.","native":"थिएटर ज़्यादा जीवंत लगता है क्योंकि मंच पर कुछ भी हो सकता है।"}]},"es":{"word":"teatro","question":"¿Has visto alguna vez una obra de teatro? ¿En qué se diferencia de ver una película?","examples":[{"en":"I watched a comedy play at the city theater with my parents.","native":"Vi una obra de comedia en el teatro de la ciudad con mis padres."},{"en":"The actors were just a few metres away from us.","native":"Los actores estaban a solo unos metros de nosotros."},{"en":"Theater feels more alive because anything can happen on stage.","native":"El teatro se siente más vivo porque cualquier cosa puede pasar en el escenario."}]},"zh":{"word":"剧院","question":"你在剧院看过戏剧吗？它和看电影有什么不同？","examples":[{"en":"I watched a comedy play at the city theater with my parents.","native":"我和父母在市剧院看了一场喜剧。"},{"en":"The actors were just a few metres away from us.","native":"演员们离我们只有几米远。"},{"en":"Theater feels more alive because anything can happen on stage.","native":"剧院感觉更有生命力，因为舞台上什么都可能发生。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'comedy', 'Do you like watching comedy shows? What makes you laugh?', '{"te":{"word":"హాస్యం","question":"మీకు హాస్య షోలు చూడటం ఇష్టమా? మిమ్మల్ని ఏమి నవ్విస్తుంది?","examples":[{"en":"I watch a comedy show every Friday to relax after work.","native":"పని తర్వాత రిలాక్స్ అవ్వడానికి నేను ప్రతి శుక్రవారం ఒక హాస్య షో చూస్తాను."},{"en":"Silly jokes about daily life make me laugh the most.","native":"దైనందిన జీవితం గురించిన వెర్రి జోక్‌లు నన్ను అత్యధికంగా నవ్విస్తాయి."},{"en":"Laughing with friends is better than laughing alone at a screen.","native":"స్క్రీన్ ముందు ఒంటరిగా నవ్వడం కంటే స్నేహితులతో నవ్వడం మేలు."}]},"hi":{"word":"हास्य","question":"क्या आपको कॉमेडी शो देखना पसंद है? किस बात पर आप हँसते हैं?","examples":[{"en":"I watch a comedy show every Friday to relax after work.","native":"काम के बाद आराम करने के लिए मैं हर शुक्रवार एक कॉमेडी शो देखता हूँ।"},{"en":"Silly jokes about daily life make me laugh the most.","native":"रोज़मर्रा की ज़िंदगी पर बने मज़ाकिया चुटकुले मुझे सबसे ज़्यादा हँसाते हैं।"},{"en":"Laughing with friends is better than laughing alone at a screen.","native":"स्क्रीन पर अकेले हँसने से बेहतर है दोस्तों के साथ हँसना।"}]},"es":{"word":"comedia","question":"¿Te gusta ver programas de comedia? ¿Qué te hace reír?","examples":[{"en":"I watch a comedy show every Friday to relax after work.","native":"Veo un programa de comedia cada viernes para relajarme después del trabajo."},{"en":"Silly jokes about daily life make me laugh the most.","native":"Los chistes tontos sobre la vida diaria son los que más me hacen reír."},{"en":"Laughing with friends is better than laughing alone at a screen.","native":"Reír con amigos es mejor que reír solo frente a una pantalla."}]},"zh":{"word":"喜剧","question":"你喜欢看喜剧节目吗？什么会让你发笑？","examples":[{"en":"I watch a comedy show every Friday to relax after work.","native":"我每周五看一个喜剧节目，下班后放松一下。"},{"en":"Silly jokes about daily life make me laugh the most.","native":"关于日常生活的傻笑话最能让我发笑。"},{"en":"Laughing with friends is better than laughing alone at a screen.","native":"和朋友一起笑比独自对着屏幕笑更好。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'adventure', 'What is the most adventurous thing you have ever done? Would you do it again?', '{"te":{"word":"సాహసం","question":"మీరు ఇప్పటివరకు చేసిన అత్యంత సాహసోపేతమైన పని ఏమిటి? మళ్లీ చేస్తారా?","examples":[{"en":"The most adventurous thing I have done is river rafting with friends.","native":"నేను ఇప్పటివరకు చేసిన అత్యంత సాహసోపేతమైన పని స్నేహితులతో రివర్ రాఫ్టింగ్."},{"en":"I was scared at first, but the guide made us feel safe.","native":"మొదట నాకు భయమేసింది, కానీ గైడ్ మమ్మల్ని భద్రంగా అనిపించేలా చేశాడు."},{"en":"I would do it again because adventure makes life exciting.","native":"సాహసం జీవితాన్ని ఉత్సాహంగా మారుస్తుంది కాబట్టి నేను మళ్లీ చేస్తాను."}]},"hi":{"word":"रोमांच","question":"आपने अब तक की सबसे रोमांचक चीज़ क्या की है? क्या आप इसे फिर से करेंगे?","examples":[{"en":"The most adventurous thing I have done is river rafting with friends.","native":"मैंने अब तक की सबसे रोमांचक चीज़ दोस्तों के साथ रिवर राफ्टिंग की है।"},{"en":"I was scared at first, but the guide made us feel safe.","native":"शुरू में मुझे डर लगा, लेकिन गाइड ने हमें सुरक्षित महसूस कराया।"},{"en":"I would do it again because adventure makes life exciting.","native":"मैं इसे फिर से करूँगा क्योंकि रोमांच ज़िंदगी को दिलचस्प बनाता है।"}]},"es":{"word":"aventura","question":"¿Qué es lo más aventurero que has hecho nunca? ¿Lo harías de nuevo?","examples":[{"en":"The most adventurous thing I have done is river rafting with friends.","native":"Lo más aventurero que he hecho es rafting en el río con amigos."},{"en":"I was scared at first, but the guide made us feel safe.","native":"Al principio tenía miedo, pero el guía nos hizo sentir seguros."},{"en":"I would do it again because adventure makes life exciting.","native":"Lo haría de nuevo porque la aventura hace la vida emocionante."}]},"zh":{"word":"冒险","question":"你做过最冒险的事情是什么？你还会再做一次吗？","examples":[{"en":"The most adventurous thing I have done is river rafting with friends.","native":"我做过最冒险的事是和朋友一起漂流。"},{"en":"I was scared at first, but the guide made us feel safe.","native":"一开始我很害怕，但向导让我们感到安全。"},{"en":"I would do it again because adventure makes life exciting.","native":"我会再做一次，因为冒险让生活充满激情。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'courage', 'Talk about a time when you needed courage. What did you do?', '{"te":{"word":"ధైర్యం","question":"మీకు ధైర్యం అవసరమైన ఒక సందర్భం గురించి మాట్లాడండి. మీరు ఏమి చేశారు?","examples":[{"en":"I needed courage when I gave my first speech in English.","native":"నేను ఇంగ్లీషులో నా మొదటి ప్రసంగం ఇచ్చినప్పుడు నాకు ధైర్యం అవసరమైంది."},{"en":"My hands were shaking, but I took a deep breath and continued.","native":"నా చేతులు వణుకుతున్నాయి, కానీ నేను లోతుగా ఊపిరి పీల్చుకుని కొనసాగించాను."},{"en":"After that day, speaking in public became less frightening for me.","native":"ఆ రోజు తర్వాత, బహిరంగంగా మాట్లాడటం నాకు తక్కువ భయంకరంగా మారింది."}]},"hi":{"word":"साहस","question":"किसी ऐसे समय के बारे में बताइए जब आपको साहस की ज़रूरत पड़ी। आपने क्या किया?","examples":[{"en":"I needed courage when I gave my first speech in English.","native":"जब मैंने अंग्रेज़ी में अपना पहला भाषण दिया, तब मुझे साहस की ज़रूरत पड़ी।"},{"en":"My hands were shaking, but I took a deep breath and continued.","native":"मेरे हाथ काँप रहे थे, लेकिन मैंने गहरी साँस ली और बोलता रहा।"},{"en":"After that day, speaking in public became less frightening for me.","native":"उस दिन के बाद, लोगों के सामने बोलना मेरे लिए कम डरावना हो गया।"}]},"es":{"word":"valentía","question":"Habla de un momento en el que necesitaste valentía. ¿Qué hiciste?","examples":[{"en":"I needed courage when I gave my first speech in English.","native":"Necesité valentía cuando di mi primer discurso en inglés."},{"en":"My hands were shaking, but I took a deep breath and continued.","native":"Me temblaban las manos, pero respiré hondo y continué."},{"en":"After that day, speaking in public became less frightening for me.","native":"Después de ese día, hablar en público me dio menos miedo."}]},"zh":{"word":"勇气","question":"谈谈你需要勇气的一次经历。你做了什么？","examples":[{"en":"I needed courage when I gave my first speech in English.","native":"当我第一次用英语演讲时，我需要勇气。"},{"en":"My hands were shaking, but I took a deep breath and continued.","native":"我的手在发抖，但我深吸一口气继续讲了下去。"},{"en":"After that day, speaking in public became less frightening for me.","native":"从那天起，公开演讲对我来说不再那么可怕了。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'mistake', 'Describe a mistake you made and what you learned from it.', '{"te":{"word":"పొరపాటు","question":"మీరు చేసిన ఒక పొరపాటును మరియు దాని నుండి మీరు నేర్చుకున్నదాన్ని వివరించండి.","examples":[{"en":"I once missed an important bus because I left home late.","native":"నేను ఇంటి నుండి ఆలస్యంగా బయలుదేరడం వల్ల ఒకసారి ముఖ్యమైన బస్సు మిస్ అయ్యాను."},{"en":"From that mistake, I learned to prepare everything the night before.","native":"ఆ పొరపాటు నుండి, ముందు రోజు రాత్రే ప్రతిదీ సిద్ధం చేసుకోవడం నేర్చుకున్నాను."},{"en":"Mistakes are painful, but they teach us better than success does.","native":"పొరపాట్లు బాధ కలిపిస్తాయి, కానీ అవి విజయం కంటే మనకు బాగా నేర్పుతాయి."}]},"hi":{"word":"ग़लती","question":"अपनी किसी ग़लती का वर्णन कीजिए और बताइए कि आपने उससे क्या सीखा।","examples":[{"en":"I once missed an important bus because I left home late.","native":"एक बार मैं घर से देर से निकलने की वजह से एक ज़रूरी बस छोड़ बैठा।"},{"en":"From that mistake, I learned to prepare everything the night before.","native":"उस ग़लती से मैंने सीखा कि हर चीज़ रात को ही तैयार कर लेनी चाहिए।"},{"en":"Mistakes are painful, but they teach us better than success does.","native":"ग़लतियाँ दर्दनाक होती हैं, लेकिन वे सफलता से बेहतर सिखाती हैं।"}]},"es":{"word":"error","question":"Describe un error que cometiste y lo que aprendiste de él.","examples":[{"en":"I once missed an important bus because I left home late.","native":"Una vez perdí un autobús importante porque salí tarde de casa."},{"en":"From that mistake, I learned to prepare everything the night before.","native":"De ese error aprendí a prepararlo todo la noche anterior."},{"en":"Mistakes are painful, but they teach us better than success does.","native":"Los errores duelen, pero nos enseñan mejor que los éxitos."}]},"zh":{"word":"错误","question":"描述你犯过的一个错误以及你从中学到了什么。","examples":[{"en":"I once missed an important bus because I left home late.","native":"有一次我因为出门晚而错过了一班重要的公交车。"},{"en":"From that mistake, I learned to prepare everything the night before.","native":"从那次错误中，我学会了在前一天晚上准备好一切。"},{"en":"Mistakes are painful, but they teach us better than success does.","native":"错误是痛苦的，但它们比成功更能教会我们。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'advice', 'What is the best advice you have ever received? Who gave it to you?', '{"te":{"word":"సలహా","question":"మీరు ఇప్పటివరకు పొందిన అత్యుత్తమ సలహా ఏమిటి? ఎవరు మీకు ఇచ్చారు?","examples":[{"en":"The best advice I received was from my mother before my exams.","native":"నేను పొందిన అత్యుత్తమ సలహా నా పరీక్షల ముందు నా అమ్మ ఇచ్చినది."},{"en":"She told me to do my best and not compare myself with others.","native":"నా వంతు కృషి చేయమని, ఇతరులతో పోల్చుకోవద్దని ఆమె నాకు చెప్పింది."},{"en":"Her words help me whenever I feel nervous about results.","native":"ఫలితాల గురించి నాకు టెన్షన్‌గా అనిపించినప్పుడల్లా ఆమె మాటలు నాకు సహాయపడతాయి."}]},"hi":{"word":"सलाह","question":"आपको अब तक मिली सबसे अच्छी सलाह क्या है? किसने दी थी?","examples":[{"en":"The best advice I received was from my mother before my exams.","native":"मुझे मिली सबसे अच्छी सलाह मेरी परीक्षाओं से पहले मेरी माँ ने दी थी।"},{"en":"She told me to do my best and not compare myself with others.","native":"उन्होंने मुझसे कहा कि मैं अपना सर्वश्रेष्ठ करूँ और खुद की तुलना दूसरों से न करूँ।"},{"en":"Her words help me whenever I feel nervous about results.","native":"जब भी परिणामों को लेकर मैं घबराता हूँ, उनके शब्द मेरी मदद करते हैं।"}]},"es":{"word":"consejo","question":"¿Cuál es el mejor consejo que has recibido? ¿Quién te lo dio?","examples":[{"en":"The best advice I received was from my mother before my exams.","native":"El mejor consejo que recibí fue de mi madre antes de mis exámenes."},{"en":"She told me to do my best and not compare myself with others.","native":"Me dijo que hiciera lo mejor posible y que no me comparara con los demás."},{"en":"Her words help me whenever I feel nervous about results.","native":"Sus palabras me ayudan siempre que me pongo nervioso por los resultados."}]},"zh":{"word":"建议","question":"你收到过最好的建议是什么？是谁给你的？","examples":[{"en":"The best advice I received was from my mother before my exams.","native":"我收到过最好的建议是考试前妈妈给我的。"},{"en":"She told me to do my best and not compare myself with others.","native":"她告诉我尽自己最大的努力，不要和别人比较。"},{"en":"Her words help me whenever I feel nervous about results.","native":"每当我对成绩感到紧张时，她的话都能帮助我。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'promise', 'Is it important to keep promises? Tell about a promise you have kept.', '{"te":{"word":"వాగ్దానం","question":"వాగ్దానాలు నిలబెట్టుకోవడం ముఖ్యమా? మీరు నిలబెట్టుకున్న ఒక వాగ్దానం గురించి చెప్పండి.","examples":[{"en":"Keeping promises is important because people trust you more.","native":"ప్రజలు మిమ్మల్ని ఎక్కువగా నమ్ముతారు కాబట్టి వాగ్దానాలు నిలబెట్టుకోవడం ముఖ్యం."},{"en":"I promised to teach my little sister English, and I did it.","native":"నా చిన్న చెల్లెలికి ఇంగ్లీష్ నేర్పుతానని వాగ్దానం చేశాను, చేశాను కూడా."},{"en":"Breaking a promise is easier than keeping one, but it hurts trust.","native":"వాగ్దానం నిలబెట్టుకోవడం కంటే విరమించుకోవడం సులభం, కానీ అది నమ్మకాన్ని దెబ్బతీస్తుంది."}]},"hi":{"word":"वादा","question":"क्या वादे निभाना ज़रूरी है? अपने निभाए किसी वादे के बारे में बताइए।","examples":[{"en":"Keeping promises is important because people trust you more.","native":"वादे निभाना ज़रूरी है क्योंकि इससे लोग आप पर ज़्यादा भरोसा करते हैं।"},{"en":"I promised to teach my little sister English, and I did it.","native":"मैंने अपनी छोटी बहन को अंग्रेज़ी सिखाने का वादा किया था, और मैंने किया भी।"},{"en":"Breaking a promise is easier than keeping one, but it hurts trust.","native":"वादा तोड़ना निभाने से आसान है, लेकिन इससे भरोसा टूटता है।"}]},"es":{"word":"promesa","question":"¿Es importante cumplir las promesas? Cuenta una promesa que hayas cumplido.","examples":[{"en":"Keeping promises is important because people trust you more.","native":"Cumplir las promesas es importante porque la gente confía más en ti."},{"en":"I promised to teach my little sister English, and I did it.","native":"Prometí enseñar inglés a mi hermana pequeña y lo hice."},{"en":"Breaking a promise is easier than keeping one, but it hurts trust.","native":"Romper una promesa es más fácil que cumplirla, pero daña la confianza."}]},"zh":{"word":"承诺","question":"信守承诺重要吗？讲讲你信守过的一个承诺。","examples":[{"en":"Keeping promises is important because people trust you more.","native":"信守承诺很重要，因为人们会更信任你。"},{"en":"I promised to teach my little sister English, and I did it.","native":"我答应教我妹妹英语，而且我做到了。"},{"en":"Breaking a promise is easier than keeping one, but it hurts trust.","native":"违背承诺比信守承诺容易，但它会伤害信任。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'surprise', 'Do you like surprises? Describe a surprise you have given or received.', '{"te":{"word":"ఆశ్చర్యం","question":"మీకు సర్‌ప్రైజ్‌లు ఇష్టమా? మీరు ఇచ్చిన లేదా అందుకున్న ఒక సర్‌ప్రైజ్‌ను వివరించండి.","examples":[{"en":"I love surprises because they show that someone cares about you.","native":"ఎవరైనా మిమ్మల్ని పట్టించుకుంటున్నారని చూపిస్తాయి కాబట్టి సర్‌ప్రైజ్‌లు నాకు చాలా ఇష్టం."},{"en":"My friends surprised me with a cake on my birthday last year.","native":"గత సంవత్సరం నా పుట్టినరోజున నా స్నేహితులు కేకుతో నాకు సర్‌ప్రైజ్ ఇచ్చారు."},{"en":"I was so happy that I almost cried in front of everyone.","native":"నేను చాలా సంతోషపడి అందరి ముందు దాదాపు ఏడ్చేశాను."}]},"hi":{"word":"सरप्राइज़","question":"क्या आपको सरप्राइज़ पसंद हैं? अपने दिए या पाए किसी सरप्राइज़ का वर्णन कीजिए।","examples":[{"en":"I love surprises because they show that someone cares about you.","native":"मुझे सरप्राइज़ बहुत पसंद हैं क्योंकि वे दिखाते हैं कि कोई आपकी परवाह करता है।"},{"en":"My friends surprised me with a cake on my birthday last year.","native":"पिछले साल मेरे जन्मदिन पर मेरे दोस्तों ने केक लाकर मुझे सरप्राइज़ दिया।"},{"en":"I was so happy that I almost cried in front of everyone.","native":"मैं इतना खुश हुआ कि सबके सामने मेरी आँखें भर आईं।"}]},"es":{"word":"sorpresa","question":"¿Te gustan las sorpresas? Describe una sorpresa que hayas dado o recibido.","examples":[{"en":"I love surprises because they show that someone cares about you.","native":"Me encantan las sorpresas porque demuestran que alguien se preocupa por ti."},{"en":"My friends surprised me with a cake on my birthday last year.","native":"Mis amigos me sorprendieron con un pastel en mi cumpleaños el año pasado."},{"en":"I was so happy that I almost cried in front of everyone.","native":"Estaba tan feliz que casi lloro delante de todos."}]},"zh":{"word":"惊喜","question":"你喜欢惊喜吗？描述一个你送出或收到的惊喜。","examples":[{"en":"I love surprises because they show that someone cares about you.","native":"我喜欢惊喜，因为它们表明有人关心你。"},{"en":"My friends surprised me with a cake on my birthday last year.","native":"去年我生日时，朋友们用蛋糕给了我一个惊喜。"},{"en":"I was so happy that I almost cried in front of everyone.","native":"我高兴得差点当着大家的面哭出来。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'party', 'Do you enjoy parties? Describe a party you have been to.', '{"te":{"word":"వేడుక","question":"మీకు పార్టీలు ఇష్టమా? మీరు వెళ్లిన ఒక పార్టీని వివరించండి.","examples":[{"en":"I enjoy small parties more than big, crowded ones.","native":"పెద్ద, రద్దీగా ఉండే పార్టీల కంటే చిన్న పార్టీలు నాకు ఎక్కువ ఇష్టం."},{"en":"Last month, I went to a goodbye party for a colleague.","native":"గత నెల, నేను ఒక సహోద్యోగి కోసం వీడ్కోలు పార్టీకి వెళ్లాను."},{"en":"We played games, sang songs, and talked until midnight.","native":"మేము ఆటలు ఆడాము, పాటలు పాడాము, అర్ధరాత్రి వరకు మాట్లాడుకున్నాము."}]},"hi":{"word":"पार्टी","question":"क्या आपको पार्टियाँ पसंद हैं? किसी ऐसी पार्टी का वर्णन कीजिए जिसमें आप गए हों।","examples":[{"en":"I enjoy small parties more than big, crowded ones.","native":"मुझे बड़ी, भीड़भाड़ वाली पार्टियों से ज़्यादा छोटी पार्टियाँ पसंद हैं।"},{"en":"Last month, I went to a goodbye party for a colleague.","native":"पिछले महीने, मैं एक सहकर्मी की विदाई पार्टी में गया था।"},{"en":"We played games, sang songs, and talked until midnight.","native":"हमने खेल खेले, गाने गाए और आधी रात तक बातें कीं।"}]},"es":{"word":"fiesta","question":"¿Te gustan las fiestas? Describe una fiesta a la que hayas ido.","examples":[{"en":"I enjoy small parties more than big, crowded ones.","native":"Disfruto más de las fiestas pequeñas que de las grandes y llenas."},{"en":"Last month, I went to a goodbye party for a colleague.","native":"El mes pasado fui a una fiesta de despedida de un colega."},{"en":"We played games, sang songs, and talked until midnight.","native":"Jugamos, cantamos canciones y hablamos hasta medianoche."}]},"zh":{"word":"聚会","question":"你喜欢聚会吗？描述一次你参加过的聚会。","examples":[{"en":"I enjoy small parties more than big, crowded ones.","native":"比起大型拥挤的聚会，我更喜欢小型聚会。"},{"en":"Last month, I went to a goodbye party for a colleague.","native":"上个月，我参加了一位同事的欢送会。"},{"en":"We played games, sang songs, and talked until midnight.","native":"我们玩游戏、唱歌，聊天聊到午夜。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'conversation', 'What topics do you enjoy talking about? Who is your favourite person to talk with?', '{"te":{"word":"సంభాషణ","question":"మీరు ఏ అంశాల గురించి మాట్లాడడానికి ఇష్టపడతారు? మాట్లాడటానికి మీకు ఇష్టమైన వ్యక్తి ఎవరు?","examples":[{"en":"I enjoy talking about travel and food with my best friend.","native":"నా పక్కా స్నేహితుడితో ప్రయాణం మరియు ఆహారం గురించి మాట్లాడటం నాకు ఇష్టం."},{"en":"A good conversation makes an evening feel much shorter.","native":"మంచి సంభాషణ సాయంత్రాన్ని చాలా తక్కువగా అనిపించేలా చేస్తుంది."},{"en":"I have learned many things just by listening to older people.","native":"పెద్దవారు మాట్లాడేది వినడం ద్వారానే నేను చాలా విషయాలు నేర్చుకున్నాను."}]},"hi":{"word":"बातचीत","question":"आप किन विषयों पर बात करना पसंद करते हैं? आपका पसंदीदा बात करने वाला व्यक्ति कौन है?","examples":[{"en":"I enjoy talking about travel and food with my best friend.","native":"मुझे अपने सबसे अच्छे दोस्त के साथ यात्रा और खाने पर बात करना पसंद है।"},{"en":"A good conversation makes an evening feel much shorter.","native":"एक अच्छी बातचीत से शाम बहुत छोटी लगने लगती है।"},{"en":"I have learned many things just by listening to older people.","native":"मैंने बड़ों की बातें सुनकर ही बहुत कुछ सीखा है।"}]},"es":{"word":"conversación","question":"¿Sobre qué temas te gusta hablar? ¿Quién es tu persona favorita para conversar?","examples":[{"en":"I enjoy talking about travel and food with my best friend.","native":"Disfruto hablando de viajes y comida con mi mejor amigo."},{"en":"A good conversation makes an evening feel much shorter.","native":"Una buena conversación hace que la tarde parezca mucho más corta."},{"en":"I have learned many things just by listening to older people.","native":"He aprendido muchas cosas solo escuchando a la gente mayor."}]},"zh":{"word":"交谈","question":"你喜欢谈论什么话题？你最喜欢和谁聊天？","examples":[{"en":"I enjoy talking about travel and food with my best friend.","native":"我喜欢和我最好的朋友聊旅行和美食。"},{"en":"A good conversation makes an evening feel much shorter.","native":"一次愉快的交谈会让夜晚显得短暂许多。"},{"en":"I have learned many things just by listening to older people.","native":"仅仅通过倾听长辈讲话，我就学到了很多东西。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'letter', 'When did you last write or receive a letter? Do you prefer letters or messages?', '{"te":{"word":"లేఖ","question":"మీరు చివరిసారిగా ఎప్పుడు లేఖ రాశారు లేదా అందుకున్నారు? మీకు లేఖలా లేదా మెసేజ్‌లా ఏది ఇష్టం?","examples":[{"en":"I received a handwritten letter from my friend two years ago.","native":"రెండు సంవత్సరాల క్రితం నేను నా స్నేహితుడి నుండి చేతితో రాసిన లేఖ అందుకున్నాను."},{"en":"I still keep it because letters feel more personal than messages.","native":"లేఖలు మెసేజ్‌ల కంటే వ్యక్తిగతంగా అనిపిస్తాయి కాబట్టి నేను దాన్ని ఇంకా దాచుకున్నాను."},{"en":"Messages are faster, but a letter can be kept forever.","native":"మెసేజ్‌లు వేగంగా ఉంటాయి, కానీ లేఖను ఎప్పటికీ దాచుకోవచ్చు."}]},"hi":{"word":"पत्र","question":"आपने आख़िरी बार कब पत्र लिखा या पाया? आपको पत्र पसंद हैं या मैसेज?","examples":[{"en":"I received a handwritten letter from my friend two years ago.","native":"दो साल पहले मुझे अपने दोस्त का हाथ से लिखा एक पत्र मिला था।"},{"en":"I still keep it because letters feel more personal than messages.","native":"मैंने उसे आज भी संभालकर रखा है क्योंकि पत्र मैसेज से ज़्यादा निजी लगते हैं।"},{"en":"Messages are faster, but a letter can be kept forever.","native":"मैसेज तेज़ होते हैं, लेकिन पत्र को हमेशा के लिए रखा जा सकता है।"}]},"es":{"word":"carta","question":"¿Cuándo escribiste o recibiste una carta por última vez? ¿Prefieres cartas o mensajes?","examples":[{"en":"I received a handwritten letter from my friend two years ago.","native":"Recibí una carta escrita a mano de mi amigo hace dos años."},{"en":"I still keep it because letters feel more personal than messages.","native":"Todavía la guardo porque las cartas se sienten más personales que los mensajes."},{"en":"Messages are faster, but a letter can be kept forever.","native":"Los mensajes son más rápidos, pero una carta se puede conservar para siempre."}]},"zh":{"word":"信件","question":"你上次写信或收到信是什么时候？你喜欢信件还是消息？","examples":[{"en":"I received a handwritten letter from my friend two years ago.","native":"两年前我收到了朋友的一封手写信。"},{"en":"I still keep it because letters feel more personal than messages.","native":"我至今保留着它，因为信件比消息更有个人色彩。"},{"en":"Messages are faster, but a letter can be kept forever.","native":"消息更快，但信件可以永远保存。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'memory', 'What is your strongest memory from school? Why do you remember it so well?', '{"te":{"word":"జ్ఞాపకం","question":"స్కూల్ నుండి మీకు అత్యంత బలమైన జ్ఞాపకం ఏమిటి? అది మీకు ఎందుకు ఇంత బాగా గుర్తుంది?","examples":[{"en":"My strongest memory is winning a prize for a science project.","native":"నా అత్యంత బలమైన జ్ఞాపకం ఒక సైన్స్ ప్రాజెక్టుకు బహుమతి గెలవడం."},{"en":"I remember it well because my whole family came to watch.","native":"నా కుటుంబం మొత్తం చూడటానికి వచ్చింది కాబట్టి అది నాకు బాగా గుర్తుంది."},{"en":"That day taught me that hard work brings happy moments.","native":"కష్టపడి పనిచేస్తే సంతోషకరమైన క్షణాలు వస్తాయని ఆ రోజు నాకు నేర్పింది."}]},"hi":{"word":"याद","question":"स्कूल की आपकी सबसे गहरी याद क्या है? आपको यह इतनी अच्छी तरह क्यों याद है?","examples":[{"en":"My strongest memory is winning a prize for a science project.","native":"मेरी सबसे गहरी याद एक विज्ञान प्रोजेक्ट के लिए पुरस्कार जीतने की है।"},{"en":"I remember it well because my whole family came to watch.","native":"मुझे यह अच्छी तरह याद है क्योंकि मेरा पूरा परिवार देखने आया था।"},{"en":"That day taught me that hard work brings happy moments.","native":"उस दिन ने मुझे सिखाया कि कड़ी मेहनत से खुशियाँ मिलती हैं।"}]},"es":{"word":"recuerdo","question":"¿Cuál es tu recuerdo más fuerte del colegio? ¿Por qué lo recuerdas tan bien?","examples":[{"en":"My strongest memory is winning a prize for a science project.","native":"Mi recuerdo más fuerte es ganar un premio por un proyecto de ciencias."},{"en":"I remember it well because my whole family came to watch.","native":"Lo recuerdo bien porque vino a verme toda mi familia."},{"en":"That day taught me that hard work brings happy moments.","native":"Ese día me enseñó que el trabajo duro trae momentos felices."}]},"zh":{"word":"回忆","question":"你在学校最深刻的记忆是什么？为什么你记得这么清楚？","examples":[{"en":"My strongest memory is winning a prize for a science project.","native":"我最深刻的记忆是因一个科学项目获奖。"},{"en":"I remember it well because my whole family came to watch.","native":"我记得很清楚，因为我全家都来观看了。"},{"en":"That day taught me that hard work brings happy moments.","native":"那一天教会了我努力会带来快乐的时刻。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'future', 'What do you hope your life will be like in ten years?', '{"te":{"word":"భవిష్యత్తు","question":"పది సంవత్సరాల తర్వాత మీ జీవితం ఎలా ఉంటుందని మీరు ఆశిస్తున్నారు?","examples":[{"en":"In ten years, I hope to have a good job and my own house.","native":"పది సంవత్సరాలలో, నాకు మంచి ఉద్యోగం మరియు స్వంత ఇల్లు ఉంటాయని ఆశిస్తున్నాను."},{"en":"I want to travel more because I have seen very little of the world.","native":"నేను ప్రపంచంలో చాలా తక్కువ చూశాను కాబట్టి ఎక్కువ ప్రయాణించాలనుకుంటున్నాను."},{"en":"The future is uncertain, but planning makes me feel ready.","native":"భవిష్యత్తు అనిశ్చితమే, కానీ ప్లానింగ్ నన్ను సిద్ధంగా అనిపించేలా చేస్తుంది."}]},"hi":{"word":"भविष्य","question":"दस साल बाद आपकी ज़िंदगी कैसी हो, ऐसी आपकी क्या उम्मीद है?","examples":[{"en":"In ten years, I hope to have a good job and my own house.","native":"दस साल बाद, मेरी उम्मीद है कि मेरे पास एक अच्छी नौकरी और अपना घर होगा।"},{"en":"I want to travel more because I have seen very little of the world.","native":"मैं ज़्यादा यात्रा करना चाहता हूँ क्योंकि मैंने दुनिया बहुत कम देखी है।"},{"en":"The future is uncertain, but planning makes me feel ready.","native":"भविष्य अनिश्चित है, लेकिन योजना बनाने से मैं तैयार महसूस करता हूँ।"}]},"es":{"word":"futuro","question":"¿Cómo esperas que sea tu vida dentro de diez años?","examples":[{"en":"In ten years, I hope to have a good job and my own house.","native":"Dentro de diez años, espero tener un buen trabajo y mi propia casa."},{"en":"I want to travel more because I have seen very little of the world.","native":"Quiero viajar más porque he visto muy poco del mundo."},{"en":"The future is uncertain, but planning makes me feel ready.","native":"El futuro es incierto, pero planificar me hace sentir preparado."}]},"zh":{"word":"未来","question":"你希望十年后你的生活是什么样子？","examples":[{"en":"In ten years, I hope to have a good job and my own house.","native":"十年后，我希望有一份好工作和自己的房子。"},{"en":"I want to travel more because I have seen very little of the world.","native":"我想多旅行，因为我见过的世界太少了。"},{"en":"The future is uncertain, but planning makes me feel ready.","native":"未来是不确定的，但做计划让我感觉有准备。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'goal', 'What is one goal you are working on right now? How will you reach it?', '{"te":{"word":"లక్ష్యం","question":"మీరు ప్రస్తుతం చేస్తున్న ఒక లక్ష్యం ఏమిటి? దాన్ని మీరు ఎలా చేరుకుంటారు?","examples":[{"en":"My goal right now is to speak English without translating in my head.","native":"నా ప్రస్తుత లక్ష్యం మనస్లో అనువదించకుండా ఇంగ్లీష్ మాట్లాడటం."},{"en":"I will reach it by practising every day and watching English films.","native":"ప్రతిరోజూ అభ్యసించడం మరియు ఇంగ్లీష్ సినిమాలు చూడటం ద్వారా దాన్ని చేరుకుంటాను."},{"en":"Small steps every week bring me closer to my goal.","native":"ప్రతి వారం చిన్న అడుగులు నన్ను నా లక్ష్యానికి దగ్గరగా తీసుకువెళ్తాయి."}]},"hi":{"word":"लक्ष्य","question":"इस समय आप किस एक लक्ष्य पर काम कर रहे हैं? आप इसे कैसे पाएँगे?","examples":[{"en":"My goal right now is to speak English without translating in my head.","native":"अभी मेरा लक्ष्य मन में अनुवाद किए बिना अंग्रेज़ी बोलना है।"},{"en":"I will reach it by practising every day and watching English films.","native":"मैं हर दिन अभ्यास करके और अंग्रेज़ी फ़िल्में देखकर इसे पाऊँगा।"},{"en":"Small steps every week bring me closer to my goal.","native":"हर हफ़्ते उठाए छोटे कदम मुझे मेरे लक्ष्य के करीब ले जाते हैं।"}]},"es":{"word":"meta","question":"¿Cuál es una meta en la que estás trabajando ahora? ¿Cómo la alcanzarás?","examples":[{"en":"My goal right now is to speak English without translating in my head.","native":"Mi meta ahora es hablar inglés sin traducir en mi cabeza."},{"en":"I will reach it by practising every day and watching English films.","native":"La alcanzaré practicando cada día y viendo películas en inglés."},{"en":"Small steps every week bring me closer to my goal.","native":"Los pequeños pasos de cada semana me acercan a mi meta."}]},"zh":{"word":"目标","question":"你目前正在努力实现的一个目标是什么？你将如何实现它？","examples":[{"en":"My goal right now is to speak English without translating in my head.","native":"我现在的目标是不在脑中翻译就能说英语。"},{"en":"I will reach it by practising every day and watching English films.","native":"我将通过每天练习和看英语电影来实现它。"},{"en":"Small steps every week bring me closer to my goal.","native":"每周的小进步让我离目标更近。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B1', 'skill', 'What new skill would you like to learn? How would you start learning it?', '{"te":{"word":"నైపుణ్యం","question":"మీరు ఏ కొత్త నైపుణ్యాన్ని నేర్చుకోవాలనుకుంటున్నారు? దాన్ని నేర్చుకోవడం ఎలా ప్రారంభిస్తారు?","examples":[{"en":"I would like to learn photography because I love beautiful pictures.","native":"అందమైన చిత్రాలు నాకు ఇష్టం కాబట్టి ఫోటోగ్రఫీ నేర్చుకోవాలనుకుంటున్నాను."},{"en":"I would start by watching free lessons online every weekend.","native":"ప్రతి వారాంతం ఆన్‌లైన్‌లో ఉచిత పాఠాలు చూడటంతో ప్రారంభిస్తాను."},{"en":"Learning a new skill is hard at first, but practice makes it fun.","native":"కొత్త నైపుణ్యం నేర్చుకోవడం మొదట కష్టం, కానీ అభ్యాసం దాన్ని సరదాగా మారుస్తుంది."}]},"hi":{"word":"कौशल","question":"आप कौन सा नया कौशल सीखना चाहेंगे? आप इसे सीखना कैसे शुरू करेंगे?","examples":[{"en":"I would like to learn photography because I love beautiful pictures.","native":"मैं फ़ोटोग्राफ़ी सीखना चाहूँगा क्योंकि मुझे सुंदर तस्वीरें पसंद हैं।"},{"en":"I would start by watching free lessons online every weekend.","native":"मैं हर सप्ताह के अंत में ऑनलाइन मुफ़्त पाठ देखकर शुरुआत करूँगा।"},{"en":"Learning a new skill is hard at first, but practice makes it fun.","native":"नया कौशल सीखना शुरू में कठिन होता है, लेकिन अभ्यास से यह मज़ेदार बन जाता है।"}]},"es":{"word":"habilidad","question":"¿Qué nueva habilidad te gustaría aprender? ¿Cómo empezarías a aprenderla?","examples":[{"en":"I would like to learn photography because I love beautiful pictures.","native":"Me gustaría aprender fotografía porque me encantan las fotos bonitas."},{"en":"I would start by watching free lessons online every weekend.","native":"Empezaría viendo lecciones gratuitas en línea cada fin de semana."},{"en":"Learning a new skill is hard at first, but practice makes it fun.","native":"Aprender una habilidad nueva es difícil al principio, pero la práctica lo hace divertido."}]},"zh":{"word":"技能","question":"你想学什么新技能？你会怎样开始学习？","examples":[{"en":"I would like to learn photography because I love beautiful pictures.","native":"我想学摄影，因为我喜欢美丽的照片。"},{"en":"I would start by watching free lessons online every weekend.","native":"我会从每个周末在网上看免费课程开始。"},{"en":"Learning a new skill is hard at first, but practice makes it fun.","native":"学习新技能一开始很难，但练习会让它变得有趣。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'challenge', 'Describe a significant challenge that forced you to change your approach. What did you learn, and would you handle it differently now?', '{"te":{"word":"సవాలు","question":"మీ విధానాన్ని మార్చుకోవాల్సి వచ్చిన ఒక ముఖ్యమైన సవాలును వివరించండి. దాని నుంచి మీరు ఏమి నేర్చుకున్నారు, ఇప్పుడు అయితే దాన్ని వేరుగా ఎదుర్కొంటారా?","examples":[{"en":"When I had to present a project in English, anxiety made me avoid practising in front of other people.","native":"నేను ఒక ప్రాజెక్టును ఇంగ్లీష్‌లో ప్రదర్శించాల్సి వచ్చినప్పుడు, ఆందోళన వల్ల ఇతరుల ముందు సాధన చేయకుండా తప్పించుకున్నాను."},{"en":"Once I began recording myself and asking classmates for specific feedback, my confidence improved even though progress was uneven.","native":"నన్ను నేను రికార్డ్ చేసుకోవడం మరియు సహపాఠులను నిర్దిష్ట అభిప్రాయం అడగడం మొదలుపెట్టిన తర్వాత, పురోగతి ఒకేలా లేకపోయినా నా ఆత్మవిశ్వాసం మెరుగుపడింది."},{"en":"If I faced the same challenge now, I would seek help earlier rather than treating every mistake as evidence of failure.","native":"ఇప్పుడు అదే సవాలు ఎదురైతే, ప్రతి తప్పును వైఫల్యానికి నిదర్శనంగా భావించడం కాకుండా ముందుగానే సహాయం కోరుతాను."}]},"hi":{"word":"चुनौती","question":"किसी ऐसी महत्वपूर्ण चुनौती का वर्णन कीजिए जिसने आपको अपना तरीका बदलने पर मजबूर किया। आपने उससे क्या सीखा, और क्या अब आप उसे अलग ढंग से संभालेंगे?","examples":[{"en":"When I had to present a project in English, anxiety made me avoid practising in front of other people.","native":"जब मुझे अंग्रेज़ी में एक परियोजना प्रस्तुत करनी थी, तो घबराहट के कारण मैं दूसरों के सामने अभ्यास करने से बचता था।"},{"en":"Once I began recording myself and asking classmates for specific feedback, my confidence improved even though progress was uneven.","native":"जब मैंने खुद को रिकॉर्ड करना और सहपाठियों से खास प्रतिक्रिया माँगना शुरू किया, तो असमान प्रगति के बावजूद मेरा आत्मविश्वास बढ़ा।"},{"en":"If I faced the same challenge now, I would seek help earlier rather than treating every mistake as evidence of failure.","native":"अगर आज वही चुनौती सामने आए, तो मेरी प्राथमिकता हर गलती को असफलता का प्रमाण मानने के बजाय पहले ही मदद माँगने की होगी।"}]},"es":{"word":"desafío","question":"Describe un desafío importante que te obligó a cambiar de enfoque. ¿Qué aprendiste y lo afrontarías de otra manera ahora?","examples":[{"en":"When I had to present a project in English, anxiety made me avoid practising in front of other people.","native":"Cuando tuve que presentar un proyecto en inglés, la ansiedad me hacía evitar practicar delante de otras personas."},{"en":"Once I began recording myself and asking classmates for specific feedback, my confidence improved even though progress was uneven.","native":"Cuando empecé a grabarme y a pedir comentarios concretos a mis compañeros, aumentó mi confianza aunque el progreso fue irregular."},{"en":"If I faced the same challenge now, I would seek help earlier rather than treating every mistake as evidence of failure.","native":"Si afrontara hoy el mismo reto, pediría ayuda antes en lugar de interpretar cada error como prueba de fracaso."}]},"zh":{"word":"挑战","question":"描述一个迫使你改变做法的重大挑战。你从中学到了什么？现在会用不同的方式处理吗？","examples":[{"en":"When I had to present a project in English, anxiety made me avoid practising in front of other people.","native":"当我必须用英语展示一个项目时，焦虑让我逃避在别人面前练习。"},{"en":"Once I began recording myself and asking classmates for specific feedback, my confidence improved even though progress was uneven.","native":"当我开始给自己录音并向同学征求具体反馈后，尽管进步并不稳定，我的信心还是增强了。"},{"en":"If I faced the same challenge now, I would seek help earlier rather than treating every mistake as evidence of failure.","native":"如果现在面对同样的挑战，我会更早寻求帮助，而不会把每个错误都看成失败的证据。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'environment', 'How should responsibility for protecting the environment be divided among individuals, businesses, and governments, especially when greener choices cost more?', '{"te":{"word":"పర్యావరణం","question":"పర్యావరణాన్ని రక్షించే బాధ్యతను వ్యక్తులు, వ్యాపారాలు మరియు ప్రభుత్వాల మధ్య ఎలా పంచాలి, ముఖ్యంగా పర్యావరణ అనుకూల ఎంపికలకు ఎక్కువ ఖర్చయ్యేటప్పుడు?","examples":[{"en":"Individuals can reduce waste and travel more sustainably, but their choices are limited when affordable alternatives do not exist.","native":"వ్యక్తులు వ్యర్థాలను తగ్గించి మరింత సుస్థిరంగా ప్రయాణించగలరు, కానీ అందుబాటు ధరలో ప్రత్యామ్నాయాలు లేనప్పుడు వారి ఎంపికలు పరిమితమవుతాయి."},{"en":"Businesses should pay for the pollution they create instead of passing environmental costs to the public.","native":"వ్యాపారాలు పర్యావరణ ఖర్చులను ప్రజలపై మోపకుండా తాము సృష్టించే కాలుష్యానికి ఖర్చు భరించాలి."},{"en":"Governments need firm standards and targeted support so that lower-income households are not punished during the transition.","native":"మార్పు సమయంలో తక్కువ ఆదాయం గల కుటుంబాలు నష్టపోకుండా ప్రభుత్వాలు కఠిన ప్రమాణాలు మరియు లక్ష్యిత సహాయాన్ని అందించాలి."}]},"hi":{"word":"पर्यावरण","question":"पर्यावरण की रक्षा की ज़िम्मेदारी व्यक्तियों, व्यवसायों और सरकारों के बीच कैसे बाँटी जानी चाहिए, खासकर जब अधिक पर्यावरण-अनुकूल विकल्प महँगे हों?","examples":[{"en":"Individuals can reduce waste and travel more sustainably, but their choices are limited when affordable alternatives do not exist.","native":"लोग कचरा घटा सकते हैं और अधिक टिकाऊ तरीके से यात्रा कर सकते हैं, लेकिन किफ़ायती विकल्प न होने पर उनकी पसंद सीमित हो जाती है।"},{"en":"Businesses should pay for the pollution they create instead of passing environmental costs to the public.","native":"व्यवसायों को पर्यावरण की लागत जनता पर डालने के बजाय अपने पैदा किए प्रदूषण की कीमत चुकानी चाहिए।"},{"en":"Governments need firm standards and targeted support so that lower-income households are not punished during the transition.","native":"सरकारों को सख्त मानक और लक्षित सहायता देनी चाहिए ताकि बदलाव के दौरान कम आय वाले परिवारों को नुकसान न हो।"}]},"es":{"word":"medio ambiente","question":"¿Cómo debería repartirse la responsabilidad de proteger el medio ambiente entre las personas, las empresas y los gobiernos, especialmente cuando las opciones más ecológicas cuestan más?","examples":[{"en":"Individuals can reduce waste and travel more sustainably, but their choices are limited when affordable alternatives do not exist.","native":"Las personas pueden reducir residuos y viajar de forma más sostenible, pero sus opciones son limitadas cuando no existen alternativas asequibles."},{"en":"Businesses should pay for the pollution they create instead of passing environmental costs to the public.","native":"Las empresas deberían pagar por la contaminación que generan en vez de trasladar los costes ambientales a la sociedad."},{"en":"Governments need firm standards and targeted support so that lower-income households are not punished during the transition.","native":"Los gobiernos necesitan normas firmes y ayudas específicas para que los hogares con menores ingresos no resulten perjudicados durante la transición."}]},"zh":{"word":"环境","question":"保护环境的责任应如何在个人、企业和政府之间分配，尤其是在环保选择成本更高的情况下？","examples":[{"en":"Individuals can reduce waste and travel more sustainably, but their choices are limited when affordable alternatives do not exist.","native":"个人可以减少浪费并选择更可持续的出行方式，但在没有可负担替代方案时，他们的选择会受到限制。"},{"en":"Businesses should pay for the pollution they create instead of passing environmental costs to the public.","native":"企业应该为自身造成的污染买单，而不是把环境成本转嫁给公众。"},{"en":"Governments need firm standards and targeted support so that lower-income households are not punished during the transition.","native":"政府需要制定严格标准并提供有针对性的支持，避免低收入家庭在转型期间受到不公平的影响。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'culture', 'How can people preserve cultural traditions while allowing them to change, and who should decide when a tradition no longer fits modern values?', '{"te":{"word":"సంస్కృతి","question":"సాంస్కృతిక సంప్రదాయాలు మారడానికి అవకాశం ఇస్తూనే ప్రజలు వాటిని ఎలా సంరక్షించగలరు, ఒక సంప్రదాయం ఆధునిక విలువలకు ఇక సరిపోదని ఎవరు నిర్ణయించాలి?","examples":[{"en":"Traditions give communities a sense of continuity, although preserving them unchanged can exclude younger generations.","native":"సంప్రదాయాలు సమాజాలకు కొనసాగింపు భావనను ఇస్తాయి, అయితే వాటిని ఏమాత్రం మార్చకుండా కాపాడటం యువ తరాలను దూరం చేయవచ్చు."},{"en":"Cultural exchange does not automatically erase identity; it can produce new practices that people genuinely choose.","native":"సాంస్కృతిక పరస్పర మార్పిడి తప్పనిసరిగా గుర్తింపును చెరిపివేయదు; ప్రజలు నిజంగా ఎంచుకునే కొత్త ఆచారాలను అది సృష్టించగలదు."},{"en":"When a custom restricts someone''s rights, respectful criticism is more valuable than defending it simply because it is old.","native":"ఒక ఆచారం ఎవరి హక్కులనైనా పరిమితం చేసినప్పుడు, అది పాతది అనే కారణంతో సమర్థించడం కంటే గౌరవప్రదమైన విమర్శ మరింత విలువైనది."}]},"hi":{"word":"संस्कृति","question":"लोग सांस्कृतिक परंपराओं को बदलने की गुंजाइश देते हुए उन्हें कैसे सुरक्षित रख सकते हैं, और कोई परंपरा आधुनिक मूल्यों के अनुकूल नहीं रही, यह किसे तय करना चाहिए?","examples":[{"en":"Traditions give communities a sense of continuity, although preserving them unchanged can exclude younger generations.","native":"परंपराएँ समुदायों को निरंतरता का एहसास देती हैं, हालाँकि उन्हें बिना बदलाव के बचाए रखना युवा पीढ़ियों को अलग-थलग कर सकता है।"},{"en":"Cultural exchange does not automatically erase identity; it can produce new practices that people genuinely choose.","native":"सांस्कृतिक आदान-प्रदान पहचान को अपने-आप नहीं मिटाता; यह ऐसी नई प्रथाएँ बना सकता है जिन्हें लोग सच में चुनते हैं।"},{"en":"When a custom restricts someone''s rights, respectful criticism is more valuable than defending it simply because it is old.","native":"जब कोई रिवाज किसी के अधिकार सीमित करता है, तो केवल उसके पुराना होने के कारण उसका बचाव करने से सम्मानपूर्ण आलोचना अधिक मूल्यवान है।"}]},"es":{"word":"cultura","question":"¿Cómo se pueden preservar las tradiciones culturales y permitir que cambien, y quién debería decidir cuándo una tradición ya no encaja con los valores modernos?","examples":[{"en":"Traditions give communities a sense of continuity, although preserving them unchanged can exclude younger generations.","native":"Las tradiciones dan a las comunidades una sensación de continuidad, aunque conservarlas sin cambios puede excluir a las generaciones más jóvenes."},{"en":"Cultural exchange does not automatically erase identity; it can produce new practices that people genuinely choose.","native":"El intercambio cultural no borra automáticamente la identidad; puede producir nuevas prácticas que la gente elige de verdad."},{"en":"When a custom restricts someone''s rights, respectful criticism is more valuable than defending it simply because it is old.","native":"Cuando una costumbre limita los derechos de alguien, la crítica respetuosa es más valiosa que defenderla simplemente porque es antigua."}]},"zh":{"word":"文化","question":"人们如何在保护文化传统的同时允许其改变？当一项传统不再符合现代价值观时，应由谁来决定？","examples":[{"en":"Traditions give communities a sense of continuity, although preserving them unchanged can exclude younger generations.","native":"传统赋予社区延续感，但原封不动地保存传统可能会把年轻一代排除在外。"},{"en":"Cultural exchange does not automatically erase identity; it can produce new practices that people genuinely choose.","native":"文化交流不会自动抹去身份认同；它可以产生人们真正愿意选择的新做法。"},{"en":"When a custom restricts someone''s rights, respectful criticism is more valuable than defending it simply because it is old.","native":"当一种习俗限制某人的权利时，尊重地提出批评比仅仅因为它历史悠久就为其辩护更有价值。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'education', 'To what extent can education transform a person''s opportunities, and which inequalities can schools not solve on their own?', '{"te":{"word":"విద్య","question":"విద్య ఒక వ్యక్తి అవకాశాలను ఎంతవరకు మార్చగలదు, పాఠశాలలు ఒంటరిగా పరిష్కరించలేని అసమానతలు ఏవి?","examples":[{"en":"Education can expand career choices and strengthen critical thinking, but qualifications do not guarantee equal access to work.","native":"విద్య వృత్తి ఎంపికలను విస్తరించి విమర్శనాత్మక ఆలోచనను బలోపేతం చేయగలదు, కానీ అర్హతలు ఉద్యోగాలకు సమాన ప్రాప్యతను హామీ ఇవ్వవు."},{"en":"Students learn more effectively when schools provide skilled teachers and support rather than expecting families to fill every gap.","native":"ప్రతి లోటును కుటుంబాలే పూరించాలని ఆశించడం కాకుండా పాఠశాలలు నైపుణ్యం గల ఉపాధ్యాయులు మరియు మద్దతును అందించినప్పుడు విద్యార్థులు మరింత సమర్థవంతంగా నేర్చుకుంటారు."},{"en":"Although education changed my own prospects, affordable housing, healthcare, and fair hiring also shape whether people can succeed.","native":"విద్య నా స్వంత అవకాశాలను మార్చినప్పటికీ, అందుబాటు ధరలో గృహవసతి, ఆరోగ్య సంరక్షణ మరియు న్యాయమైన నియామకాలు కూడా ప్రజలు విజయం సాధించగలరా అనే దానిపై ప్రభావం చూపుతాయి."}]},"hi":{"word":"शिक्षा","question":"शिक्षा किसी व्यक्ति के अवसरों को किस हद तक बदल सकती है, और कौन-सी असमानताएँ स्कूल अकेले दूर नहीं कर सकते?","examples":[{"en":"Education can expand career choices and strengthen critical thinking, but qualifications do not guarantee equal access to work.","native":"शिक्षा करियर के विकल्प बढ़ा सकती है और आलोचनात्मक सोच मज़बूत कर सकती है, लेकिन योग्यताएँ काम तक समान पहुँच की गारंटी नहीं देतीं।"},{"en":"Students learn more effectively when schools provide skilled teachers and support rather than expecting families to fill every gap.","native":"जब स्कूल हर कमी परिवारों से पूरी कराने की अपेक्षा रखने के बजाय कुशल शिक्षक और सहायता देते हैं, तब छात्र अधिक प्रभावी ढंग से सीखते हैं।"},{"en":"Although education changed my own prospects, affordable housing, healthcare, and fair hiring also shape whether people can succeed.","native":"हालाँकि शिक्षा ने मेरी अपनी संभावनाएँ बदलीं, लेकिन किफ़ायती आवास, स्वास्थ्य सेवा और निष्पक्ष भर्ती भी तय करते हैं कि लोग सफल हो पाएँगे या नहीं।"}]},"es":{"word":"educación","question":"¿Hasta qué punto puede la educación transformar las oportunidades de una persona y qué desigualdades no pueden resolver las escuelas por sí solas?","examples":[{"en":"Education can expand career choices and strengthen critical thinking, but qualifications do not guarantee equal access to work.","native":"La educación puede ampliar las opciones profesionales y reforzar el pensamiento crítico, pero los títulos no garantizan el mismo acceso al empleo."},{"en":"Students learn more effectively when schools provide skilled teachers and support rather than expecting families to fill every gap.","native":"Los estudiantes aprenden con mayor eficacia cuando las escuelas ofrecen docentes capacitados y apoyo, en vez de esperar que las familias cubran todas las carencias."},{"en":"Although education changed my own prospects, affordable housing, healthcare, and fair hiring also shape whether people can succeed.","native":"Aunque la educación cambió mis propias perspectivas, la vivienda asequible, la atención sanitaria y una contratación justa también determinan si la gente puede tener éxito."}]},"zh":{"word":"教育","question":"教育能在多大程度上改变一个人的机会？哪些不平等无法由学校单独解决？","examples":[{"en":"Education can expand career choices and strengthen critical thinking, but qualifications do not guarantee equal access to work.","native":"教育可以拓宽职业选择并增强批判性思维，但学历并不能保证平等的就业机会。"},{"en":"Students learn more effectively when schools provide skilled teachers and support rather than expecting families to fill every gap.","native":"学校提供优秀教师和支持，而不是指望家庭弥补所有不足时，学生的学习会更有效。"},{"en":"Although education changed my own prospects, affordable housing, healthcare, and fair hiring also shape whether people can succeed.","native":"虽然教育改变了我自己的前景，但可负担住房、医疗服务和公平招聘也会影响人们能否成功。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'success', 'How should success be defined, and can ambition remain healthy when society constantly compares people by income and status?', '{"te":{"word":"విజయం","question":"విజయాన్ని ఎలా నిర్వచించాలి, సమాజం ఆదాయం మరియు హోదాతో ప్రజలను నిరంతరం పోల్చుతున్నప్పుడు ఆశయం ఆరోగ్యకరంగా ఉండగలదా?","examples":[{"en":"Financial security matters to me because it creates freedom, yet earning more would feel empty if my health and relationships suffered.","native":"ఆర్థిక భద్రత నాకు ముఖ్యం, ఎందుకంటే అది స్వేచ్ఛను ఇస్తుంది; అయినప్పటికీ నా ఆరోగ్యం మరియు సంబంధాలు దెబ్బతింటే ఎక్కువ సంపాదించడం శూన్యంగా అనిపిస్తుంది."},{"en":"I consider steady progress more meaningful than public recognition, especially when a goal requires years of patient effort.","native":"ఒక లక్ష్యానికి సంవత్సరాల ఓపికతో కూడిన కృషి అవసరమైనప్పుడు, బహిరంగ గుర్తింపు కంటే స్థిరమైన పురోగతినే నేను మరింత అర్థవంతంగా భావిస్తాను."},{"en":"Success should include knowing when enough is enough; otherwise ambition can turn every achievement into another source of pressure.","native":"ఎప్పుడు ఉన్నది చాలు అని తెలుసుకోవడం కూడా విజయంలో భాగం కావాలి; లేకపోతే ఆశయం ప్రతి సాధనను మరో ఒత్తిడి మూలంగా మార్చగలదు."}]},"hi":{"word":"सफलता","question":"सफलता को कैसे परिभाषित किया जाना चाहिए, और जब समाज लगातार आय और हैसियत के आधार पर लोगों की तुलना करता है, तब क्या महत्वाकांक्षा स्वस्थ रह सकती है?","examples":[{"en":"Financial security matters to me because it creates freedom, yet earning more would feel empty if my health and relationships suffered.","native":"वित्तीय सुरक्षा मेरे लिए मायने रखती है क्योंकि वह स्वतंत्रता देती है, फिर भी अगर मेरा स्वास्थ्य और रिश्ते बिगड़ें तो अधिक कमाई खोखली लगेगी।"},{"en":"I consider steady progress more meaningful than public recognition, especially when a goal requires years of patient effort.","native":"मैं सार्वजनिक पहचान से अधिक लगातार प्रगति को सार्थक मानता हूँ, खासकर जब किसी लक्ष्य के लिए वर्षों के धैर्यपूर्ण प्रयास की आवश्यकता हो।"},{"en":"Success should include knowing when enough is enough; otherwise ambition can turn every achievement into another source of pressure.","native":"सफलता में यह जानना भी शामिल होना चाहिए कि कब पर्याप्त हो चुका है; वरना महत्वाकांक्षा हर उपलब्धि को दबाव के एक और स्रोत में बदल सकती है।"}]},"es":{"word":"éxito","question":"¿Cómo debería definirse el éxito y puede mantenerse sana la ambición cuando la sociedad compara constantemente a las personas por sus ingresos y su posición?","examples":[{"en":"Financial security matters to me because it creates freedom, yet earning more would feel empty if my health and relationships suffered.","native":"La seguridad económica me importa porque aporta libertad, pero ganar más me parecería vacío si mi salud y mis relaciones se deterioraran."},{"en":"I consider steady progress more meaningful than public recognition, especially when a goal requires years of patient effort.","native":"Considero que el progreso constante tiene más sentido que el reconocimiento público, especialmente cuando una meta exige años de esfuerzo paciente."},{"en":"Success should include knowing when enough is enough; otherwise ambition can turn every achievement into another source of pressure.","native":"El éxito debería incluir saber cuándo es suficiente; de lo contrario, la ambición puede convertir cada logro en otra fuente de presión."}]},"zh":{"word":"成功","question":"应该如何定义成功？当社会不断按收入和地位比较人们时，抱负还能保持健康吗？","examples":[{"en":"Financial security matters to me because it creates freedom, yet earning more would feel empty if my health and relationships suffered.","native":"经济保障对我很重要，因为它带来自由；但如果健康和人际关系受损，赚得再多也会让我感到空虚。"},{"en":"I consider steady progress more meaningful than public recognition, especially when a goal requires years of patient effort.","native":"我认为稳定的进步比公众认可更有意义，尤其是当一个目标需要多年耐心努力时。"},{"en":"Success should include knowing when enough is enough; otherwise ambition can turn every achievement into another source of pressure.","native":"成功应该包括懂得知足；否则，抱负会把每项成就变成另一个压力来源。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'news', 'How do you decide whether a news report is trustworthy, and what responsibility do readers and journalists have when facts remain uncertain?', '{"te":{"word":"వార్తలు","question":"ఒక వార్తా నివేదిక నమ్మదగినదో కాదో మీరు ఎలా నిర్ణయిస్తారు, వాస్తవాలు ఇంకా అనిశ్చితంగా ఉన్నప్పుడు పాఠకులు మరియు పాత్రికేయులకు ఎలాంటి బాధ్యత ఉంటుంది?","examples":[{"en":"I trust a report more when it names its sources, distinguishes evidence from opinion, and corrects mistakes openly.","native":"ఒక నివేదిక తన మూలాలను పేర్కొని, ఆధారాలను అభిప్రాయాల నుంచి వేరు చేసి, తప్పులను బహిరంగంగా సరిచేస్తే నేను దాన్ని ఎక్కువగా నమ్ముతాను."},{"en":"Breaking news is useful, but the pressure to publish quickly can spread claims before they have been properly verified.","native":"తాజా వార్తలు ఉపయోగకరమే, కానీ త్వరగా ప్రచురించాలనే ఒత్తిడి వాదనలు సరిగా ధృవీకరించబడకముందే వాటిని వ్యాప్తి చేయవచ్చు."},{"en":"Readers should compare independent coverage before sharing a dramatic story, while journalists should state clearly what is still unknown.","native":"సంచలనాత్మక కథనాన్ని పంచుకునే ముందు పాఠకులు స్వతంత్ర వార్తా నివేదికలను పోల్చాలి, ఇంకా తెలియని విషయాలను పాత్రికేయులు స్పష్టంగా చెప్పాలి."}]},"hi":{"word":"समाचार","question":"आप कैसे तय करते हैं कि कोई समाचार रिपोर्ट भरोसेमंद है, और जब तथ्य अभी अनिश्चित हों तब पाठकों और पत्रकारों की क्या ज़िम्मेदारी है?","examples":[{"en":"I trust a report more when it names its sources, distinguishes evidence from opinion, and corrects mistakes openly.","native":"मुझे उस रिपोर्ट पर अधिक भरोसा होता है जो अपने स्रोतों का नाम बताती है, प्रमाण को राय से अलग करती है और गलतियों को खुले तौर पर सुधारती है।"},{"en":"Breaking news is useful, but the pressure to publish quickly can spread claims before they have been properly verified.","native":"ताज़ा खबरें उपयोगी हैं, लेकिन जल्दी प्रकाशित करने का दबाव दावों को ठीक से सत्यापित होने से पहले फैला सकता है।"},{"en":"Readers should compare independent coverage before sharing a dramatic story, while journalists should state clearly what is still unknown.","native":"पाठकों को कोई सनसनीखेज़ खबर साझा करने से पहले स्वतंत्र रिपोर्टों की तुलना करनी चाहिए, जबकि पत्रकारों को साफ़ बताना चाहिए कि अभी क्या अज्ञात है।"}]},"es":{"word":"noticias","question":"¿Cómo decides si una noticia es fiable y qué responsabilidad tienen lectores y periodistas cuando los hechos siguen siendo inciertos?","examples":[{"en":"I trust a report more when it names its sources, distinguishes evidence from opinion, and corrects mistakes openly.","native":"Confío más en una noticia cuando identifica sus fuentes, distingue las pruebas de la opinión y corrige abiertamente sus errores."},{"en":"Breaking news is useful, but the pressure to publish quickly can spread claims before they have been properly verified.","native":"Las noticias de última hora son útiles, pero la presión por publicar rápido puede difundir afirmaciones antes de que se hayan verificado correctamente."},{"en":"Readers should compare independent coverage before sharing a dramatic story, while journalists should state clearly what is still unknown.","native":"Los lectores deberían comparar coberturas independientes antes de compartir una historia impactante, mientras que los periodistas deberían indicar con claridad qué se desconoce todavía."}]},"zh":{"word":"新闻","question":"你如何判断一篇新闻报道是否可信？当事实仍不确定时，读者和记者各自负有什么责任？","examples":[{"en":"I trust a report more when it names its sources, distinguishes evidence from opinion, and corrects mistakes openly.","native":"如果一篇报道注明消息来源、区分证据与观点，并公开纠正错误，我会更信任它。"},{"en":"Breaking news is useful, but the pressure to publish quickly can spread claims before they have been properly verified.","native":"突发新闻很有用，但抢先发布的压力可能让一些说法在得到充分核实前就传播开来。"},{"en":"Readers should compare independent coverage before sharing a dramatic story, while journalists should state clearly what is still unknown.","native":"读者在分享引人注目的消息前应比较独立报道，而记者应明确说明哪些信息仍然未知。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'remote work', 'Discuss the advantages and disadvantages of remote work. Would you choose it?', '{"te":{"word":"రిమోట్ వర్క్","question":"రిమోట్ వర్క్ యొక్క ప్రయోజనాలు మరియు అప్రయోజనాలు గురించి చర్చించండి. మీరు దాన్ని ఎంచుకుంటారా?","examples":[{"en":"Remote work saves a lot of commuting time, but it can feel quite isolating after a while.","native":"రిమోట్ వర్క్ ప్రయాణ సమయాన్ని చాలా ఆదా చేస్తుంది, కానీ కొంతకాలం తర్వాత చాలా ఒంటరిగా అనిపించవచ్చు."},{"en":"Although offices cost money to maintain, they help new employees learn from experienced colleagues.","native":"ఆఫీసుల నిర్వహణకు డబ్బు ఖర్చవుతున్నప్పటికీ, కొత్త ఉద్యోగులు అనుభవజ్ఞులైన సహోద్యోగుల నుండి నేర్చుకోవడానికి అవి సహాయపడతాయి."},{"en":"If companies trusted their staff more, hybrid schedules would probably become the norm everywhere.","native":"కంపెనీలు తమ సిబ్బందిని మరింత నమ్మితే, హైబ్రిడ్ షెడ్యూళ్లు బహుశా ప్రతిచోటా సాధారణం అవుతాయి."}]},"hi":{"word":"रिमोट वर्क","question":"रिमोट वर्क के फ़ायदों और नुकसान पर चर्चा कीजिए। क्या आप इसे चुनेंगे?","examples":[{"en":"Remote work saves a lot of commuting time, but it can feel quite isolating after a while.","native":"रिमोट वर्क से आने-जाने का काफ़ी समय बचता है, लेकिन कुछ समय बाद यह काफ़ी अकेलापन महसूस करा सकता है।"},{"en":"Although offices cost money to maintain, they help new employees learn from experienced colleagues.","native":"हालाँकि दफ़्तरों को बनाए रखने में पैसा लगता है, वे नए कर्मचारियों को अनुभवी सहकर्मियों से सीखने में मदद करते हैं।"},{"en":"If companies trusted their staff more, hybrid schedules would probably become the norm everywhere.","native":"अगर कंपनियाँ अपने कर्मचारियों पर ज़्यादा भरोसा करें, तो हाइब्रिड शेड्यूल शायद हर जगह आम हो जाएँ।"}]},"es":{"word":"trabajo remoto","question":"Analiza las ventajas y desventajas del trabajo remoto. ¿Lo elegirías?","examples":[{"en":"Remote work saves a lot of commuting time, but it can feel quite isolating after a while.","native":"El trabajo remoto ahorra mucho tiempo de traslado, pero puede resultar bastante aislante después de un tiempo."},{"en":"Although offices cost money to maintain, they help new employees learn from experienced colleagues.","native":"Aunque mantener oficinas cuesta dinero, ayudan a los empleados nuevos a aprender de colegas con experiencia."},{"en":"If companies trusted their staff more, hybrid schedules would probably become the norm everywhere.","native":"Si las empresas confiaran más en su personal, los horarios híbridos probablemente se convertirían en la norma en todas partes."}]},"zh":{"word":"远程办公","question":"讨论远程办公的利与弊。你会选择远程办公吗？","examples":[{"en":"Remote work saves a lot of commuting time, but it can feel quite isolating after a while.","native":"远程办公能节省大量通勤时间，但时间一长可能会让人感到相当孤立。"},{"en":"Although offices cost money to maintain, they help new employees learn from experienced colleagues.","native":"尽管维护办公室需要花钱，但它能帮助新员工向有经验的同事学习。"},{"en":"If companies trusted their staff more, hybrid schedules would probably become the norm everywhere.","native":"如果公司更信任员工，混合办公模式可能会在各处成为常态。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'social media', 'How has social media changed the way people communicate? Is the change mostly positive or negative?', '{"te":{"word":"సోషల్ మీడియా","question":"సోషల్ మీడియా ప్రజలు కమ్యూనికేట్ చేసే విధానాన్ని ఎలా మార్చింది? ఈ మార్పు ఎక్కువగా సానుకూలమా లేక ప్రతికూలమా?","examples":[{"en":"Social media allows families to stay in touch, although it sometimes replaces real conversations.","native":"కుటుంబాలు టచ్‌లో ఉండటానికి సోషల్ మీడియా అనుమతిస్తుంది, అయితే ఇది కొన్నిసార్లు నిజమైన సంభాషణలను భర్తీ చేస్తుంది."},{"en":"If social platforms were regulated more strictly, fewer teenagers would be exposed to harmful content.","native":"సోషల్ ప్లాట్‌ఫారమ్‌లను మరింత కఠినంగా నియంత్రిస్తే, తక్కువ మంది టీనేజర్లు హానికరమైన కంటెంట్‌కు గురవుతారు."},{"en":"News is often shared faster online, but it is not always checked before it spreads.","native":"వార్తలు ఆన్‌లైన్‌లో తరచుగా వేగంగా షేర్ చేయబడతాయి, కానీ అవి వ్యాప్తి చెందే ముందు ఎల్లప్పుడూ తనిఖీ చేయబడవు."}]},"hi":{"word":"सोशल मीडिया","question":"सोशल मीडिया ने लोगों के संवाद करने के तरीके को कैसे बदला है? क्या यह बदलाव ज़्यादातर सकारात्मक है या नकारात्मक?","examples":[{"en":"Social media allows families to stay in touch, although it sometimes replaces real conversations.","native":"सोशल मीडिया परिवारों को जुड़े रहने देता है, हालाँकि यह कभी-कभी असली बातचीत की जगह ले लेता है।"},{"en":"If social platforms were regulated more strictly, fewer teenagers would be exposed to harmful content.","native":"अगर सोशल प्लेटफ़ॉर्म पर ज़्यादा सख़्त नियम लागू हों, तो कम किशोर हानिकारक कंटेंट के संपर्क में आएँगे।"},{"en":"News is often shared faster online, but it is not always checked before it spreads.","native":"ख़बरें अक्सर ऑनलाइन तेज़ी से साझा होती हैं, लेकिन फैलने से पहले उनकी जाँच हमेशा नहीं होती।"}]},"es":{"word":"redes sociales","question":"¿Cómo han cambiado las redes sociales la forma en que la gente se comunica? ¿Es un cambio mayormente positivo o negativo?","examples":[{"en":"Social media allows families to stay in touch, although it sometimes replaces real conversations.","native":"Las redes sociales permiten a las familias mantenerse en contacto, aunque a veces reemplazan las conversaciones reales."},{"en":"If social platforms were regulated more strictly, fewer teenagers would be exposed to harmful content.","native":"Si las plataformas sociales estuvieran reguladas con más rigor, menos adolescentes estarían expuestos a contenido dañino."},{"en":"News is often shared faster online, but it is not always checked before it spreads.","native":"Las noticias a menudo se comparten más rápido en línea, pero no siempre se verifican antes de difundirse."}]},"zh":{"word":"社交媒体","question":"社交媒体如何改变了人们的交流方式？这种变化主要是积极的还是消极的？","examples":[{"en":"Social media allows families to stay in touch, although it sometimes replaces real conversations.","native":"社交媒体让家人能够保持联系，尽管它有时取代了真正的交谈。"},{"en":"If social platforms were regulated more strictly, fewer teenagers would be exposed to harmful content.","native":"如果对社交平台的监管更加严格，接触有害内容的青少年就会减少。"},{"en":"News is often shared faster online, but it is not always checked before it spreads.","native":"新闻往往在网上传播得更快，但在扩散之前并不总是经过核实。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'leadership', 'What qualities make a good leader? Can leadership be learned, or is it a natural talent?', '{"te":{"word":"నాయకత్వం","question":"మంచి నాయకుడికి ఏ లక్షణాలు ఉండాలి? నాయకత్వం నేర్చుకోవచ్చా, లేక అది సహజ ప్రతిభయేనా?","examples":[{"en":"A good leader listens carefully, although making quick decisions is also part of the role.","native":"మంచి నాయకుడు జాగ్రత్తగా వింటాడు, అయితే త్వరగా నిర్ణయాలు తీసుకోవడం కూడా ఆ పాత్రలో భాగం."},{"en":"If leadership courses were offered in every school, more young people would gain confidence early.","native":"ప్రతి పాఠశాలలో నాయకత్వ కోర్సులు అందించబడితే, మరిన్ని మంది యువకులు త్వరగా ఆత్మవిశ్వాసం పొందుతారు."},{"en":"Authority is often given to confident public speakers, but real leadership is shown through consistent actions.","native":"అధికారం తరచుగా ఆత్మవిశ్వాసంతో ప్రజల ముందు మాట్లాడేవారికి ఇవ్వబడుతుంది, కానీ నిజమైన నాయకత్వం స్థిరమైన చర్యల ద్వారా కనిపిస్తుంది."}]},"hi":{"word":"नेतृत्व","question":"अच्छे नेता में कौन-से गुण होने चाहिए? क्या नेतृत्व सीखा जा सकता है, या यह स्वाभाविक प्रतिभा है?","examples":[{"en":"A good leader listens carefully, although making quick decisions is also part of the role.","native":"अच्छा नेता ध्यान से सुनता है, हालाँकि जल्दी फ़ैसले लेना भी इस भूमिका का हिस्सा है।"},{"en":"If leadership courses were offered in every school, more young people would gain confidence early.","native":"अगर हर स्कूल में नेतृत्व के पाठ्यक्रम दिए जाएँ, तो ज़्यादा युवा जल्दी आत्मविश्वास हासिल करेंगे।"},{"en":"Authority is often given to confident public speakers, but real leadership is shown through consistent actions.","native":"अधिकार अक्सर आत्मविश्वासी सार्वजनिक वक्ताओं को दिया जाता है, लेकिन असली नेतृत्व लगातार कार्यों से दिखता है।"}]},"es":{"word":"liderazgo","question":"¿Qué cualidades hacen a un buen líder? ¿Se puede aprender a liderar o es un talento natural?","examples":[{"en":"A good leader listens carefully, although making quick decisions is also part of the role.","native":"Un buen líder escucha con atención, aunque tomar decisiones rápidas también es parte del papel."},{"en":"If leadership courses were offered in every school, more young people would gain confidence early.","native":"Si se ofrecieran cursos de liderazgo en todas las escuelas, más jóvenes ganarían confianza desde temprano."},{"en":"Authority is often given to confident public speakers, but real leadership is shown through consistent actions.","native":"La autoridad a menudo se concede a los oradores seguros, pero el verdadero liderazgo se demuestra con acciones constantes."}]},"zh":{"word":"领导力","question":"哪些品质能造就一位优秀的领导者？领导力是可以学习的，还是天生的才能？","examples":[{"en":"A good leader listens carefully, although making quick decisions is also part of the role.","native":"优秀的领导者会认真倾听，尽管快速决策也是这一角色的一部分。"},{"en":"If leadership courses were offered in every school, more young people would gain confidence early.","native":"如果每所学校都开设领导力课程，更多年轻人会及早获得自信。"},{"en":"Authority is often given to confident public speakers, but real leadership is shown through consistent actions.","native":"权力往往被授予自信的公开演说者，但真正的领导力体现在始终如一的行动中。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'stress', 'Why do people experience more stress today than in the past? How can it be managed?', '{"te":{"word":"ఒత్తిడి","question":"గతం కంటే ఈరోజుల్లో ప్రజలు ఎందుకు ఎక్కువ ఒత్తిడిని అనుభవిస్తున్నారు? దాన్ని ఎలా నిర్వహించవచ్చు?","examples":[{"en":"Although modern life is more comfortable, people are expected to be available all the time.","native":"ఆధునిక జీవితం మరింత సౌకర్యవంతంగా ఉన్నప్పటికీ, ప్రజలు ఎల్లప్పుడూ అందుబాటులో ఉండాలని భావిస్తారు."},{"en":"Stress can be reduced if regular exercise and enough sleep are treated as real priorities.","native":"క్రమం తప్పకుండా వ్యాయామం మరియు తగినంత నిద్రను నిజమైన ప్రాధాన్యతలుగా భావిస్తే ఒత్తిడిని తగ్గించవచ్చు."},{"en":"If employers encouraged shorter working hours, many health problems could be prevented before they start.","native":"యజమానులు తక్కువ పని గంటలను ప్రోత్సహిస్తే, అనేక ఆరోగ్య సమస్యలు ప్రారంభం కాకముందే నివారించబడవచ్చు."}]},"hi":{"word":"तनाव","question":"लोग आज अतीत की तुलना में ज़्यादा तनाव क्यों महसूस करते हैं? इसे कैसे नियंत्रित किया जा सकता है?","examples":[{"en":"Although modern life is more comfortable, people are expected to be available all the time.","native":"हालाँकि आधुनिक जीवन ज़्यादा आरामदायक है, लोगों से हर समय उपलब्ध रहने की उम्मीद की जाती है।"},{"en":"Stress can be reduced if regular exercise and enough sleep are treated as real priorities.","native":"नियमित व्यायाम और पर्याप्त नींद को सच्ची प्राथमिकता माना जाए तो तनाव घटाया जा सकता है।"},{"en":"If employers encouraged shorter working hours, many health problems could be prevented before they start.","native":"अगर नियोक्ता कम काम के घंटों को प्रोत्साहित करें, तो कई स्वास्थ्य समस्याएँ शुरू होने से पहले रोकी जा सकती हैं।"}]},"es":{"word":"estrés","question":"¿Por qué la gente sufre más estrés hoy que antes? ¿Cómo se puede manejar?","examples":[{"en":"Although modern life is more comfortable, people are expected to be available all the time.","native":"Aunque la vida moderna es más cómoda, se espera que la gente esté disponible todo el tiempo."},{"en":"Stress can be reduced if regular exercise and enough sleep are treated as real priorities.","native":"El estrés puede reducirse si el ejercicio regular y el sueño suficiente se tratan como prioridades reales."},{"en":"If employers encouraged shorter working hours, many health problems could be prevented before they start.","native":"Si los empleadores fomentaran jornadas más cortas, muchos problemas de salud podrían prevenirse antes de empezar."}]},"zh":{"word":"压力","question":"为什么如今人们比过去承受更大的压力？应该如何应对压力？","examples":[{"en":"Although modern life is more comfortable, people are expected to be available all the time.","native":"尽管现代生活更加舒适，人们却被期望随时保持在线。"},{"en":"Stress can be reduced if regular exercise and enough sleep are treated as real priorities.","native":"如果把规律锻炼和充足睡眠当作真正的优先事项，压力是可以减轻的。"},{"en":"If employers encouraged shorter working hours, many health problems could be prevented before they start.","native":"如果雇主鼓励缩短工作时间，许多健康问题可以在发生之前得到预防。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'advertising', 'Does advertising influence what people buy, or do consumers make independent choices?', '{"te":{"word":"ప్రకటనలు","question":"ప్రజలు ఏమి కొనుగోలు చేస్తారో ప్రకటనలు ప్రభావితం చేస్తాయా, లేక వినియోగదారులు స్వతంత్రంగా నిర్ణయాలు తీసుకుంటారా?","examples":[{"en":"Advertisements are designed to create desires, although most viewers believe they are immune to them.","native":"ప్రకటనలు కోరికలను సృష్టించడానికి రూపొందించబడతాయి, అయితే చాలామంది వీక్షకులు తాము వాటి ప్రభావానికి లోనవ్వమని నమ్ముతారు."},{"en":"If advertising aimed at children were banned, parents would probably face fewer demands in supermarkets.","native":"పిల్లలను లక్ష్యంగా చేసుకునే ప్రకటనలను నిషేధిస్తే, సూపర్ మార్కెట్లలో తల్లిదండ్రులు బహుశా తక్కువ డిమాండ్లను ఎదుర్కొంటారు."},{"en":"Products are often remembered because of emotion, not because of the quality they actually offer.","native":"ఉత్పత్తులు వాస్తవంగా అందించే నాణ్యత వల్ల కాకుండా భావోద్వేగం వల్ల తరచుగా గుర్తుండిపోతాయి."}]},"hi":{"word":"विज्ञापन","question":"क्या विज्ञापन लोगों की ख़रीदारी को प्रभावित करते हैं, या उपभोक्ता स्वतंत्र रूप से फ़ैसले करते हैं?","examples":[{"en":"Advertisements are designed to create desires, although most viewers believe they are immune to them.","native":"विज्ञापन इच्छाएँ पैदा करने के लिए बनाए जाते हैं, हालाँकि ज़्यादातर दर्शक मानते हैं कि वे इनसे अछूते हैं।"},{"en":"If advertising aimed at children were banned, parents would probably face fewer demands in supermarkets.","native":"अगर बच्चों पर निशाना साधने वाले विज्ञापनों पर रोक लगा दी जाए, तो सुपरमार्केट में माता-पिता को शायद कम माँगों का सामना करना पड़े।"},{"en":"Products are often remembered because of emotion, not because of the quality they actually offer.","native":"उत्पाद अक्सर अपनी असली गुणवत्ता की वजह से नहीं, बल्कि भावना की वजह से याद रहते हैं।"}]},"es":{"word":"publicidad","question":"¿Influye la publicidad en lo que compra la gente, o los consumidores deciden de forma independiente?","examples":[{"en":"Advertisements are designed to create desires, although most viewers believe they are immune to them.","native":"Los anuncios están diseñados para crear deseos, aunque la mayoría de los espectadores cree que es inmune a ellos."},{"en":"If advertising aimed at children were banned, parents would probably face fewer demands in supermarkets.","native":"Si se prohibiera la publicidad dirigida a los niños, los padres probablemente enfrentarían menos exigencias en los supermercados."},{"en":"Products are often remembered because of emotion, not because of the quality they actually offer.","native":"Los productos a menudo se recuerdan por la emoción, no por la calidad que realmente ofrecen."}]},"zh":{"word":"广告","question":"广告会影响人们的购买行为吗，还是消费者会做出独立的选择？","examples":[{"en":"Advertisements are designed to create desires, although most viewers believe they are immune to them.","native":"广告被设计用来制造欲望，尽管大多数观众认为自己对其免疫。"},{"en":"If advertising aimed at children were banned, parents would probably face fewer demands in supermarkets.","native":"如果禁止针对儿童的广告，父母在超市里可能会面临更少的要求。"},{"en":"Products are often remembered because of emotion, not because of the quality they actually offer.","native":"产品往往因为情感因素而被记住，而不是因为它们实际提供的品质。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'immigration', 'What challenges do immigrants face in a new country, and how can societies help them integrate?', '{"te":{"word":"వలస","question":"కొత్త దేశంలో వలసదారులు ఏ సవాళ్లను ఎదుర్కొంటారు, మరియు వారు ఇమిడిపోవడానికి సమాజాలు ఎలా సహాయపడగలవు?","examples":[{"en":"Immigrants are often expected to adapt quickly, although learning a language takes many years.","native":"వలసదారులు త్వరగా సరిపోవాలని తరచుగా భావిస్తారు, అయితే ఒక భాష నేర్చుకోవడానికి చాలా సంవత్సరాలు పడుతుంది."},{"en":"If free language courses were provided to newcomers, integration would probably happen much more smoothly.","native":"కొత్తగా వచ్చినవారికి ఉచిత భాషా కోర్సులు అందించబడితే, ఇమిడిపోవడం బహుశా మరింత సాఫీగా జరుగుతుంది."},{"en":"Communities become richer when different traditions are shared, but openness is required on both sides.","native":"విభిన్న సంప్రదాయాలు పంచుకున్నప్పుడు సమాజాలు సమృద్ధిగా మారతాయి, కానీ రెండు వైపులా విశాలమైన దృక్పథం అవసరం."}]},"hi":{"word":"आप्रवासन","question":"नए देश में आप्रवासियों को कौन-सी चुनौतियों का सामना करना पड़ता है, और समाज उनके समावेश में कैसे मदद कर सकते हैं?","examples":[{"en":"Immigrants are often expected to adapt quickly, although learning a language takes many years.","native":"आप्रवासियों से अक्सर जल्दी ढलने की उम्मीद की जाती है, हालाँकि भाषा सीखने में कई साल लगते हैं।"},{"en":"If free language courses were provided to newcomers, integration would probably happen much more smoothly.","native":"अगर नवागंतुकों को मुफ़्त भाषा पाठ्यक्रम दिए जाएँ, तो समावेश शायद कहीं ज़्यादा सुगमता से होगा।"},{"en":"Communities become richer when different traditions are shared, but openness is required on both sides.","native":"जब अलग-अलग परंपराएँ साझा होती हैं तो समाज समृद्ध बनते हैं, लेकिन दोनों ओर से खुलेपन की ज़रूरत होती है।"}]},"es":{"word":"inmigración","question":"¿Qué desafíos enfrentan los inmigrantes en un país nuevo y cómo pueden las sociedades ayudarlos a integrarse?","examples":[{"en":"Immigrants are often expected to adapt quickly, although learning a language takes many years.","native":"A menudo se espera que los inmigrantes se adapten rápido, aunque aprender un idioma lleva muchos años."},{"en":"If free language courses were provided to newcomers, integration would probably happen much more smoothly.","native":"Si se ofrecieran cursos de idiomas gratuitos a los recién llegados, la integración probablemente sería mucho más fluida."},{"en":"Communities become richer when different traditions are shared, but openness is required on both sides.","native":"Las comunidades se enriquecen cuando se comparten tradiciones diferentes, pero se requiere apertura de ambas partes."}]},"zh":{"word":"移民","question":"移民在新国家面临哪些挑战？社会如何帮助他们融入？","examples":[{"en":"Immigrants are often expected to adapt quickly, although learning a language takes many years.","native":"人们常常期望移民迅速适应，尽管学习一门语言需要很多年。"},{"en":"If free language courses were provided to newcomers, integration would probably happen much more smoothly.","native":"如果为新来者提供免费语言课程，融入过程可能会顺利得多。"},{"en":"Communities become richer when different traditions are shared, but openness is required on both sides.","native":"当不同的传统被分享时，社区会变得更加丰富，但这需要双方都保持开放。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'science', 'Should governments invest more in scientific research, even when the results are uncertain?', '{"te":{"word":"సైన్స్","question":"ఫలితాలు అనిశ్చితంగా ఉన్నప్పటికీ ప్రభుత్వాలు శాస్త్రీయ పరిశోధనలో మరింత పెట్టుబడి పెట్టాలా?","examples":[{"en":"Scientific research is expensive, but history shows that unexpected discoveries often benefit everyone much later.","native":"శాస్త్రీయ పరిశోధన ఖరీదైనది, కానీ ఊహించని ఆవిష్కరణలు తరచుగా చాలా తర్వాత అందరికీ ప్రయోజనం చేకూరుస్తాయని చరిత్ర చూపిస్తుంది."},{"en":"If public funding were cut, only profitable areas of science would continue to be explored.","native":"ప్రభుత్వ నిధులు తగ్గించబడితే, లాభదాయకమైన శాస్త్రీయ రంగాలు మాత్రమే అన్వేషించబడుతూ ఉంటాయి."},{"en":"Although results can never be guaranteed, curiosity-driven projects have already changed the world many times.","native":"ఫలితాలకు ఎప్పుడూ హామీ ఇవ్వలేము అయినప్పటికీ, జిజ్ఞాసతో నడిచే ప్రాజెక్టులు ఇప్పటికే ప్రపంచాన్ని చాలాసార్లు మార్చాయి."}]},"hi":{"word":"विज्ञान","question":"क्या सरकारों को वैज्ञानिक अनुसंधान में और निवेश करना चाहिए, भले ही परिणाम अनिश्चित हों?","examples":[{"en":"Scientific research is expensive, but history shows that unexpected discoveries often benefit everyone much later.","native":"वैज्ञानिक अनुसंधान महँगा है, लेकिन इतिहास बताता है कि अप्रत्याशित खोजें अक्सर काफ़ी बाद में सबको फ़ायदा पहुँचाती हैं।"},{"en":"If public funding were cut, only profitable areas of science would continue to be explored.","native":"अगर सार्वजनिक धन में कटौती हो जाए, तो विज्ञान के केवल लाभदायक क्षेत्रों की ही खोज जारी रहेगी।"},{"en":"Although results can never be guaranteed, curiosity-driven projects have already changed the world many times.","native":"हालाँकि परिणामों की कभी गारंटी नहीं दी जा सकती, जिज्ञासा-आधारित परियोजनाएँ दुनिया को पहले ही कई बार बदल चुकी हैं।"}]},"es":{"word":"ciencia","question":"¿Deberían los gobiernos invertir más en investigación científica, incluso cuando los resultados son inciertos?","examples":[{"en":"Scientific research is expensive, but history shows that unexpected discoveries often benefit everyone much later.","native":"La investigación científica es cara, pero la historia muestra que los descubrimientos inesperados suelen beneficiar a todos mucho después."},{"en":"If public funding were cut, only profitable areas of science would continue to be explored.","native":"Si se recortara la financiación pública, solo se seguirían explorando las áreas rentables de la ciencia."},{"en":"Although results can never be guaranteed, curiosity-driven projects have already changed the world many times.","native":"Aunque los resultados nunca pueden garantizarse, los proyectos impulsados por la curiosidad ya han cambiado el mundo muchas veces."}]},"zh":{"word":"科学","question":"即使结果不确定，政府也应该在科学研究上投入更多资金吗？","examples":[{"en":"Scientific research is expensive, but history shows that unexpected discoveries often benefit everyone much later.","native":"科学研究耗资巨大，但历史表明，意外的发现往往在很久以后惠及所有人。"},{"en":"If public funding were cut, only profitable areas of science would continue to be explored.","native":"如果削减公共资金，科学领域中将只有有利可图的方向会继续被探索。"},{"en":"Although results can never be guaranteed, curiosity-driven projects have already changed the world many times.","native":"尽管结果永远无法保证，但由好奇心驱动的项目已经多次改变了世界。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'fashion industry', 'Is the fashion industry harmful to society, or does it play a valuable cultural role?', '{"te":{"word":"ఫ్యాషన్ పరిశ్రమ","question":"ఫ్యాషన్ పరిశ్రమ సమాజానికి హానికరమా, లేక అది విలువైన సాంస్కృతిక పాత్ర పోషిస్తుందా?","examples":[{"en":"Trends are changed every season so that people feel pressured to buy clothes they do not need.","native":"ప్రజలకు అవసరం లేని దుస్తులు కొనాలన్న ఒత్తిడి కలిగించడానికి ప్రతి సీజన్‌లో ట్రెండ్‌లు మార్చబడతాయి."},{"en":"Although fashion can express identity, the industry is criticised for waste and poor working conditions.","native":"ఫ్యాషన్ గుర్తింపును వ్యక్తపరచగలదు అయినప్పటికీ, వ్యర్థాలు మరియు పేలవమైన పని పరిస్థితుల కోసం ఈ పరిశ్రమ విమర్శించబడుతుంది."},{"en":"If sustainable materials became cheaper, environmentally friendly clothing would probably be chosen more often.","native":"సస్టైనబుల్ మెటీరియల్స్ చవకగా మారితే, పర్యావరణ అనుకూల దుస్తులు బహుశా మరింత తరచుగా ఎంపిక చేయబడతాయి."}]},"hi":{"word":"फ़ैशन उद्योग","question":"क्या फ़ैशन उद्योग समाज के लिए हानिकारक है, या यह कोई मूल्यवान सांस्कृतिक भूमिका निभाता है?","examples":[{"en":"Trends are changed every season so that people feel pressured to buy clothes they do not need.","native":"ट्रेंड हर सीज़न बदले जाते हैं ताकि लोग वे कपड़े ख़रीदने का दबाव महसूस करें जिनकी उन्हें ज़रूरत नहीं है।"},{"en":"Although fashion can express identity, the industry is criticised for waste and poor working conditions.","native":"हालाँकि फ़ैशन पहचान व्यक्त कर सकता है, इस उद्योग की आलोचना कचरे और ख़राब कामकाजी हालात के लिए होती है।"},{"en":"If sustainable materials became cheaper, environmentally friendly clothing would probably be chosen more often.","native":"अगर टिकाऊ सामग्रियाँ सस्ती हो जाएँ, तो पर्यावरण-अनुकूल कपड़ों को शायद ज़्यादा बार चुना जाएगा।"}]},"es":{"word":"industria de la moda","question":"¿Es la industria de la moda perjudicial para la sociedad o desempeña un valioso papel cultural?","examples":[{"en":"Trends are changed every season so that people feel pressured to buy clothes they do not need.","native":"Las tendencias cambian cada temporada para que la gente se sienta presionada a comprar ropa que no necesita."},{"en":"Although fashion can express identity, the industry is criticised for waste and poor working conditions.","native":"Aunque la moda puede expresar identidad, la industria es criticada por el desperdicio y las malas condiciones laborales."},{"en":"If sustainable materials became cheaper, environmentally friendly clothing would probably be chosen more often.","native":"Si los materiales sostenibles fueran más baratos, probablemente se elegiría ropa ecológica con más frecuencia."}]},"zh":{"word":"时尚产业","question":"时尚产业对社会有害吗，还是它扮演着宝贵的文化角色？","examples":[{"en":"Trends are changed every season so that people feel pressured to buy clothes they do not need.","native":"潮流每一季都在变化，让人们感到有压力去购买自己并不需要的衣服。"},{"en":"Although fashion can express identity, the industry is criticised for waste and poor working conditions.","native":"尽管时尚可以表达身份，但这个行业因浪费和恶劣的工作条件而受到批评。"},{"en":"If sustainable materials became cheaper, environmentally friendly clothing would probably be chosen more often.","native":"如果可持续材料变得更便宜，环保服装可能会被更频繁地选择。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'online learning', 'Can online learning replace traditional classrooms? What is lost when education moves online?', '{"te":{"word":"ఆన్‌లైన్ లెర్నింగ్","question":"ఆన్‌లైన్ లెర్నింగ్ సాంప్రదాయ తరగతి గదులను భర్తీ చేయగలదా? విద్య ఆన్‌లైన్‌కు మారినప్పుడు ఏమి కోల్పోతాం?","examples":[{"en":"Online courses allow adults to study while working, although self-discipline is needed to finish them.","native":"ఆన్‌లైన్ కోర్సులు పని చేస్తూ పెద్దలు చదువుకోవడానికి అనుమతిస్తాయి, అయితే వాటిని పూర్తి చేయడానికి స్వయం క్రమశిక్షణ అవసరం."},{"en":"If classrooms disappeared completely, children would miss the social skills learned through daily contact.","native":"తరగతి గదులు పూర్తిగా అదృశ్యమైతే, రోజువారీ సంపర్కం ద్వారా నేర్చుకునే సామాజిక నైపుణ్యాలను పిల్లలు కోల్పోతారు."},{"en":"Recorded lectures can be paused and repeated, but questions are answered more slowly than in person.","native":"రికార్డ్ చేసిన ఉపన్యాసాలను పాజ్ చేయవచ్చు మరియు మళ్లీ వినవచ్చు, కానీ ప్రశ్నలకు సమాధానాలు ప్రత్యక్షంగా కంటే నెమ్మదిగా లభిస్తాయి."}]},"hi":{"word":"ऑनलाइन शिक्षा","question":"क्या ऑनलाइन शिक्षा पारंपरिक कक्षाओं की जगह ले सकती है? शिक्षा के ऑनलाइन होने से क्या खोता है?","examples":[{"en":"Online courses allow adults to study while working, although self-discipline is needed to finish them.","native":"ऑनलाइन पाठ्यक्रम वयस्कों को काम करते हुए पढ़ने देते हैं, हालाँकि उन्हें पूरा करने के लिए आत्म-अनुशासन चाहिए।"},{"en":"If classrooms disappeared completely, children would miss the social skills learned through daily contact.","native":"अगर कक्षाएँ पूरी तरह गायब हो जाएँ, तो बच्चे रोज़मर्रा के संपर्क से सीखे जाने वाले सामाजिक कौशल खो देंगे।"},{"en":"Recorded lectures can be paused and repeated, but questions are answered more slowly than in person.","native":"रिकॉर्ड किए गए व्याख्यान रोके और दोहराए जा सकते हैं, लेकिन सवालों के जवाब आमने-सामने की तुलना में देर से मिलते हैं।"}]},"es":{"word":"aprendizaje en línea","question":"¿Puede el aprendizaje en línea reemplazar las aulas tradicionales? ¿Qué se pierde cuando la educación se traslada a internet?","examples":[{"en":"Online courses allow adults to study while working, although self-discipline is needed to finish them.","native":"Los cursos en línea permiten a los adultos estudiar mientras trabajan, aunque se necesita autodisciplina para terminarlos."},{"en":"If classrooms disappeared completely, children would miss the social skills learned through daily contact.","native":"Si las aulas desaparecieran por completo, los niños perderían las habilidades sociales que se aprenden con el contacto diario."},{"en":"Recorded lectures can be paused and repeated, but questions are answered more slowly than in person.","native":"Las clases grabadas se pueden pausar y repetir, pero las preguntas se responden más lentamente que en persona."}]},"zh":{"word":"在线学习","question":"在线学习能取代传统课堂吗？教育转到线上会失去什么？","examples":[{"en":"Online courses allow adults to study while working, although self-discipline is needed to finish them.","native":"在线课程让成年人可以边工作边学习，尽管完成课程需要自律。"},{"en":"If classrooms disappeared completely, children would miss the social skills learned through daily contact.","native":"如果课堂完全消失，孩子们将失去通过日常接触学到的社交技能。"},{"en":"Recorded lectures can be paused and repeated, but questions are answered more slowly than in person.","native":"录播课程可以暂停和重复，但问题的回答速度比面对面慢。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'competition', 'Does competition bring out the best in people, or does it create unnecessary pressure?', '{"te":{"word":"పోటీ","question":"పోటీ ప్రజల్లోని మంచిని బయటపెడుతుందా, లేక అనవసరమైన ఒత్తిడిని సృష్టిస్తుందా?","examples":[{"en":"Competition pushes athletes to train harder, although too much of it can destroy the joy of playing.","native":"పోటీ క్రీడాకారులను మరింత కష్టపడి శిక్షణ పొందేలా ప్రేరేపిస్తుంది, అయితే అది అతిగా ఉంటే ఆటలోని ఆనందాన్ని నాశనం చేస్తుంది."},{"en":"If workplaces rewarded cooperation rather than constant rivalry, fewer employees would feel exhausted and anxious.","native":"కార్యాలయాలు నిరంతర ప్రతిద్వంద్విత్వం బదులు సహకారానికి బహూమతులు ఇస్తే, తక్కువ మంది ఉద్యోగులు అలసిపోయి ఆందోళనగా ఉంటారు."},{"en":"Marks and rankings are easily compared, but creativity is rarely measured fairly in competitive exams.","native":"మార్కులు మరియు ర్యాంకులను సులభంగా పోల్చవచ్చు, కానీ పోటీ పరీక్షల్లో సృజనాత్మకతను అరుదుగా న్యాయంగా కొలుస్తారు."}]},"hi":{"word":"प्रतिस्पर्धा","question":"क्या प्रतिस्पर्धा लोगों के अंदर की सर्वश्रेष्ठता उजागर करती है, या यह अनावश्यक दबाव पैदा करती है?","examples":[{"en":"Competition pushes athletes to train harder, although too much of it can destroy the joy of playing.","native":"प्रतिस्पर्धा एथलीटों को और मेहनत से अभ्यास करने पर प्रेरित करती है, हालाँकि इसकी अधिकता खेल का आनंद नष्ट कर सकती है।"},{"en":"If workplaces rewarded cooperation rather than constant rivalry, fewer employees would feel exhausted and anxious.","native":"अगर कार्यस्थल निरंतर प्रतिद्वंद्विता के बजाय सहयोग को पुरस्कृत करें, तो कम कर्मचारी थके और चिंतित महसूस करेंगे।"},{"en":"Marks and rankings are easily compared, but creativity is rarely measured fairly in competitive exams.","native":"अंकों और रैंकिंग की तुलना आसानी से हो जाती है, लेकिन प्रतियोगी परीक्षाओं में रचनात्मकता शायद ही कभी निष्पक्ष रूप से मापी जाती है।"}]},"es":{"word":"competencia","question":"¿La competencia saca lo mejor de las personas o crea una presión innecesaria?","examples":[{"en":"Competition pushes athletes to train harder, although too much of it can destroy the joy of playing.","native":"La competencia empuja a los atletas a entrenar más, aunque demasiada puede destruir la alegría de jugar."},{"en":"If workplaces rewarded cooperation rather than constant rivalry, fewer employees would feel exhausted and anxious.","native":"Si los lugares de trabajo recompensaran la cooperación en lugar de la rivalidad constante, menos empleados se sentirían agotados y ansiosos."},{"en":"Marks and rankings are easily compared, but creativity is rarely measured fairly in competitive exams.","native":"Las notas y las clasificaciones se comparan fácilmente, pero la creatividad rara vez se mide con justicia en los exámenes competitivos."}]},"zh":{"word":"竞争","question":"竞争能激发人们最好的一面，还是会制造不必要的压力？","examples":[{"en":"Competition pushes athletes to train harder, although too much of it can destroy the joy of playing.","native":"竞争促使运动员更加刻苦训练，尽管过度的竞争会破坏运动的乐趣。"},{"en":"If workplaces rewarded cooperation rather than constant rivalry, fewer employees would feel exhausted and anxious.","native":"如果工作场所奖励合作而不是持续的对抗，感到疲惫和焦虑的员工会更少。"},{"en":"Marks and rankings are easily compared, but creativity is rarely measured fairly in competitive exams.","native":"分数和排名很容易比较，但在竞争性考试中，创造力很少被公平地衡量。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'volunteering', 'Why do people volunteer, and should volunteering be required in schools or workplaces?', '{"te":{"word":"స్వచ్ఛంద సేవ","question":"ప్రజలు ఎందుకు స్వచ్ఛందంగా సేవ చేస్తారు, మరియు పాఠశాలల్లో లేదా కార్యాలయాల్లో స్వచ్ఛంద సేవ తప్పనిసరి చేయాలా?","examples":[{"en":"People volunteer because it gives them purpose, although free time is often limited by work.","native":"ప్రజలు స్వచ్ఛందంగా సేవ చేస్తారు ఎందుకంటే అది వారికి లక్ష్యాన్ని ఇస్తుంది, అయితే ఖాళీ సమయం తరచుగా పని వల్ల పరిమితం అవుతుంది."},{"en":"If volunteering were compulsory at school, students would discover needs they never notice otherwise.","native":"పాఠశాలలో స్వచ్ఛంద సేవ తప్పనిసరి అయితే, విద్యార్థులు లేకపోతే గమనించని అవసరాలను కనుగొంటారు."},{"en":"Communities are strengthened when help is offered freely, but volunteers should never replace paid staff.","native":"సహాయం స్వేచ్ఛగా అందించబడినప్పుడు సమాజాలు బలపడతాయి, కానీ స్వచ్ఛందులు ఎప్పుడూ జీతం పొందే సిబ్బంది స్థానంలో ఉండకూడదు."}]},"hi":{"word":"स्वयंसेवा","question":"लोग स्वयंसेवा क्यों करते हैं, और क्या स्कूलों या कार्यस्थलों पर स्वयंसेवा अनिवार्य होनी चाहिए?","examples":[{"en":"People volunteer because it gives them purpose, although free time is often limited by work.","native":"लोग स्वयंसेवा करते हैं क्योंकि यह उन्हें उद्देश्य देती है, हालाँकि खाली समय अक्सर काम से सीमित होता है।"},{"en":"If volunteering were compulsory at school, students would discover needs they never notice otherwise.","native":"अगर स्कूल में स्वयंसेवा अनिवार्य हो, तो छात्र उन ज़रूरतों को खोजेंगे जिन पर वे वरना ध्यान नहीं देते।"},{"en":"Communities are strengthened when help is offered freely, but volunteers should never replace paid staff.","native":"जब मदद स्वतंत्र रूप से दी जाती है तो समुदाय मज़बूत होते हैं, लेकिन स्वयंसेवकों को कभी भी वेतनभोगी स्टाफ़ की जगह नहीं लेनी चाहिए।"}]},"es":{"word":"voluntariado","question":"¿Por qué la gente hace voluntariado, y debería ser obligatorio en las escuelas o los lugares de trabajo?","examples":[{"en":"People volunteer because it gives them purpose, although free time is often limited by work.","native":"La gente hace voluntariado porque le da un propósito, aunque el tiempo libre suele estar limitado por el trabajo."},{"en":"If volunteering were compulsory at school, students would discover needs they never notice otherwise.","native":"Si el voluntariado fuera obligatorio en la escuela, los estudiantes descubrirían necesidades que de otro modo nunca notan."},{"en":"Communities are strengthened when help is offered freely, but volunteers should never replace paid staff.","native":"Las comunidades se fortalecen cuando la ayuda se ofrece libremente, pero los voluntarios nunca deberían reemplazar al personal remunerado."}]},"zh":{"word":"志愿服务","question":"人们为什么做志愿者？学校或工作场所是否应该强制要求志愿服务？","examples":[{"en":"People volunteer because it gives them purpose, although free time is often limited by work.","native":"人们做志愿者是因为这给了他们目标感，尽管空闲时间往往受到工作的限制。"},{"en":"If volunteering were compulsory at school, students would discover needs they never notice otherwise.","native":"如果学校强制要求志愿服务，学生们会发现他们平时从未注意到的需求。"},{"en":"Communities are strengthened when help is offered freely, but volunteers should never replace paid staff.","native":"当帮助被自愿提供时，社区会变得更强，但志愿者绝不应取代带薪员工。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'consumerism', 'Does buying more things make people happier, or does consumerism create false needs?', '{"te":{"word":"వినియోగవాదం","question":"ఎక్కువ వస్తువులు కొనడం ప్రజలను సంతోషపెడుతుందా, లేక వినియోగవాదం అవాస్తవ అవసరాలను సృష్టిస్తుందా?","examples":[{"en":"Happiness from shopping fades quickly, although advertisements promise that the next purchase will last.","native":"షాపింగ్ నుండి వచ్చే సంతోషం త్వరగా మసకబారుతుంది, అయితే తదుపరి కొనుగోలు శాశ్వతమవుతుందని ప్రకటనలు హామీ ఇస్తాయి."},{"en":"If people repaired things instead of replacing them, far less waste would be produced every year.","native":"ప్రజలు వస్తువులను మార్చడం బదులు మరమ్మతు చేస్తే, ప్రతి సంవత్సరం చాలా తక్కువ వ్యర్థాలు ఉత్పత్తి అవుతాయి."},{"en":"Status is often displayed through expensive brands, but real wealth is rarely visible on the street.","native":"స్థాయిని తరచుగా ఖరీదైన బ్రాండ్ల ద్వారా ప్రదర్శిస్తారు, కానీ నిజమైన సంపద వీధిలో అరుదుగా కనిపిస్తుంది."}]},"hi":{"word":"उपभोक्तावाद","question":"क्या ज़्यादा चीज़ें ख़रीदने से लोग खुश होते हैं, या उपभोक्तावाद झूठी ज़रूरतें पैदा करता है?","examples":[{"en":"Happiness from shopping fades quickly, although advertisements promise that the next purchase will last.","native":"ख़रीदारी से मिली खुशी जल्दी फीकी पड़ जाती है, हालाँकि विज्ञापन वादा करते हैं कि अगली ख़रीद टिकाऊ होगी।"},{"en":"If people repaired things instead of replacing them, far less waste would be produced every year.","native":"अगर लोग चीज़ें बदलने के बजाय उनकी मरम्मत करें, तो हर साल काफ़ी कम कचरा पैदा होगा।"},{"en":"Status is often displayed through expensive brands, but real wealth is rarely visible on the street.","native":"दर्जा अक्सर महँगे ब्रांडों से दिखाया जाता है, लेकिन असली दौलत सड़क पर शायद ही दिखती है।"}]},"es":{"word":"consumismo","question":"¿Comprar más cosas hace más feliz a la gente, o el consumismo crea necesidades falsas?","examples":[{"en":"Happiness from shopping fades quickly, although advertisements promise that the next purchase will last.","native":"La felicidad de las compras se desvanece rápido, aunque los anuncios prometen que la próxima compra durará."},{"en":"If people repaired things instead of replacing them, far less waste would be produced every year.","native":"Si la gente reparara las cosas en lugar de reemplazarlas, se producirían muchos menos residuos cada año."},{"en":"Status is often displayed through expensive brands, but real wealth is rarely visible on the street.","native":"El estatus a menudo se exhibe con marcas caras, pero la verdadera riqueza rara vez se ve en la calle."}]},"zh":{"word":"消费主义","question":"买更多东西会让人更快乐吗，还是消费主义制造了虚假的需求？","examples":[{"en":"Happiness from shopping fades quickly, although advertisements promise that the next purchase will last.","native":"购物带来的快乐很快消退，尽管广告承诺下一次购买会持久。"},{"en":"If people repaired things instead of replacing them, far less waste would be produced every year.","native":"如果人们修理东西而不是更换它们，每年产生的废物会少得多。"},{"en":"Status is often displayed through expensive brands, but real wealth is rarely visible on the street.","native":"地位往往通过昂贵的品牌来展示，但真正的财富在街上很少看得见。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'public transport', 'Should public transport be free for everyone? Who should pay for it?', '{"te":{"word":"ప్రజా రవాణా","question":"ప్రజా రవాణా అందరికీ ఉచితం కావాలా? దాని కోసం ఎవరు చెల్లించాలి?","examples":[{"en":"If buses and trains were completely free, city centres would be less crowded with private cars.","native":"బస్సులు మరియు రైళ్లు పూర్తిగా ఉచితమైతే, నగర కేంద్రాలు ప్రైవేట్ కార్లతో తక్కువ రద్దీగా ఉంటాయి."},{"en":"Public transport is used by everyone, although its cost is shared unequally between taxpayers and riders.","native":"ప్రజా రవాణాను అందరూ వాడతారు, అయితే దాని ఖర్చు పన్ను చెల్లించేవారికి మరియు ప్రయాణికులకు అసమానంగా పంచబడుతుంది."},{"en":"When tickets become too expensive, the poorest workers are forced into the longest journeys.","native":"టిక్కెట్లు చాలా ఖరీదైనప్పుడు, అతి పేద కార్మికులు అతి పొడవైన ప్రయాణాలకు బలవంతం చేయబడతారు."}]},"hi":{"word":"सार्वजनिक परिवहन","question":"क्या सार्वजनिक परिवहन सबके लिए मुफ़्त होना चाहिए? इसका ख़र्च किसे उठाना चाहिए?","examples":[{"en":"If buses and trains were completely free, city centres would be less crowded with private cars.","native":"अगर बसें और ट्रेनें पूरी तरह मुफ़्त हों, तो शहर के केंद्र निजी कारों से कम भीड़भाड़ वाले होंगे।"},{"en":"Public transport is used by everyone, although its cost is shared unequally between taxpayers and riders.","native":"सार्वजनिक परिवहन सभी इस्तेमाल करते हैं, हालाँकि इसकी लागत करदाताओं और यात्रियों के बीच असमान रूप से बँटती है।"},{"en":"When tickets become too expensive, the poorest workers are forced into the longest journeys.","native":"जब टिकट बहुत महँगे हो जाते हैं, तो सबसे ग़रीब मज़दूर सबसे लंबी यात्राओं के लिए मजबूर हो जाते हैं।"}]},"es":{"word":"transporte público","question":"¿Debería el transporte público ser gratuito para todos? ¿Quién debería pagarlo?","examples":[{"en":"If buses and trains were completely free, city centres would be less crowded with private cars.","native":"Si los autobuses y trenes fueran completamente gratuitos, los centros urbanos estarían menos llenos de coches privados."},{"en":"Public transport is used by everyone, although its cost is shared unequally between taxpayers and riders.","native":"El transporte público lo usa todo el mundo, aunque su coste se reparte de forma desigual entre contribuyentes y usuarios."},{"en":"When tickets become too expensive, the poorest workers are forced into the longest journeys.","native":"Cuando los billetes se vuelven demasiado caros, los trabajadores más pobres se ven obligados a hacer los trayectos más largos."}]},"zh":{"word":"公共交通","question":"公共交通应该对所有人免费吗？应该由谁来买单？","examples":[{"en":"If buses and trains were completely free, city centres would be less crowded with private cars.","native":"如果公交车和火车完全免费，市中心就不会那么拥堵私家车。"},{"en":"Public transport is used by everyone, although its cost is shared unequally between taxpayers and riders.","native":"人人都在使用公共交通，尽管其成本在纳税人和乘客之间分摊得并不均等。"},{"en":"When tickets become too expensive, the poorest workers are forced into the longest journeys.","native":"当票价变得太贵时，最贫困的工人被迫承受最长的通勤路程。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'teamwork', 'Is teamwork always better than working alone? What makes a team succeed or fail?', '{"te":{"word":"జట్టు కృషి","question":"జట్టుగా పనిచేయడం ఎల్లప్పుడూ ఒంటరిగా పనిచేయడం కంటే మంచిదేనా? జట్టు విజయవంతం కావడానికి లేదా విఫలం కావడానికి కారణం ఏమిటి?","examples":[{"en":"Teams achieve more when members trust each other, although disagreements are sometimes useful and necessary.","native":"సభ్యులు ఒకరినొకరు నమ్ముకున్నప్పుడు జట్టులు ఎక్కువ సాధిస్తాయి, అయితే అభిప్రాయ భేదాలు కొన్నిసార్లు ఉపయోగకరం మరియు అవసరం."},{"en":"If one person dominates every discussion, quieter colleagues are prevented from contributing their best ideas.","native":"ఒక వ్యక్తి ప్రతి చర్చను ఆధిపత్యం చేస్తే, నిశ్శబ్ద సహోద్యోగులు తమ ఉత్తమ ఆలోచనలను అందించకుండా నిరోధించబడతారు."},{"en":"Working alone can be faster, but complex problems are usually solved better by groups.","native":"ఒంటరిగా పనిచేయడం వేగంగా ఉండవచ్చు, కానీ సంక్లిష్ట సమస్యలను సాధారణంగా బృందాలు బాగా పరిష్కరిస్తాయి."}]},"hi":{"word":"टीमवर्क","question":"क्या टीमवर्क हमेशा अकेले काम करने से बेहतर है? किसी टीम को सफल या असफल क्या बनाता है?","examples":[{"en":"Teams achieve more when members trust each other, although disagreements are sometimes useful and necessary.","native":"जब सदस्य एक-दूसरे पर भरोसा करते हैं तो टीमें ज़्यादा हासिल करती हैं, हालाँकि मतभेद कभी-कभी उपयोगी और ज़रूरी होते हैं।"},{"en":"If one person dominates every discussion, quieter colleagues are prevented from contributing their best ideas.","native":"अगर एक व्यक्ति हर चर्चा पर हावी हो जाए, तो शांत सहकर्मियों को अपने बेहतरीन विचार देने से रोका जाता है।"},{"en":"Working alone can be faster, but complex problems are usually solved better by groups.","native":"अकेले काम करना तेज़ हो सकता है, लेकिन जटिल समस्याएँ आमतौर पर समूहों द्वारा बेहतर हल की जाती हैं।"}]},"es":{"word":"trabajo en equipo","question":"¿Es el trabajo en equipo siempre mejor que trabajar solo? ¿Qué hace que un equipo tenga éxito o fracase?","examples":[{"en":"Teams achieve more when members trust each other, although disagreements are sometimes useful and necessary.","native":"Los equipos logran más cuando los miembros confían entre sí, aunque los desacuerdos a veces son útiles y necesarios."},{"en":"If one person dominates every discussion, quieter colleagues are prevented from contributing their best ideas.","native":"Si una persona domina cada discusión, se impide que los colegas más callados aporten sus mejores ideas."},{"en":"Working alone can be faster, but complex problems are usually solved better by groups.","native":"Trabajar solo puede ser más rápido, pero los problemas complejos suelen resolverse mejor en grupo."}]},"zh":{"word":"团队合作","question":"团队合作总是比独自工作更好吗？是什么让团队成功或失败？","examples":[{"en":"Teams achieve more when members trust each other, although disagreements are sometimes useful and necessary.","native":"当成员彼此信任时，团队能取得更多成就，尽管分歧有时也是有用且必要的。"},{"en":"If one person dominates every discussion, quieter colleagues are prevented from contributing their best ideas.","native":"如果一个人主导每次讨论，安静的同事就无法贡献他们最好的想法。"},{"en":"Working alone can be faster, but complex problems are usually solved better by groups.","native":"独自工作可能更快，但复杂的问题通常由团队解决得更好。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'communication', 'Why do misunderstandings happen so often, and how can communication be improved?', '{"te":{"word":"కమ్యూనికేషన్","question":"అపార్థాలు తరచుగా ఎందుకు జరుగుతాయి, మరియు కమ్యూనికేషన్‌ను ఎలా మెరుగుపరచవచ్చు?","examples":[{"en":"Misunderstandings often happen because people listen only to reply instead of listening carefully to understand.","native":"ప్రజలు అర్థం చేసుకోవడానికి జాగ్రత్తగా వినడం బదులు సమాధానం చెప్పడానికి మాత్రమే వింటారు కాబట్టి అపార్థాలు తరచుగా జరుగుతాయి."},{"en":"If tone and body language were taught at school, many conflicts could be avoided quite easily.","native":"పాఠశాలలో ధ్వని మరియు శరీర భాషను బోధిస్తే, అనేక వివాదాలను చాలా సులభంగా నివారించవచ్చు."},{"en":"Written messages are read without emotion, although the writer may have meant something completely different.","native":"వ్రాత సందేశాలు భావోద్వేగం లేకుండా చదవబడతాయి, అయితే రచయిత పూర్తిగా భిన్నమైనది ఉద్దేశించి ఉండవచ్చు."}]},"hi":{"word":"संचार","question":"गलतफहमियाँ इतनी बार क्यों होती हैं, और संचार को कैसे बेहतर बनाया जा सकता है?","examples":[{"en":"Misunderstandings often happen because people listen only to reply instead of listening carefully to understand.","native":"गलतफहमियाँ अक्सर इसलिए होती हैं क्योंकि लोग समझने के लिए ध्यान से सुनने के बजाय सिर्फ़ जवाब देने के लिए सुनते हैं।"},{"en":"If tone and body language were taught at school, many conflicts could be avoided quite easily.","native":"अगर स्कूल में लहज़ा और बॉडी लैंग्वेज सिखाई जाए, तो कई टकरावों को काफ़ी आसानी से टाला जा सकता है।"},{"en":"Written messages are read without emotion, although the writer may have meant something completely different.","native":"लिखित संदेश बिना भावना के पढ़े जाते हैं, हालाँकि लिखने वाले का इरादा कुछ बिल्कुल अलग हो सकता है।"}]},"es":{"word":"comunicación","question":"¿Por qué ocurren los malentendidos tan a menudo, y cómo se puede mejorar la comunicación?","examples":[{"en":"Misunderstandings often happen because people listen only to reply instead of listening carefully to understand.","native":"Los malentendidos ocurren a menudo porque la gente escucha solo para responder en lugar de escuchar atentamente para comprender."},{"en":"If tone and body language were taught at school, many conflicts could be avoided quite easily.","native":"Si se enseñaran el tono y el lenguaje corporal en la escuela, muchos conflictos podrían evitarse con bastante facilidad."},{"en":"Written messages are read without emotion, although the writer may have meant something completely different.","native":"Los mensajes escritos se leen sin emoción, aunque quien escribe puede haber querido decir algo completamente distinto."}]},"zh":{"word":"沟通","question":"为什么误解如此频繁地发生？如何改善沟通？","examples":[{"en":"Misunderstandings often happen because people listen only to reply instead of listening carefully to understand.","native":"误解经常发生，因为人们倾听只是为了回应，而不是认真倾听去理解。"},{"en":"If tone and body language were taught at school, many conflicts could be avoided quite easily.","native":"如果学校教授语气和肢体语言，许多冲突可以很容易地避免。"},{"en":"Written messages are read without emotion, although the writer may have meant something completely different.","native":"书面信息被阅读时不带情感，尽管写的人可能完全不是那个意思。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'risk', 'Is taking risks necessary for a fulfilling life, or is safety more important?', '{"te":{"word":"రిస్క్","question":"సంతృప్తికరమైన జీవితానికి రిస్క్ తీసుకోవడం అవసరమా, లేక భద్రతే ముఖ్యమా?","examples":[{"en":"People who never take risks rarely fail, but they also rarely discover what they could become.","native":"ఎప్పుడూ రిస్క్ తీసుకోని వ్యక్తులు అరుదుగా విఫలమవుతారు, కానీ వారు ఏమి కాగలరో కూడా అరుదుగా కనుగొంటారు."},{"en":"If everyone chose the safest option, few new businesses or inventions would ever be created.","native":"అందరూ అత్యంత సురక్షితమైన ఎంపికను ఎంచుకుంటే, కొద్దిగానే కొత్త వ్యాపారాలు లేదా ఆవిష్కరణలు సృష్టించబడతాయి."},{"en":"Calculated risks are worth taking, although reckless decisions can damage lives that took years to build.","native":"లెక్కించిన రిస్క్‌లు తీసుకోవడం విలువైనదే, అయితే నిర్లక్ష్య నిర్ణయాలు నిర్మించడానికి సంవత్సరాలు పట్టిన జీవితాలను దెబ్బతీయగలవు."}]},"hi":{"word":"जोखिम","question":"क्या संतोषजनक जीवन के लिए जोखिम उठाना ज़रूरी है, या सुरक्षा ज़्यादा महत्वपूर्ण है?","examples":[{"en":"People who never take risks rarely fail, but they also rarely discover what they could become.","native":"जो लोग कभी जोखिम नहीं उठाते वे शायद ही असफल होते हैं, लेकिन वे यह भी शायद ही खोज पाते हैं कि वे क्या बन सकते थे।"},{"en":"If everyone chose the safest option, few new businesses or inventions would ever be created.","native":"अगर सभी लोग सबसे सुरक्षित विकल्प चुनें, तो कुछ ही नए कारोबार या आविष्कार कभी बनाए जाएँगे।"},{"en":"Calculated risks are worth taking, although reckless decisions can damage lives that took years to build.","native":"परिकलित जोखिम उठाना सार्थक है, हालाँकि लापरवाह फ़ैसले उन जीवनों को नुकसान पहुँचा सकते हैं जिन्हें बनने में साल लगे।"}]},"es":{"word":"riesgo","question":"¿Es necesario asumir riesgos para una vida plena, o es más importante la seguridad?","examples":[{"en":"People who never take risks rarely fail, but they also rarely discover what they could become.","native":"Las personas que nunca asumen riesgos rara vez fracasan, pero también rara vez descubren en qué podrían convertirse."},{"en":"If everyone chose the safest option, few new businesses or inventions would ever be created.","native":"Si todos eligieran la opción más segura, pocas empresas o inventos nuevos llegarían a crearse."},{"en":"Calculated risks are worth taking, although reckless decisions can damage lives that took years to build.","native":"Vale la pena asumir riesgos calculados, aunque las decisiones imprudentes pueden dañar vidas que tardaron años en construirse."}]},"zh":{"word":"风险","question":"要过充实的人生，冒险是必要的吗，还是安全更重要？","examples":[{"en":"People who never take risks rarely fail, but they also rarely discover what they could become.","native":"从不冒险的人很少失败，但他们也很少发现自己能成为什么样的人。"},{"en":"If everyone chose the safest option, few new businesses or inventions would ever be created.","native":"如果每个人都选择最安全的选项，就很少会有新企业或新发明被创造出来。"},{"en":"Calculated risks are worth taking, although reckless decisions can damage lives that took years to build.","native":"经过权衡的风险值得承担，尽管鲁莽的决定可能毁掉多年建立的生活。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'failure', 'Why are people so afraid of failure? Can failure be a better teacher than success?', '{"te":{"word":"వైఫల్యం","question":"ప్రజలు వైఫల్యానికి ఎందుకు అంతగా భయపడతారు? విజయం కంటే వైఫల్యం మెరుగైన ఉపాధ్యాయుడు కాగలదా?","examples":[{"en":"Although failure hurts deeply at first, it often teaches lessons that easy success never could.","native":"వైఫల్యం మొదట్లో లోతుగా బాధించినప్పటికీ, సులభమైన విజయం ఎప్పుడూ నేర్పలేని పాఠాలను అది తరచుగా నేర్పుతుంది."},{"en":"If children were allowed to fail safely, they would grow into far more resilient adults.","native":"పిల్లలు సురక్షితంగా విఫలం కావడానికి అనుమతిస్తే, వారు చాలా స్థైర్యవంతమైన పెద్దలుగా ఎదుగుతారు."},{"en":"Mistakes are punished in many workplaces, so employees hide problems until they become disasters.","native":"అనేక కార్యాలయాల్లో తప్పులకు శిక్ష విధిస్తారు, కాబట్టి ఉద్యోగులు సమస్యలు విపత్తులు అయ్యే వరకు దాచిపెడతారు."}]},"hi":{"word":"असफलता","question":"लोग असफलता से इतना डरते क्यों हैं? क्या असफलता सफलता से बेहतर शिक्षक हो सकती है?","examples":[{"en":"Although failure hurts deeply at first, it often teaches lessons that easy success never could.","native":"हालाँकि असफलता शुरू में गहरा दुख देती है, यह अक्सर वे सबक सिखाती है जो आसान सफलता कभी नहीं सिखा सकती।"},{"en":"If children were allowed to fail safely, they would grow into far more resilient adults.","native":"अगर बच्चों को सुरक्षित रूप से असफल होने दिया जाए, तो वे कहीं ज़्यादा लचीले वयस्क बनेंगे।"},{"en":"Mistakes are punished in many workplaces, so employees hide problems until they become disasters.","native":"कई कार्यस्थलों पर गलतियों की सज़ा मिलती है, इसलिए कर्मचारी समस्याओं को तब तक छिपाते हैं जब तक वे आपदा न बन जाएँ।"}]},"es":{"word":"fracaso","question":"¿Por qué la gente teme tanto al fracaso? ¿Puede el fracaso ser un mejor maestro que el éxito?","examples":[{"en":"Although failure hurts deeply at first, it often teaches lessons that easy success never could.","native":"Aunque el fracaso duele mucho al principio, a menudo enseña lecciones que el éxito fácil nunca podría enseñar."},{"en":"If children were allowed to fail safely, they would grow into far more resilient adults.","native":"Si se permitiera a los niños fracasar con seguridad, se convertirían en adultos mucho más resilientes."},{"en":"Mistakes are punished in many workplaces, so employees hide problems until they become disasters.","native":"En muchos lugares de trabajo se castigan los errores, así que los empleados ocultan los problemas hasta que se convierten en desastres."}]},"zh":{"word":"失败","question":"为什么人们如此害怕失败？失败能比成功成为更好的老师吗？","examples":[{"en":"Although failure hurts deeply at first, it often teaches lessons that easy success never could.","native":"尽管失败起初让人痛苦，但它往往教给人们轻易的成功永远无法教会的道理。"},{"en":"If children were allowed to fail safely, they would grow into far more resilient adults.","native":"如果允许孩子们安全地失败，他们会成长为更有韧性的成年人。"},{"en":"Mistakes are punished in many workplaces, so employees hide problems until they become disasters.","native":"许多工作场所惩罚错误，所以员工把问题藏起来，直到它们变成灾难。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'discipline', 'Is discipline more important than motivation for achieving long-term goals?', '{"te":{"word":"క్రమశిక్షణ","question":"దీర్ఘకాలిక లక్ష్యాలను చేరుకోవడానికి ప్రేరణ కంటే క్రమశిక్షణ ముఖ్యమైనదేనా?","examples":[{"en":"Motivation comes and goes with mood, but disciplined habits keep working even on difficult days.","native":"ప్రేరణ మూడ్‌తో వస్తూ పోతూ ఉంటుంది, కానీ క్రమశిక్షణ అలవాట్లు కష్టమైన రోజుల్లో కూడా పనిచేస్తూ ఉంటాయి."},{"en":"If discipline were valued more than talent, ordinary people would achieve extraordinary results much more often.","native":"ప్రతిభ కంటే క్రమశిక్షణకు ఎక్కువ విలువ ఇస్తే, సాధారణ ప్రజలు అసాధారణ ఫలితాలను మరింత తరచుగా సాధిస్తారు."},{"en":"Strict routines can feel boring, although they free the mind from making endless small decisions.","native":"కఠినమైన దినచర్యలు విసుగుగా అనిపించవచ్చు, అయితే అవి అనంతమైన చిన్న నిర్ణయాలు తీసుకోవడం నుండి మనస్సును విముక్తం చేస్తాయి."}]},"hi":{"word":"अनुशासन","question":"दीर्घकालिक लक्ष्यों को पाने के लिए क्या अनुशासन प्रेरणा से ज़्यादा महत्वपूर्ण है?","examples":[{"en":"Motivation comes and goes with mood, but disciplined habits keep working even on difficult days.","native":"प्रेरणा मूड के साथ आती-जाती रहती है, लेकिन अनुशासित आदतें मुश्किल दिनों में भी काम करती रहती हैं।"},{"en":"If discipline were valued more than talent, ordinary people would achieve extraordinary results much more often.","native":"अगर प्रतिभा से ज़्यादा अनुशासन को महत्व दिया जाए, तो साधारण लोग कहीं ज़्यादा बार असाधारण परिणाम हासिल करेंगे।"},{"en":"Strict routines can feel boring, although they free the mind from making endless small decisions.","native":"सख़्त दिनचर्या उबाऊ लग सकती है, हालाँकि वे अनगिनत छोटे फ़ैसलों से मन को मुक्त करती हैं।"}]},"es":{"word":"disciplina","question":"¿Es la disciplina más importante que la motivación para lograr metas a largo plazo?","examples":[{"en":"Motivation comes and goes with mood, but disciplined habits keep working even on difficult days.","native":"La motivación va y viene con el ánimo, pero los hábitos disciplinados siguen funcionando incluso en los días difíciles."},{"en":"If discipline were valued more than talent, ordinary people would achieve extraordinary results much more often.","native":"Si se valorara más la disciplina que el talento, la gente corriente lograría resultados extraordinarios con mucha más frecuencia."},{"en":"Strict routines can feel boring, although they free the mind from making endless small decisions.","native":"Las rutinas estrictas pueden parecer aburridas, aunque liberan la mente de tomar infinitas decisiones pequeñas."}]},"zh":{"word":"自律","question":"要实现长期目标，自律比动力更重要吗？","examples":[{"en":"Motivation comes and goes with mood, but disciplined habits keep working even on difficult days.","native":"动力随情绪时有时无，但自律的习惯即使在艰难的日子里也能持续发挥作用。"},{"en":"If discipline were valued more than talent, ordinary people would achieve extraordinary results much more often.","native":"如果自律比天赋更受重视，普通人会更频繁地取得非凡的成就。"},{"en":"Strict routines can feel boring, although they free the mind from making endless small decisions.","native":"严格的作息可能让人觉得乏味，尽管它们能让大脑免于做无数小决定。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'happiness', 'Can money buy happiness, or does happiness depend on things that cannot be bought?', '{"te":{"word":"సంతోషం","question":"డబ్బు సంతోషాన్ని కొనగలదా, లేక సంతోషం కొనలేని విషయాలపై ఆధారపడుతుందా?","examples":[{"en":"Money removes many worries, although happiness seems to depend more on relationships than income.","native":"డబ్బు అనేక చింతలను తొలగిస్తుంది, అయితే సంతోషం ఆదాయం కంటే సంబంధాలపై ఎక్కువగా ఆధారపడుతుంది."},{"en":"If basic needs are already covered, extra wealth adds surprisingly little to most people''s everyday satisfaction.","native":"ప్రాథమిక అవసరాలు ఇప్పటికే తీరితే, అదనపు సంపద చాలామంది ప్రజల రోజువారీ సంతృప్తికి ఆశ్చర్యకరంగా తక్కువ జోడిస్తుంది."},{"en":"Happy nations are usually those where time, fairness and community are valued above consumption.","native":"సంతోషకరమైన దేశాలు సాధారణంగా సమయం, న్యాయం మరియు సమాజాన్ని వినియోగం కంటే ఎక్కువగా విలువైస్తాయి."}]},"hi":{"word":"खुशी","question":"क्या पैसा खुशी ख़रीद सकता है, या खुशी उन चीज़ों पर निर्भर करती है जिन्हें ख़रीदा नहीं जा सकता?","examples":[{"en":"Money removes many worries, although happiness seems to depend more on relationships than income.","native":"पैसा कई चिंताएँ दूर करता है, हालाँकि खुशी आय से ज़्यादा रिश्तों पर निर्भर करती हुई लगती है।"},{"en":"If basic needs are already covered, extra wealth adds surprisingly little to most people''s everyday satisfaction.","native":"अगर बुनियादी ज़रूरतें पहले से पूरी हैं, तो अतिरिक्त दौलत ज़्यादातर लोगों की रोज़मर्रा की संतुष्टि में हैरान करने वाला कम इज़ाफ़ा करती है।"},{"en":"Happy nations are usually those where time, fairness and community are valued above consumption.","native":"खुशहाल देश आमतौर पर वे होते हैं जहाँ समय, निष्पक्षता और समुदाय को उपभोग से ऊपर रखा जाता है।"}]},"es":{"word":"felicidad","question":"¿Puede el dinero comprar la felicidad, o la felicidad depende de cosas que no se pueden comprar?","examples":[{"en":"Money removes many worries, although happiness seems to depend more on relationships than income.","native":"El dinero elimina muchas preocupaciones, aunque la felicidad parece depender más de las relaciones que de los ingresos."},{"en":"If basic needs are already covered, extra wealth adds surprisingly little to most people''s everyday satisfaction.","native":"Si las necesidades básicas ya están cubiertas, la riqueza extra añade sorprendentemente poco a la satisfacción diaria de la mayoría."},{"en":"Happy nations are usually those where time, fairness and community are valued above consumption.","native":"Las naciones felices suelen ser aquellas donde el tiempo, la justicia y la comunidad se valoran por encima del consumo."}]},"zh":{"word":"幸福","question":"金钱能买到幸福吗，还是幸福取决于买不到的东西？","examples":[{"en":"Money removes many worries, although happiness seems to depend more on relationships than income.","native":"金钱能消除许多烦恼，尽管幸福似乎更多取决于人际关系而不是收入。"},{"en":"If basic needs are already covered, extra wealth adds surprisingly little to most people''s everyday satisfaction.","native":"如果基本需求已经得到满足，额外的财富对大多数人的日常满足感几乎没有增加。"},{"en":"Happy nations are usually those where time, fairness and community are valued above consumption.","native":"幸福的国家通常是那些把时间、公平和社区看得比消费更重要的国家。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'patience', 'Is patience still valuable in a world where everything happens instantly?', '{"te":{"word":"సహనం","question":"ప్రతిదీ తక్షణం జరిగే ప్రపంచంలో సహనం ఇంకా విలువైనదేనా?","examples":[{"en":"Patience is becoming rare because almost everything can now be delivered within a day.","native":"ఇప్పుడు దాదాపు ప్రతిదీ ఒక రోజులోపు డెలివరీ చేయబడుతుంది కాబట్టి సహనం అరుదవుతోంది."},{"en":"If people learned to wait calmly, fewer angry arguments would happen in shops and offices.","native":"ప్రజలు ప్రశాంతంగా వేచి ఉండటం నేర్చుకుంటే, దుకాణాల్లోను మరియు కార్యాలయాల్లోను తక్కువ కోప వాదనలు జరుగుతాయి."},{"en":"Although speed is convenient, the best results in life are often produced slowly and carefully.","native":"వేగం అనుకూలంగా ఉన్నప్పటికీ, జీవితంలోని ఉత్తమ ఫలితాలు తరచుగా నెమ్మదిగా మరియు జాగ్రత్తగా ఉత్పత్తి అవుతాయి."}]},"hi":{"word":"धैर्य","question":"क्या उस दुनिया में जहाँ हर चीज़ तुरंत होती है, धैर्य अब भी मूल्यवान है?","examples":[{"en":"Patience is becoming rare because almost everything can now be delivered within a day.","native":"धैर्य दुर्लभ होता जा रहा है क्योंकि अब लगभग हर चीज़ एक दिन के भीतर पहुँचाई जा सकती है।"},{"en":"If people learned to wait calmly, fewer angry arguments would happen in shops and offices.","native":"अगर लोग शांति से इंतज़ार करना सीख लें, तो दुकानों और दफ़्तरों में कम गुस्सैल बहसें होंगी।"},{"en":"Although speed is convenient, the best results in life are often produced slowly and carefully.","native":"हालाँकि रफ़्तार सुविधाजनक है, जीवन के बेहतरीन परिणाम अक्सर धीरे-धीरे और सावधानी से बनाए जाते हैं।"}]},"es":{"word":"paciencia","question":"¿Sigue siendo valiosa la paciencia en un mundo donde todo ocurre al instante?","examples":[{"en":"Patience is becoming rare because almost everything can now be delivered within a day.","native":"La paciencia se está volviendo rara porque casi todo puede entregarse ahora en un día."},{"en":"If people learned to wait calmly, fewer angry arguments would happen in shops and offices.","native":"Si la gente aprendiera a esperar con calma, habría menos discusiones airadas en tiendas y oficinas."},{"en":"Although speed is convenient, the best results in life are often produced slowly and carefully.","native":"Aunque la rapidez es cómoda, los mejores resultados de la vida a menudo se producen lenta y cuidadosamente."}]},"zh":{"word":"耐心","question":"在一个一切都即时发生的世界里，耐心仍然宝贵吗？","examples":[{"en":"Patience is becoming rare because almost everything can now be delivered within a day.","native":"耐心正变得稀缺，因为几乎所有东西现在都能在一天之内送达。"},{"en":"If people learned to wait calmly, fewer angry arguments would happen in shops and offices.","native":"如果人们学会平静地等待，商店和办公室里愤怒的争吵就会减少。"},{"en":"Although speed is convenient, the best results in life are often produced slowly and carefully.","native":"尽管速度很方便，但人生中最好的成果往往是缓慢而细致地产生的。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'honesty', 'Is honesty always the best policy, or are some situations better handled with small lies?', '{"te":{"word":"నిజాయితీ","question":"నిజాయితీ ఎల్లప్పుడూ ఉత్తమ విధానమేనా, లేక కొన్ని పరిస్థితులను చిన్న అబద్ధాలతో బాగా నిర్వహించవచ్చా?","examples":[{"en":"Honesty builds trust slowly over years, although a single lie can destroy it in seconds.","native":"నిజాయితీ సంవత్సరాలుగా నెమ్మదిగా నమ్మకాన్ని నిర్మిస్తుంది, అయితే ఒక్క అబద్ధం దాన్ని క్షణాల్లో నాశనం చేయగలదు."},{"en":"If everyone were completely honest at work, some feelings would be hurt but decisions would improve.","native":"కార్యాలయంలో అందరూ పూర్తిగా నిజాయితీగా ఉంటే, కొన్ని భావనలు దెబ్బతింటాయి కానీ నిర్ణయాలు మెరుగవుతాయి."},{"en":"Polite lies are sometimes told to protect others, yet they can still damage relationships later.","native":"ఇతరులను రక్షించడానికి మర్యాదపూర్వక అబద్ధాలు కొన్నిసార్లు చెబుతారు, అయితే అవి తర్వాత సంబంధాలను దెబ్బతీయగలవు."}]},"hi":{"word":"ईमानदारी","question":"क्या ईमानदारी हमेशा सबसे अच्छी नीति है, या कुछ स्थितियाँ छोटे झूठ से बेहतर संभलती हैं?","examples":[{"en":"Honesty builds trust slowly over years, although a single lie can destroy it in seconds.","native":"ईमानदारी सालों में धीरे-धीरे भरोसा बनाती है, हालाँकि एक झूठ उसे कुछ पलों में नष्ट कर सकता है।"},{"en":"If everyone were completely honest at work, some feelings would be hurt but decisions would improve.","native":"अगर काम पर सभी पूरी तरह ईमानदार हों, तो कुछ भावनाओं को ठेस पहुँचेगी लेकिन फ़ैसले बेहतर होंगे।"},{"en":"Polite lies are sometimes told to protect others, yet they can still damage relationships later.","native":"दूसरों की रक्षा के लिए कभी-कभी विनम्र झूठ बोले जाते हैं, फिर भी वे बाद में रिश्तों को नुकसान पहुँचा सकते हैं।"}]},"es":{"word":"honestidad","question":"¿Es la honestidad siempre la mejor política, o algunas situaciones se manejan mejor con pequeñas mentiras?","examples":[{"en":"Honesty builds trust slowly over years, although a single lie can destroy it in seconds.","native":"La honestidad construye confianza lentamente durante años, aunque una sola mentira puede destruirla en segundos."},{"en":"If everyone were completely honest at work, some feelings would be hurt but decisions would improve.","native":"Si todos fueran completamente honestos en el trabajo, algunos sentimientos saldrían heridos pero las decisiones mejorarían."},{"en":"Polite lies are sometimes told to protect others, yet they can still damage relationships later.","native":"A veces se dicen mentiras corteses para proteger a otros, pero aun así pueden dañar las relaciones más tarde."}]},"zh":{"word":"诚实","question":"诚实永远是上策吗，还是有些场合用善意的谎言处理更好？","examples":[{"en":"Honesty builds trust slowly over years, although a single lie can destroy it in seconds.","native":"诚实能在多年间慢慢建立信任，尽管一个谎言就能在几秒钟内毁掉它。"},{"en":"If everyone were completely honest at work, some feelings would be hurt but decisions would improve.","native":"如果每个人在工作中都完全诚实，一些感情会受到伤害，但决策会得到改善。"},{"en":"Polite lies are sometimes told to protect others, yet they can still damage relationships later.","native":"人们有时为了保护他人而说礼貌的谎言，但它们日后仍可能损害关系。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'loyalty', 'Is loyalty to a company or group still important, or should people always put themselves first?', '{"te":{"word":"విశ్వాసం","question":"కంపెనీ లేదా సమూహం పట్ల విశ్వాసం ఇంకా ముఖ్యమేనా, లేక ప్రజలు ఎల్లప్పుడూ తమను ముందు పెట్టుకోవాలా?","examples":[{"en":"Loyal employees are valued by good companies, although loyalty is rarely rewarded during hard times.","native":"మంచి కంపెనీలు విశ్వాసమైన ఉద్యోగులను విలువైస్తాయి, అయితే కష్టమైన సమయాల్లో విశ్వాసానికి అరుదుగా బహూమతి లభిస్తుంది."},{"en":"If workers stayed loyal only to their own interests, teams would collapse whenever difficulties appeared.","native":"కార్మికులు తమ స్వార్థానికి మాత్రమే విశ్వాసంగా ఉంటే, ఇబ్బందులు వచ్చినప్పుడల్లా జట్టులు కుప్పకూలుతాయి."},{"en":"Blind loyalty can be dangerous, but abandoning friends at the first problem is worse.","native":"గుడ్డి విశ్వాసం ప్రమాదకరం కావచ్చు, కానీ మొదటి సమస్య వచ్చినప్పుడే స్నేహితులను వదిలిపెట్టడం దాని కంటే చెత్తది."}]},"hi":{"word":"वफ़ादारी","question":"क्या किसी कंपनी या समूह के प्रति वफ़ादारी अब भी महत्वपूर्ण है, या लोगों को हमेशा खुद को पहले रखना चाहिए?","examples":[{"en":"Loyal employees are valued by good companies, although loyalty is rarely rewarded during hard times.","native":"अच्छी कंपनियाँ वफ़ादार कर्मचारियों को महत्व देती हैं, हालाँकि मुश्किल समय में वफ़ादारी शायद ही सराही जाती है।"},{"en":"If workers stayed loyal only to their own interests, teams would collapse whenever difficulties appeared.","native":"अगर कर्मचारी सिर्फ़ अपने हितों के प्रति वफ़ादार रहें, तो मुश्किलें आते ही टीमें ढह जाएँगी।"},{"en":"Blind loyalty can be dangerous, but abandoning friends at the first problem is worse.","native":"अंधी वफ़ादारी ख़तरनाक हो सकती है, लेकिन पहली परेशानी पर दोस्तों को छोड़ देना उससे बदतर है।"}]},"es":{"word":"lealtad","question":"¿Sigue siendo importante la lealtad a una empresa o grupo, o debería la gente anteponerse siempre a sí misma?","examples":[{"en":"Loyal employees are valued by good companies, although loyalty is rarely rewarded during hard times.","native":"Las buenas empresas valoran a los empleados leales, aunque la lealtad rara vez se recompensa en tiempos difíciles."},{"en":"If workers stayed loyal only to their own interests, teams would collapse whenever difficulties appeared.","native":"Si los trabajadores fueran leales solo a sus propios intereses, los equipos colapsarían cada vez que aparecieran dificultades."},{"en":"Blind loyalty can be dangerous, but abandoning friends at the first problem is worse.","native":"La lealtad ciega puede ser peligrosa, pero abandonar a los amigos al primer problema es peor."}]},"zh":{"word":"忠诚","question":"对公司或团体的忠诚仍然重要吗，还是人们应该始终把自己放在第一位？","examples":[{"en":"Loyal employees are valued by good companies, although loyalty is rarely rewarded during hard times.","native":"好公司重视忠诚的员工，尽管在困难时期忠诚很少得到回报。"},{"en":"If workers stayed loyal only to their own interests, teams would collapse whenever difficulties appeared.","native":"如果员工只忠于自己的利益，一旦遇到困难，团队就会瓦解。"},{"en":"Blind loyalty can be dangerous, but abandoning friends at the first problem is worse.","native":"盲目的忠诚可能很危险，但一遇问题就抛弃朋友则更糟。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'respect', 'Should respect be earned, or should it be given automatically to everyone?', '{"te":{"word":"గౌరవం","question":"గౌరవం సంపాదించుకోవాలా, లేక అందరికీ స్వయంచాలకంగా ఇవ్వాలా?","examples":[{"en":"Respect is often demanded by authority, although genuine respect can only be earned through behaviour.","native":"అధికారం గౌరవాన్ని తరచుగా డిమాండ్ చేస్తుంది, అయితే నిజమైన గౌరవం ప్రవర్తన ద్వారా మాత్రమే సంపాదించవచ్చు."},{"en":"If basic respect were shown to every worker, many workplaces would become healthier overnight.","native":"ప్రతి కార్మికుడికి ప్రాథమిక గౌరవం చూపబడితే, అనేక కార్యాలయాలు ఒక్కరాత్రిలోనే ఆరోగ్యకరంగా మారతాయి."},{"en":"Younger generations are expected to respect age, but respect must flow in both directions.","native":"యువతరం వయసును గౌరవించాలని భావిస్తారు, కానీ గౌరవం రెండు దిశల్లోనూ ప్రవహించాలి."}]},"hi":{"word":"सम्मान","question":"क्या सम्मान कमाया जाना चाहिए, या यह सबको स्वतः मिलना चाहिए?","examples":[{"en":"Respect is often demanded by authority, although genuine respect can only be earned through behaviour.","native":"अधिकार से सम्मान अक्सर माँगा जाता है, हालाँकि सच्चा सम्मान केवल व्यवहार से कमाया जा सकता है।"},{"en":"If basic respect were shown to every worker, many workplaces would become healthier overnight.","native":"अगर हर कर्मचारी को बुनियादी सम्मान दिया जाए, तो कई कार्यस्थल रातों-रात बेहतर हो जाएँगे।"},{"en":"Younger generations are expected to respect age, but respect must flow in both directions.","native":"युवा पीढ़ी से उम्र का सम्मान करने की उम्मीद की जाती है, लेकिन सम्मान दोनों दिशाओं में बहना चाहिए।"}]},"es":{"word":"respeto","question":"¿Debe ganarse el respeto, o debería darse automáticamente a todo el mundo?","examples":[{"en":"Respect is often demanded by authority, although genuine respect can only be earned through behaviour.","native":"A menudo la autoridad exige respeto, aunque el respeto genuino solo puede ganarse con el comportamiento."},{"en":"If basic respect were shown to every worker, many workplaces would become healthier overnight.","native":"Si se mostrara un respeto básico a cada trabajador, muchos lugares de trabajo mejorarían de la noche a la mañana."},{"en":"Younger generations are expected to respect age, but respect must flow in both directions.","native":"Se espera que las generaciones jóvenes respeten la edad, pero el respeto debe fluir en ambas direcciones."}]},"zh":{"word":"尊重","question":"尊重应该靠赢得，还是应该自动给予每一个人？","examples":[{"en":"Respect is often demanded by authority, although genuine respect can only be earned through behaviour.","native":"权威常常要求被尊重，尽管真正的尊重只能通过行为赢得。"},{"en":"If basic respect were shown to every worker, many workplaces would become healthier overnight.","native":"如果每位员工都能得到基本的尊重，许多工作场所会在一夜之间变得更健康。"},{"en":"Younger generations are expected to respect age, but respect must flow in both directions.","native":"人们期望年轻一代尊敬长者，但尊重必须双向流动。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'cooperation', 'Why do countries and companies find cooperation difficult, even when everyone would benefit?', '{"te":{"word":"సహకారం","question":"అందరికీ ప్రయోజనం చేకూరినప్పటికీ దేశాలు మరియు కంపెనీలు సహకారాన్ని ఎందుకు కష్టంగా భావిస్తాయి?","examples":[{"en":"Cooperation fails when short-term advantage is chosen over benefits that everyone would share later.","native":"తర్వాత అందరూ పంచుకునే ప్రయోజనాల కంటే స్వల్పకాలిక లాభాన్ని ఎంచుకున్నప్పుడు సహకారం విఫలమవుతుంది."},{"en":"If global problems were faced together, solutions would be found faster and cost much less.","native":"ప్రపంచ సమస్యలను కలిసి ఎదుర్కుంటే, పరిష్కారాలు వేగంగా దొరుకుతాయి మరియు చాలా తక్కువ ఖర్చవుతాయి."},{"en":"Trust is built slowly between partners, although a single broken promise can undo years of work.","native":"భాగస్వాముల మధ్య నమ్మకం నెమ్మదిగా నిర్మించబడుతుంది, అయితే ఒక్క విరమించుకున్న వాగ్దానం సంవత్సరాల పనిని తుడిచిపెట్టగలదు."}]},"hi":{"word":"सहयोग","question":"देश और कंपनियाँ सहयोग को कठिन क्यों मानती हैं, भले ही सभी को फ़ायदा हो?","examples":[{"en":"Cooperation fails when short-term advantage is chosen over benefits that everyone would share later.","native":"जब बाद में सबको मिलने वाले लाभ के बजाय अल्पकालिक फ़ायदा चुना जाता है, तो सहयोग विफल होता है।"},{"en":"If global problems were faced together, solutions would be found faster and cost much less.","native":"अगर वैश्विक समस्याओं का मिलकर सामना किया जाए, तो समाधान जल्दी मिलेंगे और काफ़ी कम ख़र्च होंगे।"},{"en":"Trust is built slowly between partners, although a single broken promise can undo years of work.","native":"भागीदारों के बीच भरोसा धीरे-धीरे बनता है, हालाँकि एक टूटा वादा सालों की मेहनत बरबाद कर सकता है।"}]},"es":{"word":"cooperación","question":"¿Por qué los países y las empresas encuentran difícil la cooperación, incluso cuando todos se beneficiarían?","examples":[{"en":"Cooperation fails when short-term advantage is chosen over benefits that everyone would share later.","native":"La cooperación fracasa cuando se elige la ventaja a corto plazo por encima de los beneficios que todos compartirían después."},{"en":"If global problems were faced together, solutions would be found faster and cost much less.","native":"Si los problemas globales se afrontaran juntos, las soluciones se encontrarían más rápido y costarían mucho menos."},{"en":"Trust is built slowly between partners, although a single broken promise can undo years of work.","native":"La confianza entre socios se construye lentamente, aunque una sola promesa rota puede arruinar años de trabajo."}]},"zh":{"word":"合作","question":"为什么国家和公司之间合作如此困难，即使合作对所有人都有利？","examples":[{"en":"Cooperation fails when short-term advantage is chosen over benefits that everyone would share later.","native":"当人们选择短期利益而放弃日后大家共享的好处时，合作就会失败。"},{"en":"If global problems were faced together, solutions would be found faster and cost much less.","native":"如果全球性问题能被共同面对，解决方案会更快找到，成本也会低得多。"},{"en":"Trust is built slowly between partners, although a single broken promise can undo years of work.","native":"伙伴之间的信任建立得很慢，尽管一个破碎的承诺就能毁掉多年的努力。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'city life', 'Is city life better than life in the countryside? What do people gain and lose in cities?', '{"te":{"word":"నగర జీవితం","question":"నగర జీవితం గ్రామీణ జీవితం కంటే మంచిదేనా? నగరాల్లో ప్రజలు ఏమి పొందుతారు మరియు ఏమి కోల్పోతారు?","examples":[{"en":"Cities offer jobs and excitement, although many residents feel lonely in the middle of crowds.","native":"నగరాలు ఉద్యోగాలు మరియు ఉత్సాహాన్ని అందిస్తాయి, అయితే చాలామంది నివాసితులు జనసమూహం మధ్యలో ఒంటరిగా భావిస్తారు."},{"en":"If smaller towns had better services, fewer families would be forced to move to crowded cities.","native":"చిన్న పట్టణాల్లో మెరుగైన సౌకర్యాలు ఉంటే, తక్కువ మంది కుటుంబాలు రద్దీగా ఉండే నగరాలకు మారవలసిన అవసరం ఉండదు."},{"en":"Green spaces are valued more when they are scarce, which explains the popularity of urban parks.","native":"పచ్చదనం కరువైనప్పుడు దానికి ఎక్కువ విలువ ఇస్తారు, దీనివల్లే పట్టణ పార్కుల ప్రజాదరణ వివరించబడుతుంది."}]},"hi":{"word":"शहरी जीवन","question":"क्या शहरी जीवन गाँव के जीवन से बेहतर है? शहरों में लोग क्या पाते हैं और क्या खोते हैं?","examples":[{"en":"Cities offer jobs and excitement, although many residents feel lonely in the middle of crowds.","native":"शहर नौकरियाँ और रोमांच देते हैं, हालाँकि कई निवासी भीड़ के बीच भी अकेला महसूस करते हैं।"},{"en":"If smaller towns had better services, fewer families would be forced to move to crowded cities.","native":"अगर छोटे कस्बों में बेहतर सुविधाएँ हों, तो कम परिवारों को भीड़भाड़ वाले शहरों में जाने के लिए मजबूर होना पड़ेगा।"},{"en":"Green spaces are valued more when they are scarce, which explains the popularity of urban parks.","native":"हरी-भरी जगहें दुर्लभ होने पर ज़्यादा महत्वपूर्ण लगती हैं, जो शहरी पार्कों की लोकप्रियता समझाता है।"}]},"es":{"word":"vida urbana","question":"¿Es la vida urbana mejor que la vida en el campo? ¿Qué ganan y pierden las personas en las ciudades?","examples":[{"en":"Cities offer jobs and excitement, although many residents feel lonely in the middle of crowds.","native":"Las ciudades ofrecen trabajo y emoción, aunque muchos residentes se sienten solos en medio de las multitudes."},{"en":"If smaller towns had better services, fewer families would be forced to move to crowded cities.","native":"Si los pueblos pequeños tuvieran mejores servicios, menos familias se verían obligadas a mudarse a ciudades abarrotadas."},{"en":"Green spaces are valued more when they are scarce, which explains the popularity of urban parks.","native":"Los espacios verdes se valoran más cuando escasean, lo que explica la popularidad de los parques urbanos."}]},"zh":{"word":"城市生活","question":"城市生活比乡村生活更好吗？人们在城市中得到了什么，又失去了什么？","examples":[{"en":"Cities offer jobs and excitement, although many residents feel lonely in the middle of crowds.","native":"城市提供工作和刺激，尽管许多居民在人群中仍感到孤独。"},{"en":"If smaller towns had better services, fewer families would be forced to move to crowded cities.","native":"如果小城镇有更好的服务，被迫搬往拥挤城市的家庭就会减少。"},{"en":"Green spaces are valued more when they are scarce, which explains the popularity of urban parks.","native":"绿地稀缺时更受珍视，这就解释了城市公园为何受欢迎。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'rural life', 'Why are young people leaving villages, and what could make rural life attractive again?', '{"te":{"word":"గ్రామీణ జీవితం","question":"యువకులు గ్రామాలను ఎందుకు వదిలివెళ్తున్నారు, మరియు గ్రామీణ జీవితాన్ని మళ్లీ ఆకర్షణీయంగా చేయడానికి ఏమి చేయవచ్చు?","examples":[{"en":"Villages are abandoned when schools and hospitals close, although the land itself remains beautiful.","native":"పాఠశాలలు మరియు ఆసుపత్రులు మూతపడినప్పుడు గ్రామాలు విడిచిపెట్టబడతాయి, అయితే భూమి స్వయంగా అందమైనదిగానే ఉంటుంది."},{"en":"If reliable internet reached every village, many jobs could be done far from any city.","native":"నమ్మకమైన ఇంటర్నెట్ ప్రతి గ్రామానికి చేరితే, అనేక ఉద్యోగాలు ఏదైనా నగరానికి చాలా దూరంగా చేయవచ్చు."},{"en":"Rural life offers peace and community, but opportunities are often limited to farming and tourism.","native":"గ్రామీణ జీవితం ప్రశాంతతను మరియు సమాజాన్ని అందిస్తుంది, కానీ అవకాశాలు తరచుగా వ్యవసాయం మరియు పర్యాటకానికే పరిమితం."}]},"hi":{"word":"ग्रामीण जीवन","question":"युवा गाँव क्यों छोड़ रहे हैं, और ग्रामीण जीवन को फिर से आकर्षक क्या बना सकता है?","examples":[{"en":"Villages are abandoned when schools and hospitals close, although the land itself remains beautiful.","native":"जब स्कूल और अस्पताल बंद हो जाते हैं तो गाँव खाली हो जाते हैं, हालाँकि ज़मीन खुद वैसी ही खूबसूरत रहती है।"},{"en":"If reliable internet reached every village, many jobs could be done far from any city.","native":"अगर भरोसेमंद इंटरनेट हर गाँव तक पहुँचे, तो कई काम किसी भी शहर से दूर किए जा सकते हैं।"},{"en":"Rural life offers peace and community, but opportunities are often limited to farming and tourism.","native":"ग्रामीण जीवन शांति और अपनापन देता है, लेकिन अवसर अक्सर खेती और पर्यटन तक ही सीमित रहते हैं।"}]},"es":{"word":"vida rural","question":"¿Por qué los jóvenes abandonan los pueblos, y qué podría hacer atractiva de nuevo la vida rural?","examples":[{"en":"Villages are abandoned when schools and hospitals close, although the land itself remains beautiful.","native":"Los pueblos se abandonan cuando cierran las escuelas y los hospitales, aunque la tierra en sí sigue siendo hermosa."},{"en":"If reliable internet reached every village, many jobs could be done far from any city.","native":"Si internet fiable llegara a cada pueblo, muchos trabajos podrían hacerse lejos de cualquier ciudad."},{"en":"Rural life offers peace and community, but opportunities are often limited to farming and tourism.","native":"La vida rural ofrece paz y comunidad, pero las oportunidades suelen limitarse a la agricultura y el turismo."}]},"zh":{"word":"乡村生活","question":"为什么年轻人正在离开村庄？怎样才能让乡村生活重新变得有吸引力？","examples":[{"en":"Villages are abandoned when schools and hospitals close, although the land itself remains beautiful.","native":"当学校和医院关闭时，村庄就被遗弃了，尽管土地本身依然美丽。"},{"en":"If reliable internet reached every village, many jobs could be done far from any city.","native":"如果可靠的网络覆盖每个村庄，许多工作可以在远离任何城市的地方完成。"},{"en":"Rural life offers peace and community, but opportunities are often limited to farming and tourism.","native":"乡村生活提供宁静和社区感，但机会往往仅限于农业和旅游业。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'aging', 'How should societies care for aging populations, and what can we learn from older people?', '{"te":{"word":"వృద్ధాప్యం","question":"వృద్ధాప్య జనాభాను సమాజాలు ఎలా చూసుకోవాలి, మరియు వృద్ధుల నుండి మనం ఏమి నేర్చుకోవచ్చు?","examples":[{"en":"Older people carry experience that cannot be taught in schools, although it is often ignored.","native":"వృద్ధులు పాఠశాలల్లో నేర్పలేని అనుభవాన్ని మోస్తారు, అయితే అది తరచుగా పట్టించుకోబడదు."},{"en":"If pensions are not protected, millions of elderly citizens will be pushed into poverty.","native":"పెన్షన్లు రక్షించబడకపోతే, లక్షలాది మంది వృద్ధ పౌరులు పేదరికంలోకి నెట్టబడతారు."},{"en":"Care homes are expensive, yet many families live too far apart to help their parents daily.","native":"సంరక్షణ గృహాలు ఖరీదైనవి, అయితే చాలామంది కుటుంబాలు తమ తల్లిదండ్రులకు రోజూ సహాయం చేయలేనంత దూరంగా ఉంటారు."}]},"hi":{"word":"बुढ़ापा","question":"समाजों को बुज़ुर्ग आबादी की देखभाल कैसे करनी चाहिए, और हम बुज़ुर्गों से क्या सीख सकते हैं?","examples":[{"en":"Older people carry experience that cannot be taught in schools, although it is often ignored.","native":"बुज़ुर्ग वह अनुभव लिए होते हैं जो स्कूलों में नहीं सिखाया जा सकता, हालाँकि अक्सर उसे नज़रअंदाज़ किया जाता है।"},{"en":"If pensions are not protected, millions of elderly citizens will be pushed into poverty.","native":"अगर पेंशन सुरक्षित न रही, तो लाखों बुज़ुर्ग नागरिक ग़रीबी में धकेले जाएँगे।"},{"en":"Care homes are expensive, yet many families live too far apart to help their parents daily.","native":"केयर होम महँगे हैं, फिर भी कई परिवार अपने माता-पिता की रोज़ मदद के लिए बहुत दूर रहते हैं।"}]},"es":{"word":"envejecimiento","question":"¿Cómo deberían las sociedades cuidar a las poblaciones que envejecen, y qué podemos aprender de las personas mayores?","examples":[{"en":"Older people carry experience that cannot be taught in schools, although it is often ignored.","native":"Las personas mayores cargan una experiencia que no se puede enseñar en las escuelas, aunque a menudo se ignora."},{"en":"If pensions are not protected, millions of elderly citizens will be pushed into poverty.","native":"Si no se protegen las pensiones, millones de ciudadanos mayores serán empujados a la pobreza."},{"en":"Care homes are expensive, yet many families live too far apart to help their parents daily.","native":"Las residencias son caras, pero muchas familias viven demasiado lejos para ayudar a sus padres a diario."}]},"zh":{"word":"老龄化","question":"社会应该如何照顾老龄化人口？我们能从老年人身上学到什么？","examples":[{"en":"Older people carry experience that cannot be taught in schools, although it is often ignored.","native":"老年人拥有学校无法传授的经验，尽管这些经验常常被忽视。"},{"en":"If pensions are not protected, millions of elderly citizens will be pushed into poverty.","native":"如果养老金得不到保障，数百万老年公民将陷入贫困。"},{"en":"Care homes are expensive, yet many families live too far apart to help their parents daily.","native":"养老院费用高昂，然而许多家庭住得太远，无法每天帮助父母。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'retirement', 'Is a fixed retirement age fair, or should people decide for themselves when to stop working?', '{"te":{"word":"పదవీ విరమణ","question":"స్థిర పదవీ విరమణ వయసు న్యాయమైనదేనా, లేక ఎప్పుడు పని ఆపాలో ప్రజలే నిర్ణయించుకోవాలా?","examples":[{"en":"Retirement is welcomed by tired workers, although some people feel useless without their daily routine.","native":"అలసిపోయిన కార్మికులు పదవీ విరమణను స్వాగతిస్తారు, అయితే కొందరు రోజువారీ దినచర్య లేకుండా నిష్ప్రయోజకంగా భావిస్తారు."},{"en":"If the retirement age rises further, younger generations may struggle to find good positions.","native":"పదవీ విరమణ వయసు మరింత పెరిగితే, యువతరాలు మంచి ఉద్యోగాలు కనుగొనడానికి ఇబ్బంది పడవచ్చు."},{"en":"Experience is lost when experts retire early, but forcing everyone to stay is unfair.","native":"నిపుణులు ముందే పదవీ విరమణ చేసినప్పుడు అనుభవం కోల్పోతుంది, కానీ అందరినీ బలవంతంగా ఉంచడం అన్యాయం."}]},"hi":{"word":"सेवानिवृत्ति","question":"क्या निश्चित सेवानिवृत्ति आयु उचित है, या लोगों को खुद तय करना चाहिए कि काम कब छोड़ना है?","examples":[{"en":"Retirement is welcomed by tired workers, although some people feel useless without their daily routine.","native":"थके कर्मचारी सेवानिवृत्ति का स्वागत करते हैं, हालाँकि कुछ लोग अपनी दिनचर्या के बिना बेकार महसूस करते हैं।"},{"en":"If the retirement age rises further, younger generations may struggle to find good positions.","native":"अगर सेवानिवृत्ति की उम्र और बढ़ती है, तो युवा पीढ़ी अच्छे पद खोजने के लिए संघर्ष कर सकती है।"},{"en":"Experience is lost when experts retire early, but forcing everyone to stay is unfair.","native":"जब विशेषज्ञ जल्दी सेवानिवृत्त होते हैं तो अनुभव खोता है, लेकिन सबको बने रहने के लिए मजबूर करना अनुचित है।"}]},"es":{"word":"jubilación","question":"¿Es justa una edad de jubilación fija, o debería cada persona decidir cuándo dejar de trabajar?","examples":[{"en":"Retirement is welcomed by tired workers, although some people feel useless without their daily routine.","native":"Los trabajadores cansados reciben la jubilación con gusto, aunque algunas personas se sienten inútiles sin su rutina diaria."},{"en":"If the retirement age rises further, younger generations may struggle to find good positions.","native":"Si la edad de jubilación sube más, las generaciones jóvenes pueden tener dificultades para encontrar buenos puestos."},{"en":"Experience is lost when experts retire early, but forcing everyone to stay is unfair.","native":"La experiencia se pierde cuando los expertos se jubilan pronto, pero obligar a todos a quedarse es injusto."}]},"zh":{"word":"退休","question":"固定的退休年龄公平吗，还是应该让人们自己决定何时停止工作？","examples":[{"en":"Retirement is welcomed by tired workers, although some people feel useless without their daily routine.","native":"疲惫的劳动者欢迎退休，尽管有些人离开日常作息后会觉得自己一无是处。"},{"en":"If the retirement age rises further, younger generations may struggle to find good positions.","native":"如果退休年龄进一步提高，年轻一代可能难以找到好职位。"},{"en":"Experience is lost when experts retire early, but forcing everyone to stay is unfair.","native":"专家过早退休会让经验流失，但强迫所有人继续工作也不公平。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'unemployment', 'What causes unemployment, and whose responsibility is it to solve the problem?', '{"te":{"word":"నిరుద్యోగం","question":"నిరుద్యోగానికి కారణం ఏమిటి, మరియు ఈ సమస్యను పరిష్కరించడం ఎవరి బాధ్యత?","examples":[{"en":"Unemployment damages confidence as well as income, although society often blames the victims instead.","native":"నిరుద్యోగం ఆదాయంతో పాటు ఆత్మవిశ్వాసాన్ని కూడా దెబ్బతీస్తుంది, అయితే సమాజం తరచుగా బాధితులనే నిందిస్తుంది."},{"en":"If industries disappear from a region, entire towns can be left without any purpose.","native":"ఒక ప్రాంతం నుండి పరిశ్రమలు అదృశ్యమైతే, మొత్తం పట్టణాలు ఎలాంటి లక్ష్యం లేకుండా మిగిలిపోతాయి."},{"en":"Retraining programmes are always promised after every crisis, but the results are rarely measured properly.","native":"ప్రతి సంక్షోభం తర్వాత పునశ్శిక్షణ కార్యక్రమాలు ఎల్లప్పుడూ ప్రామిస్ చేయబడతాయి, కానీ ఫలితాలు అరుదుగా సరిగ్గా కొలవబడతాయి."}]},"hi":{"word":"बेरोज़गारी","question":"बेरोज़गारी के कारण क्या हैं, और इस समस्या को हल करना किसकी ज़िम्मेदारी है?","examples":[{"en":"Unemployment damages confidence as well as income, although society often blames the victims instead.","native":"बेरोज़गारी आय के साथ-साथ आत्मविश्वास को भी नुकसान पहुँचाती है, हालाँकि समाज अक्सर पीड़ितों को ही दोष देता है।"},{"en":"If industries disappear from a region, entire towns can be left without any purpose.","native":"अगर किसी क्षेत्र से उद्योग गायब हो जाएँ, तो पूरे कस्बे बिना किसी उद्देश्य के रह सकते हैं।"},{"en":"Retraining programmes are always promised after every crisis, but the results are rarely measured properly.","native":"हर संकट के बाद पुनः प्रशिक्षण कार्यक्रमों का वादा किया जाता है, लेकिन परिणाम शायद ही ठीक से मापे जाते हैं।"}]},"es":{"word":"desempleo","question":"¿Qué causa el desempleo, y de quién es la responsabilidad de resolver el problema?","examples":[{"en":"Unemployment damages confidence as well as income, although society often blames the victims instead.","native":"El desempleo daña la confianza además de los ingresos, aunque la sociedad suele culpar a las víctimas."},{"en":"If industries disappear from a region, entire towns can be left without any purpose.","native":"Si las industrias desaparecen de una región, pueblos enteros pueden quedarse sin ningún propósito."},{"en":"Retraining programmes are always promised after every crisis, but the results are rarely measured properly.","native":"Siempre se prometen programas de reconversión tras cada crisis, pero los resultados rara vez se miden correctamente."}]},"zh":{"word":"失业","question":"失业的原因是什么？解决这个问题是谁的责任？","examples":[{"en":"Unemployment damages confidence as well as income, although society often blames the victims instead.","native":"失业损害的不仅是收入，还有信心，尽管社会往往反而责怪受害者。"},{"en":"If industries disappear from a region, entire towns can be left without any purpose.","native":"如果一个地区的产业消失，整个城镇可能失去存在的意义。"},{"en":"Retraining programmes are always promised after every crisis, but the results are rarely measured properly.","native":"每次危机之后总会承诺再培训计划，但效果很少得到妥善衡量。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'entrepreneurship', 'Should more young people start their own businesses instead of working for established companies?', '{"te":{"word":"వ్యవస్థాపకత","question":"స్థాపిత కంపెనీల కోసం పనిచేయడం బదులు మరిన్ని మంది యువకులు తమ స్వంత వ్యాపారాలు ప్రారంభించాలా?","examples":[{"en":"Starting a business offers freedom, although most new companies fail within their first five years.","native":"వ్యాపారం ప్రారంభించడం స్వేచ్ఛను అందిస్తుంది, అయితే చాలామంది కొత్త కంపెనీలు తమ మొదటి ఐదు సంవత్సరాల్లోనే విఫలమవుతాయి."},{"en":"If entrepreneurship were taught in a practical way at school, far fewer graduates would fear self-employment.","native":"పాఠశాలలో వ్యవస్థాపకతను ఆచరణాత్మకంగా బోధిస్తే, చాలా తక్కువ మంది గ్రాడ్యుయేట్లు స్వయం ఉపాధికి భయపడతారు."},{"en":"Stable salaries are sacrificed by founders, but the lessons of failure often lead somewhere better.","native":"స్థిరమైన జీతాలు వ్యవస్థాపకులు త్యాగం చేస్తారు, కానీ వైఫల్య పాఠాలు తరచుగా ఎక్కడో మంచి చోటుకు దారితీస్తాయి."}]},"hi":{"word":"उद्यमिता","question":"क्या ज़्यादा युवाओं को स्थापित कंपनियों के लिए काम करने के बजाय अपना कारोबार शुरू करना चाहिए?","examples":[{"en":"Starting a business offers freedom, although most new companies fail within their first five years.","native":"कारोबार शुरू करने से आज़ादी मिलती है, हालाँकि ज़्यादातर नई कंपनियाँ अपने पहले पाँच सालों में ही असफल हो जाती हैं।"},{"en":"If entrepreneurship were taught in a practical way at school, far fewer graduates would fear self-employment.","native":"अगर स्कूल में उद्यमिता व्यावहारिक तरीके से पढ़ाई जाए, तो काफ़ी कम स्नातक स्व-रोज़गार से डरेंगे।"},{"en":"Stable salaries are sacrificed by founders, but the lessons of failure often lead somewhere better.","native":"संस्थापक स्थिर वेतन का त्याग करते हैं, लेकिन असफलता के सबक अक्सर कहीं बेहतर की ओर ले जाते हैं।"}]},"es":{"word":"emprendimiento","question":"¿Deberían más jóvenes crear sus propias empresas en lugar de trabajar para compañías establecidas?","examples":[{"en":"Starting a business offers freedom, although most new companies fail within their first five years.","native":"Crear una empresa ofrece libertad, aunque la mayoría de las compañías nuevas fracasan en sus primeros cinco años."},{"en":"If entrepreneurship were taught in a practical way at school, far fewer graduates would fear self-employment.","native":"Si el emprendimiento se enseñara de forma práctica en la escuela, muchos menos graduados temerían el trabajo autónomo."},{"en":"Stable salaries are sacrificed by founders, but the lessons of failure often lead somewhere better.","native":"Los fundadores sacrifican salarios estables, pero las lecciones del fracaso a menudo conducen a algo mejor."}]},"zh":{"word":"创业","question":"更多年轻人应该自己创业，而不是为成熟的公司工作吗？","examples":[{"en":"Starting a business offers freedom, although most new companies fail within their first five years.","native":"创业带来自由，尽管大多数新公司在头五年内就会失败。"},{"en":"If entrepreneurship were taught in a practical way at school, far fewer graduates would fear self-employment.","native":"如果学校以实践方式教授创业知识，害怕自雇的毕业生会少得多。"},{"en":"Stable salaries are sacrificed by founders, but the lessons of failure often lead somewhere better.","native":"创业者牺牲了稳定的薪水，但失败的教训往往会通向更好的地方。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'climate change', 'Is climate change the biggest threat we face, and can individual actions make a difference?', '{"te":{"word":"వాతావరణ మార్పు","question":"వాతావరణ మార్పు మనం ఎదుర్కొంటున్న అతిపెద్ద ముప్పా, మరియు వ్యక్తిగత చర్యలు మార్పు తీయగలవా?","examples":[{"en":"Climate change is caused mostly by large industries, although individual choices still send signals.","native":"వాతావరణ మార్పు ఎక్కువగా పెద్ద పరిశ్రమల వల్లే జరుగుతుంది, అయితే వ్యక్తిగత ఎంపికలు ఇంకా సంకేతాలు పంపుతాయి."},{"en":"If governments acted together now, the worst effects could still be avoided this century.","native":"ప్రభుత్వాలు ఇప్పుడే కలిసి చర్య తీసుకుంటే, ఈ శతాబ్దంలో అత్యంత చెత్త ప్రభావాలను ఇంకా నివారించవచ్చు."},{"en":"Extreme weather is reported every week, yet many people behave as if nothing has changed.","native":"తీవ్ర వాతావరణం ప్రతి వారం నివేదించబడుతుంది, అయితే చాలామంది ఏమీ మారలేదన్నట్లు ప్రవర్తిస్తున్నారు."}]},"hi":{"word":"जलवायु परिवर्तन","question":"क्या जलवायु परिवर्तन हमारे सामने सबसे बड़ा ख़तरा है, और क्या व्यक्तिगत कार्य फ़र्क़ डाल सकते हैं?","examples":[{"en":"Climate change is caused mostly by large industries, although individual choices still send signals.","native":"जलवायु परिवर्तन ज़्यादातर बड़े उद्योगों से होता है, हालाँकि व्यक्तिगत चुनाव भी संकेत भेजते हैं।"},{"en":"If governments acted together now, the worst effects could still be avoided this century.","native":"अगर सरकारें अभी मिलकर कार्रवाई करें, तो इस सदी में सबसे बुरे प्रभावों को अब भी टाला जा सकता है।"},{"en":"Extreme weather is reported every week, yet many people behave as if nothing has changed.","native":"हर हफ़्ते चरम मौसम की ख़बरें आती हैं, फिर भी कई लोग ऐसे व्यवहार करते हैं मानो कुछ बदला ही नहीं।"}]},"es":{"word":"cambio climático","question":"¿Es el cambio climático la mayor amenaza que enfrentamos, y pueden las acciones individuales marcar la diferencia?","examples":[{"en":"Climate change is caused mostly by large industries, although individual choices still send signals.","native":"El cambio climático es causado mayormente por las grandes industrias, aunque las decisiones individuales aún envían señales."},{"en":"If governments acted together now, the worst effects could still be avoided this century.","native":"Si los gobiernos actuaran juntos ahora, los peores efectos aún podrían evitarse este siglo."},{"en":"Extreme weather is reported every week, yet many people behave as if nothing has changed.","native":"Se informa de fenómenos meteorológicos extremos cada semana, y sin embargo mucha gente actúa como si nada hubiera cambiado."}]},"zh":{"word":"气候变化","question":"气候变化是我们面临的最大威胁吗？个人行动能产生影响吗？","examples":[{"en":"Climate change is caused mostly by large industries, although individual choices still send signals.","native":"气候变化主要由大型工业造成，尽管个人选择仍然会发出信号。"},{"en":"If governments acted together now, the worst effects could still be avoided this century.","native":"如果各国政府现在共同行动，本世纪最糟糕的影响仍然可以避免。"},{"en":"Extreme weather is reported every week, yet many people behave as if nothing has changed.","native":"极端天气每周都有报道，然而许多人的行为却好像什么都没有改变。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'renewable energy', 'Can renewable energy completely replace fossil fuels? What stands in the way?', '{"te":{"word":"పునరుత్పాదక శక్తి","question":"పునరుత్పాదక శక్తి శిలాజ ఇంధనాలను పూర్తిగా భర్తీ చేయగలదా? అడ్డంకి ఏమిటి?","examples":[{"en":"Solar and wind power have become cheaper, although storing their energy remains a challenge.","native":"సౌర మరియు పవన శక్తి చవకైనవి అయ్యాయి, అయితే వాటి శక్తిని నిల్వ చేయడం ఇంకా సవాలుగానే ఉంది."},{"en":"If fossil fuel subsidies were finally removed, green alternatives would compete much more fairly.","native":"శిలాజ ఇంధన సబ్సిడీలు చివరగా తొలగించబడితే, పచ్చని ప్రత్యామ్నాయాలు మరింత న్యాయంగా పోటీ చేస్తాయి."},{"en":"Entire regions are powered by renewables already, but heavy industry changes far more slowly.","native":"మొత్తం ప్రాంతాలు ఇప్పటికే పునరుత్పాదక శక్తితో నడుస్తున్నాయి, కానీ భారీ పరిశ్రమలు చాలా నెమ్మదిగా మారుతాయి."}]},"hi":{"word":"नवीकरणीय ऊर्जा","question":"क्या नवीकरणीय ऊर्जा जीवाश्म ईंधन की पूरी तरह जगह ले सकती है? रास्ते में क्या बाधा है?","examples":[{"en":"Solar and wind power have become cheaper, although storing their energy remains a challenge.","native":"सौर और पवन ऊर्जा सस्ती हो गई है, हालाँकि उसकी ऊर्जा जमा करना अभी भी एक चुनौती है।"},{"en":"If fossil fuel subsidies were finally removed, green alternatives would compete much more fairly.","native":"अगर जीवाश्म ईंधन सब्सिडी आख़िरकार हटा दी जाएँ, तो हरित विकल्प कहीं ज़्यादा निष्पक्ष रूप से प्रतिस्पर्धा करेंगे।"},{"en":"Entire regions are powered by renewables already, but heavy industry changes far more slowly.","native":"पूरे क्षेत्र पहले से ही नवीकरणीय ऊर्जा से चल रहे हैं, लेकिन भारी उद्योग काफ़ी धीरे बदलते हैं।"}]},"es":{"word":"energía renovable","question":"¿Puede la energía renovable reemplazar por completo a los combustibles fósiles? ¿Qué lo impide?","examples":[{"en":"Solar and wind power have become cheaper, although storing their energy remains a challenge.","native":"La energía solar y eólica se han abaratado, aunque almacenar su energía sigue siendo un desafío."},{"en":"If fossil fuel subsidies were finally removed, green alternatives would compete much more fairly.","native":"Si por fin se eliminaran los subsidios a los combustibles fósiles, las alternativas verdes competirían de forma mucho más justa."},{"en":"Entire regions are powered by renewables already, but heavy industry changes far more slowly.","native":"Regiones enteras ya funcionan con renovables, pero la industria pesada cambia mucho más despacio."}]},"zh":{"word":"可再生能源","question":"可再生能源能完全取代化石燃料吗？障碍是什么？","examples":[{"en":"Solar and wind power have become cheaper, although storing their energy remains a challenge.","native":"太阳能和风能已经变得更便宜，尽管储存这些能源仍然是一个挑战。"},{"en":"If fossil fuel subsidies were finally removed, green alternatives would compete much more fairly.","native":"如果最终取消化石燃料补贴，绿色替代能源的竞争会公平得多。"},{"en":"Entire regions are powered by renewables already, but heavy industry changes far more slowly.","native":"一些地区已经完全由可再生能源供电，但重工业的变革要慢得多。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'pollution', 'Who should pay for cleaning up pollution — companies, governments, or consumers?', '{"te":{"word":"కాలుష్యం","question":"కాలుష్యాన్ని శుభ్రం చేయడానికి ఎవరు చెల్లించాలి — కంపెనీలా, ప్రభుత్వాలా, లేక వినియోగదారులా?","examples":[{"en":"Pollution is created mostly for profit, although its costs are paid by everyone else.","native":"కాలుష్యం ఎక్కువగా లాభం కోసం సృష్టించబడుతుంది, అయితే దాని ఖర్చులు మిగతా అందరూ చెల్లిస్తారు."},{"en":"If companies paid the true cost of waste, cleaner methods would be adopted very quickly.","native":"కంపెనీలు వ్యర్థాల నిజమైన ఖర్చు చెల్లిస్తే, శుభ్రమైన పద్ధతులు చాలా త్వరగా అవలంబించబడతాయి."},{"en":"Rivers can recover when dumping is stopped, but the damage may take decades to reverse.","native":"డంపింగ్ ఆగిపోయినప్పుడు నదులు కోలుకోగలవు, కానీ నష్టాన్ని తిప్పికొట్టడానికి దశాబ్దాలు పట్టవచ్చు."}]},"hi":{"word":"प्रदूषण","question":"प्रदूषण साफ़ करने का ख़र्च किसे उठाना चाहिए — कंपनियों को, सरकारों को, या उपभोक्ताओं को?","examples":[{"en":"Pollution is created mostly for profit, although its costs are paid by everyone else.","native":"प्रदूषण ज़्यादातर मुनाफ़े के लिए पैदा किया जाता है, हालाँकि उसकी कीमत बाक़ी सब चुकाते हैं।"},{"en":"If companies paid the true cost of waste, cleaner methods would be adopted very quickly.","native":"अगर कंपनियाँ कचरे की असली कीमत चुकाएँ, तो स्वच्छ तरीके बहुत जल्दी अपनाए जाएँगे।"},{"en":"Rivers can recover when dumping is stopped, but the damage may take decades to reverse.","native":"कचरा डालना बंद होने पर नदियाँ ठीक हो सकती हैं, लेकिन नुकसान को पलटने में दशक लग सकते हैं।"}]},"es":{"word":"contaminación","question":"¿Quién debería pagar por limpiar la contaminación: las empresas, los gobiernos o los consumidores?","examples":[{"en":"Pollution is created mostly for profit, although its costs are paid by everyone else.","native":"La contaminación se crea sobre todo para obtener beneficios, aunque sus costes los pagan todos los demás."},{"en":"If companies paid the true cost of waste, cleaner methods would be adopted very quickly.","native":"Si las empresas pagaran el coste real de los residuos, se adoptarían métodos más limpios muy rápidamente."},{"en":"Rivers can recover when dumping is stopped, but the damage may take decades to reverse.","native":"Los ríos pueden recuperarse cuando se deja de verter en ellos, pero el daño puede tardar décadas en revertirse."}]},"zh":{"word":"污染","question":"治理污染的费用应该由谁承担——企业、政府还是消费者？","examples":[{"en":"Pollution is created mostly for profit, although its costs are paid by everyone else.","native":"污染大多是为利润而制造的，尽管其代价由其他所有人承担。"},{"en":"If companies paid the true cost of waste, cleaner methods would be adopted very quickly.","native":"如果企业支付废弃物的真实成本，更清洁的生产方式会被迅速采用。"},{"en":"Rivers can recover when dumping is stopped, but the damage may take decades to reverse.","native":"停止倾倒后河流可以恢复，但损害可能需要几十年才能逆转。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'recycling', 'Does recycling actually work, or is it just a way to make consumers feel better?', '{"te":{"word":"రీసైక్లింగ్","question":"రీసైక్లింగ్ నిజంగా పనిచేస్తుందా, లేక ఇది వినియోగదారులకు ఉపశమనం కల్పించే మార్గమేనా?","examples":[{"en":"Recycling certainly helps, although reducing what we buy would help the planet far more.","native":"రీసైక్లింగ్ ఖచ్చితంగా సహాయపడుతుంది, అయితే మనం కొనేది తగ్గిస్తే గ్రహానికి ఇంకా ఎక్కువ సహాయం అవుతుంది."},{"en":"If packaging were standardized absolutely everywhere, sorting waste at home would become much simpler.","native":"ప్యాకేజింగ్ ప్రతిచోటా ప్రామాణీకరించబడితే, ఇంట్లో వ్యర్థాలను వేరుచేయడం చాలా సులభం అవుతుంది."},{"en":"Much of what is carefully collected for recycling is shipped abroad and dumped instead.","native":"రీసైక్లింగ్ కోసం జాగ్రత్తగా సేకరించిన దానిలో ఎక్కువ భాగం విదేశాలకు రవాణా చేయబడి డంప్ చేయబడుతుంది."}]},"hi":{"word":"रीसाइक्लिंग","question":"क्या रीसाइक्लिंग सच में काम करती है, या यह उपभोक्ताओं को बेहतर महसूस कराने का तरीका भर है?","examples":[{"en":"Recycling certainly helps, although reducing what we buy would help the planet far more.","native":"रीसाइक्लिंग ज़रूर मदद करती है, हालाँकि हम जो ख़रीदते हैं उसे घटाने से ग्रह को कहीं ज़्यादा फ़ायदा होगा।"},{"en":"If packaging were standardized absolutely everywhere, sorting waste at home would become much simpler.","native":"अगर पैकेजिंग हर जगह बिल्कुल एकसमान हो जाए, तो घर पर कचरा छाँटना काफ़ी आसान हो जाएगा।"},{"en":"Much of what is carefully collected for recycling is shipped abroad and dumped instead.","native":"रीसाइक्लिंग के लिए ध्यान से इकट्ठा की गई चीज़ों का बड़ा हिस्सा विदेश भेजकर डंप कर दिया जाता है।"}]},"es":{"word":"reciclaje","question":"¿Funciona realmente el reciclaje, o es solo una forma de hacer sentir mejor a los consumidores?","examples":[{"en":"Recycling certainly helps, although reducing what we buy would help the planet far more.","native":"El reciclaje ciertamente ayuda, aunque reducir lo que compramos ayudaría mucho más al planeta."},{"en":"If packaging were standardized absolutely everywhere, sorting waste at home would become much simpler.","native":"Si los envases se estandarizaran absolutamente en todas partes, separar los residuos en casa sería mucho más sencillo."},{"en":"Much of what is carefully collected for recycling is shipped abroad and dumped instead.","native":"Gran parte de lo que se recoge cuidadosamente para reciclar se envía al extranjero y se tira."}]},"zh":{"word":"回收利用","question":"回收利用真的有效吗，还是它只是让消费者心里好受一点的方式？","examples":[{"en":"Recycling certainly helps, although reducing what we buy would help the planet far more.","native":"回收利用确实有帮助，尽管减少购买对地球的帮助会大得多。"},{"en":"If packaging were standardized absolutely everywhere, sorting waste at home would become much simpler.","native":"如果包装在所有地方都完全标准化，在家分类垃圾会简单得多。"},{"en":"Much of what is carefully collected for recycling is shipped abroad and dumped instead.","native":"为回收而仔细收集的东西，有很大一部分被运到国外倾倒掉了。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'space exploration', 'Is space exploration worth the money when so many problems remain unsolved on Earth?', '{"te":{"word":"అంతరిక్ష అన్వేషణ","question":"భూమిపై ఇంకా చాలా సమస్యలు పరిష్కరించబడకుండా ఉన్నప్పుడు అంతరిక్ష అన్వేషణ డబ్బుకు విలువైనదేనా?","examples":[{"en":"Space missions are very expensive, although their inventions often improve daily life on Earth.","native":"అంతరిక్ష మిషన్లు చాలా ఖరీదైనవి, అయితే వాటి ఆవిష్కరణలు తరచుగా భూమిపై రోజువారీ జీవితాన్ని మెరుగుపరుస్తాయి."},{"en":"If satellites disappeared tomorrow, weather forecasts, navigation and global communication would all collapse quickly.","native":"రేపు ఉపగ్రహాలు అదృశ్యమైతే, వాతావరణ సూచనలు, నావిగేషన్ మరియు ప్రపంచ కమ్యూనికేషన్ అన్నీ త్వరగా కుప్పకూలతాయి."},{"en":"Critics ask why rockets are funded while hospitals struggle, and the question deserves an answer.","native":"ఆసుపత్రులు ఇబ్బంది పడుతుండగా రాకెట్లకు ఎందుకు నిధులిస్తారని విమర్శకులు అడుగుతారు, మరియు ఆ ప్రశ్నకు సమాధానం అర్హం."}]},"hi":{"word":"अंतरिक्ष अन्वेषण","question":"जब धरती पर इतनी समस्याएँ हल होना बाक़ी हैं, तो क्या अंतरिक्ष अन्वेषण पैसे लायक़ है?","examples":[{"en":"Space missions are very expensive, although their inventions often improve daily life on Earth.","native":"अंतरिक्ष मिशन बहुत महँगे हैं, हालाँकि उनके आविष्कार अक्सर धरती पर रोज़मर्रा की ज़िंदगी बेहतर बनाते हैं।"},{"en":"If satellites disappeared tomorrow, weather forecasts, navigation and global communication would all collapse quickly.","native":"अगर कल उपग्रह गायब हो जाएँ, तो मौसम पूर्वानुमान, नेविगेशन और वैश्विक संचार सब जल्दी ढह जाएँगे।"},{"en":"Critics ask why rockets are funded while hospitals struggle, and the question deserves an answer.","native":"आलोचक पूछते हैं कि अस्पताल संघर्ष कर रहे हों तो रॉकेट को क्यों फंड किया जाए, और इस सवाल का जवाब मिलना चाहिए।"}]},"es":{"word":"exploración espacial","question":"¿Vale la pena gastar dinero en la exploración espacial cuando quedan tantos problemas sin resolver en la Tierra?","examples":[{"en":"Space missions are very expensive, although their inventions often improve daily life on Earth.","native":"Las misiones espaciales son muy caras, aunque sus inventos a menudo mejoran la vida diaria en la Tierra."},{"en":"If satellites disappeared tomorrow, weather forecasts, navigation and global communication would all collapse quickly.","native":"Si los satélites desaparecieran mañana, los pronósticos del tiempo, la navegación y la comunicación global colapsarían rápidamente."},{"en":"Critics ask why rockets are funded while hospitals struggle, and the question deserves an answer.","native":"Los críticos preguntan por qué se financian cohetes mientras los hospitales pasan dificultades, y la pregunta merece una respuesta."}]},"zh":{"word":"太空探索","question":"地球上还有那么多问题没有解决，太空探索值得花这些钱吗？","examples":[{"en":"Space missions are very expensive, although their inventions often improve daily life on Earth.","native":"太空任务非常昂贵，尽管它们的发明常常改善地球上的日常生活。"},{"en":"If satellites disappeared tomorrow, weather forecasts, navigation and global communication would all collapse quickly.","native":"如果卫星明天消失，天气预报、导航和全球通信都会迅速崩溃。"},{"en":"Critics ask why rockets are funded while hospitals struggle, and the question deserves an answer.","native":"批评者问，为什么在医院苦苦挣扎时还要资助火箭，这个问题值得一个答案。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'genetic engineering', 'Should genetic engineering be used to change human embryos, or only to treat disease?', '{"te":{"word":"జెనెటిక్ ఇంజనీరింగ్","question":"మానవ భ్రూణాలను మార్చడానికి జెనెటిక్ ఇంజనీరింగ్ వాడాలా, లేక వ్యాధులను నయం చేయడానికి మాత్రమే వాడాలా?","examples":[{"en":"Genetic engineering can cure terrible inherited diseases, although designing babies raises impossible ethical questions.","native":"జెనెటిక్ ఇంజనీరింగ్ భయంకరమైన వంశపారంపర్య వ్యాధులను నయం చేయగలదు, అయితే శిశువులను డిజైన్ చేయడం అసాధ్యమైన నైతిక ప్రశ్నలను లేవనెత్తుతుంది."},{"en":"If gene editing were available only to the rich, inequality would be written into biology.","native":"జీన్ ఎడిటింగ్ ధనికులకు మాత్రమే అందుబాటులో ఉంటే, అసమానత జీవశాస్త్రంలోకి వ్రాయబడుతుంది."},{"en":"Crops are modified to resist drought, but their long-term effects are still debated fiercely.","native":"పంటలు కరువును తట్టుకునేలా మార్చబడతాయి, కానీ వాటి దీర్ఘకాలిక ప్రభావాలపై ఇంకా తీవ్రంగా చర్చ జరుగుతోంది."}]},"hi":{"word":"आनुवंशिक इंजीनियरिंग","question":"क्या आनुवंशिक इंजीनियरिंग का उपयोग मानव भ्रूणों को बदलने के लिए किया जाना चाहिए, या केवल बीमारी के इलाज के लिए?","examples":[{"en":"Genetic engineering can cure terrible inherited diseases, although designing babies raises impossible ethical questions.","native":"आनुवंशिक इंजीनियरिंग भयानक आनुवंशिक बीमारियों का इलाज कर सकती है, हालाँकि बच्चों को डिज़ाइन करना असंभव नैतिक सवाल उठाता है।"},{"en":"If gene editing were available only to the rich, inequality would be written into biology.","native":"अगर जीन एडिटिंग सिर्फ़ अमीरों के लिए उपलब्ध हो, तो असमानता जीव विज्ञान में लिखी जाएगी।"},{"en":"Crops are modified to resist drought, but their long-term effects are still debated fiercely.","native":"फ़सलों को सूखा झेलने के लिए बदला जाता है, लेकिन उनके दीर्घकालिक प्रभावों पर अब भी ज़ोरदार बहस होती है।"}]},"es":{"word":"ingeniería genética","question":"¿Debería usarse la ingeniería genética para modificar embriones humanos, o solo para tratar enfermedades?","examples":[{"en":"Genetic engineering can cure terrible inherited diseases, although designing babies raises impossible ethical questions.","native":"La ingeniería genética puede curar enfermedades hereditarias terribles, aunque diseñar bebés plantea cuestiones éticas imposibles."},{"en":"If gene editing were available only to the rich, inequality would be written into biology.","native":"Si la edición genética estuviera disponible solo para los ricos, la desigualdad quedaría escrita en la biología."},{"en":"Crops are modified to resist drought, but their long-term effects are still debated fiercely.","native":"Los cultivos se modifican para resistir la sequía, pero sus efectos a largo plazo aún se debaten con intensidad."}]},"zh":{"word":"基因工程","question":"基因工程应该用于改变人类胚胎，还是只用于治疗疾病？","examples":[{"en":"Genetic engineering can cure terrible inherited diseases, although designing babies raises impossible ethical questions.","native":"基因工程可以治愈可怕的遗传疾病，尽管设计婴儿会引发无法解答的伦理问题。"},{"en":"If gene editing were available only to the rich, inequality would be written into biology.","native":"如果基因编辑只向富人开放，不平等将被写进生物学。"},{"en":"Crops are modified to resist drought, but their long-term effects are still debated fiercely.","native":"农作物被改造以抵抗干旱，但其长期影响仍在激烈争论中。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'medicine', 'Should healthcare be free for everyone, even if that means higher taxes?', '{"te":{"word":"వైద్యం","question":"పన్నులు ఎక్కువ అయినా సరే, అందరికీ వైద్యం ఉచితం కావాలా?","examples":[{"en":"Free healthcare saves lives quietly every day, although waiting lists can become painfully long.","native":"ఉచిత వైద్యం ప్రతిరోజూ నిశ్శబ్దంగా ప్రాణాలను కాపాడుతుంది, అయితే నిరీక్షణ జాబితాలు బాధాకరంగా పొడవుగా మారవచ్చు."},{"en":"If medicines were priced fairly, far fewer families would be ruined by a single illness.","native":"మందులు న్యాయంగా ధర వేయబడితే, ఒక్క అనారోగ్యంతో చాలా తక్కువ మంది కుటుంబాలు నాశనం అవుతాయి."},{"en":"Prevention is cheaper than treatment, yet most health budgets are spent after people fall ill.","native":"చికిత్స కంటే నివారణ చవకైనది, అయితే చాలామంది ఆరోగ్య బడ్జెట్లు ప్రజలు జబ్బుపడిన తర్వాత ఖర్చవుతాయి."}]},"hi":{"word":"चिकित्सा","question":"क्या सबके लिए स्वास्थ्य सेवा मुफ़्त होनी चाहिए, भले ही इसका मतलब ज़्यादा टैक्स हो?","examples":[{"en":"Free healthcare saves lives quietly every day, although waiting lists can become painfully long.","native":"मुफ़्त स्वास्थ्य सेवा हर दिन चुपचाप जानें बचाती है, हालाँकि प्रतीक्षा सूचियाँ दर्दनाक रूप से लंबी हो सकती हैं।"},{"en":"If medicines were priced fairly, far fewer families would be ruined by a single illness.","native":"अगर दवाओं की कीमत उचित हो, तो एक बीमारी से काफ़ी कम परिवार बर्बाद होंगे।"},{"en":"Prevention is cheaper than treatment, yet most health budgets are spent after people fall ill.","native":"इलाज से बचाव सस्ता है, फिर भी ज़्यादातर स्वास्थ्य बजट लोगों के बीमार पड़ने के बाद ख़र्च होते हैं।"}]},"es":{"word":"medicina","question":"¿Debería la sanidad ser gratuita para todos, aunque eso signifique impuestos más altos?","examples":[{"en":"Free healthcare saves lives quietly every day, although waiting lists can become painfully long.","native":"La sanidad gratuita salva vidas silenciosamente cada día, aunque las listas de espera pueden volverse dolorosamente largas."},{"en":"If medicines were priced fairly, far fewer families would be ruined by a single illness.","native":"Si los medicamentos tuvieran precios justos, muchas menos familias quedarían arruinadas por una sola enfermedad."},{"en":"Prevention is cheaper than treatment, yet most health budgets are spent after people fall ill.","native":"La prevención es más barata que el tratamiento, y sin embargo la mayoría de los presupuestos se gastan después de que la gente enferme."}]},"zh":{"word":"医疗","question":"即使意味着更高的税收，医疗也应该对所有人免费吗？","examples":[{"en":"Free healthcare saves lives quietly every day, although waiting lists can become painfully long.","native":"免费医疗每天都在悄然挽救生命，尽管候诊名单可能会变得漫长难熬。"},{"en":"If medicines were priced fairly, far fewer families would be ruined by a single illness.","native":"如果药品定价公平，因病致贫的家庭会少得多。"},{"en":"Prevention is cheaper than treatment, yet most health budgets are spent after people fall ill.","native":"预防比治疗更便宜，然而大部分医疗预算都花在人们生病之后。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'vaccination', 'Should vaccines be mandatory, or should individuals always have the right to refuse?', '{"te":{"word":"టీకాలు","question":"టీకాలు తప్పనిసరి కావాలా, లేక వ్యక్తులకు ఎల్లప్పుడూ తిరస్కరించే హక్కు ఉండాలా?","examples":[{"en":"Vaccines protect entire communities from disease, although some people still refuse them out of fear.","native":"టీకాలు మొత్తం సమాజాలను వ్యాధుల నుండి రక్షిస్తాయి, అయితే కొందరు భయంతో వాటిని ఇంకా తిరస్కరిస్తారు."},{"en":"If vaccination rates fall too low, old diseases return and the weakest suffer first.","native":"టీకా రేట్లు చాలా తగ్గితే, పాత వ్యాధులు తిరిగి వస్తాయి మరియు అత్యంత బలహీనులు మొదట బాధపడతారు."},{"en":"Mandatory programmes are often criticised as controlling, but public health depends on shared responsibility.","native":"తప్పనిసరి కార్యక్రమాలు తరచుగా నియంత్రణగా విమర్శించబడతాయి, కానీ ప్రజారోగ్యం భాగస్వామ్య బాధ్యతపై ఆధారపడుతుంది."}]},"hi":{"word":"टीकाकरण","question":"क्या टीके अनिवार्य होने चाहिए, या व्यक्तियों को हमेशा मना करने का अधिकार होना चाहिए?","examples":[{"en":"Vaccines protect entire communities from disease, although some people still refuse them out of fear.","native":"टीके पूरे समुदायों को बीमारियों से बचाते हैं, हालाँकि कुछ लोग डर से उन्हें अब भी मना कर देते हैं।"},{"en":"If vaccination rates fall too low, old diseases return and the weakest suffer first.","native":"अगर टीकाकरण दरें बहुत गिर जाएँ, तो पुरानी बीमारियाँ लौटती हैं और सबसे कमज़ोर पहले पीड़ित होते हैं।"},{"en":"Mandatory programmes are often criticised as controlling, but public health depends on shared responsibility.","native":"अनिवार्य कार्यक्रमों की अक्सर नियंत्रक होने की आलोचना होती है, लेकिन सार्वजनिक स्वास्थ्य साझा ज़िम्मेदारी पर टिका है।"}]},"es":{"word":"vacunación","question":"¿Deberían ser obligatorias las vacunas, o deberían las personas tener siempre derecho a rechazarlas?","examples":[{"en":"Vaccines protect entire communities from disease, although some people still refuse them out of fear.","native":"Las vacunas protegen a comunidades enteras de enfermedades, aunque algunas personas aún las rechazan por miedo."},{"en":"If vaccination rates fall too low, old diseases return and the weakest suffer first.","native":"Si las tasas de vacunación caen demasiado, las viejas enfermedades regresan y los más débiles sufren primero."},{"en":"Mandatory programmes are often criticised as controlling, but public health depends on shared responsibility.","native":"Los programas obligatorios son criticados a menudo por controladores, pero la salud pública depende de la responsabilidad compartida."}]},"zh":{"word":"疫苗接种","question":"疫苗应该强制接种吗，还是个人应始终有权拒绝？","examples":[{"en":"Vaccines protect entire communities from disease, although some people still refuse them out of fear.","native":"疫苗保护整个社区免受疾病侵害，尽管有些人仍因恐惧而拒绝接种。"},{"en":"If vaccination rates fall too low, old diseases return and the weakest suffer first.","native":"如果疫苗接种率降得太低，旧疾病会卷土重来，最脆弱的人会首先受苦。"},{"en":"Mandatory programmes are often criticised as controlling, but public health depends on shared responsibility.","native":"强制接种计划常被批评为控制欲太强，但公共卫生依赖于共同的责任。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'sleep', 'Why do modern societies value sleep so little, and what are the consequences?', '{"te":{"word":"నిద్ర","question":"ఆధునిక సమాజాలు నిద్రను ఎందుకు అంత తక్కువగా విలువైస్తాయి, మరియు దాని పరిణామాలు ఏమిటి?","examples":[{"en":"Sleep is often treated like wasted time, although nothing restores the brain as effectively.","native":"నిద్రను తరచుగా వృథా సమయంలా భావిస్తారు, అయితే మెదడును అంత ప్రభావవంతంగా పునరుద్ధరించేది ఏమీ లేదు."},{"en":"If schools started later in the morning, teenagers would learn more and feel less anxious.","native":"పాఠశాలలు ఉదయం ఆలస్యంగా ప్రారంభమైతే, టీనేజర్లు ఎక్కువ నేర్చుకుంటారు మరియు తక్కువ ఆందోళనగా ఉంటారు."},{"en":"Tired drivers cause thousands of accidents yearly, yet sleeplessness is still praised as ambition.","native":"అలసిన డ్రైవర్లు ప్రతి సంవత్సరం వేలాది ప్రమాదాలకు కారణమవుతారు, అయితే నిద్రలేమిని ఇంకా ధ్యేయంగా పొగుడుతారు."}]},"hi":{"word":"नींद","question":"आधुनिक समाज नींद को इतना कम महत्व क्यों देते हैं, और इसके परिणाम क्या हैं?","examples":[{"en":"Sleep is often treated like wasted time, although nothing restores the brain as effectively.","native":"नींद को अक्सर बर्बाद समय जैसा माना जाता है, हालाँकि दिमाग को उतनी असरदार ढंग से कुछ भी ताज़ा नहीं करता।"},{"en":"If schools started later in the morning, teenagers would learn more and feel less anxious.","native":"अगर स्कूल सुबह देर से शुरू हों, तो किशोर ज़्यादा सीखेंगे और कम चिंतित रहेंगे।"},{"en":"Tired drivers cause thousands of accidents yearly, yet sleeplessness is still praised as ambition.","native":"थके ड्राइवर हर साल हज़ारों दुर्घटनाओं का कारण बनते हैं, फिर भी नींद न लेने को महत्वाकांक्षा समझकर सराहा जाता है।"}]},"es":{"word":"sueño","question":"¿Por qué las sociedades modernas valoran tan poco el sueño, y cuáles son las consecuencias?","examples":[{"en":"Sleep is often treated like wasted time, although nothing restores the brain as effectively.","native":"El sueño se trata a menudo como tiempo perdido, aunque nada restaura el cerebro con tanta eficacia."},{"en":"If schools started later in the morning, teenagers would learn more and feel less anxious.","native":"Si las escuelas empezaran más tarde por la mañana, los adolescentes aprenderían más y se sentirían menos ansiosos."},{"en":"Tired drivers cause thousands of accidents yearly, yet sleeplessness is still praised as ambition.","native":"Los conductores cansados causan miles de accidentes al año, y sin embargo la falta de sueño aún se elogia como ambición."}]},"zh":{"word":"睡眠","question":"为什么现代社会如此轻视睡眠？后果是什么？","examples":[{"en":"Sleep is often treated like wasted time, although nothing restores the brain as effectively.","native":"睡眠常被视为浪费时间，尽管没有什么能像这样有效地恢复大脑。"},{"en":"If schools started later in the morning, teenagers would learn more and feel less anxious.","native":"如果学校早上晚点上课，青少年会学得更多，焦虑也会更少。"},{"en":"Tired drivers cause thousands of accidents yearly, yet sleeplessness is still praised as ambition.","native":"疲劳的司机每年造成数千起事故，然而缺少睡眠仍被当作上进心来赞美。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'exercise', 'Why do so many people avoid exercise even though they know it is good for them?', '{"te":{"word":"వ్యాయామం","question":"వ్యాయామం మంచిదని తెలిసినా చాలామంది ఎందుకు దాన్ని తప్పుకుంటారు?","examples":[{"en":"Exercise is well known to extend life, although gyms remain empty in every neighbourhood.","native":"వ్యాయామం ఆయుష్షును పొడగిస్తుందని బాగా తెలుసు, అయితే ప్రతి పరిసరంలోని జిమ్‌లు ఖాళీగానే ఉంటాయి."},{"en":"If movement were built into daily routines, willpower would no longer decide who stays healthy.","native":"రోజువారీ దినచర్యలో కదలికను కలిపితే, ఎవరు ఆరోగ్యంగా ఉంటారో ఇక సంకల్ప శక్తి నిర్ణయించదు."},{"en":"People often blame laziness, but exhaustion from long working hours is rarely taken seriously.","native":"ప్రజలు తరచుగా సోమరితనాన్ని నిందిస్తారు, కానీ పొడవైన పని గంటల వల్ల వచ్చే అలసటను అరుదుగా తీవ్రంగా తీసుకుంటారు."}]},"hi":{"word":"व्यायाम","question":"इतने लोग व्यायाम से क्यों बचते हैं, भले ही वे जानते हैं कि यह उनके लिए अच्छा है?","examples":[{"en":"Exercise is well known to extend life, although gyms remain empty in every neighbourhood.","native":"यह अच्छी तरह जाना जाता है कि व्यायाम उम्र बढ़ाता है, हालाँकि हर मोहल्ले के जिम खाली पड़े रहते हैं।"},{"en":"If movement were built into daily routines, willpower would no longer decide who stays healthy.","native":"अगर दिनचर्या में हलचल शामिल हो जाए, तो कौन स्वस्थ रहेगा यह इच्छाशक्ति तय नहीं करेगी।"},{"en":"People often blame laziness, but exhaustion from long working hours is rarely taken seriously.","native":"लोग अक्सर आलस्य को दोष देते हैं, लेकिन लंबे काम के घंटों की थकान को शायद ही गंभीरता से लिया जाता है।"}]},"es":{"word":"ejercicio","question":"¿Por qué tanta gente evita el ejercicio aun sabiendo que es bueno para ellos?","examples":[{"en":"Exercise is well known to extend life, although gyms remain empty in every neighbourhood.","native":"Es bien sabido que el ejercicio alarga la vida, aunque los gimnasios siguen vacíos en todos los barrios."},{"en":"If movement were built into daily routines, willpower would no longer decide who stays healthy.","native":"Si el movimiento se incorporara a las rutinas diarias, la fuerza de voluntad ya no decidiría quién se mantiene sano."},{"en":"People often blame laziness, but exhaustion from long working hours is rarely taken seriously.","native":"La gente suele culpar a la pereza, pero el agotamiento por las largas jornadas rara vez se toma en serio."}]},"zh":{"word":"锻炼","question":"为什么这么多人明知锻炼有益却仍然逃避锻炼？","examples":[{"en":"Exercise is well known to extend life, although gyms remain empty in every neighbourhood.","native":"众所周知锻炼能延长寿命，尽管每个街区的健身房都空空如也。"},{"en":"If movement were built into daily routines, willpower would no longer decide who stays healthy.","native":"如果把运动融入日常生活，谁能保持健康就不再由意志力决定。"},{"en":"People often blame laziness, but exhaustion from long working hours is rarely taken seriously.","native":"人们常常责怪懒惰，但长时间工作带来的疲惫很少被认真对待。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'diet', 'Are modern diets making us sick? Who is responsible for what people eat?', '{"te":{"word":"ఆహారపు అలవాట్లు","question":"ఆధునిక ఆహారపు అలవాట్లు మనల్ని జబ్బులవారిని చేస్తున్నాయా? ప్రజలు ఏమి తింటారో దానికి బాధ్యులు ఎవరు?","examples":[{"en":"Processed food is cheap and convenient, although its real cost appears in hospitals later.","native":"ప్రాసెస్ చేసిన ఆహారం చవకగా మరియు అనుకూలంగా ఉంటుంది, అయితే దాని నిజమైన ఖర్చు తర్వాత ఆసుపత్రుల్లో కనిపిస్తుంది."},{"en":"If sugar were taxed like tobacco, manufacturers would probably change their recipes quite quickly.","native":"చక్కెరపై పొగాకులా పన్ను విధిస్తే, తయారీదారులు బహుశా తమ రెసిపీలను చాలా త్వరగా మారుస్తారు."},{"en":"Healthy eating is taught in schools, but unhealthy snacks are sold right outside the gates.","native":"పాఠశాలల్లో ఆరోగ్యకరమైన ఆహారం గురించి నేర్పుతారు, కానీ అనారోగ్యకరమైన స్నాక్స్ గేట్ల వెంటనే అమ్మబడుతాయి."}]},"hi":{"word":"खान-पान","question":"क्या आधुनिक खान-पान हमें बीमार बना रहा है? लोग क्या खाते हैं, इसके लिए ज़िम्मेदार कौन है?","examples":[{"en":"Processed food is cheap and convenient, although its real cost appears in hospitals later.","native":"प्रोसेस्ड खाना सस्ता और सुविधाजनक है, हालाँकि उसकी असली कीमत बाद में अस्पतालों में दिखती है।"},{"en":"If sugar were taxed like tobacco, manufacturers would probably change their recipes quite quickly.","native":"अगर चीनी पर तंबाकू जैसा टैक्स लगे, तो निर्माता शायद अपनी रेसिपी काफ़ी जल्दी बदल देंगे।"},{"en":"Healthy eating is taught in schools, but unhealthy snacks are sold right outside the gates.","native":"स्कूलों में स्वस्थ खाना सिखाया जाता है, लेकिन अस्वास्थ्यकर स्नैक्स गेट के ठीक बाहर बेचे जाते हैं।"}]},"es":{"word":"dieta","question":"¿Nos están enfermando las dietas modernas? ¿Quién es responsable de lo que come la gente?","examples":[{"en":"Processed food is cheap and convenient, although its real cost appears in hospitals later.","native":"La comida procesada es barata y cómoda, aunque su coste real aparece después en los hospitales."},{"en":"If sugar were taxed like tobacco, manufacturers would probably change their recipes quite quickly.","native":"Si el azúcar se gravara como el tabaco, los fabricantes probablemente cambiarían sus recetas muy rápido."},{"en":"Healthy eating is taught in schools, but unhealthy snacks are sold right outside the gates.","native":"La alimentación saludable se enseña en las escuelas, pero los snacks poco sanos se venden justo a la salida."}]},"zh":{"word":"饮食","question":"现代饮食正在让我们生病吗？谁应该对人们吃什么负责？","examples":[{"en":"Processed food is cheap and convenient, although its real cost appears in hospitals later.","native":"加工食品便宜又方便，尽管它的真实代价日后会出现在医院里。"},{"en":"If sugar were taxed like tobacco, manufacturers would probably change their recipes quite quickly.","native":"如果像烟草一样对糖征税，制造商可能会很快改变配方。"},{"en":"Healthy eating is taught in schools, but unhealthy snacks are sold right outside the gates.","native":"学校里教健康饮食，但不健康的零食就在校门口外出售。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'writing', 'Is good writing still important in the age of texting and artificial intelligence tools?', '{"te":{"word":"రచన","question":"టెక్స్టింగ్ మరియు ఆర్టిఫిషియల్ ఇంటెలిజెన్స్ టూల్స్ యుగంలో మంచి రచన ఇంకా ముఖ్యమేనా?","examples":[{"en":"Clear writing still reflects clear thinking, although few jobs now require long formal reports.","native":"స్పష్టమైన రచన ఇంకా స్పష్టమైన ఆలోచనను ప్రతిబింబిస్తుంది, అయితే ఇప్పుడు తక్కువ ఉద్యోగాలే పొడవైన అధికారిక నివేదికలు కోరుతాయి."},{"en":"If machines wrote everything for us, we might slowly lose the ability to structure ideas.","native":"యంత్రాలు మన కోసం ప్రతిదీ వ్రాస్తే, ఆలోచనలను నిర్మించే సామర్థ్యాన్ని మనం నెమ్మదిగా కోల్పోవచ్చు."},{"en":"Text messages reward speed and brevity, but some important thoughts simply need more space.","native":"టెక్స్ట్ సందేశాలు వేగానికి మరియు సంక్షిప్తతకు బహూమతి ఇస్తాయి, కానీ కొన్ని ముఖ్యమైన ఆలోచనలకు కేవలం ఎక్కువ స్థలం కావాలి."}]},"hi":{"word":"लेखन","question":"टेक्स्टिंग और आर्टिफ़िशियल इंटेलिजेंस टूल के युग में क्या अच्छा लेखन अब भी महत्वपूर्ण है?","examples":[{"en":"Clear writing still reflects clear thinking, although few jobs now require long formal reports.","native":"स्पष्ट लेखन अब भी स्पष्ट सोच दर्शाता है, हालाँकि अब कम ही नौकरियों में लंबी औपचारिक रिपोर्ट चाहिए।"},{"en":"If machines wrote everything for us, we might slowly lose the ability to structure ideas.","native":"अगर मशीनें हमारे लिए सब कुछ लिखें, तो हम विचारों को व्यवस्थित करने की क्षमता धीरे-धीरे खो सकते हैं।"},{"en":"Text messages reward speed and brevity, but some important thoughts simply need more space.","native":"टेक्स्ट संदेश रफ़्तार और संक्षिप्तता को पुरस्कृत करते हैं, लेकिन कुछ महत्वपूर्ण विचारों को बस ज़्यादा जगह चाहिए।"}]},"es":{"word":"escritura","question":"¿Sigue siendo importante escribir bien en la era de los mensajes y las herramientas de inteligencia artificial?","examples":[{"en":"Clear writing still reflects clear thinking, although few jobs now require long formal reports.","native":"La escritura clara sigue reflejando un pensamiento claro, aunque pocos trabajos exigen ya informes formales largos."},{"en":"If machines wrote everything for us, we might slowly lose the ability to structure ideas.","native":"Si las máquinas lo escribieran todo por nosotros, podríamos perder lentamente la capacidad de estructurar ideas."},{"en":"Text messages reward speed and brevity, but some important thoughts simply need more space.","native":"Los mensajes de texto premian la rapidez y la brevedad, pero algunos pensamientos importantes simplemente necesitan más espacio."}]},"zh":{"word":"写作","question":"在发短信和人工智能工具的时代，良好的写作能力还重要吗？","examples":[{"en":"Clear writing still reflects clear thinking, although few jobs now require long formal reports.","native":"清晰的写作仍然反映清晰的思维，尽管现在很少有工作需要冗长的正式报告。"},{"en":"If machines wrote everything for us, we might slowly lose the ability to structure ideas.","native":"如果机器替我们写所有东西，我们可能会慢慢失去组织思想的能力。"},{"en":"Text messages reward speed and brevity, but some important thoughts simply need more space.","native":"短信奖励速度和简洁，但有些重要的思想就是需要更多空间。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'art', 'Should governments fund the arts when public money is limited?', '{"te":{"word":"కళ","question":"ప్రజా డబ్బు పరిమితంగా ఉన్నప్పుడు ప్రభుత్వాలు కళలకు నిధులివ్వాలా?","examples":[{"en":"Art is dismissed as a luxury, although it shapes how entire generations understand themselves.","native":"కళను విలాసంగా కొట్టిపడేస్తారు, అయితే తరాలు తమను ఎలా అర్థం చేసుకుంటాయో అది రూపొందిస్తుంది."},{"en":"If funding depended only on ticket sales, experimental artists would vanish from public view.","native":"నిధులు టిక్కెట్ అమ్మకాలపై మాత్రమే ఆధారపడితే, ప్రయోగాత్మక కళాకారులు ప్రజా దృష్టి నుండి అదృశ్యమవుతారు."},{"en":"Museums are visited by millions, but the artists inside them often died in poverty.","native":"మ్యూజియంలను లక్షలాది మంది సందర్శిస్తారు, కానీ వాటిలోని కళాకారులు తరచుగా పేదరికంలో మరణించారు."}]},"hi":{"word":"कला","question":"जब सार्वजनिक धन सीमित हो, तो क्या सरकारों को कला को फंड करना चाहिए?","examples":[{"en":"Art is dismissed as a luxury, although it shapes how entire generations understand themselves.","native":"कला को विलासिता समझकर खारिज कर दिया जाता है, हालाँकि यह तय करती है कि पूरी पीढ़ियाँ खुद को कैसे समझती हैं।"},{"en":"If funding depended only on ticket sales, experimental artists would vanish from public view.","native":"अगर फंडिंग सिर्फ़ टिकट बिक्री पर निर्भर हो, तो प्रयोगधर्मी कलाकार जनता की नज़र से गायब हो जाएँगे।"},{"en":"Museums are visited by millions, but the artists inside them often died in poverty.","native":"संग्रहालयों में लाखों लोग जाते हैं, लेकिन उनमें मौजूद कलाकार अक्सर ग़रीबी में मर गए।"}]},"es":{"word":"arte","question":"¿Deberían los gobiernos financiar las artes cuando el dinero público es limitado?","examples":[{"en":"Art is dismissed as a luxury, although it shapes how entire generations understand themselves.","native":"El arte se descarta como un lujo, aunque da forma a cómo generaciones enteras se entienden a sí mismas."},{"en":"If funding depended only on ticket sales, experimental artists would vanish from public view.","native":"Si la financiación dependiera solo de la venta de entradas, los artistas experimentales desaparecerían de la vista pública."},{"en":"Museums are visited by millions, but the artists inside them often died in poverty.","native":"Los museos son visitados por millones, pero los artistas que exhiben a menudo murieron en la pobreza."}]},"zh":{"word":"艺术","question":"在公共资金有限的情况下，政府应该资助艺术吗？","examples":[{"en":"Art is dismissed as a luxury, although it shapes how entire generations understand themselves.","native":"艺术被当作奢侈品而不予重视，尽管它塑造了一代又一代人如何理解自己。"},{"en":"If funding depended only on ticket sales, experimental artists would vanish from public view.","native":"如果资助只取决于票房收入，实验艺术家将从公众视野中消失。"},{"en":"Museums are visited by millions, but the artists inside them often died in poverty.","native":"博物馆有数百万人参观，但其中的艺术家常常死于贫困。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'gaming', 'Are video games a waste of time, or can they be genuinely beneficial?', '{"te":{"word":"గేమింగ్","question":"వీడియో గేమ్స్ సమయం వృథానా, లేక అవి నిజంగా ప్రయోజనకరం కావచ్చా?","examples":[{"en":"Games are blamed for violence, although research keeps failing to prove a simple link.","native":"హింసకు గేమ్స్‌ను నిందిస్తారు, అయితే సరళమైన సంబంధాన్ని రుజువు చేయడంలో పరిశోధన పదేపదే విఫలమవుతోంది."},{"en":"If they are played in moderation, strategy games can teach planning and patience quite effectively.","native":"అవి మితంగా ఆడబడితే, వ్యూహాత్మక గేమ్స్ ప్రణాళికను మరియు సహనాన్ని చాలా ప్రభావవంతంగా నేర్పగలవు."},{"en":"Real problems appear when gaming replaces sleep, friendships and responsibilities rather than boredom.","native":"గేమింగ్ విసుగు బదులు నిద్ర, స్నేహాలు మరియు బాధ్యతలను భర్తీ చేసినప్పుడు నిజమైన సమస్యలు తలెత్తుతాయి."}]},"hi":{"word":"गेमिंग","question":"क्या वीडियो गेम समय की बर्बादी हैं, या वे सच में फ़ायदेमंद हो सकते हैं?","examples":[{"en":"Games are blamed for violence, although research keeps failing to prove a simple link.","native":"हिंसा के लिए गेम्स को दोष दिया जाता है, हालाँकि शोध बार-बार सीधा संबंध साबित करने में असफल होता है।"},{"en":"If they are played in moderation, strategy games can teach planning and patience quite effectively.","native":"अगर संयम से खेले जाएँ, तो रणनीति वाले गेम योजना और धैर्य काफ़ी असरदार ढंग से सिखा सकते हैं।"},{"en":"Real problems appear when gaming replaces sleep, friendships and responsibilities rather than boredom.","native":"असली समस्याएँ तब आती हैं जब गेमिंग ऊब के बजाय नींद, दोस्ती और ज़िम्मेदारियों की जगह ले लेता है।"}]},"es":{"word":"videojuegos","question":"¿Son los videojuegos una pérdida de tiempo, o pueden ser realmente beneficiosos?","examples":[{"en":"Games are blamed for violence, although research keeps failing to prove a simple link.","native":"Se culpa a los videojuegos de la violencia, aunque la investigación sigue sin lograr demostrar un vínculo simple."},{"en":"If they are played in moderation, strategy games can teach planning and patience quite effectively.","native":"Si se juega con moderación, los juegos de estrategia pueden enseñar planificación y paciencia con bastante eficacia."},{"en":"Real problems appear when gaming replaces sleep, friendships and responsibilities rather than boredom.","native":"Los verdaderos problemas aparecen cuando jugar reemplaza el sueño, las amistades y las responsabilidades en lugar del aburrimiento."}]},"zh":{"word":"电子游戏","question":"电子游戏是浪费时间，还是确实可以带来益处？","examples":[{"en":"Games are blamed for violence, although research keeps failing to prove a simple link.","native":"人们把暴力归咎于电子游戏，尽管研究一直未能证明两者之间有简单的联系。"},{"en":"If they are played in moderation, strategy games can teach planning and patience quite effectively.","native":"如果适度游玩，策略游戏可以相当有效地培养规划和耐心。"},{"en":"Real problems appear when gaming replaces sleep, friendships and responsibilities rather than boredom.","native":"当游戏取代的不再是无聊，而是睡眠、友谊和责任时，真正的问题就出现了。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'smartphones', 'Have smartphones improved our lives, or have they made us more distracted and anxious?', '{"te":{"word":"స్మార్ట్‌ఫోన్లు","question":"స్మార్ట్‌ఫోన్లు మన జీవితాలను మెరుగుపరిచాయా, లేక మనల్ని మరింత పరధ్యానంగా మరియు ఆందోళనగా మార్చాయా?","examples":[{"en":"Smartphones connect us to almost everything these days, although constant notifications fragment our attention completely.","native":"స్మార్ట్‌ఫోన్లు ఈరోజుల్లో మనల్ని దాదాపు ప్రతిదానితో అనుసంధానిస్తాయి, అయితే నిరంతర నోటిఫికేషన్లు మన శ్రద్ధను పూర్తిగా చీల్చివేస్తాయి."},{"en":"If phones were banned at dinner tables, families might rediscover the art of conversation.","native":"భోజన టేబుళ్ల వద్ద ఫోన్లను నిషేధిస్తే, కుటుంబాలు సంభాషణ కళను తిరిగి కనుగొనవచ్చు."},{"en":"Greater productivity is promised by every new app, but hours disappear into scrolling instead.","native":"ప్రతి కొత్త యాప్ ఎక్కువ ఉత్పాదకతను హామీ ఇస్తుంది, కానీ గంటలు స్క్రోలింగ్‌లో కరిగిపోతాయి."}]},"hi":{"word":"स्मार्टफ़ोन","question":"क्या स्मार्टफ़ोन ने हमारी ज़िंदगी बेहतर बनाई है, या हमें ज़्यादा विचलित और चिंतित बना दिया है?","examples":[{"en":"Smartphones connect us to almost everything these days, although constant notifications fragment our attention completely.","native":"स्मार्टफ़ोन आजकल हमें लगभग हर चीज़ से जोड़ते हैं, हालाँकि लगातार नोटिफ़िकेशन हमारा ध्यान पूरी तरह बिखेर देते हैं।"},{"en":"If phones were banned at dinner tables, families might rediscover the art of conversation.","native":"अगर खाने की मेज़ पर फ़ोन बैन कर दिए जाएँ, तो परिवार बातचीत की कला फिर से खोज सकते हैं।"},{"en":"Greater productivity is promised by every new app, but hours disappear into scrolling instead.","native":"हर नया ऐप ज़्यादा उत्पादकता का वादा करता है, लेकिन घंटे स्क्रॉलिंग में गुम हो जाते हैं।"}]},"es":{"word":"teléfonos inteligentes","question":"¿Han mejorado los teléfonos inteligentes nuestras vidas, o nos han vuelto más distraídos y ansiosos?","examples":[{"en":"Smartphones connect us to almost everything these days, although constant notifications fragment our attention completely.","native":"Los teléfonos inteligentes nos conectan hoy con casi todo, aunque las notificaciones constantes fragmentan por completo nuestra atención."},{"en":"If phones were banned at dinner tables, families might rediscover the art of conversation.","native":"Si se prohibieran los teléfonos en la mesa, las familias podrían redescubrir el arte de la conversación."},{"en":"Greater productivity is promised by every new app, but hours disappear into scrolling instead.","native":"Cada aplicación nueva promete mayor productividad, pero las horas desaparecen desplazándose por la pantalla."}]},"zh":{"word":"智能手机","question":"智能手机改善了我们的生活，还是让我们变得更加分心和焦虑？","examples":[{"en":"Smartphones connect us to almost everything these days, although constant notifications fragment our attention completely.","native":"如今智能手机让我们与几乎所有事物相连，尽管持续的通知把我们的注意力彻底割裂了。"},{"en":"If phones were banned at dinner tables, families might rediscover the art of conversation.","native":"如果餐桌上禁止使用手机，家人或许能重新发现交谈的艺术。"},{"en":"Greater productivity is promised by every new app, but hours disappear into scrolling instead.","native":"每个新应用都承诺提高效率，但时间却消失在刷屏之中。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'automation', 'Will automation destroy more jobs than it creates? Who should be responsible for displaced workers?', '{"te":{"word":"ఆటోమేషన్","question":"ఆటోమేషన్ సృష్టించేదాని కంటే ఎక్కువ ఉద్యోగాలను నాశనం చేస్తుందా? ఉద్యోగాలు కోల్పోయిన కార్మికుల బాధ్యత ఎవరిది?","examples":[{"en":"Machines have replaced workers before, although new industries have usually appeared to absorb them.","native":"యంత్రాలు ఇంతకుముందు కార్మికులను భర్తీ చేశాయి, అయితే వారిని మింగేసుకునే కొత్త పరిశ్రమలు సాధారణంగా కనిపించాయి."},{"en":"If driving becomes fully automated, millions of professional drivers will suddenly need new careers.","native":"డ్రైవింగ్ పూర్తిగా ఆటోమేట్ అయితే, లక్షలాది మంది ప్రొఫెషనల్ డ్రైవర్లకు అకస్మాత్తుగా కొత్త వృత్తులు కావాలి."},{"en":"Productivity gains are celebrated by shareholders, but the benefits are rarely shared with those displaced.","native":"ఉత్పాదకత లాభాలను వాటాదారులు జరుపుకుంటారు, కానీ ఉద్యోగాలు కోల్పోయినవారితో ప్రయోజనాలు అరుదుగా పంచబడతాయి."}]},"hi":{"word":"स्वचालन","question":"क्या स्वचालन जितनी नौकरियाँ बनाएगा उससे ज़्यादा नष्ट करेगा? बेअसर हुए कर्मचारियों की ज़िम्मेदारी किसकी होनी चाहिए?","examples":[{"en":"Machines have replaced workers before, although new industries have usually appeared to absorb them.","native":"मशीनें पहले भी कामगारों की जगह ले चुकी हैं, हालाँकि नए उद्योग आमतौर पर उन्हें समाहित करने के लिए उभरे हैं।"},{"en":"If driving becomes fully automated, millions of professional drivers will suddenly need new careers.","native":"अगर ड्राइविंग पूरी तरह स्वचालित हो जाए, तो लाखों पेशेवर ड्राइवरों को अचानक नए करियर चाहिए होंगे।"},{"en":"Productivity gains are celebrated by shareholders, but the benefits are rarely shared with those displaced.","native":"उत्पादकता लाभ का जश्न शेयरधारक मनाते हैं, लेकिन विस्थापित लोगों के साथ फ़ायदा शायद ही बँटता है।"}]},"es":{"word":"automatización","question":"¿Destruirá la automatización más empleos de los que crea? ¿Quién debería hacerse cargo de los trabajadores desplazados?","examples":[{"en":"Machines have replaced workers before, although new industries have usually appeared to absorb them.","native":"Las máquinas han reemplazado trabajadores antes, aunque normalmente han aparecido industrias nuevas para absorberlos."},{"en":"If driving becomes fully automated, millions of professional drivers will suddenly need new careers.","native":"Si la conducción se automatiza por completo, millones de conductores profesionales necesitarán de repente nuevas carreras."},{"en":"Productivity gains are celebrated by shareholders, but the benefits are rarely shared with those displaced.","native":"Los accionistas celebran las ganancias de productividad, pero los beneficios rara vez se comparten con los desplazados."}]},"zh":{"word":"自动化","question":"自动化摧毁的工作岗位会比它创造的更多吗？谁应该为失业的工人负责？","examples":[{"en":"Machines have replaced workers before, although new industries have usually appeared to absorb them.","native":"机器以前就取代过工人，尽管通常会有新产业出现来吸纳他们。"},{"en":"If driving becomes fully automated, millions of professional drivers will suddenly need new careers.","native":"如果驾驶完全自动化，数百万职业司机将突然需要新的职业。"},{"en":"Productivity gains are celebrated by shareholders, but the benefits are rarely shared with those displaced.","native":"股东们庆祝生产率的提升，但收益很少与被取代的工人分享。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'e-commerce', 'Is online shopping destroying local shops, and does it matter if it is?', '{"te":{"word":"ఇ-కామర్స్","question":"ఆన్‌లైన్ షాపింగ్ స్థానిక దుకాణాలను నాశనం చేస్తోందా, మరియు అలా జరిగితే అది పట్టించుకోవలసిన విషయమేనా?","examples":[{"en":"Online shopping is faster and cheaper, although something important disappears with empty main streets.","native":"ఆన్‌లైన్ షాపింగ్ వేగంగా మరియు చవకగా ఉంటుంది, అయితే ఖాళీ అయిన ప్రధాన వీధులతో ఏదో ముఖ్యమైనది అదృశ్యమవుతుంది."},{"en":"If local shops vanished completely, elderly people without cars would be affected most severely.","native":"స్థానిక దుకాణాలు పూర్తిగా అదృశ్యమైతే, కార్లు లేని వృద్ధులు అత్యంత తీవ్రంగా ప్రభావితమవుతారు."},{"en":"Returns are made so easy that customers order five sizes and send four back.","native":"రిటర్న్లు చాలా సులభం చేయబడ్డాయి కాబట్టి కస్టమర్లు ఐదు సైజులు ఆర్డర్ చేసి నాలుగు తిరిగి పంపుతారు."}]},"hi":{"word":"ई-कॉमर्स","question":"क्या ऑनलाइन ख़रीदारी स्थानीय दुकानों को नष्ट कर रही है, और क्या यह मायने रखता है?","examples":[{"en":"Online shopping is faster and cheaper, although something important disappears with empty main streets.","native":"ऑनलाइन ख़रीदारी तेज़ और सस्ती है, हालाँकि खाली बाज़ारों के साथ कुछ महत्वपूर्ण गायब हो जाता है।"},{"en":"If local shops vanished completely, elderly people without cars would be affected most severely.","native":"अगर स्थानीय दुकानें पूरी तरह गायब हो जाएँ, तो बिना गाड़ी वाले बुज़ुर्ग सबसे ज़्यादा प्रभावित होंगे।"},{"en":"Returns are made so easy that customers order five sizes and send four back.","native":"रिटर्न इतना आसान बना दिया गया है कि ग्राहक पाँच साइज़ मँगाकर चार वापस भेज देते हैं।"}]},"es":{"word":"comercio electrónico","question":"¿Están las compras en línea destruyendo las tiendas locales, y importa que lo hagan?","examples":[{"en":"Online shopping is faster and cheaper, although something important disappears with empty main streets.","native":"Comprar en línea es más rápido y barato, aunque algo importante desaparece con las calles principales vacías."},{"en":"If local shops vanished completely, elderly people without cars would be affected most severely.","native":"Si las tiendas locales desaparecieran por completo, las personas mayores sin coche serían las más afectadas."},{"en":"Returns are made so easy that customers order five sizes and send four back.","native":"Las devoluciones son tan fáciles que los clientes piden cinco tallas y devuelven cuatro."}]},"zh":{"word":"电子商务","question":"网购正在摧毁本地商店吗？如果是，这重要吗？","examples":[{"en":"Online shopping is faster and cheaper, although something important disappears with empty main streets.","native":"网购更快更便宜，尽管随着主街变得空荡荡，一些重要的东西也在消失。"},{"en":"If local shops vanished completely, elderly people without cars would be affected most severely.","native":"如果本地商店完全消失，没有车的老人将受到最严重的影响。"},{"en":"Returns are made so easy that customers order five sizes and send four back.","native":"退货被弄得如此容易，以至于顾客订五个尺码再退回四个。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'banking', 'Do banks serve ordinary people fairly, or do they mainly protect their own interests?', '{"te":{"word":"బ్యాంకింగ్","question":"బ్యాంకులు సాధారణ ప్రజలకు న్యాయంగా సేవ చేస్తాయా, లేక అవి ప్రధానంగా తమ స్వార్థాలనే కాపాడుతాయా?","examples":[{"en":"Banks are trusted with our savings, although their mistakes are often paid for by taxpayers.","native":"మన పొదుపులతో బ్యాంకులను నమ్ముతాం, అయితే వాటి తప్పుల ఖర్చు తరచుగా పన్ను చెల్లించేవారు చెల్లిస్తారు."},{"en":"If banking fees were made fully transparent, millions of customers would switch providers immediately.","native":"బ్యాంకింగ్ రుసుములు పూర్తిగా పారదర్శకం చేయబడితే, లక్షలాది మంది కస్టమర్లు వెంటనే ప్రొవైడర్లను మారుస్తారు."},{"en":"Small businesses struggle to get loans, yet large bonuses continue to be paid at the top.","native":"చిన్న వ్యాపారాలు రుణాలు పొందడానికి ఇబ్బంది పడుతాయి, అయితే పైస్థాయిలో పెద్ద బోనస్లు ఇవ్వడం కొనసాగుతూనే ఉంటుంది."}]},"hi":{"word":"बैंकिंग","question":"क्या बैंक आम लोगों की निष्पक्ष सेवा करते हैं, या वे मुख्य रूप से अपने हितों की रक्षा करते हैं?","examples":[{"en":"Banks are trusted with our savings, although their mistakes are often paid for by taxpayers.","native":"हमारी बचत के साथ बैंकों पर भरोसा किया जाता है, हालाँकि उनकी गलतियों की कीमत अक्सर करदाता चुकाते हैं।"},{"en":"If banking fees were made fully transparent, millions of customers would switch providers immediately.","native":"अगर बैंकिंग शुल्क पूरी तरह पारदर्शी कर दिया जाए, तो लाखों ग्राहक तुरंत प्रदाता बदल लेंगे।"},{"en":"Small businesses struggle to get loans, yet large bonuses continue to be paid at the top.","native":"छोटे कारोबारों को कर्ज़ मिलने में संघर्ष करना पड़ता है, फिर भी ऊपर बड़े बोनस दिए जाते रहते हैं।"}]},"es":{"word":"banca","question":"¿Sirven los bancos con justicia a la gente corriente, o protegen principalmente sus propios intereses?","examples":[{"en":"Banks are trusted with our savings, although their mistakes are often paid for by taxpayers.","native":"Se confía a los bancos nuestros ahorros, aunque sus errores a menudo los pagan los contribuyentes."},{"en":"If banking fees were made fully transparent, millions of customers would switch providers immediately.","native":"Si las comisiones bancarias fueran totalmente transparentes, millones de clientes cambiarían de proveedor inmediatamente."},{"en":"Small businesses struggle to get loans, yet large bonuses continue to be paid at the top.","native":"Las pequeñas empresas luchan por conseguir préstamos, mientras en las cúpulas se siguen pagando grandes bonificaciones."}]},"zh":{"word":"银行业","question":"银行是否公平地为普通人服务，还是它们主要在维护自己的利益？","examples":[{"en":"Banks are trusted with our savings, although their mistakes are often paid for by taxpayers.","native":"我们把积蓄托付给银行，尽管它们的错误常常由纳税人买单。"},{"en":"If banking fees were made fully transparent, millions of customers would switch providers immediately.","native":"如果银行费用完全透明，数百万客户会立即更换银行。"},{"en":"Small businesses struggle to get loans, yet large bonuses continue to be paid at the top.","native":"小企业很难获得贷款，而高层却继续领取高额奖金。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'investment', 'Should ordinary people invest in the stock market, or is it too risky for most savers?', '{"te":{"word":"పెట్టుబడి","question":"సాధారణ ప్రజలు స్టాక్ మార్కెట్‌లో పెట్టుబడి పెట్టాలా, లేక చాలామంది పొదుపుదారులకు అది చాలా రిస్కీనా?","examples":[{"en":"Investing builds wealth slowly over decades, although panic selling destroys it in a week.","native":"పెట్టుబడి దశాబ్దాలుగా నెమ్మదిగా సంపదను నిర్మిస్తుంది, అయితే భయంతో అమ్మేయడం దాన్ని వారంలో నాశనం చేస్తుంది."},{"en":"If financial education were truly universal, far fewer people would fall for guaranteed-return scams.","native":"ఆర్థిక విద్య నిజంగా సార్వత్రికం అయితే, హామీ ఇచ్చిన రిటర్న్ మోసాలకు చాలా తక్కువ మంది బలవుతారు."},{"en":"Cash left in savings accounts loses value quietly, but markets can crash without warning.","native":"పొదుపు ఖాతాల్లో ఉంచిన నగదు నిశ్శబ్దంగా విలువ కోల్పోతుంది, కానీ మార్కెట్లు హెచ్చరిక లేకుండా కూలిపోవచ్చు."}]},"hi":{"word":"निवेश","question":"क्या आम लोगों को शेयर बाज़ार में निवेश करना चाहिए, या यह ज़्यादातर बचतकर्ताओं के लिए बहुत जोखिम भरा है?","examples":[{"en":"Investing builds wealth slowly over decades, although panic selling destroys it in a week.","native":"निवेश दशकों में धीरे-धीरे दौलत बनाता है, हालाँकि घबराहट में बेचने से वह एक हफ़्ते में नष्ट हो जाती है।"},{"en":"If financial education were truly universal, far fewer people would fall for guaranteed-return scams.","native":"अगर वित्तीय शिक्षा सच में सार्वभौमिक हो, तो गारंटीड रिटर्न वाले घोटालों में काफ़ी कम लोग फँसेंगे।"},{"en":"Cash left in savings accounts loses value quietly, but markets can crash without warning.","native":"बचत खातों में रखा नकद चुपचाप मूल्य खोता है, लेकिन बाज़ार बिना चेतावनी के गिर भी सकते हैं।"}]},"es":{"word":"inversión","question":"¿Debería la gente corriente invertir en bolsa, o es demasiado arriesgado para la mayoría de los ahorradores?","examples":[{"en":"Investing builds wealth slowly over decades, although panic selling destroys it in a week.","native":"Invertir construye riqueza lentamente durante décadas, aunque vender presa del pánico la destruye en una semana."},{"en":"If financial education were truly universal, far fewer people would fall for guaranteed-return scams.","native":"Si la educación financiera fuera verdaderamente universal, mucha menos gente caería en estafas de rentabilidad garantizada."},{"en":"Cash left in savings accounts loses value quietly, but markets can crash without warning.","native":"El efectivo guardado en cuentas de ahorro pierde valor silenciosamente, pero los mercados pueden desplomarse sin aviso."}]},"zh":{"word":"投资","question":"普通人应该投资股市吗，还是对大多数储户来说风险太大？","examples":[{"en":"Investing builds wealth slowly over decades, although panic selling destroys it in a week.","native":"投资能在几十年间慢慢积累财富，尽管恐慌性抛售能在一周内将其毁掉。"},{"en":"If financial education were truly universal, far fewer people would fall for guaranteed-return scams.","native":"如果金融教育真正普及，落入保证回报骗局的人会少得多。"},{"en":"Cash left in savings accounts loses value quietly, but markets can crash without warning.","native":"存在储蓄账户里的现金悄悄贬值，但市场也可能毫无预警地崩盘。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'debt', 'Is borrowing money a normal part of modern life, or should debt be avoided at all costs?', '{"te":{"word":"అప్పు","question":"డబ్బు అప్పు చేయడం ఆధునిక జీవితంలో సాధారణ భాగమేనా, లేక అప్పును ఏ ధరైనా తప్పించుకోవాలా?","examples":[{"en":"Debt allows families to buy homes, although it quietly transfers future freedom to lenders.","native":"అప్పు కుటుంబాలు ఇళ్లు కొనడానికి అనుమతిస్తుంది, అయితే అది నిశ్శబ్దంగా భవిష్యత్ స్వేచ్ఛను రుణదాతలకు బదిలీ చేస్తుంది."},{"en":"If credit cards explained their true costs clearly, fewer young people would fall into debt.","native":"క్రెడిట్ కార్డులు తమ నిజమైన ఖర్చులను స్పష్టంగా వివరిస్తే, తక్కువ మంది యువకులు అప్పులో పడతారు."},{"en":"Student loans are often described as investments, but repayments can follow graduates for decades.","native":"విద్యార్థి రుణాలను తరచుగా పెట్టుబడులుగా వర్ణిస్తారు, కానీ వాటి తిరిగి చెల్లింపులు గ్రాడ్యుయేట్లను దశాబ్దాలపాటు వెంబడించవచ్చు."}]},"hi":{"word":"कर्ज़","question":"क्या पैसा उधार लेना आधुनिक जीवन का सामान्य हिस्सा है, या कर्ज़ से हर कीमत पर बचना चाहिए?","examples":[{"en":"Debt allows families to buy homes, although it quietly transfers future freedom to lenders.","native":"कर्ज़ परिवारों को घर ख़रीदने देता है, हालाँकि यह चुपचाप भविष्य की आज़ादी ऋणदाताओं को सौंप देता है।"},{"en":"If credit cards explained their true costs clearly, fewer young people would fall into debt.","native":"अगर क्रेडिट कार्ड अपनी असली लागत साफ़ बताएँ, तो कम युवा कर्ज़ में फँसेंगे।"},{"en":"Student loans are often described as investments, but repayments can follow graduates for decades.","native":"छात्र ऋण को अक्सर निवेश बताया जाता है, लेकिन उसकी किश्तें स्नातकों का दशकों तक पीछा कर सकती हैं।"}]},"es":{"word":"deuda","question":"¿Es endeudarse una parte normal de la vida moderna, o debería evitarse la deuda a toda costa?","examples":[{"en":"Debt allows families to buy homes, although it quietly transfers future freedom to lenders.","native":"La deuda permite a las familias comprar viviendas, aunque transfiere silenciosamente libertad futura a los prestamistas."},{"en":"If credit cards explained their true costs clearly, fewer young people would fall into debt.","native":"Si las tarjetas de crédito explicaran claramente sus costes reales, menos jóvenes caerían en deudas."},{"en":"Student loans are often described as investments, but repayments can follow graduates for decades.","native":"Los préstamos estudiantiles se describen a menudo como inversiones, pero los pagos pueden perseguir a los graduados durante décadas."}]},"zh":{"word":"债务","question":"借钱是现代生活的常态，还是应该不惜一切代价避免负债？","examples":[{"en":"Debt allows families to buy homes, although it quietly transfers future freedom to lenders.","native":"债务让家庭能够买房，尽管它悄悄地把未来的自由转移给了放贷人。"},{"en":"If credit cards explained their true costs clearly, fewer young people would fall into debt.","native":"如果信用卡清楚地说明真实成本，陷入债务的年轻人会减少。"},{"en":"Student loans are often described as investments, but repayments can follow graduates for decades.","native":"学生贷款常被描述为投资，但还款可能伴随毕业生数十年。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'digital literacy', 'Which digital skills are essential in modern life, and how should schools help people develop them?', '{"te":{"word":"డిజిటల్ అక్షరాస్యత","question":"ఆధునిక జీవితంలో ఏ డిజిటల్ నైపుణ్యాలు అవసరం, వాటిని అభివృద్ధి చేసుకోవడంలో పాఠశాలలు ప్రజలకు ఎలా సహాయపడాలి?","examples":[{"en":"Digital literacy involves judging online information, not merely knowing how to operate a device.","native":"డిజిటల్ అక్షరాస్యత అంటే కేవలం పరికరాన్ని ఎలా ఉపయోగించాలో తెలుసుకోవడం కాకుండా, ఆన్‌లైన్ సమాచారాన్ని అంచనా వేయడం కూడా."},{"en":"Schools should teach students how algorithms influence the content they see.","native":"అల్గోరిథమ్‌లు విద్యార్థులు చూసే కంటెంట్‌ను ఎలా ప్రభావితం చేస్తాయో పాఠశాలలు వారికి బోధించాలి."},{"en":"Without practical guidance, even confident users can expose themselves to fraud.","native":"ఆచరణాత్మక మార్గదర్శకత్వం లేకపోతే, ఆత్మవిశ్వాసం ఉన్న వినియోగదారులు కూడా మోసానికి గురయ్యే ప్రమాదంలో పడవచ్చు."}]},"hi":{"word":"डिजिटल साक्षरता","question":"आधुनिक जीवन में कौन-से डिजिटल कौशल आवश्यक हैं, और उन्हें विकसित करने में स्कूलों को लोगों की कैसे मदद करनी चाहिए?","examples":[{"en":"Digital literacy involves judging online information, not merely knowing how to operate a device.","native":"डिजिटल साक्षरता में ऑनलाइन जानकारी का आकलन करना शामिल है, केवल किसी उपकरण को चलाना जानना नहीं।"},{"en":"Schools should teach students how algorithms influence the content they see.","native":"स्कूलों को छात्रों को सिखाना चाहिए कि एल्गोरिदम उनके सामने आने वाली सामग्री को कैसे प्रभावित करते हैं।"},{"en":"Without practical guidance, even confident users can expose themselves to fraud.","native":"व्यावहारिक मार्गदर्शन के बिना आत्मविश्वासी उपयोगकर्ता भी खुद को धोखाधड़ी के जोखिम में डाल सकते हैं।"}]},"es":{"word":"alfabetización digital","question":"¿Qué habilidades digitales son esenciales en la vida moderna y cómo deberían ayudar las escuelas a desarrollarlas?","examples":[{"en":"Digital literacy involves judging online information, not merely knowing how to operate a device.","native":"La alfabetización digital implica evaluar la información en línea, no solo saber utilizar un dispositivo."},{"en":"Schools should teach students how algorithms influence the content they see.","native":"Las escuelas deberían enseñar al alumnado cómo influyen los algoritmos en el contenido que ve."},{"en":"Without practical guidance, even confident users can expose themselves to fraud.","native":"Sin orientación práctica, incluso los usuarios seguros de sí mismos pueden exponerse al fraude."}]},"zh":{"word":"数字素养","question":"现代生活中哪些数字技能必不可少，学校应该如何帮助人们培养这些技能？","examples":[{"en":"Digital literacy involves judging online information, not merely knowing how to operate a device.","native":"数字素养包括判断网络信息，而不仅仅是会操作设备。"},{"en":"Schools should teach students how algorithms influence the content they see.","native":"学校应该教学生了解算法如何影响他们看到的内容。"},{"en":"Without practical guidance, even confident users can expose themselves to fraud.","native":"如果没有实际指导，即使自信的用户也可能使自己面临诈骗风险。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'cybersecurity', 'How should individuals, businesses, and governments share responsibility for cybersecurity?', '{"te":{"word":"సైబర్ భద్రత","question":"సైబర్ భద్రత బాధ్యతను వ్యక్తులు, వ్యాపార సంస్థలు మరియు ప్రభుత్వాలు ఎలా పంచుకోవాలి?","examples":[{"en":"Strong passwords matter, but organizations must also design systems that remain secure when people make mistakes.","native":"బలమైన పాస్‌వర్డ్‌లు ముఖ్యమే, కానీ ప్రజలు తప్పులు చేసినప్పుడు కూడా సురక్షితంగా ఉండే వ్యవస్థలను సంస్థలు రూపొందించాలి."},{"en":"Companies should report serious data breaches promptly instead of protecting their reputation.","native":"కంపెనీలు తమ ప్రతిష్ఠను కాపాడుకోవడానికి ప్రయత్నించకుండా, తీవ్రమైన డేటా ఉల్లంఘనలను వెంటనే నివేదించాలి."},{"en":"If governments impose sensible standards, essential services will be harder for criminals to disrupt.","native":"ప్రభుత్వాలు సమంజసమైన ప్రమాణాలను విధిస్తే, నేరస్థులు అత్యవసర సేవలకు అంతరాయం కలిగించడం మరింత కష్టమవుతుంది."}]},"hi":{"word":"साइबर सुरक्षा","question":"व्यक्तियों, व्यवसायों और सरकारों को साइबर सुरक्षा की ज़िम्मेदारी किस तरह साझा करनी चाहिए?","examples":[{"en":"Strong passwords matter, but organizations must also design systems that remain secure when people make mistakes.","native":"मज़बूत पासवर्ड महत्वपूर्ण हैं, लेकिन संगठनों को ऐसे सिस्टम भी बनाने चाहिए जो लोगों से गलती होने पर भी सुरक्षित रहें।"},{"en":"Companies should report serious data breaches promptly instead of protecting their reputation.","native":"कंपनियों को अपनी प्रतिष्ठा बचाने के बजाय गंभीर डेटा उल्लंघनों की तुरंत सूचना देनी चाहिए।"},{"en":"If governments impose sensible standards, essential services will be harder for criminals to disrupt.","native":"अगर सरकारें समझदारी भरे मानक लागू करें, तो अपराधियों के लिए आवश्यक सेवाओं को बाधित करना कठिन होगा।"}]},"es":{"word":"ciberseguridad","question":"¿Cómo deberían repartirse la responsabilidad de la ciberseguridad las personas, las empresas y los gobiernos?","examples":[{"en":"Strong passwords matter, but organizations must also design systems that remain secure when people make mistakes.","native":"Las contraseñas seguras importan, pero las organizaciones también deben diseñar sistemas que sigan siendo seguros cuando la gente se equivoca."},{"en":"Companies should report serious data breaches promptly instead of protecting their reputation.","native":"Las empresas deberían informar rápidamente de las filtraciones graves de datos en vez de proteger su reputación."},{"en":"If governments impose sensible standards, essential services will be harder for criminals to disrupt.","native":"Si los gobiernos imponen normas sensatas, será más difícil que los delincuentes interrumpan los servicios esenciales."}]},"zh":{"word":"网络安全","question":"个人、企业和政府应该如何共同承担网络安全责任？","examples":[{"en":"Strong passwords matter, but organizations must also design systems that remain secure when people make mistakes.","native":"高强度密码很重要，但组织也必须设计出在人们犯错时仍能保持安全的系统。"},{"en":"Companies should report serious data breaches promptly instead of protecting their reputation.","native":"公司应该及时报告严重的数据泄露，而不是只顾维护自己的声誉。"},{"en":"If governments impose sensible standards, essential services will be harder for criminals to disrupt.","native":"如果政府制定合理的标准，犯罪分子就更难破坏基本服务。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'misinformation', 'Why does misinformation spread so quickly, and what should individuals and online platforms do about it?', '{"te":{"word":"తప్పుడు సమాచారం","question":"తప్పుడు సమాచారం ఎందుకు అంత వేగంగా వ్యాపిస్తుంది, దాని గురించి వ్యక్తులు మరియు ఆన్‌లైన్ వేదికలు ఏమి చేయాలి?","examples":[{"en":"False claims often spread because they provoke a stronger emotional reaction than careful reporting.","native":"జాగ్రత్తగా చేసిన వార్తా నివేదికల కంటే తప్పుడు వాదనలు బలమైన భావోద్వేగ స్పందనను కలిగిస్తాయి కాబట్టి అవి తరచుగా వ్యాపిస్తాయి."},{"en":"Before sharing a dramatic story, people should check its source, date, and supporting evidence.","native":"సంచలనాత్మక కథనాన్ని పంచుకునే ముందు, ప్రజలు దాని మూలం, తేదీ మరియు దానికి మద్దతు ఇచ్చే ఆధారాలను తనిఖీ చేయాలి."},{"en":"Platforms could reduce harm without censoring debate by adding context from independent experts.","native":"స్వతంత్ర నిపుణుల సందర్భ వివరణను జోడించడం ద్వారా వేదికలు చర్చను సెన్సార్ చేయకుండానే హానిని తగ్గించగలవు."}]},"hi":{"word":"भ्रामक जानकारी","question":"भ्रामक जानकारी इतनी तेज़ी से क्यों फैलती है, और व्यक्तियों तथा ऑनलाइन मंचों को इसके बारे में क्या करना चाहिए?","examples":[{"en":"False claims often spread because they provoke a stronger emotional reaction than careful reporting.","native":"झूठे दावे अक्सर इसलिए फैलते हैं क्योंकि वे सावधानी से की गई रिपोर्टिंग की तुलना में अधिक तीखी भावनात्मक प्रतिक्रिया पैदा करते हैं।"},{"en":"Before sharing a dramatic story, people should check its source, date, and supporting evidence.","native":"किसी सनसनीखेज़ खबर को साझा करने से पहले लोगों को उसके स्रोत, तारीख और सहायक प्रमाण की जाँच करनी चाहिए।"},{"en":"Platforms could reduce harm without censoring debate by adding context from independent experts.","native":"मंच स्वतंत्र विशेषज्ञों का संदर्भ जोड़कर बहस को सेंसर किए बिना नुकसान कम कर सकते हैं।"}]},"es":{"word":"desinformación","question":"¿Por qué se difunde tan rápido la desinformación y qué deberían hacer al respecto las personas y las plataformas digitales?","examples":[{"en":"False claims often spread because they provoke a stronger emotional reaction than careful reporting.","native":"Las afirmaciones falsas suelen difundirse porque provocan una reacción emocional más fuerte que la información rigurosa."},{"en":"Before sharing a dramatic story, people should check its source, date, and supporting evidence.","native":"Antes de compartir una historia impactante, la gente debería comprobar su fuente, fecha y pruebas de respaldo."},{"en":"Platforms could reduce harm without censoring debate by adding context from independent experts.","native":"Las plataformas podrían reducir el daño sin censurar el debate si añadieran contexto de expertos independientes."}]},"zh":{"word":"错误信息","question":"错误信息为何传播得如此迅速，个人和网络平台应该如何应对？","examples":[{"en":"False claims often spread because they provoke a stronger emotional reaction than careful reporting.","native":"虚假说法往往会传播开来，因为它们比严谨的报道更容易引发强烈的情绪反应。"},{"en":"Before sharing a dramatic story, people should check its source, date, and supporting evidence.","native":"在分享耸人听闻的消息之前，人们应该核查其来源、日期和佐证。"},{"en":"Platforms could reduce harm without censoring debate by adding context from independent experts.","native":"平台可以补充独立专家提供的背景信息，在不审查讨论的情况下减少危害。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'public health', 'When, if ever, should governments restrict individual choices to protect public health?', '{"te":{"word":"ప్రజారోగ్యం","question":"ప్రజారోగ్యాన్ని కాపాడటానికి ప్రభుత్వాలు వ్యక్తిగత ఎంపికలను ఎప్పుడు పరిమితం చేయాలి, లేదా అసలు పరిమితం చేయకూడదా?","examples":[{"en":"Public health measures are justified when one person''s decision creates a serious risk for others.","native":"ఒక వ్యక్తి నిర్ణయం ఇతరులకు తీవ్రమైన ప్రమాదాన్ని కలిగించినప్పుడు ప్రజారోగ్య చర్యలు సమర్థనీయమవుతాయి."},{"en":"However, restrictions should be based on evidence, limited in time, and explained transparently.","native":"అయితే, పరిమితులు ఆధారాలపై ఉండాలి, నిర్ణీత కాలానికే వర్తించాలి మరియు వాటిని పారదర్శకంగా వివరించాలి."},{"en":"Trust is more likely to grow when communities are involved in designing health campaigns.","native":"ఆరోగ్య ప్రచారాల రూపకల్పనలో సమాజాలను భాగస్వామ్యం చేసినప్పుడు నమ్మకం పెరిగే అవకాశం ఎక్కువగా ఉంటుంది."}]},"hi":{"word":"जन स्वास्थ्य","question":"सरकारों को जन स्वास्थ्य की रक्षा के लिए लोगों की व्यक्तिगत पसंद पर कब, अगर कभी, प्रतिबंध लगाना चाहिए?","examples":[{"en":"Public health measures are justified when one person''s decision creates a serious risk for others.","native":"जब एक व्यक्ति का निर्णय दूसरों के लिए गंभीर जोखिम पैदा करता है, तब जन स्वास्थ्य के उपाय उचित होते हैं।"},{"en":"However, restrictions should be based on evidence, limited in time, and explained transparently.","native":"हालाँकि, प्रतिबंध प्रमाण पर आधारित, सीमित अवधि के और पारदर्शी ढंग से समझाए गए होने चाहिए।"},{"en":"Trust is more likely to grow when communities are involved in designing health campaigns.","native":"जब स्वास्थ्य अभियानों को तैयार करने में समुदायों को शामिल किया जाता है, तो भरोसा बढ़ने की संभावना अधिक होती है।"}]},"es":{"word":"salud pública","question":"¿Cuándo, si acaso, deberían los gobiernos limitar las decisiones individuales para proteger la salud pública?","examples":[{"en":"Public health measures are justified when one person''s decision creates a serious risk for others.","native":"Las medidas de salud pública están justificadas cuando la decisión de una persona crea un riesgo grave para los demás."},{"en":"However, restrictions should be based on evidence, limited in time, and explained transparently.","native":"Sin embargo, las restricciones deberían basarse en pruebas, limitarse en el tiempo y explicarse con transparencia."},{"en":"Trust is more likely to grow when communities are involved in designing health campaigns.","native":"Es más probable que aumente la confianza cuando las comunidades participan en el diseño de las campañas sanitarias."}]},"zh":{"word":"公共卫生","question":"政府在什么情况下应该限制个人选择以保护公共卫生，还是根本不应该这样做？","examples":[{"en":"Public health measures are justified when one person''s decision creates a serious risk for others.","native":"当一个人的决定给他人带来严重风险时，公共卫生措施就是合理的。"},{"en":"However, restrictions should be based on evidence, limited in time, and explained transparently.","native":"不过，限制措施应以证据为依据、有明确期限，并得到透明的解释。"},{"en":"Trust is more likely to grow when communities are involved in designing health campaigns.","native":"让社区参与设计健康宣传活动，更有可能增进信任。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'mental health', 'How can workplaces and schools support mental health without invading people''s privacy?', '{"te":{"word":"మానసిక ఆరోగ్యం","question":"ప్రజల గోప్యతకు భంగం కలిగించకుండా కార్యాలయాలు మరియు పాఠశాలలు మానసిక ఆరోగ్యానికి ఎలా మద్దతు ఇవ్వగలవు?","examples":[{"en":"Institutions should make confidential counselling easy to access before a problem becomes a crisis.","native":"సమస్య సంక్షోభంగా మారకముందే గోప్యమైన కౌన్సెలింగ్ సులభంగా అందుబాటులో ఉండేలా సంస్థలు చూడాలి."},{"en":"Managers and teachers need training to notice warning signs without making assumptions.","native":"ఊహాగానాలు చేయకుండా హెచ్చరిక సంకేతాలను గుర్తించడానికి మేనేజర్లు మరియు ఉపాధ్యాయులకు శిక్షణ అవసరం."},{"en":"A supportive culture allows people to request reasonable adjustments without fearing discrimination.","native":"మద్దతు ఇచ్చే సంస్కృతి, వివక్షకు భయపడకుండా తగిన మార్పులను కోరడానికి ప్రజలకు అవకాశం ఇస్తుంది."}]},"hi":{"word":"मानसिक स्वास्थ्य","question":"कार्यस्थल और स्कूल लोगों की निजता में दखल दिए बिना मानसिक स्वास्थ्य का समर्थन कैसे कर सकते हैं?","examples":[{"en":"Institutions should make confidential counselling easy to access before a problem becomes a crisis.","native":"समस्या के संकट बनने से पहले संस्थानों को गोपनीय परामर्श आसानी से उपलब्ध कराना चाहिए।"},{"en":"Managers and teachers need training to notice warning signs without making assumptions.","native":"प्रबंधकों और शिक्षकों को बिना अनुमान लगाए चेतावनी के संकेत पहचानने का प्रशिक्षण चाहिए।"},{"en":"A supportive culture allows people to request reasonable adjustments without fearing discrimination.","native":"सहयोगी संस्कृति लोगों को भेदभाव के डर के बिना उचित बदलाव माँगने की सुविधा देती है।"}]},"es":{"word":"salud mental","question":"¿Cómo pueden los lugares de trabajo y las escuelas apoyar la salud mental sin invadir la privacidad de las personas?","examples":[{"en":"Institutions should make confidential counselling easy to access before a problem becomes a crisis.","native":"Las instituciones deberían facilitar el acceso a orientación confidencial antes de que un problema se convierta en una crisis."},{"en":"Managers and teachers need training to notice warning signs without making assumptions.","native":"Los responsables y docentes necesitan formación para detectar señales de alarma sin hacer suposiciones."},{"en":"A supportive culture allows people to request reasonable adjustments without fearing discrimination.","native":"Una cultura de apoyo permite pedir adaptaciones razonables sin temor a la discriminación."}]},"zh":{"word":"心理健康","question":"工作场所和学校如何在不侵犯个人隐私的前提下支持心理健康？","examples":[{"en":"Institutions should make confidential counselling easy to access before a problem becomes a crisis.","native":"机构应该让人们在问题演变成危机之前，能够方便地获得保密咨询。"},{"en":"Managers and teachers need training to notice warning signs without making assumptions.","native":"管理人员和教师需要接受培训，以便在不妄加猜测的情况下发现警示信号。"},{"en":"A supportive culture allows people to request reasonable adjustments without fearing discrimination.","native":"支持性的文化能让人们在不担心受到歧视的情况下提出合理的调整要求。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'housing', 'Why has affordable housing become difficult to find in many cities, and which solutions seem fairest?', '{"te":{"word":"గృహవసతి","question":"అనేక నగరాల్లో సరసమైన గృహవసతి దొరకడం ఎందుకు కష్టమైంది, ఏ పరిష్కారాలు అత్యంత న్యాయమైనవిగా అనిపిస్తున్నాయి?","examples":[{"en":"Demand has risen faster than construction, while many existing homes are treated primarily as investments.","native":"నిర్మాణం కంటే డిమాండ్ వేగంగా పెరిగింది, అదే సమయంలో ఇప్పటికే ఉన్న అనేక ఇళ్లను ప్రధానంగా పెట్టుబడులుగా చూస్తున్నారు."},{"en":"Cities could require new developments to include homes that ordinary workers can afford.","native":"సాధారణ ఉద్యోగులు కొనగలిగే ఇళ్లను కొత్త నిర్మాణ ప్రాజెక్టులు తప్పనిసరిగా కలిగి ఉండాలని నగరాలు నిబంధన పెట్టవచ్చు."},{"en":"Rent controls may protect current tenants, but poorly designed rules can discourage new housing.","native":"అద్దె నియంత్రణలు ప్రస్తుత అద్దెదారులను రక్షించవచ్చు, కానీ సరిగా రూపొందించని నియమాలు కొత్త గృహ నిర్మాణాన్ని నిరుత్సాహపరచవచ్చు."}]},"hi":{"word":"आवास","question":"कई शहरों में किफ़ायती आवास मिलना कठिन क्यों हो गया है, और कौन-से समाधान सबसे न्यायसंगत लगते हैं?","examples":[{"en":"Demand has risen faster than construction, while many existing homes are treated primarily as investments.","native":"निर्माण की तुलना में माँग तेज़ी से बढ़ी है, जबकि कई मौजूदा घरों को मुख्य रूप से निवेश माना जाता है।"},{"en":"Cities could require new developments to include homes that ordinary workers can afford.","native":"शहर नई परियोजनाओं में ऐसे घर शामिल करना अनिवार्य कर सकते हैं जिन्हें सामान्य कर्मचारी खरीद सकें।"},{"en":"Rent controls may protect current tenants, but poorly designed rules can discourage new housing.","native":"किराया नियंत्रण मौजूदा किरायेदारों की रक्षा कर सकता है, लेकिन खराब तरीके से बनाए गए नियम नए आवास निर्माण को हतोत्साहित कर सकते हैं।"}]},"es":{"word":"vivienda","question":"¿Por qué se ha vuelto difícil encontrar vivienda asequible en muchas ciudades y qué soluciones parecen más justas?","examples":[{"en":"Demand has risen faster than construction, while many existing homes are treated primarily as investments.","native":"La demanda ha aumentado más rápido que la construcción, mientras que muchas viviendas existentes se tratan principalmente como inversiones."},{"en":"Cities could require new developments to include homes that ordinary workers can afford.","native":"Las ciudades podrían exigir que las nuevas promociones incluyan viviendas que los trabajadores corrientes puedan pagar."},{"en":"Rent controls may protect current tenants, but poorly designed rules can discourage new housing.","native":"Los controles de alquiler pueden proteger a los inquilinos actuales, pero unas normas mal diseñadas pueden desalentar la construcción de vivienda."}]},"zh":{"word":"住房","question":"为什么许多城市越来越难找到可负担的住房，哪些解决办法最公平？","examples":[{"en":"Demand has risen faster than construction, while many existing homes are treated primarily as investments.","native":"需求增长快于住房建设，而许多现有房屋主要被当作投资品。"},{"en":"Cities could require new developments to include homes that ordinary workers can afford.","native":"城市可以要求新开发项目包含普通劳动者负担得起的住房。"},{"en":"Rent controls may protect current tenants, but poorly designed rules can discourage new housing.","native":"租金管制可能保护现有租户，但设计不当的规则会抑制新住房建设。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'tourism', 'How can popular destinations benefit from tourism without damaging local communities and the environment?', '{"te":{"word":"పర్యాటకం","question":"ప్రసిద్ధ పర్యాటక ప్రదేశాలు స్థానిక సమాజాలకు మరియు పర్యావరణానికి హాని కలిగించకుండా పర్యాటకం నుంచి ఎలా ప్రయోజనం పొందగలవు?","examples":[{"en":"Tourism creates jobs and funds cultural sites, yet overcrowding can make daily life difficult for residents.","native":"పర్యాటకం ఉద్యోగాలను సృష్టించి సాంస్కృతిక ప్రదేశాలకు నిధులు సమకూరుస్తుంది, అయినప్పటికీ అధిక రద్దీ స్థానికుల రోజువారీ జీవితాన్ని కష్టతరం చేయవచ్చు."},{"en":"Visitors should respect local customs and spend money with locally owned businesses.","native":"సందర్శకులు స్థానిక ఆచారాలను గౌరవించి, స్థానికుల యాజమాన్యంలోని వ్యాపారాల్లో ఖర్చు చేయాలి."},{"en":"Limiting access during peak seasons may protect fragile places without ending tourism completely.","native":"రద్దీ సీజన్లలో ప్రవేశాన్ని పరిమితం చేయడం పర్యాటకాన్ని పూర్తిగా నిలిపివేయకుండానే సున్నితమైన ప్రదేశాలను రక్షించవచ్చు."}]},"hi":{"word":"पर्यटन","question":"लोकप्रिय पर्यटन स्थल स्थानीय समुदायों और पर्यावरण को नुकसान पहुँचाए बिना पर्यटन से कैसे लाभ उठा सकते हैं?","examples":[{"en":"Tourism creates jobs and funds cultural sites, yet overcrowding can make daily life difficult for residents.","native":"पर्यटन रोज़गार पैदा करता है और सांस्कृतिक स्थलों के लिए धन जुटाता है, फिर भी अत्यधिक भीड़ निवासियों का दैनिक जीवन कठिन बना सकती है।"},{"en":"Visitors should respect local customs and spend money with locally owned businesses.","native":"आगंतुकों को स्थानीय रीति-रिवाजों का सम्मान करना चाहिए और स्थानीय स्वामित्व वाले व्यवसायों में पैसा खर्च करना चाहिए।"},{"en":"Limiting access during peak seasons may protect fragile places without ending tourism completely.","native":"व्यस्त मौसम में प्रवेश सीमित करने से पर्यटन को पूरी तरह बंद किए बिना नाज़ुक स्थानों की रक्षा हो सकती है।"}]},"es":{"word":"turismo","question":"¿Cómo pueden los destinos populares beneficiarse del turismo sin perjudicar a las comunidades locales ni al medio ambiente?","examples":[{"en":"Tourism creates jobs and funds cultural sites, yet overcrowding can make daily life difficult for residents.","native":"El turismo crea empleo y financia lugares culturales, pero la masificación puede dificultar la vida cotidiana de los residentes."},{"en":"Visitors should respect local customs and spend money with locally owned businesses.","native":"Los visitantes deberían respetar las costumbres locales y gastar en negocios de propiedad local."},{"en":"Limiting access during peak seasons may protect fragile places without ending tourism completely.","native":"Limitar el acceso durante la temporada alta puede proteger lugares frágiles sin acabar por completo con el turismo."}]},"zh":{"word":"旅游业","question":"热门目的地如何在不损害当地社区和环境的情况下从旅游业中受益？","examples":[{"en":"Tourism creates jobs and funds cultural sites, yet overcrowding can make daily life difficult for residents.","native":"旅游业创造就业并为文化场所提供资金，但过度拥挤会给居民的日常生活带来困难。"},{"en":"Visitors should respect local customs and spend money with locally owned businesses.","native":"游客应该尊重当地习俗，并在本地人经营的商家消费。"},{"en":"Limiting access during peak seasons may protect fragile places without ending tourism completely.","native":"在旺季限制游客数量，可以在不彻底停止旅游的情况下保护脆弱地区。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'globalization', 'Has globalization improved lives overall, or has it created more problems than benefits?', '{"te":{"word":"ప్రపంచీకరణ","question":"మొత్తంగా ప్రపంచీకరణ ప్రజల జీవితాలను మెరుగుపరిచిందా, లేక ప్రయోజనాల కంటే ఎక్కువ సమస్యలను సృష్టించిందా?","examples":[{"en":"Global trade has made many products cheaper, although some communities have lost stable industries.","native":"ప్రపంచ వాణిజ్యం అనేక ఉత్పత్తులను చౌకగా చేసింది, అయితే కొన్ని సమాజాలు స్థిరమైన పరిశ్రమలను కోల్పోయాయి."},{"en":"Cultural exchange can broaden people''s views without requiring every place to become identical.","native":"ప్రతి ప్రదేశం ఒకేలా మారాల్సిన అవసరం లేకుండానే సాంస్కృతిక పరస్పర మార్పిడి ప్రజల దృక్పథాలను విస్తరించగలదు."},{"en":"If multinational companies faced common labour and environmental standards, globalization would be fairer.","native":"బహుళజాతి కంపెనీలు ఉమ్మడి కార్మిక మరియు పర్యావరణ ప్రమాణాలను పాటించాల్సి వస్తే, ప్రపంచీకరణ మరింత న్యాయంగా ఉంటుంది."}]},"hi":{"word":"वैश्वीकरण","question":"क्या वैश्वीकरण ने कुल मिलाकर जीवन बेहतर बनाया है, या इसने लाभ से अधिक समस्याएँ पैदा की हैं?","examples":[{"en":"Global trade has made many products cheaper, although some communities have lost stable industries.","native":"वैश्विक व्यापार ने कई उत्पादों को सस्ता बनाया है, हालाँकि कुछ समुदायों ने स्थिर उद्योग खो दिए हैं।"},{"en":"Cultural exchange can broaden people''s views without requiring every place to become identical.","native":"सांस्कृतिक आदान-प्रदान हर जगह को एक जैसा बनाए बिना लोगों के दृष्टिकोण को व्यापक कर सकता है।"},{"en":"If multinational companies faced common labour and environmental standards, globalization would be fairer.","native":"अगर बहुराष्ट्रीय कंपनियों पर समान श्रम और पर्यावरण मानक लागू हों, तो वैश्वीकरण अधिक न्यायसंगत होगा।"}]},"es":{"word":"globalización","question":"¿Ha mejorado la globalización la vida en general o ha creado más problemas que beneficios?","examples":[{"en":"Global trade has made many products cheaper, although some communities have lost stable industries.","native":"El comercio mundial ha abaratado muchos productos, aunque algunas comunidades han perdido industrias estables."},{"en":"Cultural exchange can broaden people''s views without requiring every place to become identical.","native":"El intercambio cultural puede ampliar las perspectivas de la gente sin exigir que todos los lugares se vuelvan idénticos."},{"en":"If multinational companies faced common labour and environmental standards, globalization would be fairer.","native":"Si las empresas multinacionales se enfrentaran a normas laborales y ambientales comunes, la globalización sería más justa."}]},"zh":{"word":"全球化","question":"总体而言，全球化改善了生活，还是带来的问题多于好处？","examples":[{"en":"Global trade has made many products cheaper, although some communities have lost stable industries.","native":"全球贸易使许多产品更便宜，尽管一些社区因此失去了稳定的产业。"},{"en":"Cultural exchange can broaden people''s views without requiring every place to become identical.","native":"文化交流可以拓宽人们的视野，而不必让每个地方都变得千篇一律。"},{"en":"If multinational companies faced common labour and environmental standards, globalization would be fairer.","native":"如果跨国公司都须遵守共同的劳工和环境标准，全球化会更加公平。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'inequality', 'What are the main causes of economic inequality, and which policies could reduce it fairly?', '{"te":{"word":"అసమానత","question":"ఆర్థిక అసమానతకు ప్రధాన కారణాలు ఏమిటి, దాన్ని న్యాయంగా తగ్గించగల విధానాలు ఏవి?","examples":[{"en":"Inequality grows when wages remain flat while the value of property and investments rises.","native":"వేతనాలు స్థిరంగా ఉండగా ఆస్తి మరియు పెట్టుబడుల విలువ పెరిగినప్పుడు అసమానత పెరుగుతుంది."},{"en":"Quality education can improve opportunity, but it cannot replace fair pay and affordable services.","native":"నాణ్యమైన విద్య అవకాశాలను మెరుగుపరచగలదు, కానీ అది న్యాయమైన వేతనాలు మరియు అందుబాటు ధరల్లో సేవలకు ప్రత్యామ్నాయం కాదు."},{"en":"Progressive taxes are more acceptable when citizens can see how the revenue benefits society.","native":"పన్నుల ఆదాయం సమాజానికి ఎలా ప్రయోజనం చేకూరుస్తుందో పౌరులు చూడగలిగినప్పుడు ప్రగతిశీల పన్నులు మరింత ఆమోదయోగ్యంగా ఉంటాయి."}]},"hi":{"word":"असमानता","question":"आर्थिक असमानता के मुख्य कारण क्या हैं, और कौन-सी नीतियाँ इसे न्यायपूर्ण ढंग से कम कर सकती हैं?","examples":[{"en":"Inequality grows when wages remain flat while the value of property and investments rises.","native":"जब वेतन स्थिर रहता है और संपत्ति तथा निवेश का मूल्य बढ़ता है, तब असमानता बढ़ती है।"},{"en":"Quality education can improve opportunity, but it cannot replace fair pay and affordable services.","native":"गुणवत्तापूर्ण शिक्षा अवसर बढ़ा सकती है, लेकिन वह उचित वेतन और किफ़ायती सेवाओं की जगह नहीं ले सकती।"},{"en":"Progressive taxes are more acceptable when citizens can see how the revenue benefits society.","native":"जब नागरिक देख पाते हैं कि कर से मिलने वाला राजस्व समाज को कैसे लाभ पहुँचाता है, तब प्रगतिशील कर अधिक स्वीकार्य होते हैं।"}]},"es":{"word":"desigualdad","question":"¿Cuáles son las principales causas de la desigualdad económica y qué políticas podrían reducirla de manera justa?","examples":[{"en":"Inequality grows when wages remain flat while the value of property and investments rises.","native":"La desigualdad aumenta cuando los salarios se estancan mientras sube el valor de la propiedad y las inversiones."},{"en":"Quality education can improve opportunity, but it cannot replace fair pay and affordable services.","native":"La educación de calidad puede mejorar las oportunidades, pero no sustituye a un salario justo ni a servicios asequibles."},{"en":"Progressive taxes are more acceptable when citizens can see how the revenue benefits society.","native":"Los impuestos progresivos son más aceptables cuando la ciudadanía puede ver cómo benefician sus ingresos a la sociedad."}]},"zh":{"word":"不平等","question":"经济不平等的主要原因是什么，哪些政策能够公平地缩小差距？","examples":[{"en":"Inequality grows when wages remain flat while the value of property and investments rises.","native":"当工资停滞不前而房产和投资不断升值时，不平等就会加剧。"},{"en":"Quality education can improve opportunity, but it cannot replace fair pay and affordable services.","native":"优质教育可以增加机会，但不能取代公平的薪酬和负担得起的服务。"},{"en":"Progressive taxes are more acceptable when citizens can see how the revenue benefits society.","native":"当公民能看到税收如何惠及社会时，累进税制会更容易被接受。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'gender equality', 'What progress has been made toward gender equality, and which obstacles still need attention?', '{"te":{"word":"లింగ సమానత్వం","question":"లింగ సమానత్వం దిశగా ఎలాంటి పురోగతి సాధించబడింది, ఇంకా ఏ అడ్డంకులపై దృష్టి పెట్టాలి?","examples":[{"en":"Legal equality is important, but everyday expectations still influence education, careers, and family roles.","native":"చట్టపరమైన సమానత్వం ముఖ్యం, కానీ రోజువారీ అంచనాలు ఇప్పటికీ విద్య, వృత్తులు మరియు కుటుంబ పాత్రలను ప్రభావితం చేస్తున్నాయి."},{"en":"Employers should publish pay data so that unexplained differences can be identified and corrected.","native":"వివరణ లేని తేడాలను గుర్తించి సరిచేయడానికి యజమానులు వేతన వివరాలను ప్రచురించాలి."},{"en":"Lasting progress requires men as well as women to challenge unfair traditions.","native":"దీర్ఘకాలిక పురోగతికి మహిళలతో పాటు పురుషులు కూడా అన్యాయమైన సంప్రదాయాలను ప్రశ్నించాలి."}]},"hi":{"word":"लैंगिक समानता","question":"लैंगिक समानता की दिशा में क्या प्रगति हुई है, और किन बाधाओं पर अभी भी ध्यान देने की आवश्यकता है?","examples":[{"en":"Legal equality is important, but everyday expectations still influence education, careers, and family roles.","native":"कानूनी समानता महत्वपूर्ण है, लेकिन रोज़मर्रा की अपेक्षाएँ अभी भी शिक्षा, करियर और पारिवारिक भूमिकाओं को प्रभावित करती हैं।"},{"en":"Employers should publish pay data so that unexplained differences can be identified and corrected.","native":"नियोक्ताओं को वेतन के आँकड़े प्रकाशित करने चाहिए ताकि बिना स्पष्टीकरण वाले अंतर पहचाने और सुधारे जा सकें।"},{"en":"Lasting progress requires men as well as women to challenge unfair traditions.","native":"स्थायी प्रगति के लिए महिलाओं के साथ पुरुषों को भी अन्यायपूर्ण परंपराओं को चुनौती देनी होगी।"}]},"es":{"word":"igualdad de género","question":"¿Qué avances se han logrado hacia la igualdad de género y qué obstáculos todavía requieren atención?","examples":[{"en":"Legal equality is important, but everyday expectations still influence education, careers, and family roles.","native":"La igualdad jurídica es importante, pero las expectativas cotidianas todavía influyen en la educación, las carreras y los roles familiares."},{"en":"Employers should publish pay data so that unexplained differences can be identified and corrected.","native":"Los empleadores deberían publicar datos salariales para que las diferencias sin explicación puedan identificarse y corregirse."},{"en":"Lasting progress requires men as well as women to challenge unfair traditions.","native":"El progreso duradero exige que tanto los hombres como las mujeres cuestionen las tradiciones injustas."}]},"zh":{"word":"性别平等","question":"在实现性别平等方面已经取得了哪些进展，还有哪些障碍需要关注？","examples":[{"en":"Legal equality is important, but everyday expectations still influence education, careers, and family roles.","native":"法律上的平等很重要，但日常社会期待仍在影响教育、职业和家庭角色。"},{"en":"Employers should publish pay data so that unexplained differences can be identified and corrected.","native":"雇主应该公布薪酬数据，以便发现并纠正无法合理解释的差异。"},{"en":"Lasting progress requires men as well as women to challenge unfair traditions.","native":"持久的进步需要男性和女性共同挑战不公平的传统。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'workplace diversity', 'How can organizations gain the benefits of workplace diversity rather than simply hiring people from different backgrounds?', '{"te":{"word":"కార్యాలయ వైవిధ్యం","question":"కేవలం భిన్న నేపథ్యాల వారిని నియమించడమే కాకుండా కార్యాలయ వైవిధ్యం వల్ల కలిగే ప్రయోజనాలను సంస్థలు ఎలా సాధించగలవు?","examples":[{"en":"A diverse team can recognize needs and risks that a more uniform group might overlook.","native":"వైవిధ్యమైన బృందం, ఒకే తరహా సమూహం గమనించకుండా వదిలేసే అవసరాలు మరియు ప్రమాదాలను గుర్తించగలదు."},{"en":"Representation alone is insufficient if some employees are routinely ignored in meetings.","native":"సమావేశాల్లో కొంతమంది ఉద్యోగుల అభిప్రాయాలను తరచూ పట్టించుకోకపోతే, కేవలం ప్రాతినిధ్యం ఉండటం సరిపోదు."},{"en":"Managers should use clear promotion criteria and respond seriously when discrimination is reported.","native":"మేనేజర్లు పదోన్నతికి స్పష్టమైన ప్రమాణాలను ఉపయోగించి, వివక్ష గురించి ఫిర్యాదు చేసినప్పుడు దాన్ని తీవ్రంగా పరిగణించాలి."}]},"hi":{"word":"कार्यस्थल की विविधता","question":"संगठन केवल अलग-अलग पृष्ठभूमि के लोगों को नियुक्त करने के बजाय कार्यस्थल की विविधता के वास्तविक लाभ कैसे प्राप्त कर सकते हैं?","examples":[{"en":"A diverse team can recognize needs and risks that a more uniform group might overlook.","native":"एक विविध टीम उन ज़रूरतों और जोखिमों को पहचान सकती है जिन्हें एक जैसे लोगों का समूह अनदेखा कर सकता है।"},{"en":"Representation alone is insufficient if some employees are routinely ignored in meetings.","native":"अगर बैठकों में कुछ कर्मचारियों की नियमित रूप से अनदेखी होती है, तो केवल प्रतिनिधित्व पर्याप्त नहीं है।"},{"en":"Managers should use clear promotion criteria and respond seriously when discrimination is reported.","native":"प्रबंधकों को पदोन्नति के स्पष्ट मानदंड अपनाने चाहिए और भेदभाव की शिकायत मिलने पर गंभीरता से कार्रवाई करनी चाहिए।"}]},"es":{"word":"diversidad laboral","question":"¿Cómo pueden las organizaciones obtener los beneficios de la diversidad laboral en vez de limitarse a contratar a personas de distintos orígenes?","examples":[{"en":"A diverse team can recognize needs and risks that a more uniform group might overlook.","native":"Un equipo diverso puede reconocer necesidades y riesgos que un grupo más uniforme quizá pasaría por alto."},{"en":"Representation alone is insufficient if some employees are routinely ignored in meetings.","native":"La representación por sí sola no basta si se ignora habitualmente a algunos empleados en las reuniones."},{"en":"Managers should use clear promotion criteria and respond seriously when discrimination is reported.","native":"Los responsables deberían aplicar criterios claros de ascenso y responder con seriedad cuando se denuncia discriminación."}]},"zh":{"word":"职场多元化","question":"组织如何真正获得职场多元化的益处，而不只是招聘不同背景的人？","examples":[{"en":"A diverse team can recognize needs and risks that a more uniform group might overlook.","native":"多元化团队能够发现较为单一的群体可能忽略的需求和风险。"},{"en":"Representation alone is insufficient if some employees are routinely ignored in meetings.","native":"如果一些员工在会议中经常被忽视，只有人员构成上的代表性还远远不够。"},{"en":"Managers should use clear promotion criteria and respond seriously when discrimination is reported.","native":"管理者应该采用明确的晋升标准，并认真处理歧视投诉。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'lifelong learning', 'Why is lifelong learning increasingly important, and what makes it possible for busy adults?', '{"te":{"word":"జీవితాంత అభ్యాసం","question":"జీవితాంత అభ్యాసం ఎందుకు మరింత ముఖ్యమవుతోంది, బిజీగా ఉండే పెద్దలకు అది సాధ్యమయ్యేలా చేసేది ఏమిటి?","examples":[{"en":"Technology changes many jobs so quickly that one qualification may no longer last an entire career.","native":"సాంకేతికత అనేక ఉద్యోగాలను చాలా వేగంగా మారుస్తోంది కాబట్టి ఒక అర్హత మొత్తం వృత్తి జీవితానికి ఇక సరిపోకపోవచ్చు."},{"en":"Short, flexible courses help adults learn without giving up work or family responsibilities.","native":"చిన్నవిగా, అనువుగా ఉండే కోర్సులు పెద్దలు ఉద్యోగాన్ని లేదా కుటుంబ బాధ్యతలను వదులుకోకుండా నేర్చుకోవడానికి సహాయపడతాయి."},{"en":"Employers benefit when they give staff time and support to develop new skills.","native":"కొత్త నైపుణ్యాలు అభివృద్ధి చేసుకోవడానికి సిబ్బందికి సమయం మరియు మద్దతు ఇచ్చినప్పుడు యజమానులు కూడా ప్రయోజనం పొందుతారు."}]},"hi":{"word":"आजीवन सीखना","question":"आजीवन सीखना लगातार अधिक महत्वपूर्ण क्यों हो रहा है, और व्यस्त वयस्कों के लिए इसे क्या संभव बनाता है?","examples":[{"en":"Technology changes many jobs so quickly that one qualification may no longer last an entire career.","native":"तकनीक कई नौकरियों को इतनी तेज़ी से बदलती है कि एक योग्यता अब पूरे करियर के लिए पर्याप्त नहीं रह सकती।"},{"en":"Short, flexible courses help adults learn without giving up work or family responsibilities.","native":"छोटे और लचीले पाठ्यक्रम वयस्कों को काम या पारिवारिक ज़िम्मेदारियाँ छोड़े बिना सीखने में मदद करते हैं।"},{"en":"Employers benefit when they give staff time and support to develop new skills.","native":"जब नियोक्ता कर्मचारियों को नए कौशल विकसित करने के लिए समय और सहयोग देते हैं, तो उन्हें भी लाभ होता है।"}]},"es":{"word":"aprendizaje permanente","question":"¿Por qué es cada vez más importante el aprendizaje permanente y qué lo hace posible para los adultos ocupados?","examples":[{"en":"Technology changes many jobs so quickly that one qualification may no longer last an entire career.","native":"La tecnología transforma muchos empleos tan rápido que una sola titulación quizá ya no sirva para toda una carrera profesional."},{"en":"Short, flexible courses help adults learn without giving up work or family responsibilities.","native":"Los cursos breves y flexibles ayudan a los adultos a aprender sin abandonar el trabajo ni las responsabilidades familiares."},{"en":"Employers benefit when they give staff time and support to develop new skills.","native":"Los empleadores se benefician cuando dan al personal tiempo y apoyo para desarrollar nuevas habilidades."}]},"zh":{"word":"终身学习","question":"终身学习为何越来越重要，忙碌的成年人怎样才能做到这一点？","examples":[{"en":"Technology changes many jobs so quickly that one qualification may no longer last an entire career.","native":"技术使许多工作迅速变化，因此一项资格可能已无法满足整个职业生涯的需要。"},{"en":"Short, flexible courses help adults learn without giving up work or family responsibilities.","native":"简短灵活的课程能帮助成年人在不放弃工作或家庭责任的情况下学习。"},{"en":"Employers benefit when they give staff time and support to develop new skills.","native":"雇主为员工提供时间和支持来培养新技能时，企业自身也会受益。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'critical thinking', 'How can people strengthen critical thinking when they are surrounded by persuasive media and strong opinions?', '{"te":{"word":"విమర్శనాత్మక ఆలోచన","question":"ప్రభావితం చేసే మీడియా మరియు బలమైన అభిప్రాయాలు చుట్టూ ఉన్నప్పుడు ప్రజలు విమర్శనాత్మక ఆలోచనను ఎలా బలోపేతం చేసుకోగలరు?","examples":[{"en":"Critical thinking begins with asking what evidence would prove a claim wrong.","native":"ఒక వాదన తప్పని ఏ ఆధారం నిరూపించగలదో అడగడంతో విమర్శనాత్మక ఆలోచన మొదలవుతుంది."},{"en":"People should compare credible sources and separate emotional language from factual support.","native":"ప్రజలు విశ్వసనీయ మూలాలను పోల్చి, భావోద్వేగ భాషను వాస్తవ ఆధారాల నుండి వేరు చేయాలి."},{"en":"Changing your mind after seeing better evidence is a sign of judgement, not weakness.","native":"మెరుగైన ఆధారాలను చూసిన తర్వాత మీ అభిప్రాయాన్ని మార్చుకోవడం బలహీనత కాదు, మంచి వివేచనకు సంకేతం."}]},"hi":{"word":"आलोचनात्मक सोच","question":"प्रभावशाली मीडिया और दृढ़ विचारों से घिरे होने पर लोग अपनी आलोचनात्मक सोच कैसे मज़बूत कर सकते हैं?","examples":[{"en":"Critical thinking begins with asking what evidence would prove a claim wrong.","native":"आलोचनात्मक सोच इस सवाल से शुरू होती है कि कौन-सा प्रमाण किसी दावे को गलत साबित करेगा।"},{"en":"People should compare credible sources and separate emotional language from factual support.","native":"लोगों को विश्वसनीय स्रोतों की तुलना करनी चाहिए और भावनात्मक भाषा को तथ्यात्मक आधार से अलग करना चाहिए।"},{"en":"Changing your mind after seeing better evidence is a sign of judgement, not weakness.","native":"बेहतर प्रमाण देखने के बाद अपनी राय बदलना कमज़ोरी नहीं, बल्कि समझदारी की निशानी है।"}]},"es":{"word":"pensamiento crítico","question":"¿Cómo puede la gente reforzar su pensamiento crítico cuando está rodeada de medios persuasivos y opiniones firmes?","examples":[{"en":"Critical thinking begins with asking what evidence would prove a claim wrong.","native":"El pensamiento crítico comienza preguntando qué pruebas demostrarían que una afirmación es falsa."},{"en":"People should compare credible sources and separate emotional language from factual support.","native":"La gente debería comparar fuentes fiables y separar el lenguaje emocional del respaldo factual."},{"en":"Changing your mind after seeing better evidence is a sign of judgement, not weakness.","native":"Cambiar de opinión al ver mejores pruebas es señal de buen criterio, no de debilidad."}]},"zh":{"word":"批判性思维","question":"面对具有说服力的媒体和强烈观点，人们如何增强批判性思维？","examples":[{"en":"Critical thinking begins with asking what evidence would prove a claim wrong.","native":"批判性思维始于追问什么证据能够证明某个说法是错误的。"},{"en":"People should compare credible sources and separate emotional language from factual support.","native":"人们应该比较可信来源，并将情绪化语言与事实依据区分开来。"},{"en":"Changing your mind after seeing better evidence is a sign of judgement, not weakness.","native":"看到更有力的证据后改变观点，是判断力的体现，而不是软弱。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'decision-making', 'What helps people make good decisions when information is incomplete and the consequences are uncertain?', '{"te":{"word":"నిర్ణయాలు తీసుకోవడం","question":"సమాచారం అసంపూర్ణంగా ఉండి, పరిణామాలు అనిశ్చితంగా ఉన్నప్పుడు మంచి నిర్ణయాలు తీసుకోవడానికి ప్రజలకు ఏది సహాయపడుతుంది?","examples":[{"en":"Listing the likely benefits, costs, and risks can prevent one attractive option from dominating the discussion.","native":"సంభావ్య ప్రయోజనాలు, ఖర్చులు మరియు ప్రమాదాలను జాబితా చేయడం వల్ల ఆకర్షణీయమైన ఒక ఎంపిక మొత్తం చర్చను ఆధిపత్యం చేయకుండా ఉంటుంది."},{"en":"Good decision-makers seek different perspectives but set a deadline so that analysis does not become avoidance.","native":"మంచి నిర్ణయాలు తీసుకునేవారు భిన్న దృక్పథాలను కోరతారు, కానీ విశ్లేషణ తప్పించుకునే మార్గంగా మారకుండా గడువు నిర్ణయిస్తారు."},{"en":"When uncertainty cannot be removed, a reversible small step may be wiser than a permanent commitment.","native":"అనిశ్చితిని తొలగించలేనప్పుడు, శాశ్వత నిబద్ధత కంటే వెనక్కి మార్చగల చిన్న అడుగు తెలివైనది కావచ్చు."}]},"hi":{"word":"निर्णय लेना","question":"जब जानकारी अधूरी हो और परिणाम अनिश्चित हों, तब लोगों को अच्छे निर्णय लेने में क्या मदद करता है?","examples":[{"en":"Listing the likely benefits, costs, and risks can prevent one attractive option from dominating the discussion.","native":"संभावित लाभ, लागत और जोखिमों की सूची बनाने से कोई एक आकर्षक विकल्प पूरी चर्चा पर हावी नहीं होता।"},{"en":"Good decision-makers seek different perspectives but set a deadline so that analysis does not become avoidance.","native":"अच्छे निर्णयकर्ता अलग-अलग दृष्टिकोण तलाशते हैं, लेकिन एक समय-सीमा तय करते हैं ताकि विश्लेषण टालमटोल न बन जाए।"},{"en":"When uncertainty cannot be removed, a reversible small step may be wiser than a permanent commitment.","native":"जब अनिश्चितता दूर न की जा सके, तब स्थायी प्रतिबद्धता की तुलना में वापस लिया जा सकने वाला छोटा कदम अधिक समझदारी भरा हो सकता है।"}]},"es":{"word":"toma de decisiones","question":"¿Qué ayuda a tomar buenas decisiones cuando la información es incompleta y las consecuencias son inciertas?","examples":[{"en":"Listing the likely benefits, costs, and risks can prevent one attractive option from dominating the discussion.","native":"Enumerar los posibles beneficios, costes y riesgos puede evitar que una opción atractiva domine la discusión."},{"en":"Good decision-makers seek different perspectives but set a deadline so that analysis does not become avoidance.","native":"Quienes deciden bien buscan distintas perspectivas, pero fijan un plazo para que el análisis no se convierta en una forma de evitar la decisión."},{"en":"When uncertainty cannot be removed, a reversible small step may be wiser than a permanent commitment.","native":"Cuando no se puede eliminar la incertidumbre, un pequeño paso reversible puede ser más sensato que un compromiso permanente."}]},"zh":{"word":"决策","question":"当信息不完整且后果不确定时，什么能帮助人们做出明智的决定？","examples":[{"en":"Listing the likely benefits, costs, and risks can prevent one attractive option from dominating the discussion.","native":"列出可能的收益、成本和风险，可以避免某个诱人的选项主导整个讨论。"},{"en":"Good decision-makers seek different perspectives but set a deadline so that analysis does not become avoidance.","native":"善于决策的人会寻求不同观点，但也会设定期限，以免分析变成逃避。"},{"en":"When uncertainty cannot be removed, a reversible small step may be wiser than a permanent commitment.","native":"当不确定性无法消除时，先迈出可撤回的一小步，可能比做出永久承诺更明智。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'conflict resolution', 'Which approaches are most effective for resolving conflicts at work or in a community?', '{"te":{"word":"వివాద పరిష్కారం","question":"కార్యాలయంలో లేదా సమాజంలో వివాదాలను పరిష్కరించడానికి ఏ పద్ధతులు అత్యంత ప్రభావవంతంగా ఉంటాయి?","examples":[{"en":"People are more willing to compromise when they feel their concerns have been heard accurately.","native":"తమ ఆందోళనలను సరిగ్గా విన్నారని భావించినప్పుడు ప్రజలు రాజీ పడేందుకు మరింత సిద్ధంగా ఉంటారు."},{"en":"Focusing on shared interests often reveals solutions that a debate about blame would hide.","native":"ఉమ్మడి ప్రయోజనాలపై దృష్టి పెట్టడం వల్ల నింద గురించి జరిగే వాదన దాచే పరిష్కారాలు తరచుగా కనిపిస్తాయి."},{"en":"If emotions remain intense, a neutral mediator can keep the conversation respectful and practical.","native":"భావోద్వేగాలు ఇంకా తీవ్రంగా ఉంటే, తటస్థ మధ్యవర్తి సంభాషణను గౌరవప్రదంగా మరియు ఆచరణాత్మకంగా ఉంచగలరు."}]},"hi":{"word":"संघर्ष समाधान","question":"कार्यस्थल या समुदाय में संघर्ष सुलझाने के लिए कौन-से तरीके सबसे प्रभावी हैं?","examples":[{"en":"People are more willing to compromise when they feel their concerns have been heard accurately.","native":"जब लोगों को लगता है कि उनकी चिंताओं को सही ढंग से सुना गया है, तो वे समझौता करने के लिए अधिक तैयार होते हैं।"},{"en":"Focusing on shared interests often reveals solutions that a debate about blame would hide.","native":"साझा हितों पर ध्यान देने से अक्सर ऐसे समाधान सामने आते हैं जिन्हें दोष पर बहस छिपा देती।"},{"en":"If emotions remain intense, a neutral mediator can keep the conversation respectful and practical.","native":"अगर भावनाएँ तीव्र बनी रहें, तो एक निष्पक्ष मध्यस्थ बातचीत को सम्मानजनक और व्यावहारिक बनाए रख सकता है।"}]},"es":{"word":"resolución de conflictos","question":"¿Qué enfoques son más eficaces para resolver conflictos en el trabajo o en una comunidad?","examples":[{"en":"People are more willing to compromise when they feel their concerns have been heard accurately.","native":"La gente está más dispuesta a llegar a acuerdos cuando siente que sus preocupaciones se han escuchado correctamente."},{"en":"Focusing on shared interests often reveals solutions that a debate about blame would hide.","native":"Centrarse en los intereses comunes suele revelar soluciones que un debate sobre la culpa ocultaría."},{"en":"If emotions remain intense, a neutral mediator can keep the conversation respectful and practical.","native":"Si las emociones siguen siendo intensas, un mediador neutral puede mantener la conversación respetuosa y práctica."}]},"zh":{"word":"冲突解决","question":"哪些方法最能有效解决职场或社区中的冲突？","examples":[{"en":"People are more willing to compromise when they feel their concerns have been heard accurately.","native":"当人们觉得自己的关切得到了准确理解时，会更愿意作出妥协。"},{"en":"Focusing on shared interests often reveals solutions that a debate about blame would hide.","native":"关注共同利益，往往能发现争论谁对谁错时看不到的解决方案。"},{"en":"If emotions remain intense, a neutral mediator can keep the conversation respectful and practical.","native":"如果情绪依然激烈，中立的调解人可以让对话保持尊重并注重实际。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'negotiation', 'What makes a negotiation fair and successful when the two sides do not have equal power?', '{"te":{"word":"చర్చలు","question":"రెండు పక్షాలకు సమానమైన శక్తి లేనప్పుడు చర్చలను న్యాయంగా మరియు విజయవంతంగా చేసేది ఏమిటి?","examples":[{"en":"A successful negotiation addresses each side''s main interests rather than forcing an immediate compromise.","native":"విజయవంతమైన చర్చ తక్షణ రాజీని బలవంతం చేయకుండా ప్రతి పక్షం యొక్క ప్రధాన ప్రయోజనాలను పరిష్కరిస్తుంది."},{"en":"Preparing alternatives gives weaker participants more confidence to reject an unfair offer.","native":"ప్రత్యామ్నాయాలను సిద్ధం చేసుకోవడం బలహీన స్థితిలో ఉన్న పాల్గొనేవారికి అన్యాయమైన ప్రతిపాదనను తిరస్కరించే మరింత ఆత్మవిశ్వాసాన్ని ఇస్తుంది."},{"en":"Agreements are more durable when expectations, deadlines, and responsibilities are written clearly.","native":"అంచనాలు, గడువులు మరియు బాధ్యతలను స్పష్టంగా రాసినప్పుడు ఒప్పందాలు ఎక్కువకాలం నిలుస్తాయి."}]},"hi":{"word":"बातचीत","question":"जब दोनों पक्षों के पास समान शक्ति न हो, तब बातचीत को निष्पक्ष और सफल क्या बनाता है?","examples":[{"en":"A successful negotiation addresses each side''s main interests rather than forcing an immediate compromise.","native":"सफल बातचीत तत्काल समझौता थोपने के बजाय दोनों पक्षों के मुख्य हितों पर ध्यान देती है।"},{"en":"Preparing alternatives gives weaker participants more confidence to reject an unfair offer.","native":"विकल्प तैयार रखने से कमज़ोर पक्ष के प्रतिभागियों को अनुचित प्रस्ताव ठुकराने का अधिक आत्मविश्वास मिलता है।"},{"en":"Agreements are more durable when expectations, deadlines, and responsibilities are written clearly.","native":"जब अपेक्षाएँ, समय-सीमाएँ और ज़िम्मेदारियाँ स्पष्ट रूप से लिखी हों, तो समझौते अधिक टिकाऊ होते हैं।"}]},"es":{"word":"negociación","question":"¿Qué hace que una negociación sea justa y exitosa cuando las dos partes no tienen el mismo poder?","examples":[{"en":"A successful negotiation addresses each side''s main interests rather than forcing an immediate compromise.","native":"Una negociación exitosa aborda los principales intereses de cada parte en lugar de forzar un acuerdo inmediato."},{"en":"Preparing alternatives gives weaker participants more confidence to reject an unfair offer.","native":"Preparar alternativas da a los participantes más débiles mayor confianza para rechazar una oferta injusta."},{"en":"Agreements are more durable when expectations, deadlines, and responsibilities are written clearly.","native":"Los acuerdos son más duraderos cuando las expectativas, los plazos y las responsabilidades quedan claramente por escrito."}]},"zh":{"word":"谈判","question":"当双方力量不对等时，怎样才能使谈判公平并取得成功？","examples":[{"en":"A successful negotiation addresses each side''s main interests rather than forcing an immediate compromise.","native":"成功的谈判会处理双方的核心利益，而不是强迫双方立即妥协。"},{"en":"Preparing alternatives gives weaker participants more confidence to reject an unfair offer.","native":"准备好其他选择，能让处于弱势的一方更有信心拒绝不公平的提议。"},{"en":"Agreements are more durable when expectations, deadlines, and responsibilities are written clearly.","native":"明确写下预期、期限和责任，能使协议更加持久。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'time management', 'Why do people struggle to manage their time, and which strategies genuinely help?', '{"te":{"word":"సమయ నిర్వహణ","question":"ప్రజలు తమ సమయాన్ని నిర్వహించడంలో ఎందుకు ఇబ్బంది పడతారు, నిజంగా సహాయపడే పద్ధతులు ఏవి?","examples":[{"en":"People often underestimate how long complex tasks take and leave no space for interruptions.","native":"సంక్లిష్ట పనులకు పట్టే సమయాన్ని ప్రజలు తరచుగా తక్కువగా అంచనా వేస్తారు మరియు అంతరాయాలకు సమయం కేటాయించరు."},{"en":"Choosing three priorities is usually more effective than filling every hour with minor activities.","native":"ప్రతి గంటను చిన్న పనులతో నింపడం కంటే మూడు ప్రాధాన్యాలను ఎంచుకోవడం సాధారణంగా మరింత ప్రభావవంతంగా ఉంటుంది."},{"en":"Regular breaks protect concentration, whereas constant multitasking creates the illusion of progress.","native":"క్రమమైన విరామాలు ఏకాగ్రతను కాపాడతాయి, అయితే నిరంతరం అనేక పనులు చేయడం పురోగతి జరుగుతోందనే భ్రమను కలిగిస్తుంది."}]},"hi":{"word":"समय प्रबंधन","question":"लोग अपने समय का प्रबंधन करने में क्यों संघर्ष करते हैं, और कौन-सी रणनीतियाँ वास्तव में मदद करती हैं?","examples":[{"en":"People often underestimate how long complex tasks take and leave no space for interruptions.","native":"लोग अक्सर जटिल कामों में लगने वाले समय को कम आँकते हैं और रुकावटों के लिए कोई गुंजाइश नहीं छोड़ते।"},{"en":"Choosing three priorities is usually more effective than filling every hour with minor activities.","native":"हर घंटे को छोटे कामों से भरने की तुलना में तीन प्राथमिकताएँ चुनना आम तौर पर अधिक प्रभावी होता है।"},{"en":"Regular breaks protect concentration, whereas constant multitasking creates the illusion of progress.","native":"नियमित विराम एकाग्रता बनाए रखते हैं, जबकि लगातार कई काम करना प्रगति का भ्रम पैदा करता है।"}]},"es":{"word":"gestión del tiempo","question":"¿Por qué cuesta gestionar el tiempo y qué estrategias ayudan de verdad?","examples":[{"en":"People often underestimate how long complex tasks take and leave no space for interruptions.","native":"La gente suele subestimar cuánto duran las tareas complejas y no deja margen para las interrupciones."},{"en":"Choosing three priorities is usually more effective than filling every hour with minor activities.","native":"Elegir tres prioridades suele ser más eficaz que llenar cada hora con actividades menores."},{"en":"Regular breaks protect concentration, whereas constant multitasking creates the illusion of progress.","native":"Los descansos regulares protegen la concentración, mientras que hacer varias tareas constantemente crea una ilusión de progreso."}]},"zh":{"word":"时间管理","question":"人们为什么难以管理时间，哪些方法真正有效？","examples":[{"en":"People often underestimate how long complex tasks take and leave no space for interruptions.","native":"人们经常低估复杂任务所需的时间，也没有为突发情况留出余地。"},{"en":"Choosing three priorities is usually more effective than filling every hour with minor activities.","native":"选择三项优先事项，通常比用琐碎活动填满每个小时更有效。"},{"en":"Regular breaks protect concentration, whereas constant multitasking creates the illusion of progress.","native":"定期休息有助于保持专注，而不停地处理多项任务只会制造取得进展的错觉。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'creativity', 'Can creativity be taught, or is it mainly a natural talent? How can schools and workplaces encourage it?', '{"te":{"word":"సృజనాత్మకత","question":"సృజనాత్మకతను బోధించగలమా, లేక అది ప్రధానంగా సహజ ప్రతిభా? పాఠశాలలు మరియు కార్యాలయాలు దాన్ని ఎలా ప్రోత్సహించగలవు?","examples":[{"en":"Creativity improves when people practise generating several imperfect ideas before judging any of them.","native":"ఏ ఆలోచననైనా అంచనా వేయడానికి ముందు పరిపూర్ణంగా లేని అనేక ఆలోచనలను రూపొందించడం సాధన చేసినప్పుడు సృజనాత్మకత మెరుగుపడుతుంది."},{"en":"Knowledge provides useful material for imagination, so creative work still requires patient study.","native":"జ్ఞానం ఊహాశక్తికి ఉపయోగకరమైన విషయాన్ని అందిస్తుంది, కాబట్టి సృజనాత్మక పనికి కూడా ఓపికతో కూడిన అధ్యయనం అవసరం."},{"en":"Schools can encourage originality by allowing more than one reasonable answer to a problem.","native":"ఒక సమస్యకు ఒకటి కంటే ఎక్కువ సమంజసమైన సమాధానాలను అనుమతించడం ద్వారా పాఠశాలలు స్వతంత్ర ఆలోచనను ప్రోత్సహించగలవు."}]},"hi":{"word":"रचनात्मकता","question":"क्या रचनात्मकता सिखाई जा सकती है, या यह मुख्य रूप से स्वाभाविक प्रतिभा है? स्कूल और कार्यस्थल इसे कैसे बढ़ावा दे सकते हैं?","examples":[{"en":"Creativity improves when people practise generating several imperfect ideas before judging any of them.","native":"जब लोग किसी विचार को परखने से पहले कई अधूरे विचार बनाने का अभ्यास करते हैं, तो रचनात्मकता बढ़ती है।"},{"en":"Knowledge provides useful material for imagination, so creative work still requires patient study.","native":"ज्ञान कल्पना को उपयोगी सामग्री देता है, इसलिए रचनात्मक काम के लिए भी धैर्यपूर्वक अध्ययन आवश्यक है।"},{"en":"Schools can encourage originality by allowing more than one reasonable answer to a problem.","native":"किसी समस्या के एक से अधिक उचित उत्तर स्वीकार करके स्कूल मौलिकता को प्रोत्साहित कर सकते हैं।"}]},"es":{"word":"creatividad","question":"¿Se puede enseñar la creatividad o es principalmente un talento natural? ¿Cómo pueden fomentarla las escuelas y los lugares de trabajo?","examples":[{"en":"Creativity improves when people practise generating several imperfect ideas before judging any of them.","native":"La creatividad mejora cuando se practica la generación de varias ideas imperfectas antes de juzgar cualquiera de ellas."},{"en":"Knowledge provides useful material for imagination, so creative work still requires patient study.","native":"El conocimiento aporta material útil a la imaginación, por lo que el trabajo creativo también exige estudiar con paciencia."},{"en":"Schools can encourage originality by allowing more than one reasonable answer to a problem.","native":"Las escuelas pueden fomentar la originalidad al permitir más de una respuesta razonable a un problema."}]},"zh":{"word":"创造力","question":"创造力可以培养，还是主要来自天赋？学校和工作场所应如何鼓励创造力？","examples":[{"en":"Creativity improves when people practise generating several imperfect ideas before judging any of them.","native":"在评价任何想法之前，先练习提出多个不完美的构想，这能提升创造力。"},{"en":"Knowledge provides useful material for imagination, so creative work still requires patient study.","native":"知识为想象力提供有用的素材，因此创造性工作仍需要耐心学习。"},{"en":"Schools can encourage originality by allowing more than one reasonable answer to a problem.","native":"学校允许一个问题有多个合理答案，就能鼓励原创思维。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'innovation', 'When does innovation genuinely improve society, and how should its risks be managed?', '{"te":{"word":"ఆవిష్కరణ","question":"ఆవిష్కరణ ఎప్పుడు సమాజాన్ని నిజంగా మెరుగుపరుస్తుంది, దాని ప్రమాదాలను ఎలా నిర్వహించాలి?","examples":[{"en":"Innovation is valuable when it solves a real need rather than merely making an existing product fashionable.","native":"ఇప్పటికే ఉన్న ఉత్పత్తిని కేవలం ఫ్యాషన్‌గా మార్చడం కాకుండా నిజమైన అవసరాన్ని పరిష్కరించినప్పుడు ఆవిష్కరణ విలువైనది."},{"en":"Testing new systems on a limited scale can reveal unintended consequences before they affect everyone.","native":"కొత్త వ్యవస్థలను పరిమిత స్థాయిలో పరీక్షించడం వల్ల అవి అందరినీ ప్రభావితం చేయకముందే ఊహించని పరిణామాలు బయటపడవచ్చు."},{"en":"Public funding should support promising research whose benefits may take years to appear.","native":"ప్రయోజనాలు కనిపించడానికి సంవత్సరాలు పట్టే ఆశాజనక పరిశోధనకు ప్రభుత్వ నిధులు మద్దతు ఇవ్వాలి."}]},"hi":{"word":"नवाचार","question":"नवाचार वास्तव में समाज को कब बेहतर बनाता है, और उसके जोखिमों का प्रबंधन कैसे किया जाना चाहिए?","examples":[{"en":"Innovation is valuable when it solves a real need rather than merely making an existing product fashionable.","native":"नवाचार तब मूल्यवान होता है जब वह किसी मौजूदा उत्पाद को केवल फैशनेबल बनाने के बजाय वास्तविक ज़रूरत पूरी करता है।"},{"en":"Testing new systems on a limited scale can reveal unintended consequences before they affect everyone.","native":"नई प्रणालियों को सीमित स्तर पर परखने से सबको प्रभावित करने से पहले उनके अनचाहे परिणाम सामने आ सकते हैं।"},{"en":"Public funding should support promising research whose benefits may take years to appear.","native":"सरकारी धन को ऐसे आशाजनक शोध का समर्थन करना चाहिए जिसके लाभ सामने आने में कई वर्ष लग सकते हैं।"}]},"es":{"word":"innovación","question":"¿Cuándo mejora realmente la innovación la sociedad y cómo deberían gestionarse sus riesgos?","examples":[{"en":"Innovation is valuable when it solves a real need rather than merely making an existing product fashionable.","native":"La innovación es valiosa cuando resuelve una necesidad real en vez de limitarse a poner de moda un producto existente."},{"en":"Testing new systems on a limited scale can reveal unintended consequences before they affect everyone.","native":"Probar nuevos sistemas a escala limitada puede revelar consecuencias imprevistas antes de que afecten a todo el mundo."},{"en":"Public funding should support promising research whose benefits may take years to appear.","native":"La financiación pública debería apoyar investigaciones prometedoras cuyos beneficios pueden tardar años en aparecer."}]},"zh":{"word":"创新","question":"创新在什么情况下能真正改善社会，又该如何管理其风险？","examples":[{"en":"Innovation is valuable when it solves a real need rather than merely making an existing product fashionable.","native":"创新的价值在于解决真实需求，而不只是让已有产品变得时髦。"},{"en":"Testing new systems on a limited scale can reveal unintended consequences before they affect everyone.","native":"在有限范围内测试新系统，可以在其影响所有人之前发现意外后果。"},{"en":"Public funding should support promising research whose benefits may take years to appear.","native":"公共资金应该支持有前景但可能需要多年才能显现效益的研究。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'privacy', 'How much privacy should people trade for convenience or security when they use online services?', '{"te":{"word":"గోప్యత","question":"ఆన్‌లైన్ సేవలను ఉపయోగించేటప్పుడు సౌకర్యం లేదా భద్రత కోసం ప్రజలు తమ గోప్యతలో ఎంత భాగాన్ని వదులుకోవాలి?","examples":[{"en":"People often accept data collection without understanding how long their information will be stored.","native":"తమ సమాచారం ఎంతకాలం నిల్వ చేయబడుతుందో అర్థం చేసుకోకుండానే ప్రజలు తరచుగా డేటా సేకరణకు అంగీకరిస్తారు."},{"en":"Convenient services should offer meaningful choices instead of making surveillance the default.","native":"సౌకర్యవంతమైన సేవలు నిఘాను ముందుగా నిర్ణయించిన ఎంపికగా చేయకుండా నిజమైన ఎంపికలను అందించాలి."},{"en":"Security can justify limited monitoring, but independent oversight is needed to prevent abuse.","native":"భద్రత పరిమిత పర్యవేక్షణను సమర్థించవచ్చు, కానీ దుర్వినియోగాన్ని నిరోధించడానికి స్వతంత్ర పర్యవేక్షణ అవసరం."}]},"hi":{"word":"निजता","question":"ऑनलाइन सेवाओं का उपयोग करते समय लोगों को सुविधा या सुरक्षा के बदले कितनी निजता छोड़नी चाहिए?","examples":[{"en":"People often accept data collection without understanding how long their information will be stored.","native":"लोग अक्सर यह समझे बिना डेटा संग्रह स्वीकार कर लेते हैं कि उनकी जानकारी कितने समय तक रखी जाएगी।"},{"en":"Convenient services should offer meaningful choices instead of making surveillance the default.","native":"सुविधाजनक सेवाओं को निगरानी को सामान्य व्यवस्था बनाने के बजाय वास्तविक विकल्प देने चाहिए।"},{"en":"Security can justify limited monitoring, but independent oversight is needed to prevent abuse.","native":"सुरक्षा सीमित निगरानी को उचित ठहरा सकती है, लेकिन दुरुपयोग रोकने के लिए स्वतंत्र निरीक्षण आवश्यक है।"}]},"es":{"word":"privacidad","question":"¿Cuánta privacidad debería sacrificar la gente a cambio de comodidad o seguridad al utilizar servicios en línea?","examples":[{"en":"People often accept data collection without understanding how long their information will be stored.","native":"La gente suele aceptar la recopilación de datos sin entender cuánto tiempo se conservará su información."},{"en":"Convenient services should offer meaningful choices instead of making surveillance the default.","native":"Los servicios cómodos deberían ofrecer opciones reales en lugar de convertir la vigilancia en la configuración predeterminada."},{"en":"Security can justify limited monitoring, but independent oversight is needed to prevent abuse.","native":"La seguridad puede justificar una supervisión limitada, pero hace falta un control independiente para evitar abusos."}]},"zh":{"word":"隐私","question":"使用网络服务时，人们应该用多少隐私来换取便利或安全？","examples":[{"en":"People often accept data collection without understanding how long their information will be stored.","native":"人们经常在不了解个人信息会被保存多久的情况下，同意数据收集。"},{"en":"Convenient services should offer meaningful choices instead of making surveillance the default.","native":"便捷的服务应该提供真正的选择，而不是把监控设为默认做法。"},{"en":"Security can justify limited monitoring, but independent oversight is needed to prevent abuse.","native":"安全可以成为有限监控的理由，但仍需独立监督来防止滥用。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'data protection', 'What obligations should organizations have when they collect and store personal data?', '{"te":{"word":"డేటా రక్షణ","question":"వ్యక్తిగత డేటాను సేకరించి నిల్వ చేసేటప్పుడు సంస్థలకు ఎలాంటి బాధ్యతలు ఉండాలి?","examples":[{"en":"Organizations should collect only the information they genuinely need and delete it when its purpose ends.","native":"సంస్థలు తమకు నిజంగా అవసరమైన సమాచారాన్ని మాత్రమే సేకరించి, దాని అవసరం ముగిసినప్పుడు తొలగించాలి."},{"en":"Clear consent is meaningless if refusing it makes an essential service impossible to use.","native":"సమ్మతిని నిరాకరించడం వల్ల అవసరమైన సేవను ఉపయోగించలేకపోతే, స్పష్టంగా తెలిపిన సమ్మతికి అర్థం ఉండదు."},{"en":"Serious breaches should trigger prompt warnings, practical support, and meaningful penalties.","native":"తీవ్రమైన డేటా ఉల్లంఘనలు వెంటనే హెచ్చరికలు, ఆచరణాత్మక సహాయం మరియు ప్రభావవంతమైన శిక్షలకు దారితీయాలి."}]},"hi":{"word":"डेटा संरक्षण","question":"व्यक्तिगत डेटा इकट्ठा और संग्रहीत करते समय संगठनों की क्या ज़िम्मेदारियाँ होनी चाहिए?","examples":[{"en":"Organizations should collect only the information they genuinely need and delete it when its purpose ends.","native":"संगठनों को केवल वही जानकारी एकत्र करनी चाहिए जिसकी उन्हें वास्तव में ज़रूरत हो और उद्देश्य पूरा होने पर उसे मिटा देना चाहिए।"},{"en":"Clear consent is meaningless if refusing it makes an essential service impossible to use.","native":"अगर सहमति से इनकार करने पर किसी आवश्यक सेवा का उपयोग असंभव हो जाए, तो स्पष्ट सहमति का कोई अर्थ नहीं रहता।"},{"en":"Serious breaches should trigger prompt warnings, practical support, and meaningful penalties.","native":"गंभीर डेटा उल्लंघनों के बाद तुरंत चेतावनी, व्यावहारिक सहायता और प्रभावी दंड मिलना चाहिए।"}]},"es":{"word":"protección de datos","question":"¿Qué obligaciones deberían tener las organizaciones cuando recopilan y almacenan datos personales?","examples":[{"en":"Organizations should collect only the information they genuinely need and delete it when its purpose ends.","native":"Las organizaciones deberían recopilar solo la información que realmente necesitan y eliminarla cuando termine su finalidad."},{"en":"Clear consent is meaningless if refusing it makes an essential service impossible to use.","native":"El consentimiento claro no significa nada si rechazarlo impide utilizar un servicio esencial."},{"en":"Serious breaches should trigger prompt warnings, practical support, and meaningful penalties.","native":"Las filtraciones graves deberían provocar avisos rápidos, apoyo práctico y sanciones significativas."}]},"zh":{"word":"数据保护","question":"组织收集和存储个人数据时应承担哪些义务？","examples":[{"en":"Organizations should collect only the information they genuinely need and delete it when its purpose ends.","native":"组织应该只收集真正需要的信息，并在用途结束后将其删除。"},{"en":"Clear consent is meaningless if refusing it makes an essential service impossible to use.","native":"如果拒绝同意就无法使用一项基本服务，那么所谓的明确同意便毫无意义。"},{"en":"Serious breaches should trigger prompt warnings, practical support, and meaningful penalties.","native":"发生严重数据泄露后，应立即发出警告、提供实际帮助，并实施有力度的处罚。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'journalism', 'What responsibilities do journalists have when speed, accuracy, and the public interest conflict?', '{"te":{"word":"పత్రికారంగం","question":"వేగం, ఖచ్చితత్వం మరియు ప్రజా ప్రయోజనం పరస్పరం విరుద్ధంగా ఉన్నప్పుడు పాత్రికేయులకు ఎలాంటి బాధ్యతలు ఉంటాయి?","examples":[{"en":"Being first matters less than confirming facts that could damage an innocent person''s reputation.","native":"ఒక నిర్దోషి ప్రతిష్ఠకు హాని కలిగించగల వాస్తవాలను నిర్ధారించడం కంటే ముందుగా వార్తను అందించడం తక్కువ ముఖ్యం."},{"en":"Journalists should explain what they know, what remains uncertain, and how their evidence was obtained.","native":"పాత్రికేయులు తమకు ఏమి తెలుసో, ఇంకా ఏది అనిశ్చితంగా ఉందో మరియు తమ ఆధారాలు ఎలా పొందారో వివరించాలి."},{"en":"Public-interest reporting may justify revealing private conduct when it exposes corruption or serious harm.","native":"అవినీతి లేదా తీవ్రమైన హానిని బయటపెడితే, ప్రజా ప్రయోజన వార్తా నివేదిక వ్యక్తిగత ప్రవర్తనను వెల్లడించడాన్ని సమర్థించవచ్చు."}]},"hi":{"word":"पत्रकारिता","question":"जब गति, सटीकता और जनहित आपस में टकराएँ, तब पत्रकारों की क्या ज़िम्मेदारियाँ होती हैं?","examples":[{"en":"Being first matters less than confirming facts that could damage an innocent person''s reputation.","native":"सबसे पहले खबर देने से अधिक महत्वपूर्ण उन तथ्यों की पुष्टि करना है जो किसी निर्दोष व्यक्ति की प्रतिष्ठा को नुकसान पहुँचा सकते हैं।"},{"en":"Journalists should explain what they know, what remains uncertain, and how their evidence was obtained.","native":"पत्रकारों को बताना चाहिए कि वे क्या जानते हैं, क्या अब भी अनिश्चित है और उनके प्रमाण कैसे प्राप्त हुए।"},{"en":"Public-interest reporting may justify revealing private conduct when it exposes corruption or serious harm.","native":"जब निजी आचरण का खुलासा भ्रष्टाचार या गंभीर नुकसान सामने लाता है, तब जनहित की रिपोर्टिंग उसे उचित ठहरा सकती है।"}]},"es":{"word":"periodismo","question":"¿Qué responsabilidades tienen los periodistas cuando entran en conflicto la rapidez, la precisión y el interés público?","examples":[{"en":"Being first matters less than confirming facts that could damage an innocent person''s reputation.","native":"Ser el primero importa menos que confirmar hechos que podrían dañar la reputación de una persona inocente."},{"en":"Journalists should explain what they know, what remains uncertain, and how their evidence was obtained.","native":"Los periodistas deberían explicar qué saben, qué sigue siendo incierto y cómo obtuvieron sus pruebas."},{"en":"Public-interest reporting may justify revealing private conduct when it exposes corruption or serious harm.","native":"El periodismo de interés público puede justificar revelar una conducta privada cuando destapa corrupción o daños graves."}]},"zh":{"word":"新闻业","question":"当速度、准确性和公共利益发生冲突时，记者应承担哪些责任？","examples":[{"en":"Being first matters less than confirming facts that could damage an innocent person''s reputation.","native":"抢先报道不如核实可能损害无辜者声誉的事实重要。"},{"en":"Journalists should explain what they know, what remains uncertain, and how their evidence was obtained.","native":"记者应该说明自己掌握了什么、哪些方面仍不确定，以及证据是如何获得的。"},{"en":"Public-interest reporting may justify revealing private conduct when it exposes corruption or serious harm.","native":"如果能揭露腐败或严重危害，公共利益报道可能有理由披露私人行为。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'freedom of speech', 'Where should societies draw the line between freedom of speech and protection from harm?', '{"te":{"word":"భావ ప్రకటనా స్వేచ్ఛ","question":"భావ ప్రకటనా స్వేచ్ఛకు మరియు హాని నుంచి రక్షణకు మధ్య సమాజాలు ఎక్కడ హద్దు నిర్ణయించాలి?","examples":[{"en":"Freedom of speech protects unpopular opinions, not a right to threaten other people without consequences.","native":"భావ ప్రకటనా స్వేచ్ఛ ప్రజాదరణ లేని అభిప్రాయాలను రక్షిస్తుంది, కానీ పరిణామాలు లేకుండా ఇతరులను బెదిరించే హక్కును కాదు."},{"en":"Rules against harmful expression must be precise enough to prevent authorities from silencing criticism.","native":"హానికరమైన వ్యక్తీకరణకు వ్యతిరేకమైన నియమాలు, అధికారులు విమర్శలను అణచివేయకుండా నిరోధించేంత స్పష్టంగా ఉండాలి."},{"en":"Open debate works best when speakers can be challenged with evidence rather than intimidated.","native":"వక్తలను బెదిరించడం కాకుండా ఆధారాలతో సవాలు చేయగలిగినప్పుడు బహిరంగ చర్చ ఉత్తమంగా పనిచేస్తుంది."}]},"hi":{"word":"अभिव्यक्ति की स्वतंत्रता","question":"समाजों को अभिव्यक्ति की स्वतंत्रता और नुकसान से सुरक्षा के बीच सीमा कहाँ तय करनी चाहिए?","examples":[{"en":"Freedom of speech protects unpopular opinions, not a right to threaten other people without consequences.","native":"अभिव्यक्ति की स्वतंत्रता अलोकप्रिय विचारों की रक्षा करती है, बिना परिणाम के दूसरों को धमकाने के अधिकार की नहीं।"},{"en":"Rules against harmful expression must be precise enough to prevent authorities from silencing criticism.","native":"हानिकारक अभिव्यक्ति के विरुद्ध नियम इतने स्पष्ट होने चाहिए कि अधिकारी उनका उपयोग आलोचना दबाने के लिए न कर सकें।"},{"en":"Open debate works best when speakers can be challenged with evidence rather than intimidated.","native":"खुली बहस तब सबसे अच्छी होती है जब वक्ताओं को डराने के बजाय प्रमाण से चुनौती दी जा सके।"}]},"es":{"word":"libertad de expresión","question":"¿Dónde deberían trazar las sociedades el límite entre la libertad de expresión y la protección frente al daño?","examples":[{"en":"Freedom of speech protects unpopular opinions, not a right to threaten other people without consequences.","native":"La libertad de expresión protege las opiniones impopulares, no el derecho a amenazar a otras personas sin consecuencias."},{"en":"Rules against harmful expression must be precise enough to prevent authorities from silencing criticism.","native":"Las normas contra expresiones dañinas deben ser lo bastante precisas para impedir que las autoridades silencien las críticas."},{"en":"Open debate works best when speakers can be challenged with evidence rather than intimidated.","native":"El debate abierto funciona mejor cuando se puede cuestionar a los participantes con pruebas en vez de intimidarlos."}]},"zh":{"word":"言论自由","question":"社会应如何划定言论自由与免受伤害之间的界限？","examples":[{"en":"Freedom of speech protects unpopular opinions, not a right to threaten other people without consequences.","native":"言论自由保护不受欢迎的观点，但不意味着可以不负后果地威胁他人。"},{"en":"Rules against harmful expression must be precise enough to prevent authorities from silencing criticism.","native":"针对有害言论的规则必须足够明确，以防当局借此压制批评。"},{"en":"Open debate works best when speakers can be challenged with evidence rather than intimidated.","native":"当发言者面对的是有证据的质疑而不是恐吓时，公开讨论最有效。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'democracy', 'What makes a democracy function well beyond simply holding elections?', '{"te":{"word":"ప్రజాస్వామ్యం","question":"కేవలం ఎన్నికలు నిర్వహించడాన్ని మించి ప్రజాస్వామ్యం బాగా పనిచేయడానికి ఏమి అవసరం?","examples":[{"en":"Free elections matter, but voters also need reliable information and institutions that enforce the law impartially.","native":"స్వేచ్ఛాయుత ఎన్నికలు ముఖ్యం, కానీ ఓటర్లకు విశ్వసనీయ సమాచారం మరియు చట్టాన్ని నిష్పాక్షికంగా అమలు చేసే సంస్థలు కూడా అవసరం."},{"en":"Democracy weakens when leaders treat political opponents as enemies rather than legitimate rivals.","native":"నాయకులు రాజకీయ ప్రత్యర్థులను చట్టబద్ధమైన పోటీదారులుగా కాకుండా శత్రువులుగా చూసినప్పుడు ప్రజాస్వామ్యం బలహీనపడుతుంది."},{"en":"Citizens must be able to question those in power between elections, not only on voting day.","native":"పౌరులు అధికారంలో ఉన్నవారిని ఎన్నికల మధ్య కాలంలో కూడా ప్రశ్నించగలగాలి, కేవలం ఓటు వేసే రోజున మాత్రమే కాదు."}]},"hi":{"word":"लोकतंत्र","question":"केवल चुनाव कराने से आगे, लोकतंत्र को अच्छी तरह चलाने के लिए क्या आवश्यक है?","examples":[{"en":"Free elections matter, but voters also need reliable information and institutions that enforce the law impartially.","native":"स्वतंत्र चुनाव महत्वपूर्ण हैं, लेकिन मतदाताओं को विश्वसनीय जानकारी और निष्पक्ष रूप से कानून लागू करने वाली संस्थाएँ भी चाहिए।"},{"en":"Democracy weakens when leaders treat political opponents as enemies rather than legitimate rivals.","native":"जब नेता राजनीतिक विरोधियों को वैध प्रतिद्वंद्वी के बजाय दुश्मन मानते हैं, तो लोकतंत्र कमज़ोर होता है।"},{"en":"Citizens must be able to question those in power between elections, not only on voting day.","native":"नागरिकों को केवल मतदान के दिन नहीं, बल्कि चुनावों के बीच भी सत्ता में बैठे लोगों से सवाल करने में सक्षम होना चाहिए।"}]},"es":{"word":"democracia","question":"¿Qué hace que una democracia funcione bien, más allá de celebrar elecciones?","examples":[{"en":"Free elections matter, but voters also need reliable information and institutions that enforce the law impartially.","native":"Las elecciones libres importan, pero los votantes también necesitan información fiable e instituciones que apliquen la ley con imparcialidad."},{"en":"Democracy weakens when leaders treat political opponents as enemies rather than legitimate rivals.","native":"La democracia se debilita cuando los líderes tratan a sus adversarios políticos como enemigos en vez de rivales legítimos."},{"en":"Citizens must be able to question those in power between elections, not only on voting day.","native":"La ciudadanía debe poder cuestionar a quienes gobiernan entre elecciones, no solo el día de la votación."}]},"zh":{"word":"民主","question":"除了举行选举之外，怎样才能使民主制度良好运作？","examples":[{"en":"Free elections matter, but voters also need reliable information and institutions that enforce the law impartially.","native":"自由选举很重要，但选民还需要可靠的信息和公正执法的机构。"},{"en":"Democracy weakens when leaders treat political opponents as enemies rather than legitimate rivals.","native":"当领导人把政治对手视为敌人而不是合法竞争者时，民主就会削弱。"},{"en":"Citizens must be able to question those in power between elections, not only on voting day.","native":"公民必须能够在两次选举之间质询掌权者，而不只是在投票日表达意见。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'civic engagement', 'Why do some people participate in community and public life while others withdraw, and how can engagement be encouraged?', '{"te":{"word":"పౌర భాగస్వామ్యం","question":"కొందరు సమాజ మరియు ప్రజా జీవితంలో పాల్గొంటుండగా మరికొందరు ఎందుకు దూరమవుతారు, భాగస్వామ్యాన్ని ఎలా ప్రోత్సహించవచ్చు?","examples":[{"en":"People are more likely to participate when they can see a direct connection between their effort and local change.","native":"తమ కృషికి స్థానిక మార్పుకు మధ్య ప్రత్యక్ష సంబంధాన్ని చూడగలిగినప్పుడు ప్రజలు పాల్గొనే అవకాశం ఎక్కువగా ఉంటుంది."},{"en":"Schools can build civic habits by giving students genuine responsibility for shared decisions.","native":"ఉమ్మడి నిర్ణయాలకు విద్యార్థులకు నిజమైన బాధ్యత ఇవ్వడం ద్వారా పాఠశాలలు పౌర అలవాట్లను పెంపొందించగలవు."},{"en":"Digital campaigns raise awareness quickly, but lasting engagement usually requires work beyond clicking a button.","native":"డిజిటల్ ప్రచారాలు త్వరగా అవగాహన పెంచుతాయి, కానీ దీర్ఘకాలిక భాగస్వామ్యానికి సాధారణంగా ఒక బటన్ నొక్కడం కంటే ఎక్కువ కృషి అవసరం."}]},"hi":{"word":"नागरिक भागीदारी","question":"कुछ लोग सामुदायिक और सार्वजनिक जीवन में हिस्सा क्यों लेते हैं जबकि अन्य पीछे हट जाते हैं, और भागीदारी को कैसे प्रोत्साहित किया जा सकता है?","examples":[{"en":"People are more likely to participate when they can see a direct connection between their effort and local change.","native":"जब लोग अपने प्रयास और स्थानीय बदलाव के बीच सीधा संबंध देख पाते हैं, तो उनके भाग लेने की संभावना अधिक होती है।"},{"en":"Schools can build civic habits by giving students genuine responsibility for shared decisions.","native":"साझा निर्णयों के लिए छात्रों को वास्तविक ज़िम्मेदारी देकर स्कूल नागरिक आदतें विकसित कर सकते हैं।"},{"en":"Digital campaigns raise awareness quickly, but lasting engagement usually requires work beyond clicking a button.","native":"डिजिटल अभियान तेज़ी से जागरूकता बढ़ाते हैं, लेकिन स्थायी भागीदारी के लिए आम तौर पर बटन क्लिक करने से आगे काम करना पड़ता है।"}]},"es":{"word":"participación cívica","question":"¿Por qué algunas personas participan en la vida comunitaria y pública mientras otras se alejan, y cómo puede fomentarse la participación?","examples":[{"en":"People are more likely to participate when they can see a direct connection between their effort and local change.","native":"Es más probable que la gente participe cuando ve una relación directa entre su esfuerzo y el cambio local."},{"en":"Schools can build civic habits by giving students genuine responsibility for shared decisions.","native":"Las escuelas pueden crear hábitos cívicos dando al alumnado una responsabilidad real en las decisiones compartidas."},{"en":"Digital campaigns raise awareness quickly, but lasting engagement usually requires work beyond clicking a button.","native":"Las campañas digitales sensibilizan con rapidez, pero la participación duradera suele exigir trabajo más allá de pulsar un botón."}]},"zh":{"word":"公民参与","question":"为什么有些人参与社区和公共生活，而另一些人选择退出？怎样才能鼓励参与？","examples":[{"en":"People are more likely to participate when they can see a direct connection between their effort and local change.","native":"当人们能看到自己的努力与当地变化之间的直接联系时，会更愿意参与。"},{"en":"Schools can build civic habits by giving students genuine responsibility for shared decisions.","native":"学校可以让学生真正负责共同决策，从而培养公民参与习惯。"},{"en":"Digital campaigns raise awareness quickly, but lasting engagement usually requires work beyond clicking a button.","native":"数字宣传能迅速提高意识，但持久参与通常需要付出点击按钮以外的实际行动。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'international cooperation', 'Which global problems require international cooperation, and why is agreement so difficult?', '{"te":{"word":"అంతర్జాతీయ సహకారం","question":"ఏ ప్రపంచ సమస్యలకు అంతర్జాతీయ సహకారం అవసరం, దేశాల మధ్య ఒప్పందం కుదరడం ఎందుకు అంత కష్టం?","examples":[{"en":"Climate threats, pandemics, and organized crime cross borders, so no country can manage them alone.","native":"వాతావరణ ముప్పులు, మహమ్మారులు మరియు వ్యవస్థీకృత నేరాలు సరిహద్దులను దాటుతాయి, కాబట్టి ఏ దేశమూ వాటిని ఒంటరిగా నిర్వహించలేదు."},{"en":"Cooperation becomes difficult when governments face immediate domestic costs but benefits arrive much later.","native":"ప్రభుత్వాలు తక్షణ దేశీయ ఖర్చులను ఎదుర్కొంటూ ప్రయోజనాలు చాలా ఆలస్యంగా వచ్చినప్పుడు సహకారం కష్టమవుతుంది."},{"en":"Shared goals are more credible when wealthy countries contribute resources as well as promises.","native":"సంపన్న దేశాలు వాగ్దానాలతో పాటు వనరులను కూడా అందించినప్పుడు ఉమ్మడి లక్ష్యాలు మరింత విశ్వసనీయంగా ఉంటాయి."}]},"hi":{"word":"अंतरराष्ट्रीय सहयोग","question":"किन वैश्विक समस्याओं के लिए अंतरराष्ट्रीय सहयोग आवश्यक है, और सहमति बनाना इतना कठिन क्यों होता है?","examples":[{"en":"Climate threats, pandemics, and organized crime cross borders, so no country can manage them alone.","native":"जलवायु संबंधी खतरे, महामारियाँ और संगठित अपराध सीमाएँ पार करते हैं, इसलिए कोई देश अकेले उनसे नहीं निपट सकता।"},{"en":"Cooperation becomes difficult when governments face immediate domestic costs but benefits arrive much later.","native":"जब सरकारों को तुरंत घरेलू लागत उठानी पड़ती है लेकिन लाभ बहुत बाद में मिलते हैं, तब सहयोग कठिन हो जाता है।"},{"en":"Shared goals are more credible when wealthy countries contribute resources as well as promises.","native":"जब धनी देश वादों के साथ संसाधन भी देते हैं, तब साझा लक्ष्य अधिक विश्वसनीय लगते हैं।"}]},"es":{"word":"cooperación internacional","question":"¿Qué problemas mundiales requieren cooperación internacional y por qué es tan difícil llegar a acuerdos?","examples":[{"en":"Climate threats, pandemics, and organized crime cross borders, so no country can manage them alone.","native":"Las amenazas climáticas, las pandemias y el crimen organizado cruzan fronteras, por lo que ningún país puede afrontarlos solo."},{"en":"Cooperation becomes difficult when governments face immediate domestic costs but benefits arrive much later.","native":"La cooperación se vuelve difícil cuando los gobiernos afrontan costes nacionales inmediatos, pero los beneficios llegan mucho después."},{"en":"Shared goals are more credible when wealthy countries contribute resources as well as promises.","native":"Los objetivos compartidos son más creíbles cuando los países ricos aportan recursos además de promesas."}]},"zh":{"word":"国际合作","question":"哪些全球性问题需要国际合作，各国为何难以达成协议？","examples":[{"en":"Climate threats, pandemics, and organized crime cross borders, so no country can manage them alone.","native":"气候威胁、流行病和有组织犯罪都会跨越国界，因此任何国家都无法独自应对。"},{"en":"Cooperation becomes difficult when governments face immediate domestic costs but benefits arrive much later.","native":"当政府要立即承担国内成本，而收益很久以后才会出现时，合作就会变得困难。"},{"en":"Shared goals are more credible when wealthy countries contribute resources as well as promises.","native":"富裕国家不仅作出承诺，还投入资源时，共同目标会更可信。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'humanitarian aid', 'How can humanitarian aid meet urgent needs without creating dependency or ignoring local knowledge?', '{"te":{"word":"మానవతా సహాయం","question":"స్థానిక జ్ఞానాన్ని విస్మరించకుండా లేదా ఆధారపడే పరిస్థితిని సృష్టించకుండా మానవతా సహాయం అత్యవసర అవసరాలను ఎలా తీర్చగలదు?","examples":[{"en":"Emergency aid should reach people according to need rather than political loyalty or media attention.","native":"అత్యవసర సహాయం రాజకీయ విధేయత లేదా మీడియా దృష్టి ఆధారంగా కాకుండా అవసరం ఆధారంగా ప్రజలకు చేరాలి."},{"en":"Local organizations often understand communities better and should help decide how resources are used.","native":"స్థానిక సంస్థలకు తరచుగా సమాజాల గురించి మెరుగైన అవగాహన ఉంటుంది, కాబట్టి వనరులను ఎలా ఉపయోగించాలో నిర్ణయించడంలో అవి భాగస్వామ్యం కావాలి."},{"en":"Long-term recovery requires restoring livelihoods and public services, not distributing supplies forever.","native":"దీర్ఘకాలిక పునరుద్ధరణకు సరఫరాలను ఎప్పటికీ పంచడం కాకుండా జీవనోపాధులు మరియు ప్రజా సేవలను పునరుద్ధరించడం అవసరం."}]},"hi":{"word":"मानवीय सहायता","question":"मानवीय सहायता निर्भरता पैदा किए या स्थानीय ज्ञान की अनदेखी किए बिना तत्काल ज़रूरतें कैसे पूरी कर सकती है?","examples":[{"en":"Emergency aid should reach people according to need rather than political loyalty or media attention.","native":"आपातकालीन सहायता राजनीतिक निष्ठा या मीडिया के ध्यान के बजाय ज़रूरत के अनुसार लोगों तक पहुँचनी चाहिए।"},{"en":"Local organizations often understand communities better and should help decide how resources are used.","native":"स्थानीय संगठन अक्सर समुदायों को बेहतर समझते हैं और उन्हें यह तय करने में भाग लेना चाहिए कि संसाधनों का उपयोग कैसे हो।"},{"en":"Long-term recovery requires restoring livelihoods and public services, not distributing supplies forever.","native":"लंबी अवधि की बहाली के लिए आजीविका और सार्वजनिक सेवाएँ फिर से स्थापित करनी होती हैं, हमेशा सामग्री बाँटते रहना पर्याप्त नहीं है।"}]},"es":{"word":"ayuda humanitaria","question":"¿Cómo puede la ayuda humanitaria atender necesidades urgentes sin crear dependencia ni ignorar el conocimiento local?","examples":[{"en":"Emergency aid should reach people according to need rather than political loyalty or media attention.","native":"La ayuda de emergencia debería llegar a la gente según sus necesidades, no según su lealtad política ni la atención mediática."},{"en":"Local organizations often understand communities better and should help decide how resources are used.","native":"Las organizaciones locales suelen comprender mejor a las comunidades y deberían ayudar a decidir cómo se utilizan los recursos."},{"en":"Long-term recovery requires restoring livelihoods and public services, not distributing supplies forever.","native":"La recuperación a largo plazo exige restablecer los medios de vida y los servicios públicos, no repartir suministros para siempre."}]},"zh":{"word":"人道主义援助","question":"人道主义援助如何在不造成依赖或忽视当地知识的情况下满足紧急需求？","examples":[{"en":"Emergency aid should reach people according to need rather than political loyalty or media attention.","native":"紧急援助应根据需求送到人们手中，而不是取决于政治立场或媒体关注度。"},{"en":"Local organizations often understand communities better and should help decide how resources are used.","native":"当地组织往往更了解社区，因此应该参与决定资源的使用方式。"},{"en":"Long-term recovery requires restoring livelihoods and public services, not distributing supplies forever.","native":"长期恢复需要重建生计和公共服务，而不是永远发放物资。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'animal welfare', 'What responsibilities do humans have toward animals used for food, research, and entertainment?', '{"te":{"word":"జంతు సంక్షేమం","question":"ఆహారం, పరిశోధన మరియు వినోదం కోసం ఉపయోగించే జంతువుల పట్ల మనుషులకు ఎలాంటి బాధ్యతలు ఉన్నాయి?","examples":[{"en":"At a minimum, animals should be protected from unnecessary pain and kept in conditions suited to their needs.","native":"కనీసం, జంతువులను అనవసరమైన బాధ నుండి రక్షించి, వాటి అవసరాలకు తగిన పరిస్థితుల్లో ఉంచాలి."},{"en":"Scientific research involving animals should proceed only when no reliable alternative exists.","native":"నమ్మదగిన ప్రత్యామ్నాయం లేనప్పుడు మాత్రమే జంతువులతో కూడిన శాస్త్రీయ పరిశోధన కొనసాగాలి."},{"en":"Consumers can influence welfare standards by asking how products were produced, although clear labels are essential.","native":"ఉత్పత్తులు ఎలా తయారయ్యాయో అడగడం ద్వారా వినియోగదారులు జంతు సంక్షేమ ప్రమాణాలను ప్రభావితం చేయగలరు, అయితే స్పష్టమైన లేబుళ్లు అవసరం."}]},"hi":{"word":"पशु कल्याण","question":"भोजन, अनुसंधान और मनोरंजन के लिए उपयोग किए जाने वाले पशुओं के प्रति मनुष्यों की क्या ज़िम्मेदारियाँ हैं?","examples":[{"en":"At a minimum, animals should be protected from unnecessary pain and kept in conditions suited to their needs.","native":"कम से कम, पशुओं को अनावश्यक पीड़ा से बचाया जाना चाहिए और उनकी ज़रूरतों के अनुकूल परिस्थितियों में रखा जाना चाहिए।"},{"en":"Scientific research involving animals should proceed only when no reliable alternative exists.","native":"पशुओं पर आधारित वैज्ञानिक अनुसंधान तभी होना चाहिए जब कोई विश्वसनीय विकल्प उपलब्ध न हो।"},{"en":"Consumers can influence welfare standards by asking how products were produced, although clear labels are essential.","native":"उत्पाद कैसे बनाए गए, यह पूछकर उपभोक्ता कल्याण मानकों को प्रभावित कर सकते हैं, हालाँकि स्पष्ट लेबल आवश्यक हैं।"}]},"es":{"word":"bienestar animal","question":"¿Qué responsabilidades tenemos hacia los animales utilizados para la alimentación, la investigación y el entretenimiento?","examples":[{"en":"At a minimum, animals should be protected from unnecessary pain and kept in conditions suited to their needs.","native":"Como mínimo, los animales deberían estar protegidos del dolor innecesario y mantenerse en condiciones adecuadas para sus necesidades."},{"en":"Scientific research involving animals should proceed only when no reliable alternative exists.","native":"La investigación científica con animales solo debería realizarse cuando no exista una alternativa fiable."},{"en":"Consumers can influence welfare standards by asking how products were produced, although clear labels are essential.","native":"Los consumidores pueden influir en las normas de bienestar preguntando cómo se produjeron los productos, aunque es esencial un etiquetado claro."}]},"zh":{"word":"动物福利","question":"对于被用于食物、研究和娱乐的动物，人类负有哪些责任？","examples":[{"en":"At a minimum, animals should be protected from unnecessary pain and kept in conditions suited to their needs.","native":"至少应该保护动物免受不必要的痛苦，并为它们提供符合其需求的生活条件。"},{"en":"Scientific research involving animals should proceed only when no reliable alternative exists.","native":"只有在没有可靠替代方案时，才应该开展涉及动物的科学研究。"},{"en":"Consumers can influence welfare standards by asking how products were produced, although clear labels are essential.","native":"消费者可以通过询问产品的生产方式来影响福利标准，但清晰的标签必不可少。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'sustainable agriculture', 'How can farming produce enough food while protecting soil, water, and rural livelihoods?', '{"te":{"word":"సుస్థిర వ్యవసాయం","question":"వ్యవసాయం నేల, నీరు మరియు గ్రామీణ జీవనోపాధులను కాపాడుతూ తగినంత ఆహారాన్ని ఎలా ఉత్పత్తి చేయగలదు?","examples":[{"en":"Sustainable farming protects soil through crop rotation, careful grazing, and reduced dependence on harmful chemicals.","native":"పంట మార్పిడి, జాగ్రత్తగా పశువులను మేపడం మరియు హానికరమైన రసాయనాలపై ఆధారపడటాన్ని తగ్గించడం ద్వారా సుస్థిర వ్యవసాయం నేలను రక్షిస్తుంది."},{"en":"Farmers need financial support during the transition because environmental benefits may take several seasons to appear.","native":"పర్యావరణ ప్రయోజనాలు కనిపించడానికి అనేక పంట కాలాలు పట్టవచ్చు కాబట్టి మార్పు సమయంలో రైతులకు ఆర్థిక సహాయం అవసరం."},{"en":"Technology can reduce water and fertilizer use, but solutions must remain affordable for small farms.","native":"సాంకేతికత నీరు మరియు ఎరువుల వినియోగాన్ని తగ్గించగలదు, కానీ పరిష్కారాలు చిన్న రైతులకు అందుబాటు ధరలో ఉండాలి."}]},"hi":{"word":"टिकाऊ कृषि","question":"खेती मिट्टी, पानी और ग्रामीण आजीविका की रक्षा करते हुए पर्याप्त भोजन कैसे पैदा कर सकती है?","examples":[{"en":"Sustainable farming protects soil through crop rotation, careful grazing, and reduced dependence on harmful chemicals.","native":"टिकाऊ खेती फसल चक्र, नियंत्रित चराई और हानिकारक रसायनों पर कम निर्भरता के ज़रिए मिट्टी की रक्षा करती है।"},{"en":"Farmers need financial support during the transition because environmental benefits may take several seasons to appear.","native":"बदलाव के दौरान किसानों को वित्तीय सहायता चाहिए क्योंकि पर्यावरणीय लाभ दिखाई देने में कई मौसम लग सकते हैं।"},{"en":"Technology can reduce water and fertilizer use, but solutions must remain affordable for small farms.","native":"तकनीक पानी और उर्वरक का उपयोग कम कर सकती है, लेकिन समाधान छोटे किसानों की पहुँच में रहने चाहिए।"}]},"es":{"word":"agricultura sostenible","question":"¿Cómo puede la agricultura producir suficiente alimento y a la vez proteger el suelo, el agua y los medios de vida rurales?","examples":[{"en":"Sustainable farming protects soil through crop rotation, careful grazing, and reduced dependence on harmful chemicals.","native":"La agricultura sostenible protege el suelo mediante la rotación de cultivos, el pastoreo cuidadoso y una menor dependencia de productos químicos nocivos."},{"en":"Farmers need financial support during the transition because environmental benefits may take several seasons to appear.","native":"Los agricultores necesitan apoyo económico durante la transición porque los beneficios ambientales pueden tardar varias temporadas en aparecer."},{"en":"Technology can reduce water and fertilizer use, but solutions must remain affordable for small farms.","native":"La tecnología puede reducir el uso de agua y fertilizantes, pero las soluciones deben seguir siendo asequibles para las pequeñas explotaciones."}]},"zh":{"word":"可持续农业","question":"农业如何在生产充足食物的同时保护土壤、水资源和农村生计？","examples":[{"en":"Sustainable farming protects soil through crop rotation, careful grazing, and reduced dependence on harmful chemicals.","native":"可持续农业通过轮作、合理放牧和减少对有害化学品的依赖来保护土壤。"},{"en":"Farmers need financial support during the transition because environmental benefits may take several seasons to appear.","native":"转型期间农民需要资金支持，因为环境效益可能要经过几个种植季才会显现。"},{"en":"Technology can reduce water and fertilizer use, but solutions must remain affordable for small farms.","native":"技术可以减少水和肥料的使用，但解决方案必须让小型农场负担得起。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'food security', 'Why do people suffer hunger in a world that produces enough food, and which responses are most effective?', '{"te":{"word":"ఆహార భద్రత","question":"తగినంత ఆహారాన్ని ఉత్పత్తి చేసే ప్రపంచంలో కూడా ప్రజలు ఆకలితో ఎందుకు బాధపడుతున్నారు, ఏ పరిష్కారాలు అత్యంత ప్రభావవంతమైనవి?","examples":[{"en":"Food insecurity is often caused by poverty, conflict, and weak distribution rather than a total lack of food.","native":"ఆహార అభద్రత తరచుగా మొత్తం ఆహార కొరత కంటే పేదరికం, ఘర్షణ మరియు బలహీనమైన పంపిణీ వల్ల కలుగుతుంది."},{"en":"Reliable storage and transport can prevent harvests from being lost before they reach consumers.","native":"విశ్వసనీయమైన నిల్వ మరియు రవాణా పంటలు వినియోగదారులకు చేరకముందే నష్టపోకుండా నివారించగలవు."},{"en":"Governments should combine emergency assistance with policies that help families earn stable incomes.","native":"ప్రభుత్వాలు అత్యవసర సహాయాన్ని, కుటుంబాలు స్థిరమైన ఆదాయాన్ని సంపాదించడానికి సహాయపడే విధానాలతో కలపాలి."}]},"hi":{"word":"खाद्य सुरक्षा","question":"पर्याप्त भोजन पैदा करने वाली दुनिया में भी लोग भूख से क्यों पीड़ित हैं, और कौन-से उपाय सबसे प्रभावी हैं?","examples":[{"en":"Food insecurity is often caused by poverty, conflict, and weak distribution rather than a total lack of food.","native":"खाद्य असुरक्षा अक्सर भोजन की पूरी कमी के बजाय गरीबी, संघर्ष और कमज़ोर वितरण के कारण होती है।"},{"en":"Reliable storage and transport can prevent harvests from being lost before they reach consumers.","native":"भरोसेमंद भंडारण और परिवहन फसल को उपभोक्ताओं तक पहुँचने से पहले बर्बाद होने से बचा सकते हैं।"},{"en":"Governments should combine emergency assistance with policies that help families earn stable incomes.","native":"सरकारों को आपातकालीन सहायता के साथ ऐसी नीतियाँ जोड़नी चाहिए जो परिवारों को स्थिर आय कमाने में मदद करें।"}]},"es":{"word":"seguridad alimentaria","question":"¿Por qué hay personas que pasan hambre en un mundo que produce suficiente alimento y qué respuestas son más eficaces?","examples":[{"en":"Food insecurity is often caused by poverty, conflict, and weak distribution rather than a total lack of food.","native":"La inseguridad alimentaria suele deberse a la pobreza, los conflictos y una distribución deficiente, no a una falta total de alimentos."},{"en":"Reliable storage and transport can prevent harvests from being lost before they reach consumers.","native":"Un almacenamiento y un transporte fiables pueden evitar que las cosechas se pierdan antes de llegar a los consumidores."},{"en":"Governments should combine emergency assistance with policies that help families earn stable incomes.","native":"Los gobiernos deberían combinar la ayuda de emergencia con políticas que permitan a las familias obtener ingresos estables."}]},"zh":{"word":"粮食安全","question":"世界生产的食物足够，为何仍有人挨饿？哪些对策最有效？","examples":[{"en":"Food insecurity is often caused by poverty, conflict, and weak distribution rather than a total lack of food.","native":"粮食不安全往往源于贫困、冲突和分配不畅，而不是食物总量不足。"},{"en":"Reliable storage and transport can prevent harvests from being lost before they reach consumers.","native":"可靠的储存和运输可以防止收成在送达消费者之前损失。"},{"en":"Governments should combine emergency assistance with policies that help families earn stable incomes.","native":"政府应该把紧急援助与帮助家庭获得稳定收入的政策结合起来。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'water scarcity', 'What causes water scarcity, and how should limited water be shared among households, farming, and industry?', '{"te":{"word":"నీటి కొరత","question":"నీటి కొరతకు కారణాలు ఏమిటి, పరిమిత నీటిని గృహాలు, వ్యవసాయం మరియు పరిశ్రమల మధ్య ఎలా పంచాలి?","examples":[{"en":"Scarcity results not only from low rainfall but also from pollution, leaking systems, and excessive demand.","native":"కొరత తక్కువ వర్షపాతం వల్ల మాత్రమే కాకుండా కాలుష్యం, లీకవుతున్న వ్యవస్థలు మరియు అధిక డిమాండ్ వల్ల కూడా ఏర్పడుతుంది."},{"en":"Basic household needs should take priority, while heavy users pay prices that encourage conservation.","native":"ప్రాథమిక గృహ అవసరాలకు ప్రాధాన్యం ఇవ్వాలి, అధికంగా వినియోగించేవారు పొదుపును ప్రోత్సహించే ధరలు చెల్లించాలి."},{"en":"Regions can prepare for drought by reusing wastewater, protecting rivers, and choosing crops suited to local conditions.","native":"వ్యర్థ జలాలను తిరిగి ఉపయోగించడం, నదులను రక్షించడం మరియు స్థానిక పరిస్థితులకు సరిపోయే పంటలను ఎంచుకోవడం ద్వారా ప్రాంతాలు కరువుకు సిద్ధమవగలవు."}]},"hi":{"word":"जल संकट","question":"जल संकट किन कारणों से होता है, और सीमित पानी को घरों, खेती और उद्योग के बीच कैसे बाँटा जाना चाहिए?","examples":[{"en":"Scarcity results not only from low rainfall but also from pollution, leaking systems, and excessive demand.","native":"कमी केवल कम वर्षा से नहीं, बल्कि प्रदूषण, रिसती व्यवस्थाओं और अत्यधिक माँग से भी पैदा होती है।"},{"en":"Basic household needs should take priority, while heavy users pay prices that encourage conservation.","native":"घरों की बुनियादी ज़रूरतों को प्राथमिकता मिलनी चाहिए, जबकि अधिक उपयोग करने वालों से ऐसी कीमत ली जाए जो बचत को प्रोत्साहित करे।"},{"en":"Regions can prepare for drought by reusing wastewater, protecting rivers, and choosing crops suited to local conditions.","native":"क्षेत्र अपशिष्ट जल का दोबारा उपयोग करके, नदियों की रक्षा करके और स्थानीय परिस्थितियों के अनुकूल फसलें चुनकर सूखे की तैयारी कर सकते हैं।"}]},"es":{"word":"escasez de agua","question":"¿Qué causa la escasez de agua y cómo debería repartirse el agua limitada entre los hogares, la agricultura y la industria?","examples":[{"en":"Scarcity results not only from low rainfall but also from pollution, leaking systems, and excessive demand.","native":"La escasez no solo se debe a la falta de lluvia, sino también a la contaminación, las redes con fugas y una demanda excesiva."},{"en":"Basic household needs should take priority, while heavy users pay prices that encourage conservation.","native":"Las necesidades domésticas básicas deberían tener prioridad, mientras que los grandes usuarios pagarían precios que fomenten el ahorro."},{"en":"Regions can prepare for drought by reusing wastewater, protecting rivers, and choosing crops suited to local conditions.","native":"Las regiones pueden prepararse para la sequía reutilizando aguas residuales, protegiendo los ríos y eligiendo cultivos adaptados a las condiciones locales."}]},"zh":{"word":"水资源短缺","question":"水资源短缺由什么造成，有限的水应如何在家庭、农业和工业之间分配？","examples":[{"en":"Scarcity results not only from low rainfall but also from pollution, leaking systems, and excessive demand.","native":"水资源短缺不仅源于降雨不足，也来自污染、管网泄漏和过度需求。"},{"en":"Basic household needs should take priority, while heavy users pay prices that encourage conservation.","native":"基本家庭需求应优先得到满足，而用水大户应支付能够鼓励节约的价格。"},{"en":"Regions can prepare for drought by reusing wastewater, protecting rivers, and choosing crops suited to local conditions.","native":"各地区可以通过回用废水、保护河流和选择适合当地条件的作物来应对干旱。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'urban planning', 'What makes a city well planned for residents of different ages, abilities, and incomes?', '{"te":{"word":"పట్టణ ప్రణాళిక","question":"విభిన్న వయసులు, సామర్థ్యాలు మరియు ఆదాయాలు గల నివాసులకు ఒక నగరం చక్కగా ప్రణాళిక చేయబడిందని చెప్పడానికి ఏమి అవసరం?","examples":[{"en":"Good planning places homes, jobs, schools, and services close enough to reduce unnecessary travel.","native":"మంచి ప్రణాళిక ఇళ్లు, ఉద్యోగాలు, పాఠశాలలు మరియు సేవలను అనవసర ప్రయాణాన్ని తగ్గించేంత దగ్గరగా ఉంచుతుంది."},{"en":"Safe pavements, public spaces, and reliable transport allow children, older people, and disabled residents to participate.","native":"సురక్షితమైన కాలిబాటలు, బహిరంగ ప్రదేశాలు మరియు విశ్వసనీయ రవాణా పిల్లలు, వృద్ధులు మరియు దివ్యాంగ నివాసులు పాల్గొనేలా చేస్తాయి."},{"en":"Residents should influence major developments before decisions become too expensive to change.","native":"నిర్ణయాలను మార్చడం చాలా ఖరీదైనదిగా మారకముందే ప్రధాన నిర్మాణ ప్రాజెక్టులపై నివాసులు ప్రభావం చూపాలి."}]},"hi":{"word":"शहरी नियोजन","question":"अलग-अलग उम्र, क्षमताओं और आय वाले निवासियों के लिए किसी शहर को सुनियोजित क्या बनाता है?","examples":[{"en":"Good planning places homes, jobs, schools, and services close enough to reduce unnecessary travel.","native":"अच्छा नियोजन घरों, नौकरियों, स्कूलों और सेवाओं को इतना पास रखता है कि अनावश्यक यात्रा कम हो।"},{"en":"Safe pavements, public spaces, and reliable transport allow children, older people, and disabled residents to participate.","native":"सुरक्षित फुटपाथ, सार्वजनिक स्थान और भरोसेमंद परिवहन बच्चों, बुज़ुर्गों और दिव्यांग निवासियों को भाग लेने में सक्षम बनाते हैं।"},{"en":"Residents should influence major developments before decisions become too expensive to change.","native":"निर्णयों को बदलना बहुत महँगा होने से पहले निवासियों को बड़ी विकास परियोजनाओं पर प्रभाव डालने का अवसर मिलना चाहिए।"}]},"es":{"word":"planificación urbana","question":"¿Qué hace que una ciudad esté bien planificada para residentes de distintas edades, capacidades e ingresos?","examples":[{"en":"Good planning places homes, jobs, schools, and services close enough to reduce unnecessary travel.","native":"Una buena planificación sitúa las viviendas, los empleos, las escuelas y los servicios lo bastante cerca para reducir desplazamientos innecesarios."},{"en":"Safe pavements, public spaces, and reliable transport allow children, older people, and disabled residents to participate.","native":"Las aceras seguras, los espacios públicos y el transporte fiable permiten participar a niños, mayores y residentes con discapacidad."},{"en":"Residents should influence major developments before decisions become too expensive to change.","native":"Los residentes deberían influir en los grandes proyectos antes de que resulte demasiado caro cambiar las decisiones."}]},"zh":{"word":"城市规划","question":"怎样规划城市，才能满足不同年龄、能力和收入水平居民的需求？","examples":[{"en":"Good planning places homes, jobs, schools, and services close enough to reduce unnecessary travel.","native":"良好的规划让住宅、工作地点、学校和服务设施距离合理，从而减少不必要的出行。"},{"en":"Safe pavements, public spaces, and reliable transport allow children, older people, and disabled residents to participate.","native":"安全的人行道、公共空间和可靠的交通，使儿童、老年人和残障居民都能参与社会生活。"},{"en":"Residents should influence major developments before decisions become too expensive to change.","native":"居民应该在改变决定的代价变得过高之前，参与影响重大开发项目。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'infrastructure', 'How should governments decide which infrastructure projects to fund and maintain?', '{"te":{"word":"మౌలిక సదుపాయాలు","question":"ఏ మౌలిక సదుపాయాల ప్రాజెక్టులకు నిధులు ఇవ్వాలి మరియు వాటిని నిర్వహించాలి అనే విషయాన్ని ప్రభుత్వాలు ఎలా నిర్ణయించాలి?","examples":[{"en":"Maintenance is less visible than a new bridge, but neglecting it creates higher costs and serious safety risks.","native":"కొత్త వంతెనతో పోలిస్తే నిర్వహణ అంతగా కనిపించదు, కానీ దాన్ని నిర్లక్ష్యం చేయడం ఎక్కువ ఖర్చులకు మరియు తీవ్రమైన భద్రతా ప్రమాదాలకు దారితీస్తుంది."},{"en":"Projects should be judged by long-term public value rather than short-term political popularity.","native":"ప్రాజెక్టులను స్వల్పకాలిక రాజకీయ ప్రజాదరణతో కాకుండా దీర్ఘకాలిక ప్రజా విలువతో అంచనా వేయాలి."},{"en":"Transparent budgets and independent inspections make it harder for corruption to waste essential investment.","native":"పారదర్శక బడ్జెట్లు మరియు స్వతంత్ర తనిఖీల వల్ల కీలకమైన పెట్టుబడిని అవినీతి వృథా చేయడం మరింత కష్టమవుతుంది."}]},"hi":{"word":"बुनियादी ढाँचा","question":"सरकारों को यह कैसे तय करना चाहिए कि किन बुनियादी ढाँचा परियोजनाओं को धन और रखरखाव दिया जाए?","examples":[{"en":"Maintenance is less visible than a new bridge, but neglecting it creates higher costs and serious safety risks.","native":"रखरखाव नए पुल जितना दिखाई नहीं देता, लेकिन उसकी उपेक्षा अधिक लागत और गंभीर सुरक्षा जोखिम पैदा करती है।"},{"en":"Projects should be judged by long-term public value rather than short-term political popularity.","native":"परियोजनाओं का आकलन अल्पकालिक राजनीतिक लोकप्रियता के बजाय दीर्घकालिक सार्वजनिक मूल्य से होना चाहिए।"},{"en":"Transparent budgets and independent inspections make it harder for corruption to waste essential investment.","native":"पारदर्शी बजट और स्वतंत्र निरीक्षण भ्रष्टाचार के लिए आवश्यक निवेश को बर्बाद करना कठिन बनाते हैं।"}]},"es":{"word":"infraestructura","question":"¿Cómo deberían decidir los gobiernos qué proyectos de infraestructura financiar y mantener?","examples":[{"en":"Maintenance is less visible than a new bridge, but neglecting it creates higher costs and serious safety risks.","native":"El mantenimiento es menos visible que un puente nuevo, pero descuidarlo genera costes mayores y graves riesgos de seguridad."},{"en":"Projects should be judged by long-term public value rather than short-term political popularity.","native":"Los proyectos deberían evaluarse por su valor público a largo plazo, no por su popularidad política inmediata."},{"en":"Transparent budgets and independent inspections make it harder for corruption to waste essential investment.","native":"Los presupuestos transparentes y las inspecciones independientes dificultan que la corrupción desperdicie inversiones esenciales."}]},"zh":{"word":"基础设施","question":"政府应如何决定资助和维护哪些基础设施项目？","examples":[{"en":"Maintenance is less visible than a new bridge, but neglecting it creates higher costs and serious safety risks.","native":"维护工作不像新桥那样引人注目，但忽视维护会造成更高成本和严重安全风险。"},{"en":"Projects should be judged by long-term public value rather than short-term political popularity.","native":"评估项目应看其长期公共价值，而不是短期政治热度。"},{"en":"Transparent budgets and independent inspections make it harder for corruption to waste essential investment.","native":"透明的预算和独立检查能降低腐败浪费关键投资的可能性。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'energy conservation', 'Who should bear responsibility for reducing energy use: individuals, businesses, or governments?', '{"te":{"word":"శక్తి సంరక్షణ","question":"శక్తి వినియోగాన్ని తగ్గించే బాధ్యతను ఎవరు భరించాలి: వ్యక్తులా, వ్యాపారాలా, లేక ప్రభుత్వాలా?","examples":[{"en":"Households can reduce waste, but efficient buildings and appliances make responsible choices much easier.","native":"గృహాలు వృథాను తగ్గించగలవు, కానీ శక్తి సామర్థ్యం గల భవనాలు మరియు ఉపకరణాలు బాధ్యతాయుతమైన ఎంపికలను చాలా సులభం చేస్తాయి."},{"en":"Businesses should measure their energy use and invest first in changes that save both power and money.","native":"వ్యాపారాలు తమ శక్తి వినియోగాన్ని కొలిచి, విద్యుత్తు మరియు డబ్బు రెండింటినీ ఆదా చేసే మార్పుల్లో ముందుగా పెట్టుబడి పెట్టాలి."},{"en":"Governments can set firm standards while helping low-income families afford necessary improvements.","native":"ప్రభుత్వాలు కఠినమైన ప్రమాణాలను నిర్ణయిస్తూ, తక్కువ ఆదాయం గల కుటుంబాలు అవసరమైన మెరుగుదలల ఖర్చును భరించడానికి సహాయపడగలవు."}]},"hi":{"word":"ऊर्जा संरक्षण","question":"ऊर्जा का उपयोग घटाने की ज़िम्मेदारी किसे उठानी चाहिए: व्यक्तियों, व्यवसायों या सरकारों को?","examples":[{"en":"Households can reduce waste, but efficient buildings and appliances make responsible choices much easier.","native":"परिवार बर्बादी कम कर सकते हैं, लेकिन ऊर्जा-कुशल इमारतें और उपकरण ज़िम्मेदार विकल्प चुनना बहुत आसान बनाते हैं।"},{"en":"Businesses should measure their energy use and invest first in changes that save both power and money.","native":"व्यवसायों को अपने ऊर्जा उपयोग को मापना चाहिए और पहले उन बदलावों में निवेश करना चाहिए जो बिजली और पैसा दोनों बचाएँ।"},{"en":"Governments can set firm standards while helping low-income families afford necessary improvements.","native":"सरकारें सख्त मानक तय करने के साथ कम आय वाले परिवारों को आवश्यक सुधारों का खर्च उठाने में मदद कर सकती हैं।"}]},"es":{"word":"ahorro energético","question":"¿Quién debería asumir la responsabilidad de reducir el consumo de energía: las personas, las empresas o los gobiernos?","examples":[{"en":"Households can reduce waste, but efficient buildings and appliances make responsible choices much easier.","native":"Los hogares pueden reducir el desperdicio, pero los edificios y aparatos eficientes facilitan mucho las decisiones responsables."},{"en":"Businesses should measure their energy use and invest first in changes that save both power and money.","native":"Las empresas deberían medir su consumo energético e invertir primero en cambios que ahorren tanto energía como dinero."},{"en":"Governments can set firm standards while helping low-income families afford necessary improvements.","native":"Los gobiernos pueden establecer normas firmes y ayudar a las familias de bajos ingresos a costear las mejoras necesarias."}]},"zh":{"word":"节约能源","question":"减少能源使用的责任应该由个人、企业还是政府承担？","examples":[{"en":"Households can reduce waste, but efficient buildings and appliances make responsible choices much easier.","native":"家庭可以减少浪费，但节能建筑和电器能让负责任的选择容易得多。"},{"en":"Businesses should measure their energy use and invest first in changes that save both power and money.","native":"企业应该衡量能源使用情况，并优先投资于既省电又省钱的改进。"},{"en":"Governments can set firm standards while helping low-income families afford necessary improvements.","native":"政府可以制定严格标准，同时帮助低收入家庭负担必要的改造。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'biodiversity', 'Why is biodiversity important, and what sacrifices should society make to protect it?', '{"te":{"word":"జీవ వైవిధ్యం","question":"జీవ వైవిధ్యం ఎందుకు ముఖ్యం, దాన్ని రక్షించడానికి సమాజం ఎలాంటి త్యాగాలు చేయాలి?","examples":[{"en":"Biodiversity makes ecosystems more resilient because different species perform connected roles.","native":"వివిధ జాతులు పరస్పర సంబంధం ఉన్న పాత్రలను నిర్వహిస్తాయి కాబట్టి జీవ వైవిధ్యం పర్యావరణ వ్యవస్థలను మరింత తట్టుకునేలా చేస్తుంది."},{"en":"Protecting habitats may limit some development, but restoring nature later is often far more expensive.","native":"నివాస ప్రాంతాలను రక్షించడం కొంత అభివృద్ధిని పరిమితం చేయవచ్చు, కానీ తర్వాత ప్రకృతిని పునరుద్ధరించడం తరచుగా చాలా ఎక్కువ ఖర్చవుతుంది."},{"en":"Conservation succeeds when local communities share the economic benefits of healthy land and wildlife.","native":"ఆరోగ్యకరమైన భూమి మరియు వన్యప్రాణుల ఆర్థిక ప్రయోజనాలను స్థానిక సమాజాలు పంచుకున్నప్పుడు పరిరక్షణ విజయవంతమవుతుంది."}]},"hi":{"word":"जैव विविधता","question":"जैव विविधता क्यों महत्वपूर्ण है, और उसकी रक्षा के लिए समाज को कौन-से त्याग करने चाहिए?","examples":[{"en":"Biodiversity makes ecosystems more resilient because different species perform connected roles.","native":"जैव विविधता पारिस्थितिकी तंत्र को अधिक लचीला बनाती है क्योंकि अलग-अलग प्रजातियाँ आपस में जुड़ी भूमिकाएँ निभाती हैं।"},{"en":"Protecting habitats may limit some development, but restoring nature later is often far more expensive.","native":"आवासों की रक्षा कुछ विकास को सीमित कर सकती है, लेकिन बाद में प्रकृति को बहाल करना अक्सर बहुत अधिक महँगा पड़ता है।"},{"en":"Conservation succeeds when local communities share the economic benefits of healthy land and wildlife.","native":"संरक्षण तब सफल होता है जब स्थानीय समुदाय स्वस्थ भूमि और वन्यजीवों के आर्थिक लाभों में भागीदार हों।"}]},"es":{"word":"biodiversidad","question":"¿Por qué es importante la biodiversidad y qué sacrificios debería hacer la sociedad para protegerla?","examples":[{"en":"Biodiversity makes ecosystems more resilient because different species perform connected roles.","native":"La biodiversidad hace que los ecosistemas sean más resistentes porque las distintas especies desempeñan funciones conectadas."},{"en":"Protecting habitats may limit some development, but restoring nature later is often far more expensive.","native":"Proteger los hábitats puede limitar parte del desarrollo, pero restaurar la naturaleza más tarde suele resultar mucho más caro."},{"en":"Conservation succeeds when local communities share the economic benefits of healthy land and wildlife.","native":"La conservación tiene éxito cuando las comunidades locales comparten los beneficios económicos de unas tierras y una fauna sanas."}]},"zh":{"word":"生物多样性","question":"生物多样性为何重要，社会应该为保护它作出哪些牺牲？","examples":[{"en":"Biodiversity makes ecosystems more resilient because different species perform connected roles.","native":"生物多样性使生态系统更有韧性，因为不同物种承担着相互关联的作用。"},{"en":"Protecting habitats may limit some development, but restoring nature later is often far more expensive.","native":"保护栖息地可能限制某些开发，但日后恢复自然往往要昂贵得多。"},{"en":"Conservation succeeds when local communities share the economic benefits of healthy land and wildlife.","native":"当地社区能够分享健康土地和野生动物带来的经济利益时，保护工作才会成功。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'deforestation', 'What drives deforestation, and which policies can protect forests without depriving local communities of their livelihoods?', '{"te":{"word":"అడవుల నరికివేత","question":"అడవుల నరికివేతకు కారణాలు ఏమిటి, స్థానిక సమాజాల జీవనోపాధిని దెబ్బతీయకుండా అడవులను ఏ విధానాలు రక్షించగలవు?","examples":[{"en":"Forests are often cleared for agriculture, mining, and roads because their long-term value is missing from market prices.","native":"వ్యవసాయం, గనుల తవ్వకం మరియు రహదారుల కోసం అడవులను తరచుగా తొలగిస్తారు, ఎందుకంటే వాటి దీర్ఘకాలిక విలువ మార్కెట్ ధరల్లో కనిపించదు."},{"en":"Protecting forests works better when local and Indigenous communities have secure rights to manage the land.","native":"స్థానిక మరియు ఆదివాసీ సమాజాలకు భూమిని నిర్వహించడానికి సురక్షితమైన హక్కులు ఉన్నప్పుడు అడవుల రక్షణ మెరుగ్గా పనిచేస్తుంది."},{"en":"Companies should trace supply chains so that consumers are not unknowingly funding illegal clearance.","native":"వినియోగదారులు తెలియకుండానే అక్రమంగా అడవులను తొలగించడానికి నిధులు అందించకుండా కంపెనీలు సరఫరా గొలుసులను వాటి మూలం వరకు గుర్తించాలి."}]},"hi":{"word":"वनों की कटाई","question":"वनों की कटाई किन कारणों से होती है, और कौन-सी नीतियाँ स्थानीय समुदायों की आजीविका छीने बिना जंगलों की रक्षा कर सकती हैं?","examples":[{"en":"Forests are often cleared for agriculture, mining, and roads because their long-term value is missing from market prices.","native":"जंगल अक्सर खेती, खनन और सड़कों के लिए साफ़ किए जाते हैं क्योंकि उनका दीर्घकालिक मूल्य बाज़ार की कीमतों में शामिल नहीं होता।"},{"en":"Protecting forests works better when local and Indigenous communities have secure rights to manage the land.","native":"जब स्थानीय और आदिवासी समुदायों को भूमि के प्रबंधन के सुरक्षित अधिकार मिलते हैं, तब वन संरक्षण बेहतर काम करता है।"},{"en":"Companies should trace supply chains so that consumers are not unknowingly funding illegal clearance.","native":"कंपनियों को आपूर्ति शृंखलाओं के स्रोत का पता लगाना चाहिए ताकि उपभोक्ता अनजाने में अवैध कटाई को धन न दें।"}]},"es":{"word":"deforestación","question":"¿Qué impulsa la deforestación y qué políticas pueden proteger los bosques sin privar a las comunidades locales de sus medios de vida?","examples":[{"en":"Forests are often cleared for agriculture, mining, and roads because their long-term value is missing from market prices.","native":"Los bosques se talan a menudo para la agricultura, la minería y las carreteras porque su valor a largo plazo no aparece en los precios de mercado."},{"en":"Protecting forests works better when local and Indigenous communities have secure rights to manage the land.","native":"La protección de los bosques funciona mejor cuando las comunidades locales e indígenas tienen derechos seguros para gestionar la tierra."},{"en":"Companies should trace supply chains so that consumers are not unknowingly funding illegal clearance.","native":"Las empresas deberían rastrear las cadenas de suministro para que los consumidores no financien sin saberlo la tala ilegal."}]},"zh":{"word":"森林砍伐","question":"哪些因素推动了森林砍伐，哪些政策能在不剥夺当地社区生计的情况下保护森林？","examples":[{"en":"Forests are often cleared for agriculture, mining, and roads because their long-term value is missing from market prices.","native":"森林经常因农业、采矿和修路而被清除，因为其长期价值没有体现在市场价格中。"},{"en":"Protecting forests works better when local and Indigenous communities have secure rights to manage the land.","native":"当地和原住民社区拥有稳定的土地管理权时，森林保护会更有效。"},{"en":"Companies should trace supply chains so that consumers are not unknowingly funding illegal clearance.","native":"企业应该追踪供应链，以免消费者在不知情的情况下资助非法砍伐。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'ocean conservation', 'Which actions are most urgently needed to protect oceans from pollution and overuse?', '{"te":{"word":"సముద్ర పరిరక్షణ","question":"కాలుష్యం మరియు మితిమీరిన వినియోగం నుంచి సముద్రాలను రక్షించడానికి అత్యవసరంగా ఏ చర్యలు అవసరం?","examples":[{"en":"Reducing single-use plastic helps, but lost fishing gear and industrial waste also require strict controls.","native":"ఒక్కసారి వాడే ప్లాస్టిక్‌ను తగ్గించడం సహాయపడుతుంది, కానీ పోయిన చేపల వలలు మరియు పారిశ్రామిక వ్యర్థాలపై కూడా కఠిన నియంత్రణలు అవసరం."},{"en":"Marine reserves allow damaged ecosystems to recover when boundaries are enforced and nearby fishers are consulted.","native":"సరిహద్దులను అమలు చేసి, సమీపంలోని మత్స్యకారులను సంప్రదించినప్పుడు సముద్ర రక్షిత ప్రాంతాలు దెబ్బతిన్న పర్యావరణ వ్యవస్థలు కోలుకోవడానికి అవకాశం ఇస్తాయి."},{"en":"Fishing limits must follow scientific evidence so that today''s income does not destroy tomorrow''s catch.","native":"నేటి ఆదాయం రేపటి చేపల వేటను నాశనం చేయకుండా చేపల వేట పరిమితులు శాస్త్రీయ ఆధారాలను అనుసరించాలి."}]},"hi":{"word":"महासागर संरक्षण","question":"महासागरों को प्रदूषण और अत्यधिक उपयोग से बचाने के लिए किन कदमों की सबसे तत्काल आवश्यकता है?","examples":[{"en":"Reducing single-use plastic helps, but lost fishing gear and industrial waste also require strict controls.","native":"एक बार इस्तेमाल होने वाले प्लास्टिक को कम करना मददगार है, लेकिन खोए हुए मछली पकड़ने के उपकरण और औद्योगिक कचरे पर भी कड़ा नियंत्रण चाहिए।"},{"en":"Marine reserves allow damaged ecosystems to recover when boundaries are enforced and nearby fishers are consulted.","native":"जब सीमाएँ लागू की जाती हैं और आसपास के मछुआरों से सलाह ली जाती है, तब समुद्री संरक्षित क्षेत्र क्षतिग्रस्त पारिस्थितिकी तंत्र को ठीक होने देते हैं।"},{"en":"Fishing limits must follow scientific evidence so that today''s income does not destroy tomorrow''s catch.","native":"मछली पकड़ने की सीमाएँ वैज्ञानिक प्रमाण पर आधारित होनी चाहिए ताकि आज की कमाई के लिए भविष्य की मछलियों का भंडार नष्ट न हो।"}]},"es":{"word":"conservación de los océanos","question":"¿Qué medidas se necesitan con mayor urgencia para proteger los océanos de la contaminación y la sobreexplotación?","examples":[{"en":"Reducing single-use plastic helps, but lost fishing gear and industrial waste also require strict controls.","native":"Reducir el plástico de un solo uso ayuda, pero los aparejos de pesca perdidos y los residuos industriales también requieren controles estrictos."},{"en":"Marine reserves allow damaged ecosystems to recover when boundaries are enforced and nearby fishers are consulted.","native":"Las reservas marinas permiten que los ecosistemas dañados se recuperen cuando se respetan sus límites y se consulta a los pescadores cercanos."},{"en":"Fishing limits must follow scientific evidence so that today''s income does not destroy tomorrow''s catch.","native":"Los límites de pesca deben seguir las pruebas científicas para que los ingresos de hoy no destruyan las capturas de mañana."}]},"zh":{"word":"海洋保护","question":"要保护海洋免受污染和过度利用，目前最迫切需要采取哪些行动？","examples":[{"en":"Reducing single-use plastic helps, but lost fishing gear and industrial waste also require strict controls.","native":"减少一次性塑料会有所帮助，但遗失的渔具和工业废物也需要严格管控。"},{"en":"Marine reserves allow damaged ecosystems to recover when boundaries are enforced and nearby fishers are consulted.","native":"在严格执行保护区边界并征求附近渔民意见时，海洋保护区能让受损生态系统恢复。"},{"en":"Fishing limits must follow scientific evidence so that today''s income does not destroy tomorrow''s catch.","native":"捕捞限额必须遵循科学证据，不能让今天的收入毁掉明天的渔获。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'waste management', 'How should cities reduce waste rather than merely moving it to landfills or exporting it elsewhere?', '{"te":{"word":"వ్యర్థాల నిర్వహణ","question":"వ్యర్థాలను కేవలం పూడ్చివేత ప్రాంతాలకు తరలించడం లేదా వేరే చోటుకు ఎగుమతి చేయడం కాకుండా నగరాలు వాటిని ఎలా తగ్గించాలి?","examples":[{"en":"Manufacturers should design products that last longer and can be repaired with affordable parts.","native":"తయారీదారులు ఎక్కువకాలం మన్నే మరియు అందుబాటు ధరలో విడిభాగాలతో మరమ్మతు చేయగల ఉత్పత్తులను రూపొందించాలి."},{"en":"Separate collection makes recycling more effective, but residents need simple rules and reliable services.","native":"వ్యర్థాలను వేర్వేరుగా సేకరించడం రీసైక్లింగ్‌ను మరింత ప్రభావవంతం చేస్తుంది, కానీ నివాసులకు సరళమైన నియమాలు మరియు విశ్వసనీయ సేవలు అవసరం."},{"en":"Charging for unnecessary packaging would encourage businesses to prevent waste before it is created.","native":"అనవసరమైన ప్యాకేజింగ్‌పై రుసుము విధించడం వ్యర్థం ఏర్పడకముందే దాన్ని నివారించడానికి వ్యాపారాలను ప్రోత్సహిస్తుంది."}]},"hi":{"word":"कचरा प्रबंधन","question":"शहरों को कचरा केवल भराव स्थलों पर भेजने या कहीं और निर्यात करने के बजाय उसे कैसे कम करना चाहिए?","examples":[{"en":"Manufacturers should design products that last longer and can be repaired with affordable parts.","native":"निर्माताओं को ऐसे उत्पाद बनाने चाहिए जो अधिक समय चलें और जिनकी मरम्मत किफ़ायती पुर्ज़ों से हो सके।"},{"en":"Separate collection makes recycling more effective, but residents need simple rules and reliable services.","native":"अलग-अलग संग्रह से पुनर्चक्रण अधिक प्रभावी होता है, लेकिन निवासियों को सरल नियम और भरोसेमंद सेवाएँ चाहिए।"},{"en":"Charging for unnecessary packaging would encourage businesses to prevent waste before it is created.","native":"अनावश्यक पैकेजिंग पर शुल्क लगाने से व्यवसाय कचरा पैदा होने से पहले ही उसे रोकने के लिए प्रोत्साहित होंगे।"}]},"es":{"word":"gestión de residuos","question":"¿Cómo deberían las ciudades reducir los residuos en vez de limitarse a llevarlos a vertederos o exportarlos a otros lugares?","examples":[{"en":"Manufacturers should design products that last longer and can be repaired with affordable parts.","native":"Los fabricantes deberían diseñar productos que duren más y puedan repararse con piezas asequibles."},{"en":"Separate collection makes recycling more effective, but residents need simple rules and reliable services.","native":"La recogida separada hace más eficaz el reciclaje, pero los residentes necesitan normas sencillas y servicios fiables."},{"en":"Charging for unnecessary packaging would encourage businesses to prevent waste before it is created.","native":"Cobrar por los envases innecesarios animaría a las empresas a evitar los residuos antes de que se generen."}]},"zh":{"word":"废物管理","question":"城市应如何真正减少废物，而不是仅仅将其运往填埋场或出口到其他地方？","examples":[{"en":"Manufacturers should design products that last longer and can be repaired with affordable parts.","native":"制造商应该设计使用寿命更长、能用价格合理的零件维修的产品。"},{"en":"Separate collection makes recycling more effective, but residents need simple rules and reliable services.","native":"分类收集能提高回收效率，但居民需要简单的规则和可靠的服务。"},{"en":"Charging for unnecessary packaging would encourage businesses to prevent waste before it is created.","native":"对不必要的包装收费，会促使企业从源头防止废物产生。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'corporate responsibility', 'Should companies be responsible only for following the law and making a profit, or also for their wider impact?', '{"te":{"word":"కార్పొరేట్ బాధ్యత","question":"కంపెనీలు కేవలం చట్టాన్ని పాటించడం మరియు లాభం పొందడానికే బాధ్యత వహించాలా, లేక తమ విస్తృత ప్రభావానికి కూడా బాధ్యత వహించాలా?","examples":[{"en":"Following the law is a minimum standard, especially where regulations are weak or poorly enforced.","native":"చట్టాలను పాటించడం కనీస ప్రమాణం మాత్రమే, ముఖ్యంగా నియంత్రణలు బలహీనంగా లేదా సరిగా అమలు కాని చోట."},{"en":"Companies should publish measurable social and environmental targets and allow independent checks of their claims.","native":"కంపెనీలు కొలవగల సామాజిక మరియు పర్యావరణ లక్ష్యాలను ప్రచురించి, తమ వాదనలను స్వతంత్రంగా తనిఖీ చేయడానికి అనుమతించాలి."},{"en":"Responsible decisions may reduce short-term profit, but they can protect workers, communities, and long-term trust.","native":"బాధ్యతాయుత నిర్ణయాలు స్వల్పకాలిక లాభాన్ని తగ్గించవచ్చు, కానీ అవి కార్మికులు, సమాజాలు మరియు దీర్ఘకాలిక నమ్మకాన్ని రక్షించగలవు."}]},"hi":{"word":"कॉरपोरेट ज़िम्मेदारी","question":"क्या कंपनियों की ज़िम्मेदारी केवल कानून का पालन करना और लाभ कमाना है, या अपने व्यापक प्रभाव की भी है?","examples":[{"en":"Following the law is a minimum standard, especially where regulations are weak or poorly enforced.","native":"कानून का पालन न्यूनतम मानक है, खासकर वहाँ जहाँ नियम कमज़ोर हैं या ठीक से लागू नहीं होते।"},{"en":"Companies should publish measurable social and environmental targets and allow independent checks of their claims.","native":"कंपनियों को मापने योग्य सामाजिक और पर्यावरणीय लक्ष्य प्रकाशित करने चाहिए और अपने दावों की स्वतंत्र जाँच की अनुमति देनी चाहिए।"},{"en":"Responsible decisions may reduce short-term profit, but they can protect workers, communities, and long-term trust.","native":"ज़िम्मेदार निर्णय अल्पकालिक लाभ घटा सकते हैं, लेकिन वे कर्मचारियों, समुदायों और दीर्घकालिक भरोसे की रक्षा कर सकते हैं।"}]},"es":{"word":"responsabilidad empresarial","question":"¿Deberían las empresas limitarse a cumplir la ley y obtener beneficios, o ser también responsables de su impacto más amplio?","examples":[{"en":"Following the law is a minimum standard, especially where regulations are weak or poorly enforced.","native":"Cumplir la ley es un requisito mínimo, especialmente donde la normativa es débil o se aplica mal."},{"en":"Companies should publish measurable social and environmental targets and allow independent checks of their claims.","native":"Las empresas deberían publicar objetivos sociales y ambientales medibles y permitir la verificación independiente de sus afirmaciones."},{"en":"Responsible decisions may reduce short-term profit, but they can protect workers, communities, and long-term trust.","native":"Las decisiones responsables pueden reducir los beneficios a corto plazo, pero protegen a los trabajadores, las comunidades y la confianza a largo plazo."}]},"zh":{"word":"企业责任","question":"企业只需负责守法和盈利，还是也应对自身更广泛的影响负责？","examples":[{"en":"Following the law is a minimum standard, especially where regulations are weak or poorly enforced.","native":"遵守法律只是最低标准，尤其是在法规薄弱或执行不力的地方。"},{"en":"Companies should publish measurable social and environmental targets and allow independent checks of their claims.","native":"企业应该公布可衡量的社会和环境目标，并允许独立机构核查其声明。"},{"en":"Responsible decisions may reduce short-term profit, but they can protect workers, communities, and long-term trust.","native":"负责任的决定可能减少短期利润，但能保护劳动者、社区和长期信任。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'ethical consumption', 'Can shopping choices meaningfully improve labour and environmental conditions, or must change mainly come from governments and businesses?', '{"te":{"word":"నైతిక వినియోగం","question":"కొనుగోలు ఎంపికలు కార్మిక మరియు పర్యావరణ పరిస్థితులను గణనీయంగా మెరుగుపరచగలవా, లేక మార్పు ప్రధానంగా ప్రభుత్వాలు మరియు వ్యాపారాల నుంచే రావాలా?","examples":[{"en":"Ethical products are difficult to choose when labels are confusing and responsible options cost much more.","native":"లేబుళ్లు గందరగోళంగా ఉండి, బాధ్యతాయుతమైన ఎంపికలకు చాలా ఎక్కువ ఖర్చయ్యేటప్పుడు నైతిక ఉత్పత్తులను ఎంచుకోవడం కష్టం."},{"en":"Consumers can signal demand, but governments must prevent harmful products from competing through unfairly low prices.","native":"వినియోగదారులు డిమాండ్‌ను సూచించగలరు, కానీ అన్యాయంగా తక్కువ ధరల ద్వారా హానికరమైన ఉత్పత్తులు పోటీ పడకుండా ప్రభుత్వాలు నిరోధించాలి."},{"en":"Buying fewer durable goods may have a greater effect than constantly replacing items with greener versions.","native":"వస్తువులను పర్యావరణ అనుకూలమైన కొత్త రూపాలతో నిరంతరం మార్చడం కంటే తక్కువ సంఖ్యలో మన్నికైన వస్తువులను కొనడం ఎక్కువ ప్రభావం చూపవచ్చు."}]},"hi":{"word":"नैतिक उपभोग","question":"क्या खरीदारी के विकल्प श्रम और पर्यावरण की स्थितियों में सार्थक सुधार ला सकते हैं, या बदलाव मुख्य रूप से सरकारों और व्यवसायों से आना चाहिए?","examples":[{"en":"Ethical products are difficult to choose when labels are confusing and responsible options cost much more.","native":"जब लेबल उलझाने वाले हों और ज़िम्मेदार विकल्प बहुत महँगे हों, तब नैतिक उत्पाद चुनना कठिन होता है।"},{"en":"Consumers can signal demand, but governments must prevent harmful products from competing through unfairly low prices.","native":"उपभोक्ता माँग का संकेत दे सकते हैं, लेकिन सरकारों को हानिकारक उत्पादों को अनुचित रूप से कम कीमतों के सहारे प्रतिस्पर्धा करने से रोकना चाहिए।"},{"en":"Buying fewer durable goods may have a greater effect than constantly replacing items with greener versions.","native":"सामान को लगातार अधिक पर्यावरण-अनुकूल संस्करणों से बदलने की तुलना में कम लेकिन टिकाऊ वस्तुएँ खरीदना अधिक प्रभावी हो सकता है।"}]},"es":{"word":"consumo ético","question":"¿Pueden las decisiones de compra mejorar de forma significativa las condiciones laborales y ambientales, o debe venir el cambio principalmente de los gobiernos y las empresas?","examples":[{"en":"Ethical products are difficult to choose when labels are confusing and responsible options cost much more.","native":"Es difícil elegir productos éticos cuando las etiquetas son confusas y las opciones responsables cuestan mucho más."},{"en":"Consumers can signal demand, but governments must prevent harmful products from competing through unfairly low prices.","native":"Los consumidores pueden señalar la demanda, pero los gobiernos deben impedir que los productos dañinos compitan mediante precios injustamente bajos."},{"en":"Buying fewer durable goods may have a greater effect than constantly replacing items with greener versions.","native":"Comprar menos productos duraderos puede tener más efecto que sustituir constantemente los artículos por versiones más ecológicas."}]},"zh":{"word":"道德消费","question":"购物选择能否切实改善劳动和环境条件，还是改变主要必须来自政府和企业？","examples":[{"en":"Ethical products are difficult to choose when labels are confusing and responsible options cost much more.","native":"当标签令人困惑、负责任的选择又贵得多时，人们很难挑选符合道德标准的产品。"},{"en":"Consumers can signal demand, but governments must prevent harmful products from competing through unfairly low prices.","native":"消费者可以表达需求，但政府必须防止有害产品凭借不公平的低价参与竞争。"},{"en":"Buying fewer durable goods may have a greater effect than constantly replacing items with greener versions.","native":"少买一些耐用商品，可能比不断用更环保的版本替换现有物品更有效。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'gig economy', 'Does the gig economy offer useful flexibility, or does it transfer too much risk from companies to workers?', '{"te":{"word":"గిగ్ ఆర్థిక వ్యవస్థ","question":"గిగ్ ఆర్థిక వ్యవస్థ ఉపయోగకరమైన అనువుదనాన్ని అందిస్తుందా, లేక కంపెనీల నుంచి కార్మికులకు మరీ ఎక్కువ ప్రమాదాన్ని బదిలీ చేస్తుందా?","examples":[{"en":"Flexible hours can help some workers, but unpredictable income makes rent and family expenses difficult to plan.","native":"అనువైన పని గంటలు కొంతమంది కార్మికులకు సహాయపడవచ్చు, కానీ ఊహించలేని ఆదాయం వల్ల అద్దె మరియు కుటుంబ ఖర్చులను ప్రణాళిక చేయడం కష్టమవుతుంది."},{"en":"Platforms control prices and access to customers, so describing every worker as fully independent can be misleading.","native":"వేదికలు ధరలను మరియు కస్టమర్లను చేరుకునే అవకాశాన్ని నియంత్రిస్తాయి, కాబట్టి ప్రతి కార్మికుడిని పూర్తిగా స్వతంత్రుడిగా వర్ణించడం తప్పుదోవ పట్టించవచ్చు."},{"en":"Basic protections such as insurance, transparent ratings, and a fair appeal process need not eliminate flexibility.","native":"బీమా, పారదర్శక రేటింగ్‌లు మరియు న్యాయమైన అప్పీల్ ప్రక్రియ వంటి ప్రాథమిక రక్షణలు అనువుదనాన్ని తొలగించాల్సిన అవసరం లేదు."}]},"hi":{"word":"गिग अर्थव्यवस्था","question":"क्या गिग अर्थव्यवस्था उपयोगी लचीलापन देती है, या कंपनियों से बहुत अधिक जोखिम श्रमिकों पर डाल देती है?","examples":[{"en":"Flexible hours can help some workers, but unpredictable income makes rent and family expenses difficult to plan.","native":"लचीले काम के घंटे कुछ श्रमिकों की मदद कर सकते हैं, लेकिन अनिश्चित आय से किराए और पारिवारिक खर्चों की योजना बनाना कठिन होता है।"},{"en":"Platforms control prices and access to customers, so describing every worker as fully independent can be misleading.","native":"प्लेटफ़ॉर्म कीमतों और ग्राहकों तक पहुँच को नियंत्रित करते हैं, इसलिए हर श्रमिक को पूरी तरह स्वतंत्र बताना भ्रामक हो सकता है।"},{"en":"Basic protections such as insurance, transparent ratings, and a fair appeal process need not eliminate flexibility.","native":"बीमा, पारदर्शी रेटिंग और निष्पक्ष अपील प्रक्रिया जैसी बुनियादी सुरक्षाओं के लिए लचीलापन समाप्त करना आवश्यक नहीं है।"}]},"es":{"word":"economía de plataformas","question":"¿Ofrece la economía de plataformas una flexibilidad útil o transfiere demasiado riesgo de las empresas a los trabajadores?","examples":[{"en":"Flexible hours can help some workers, but unpredictable income makes rent and family expenses difficult to plan.","native":"La flexibilidad horaria puede ayudar a algunos trabajadores, pero unos ingresos imprevisibles dificultan planificar el alquiler y los gastos familiares."},{"en":"Platforms control prices and access to customers, so describing every worker as fully independent can be misleading.","native":"Las plataformas controlan los precios y el acceso a los clientes, por lo que describir a cada trabajador como totalmente independiente puede ser engañoso."},{"en":"Basic protections such as insurance, transparent ratings, and a fair appeal process need not eliminate flexibility.","native":"Las protecciones básicas, como seguros, calificaciones transparentes y un proceso de apelación justo, no tienen por qué eliminar la flexibilidad."}]},"zh":{"word":"零工经济","question":"零工经济是提供了有用的灵活性，还是把过多风险从企业转嫁给了劳动者？","examples":[{"en":"Flexible hours can help some workers, but unpredictable income makes rent and family expenses difficult to plan.","native":"灵活的工时可以帮助一些劳动者，但不稳定的收入使房租和家庭开支难以规划。"},{"en":"Platforms control prices and access to customers, so describing every worker as fully independent can be misleading.","native":"平台控制价格和接触客户的机会，因此把每位劳动者都称为完全独立可能会误导人。"},{"en":"Basic protections such as insurance, transparent ratings, and a fair appeal process need not eliminate flexibility.","native":"保险、透明评分和公平申诉程序等基本保障并不一定会牺牲灵活性。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'job satisfaction', 'What contributes most to job satisfaction, and how much responsibility belongs to employers and employees?', '{"te":{"word":"ఉద్యోగ సంతృప్తి","question":"ఉద్యోగ సంతృప్తికి ఎక్కువగా దోహదపడేది ఏమిటి, దానికి యజమానులు మరియు ఉద్యోగులు ఎంతవరకు బాధ్యత వహించాలి?","examples":[{"en":"Fair pay matters, but people also value respect, useful work, and some control over how tasks are completed.","native":"న్యాయమైన వేతనం ముఖ్యం, కానీ ప్రజలు గౌరవం, ఉపయోగకరమైన పని మరియు పనులను ఎలా పూర్తి చేయాలనే విషయంలో కొంత నియంత్రణకు కూడా విలువ ఇస్తారు."},{"en":"Managers improve satisfaction when expectations are clear and good performance receives specific recognition.","native":"అంచనాలు స్పష్టంగా ఉండి, మంచి పనితీరుకు నిర్దిష్టమైన గుర్తింపు లభించినప్పుడు మేనేజర్లు ఉద్యోగ సంతృప్తిని మెరుగుపరుస్తారు."},{"en":"Employees can seek growth and better communication, although they cannot repair a consistently harmful culture alone.","native":"ఉద్యోగులు ఎదుగుదల మరియు మెరుగైన సమాచార మార్పిడిని కోరవచ్చు, అయితే నిరంతరం హానికరంగా ఉండే సంస్కృతిని వారు ఒంటరిగా సరిచేయలేరు."}]},"hi":{"word":"नौकरी से संतुष्टि","question":"नौकरी से संतुष्टि में सबसे अधिक योगदान किसका होता है, और नियोक्ताओं तथा कर्मचारियों की कितनी ज़िम्मेदारी है?","examples":[{"en":"Fair pay matters, but people also value respect, useful work, and some control over how tasks are completed.","native":"उचित वेतन महत्वपूर्ण है, लेकिन लोग सम्मान, उपयोगी काम और कार्य पूरे करने के तरीके पर कुछ नियंत्रण को भी महत्व देते हैं।"},{"en":"Managers improve satisfaction when expectations are clear and good performance receives specific recognition.","native":"जब अपेक्षाएँ स्पष्ट हों और अच्छे प्रदर्शन को विशेष पहचान मिले, तब प्रबंधक संतुष्टि बढ़ाते हैं।"},{"en":"Employees can seek growth and better communication, although they cannot repair a consistently harmful culture alone.","native":"कर्मचारी विकास और बेहतर संवाद की कोशिश कर सकते हैं, हालाँकि वे लगातार हानिकारक संस्कृति को अकेले नहीं सुधार सकते।"}]},"es":{"word":"satisfacción laboral","question":"¿Qué contribuye más a la satisfacción laboral y cuánta responsabilidad corresponde a empleadores y empleados?","examples":[{"en":"Fair pay matters, but people also value respect, useful work, and some control over how tasks are completed.","native":"Un salario justo importa, pero la gente también valora el respeto, el trabajo útil y cierto control sobre cómo se realizan las tareas."},{"en":"Managers improve satisfaction when expectations are clear and good performance receives specific recognition.","native":"Los responsables mejoran la satisfacción cuando las expectativas son claras y el buen rendimiento recibe un reconocimiento específico."},{"en":"Employees can seek growth and better communication, although they cannot repair a consistently harmful culture alone.","native":"Los empleados pueden buscar crecimiento y una mejor comunicación, aunque no pueden reparar por sí solos una cultura constantemente dañina."}]},"zh":{"word":"工作满意度","question":"哪些因素对工作满意度影响最大，雇主和员工各自应承担多少责任？","examples":[{"en":"Fair pay matters, but people also value respect, useful work, and some control over how tasks are completed.","native":"公平的薪酬很重要，但人们也重视尊重、有意义的工作以及对任务完成方式的一定自主权。"},{"en":"Managers improve satisfaction when expectations are clear and good performance receives specific recognition.","native":"当要求明确且良好表现得到具体认可时，管理者能够提高员工的满意度。"},{"en":"Employees can seek growth and better communication, although they cannot repair a consistently harmful culture alone.","native":"员工可以寻求成长和更好的沟通，但无法独自修复长期有害的企业文化。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'career change', 'When is a career change a wise choice, and what preparation can reduce the risk?', '{"te":{"word":"వృత్తి మార్పు","question":"వృత్తిని మార్చడం ఎప్పుడు తెలివైన ఎంపిక అవుతుంది, ఏ సిద్ధత ప్రమాదాన్ని తగ్గించగలదు?","examples":[{"en":"Changing careers may be sensible when dissatisfaction reflects the field itself rather than one difficult workplace.","native":"అసంతృప్తి ఒక కష్టమైన కార్యాలయం వల్ల కాకుండా ఆ రంగం వల్లనే వస్తే వృత్తిని మార్చడం సమంజసం కావచ్చు."},{"en":"Testing a new direction through courses, volunteering, or part-time work can reveal whether expectations are realistic.","native":"కోర్సులు, స్వచ్ఛంద సేవ లేదా పార్ట్‌టైమ్ పని ద్వారా కొత్త దిశను పరీక్షించడం అంచనాలు వాస్తవికంగా ఉన్నాయో లేదో వెల్లడించగలదు."},{"en":"A financial reserve and transferable skills make the transition safer without guaranteeing immediate success.","native":"ఆర్థిక నిల్వ మరియు బదిలీ చేయగల నైపుణ్యాలు తక్షణ విజయానికి హామీ ఇవ్వకపోయినా మార్పును సురక్షితంగా చేస్తాయి."}]},"hi":{"word":"करियर में बदलाव","question":"करियर बदलना कब समझदारी भरा विकल्प होता है, और कौन-सी तैयारी जोखिम घटा सकती है?","examples":[{"en":"Changing careers may be sensible when dissatisfaction reflects the field itself rather than one difficult workplace.","native":"जब असंतोष किसी एक कठिन कार्यस्थल के बजाय पूरे क्षेत्र से जुड़ा हो, तब करियर बदलना समझदारी हो सकती है।"},{"en":"Testing a new direction through courses, volunteering, or part-time work can reveal whether expectations are realistic.","native":"पाठ्यक्रम, स्वयंसेवा या अंशकालिक काम के ज़रिए नई दिशा आज़माने से पता चल सकता है कि अपेक्षाएँ यथार्थवादी हैं या नहीं।"},{"en":"A financial reserve and transferable skills make the transition safer without guaranteeing immediate success.","native":"आर्थिक बचत और दूसरे क्षेत्रों में काम आने वाले कौशल तत्काल सफलता की गारंटी दिए बिना बदलाव को अधिक सुरक्षित बनाते हैं।"}]},"es":{"word":"cambio de carrera","question":"¿Cuándo es sensato cambiar de carrera y qué preparación puede reducir el riesgo?","examples":[{"en":"Changing careers may be sensible when dissatisfaction reflects the field itself rather than one difficult workplace.","native":"Cambiar de carrera puede ser sensato cuando la insatisfacción se debe al propio sector y no a un único lugar de trabajo difícil."},{"en":"Testing a new direction through courses, volunteering, or part-time work can reveal whether expectations are realistic.","native":"Probar una nueva dirección mediante cursos, voluntariado o trabajo a tiempo parcial puede revelar si las expectativas son realistas."},{"en":"A financial reserve and transferable skills make the transition safer without guaranteeing immediate success.","native":"Un colchón financiero y las habilidades transferibles hacen la transición más segura sin garantizar un éxito inmediato."}]},"zh":{"word":"职业转型","question":"什么时候转行是明智的选择，哪些准备可以降低风险？","examples":[{"en":"Changing careers may be sensible when dissatisfaction reflects the field itself rather than one difficult workplace.","native":"如果不满来自行业本身，而不只是某个糟糕的工作场所，那么转行可能是合理的。"},{"en":"Testing a new direction through courses, volunteering, or part-time work can reveal whether expectations are realistic.","native":"通过课程、志愿服务或兼职工作尝试新方向，可以判断自己的期待是否现实。"},{"en":"A financial reserve and transferable skills make the transition safer without guaranteeing immediate success.","native":"资金储备和可迁移技能能使转型更安全，但不能保证立刻成功。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('B2', 'productivity', 'How should productivity be measured without encouraging overwork or sacrificing quality?', '{"te":{"word":"ఉత్పాదకత","question":"అధిక పనిని ప్రోత్సహించకుండా లేదా నాణ్యతను త్యాగం చేయకుండా ఉత్పాదకతను ఎలా కొలవాలి?","examples":[{"en":"Counting hours rewards visible activity, whereas useful measures focus on completed work and its quality.","native":"పని గంటలను లెక్కించడం బయటకు కనిపించే కార్యకలాపానికి ప్రతిఫలం ఇస్తుంది, అయితే ఉపయోగకరమైన కొలమానాలు పూర్తయిన పని మరియు దాని నాణ్యతపై దృష్టి పెడతాయి."},{"en":"Teams often become more productive after removing unnecessary meetings rather than asking everyone to work faster.","native":"ప్రతి ఒక్కరూ వేగంగా పనిచేయాలని అడగడం కంటే అనవసర సమావేశాలను తొలగించిన తర్వాత బృందాలు తరచుగా మరింత ఉత్పాదకంగా మారతాయి."},{"en":"Sustainable productivity includes rest, learning, and maintenance because exhausted people create costly mistakes.","native":"అలసిపోయిన వ్యక్తులు ఖరీదైన తప్పులు చేస్తారు కాబట్టి సుస్థిర ఉత్పాదకతలో విశ్రాంతి, అభ్యాసం మరియు నిర్వహణ కూడా ఉంటాయి."}]},"hi":{"word":"उत्पादकता","question":"अत्यधिक काम को बढ़ावा दिए या गुणवत्ता से समझौता किए बिना उत्पादकता को कैसे मापा जाना चाहिए?","examples":[{"en":"Counting hours rewards visible activity, whereas useful measures focus on completed work and its quality.","native":"घंटे गिनना दिखाई देने वाली गतिविधि को पुरस्कृत करता है, जबकि उपयोगी माप पूरे हुए काम और उसकी गुणवत्ता पर ध्यान देते हैं।"},{"en":"Teams often become more productive after removing unnecessary meetings rather than asking everyone to work faster.","native":"सबको तेज़ काम करने के लिए कहने के बजाय अनावश्यक बैठकें हटाने पर टीमें अक्सर अधिक उत्पादक बनती हैं।"},{"en":"Sustainable productivity includes rest, learning, and maintenance because exhausted people create costly mistakes.","native":"टिकाऊ उत्पादकता में आराम, सीखना और रखरखाव शामिल हैं क्योंकि थके हुए लोग महँगी गलतियाँ करते हैं।"}]},"es":{"word":"productividad","question":"¿Cómo debería medirse la productividad sin fomentar el exceso de trabajo ni sacrificar la calidad?","examples":[{"en":"Counting hours rewards visible activity, whereas useful measures focus on completed work and its quality.","native":"Contar horas premia la actividad visible, mientras que las medidas útiles se centran en el trabajo terminado y su calidad."},{"en":"Teams often become more productive after removing unnecessary meetings rather than asking everyone to work faster.","native":"Los equipos suelen volverse más productivos al eliminar reuniones innecesarias en vez de pedir a todos que trabajen más rápido."},{"en":"Sustainable productivity includes rest, learning, and maintenance because exhausted people create costly mistakes.","native":"La productividad sostenible incluye descanso, aprendizaje y mantenimiento porque las personas agotadas cometen errores costosos."}]},"zh":{"word":"生产效率","question":"应如何衡量生产效率，才能既不鼓励过度工作，也不牺牲质量？","examples":[{"en":"Counting hours rewards visible activity, whereas useful measures focus on completed work and its quality.","native":"计算工时会奖励表面上的忙碌，而有用的衡量方式关注完成的工作及其质量。"},{"en":"Teams often become more productive after removing unnecessary meetings rather than asking everyone to work faster.","native":"与其要求所有人工作得更快，团队在取消不必要的会议后往往会更高效。"},{"en":"Sustainable productivity includes rest, learning, and maintenance because exhausted people create costly mistakes.","native":"可持续的生产效率包括休息、学习和维护，因为疲惫的人会犯下代价高昂的错误。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'globalization', 'Discuss the effects of globalization on local cultures.', '{"te":{"word":"ప్రపంచీకరణ","question":"స్థానిక సంస్కృతులపై ప్రపంచీకరణ ప్రభావాలను చర్చించండి.","examples":[{"en":"Globalization can widen cultural exchange, yet the commercial platforms that carry it often privilege languages and traditions with the greatest purchasing power.","native":"ప్రపంచీకరణ సాంస్కృతిక మార్పిడిని విస్తరించగలదు, అయినప్పటికీ దాన్ని మోసుకెళ్లే వాణిజ్య వేదికలు తరచూ అత్యధిక కొనుగోలు శక్తి ఉన్న భాషలు మరియు సంప్రదాయాలకు ప్రాధాన్యం ఇస్తాయి."},{"en":"Local communities are not merely passive victims: they adapt imported influences, producing hybrid forms that complicate any simple opposition between authentic and foreign culture.","native":"స్థానిక సమాజాలు కేవలం నిష్క్రియాత్మక బాధితులు కావు: అవి దిగుమతి చేసుకున్న ప్రభావాలను తమకు అనుగుణంగా మార్చుకొని, ప్రామాణిక సంస్కృతి మరియు విదేశీ సంస్కృతి మధ్య సరళమైన వ్యతిరేకతను సంక్లిష్టం చేసే మిశ్రమ రూపాలను సృష్టిస్తాయి."},{"en":"Policies that fund minority-language education and give creators control over their heritage can preserve cultural diversity without attempting to freeze traditions in time.","native":"అల్పసంఖ్యాక భాషా విద్యకు నిధులు సమకూర్చి, సృష్టికర్తలకు వారి వారసత్వంపై నియంత్రణ ఇచ్చే విధానాలు సంప్రదాయాలను కాలంలో గడ్డకట్టించకుండా సాంస్కృతిక వైవిధ్యాన్ని కాపాడగలవు."}]},"hi":{"word":"वैश्वीकरण","question":"स्थानीय संस्कृतियों पर वैश्वीकरण के प्रभावों पर चर्चा कीजिए।","examples":[{"en":"Globalization can widen cultural exchange, yet the commercial platforms that carry it often privilege languages and traditions with the greatest purchasing power.","native":"वैश्वीकरण सांस्कृतिक आदान-प्रदान का विस्तार कर सकता है, फिर भी उसे आगे बढ़ाने वाले व्यावसायिक मंच अक्सर सबसे अधिक क्रय-शक्ति वाली भाषाओं और परंपराओं को प्राथमिकता देते हैं।"},{"en":"Local communities are not merely passive victims: they adapt imported influences, producing hybrid forms that complicate any simple opposition between authentic and foreign culture.","native":"स्थानीय समुदाय केवल निष्क्रिय पीड़ित नहीं होते: वे बाहर से आए प्रभावों को अपने अनुसार ढालकर ऐसे मिश्रित रूप बनाते हैं जो प्रामाणिक और विदेशी संस्कृति के बीच किसी सरल विरोध को जटिल बना देते हैं।"},{"en":"Policies that fund minority-language education and give creators control over their heritage can preserve cultural diversity without attempting to freeze traditions in time.","native":"अल्पसंख्यक भाषाओं की शिक्षा को वित्तपोषित करने और रचनाकारों को अपनी विरासत पर नियंत्रण देने वाली नीतियाँ परंपराओं को समय में स्थिर किए बिना सांस्कृतिक विविधता बचा सकती हैं।"}]},"es":{"word":"globalización","question":"Analiza los efectos de la globalización en las culturas locales.","examples":[{"en":"Globalization can widen cultural exchange, yet the commercial platforms that carry it often privilege languages and traditions with the greatest purchasing power.","native":"La globalización puede ampliar el intercambio cultural, pero las plataformas comerciales que lo difunden suelen privilegiar las lenguas y tradiciones con mayor poder adquisitivo."},{"en":"Local communities are not merely passive victims: they adapt imported influences, producing hybrid forms that complicate any simple opposition between authentic and foreign culture.","native":"Las comunidades locales no son meras víctimas pasivas: adaptan influencias importadas y crean formas híbridas que complican cualquier oposición simple entre cultura auténtica y extranjera."},{"en":"Policies that fund minority-language education and give creators control over their heritage can preserve cultural diversity without attempting to freeze traditions in time.","native":"Las políticas que financian la educación en lenguas minoritarias y dan a los creadores control sobre su patrimonio pueden preservar la diversidad cultural sin pretender congelar las tradiciones en el tiempo."}]},"zh":{"word":"全球化","question":"讨论全球化对本土文化的影响。","examples":[{"en":"Globalization can widen cultural exchange, yet the commercial platforms that carry it often privilege languages and traditions with the greatest purchasing power.","native":"全球化能够扩大文化交流，但承载这种交流的商业平台往往偏重购买力最强的语言与传统。"},{"en":"Local communities are not merely passive victims: they adapt imported influences, producing hybrid forms that complicate any simple opposition between authentic and foreign culture.","native":"本地社群并非只是被动的受害者；它们会调整外来影响，创造出混合形式，使本土文化与外来文化之间的简单对立变得复杂。"},{"en":"Policies that fund minority-language education and give creators control over their heritage can preserve cultural diversity without attempting to freeze traditions in time.","native":"资助少数语言教育并让创作者掌控自身文化遗产的政策，可以保护文化多样性，而无须试图把传统凝固在某个时代。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'artificial intelligence', 'How do you think artificial intelligence will change our lives?', '{"te":{"word":"కృత్రిమ మేధస్సు","question":"కృత్రిమ మేధస్సు మన జీవితాలను ఎలా మారుస్తుందని మీరు అనుకుంటున్నారు?","examples":[{"en":"Artificial intelligence is likely to redistribute tasks rather than simply eliminate occupations, making access to retraining and bargaining power decisive in determining who benefits.","native":"కృత్రిమ మేధస్సు ఉద్యోగాలను పూర్తిగా తొలగించడం కంటే పనులను పునర్విభజించే అవకాశం ఎక్కువ; అందువల్ల పునశ్శిక్షణకు ప్రాప్యత మరియు చర్చా శక్తి ఎవరు లాభపడతారో నిర్ణయించడంలో కీలకం అవుతాయి."},{"en":"When predictive systems influence medicine, credit, or policing, their apparent efficiency must be weighed against opaque reasoning and the danger of reproducing historical discrimination.","native":"అంచనా వ్యవస్థలు వైద్యం, రుణం లేదా పోలీసింగ్‌ను ప్రభావితం చేసినప్పుడు, వాటి కనిపించే సమర్థతను అపారదర్శక తర్కం మరియు చారిత్రక వివక్షను పునరుత్పత్తి చేసే ప్రమాదంతో తూకం వేయాలి."},{"en":"The deepest change may be epistemic: as synthetic content becomes ubiquitous, societies will need new ways to establish authorship, evidence, and justified trust.","native":"అత్యంత లోతైన మార్పు జ్ఞాన సంబంధమైనదై ఉండవచ్చు: కృత్రిమంగా సృష్టించిన విషయం సర్వవ్యాప్తమవుతున్న కొద్దీ, రచయితత్వం, ఆధారం మరియు సమర్థనీయ విశ్వాసాన్ని నిర్ధారించడానికి సమాజాలకు కొత్త మార్గాలు అవసరమవుతాయి."}]},"hi":{"word":"कृत्रिम बुद्धिमत्ता","question":"आपको क्या लगता है कि कृत्रिम बुद्धिमत्ता हमारे जीवन को कैसे बदलेगी?","examples":[{"en":"Artificial intelligence is likely to redistribute tasks rather than simply eliminate occupations, making access to retraining and bargaining power decisive in determining who benefits.","native":"कृत्रिम बुद्धिमत्ता संभवतः पेशों को पूरी तरह समाप्त करने के बजाय कार्यों का पुनर्वितरण करेगी, इसलिए पुनःप्रशिक्षण तक पहुँच और सौदेबाज़ी की शक्ति यह तय करने में निर्णायक होंगी कि लाभ किसे मिलता है।"},{"en":"When predictive systems influence medicine, credit, or policing, their apparent efficiency must be weighed against opaque reasoning and the danger of reproducing historical discrimination.","native":"जब पूर्वानुमान प्रणालियाँ चिकित्सा, ऋण या पुलिस व्यवस्था को प्रभावित करती हैं, तब उनकी दिखाई देने वाली दक्षता को अपारदर्शी तर्क और ऐतिहासिक भेदभाव दोहराने के खतरे के विरुद्ध तौलना चाहिए।"},{"en":"The deepest change may be epistemic: as synthetic content becomes ubiquitous, societies will need new ways to establish authorship, evidence, and justified trust.","native":"सबसे गहरा बदलाव ज्ञान-संबंधी हो सकता है: कृत्रिम रूप से निर्मित सामग्री के सर्वव्यापी होने पर समाजों को लेखकत्व, प्रमाण और तर्कसंगत विश्वास स्थापित करने के नए तरीके चाहिए होंगे।"}]},"es":{"word":"inteligencia artificial","question":"¿Cómo crees que la inteligencia artificial cambiará nuestras vidas?","examples":[{"en":"Artificial intelligence is likely to redistribute tasks rather than simply eliminate occupations, making access to retraining and bargaining power decisive in determining who benefits.","native":"Es probable que la inteligencia artificial redistribuya tareas en vez de limitarse a eliminar ocupaciones, por lo que el acceso a la reconversión y el poder de negociación serán decisivos para determinar quién se beneficia."},{"en":"When predictive systems influence medicine, credit, or policing, their apparent efficiency must be weighed against opaque reasoning and the danger of reproducing historical discrimination.","native":"Cuando los sistemas predictivos influyen en la medicina, el crédito o la actividad policial, su aparente eficiencia debe sopesarse frente a un razonamiento opaco y al riesgo de reproducir discriminaciones históricas."},{"en":"The deepest change may be epistemic: as synthetic content becomes ubiquitous, societies will need new ways to establish authorship, evidence, and justified trust.","native":"El cambio más profundo puede ser epistémico: a medida que el contenido sintético se vuelva omnipresente, las sociedades necesitarán nuevas formas de establecer autoría, evidencia y confianza justificada."}]},"zh":{"word":"人工智能","question":"你认为人工智能将如何改变我们的生活？","examples":[{"en":"Artificial intelligence is likely to redistribute tasks rather than simply eliminate occupations, making access to retraining and bargaining power decisive in determining who benefits.","native":"人工智能更可能重新分配任务，而非简单消灭职业，因此能否获得再培训以及议价能力的强弱，将决定谁能从中受益。"},{"en":"When predictive systems influence medicine, credit, or policing, their apparent efficiency must be weighed against opaque reasoning and the danger of reproducing historical discrimination.","native":"当预测系统影响医疗、信贷或警务时，必须把其表面的效率与推理不透明、复制历史歧视的风险一并权衡。"},{"en":"The deepest change may be epistemic: as synthetic content becomes ubiquitous, societies will need new ways to establish authorship, evidence, and justified trust.","native":"最深刻的变化或许发生在知识层面：随着合成内容无处不在，社会需要新的方法来确认作者身份、证据与有正当依据的信任。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'motivation', 'What motivates people to achieve their goals?', '{"te":{"word":"ప్రేరణ","question":"వారి లక్ష్యాలను చేరుకోవడానికి ప్రజలకు ఏమి ప్రేరణ ఇస్తుంది?","examples":[{"en":"Motivation often emerges after action has begun, which suggests that routines and attainable milestones can be more reliable than waiting for inspiration.","native":"చర్య ప్రారంభమైన తర్వాతే ప్రేరణ తరచూ ఉద్భవిస్తుంది; కాబట్టి స్ఫూర్తి కోసం వేచి ఉండటం కంటే దినచర్యలు మరియు సాధ్యమైన మైలురాళ్లు మరింత నమ్మదగినవని ఇది సూచిస్తుంది."},{"en":"External rewards may initiate effort, but they can weaken intrinsic commitment when people begin to interpret a valued activity solely as a transaction.","native":"బాహ్య బహుమతులు ప్రయత్నాన్ని ప్రారంభించవచ్చు, కానీ విలువైన కార్యకలాపాన్ని ప్రజలు కేవలం లావాదేవీగా అర్థం చేసుకోవడం మొదలుపెట్టినప్పుడు అవి అంతర్గత నిబద్ధతను బలహీనపరచగలవు."},{"en":"Long-term persistence depends on connecting a goal to identity and meaning while designing feedback that makes distant progress psychologically visible.","native":"దీర్ఘకాలిక పట్టుదల ఒక లక్ష్యాన్ని గుర్తింపు మరియు అర్థంతో అనుసంధానించడంతో పాటు, దూరంగా ఉన్న పురోగతిని మానసికంగా కనిపించేలా చేసే అభిప్రాయ వ్యవస్థను రూపొందించడంపై ఆధారపడుతుంది."}]},"hi":{"word":"प्रेरणा","question":"लोगों को उनके लक्ष्य हासिल करने के लिए क्या प्रेरित करता है?","examples":[{"en":"Motivation often emerges after action has begun, which suggests that routines and attainable milestones can be more reliable than waiting for inspiration.","native":"प्रेरणा अक्सर काम शुरू होने के बाद पैदा होती है, जिससे पता चलता है कि दिनचर्या और हासिल किए जा सकने वाले पड़ाव प्रेरणा की प्रतीक्षा से अधिक भरोसेमंद हो सकते हैं।"},{"en":"External rewards may initiate effort, but they can weaken intrinsic commitment when people begin to interpret a valued activity solely as a transaction.","native":"बाहरी पुरस्कार प्रयास शुरू करा सकते हैं, लेकिन जब लोग किसी मूल्यवान गतिविधि को केवल लेन-देन समझने लगते हैं, तब वे आंतरिक प्रतिबद्धता कमज़ोर कर सकते हैं।"},{"en":"Long-term persistence depends on connecting a goal to identity and meaning while designing feedback that makes distant progress psychologically visible.","native":"दीर्घकालिक दृढ़ता किसी लक्ष्य को पहचान और अर्थ से जोड़ने के साथ ऐसी प्रतिक्रिया व्यवस्था बनाने पर निर्भर करती है जो दूर की प्रगति को मनोवैज्ञानिक रूप से दिखाई दे।"}]},"es":{"word":"motivación","question":"¿Qué motiva a las personas a alcanzar sus metas?","examples":[{"en":"Motivation often emerges after action has begun, which suggests that routines and attainable milestones can be more reliable than waiting for inspiration.","native":"La motivación suele surgir después de comenzar a actuar, lo que sugiere que las rutinas y los hitos alcanzables pueden ser más fiables que esperar la inspiración."},{"en":"External rewards may initiate effort, but they can weaken intrinsic commitment when people begin to interpret a valued activity solely as a transaction.","native":"Las recompensas externas pueden iniciar el esfuerzo, pero debilitan el compromiso intrínseco cuando las personas empiezan a interpretar una actividad valiosa únicamente como una transacción."},{"en":"Long-term persistence depends on connecting a goal to identity and meaning while designing feedback that makes distant progress psychologically visible.","native":"La perseverancia a largo plazo depende de vincular el objetivo con la identidad y el sentido, y de diseñar una retroalimentación que haga psicológicamente visible el progreso lejano."}]},"zh":{"word":"动力","question":"是什么激励人们实现目标？","examples":[{"en":"Motivation often emerges after action has begun, which suggests that routines and attainable milestones can be more reliable than waiting for inspiration.","native":"动力往往在行动开始后才出现，这说明日常惯例和可实现的阶段目标，可能比等待灵感更为可靠。"},{"en":"External rewards may initiate effort, but they can weaken intrinsic commitment when people begin to interpret a valued activity solely as a transaction.","native":"外部奖励或许能促使人开始努力，但当人们把一项有价值的活动仅仅理解为交易时，奖励也会削弱内在投入。"},{"en":"Long-term persistence depends on connecting a goal to identity and meaning while designing feedback that makes distant progress psychologically visible.","native":"长期坚持既取决于把目标与身份认同和意义联系起来，也取决于设计反馈，让遥远的进展在心理上变得可见。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'urbanization', 'What are the main benefits and challenges of urbanization?', '{"te":{"word":"పట్టణీకరణ","question":"పట్టణీకరణ వల్ల కలిగే ప్రధాన ప్రయోజనాలు మరియు సవాళ్లు ఏమిటి?","examples":[{"en":"Dense cities can raise productivity and reduce per-capita resource use, provided that housing and transport policy prevent those gains from being captured by landowners alone.","native":"సాంద్ర నగరాలు ఉత్పాదకతను పెంచి తలసరి వనరుల వినియోగాన్ని తగ్గించగలవు; అయితే గృహనిర్మాణ మరియు రవాణా విధానం ఆ లాభాలను భూయజమానులు మాత్రమే స్వాధీనం చేసుకోకుండా నిరోధించాలి."},{"en":"Informal settlements reveal a paradox of urban growth: newcomers gain proximity to opportunity while remaining excluded from secure tenure and basic services.","native":"అనధికారిక నివాసాలు పట్టణ వృద్ధిలోని వైరుధ్యాన్ని చూపుతాయి: కొత్తగా వచ్చినవారు అవకాశాలకు దగ్గరవుతారు, కానీ సురక్షిత నివాస హక్కు మరియు ప్రాథమిక సేవల నుంచి వెలివేయబడుతూనే ఉంటారు."},{"en":"Successful planning must coordinate climate resilience, public space, and mixed-income housing rather than treating congestion or pollution as isolated technical problems.","native":"విజయవంతమైన ప్రణాళిక రద్దీ లేదా కాలుష్యాన్ని వేరువేరు సాంకేతిక సమస్యలుగా చూడకుండా, వాతావరణ స్థైర్యం, బహిరంగ ప్రదేశం మరియు మిశ్రమ ఆదాయ గృహనిర్మాణాన్ని సమన్వయం చేయాలి."}]},"hi":{"word":"शहरीकरण","question":"शहरीकरण के मुख्य लाभ और चुनौतियाँ क्या हैं?","examples":[{"en":"Dense cities can raise productivity and reduce per-capita resource use, provided that housing and transport policy prevent those gains from being captured by landowners alone.","native":"सघन शहर उत्पादकता बढ़ा और प्रति व्यक्ति संसाधन-उपयोग घटा सकते हैं, बशर्ते आवास तथा परिवहन नीति इन लाभों पर केवल भू-स्वामियों का कब्ज़ा न होने दे।"},{"en":"Informal settlements reveal a paradox of urban growth: newcomers gain proximity to opportunity while remaining excluded from secure tenure and basic services.","native":"अनौपचारिक बस्तियाँ शहरी विकास का विरोधाभास दिखाती हैं: नए निवासी अवसरों के निकट पहुँचते हैं, फिर भी सुरक्षित आवास-अधिकार और बुनियादी सेवाओं से वंचित रहते हैं।"},{"en":"Successful planning must coordinate climate resilience, public space, and mixed-income housing rather than treating congestion or pollution as isolated technical problems.","native":"सफल नियोजन को भीड़भाड़ या प्रदूषण को अलग-अलग तकनीकी समस्याएँ मानने के बजाय जलवायु सहनशीलता, सार्वजनिक स्थान और मिश्रित-आय आवास में समन्वय करना चाहिए।"}]},"es":{"word":"urbanización","question":"¿Cuáles son los principales beneficios y desafíos de la urbanización?","examples":[{"en":"Dense cities can raise productivity and reduce per-capita resource use, provided that housing and transport policy prevent those gains from being captured by landowners alone.","native":"Las ciudades densas pueden elevar la productividad y reducir el uso de recursos por habitante, siempre que las políticas de vivienda y transporte impidan que esos beneficios queden únicamente en manos de los propietarios del suelo."},{"en":"Informal settlements reveal a paradox of urban growth: newcomers gain proximity to opportunity while remaining excluded from secure tenure and basic services.","native":"Los asentamientos informales revelan una paradoja del crecimiento urbano: los recién llegados se acercan a las oportunidades, pero siguen excluidos de una tenencia segura y de servicios básicos."},{"en":"Successful planning must coordinate climate resilience, public space, and mixed-income housing rather than treating congestion or pollution as isolated technical problems.","native":"Una planificación acertada debe coordinar la resiliencia climática, el espacio público y la vivienda para distintos niveles de ingreso, en lugar de tratar la congestión o la contaminación como problemas técnicos aislados."}]},"zh":{"word":"城市化","question":"城市化的主要益处和挑战是什么？","examples":[{"en":"Dense cities can raise productivity and reduce per-capita resource use, provided that housing and transport policy prevent those gains from being captured by landowners alone.","native":"高密度城市能够提高生产率并减少人均资源消耗，前提是住房与交通政策防止这些收益仅被土地所有者攫取。"},{"en":"Informal settlements reveal a paradox of urban growth: newcomers gain proximity to opportunity while remaining excluded from secure tenure and basic services.","native":"非正规住区揭示了城市增长的悖论：新来者更接近机会，却仍被排除在稳定居住权与基本服务之外。"},{"en":"Successful planning must coordinate climate resilience, public space, and mixed-income housing rather than treating congestion or pollution as isolated technical problems.","native":"成功的规划必须统筹气候韧性、公共空间与混合收入住房，而不是把拥堵或污染当作彼此孤立的技术问题。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'privacy', 'Is privacy possible in the digital age? Give your views.', '{"te":{"word":"గోప్యత","question":"డిజిటల్ యుగంలో గోప్యత సాధ్యమేనా? మీ అభిప్రాయాలు తెలపండి.","examples":[{"en":"Digital privacy is not absolute secrecy but meaningful control over which data are collected, how they are combined, and which decisions they are allowed to influence.","native":"డిజిటల్ గోప్యత అంటే సంపూర్ణ రహస్యత కాదు; ఏ డేటాను సేకరిస్తారు, దాన్ని ఎలా కలుపుతారు, అది ఏ నిర్ణయాలను ప్రభావితం చేయడానికి అనుమతిస్తారు అన్న వాటిపై అర్థవంతమైన నియంత్రణ."},{"en":"Consent offers little protection when essential services require acceptance of complex terms and data can be inferred about people who never disclosed them.","native":"అవసరమైన సేవలు సంక్లిష్ట నిబంధనలను అంగీకరించాల్సిందేనని చేసినప్పుడు, అలాగే ఎప్పుడూ వెల్లడించని వ్యక్తుల గురించిన డేటాను కూడా ఊహించగలిగినప్పుడు సమ్మతి తక్కువ రక్షణనే అందిస్తుంది."},{"en":"Effective safeguards therefore require data minimization, independent oversight, and enforceable rights to access, correction, and deletion rather than stronger passwords alone.","native":"కాబట్టి సమర్థవంతమైన రక్షణలకు బలమైన పాస్‌వర్డ్‌లు మాత్రమే కాకుండా డేటా కనిష్ఠీకరణ, స్వతంత్ర పర్యవేక్షణ మరియు ప్రాప్యత, సవరణ, తొలగింపుకు అమలు చేయగల హక్కులు అవసరం."}]},"hi":{"word":"निजता","question":"क्या डिजिटल युग में निजता संभव है? अपने विचार दीजिए।","examples":[{"en":"Digital privacy is not absolute secrecy but meaningful control over which data are collected, how they are combined, and which decisions they are allowed to influence.","native":"डिजिटल निजता पूर्ण गोपनीयता नहीं, बल्कि इस पर सार्थक नियंत्रण है कि कौन-सा डेटा एकत्र हो, उसे कैसे जोड़ा जाए और उसे किन निर्णयों को प्रभावित करने दिया जाए।"},{"en":"Consent offers little protection when essential services require acceptance of complex terms and data can be inferred about people who never disclosed them.","native":"जब आवश्यक सेवाएँ जटिल शर्तें स्वीकार करना अनिवार्य बनाती हैं और उन लोगों के बारे में भी डेटा निकाला जा सकता है जिन्होंने उसे कभी साझा नहीं किया, तब सहमति बहुत कम सुरक्षा देती है।"},{"en":"Effective safeguards therefore require data minimization, independent oversight, and enforceable rights to access, correction, and deletion rather than stronger passwords alone.","native":"इसलिए प्रभावी सुरक्षा के लिए केवल अधिक मज़बूत पासवर्ड नहीं, बल्कि न्यूनतम डेटा-संग्रह, स्वतंत्र निगरानी और पहुँच, सुधार तथा मिटाने के लागू किए जा सकने वाले अधिकार चाहिए।"}]},"es":{"word":"privacidad","question":"¿Es posible la privacidad en la era digital? Da tu opinión.","examples":[{"en":"Digital privacy is not absolute secrecy but meaningful control over which data are collected, how they are combined, and which decisions they are allowed to influence.","native":"La privacidad digital no consiste en un secreto absoluto, sino en un control significativo sobre qué datos se recogen, cómo se combinan y en qué decisiones pueden influir."},{"en":"Consent offers little protection when essential services require acceptance of complex terms and data can be inferred about people who never disclosed them.","native":"El consentimiento protege poco cuando los servicios esenciales exigen aceptar condiciones complejas y se pueden inferir datos sobre personas que nunca los revelaron."},{"en":"Effective safeguards therefore require data minimization, independent oversight, and enforceable rights to access, correction, and deletion rather than stronger passwords alone.","native":"Por tanto, unas garantías eficaces requieren minimizar los datos, supervisión independiente y derechos exigibles de acceso, rectificación y supresión, no solo contraseñas más seguras."}]},"zh":{"word":"隐私","question":"在数字时代，隐私还有可能吗？谈谈你的看法。","examples":[{"en":"Digital privacy is not absolute secrecy but meaningful control over which data are collected, how they are combined, and which decisions they are allowed to influence.","native":"数字隐私并非绝对保密，而是切实控制收集哪些数据、如何组合数据，以及允许数据影响哪些决定。"},{"en":"Consent offers little protection when essential services require acceptance of complex terms and data can be inferred about people who never disclosed them.","native":"当基本服务要求用户接受复杂条款，而且还能推断出当事人从未披露的数据时，同意机制几乎无法提供保护。"},{"en":"Effective safeguards therefore require data minimization, independent oversight, and enforceable rights to access, correction, and deletion rather than stronger passwords alone.","native":"因此，有效保障需要数据最小化、独立监督，以及可执行的查阅、更正和删除权，而不能只依靠更强的密码。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'work-life balance', 'How can people maintain a healthy work-life balance?', '{"te":{"word":"పని-జీవిత సమతుల్యత","question":"ప్రజలు ఆరోగ్యకరమైన పని-జీవిత సమతుల్యతను ఎలా కొనసాగించగలరు?","examples":[{"en":"Individual boundary-setting has limited effect when promotion, job security, and professional status implicitly reward permanent availability.","native":"పదోన్నతి, ఉద్యోగ భద్రత మరియు వృత్తిపరమైన హోదా ఎల్లప్పుడూ అందుబాటులో ఉండటాన్ని పరోక్షంగా ప్రోత్సహించినప్పుడు, వ్యక్తులు హద్దులు పెట్టుకోవడం పరిమిత ప్రభావమే చూపుతుంది."},{"en":"Flexible work can increase autonomy, yet without workload limits it may simply transfer the office into the home and make unpaid labor less visible.","native":"అనువైన పని స్వయంప్రతిపత్తిని పెంచగలదు, అయితే పనిభారం పరిమితులు లేకపోతే అది కార్యాలయాన్ని ఇంటికి తరలించి, వేతనం లేని శ్రమను మరింత కనిపించకుండా చేయవచ్చు."},{"en":"A sustainable balance requires organizations to evaluate outcomes rather than presenteeism and societies to value care, rest, and civic life as productive goods.","native":"స్థిరమైన సమతుల్యతకు సంస్థలు కార్యాలయంలో కనిపించే సమయాన్ని కాకుండా ఫలితాలను అంచనా వేయాలి; సమాజాలు సంరక్షణ, విశ్రాంతి మరియు పౌర జీవితాన్ని ఉత్పాదక విలువలుగా గుర్తించాలి."}]},"hi":{"word":"कार्य-जीवन संतुलन","question":"लोग स्वस्थ कार्य-जीवन संतुलन कैसे बनाए रख सकते हैं?","examples":[{"en":"Individual boundary-setting has limited effect when promotion, job security, and professional status implicitly reward permanent availability.","native":"जब पदोन्नति, नौकरी की सुरक्षा और पेशेवर प्रतिष्ठा अप्रत्यक्ष रूप से हर समय उपलब्ध रहने को पुरस्कृत करती हैं, तब व्यक्तिगत सीमाएँ तय करने का प्रभाव सीमित रहता है।"},{"en":"Flexible work can increase autonomy, yet without workload limits it may simply transfer the office into the home and make unpaid labor less visible.","native":"लचीला काम स्वायत्तता बढ़ा सकता है, फिर भी कार्यभार की सीमा के बिना वह कार्यालय को घर में पहुँचा सकता है और अवैतनिक श्रम को कम दिखाई देने वाला बना सकता है।"},{"en":"A sustainable balance requires organizations to evaluate outcomes rather than presenteeism and societies to value care, rest, and civic life as productive goods.","native":"टिकाऊ संतुलन के लिए संगठनों को केवल कार्यस्थल पर मौजूदगी नहीं, बल्कि परिणाम आँकने चाहिए और समाजों को देखभाल, विश्राम तथा नागरिक जीवन को उत्पादक मूल्यों के रूप में मानना चाहिए।"}]},"es":{"word":"equilibrio entre trabajo y vida","question":"¿Cómo pueden las personas mantener un equilibrio saludable entre trabajo y vida?","examples":[{"en":"Individual boundary-setting has limited effect when promotion, job security, and professional status implicitly reward permanent availability.","native":"Establecer límites individuales tiene un efecto limitado cuando la promoción, la seguridad laboral y el prestigio profesional premian implícitamente la disponibilidad permanente."},{"en":"Flexible work can increase autonomy, yet without workload limits it may simply transfer the office into the home and make unpaid labor less visible.","native":"El trabajo flexible puede aumentar la autonomía, pero sin límites de carga laboral quizá solo traslade la oficina al hogar y vuelva menos visible el trabajo no remunerado."},{"en":"A sustainable balance requires organizations to evaluate outcomes rather than presenteeism and societies to value care, rest, and civic life as productive goods.","native":"Un equilibrio sostenible exige que las organizaciones evalúen resultados en vez de presentismo y que las sociedades valoren los cuidados, el descanso y la vida cívica como bienes productivos."}]},"zh":{"word":"工作与生活的平衡","question":"人们如何保持健康的工作与生活平衡？","examples":[{"en":"Individual boundary-setting has limited effect when promotion, job security, and professional status implicitly reward permanent availability.","native":"当晋升、职业保障与专业地位暗中奖励随时待命时，个人设定边界所能发挥的作用十分有限。"},{"en":"Flexible work can increase autonomy, yet without workload limits it may simply transfer the office into the home and make unpaid labor less visible.","native":"灵活工作可以增加自主性，但如果工作量没有上限，它可能只是把办公室搬进家中，并让无偿劳动变得更隐蔽。"},{"en":"A sustainable balance requires organizations to evaluate outcomes rather than presenteeism and societies to value care, rest, and civic life as productive goods.","native":"可持续的平衡要求组织评价成果而非在岗表演，也要求社会把照护、休息与公民生活视为具有生产价值的事物。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'resilience', 'Discuss whether resilience is an innate trait or a quality that people can develop through experience.', '{"te":{"word":"స్థైర్యం","question":"స్థైర్యం సహజమైన లక్షణమా, లేక అనుభవం ద్వారా అభివృద్ధి చేసుకోగల గుణమా అనేదాని గురించి చర్చించండి.","examples":[{"en":"While some individuals appear naturally resilient, it could be argued that adversity, rather than genetics, plays the decisive role in shaping this quality.","native":"కొందరు సహజంగా స్థైర్యంతో కనిపిస్తారేమో కానీ, జన్యువుల కంటే విపత్తులే ఈ గుణాన్ని రూపొందించడంలో నిర్ణయాత్మక పాత్ర పోషిస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, temperament matters to some extent; nevertheless, supportive relationships and learned coping strategies seem far more influential in the long run.","native":"నిజానికి స్వభావం కొంత వరకు ముఖ్యమే; అయినప్పటికీ, సహాయకరమైన సంబంధాలు మరియు నేర్చుకున్న ఎదుర్కొనే వ్యూహాలు దీర్ఘకాలంలో చాలా ప్రభావవంతంగా ఉంటాయి."},{"en":"On balance, I would contend that resilience resembles a muscle: although rarely comfortable, deliberate exposure to manageable setbacks tends to strengthen it considerably.","native":"మొత్తానికి, స్థైర్యం కండరంలాంటిదని నేను పేర్కొంటాను: అరుదుగా సౌకర్యవంతంగా ఉన్నప్పటికీ, నియంత్రించగల ఇబ్బందులను ఉద్దేశపూర్వకంగా ఎదుర్కోవడం దానిని గణనీయంగా బలపరుస్తుంది."}]},"hi":{"word":"लचीलापन","question":"चर्चा कीजिए कि लचीलापन एक जन्मजात गुण है या अनुभव के माध्यम से विकसित की जा सकने वाली विशेषता।","examples":[{"en":"While some individuals appear naturally resilient, it could be argued that adversity, rather than genetics, plays the decisive role in shaping this quality.","native":"जबकि कुछ लोग स्वाभाविक रूप से लचीले प्रतीत होते हैं, यह तर्क दिया जा सकता है कि इस गुण को आकार देने में आनुवंशिकता से अधिक विपत्तियाँ निर्णायक भूमिका निभाती हैं।"},{"en":"Admittedly, temperament matters to some extent; nevertheless, supportive relationships and learned coping strategies seem far more influential in the long run.","native":"यह स्वीकार करना होगा कि स्वभाव कुछ हद तक मायने रखता है; फिर भी, सहायक रिश्ते और सीखी गई सामना करने की रणनीतियाँ लंबे समय में कहीं अधिक प्रभावशाली लगती हैं।"},{"en":"On balance, I would contend that resilience resembles a muscle: although rarely comfortable, deliberate exposure to manageable setbacks tends to strengthen it considerably.","native":"कुल मिलाकर, मेरा मानना है कि लचीलापन एक माँसपेशी जैसा है: यद्यपि यह शायद ही आरामदायक होता है, प्रबंधनीय असफलताओं का जानबूझकर सामना इसे काफी मज़बूत बनाता है।"}]},"es":{"word":"resiliencia","question":"Analiza si la resiliencia es un rasgo innato o una cualidad que las personas pueden desarrollar con la experiencia.","examples":[{"en":"While some individuals appear naturally resilient, it could be argued that adversity, rather than genetics, plays the decisive role in shaping this quality.","native":"Aunque algunas personas parecen resilientes por naturaleza, podría argumentarse que la adversidad, más que la genética, desempeña el papel decisivo en la formación de esta cualidad."},{"en":"Admittedly, temperament matters to some extent; nevertheless, supportive relationships and learned coping strategies seem far more influential in the long run.","native":"Es cierto que el temperamento importa hasta cierto punto; sin embargo, las relaciones de apoyo y las estrategias de afrontamiento aprendidas parecen mucho más influyentes a largo plazo."},{"en":"On balance, I would contend that resilience resembles a muscle: although rarely comfortable, deliberate exposure to manageable setbacks tends to strengthen it considerably.","native":"En definitiva, yo sostendría que la resiliencia se parece a un músculo: aunque rara vez resulta cómodo, la exposición deliberada a reveses manejables tiende a fortalecerla considerablemente."}]},"zh":{"word":"韧性","question":"讨论韧性是与生俱来的特质，还是人们可以通过经历培养的品质。","examples":[{"en":"While some individuals appear naturally resilient, it could be argued that adversity, rather than genetics, plays the decisive role in shaping this quality.","native":"尽管有些人似乎天生就有韧性，但可以认为，在塑造这种品质方面，逆境而非基因起着决定性作用。"},{"en":"Admittedly, temperament matters to some extent; nevertheless, supportive relationships and learned coping strategies seem far more influential in the long run.","native":"诚然，性格在某种程度上确实重要；然而，从长远来看，支持性的人际关系和后天习得的应对策略似乎影响更大。"},{"en":"On balance, I would contend that resilience resembles a muscle: although rarely comfortable, deliberate exposure to manageable setbacks tends to strengthen it considerably.","native":"总体而言，我认为韧性就像一块肌肉：虽然刻意面对可控的挫折很少让人感到舒适，但它往往会大大增强韧性。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'innovation', 'To what extent does innovation depend on individual genius rather than collaborative effort?', '{"te":{"word":"ఆవిష్కరణ","question":"ఆవిష్కరణ వ్యక్తిగత ప్రతిభ కంటే సామూహిక కృషిపై ఎంత వరకు ఆధారపడుతుంది?","examples":[{"en":"Although history celebrates lone inventors, most breakthroughs arguably emerge from networks of researchers who build, often unknowingly, on one another''s incremental work.","native":"చరిత్ర ఏకాకి ఆవిష్కర్తలను కొనియాడినప్పటికీ, చాలా పురోగతులు ఒకరి క్రమిక పనిపై మరొకరు తరచుగా తెలియకుండానే నిర్మించే పరిశోధకుల నెట్‌వర్కుల నుండే ఉద్భవిస్తాయని చెప్పవచ్చు."},{"en":"It could be argued that genius provides the spark, yet without institutions willing to fund and refine ideas, most innovations would remain little more than curiosities.","native":"ప్రతిభ మొదటి మెరుపును ఇస్తుందని చెప్పవచ్చు, అయితే ఆలోచనలకు నిధులు సమకూర్చి వాటిని రుగ్మతలు చేసే సంస్థలు లేకపోతే, చాలా ఆవిష్కరణలు కేవలం ఆసక్తికర వస్తువులుగానే మిగిలిపోతాయి."},{"en":"To some extent the romantic myth of the solitary genius persists because it simplifies a far messier, collaborative reality; nevertheless, it distorts how progress actually happens.","native":"ఏకాకి ప్రతిభావంతుని రొమాంటిక్ పురాణం కొంత వరకు కొనసాగుతుంది, ఎందుకంటే అది చాలా గందరగోళమైన, సామూహిక వాస్తవాన్ని సరళీకరిస్తుంది; అయినప్పటికీ, పురోగతి వాస్తవంగా ఎలా జరుగుతుందో అది అపవ్యాఖ్యానం చేస్తుంది."}]},"hi":{"word":"नवाचार","question":"नवाचार किस हद तक व्यक्तिगत प्रतिभा पर निर्भर करता है, और किस हद तक सहयोगात्मक प्रयास पर?","examples":[{"en":"Although history celebrates lone inventors, most breakthroughs arguably emerge from networks of researchers who build, often unknowingly, on one another''s incremental work.","native":"यद्यपि इतिहास अकेले आविष्कारकों का गुणगान करता है, फिर भी अधिकांश सफलताएँ तर्कतः शोधकर्ताओं के ऐसे नेटवर्क से निकलती हैं जो अक्सर अनजाने में एक-दूसरे के क्रमिक कार्य पर आगे बनाते हैं।"},{"en":"It could be argued that genius provides the spark, yet without institutions willing to fund and refine ideas, most innovations would remain little more than curiosities.","native":"यह तर्क दिया जा सकता है कि प्रतिभा चिंगारी प्रदान करती है, लेकिन विचारों को धन देने और परिष्कृत करने के लिए तैयार संस्थाओं के बिना, अधिकांश नवाचार महज़ जिज्ञासा की वस्तु बनकर रह जाएँगे।"},{"en":"To some extent the romantic myth of the solitary genius persists because it simplifies a far messier, collaborative reality; nevertheless, it distorts how progress actually happens.","native":"कुछ हद तक एकाकी प्रतिभा का रोमांटिक मिथक इसलिए टिका रहता है क्योंकि यह कहीं अधिक अव्यवस्थित, सहयोगी वास्तविकता को सरल बना देता है; फिर भी, यह विकृत करता है कि प्रगति वास्तव में कैसे होती है।"}]},"es":{"word":"innovación","question":"¿Hasta qué punto depende la innovación del genio individual y no del esfuerzo colaborativo?","examples":[{"en":"Although history celebrates lone inventors, most breakthroughs arguably emerge from networks of researchers who build, often unknowingly, on one another''s incremental work.","native":"Aunque la historia celebra a los inventores solitarios, la mayoría de los avances surgen, posiblemente, de redes de investigadores que se apoyan, a menudo sin saberlo, en el trabajo incremental de los demás."},{"en":"It could be argued that genius provides the spark, yet without institutions willing to fund and refine ideas, most innovations would remain little more than curiosities.","native":"Podría argumentarse que el genio aporta la chispa, pero sin instituciones dispuestas a financiar y perfeccionar las ideas, la mayoría de las innovaciones seguirían siendo meras curiosidades."},{"en":"To some extent the romantic myth of the solitary genius persists because it simplifies a far messier, collaborative reality; nevertheless, it distorts how progress actually happens.","native":"En cierta medida, el mito romántico del genio solitario persiste porque simplifica una realidad colaborativa mucho más caótica; sin embargo, distorsiona cómo ocurre realmente el progreso."}]},"zh":{"word":"创新","question":"创新在多大程度上依赖于个人天赋而非协作努力？","examples":[{"en":"Although history celebrates lone inventors, most breakthroughs arguably emerge from networks of researchers who build, often unknowingly, on one another''s incremental work.","native":"尽管历史歌颂孤独的发明家，但可以说，大多数突破都源自研究者网络，他们往往在不知不觉中建立在彼此渐进的工作之上。"},{"en":"It could be argued that genius provides the spark, yet without institutions willing to fund and refine ideas, most innovations would remain little more than curiosities.","native":"可以认为，天才提供了火花，但如果没有愿意资助和完善创意的机构，大多数创新将只不过沦为新奇玩物。"},{"en":"To some extent the romantic myth of the solitary genius persists because it simplifies a far messier, collaborative reality; nevertheless, it distorts how progress actually happens.","native":"在某种程度上，孤独天才的浪漫神话之所以经久不衰，是因为它把一个远为混乱、协作的现实简单化了；然而，它扭曲了进步实际发生的方式。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'freedom', 'Is complete freedom desirable, or do societies need limits to function well?', '{"te":{"word":"స్వేచ్ఛ","question":"పూర్తి స్వేచ్ఛ కావాల్సిందేనా, లేక సమాజాలు బాగా పనిచేయాలంటే పరిమితులు అవసరమా?","examples":[{"en":"While few would dispute the value of personal liberty, it could be argued that absolute freedom tends to erode the very security that makes meaningful choices possible.","native":"వ్యక్తిగత స్వాతంత్ర్యం విలువను తక్కువ మందే ఖండిస్తారేమో కానీ, పూర్తి స్వేచ్ఛ అర్థవంతమైన ఎంపికలను సాధ్యం చేసే భద్రతనే కొట్టివేస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, restrictions can be abused by those in power; nevertheless, sensible rules often protect the vulnerable more than they constrain the strong.","native":"నిజానికి అధికారంలో ఉన్నవారు ఆంక్షలను దుర్వినియోగం చేయవచ్చు; అయినప్పటికీ, సమంజసమైన నియమాలు తరచుగా బలవంతులను అడ్డగించడం కంటే బలహీనులను ఎక్కువగా రక్షిస్తాయి."},{"en":"On balance, freedom seems less like the absence of rules and more like a fragile equilibrium that societies must continually renegotiate as circumstances change.","native":"మొత్తానికి, స్వేచ్ఛ నియమాల లేమి కంటే, పరిస్థితులు మారేకొద్దీ సమాజాలు నిరంతరం మళ్లీ సర్దుబాటు చేసుకోవాల్సిన సున్నితమైన సమతుల్యతలా ఎక్కువగా కనిపిస్తుంది."}]},"hi":{"word":"स्वतंत्रता","question":"क्या पूर्ण स्वतंत्रता वांछनीय है, या समाजों को अच्छे से काम करने के लिए सीमाओं की आवश्यकता है?","examples":[{"en":"While few would dispute the value of personal liberty, it could be argued that absolute freedom tends to erode the very security that makes meaningful choices possible.","native":"जबकि व्यक्तिगत स्वतंत्रता के मूल्य पर बहुत कम लोग आपत्ति करेंगे, यह तर्क दिया जा सकता है कि पूर्ण स्वतंत्रता उसी सुरक्षा को क्षय कर देती है जो सार्थक विकल्पों को संभव बनाती है।"},{"en":"Admittedly, restrictions can be abused by those in power; nevertheless, sensible rules often protect the vulnerable more than they constrain the strong.","native":"यह स्वीकार करना होगा कि सत्ता में बैठे लोग प्रतिबंधों का दुरुपयोग कर सकते हैं; फिर भी, समझदारी भरे नियम अक्सर मज़बूतों को बाँधने से ज़्यादा कमज़ोरों की रक्षा करते हैं।"},{"en":"On balance, freedom seems less like the absence of rules and more like a fragile equilibrium that societies must continually renegotiate as circumstances change.","native":"कुल मिलाकर, स्वतंत्रता नियमों की अनुपस्थिति से कम और एक नाज़ुक संतुलन जैसी अधिक लगती है, जिसे समाजों को बदलती परिस्थितियों के साथ लगातार दोबारा तय करना पड़ता है।"}]},"es":{"word":"libertad","question":"¿Es deseable la libertad absoluta, o necesitan las sociedades límites para funcionar bien?","examples":[{"en":"While few would dispute the value of personal liberty, it could be argued that absolute freedom tends to erode the very security that makes meaningful choices possible.","native":"Aunque pocos cuestionarían el valor de la libertad personal, podría argumentarse que la libertad absoluta tiende a erosionar la propia seguridad que hace posibles las decisiones significativas."},{"en":"Admittedly, restrictions can be abused by those in power; nevertheless, sensible rules often protect the vulnerable more than they constrain the strong.","native":"Es cierto que quienes detentan el poder pueden abusar de las restricciones; sin embargo, las normas sensatas suelen proteger a los vulnerables más de lo que limitan a los fuertes."},{"en":"On balance, freedom seems less like the absence of rules and more like a fragile equilibrium that societies must continually renegotiate as circumstances change.","native":"En definitiva, la libertad parece menos la ausencia de reglas y más un equilibrio frágil que las sociedades deben renegociar continuamente a medida que cambian las circunstancias."}]},"zh":{"word":"自由","question":"完全的自由是否可取，还是社会需要一定的限制才能良好运转？","examples":[{"en":"While few would dispute the value of personal liberty, it could be argued that absolute freedom tends to erode the very security that makes meaningful choices possible.","native":"尽管很少有人会质疑个人自由的价值，但可以认为，绝对的自由往往会侵蚀使有意义的选择成为可能的那种安全本身。"},{"en":"Admittedly, restrictions can be abused by those in power; nevertheless, sensible rules often protect the vulnerable more than they constrain the strong.","native":"诚然，当权者可能滥用限制；然而，明智的规则往往更多地保护弱者，而不是束缚强者。"},{"en":"On balance, freedom seems less like the absence of rules and more like a fragile equilibrium that societies must continually renegotiate as circumstances change.","native":"总体而言，自由与其说意味着没有规则，不如说是一种脆弱的平衡，社会必须随着环境的变化不断重新协商。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'responsibility', 'Should individuals be held fully responsible for their choices, or do circumstances matter more?', '{"te":{"word":"బాధ్యత","question":"వ్యక్తులు తమ ఎంపికలకు పూర్తి బాధ్యత వహించాలా, లేక పరిస్థితులు మరింత ముఖ్యమైనవేనా?","examples":[{"en":"It could be argued that holding people accountable encourages prudence, yet this overlooks how profoundly poverty, upbringing, and sheer luck constrain the choices actually available.","native":"వ్యక్తులను జవాబుదారీగా భావించడం వివేకాన్ని ప్రోత్సహిస్తుందని చెప్పవచ్చు, అయితే పేదరికం, పెంపకం మరియు కేవలం అదృష్టం వాస్తవంగా అందుబాటులో ఉన్న ఎంపికలను ఎంతగా పరిమితం చేస్తాయో ఇది పట్టించుకోదు."},{"en":"While personal responsibility matters to some extent, societies that ignore structural disadvantages tend to confuse blaming individuals with solving underlying problems.","native":"వ్యక్తిగత బాధ్యత కొంత వరకు ముఖ్యమైనప్పటికీ, నిర్మాణాత్మక అసౌకర్యాలను పట్టించుకోని సమాజాలు వ్యక్తులను నిందించడాన్నీ, అంతర్లీన సమస్యలను పరిష్కరించడాన్నీ గందరగోళం చేస్తాయి."},{"en":"Nevertheless, dismissing responsibility altogether is equally misguided, since a sense of agency, however constrained, remains essential for dignity and social cooperation.","native":"అయినప్పటికీ, బాధ్యతను పూర్తిగా పక్కనపెట్టడం కూడా అంతే తప్పు, ఎందుకంటే ఎంత పరిమితమైనప్పటికీ, తామే చేయగలమనే భావన గౌరవానికీ, సామాజిక సహకారానికీ అత్యవసరం."}]},"hi":{"word":"ज़िम्मेदारी","question":"क्या व्यक्तियों को उनके चुनावों के लिए पूरी तरह ज़िम्मेदार ठहराया जाना चाहिए, या परिस्थितियाँ अधिक मायने रखती हैं?","examples":[{"en":"It could be argued that holding people accountable encourages prudence, yet this overlooks how profoundly poverty, upbringing, and sheer luck constrain the choices actually available.","native":"यह तर्क दिया जा सकता है कि लोगों को जवाबदेह ठहराना विवेक को बढ़ावा देता है, लेकिन यह नज़रअंदाज़ करता है कि गरीबी, परवरिश और महज़ किस्मत उपलब्ध विकल्पों को कितनी गहराई तक सीमित करती हैं।"},{"en":"While personal responsibility matters to some extent, societies that ignore structural disadvantages tend to confuse blaming individuals with solving underlying problems.","native":"जबकि व्यक्तिगत ज़िम्मेदारी कुछ हद तक मायने रखती है, जो समाज संरचनात्मक कमियों को अनदेखा करते हैं वे व्यक्तियों को दोष देने और अंतर्निहित समस्याओं को सुलझाने में भ्रम पैदा करते हैं।"},{"en":"Nevertheless, dismissing responsibility altogether is equally misguided, since a sense of agency, however constrained, remains essential for dignity and social cooperation.","native":"फिर भी, ज़िम्मेदारी को पूरी तरह खारिज करना भी उतना ही भ्रामक है, क्योंकि स्वयं करने की भावना—चाहे कितनी भी सीमित हो—गरिमा और सामाजिक सहयोग के लिए आवश्यक बनी रहती है।"}]},"es":{"word":"responsabilidad","question":"¿Deberían las personas ser plenamente responsables de sus decisiones, o importan más las circunstancias?","examples":[{"en":"It could be argued that holding people accountable encourages prudence, yet this overlooks how profoundly poverty, upbringing, and sheer luck constrain the choices actually available.","native":"Podría argumentarse que exigir responsabilidades fomenta la prudencia, pero esto pasa por alto cuánto limitan la pobreza, la crianza y la pura suerte las opciones realmente disponibles."},{"en":"While personal responsibility matters to some extent, societies that ignore structural disadvantages tend to confuse blaming individuals with solving underlying problems.","native":"Aunque la responsabilidad personal importa hasta cierto punto, las sociedades que ignoran las desventajas estructurales tienden a confundir culpar a las personas con resolver los problemas de fondo."},{"en":"Nevertheless, dismissing responsibility altogether is equally misguided, since a sense of agency, however constrained, remains essential for dignity and social cooperation.","native":"Sin embargo, descartar por completo la responsabilidad es igualmente erróneo, ya que la sensación de autonomía, por limitada que sea, sigue siendo esencial para la dignidad y la cooperación social."}]},"zh":{"word":"责任","question":"个人应该为自己的选择承担全部责任，还是环境更加重要？","examples":[{"en":"It could be argued that holding people accountable encourages prudence, yet this overlooks how profoundly poverty, upbringing, and sheer luck constrain the choices actually available.","native":"可以认为，让人们为自己的选择负责能鼓励审慎，但这忽视了贫困、成长环境和纯粹的运气对实际可用选择的深刻限制。"},{"en":"While personal responsibility matters to some extent, societies that ignore structural disadvantages tend to confuse blaming individuals with solving underlying problems.","native":"尽管个人责任在某种程度上确实重要，但忽视结构性不利条件的社会，往往会把责怪个人与解决根本问题混为一谈。"},{"en":"Nevertheless, dismissing responsibility altogether is equally misguided, since a sense of agency, however constrained, remains essential for dignity and social cooperation.","native":"然而，完全否定责任同样是错误的，因为无论受到多大限制，自主感对于尊严和社会合作仍然至关重要。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'empathy', 'Can empathy be taught, or is it something people either have or lack?', '{"te":{"word":"సానుభూతి","question":"సానుభూతిని నేర్పవచ్చా, లేక అది కొందరికి ఉండి కొందరికి లేనిదేనా?","examples":[{"en":"Although empathy partly reflects temperament, it could be argued that literature, travel, and honest conversation expand our capacity to imagine other people''s inner lives.","native":"సానుభూతి పాక్షికంగా స్వభావాన్ని ప్రతిబింబిస్తున్నప్పటికీ, సాహిత్యం, యాత్రలు మరియు నిజాయితీగల సంభాషణలు ఇతరుల అంతర్గత జీవితాలను ఊహించే మన సామర్థ్యాన్ని విస్తరిస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, some individuals seem instinctively compassionate; nevertheless, schools that practise perspective-taking report measurable improvements in how students treat one another.","native":"నిజానికి కొందరు స్వభావతః కరుణామయులుగా ఉంటారు; అయినప్పటికీ, ఇతరుల దృక్కోణం నుండి ఆలోచించడం అభ్యసించే పాఠశాలలు విద్యార్థుల పరస్పర ప్రవర్తనలో కొలవగల మెరుగుదలలను నివేదిస్తున్నాయి."},{"en":"On balance, empathy appears less like a fixed gift and more like a habit of attention that can, with deliberate effort, be cultivated or allowed to wither.","native":"మొత్తానికి, సానుభూతి స్థిరమైన వరం కంటే శ్రద్ధ అనే అలవాటులా ఎక్కువగా కనిపిస్తుంది; ఉద్దేశపూర్వక కృషితో దాన్ని పెంచవచ్చు లేదా వాడిపోనివ్వవచ్చు."}]},"hi":{"word":"समानुभूति","question":"क्या समानुभूति सिखाई जा सकती है, या यह कुछ ऐसा है जो लोगों में या तो होती है या नहीं?","examples":[{"en":"Although empathy partly reflects temperament, it could be argued that literature, travel, and honest conversation expand our capacity to imagine other people''s inner lives.","native":"यद्यपि समानुभूति आंशिक रूप से स्वभाव को दर्शाती है, फिर भी यह तर्क दिया जा सकता है कि साहित्य, यात्रा और ईमानदार बातचीत दूसरों के आंतरिक जीवन की कल्पना करने की हमारी क्षमता का विस्तार करते हैं।"},{"en":"Admittedly, some individuals seem instinctively compassionate; nevertheless, schools that practise perspective-taking report measurable improvements in how students treat one another.","native":"यह स्वीकार करना होगा कि कुछ लोग सहज रूप से दयालु प्रतीत होते हैं; फिर भी, दूसरों का दृष्टिकोण अपनाने का अभ्यास करने वाले विद्यालय छात्रों के पारस्परिक व्यवहार में मापने योग्य सुधार की सूचना देते हैं।"},{"en":"On balance, empathy appears less like a fixed gift and more like a habit of attention that can, with deliberate effort, be cultivated or allowed to wither.","native":"कुल मिलाकर, समानुभूति एक स्थिर वरदान से कम और ध्यान की एक ऐसी आदत जैसी अधिक लगती है जिसे जानबूझकर प्रयास से विकसित किया जा सकता है या मुरझाने दिया जा सकता है।"}]},"es":{"word":"empatía","question":"¿Puede enseñarse la empatía, o es algo que las personas tienen o no tienen?","examples":[{"en":"Although empathy partly reflects temperament, it could be argued that literature, travel, and honest conversation expand our capacity to imagine other people''s inner lives.","native":"Aunque la empatía refleja en parte el temperamento, podría argumentarse que la literatura, los viajes y la conversación honesta amplían nuestra capacidad de imaginar la vida interior de los demás."},{"en":"Admittedly, some individuals seem instinctively compassionate; nevertheless, schools that practise perspective-taking report measurable improvements in how students treat one another.","native":"Es cierto que algunas personas parecen compasivas por instinto; sin embargo, las escuelas que practican la toma de perspectiva reportan mejoras medibles en cómo se tratan los estudiantes entre sí."},{"en":"On balance, empathy appears less like a fixed gift and more like a habit of attention that can, with deliberate effort, be cultivated or allowed to wither.","native":"En definitiva, la empatía parece menos un don fijo y más un hábito de atención que, con esfuerzo deliberado, puede cultivarse o dejarse marchitar."}]},"zh":{"word":"同理心","question":"同理心是可以教授的吗，还是人们要么有要么没有的东西？","examples":[{"en":"Although empathy partly reflects temperament, it could be argued that literature, travel, and honest conversation expand our capacity to imagine other people''s inner lives.","native":"尽管同理心部分反映了性格，但可以认为，文学、旅行和真诚的交谈能拓展我们想象他人内心世界的能力。"},{"en":"Admittedly, some individuals seem instinctively compassionate; nevertheless, schools that practise perspective-taking report measurable improvements in how students treat one another.","native":"诚然，有些人似乎天生富有同情心；然而，实践换位思考的学校报告说，学生彼此相处的方式有了可衡量的改善。"},{"en":"On balance, empathy appears less like a fixed gift and more like a habit of attention that can, with deliberate effort, be cultivated or allowed to wither.","native":"总体而言，同理心似乎不像是一份固定的天赋，更像是一种专注的习惯，通过刻意努力可以培养，也可能任其枯萎。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'consumerism', 'Does consumer culture improve our lives, or does it create needs we never had?', '{"te":{"word":"వినియోగవాదం","question":"వినియోగ సంస్కృతి మన జీవితాలను మెరుగుపరుస్తుందా, లేక మనకు లేని అవసరాలను సృష్టిస్తుందా?","examples":[{"en":"While consumerism has undeniably raised material comfort, it could be argued that advertising manufactures dissatisfaction, persuading people that happiness lies always one purchase away.","native":"వినియోగవాదం భౌతిక సౌకర్యాన్ని నిస్సందేహంగా పెంచినప్పటికీ, ప్రకటనలు అసంతృప్తిని తయారుచేస్తాయని, ఆనందం ఎల్లప్పుడూ ఒక కొనుగోలు దూరంలో ఉంటుందని ప్రజలను ఒప్పిస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, markets give us choice; nevertheless, an abundance of nearly identical options often produces anxiety rather than the liberation that choice supposedly brings.","native":"నిజానికి మార్కెట్లు మనకు ఎంపికను ఇస్తాయి; అయినప్పటికీ, దాదాపు ఒకేలా ఉండే ఎంపికల సమృద్ధి తరచుగా ఎంపిక తేస్తుందని చెప్పబడే విముక్తికి బదులు ఆందోళనను కలిపిస్తుంది."},{"en":"On balance, consumption becomes problematic when possessions shift from serving our needs to defining our identity, a boundary modern marketing deliberately blurs.","native":"మొత్తానికి, ఆస్తులు మన అవసరాలను తీర్చడం నుండి మన గుర్తింపును నిర్వచించడానికి మారినప్పుడు వినియోగం సమస్యగా మారుతుంది; ఆధునిక మార్కెటింగ్ ఉద్దేశపూర్వకంగా మసకబార్చే సరిహద్దు ఇది."}]},"hi":{"word":"उपभोक्तावाद","question":"क्या उपभोक्ता संस्कृति हमारे जीवन को बेहतर बनाती है, या वह ऐसी ज़रूरतें पैदा करती है जो हमें कभी थी ही नहीं?","examples":[{"en":"While consumerism has undeniably raised material comfort, it could be argued that advertising manufactures dissatisfaction, persuading people that happiness lies always one purchase away.","native":"जबकि उपभोक्तावाद ने निस्संदेह भौतिक आराम बढ़ाया है, यह तर्क दिया जा सकता है कि विज्ञापन असंतोष का निर्माण करता है, और लोगों को यह मनाता है कि खुशी हमेशा एक खरीद दूर है।"},{"en":"Admittedly, markets give us choice; nevertheless, an abundance of nearly identical options often produces anxiety rather than the liberation that choice supposedly brings.","native":"यह स्वीकार करना होगा कि बाज़ार हमें विकल्प देते हैं; फिर भी, लगभग एक जैसे विकल्पों की भरमार अक्सर उस मुक्ति के बजाय चिंता पैदा करती है जो विकल्प कथित तौर पर लाता है।"},{"en":"On balance, consumption becomes problematic when possessions shift from serving our needs to defining our identity, a boundary modern marketing deliberately blurs.","native":"कुल मिलाकर, उपभोग तब समस्याग्रस्त हो जाता है जब सामान हमारी ज़रूरतों को पूरा करने के बजाय हमारी पहचान बनाने लगता है—यह सीमा आधुनिक विपणन जानबूझकर धुंधली करता है।"}]},"es":{"word":"consumismo","question":"¿Mejora nuestras vidas la cultura de consumo, o crea necesidades que nunca tuvimos?","examples":[{"en":"While consumerism has undeniably raised material comfort, it could be argued that advertising manufactures dissatisfaction, persuading people that happiness lies always one purchase away.","native":"Aunque el consumismo ha elevado innegablemente el confort material, podría argumentarse que la publicidad fabrica insatisfacción, convenciendo a la gente de que la felicidad está siempre a una compra de distancia."},{"en":"Admittedly, markets give us choice; nevertheless, an abundance of nearly identical options often produces anxiety rather than the liberation that choice supposedly brings.","native":"Es cierto que los mercados nos dan opciones; sin embargo, una abundancia de alternativas casi idénticas suele producir ansiedad en lugar de la liberación que supuestamente trae la elección."},{"en":"On balance, consumption becomes problematic when possessions shift from serving our needs to defining our identity, a boundary modern marketing deliberately blurs.","native":"En definitiva, el consumo se vuelve problemático cuando las posesiones pasan de satisfacer nuestras necesidades a definir nuestra identidad, un límite que el marketing moderno difumina deliberadamente."}]},"zh":{"word":"消费主义","question":"消费文化改善了我们的生活，还是创造了我们从未有过的需求？","examples":[{"en":"While consumerism has undeniably raised material comfort, it could be argued that advertising manufactures dissatisfaction, persuading people that happiness lies always one purchase away.","native":"尽管消费主义无疑提高了物质舒适度，但可以认为，广告制造了不满，说服人们幸福总是只差一次购买。"},{"en":"Admittedly, markets give us choice; nevertheless, an abundance of nearly identical options often produces anxiety rather than the liberation that choice supposedly brings.","native":"诚然，市场给了我们选择；然而，大量几乎相同的选项往往带来焦虑，而不是选择本应带来的解放感。"},{"en":"On balance, consumption becomes problematic when possessions shift from serving our needs to defining our identity, a boundary modern marketing deliberately blurs.","native":"总体而言，当拥有物从满足需求转变为定义我们的身份时，消费就变得成问题了——这正是现代营销刻意模糊的界限。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'migration', 'Do the benefits of international migration outweigh the challenges it creates for host countries?', '{"te":{"word":"వలస","question":"అంతర్జాతీయ వలసల ప్రయోజనాలు ఆతిథ్య దేశాలకు ఇవ్వే సవాళ్లను అధిగమిస్తాయా?","examples":[{"en":"Although migration can strain housing and public services initially, it could be argued that migrants typically contribute more in taxes and innovation than they ever receive.","native":"వలసలు ప్రారంభంలో గృహాలపైనూ, ప్రజా సేవలపైనూ ఒత్తిడి కలిపించవచ్చు అయితే, వలసదారులు సాధారణంగా తాము పొందే దానికంటే పన్నుల రూపంలోనూ ఆవిష్కరణల రూపంలోనూ ఎక్కువగా అందిస్తారని చెప్పవచ్చు."},{"en":"Admittedly, rapid demographic change unsettles some communities; nevertheless, ageing economies would face severe labour shortages without the arrival of younger migrant workers.","native":"నిజానికి వేగవంతమైన జనాభా మార్పు కొన్ని సమాజాలను కలవరపెడుతుంది; అయినప్పటికీ, యువ వలస కార్మికులు రాకపోతే వృద్ధాప్య ఆర్థిక వ్యవస్థలు తీవ్రమైన కార్మిక కొరతను ఎదుర్కొంటాయి."},{"en":"On balance, the debate says as much about political anxieties as economics, since the evidence for long-term fiscal benefits is, if anything, remarkably consistent.","native":"మొత్తానికి, దీర్ఘకాలిక ఆర్థిక ప్రయోజనాలకు సాక్ష్యాలు అసాధారణంగా స్థిరంగా ఉన్నందున, ఈ చర్చ ఆర్థిక శాస్త్రం గురించినంతగా రాజకీయ ఆందోళనల గురించి కూడా చెబుతుంది."}]},"hi":{"word":"प्रवासन","question":"क्या अंतरराष्ट्रीय प्रवासन के लाभ मेज़बान देशों के सामने आने वाली चुनौतियों से अधिक हैं?","examples":[{"en":"Although migration can strain housing and public services initially, it could be argued that migrants typically contribute more in taxes and innovation than they ever receive.","native":"यद्यपि प्रवासन शुरू में आवास और सार्वजनिक सेवाओं पर दबाव डाल सकता है, फिर भी यह तर्क दिया जा सकता है कि प्रवासी आमतौर पर जो कुछ पाते हैं उससे अधिक करों और नवाचार के रूप में योगदान देते हैं।"},{"en":"Admittedly, rapid demographic change unsettles some communities; nevertheless, ageing economies would face severe labour shortages without the arrival of younger migrant workers.","native":"यह स्वीकार करना होगा कि तेज़ जनांकिकीय बदलाव कुछ समुदायों को अस्थिर करता है; फिर भी, युवा प्रवासी श्रमिकों के आगमन के बिना, बूढ़ी अर्थव्यवस्थाओं को गंभीर श्रमिक कमी का सामना करना पड़ेगा।"},{"en":"On balance, the debate says as much about political anxieties as economics, since the evidence for long-term fiscal benefits is, if anything, remarkably consistent.","native":"कुल मिलाकर, यह बहस अर्थशास्त्र के बारे में उतना ही कहती है जितना राजनीतिक चिंताओं के बारे में, क्योंकि दीर्घकालिक राजकोषीय लाभों का प्रमाण उल्लेखनीय रूप से सुसंगत है।"}]},"es":{"word":"migración","question":"¿Superan los beneficios de la migración internacional los desafíos que crea para los países de acogida?","examples":[{"en":"Although migration can strain housing and public services initially, it could be argued that migrants typically contribute more in taxes and innovation than they ever receive.","native":"Aunque la migración puede tensionar inicialmente la vivienda y los servicios públicos, podría argumentarse que los migrantes suelen contribuir más en impuestos e innovación de lo que jamás reciben."},{"en":"Admittedly, rapid demographic change unsettles some communities; nevertheless, ageing economies would face severe labour shortages without the arrival of younger migrant workers.","native":"Es cierto que el cambio demográfico rápido inquieta a algunas comunidades; sin embargo, las economías envejecidas afrontarían graves escaseces de mano de obra sin la llegada de trabajadores migrantes jóvenes."},{"en":"On balance, the debate says as much about political anxieties as economics, since the evidence for long-term fiscal benefits is, if anything, remarkably consistent.","native":"En definitiva, el debate dice tanto sobre las ansiedades políticas como sobre la economía, ya que la evidencia de los beneficios fiscales a largo plazo es notablemente consistente."}]},"zh":{"word":"移民","question":"国际移民的好处是否超过了它给接收国带来的挑战？","examples":[{"en":"Although migration can strain housing and public services initially, it could be argued that migrants typically contribute more in taxes and innovation than they ever receive.","native":"尽管移民最初可能给住房和公共服务带来压力，但可以认为，移民在税收和创新方面的贡献通常超过他们所获得的。"},{"en":"Admittedly, rapid demographic change unsettles some communities; nevertheless, ageing economies would face severe labour shortages without the arrival of younger migrant workers.","native":"诚然，快速的人口结构变化让一些社区感到不安；然而，如果没有年轻移民工人的到来，老龄化经济体将面临严重的劳动力短缺。"},{"en":"On balance, the debate says as much about political anxieties as economics, since the evidence for long-term fiscal benefits is, if anything, remarkably consistent.","native":"总体而言，这场辩论既关乎经济，也关乎政治焦虑，因为长期财政收益的证据即便不说别的，也是高度一致的。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'media bias', 'Can news media ever be truly objective, or is some bias inevitable?', '{"te":{"word":"మీడియా పక్షపాతం","question":"వార్తా మాధ్యమాలు నిజంగా నిష్పక్షపాతంగా ఉండగలవా, లేక కొంత పక్షపాతం అనివార్యమా?","examples":[{"en":"While journalists may strive for impartiality, it could be argued that every editorial choice, from headline wording to story selection, quietly encodes a particular worldview.","native":"జర్నలిస్టులు నిష్పక్షపాతం కోసం శ్రమించవచ్చు అయితే, శీర్షిక పదబంధం నుండి కథనాల ఎంపిక వరకు ప్రతి సంపాదకీయ నిర్ణయం నిశ్శబ్దంగా ఒక ప్రత్యేక ప్రపంచ దృష్టిని సంకేతీకరిస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, professional standards reduce the most blatant distortions; nevertheless, ownership structures and commercial pressures shape coverage in ways audiences rarely notice.","native":"నిజానికి వృత్తిపరమైన ప్రమాణాలు అత్యంత స్పష్టమైన వక్రీకరణలను తగ్గిస్తాయి; అయినప్పటికీ, యాజమాన్య నిర్మాణాలు మరియు వాణిజ్య ఒత్తిళ్లు ప్రేక్షకులు అరుదుగా గమనించే విధంగా కవరేజీని రూపొందిస్తాయి."},{"en":"On balance, complete objectivity may be unattainable, yet transparency about one''s perspective is arguably a more honest goal than pretending bias does not exist.","native":"మొత్తానికి, పూర్తి నిష్పక్షపాతం చేతనమవకపోవచ్చు, అయితే తమ దృక్కోణం గురించి పారదర్శకంగా ఉండటం పక్షపాతం లేదని నటించడం కంటే నిజాయితీగల లక్ష్యం అని చెప్పవచ్చు."}]},"hi":{"word":"मीडिया पक्षपात","question":"क्या समाचार मीडिया कभी सच में निष्पक्ष हो सकती है, या कुछ पक्षपात अनिवार्य है?","examples":[{"en":"While journalists may strive for impartiality, it could be argued that every editorial choice, from headline wording to story selection, quietly encodes a particular worldview.","native":"जबकि पत्रकार निष्पक्षता के लिए प्रयास कर सकते हैं, यह तर्क दिया जा सकता है कि शीर्षक के शब्दों से लेकर खबरों के चयन तक, हर संपादकीय निर्णय चुपचाप एक विशेष दृष्टिकोण को कूटबद्ध करता है।"},{"en":"Admittedly, professional standards reduce the most blatant distortions; nevertheless, ownership structures and commercial pressures shape coverage in ways audiences rarely notice.","native":"यह स्वीकार करना होगा कि व्यावसायिक मानक सबसे स्पष्ट विकृतियों को कम करते हैं; फिर भी, स्वामित्व संरचनाएँ और व्यावसायिक दबाव कवरेज को उन तरीकों से आकार देते हैं जिन्हें दर्शक शायद ही कभी नोटिस करते हैं।"},{"en":"On balance, complete objectivity may be unattainable, yet transparency about one''s perspective is arguably a more honest goal than pretending bias does not exist.","native":"कुल मिलाकर, पूर्ण वस्तुनिष्ठता शायद असंभव है, फिर भी अपने दृष्टिकोण के बारे में पारदर्शिता यह दिखावा करने से अधिक ईमानदार लक्ष्य है कि पक्षपात मौजूद ही नहीं है।"}]},"es":{"word":"sesgo mediático","question":"¿Pueden los medios de noticias ser realmente objetivos, o es inevitable cierto sesgo?","examples":[{"en":"While journalists may strive for impartiality, it could be argued that every editorial choice, from headline wording to story selection, quietly encodes a particular worldview.","native":"Aunque los periodistas pueden esforzarse por ser imparciales, podría argumentarse que cada decisión editorial, desde el titular hasta la selección de historias, codifica silenciosamente una visión particular del mundo."},{"en":"Admittedly, professional standards reduce the most blatant distortions; nevertheless, ownership structures and commercial pressures shape coverage in ways audiences rarely notice.","native":"Es cierto que los estándares profesionales reducen las distorsiones más flagrantes; sin embargo, las estructuras de propiedad y las presiones comerciales moldean la cobertura de maneras que el público rara vez percibe."},{"en":"On balance, complete objectivity may be unattainable, yet transparency about one''s perspective is arguably a more honest goal than pretending bias does not exist.","native":"En definitiva, la objetividad completa quizá sea inalcanzable, pero la transparencia sobre la propia perspectiva es un objetivo más honesto que fingir que el sesgo no existe."}]},"zh":{"word":"媒体偏见","question":"新闻媒体能够真正客观吗，还是某种偏见不可避免？","examples":[{"en":"While journalists may strive for impartiality, it could be argued that every editorial choice, from headline wording to story selection, quietly encodes a particular worldview.","native":"尽管记者可能努力追求公正，但可以认为，从标题措辞到报道选题，每一个编辑决策都在悄然编码某种特定的世界观。"},{"en":"Admittedly, professional standards reduce the most blatant distortions; nevertheless, ownership structures and commercial pressures shape coverage in ways audiences rarely notice.","native":"诚然，职业标准能减少最明目张胆的歪曲；然而，所有权结构和商业压力以受众很少注意到的方式塑造着报道。"},{"en":"On balance, complete objectivity may be unattainable, yet transparency about one''s perspective is arguably a more honest goal than pretending bias does not exist.","native":"总体而言，完全的客观或许无法实现，但坦承自己的视角可以说是一个比假装偏见不存在更诚实的目标。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'creativity', 'Is creativity a natural gift, or can it be developed through practice and discipline?', '{"te":{"word":"సృజనాత్మకత","question":"సృజనాత్మకత సహజమైన వరమా, లేక అభ్యాసం మరియు క్రమశిక్షణ ద్వారా అభివృద్ధి చేయగలదా?","examples":[{"en":"While a few people seem effortlessly inventive, it could be argued that most creative achievements rest on years of unglamorous practice rather than sudden inspiration.","native":"కొందరు శ్రమ లేకుండా సరికొత్త ఆలోచనలు చేస్తారేమో కానీ, చాలా సృజనాత్మక విజయాలు ఆకస్మిక స్ఫూర్తి కంటే సంవత్సరాల అర్పణాభావ అభ్యాసంపై ఆధారపడి ఉంటాయని చెప్పవచ్చు."},{"en":"Admittedly, formal education sometimes stifles originality; nevertheless, constraints of any kind often provoke the very ingenuity they appear to suppress.","native":"నిజానికి అధికారిక విద్య కొన్నిసార్లు వినూత్నతను కుదించేస్తుంది; అయినప్పటికీ, ఎటువంటి పరిమితులైనా తాము అణచివేస్తున్నట్టు కనిపించే సృజనాత్మకతనే తరచుగా రేకెత్తిస్తాయి."},{"en":"On balance, creativity seems less a mysterious talent than a willingness to tolerate failure, since genuinely novel ideas almost always emerge from numerous discarded attempts.","native":"మొత్తానికి, సృజనాత్మకత రహస్యమైన ప్రతిభ కంటే వైఫల్యాన్ని సహించే సిద్ధాంతంలా కనిపిస్తుంది, ఎందుకంటే నిజంగా కొత్త ఆలోచనలు దాదాపు ఎల్లప్పుడూ పడేయబడిన అనేక ప్రయత్నాల నుండే పుడతాయి."}]},"hi":{"word":"रचनात्मकता","question":"क्या रचनात्मकता एक स्वाभाविक उपहार है, या इसे अभ्यास और अनुशासन से विकसित किया जा सकता है?","examples":[{"en":"While a few people seem effortlessly inventive, it could be argued that most creative achievements rest on years of unglamorous practice rather than sudden inspiration.","native":"जबकि कुछ लोग बिना प्रयास के सृजनशील प्रतीत होते हैं, यह तर्क दिया जा सकता है कि अधिकांश रचनात्मक उपलब्धियाँ अचानक प्रेरणा के बजाय वर्षों के साधारण अभ्यास पर टिकी होती हैं।"},{"en":"Admittedly, formal education sometimes stifles originality; nevertheless, constraints of any kind often provoke the very ingenuity they appear to suppress.","native":"यह स्वीकार करना होगा कि औपचारिक शिक्षा कभी-कभी मौलिकता को दबा देती है; फिर भी, किसी भी तरह की रुकावटें अक्सर उसी सृजनशीलता को उकेरती हैं जिसे वे दबाती हुई प्रतीत होती हैं।"},{"en":"On balance, creativity seems less a mysterious talent than a willingness to tolerate failure, since genuinely novel ideas almost always emerge from numerous discarded attempts.","native":"कुल मिलाकर, रचनात्मकता किसी रहस्यमयी प्रतिभा से कम और असफलता सहने की इच्छा जैसी अधिक लगती है, क्योंकि सचमुच नए विचार लगभग हमेशा असंख्य खारिज किए गए प्रयासों से निकलते हैं।"}]},"es":{"word":"creatividad","question":"¿Es la creatividad un don natural, o puede desarrollarse mediante la práctica y la disciplina?","examples":[{"en":"While a few people seem effortlessly inventive, it could be argued that most creative achievements rest on years of unglamorous practice rather than sudden inspiration.","native":"Aunque algunas personas parecen inventivas sin esfuerzo, podría argumentarse que la mayoría de los logros creativos se apoyan en años de práctica poco glamurosa más que en inspiración repentina."},{"en":"Admittedly, formal education sometimes stifles originality; nevertheless, constraints of any kind often provoke the very ingenuity they appear to suppress.","native":"Es cierto que la educación formal a veces sofoca la originalidad; sin embargo, las limitaciones de cualquier tipo suelen provocar precisamente el ingenio que parecen reprimir."},{"en":"On balance, creativity seems less a mysterious talent than a willingness to tolerate failure, since genuinely novel ideas almost always emerge from numerous discarded attempts.","native":"En definitiva, la creatividad parece menos un talento misterioso que una disposición a tolerar el fracaso, ya que las ideas realmente novedosas casi siempre surgen de numerosos intentos descartados."}]},"zh":{"word":"创造力","question":"创造力是天生的礼物，还是可以通过练习和自律培养的？","examples":[{"en":"While a few people seem effortlessly inventive, it could be argued that most creative achievements rest on years of unglamorous practice rather than sudden inspiration.","native":"尽管少数人似乎毫不费力地富有创意，但可以认为，大多数创造性成就依靠的是多年平凡的练习，而非突如其来的灵感。"},{"en":"Admittedly, formal education sometimes stifles originality; nevertheless, constraints of any kind often provoke the very ingenuity they appear to suppress.","native":"诚然，正规教育有时会扼杀原创性；然而，任何形式的限制往往恰恰激发出它们表面上压抑的创造力。"},{"en":"On balance, creativity seems less a mysterious talent than a willingness to tolerate failure, since genuinely novel ideas almost always emerge from numerous discarded attempts.","native":"总体而言，创造力与其说是一种神秘的天赋，不如说是一种容忍失败的意愿，因为真正新颖的想法几乎总是从无数被丢弃的尝试中诞生的。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'ambition', 'Is ambition a virtue that drives progress, or a dangerous force that leads to dissatisfaction?', '{"te":{"word":"అభిలాష","question":"అభిలాష పురోగతిని నడిపించే సద్గుణమా, లేక అసంతృప్తికి దారితీసే ప్రమాదకర శక్తియా?","examples":[{"en":"While ambition unquestionably fuels achievement, it could be argued that unrestrained striving often corrodes the contentment it was supposed to secure.","native":"అభిలాష నిస్సందేహంగా విజయాలకు ఇంధనమయినప్పటికీ, అదుపులేని శ్రమ తాను భద్రపరచాలనుకున్న తృప్తినే తరచుగా తరిగివేస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, societies depend on ambitious individuals for leadership and innovation; nevertheless, cultures that glorify relentless competition tend to produce exhausted, anxious citizens.","native":"నిజానికి నాయకత్వం, ఆవిష్కరణల కోసం సమాజాలు అభిలాషులపై ఆధారపడతాయి; అయినప్పటికీ, అహర్నిశ పోటీని కీర్తించే సంస్కృతులు అలసిపోయిన, ఆందోళనగల పౌరులను సృష్టిస్తాయి."},{"en":"On balance, ambition appears healthiest when directed towards mastery rather than status, although distinguishing the two is considerably harder than motivational slogans suggest.","native":"మొత్తానికి, అభిలాష ప్రతిష్ఠ కంటే నైపుణ్యం వైపు మళ్లినప్పుడు అత్యంత ఆరోగ్యకరంగా ఉంటుంది, అయితే ఈ రెంటి మధ్య తేడా చెప్పడం ప్రేరణాత్మక నినాదాలు సూచించే దానికంటే చాలా కష్టం."}]},"hi":{"word":"महत्वाकांक्षा","question":"क्या महत्वाकांक्षा एक गुण है जो प्रगति को प्रेरित करती है, या एक खतरनाक शक्ति है जो असंतोष की ओर ले जाती है?","examples":[{"en":"While ambition unquestionably fuels achievement, it could be argued that unrestrained striving often corrodes the contentment it was supposed to secure.","native":"जबकि महत्वाकांक्षा निस्संदेह उपलब्धियों को बल देती है, यह तर्क दिया जा सकता है कि अनियंत्रित प्रयास अक्सर उसी संतोष को क्षय कर देता है जिसे वह सुरक्षित करने वाला था।"},{"en":"Admittedly, societies depend on ambitious individuals for leadership and innovation; nevertheless, cultures that glorify relentless competition tend to produce exhausted, anxious citizens.","native":"यह स्वीकार करना होगा कि समाज नेतृत्व और नवाचार के लिए महत्वाकांक्षी व्यक्तियों पर निर्भर करते हैं; फिर भी, अथक प्रतिस्पर्धा का महिमामंडन करने वाली संस्कृतियाँ थके और चिंतित नागरिक पैदा करती हैं।"},{"en":"On balance, ambition appears healthiest when directed towards mastery rather than status, although distinguishing the two is considerably harder than motivational slogans suggest.","native":"कुल मिलाकर, महत्वाकांक्षा तब सबसे स्वस्थ लगती है जब वह प्रतिष्ठा के बजाय प्रवीणता की ओर निर्देशित हो, यद्यपि दोनों में अंतर करना प्रेरणादायक नारों के सुझाव से काफी कठिन है।"}]},"es":{"word":"ambición","question":"¿Es la ambición una virtud que impulsa el progreso, o una fuerza peligrosa que conduce a la insatisfacción?","examples":[{"en":"While ambition unquestionably fuels achievement, it could be argued that unrestrained striving often corrodes the contentment it was supposed to secure.","native":"Aunque la ambición indudablemente alimenta los logros, podría argumentarse que el afán desmedido a menudo corroe la satisfacción que supuestamente debía asegurar."},{"en":"Admittedly, societies depend on ambitious individuals for leadership and innovation; nevertheless, cultures that glorify relentless competition tend to produce exhausted, anxious citizens.","native":"Es cierto que las sociedades dependen de personas ambiciosas para el liderazgo y la innovación; sin embargo, las culturas que glorifican la competencia implacable tienden a producir ciudadanos agotados y ansiosos."},{"en":"On balance, ambition appears healthiest when directed towards mastery rather than status, although distinguishing the two is considerably harder than motivational slogans suggest.","native":"En definitiva, la ambición parece más saludable cuando se orienta hacia la maestría y no hacia el estatus, aunque distinguir ambas cosas es bastante más difícil de lo que sugieren los lemas motivacionales."}]},"zh":{"word":"雄心","question":"雄心是推动进步的美德，还是导致不满的危险力量？","examples":[{"en":"While ambition unquestionably fuels achievement, it could be argued that unrestrained striving often corrodes the contentment it was supposed to secure.","native":"尽管雄心无疑能推动成就，但可以认为，不受约束的追逐往往会侵蚀它本应保障的满足感。"},{"en":"Admittedly, societies depend on ambitious individuals for leadership and innovation; nevertheless, cultures that glorify relentless competition tend to produce exhausted, anxious citizens.","native":"诚然，社会依靠有雄心的人来实现领导力和创新；然而，赞美无情竞争的文化往往会造就疲惫而焦虑的公民。"},{"en":"On balance, ambition appears healthiest when directed towards mastery rather than status, although distinguishing the two is considerably harder than motivational slogans suggest.","native":"总体而言，当雄心指向精通而非地位时，它似乎最为健康，尽管区分两者远比励志口号所暗示的要困难得多。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'trust', 'Why has trust in institutions declined in many societies, and can it be rebuilt?', '{"te":{"word":"నమ్మకం","question":"అనేక సమాజాలలో సంస్థల పట్ల నమ్మకం ఎందుకు క్షీణించింది, మరియు దాన్ని పునర్నిర్మించవచ్చా?","examples":[{"en":"It could be argued that trust erodes whenever institutions break promises without consequences, since credibility, once squandered, is notoriously difficult to restore.","native":"సంస్థలు పరిణామాలు లేకుండా వాగ్దానాలు ఉల్లంఘించినప్పుడల్లా నమ్మకం క్షయిస్తుందని చెప్పవచ్చు, ఎందుకంటే ఒక్కసారి వృథా చేసిన విశ్వసనీయతను పునరుద్ధరించడం ప్రసిద్ధంగా కష్టం."},{"en":"While scandals understandably breed suspicion, excessive cynicism is hardly cost-free, because societies cannot function when every official claim is presumed fraudulent.","native":"కుంభకోణాలు అనుమానాన్ని పెంచడం అర్థమయినప్పటికీ, అతిగా అవిశ్వాసం నష్టం లేనిది కాదు, ఎందుకంటే ప్రతి అధికారిక ప్రకటనను మోసమని భావించినప్పుడు సమాజాలు పనిచేయలేవు."},{"en":"Nevertheless, rebuilding trust is possible, though it usually demands sustained transparency and genuine accountability rather than carefully worded apologies and cosmetic reforms.","native":"అయినప్పటికీ, నమ్మకాన్ని పునర్నిర్మించడం సాధ్యమే, అయితే దానికి సాధారణంగా జాగ్రత్తగా రాసిన క్షమాపణలు, ఉపచార సంస్కరణల కంటే నిరంతర పారదర్శకత, నిజమైన జవాబుదారీతనం అవసరం."}]},"hi":{"word":"विश्वास","question":"कई समाजों में संस्थाओं पर विश्वास क्यों कम हुआ है, और क्या इसे दोबारा बनाया जा सकता है?","examples":[{"en":"It could be argued that trust erodes whenever institutions break promises without consequences, since credibility, once squandered, is notoriously difficult to restore.","native":"यह तर्क दिया जा सकता है कि जब भी संस्थाएँ बिना परिणामों के वादे तोड़ती हैं, विश्वास क्षीण होता है, क्योंकि एक बार नष्ट की गई विश्वसनीयता को बहाल करना कुख्यात रूप से कठिन है।"},{"en":"While scandals understandably breed suspicion, excessive cynicism is hardly cost-free, because societies cannot function when every official claim is presumed fraudulent.","native":"जबकि घोटाले समझ में आने योग्य रूप से संदेह पैदा करते हैं, अत्यधिक निराशावाद मुफ़्त नहीं है, क्योंकि जब हर आधिकारिक दावे को धोखा मान लिया जाए तो समाज काम नहीं कर सकते।"},{"en":"Nevertheless, rebuilding trust is possible, though it usually demands sustained transparency and genuine accountability rather than carefully worded apologies and cosmetic reforms.","native":"फिर भी, विश्वास को दोबारा बनाना संभव है, यद्यपि इसके लिए आमतौर पर सोचे-समझे शब्दों वाली माफ़ी और सतही सुधारों के बजाय निरंतर पारदर्शिता और वास्तविक जवाबदेही चाहिए।"}]},"es":{"word":"confianza","question":"¿Por qué ha disminuido la confianza en las instituciones en muchas sociedades, y puede reconstruirse?","examples":[{"en":"It could be argued that trust erodes whenever institutions break promises without consequences, since credibility, once squandered, is notoriously difficult to restore.","native":"Podría argumentarse que la confianza se erosiona cada vez que las instituciones incumplen promesas sin consecuencias, ya que la credibilidad, una vez dilapidada, es notoriamente difícil de recuperar."},{"en":"While scandals understandably breed suspicion, excessive cynicism is hardly cost-free, because societies cannot function when every official claim is presumed fraudulent.","native":"Aunque los escándalos generan comprensiblemente sospechas, el cinismo excesivo no es gratuito, porque las sociedades no pueden funcionar cuando toda afirmación oficial se presume fraudulenta."},{"en":"Nevertheless, rebuilding trust is possible, though it usually demands sustained transparency and genuine accountability rather than carefully worded apologies and cosmetic reforms.","native":"Sin embargo, reconstruir la confianza es posible, aunque suele exigir transparencia sostenida y responsabilidad genuina, en lugar de disculpas cuidadosamente redactadas y reformas cosméticas."}]},"zh":{"word":"信任","question":"为什么许多社会对机构的信任下降了，这种信任还能重建吗？","examples":[{"en":"It could be argued that trust erodes whenever institutions break promises without consequences, since credibility, once squandered, is notoriously difficult to restore.","native":"可以认为，每当机构违背承诺却无需承担后果时，信任就会受到侵蚀，因为信誉一旦挥霍殆尽，便出了名地难以恢复。"},{"en":"While scandals understandably breed suspicion, excessive cynicism is hardly cost-free, because societies cannot function when every official claim is presumed fraudulent.","native":"尽管丑闻滋生怀疑情有可原，但过度愤世嫉俗并非毫无代价，因为当每一项官方声明都被推定为欺诈时，社会就无法运转。"},{"en":"Nevertheless, rebuilding trust is possible, though it usually demands sustained transparency and genuine accountability rather than carefully worded apologies and cosmetic reforms.","native":"然而，重建信任是可能的，尽管这通常需要持续的透明度和真正的问责制，而不是措辞谨慎的道歉和表面文章式的改革。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'leadership', 'What qualities distinguish a genuinely good leader from someone who merely holds power?', '{"te":{"word":"నాయకత్వం","question":"నిజంగా మంచి నాయకుణ్ణి కేవలం అధికారంలో ఉన్నవారి నుండి వేరు చేసే గుణాలు ఏవి?","examples":[{"en":"Although charisma often wins attention, it could be argued that integrity and the willingness to admit mistakes distinguish authentic leadership from mere self-promotion.","native":"ఆకర్షణీయ వ్యక్తిత్వం తరచుగా దృష్టిని గెలుచుకున్నప్పటికీ, నిజాయితీ మరియు పొరపాట్లను ఒప్పుకునే సిద్ధాంతం ప్రామాణిక నాయకత్వాన్ని కేవలం ఆత్మప్రచారం నుండి వేరు చేస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, decisive authority matters in a crisis; nevertheless, leaders who never consult others tend to confuse obedience with genuine, durable support.","native":"నిజానికి సంక్షోభ సమయంలో నిర్ణయాత్మక అధికారం ముఖ్యం; అయినప్పటికీ, ఎప్పుడూ ఇతరులను సంప్రదించని నాయకులు విధేయతనూ, నిజమైన శాశ్వత మద్దతునూ గందరగోళం చేస్తారు."},{"en":"On balance, the finest leaders seem to measure success by what their people achieve after they leave, a standard that vanity projects rarely survive.","native":"మొత్తానికి, అత్యుత్తమ నాయకులు తాము వెళ్లిపోయిన తర్వాత తమ వ్యక్తులు ఏమి సాధించారనే దానితో విజయాన్ని కొలుస్తారు; అహంకార ప్రాజెక్టులు అరుదుగా దాటగల ప్రమాణం ఇది."}]},"hi":{"word":"नेतृत्व","question":"कौन से गुण एक सच्चे अच्छे नेता को महज़ सत्ता धारण करने वाले व्यक्ति से अलग करते हैं?","examples":[{"en":"Although charisma often wins attention, it could be argued that integrity and the willingness to admit mistakes distinguish authentic leadership from mere self-promotion.","native":"यद्यपि करिश्मा अक्सर ध्यान जीत लेता है, फिर भी यह तर्क दिया जा सकता है कि ईमानदारी और गलतियाँ स्वीकार करने की तैयारी प्रामाणिक नेतृत्व को महज़ आत्म-प्रचार से अलग करती हैं।"},{"en":"Admittedly, decisive authority matters in a crisis; nevertheless, leaders who never consult others tend to confuse obedience with genuine, durable support.","native":"यह स्वीकार करना होगा कि संकट में निर्णायक अधिकार मायने रखता है; फिर भी, जो नेता कभी दूसरों से सलाह नहीं लेते, वे आज्ञाकारिता और वास्तविक, टिकाऊ समर्थन में भ्रम पैदा करते हैं।"},{"en":"On balance, the finest leaders seem to measure success by what their people achieve after they leave, a standard that vanity projects rarely survive.","native":"कुल मिलाकर, सर्वश्रेष्ठ नेता अपने जाने के बाद अपने लोगों की उपलब्धियों से सफलता मापते प्रतीत होते हैं—यह मानदंड घमंडी परियोजनाएँ शायद ही कभी पार कर पाती हैं।"}]},"es":{"word":"liderazgo","question":"¿Qué cualidades distinguen a un líder genuinamente bueno de alguien que simplemente detenta el poder?","examples":[{"en":"Although charisma often wins attention, it could be argued that integrity and the willingness to admit mistakes distinguish authentic leadership from mere self-promotion.","native":"Aunque el carisma suele atraer la atención, podría argumentarse que la integridad y la disposición a admitir errores distinguen el liderazgo auténtico de la mera autopromoción."},{"en":"Admittedly, decisive authority matters in a crisis; nevertheless, leaders who never consult others tend to confuse obedience with genuine, durable support.","native":"Es cierto que la autoridad decisiva importa en una crisis; sin embargo, los líderes que nunca consultan a los demás tienden a confundir la obediencia con un apoyo genuino y duradero."},{"en":"On balance, the finest leaders seem to measure success by what their people achieve after they leave, a standard that vanity projects rarely survive.","native":"En definitiva, los mejores líderes parecen medir el éxito por lo que su gente logra después de que ellos se van, un criterio que los proyectos de vanidad rara vez superan."}]},"zh":{"word":"领导力","question":"哪些品质能把真正优秀的领导者与仅仅掌握权力的人区分开来？","examples":[{"en":"Although charisma often wins attention, it could be argued that integrity and the willingness to admit mistakes distinguish authentic leadership from mere self-promotion.","native":"尽管个人魅力往往能赢得关注，但可以认为，正直和承认错误的意愿才能将真正的领导力与纯粹的自我推销区分开来。"},{"en":"Admittedly, decisive authority matters in a crisis; nevertheless, leaders who never consult others tend to confuse obedience with genuine, durable support.","native":"诚然，在危机中果断的权威很重要；然而，从不征求他人意见的领导者往往会把服从与真诚、持久的支持混为一谈。"},{"en":"On balance, the finest leaders seem to measure success by what their people achieve after they leave, a standard that vanity projects rarely survive.","native":"总体而言，最优秀的领导者似乎以他们离开后下属取得的成就来衡量成功——虚荣的项目很少能经得起这一标准。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'digital footprint', 'Should people be more concerned about the permanent digital footprints they leave online?', '{"te":{"word":"డిజిటల్ ముద్ర","question":"తాము ఆన్‌లైన్‌లో వదిలే శాశ్వత డిజిటల్ ముద్రల గురించి ప్రజలు మరింత ఆందోళన చెందాలా?","examples":[{"en":"While younger generations treat online sharing casually, it could be argued that data collected today may be judged by standards, employers, and algorithms that do not yet exist.","native":"యువ తరాలు ఆన్‌లైన్ భాగస్వామ్యాన్ని సాధారణంగా తీసుకున్నప్పటికీ, ఈరోజు సేకరించిన డేటాను ఇంకా లేని ప్రమాణాలు, యజమానులు మరియు అల్గారిథమ్‌ల ద్వారా అంచనా వేయవచ్చని చెప్పవచ్చు."},{"en":"Admittedly, deleting accounts feels reassuring; nevertheless, archived copies and screenshots make true erasure largely illusory once information has circulated widely.","native":"నిజానికి ఖాతాలను తొలగించడం ధైర్యాన్ని ఇస్తుంది; అయినప్పటికీ, సమాచారం విస్తృతంగా ప్రసారమైన తర్వాత ఆర్కైవ్ కాపీలు, స్క్రీన్‌షాట్‌లు నిజమైన తొలగింపును పెద్దగా భ్రమగా మారుస్తాయి."},{"en":"On balance, a degree of caution seems prudent, although living in perpetual fear of one''s own shadow would be an unreasonable price for digital participation.","native":"మొత్తానికి, కొంత జాగ్రత్త వివేకమే అనిపిస్తుంది, అయితే తమ స్వంత నీడ పట్ల శాశ్వత భయంతో జీవించడం డిజిటల్ భాగస్వామ్యానికి అన్యాయమైన ధర అవుతుంది."}]},"hi":{"word":"डिजिटल फुटप्रिंट","question":"क्या लोगों को अपने ऑनलाइन छोड़े गए स्थायी डिजिटल फुटप्रिंट को लेकर अधिक चिंतित होना चाहिए?","examples":[{"en":"While younger generations treat online sharing casually, it could be argued that data collected today may be judged by standards, employers, and algorithms that do not yet exist.","native":"जबकि युवा पीढ़ियाँ ऑनलाइन साझाकरण को बेलगाम मानती हैं, यह तर्क दिया जा सकता है कि आज एकत्रित डेटा का मूल्यांकन उन मानकों, नियोक्ताओं और एल्गोरिदम से हो सकता है जो अभी मौजूद ही नहीं हैं।"},{"en":"Admittedly, deleting accounts feels reassuring; nevertheless, archived copies and screenshots make true erasure largely illusory once information has circulated widely.","native":"यह स्वीकार करना होगा कि खाते हटाना सुकून देता है; फिर भी, जानकारी के व्यापक रूप से फैलने के बाद संग्रहीत प्रतियाँ और स्क्रीनशॉट सच्चे विलोपन को काफी हद तक भ्रम बना देते हैं।"},{"en":"On balance, a degree of caution seems prudent, although living in perpetual fear of one''s own shadow would be an unreasonable price for digital participation.","native":"कुल मिलाकर, कुछ हद तक सावधानी विवेकपूर्ण लगती है, यद्यपि अपनी ही परछाईं से हमेशा डरते रहना डिजिटल भागीदारी की अनुचित कीमत होगी।"}]},"es":{"word":"huella digital","question":"¿Debería preocuparse más la gente por las huellas digitales permanentes que deja en internet?","examples":[{"en":"While younger generations treat online sharing casually, it could be argued that data collected today may be judged by standards, employers, and algorithms that do not yet exist.","native":"Aunque las generaciones jóvenes tratan con ligereza compartir en línea, podría argumentarse que los datos recopilados hoy podrían ser juzgados por estándares, empleadores y algoritmos que aún no existen."},{"en":"Admittedly, deleting accounts feels reassuring; nevertheless, archived copies and screenshots make true erasure largely illusory once information has circulated widely.","native":"Es cierto que eliminar cuentas resulta tranquilizador; sin embargo, las copias archivadas y las capturas de pantalla hacen que el borrado real sea en gran parte ilusorio una vez que la información circula ampliamente."},{"en":"On balance, a degree of caution seems prudent, although living in perpetual fear of one''s own shadow would be an unreasonable price for digital participation.","native":"En definitiva, cierto grado de cautela parece prudente, aunque vivir con miedo perpetuo de la propia sombra sería un precio irrazonable por la participación digital."}]},"zh":{"word":"数字足迹","question":"人们是否应该更加担心自己在网络上留下的永久数字足迹？","examples":[{"en":"While younger generations treat online sharing casually, it could be argued that data collected today may be judged by standards, employers, and algorithms that do not yet exist.","native":"尽管年轻一代对待网络分享很随意，但可以认为，今天收集的数据可能会被尚不存在的标准、雇主和算法来评判。"},{"en":"Admittedly, deleting accounts feels reassuring; nevertheless, archived copies and screenshots make true erasure largely illusory once information has circulated widely.","native":"诚然，删除账户让人安心；然而，一旦信息广泛传播，存档副本和截图就使得真正的删除在很大程度上成为幻觉。"},{"en":"On balance, a degree of caution seems prudent, although living in perpetual fear of one''s own shadow would be an unreasonable price for digital participation.","native":"总体而言，保持一定程度的谨慎似乎是明智的，尽管永远生活在对自己阴影的恐惧中，将是参与数字生活的不合理代价。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'ageing population', 'How should societies adapt to the economic and social effects of an ageing population?', '{"te":{"word":"వృద్ధాప్య జనాభా","question":"వృద్ధాప్య జనాభా యొక్క ఆర్థిక, సామాజిక ప్రభావాలకు సమాజాలు ఎలా అనుగుణంగా మారాలి?","examples":[{"en":"While longer lifespans represent a triumph of medicine, it could be argued that pension systems designed for shorter retirements are quietly becoming unsustainable.","native":"దీర్ఘాయువు వైద్యం విజయాన్ని సూచించినప్పటికీ, తక్కువ పదవీ విరమణల కోసం రూపొందించిన పెన్షన్ వ్యవస్థలు నిశ్శబ్దంగా స్థిరత్వం కోల్పోతున్నాయని చెప్పవచ్చు."},{"en":"Admittedly, raising the retirement age balances budgets; nevertheless, such policies ignore how unevenly physical decline affects manual workers compared with office professionals.","native":"నిజానికి పదవీ విరమణ వయసును పెంచడం బడ్జెట్లను సమతుల్యం చేస్తుంది; అయినప్పటికీ, శారీరక క్షీణత భౌతిక కార్మికులనూ కార్యాలయ నిపుణులనూ ఎంత అసమానంగా ప్రభావితం చేస్తుందో అలాంటి విధానాలు పట్టించుకోవు."},{"en":"On balance, ageing societies will need to value older citizens as contributors rather than burdens, although achieving that cultural shift is easier said than done.","native":"మొత్తానికి, వృద్ధాప్య సమాజాలు వృద్ధ పౌరులను భారాలుగా కాకుండా సహకారులుగా విలువ చేయాలి, అయితే ఆ సాంస్కృతిక మార్పు చెప్పడం కంటే చేయడం కష్టం."}]},"hi":{"word":"बूढ़ी आबादी","question":"बूढ़ी होती आबादी के आर्थिक और सामाजिक प्रभावों के अनुकूल समाजों को कैसे ढलना चाहिए?","examples":[{"en":"While longer lifespans represent a triumph of medicine, it could be argued that pension systems designed for shorter retirements are quietly becoming unsustainable.","native":"जबकि लंबी उम्र चिकित्सा की जीत का प्रतीक है, यह तर्क दिया जा सकता है कि छोटी सेवानिवृत्ति के लिए बनाई गई पेंशन व्यवस्थाएँ चुपचाप अस्थिर होती जा रही हैं।"},{"en":"Admittedly, raising the retirement age balances budgets; nevertheless, such policies ignore how unevenly physical decline affects manual workers compared with office professionals.","native":"यह स्वीकार करना होगा कि सेवानिवृत्ति की आयु बढ़ाना बजट संतुलित करता है; फिर भी, ऐसी नीतियाँ अनदेखा करती हैं कि शारीरिक क्षय शारीरिक श्रमिकों को कार्यालयीन पेशेवरों की तुलना में कितना असमान रूप से प्रभावित करता है।"},{"en":"On balance, ageing societies will need to value older citizens as contributors rather than burdens, although achieving that cultural shift is easier said than done.","native":"कुल मिलाकर, बूढ़े समाजों को वरिष्ठ नागरिकों को बोझ के बजाय योगदानकर्ता मानना होगा, यद्यपि यह सांस्कृतिक बदलाव लाना कहने से कहीं कठिन है।"}]},"es":{"word":"envejecimiento de la población","question":"¿Cómo deberían adaptarse las sociedades a los efectos económicos y sociales del envejecimiento de la población?","examples":[{"en":"While longer lifespans represent a triumph of medicine, it could be argued that pension systems designed for shorter retirements are quietly becoming unsustainable.","native":"Aunque una mayor longevidad representa un triunfo de la medicina, podría argumentarse que los sistemas de pensiones diseñados para jubilaciones más cortas se están volviendo silenciosamente insostenibles."},{"en":"Admittedly, raising the retirement age balances budgets; nevertheless, such policies ignore how unevenly physical decline affects manual workers compared with office professionals.","native":"Es cierto que elevar la edad de jubilación equilibra los presupuestos; sin embargo, tales políticas ignoran cuán desigualmente afecta el declive físico a los trabajadores manuales frente a los profesionales de oficina."},{"en":"On balance, ageing societies will need to value older citizens as contributors rather than burdens, although achieving that cultural shift is easier said than done.","native":"En definitiva, las sociedades envejecidas tendrán que valorar a los ciudadanos mayores como contribuyentes y no como cargas, aunque lograr ese cambio cultural es más fácil de decir que de hacer."}]},"zh":{"word":"人口老龄化","question":"社会应如何适应人口老龄化带来的经济和社会影响？","examples":[{"en":"While longer lifespans represent a triumph of medicine, it could be argued that pension systems designed for shorter retirements are quietly becoming unsustainable.","native":"尽管寿命延长代表了医学的胜利，但可以认为，为较短退休期设计的养老金体系正在悄然变得不可持续。"},{"en":"Admittedly, raising the retirement age balances budgets; nevertheless, such policies ignore how unevenly physical decline affects manual workers compared with office professionals.","native":"诚然，提高退休年龄可以平衡预算；然而，这类政策忽视了体力衰退对体力劳动者与办公室专业人士的影响是多么不均等。"},{"en":"On balance, ageing societies will need to value older citizens as contributors rather than burdens, although achieving that cultural shift is easier said than done.","native":"总体而言，老龄化社会需要把老年公民视为贡献者而非负担，尽管实现这种文化转变知易行难。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'censorship', 'Under what circumstances, if any, is censorship justified in a free society?', '{"te":{"word":"సెన్సార్‌షిప్","question":"స్వేచ్ఛాయుత సమాజంలో ఏ పరిస్థితుల్లోనైనా సెన్సార్‌షిప్ సమర్థనీయమా?","examples":[{"en":"While few endorse censorship in principle, it could be argued that incitement to violence crosses a line where unrestricted expression begins to destroy the rights of others.","native":"సూత్రప్రాయంగా సెన్సార్‌షిప్‌ను తక్కువ మందే ఆమోదిస్తారేమో కానీ, హింసకు ఉసిగొల్పడం నిరాంక్ష వ్యక్తీకరణ ఇతరుల హక్కులను ధ్వంసం చేయడం ప్రారంభించే సరిహద్దును దాటుతుందని చెప్పవచ్చు."},{"en":"Admittedly, governments habitually invoke public safety to silence critics; nevertheless, the absence of any limits at all would leave the vulnerable exposed to coordinated harassment.","native":"నిజానికి ప్రభుత్వాలు విమర్శకులను మౌనపరచడానికి అలవాటుగా ప్రజా భద్రతను ప్రస్తావిస్తాయి; అయినప్పటికీ, ఎటువంటి పరిమితులూ లేకపోవడం బలహీనులను సంయుక్త వేధింపులకు గురి చేస్తుంది."},{"en":"On balance, censorship seems defensible only when it is narrow, transparent, and reversible, since power granted temporarily has a notorious tendency to become permanent.","native":"మొత్తానికి, సెన్సార్‌షిప్ పరిమితంగా, పారదర్శకంగా, రద్దు చేయగలిగినట్టుగా ఉన్నప్పుడే సమర్థనీయంగా ఉంటుంది, ఎందుకంటే తాత్కాలికంగా ఇచ్చిన అధికారం శాశ్వతమవ్వడానికి ప్రసిద్ధ ధోరణి కలది."}]},"hi":{"word":"सेंसरशिप","question":"स्वतंत्र समाज में किन परिस्थितियों में, यदि कोई हों, सेंसरशिप उचित है?","examples":[{"en":"While few endorse censorship in principle, it could be argued that incitement to violence crosses a line where unrestricted expression begins to destroy the rights of others.","native":"जबकि सिद्धांततः सेंसरशिप का समर्थन बहुत कम लोग करते हैं, यह तर्क दिया जा सकता है कि हिंसा के लिए उकसाना उस सीमा को पार करता है जहाँ अप्रतिबंध अभिव्यक्ति दूसरों के अधिकारों को नष्ट करने लगती है।"},{"en":"Admittedly, governments habitually invoke public safety to silence critics; nevertheless, the absence of any limits at all would leave the vulnerable exposed to coordinated harassment.","native":"यह स्वीकार करना होगा कि सरकारें आलोचकों को चुप कराने के लिए आदतन जनसुरक्षा का हवाला देती हैं; फिर भी, किसी भी सीमा के बिल्कुल न होने से कमज़ोर लोग संगठित उत्पीड़न के शिकार होंगे।"},{"en":"On balance, censorship seems defensible only when it is narrow, transparent, and reversible, since power granted temporarily has a notorious tendency to become permanent.","native":"कुल मिलाकर, सेंसरशिप तभी बचावयोग्य लगती है जब वह संकीर्ण, पारदर्शी और उलटने योग्य हो, क्योंकि अस्थायी रूप से दी गई शक्ति स्थायी बनने की कुख्यात प्रवृत्ति रखती है।"}]},"es":{"word":"censura","question":"¿En qué circunstancias, si es que en alguna, se justifica la censura en una sociedad libre?","examples":[{"en":"While few endorse censorship in principle, it could be argued that incitement to violence crosses a line where unrestricted expression begins to destroy the rights of others.","native":"Aunque pocos respaldan la censura en principio, podría argumentarse que la incitación a la violencia cruza una línea donde la expresión sin restricciones empieza a destruir los derechos de los demás."},{"en":"Admittedly, governments habitually invoke public safety to silence critics; nevertheless, the absence of any limits at all would leave the vulnerable exposed to coordinated harassment.","native":"Es cierto que los gobiernos invocan habitualmente la seguridad pública para silenciar a los críticos; sin embargo, la ausencia total de límites dejaría a los vulnerables expuestos al acoso coordinado."},{"en":"On balance, censorship seems defensible only when it is narrow, transparent, and reversible, since power granted temporarily has a notorious tendency to become permanent.","native":"En definitiva, la censura solo parece defendible cuando es estrecha, transparente y reversible, ya que el poder concedido temporalmente tiene una notoria tendencia a volverse permanente."}]},"zh":{"word":"审查制度","question":"在自由社会中，审查制度在何种情况下（如果有的话）是正当的？","examples":[{"en":"While few endorse censorship in principle, it could be argued that incitement to violence crosses a line where unrestricted expression begins to destroy the rights of others.","native":"尽管原则上很少有人赞同审查，但可以认为，煽动暴力越过了一条界线——在那里，不受限制的表达开始摧毁他人的权利。"},{"en":"Admittedly, governments habitually invoke public safety to silence critics; nevertheless, the absence of any limits at all would leave the vulnerable exposed to coordinated harassment.","native":"诚然，政府惯常以公共安全为借口让批评者噤声；然而，完全没有任何限制会让弱势群体暴露于有组织的骚扰之中。"},{"en":"On balance, censorship seems defensible only when it is narrow, transparent, and reversible, since power granted temporarily has a notorious tendency to become permanent.","native":"总体而言，审查只有在范围狭窄、透明且可撤销时似乎才是可辩护的，因为临时授予的权力出了名地容易变成永久。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'surveillance', 'Does mass surveillance make us safer, or does it undermine the freedoms it claims to protect?', '{"te":{"word":"నిఘా","question":"సమూహ నిఘా మనల్ని సురక్షితంగా చేస్తుందా, లేక తాను రక్షిస్తున్నట్టు చెప్పుకునే స్వేచ్ఛలను బలహీనపరుస్తుందా?","examples":[{"en":"While governments insist surveillance prevents attacks, it could be argued that the evidence for such claims remains surprisingly thin relative to the powers accumulated.","native":"ప్రభుత్వాలు నిఘా దాడులను నివారిస్తుందని పట్టుబట్టినప్పటికీ, పేరుకుపోయిన అధికారాలతో పోలిస్తే అలాంటి వాదనలకు సాక్ష్యాలు ఆశ్చర్యకరంగా పలుచగా ఉన్నాయని చెప్పవచ్చు."},{"en":"Admittedly, most people feel they have nothing to hide; nevertheless, constant monitoring demonstrably chills dissent, journalism, and even private conversation among ordinary citizens.","native":"నిజానికి చాలామందికి దాచడానికి ఏమీ లేదనిపిస్తుంది; అయినప్పటికీ, నిరంతర పర్యవేక్షణ అసమ్మతిని, జర్నలిజాన్ని, సామాన్య పౌరుల వ్యక్తిగత సంభాషణలను కూడా నిరుత్సాహపరుస్తుందని స్పష్టంగా తెలుస్తుంది."},{"en":"On balance, security gained through surveillance seems fragile when it erodes the trust and openness that genuinely keep societies stable over the long term.","native":"మొత్తానికి, నిఘా ద్వారా వచ్చే భద్రత, సమాజాలను దీర్ఘకాలం స్థిరంగా ఉంచే నమ్మకాన్నీ వెల్లడి స్వభావాన్నీ క్షయపరిచినప్పుడు పెళుసుగా ఉంటుంది."}]},"hi":{"word":"निगरानी","question":"क्या सामूहिक निगरानी हमें सुरक्षित बनाती है, या वह उन्हीं स्वतंत्रताओं को कमज़ोर करती है जिनकी रक्षा का दावा करती है?","examples":[{"en":"While governments insist surveillance prevents attacks, it could be argued that the evidence for such claims remains surprisingly thin relative to the powers accumulated.","native":"जबकि सरकारें ज़ोर देती हैं कि निगरानी हमलों को रोकती है, यह तर्क दिया जा सकता है कि जुटाई गई शक्तियों की तुलना में ऐसे दावों का प्रमाण आश्चर्यजनक रूप से कमज़ोर है।"},{"en":"Admittedly, most people feel they have nothing to hide; nevertheless, constant monitoring demonstrably chills dissent, journalism, and even private conversation among ordinary citizens.","native":"यह स्वीकार करना होगा कि अधिकांश लोग सोचते हैं कि उन्हें छिपाने को कुछ नहीं है; फिर भी, निरंतर नज़र असहमति, पत्रकारिता और आम नागरिकों की निजी बातचीत को भी प्रदर्शनात्मक रूप से ठंडा कर देती है।"},{"en":"On balance, security gained through surveillance seems fragile when it erodes the trust and openness that genuinely keep societies stable over the long term.","native":"कुल मिलाकर, निगरानी से मिली सुरक्षा भंगुर लगती है जब वह उस विश्वास और खुलेपन को क्षय करती है जो वास्तव में समाजों को दीर्घकाल तक स्थिर रखते हैं।"}]},"es":{"word":"vigilancia","question":"¿Nos hace más seguros la vigilancia masiva, o socava las libertades que dice proteger?","examples":[{"en":"While governments insist surveillance prevents attacks, it could be argued that the evidence for such claims remains surprisingly thin relative to the powers accumulated.","native":"Aunque los gobiernos insisten en que la vigilancia previene ataques, podría argumentarse que la evidencia de tales afirmaciones sigue siendo sorprendentemente escasa en relación con los poderes acumulados."},{"en":"Admittedly, most people feel they have nothing to hide; nevertheless, constant monitoring demonstrably chills dissent, journalism, and even private conversation among ordinary citizens.","native":"Es cierto que la mayoría siente que no tiene nada que ocultar; sin embargo, la monitorización constante enfría demostrablemente la disidencia, el periodismo e incluso la conversación privada de los ciudadanos."},{"en":"On balance, security gained through surveillance seems fragile when it erodes the trust and openness that genuinely keep societies stable over the long term.","native":"En definitiva, la seguridad obtenida mediante la vigilancia parece frágil cuando erosiona la confianza y la apertura que realmente mantienen estables a las sociedades a largo plazo."}]},"zh":{"word":"监控","question":"大规模监控让我们更安全，还是破坏了它声称要保护的自由？","examples":[{"en":"While governments insist surveillance prevents attacks, it could be argued that the evidence for such claims remains surprisingly thin relative to the powers accumulated.","native":"尽管政府坚称监控能防止袭击，但可以认为，与所积累的权力相比，此类说法的证据少得令人惊讶。"},{"en":"Admittedly, most people feel they have nothing to hide; nevertheless, constant monitoring demonstrably chills dissent, journalism, and even private conversation among ordinary citizens.","native":"诚然，大多数人觉得自己没有什么可隐瞒的；然而，持续的监控明显抑制了异见、新闻工作，甚至普通公民的私人交谈。"},{"en":"On balance, security gained through surveillance seems fragile when it erodes the trust and openness that genuinely keep societies stable over the long term.","native":"总体而言，通过监控获得的安全似乎是脆弱的，因为它侵蚀了真正让社会长期保持稳定的信任与开放。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'capitalism', 'Does capitalism reward hard work fairly, or does it mainly benefit those who already own wealth?', '{"te":{"word":"మూలధనవాదం","question":"మూలధనవాదం కష్టపడేవారికి న్యాయమైన ప్రతిఫలం ఇస్తుందా, లేక ఇప్పటికే సంపద ఉన్నవారికే ప్రధానంగా ప్రయోజనం చేకూరుస్తుందా?","examples":[{"en":"While capitalism has lifted millions out of poverty, it could be argued that its rewards flow disproportionately to owners of capital rather than creators of value.","native":"మూలధనవాదం కోట్లాదిమందిని పేదరికం నుండి బయటపడేసినప్పటికీ, దాని ప్రతిఫలాలు విలువను సృష్టించేవారి కంటే మూలధన యజమానులకు అసమానంగా ప్రవహిస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, competition drives efficiency and innovation; nevertheless, without regulation, markets tend to concentrate power in ways that eventually undermine competition itself.","native":"నిజానికి పోటీ సామర్థ్యాన్నీ ఆవిష్కరణలనూ నడిపిస్తుంది; అయినప్పటికీ, నియంత్రణ లేకుంటే మార్కెట్లు చివరికి పోటీనే బలహీనపరిచే విధంగా అధికారాన్ని కేంద్రీకరిస్తాయి."},{"en":"On balance, the system seems excellent at generating wealth yet considerably less reliable at distributing it, which explains why debates about fairness never quite disappear.","native":"మొత్తానికి, ఈ వ్యవస్థ సంపదను సృష్టించడంలో అద్భుతమైనప్పటికీ దాన్ని పంపిణీ చేయడంలో చాలా తక్కువ నమ్మదగినది; న్యాయం గురించిన చర్చలు ఎందుకు అంతిపోవో ఇది వివరిస్తుంది."}]},"hi":{"word":"पूँजीवाद","question":"क्या पूँजीवाद मेहनत का उचित फल देता है, या यह मुख्य रूप से उन्हीं को लाभ पहुँचाता है जिनके पास पहले से धन है?","examples":[{"en":"While capitalism has lifted millions out of poverty, it could be argued that its rewards flow disproportionately to owners of capital rather than creators of value.","native":"जबकि पूँजीवाद ने लाखों लोगों को गरीबी से बाहर निकाला है, यह तर्क दिया जा सकता है कि इसके पुरस्कार मूल्य रचने वालों की तुलना में पूँजी के मालिकों को असमानुपातिक रूप से मिलते हैं।"},{"en":"Admittedly, competition drives efficiency and innovation; nevertheless, without regulation, markets tend to concentrate power in ways that eventually undermine competition itself.","native":"यह स्वीकार करना होगा कि प्रतिस्पर्धा दक्षता और नवाचार चलाती है; फिर भी, विनियमन के बिना, बाज़ार शक्ति को ऐसे तरीकों से केंद्रित करते हैं जो अंततः स्वयं प्रतिस्पर्धा को ही कमज़ोर कर देते हैं।"},{"en":"On balance, the system seems excellent at generating wealth yet considerably less reliable at distributing it, which explains why debates about fairness never quite disappear.","native":"कुल मिलाकर, यह व्यवस्था धन पैदा करने में उत्कृष्ट लगती है, परंतु उसे बाँटने में काफी कम विश्वसनीय—यही कारण है कि न्याय पर बहस कभी पूरी तरह खत्म नहीं होती।"}]},"es":{"word":"capitalismo","question":"¿Recompensa el capitalismo el trabajo duro con justicia, o beneficia principalmente a quienes ya poseen riqueza?","examples":[{"en":"While capitalism has lifted millions out of poverty, it could be argued that its rewards flow disproportionately to owners of capital rather than creators of value.","native":"Aunque el capitalismo ha sacado a millones de la pobreza, podría argumentarse que sus recompensas fluyen desproporcionadamente hacia los dueños del capital más que hacia los creadores de valor."},{"en":"Admittedly, competition drives efficiency and innovation; nevertheless, without regulation, markets tend to concentrate power in ways that eventually undermine competition itself.","native":"Es cierto que la competencia impulsa la eficiencia y la innovación; sin embargo, sin regulación, los mercados tienden a concentrar el poder de maneras que acaban socavando la propia competencia."},{"en":"On balance, the system seems excellent at generating wealth yet considerably less reliable at distributing it, which explains why debates about fairness never quite disappear.","native":"En definitiva, el sistema parece excelente generando riqueza, pero considerablemente menos fiable distribuyéndola, lo que explica por qué los debates sobre la equidad nunca desaparecen del todo."}]},"zh":{"word":"资本主义","question":"资本主义是否公平地回报辛勤劳动，还是主要让已经拥有财富的人受益？","examples":[{"en":"While capitalism has lifted millions out of poverty, it could be argued that its rewards flow disproportionately to owners of capital rather than creators of value.","native":"尽管资本主义使数百万人摆脱了贫困，但可以认为，其回报不成比例地流向资本所有者，而非价值创造者。"},{"en":"Admittedly, competition drives efficiency and innovation; nevertheless, without regulation, markets tend to concentrate power in ways that eventually undermine competition itself.","native":"诚然，竞争推动了效率和创新；然而，缺乏监管时，市场往往会以最终削弱竞争本身的方式集中权力。"},{"en":"On balance, the system seems excellent at generating wealth yet considerably less reliable at distributing it, which explains why debates about fairness never quite disappear.","native":"总体而言，这个体系在创造财富方面似乎很出色，但在分配财富方面却远不那么可靠——这解释了为什么关于公平的争论从未真正消失。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'meritocracy', 'Is meritocracy a fair ideal, or does it disguise the advantages people are born with?', '{"te":{"word":"ప్రతిభావాదం","question":"ప్రతిభావాదం న్యాయమైన ఆదర్శమా, లేక ప్రజలు పుట్టుకతో పొందే అనుకూలతలను కప్పిపుచ్చేదేనా?","examples":[{"en":"While rewarding talent sounds obviously just, it could be argued that merit itself is largely a product of fortunate circumstances few recipients care to acknowledge.","native":"ప్రతిభకు ప్రతిఫలం ఇవ్వడం స్పష్టంగా న్యాయంగా అనిపించినప్పటికీ, ప్రతిభ అనేది పెద్దగా అదృష్ట పరిస్థితుల ఉత్పత్తి అని చెప్పవచ్చు; దీన్ని పొందినవారు అరుదుగా అంగీకరిస్తారు."},{"en":"Admittedly, meritocratic competition outperforms nepotism and inherited privilege; nevertheless, winners in such systems often develop a corrosive contempt for those who fail.","native":"నిజానికి ప్రతిభాధారిత పోటీ స్వజనపక్షపాతం, వంశపారంపర్య ప్రాబల్యం కంటే మెరుగ్గా ఉంటుంది; అయినప్పటికీ, అలాంటి వ్యవస్థల్లో విజేతలు తరచుగా ఓడిపోయినవారి పట్ల తీవ్రమైన తృణీకారాన్ని పెంచుకుంటారు."},{"en":"On balance, meritocracy seems defensible only when genuine equality of opportunity exists beforehand, a condition that most societies proclaim far more readily than they achieve.","native":"మొత్తానికి, సమాన అవకాశం ముందుగా నిజంగా ఉన్నప్పుడే ప్రతిభావాదం సమర్థనీయంగా ఉంటుంది; చాలా సమాజాలు సాధించడం కంటే ప్రకటించడానికే ఎక్కువగా ఇష్టపడే షరతు ఇది."}]},"hi":{"word":"प्रतिभावाद","question":"क्या प्रतिभावाद एक न्यायपूर्ण आदर्श है, या यह उन सुविधाओं को छिपाता है जो लोगों को जन्म से मिलती हैं?","examples":[{"en":"While rewarding talent sounds obviously just, it could be argued that merit itself is largely a product of fortunate circumstances few recipients care to acknowledge.","native":"जबकि प्रतिभा को पुरस्कृत करना स्पष्ट रूप से न्यायोचित लगता है, यह तर्क दिया जा सकता है कि प्रतिभा स्वयं काफी हद तक भाग्यशाली परिस्थितियों का उत्पाद है, जिसे प्राप्तकर्ता शायद ही स्वीकार करते हैं।"},{"en":"Admittedly, meritocratic competition outperforms nepotism and inherited privilege; nevertheless, winners in such systems often develop a corrosive contempt for those who fail.","native":"यह स्वीकार करना होगा कि प्रतिभावादी प्रतिस्पर्धा भाई-भतीजावाद और विरासत के विशेषाधिकार से बेहतर है; फिर भी, ऐसी व्यवस्थाओं के विजेता अक्सर असफल लोगों के प्रति विनाशकारी तिरस्कार विकसित कर लेते हैं।"},{"en":"On balance, meritocracy seems defensible only when genuine equality of opportunity exists beforehand, a condition that most societies proclaim far more readily than they achieve.","native":"कुल मिलाकर, प्रतिभावाद तभी बचावयोग्य लगता है जब पहले से अवसर की वास्तविक समानता मौजूद हो—यह शर्त अधिकांश समाज प्राप्त करने से कहीं अधिक आसानी से घोषित करते हैं।"}]},"es":{"word":"meritocracia","question":"¿Es la meritocracia un ideal justo, o disimula las ventajas con las que nacen las personas?","examples":[{"en":"While rewarding talent sounds obviously just, it could be argued that merit itself is largely a product of fortunate circumstances few recipients care to acknowledge.","native":"Aunque recompensar el talento suena obviamente justo, podría argumentarse que el mérito mismo es en gran parte producto de circunstancias afortunadas que pocos beneficiarios se dignan reconocer."},{"en":"Admittedly, meritocratic competition outperforms nepotism and inherited privilege; nevertheless, winners in such systems often develop a corrosive contempt for those who fail.","native":"Es cierto que la competencia meritocrática supera al nepotismo y al privilegio heredado; sin embargo, los ganadores de tales sistemas a menudo desarrollan un desprecio corrosivo hacia quienes fracasan."},{"en":"On balance, meritocracy seems defensible only when genuine equality of opportunity exists beforehand, a condition that most societies proclaim far more readily than they achieve.","native":"En definitiva, la meritocracia solo parece defendible cuando existe de antemano una igualdad de oportunidades genuina, condición que la mayoría de las sociedades proclaman con mucha más facilidad de la que la alcanzan."}]},"zh":{"word":"精英制度","question":"精英制度是公平的理想，还是掩盖了人们与生俱来的优势？","examples":[{"en":"While rewarding talent sounds obviously just, it could be argued that merit itself is largely a product of fortunate circumstances few recipients care to acknowledge.","native":"尽管奖励才能听起来显然很公正，但可以认为，功绩本身在很大程度上是幸运环境的产物，而受益者很少愿意承认这一点。"},{"en":"Admittedly, meritocratic competition outperforms nepotism and inherited privilege; nevertheless, winners in such systems often develop a corrosive contempt for those who fail.","native":"诚然，精英式竞争胜过任人唯亲和世袭特权；然而，这类制度中的赢家往往会对失败者滋生一种腐蚀性的蔑视。"},{"en":"On balance, meritocracy seems defensible only when genuine equality of opportunity exists beforehand, a condition that most societies proclaim far more readily than they achieve.","native":"总体而言，只有当真正的机会平等事先存在时，精英制度似乎才是可辩护的——而大多数社会对这一条件的宣扬远比其实现要容易得多。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'bureaucracy', 'Is bureaucracy a necessary evil, or does it do more harm than good?', '{"te":{"word":"అధికారతంత్రం","question":"అధికారతంత్రం అనివార్యమైన కీడా, లేక మేలు కంటే కీడే ఎక్కువ చేస్తుందా?","examples":[{"en":"While bureaucracy frustrates almost everyone who encounters it, it could be argued that predictable rules protect citizens far better than the whims of officials.","native":"అధికారతంత్రం దాన్ని ఎదుర్కొనే దాదాపు ప్రతివారిని విసిగించినప్పటికీ, అధికారుల ఉత్పాటాల కంటే ముందుగా చెప్పగల నియమాలు పౌరులను చాలా బాగా రక్షిస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, excessive procedures waste time and stifle initiative; nevertheless, the alternative, arbitrary personal discretion, has historically proven considerably more corrupt and unjust.","native":"నిజానికి అతిగా విధానాలు సమయాన్ని వృథా చేసి చొరవను కుదించేస్తాయి; అయినప్పటికీ, ప్రత్యామ్నాయమైన అనియంత్ర వ్యక్తిగత వివేచన చారిత్రకంగా చాలా అవినీతిపరంగా, అన్యాయంగా నిరూపితమైంది."},{"en":"On balance, bureaucracy resembles an immune system: indispensable in moderation, yet capable of attacking the very organism it exists to defend when it grows unchecked.","native":"మొత్తానికి, అధికారతంత్రం రోగనిరోధక వ్యవస్థలాంటిది: మితంగా ఉంటే అత్యవసరం, అయితే అదుపుతప్పి పెరిగితే తాను రక్షించాల్సిన జీవినే దాడి చేయగలదు."}]},"hi":{"word":"नौकरशाही","question":"क्या नौकरशाही एक आवश्यक बुराई है, या यह भलाई से अधिक नुकसान करती है?","examples":[{"en":"While bureaucracy frustrates almost everyone who encounters it, it could be argued that predictable rules protect citizens far better than the whims of officials.","native":"जबकि नौकरशाही इससे जुड़ने वाले लगभग हर व्यक्ति को परेशान करती है, यह तर्क दिया जा सकता है कि अनुमानित नियम अधिकारियों की मनमानी की तुलना में नागरिकों की कहीं बेहतर रक्षा करते हैं।"},{"en":"Admittedly, excessive procedures waste time and stifle initiative; nevertheless, the alternative, arbitrary personal discretion, has historically proven considerably more corrupt and unjust.","native":"यह स्वीकार करना होगा कि अत्यधिक प्रक्रियाएँ समय बर्बाद करती हैं और पहल को दबाती हैं; फिर भी, विकल्प—मनमाना व्यक्तिगत विवेक—ऐतिहासिक रूप से काफी अधिक भ्रष्ट और अनुचित सिद्ध हुआ है।"},{"en":"On balance, bureaucracy resembles an immune system: indispensable in moderation, yet capable of attacking the very organism it exists to defend when it grows unchecked.","native":"कुल मिलाकर, नौकरशाही प्रतिरक्षा प्रणाली जैसी है: संयम में अपरिहार्य, फिर भी अनियंत्रित बढ़ने पर उसी शरीर पर हमला करने में सक्षम जिसकी रक्षा के लिए वह मौजूद है।"}]},"es":{"word":"burocracia","question":"¿Es la burocracia un mal necesario, o causa más daño que beneficio?","examples":[{"en":"While bureaucracy frustrates almost everyone who encounters it, it could be argued that predictable rules protect citizens far better than the whims of officials.","native":"Aunque la burocracia frustra a casi todo el que la encuentra, podría argumentarse que las reglas predecibles protegen a los ciudadanos mucho mejor que los caprichos de los funcionarios."},{"en":"Admittedly, excessive procedures waste time and stifle initiative; nevertheless, the alternative, arbitrary personal discretion, has historically proven considerably more corrupt and unjust.","native":"Es cierto que los trámites excesivos desperdician tiempo y ahogan la iniciativa; sin embargo, la alternativa, la discreción personal arbitraria, ha demostrado históricamente ser considerablemente más corrupta e injusta."},{"en":"On balance, bureaucracy resembles an immune system: indispensable in moderation, yet capable of attacking the very organism it exists to defend when it grows unchecked.","native":"En definitiva, la burocracia se parece a un sistema inmunitario: indispensable con moderación, pero capaz de atacar al propio organismo que existe para defender cuando crece sin control."}]},"zh":{"word":"官僚体制","question":"官僚体制是必要的恶，还是弊大于利？","examples":[{"en":"While bureaucracy frustrates almost everyone who encounters it, it could be argued that predictable rules protect citizens far better than the whims of officials.","native":"尽管官僚体制让几乎每个接触它的人都感到沮丧，但可以认为，可预测的规则比官员的心血来潮更能保护公民。"},{"en":"Admittedly, excessive procedures waste time and stifle initiative; nevertheless, the alternative, arbitrary personal discretion, has historically proven considerably more corrupt and unjust.","native":"诚然，繁琐的程序浪费时间并扼杀主动性；然而，其替代方案——任意的个人裁量——在历史上被证明要腐败和不公得多。"},{"en":"On balance, bureaucracy resembles an immune system: indispensable in moderation, yet capable of attacking the very organism it exists to defend when it grows unchecked.","native":"总体而言，官僚体制就像免疫系统：适度时不可或缺，但一旦失控增长，就可能攻击它本应保卫的机体本身。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'corruption', 'Why does corruption persist even in wealthy, well-educated societies?', '{"te":{"word":"అవినీతి","question":"ధనవంతులైన, బాగా చదువుకున్న సమాజాల్లోనూ అవినీతి ఎందుకు కొనసాగుతుంది?","examples":[{"en":"While poverty clearly aggravates corruption, it could be argued that affluent societies simply refine it into lobbying, revolving doors, and technically legal favours.","native":"పేదరికం అవినీతిని స్పష్టంగా తీవ్రతరం చేసినప్పటికీ, సంపన్న సమాజాలు దాన్ని లాబ్బింగ్, రివాల్వింగ్ డోర్లు మరియు సాంకేతికంగా చట్టబద్ధమైన ఉపకారాలుగా మెరుగుపరుస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, strong institutions deter the crudest forms of bribery; nevertheless, wherever discretion meets opportunity and weak oversight, temptation reliably reappears.","native":"నిజానికి బలమైన సంస్థలు అత్యంత స్థూలమైన లంచాలను నివారిస్తాయి; అయినప్పటికీ, వివేచన అవకాశంతోనూ బలహీన పర్యవేక్షణతోనూ కలిసిన చోటు ప్రలోభం తప్పక తిరిగి వస్తుంది."},{"en":"On balance, corruption persists less because people are inherently dishonest than because systems quietly reward it, which suggests reform must target incentives rather than morals.","native":"మొత్తానికి, ప్రజలు స్వభావతః అసాధువులు కాబట్టి కాదు, వ్యవస్థలు నిశ్శబ్దంగా అవినీతిని ప్రతిఫలం ఇచ్చేందువల్ల అది కొనసాగుతుంది; సంస్కరణలు నైతికత కంటే ప్రోత్సాహకాలను లక్ష్యంగా చేసుకోవాలని ఇది సూచిస్తుంది."}]},"hi":{"word":"भ्रष्टाचार","question":"धनवान और सुशिक्षित समाजों में भी भ्रष्टाचार क्यों बना रहता है?","examples":[{"en":"While poverty clearly aggravates corruption, it could be argued that affluent societies simply refine it into lobbying, revolving doors, and technically legal favours.","native":"जबकि गरीबी स्पष्ट रूप से भ्रष्टाचार को बढ़ाती है, यह तर्क दिया जा सकता है कि समृद्ध समाज इसे बस लॉबिंग, रिवॉल्विंग दरवाज़ों और तकनीकी रूप से कानूनी एहसानों में परिष्कृत कर देते हैं।"},{"en":"Admittedly, strong institutions deter the crudest forms of bribery; nevertheless, wherever discretion meets opportunity and weak oversight, temptation reliably reappears.","native":"यह स्वीकार करना होगा कि मज़बूत संस्थाएँ रिश्वत के सबसे क्रूर रूपों को रोकती हैं; फिर भी, जहाँ भी विवेक, अवसर और कमज़ोर निगरानी मिलते हैं, प्रलोभन विश्वसनीय रूप से लौट आता है।"},{"en":"On balance, corruption persists less because people are inherently dishonest than because systems quietly reward it, which suggests reform must target incentives rather than morals.","native":"कुल मिलाकर, भ्रष्टाचार इसलिए कम बना रहता है कि लोग स्वभावतः बेईमान हैं, बल्कि इसलिए अधिक कि व्यवस्थाएँ चुपचाप उसे पुरस्कृत करती हैं—इससे पता चलता है कि सुधार को नैतिकता के बजाय प्रोत्साहनों को लक्ष्य करना चाहिए।"}]},"es":{"word":"corrupción","question":"¿Por qué persiste la corrupción incluso en sociedades ricas y bien educadas?","examples":[{"en":"While poverty clearly aggravates corruption, it could be argued that affluent societies simply refine it into lobbying, revolving doors, and technically legal favours.","native":"Aunque la pobreza claramente agrava la corrupción, podría argumentarse que las sociedades afluentes simplemente la refinan en forma de grupos de presión, puertas giratorias y favores técnicamente legales."},{"en":"Admittedly, strong institutions deter the crudest forms of bribery; nevertheless, wherever discretion meets opportunity and weak oversight, temptation reliably reappears.","native":"Es cierto que las instituciones fuertes disuaden las formas más crudas de soborno; sin embargo, dondequiera que la discreción coincide con la oportunidad y una supervisión débil, la tentación reaparece infaliblemente."},{"en":"On balance, corruption persists less because people are inherently dishonest than because systems quietly reward it, which suggests reform must target incentives rather than morals.","native":"En definitiva, la corrupción persiste menos porque la gente sea intrínsecamente deshonesta que porque los sistemas la recompensan silenciosamente, lo que sugiere que la reforma debe apuntar a los incentivos y no a la moral."}]},"zh":{"word":"腐败","question":"为什么腐败即使在富裕、教育良好的社会中也依然存在？","examples":[{"en":"While poverty clearly aggravates corruption, it could be argued that affluent societies simply refine it into lobbying, revolving doors, and technically legal favours.","native":"尽管贫困显然会加剧腐败，但可以认为，富裕社会只是把它提炼成了游说、旋转门和技术上合法的恩惠。"},{"en":"Admittedly, strong institutions deter the crudest forms of bribery; nevertheless, wherever discretion meets opportunity and weak oversight, temptation reliably reappears.","native":"诚然，强大的机构能遏制最粗劣的贿赂形式；然而，凡裁量权遇上机会且监督薄弱之处，诱惑总会可靠地重现。"},{"en":"On balance, corruption persists less because people are inherently dishonest than because systems quietly reward it, which suggests reform must target incentives rather than morals.","native":"总体而言，腐败之所以持续，与其说是因为人们天生不诚实，不如说是因为制度在悄然奖励它——这表明改革必须针对激励机制而非道德说教。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'transparency', 'Should governments and large companies be forced to operate with complete transparency?', '{"te":{"word":"పారదర్శకత","question":"ప్రభుత్వాలు, పెద్ద సంస్థలు పూర్తి పారదర్శకతతో పనిచేయాలని బలవంతం చేయాలా?","examples":[{"en":"While transparency undeniably deters misconduct, it could be argued that total openness would render delicate negotiations and legitimate confidentiality nearly impossible to sustain.","native":"పారదర్శకత తప్పుచర్యలను నిస్సందేహంగా నివారిస్తున్నప్పటికీ, పూర్తి వెల్లడి సున్నితమైన చర్చలనూ, చట్టబద్ధమైన గోప్యతనూ కొనసాగించడం దాదాపు అసాధ్యం చేస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, sunlight remains the best disinfectant; nevertheless, indiscriminate disclosure can endanger sources, security operations, and the privacy of ordinary employees.","native":"నిజానికి సూర్యకాంతి ఉత్తమమైన శుద్ధికారకం; అయినప్పటికీ, వివేచనలేని బహిర్గతం వర్గాలనూ, భద్రతా కార్యకలాపాలనూ, సామాన్య ఉద్యోగుల గోప్యతనూ ప్రమాదంలో పడేయగలదు."},{"en":"On balance, transparency seems most valuable when targeted at decisions and spending rather than every internal conversation, a distinction reformers too often ignore.","native":"మొత్తానికి, ప్రతి అంతర్గత సంభాషణ కంటే నిర్ణయాలు, ఖర్చులపై లక్ష్యంగా పెట్టినప్పుడు పారదర్శకత అత్యంత విలువైనదిగా ఉంటుంది; సంస్కర్తలు తరచుగా పట్టించుకోని తేడా ఇది."}]},"hi":{"word":"पारदर्शिता","question":"क्या सरकारों और बड़ी कंपनियों को पूर्ण पारदर्शिता के साथ काम करने के लिए मजबूर किया जाना चाहिए?","examples":[{"en":"While transparency undeniably deters misconduct, it could be argued that total openness would render delicate negotiations and legitimate confidentiality nearly impossible to sustain.","native":"जबकि पारदर्शिता निस्संदेह कदाचार को रोकती है, यह तर्क दिया जा सकता है कि पूर्ण खुलेपन से नाज़ुक बातचीत और वैध गोपनीयता को बनाए रखना लगभग असंभव हो जाएगा।"},{"en":"Admittedly, sunlight remains the best disinfectant; nevertheless, indiscriminate disclosure can endanger sources, security operations, and the privacy of ordinary employees.","native":"यह स्वीकार करना होगा कि धूप सबसे अच्छा कीटाणुनाशक है; फिर भी, अंधाधुंध खुलासा स्रोतों, सुरक्षा अभियानों और आम कर्मचारियों की निजता को खतरे में डाल सकता है।"},{"en":"On balance, transparency seems most valuable when targeted at decisions and spending rather than every internal conversation, a distinction reformers too often ignore.","native":"कुल मिलाकर, पारदर्शिता तब सबसे मूल्यवान लगती है जब वह हर आंतरिक बातचीत के बजाय निर्णयों और खर्चों पर लक्षित हो—यह अंतर सुधारक अक्सर अनदेखा कर देते हैं।"}]},"es":{"word":"transparencia","question":"¿Debería obligarse a los gobiernos y a las grandes empresas a operar con total transparencia?","examples":[{"en":"While transparency undeniably deters misconduct, it could be argued that total openness would render delicate negotiations and legitimate confidentiality nearly impossible to sustain.","native":"Aunque la transparencia indudablemente disuade la mala conducta, podría argumentarse que la apertura total haría casi imposible sostener negociaciones delicadas y confidencialidad legítima."},{"en":"Admittedly, sunlight remains the best disinfectant; nevertheless, indiscriminate disclosure can endanger sources, security operations, and the privacy of ordinary employees.","native":"Es cierto que la luz del sol sigue siendo el mejor desinfectante; sin embargo, la divulgación indiscriminada puede poner en peligro fuentes, operaciones de seguridad y la privacidad de empleados ordinarios."},{"en":"On balance, transparency seems most valuable when targeted at decisions and spending rather than every internal conversation, a distinction reformers too often ignore.","native":"En definitiva, la transparencia parece más valiosa cuando se dirige a las decisiones y al gasto, y no a cada conversación interna, una distinción que los reformadores ignoran con demasiada frecuencia."}]},"zh":{"word":"透明度","question":"是否应该强制政府和大型企业以完全透明的方式运作？","examples":[{"en":"While transparency undeniably deters misconduct, it could be argued that total openness would render delicate negotiations and legitimate confidentiality nearly impossible to sustain.","native":"尽管透明无疑能遏制不当行为，但可以认为，完全公开将使微妙的谈判和合法的保密几乎无法维持。"},{"en":"Admittedly, sunlight remains the best disinfectant; nevertheless, indiscriminate disclosure can endanger sources, security operations, and the privacy of ordinary employees.","native":"诚然，阳光仍是最好的消毒剂；然而，不加选择的披露可能危及消息来源、安全行动和普通员工的隐私。"},{"en":"On balance, transparency seems most valuable when targeted at decisions and spending rather than every internal conversation, a distinction reformers too often ignore.","native":"总体而言，透明在针对决策和支出时似乎最有价值，而不是针对每一次内部对话——改革者太常忽视这一区别。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'accountability', 'Why are powerful individuals and institutions so rarely held accountable for serious failures?', '{"te":{"word":"జవాబుదారీతనం","question":"తీవ్రమైన వైఫల్యాలకు శక్తివంతమైన వ్యక్తులు, సంస్థలు ఎందుకు చాలా అరుదుగా బాధ్యులు అవుతారు?","examples":[{"en":"While rules technically apply to everyone, it could be argued that wealth and influence purchase a practical immunity that ordinary people can scarcely imagine.","native":"నియమాలు సాంకేతికంగా అందరికీ వర్తించినప్పటికీ, సంపద, ప్రభావం సామాన్యులు ఊహించలేని ఆచరణాత్మక మినహాయింపును కొనుగోలు చేస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, prosecuting leaders carries risks of instability; nevertheless, habitual impunity corrodes public trust far more deeply than any single trial ever could.","native":"నిజానికి నాయకులపై విచారణ అస్థిరత ప్రమాదాలను కలిగి ఉంటుంది; అయినప్పటికీ, అలవాటుపడిన శిక్షారహితత్వం ఏ ఒక్క విచారణ కంటే ప్రజా విశ్వాసాన్ని చాలా లోతుగా తరిగివేస్తుంది."},{"en":"On balance, accountability fails not for lack of laws but because those responsible for enforcing them often belong to the same circles they would need to investigate.","native":"మొత్తానికి, జవాబుదారీతనం చట్టాల లేమివల్ల కాదు, వాటిని అమలు చేయాల్సినవారు తాము విచారించాల్సిన వర్గాలకే చెందినవారు అయ్యేందువల్ల విఫలమవుతుంది."}]},"hi":{"word":"जवाबदेही","question":"गंभीर विफलताओं के लिए शक्तिशाली व्यक्तियों और संस्थाओं से इतनी कम हिसाब क्यों माँगा जाता है?","examples":[{"en":"While rules technically apply to everyone, it could be argued that wealth and influence purchase a practical immunity that ordinary people can scarcely imagine.","native":"जबकि नियम तकनीकी रूप से सभी पर लागू होते हैं, यह तर्क दिया जा सकता है कि धन और प्रभाव एक व्यावहारिक प्रतिरक्षा खरीद लेते हैं जिसकी कल्पना आम लोग मुश्किल से कर सकते हैं।"},{"en":"Admittedly, prosecuting leaders carries risks of instability; nevertheless, habitual impunity corrodes public trust far more deeply than any single trial ever could.","native":"यह स्वीकार करना होगा कि नेताओं पर मुकदमा चलाने में अस्थिरता का जोखिम है; फिर भी, आदतन दंडमुक्ति किसी भी एक मुकदमे की तुलना में जनविश्वास को कहीं अधिक गहराई तक क्षय करती है।"},{"en":"On balance, accountability fails not for lack of laws but because those responsible for enforcing them often belong to the same circles they would need to investigate.","native":"कुल मिलाकर, जवाबदेही कानूनों की कमी से नहीं, बल्कि इसलिए विफल होती है कि उन्हें लागू करने के ज़िम्मेदार लोग अक्सर उन्हीं हलकों से होते हैं जिनकी उन्हें जाँच करनी चाहिए।"}]},"es":{"word":"rendición de cuentas","question":"¿Por qué rara vez se exige cuentas a individuos e instituciones poderosos por fracasos graves?","examples":[{"en":"While rules technically apply to everyone, it could be argued that wealth and influence purchase a practical immunity that ordinary people can scarcely imagine.","native":"Aunque las normas técnicamente se aplican a todos, podría argumentarse que la riqueza y la influencia compran una inmunidad práctica que la gente común apenas puede imaginar."},{"en":"Admittedly, prosecuting leaders carries risks of instability; nevertheless, habitual impunity corrodes public trust far more deeply than any single trial ever could.","native":"Es cierto que procesar a los líderes conlleva riesgos de inestabilidad; sin embargo, la impunidad habitual corroe la confianza pública mucho más profundamente que cualquier juicio aislado."},{"en":"On balance, accountability fails not for lack of laws but because those responsible for enforcing them often belong to the same circles they would need to investigate.","native":"En definitiva, la rendición de cuentas falla no por falta de leyes, sino porque quienes deben hacerlas cumplir a menudo pertenecen a los mismos círculos que tendrían que investigar."}]},"zh":{"word":"问责制","question":"为什么有权势的个人和机构很少为严重的失败被追责？","examples":[{"en":"While rules technically apply to everyone, it could be argued that wealth and influence purchase a practical immunity that ordinary people can scarcely imagine.","native":"尽管规则在技术上适用于所有人，但可以认为，财富和影响力买到的是一种普通人几乎无法想象的实际豁免权。"},{"en":"Admittedly, prosecuting leaders carries risks of instability; nevertheless, habitual impunity corrodes public trust far more deeply than any single trial ever could.","native":"诚然，起诉领导人有引发不稳定的风险；然而，习惯性的有罪不罚对公众信任的侵蚀远比任何一次审判都要深得多。"},{"en":"On balance, accountability fails not for lack of laws but because those responsible for enforcing them often belong to the same circles they would need to investigate.","native":"总体而言，问责制的失败并非因为缺少法律，而是因为负责执法的人往往属于他们本应调查的同一个圈子。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'justice', 'Is justice mainly about punishing wrongdoing, or about repairing the harm that was done?', '{"te":{"word":"న్యాయం","question":"న్యాయం అంటే ప్రధానంగా తప్పు చేసినవారిని శిక్షించడమేనా, లేక జరిగిన హానిని సరిచేయడమేనా?","examples":[{"en":"While punishment satisfies a deep human instinct for proportionality, it could be argued that it rarely restores what victims actually lost or needed.","native":"శిక్ష అనుపాతబద్ధత కోసమైన లోతైన మానవ స్వభావాన్ని తృప్తిపరిచినప్పటికీ, బాధితులు వాస్తవంగా కోల్పోయినదాన్నీ కోరినదాన్నీ అది అరుదుగా పునరుద్ధరిస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, restorative approaches appear soft to those craving retribution; nevertheless, evidence increasingly suggests they reduce reoffending more effectively than imprisonment.","native":"నిజానికి ప్రతీకారం కోరేవారికి పునరుద్ధరణ విధానాలు మృదువుగా అనిపిస్తాయి; అయినప్పటికీ, సాక్ష్యాలు కారాగారం కంటే అవి మళ్లీ నేరాలు చేయడాన్ని ఎక్కువ ప్రభావవంతంగా తగ్గిస్తాయని సూచిస్తున్నాయి."},{"en":"On balance, justice seems most complete when it balances accountability with repair, although societies differ enormously in how much weight each element receives.","native":"మొత్తానికి, న్యాయం జవాబుదారీతనాన్నీ సరిచేయడాన్నీ సమతుల్యం చేసినప్పుడు అత్యంత సంపూర్ణంగా ఉంటుంది, అయితే ప్రతి అంశానికి ఎంత ప్రాధాన్యం ఇస్తారో సమాజాల మధ్య అపారమైన తేడా ఉంటుంది."}]},"hi":{"word":"न्याय","question":"क्या न्याय मुख्य रूप से गलत कार्य की सज़ा देना है, या हुए नुकसान की भरपाई करना?","examples":[{"en":"While punishment satisfies a deep human instinct for proportionality, it could be argued that it rarely restores what victims actually lost or needed.","native":"जबकि दंड आनुपातिकता की गहरी मानवीय प्रवृत्ति को संतुष्ट करता है, यह तर्क दिया जा सकता है कि यह शायद ही कभी वह वापस करता है जो पीड़ितों ने वास्तव में खोया या जिसकी उन्हें ज़रूरत थी।"},{"en":"Admittedly, restorative approaches appear soft to those craving retribution; nevertheless, evidence increasingly suggests they reduce reoffending more effectively than imprisonment.","native":"यह स्वीकार करना होगा कि प्रतिशोध चाहने वालों को पुनर्स्थापनात्मक तरीके नरम लगते हैं; फिर भी, प्रमाण तेज़ी से बताते हैं कि ये कारावास की तुलना में दोबारा अपराध को अधिक प्रभावी ढंग से कम करते हैं।"},{"en":"On balance, justice seems most complete when it balances accountability with repair, although societies differ enormously in how much weight each element receives.","native":"कुल मिलाकर, न्याय तब सबसे पूर्ण लगता है जब वह जवाबदेही और मरम्मत में संतुलन बनाए, यद्यपि हर तत्व को कितना महत्व मिले, इसमें समाजों में असाधारण अंतर है।"}]},"es":{"word":"justicia","question":"¿Consiste la justicia principalmente en castigar el delito, o en reparar el daño causado?","examples":[{"en":"While punishment satisfies a deep human instinct for proportionality, it could be argued that it rarely restores what victims actually lost or needed.","native":"Aunque el castigo satisface un profundo instinto humano de proporcionalidad, podría argumentarse que rara vez restituye lo que las víctimas realmente perdieron o necesitaban."},{"en":"Admittedly, restorative approaches appear soft to those craving retribution; nevertheless, evidence increasingly suggests they reduce reoffending more effectively than imprisonment.","native":"Es cierto que los enfoques restaurativos parecen blandos a quienes ansían retribución; sin embargo, la evidencia sugiere cada vez más que reducen la reincidencia con mayor eficacia que la prisión."},{"en":"On balance, justice seems most complete when it balances accountability with repair, although societies differ enormously in how much weight each element receives.","native":"En definitiva, la justicia parece más completa cuando equilibra la rendición de cuentas con la reparación, aunque las sociedades difieren enormemente en el peso que conceden a cada elemento."}]},"zh":{"word":"正义","question":"正义主要是惩罚不法行为，还是修复所造成的伤害？","examples":[{"en":"While punishment satisfies a deep human instinct for proportionality, it could be argued that it rarely restores what victims actually lost or needed.","native":"尽管惩罚满足了人类对相称性的深层本能，但可以认为，它很少能恢复受害者真正失去或需要的东西。"},{"en":"Admittedly, restorative approaches appear soft to those craving retribution; nevertheless, evidence increasingly suggests they reduce reoffending more effectively than imprisonment.","native":"诚然，在渴望报复的人看来，恢复性司法显得软弱；然而，越来越多的证据表明，它比监禁更能有效减少再犯。"},{"en":"On balance, justice seems most complete when it balances accountability with repair, although societies differ enormously in how much weight each element receives.","native":"总体而言，当正义在问责与修复之间取得平衡时，它似乎最为完整，尽管各社会对每个要素赋予的权重差异巨大。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'equality', 'Should societies aim for equality of opportunity, equality of outcome, or something in between?', '{"te":{"word":"సమానత్వం","question":"సమాజాలు అవకాశ సమానత్వాన్నా, ఫలిత సమానత్వాన్నా, లేక రెండింటి మధ్య ఏదోనైనా లక్ష్యంగా చేసుకోవాలా?","examples":[{"en":"While equality of outcome sounds compassionate, it could be argued that enforcing identical results would require intolerable interference in people''s divergent choices and talents.","native":"ఫలిత సమానత్వం కరుణామయంగా అనిపించినప్పటికీ, ఒకే ఫలితాలను అమలు చేయడానికి ప్రజల వైవిధ్యమైన ఎంపికలు, ప్రతిభల్లో తాళాలేని జోక్యం అవసరమవుతుందని చెప్పవచ్చు."},{"en":"Admittedly, opportunity alone is insufficient when starting points differ grotesquely; nevertheless, most people accept unequal results provided the competition itself seems genuinely fair.","native":"నిజానికి ప్రారంభ స్థానాలు వికారంగా భిన్నమైనప్పుడు అవకాశం మాత్రమే సరిపోదు; అయినప్పటికీ, పోటీ నిజంగా న్యాయంగా అనిపిస్తే చాలామంది అసమాన ఫలితాలను అంగీకరిస్తారు."},{"en":"On balance, a pragmatic middle course seems wisest: guarantee a dignified minimum for everyone, yet allow outcomes to vary with effort, talent, and, inevitably, luck.","native":"మొత్తానికి, ఆచరణాత్మక మధ్యమార్గమే తెలివైనది: అందరికీ గౌరవప్రదమైన కనీసం హామీ ఇస్తూ, కృషి, ప్రతిభ మరియు అనివార్యంగా అదృష్టంతో ఫలితాలు మారనివ్వడం."}]},"hi":{"word":"समानता","question":"क्या समाजों को अवसर की समानता, परिणाम की समानता, या बीच के किसी रास्ते का लक्ष्य रखना चाहिए?","examples":[{"en":"While equality of outcome sounds compassionate, it could be argued that enforcing identical results would require intolerable interference in people''s divergent choices and talents.","native":"जबकि परिणाम की समानता दयालु लगती है, यह तर्क दिया जा सकता है कि समान परिणाम लागू करने के लिए लोगों के अलग-अलग चुनावों और प्रतिभाओं में असहनीय हस्तक्षेप की आवश्यकता होगी।"},{"en":"Admittedly, opportunity alone is insufficient when starting points differ grotesquely; nevertheless, most people accept unequal results provided the competition itself seems genuinely fair.","native":"यह स्वीकार करना होगा कि शुरुआती बिंदु भयंकर रूप से अलग हों तो केवल अवसर पर्याप्त नहीं है; फिर भी, यदि प्रतिस्पर्धा वास्तव में निष्पक्ष लगे तो अधिकांश लोग असमान परिणाम स्वीकार कर लेते हैं।"},{"en":"On balance, a pragmatic middle course seems wisest: guarantee a dignified minimum for everyone, yet allow outcomes to vary with effort, talent, and, inevitably, luck.","native":"कुल मिलाकर, व्यावहारिक मध्यम मार्ग सबसे बुद्धिमान लगता है: सभी के लिए गरिमामय न्यूनतम की गारंटी दें, फिर भी परिणामों को प्रयास, प्रतिभा और अनिवार्य रूप से किस्मत के साथ बदलने दें।"}]},"es":{"word":"igualdad","question":"¿Deberían las sociedades aspirar a la igualdad de oportunidades, a la igualdad de resultados, o a algo intermedio?","examples":[{"en":"While equality of outcome sounds compassionate, it could be argued that enforcing identical results would require intolerable interference in people''s divergent choices and talents.","native":"Aunque la igualdad de resultados suena compasiva, podría argumentarse que imponer resultados idénticos exigiría una interferencia intolerable en las decisiones y talentos divergentes de las personas."},{"en":"Admittedly, opportunity alone is insufficient when starting points differ grotesquely; nevertheless, most people accept unequal results provided the competition itself seems genuinely fair.","native":"Es cierto que la oportunidad por sí sola es insuficiente cuando los puntos de partida difieren grotescamente; sin embargo, la mayoría acepta resultados desiguales siempre que la competencia parezca genuinamente justa."},{"en":"On balance, a pragmatic middle course seems wisest: guarantee a dignified minimum for everyone, yet allow outcomes to vary with effort, talent, and, inevitably, luck.","native":"En definitiva, un término medio pragmático parece lo más sabio: garantizar un mínimo digno para todos, pero permitir que los resultados varíen con el esfuerzo, el talento e, inevitablemente, la suerte."}]},"zh":{"word":"平等","question":"社会应当追求机会平等、结果平等，还是介于两者之间的某种状态？","examples":[{"en":"While equality of outcome sounds compassionate, it could be argued that enforcing identical results would require intolerable interference in people''s divergent choices and talents.","native":"尽管结果平等听起来富有同情心，但可以认为，强制实现相同的结果需要难以忍受地干预人们不同的选择与才能。"},{"en":"Admittedly, opportunity alone is insufficient when starting points differ grotesquely; nevertheless, most people accept unequal results provided the competition itself seems genuinely fair.","native":"诚然，当起点差异悬殊时，仅凭机会并不足够；然而，只要竞争本身看起来真正公平，大多数人能接受不平等的结果。"},{"en":"On balance, a pragmatic middle course seems wisest: guarantee a dignified minimum for everyone, yet allow outcomes to vary with effort, talent, and, inevitably, luck.","native":"总体而言，务实的中间道路似乎最明智：为每个人保障有尊严的最低生活，同时允许结果随努力、才能以及不可避免的运气而变化。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'activism', 'Is street activism still an effective way to achieve political change in the digital age?', '{"te":{"word":"క్రియావాదం","question":"డిజిటల్ యుగంలో రాజకీయ మార్పు సాధించడానికి వీధి ఉద్యమాలు ఇంకా ప్రభావవంతమైన మార్గమేనా?","examples":[{"en":"While online campaigns spread awareness instantly, it could be argued that physical protest still forces governments to reckon with costs that hashtags alone rarely impose.","native":"ఆన్‌లైన్ ప్రచారాలు అవగాహనను తక్షణమే వ్యాప్తి చేసినప్పటికీ, హ్యాష్‌ట్యాగ్‌లు మాత్రమే అరుదుగా విధించే ఖర్చులను భౌతిక నిరసనలు ప్రభుత్వాలకు ఇంకా గుర్తు చేయిస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, activism sometimes alienates the very audiences it needs to persuade; nevertheless, most rights we now take for granted were won through initially unpopular disruption.","native":"నిజానికి క్రియావాదం కొన్నిసార్లు తాను ఒప్పించాల్సిన ప్రేక్షకులనే దూరం చేస్తుంది; అయినప్పటికీ, మనం ఇప్పుడు సాధారణంగా అనుకుంటున్న చాలా హక్కులు ప్రారంభంలో అప్రజాదరణ పొందిన అంతరాయాల ద్వారానే గెలుచుకున్నాయి."},{"en":"On balance, activism works best as one instrument among several, since durable change usually requires negotiation and institutional reform long after the crowds disperse.","native":"మొత్తానికి, క్రియావాదం అనేక సాధనాల్లో ఒకటిగా ఉన్నప్పుడు బాగా పనిచేస్తుంది, ఎందుకంటే గుంపులు వెదజల్లిన తర్వాత చాలా కాలం శాశ్వత మార్పుకు సాధారణంగా చర్చలు, సంస్థాగత సంస్కరణలు అవసరం."}]},"hi":{"word":"सक्रियतावाद","question":"क्या डिजिटल युग में राजनीतिक बदलाव लाने के लिए सड़कों का आंदोलन अब भी प्रभावी तरीका है?","examples":[{"en":"While online campaigns spread awareness instantly, it could be argued that physical protest still forces governments to reckon with costs that hashtags alone rarely impose.","native":"जबकि ऑनलाइन अभियान जागरूकता तुरंत फैलाते हैं, यह तर्क दिया जा सकता है कि भौतिक विरोध अब भी सरकारों को उन कीमतों का एहसास कराता है जो अकेले हैशटैग शायद ही थोपते हैं।"},{"en":"Admittedly, activism sometimes alienates the very audiences it needs to persuade; nevertheless, most rights we now take for granted were won through initially unpopular disruption.","native":"यह स्वीकार करना होगा कि सक्रियतावाद कभी-कभी उन्हीं दर्शकों को अलग कर देता है जिन्हें मनाने की ज़रूरत है; फिर भी, अधिकांश अधिकार जिन्हें हम आज स्वाभाविक मानते हैं, शुरू में अलोकप्रिय व्यवधानों से ही जीते गए थे।"},{"en":"On balance, activism works best as one instrument among several, since durable change usually requires negotiation and institutional reform long after the crowds disperse.","native":"कुल मिलाकर, सक्रियतावाद कई साधनों में से एक के रूप में सबसे अच्छा काम करता है, क्योंकि भीड़ बिखरने के काफी बाद भी टिकाऊ बदलाव के लिए आमतौर पर बातचीत और संस्थागत सुधार ज़रूरी होते हैं।"}]},"es":{"word":"activismo","question":"¿Sigue siendo el activismo callejero una forma eficaz de lograr cambios políticos en la era digital?","examples":[{"en":"While online campaigns spread awareness instantly, it could be argued that physical protest still forces governments to reckon with costs that hashtags alone rarely impose.","native":"Aunque las campañas en línea difunden conciencia al instante, podría argumentarse que la protesta física aún obliga a los gobiernos a asumir costes que los hashtags por sí solos rara vez imponen."},{"en":"Admittedly, activism sometimes alienates the very audiences it needs to persuade; nevertheless, most rights we now take for granted were won through initially unpopular disruption.","native":"Es cierto que el activismo a veces aleja a los públicos que necesita persuadir; sin embargo, la mayoría de los derechos que hoy damos por sentados se conquistaron mediante disrupciones inicialmente impopulares."},{"en":"On balance, activism works best as one instrument among several, since durable change usually requires negotiation and institutional reform long after the crowds disperse.","native":"En definitiva, el activismo funciona mejor como un instrumento entre varios, ya que el cambio duradero suele requerir negociación y reforma institucional mucho después de que las multitudes se dispersen."}]},"zh":{"word":"行动主义","question":"在数字时代，街头行动主义仍然是实现政治变革的有效方式吗？","examples":[{"en":"While online campaigns spread awareness instantly, it could be argued that physical protest still forces governments to reckon with costs that hashtags alone rarely impose.","native":"尽管线上运动能瞬间传播意识，但可以认为，实体抗议仍然迫使政府承担仅靠标签运动很少能施加的代价。"},{"en":"Admittedly, activism sometimes alienates the very audiences it needs to persuade; nevertheless, most rights we now take for granted were won through initially unpopular disruption.","native":"诚然，行动主义有时会疏远它本需说服的受众；然而，我们如今视为理所当然的大多数权利，都是通过起初不受欢迎的抗争行动赢得的。"},{"en":"On balance, activism works best as one instrument among several, since durable change usually requires negotiation and institutional reform long after the crowds disperse.","native":"总体而言，行动主义作为多种工具之一时效果最好，因为人群散去很久之后，持久的变革通常仍需要谈判和制度改革。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'philanthropy', 'Does philanthropy by the wealthy benefit society, or does it give a few individuals too much influence?', '{"te":{"word":"పరోపకారం","question":"ధనికుల పరోపకారం సమాజానికి ప్రయోజనం చేకూరుస్తుందా, లేక కొద్దిమందికి అతిగా ప్రభావం ఇస్తుందా?","examples":[{"en":"While philanthropic donations fund valuable research and relief, it could be argued that they also allow unelected billionaires to set public priorities according to personal preference.","native":"పరోపకార విరాళాలు విలువైన పరిశోధనలకూ, సహాయక చర్యలకూ నిధులు అందించినప్పటికీ, ఎన్నికలేని బిలియనీర్లు వ్యక్తిగత అభిరుచుల ప్రకారం ప్రజా ప్రాధాన్యతలను నిర్ణయించడానికి కూడా అవి అనుమతిస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, private generosity moves faster than government bureaucracy; nevertheless, gratitude is a poor substitute for accountability when essential services depend on one donor''s whim.","native":"నిజానికి ప్రైవేటు ఉదారత ప్రభుత్వ అధికారతంత్రం కంటే వేగంగా కదులుతుంది; అయినప్పటికీ, అత్యవసర సేవలు ఒక దాత ఉత్పాటంపై ఆధారపడినప్పుడు కృతజ్ఞత జవాబుదారీతనానికి పేద ప్రత్యామ్నాయం."},{"en":"On balance, philanthropy seems most defensible when it complements rather than replaces taxation, since a civilised society should not depend upon the moods of the fortunate.","native":"మొత్తానికి, పరోపకారం పన్నులకు ప్రత్యామ్నాయం కాకుండా పూరకంగా ఉన్నప్పుడు అత్యంత సమర్థనీయం, ఎందుకంటే నాగరిక సమాజం అదృష్టవంతుల మూడ్‌లపై ఆధారపడకూడదు."}]},"hi":{"word":"परोपकार","question":"क्या धनी लोगों का परोपकार समाज को लाभ पहुँचाता है, या यह कुछ ही व्यक्तियों को अत्यधिक प्रभाव दे देता है?","examples":[{"en":"While philanthropic donations fund valuable research and relief, it could be argued that they also allow unelected billionaires to set public priorities according to personal preference.","native":"जबकि परोपकारी दान मूल्यवान अनुसंधान और राहत को धन देते हैं, यह तर्क दिया जा सकता है कि वे अनिर्वाचित अरबपतियों को भी निजी पसंद के अनुसार सार्वजनिक प्राथमिकताएँ तय करने देते हैं।"},{"en":"Admittedly, private generosity moves faster than government bureaucracy; nevertheless, gratitude is a poor substitute for accountability when essential services depend on one donor''s whim.","native":"यह स्वीकार करना होगा कि निजी उदारता सरकारी नौकरशाही से तेज़ चलती है; फिर भी, जब आवश्यक सेवाएँ एक दाता के मिज़ाज पर निर्भर हों तो कृतज्ञता जवाबदेही का घटिया विकल्प है।"},{"en":"On balance, philanthropy seems most defensible when it complements rather than replaces taxation, since a civilised society should not depend upon the moods of the fortunate.","native":"कुल मिलाकर, परोपकार तब सबसे अधिक बचावयोग्य लगता है जब वह कराधान का प्रतिस्थापन नहीं बल्कि पूरक हो, क्योंकि एक सभ्य समाज को भाग्यवानों के मनोभाव पर निर्भर नहीं होना चाहिए।"}]},"es":{"word":"filantropía","question":"¿Beneficia la filantropía de los ricos a la sociedad, o concede a unos pocos individuos demasiada influencia?","examples":[{"en":"While philanthropic donations fund valuable research and relief, it could be argued that they also allow unelected billionaires to set public priorities according to personal preference.","native":"Aunque las donaciones filantrópicas financian investigación y ayuda valiosas, podría argumentarse que también permiten a multimillonarios no elegidos fijar prioridades públicas según sus preferencias personales."},{"en":"Admittedly, private generosity moves faster than government bureaucracy; nevertheless, gratitude is a poor substitute for accountability when essential services depend on one donor''s whim.","native":"Es cierto que la generosidad privada se mueve más rápido que la burocracia gubernamental; sin embargo, la gratitud es un mal sustituto de la rendición de cuentas cuando los servicios esenciales dependen del capricho de un donante."},{"en":"On balance, philanthropy seems most defensible when it complements rather than replaces taxation, since a civilised society should not depend upon the moods of the fortunate.","native":"En definitiva, la filantropía parece más defendible cuando complementa los impuestos en lugar de sustituirlos, ya que una sociedad civilizada no debería depender de los humores de los afortunados."}]},"zh":{"word":"慈善","question":"富人的慈善行为造福了社会，还是让少数个人拥有了过大的影响力？","examples":[{"en":"While philanthropic donations fund valuable research and relief, it could be argued that they also allow unelected billionaires to set public priorities according to personal preference.","native":"尽管慈善捐款资助了有价值的研究和救援，但可以认为，它们也让未经选举的亿万富翁得以按个人偏好设定公共优先事项。"},{"en":"Admittedly, private generosity moves faster than government bureaucracy; nevertheless, gratitude is a poor substitute for accountability when essential services depend on one donor''s whim.","native":"诚然，私人慷慨比政府官僚机构行动更快；然而，当基本服务取决于一位捐赠者的心血来潮时，感恩并不能替代问责。"},{"en":"On balance, philanthropy seems most defensible when it complements rather than replaces taxation, since a civilised society should not depend upon the moods of the fortunate.","native":"总体而言，当慈善补充而非取代税收时，它似乎最站得住脚，因为一个文明社会不应依赖于幸运者的心情。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'wealth', 'Does great personal wealth bring genuine happiness, or does it create its own problems?', '{"te":{"word":"సంపద","question":"గొప్ప వ్యక్తిగత సంపద నిజమైన ఆనందాన్ని ఇస్తుందా, లేక దాని స్వంత సమస్యలను సృష్టిస్తుందా?","examples":[{"en":"While wealth undeniably removes the anxieties of poverty, it could be argued that beyond a comfortable threshold, additional money purchases remarkably little extra contentment.","native":"సంపద పేదరికపు ఆందోళనలను నిస్సందేహంగా తొలగించినప్పటికీ, సౌకర్యవంతమైన స్థాయి దాటిన తర్వాత అదనపు డబ్బు ఆశ్చర్యకరంగా తక్కువ అదనపు తృప్తిని కొనుగోలు చేస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, the rich enjoy freedom and security most people lack; nevertheless, extreme affluence frequently breeds isolation, suspicion, and a peculiar fear of losing everything.","native":"నిజానికి ధనికులు చాలామందికి లేని స్వేచ్ఛనూ భద్రతనూ అనుభవిస్తారు; అయినప్పటికీ, అత్యంత ఐశ్వర్యం తరచుగా ఒంటరితనాన్నీ, అనుమానాన్నీ, అంతా కోల్పోతామనే విచిత్ర భయాన్నీ పెంచుతుంది."},{"en":"On balance, wealth seems to amplify rather than transform character, which perhaps explains why some rich people are serene while others remain perpetually dissatisfied.","native":"మొత్తానికి, సంపద స్వభావాన్ని మార్చడం కంటే పెంచడం చేస్తుందని అనిపిస్తుంది; కొందరు ధనికులు ప్రశాంతంగా ఉండగా మరికొందరు శాశ్వత అసంతృప్తులుగా ఉండటానికి బహుశా ఇది కారణం."}]},"hi":{"word":"धन","question":"क्या बहुत अधिक व्यक्तिगत धन वास्तविक खुशी लाता है, या यह अपनी अलग समस्याएँ पैदा करता है?","examples":[{"en":"While wealth undeniably removes the anxieties of poverty, it could be argued that beyond a comfortable threshold, additional money purchases remarkably little extra contentment.","native":"जबकि धन निस्संदेह गरीबी की चिंताएँ दूर करता है, यह तर्क दिया जा सकता है कि आरामदायक सीमा के आगे, अतिरिक्त पैसा आश्चर्यजनक रूप से कम अतिरिक्त संतोष खरीदता है।"},{"en":"Admittedly, the rich enjoy freedom and security most people lack; nevertheless, extreme affluence frequently breeds isolation, suspicion, and a peculiar fear of losing everything.","native":"यह स्वीकार करना होगा कि अमीर वह स्वतंत्रता और सुरक्षा भोगते हैं जो अधिकांश लोगों के पास नहीं है; फिर भी, अत्यंत समृद्धि अक्सर अकेलापन, संदेह और सब कुछ खोने का एक विचित्र डर पैदा करती है।"},{"en":"On balance, wealth seems to amplify rather than transform character, which perhaps explains why some rich people are serene while others remain perpetually dissatisfied.","native":"कुल मिलाकर, धन चरित्र को बदलने के बजाय उसे बढ़ाता प्रतीत होता है—शायद इसीलिए कुछ अमीर शांत रहते हैं जबकि अन्य सदा असंतुष्ट बने रहते हैं।"}]},"es":{"word":"riqueza","question":"¿Trae la gran riqueza personal una felicidad genuina, o crea sus propios problemas?","examples":[{"en":"While wealth undeniably removes the anxieties of poverty, it could be argued that beyond a comfortable threshold, additional money purchases remarkably little extra contentment.","native":"Aunque la riqueza indudablemente elimina las ansiedades de la pobreza, podría argumentarse que, más allá de un umbral cómodo, el dinero adicional compra sorprendentemente poca satisfacción extra."},{"en":"Admittedly, the rich enjoy freedom and security most people lack; nevertheless, extreme affluence frequently breeds isolation, suspicion, and a peculiar fear of losing everything.","native":"Es cierto que los ricos disfrutan de una libertad y seguridad que la mayoría carece; sin embargo, la afluencia extrema frecuentemente engendra aislamiento, sospecha y un miedo peculiar a perderlo todo."},{"en":"On balance, wealth seems to amplify rather than transform character, which perhaps explains why some rich people are serene while others remain perpetually dissatisfied.","native":"En definitiva, la riqueza parece amplificar el carácter más que transformarlo, lo que quizá explique por qué algunos ricos son serenos mientras otros permanecen perpetuamente insatisfechos."}]},"zh":{"word":"财富","question":"巨额的个人财富能带来真正的幸福，还是会制造它自己的问题？","examples":[{"en":"While wealth undeniably removes the anxieties of poverty, it could be argued that beyond a comfortable threshold, additional money purchases remarkably little extra contentment.","native":"尽管财富无疑消除了贫困带来的焦虑，但可以认为，超过舒适门槛之后，额外的金钱买到的额外满足感少得惊人。"},{"en":"Admittedly, the rich enjoy freedom and security most people lack; nevertheless, extreme affluence frequently breeds isolation, suspicion, and a peculiar fear of losing everything.","native":"诚然，富人享受着大多数人缺乏的自由与安全；然而，极端的富裕往往滋生孤立、猜疑，以及一种害怕失去一切的奇特恐惧。"},{"en":"On balance, wealth seems to amplify rather than transform character, which perhaps explains why some rich people are serene while others remain perpetually dissatisfied.","native":"总体而言，财富似乎放大而非改变人的性格——这或许解释了为什么有些富人从容安详，而另一些却永远不满足。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'poverty', 'Is poverty mainly the result of personal failure, or of the way society is organised?', '{"te":{"word":"పేదరికం","question":"పేదరికం ప్రధానంగా వ్యక్తిగత వైఫల్యం ఫలితమా, లేక సమాజ నిర్మాణం ఫలితమా?","examples":[{"en":"While individual choices plainly matter, it could be argued that attributing poverty chiefly to laziness ignores overwhelming evidence about inherited disadvantage and plain bad luck.","native":"వ్యక్తిగత ఎంపికలు స్పష్టంగా ముఖ్యమయినప్పటికీ, పేదరికాన్ని ప్రధానంగా సోమరితనానికి ఆపాదించడం వంశపారంపర్య అసౌకర్యాలు, సాదా దురదృష్టం గురించిన అధిక సాక్ష్యాలను పట్టించుకోవదని చెప్పవచ్చు."},{"en":"Admittedly, some escape destitution through extraordinary effort; nevertheless, celebrating rare exceptions distracts from the structural barriers that defeat millions of equally determined people.","native":"నిజానికి కొందరు అసాధారణ కృషితో దారిద్ర్యం నుండి బయటపడతారు; అయినప్పటికీ, అరుదైన మినహాయింపులను కీర్తించడం అంతే దృఢసంకల్పం గల కోట్లాదిమందిని ఓడించే నిర్మాణాత్మక అడ్డంకుల నుండి దృష్టి మళ్లిస్తుంది."},{"en":"On balance, poverty appears less a verdict on character than a reflection of circumstances, although acknowledging this demands an uncomfortable humility from the successful.","native":"మొత్తానికి, పేదరికం స్వభావంపై తీర్పు కంటే పరిస్థితుల ప్రతిబింబంగా కనిపిస్తుంది, అయితే దీన్ని అంగీకరించడానికి విజేతల నుండి అసౌకర్యకరమైన వినయం అవసరం."}]},"hi":{"word":"गरीबी","question":"क्या गरीबी मुख्य रूप से व्यक्तिगत असफलता का परिणाम है, या समाज के संगठन का?","examples":[{"en":"While individual choices plainly matter, it could be argued that attributing poverty chiefly to laziness ignores overwhelming evidence about inherited disadvantage and plain bad luck.","native":"जबकि व्यक्तिगत चुनाव स्पष्ट रूप से मायने रखते हैं, यह तर्क दिया जा सकता है कि गरीबी को मुख्यतः आलस्य से जोड़ना विरासत में मिली कमियों और महज़ दुर्भाग्य के भारी प्रमाण को अनदेखा करता है।"},{"en":"Admittedly, some escape destitution through extraordinary effort; nevertheless, celebrating rare exceptions distracts from the structural barriers that defeat millions of equally determined people.","native":"यह स्वीकार करना होगा कि कुछ लोग असाधारण प्रयास से दरिद्रता से बाहर निकलते हैं; फिर भी, दुर्लभ अपवादों का जश्न मनाना उन संरचनात्मक बाधाओं से ध्यान हटाता है जो लाखों समान रूप से दृढ़ लोगों को पराजित करती हैं।"},{"en":"On balance, poverty appears less a verdict on character than a reflection of circumstances, although acknowledging this demands an uncomfortable humility from the successful.","native":"कुल मिलाकर, गरीबी चरित्र पर फैसले से कम और परिस्थितियों के प्रतिबिंब जैसी अधिक लगती है, यद्यपि इसे स्वीकार करने के लिए सफल लोगों से एक असहज विनम्रता माँगती है।"}]},"es":{"word":"pobreza","question":"¿Es la pobreza principalmente resultado del fracaso personal, o de la forma en que se organiza la sociedad?","examples":[{"en":"While individual choices plainly matter, it could be argued that attributing poverty chiefly to laziness ignores overwhelming evidence about inherited disadvantage and plain bad luck.","native":"Aunque las decisiones individuales claramente importan, podría argumentarse que atribuir la pobreza principalmente a la pereza ignora pruebas abrumadoras sobre la desventaja heredada y la simple mala suerte."},{"en":"Admittedly, some escape destitution through extraordinary effort; nevertheless, celebrating rare exceptions distracts from the structural barriers that defeat millions of equally determined people.","native":"Es cierto que algunos escapan de la miseria mediante un esfuerzo extraordinario; sin embargo, celebrar raras excepciones distrae de las barreras estructurales que derrotan a millones de personas igualmente decididas."},{"en":"On balance, poverty appears less a verdict on character than a reflection of circumstances, although acknowledging this demands an uncomfortable humility from the successful.","native":"En definitiva, la pobreza parece menos un veredicto sobre el carácter que un reflejo de las circunstancias, aunque reconocerlo exige una humildad incómoda por parte de los exitosos."}]},"zh":{"word":"贫困","question":"贫困主要是个人失败的结果，还是社会组织方式的结果？","examples":[{"en":"While individual choices plainly matter, it could be argued that attributing poverty chiefly to laziness ignores overwhelming evidence about inherited disadvantage and plain bad luck.","native":"尽管个人选择显然很重要，但可以认为，把贫困主要归因于懒惰，忽视了关于遗传性劣势和纯粹厄运的大量证据。"},{"en":"Admittedly, some escape destitution through extraordinary effort; nevertheless, celebrating rare exceptions distracts from the structural barriers that defeat millions of equally determined people.","native":"诚然，有些人通过非凡的努力摆脱了赤贫；然而，赞美罕见的例外会让人忽视那些击败了数百万同样坚定之人的结构性障碍。"},{"en":"On balance, poverty appears less a verdict on character than a reflection of circumstances, although acknowledging this demands an uncomfortable humility from the successful.","native":"总体而言，贫困似乎与其说是对品格的判决，不如说是环境的反映，尽管承认这一点需要成功者拿出令人不安的谦逊。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'social mobility', 'Has social mobility become harder in recent decades, and what could restore it?', '{"te":{"word":"సామాజిక గతిశీలత","question":"ఇటీవలి దశాబ్దాల్లో సామాజిక గతిశీలత కష్టతరమైందా, దాన్ని తిరిగి పుంజుకోవడానికి ఏమి చేయవచ్చు?","examples":[{"en":"While politicians celebrate opportunity for all, it could be argued that rising housing costs and educational stratification have quietly frozen mobility across much of the developed world.","native":"రాజకీయ నాయకులు అందరికీ అవకాశం అని కొనియాడినప్పటికీ, పెరుగుతున్న గృహ వ్యయాలు, విద్యా స్థరీకరణ అభివృద్ధి చెందిన ప్రపంచంలో ఎక్కువ భాగం గతిశీలతను నిశ్శబ్దంగా స్తంభింపజేశాయని చెప్పవచ్చు."},{"en":"Admittedly, exceptional individuals still climb dramatically; nevertheless, the statistics suggest that birthplace and parental income predict adult outcomes with depressing accuracy.","native":"నిజానికి అసాధారణ వ్యక్తులు ఇంకా నాటకీయంగా ఎదుగుతారు; అయినప్పటికీ, గణాంకాలు జన్మస్థలం, తల్లిదండ్రుల ఆదాయం వయోజన ఫలితాలను నిరాశపరిచే ఖచ్చితత్వంతో అంచనా వేస్తాయని సూచిస్తున్నాయి."},{"en":"On balance, restoring mobility would demand sustained investment in early childhood and affordable housing, remedies far less glamorous than the rhetoric they would replace.","native":"మొత్తానికి, గతిశీలతను పునరుద్ధరించడానికి ప్రారంభ బాల్యం, సరసమైన గృహాలపై నిరంతర పెట్టుబడులు అవసరం; అవి భర్తీ చేసే ఉపన్యాసాల కంటే చాలా తక్కువ ఆకర్షణీయమైన పరిష్కారాలు."}]},"hi":{"word":"सामाजिक गतिशीलता","question":"क्या हाल के दशकों में सामाजिक गतिशीलता कठिन हो गई है, और इसे बहाल करने के लिए क्या किया जा सकता है?","examples":[{"en":"While politicians celebrate opportunity for all, it could be argued that rising housing costs and educational stratification have quietly frozen mobility across much of the developed world.","native":"जबकि राजनेता सभी के लिए अवसर का गुणगान करते हैं, यह तर्क दिया जा सकता है कि बढ़ती आवास लागत और शैक्षिक स्तरीकरण ने विकसित दुनिया के अधिकांश हिस्से में गतिशीलता को चुपचाप जमा दिया है।"},{"en":"Admittedly, exceptional individuals still climb dramatically; nevertheless, the statistics suggest that birthplace and parental income predict adult outcomes with depressing accuracy.","native":"यह स्वीकार करना होगा कि असाधारण व्यक्ति अब भी नाटकीय रूप से ऊपर चढ़ते हैं; फिर भी, आँकड़े बताते हैं कि जन्मस्थान और माता-पिता की आय वयस्क परिणामों की भविष्यवाणी निराशाजनक सटीकता से करते हैं।"},{"en":"On balance, restoring mobility would demand sustained investment in early childhood and affordable housing, remedies far less glamorous than the rhetoric they would replace.","native":"कुल मिलाकर, गतिशीलता बहाल करने के लिए प्रारंभिक बचपन और किफ़ायती आवास में निरंतर निवेश चाहिए—ये उपाय उस शानदार बातचीत की तुलना में कहीं कम आकर्षक हैं जिसकी वे जगह लेंगे।"}]},"es":{"word":"movilidad social","question":"¿Se ha vuelto más difícil la movilidad social en las últimas décadas, y qué podría restaurarla?","examples":[{"en":"While politicians celebrate opportunity for all, it could be argued that rising housing costs and educational stratification have quietly frozen mobility across much of the developed world.","native":"Aunque los políticos celebran la oportunidad para todos, podría argumentarse que el aumento del coste de la vivienda y la estratificación educativa han congelado silenciosamente la movilidad en gran parte del mundo desarrollado."},{"en":"Admittedly, exceptional individuals still climb dramatically; nevertheless, the statistics suggest that birthplace and parental income predict adult outcomes with depressing accuracy.","native":"Es cierto que algunos individuos excepcionales aún ascienden espectacularmente; sin embargo, las estadísticas sugieren que el lugar de nacimiento y los ingresos de los padres predicen los resultados adultos con una precisión deprimente."},{"en":"On balance, restoring mobility would demand sustained investment in early childhood and affordable housing, remedies far less glamorous than the rhetoric they would replace.","native":"En definitiva, restaurar la movilidad exigiría una inversión sostenida en la primera infancia y en vivienda asequible, remedios mucho menos glamurosos que la retórica que reemplazarían."}]},"zh":{"word":"社会流动性","question":"近几十年来，社会流动性是否变得更难了，怎样才能恢复它？","examples":[{"en":"While politicians celebrate opportunity for all, it could be argued that rising housing costs and educational stratification have quietly frozen mobility across much of the developed world.","native":"尽管政客们赞美人人有机会，但可以认为，不断上涨的住房成本和教育分层已悄然冻结了发达世界大部分地区的流动性。"},{"en":"Admittedly, exceptional individuals still climb dramatically; nevertheless, the statistics suggest that birthplace and parental income predict adult outcomes with depressing accuracy.","native":"诚然，杰出的个人仍然能够戏剧性地上升；然而，统计数据表明，出生地和父母收入以令人沮丧的准确性预测着成年后的结局。"},{"en":"On balance, restoring mobility would demand sustained investment in early childhood and affordable housing, remedies far less glamorous than the rhetoric they would replace.","native":"总体而言，恢复流动性需要在幼儿早期和可负担住房上持续投入——这些补救措施远不如它们所取代的豪言壮语那样光鲜。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'privilege', 'Why do people find it so difficult to recognise their own privileges?', '{"te":{"word":"ప్రత్యేక హక్కు","question":"ప్రజలు తమ స్వంత ప్రత్యేక హక్కులను గుర్తించడం ఎందుకు అంత కష్టంగా భావిస్తారు?","examples":[{"en":"While privilege feels invisible to those who possess it, it could be argued that advantages absorbed from birth masquerade convincingly as personal merit and deserved reward.","native":"ప్రత్యేక హక్కు దాన్ని కలవారికి అదృశ్యంగా అనిపించినప్పటికీ, పుట్టుక నుండి ఇమిడిపోయిన అనుకూలతలు వ్యక్తిగత ప్రతిభగా, అర్హమైన బహుమతిగా నమ్మదగినంతగా ముసుగువేసుకుంటాయని చెప్పవచ్చు."},{"en":"Admittedly, acknowledging advantage threatens the flattering stories we tell ourselves; nevertheless, denying it simply shifts the burden of explanation onto those who never had it.","native":"నిజానికి అనుకూలతను అంగీకరించడం మనం మనకు చెప్పుకునే మెచ్చుకోలు కథలను బెదిరిస్తుంది; అయినప్పటికీ, దాన్ని తిరస్కరించడం వివరణ భారాన్ని అది ఎప్పుడూ లేనివారిపైకి జరుపుతుంది."},{"en":"On balance, recognising privilege need not induce guilt; rather, it offers a clearer map of the terrain, which is arguably the beginning of any honest conversation about fairness.","native":"మొత్తానికి, ప్రత్యేక హక్కును గుర్తించడం అపరాధభావాన్ని కలిపించనవసరం లేదు; బదులుగా, అది భూభాగం యొక్క స్పష్టమైన పటాన్ని ఇస్తుంది—న్యాయం గురించిన ఏ నిజాయితీ సంభాషణకైనా ఇది ప్రారంభమని చెప్పవచ్చు."}]},"hi":{"word":"विशेषाधिकार","question":"लोग अपने विशेषाधिकारों को पहचानना इतना कठिन क्यों पाते हैं?","examples":[{"en":"While privilege feels invisible to those who possess it, it could be argued that advantages absorbed from birth masquerade convincingly as personal merit and deserved reward.","native":"जबकि विशेषाधिकार उसे रखने वालों को अदृश्य लगता है, यह तर्क दिया जा सकता है कि जन्म से मिले लाभ विश्वसनीय रूप से व्यक्तिगत योग्यता और अर्जित पुरस्कार का भेस धारण कर लेते हैं।"},{"en":"Admittedly, acknowledging advantage threatens the flattering stories we tell ourselves; nevertheless, denying it simply shifts the burden of explanation onto those who never had it.","native":"यह स्वीकार करना होगा कि सुविधा स्वीकार करना उन चापलूस कहानियों को धमकाता है जो हम खुद को सुनाते हैं; फिर भी, इससे इनकार करना व्याख्या का बोझ उन लोगों पर डाल देता है जिन्हें यह कभी मिला ही नहीं।"},{"en":"On balance, recognising privilege need not induce guilt; rather, it offers a clearer map of the terrain, which is arguably the beginning of any honest conversation about fairness.","native":"कुल मिलाकर, विशेषाधिकार पहचानने से अपराधबोध पैदा करने की ज़रूरत नहीं; बल्कि, यह भू-भाग का एक स्पष्ट नक्शा देता है—जो तर्कतः निष्पक्षता पर किसी भी ईमानदार बातचीत की शुरुआत है।"}]},"es":{"word":"privilegio","question":"¿Por qué a la gente le resulta tan difícil reconocer sus propios privilegios?","examples":[{"en":"While privilege feels invisible to those who possess it, it could be argued that advantages absorbed from birth masquerade convincingly as personal merit and deserved reward.","native":"Aunque el privilegio resulta invisible para quien lo posee, podría argumentarse que las ventajas absorbidas desde el nacimiento se disfrazan convincentemente de mérito personal y recompensa merecida."},{"en":"Admittedly, acknowledging advantage threatens the flattering stories we tell ourselves; nevertheless, denying it simply shifts the burden of explanation onto those who never had it.","native":"Es cierto que reconocer la ventaja amenaza las historias halagadoras que nos contamos; sin embargo, negarla simplemente traslada la carga de la explicación a quienes nunca la tuvieron."},{"en":"On balance, recognising privilege need not induce guilt; rather, it offers a clearer map of the terrain, which is arguably the beginning of any honest conversation about fairness.","native":"En definitiva, reconocer el privilegio no tiene por qué inducir culpa; más bien ofrece un mapa más claro del terreno, que es posiblemente el comienzo de cualquier conversación honesta sobre la equidad."}]},"zh":{"word":"特权","question":"为什么人们很难认识到自己所享有的特权？","examples":[{"en":"While privilege feels invisible to those who possess it, it could be argued that advantages absorbed from birth masquerade convincingly as personal merit and deserved reward.","native":"尽管特权对拥有它的人来说是无形的，但可以认为，从出生起就吸收的优势会令人信服地伪装成个人功绩和应得的回报。"},{"en":"Admittedly, acknowledging advantage threatens the flattering stories we tell ourselves; nevertheless, denying it simply shifts the burden of explanation onto those who never had it.","native":"诚然，承认优势会威胁到我们讲给自己听的那些自我美化的故事；然而，否认它只是把解释的负担转嫁给了那些从未拥有过它的人。"},{"en":"On balance, recognising privilege need not induce guilt; rather, it offers a clearer map of the terrain, which is arguably the beginning of any honest conversation about fairness.","native":"总体而言，认识特权不必引发内疚；相反，它提供了一幅更清晰的地形图——可以说，这是任何关于公平的诚实对话的起点。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'discrimination', 'Why does discrimination persist even where laws clearly prohibit it?', '{"te":{"word":"వివక్ష","question":"చట్టాలు స్పష్టంగా నిషేధించిన చోటున్నా వివక్ష ఎందుకు కొనసాగుతుంది?","examples":[{"en":"While legislation has outlawed overt discrimination, it could be argued that prejudice has simply retreated into subtler forms that laws struggle to reach.","native":"చట్టబద్ధత బహిరంగ వివక్షను నిషేధించినప్పటికీ, పక్షపాతం చట్టాలు చేరుకోవడానికి ఇబ్బందిపడే సూక్ష్మమైన రూపాల్లోకి వెనక్కి వెళ్లిపోయిందని చెప్పవచ్చు."},{"en":"Admittedly, attitudes have improved dramatically within living memory; nevertheless, unconscious bias demonstrably influences hiring, lending, and policing decisions despite sincere egalitarian intentions.","native":"నిజానికి జీవిత జ్ఞాపకాల్లో వైఖరులు నాటకీయంగా మెరుగయ్యాయి; అయినప్పటికీ, నిజాయితీగల సమానత్వ ఉద్దేశాలున్నా, అపరిచిత పక్షపాతం నియామకాలు, రుణాలు మరియు పోలీసు నిర్ణయాలను స్పష్టంగా ప్రభావితం చేస్తుంది."},{"en":"On balance, ending discrimination appears to require changing institutions rather than merely hearts, since goodwill alone has never dismantled a single entrenched hierarchy.","native":"మొత్తానికి, వివక్షను అంతం చేయడానికి హృదయాలు కాకుండా సంస్థలను మార్చడం అవసరమని అనిపిస్తుంది, ఎందుకంటే సద్భావం మాత్రమే ఏ ఒక్క పాతుకుపోయిన సోపానక్రమాన్ని కూల్చలేదు."}]},"hi":{"word":"भेदभाव","question":"जहाँ कानून स्पष्ट रूप से इसे रोकते हैं, वहाँ भी भेदभाव क्यों बना रहता है?","examples":[{"en":"While legislation has outlawed overt discrimination, it could be argued that prejudice has simply retreated into subtler forms that laws struggle to reach.","native":"जबकि कानून ने खुले भेदभाव को अवैध कर दिया है, यह तर्क दिया जा सकता है कि पूर्वाग्रह बस उन सूक्ष्म रूपों में पीछे हट गया है जिन तक कानून पहुँचने में संघर्ष करते हैं।"},{"en":"Admittedly, attitudes have improved dramatically within living memory; nevertheless, unconscious bias demonstrably influences hiring, lending, and policing decisions despite sincere egalitarian intentions.","native":"यह स्वीकार करना होगा कि जीवित स्मृति में दृष्टिकोण नाटकीय रूप से सुधरे हैं; फिर भी, अचेतन पूर्वाग्रह ईमानदार समतावादी इरादों के बावजूद भर्ती, ऋण और पुलिसिंग निर्णयों को प्रदर्शनात्मक रूप से प्रभावित करता है।"},{"en":"On balance, ending discrimination appears to require changing institutions rather than merely hearts, since goodwill alone has never dismantled a single entrenched hierarchy.","native":"कुल मिलाकर, भेदभाव समाप्त करने के लिए केवल दिलों के बजाय संस्थाओं को बदलना आवश्यक लगता है, क्योंकि अकेली सद्भावना ने आज तक कोई एक भी गढ़ा हुआ पदानुक्रम नहीं गिराया।"}]},"es":{"word":"discriminación","question":"¿Por qué persiste la discriminación incluso donde las leyes la prohíben claramente?","examples":[{"en":"While legislation has outlawed overt discrimination, it could be argued that prejudice has simply retreated into subtler forms that laws struggle to reach.","native":"Aunque la legislación ha prohibido la discriminación abierta, podría argumentarse que el prejuicio simplemente se ha replegado hacia formas más sutiles a las que las leyes apenas llegan."},{"en":"Admittedly, attitudes have improved dramatically within living memory; nevertheless, unconscious bias demonstrably influences hiring, lending, and policing decisions despite sincere egalitarian intentions.","native":"Es cierto que las actitudes han mejorado drásticamente en una generación; sin embargo, el sesgo inconsciente influye demostrablemente en decisiones de contratación, crédito y policía pese a intenciones igualitarias sinceras."},{"en":"On balance, ending discrimination appears to require changing institutions rather than merely hearts, since goodwill alone has never dismantled a single entrenched hierarchy.","native":"En definitiva, acabar con la discriminación parece requerir cambiar instituciones más que corazones, ya que la buena voluntad por sí sola jamás ha desmantelado una sola jerarquía arraigada."}]},"zh":{"word":"歧视","question":"为什么即使在法律明确禁止的地方，歧视依然存在？","examples":[{"en":"While legislation has outlawed overt discrimination, it could be argued that prejudice has simply retreated into subtler forms that laws struggle to reach.","native":"尽管立法已禁止公开的歧视，但可以认为，偏见只是退入了法律难以触及的更隐蔽形式。"},{"en":"Admittedly, attitudes have improved dramatically within living memory; nevertheless, unconscious bias demonstrably influences hiring, lending, and policing decisions despite sincere egalitarian intentions.","native":"诚然，在世人们的记忆里，社会态度已有巨大改善；然而，无意识偏见显然影响着招聘、信贷和执法决策，尽管人们怀有真诚的平等主义意愿。"},{"en":"On balance, ending discrimination appears to require changing institutions rather than merely hearts, since goodwill alone has never dismantled a single entrenched hierarchy.","native":"总体而言，消除歧视似乎需要改变制度而不仅仅是人心，因为单靠善意从未拆除过任何一个根深蒂固的等级体系。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'tolerance', 'Are there limits to what a tolerant society should tolerate?', '{"te":{"word":"సహనం","question":"సహించే సమాజం సహించాల్సిన దానికి పరిమితులు ఉన్నాయా?","examples":[{"en":"While tolerance rightly ranks among the cardinal democratic virtues, it could be argued that tolerating intolerance itself gradually destroys the conditions that make tolerance possible.","native":"సహనం ప్రధాన ప్రజాస్వామిక సద్గుణాల్లో ఒకటిగా సరిగ్గానే నిలుస్తున్నప్పటికీ, అసహనాన్ని సహించడం సహనాన్ని సాధ్యం చేసే పరిస్థితులనే క్రమంగా నాశనం చేస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, drawing boundaries risks hypocrisy and abuse; nevertheless, a society unwilling to defend its foundational values may discover that its openness becomes its greatest vulnerability.","native":"నిజానికి సరిహద్దులు గీయడం పాక్షికత, దుర్వినియోగ ప్రమాదాలను కలిగి ఉంటుంది; అయినప్పటికీ, తమ పునాది విలువలను రక్షించుకోవడానికి ఇష్టపడని సమాజం తన వెల్లడి స్వభావమే తన అతిపెద్ద బలహీనత అవుతుందని కనుగొనవచ్చు."},{"en":"On balance, tolerance seems wisest when extended to beliefs and identities yet withheld from violence and coercion, a distinction simpler to state than to apply consistently.","native":"మొత్తానికి, సహనం నమ్మకాలు, గుర్తింపులకు విస్తరించి, హింస, బలవంతం నుండి దూరంగా ఉన్నప్పుడు అత్యంత తెలివైనదిగా ఉంటుంది; చెప్పడానికి కంటే స్థిరంగా అమలు చేయడం కష్టమైన వ్యత్యాసం ఇది."}]},"hi":{"word":"सहिष्णुता","question":"क्या एक सहिष्णु समाज को जो सहना चाहिए, उसकी कोई सीमाएँ हैं?","examples":[{"en":"While tolerance rightly ranks among the cardinal democratic virtues, it could be argued that tolerating intolerance itself gradually destroys the conditions that make tolerance possible.","native":"जबकि सहिष्णुता प्रमुख लोकतांत्रिक गुणों में सही रूप से गिनी जाती है, यह तर्क दिया जा सकता है कि असहिष्णुता को सहना धीरे-धीरे उन्हीं परिस्थितियों को नष्ट कर देता है जो सहिष्णुता को संभव बनाती हैं।"},{"en":"Admittedly, drawing boundaries risks hypocrisy and abuse; nevertheless, a society unwilling to defend its foundational values may discover that its openness becomes its greatest vulnerability.","native":"यह स्वीकार करना होगा कि सीमाएँ खींचना पाखंड और दुरुपयोग का जोखिम लाता है; फिर भी, अपने मूलभूत मूल्यों की रक्षा करने को तैयार न रहने वाला समाज पा सकता है कि उसका खुलापन उसकी सबसे बड़ी कमज़ोरी बन जाए।"},{"en":"On balance, tolerance seems wisest when extended to beliefs and identities yet withheld from violence and coercion, a distinction simpler to state than to apply consistently.","native":"कुल मिलाकर, सहिष्णुता तब सबसे बुद्धिमान लगती है जब वह मान्यताओं और पहचानों तक विस्तारित हो, पर हिंसा और जबरदस्ती से रोकी जाए—यह अंतर कहने में जितना आसान है, लगातार लागू करने में उतना नहीं।"}]},"es":{"word":"tolerancia","question":"¿Hay límites a lo que una sociedad tolerante debería tolerar?","examples":[{"en":"While tolerance rightly ranks among the cardinal democratic virtues, it could be argued that tolerating intolerance itself gradually destroys the conditions that make tolerance possible.","native":"Aunque la tolerancia se cuenta con razón entre las virtudes democráticas cardinales, podría argumentarse que tolerar la intolerancia misma destruye gradualmente las condiciones que hacen posible la tolerancia."},{"en":"Admittedly, drawing boundaries risks hypocrisy and abuse; nevertheless, a society unwilling to defend its foundational values may discover that its openness becomes its greatest vulnerability.","native":"Es cierto que trazar límites arriesga hipocresía y abuso; sin embargo, una sociedad que no está dispuesta a defender sus valores fundamentales puede descubrir que su apertura se convierte en su mayor vulnerabilidad."},{"en":"On balance, tolerance seems wisest when extended to beliefs and identities yet withheld from violence and coercion, a distinction simpler to state than to apply consistently.","native":"En definitiva, la tolerancia parece más sabia cuando se extiende a creencias e identidades pero se niega a la violencia y la coacción, una distinción más fácil de enunciar que de aplicar con coherencia."}]},"zh":{"word":"宽容","question":"一个宽容的社会所应容忍的事物是否有其限度？","examples":[{"en":"While tolerance rightly ranks among the cardinal democratic virtues, it could be argued that tolerating intolerance itself gradually destroys the conditions that make tolerance possible.","native":"尽管宽容理当位列民主的基本美德之中，但可以认为，容忍不宽容本身会逐渐摧毁使宽容成为可能的条件。"},{"en":"Admittedly, drawing boundaries risks hypocrisy and abuse; nevertheless, a society unwilling to defend its foundational values may discover that its openness becomes its greatest vulnerability.","native":"诚然，划定界限有虚伪和滥用的风险；然而，一个不愿捍卫其基本价值的社会可能会发现，它的开放反而成了它最大的软肋。"},{"en":"On balance, tolerance seems wisest when extended to beliefs and identities yet withheld from violence and coercion, a distinction simpler to state than to apply consistently.","native":"总体而言，宽容在延伸至信仰和身份、却拒绝对暴力和胁迫让步时似乎最为明智——这一区别说起来容易，要始终贯彻却难。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'diversity', 'Does cultural diversity strengthen societies, or does it make social cohesion harder to maintain?', '{"te":{"word":"వైవిధ్యం","question":"సాంస్కృతిక వైవిధ్యం సమాజాలను బలపరుస్తుందా, లేక సామాజిక ఐక్యతను కొనసాగించడాన్ని కష్టతరం చేస్తుందా?","examples":[{"en":"While diversity undeniably enriches cuisine, art, and ideas, it could be argued that it demands deliberate effort, since difference alone never guarantees mutual understanding.","native":"వైవిధ్యం వంటకాలనూ, కళలనూ, ఆలోచనలనూ నిస్సందేహంగా సమృద్ధి చేసినప్పటికీ, భేదం మాత్రమే పరస్పర అవగాహనను ఎప్పుడూ హామీ ఇవ్వదు కాబట్టి అది ఉద్దేశపూర్వక కృషిని కోరుతుందని చెప్పవచ్చు."},{"en":"Admittedly, homogeneous societies enjoy an easy, unspoken solidarity; nevertheless, they also tend towards complacency, mistaking familiarity for virtue and outsiders for threats.","native":"నిజానికి సజాతీయ సమాజాలు సులభమైన, చెప్పని ఐక్యతను అనుభవిస్తాయి; అయినప్పటికీ, అవి స్వపరిపూర్ణత వైపు మొగ్గు చూపుతాయి, పరిచయాన్ని సద్గుణంగా, బయటివారిని ముప్పులుగా భ్రమపడతాయి."},{"en":"On balance, cohesion seems to depend less on sameness than on shared institutions and fair treatment, which suggests diversity itself is rarely the actual problem.","native":"మొత్తానికి, ఐక్యత ఏకరూపత కంటే ఉమ్మడి సంస్థలు, న్యాయమైన వ్యవహారంపై ఎక్కువగా ఆధారపడుతుందని అనిపిస్తుంది; వైవిధ్యమే అసలు సమస్య అరుదని ఇది సూచిస్తుంది."}]},"hi":{"word":"विविधता","question":"क्या सांस्कृतिक विविधता समाजों को मज़बूत बनाती है, या सामाजिक एकजुटता बनाए रखना कठिन कर देती है?","examples":[{"en":"While diversity undeniably enriches cuisine, art, and ideas, it could be argued that it demands deliberate effort, since difference alone never guarantees mutual understanding.","native":"जबकि विविधता निस्संदेह व्यंजन, कला और विचारों को समृद्ध करती है, यह तर्क दिया जा सकता है कि इसके लिए जानबूझकर प्रयास चाहिए, क्योंकि अकेला अंतर कभी पारस्परिक समझ की गारंटी नहीं देता।"},{"en":"Admittedly, homogeneous societies enjoy an easy, unspoken solidarity; nevertheless, they also tend towards complacency, mistaking familiarity for virtue and outsiders for threats.","native":"यह स्वीकार करना होगा कि सजातीय समाज एक सहज, अकथित एकजुटता का आनंद लेते हैं; फिर भी, वे आत्मसंतोष की ओर भी झुकते हैं, परिचितता को गुण और बाहरी लोगों को खतरा समझ बैठते हैं।"},{"en":"On balance, cohesion seems to depend less on sameness than on shared institutions and fair treatment, which suggests diversity itself is rarely the actual problem.","native":"कुल मिलाकर, एकजुटता समानता से कम और साझा संस्थाओं तथा निष्पक्ष व्यवहार पर अधिक निर्भर लगती है—इससे पता चलता है कि विविधता स्वयं शायद ही कभी वास्तविक समस्या होती है।"}]},"es":{"word":"diversidad","question":"¿Fortalece la diversidad cultural a las sociedades, o dificulta mantener la cohesión social?","examples":[{"en":"While diversity undeniably enriches cuisine, art, and ideas, it could be argued that it demands deliberate effort, since difference alone never guarantees mutual understanding.","native":"Aunque la diversidad indudablemente enriquece la cocina, el arte y las ideas, podría argumentarse que exige un esfuerzo deliberado, ya que la diferencia por sí sola nunca garantiza la comprensión mutua."},{"en":"Admittedly, homogeneous societies enjoy an easy, unspoken solidarity; nevertheless, they also tend towards complacency, mistaking familiarity for virtue and outsiders for threats.","native":"Es cierto que las sociedades homogéneas disfrutan de una solidaridad fácil y tácita; sin embargo, también tienden a la complacencia, confundiendo la familiaridad con la virtud y a los forasteros con amenazas."},{"en":"On balance, cohesion seems to depend less on sameness than on shared institutions and fair treatment, which suggests diversity itself is rarely the actual problem.","native":"En definitiva, la cohesión parece depender menos de la uniformidad que de las instituciones compartidas y el trato justo, lo que sugiere que la diversidad en sí rara vez es el verdadero problema."}]},"zh":{"word":"多样性","question":"文化多样性是增强了社会，还是让社会凝聚力更难维持？","examples":[{"en":"While diversity undeniably enriches cuisine, art, and ideas, it could be argued that it demands deliberate effort, since difference alone never guarantees mutual understanding.","native":"尽管多样性无疑丰富了美食、艺术和思想，但可以认为，它需要刻意的努力，因为仅仅存在差异并不能保证相互理解。"},{"en":"Admittedly, homogeneous societies enjoy an easy, unspoken solidarity; nevertheless, they also tend towards complacency, mistaking familiarity for virtue and outsiders for threats.","native":"诚然，同质化的社会享有一种轻松而不言自明的团结；然而，它们也容易陷入自满，把熟悉误认为美德，把外来者误认为威胁。"},{"en":"On balance, cohesion seems to depend less on sameness than on shared institutions and fair treatment, which suggests diversity itself is rarely the actual problem.","native":"总体而言，凝聚力似乎更多地取决于共同的制度和公平的对待，而非整齐划一——这表明多样性本身很少是真正的问题。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'multiculturalism', 'Has multiculturalism succeeded as a policy, or should newcomers be expected to assimilate?', '{"te":{"word":"బహుళ సంస్కృతివాదం","question":"విధానంగా బహుళ సంస్కృతివాదం విజయవంతమైందా, లేక కొత్తగా వచ్చినవారు విలీనం కావాలని ఆశించాలా?","examples":[{"en":"While critics declare multiculturalism a failure, it could be argued that the alternatives, forced assimilation and exclusion, have historically produced far deeper resentments.","native":"విమర్శకులు బహుళ సంస్కృతివాదం విఫలమైందని ప్రకటించినప్పటికీ, బలవంతపు విలీనం, మినహాయింపు అనే ప్రత్యామ్నాయాలు చారిత్రకంగా చాలా లోతైన అసంతృప్తులను సృష్టించాయని చెప్పవచ్చు."},{"en":"Admittedly, parallel communities can develop when integration is neglected; nevertheless, the evidence suggests most second-generation immigrants adopt the majority language and customs with ease.","native":"నిజానికి విలీనం నిర్లక్ష్యం చేయబడినప్పుడు సమాంతర సమాజాలు ఏర్పడవచ్చు; అయినప్పటికీ, చాలామంది రెండో తరం వలసదారులు మెజారిటీ భాషనూ ఆచారాలనూ సులభంగా అవలంబిస్తారని సాక్ష్యాలు సూచిస్తున్నాయి."},{"en":"On balance, multiculturalism seems less a rigid doctrine than a pragmatic recognition that belonging cannot be commanded, only patiently and fairly encouraged.","native":"మొత్తానికి, బహుళ సంస్కృతివాదం కఠోర సిద్ధాంతం కంటే, చేరికను ఆజ్ఞాపించలేము, కేవలం సహనంగా, న్యాయంగా ప్రోత్సహించగలమనే ఆచరణాత్మక గుర్తింపుగా కనిపిస్తుంది."}]},"hi":{"word":"बहुसांस्कृतिकवाद","question":"क्या बहुसांस्कृतिकवाद एक नीति के रूप में सफल रहा है, या नवागंतुकों से घुल-मिल जाने की अपेक्षा की जानी चाहिए?","examples":[{"en":"While critics declare multiculturalism a failure, it could be argued that the alternatives, forced assimilation and exclusion, have historically produced far deeper resentments.","native":"जबकि आलोचक बहुसांस्कृतिकवाद को असफल घोषित करते हैं, यह तर्क दिया जा सकता है कि विकल्प—जबरन समाकलन और बहिष्कार—ऐतिहासिक रूप से कहीं गहरी नाराज़गियाँ पैदा कर चुके हैं।"},{"en":"Admittedly, parallel communities can develop when integration is neglected; nevertheless, the evidence suggests most second-generation immigrants adopt the majority language and customs with ease.","native":"यह स्वीकार करना होगा कि एकीकरण की उपेक्षा होने पर समानांतर समुदाय विकसित हो सकते हैं; फिर भी, प्रमाण बताते हैं कि अधिकांश दूसरी पीढ़ी के आप्रवासी बहुमत की भाषा और रीति-रिवाज़ों को आसानी से अपना लेते हैं।"},{"en":"On balance, multiculturalism seems less a rigid doctrine than a pragmatic recognition that belonging cannot be commanded, only patiently and fairly encouraged.","native":"कुल मिलाकर, बहुसांस्कृतिकवाद किसी कठोर सिद्धांत से कम और इस व्यावहारिक स्वीकृति जैसा अधिक लगता है कि अपनेपन का आदेश नहीं दिया जा सकता, बस धैर्य और निष्पक्षता से प्रोत्साहित किया जा सकता है।"}]},"es":{"word":"multiculturalismo","question":"¿Ha tenido éxito el multiculturalismo como política, o debería esperarse que los recién llegados se asimilen?","examples":[{"en":"While critics declare multiculturalism a failure, it could be argued that the alternatives, forced assimilation and exclusion, have historically produced far deeper resentments.","native":"Aunque los críticos declaran fracasado el multiculturalismo, podría argumentarse que las alternativas, la asimilación forzada y la exclusión, han producido históricamente resentimientos mucho más profundos."},{"en":"Admittedly, parallel communities can develop when integration is neglected; nevertheless, the evidence suggests most second-generation immigrants adopt the majority language and customs with ease.","native":"Es cierto que pueden surgir comunidades paralelas cuando se descuida la integración; sin embargo, la evidencia sugiere que la mayoría de los inmigrantes de segunda generación adoptan con facilidad el idioma y las costumbres mayoritarios."},{"en":"On balance, multiculturalism seems less a rigid doctrine than a pragmatic recognition that belonging cannot be commanded, only patiently and fairly encouraged.","native":"En definitiva, el multiculturalismo parece menos una doctrina rígida que un reconocimiento pragmático de que la pertenencia no puede ordenarse, solo fomentarse con paciencia y equidad."}]},"zh":{"word":"多元文化主义","question":"多元文化主义作为一项政策成功了吗，还是应当要求新移民融入主流？","examples":[{"en":"While critics declare multiculturalism a failure, it could be argued that the alternatives, forced assimilation and exclusion, have historically produced far deeper resentments.","native":"尽管批评者宣称多元文化主义失败了，但可以认为，其替代方案——强制同化和排斥——在历史上造成了深得多的怨恨。"},{"en":"Admittedly, parallel communities can develop when integration is neglected; nevertheless, the evidence suggests most second-generation immigrants adopt the majority language and customs with ease.","native":"诚然，当融合被忽视时，可能形成平行社区；然而，证据表明，大多数第二代移民都能轻松采用多数群体的语言和习俗。"},{"en":"On balance, multiculturalism seems less a rigid doctrine than a pragmatic recognition that belonging cannot be commanded, only patiently and fairly encouraged.","native":"总体而言，多元文化主义与其说是一条僵硬的教条，不如说是一种务实的认识：归属感无法靠命令获得，只能耐心而公平地培养。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'assimilation', 'What do immigrants gain and lose when they assimilate into a new culture?', '{"te":{"word":"విలీనం","question":"కొత్త సంస్కృతిలో విలీనం అయినప్పుడు వలసదారులు ఏమి పొందుతారు, ఏమి కోల్పోతారు?","examples":[{"en":"While assimilation eases daily life and broadens opportunity, it could be argued that the pressure to conform exacts a quiet toll on identity, language, and family memory.","native":"విలీనం దైనందిన జీవితాన్ని సులభతరం చేసి అవకాశాలను విస్తరించినప్పటికీ, అనుగుణంగా ఉండాల్సిన ఒత్తిడి గుర్తింపు, భాష మరియు కుటుంబ జ్ఞాపకాలపై నిశ్శబ్దమైన ధర విధిస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, every migrant negotiates some blending of old and new; nevertheless, those who assimilate most completely often describe a peculiar grief that others find difficult to understand.","native":"నిజానికి ప్రతి వలసదారు కొత్తది, పాతది కలిపే ఏదో ఒక సర్దుబాటు చేస్తారు; అయినప్పటికీ, అత్యంత పూర్తిగా విలీనమైనవారు తరచుగా ఇతరులకు అర్థం కాని విచిత్రమైన దుఃఖాన్ని వర్ణిస్తారు."},{"en":"On balance, assimilation seems healthiest when it remains a choice rather than an obligation, since genuine belonging has never yet been produced by compulsion.","native":"మొత్తానికి, విలీనం బాధ్యత కంటే ఎంపికగా ఉన్నప్పుడు అత్యంత ఆరోగ్యకరంగా ఉంటుంది, ఎందుకంటే బలవంతంతో నిజమైన చేరిక ఇంతవరకూ ఎప్పుడూ ఉత్పత్తి కాలేదు."}]},"hi":{"word":"समाकलन","question":"जब आप्रवासी किसी नई संस्कृति में घुल जाते हैं तो वे क्या पाते हैं और क्या खोते हैं?","examples":[{"en":"While assimilation eases daily life and broadens opportunity, it could be argued that the pressure to conform exacts a quiet toll on identity, language, and family memory.","native":"जबकि समाकलन दैनिक जीवन आसान करता है और अवसर बढ़ाता है, यह तर्क दिया जा सकता है कि अनुकूलन का दबाव पहचान, भाषा और पारिवारिक स्मृति पर एक मौन कीमत वसूलता है।"},{"en":"Admittedly, every migrant negotiates some blending of old and new; nevertheless, those who assimilate most completely often describe a peculiar grief that others find difficult to understand.","native":"यह स्वीकार करना होगा कि हर प्रवासी पुराने और नए का कोई न कोई मिश्रण करता है; फिर भी, जो सबसे पूरी तरह घुल जाते हैं, वे अक्सर एक विचित्र शोक का वर्णन करते हैं जिसे दूसरे समझना कठिन पाते हैं।"},{"en":"On balance, assimilation seems healthiest when it remains a choice rather than an obligation, since genuine belonging has never yet been produced by compulsion.","native":"कुल मिलाकर, समाकलन तब सबसे स्वस्थ लगता है जब वह दायित्व के बजाय एक विकल्प रहे, क्योंकि वास्तविक अपनेपन को आज तक मजबूरी से कभी पैदा नहीं किया गया है।"}]},"es":{"word":"asimilación","question":"¿Qué ganan y qué pierden los inmigrantes cuando se asimilan a una nueva cultura?","examples":[{"en":"While assimilation eases daily life and broadens opportunity, it could be argued that the pressure to conform exacts a quiet toll on identity, language, and family memory.","native":"Aunque la asimilación facilita la vida diaria y amplía las oportunidades, podría argumentarse que la presión por conformarse cobra un precio silencioso sobre la identidad, la lengua y la memoria familiar."},{"en":"Admittedly, every migrant negotiates some blending of old and new; nevertheless, those who assimilate most completely often describe a peculiar grief that others find difficult to understand.","native":"Es cierto que todo migrante negocia alguna mezcla de lo viejo y lo nuevo; sin embargo, quienes se asimilan más por completo a menudo describen un dolor peculiar que a otros les resulta difícil de comprender."},{"en":"On balance, assimilation seems healthiest when it remains a choice rather than an obligation, since genuine belonging has never yet been produced by compulsion.","native":"En definitiva, la asimilación parece más saludable cuando sigue siendo una elección y no una obligación, ya que la pertenencia genuina jamás ha sido producida por la compulsión."}]},"zh":{"word":"同化","question":"移民在融入新文化时得到了什么，又失去了什么？","examples":[{"en":"While assimilation eases daily life and broadens opportunity, it could be argued that the pressure to conform exacts a quiet toll on identity, language, and family memory.","native":"尽管同化让日常生活更便利、机会更广阔，但可以认为，顺从的压力会悄悄地索取身份、语言和家族记忆作为代价。"},{"en":"Admittedly, every migrant negotiates some blending of old and new; nevertheless, those who assimilate most completely often describe a peculiar grief that others find difficult to understand.","native":"诚然，每个移民都要在新旧之间做出某种调和；然而，同化得最彻底的人往往会描述一种旁人难以理解的奇特哀伤。"},{"en":"On balance, assimilation seems healthiest when it remains a choice rather than an obligation, since genuine belonging has never yet been produced by compulsion.","native":"总体而言，当同化是一种选择而非义务时，它似乎最为健康，因为真正的归属感从来无法靠强迫产生。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'heritage', 'Should preserving cultural heritage be a priority, even when it conflicts with economic development?', '{"te":{"word":"వారసత్వం","question":"ఆర్థిక అభివృద్ధితో విభేదించినప్పటికీ, సాంస్కృతిక వారసత్వాన్ని కాపాడడం ప్రాధాన్యం కావాలా?","examples":[{"en":"While development advocates dismiss preservation as nostalgia, it could be argued that heritage anchors collective identity in ways that GDP figures entirely fail to capture.","native":"అభివృద్ధి సమర్థకులు పరిరక్షణను పురాతన భావనగా తక్కువ చేసినప్పటికీ, జీడీపీ గణాంకాలు పూర్తిగా పట్టుకోలేని విధంగా వారసత్వం సామూహిక గుర్తింపును స్థిరపరుస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, not every old building merits saving; nevertheless, societies that demolish their past for short-term profit frequently express regret within a single generation.","native":"నిజానికి ప్రతి పాత భవనమూ కాపాడటానికి అర్హం కాదు; అయినప్పటికీ, స్వల్పకాలిక లాభం కోసం తమ గతాన్ని కూల్చే సమాజాలు తరచుగా ఒక్క తరంలోపే పశ్చాత్తాపం వ్యక్తం చేస్తాయి."},{"en":"On balance, preservation seems wisest when selective and living, since a heritage reduced to museum pieces arguably loses the vitality that made it worth keeping.","native":"మొత్తానికి, పరిరక్షణ ఎంపికగా, జీవంతంగా ఉన్నప్పుడు అత్యంత తెలివైనది, ఎందుకంటే మ్యూజియం వస్తువులుగా తగ్గిన వారసత్వం దాన్ని కాపాడదగ్గ చైతన్యాన్ని కోల్పోతుందని చెప్పవచ్చు."}]},"hi":{"word":"विरासत","question":"क्या सांस्कृतिक विरासत को संरक्षित करना प्राथमिकता होनी चाहिए, भले ही यह आर्थिक विकास से टकराए?","examples":[{"en":"While development advocates dismiss preservation as nostalgia, it could be argued that heritage anchors collective identity in ways that GDP figures entirely fail to capture.","native":"जबकि विकास समर्थक संरक्षण को पुराने की चाह कहकर खारिज करते हैं, यह तर्क दिया जा सकता है कि विरासत सामूहिक पहचान को उन तरीकों से सुधृढ़ करती है जिन्हें जीडीपी के आँकड़े बिल्कुल पकड़ नहीं पाते।"},{"en":"Admittedly, not every old building merits saving; nevertheless, societies that demolish their past for short-term profit frequently express regret within a single generation.","native":"यह स्वीकार करना होगा कि हर पुरानी इमारत बचाने लायक नहीं है; फिर भी, अल्पकालिक लाभ के लिए अपना अतीत गिराने वाले समाज अक्सर एक ही पीढ़ी के भीतर पछतावा व्यक्त करते हैं।"},{"en":"On balance, preservation seems wisest when selective and living, since a heritage reduced to museum pieces arguably loses the vitality that made it worth keeping.","native":"कुल मिलाकर, संरक्षण तब सबसे बुद्धिमान लगता है जब वह चयनात्मक और जीवंत हो, क्योंकि संग्रहालय की वस्तुओं तक सीमित विरासत तर्कतः वही जीवंतता खो देती है जिसके लिए उसे रखना सार्थक था।"}]},"es":{"word":"patrimonio","question":"¿Debería ser prioritario preservar el patrimonio cultural, incluso cuando entra en conflicto con el desarrollo económico?","examples":[{"en":"While development advocates dismiss preservation as nostalgia, it could be argued that heritage anchors collective identity in ways that GDP figures entirely fail to capture.","native":"Aunque los defensores del desarrollo descartan la preservación como nostalgia, podría argumentarse que el patrimonio ancla la identidad colectiva de maneras que las cifras del PIB no capturan en absoluto."},{"en":"Admittedly, not every old building merits saving; nevertheless, societies that demolish their past for short-term profit frequently express regret within a single generation.","native":"Es cierto que no todo edificio antiguo merece salvarse; sin embargo, las sociedades que demuelen su pasado por beneficios a corto plazo frecuentemente expresan arrepentimiento en una sola generación."},{"en":"On balance, preservation seems wisest when selective and living, since a heritage reduced to museum pieces arguably loses the vitality that made it worth keeping.","native":"En definitiva, la preservación parece más sabia cuando es selectiva y viva, ya que un patrimonio reducido a piezas de museo pierde posiblemente la vitalidad que lo hacía digno de conservar."}]},"zh":{"word":"文化遗产","question":"即使与经济发展相冲突，保护文化遗产是否也应当作为优先事项？","examples":[{"en":"While development advocates dismiss preservation as nostalgia, it could be argued that heritage anchors collective identity in ways that GDP figures entirely fail to capture.","native":"尽管发展的倡导者把保护斥为怀旧，但可以认为，遗产以国内生产总值数据完全无法捕捉的方式锚定着集体认同。"},{"en":"Admittedly, not every old building merits saving; nevertheless, societies that demolish their past for short-term profit frequently express regret within a single generation.","native":"诚然，并非每栋老建筑都值得保留；然而，为短期利益拆除历史的社会，往往不出一代人就会表达悔意。"},{"en":"On balance, preservation seems wisest when selective and living, since a heritage reduced to museum pieces arguably loses the vitality that made it worth keeping.","native":"总体而言，有选择且活态的保护似乎最明智，因为沦为博物馆藏品的遗产可以说失去了最初使其值得保存的活力。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'tradition', 'When should traditions be preserved, and when should they be abandoned?', '{"te":{"word":"సంప్రదాయం","question":"సంప్రదాయాలను ఎప్పుడు కాపాడాలి, ఎప్పుడు వదిలివేయాలి?","examples":[{"en":"While traditions provide continuity and belonging, it could be argued that some deserve preservation only as history, not as obligations imposed upon the living.","native":"సంప్రదాయాలు అన్వయాన్నీ చేరికనూ అందించినప్పటికీ, కొన్నింటిని జీవించేవారిపై విధించే బాధ్యతలుగా కాకుండా కేవలం చరిత్రగా మాత్రమే కాపాడాలని చెప్పవచ్చు."},{"en":"Admittedly, every generation reformulates what it inherits; nevertheless, discarding customs wholesale risks severing the threads that connect individuals to something larger than themselves.","native":"నిజానికి ప్రతి తరం తాను వారసత్వంగా పొందినదాన్ని తిరిగి రూపొందిస్తుంది; అయినప్పటికీ, ఆచారాలను మొత్తంగా పడేయడం వ్యక్తులను వారికంటే గొప్ప దేనితోనూ కలిపే దారాలను తెంచే ప్రమాదం ఉంది."},{"en":"On balance, a tradition''s value seems to lie in whether it still nourishes human flourishing, a test far more demanding than mere age or sentimental attachment.","native":"మొత్తానికి, సంప్రదాయం విలువ అది ఇంకా మానవ వికాసాన్ని పోషిస్తుందా లేదా అనే దానిపై ఆధారపడి ఉంటుంది; కేవలం పురాతనత్వం లేదా భావోద్వేగ అనుబంధం కంటే ఇది చాలా కఠినమైన పరీక్ష."}]},"hi":{"word":"परंपरा","question":"परंपराओं को कब संरक्षित किया जाना चाहिए, और कब त्याग देना चाहिए?","examples":[{"en":"While traditions provide continuity and belonging, it could be argued that some deserve preservation only as history, not as obligations imposed upon the living.","native":"जबकि परंपराएँ निरंतरता और अपनेपन देती हैं, यह तर्क दिया जा सकता है कि कुछ केवल इतिहास के रूप में संरक्षण की हक़दार हैं, जीवित लोगों पर थोपे गए दायित्वों के रूप में नहीं।"},{"en":"Admittedly, every generation reformulates what it inherits; nevertheless, discarding customs wholesale risks severing the threads that connect individuals to something larger than themselves.","native":"यह स्वीकार करना होगा कि हर पीढ़ी अपनी विरासत को नया रूप देती है; फिर भी, रीति-रिवाज़ों को थोक में त्यागना उन धागों को काटने का जोखिम लाता है जो व्यक्तियों को उनसे बड़ी किसी चीज़ से जोड़ते हैं।"},{"en":"On balance, a tradition''s value seems to lie in whether it still nourishes human flourishing, a test far more demanding than mere age or sentimental attachment.","native":"कुल मिलाकर, परंपरा का मूल्य इसमें निहित लगता है कि क्या वह अब भी मानवीय समृद्धि का पोषण करती है—यह परीक्षा महज़ पुरानापन या भावनात्मक लगाव से कहीं अधिक कठिन है।"}]},"es":{"word":"tradición","question":"¿Cuándo deberían preservarse las tradiciones y cuándo abandonarse?","examples":[{"en":"While traditions provide continuity and belonging, it could be argued that some deserve preservation only as history, not as obligations imposed upon the living.","native":"Aunque las tradiciones aportan continuidad y pertenencia, podría argumentarse que algunas merecen preservarse solo como historia, no como obligaciones impuestas a los vivos."},{"en":"Admittedly, every generation reformulates what it inherits; nevertheless, discarding customs wholesale risks severing the threads that connect individuals to something larger than themselves.","native":"Es cierto que cada generación reformula lo que hereda; sin embargo, descartar las costumbres al por mayor arriesga cortar los hilos que conectan a los individuos con algo más grande que ellos mismos."},{"en":"On balance, a tradition''s value seems to lie in whether it still nourishes human flourishing, a test far more demanding than mere age or sentimental attachment.","native":"En definitiva, el valor de una tradición parece residir en si aún nutre el florecimiento humano, una prueba mucho más exigente que la mera antigüedad o el apego sentimental."}]},"zh":{"word":"传统","question":"传统应当在什么时候被保留，又在什么时候被抛弃？","examples":[{"en":"While traditions provide continuity and belonging, it could be argued that some deserve preservation only as history, not as obligations imposed upon the living.","native":"尽管传统提供了延续性和归属感，但可以认为，有些传统只值得作为历史来保存，而不应作为强加给生者的义务。"},{"en":"Admittedly, every generation reformulates what it inherits; nevertheless, discarding customs wholesale risks severing the threads that connect individuals to something larger than themselves.","native":"诚然，每一代人都会重新诠释所继承的东西；然而，全盘抛弃习俗有可能切断把个人与超越自身的事物联系起来的纽带。"},{"en":"On balance, a tradition''s value seems to lie in whether it still nourishes human flourishing, a test far more demanding than mere age or sentimental attachment.","native":"总体而言，传统的价值似乎在于它是否仍然滋养着人类的蓬勃发展——这一考验远比单纯的古老或情感依恋更为严苛。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'progress', 'Is human progress inevitable, or could societies move backwards?', '{"te":{"word":"పురోగతి","question":"మానవ పురోగతి అనివార్యమా, లేక సమాజాలు వెనక్కి వెళ్లవచ్చా?","examples":[{"en":"While optimists treat progress as a law of nature, it could be argued that history records as many civilisational collapses as it does advances.","native":"ఆశావాదులు పురోగతిని ప్రకృతి నియమంగా భావించినప్పటికీ, చరిత్ర పురోగతులన్నింటిని అంతే నాగరికతా పతనాలను కూడా నమోదు చేస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, material living standards have risen spectacularly; nevertheless, moral and political gains appear disturbingly reversible whenever fear displaces reason in public life.","native":"నిజానికి భౌతిక జీవన ప్రమాణాలు అద్భుతంగా పెరిగాయి; అయినప్పటికీ, ప్రజా జీవితంలో భయం తర్కాన్ని వెనక్కి నెట్టినప్పుడల్లా నైతిక, రాజకీయ పురోగతులు కలవరపరిచేంతగా రద్దయ్యేలా కనిపిస్తాయి."},{"en":"On balance, progress seems less like an escalator than a staircase we must keep climbing deliberately, since standing still, in effect, means slowly moving backwards.","native":"మొత్తానికి, పురోగతి ఎస్కలేటర్ కంటే మనం ఉద్దేశపూర్వకంగా ఎక్కుతూనే ఉండాల్సిన మెట్లలా కనిపిస్తుంది, ఎందుకంటే నిలిచిపోవడం వాస్తవానికి నెమ్మదిగా వెనక్కి వెళ్లడమే."}]},"hi":{"word":"प्रगति","question":"क्या मानवीय प्रगति अनिवार्य है, या समाज पीछे भी जा सकते हैं?","examples":[{"en":"While optimists treat progress as a law of nature, it could be argued that history records as many civilisational collapses as it does advances.","native":"जबकि आशावादी प्रगति को प्रकृति का नियम मानते हैं, यह तर्क दिया जा सकता है कि इतिहास उतनी ही सभ्यताओं के पतन को भी दर्ज करता है जितनी प्रगतियों को।"},{"en":"Admittedly, material living standards have risen spectacularly; nevertheless, moral and political gains appear disturbingly reversible whenever fear displaces reason in public life.","native":"यह स्वीकार करना होगा कि भौतिक जीवन स्तर शानदार रूप से ऊँचा हुआ है; फिर भी, जब भी सार्वजनिक जीवन में भय तर्क की जगह लेता है, नैतिक और राजनीतिक उपलब्धियाँ चौंकाने वाली तरह से उलटने योग्य लगती हैं।"},{"en":"On balance, progress seems less like an escalator than a staircase we must keep climbing deliberately, since standing still, in effect, means slowly moving backwards.","native":"कुल मिलाकर, प्रगति एस्केलेटर से कम और उस सीढ़ी जैसी अधिक लगती है जिसे हमें जानबूझकर चढ़ते रहना होगा, क्योंकि रुक जाना वास्तव में धीरे-धीरे पीछे जाना है।"}]},"es":{"word":"progreso","question":"¿Es inevitable el progreso humano, o podrían las sociedades retroceder?","examples":[{"en":"While optimists treat progress as a law of nature, it could be argued that history records as many civilisational collapses as it does advances.","native":"Aunque los optimistas tratan el progreso como una ley de la naturaleza, podría argumentarse que la historia registra tantos colapsos civilizatorios como avances."},{"en":"Admittedly, material living standards have risen spectacularly; nevertheless, moral and political gains appear disturbingly reversible whenever fear displaces reason in public life.","native":"Es cierto que los niveles materiales de vida han subido espectacularmente; sin embargo, los avances morales y políticos parecen inquietantemente reversibles cada vez que el miedo desplaza a la razón en la vida pública."},{"en":"On balance, progress seems less like an escalator than a staircase we must keep climbing deliberately, since standing still, in effect, means slowly moving backwards.","native":"En definitiva, el progreso parece menos una escalera mecánica que una escalinata que debemos seguir subiendo deliberadamente, ya que quedarse quieto equivale, en efecto, a retroceder lentamente."}]},"zh":{"word":"进步","question":"人类的进步是不可避免的吗，还是社会也可能倒退？","examples":[{"en":"While optimists treat progress as a law of nature, it could be argued that history records as many civilisational collapses as it does advances.","native":"尽管乐观主义者把进步当作自然法则，但可以认为，历史记载的文明崩溃与进步一样多。"},{"en":"Admittedly, material living standards have risen spectacularly; nevertheless, moral and political gains appear disturbingly reversible whenever fear displaces reason in public life.","native":"诚然，物质生活水平已经惊人地提高；然而，每当恐惧在公共生活中取代理性时，道德和政治成果似乎都会惊人地可逆。"},{"en":"On balance, progress seems less like an escalator than a staircase we must keep climbing deliberately, since standing still, in effect, means slowly moving backwards.","native":"总体而言，进步与其说像自动扶梯，不如说像一段我们必须刻意不断攀登的楼梯，因为原地踏步实际上就意味着缓慢倒退。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'individualism', 'Does individualism liberate people, or does it leave them isolated and unsupported?', '{"te":{"word":"వ్యక్తివాదం","question":"వ్యక్తివాదం ప్రజలను విముక్తం చేస్తుందా, లేక వారిని ఒంటరిగా, అండదండలు లేకుండా వదిలేస్తుందా?","examples":[{"en":"While individualism freed millions from stifling conformity, it could be argued that its extreme form dissolves the mutual obligations that once cushioned personal failure.","native":"వ్యక్తివాదం కోట్లాదిమందిని ఊపిరాడని అనుకూలత నుండి విముక్తం చేసినప్పటికీ, దాని తీవ్ర రూపం గతంలో వ్యక్తిగత వైఫల్యాన్ని తడ్బదిలిగా చేసిన పరస్పర బాధ్యతలను కరిగిస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, self-reliance builds confidence and initiative; nevertheless, the loneliest societies are often those most committed to the ideal of the self-sufficient individual.","native":"నిజానికి స్వయంసమృద్ధి విశ్వాసాన్నీ చొరవనూ పెంచుతుంది; అయినప్పటికీ, అత్యంత ఒంటరి సమాజాలు తరచుగా స్వయం సమర్థ వ్యక్తి ఆదర్శానికి అత్యంత కట్టుబడినవే అవుతాయి."},{"en":"On balance, individualism seems healthiest when balanced against community, since autonomy without connection tends to produce freedom that feels remarkably like abandonment.","native":"మొత్తానికి, వ్యక్తివాదం సమాజంతో సమతుల్యమైనప్పుడు అత్యంత ఆరోగ్యకరంగా ఉంటుంది, ఎందుకంటే అనుబంధం లేని స్వాయత్తత్వం విడిచిపెట్టబడినట్టు అనిపించే స్వేచ్ఛను తెస్తుంది."}]},"hi":{"word":"व्यक्तिवाद","question":"क्या व्यक्तिवाद लोगों को मुक्त करता है, या उन्हें अकेला और बेसहारा छोड़ देता है?","examples":[{"en":"While individualism freed millions from stifling conformity, it could be argued that its extreme form dissolves the mutual obligations that once cushioned personal failure.","native":"जबकि व्यक्तिवाद ने लाखों लोगों को दमघोंटू अनुरूपता से मुक्त किया, यह तर्क दिया जा सकता है कि इसका चरम रूप उन पारस्परिक दायित्वों को भंग कर देता है जो कभी व्यक्तिगत असफलता को संभालते थे।"},{"en":"Admittedly, self-reliance builds confidence and initiative; nevertheless, the loneliest societies are often those most committed to the ideal of the self-sufficient individual.","native":"यह स्वीकार करना होगा कि आत्मनिर्भरता आत्मविश्वास और पहल बनाती है; फिर भी, सबसे अकेले समाज अक्सर वही होते हैं जो आत्मनिर्भर व्यक्ति के आदर्श के प्रति सबसे अधिक प्रतिबद्ध होते हैं।"},{"en":"On balance, individualism seems healthiest when balanced against community, since autonomy without connection tends to produce freedom that feels remarkably like abandonment.","native":"कुल मिलाकर, व्यक्तिवाद तब सबसे स्वस्थ लगता है जब वह समुदाय से संतुलित हो, क्योंकि बिना जुड़ाव की स्वायत्तता ऐसी स्वतंत्रता पैदा करती है जो उल्लेखनीय रूप से त्याग जैसी लगती है।"}]},"es":{"word":"individualismo","question":"¿Libera el individualismo a las personas, o las deja aisladas y desprotegidas?","examples":[{"en":"While individualism freed millions from stifling conformity, it could be argued that its extreme form dissolves the mutual obligations that once cushioned personal failure.","native":"Aunque el individualismo liberó a millones de una conformidad asfixiante, podría argumentarse que su forma extrema disuelve las obligaciones mutuas que antes amortiguaban el fracaso personal."},{"en":"Admittedly, self-reliance builds confidence and initiative; nevertheless, the loneliest societies are often those most committed to the ideal of the self-sufficient individual.","native":"Es cierto que la autosuficiencia genera confianza e iniciativa; sin embargo, las sociedades más solitarias suelen ser las más comprometidas con el ideal del individuo autosuficiente."},{"en":"On balance, individualism seems healthiest when balanced against community, since autonomy without connection tends to produce freedom that feels remarkably like abandonment.","native":"En definitiva, el individualismo parece más saludable cuando se equilibra con la comunidad, ya que la autonomía sin conexión tiende a producir una libertad que se siente notablemente como abandono."}]},"zh":{"word":"个人主义","question":"个人主义解放了人们，还是让他们孤立无援？","examples":[{"en":"While individualism freed millions from stifling conformity, it could be argued that its extreme form dissolves the mutual obligations that once cushioned personal failure.","native":"尽管个人主义使数百万人摆脱了令人窒息的从众，但可以认为，它的极端形式消解了曾经缓冲个人失败的相互义务。"},{"en":"Admittedly, self-reliance builds confidence and initiative; nevertheless, the loneliest societies are often those most committed to the ideal of the self-sufficient individual.","native":"诚然，自力更生能建立信心和主动性；然而，最孤独的社会往往正是那些最信奉自给自足个人理想的社会。"},{"en":"On balance, individualism seems healthiest when balanced against community, since autonomy without connection tends to produce freedom that feels remarkably like abandonment.","native":"总体而言，个人主义在与社群相平衡时似乎最为健康，因为没有联结的自主往往会产生一种感觉上像极了被抛弃的自由。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'community', 'Why do many people feel a weaker sense of community than previous generations did?', '{"te":{"word":"సంఘం","question":"గత తరాలతో పోలిస్తే చాలామంది సంఘ భావన బలహీనంగా ఎందుకు భావిస్తున్నారు?","examples":[{"en":"While commentators blame technology for declining community, it could be argued that economic mobility and insecure work uproot people long before smartphones enter the picture.","native":"వ్యాఖ్యాతలు సంఘ క్షయానికి సాంకేతికతను నిందించినప్పటికీ, స్మార్ట్‌ఫోన్లు చేరడానికి చాలా ముందే ఆర్థిక సంచలనం, అస్థిర ఉద్యోగాలు ప్రజలను వేళ్లతో పెకిలిస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, online networks connect us across continents; nevertheless, they rarely provide the practical support—borrowed tools, shared childcare—that physical neighbours once routinely exchanged.","native":"నిజానికి ఆన్‌లైన్ నెట్‌వర్కులు మనల్ని ఖండాల అటుగా కలుపుతాయి; అయినప్పటికీ, భౌతిక పొరుగువారు గతంలో అలవాటుగా మార్చుకునే ఆచరణాత్మక సహాయాన్ని—అప్పుగా తీసుకునే పనిముట్లు, పంచుకునే పిల్లల సంరక్షణ—అవి అరుదుగా అందిస్తాయి."},{"en":"On balance, community seems less a casualty of modernity than a practice we have stopped rehearsing, which implies it could be deliberately rebuilt if we chose.","native":"మొత్తానికి, సంఘం ఆధునికత బలి కంటే మనం అభ్యసించడం మానేసిన అభ్యాసంలా కనిపిస్తుంది; మనం ఎంచుకుంటే దాన్ని ఉద్దేశపూర్వకంగా తిరిగి నిర్మించవచ్చని ఇది సూచిస్తుంది."}]},"hi":{"word":"समुदाय","question":"पिछली पीढ़ियों की तुलना में बहुत से लोग समुदाय की भावना कमज़ोर क्यों महसूस करते हैं?","examples":[{"en":"While commentators blame technology for declining community, it could be argued that economic mobility and insecure work uproot people long before smartphones enter the picture.","native":"जबकि टिप्पणीकार समुदाय के क्षय के लिए तकनीक को दोष देते हैं, यह तर्क दिया जा सकता है कि स्मार्टफोन आने से काफी पहले आर्थिक गतिशीलता और असुरक्षित काम लोगों को जड़ से उखाड़ देते हैं।"},{"en":"Admittedly, online networks connect us across continents; nevertheless, they rarely provide the practical support—borrowed tools, shared childcare—that physical neighbours once routinely exchanged.","native":"यह स्वीकार करना होगा कि ऑनलाइन नेटवर्क हमें महाद्वीपों के पार जोड़ते हैं; फिर भी, वे शायद ही वह व्यावहारिक सहायता देते हैं—उधार लिए औज़ार, साझा बच्चों की देखभाल—जो पड़ोसी कभी नियमित रूप से बाँटते थे।"},{"en":"On balance, community seems less a casualty of modernity than a practice we have stopped rehearsing, which implies it could be deliberately rebuilt if we chose.","native":"कुल मिलाकर, समुदाय आधुनिकता का शिकार होने से कम और एक ऐसा अभ्यास अधिक लगता है जिसे हमने दोहराना बंद कर दिया है—इसका अर्थ है कि हम चाहें तो इसे जानबूझकर फिर से बना सकते हैं।"}]},"es":{"word":"comunidad","question":"¿Por qué muchas personas sienten un sentido de comunidad más débil que las generaciones anteriores?","examples":[{"en":"While commentators blame technology for declining community, it could be argued that economic mobility and insecure work uproot people long before smartphones enter the picture.","native":"Aunque los comentaristas culpan a la tecnología del declive comunitario, podría argumentarse que la movilidad económica y el trabajo inseguro desarraiguan a la gente mucho antes de que aparezcan los teléfonos inteligentes."},{"en":"Admittedly, online networks connect us across continents; nevertheless, they rarely provide the practical support—borrowed tools, shared childcare—that physical neighbours once routinely exchanged.","native":"Es cierto que las redes en línea nos conectan entre continentes; sin embargo, rara vez brindan el apoyo práctico —herramientas prestadas, cuidado infantil compartido— que los vecinos físicos antes intercambiaban con rutina."},{"en":"On balance, community seems less a casualty of modernity than a practice we have stopped rehearsing, which implies it could be deliberately rebuilt if we chose.","native":"En definitiva, la comunidad parece menos una víctima de la modernidad que una práctica que hemos dejado de ensayar, lo que implica que podría reconstruirse deliberadamente si así lo eligiéramos."}]},"zh":{"word":"社区","question":"为什么许多人感到的社区归属感比前几代人更弱？","examples":[{"en":"While commentators blame technology for declining community, it could be argued that economic mobility and insecure work uproot people long before smartphones enter the picture.","native":"尽管评论者把社区的衰落归咎于技术，但可以认为，早在智能手机出现之前，经济流动性和不稳定的工作就已经让人们背井离乡。"},{"en":"Admittedly, online networks connect us across continents; nevertheless, they rarely provide the practical support—borrowed tools, shared childcare—that physical neighbours once routinely exchanged.","native":"诚然，网络把我们连接到了世界各地；然而，它们很少提供实体邻里过去常常互相交换的那种实际帮助——借用的工具、分担的育儿。"},{"en":"On balance, community seems less a casualty of modernity than a practice we have stopped rehearsing, which implies it could be deliberately rebuilt if we chose.","native":"总体而言，社区与其说是现代性的牺牲品，不如说是一种我们已停止演练的实践——这意味着只要我们愿意，就可以有意识地重建它。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'loneliness', 'Why has loneliness been called an epidemic, and what can be done about it?', '{"te":{"word":"ఒంటరితనం","question":"ఒంటరితనాన్ని మహమ్మారిగా ఎందుకు పిలుస్తున్నారు, దాని గురించి ఏమి చేయవచ్చు?","examples":[{"en":"While loneliness has always existed, it could be argued that modern life has industrialised it, replacing the village square with the solitary, glowing screen.","native":"ఒంటరితనం ఎప్పటినుంచో ఉన్నప్పటికీ, ఆధునిక జీవితం దాన్ని పారిశ్రామికీకరించిందని, గ్రామ చావడిని ఒంటరి, వెలిగే తెరతో భర్తీ చేసిందని చెప్పవచ్చు."},{"en":"Admittedly, introverts recharge in solitude and should not be pathologised; nevertheless, chronic isolation measurably damages health as severely as smoking or obesity.","native":"నిజానికి అంతర్ముఖులు ఏకాంతంలో శక్తిని పుంజుకుంటారు, వారిని రోగిగా చిత్రించకూడదు; అయినప్పటికీ, దీర్ఘకాలిక ఏకాంతం పొగతాగడం లేదా ఊబకాయంలా తీవ్రంగా ఆరోగ్యాన్ని కొలవగలంతగా దెబ్బతీస్తుంది."},{"en":"On balance, loneliness seems less a personal failing than a design flaw in how we organise cities and work, which suggests collective rather than individual remedies.","native":"మొత్తానికి, ఒంటరితనం వ్యక్తిగత లోపం కంటే మనం నగరాలనూ పనినీ ఎలా నిర్వహిస్తున్నామో అందులోని రూపకల్పన లోపంలా కనిపిస్తుంది; వ్యక్తిగత కంటే సామూహిక పరిష్కారాలను ఇది సూచిస్తుంది."}]},"hi":{"word":"अकेलापन","question":"अकेलापन को महामारी क्यों कहा गया है, और इसके बारे में क्या किया जा सकता है?","examples":[{"en":"While loneliness has always existed, it could be argued that modern life has industrialised it, replacing the village square with the solitary, glowing screen.","native":"जबकि अकेलापन हमेशा से मौजूद रहा है, यह तर्क दिया जा सकता है कि आधुनिक जीवन ने इसे औद्योगीकरण दे दिया है, गाँव के चौक को एकाकी, चमकती स्क्रीन से बदल दिया है।"},{"en":"Admittedly, introverts recharge in solitude and should not be pathologised; nevertheless, chronic isolation measurably damages health as severely as smoking or obesity.","native":"यह स्वीकार करना होगा कि अंतर्मुखी एकांत में ऊर्जा पाते हैं और उन्हें रोगी नहीं ठहराना चाहिए; फिर भी, दीर्घकालिक अलगाव धूम्रपान या मोटापे जितनी गंभीरता से स्वास्थ्य को मापने योग्य नुकसान पहुँचाता है।"},{"en":"On balance, loneliness seems less a personal failing than a design flaw in how we organise cities and work, which suggests collective rather than individual remedies.","native":"कुल मिलाकर, अकेलापन व्यक्तिगत कमी से कम और शहरों तथा काम के हमारे संगठन की डिज़ाइन खामी जैसा अधिक लगता है—इससे व्यक्तिगत के बजाय सामूहिक उपायों का सुझाव मिलता है।"}]},"es":{"word":"soledad","question":"¿Por qué se ha llamado epidemia a la soledad, y qué puede hacerse al respecto?","examples":[{"en":"While loneliness has always existed, it could be argued that modern life has industrialised it, replacing the village square with the solitary, glowing screen.","native":"Aunque la soledad siempre ha existido, podría argumentarse que la vida moderna la ha industrializado, sustituyendo la plaza del pueblo por la pantalla solitaria y brillante."},{"en":"Admittedly, introverts recharge in solitude and should not be pathologised; nevertheless, chronic isolation measurably damages health as severely as smoking or obesity.","native":"Es cierto que los introvertidos se recargan en soledad y no deben patologizarse; sin embargo, el aislamiento crónico daña la salud de forma medible tan gravemente como el tabaco o la obesidad."},{"en":"On balance, loneliness seems less a personal failing than a design flaw in how we organise cities and work, which suggests collective rather than individual remedies.","native":"En definitiva, la soledad parece menos un defecto personal que un fallo de diseño en cómo organizamos las ciudades y el trabajo, lo que sugiere remedios colectivos más que individuales."}]},"zh":{"word":"孤独","question":"为什么孤独被称为一种流行病，我们能做些什么？","examples":[{"en":"While loneliness has always existed, it could be argued that modern life has industrialised it, replacing the village square with the solitary, glowing screen.","native":"尽管孤独一直存在，但可以认为，现代生活已经把它工业化了，用孤独发光的屏幕取代了村庄的广场。"},{"en":"Admittedly, introverts recharge in solitude and should not be pathologised; nevertheless, chronic isolation measurably damages health as severely as smoking or obesity.","native":"诚然，内向者在独处中恢复精力，不应被病理化；然而，长期的孤立对健康的损害可衡量地不亚于吸烟或肥胖。"},{"en":"On balance, loneliness seems less a personal failing than a design flaw in how we organise cities and work, which suggests collective rather than individual remedies.","native":"总体而言，孤独与其说是个人的失败，不如说是我们组织城市和工作方式中的设计缺陷——这提示我们需要集体而非个人的对策。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'happiness', 'Can happiness be pursued directly, or is it only ever a by-product of other pursuits?', '{"te":{"word":"ఆనందం","question":"ఆనందాన్ని ప్రత్యక్షంగా వెంబడించవచ్చా, లేక అది ఎల్లప్పుడూ ఇతర అన్వేషణల ఉపఉత్పత్తి మాత్రమేనా?","examples":[{"en":"While self-help industries promise happiness on demand, it could be argued that chasing it directly tends to make people painfully aware of its absence.","native":"స్వయం-సహాయ పరిశ్రమలు డిమాండ్ మీద ఆనందాన్ని వాగ్దానం చేసినప్పటికీ, దాన్ని ప్రత్యక్షంగా వెంటాడడం దాని లేమిని ప్రజలకు బాధాకరంగా గుర్తు చేస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, circumstances matter, since destitution reliably produces misery; nevertheless, beyond sufficiency, happiness correlates more strongly with relationships than with further gains.","native":"నిజానికి పరిస్థితులు ముఖ్యం, ఎందుకంటే దారిద్ర్యం తప్పకుండా దుఃఖాన్ని ఇస్తుంది; అయినప్పటికీ, సరిపోయినంత దాటిన తర్వాత ఆనందం మరింత లాభాల కంటే సంబంధాలతో బలంగా ముడిపడి ఉంటుంది."},{"en":"On balance, happiness seems to arrive sideways, as a consequence of engagement and purpose, rather than as a destination one can approach by staring at the horizon.","native":"మొత్తానికి, ఆనందం క్షితిజం వైపు వెంటాడగల గమ్యంగా కాకుండా, నిమగ్నత, లక్ష్యం యొక్క పర్యవసానంగా పక్కదారి నుండి వస్తుందని అనిపిస్తుంది."}]},"hi":{"word":"खुशी","question":"क्या खुशी का सीधे पीछा किया जा सकता है, या यह सदैव अन्य खोजों का उप-उत्पाद ही होती है?","examples":[{"en":"While self-help industries promise happiness on demand, it could be argued that chasing it directly tends to make people painfully aware of its absence.","native":"जबकि स्वयं-सहायता उद्योग माँग पर खुशी का वादा करते हैं, यह तर्क दिया जा सकता है कि इसका सीधा पीछा करना लोगों को इसकी अनुपस्थिति का दर्दनाक एहसास करा देता है।"},{"en":"Admittedly, circumstances matter, since destitution reliably produces misery; nevertheless, beyond sufficiency, happiness correlates more strongly with relationships than with further gains.","native":"यह स्वीकार करना होगा कि परिस्थितियाँ मायने रखती हैं, क्योंकि दरिद्रता विश्वसनीय रूप से दुख पैदा करती है; फिर भी, पर्याप्तता के आगे, खुशी आगे की प्राप्तियों से अधिक रिश्तों से दृढ़ता से जुड़ती है।"},{"en":"On balance, happiness seems to arrive sideways, as a consequence of engagement and purpose, rather than as a destination one can approach by staring at the horizon.","native":"कुल मिलाकर, खुशी तिरछे रास्ते से आती प्रतीत होती है—संलग्नता और उद्देश्य के परिणाम के रूप में—ना कि ऐसी मंज़िल जिसे क्षितिज को घूरकर पाया जा सके।"}]},"es":{"word":"felicidad","question":"¿Puede perseguirse la felicidad directamente, o es siempre un subproducto de otras búsquedas?","examples":[{"en":"While self-help industries promise happiness on demand, it could be argued that chasing it directly tends to make people painfully aware of its absence.","native":"Aunque las industrias de autoayuda prometen felicidad a demanda, podría argumentarse que perseguirla directamente tiende a hacer a las personas dolorosamente conscientes de su ausencia."},{"en":"Admittedly, circumstances matter, since destitution reliably produces misery; nevertheless, beyond sufficiency, happiness correlates more strongly with relationships than with further gains.","native":"Es cierto que las circunstancias importan, ya que la miseria produce infelicidad de forma fiable; sin embargo, más allá de la suficiencia, la felicidad se correlaciona más con las relaciones que con ganancias adicionales."},{"en":"On balance, happiness seems to arrive sideways, as a consequence of engagement and purpose, rather than as a destination one can approach by staring at the horizon.","native":"En definitiva, la felicidad parece llegar de lado, como consecuencia del compromiso y el propósito, y no como un destino al que uno se acerca mirando fijamente al horizonte."}]},"zh":{"word":"幸福","question":"幸福可以被直接追求吗，还是它永远只是其他追求的副产品？","examples":[{"en":"While self-help industries promise happiness on demand, it could be argued that chasing it directly tends to make people painfully aware of its absence.","native":"尽管自助产业承诺按需供应幸福，但可以认为，直接追逐幸福往往会让人们痛苦地意识到它的缺失。"},{"en":"Admittedly, circumstances matter, since destitution reliably produces misery; nevertheless, beyond sufficiency, happiness correlates more strongly with relationships than with further gains.","native":"诚然，环境很重要，因为赤贫确实可靠地产生痛苦；然而，在满足基本需求之后，幸福与人际关系的相关性强于与更多收获的相关性。"},{"en":"On balance, happiness seems to arrive sideways, as a consequence of engagement and purpose, rather than as a destination one can approach by staring at the horizon.","native":"总体而言，幸福似乎是从侧面降临的，是投入和目标的副产品，而不是一个可以盯着地平线直取的目的地。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'well-being', 'Should governments measure national success by well-being rather than economic growth?', '{"te":{"word":"శ్రేయస్సు","question":"ఆర్థిక వృద్ధి కంటే శ్రేయస్సు ద్వారా జాతీయ విజయాన్ని ప్రభుత్వాలు కొలవాలా?","examples":[{"en":"While GDP tracks economic activity efficiently, it could be argued that it remains stubbornly silent about whether citizens'' lives are actually improving in any meaningful sense.","native":"జీడీపీ ఆర్థిక కార్యకలాపాలను సమర్థంగా గుర్తించినప్పటికీ, పౌరుల జీవితాలు వాస్తవంగా ఏ అర్థవంతమైన పద్ధతిలోనైనా మెరుగవుతున్నాయా అనే దాని గురించి అది పట్టుతనంగా మౌనంగా ఉంటుందని చెప్పవచ్చు."},{"en":"Admittedly, well-being is slippery to define and harder to compare; nevertheless, choosing to measure it signals that people, not production, constitute the point of policy.","native":"నిజానికి శ్రేయస్సు నిర్వచించడానికి జారుగా, పోల్చడానికి కష్టంగా ఉంటుంది; అయినప్పటికీ, దాన్ని కొలవడానికి ఎంచుకోవడం విధానం లక్ష్యం ఉత్పత్తి కాదు, ప్రజలు అని సూచిస్తుంది."},{"en":"On balance, supplementing growth figures with well-being metrics seems prudent, although replacing them entirely risks trading one crude simplification for another.","native":"మొత్తానికి, వృద్ధి గణాంకాలను శ్రేయస్సు కొలమానాలతో పూరకం చేయడం వివేకంగా అనిపిస్తుంది, అయితే వాటిని పూర్తిగా భర్తీ చేయడం ఒక స్థూల సరళీకరణను మరొక దానితో మార్చుకునే ప్రమాదం ఉంది."}]},"hi":{"word":"कल्याण","question":"क्या सरकारों को आर्थिक विकास के बजाय कल्याण से राष्ट्रीय सफलता मापनी चाहिए?","examples":[{"en":"While GDP tracks economic activity efficiently, it could be argued that it remains stubbornly silent about whether citizens'' lives are actually improving in any meaningful sense.","native":"जबकि जीडीपी आर्थिक गतिविधि को कुशलता से ट्रैक करता है, यह तर्क दिया जा सकता है कि नागरिकों के जीवन वास्तव में किसी सार्थक अर्थ में सुधर रहे हैं या नहीं, इस पर वह ज़िद से चुप रहता है।"},{"en":"Admittedly, well-being is slippery to define and harder to compare; nevertheless, choosing to measure it signals that people, not production, constitute the point of policy.","native":"यह स्वीकार करना होगा कि कल्याण को परिभाषित करना फिसलन भरा और तुलना करना कठिन है; फिर भी, इसे मापना चुनना यह संकेत देता है कि नीति का उद्देश्य उत्पादन नहीं, लोग हैं।"},{"en":"On balance, supplementing growth figures with well-being metrics seems prudent, although replacing them entirely risks trading one crude simplification for another.","native":"कुल मिलाकर, विकास के आँकड़ों को कल्याण मापदंडों से पूरक करना विवेकपूर्ण लगता है, यद्यपि उन्हें पूरी तरह बदल देना एक क्रूर सरलीकरण को दूसरे से बदलने का जोखिम लाता है।"}]},"es":{"word":"bienestar","question":"¿Deberían los gobiernos medir el éxito nacional por el bienestar en lugar del crecimiento económico?","examples":[{"en":"While GDP tracks economic activity efficiently, it could be argued that it remains stubbornly silent about whether citizens'' lives are actually improving in any meaningful sense.","native":"Aunque el PIB rastrea la actividad económica eficientemente, podría argumentarse que guarda un silencio obstinado sobre si las vidas de los ciudadanos mejoran realmente en algún sentido significativo."},{"en":"Admittedly, well-being is slippery to define and harder to compare; nevertheless, choosing to measure it signals that people, not production, constitute the point of policy.","native":"Es cierto que el bienestar es resbaladizo de definir y más difícil de comparar; sin embargo, elegir medirlo señala que las personas, y no la producción, constituyen el objetivo de la política."},{"en":"On balance, supplementing growth figures with well-being metrics seems prudent, although replacing them entirely risks trading one crude simplification for another.","native":"En definitiva, complementar las cifras de crecimiento con métricas de bienestar parece prudente, aunque reemplazarlas por completo arriesga cambiar una simplificación burda por otra."}]},"zh":{"word":"福祉","question":"政府应该用福祉而非经济增长来衡量国家成就吗？","examples":[{"en":"While GDP tracks economic activity efficiently, it could be argued that it remains stubbornly silent about whether citizens'' lives are actually improving in any meaningful sense.","native":"尽管国内生产总值能高效追踪经济活动，但可以认为，它对公民的生活是否在任何有意义的层面上真正改善始终顽固地保持沉默。"},{"en":"Admittedly, well-being is slippery to define and harder to compare; nevertheless, choosing to measure it signals that people, not production, constitute the point of policy.","native":"诚然，福祉难以定义，也更难比较；然而，选择去衡量它表明人才是政策的目标，而非生产。"},{"en":"On balance, supplementing growth figures with well-being metrics seems prudent, although replacing them entirely risks trading one crude simplification for another.","native":"总体而言，用福祉指标补充增长数据似乎是审慎的，尽管完全取而代之可能会有用一种粗糙的简化替代另一种的风险。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'burnout', 'Is burnout a personal failure to cope, or a symptom of unreasonable workplace expectations?', '{"te":{"word":"బర్నౌట్","question":"బర్నౌట్ అనేది ఎదుర్కోలేని వ్యక్తిగత వైఫల్యమా, లేక అసభ్యమైన కార్యాలయ అంచనాల లక్షణమా?","examples":[{"en":"While employers frame burnout as an individual resilience problem, it could be argued that no amount of mindfulness compensates for chronically impossible workloads.","native":"యజమానులు బర్నౌట్‌ను వ్యక్తిగత స్థైర్య సమస్యగా చిత్రించినప్పటికీ, దీర్ఘకాలంగా అసాధ్యమైన పనిభారానికి ఎంత ధ్యానశక్తినైనా పరిహారం చేయలేదని చెప్పవచ్చు."},{"en":"Admittedly, personal boundaries and rest matter; nevertheless, treating a systemic issue as a private weakness conveniently absolves organisations of any obligation to change.","native":"నిజానికి వ్యక్తిగత సరిహద్దులు, విశ్రాంతి ముఖ్యం; అయినప్పటికీ, వ్యవస్థాగత సమస్యను వ్యక్తిగత బలహీనతగా చూపడం సంస్థలను మారాల్సిన బాధ్యత నుండి సౌకర్యవంతంగా విముక్తం చేస్తుంది."},{"en":"On balance, burnout seems best understood as an organisational diagnosis rather than a personal one, since resilient people break too when demands indefinitely exceed resources.","native":"మొత్తానికి, బర్నౌట్ వ్యక్తిగత నిదానం కంటే సంస్థాగత నిదానంగా అర్థం చేసుకోవడం మంచిది, ఎందుకంటే డిమాండ్లు వనరులను అనిదిష్టంగా అధిగమించినప్పుడు స్థితిస్థాపక వ్యక్తులు కూడా కుప్పకూలుతారు."}]},"hi":{"word":"बर्नआउट","question":"क्या बर्नआउट सामना करने में व्यक्तिगत असफलता है, या अनुचित कार्यस्थल अपेक्षाओं का लक्षण?","examples":[{"en":"While employers frame burnout as an individual resilience problem, it could be argued that no amount of mindfulness compensates for chronically impossible workloads.","native":"जबकि नियोक्ता बर्नआउट को व्यक्तिगत लचीलेपन की समस्या के रूप में चित्रित करते हैं, यह तर्क दिया जा सकता है कि पुरानी असंभव कामभार की भरपाई कोई भी मात्रा में माइंडफुलनेस नहीं कर सकती।"},{"en":"Admittedly, personal boundaries and rest matter; nevertheless, treating a systemic issue as a private weakness conveniently absolves organisations of any obligation to change.","native":"यह स्वीकार करना होगा कि व्यक्तिगत सीमाएँ और आराम मायने रखते हैं; फिर भी, किसी व्यवस्थागत मुद्दे को निजी कमज़ोरी मानना संगठनों को बदलने के हर दायित्व से सुविधाजनक रूप से मुक्त कर देता है।"},{"en":"On balance, burnout seems best understood as an organisational diagnosis rather than a personal one, since resilient people break too when demands indefinitely exceed resources.","native":"कुल मिलाकर, बर्नआउट को व्यक्तिगत निदान के बजाय संगठनात्मक निदान समझना बेहतर लगता है, क्योंकि जब माँगें अनिश्चित काल तक संसाधनों से अधिक होती हैं तो लचीले लोग भी टूट जाते हैं।"}]},"es":{"word":"agotamiento laboral","question":"¿Es el agotamiento laboral un fracaso personal para afrontar, o un síntoma de expectativas laborales irrazonables?","examples":[{"en":"While employers frame burnout as an individual resilience problem, it could be argued that no amount of mindfulness compensates for chronically impossible workloads.","native":"Aunque los empleadores presentan el agotamiento como un problema de resiliencia individual, podría argumentarse que ninguna cantidad de atención plena compensa cargas de trabajo crónicamente imposibles."},{"en":"Admittedly, personal boundaries and rest matter; nevertheless, treating a systemic issue as a private weakness conveniently absolves organisations of any obligation to change.","native":"Es cierto que los límites personales y el descanso importan; sin embargo, tratar un problema sistémico como una debilidad privada absuelve convenientemente a las organizaciones de cualquier obligación de cambiar."},{"en":"On balance, burnout seems best understood as an organisational diagnosis rather than a personal one, since resilient people break too when demands indefinitely exceed resources.","native":"En definitiva, el agotamiento parece entenderse mejor como un diagnóstico organizacional y no personal, ya que las personas resilientes también se quiebran cuando las exigencias superan indefinidamente los recursos."}]},"zh":{"word":"职业倦怠","question":"职业倦怠是个人应对不力的失败，还是不合理职场期望的症状？","examples":[{"en":"While employers frame burnout as an individual resilience problem, it could be argued that no amount of mindfulness compensates for chronically impossible workloads.","native":"尽管雇主把职业倦怠描述为个人韧性的问题，但可以认为，再多的正念练习也无法弥补长期不可能完成的工作量。"},{"en":"Admittedly, personal boundaries and rest matter; nevertheless, treating a systemic issue as a private weakness conveniently absolves organisations of any obligation to change.","native":"诚然，个人界限和休息很重要；然而，把一个系统性问题当作私人弱点来对待，恰好让组织免于承担任何变革的义务。"},{"en":"On balance, burnout seems best understood as an organisational diagnosis rather than a personal one, since resilient people break too when demands indefinitely exceed resources.","native":"总体而言，职业倦怠最好被理解为组织层面的诊断而非个人诊断，因为当要求无限期地超过资源时，有韧性的人也会垮掉。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'perfectionism', 'Is perfectionism a strength that drives excellence, or a weakness that prevents completion?', '{"te":{"word":"పరిపూర్ణతావాదం","question":"పరిపూర్ణతావాదం శ్రేష్ఠతను నడిపించే బలమా, లేక పూర్తయ్యేలా అడ్డుకునే బలహీనతయా?","examples":[{"en":"While perfectionists produce meticulous work, it could be argued that their standards often function less as aspirations than as elaborate excuses for procrastination.","native":"పరిపూర్ణతావాదులు నిఖర్వైన పనిని ఉత్పత్తి చేసినప్పటికీ, వారి ప్రమాణాలు తరచుగా ఆకాంక్షలుగా కంటే వాయిదాపడానికి విస్తృత సాకులుగా పనిచేస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, society benefits when surgeons and engineers sweat details; nevertheless, perfectionism applied indiscriminately to every email and errand yields exhaustion, not excellence.","native":"నిజానికి సర్జన్లు, ఇంజినీర్లు వివరాలపై శ్రమించినప్పుడు సమాజం ప్రయోజనం పొందుతుంది; అయినప్పటికీ, ప్రతి ఇమెయిల్, చిన్న పనికి వివక్ష లేకుండా పరిపూర్ణతావాదం అన్వయించడం శ్రేష్ఠతను కాదు, అలసటను ఇస్తుంది."},{"en":"On balance, the healthier ideal seems to be excellence in what matters and sufficiency elsewhere, a distinction perfectionists find genuinely painful to accept.","native":"మొత్తానికి, ముఖ్యమైన వాటిలో శ్రేష్ఠత, మిగిలిన వాటిలో సరిపోయినంత అనేది ఆరోగ్యకరమైన ఆదర్శంగా కనిపిస్తుంది; పరిపూర్ణతావాదులు అంగీకరించడానికి నిజంగా బాధపడే వ్యత్యాసం ఇది."}]},"hi":{"word":"पूर्णतावाद","question":"क्या पूर्णतावाद एक शक्ति है जो उत्कृष्टता को प्रेरित करती है, या एक कमज़ोरी है जो पूर्णता में बाधा डालती है?","examples":[{"en":"While perfectionists produce meticulous work, it could be argued that their standards often function less as aspirations than as elaborate excuses for procrastination.","native":"जबकि पूर्णतावादी सूक्ष्म कार्य करते हैं, यह तर्क दिया जा सकता है कि उनके मानदंड अक्सर आकांक्षाओं से कम और टालमटोल के विस्तृत बहाने जैसे अधिक काम करते हैं।"},{"en":"Admittedly, society benefits when surgeons and engineers sweat details; nevertheless, perfectionism applied indiscriminately to every email and errand yields exhaustion, not excellence.","native":"यह स्वीकार करना होगा कि जब सर्जन और इंजीनियर बारीकियों पर पसीना बहाते हैं तो समाज को लाभ होता है; फिर भी, हर ईमेल और छोटे काम पर अंधाधुंध पूर्णतावाद लागू करना उत्कृष्टता नहीं, थकान देता है।"},{"en":"On balance, the healthier ideal seems to be excellence in what matters and sufficiency elsewhere, a distinction perfectionists find genuinely painful to accept.","native":"कुल मिलाकर, स्वस्थ आदर्श यह लगता है: जो मायने रखता है उसमें उत्कृष्टता और बाकी जगह पर्याप्तता—यह अंतर पूर्णतावादियों के लिए स्वीकार करना सचमुच दर्दनाक है।"}]},"es":{"word":"perfeccionismo","question":"¿Es el perfeccionismo una fortaleza que impulsa la excelencia, o una debilidad que impide terminar?","examples":[{"en":"While perfectionists produce meticulous work, it could be argued that their standards often function less as aspirations than as elaborate excuses for procrastination.","native":"Aunque los perfeccionistas producen trabajo meticuloso, podría argumentarse que sus estándares a menudo funcionan menos como aspiraciones que como excusas elaboradas para procrastinar."},{"en":"Admittedly, society benefits when surgeons and engineers sweat details; nevertheless, perfectionism applied indiscriminately to every email and errand yields exhaustion, not excellence.","native":"Es cierto que la sociedad se beneficia cuando cirujanos e ingenieros cuidan los detalles; sin embargo, el perfeccionismo aplicado indiscriminadamente a cada correo y recado produce agotamiento, no excelencia."},{"en":"On balance, the healthier ideal seems to be excellence in what matters and sufficiency elsewhere, a distinction perfectionists find genuinely painful to accept.","native":"En definitiva, el ideal más sano parece ser la excelencia en lo que importa y la suficiencia en lo demás, una distinción que a los perfeccionistas les resulta genuinamente dolorosa de aceptar."}]},"zh":{"word":"完美主义","question":"完美主义是驱动卓越的力量，还是阻碍完成的弱点？","examples":[{"en":"While perfectionists produce meticulous work, it could be argued that their standards often function less as aspirations than as elaborate excuses for procrastination.","native":"尽管完美主义者能做出一丝不苟的工作，但可以认为，他们的标准往往与其说是追求，不如说是拖延的精心借口。"},{"en":"Admittedly, society benefits when surgeons and engineers sweat details; nevertheless, perfectionism applied indiscriminately to every email and errand yields exhaustion, not excellence.","native":"诚然，当外科医生和工程师精益求精时，社会从中受益；然而，把完美主义不加区分地用于每封邮件和每件琐事，带来的只是疲惫而非卓越。"},{"en":"On balance, the healthier ideal seems to be excellence in what matters and sufficiency elsewhere, a distinction perfectionists find genuinely painful to accept.","native":"总体而言，更健康的理想似乎是在重要的事情上追求卓越，在其余事情上够用即可——这一区分让完美主义者真正难以接受。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'procrastination', 'Why do intelligent people procrastinate, and is it always a bad thing?', '{"te":{"word":"వాయిదా","question":"తెలివైనవారు ఎందుకు వాయిదాలు వేస్తారు, అది ఎల్లప్పుడూ చెడు విషయమేనా?","examples":[{"en":"While procrastination is universally condemned as laziness, it could be argued that it often signals fear of failure rather than any shortage of diligence.","native":"వాయిదా వేయడాన్ని సోమరితనం అని సర్వసాధారణంగా ఖండించినప్పటికీ, అది తరచుగా శ్రమ కొరత కాదు, వైఫల్య భయాన్ని సూచిస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, chronic delay sabotages careers and relationships; nevertheless, a period of apparent idleness sometimes allows genuinely better ideas to mature quietly in the background.","native":"నిజానికి దీర్ఘకాలిక ఆలస్యం వృత్తులనూ సంబంధాలనూ ధ్వంసం చేస్తుంది; అయినప్పటికీ, కనిపించే సోమారితనపు కాలం కొన్నిసార్లు నిజంగా మెరుగైన ఆలోచనలను వెనుక నిశ్శబ్దంగా పక్వానికి అనుమతిస్తుంది."},{"en":"On balance, procrastination deserves treatment as an emotional regulation problem, not a time-management one, which explains why planners and apps so rarely cure it.","native":"మొత్తానికి, వాయిదా పడడాన్ని సమయ నిర్వహణ సమస్యగా కాకుండా భావోద్వేగ నియంత్రణ సమస్యగా పరిగణించాలి; ప్లానర్లు, యాప్‌లు దాన్ని ఎందుకు అరుదుగా నయం చేస్తాయో ఇది వివరిస్తుంది."}]},"hi":{"word":"टालमटोल","question":"बुद्धिमान लोग टालमटोल क्यों करते हैं, और क्या यह हमेशा बुरी बात है?","examples":[{"en":"While procrastination is universally condemned as laziness, it could be argued that it often signals fear of failure rather than any shortage of diligence.","native":"जबकि टालमटोल को सर्वत्र आलस्य कहकर निंदा जाती है, यह तर्क दिया जा सकता है कि यह अक्सर परिश्रम की कमी के बजाय असफलता के डर का संकेत देता है।"},{"en":"Admittedly, chronic delay sabotages careers and relationships; nevertheless, a period of apparent idleness sometimes allows genuinely better ideas to mature quietly in the background.","native":"यह स्वीकार करना होगा कि पुरानी देरी करियर और रिश्तों को नुकसान पहुँचाती है; फिर भी, दिखने वाली निष्क्रियता का दौर कभी-कभी सचमुच बेहतर विचारों को पृष्ठभूमि में चुपचाप परिपक्व होने देता है।"},{"en":"On balance, procrastination deserves treatment as an emotional regulation problem, not a time-management one, which explains why planners and apps so rarely cure it.","native":"कुल मिलाकर, टालमटोल को समय-प्रबंधन नहीं, भावनात्मक नियमन की समस्या मानना चाहिए—इसीलिए प्लानर और ऐप इसे शायद ही कभी ठीक कर पाते हैं।"}]},"es":{"word":"procrastinación","question":"¿Por qué procrastinan las personas inteligentes, y es siempre algo malo?","examples":[{"en":"While procrastination is universally condemned as laziness, it could be argued that it often signals fear of failure rather than any shortage of diligence.","native":"Aunque la procrastinación se condena universalmente como pereza, podría argumentarse que a menudo señala miedo al fracaso más que cualquier escasez de diligencia."},{"en":"Admittedly, chronic delay sabotages careers and relationships; nevertheless, a period of apparent idleness sometimes allows genuinely better ideas to mature quietly in the background.","native":"Es cierto que la demora crónica sabotea carreras y relaciones; sin embargo, un período de aparente ociosidad a veces permite que ideas genuinamente mejores maduren silenciosamente en segundo plano."},{"en":"On balance, procrastination deserves treatment as an emotional regulation problem, not a time-management one, which explains why planners and apps so rarely cure it.","native":"En definitiva, la procrastinación merece tratarse como un problema de regulación emocional, no de gestión del tiempo, lo que explica por qué las agendas y las aplicaciones rara vez la curan."}]},"zh":{"word":"拖延","question":"为什么聪明的人也会拖延，拖延总是坏事吗？","examples":[{"en":"While procrastination is universally condemned as laziness, it could be argued that it often signals fear of failure rather than any shortage of diligence.","native":"尽管拖延被普遍谴责为懒惰，但可以认为，它往往标志着对失败的恐惧，而非勤奋的缺乏。"},{"en":"Admittedly, chronic delay sabotages careers and relationships; nevertheless, a period of apparent idleness sometimes allows genuinely better ideas to mature quietly in the background.","native":"诚然，长期拖延会损害事业和人际关系；然而，一段看似闲散的时光有时能让真正更好的想法在后台悄然成熟。"},{"en":"On balance, procrastination deserves treatment as an emotional regulation problem, not a time-management one, which explains why planners and apps so rarely cure it.","native":"总体而言，拖延应当被视为情绪调节问题而非时间管理问题——这解释了为什么日程表和应用程序很少能治愈它。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'discipline', 'To what extent does discipline depend on the environments and systems people build rather than individual willpower?', '{"te":{"word":"క్రమశిక్షణ","question":"క్రమశిక్షణ వ్యక్తిగత సంకల్పబలం కంటే ప్రజలు నిర్మించుకునే పరిసరాలు మరియు వ్యవస్థలపై ఎంతవరకు ఆధారపడుతుంది?","examples":[{"en":"Treating discipline as sheer willpower overlooks how defaults, social expectations, and the design of one''s environment make some behaviours considerably easier to sustain than others.","native":"క్రమశిక్షణను కేవలం సంకల్పబలంగా చూడటం వల్ల, ముందస్తు ఎంపికలు, సామాజిక అంచనాలు మరియు వ్యక్తి పరిసరాల రూపకల్పన కొన్ని ప్రవర్తనలను ఇతర వాటికంటే కొనసాగించడం ఎంత సులభం చేస్తాయో మనం విస్మరిస్తాం."},{"en":"Personal responsibility still matters, but demanding identical self-control from people facing radically different constraints on time, health, and money mistakes unequal conditions for unequal character.","native":"వ్యక్తిగత బాధ్యత ఇప్పటికీ ముఖ్యం, కానీ సమయం, ఆరోగ్యం మరియు డబ్బుపై పూర్తిగా భిన్నమైన పరిమితులను ఎదుర్కొనే ప్రజల నుంచి ఒకే స్థాయి స్వీయ నియంత్రణను కోరడం అసమాన పరిస్థితులను అసమాన స్వభావంగా పొరబడటమే."},{"en":"Durable discipline may therefore depend on designing systems that reduce repeated temptation while preserving enough flexibility to recover from inevitable lapses.","native":"అందువల్ల స్థిరమైన క్రమశిక్షణ పదేపదే ఎదురయ్యే ప్రలోభాలను తగ్గించే వ్యవస్థలను రూపొందించడంపై ఆధారపడవచ్చు; అదే సమయంలో అనివార్యమైన తప్పిదాల నుంచి కోలుకునేందుకు తగిన సౌలభ్యాన్ని ఉంచాలి."}]},"hi":{"word":"अनुशासन","question":"अनुशासन व्यक्तिगत इच्छाशक्ति के बजाय लोगों द्वारा बनाए गए परिवेश और व्यवस्थाओं पर किस हद तक निर्भर करता है?","examples":[{"en":"Treating discipline as sheer willpower overlooks how defaults, social expectations, and the design of one''s environment make some behaviours considerably easier to sustain than others.","native":"अनुशासन को केवल इच्छाशक्ति मानना इस बात की अनदेखी करता है कि पूर्वनिर्धारित विकल्प, सामाजिक अपेक्षाएँ और व्यक्ति के परिवेश की बनावट कुछ व्यवहारों को दूसरों की तुलना में बनाए रखना कितना आसान कर देती हैं।"},{"en":"Personal responsibility still matters, but demanding identical self-control from people facing radically different constraints on time, health, and money mistakes unequal conditions for unequal character.","native":"व्यक्तिगत जिम्मेदारी अब भी मायने रखती है, लेकिन समय, स्वास्थ्य और धन की बिल्कुल अलग सीमाओं का सामना कर रहे लोगों से समान आत्म-नियंत्रण माँगना असमान परिस्थितियों को असमान चरित्र समझने की भूल है।"},{"en":"Durable discipline may therefore depend on designing systems that reduce repeated temptation while preserving enough flexibility to recover from inevitable lapses.","native":"इसलिए टिकाऊ अनुशासन ऐसी व्यवस्थाएँ बनाने पर निर्भर हो सकता है जो बार-बार के प्रलोभन घटाएँ और साथ ही अपरिहार्य चूकों से उबरने के लिए पर्याप्त लचीलापन बनाए रखें।"}]},"es":{"word":"disciplina","question":"¿Hasta qué punto depende la disciplina de los entornos y sistemas que construyen las personas, más que de la fuerza de voluntad individual?","examples":[{"en":"Treating discipline as sheer willpower overlooks how defaults, social expectations, and the design of one''s environment make some behaviours considerably easier to sustain than others.","native":"Tratar la disciplina como mera fuerza de voluntad pasa por alto cómo las opciones predeterminadas, las expectativas sociales y el diseño del propio entorno hacen que unas conductas sean mucho más fáciles de mantener que otras."},{"en":"Personal responsibility still matters, but demanding identical self-control from people facing radically different constraints on time, health, and money mistakes unequal conditions for unequal character.","native":"La responsabilidad personal sigue importando, pero exigir idéntico autocontrol a quienes afrontan limitaciones radicalmente distintas de tiempo, salud y dinero confunde condiciones desiguales con un carácter desigual."},{"en":"Durable discipline may therefore depend on designing systems that reduce repeated temptation while preserving enough flexibility to recover from inevitable lapses.","native":"Por tanto, una disciplina duradera puede depender de diseñar sistemas que reduzcan la tentación reiterada y conserven suficiente flexibilidad para recuperarse de fallos inevitables."}]},"zh":{"word":"自律","question":"自律在多大程度上取决于人们营造的环境与制度，而非个人意志力？","examples":[{"en":"Treating discipline as sheer willpower overlooks how defaults, social expectations, and the design of one''s environment make some behaviours considerably easier to sustain than others.","native":"把自律仅仅视为意志力，会忽略默认选项、社会期待和个人环境的设计如何让某些行为比其他行为更容易长期维持。"},{"en":"Personal responsibility still matters, but demanding identical self-control from people facing radically different constraints on time, health, and money mistakes unequal conditions for unequal character.","native":"个人责任仍然重要，但要求在时间、健康和经济方面承受截然不同限制的人表现出同等自制力，是把条件不平等误判为品格不平等。"},{"en":"Durable discipline may therefore depend on designing systems that reduce repeated temptation while preserving enough flexibility to recover from inevitable lapses.","native":"因此，持久的自律或许依赖于设计减少反复诱惑的制度，同时保留足够弹性，以便从不可避免的失误中恢复。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'curiosity', 'Does curiosity decline with age, and should schools do more to protect it?', '{"te":{"word":"జిజ్ఞాస","question":"వయసుతో పాటు జిజ్ఞాస తగ్గుతుందా, దాన్ని కాపాడడానికి పాఠశాలలు మరింత చేయాలా?","examples":[{"en":"While children interrogate the world relentlessly, it could be argued that schooling, with its standardised answers, gradually trains the questioning instinct out of them.","native":"పిల్లలు ప్రపంచాన్ని అహర్నిశం ప్రశ్నిస్తున్నప్పటికీ, ప్రామాణిక సమాధానాలతో కూడిన పాఠశాల విద్య ప్రశ్నించే స్వభావాన్ని వారి నుండి క్రమంగా తీసేస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, curiosity can be inconvenient and even dangerous; nevertheless, every scientific advance and most moral progress began with someone refusing to stop asking why.","native":"నిజానికి జిజ్ఞాస అసౌకర్యంగా, అపాయకరంగానూ కావచ్చు; అయినప్పటికీ, ప్రతి శాస్త్రీయ పురోగతి, చాలా నైతిక పురోగతి ఎందుకు అని అడగడం ఆపడానికి నిరాకరించిన ఎవరితోనో ప్రారంభమైంది."},{"en":"On balance, curiosity seems less a childhood trait that fades than a muscle adults neglect, although reviving it requires tolerating uncertainty more gracefully than most institutions do.","native":"మొత్తానికి, జిజ్ఞాస మసకబారే బాల్య లక్షణం కంటే పెద్దలు నిర్లక్ష్యం చేసే కండరంలా కనిపిస్తుంది, అయితే దాన్ని పునరుజ్జీవించడానికి చాలా సంస్థలు చేసే దానికంటే అనిశ్చితిని మరింత సొగసుగా సహించాలి."}]},"hi":{"word":"जिज्ञासा","question":"क्या उम्र के साथ जिज्ञासा घटती है, और क्या विद्यालयों को इसे बचाने के लिए और अधिक करना चाहिए?","examples":[{"en":"While children interrogate the world relentlessly, it could be argued that schooling, with its standardised answers, gradually trains the questioning instinct out of them.","native":"जबकि बच्चे दुनिया से अथक सवाल करते हैं, यह तर्क दिया जा सकता है कि मानकीकृत उत्तरों वाली स्कूली शिक्षा धीरे-धीरे पूछने की प्रवृत्ति को उनसे बाहर निकाल देती है।"},{"en":"Admittedly, curiosity can be inconvenient and even dangerous; nevertheless, every scientific advance and most moral progress began with someone refusing to stop asking why.","native":"यह स्वीकार करना होगा कि जिज्ञासा असुविधाजनक और यहाँ तक कि खतरनाक हो सकती है; फिर भी, हर वैज्ञानिक प्रगति और अधिकांश नैतिक प्रगति किसी ऐसे व्यक्ति से शुरू हुई जिसने क्यों पूछना बंद करने से इनकार कर दिया।"},{"en":"On balance, curiosity seems less a childhood trait that fades than a muscle adults neglect, although reviving it requires tolerating uncertainty more gracefully than most institutions do.","native":"कुल मिलाकर, जिज्ञासा फीका पड़ने वाली बचपन की विशेषता से कम और वयस्कों की उपेक्षित माँसपेशी जैसी अधिक लगती है, यद्यपि इसे पुनर्जीवित करने के लिए अनिश्चितता को अधिकांश संस्थाओं से बेहतर सहने की ज़रूरत है।"}]},"es":{"word":"curiosidad","question":"¿Disminuye la curiosidad con la edad, y deberían las escuelas hacer más por protegerla?","examples":[{"en":"While children interrogate the world relentlessly, it could be argued that schooling, with its standardised answers, gradually trains the questioning instinct out of them.","native":"Aunque los niños interrogan el mundo sin descanso, podría argumentarse que la escolarización, con sus respuestas estandarizadas, les va extirpando gradualmente el instinto de preguntar."},{"en":"Admittedly, curiosity can be inconvenient and even dangerous; nevertheless, every scientific advance and most moral progress began with someone refusing to stop asking why.","native":"Es cierto que la curiosidad puede ser incómoda e incluso peligrosa; sin embargo, todo avance científico y la mayoría del progreso moral comenzaron con alguien que se negó a dejar de preguntar por qué."},{"en":"On balance, curiosity seems less a childhood trait that fades than a muscle adults neglect, although reviving it requires tolerating uncertainty more gracefully than most institutions do.","native":"En definitiva, la curiosidad parece menos un rasgo infantil que se desvanece que un músculo que los adultos descuidan, aunque reavivarla exige tolerar la incertidumbre con más gracia de lo que lo hacen la mayoría de las instituciones."}]},"zh":{"word":"好奇心","question":"好奇心会随着年龄增长而减退吗，学校是否应当为保护它做得更多？","examples":[{"en":"While children interrogate the world relentlessly, it could be argued that schooling, with its standardised answers, gradually trains the questioning instinct out of them.","native":"尽管孩子们不厌其烦地追问这个世界，但可以认为，标准化答案的学校教育会逐渐把他们提问的本能训练掉。"},{"en":"Admittedly, curiosity can be inconvenient and even dangerous; nevertheless, every scientific advance and most moral progress began with someone refusing to stop asking why.","native":"诚然，好奇心可能带来不便甚至危险；然而，每一项科学进步和大多数道德进步，都始于某个拒绝停止问“为什么”的人。"},{"en":"On balance, curiosity seems less a childhood trait that fades than a muscle adults neglect, although reviving it requires tolerating uncertainty more gracefully than most institutions do.","native":"总体而言，好奇心与其说是一种会消退的童年特质，不如说是成年人疏于锻炼的肌肉——尽管重新激活它需要比大多数机构更优雅地容忍不确定性。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'wisdom', 'How does wisdom differ from intelligence, and can it be taught?', '{"te":{"word":"జ్ఞానం","question":"జ్ఞానం తెలివితేటలకు ఎలా భిన్నం, దాన్ని నేర్పవచ్చా?","examples":[{"en":"While intelligence solves problems quickly, it could be argued that wisdom consists largely in knowing which problems deserve solving and which battles deserve declining.","native":"తెలివితేటలు సమస్యలను త్వరగా పరిష్కరించినప్పటికీ, ఏ సమస్యలు పరిష్కారానికి అర్హమో, ఏ పోరాటాలు వదిలివేయాలో తెలుసుకోవడమే జ్ఞానం అని పెద్దగా చెప్పవచ్చు."},{"en":"Admittedly, cleverness wins examinations and promotions; nevertheless, the most catastrophic decisions in history were frequently made by highly intelligent people lacking perspective.","native":"నిజానికి తెలివి పరీక్షలు, పదోన్నతులు గెలిపిస్తుంది; అయినప్పటికీ, చరిత్రలో అత్యంత వినాశకరమైన నిర్ణయాలు తరచుగా దృక్కోణం లేని అతి తెలివైన వ్యక్తులే తీసుకున్నాయి."},{"en":"On balance, wisdom seems to accumulate through reflected experience rather than instruction, which perhaps explains why it remains stubbornly resistant to being taught.","native":"మొత్తానికి, జ్ఞానం బోధన కంటే ప్రతిబింబించిన అనుభవం ద్వారా పేరుకుపోతుందని అనిపిస్తుంది; అది నేర్పడానికి పట్టుతనంగా ఎదుర్కొంటూనే ఉండటానికి బహుశా ఇది కారణం."}]},"hi":{"word":"प्रज्ञा","question":"प्रज्ञा बुद्धि से किस तरह भिन्न है, और क्या इसे सिखाया जा सकता है?","examples":[{"en":"While intelligence solves problems quickly, it could be argued that wisdom consists largely in knowing which problems deserve solving and which battles deserve declining.","native":"जबकि बुद्धि समस्याओं को जल्दी सुलझाती है, यह तर्क दिया जा सकता है कि प्रज्ञा काफी हद तक यह जानने में निहित है कि कौन सी समस्याएँ सुलझाने लायक हैं और कौन सी लड़ाइयाँ छोड़ने लायक।"},{"en":"Admittedly, cleverness wins examinations and promotions; nevertheless, the most catastrophic decisions in history were frequently made by highly intelligent people lacking perspective.","native":"यह स्वीकार करना होगा कि चतुराई परीक्षाएँ और पदोन्नतियाँ दिलाती है; फिर भी, इतिहास के सबसे विनाशकारी फैसले अक्सर अत्यंत बुद्धिमान परंतु दूरदृष्टि-विहीन लोगों ने ही लिए।"},{"en":"On balance, wisdom seems to accumulate through reflected experience rather than instruction, which perhaps explains why it remains stubbornly resistant to being taught.","native":"कुल मिलाकर, प्रज्ञा निर्देश के बजाय चिंतित अनुभव से जमा होती प्रतीत होती है—शायद यही बताता है कि यह सिखाए जाने का ज़िद से विरोध क्यों करती रहती है।"}]},"es":{"word":"sabiduría","question":"¿En qué se diferencia la sabiduría de la inteligencia, y puede enseñarse?","examples":[{"en":"While intelligence solves problems quickly, it could be argued that wisdom consists largely in knowing which problems deserve solving and which battles deserve declining.","native":"Aunque la inteligencia resuelve problemas con rapidez, podría argumentarse que la sabiduría consiste en gran parte en saber qué problemas merecen resolverse y qué batallas merecen declinarse."},{"en":"Admittedly, cleverness wins examinations and promotions; nevertheless, the most catastrophic decisions in history were frequently made by highly intelligent people lacking perspective.","native":"Es cierto que el ingenio gana exámenes y ascensos; sin embargo, las decisiones más catastróficas de la historia fueron tomadas con frecuencia por personas muy inteligentes sin perspectiva."},{"en":"On balance, wisdom seems to accumulate through reflected experience rather than instruction, which perhaps explains why it remains stubbornly resistant to being taught.","native":"En definitiva, la sabiduría parece acumularse mediante la experiencia reflexionada más que por instrucción, lo que quizá explique por qué sigue siendo obstinadamente resistente a ser enseñada."}]},"zh":{"word":"智慧","question":"智慧与智力有何不同，它可以被教授吗？","examples":[{"en":"While intelligence solves problems quickly, it could be argued that wisdom consists largely in knowing which problems deserve solving and which battles deserve declining.","native":"尽管智力能快速解决问题，但可以认为，智慧很大程度上在于知道哪些问题值得解决、哪些争斗值得放弃。"},{"en":"Admittedly, cleverness wins examinations and promotions; nevertheless, the most catastrophic decisions in history were frequently made by highly intelligent people lacking perspective.","native":"诚然，聪明能赢得考试和晋升；然而，历史上最具灾难性的决策，往往是由极聪明却缺乏格局的人做出的。"},{"en":"On balance, wisdom seems to accumulate through reflected experience rather than instruction, which perhaps explains why it remains stubbornly resistant to being taught.","native":"总体而言，智慧似乎是通过反思过的经验而非教导积累起来的——这或许解释了为什么它始终顽固地抗拒被教授。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'knowledge', 'Is having access to unlimited information the same as having knowledge?', '{"te":{"word":"విజ్ఞానం","question":"అపరిమిత సమాచారానికి అందుబాటు ఉండడం విజ్ఞానం ఉండడంతో సమానమా?","examples":[{"en":"While the internet grants instant access to nearly all recorded information, it could be argued that information without understanding resembles a library read by no one.","native":"ఇంటర్నెట్ దాదాపు అన్ని నమోదైన సమాచారానికి తక్షణ అందుబాటును ఇచ్చినప్పటికీ, అవగాహన లేని సమాచారం ఎవరూ చదవని గ్రంథాలయంలాంటిదని చెప్పవచ్చు."},{"en":"Admittedly, lookup tools free memory for higher thinking; nevertheless, effortless retrieval appears to erode the slow, effortful learning through which deep knowledge actually forms.","native":"నిజానికి సెర్చ్ సాధనాలు ఉన్నత ఆలోచన కోసం జ్ఞాపకశక్తిని విడుదల చేస్తాయి; అయినప్పటికీ, శ్రమరహిత పునఃప్రాప్తి లోతైన విజ్ఞానం వాస్తవంగా ఏర్పడే నెమ్మదైన, శ్రమతో కూడిన అభ్యాసాన్ని తగ్గిస్తుందని అనిపిస్తుంది."},{"en":"On balance, knowledge seems to involve judgment about what matters and why, a capacity no search engine has yet managed to outsource convincingly.","native":"మొత్తానికి, విజ్ఞానం ఏది ముఖ్యమో, ఎందుకో గురించిన విచారణను కలిగి ఉంటుందని అనిపిస్తుంది; ఏ సెర్చ్ ఇంజిన్ ఇంకా నమ్మదగినంతగా బహిష్కరించలేని సామర్థ్యం ఇది."}]},"hi":{"word":"ज्ञान","question":"क्या असीमित जानकारी तक पहुँच होना ज्ञान होने के समान है?","examples":[{"en":"While the internet grants instant access to nearly all recorded information, it could be argued that information without understanding resembles a library read by no one.","native":"जबकि इंटरनेट लगभग सारी दर्ज जानकारी तक तुरंत पहुँच देता है, यह तर्क दिया जा सकता है कि बिना समझ की जानकारी ऐसे पुस्तकालय जैसी है जिसे कोई नहीं पढ़ता।"},{"en":"Admittedly, lookup tools free memory for higher thinking; nevertheless, effortless retrieval appears to erode the slow, effortful learning through which deep knowledge actually forms.","native":"यह स्वीकार करना होगा कि खोज उपकरण उच्च चिंतन के लिए स्मृति मुक्त करते हैं; फिर भी, सहज पुनर्प्राप्ति उस धीमी, प्रयासपूर्ण सीखने की प्रक्रिया को क्षय करती प्रतीत होती है जिससे गहरा ज्ञान वास्तव में बनता है।"},{"en":"On balance, knowledge seems to involve judgment about what matters and why, a capacity no search engine has yet managed to outsource convincingly.","native":"कुल मिलाकर, ज्ञान में यह विवेक शामिल लगता है कि क्या मायने रखता है और क्यों—यह क्षमता अब तक कोई खोज इंजन विश्वसनीय रूप से बाहर नहीं सौंप पाया है।"}]},"es":{"word":"conocimiento","question":"¿Es tener acceso a información ilimitada lo mismo que tener conocimiento?","examples":[{"en":"While the internet grants instant access to nearly all recorded information, it could be argued that information without understanding resembles a library read by no one.","native":"Aunque internet otorga acceso instantáneo a casi toda la información registrada, podría argumentarse que la información sin comprensión se parece a una biblioteca que nadie lee."},{"en":"Admittedly, lookup tools free memory for higher thinking; nevertheless, effortless retrieval appears to erode the slow, effortful learning through which deep knowledge actually forms.","native":"Es cierto que las herramientas de búsqueda liberan memoria para el pensamiento superior; sin embargo, la recuperación sin esfuerzo parece erosionar el aprendizaje lento y esforzado mediante el cual se forma realmente el conocimiento profundo."},{"en":"On balance, knowledge seems to involve judgment about what matters and why, a capacity no search engine has yet managed to outsource convincingly.","native":"En definitiva, el conocimiento parece implicar juicio sobre qué importa y por qué, una capacidad que ningún buscador ha logrado aún subcontratar de forma convincente."}]},"zh":{"word":"知识","question":"能够获取无限的信息等同于拥有知识吗？","examples":[{"en":"While the internet grants instant access to nearly all recorded information, it could be argued that information without understanding resembles a library read by no one.","native":"尽管互联网让人们能即时获取几乎所有已记录的信息，但可以认为，没有理解的信息就像一座无人阅读的图书馆。"},{"en":"Admittedly, lookup tools free memory for higher thinking; nevertheless, effortless retrieval appears to erode the slow, effortful learning through which deep knowledge actually forms.","native":"诚然，搜索工具解放了记忆以便进行更高层次的思考；然而，毫不费力的检索似乎侵蚀了真正形成深层知识的那种缓慢而费力的学习。"},{"en":"On balance, knowledge seems to involve judgment about what matters and why, a capacity no search engine has yet managed to outsource convincingly.","native":"总体而言，知识似乎包含对什么重要以及为何重要的判断力——这是任何搜索引擎迄今都无法令人信服地外包的能力。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'honesty', 'Is complete honesty always the best policy, or are small lies sometimes necessary?', '{"te":{"word":"నిజాయితీ","question":"పూర్తి నిజాయితీ ఎల్లప్పుడూ ఉత్తమ విధానమేనా, లేక చిన్న అబద్ధాలు కొన్నిసార్లు అవసరమా?","examples":[{"en":"While honesty underpins every durable relationship, it could be argued that unfiltered truth-telling sometimes serves the speaker''s conscience more than the listener''s welfare.","native":"నిజాయితీ ప్రతి శాశ్వత సంబంధానికి పునాది అయినప్పటికీ, వడపోత లేని నిజం చెప్పడం కొన్నిసార్లు వినేవారి శ్రేయస్సు కంటే చెప్పేవారి మనస్సాక్షికే ఎక్కువగా సేవ చేస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, tactful omissions can be kind; nevertheless, habitual small dishonesties corrode trust quietly, since people forgive painful truths far more readily than discovered deceptions.","native":"నిజానికి మర్యాదపూర్వక మినహాయింపులు దయగా ఉండవచ్చు; అయినప్పటికీ, అలవాటుపడిన చిన్న అసత్యాలు నమ్మకాన్ని నిశ్శబ్దంగా తరిగివేస్తాయి, ఎందుకంటే ప్రజలు బయటపడిన మోసాల కంటే బాధాకరమైన నిజాలను చాలా త్వరగా క్షమిస్తారు."},{"en":"On balance, honesty seems to require courage delivered with tact, a combination considerably rarer than either brutal candour or comfortable silence.","native":"మొత్తానికి, నిజాయితీ మర్యాదతో కూడిన ధైర్యాన్ని కోరుతుందని అనిపిస్తుంది; ముద్దోష్టమైన స్పష్టత లేదా సౌకర్యవంతమైన మౌనం కంటే ఈ కలయిక చాలా అరుదు."}]},"hi":{"word":"ईमानदारी","question":"क्या पूर्ण ईमानदारी हमेशा सबसे अच्छी नीति है, या छोटे झूठ कभी-कभी आवश्यक हैं?","examples":[{"en":"While honesty underpins every durable relationship, it could be argued that unfiltered truth-telling sometimes serves the speaker''s conscience more than the listener''s welfare.","native":"जबकि ईमानदारी हर टिकाऊ रिश्ते की बुनियाद है, यह तर्क दिया जा सकता है कि बिना छाँटी सच्चाई कभी-कभी सुनने वाले की भलाई से ज़्यादा बोलने वाले की अंतरात्मा की सेवा करती है।"},{"en":"Admittedly, tactful omissions can be kind; nevertheless, habitual small dishonesties corrode trust quietly, since people forgive painful truths far more readily than discovered deceptions.","native":"यह स्वीकार करना होगा कि व्यवहारकुशल चुप्पियाँ दयालु हो सकती हैं; फिर भी, आदतन छोटी बेईमानियाँ विश्वास को चुपचाप क्षय करती हैं, क्योंकि लोग पकड़े गए धोखों की तुलना में दर्दनाक सच्चाई कहीं जल्दी माफ़ कर देते हैं।"},{"en":"On balance, honesty seems to require courage delivered with tact, a combination considerably rarer than either brutal candour or comfortable silence.","native":"कुल मिलाकर, ईमानदारी व्यवहार के साथ दिया गया साहस माँगती प्रतीत होती है—यह मेल क्रूर स्पष्टवादिता या सुविधाजनक मौन दोनों से काफी दुर्लभ है।"}]},"es":{"word":"honestidad","question":"¿Es la honestidad completa siempre la mejor política, o son a veces necesarias las pequeñas mentiras?","examples":[{"en":"While honesty underpins every durable relationship, it could be argued that unfiltered truth-telling sometimes serves the speaker''s conscience more than the listener''s welfare.","native":"Aunque la honestidad sustenta toda relación duradera, podría argumentarse que decir la verdad sin filtros a veces sirve más a la conciencia del que habla que al bienestar del que escucha."},{"en":"Admittedly, tactful omissions can be kind; nevertheless, habitual small dishonesties corrode trust quietly, since people forgive painful truths far more readily than discovered deceptions.","native":"Es cierto que las omisiones corteses pueden ser bondadosas; sin embargo, las pequeñas deshonestidades habituales erosionan la confianza en silencio, ya que la gente perdona verdades dolorosas mucho antes que engaños descubiertos."},{"en":"On balance, honesty seems to require courage delivered with tact, a combination considerably rarer than either brutal candour or comfortable silence.","native":"En definitiva, la honestidad parece exigir coraje entregado con tacto, una combinación considerablemente más rara que la franqueza brutal o el silencio cómodo."}]},"zh":{"word":"诚实","question":"完全诚实永远是上策吗，还是小小的谎言有时是必要的？","examples":[{"en":"While honesty underpins every durable relationship, it could be argued that unfiltered truth-telling sometimes serves the speaker''s conscience more than the listener''s welfare.","native":"尽管诚实是每段持久关系的基石，但可以认为，不加过滤的真话有时更多地服务于说话者的良心，而非倾听者的福祉。"},{"en":"Admittedly, tactful omissions can be kind; nevertheless, habitual small dishonesties corrode trust quietly, since people forgive painful truths far more readily than discovered deceptions.","native":"诚然，得体的隐瞒可能是善意的；然而，习惯性的小谎言会悄悄侵蚀信任，因为人们原谅痛苦的真话远比原谅被揭穿的欺骗要快。"},{"en":"On balance, honesty seems to require courage delivered with tact, a combination considerably rarer than either brutal candour or comfortable silence.","native":"总体而言，诚实似乎需要以圆融方式表达的勇气——这种结合比残酷的坦率或舒适的沉默都要罕见得多。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'integrity', 'What does it mean to have integrity when no one is watching?', '{"te":{"word":"సమగ్రత","question":"ఎవరూ చూడనప్పుడు సమగ్రత ఉండడం అంటే ఏమిటి?","examples":[{"en":"While reputation depends on what others observe, it could be argued that integrity is precisely what remains when observation, incentives, and consequences are all removed.","native":"కీర్తి ఇతరులు గమనించే దానిపై ఆధారపడినప్పటికీ, పర్యవేక్షణ, ప్రోత్సాహకాలు, పరిణామాలు అన్నీ తీసేసినప్పుడు మిగిలేదే సమగ్రత అని చెప్పవచ్చు."},{"en":"Admittedly, few people withstand every temptation flawlessly; nevertheless, character reveals itself less in dramatic choices than in small, unwitnessed decisions repeated daily.","native":"నిజానికి ప్రతి ప్రలోభాన్ని లోపం లేకుండా తట్టుకునేవారు తక్కువ; అయినప్పటికీ, స్వభావం నాటకీయ ఎంపికల్లో కంటే రోజూ పునరావృతమయ్యే చిన్న, ఎవరూ చూడని నిర్ణయాల్లోనే బహిర్గతమవుతుంది."},{"en":"On balance, integrity seems less a fixed possession than a practice, sustained by habits so consistent they eventually become indistinguishable from identity itself.","native":"మొత్తానికి, సమగ్రత స్థిరమైన ఆస్తి కంటే ఒక అభ్యాసంలా కనిపిస్తుంది; చివరికి గుర్తింపుతోనే వేరు చేయలేనంత స్థిరమైన అలవాట్లు దాన్ని నిలుపుతాయి."}]},"hi":{"word":"सत्यनिष्ठा","question":"जब कोई देख नहीं रहा हो तो सत्यनिष्ठा होने का क्या अर्थ है?","examples":[{"en":"While reputation depends on what others observe, it could be argued that integrity is precisely what remains when observation, incentives, and consequences are all removed.","native":"जबकि प्रतिष्ठा इस पर निर्भर करती है कि दूसरे क्या देखते हैं, यह तर्क दिया जा सकता है कि सत्यनिष्ठा ठीक वही है जो निगरानी, प्रोत्साहन और परिणाम—सब हटा दिए जाने पर बचती है।"},{"en":"Admittedly, few people withstand every temptation flawlessly; nevertheless, character reveals itself less in dramatic choices than in small, unwitnessed decisions repeated daily.","native":"यह स्वीकार करना होगा कि बहुत कम लोग हर प्रलोभन का निर्दोष सामना करते हैं; फिर भी, चरित्र नाटकीय चुनावों से कम और रोज़ दोहराए गए छोटे, अदेखे फैसलों में अधिक प्रकट होता है।"},{"en":"On balance, integrity seems less a fixed possession than a practice, sustained by habits so consistent they eventually become indistinguishable from identity itself.","native":"कुल मिलाकर, सत्यनिष्ठा कोई स्थिर संपत्ति से कम और एक अभ्यास जैसी अधिक लगती है, जिसे इतनी सुसंगत आदतें कायम रखती हैं कि वे अंततः पहचान से अलग नहीं रहतीं।"}]},"es":{"word":"integridad","question":"¿Qué significa tener integridad cuando nadie está mirando?","examples":[{"en":"While reputation depends on what others observe, it could be argued that integrity is precisely what remains when observation, incentives, and consequences are all removed.","native":"Aunque la reputación depende de lo que otros observan, podría argumentarse que la integridad es precisamente lo que queda cuando se eliminan la observación, los incentivos y las consecuencias."},{"en":"Admittedly, few people withstand every temptation flawlessly; nevertheless, character reveals itself less in dramatic choices than in small, unwitnessed decisions repeated daily.","native":"Es cierto que pocas personas resisten toda tentación sin fallas; sin embargo, el carácter se revela menos en decisiones dramáticas que en pequeñas decisiones sin testigos repetidas a diario."},{"en":"On balance, integrity seems less a fixed possession than a practice, sustained by habits so consistent they eventually become indistinguishable from identity itself.","native":"En definitiva, la integridad parece menos una posesión fija que una práctica, sostenida por hábitos tan consistentes que acaban siendo indistinguibles de la propia identidad."}]},"zh":{"word":"正直","question":"在无人注视的时候，坚守正直意味着什么？","examples":[{"en":"While reputation depends on what others observe, it could be argued that integrity is precisely what remains when observation, incentives, and consequences are all removed.","native":"尽管声誉取决于他人所观察到的，但可以认为，正直恰恰是在观察、激励和后果都被移除之后仍然留存的东西。"},{"en":"Admittedly, few people withstand every temptation flawlessly; nevertheless, character reveals itself less in dramatic choices than in small, unwitnessed decisions repeated daily.","native":"诚然，很少有人能毫无瑕疵地抵挡每一种诱惑；然而，品格更多地体现在每天重复的那些无人见证的小决定中，而非戏剧性的抉择里。"},{"en":"On balance, integrity seems less a fixed possession than a practice, sustained by habits so consistent they eventually become indistinguishable from identity itself.","native":"总体而言，正直似乎不是一种固定的所有物，而是一种实践——由高度一致的习惯维系，以至于它们最终与身份本身难以区分。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'loyalty', 'Is loyalty an unconditional virtue, or should it depend on how others behave?', '{"te":{"word":"విశ్వాసం","question":"విశ్వాసం నిష్ఠారహిత సద్గుణమా, లేక ఇతరుల ప్రవర్తనపై ఆధారపడాలా?","examples":[{"en":"While loyalty binds families, friendships, and nations together, it could be argued that unconditional allegiance has excused complicity in countless historical wrongs.","native":"విశ్వాసం కుటుంబాలనూ, స్నేహాలనూ, దేశాలనూ కలిపి ఉంచినప్పటికీ, నిష్ఠారహిత అనుగత్యం అసంఖ్యాక చారిత్రక తప్పుల్లో భాగస్వామ్యానికి సాకు ఇచ్చిందని చెప్పవచ్చు."},{"en":"Admittedly, abandoning commitments at the first disappointment is hardly admirable; nevertheless, loyalty that survives betrayal of shared values ceases to be a virtue at all.","native":"నిజానికి మొదటి నిరాశ వద్దే వాగ్దానాలను వదిలివేయడం ప్రశంసనీయం కాదు; అయినప్పటికీ, ఉమ్మడి విలువల ద్రోహం తర్వాతనూ మిగిలే విశ్వాసం ఇక సద్గుణం కాదు."},{"en":"On balance, loyalty seems to deserve its high reputation only when it remains conditional on decency, a qualification its most fervent defenders rarely mention.","native":"మొత్తానికి, విశ్వాసం మర్యాదపై షరతుగా ఉన్నప్పుడే తన ఉన్నత ఖ్యాతికి అర్హమవుతుందని అనిపిస్తుంది; దాని అత్యంత ఉత్సాహవంతమైన సమర్థకులు అరుదుగా ప్రస్తావించే అర్హత ఇది."}]},"hi":{"word":"निष्ठा","question":"क्या निष्ठा एक बिना शर्त गुण है, या इसे दूसरों के व्यवहार पर निर्भर होना चाहिए?","examples":[{"en":"While loyalty binds families, friendships, and nations together, it could be argued that unconditional allegiance has excused complicity in countless historical wrongs.","native":"जबकि निष्ठा परिवारों, दोस्तियों और राष्ट्रों को बाँधती है, यह तर्क दिया जा सकता है कि बिना शर्त वफ़ादारी ने अनगिनत ऐतिहासिक दुष्कृत्यों में भागीदारी का बहाना दिया है।"},{"en":"Admittedly, abandoning commitments at the first disappointment is hardly admirable; nevertheless, loyalty that survives betrayal of shared values ceases to be a virtue at all.","native":"यह स्वीकार करना होगा कि पहली निराशा पर ही प्रतिबद्धताएँ छोड़ देना सराहनीय नहीं है; फिर भी, साझा मूल्यों के विश्वासघात के बाद भी टिकी निष्ठा गुण रहना बंद कर देती है।"},{"en":"On balance, loyalty seems to deserve its high reputation only when it remains conditional on decency, a qualification its most fervent defenders rarely mention.","native":"कुल मिलाकर, निष्ठा अपनी ऊँची प्रतिष्ठा की हक़दार तभी लगती है जब वह सभ्यता पर सशर्त रहे—यह शर्त इसके सबसे उत्साही समर्थक शायद ही कभी बताते हैं।"}]},"es":{"word":"lealtad","question":"¿Es la lealtad una virtud incondicional, o debería depender de cómo se comporten los demás?","examples":[{"en":"While loyalty binds families, friendships, and nations together, it could be argued that unconditional allegiance has excused complicity in countless historical wrongs.","native":"Aunque la lealtad une a familias, amistades y naciones, podría argumentarse que la fidelidad incondicional ha excusado la complicidad en innumerables errores históricos."},{"en":"Admittedly, abandoning commitments at the first disappointment is hardly admirable; nevertheless, loyalty that survives betrayal of shared values ceases to be a virtue at all.","native":"Es cierto que abandonar los compromisos a la primera decepción no es admirable; sin embargo, la lealtad que sobrevive a la traición de valores compartidos deja de ser una virtud."},{"en":"On balance, loyalty seems to deserve its high reputation only when it remains conditional on decency, a qualification its most fervent defenders rarely mention.","native":"En definitiva, la lealtad solo parece merecer su elevada reputación cuando permanece condicionada a la decencia, una matización que sus defensores más fervientes rara vez mencionan."}]},"zh":{"word":"忠诚","question":"忠诚是一种无条件的美德，还是应当取决于他人的行为？","examples":[{"en":"While loyalty binds families, friendships, and nations together, it could be argued that unconditional allegiance has excused complicity in countless historical wrongs.","native":"尽管忠诚把家庭、友谊和国家凝聚在一起，但可以认为，无条件的效忠曾为无数历史错误中的同谋行为提供了借口。"},{"en":"Admittedly, abandoning commitments at the first disappointment is hardly admirable; nevertheless, loyalty that survives betrayal of shared values ceases to be a virtue at all.","native":"诚然，一遇到失望就背弃承诺并不值得钦佩；然而，在共同价值观遭到背叛后仍然存续的忠诚，就不再是美德了。"},{"en":"On balance, loyalty seems to deserve its high reputation only when it remains conditional on decency, a qualification its most fervent defenders rarely mention.","native":"总体而言，忠诚只有在以正直为条件时才配得上它的崇高声誉——而它最狂热的捍卫者很少提及这一限定。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'forgiveness', 'Does forgiving someone benefit the victim more than the offender?', '{"te":{"word":"క్షమాపణ","question":"ఎవరినైనా క్షమించడం నేరస్తుడి కంటే బాధితుడికే ఎక్కువ ప్రయోజనం చేస్తుందా?","examples":[{"en":"While forgiveness is often framed as a gift to the wrongdoer, it could be argued that its principal beneficiary is the forgiver, released from the weight of resentment.","native":"క్షమాపణను తరచుగా తప్పుచేసినవారికి ఇచ్చే బహుమతిగా చిత్రించినప్పటికీ, దాని ప్రధాన లబ్ధిదారు క్షమించినవారే—అసూయ భారం నుండి విడుదలైనవారు—అని చెప్పవచ్చు."},{"en":"Admittedly, some offences seem unforgivable, and pressured reconciliation can feel like a second injustice; nevertheless, refusing ever to forgive tends to prolong the original harm indefinitely.","native":"నిజానికి కొన్ని నేరాలు క్షమించలేనివిగా అనిపిస్తాయి, బలవంతపు సర్దుబాటు రెండో అన్యాయంలా అనిపించవచ్చు; అయినప్పటికీ, ఎప్పుడూ క్షమించకపోవడం అసలు హానిని అనిదిష్టంగా పొడిగిస్తుంది."},{"en":"On balance, forgiveness seems to work best when it is chosen freely and slowly, since commanded pardons rarely achieve the peace they are supposed to produce.","native":"మొత్తానికి, క్షమాపణ స్వేచ్ఛగా, నెమ్మదిగా ఎంచుకున్నప్పుడే బాగా పనిచేస్తుందని అనిపిస్తుంది, ఎందుకంటే ఆజ్ఞాపించిన మాఫీలు తాము ఉత్పత్తి చేయాల్సిన శాంతిని అరుదుగా సాధిస్తాయి."}]},"hi":{"word":"क्षमा","question":"क्या किसी को क्षमा करना अपराधी से ज़्यादा पीड़ित को लाभ पहुँचाता है?","examples":[{"en":"While forgiveness is often framed as a gift to the wrongdoer, it could be argued that its principal beneficiary is the forgiver, released from the weight of resentment.","native":"जबकि क्षमा को अक्सर अपराधी को दिया गया उपहार बताया जाता है, यह तर्क दिया जा सकता है कि इसका मुख्य लाभार्थी स्वयं क्षमा करने वाला है, जो ईर्ष्या के बोझ से मुक्त हो जाता है।"},{"en":"Admittedly, some offences seem unforgivable, and pressured reconciliation can feel like a second injustice; nevertheless, refusing ever to forgive tends to prolong the original harm indefinitely.","native":"यह स्वीकार करना होगा कि कुछ अपराध अक्षम्य लगते हैं, और दबाव में मेल-मिलाप दूसरा अन्याय जैसा लग सकता है; फिर भी, कभी क्षमा न करने से इनकार करना मूल क्षति को अनिश्चित काल तक लम्बा कर देता है।"},{"en":"On balance, forgiveness seems to work best when it is chosen freely and slowly, since commanded pardons rarely achieve the peace they are supposed to produce.","native":"कुल मिलाकर, क्षमा तब सबसे अच्छा काम करती लगती है जब उसे स्वतंत्र रूप से और धीरे-धीरे चुना जाए, क्योंकि आदेशित माफ़ियाँ शायद ही कभी वह शांति लाती हैं जो उनसे अपेक्षित होती है।"}]},"es":{"word":"perdón","question":"¿Beneficia perdonar a alguien más a la víctima que al ofensor?","examples":[{"en":"While forgiveness is often framed as a gift to the wrongdoer, it could be argued that its principal beneficiary is the forgiver, released from the weight of resentment.","native":"Aunque el perdón suele presentarse como un regalo para el ofensor, podría argumentarse que su principal beneficiario es quien perdona, liberado del peso del resentimiento."},{"en":"Admittedly, some offences seem unforgivable, and pressured reconciliation can feel like a second injustice; nevertheless, refusing ever to forgive tends to prolong the original harm indefinitely.","native":"Es cierto que algunas ofensas parecen imperdonables, y la reconciliación forzada puede sentirse como una segunda injusticia; sin embargo, negarse jamás a perdonar tiende a prolongar el daño original indefinidamente."},{"en":"On balance, forgiveness seems to work best when it is chosen freely and slowly, since commanded pardons rarely achieve the peace they are supposed to produce.","native":"En definitiva, el perdón parece funcionar mejor cuando se elige libremente y con lentitud, ya que las absoluciones ordenadas rara vez logran la paz que se supone deben producir."}]},"zh":{"word":"宽恕","question":"宽恕一个人对受害者的益处是否大于对过错者的益处？","examples":[{"en":"While forgiveness is often framed as a gift to the wrongdoer, it could be argued that its principal beneficiary is the forgiver, released from the weight of resentment.","native":"尽管宽恕常被描述为给予过错者的礼物，但可以认为，它的主要受益者是宽恕者本人——从怨恨的重负中解脱出来的人。"},{"en":"Admittedly, some offences seem unforgivable, and pressured reconciliation can feel like a second injustice; nevertheless, refusing ever to forgive tends to prolong the original harm indefinitely.","native":"诚然，有些冒犯似乎不可原谅，而被施压的和解可能让人感觉像第二次不公；然而，永远拒绝宽恕往往会无限期地延长最初的伤害。"},{"en":"On balance, forgiveness seems to work best when it is chosen freely and slowly, since commanded pardons rarely achieve the peace they are supposed to produce.","native":"总体而言，宽恕在被自由地、缓慢地选择时似乎效果最好，因为被命令的赦免很少能带来它本应产生的平静。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'courage', 'Is courage the absence of fear, or acting rightly despite being afraid?', '{"te":{"word":"ధైర్యం","question":"ధైర్యం అంటే భయం లేకపోవడమా, లేక భయపడుతున్నా సరైనది చేయడమా?","examples":[{"en":"While we celebrate fearless heroes, it could be argued that courage without fear is merely confidence, and that true bravery requires something worth fearing.","native":"మనం నిర్భయ వీరులను కొనియాడినప్పటికీ, భయం లేని ధైర్యం కేవలం ఆత్మవిశ్వాసమేనని, నిజమైన పరాక్రమానికి భయపడదగిన ఏదో అవసరమని చెప్పవచ్చు."},{"en":"Admittedly, physical daring impresses us most; nevertheless, moral courage—admitting error, defending the unpopular—demands far more of most people than any battlefield.","native":"నిజానికి శారీరక ధైర్యం మనల్ని అత్యంత ఆకట్టుకుంటుంది; అయినప్పటికీ, నైతిక ధైర్యం—పొరపాటు ఒప్పుకోవడం, అప్రజాదరణ పొందినదాన్ని సమర్థించడం—ఏ యుద్ధభూమి కంటే చాలామంది నుండి ఎక్కువను కోరుతుంది."},{"en":"On balance, courage seems less an inborn trait than a decision practised repeatedly, which suggests it is available to anyone willing to act while still afraid.","native":"మొత్తానికి, ధైర్యం సహజ లక్షణం కంటే పదేపదే అభ్యసించే నిర్ణయంలా కనిపిస్తుంది; భయంతో ఉండగానే చర్య తీసుకోవాలనుకునే ఎవరికైనా అది అందుబాటులో ఉందని ఇది సూచిస్తుంది."}]},"hi":{"word":"साहस","question":"क्या साहस भय की अनुपस्थिति है, या डरते हुए भी सही कार्य करना?","examples":[{"en":"While we celebrate fearless heroes, it could be argued that courage without fear is merely confidence, and that true bravery requires something worth fearing.","native":"जबकि हम निडर नायकों का गुणगान करते हैं, यह तर्क दिया जा सकता है कि भय के बिना साहस महज़ आत्मविश्वास है, और सच्ची वीरता के लिए किसी डरने लायक चीज़ की ज़रूरत होती है।"},{"en":"Admittedly, physical daring impresses us most; nevertheless, moral courage—admitting error, defending the unpopular—demands far more of most people than any battlefield.","native":"यह स्वीकार करना होगा कि शारीरिक दुस्साहस हमें सबसे अधिक प्रभावित करता है; फिर भी, नैतिक साहस—गलती मानना, अलोकप्रिय का बचाव—अधिकांश लोगों से किसी भी युद्धभूमि से कहीं अधिक माँगता है।"},{"en":"On balance, courage seems less an inborn trait than a decision practised repeatedly, which suggests it is available to anyone willing to act while still afraid.","native":"कुल मिलाकर, साहस जन्मजात गुण से कम और बार-बार किया गया निर्णय जैसा अधिक लगता है—इससे पता चलता है कि यह हर उस व्यक्ति के लिए उपलब्ध है जो डरते हुए भी कार्य करने को तैयार हो।"}]},"es":{"word":"valentía","question":"¿Es la valentía la ausencia de miedo, o actuar correctamente a pesar del temor?","examples":[{"en":"While we celebrate fearless heroes, it could be argued that courage without fear is merely confidence, and that true bravery requires something worth fearing.","native":"Aunque celebramos a los héroes intrépidos, podría argumentarse que la valentía sin miedo es mera confianza, y que el verdadero coraje requiere algo que valga la pena temer."},{"en":"Admittedly, physical daring impresses us most; nevertheless, moral courage—admitting error, defending the unpopular—demands far more of most people than any battlefield.","native":"Es cierto que la osadía física es lo que más nos impresiona; sin embargo, el coraje moral —admitir el error, defender lo impopular— exige a la mayoría mucho más que cualquier campo de batalla."},{"en":"On balance, courage seems less an inborn trait than a decision practised repeatedly, which suggests it is available to anyone willing to act while still afraid.","native":"En definitiva, la valentía parece menos un rasgo innato que una decisión practicada repetidamente, lo que sugiere que está al alcance de cualquiera dispuesto a actuar aun sintiendo miedo."}]},"zh":{"word":"勇气","question":"勇气是没有恐惧，还是尽管害怕仍然做正确的事？","examples":[{"en":"While we celebrate fearless heroes, it could be argued that courage without fear is merely confidence, and that true bravery requires something worth fearing.","native":"尽管我们赞美无所畏惧的英雄，但可以认为，没有恐惧的勇气不过是自信，而真正的勇敢需要有值得害怕的东西存在。"},{"en":"Admittedly, physical daring impresses us most; nevertheless, moral courage—admitting error, defending the unpopular—demands far more of most people than any battlefield.","native":"诚然，身体上的胆识最令我们印象深刻；然而，道德勇气——承认错误、捍卫不受欢迎的事物——对大多数人的要求远胜任何战场。"},{"en":"On balance, courage seems less an inborn trait than a decision practised repeatedly, which suggests it is available to anyone willing to act while still afraid.","native":"总体而言，勇气与其说是一种天生的特质，不如说是一个反复练习的决定——这意味着任何愿意带着恐惧行动的人都可以拥有它。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'hope', 'Is hope a realistic guide to action, or merely a comforting illusion?', '{"te":{"word":"ఆశ","question":"ఆశ చర్యకు వాస్తవిక మార్గదర్శియా, లేక కేవలం ఓదార్పు భ్రమయా?","examples":[{"en":"While cynics dismiss hope as naivety, it could be argued that nearly every significant achievement began as an act of hope unsupported by guarantees.","native":"నిరాశావాదులు ఆశను అమాయకత్వంగా తక్కువ చేసినప్పటికీ, దాదాపు ప్రతి గణనీయమైన విజయం హామీలు లేని ఆశ చర్యగా ప్రారంభమైందని చెప్పవచ్చు."},{"en":"Admittedly, blind optimism delays necessary adaptation; nevertheless, hopelessness is demonstrably a worse guide, since it forecloses possibilities that effort might have created.","native":"నిజానికి గుడ్డి ఆశావాదం అవసరమైన అనుసరణను ఆలస్యం చేస్తుంది; అయినప్పటికీ, నిరాశ స్పష్టంగా చెత్త మార్గదర్శి, ఎందుకంటే అది కృషి సృష్టించి ఉండగల అవకాశాలను ముందే మూసివేస్తుంది."},{"en":"On balance, hope seems wisest when coupled with clear-eyed assessment, functioning less as a prediction of success than as a precondition for attempting it.","native":"మొత్తానికి, ఆశ స్పష్టమైన అంచనాతో జతచేయబడినప్పుడు అత్యంత తెలివైనదిగా ఉంటుంది; విజయం యొక్క అంచనాగా కంటే దాన్ని ప్రయత్నించడానికి పూర్వపక్షంగా పనిచేస్తుంది."}]},"hi":{"word":"आशा","question":"क्या आशा कार्रवाई की यथार्थवादी मार्गदर्शक है, या महज़ एक सांत्वनादायक भ्रम?","examples":[{"en":"While cynics dismiss hope as naivety, it could be argued that nearly every significant achievement began as an act of hope unsupported by guarantees.","native":"जबकि निराशावादी आशा को भोलापन कहकर खारिज करते हैं, यह तर्क दिया जा सकता है कि लगभग हर महत्वपूर्ण उपलब्धि गारंटी के बिना आशा के कार्य के रूप में शुरू हुई।"},{"en":"Admittedly, blind optimism delays necessary adaptation; nevertheless, hopelessness is demonstrably a worse guide, since it forecloses possibilities that effort might have created.","native":"यह स्वीकार करना होगा कि अंधा आशावाद आवश्यक अनुकूलन में देरी करता है; फिर भी, निराशा प्रदर्शनात्मक रूप से बदतर मार्गदर्शक है, क्योंकि यह उन संभावनाओं को पहले से बंद कर देती है जिन्हें प्रयास पैदा कर सकता था।"},{"en":"On balance, hope seems wisest when coupled with clear-eyed assessment, functioning less as a prediction of success than as a precondition for attempting it.","native":"कुल मिलाकर, आशा तब सबसे बुद्धिमान लगती है जब वह स्पष्ट मूल्यांकन के साथ जुड़ी हो—यह सफलता की भविष्यवाणी से कम और उसे आज़माने की पूर्वशर्त जैसी अधिक काम करती है।"}]},"es":{"word":"esperanza","question":"¿Es la esperanza una guía realista para la acción, o meramente una ilusión reconfortante?","examples":[{"en":"While cynics dismiss hope as naivety, it could be argued that nearly every significant achievement began as an act of hope unsupported by guarantees.","native":"Aunque los cínicos descartan la esperanza como ingenuidad, podría argumentarse que casi todo logro significativo comenzó como un acto de esperanza sin garantías."},{"en":"Admittedly, blind optimism delays necessary adaptation; nevertheless, hopelessness is demonstrably a worse guide, since it forecloses possibilities that effort might have created.","native":"Es cierto que el optimismo ciego retrasa la adaptación necesaria; sin embargo, la desesperanza es demostrablemente una guía peor, ya que cierra posibilidades que el esfuerzo podría haber creado."},{"en":"On balance, hope seems wisest when coupled with clear-eyed assessment, functioning less as a prediction of success than as a precondition for attempting it.","native":"En definitiva, la esperanza parece más sabia cuando se acompaña de una evaluación lúcida, funcionando menos como predicción del éxito que como condición previa para intentarlo."}]},"zh":{"word":"希望","question":"希望是行动的现实指南，还是仅仅是一种令人安慰的幻觉？","examples":[{"en":"While cynics dismiss hope as naivety, it could be argued that nearly every significant achievement began as an act of hope unsupported by guarantees.","native":"尽管愤世嫉俗者把希望斥为天真，但可以认为，几乎每一项重大成就都始于一次没有保障支持的希望之举。"},{"en":"Admittedly, blind optimism delays necessary adaptation; nevertheless, hopelessness is demonstrably a worse guide, since it forecloses possibilities that effort might have created.","native":"诚然，盲目的乐观会拖延必要的调整；然而，绝望显然是更糟糕的向导，因为它预先扼杀了努力本可能创造的可能性。"},{"en":"On balance, hope seems wisest when coupled with clear-eyed assessment, functioning less as a prediction of success than as a precondition for attempting it.","native":"总体而言，希望在与清醒的评估相结合时似乎最为明智——它的作用与其说是对成功的预测，不如说是尝试成功的前提条件。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'optimism', 'Does being optimistic actually change outcomes, or only how we feel about them?', '{"te":{"word":"ఆశావాదం","question":"ఆశావాదం ఉండడం వాస్తవంగా ఫలితాలను మారుస్తుందా, లేక వాటి గురించి మనం ఎలా భావిస్తామో మాత్రమేనా?","examples":[{"en":"While pessimists pride themselves on realism, it could be argued that optimism functions as a self-fulfilling prophecy by sustaining effort where despair would quit early.","native":"నిరాశావాదులు తమ యథార్థత గురించి గర్వపడినప్పటికీ, నిరాశ త్వరగా వదులుకునే చోటు కృషిని కొనసాగించడం ద్వారా ఆశావాదం స్వయం పూర్తయ్యే ప్రవచనంగా పనిచేస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, unchecked optimism blinds investors, planners, and patients to genuine risks; nevertheless, its absence reliably produces the failure that pessimism confidently predicted.","native":"నిజానికి అదుపులేని ఆశావాదం పెట్టుబడిదారులనూ, ప్రణాళికాకర్తలనూ, రోగులనూ నిజమైన ప్రమాదాల పట్ల గుడ్డివారిని చేస్తుంది; అయినప్పటికీ, దాని లేమి నిరాశావాదం నమ్మకంగా అంచనా వేసిన వైఫల్యాన్ని తప్పకుండా ఉత్పత్తి చేస్తుంది."},{"en":"On balance, the evidence favours a disciplined optimism: expect favourable outcomes, yet prepare rigorously for unfavourable ones, a combination harder than either extreme.","native":"మొత్తానికి, సాక్ష్యాలు క్రమశిక్షణగల ఆశావాదానికి అనుకూలం: అనుకూల ఫలితాలను ఆశిస్తూ, ప్రతికూల ఫలితాలకు కఠోరంగా సిద్ధమవ్వడం; ఏ తీవ్రత కంటే కష్టమైన కలయిక ఇది."}]},"hi":{"word":"आशावाद","question":"क्या आशावादी होना वास्तव में परिणाम बदलता है, या सिर्फ उनके प्रति हमारी भावना?","examples":[{"en":"While pessimists pride themselves on realism, it could be argued that optimism functions as a self-fulfilling prophecy by sustaining effort where despair would quit early.","native":"जबकि निराशावादी अपनी यथार्थवादिता पर गर्व करते हैं, यह तर्क दिया जा सकता है कि आशावाद आत्मपूरक भविष्यवाणी की तरह काम करता है, जहाँ निराशा जल्दी हार मान लेती, वहाँ प्रयास को कायम रखकर।"},{"en":"Admittedly, unchecked optimism blinds investors, planners, and patients to genuine risks; nevertheless, its absence reliably produces the failure that pessimism confidently predicted.","native":"यह स्वीकार करना होगा कि अनियंत्रित आशावाद निवेशकों, योजनाकारों और रोगियों को वास्तविक जोखिमों से अंधा कर देता है; फिर भी, इसकी अनुपस्थिति विश्वसनीय रूप से वही असफलता पैदा करती है जिसकी भविष्यवाणी निराशावाद ने आत्मविश्वास से की थी।"},{"en":"On balance, the evidence favours a disciplined optimism: expect favourable outcomes, yet prepare rigorously for unfavourable ones, a combination harder than either extreme.","native":"कुल मिलाकर, प्रमाण अनुशासित आशावाद के पक्ष में है: अनुकूल परिणामों की अपेक्षा करें, फिर भी प्रतिकूल परिणामों की कठोर तैयारी करें—यह मेल किसी भी चरम से कठिन है।"}]},"es":{"word":"optimismo","question":"¿Cambia realmente los resultados ser optimista, o solo cómo nos sentimos al respecto?","examples":[{"en":"While pessimists pride themselves on realism, it could be argued that optimism functions as a self-fulfilling prophecy by sustaining effort where despair would quit early.","native":"Aunque los pesimistas se enorgullecen de su realismo, podría argumentarse que el optimismo funciona como profecía autocumplida al sostener el esfuerzo donde la desesperación abandonaría pronto."},{"en":"Admittedly, unchecked optimism blinds investors, planners, and patients to genuine risks; nevertheless, its absence reliably produces the failure that pessimism confidently predicted.","native":"Es cierto que el optimismo descontrolado ciega a inversores, planificadores y pacientes ante riesgos genuinos; sin embargo, su ausencia produce con fiabilidad el fracaso que el pesimismo predijo confiadamente."},{"en":"On balance, the evidence favours a disciplined optimism: expect favourable outcomes, yet prepare rigorously for unfavourable ones, a combination harder than either extreme.","native":"En definitiva, la evidencia favorece un optimismo disciplinado: esperar resultados favorables pero prepararse rigurosamente para los desfavorables, una combinación más difícil que cualquiera de los extremos."}]},"zh":{"word":"乐观","question":"乐观真的能改变结果吗，还是只改变我们对结果的感受？","examples":[{"en":"While pessimists pride themselves on realism, it could be argued that optimism functions as a self-fulfilling prophecy by sustaining effort where despair would quit early.","native":"尽管悲观主义者以现实主义为傲，但可以认为，乐观通过维持努力而成为一种自我实现的预言——而绝望则会早早放弃。"},{"en":"Admittedly, unchecked optimism blinds investors, planners, and patients to genuine risks; nevertheless, its absence reliably produces the failure that pessimism confidently predicted.","native":"诚然，失控的乐观会让投资者、规划者和患者对真正的风险视而不见；然而，缺少乐观则可靠地制造出悲观主义曾自信预测的失败。"},{"en":"On balance, the evidence favours a disciplined optimism: expect favourable outcomes, yet prepare rigorously for unfavourable ones, a combination harder than either extreme.","native":"总体而言，证据支持一种有纪律的乐观：期待有利的结果，同时严谨地为不利结果做准备——这种组合比任何一个极端都更难。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'regret', 'Do people regret the things they did more than the things they never tried?', '{"te":{"word":"పశ్చాత్తాపం","question":"ప్రజలు తాము చేసిన వాటి కంటే ఎప్పుడూ ప్రయత్నించని వాటి గురించే ఎక్కువగా పశ్చాత్తాపపడతారా?","examples":[{"en":"While failed attempts sting immediately, it could be argued that untaken chances ache far longer, since imagination keeps revising what might have been indefinitely.","native":"విఫల ప్రయత్నాలు వెంటనే బాధించినప్పటికీ, తీసుకోని అవకాశాలు చాలా కాలం బాధిస్తాయని చెప్పవచ్చు, ఎందుకంటే ఊహ ఉండేది ఏమిటో అనిదిష్టంగా సవరిస్తూనే ఉంటుంది."},{"en":"Admittedly, research on regret is complicated by memory''s distortions; nevertheless, the dying consistently report regretting inaction considerably more than embarrassing or costly action.","native":"నిజానికి జ్ఞాపకశక్తి వక్రీకరణల వల్ల పశ్చాత్తాపంపై పరిశోధన క్లిష్టమైంది; అయినప్పటికీ, మరణ శయ్యల వారు సిగ్గుచెట్టు లేదా ఖరీదైన చర్య కంటే నిష్క్రియ గురించే గణనీయంగా ఎక్కువ పశ్చాత్తాపపడతారని నిరంతరం నివేదిస్తారు."},{"en":"On balance, regret seems a poor compass but a useful teacher, provided one examines it occasionally rather than taking up permanent residence in its territory.","native":"మొత్తానికి, పశ్చాత్తాపం పేద దిక్సూచి అయినా ఉపయోగకరమైన ఉపాధ్యాయుడు అనిపిస్తుంది; దాని భూభాగంలో శాశ్వత నివాసం ఏర్పరచుకోకుండా అప్పుడప్పుడూ పరిశీలిస్తే చాలు."}]},"hi":{"word":"पछतावा","question":"क्या लोगों को की हुई चीज़ों से ज़्यादा कभी न आज़माई गई चीज़ों का पछतावा होता है?","examples":[{"en":"While failed attempts sting immediately, it could be argued that untaken chances ache far longer, since imagination keeps revising what might have been indefinitely.","native":"जबकि असफल प्रयास तुरंत चुभते हैं, यह तर्क दिया जा सकता है कि न लिए गए अवसर कहीं अधिक समय तक दुखते हैं, क्योंकि कल्पना इस बात को अनिश्चित काल तक संशोधित करती रहती है कि क्या हो सकता था।"},{"en":"Admittedly, research on regret is complicated by memory''s distortions; nevertheless, the dying consistently report regretting inaction considerably more than embarrassing or costly action.","native":"यह स्वीकार करना होगा कि स्मृति की विकृतियों से पछतावे पर शोध जटिल है; फिर भी, मृत्युशैया पर पड़े लोग लगातार बताते हैं कि शर्मनाक या महँगे कार्य की तुलना में न किए जाने का पछतावा काफी अधिक होता है।"},{"en":"On balance, regret seems a poor compass but a useful teacher, provided one examines it occasionally rather than taking up permanent residence in its territory.","native":"कुल मिलाकर, पछतावा एक खराब दिशासूचक लेकिन उपयोगी शिक्षक लगता है, बशर्ते कोई इसके क्षेत्र में स्थायी निवास बनाने के बजाय कभी-कभी इसका परीक्षण करे।"}]},"es":{"word":"arrepentimiento","question":"¿Se arrepiente la gente más de lo que hizo que de lo que nunca intentó?","examples":[{"en":"While failed attempts sting immediately, it could be argued that untaken chances ache far longer, since imagination keeps revising what might have been indefinitely.","native":"Aunque los intentos fallidos escuecen de inmediato, podría argumentarse que las oportunidades no tomadas duelen mucho más tiempo, ya que la imaginación sigue revisando lo que pudo haber sido indefinidamente."},{"en":"Admittedly, research on regret is complicated by memory''s distortions; nevertheless, the dying consistently report regretting inaction considerably more than embarrassing or costly action.","native":"Es cierto que la investigación sobre el arrepentimiento se complica por las distorsiones de la memoria; sin embargo, los moribundos reportan consistentemente lamentar la inacción considerablemente más que la acción embarazosa o costosa."},{"en":"On balance, regret seems a poor compass but a useful teacher, provided one examines it occasionally rather than taking up permanent residence in its territory.","native":"En definitiva, el arrepentimiento parece una brújula pobre pero un maestro útil, siempre que uno lo examine ocasionalmente en lugar de fijar residencia permanente en su territorio."}]},"zh":{"word":"遗憾","question":"人们对做过的事情的后悔，是否少于对从未尝试之事的后悔？","examples":[{"en":"While failed attempts sting immediately, it could be argued that untaken chances ache far longer, since imagination keeps revising what might have been indefinitely.","native":"尽管失败的尝试会立即带来刺痛，但可以认为，未曾把握的机会疼痛得更久，因为想象会无限期地不断改写“本可以怎样”。"},{"en":"Admittedly, research on regret is complicated by memory''s distortions; nevertheless, the dying consistently report regretting inaction considerably more than embarrassing or costly action.","native":"诚然，关于后悔的研究因记忆的扭曲而变得复杂；然而，临终者始终报告说，对不作为的后悔远远多于对令人尴尬或代价高昂的行动的后悔。"},{"en":"On balance, regret seems a poor compass but a useful teacher, provided one examines it occasionally rather than taking up permanent residence in its territory.","native":"总体而言，后悔似乎是一个糟糕的指南针，却是一位有用的老师——只要人们偶尔审视它，而不是在它的领地中永久定居。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'gratitude', 'Does practising gratitude genuinely improve well-being, or is it just a fashionable self-help trend?', '{"te":{"word":"కృతజ్ఞత","question":"కృతజ్ఞత అభ్యాసం నిజంగా శ్రేయస్సును మెరుగుపరుస్తుందా, లేక అది కేవలం ఫ్యాషనబుల్ స్వయం-సహాయ ట్రెండేనా?","examples":[{"en":"While gratitude journals risk becoming hollow rituals, it could be argued that deliberately noticing good fortune reliably shifts attention away from what is lacking.","native":"కృతజ్ఞత డైరీలు లోపలి కర్మకాండలు కావడానికి ప్రమాదమున్నప్పటికీ, అదృష్టాన్ని ఉద్దేశపూర్వకంగా గమనించడం లేని దాని నుండి దృష్టిని తప్పకుండా మళ్లిస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, forced thankfulness can suppress legitimate grievances; nevertheless, the research linking regular gratitude practice to improved sleep and mood is surprisingly robust.","native":"నిజానికి బలవంతపు కృతజ్ఞత చట్టబద్ధమైన ఫిర్యాదులను అణచివేయవచ్చు; అయినప్పటికీ, క్రమమైన కృతజ్ఞత అభ్యాసాన్ని మెరుగైన నిద్ర, మానసిక స్థితితో ముడిపెట్టే పరిశోధన ఆశ్చర్యకరంగా దృఢంగా ఉంది."},{"en":"On balance, gratitude seems less a mood than a discipline of attention, valuable precisely because entitlement is the default setting of the comfortably off.","native":"మొత్తానికి, కృతజ్ఞత మూడ్ కంటే దృష్టి యొక్క క్రమశిక్షణలా కనిపిస్తుంది; హక్కుదార భావన సౌకర్యవంతుల అప్రమేయ స్థితి కాబట్టే ఇది విలువైనది."}]},"hi":{"word":"कृतज्ञता","question":"क्या कृतज्ञता का अभ्यास वास्तव में कल्याण सुधारता है, या यह सिर्फ एक फैशनेबल स्वयं-सहायता रुझान है?","examples":[{"en":"While gratitude journals risk becoming hollow rituals, it could be argued that deliberately noticing good fortune reliably shifts attention away from what is lacking.","native":"जबकि कृतज्ञता डायरियाँ खोखले अनुष्ठान बनने का जोखिम रखती हैं, यह तर्क दिया जा सकता है कि अच्छे भाग्य को जानबूझकर नोटिस करना ध्यान को उस चीज़ से विश्वसनीय रूप से हटा देता है जो नहीं है।"},{"en":"Admittedly, forced thankfulness can suppress legitimate grievances; nevertheless, the research linking regular gratitude practice to improved sleep and mood is surprisingly robust.","native":"यह स्वीकार करना होगा कि जबरन आभार वैध शिकायतों को दबा सकता है; फिर भी, नियमित कृतज्ञता अभ्यास को बेहतर नींद और मूड से जोड़ने वाला शोध आश्चर्यजनक रूप से मज़बूत है।"},{"en":"On balance, gratitude seems less a mood than a discipline of attention, valuable precisely because entitlement is the default setting of the comfortably off.","native":"कुल मिलाकर, कृतज्ञता मूड से कम और ध्यान के अनुशासन जैसी अधिक लगती है—ठीक इसलिए मूल्यवान क्योंकि हक़दारी की भावना आरामदेह लोगों की तयशुदा स्थिति है।"}]},"es":{"word":"gratitud","question":"¿Mejora realmente el bienestar practicar la gratitud, o es solo una moda de autoayuda?","examples":[{"en":"While gratitude journals risk becoming hollow rituals, it could be argued that deliberately noticing good fortune reliably shifts attention away from what is lacking.","native":"Aunque los diarios de gratitud arriesgan convertirse en rituales vacíos, podría argumentarse que notar deliberadamente la buena fortuna desvía con fiabilidad la atención de lo que falta."},{"en":"Admittedly, forced thankfulness can suppress legitimate grievances; nevertheless, the research linking regular gratitude practice to improved sleep and mood is surprisingly robust.","native":"Es cierto que el agradecimiento forzado puede suprimir agravios legítimos; sin embargo, la investigación que vincula la práctica regular de gratitud con mejor sueño y ánimo es sorprendentemente sólida."},{"en":"On balance, gratitude seems less a mood than a discipline of attention, valuable precisely because entitlement is the default setting of the comfortably off.","native":"En definitiva, la gratitud parece menos un estado de ánimo que una disciplina de la atención, valiosa precisamente porque el sentimiento de merecimiento es el ajuste predeterminado de los acomodados."}]},"zh":{"word":"感恩","question":"练习感恩真的能改善幸福感吗，还是只是一种时髦的自助潮流？","examples":[{"en":"While gratitude journals risk becoming hollow rituals, it could be argued that deliberately noticing good fortune reliably shifts attention away from what is lacking.","native":"尽管感恩日记有沦为空洞仪式的风险，但可以认为，刻意留意好运会可靠地把注意力从缺失之物上移开。"},{"en":"Admittedly, forced thankfulness can suppress legitimate grievances; nevertheless, the research linking regular gratitude practice to improved sleep and mood is surprisingly robust.","native":"诚然，强制的感恩可能压抑正当的不满；然而，把规律感恩练习与改善睡眠和情绪联系起来的研究出人意料地扎实。"},{"en":"On balance, gratitude seems less a mood than a discipline of attention, valuable precisely because entitlement is the default setting of the comfortably off.","native":"总体而言，感恩与其说是一种心情，不如说是一种注意力的训练——它之所以可贵，恰恰因为“理所当然”是富足者的默认设置。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'compassion', 'Can compassion towards strangers be sustained, or does fatigue inevitably set in?', '{"te":{"word":"కరుణ","question":"అపరిచితుల పట్ల కరుణను కొనసాగించగలమా, లేక అలసట అనివార్యంగా వస్తుందా?","examples":[{"en":"While compassion flows easily towards people we know, it could be argued that extending it to distant strangers requires imagination that most daily life actively discourages.","native":"మనకు తెలిసినవారి పట్ల కరుణ సులభంగా ప్రవహించినప్పటికీ, దూరమైన అపరిచితుల వైపు దాన్ని విస్తరించడానికి చాలా దైనందిన జీవితం చురుకుగా నిరుత్సాహపరిచే ఊహ అవసరమని చెప్పవచ్చు."},{"en":"Admittedly, compassion fatigue afflicts aid workers and news audiences alike; nevertheless, empathy appears renewable through rest and boundaries rather than being a strictly finite resource.","native":"నిజానికి కరుణా అలసట సహాయక కార్యకర్తలనూ, వార్తా ప్రేక్షకులనూ సమానంగా బాధిస్తుంది; అయినప్పటికీ, సానుభూతి కఠోరంగా పరిమిత వనరు కాకుండా విశ్రాంతి, సరిహద్దుల ద్వారా పునరుత్పత్తి చేయగలదని అనిపిస్తుంది."},{"en":"On balance, compassion seems sustainable when practised as a habit of small acts rather than an emotion, since feelings fade but routines, once formed, endure.","native":"మొత్తానికి, కరుణను భావనగా కాకుండా చిన్న చర్యల అలవాటుగా అభ్యసించినప్పుడు అది స్థిరంగా ఉంటుందని అనిపిస్తుంది, ఎందుకంటే భావాలు మసకబారతాయి కానీ ఏర్పడిన దినచర్యలు నిలుస్తాయి."}]},"hi":{"word":"करुणा","question":"क्या अजनबियों के प्रति करुणा कायम रखी जा सकती है, या थकान अनिवार्य रूप से आ ही जाती है?","examples":[{"en":"While compassion flows easily towards people we know, it could be argued that extending it to distant strangers requires imagination that most daily life actively discourages.","native":"जबकि करुणा जानने वालों के प्रति आसानी से बहती है, यह तर्क दिया जा सकता है कि इसे दूर के अजनबियों तक बढ़ाने के लिए वह कल्पना चाहिए जिसे अधिकांश दैनिक जीवन सक्रिय रूप से हतोत्साहित करता है।"},{"en":"Admittedly, compassion fatigue afflicts aid workers and news audiences alike; nevertheless, empathy appears renewable through rest and boundaries rather than being a strictly finite resource.","native":"यह स्वीकार करना होगा कि करुणा-थकान सहायता कर्मियों और समाचार दर्शकों दोनों को प्रभावित करती है; फिर भी, समानुभूति सीमित संसाधन होने के बजाय आराम और सीमाओं से नवीकरणीय प्रतीत होती है।"},{"en":"On balance, compassion seems sustainable when practised as a habit of small acts rather than an emotion, since feelings fade but routines, once formed, endure.","native":"कुल मिलाकर, करुणा तब टिकाऊ लगती है जब उसे भावना के बजाय छोटे कार्यों की आदत के रूप में अपनाया जाए, क्योंकि भावनाएँ फीकी पड़ती हैं पर बन गई दिनचर्याएँ टिकती हैं।"}]},"es":{"word":"compasión","question":"¿Puede sostenerse la compasión hacia los extraños, o es inevitable que aparezca la fatiga?","examples":[{"en":"While compassion flows easily towards people we know, it could be argued that extending it to distant strangers requires imagination that most daily life actively discourages.","native":"Aunque la compasión fluye fácilmente hacia quienes conocemos, podría argumentarse que extenderla a extraños lejanos requiere una imaginación que la vida diaria desalienta activamente."},{"en":"Admittedly, compassion fatigue afflicts aid workers and news audiences alike; nevertheless, empathy appears renewable through rest and boundaries rather than being a strictly finite resource.","native":"Es cierto que la fatiga por compasión aflige por igual a cooperantes y audiencias de noticias; sin embargo, la empatía parece renovable mediante el descanso y los límites, en lugar de ser un recurso estrictamente finito."},{"en":"On balance, compassion seems sustainable when practised as a habit of small acts rather than an emotion, since feelings fade but routines, once formed, endure.","native":"En definitiva, la compasión parece sostenible cuando se practica como un hábito de pequeños actos y no como una emoción, ya que los sentimientos se desvanecen pero las rutinas, una vez formadas, perduran."}]},"zh":{"word":"怜悯","question":"对陌生人的怜悯能够持续吗，还是倦怠终究不可避免地会出现？","examples":[{"en":"While compassion flows easily towards people we know, it could be argued that extending it to distant strangers requires imagination that most daily life actively discourages.","native":"尽管怜悯很容易流向我们认识的人，但可以认为，把它延伸到远方的陌生人需要一种想象力——而大多数日常生活恰恰在积极打击这种想象力。"},{"en":"Admittedly, compassion fatigue afflicts aid workers and news audiences alike; nevertheless, empathy appears renewable through rest and boundaries rather than being a strictly finite resource.","native":"诚然，怜悯疲劳同样困扰着援助工作者和新闻受众；然而，同理心似乎可以通过休息和界限来更新，而不是一种严格有限的资源。"},{"en":"On balance, compassion seems sustainable when practised as a habit of small acts rather than an emotion, since feelings fade but routines, once formed, endure.","native":"总体而言，当怜悯被当作微小行动的习惯而非情绪来践行时，它似乎才是可持续的，因为感觉会消退，而一旦养成的惯例却会延续下去。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'altruism', 'Is pure altruism possible, or is every generous act ultimately self-interested?', '{"te":{"word":"నిస్వార్థం","question":"స్వచ్ఛమైన నిస్వార్థం సాధ్యమేనా, లేక ప్రతి ఉదార చర్య అంతిమంగా స్వార్థపూరితమేనా?","examples":[{"en":"While sceptics insist that generosity always rewards the giver, it could be argued that feeling good about helping others hardly disqualifies the help itself as genuine.","native":"అనుమానవాదులు ఉదారత ఎల్లప్పుడూ ఇచ్చేవారిని ప్రతిఫలం పొందేలా చేస్తుందని పట్టుబట్టినప్పటికీ, ఇతరులకు సహాయం చేయడం గురించి సంతోషం అనుభవించడం ఆ సహాయాన్ని నిజమైనదిగా అనర్హం చేయదని చెప్పవచ్చు."},{"en":"Admittedly, people donate blood, kidneys, and fortunes anonymously; nevertheless, even these acts might be traced to values or identities the donors wish to preserve.","native":"నిజానికి ప్రజలు రక్తం, మూత్రపిండాలు, ఆస్తులను అనామకంగా విరాళంగా ఇస్తారు; అయినప్పటికీ, ఈ చర్యలు కూడా దాతలు కాపాడుకోవాలనుకునే విలువలు లేదా గుర్తింపులకు జాడించవచ్చు."},{"en":"On balance, the philosophical debate seems less important than the outcome, since motives are mixed in all of us while the hungry person fed remains fed regardless.","native":"మొత్తానికి, తత్వ చర్చ కంటే ఫలితమే ముఖ్యమని అనిపిస్తుంది, ఎందుకంటే మనందరిలోనూ ప్రేరణలు మిశ్రమమైనప్పటికీ, ఆహారం పొందిన ఆకలిగల్లవాడు అందేలా తినిపించబడినవాడే."}]},"hi":{"word":"निःस्वार्थता","question":"क्या शुद्ध निःस्वार्थता संभव है, या हर उदार कार्य अंततः स्वार्थी ही होता है?","examples":[{"en":"While sceptics insist that generosity always rewards the giver, it could be argued that feeling good about helping others hardly disqualifies the help itself as genuine.","native":"जबकि संशयवादी ज़ोर देते हैं कि उदारता हमेशा देने वाले को पुरस्कृत करती है, यह तर्क दिया जा सकता है कि दूसरों की मदद करने में अच्छा महसूस करना उस मदद को असली होने से अयोग्य नहीं ठहराता।"},{"en":"Admittedly, people donate blood, kidneys, and fortunes anonymously; nevertheless, even these acts might be traced to values or identities the donors wish to preserve.","native":"यह स्वीकार करना होगा कि लोग गुमनाम रूप से रक्त, गुर्दे और संपत्तियाँ दान करते हैं; फिर भी, इन कार्यों को भी उन मूल्यों या पहचानों से जोड़ा जा सकता है जिन्हें दाता बनाए रखना चाहते हैं।"},{"en":"On balance, the philosophical debate seems less important than the outcome, since motives are mixed in all of us while the hungry person fed remains fed regardless.","native":"कुल मिलाकर, दार्शनिक बहस परिणाम से कम महत्वपूर्ण लगती है, क्योंकि हम सभी में उद्देश्य मिश्रित होते हैं, जबकि खिलाया गया भूखा व्यक्ति वैसे भी खिलाया गया ही रहता है।"}]},"es":{"word":"altruismo","question":"¿Es posible el altruismo puro, o todo acto generoso es en última instancia interesado?","examples":[{"en":"While sceptics insist that generosity always rewards the giver, it could be argued that feeling good about helping others hardly disqualifies the help itself as genuine.","native":"Aunque los escépticos insisten en que la generosidad siempre recompensa al dador, podría argumentarse que sentirse bien por ayudar a otros apenas descalifica la ayuda misma como genuina."},{"en":"Admittedly, people donate blood, kidneys, and fortunes anonymously; nevertheless, even these acts might be traced to values or identities the donors wish to preserve.","native":"Es cierto que la gente dona sangre, riñones y fortunas anónimamente; sin embargo, incluso estos actos podrían rastrearse hasta valores o identidades que los donantes desean preservar."},{"en":"On balance, the philosophical debate seems less important than the outcome, since motives are mixed in all of us while the hungry person fed remains fed regardless.","native":"En definitiva, el debate filosófico parece menos importante que el resultado, ya que los motivos son mixtos en todos nosotros, mientras que la persona hambrienta alimentada sigue alimentada de todos modos."}]},"zh":{"word":"利他主义","question":"纯粹的利他主义可能存在吗，还是每一个慷慨的行为归根结底都是自利的？","examples":[{"en":"While sceptics insist that generosity always rewards the giver, it could be argued that feeling good about helping others hardly disqualifies the help itself as genuine.","native":"尽管怀疑论者坚称慷慨总是回报给予者，但可以认为，因帮助他人而感到愉悦并不能使帮助本身变得不真诚。"},{"en":"Admittedly, people donate blood, kidneys, and fortunes anonymously; nevertheless, even these acts might be traced to values or identities the donors wish to preserve.","native":"诚然，人们匿名捐献血液、肾脏和财富；然而，即便是这些行为，也可能追溯到捐赠者希望保持的价值观或自我认同。"},{"en":"On balance, the philosophical debate seems less important than the outcome, since motives are mixed in all of us while the hungry person fed remains fed regardless.","native":"总体而言，这场哲学辩论似乎没有结果那么重要，因为我们每个人的动机都是复杂的，而得到食物的饥饿者无论如何都已吃饱。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'greed', 'Is greed a natural human instinct that economies depend on, or a vice that should be restrained?', '{"te":{"word":"అత్యాశ","question":"అత్యాశ ఆర్థిక వ్యవస్థలు ఆధారపడే సహజ మానవ స్వభావమా, లేక అదుపులో ఉంచాల్సిన దుర్గుణమా?","examples":[{"en":"While economists sometimes defend greed as the engine of prosperity, it could be argued that markets function despite greed rather than because of it.","native":"ఆర్థికవేత్తలు కొన్నిసార్లు అత్యాశను శ్రేయస్సు యొక్క యంత్రంగా సమర్థించినప్పటికీ, మార్కెట్లు అత్యాశ వల్ల కాకుండా అది ఉన్నా పనిచేస్తాయని చెప్పవచ్చు."},{"en":"Admittedly, acquisitiveness motivates effort and risk-taking; nevertheless, unrestrained, it reliably produces speculation, fraud, and crises whose costs fall on the innocent.","native":"నిజానికి సంపాదనాశ కృషినీ, రిస్క్ తీసుకోవడాన్నీ ప్రేరేపిస్తుంది; అయినప్పటికీ, అదుపు లేకుంటే అది సట్టాలనూ, మోసాలనూ, సంక్షోభాలనూ తప్పకుండా ఉత్పత్తి చేస్తుంది—వాటి ఖర్చు నిరపరాధులపై పడుతుంది."},{"en":"On balance, greed seems useful as a servant and catastrophic as a master, which is why successful societies channel it rather than celebrating it outright.","native":"మొత్తానికి, అత్యాశ నౌకరుగా ఉపయోగపడుతుంది, యజమానిగా వినాశకరం; విజయవంతమైన సమాజాలు దాన్ని పూర్తిగా కీర్తించడం కంటే మార్గనిర్దేశం చేయడమే ఇందుకు కారణం."}]},"hi":{"word":"लालच","question":"क्या लालच एक स्वाभाविक मानव प्रवृत्ति है जिस पर अर्थव्यवस्थाएँ निर्भर हैं, या एक दुर्गुण है जिसे नियंत्रित किया जाना चाहिए?","examples":[{"en":"While economists sometimes defend greed as the engine of prosperity, it could be argued that markets function despite greed rather than because of it.","native":"जबकि अर्थशास्त्री कभी-कभी लालच को समृद्धि का इंजन बताकर उसका बचाव करते हैं, यह तर्क दिया जा सकता है कि बाज़ार लालच की वजह से नहीं, बल्कि उसके बावजूद काम करते हैं।"},{"en":"Admittedly, acquisitiveness motivates effort and risk-taking; nevertheless, unrestrained, it reliably produces speculation, fraud, and crises whose costs fall on the innocent.","native":"यह स्वीकार करना होगा कि अर्जन-प्रवृत्ति प्रयास और जोखिम लेने को प्रेरित करती है; फिर भी, अनियंत्रित होने पर यह विश्वसनीय रूप से सट्टाबाज़ी, धोखाधड़ी और संकट पैदा करती है जिनकी कीमत निर्दोष लोग चुकाते हैं।"},{"en":"On balance, greed seems useful as a servant and catastrophic as a master, which is why successful societies channel it rather than celebrating it outright.","native":"कुल मिलाकर, लालच नौकर के रूप में उपयोगी और स्वामी के रूप में विनाशकारी लगती है—यही कारण है कि सफल समाज इसका पुरस्संगीत करने के बजाय इसे मार्गदर्शित करते हैं।"}]},"es":{"word":"avaricia","question":"¿Es la avaricia un instinto humano natural del que dependen las economías, o un vicio que debería contenerse?","examples":[{"en":"While economists sometimes defend greed as the engine of prosperity, it could be argued that markets function despite greed rather than because of it.","native":"Aunque los economistas a veces defienden la avaricia como motor de la prosperidad, podría argumentarse que los mercados funcionan a pesar de la avaricia más que gracias a ella."},{"en":"Admittedly, acquisitiveness motivates effort and risk-taking; nevertheless, unrestrained, it reliably produces speculation, fraud, and crises whose costs fall on the innocent.","native":"Es cierto que la codicia motiva el esfuerzo y la asunción de riesgos; sin embargo, desenfrenada, produce con fiabilidad especulación, fraude y crisis cuyos costes recaen sobre los inocentes."},{"en":"On balance, greed seems useful as a servant and catastrophic as a master, which is why successful societies channel it rather than celebrating it outright.","native":"En definitiva, la avaricia parece útil como sirviente y catastrófica como amo, razón por la cual las sociedades exitosas la canalizan en lugar de celebrarla abiertamente."}]},"zh":{"word":"贪婪","question":"贪婪是经济赖以运转的自然人类本能，还是应当加以约束的恶行？","examples":[{"en":"While economists sometimes defend greed as the engine of prosperity, it could be argued that markets function despite greed rather than because of it.","native":"尽管经济学家有时把贪婪辩护为繁荣的引擎，但可以认为，市场的运转与其说是拜贪婪所赐，不如说是尽管有贪婪仍能运转。"},{"en":"Admittedly, acquisitiveness motivates effort and risk-taking; nevertheless, unrestrained, it reliably produces speculation, fraud, and crises whose costs fall on the innocent.","native":"诚然，占有欲能激励努力和冒险；然而，一旦失去约束，它总会可靠地制造投机、欺诈和危机，而代价却由无辜者承担。"},{"en":"On balance, greed seems useful as a servant and catastrophic as a master, which is why successful societies channel it rather than celebrating it outright.","native":"总体而言，贪婪作为仆从有用，作为主人则是灾难——这正是成功的社会对它加以引导而非公然颂扬的原因。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'materialism', 'Why do so many people believe possessions will make them happy despite evidence to the contrary?', '{"te":{"word":"భౌతికవాదం","question":"వ్యతిరేక సాక్ష్యాలున్నా చాలామంది ఆస్తులు ఆనందం ఇస్తాయని ఎందుకు నమ్ముతారు?","examples":[{"en":"While everyone knows intellectually that money cannot buy happiness, it could be argued that advertising and social comparison keep persuading our instincts otherwise.","native":"డబ్బుతో ఆనందం కొనలేమని అందరూ బౌద్ధికంగా తెలిసినప్పటికీ, ప్రకటనలు, సామాజిక పోలికలు మన స్వభావాన్ని ఇలా కాదని ఒప్పిస్తూనే ఉంటాయని చెప్పవచ్చు."},{"en":"Admittedly, possessions deliver brief, genuine pleasure; nevertheless, hedonic adaptation ensures that today''s coveted purchase becomes tomorrow''s unnoticed background with remarkable speed.","native":"నిజానికి ఆస్తులు క్షణిక, నిజమైన ఆనందాన్ని ఇస్తాయి; అయినప్పటికీ, ఆనంద అనుసరణ ఈరోజు కోరిన కొనుగోలు రేపు గమనించని నేపథ్యమవుతుందని అసాధారణ వేగంతో నిర్ధారిస్తుంది."},{"en":"On balance, materialism persists because it answers a real hunger—for status, security, identity—with the wrong food, leaving the appetite itself untouched.","native":"మొత్తానికి, భౌతికవాదం కొనసాగుతుంది ఎందుకంటే అది నిజమైన ఆకలికి—ప్రతిష్ఠ, భద్రత, గుర్తింపు కోసం—తప్పు ఆహారంతో సమాధానం ఇస్తుంది, ఆకలిని అలాగే ఉంచుతుంది."}]},"hi":{"word":"भौतिकवाद","question":"इसके विपरीत साक्ष्यों के बावजूद इतने लोग यह क्यों मानते हैं कि सामान उन्हें खुश करेगा?","examples":[{"en":"While everyone knows intellectually that money cannot buy happiness, it could be argued that advertising and social comparison keep persuading our instincts otherwise.","native":"जबकि हर कोई बौद्धिक रूप से जानता है कि पैसा खुशी नहीं खरीद सकता, यह तर्क दिया जा सकता है कि विज्ञापन और सामाजिक तुलना हमारी प्रवृत्तियों को बार-बार उल्टा मना लेते हैं।"},{"en":"Admittedly, possessions deliver brief, genuine pleasure; nevertheless, hedonic adaptation ensures that today''s coveted purchase becomes tomorrow''s unnoticed background with remarkable speed.","native":"यह स्वीकार करना होगा कि सामान क्षणिक, वास्तविक आनंद देता है; फिर भी, सुख-अनुकूलन सुनिश्चित करता है कि आज की लालसित खरीद उल्लेखनीय गति से कल का अनदेखा पृष्ठभूमि बन जाए।"},{"en":"On balance, materialism persists because it answers a real hunger—for status, security, identity—with the wrong food, leaving the appetite itself untouched.","native":"कुल मिलाकर, भौतिकवाद इसलिए बना रहता है क्योंकि यह एक वास्तविक भूख—प्रतिष्ठा, सुरक्षा, पहचान के लिए—का उत्तर गलत भोजन से देता है, और भूख को वैसा ही छोड़ देता है।"}]},"es":{"word":"materialismo","question":"¿Por qué tanta gente cree que las posesiones la harán feliz pese a la evidencia en contrario?","examples":[{"en":"While everyone knows intellectually that money cannot buy happiness, it could be argued that advertising and social comparison keep persuading our instincts otherwise.","native":"Aunque todos saben intelectualmente que el dinero no compra la felicidad, podría argumentarse que la publicidad y la comparación social siguen persuadiendo a nuestros instintos de lo contrario."},{"en":"Admittedly, possessions deliver brief, genuine pleasure; nevertheless, hedonic adaptation ensures that today''s coveted purchase becomes tomorrow''s unnoticed background with remarkable speed.","native":"Es cierto que las posesiones brindan un placer breve y genuino; sin embargo, la adaptación hedónica asegura que la compra codiciada de hoy se convierta con notable rapidez en el fondo inadvertido de mañana."},{"en":"On balance, materialism persists because it answers a real hunger—for status, security, identity—with the wrong food, leaving the appetite itself untouched.","native":"En definitiva, el materialismo persiste porque responde a un hambre real —de estatus, seguridad, identidad— con el alimento equivocado, dejando el apetito intacto."}]},"zh":{"word":"物质主义","question":"为什么尽管有相反的证据，仍有那么多人相信物质财富会让他们幸福？","examples":[{"en":"While everyone knows intellectually that money cannot buy happiness, it could be argued that advertising and social comparison keep persuading our instincts otherwise.","native":"尽管每个人在理智上都知道金钱买不到幸福，但可以认为，广告和社会攀比不断地说服我们的本能去相信相反的东西。"},{"en":"Admittedly, possessions deliver brief, genuine pleasure; nevertheless, hedonic adaptation ensures that today''s coveted purchase becomes tomorrow''s unnoticed background with remarkable speed.","native":"诚然，物质能带来短暂而真实的快乐；然而，享乐适应确保今天渴望的购买会以惊人的速度变成明天视而不见的背景。"},{"en":"On balance, materialism persists because it answers a real hunger—for status, security, identity—with the wrong food, leaving the appetite itself untouched.","native":"总体而言，物质主义之所以持续存在，是因为它用错误的食物回应了真实的渴望——对地位、安全和身份的渴望——而让那份渴望本身原封不动。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'minimalism', 'Is minimalism a meaningful critique of consumer society, or just another lifestyle trend?', '{"te":{"word":"సరళ జీవనవాదం","question":"సరళ జీవనవాదం వినియోగ సమాజంపై అర్థవంతమైన విమర్శేనా, లేక మరో జీవనశైలి ట్రెండేనా?","examples":[{"en":"While minimalism began as a protest against excess, it could be argued that the market has already repackaged anti-consumption as another expensive aesthetic to purchase.","native":"సరళ జీవనవాదం అధికతపై నిరసనగా ప్రారంభమైనప్పటికీ, మార్కెట్ వినియోగ వ్యతిరేకతను కొనుగోలు చేయదగిన మరో ఖరీదైన సౌందర్యంగా ఇప్పటికే పునర్ప్యాకేజ్ చేసిందని చెప్పవచ్చు."},{"en":"Admittedly, decluttering genuinely relieves some people; nevertheless, owning little is only a choice for those wealthy enough to replace anything they discard.","native":"నిజానికి గందరగోళం తొలగించడం కొందరికి నిజంగా ఉపశమనం ఇస్తుంది; అయినప్పటికీ, తక్కువ కలిగి ఉండడం తాము పడేసిన దేనినైనా భర్తీ చేయగలంత ధనవంతులకు మాత్రమే ఎంపిక."},{"en":"On balance, minimalism seems most convincing as a question—what do I actually need?—rather than as an identity, which risks becoming another form of competitive display.","native":"మొత్తానికి, సరళ జీవనవాదం గుర్తింపుగా కంటే ఒక ప్రశ్నగా—నాకు వాస్తవంగా ఏమి అవసరం?—అత్యంత నమ్మదగినంగా ఉంటుంది; గుర్తింపు పోటీ ప్రదర్శన యొక్క మరో రూపం కావడానికి ప్రమాదం ఉంది."}]},"hi":{"word":"न्यूनतमवाद","question":"क्या न्यूनतमवाद उपभोक्ता समाज की सार्थक आलोचना है, या बस एक और जीवनशैली का चलन?","examples":[{"en":"While minimalism began as a protest against excess, it could be argued that the market has already repackaged anti-consumption as another expensive aesthetic to purchase.","native":"जबकि न्यूनतमवाद अतिरिक्तता के विरुद्ध विरोध के रूप में शुरू हुआ, यह तर्क दिया जा सकता है कि बाज़ार ने उपभोग-विरोध को पहले ही खरीदने योग्य एक और महँगे सौंदर्य में फिर से पैक कर दिया है।"},{"en":"Admittedly, decluttering genuinely relieves some people; nevertheless, owning little is only a choice for those wealthy enough to replace anything they discard.","native":"यह स्वीकार करना होगा कि सामान घटाना कुछ लोगों को सचमुच राहत देता है; फिर भी, कम रखना केवल उन्हीं के लिए एक विकल्प है जो इतने धनी हैं कि फेंकी हुई हर चीज़ बदल सकें।"},{"en":"On balance, minimalism seems most convincing as a question—what do I actually need?—rather than as an identity, which risks becoming another form of competitive display.","native":"कुल मिलाकर, न्यूनतमवाद एक पहचान के बजाय एक प्रश्न के रूप में—मुझे वास्तव में क्या चाहिए?—सबसे अधिक ठोस लगता है; पहचान बनने पर यह प्रतिस्पर्धी प्रदर्शन का एक और रूप बनने का जोखिम रखता है।"}]},"es":{"word":"minimalismo","question":"¿Es el minimalismo una crítica significativa de la sociedad de consumo, o solo otra tendencia de estilo de vida?","examples":[{"en":"While minimalism began as a protest against excess, it could be argued that the market has already repackaged anti-consumption as another expensive aesthetic to purchase.","native":"Aunque el minimalismo comenzó como una protesta contra el exceso, podría argumentarse que el mercado ya ha reempaquetado el anticonsumo como otra estética cara que comprar."},{"en":"Admittedly, decluttering genuinely relieves some people; nevertheless, owning little is only a choice for those wealthy enough to replace anything they discard.","native":"Es cierto que ordenar y deshacerse de cosas alivia genuinamente a algunas personas; sin embargo, poseer poco solo es una opción para quienes son lo bastante ricos para reemplazar cualquier cosa que descarten."},{"en":"On balance, minimalism seems most convincing as a question—what do I actually need?—rather than as an identity, which risks becoming another form of competitive display.","native":"En definitiva, el minimalismo parece más convincente como pregunta —¿qué necesito realmente?— que como identidad, la cual arriesga convertirse en otra forma de exhibición competitiva."}]},"zh":{"word":"极简主义","question":"极简主义是对消费社会有意义的批判，还是仅仅是另一种生活方式潮流？","examples":[{"en":"While minimalism began as a protest against excess, it could be argued that the market has already repackaged anti-consumption as another expensive aesthetic to purchase.","native":"尽管极简主义始于对过度消费的抗议，但可以认为，市场已经把反消费重新包装成另一种可供购买的昂贵美学。"},{"en":"Admittedly, decluttering genuinely relieves some people; nevertheless, owning little is only a choice for those wealthy enough to replace anything they discard.","native":"诚然，断舍离确实能让一些人感到轻松；然而，少拥有只是那些富到可以替换任何丢弃之物的人才能做出的选择。"},{"en":"On balance, minimalism seems most convincing as a question—what do I actually need?—rather than as an identity, which risks becoming another form of competitive display.","native":"总体而言，极简主义作为一个问题——我究竟需要什么？——比作为一种身份更有说服力，因为后者有沦为另一种竞争性炫耀的风险。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'fame', 'Why do so many people desire fame, and does it deliver what they expect?', '{"te":{"word":"కీర్తి","question":"చాలామంది కీర్తిని ఎందుకు కోరుతారు, అది వారు ఊహించినది ఇస్తుందా?","examples":[{"en":"While fame promises validation on a grand scale, it could be argued that it mostly magnifies scrutiny, transforming ordinary mistakes into public spectacles overnight.","native":"కీర్తి భవ్యమైన స్థాయిలో గుర్తింపును వాగ్దానం చేసినప్పటికీ, అది ఎక్కువగా పరీక్షను పెంచుతుందని, సాధారణ పొరపాట్లను ఒక్కరాత్రిలో ప్రజా ప్రదర్శనలుగా మారుస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, celebrity confers influence and access; nevertheless, studies of the famous consistently report loneliness, distrust, and a disorienting confusion between persona and self.","native":"నిజానికి ప్రసిద్ధి ప్రభావాన్నీ అవకాశాలనూ ఇస్తుంది; అయినప్పటికీ, ప్రసిద్ధులపై అధ్యయనాలు ఒంటరితనాన్నీ, అవిశ్వాసాన్నీ, పాత్రకూ నిజస్వరూపానికీ మధ్య గందరగోళాన్నీ నిరంతరం నివేదిస్తాయి."},{"en":"On balance, people seem to crave not fame itself but the recognition it symbolises, a need that intimate communities once satisfied without any audience at all.","native":"మొత్తానికి, ప్రజలు కీర్తినే కాదు, అది సూచించే గుర్తింపును కోరుతారని అనిపిస్తుంది; ఎటువంటి ప్రేక్షకులూ లేకుండా గతంలో సన్నిహిత సమాజాలు తీర్చిన అవసరం ఇది."}]},"hi":{"word":"प्रसिद्धि","question":"इतने लोग प्रसिद्धि की चाह क्यों रखते हैं, और क्या यह वह देती है जिसकी वे उम्मीद करते हैं?","examples":[{"en":"While fame promises validation on a grand scale, it could be argued that it mostly magnifies scrutiny, transforming ordinary mistakes into public spectacles overnight.","native":"जबकि प्रसिद्धि भव्य स्तर पर मान्यता का वादा करती है, यह तर्क दिया जा सकता है कि यह ज्यादातर जाँच को बढ़ाती है, साधारण गलतियों को रातों-रात सार्वजनिक तमाशे में बदल देती है।"},{"en":"Admittedly, celebrity confers influence and access; nevertheless, studies of the famous consistently report loneliness, distrust, and a disorienting confusion between persona and self.","native":"यह स्वीकार करना होगा कि ख्याति प्रभाव और पहुँच देती है; फिर भी, प्रसिद्ध लोगों के अध्ययन लगातार अकेलापन, अविश्वास और व्यक्तित्व तथा असली स्व के बीच भ्रम की सूचना देते हैं।"},{"en":"On balance, people seem to crave not fame itself but the recognition it symbolises, a need that intimate communities once satisfied without any audience at all.","native":"कुल मिलाकर, लोग खुद प्रसिद्धि नहीं बल्कि उसके द्वारा प्रतीकित मान्यता के लालायित लगते हैं—यह ज़रूरत कभी घनिष्ठ समुदाय बिना किसी दर्शक के ही पूरी करते थे।"}]},"es":{"word":"fama","question":"¿Por qué desean la fama tantas personas, y les da lo que esperan?","examples":[{"en":"While fame promises validation on a grand scale, it could be argued that it mostly magnifies scrutiny, transforming ordinary mistakes into public spectacles overnight.","native":"Aunque la fama promete validación a gran escala, podría argumentarse que sobre todo magnifica el escrutinio, transformando errores ordinarios en espectáculos públicos de la noche a la mañana."},{"en":"Admittedly, celebrity confers influence and access; nevertheless, studies of the famous consistently report loneliness, distrust, and a disorienting confusion between persona and self.","native":"Es cierto que la celebridad confiere influencia y acceso; sin embargo, los estudios sobre los famosos reportan consistentemente soledad, desconfianza y una confusión desorientadora entre el personaje y el yo."},{"en":"On balance, people seem to crave not fame itself but the recognition it symbolises, a need that intimate communities once satisfied without any audience at all.","native":"En definitiva, la gente parece ansiar no la fama misma sino el reconocimiento que simboliza, una necesidad que las comunidades íntimas antes satisfacían sin público alguno."}]},"zh":{"word":"名声","question":"为什么那么多人渴望名声，它能带来他们所期待的东西吗？","examples":[{"en":"While fame promises validation on a grand scale, it could be argued that it mostly magnifies scrutiny, transforming ordinary mistakes into public spectacles overnight.","native":"尽管名声承诺了宏大的认可，但可以认为，它主要放大的是审视——一夜之间把普通的错误变成公众的围观。"},{"en":"Admittedly, celebrity confers influence and access; nevertheless, studies of the famous consistently report loneliness, distrust, and a disorienting confusion between persona and self.","native":"诚然，名气带来影响力和机会；然而，对名人的研究始终报告孤独、不信任，以及人设与自我之间令人迷失的混淆。"},{"en":"On balance, people seem to crave not fame itself but the recognition it symbolises, a need that intimate communities once satisfied without any audience at all.","native":"总体而言，人们渴望的似乎不是名声本身，而是它所象征的认可——这种需求，亲密的社群曾经无需任何观众就能满足。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'automation', 'Will automation ultimately create more jobs than it destroys, or is this time different?', '{"te":{"word":"స్వయంచాలకత","question":"స్వయంచాలకత చివరికి ధ్వంసం చేసిన దానికంటే ఎక్కువ ఉద్యోగాలను సృష్టిస్తుందా, లేక ఈసారి విషయం మరోలా ఉందా?","examples":[{"en":"While history suggests technology creates new occupations to replace obsolete ones, it could be argued that the speed of current automation may outpace retraining entirely.","native":"సాంకేతికత పాతబడినవాటి స్థానంలో కొత్త వృత్తులను సృష్టిస్తుందని చరిత్ర సూచించినప్పటికీ, ప్రస్తుత స్వయంచాలకత వేగం పునశ్శిక్షణను పూర్తిగా అధిగమించవచ్చని చెప్పవచ్చు."},{"en":"Admittedly, previous industrial revolutions produced more employment, not less; nevertheless, those transitions were measured in generations, whereas algorithmic displacement now happens within single careers.","native":"నిజానికి గత పారిశ్రామిక విప్లవాలు తక్కువ కాకుండా ఎక్కువ ఉద్యోగాలను ఇచ్చాయి; అయినప్పటికీ, ఆ మార్పులు తరాలలో కొలవబడ్డాయి, అయితే అల్గారిథమిక్ విస్థాపన ఇప్పుడు ఒకే వృత్తి లోపల జరుగుతుంది."},{"en":"On balance, the question seems less whether jobs will exist than who will capture their value, since productivity gains have lately flowed overwhelmingly to capital rather than labour.","native":"మొత్తానికి, ఉద్యోగాలు ఉంటాయా కాదా అన్నది కంటే వాటి విలువను ఎవరు పొందుతారు అన్నదే ప్రశ్న అనిపిస్తుంది, ఎందుకంటే ఉత్పాదకత లాభాలు ఇటీవల కార్మికుల కంటే మూలధనానికే అధికంగా ప్రవహించాయి."}]},"hi":{"word":"स्वचालन","question":"क्या स्वचालन अंततः नष्ट करने से ज़्यादा नौकरियाँ बनाएगा, या इस बार मामला अलग है?","examples":[{"en":"While history suggests technology creates new occupations to replace obsolete ones, it could be argued that the speed of current automation may outpace retraining entirely.","native":"जबकि इतिहास बताता है कि तकनीक अप्रचलित पेशों की जगह नए पेशे बनाती है, यह तर्क दिया जा सकता है कि मौजूदा स्वचालन की गति पुनःप्रशिक्षण को पूरी तरह पीछे छोड़ सकती है।"},{"en":"Admittedly, previous industrial revolutions produced more employment, not less; nevertheless, those transitions were measured in generations, whereas algorithmic displacement now happens within single careers.","native":"यह स्वीकार करना होगा कि पिछली औद्योगिक क्रांतियों ने कम नहीं, अधिक रोज़गार दिया; फिर भी, वे संक्रमण पीढ़ियों में मापे गए, जबकि एल्गोरिदमिक विस्थापन अब एक ही करियर के भीतर हो रहा है।"},{"en":"On balance, the question seems less whether jobs will exist than who will capture their value, since productivity gains have lately flowed overwhelmingly to capital rather than labour.","native":"कुल मिलाकर, सवाल यह कम लगता है कि नौकरियाँ रहेंगी या नहीं, और यह अधिक कि उनका मूल्य कौन हासिल करेगा, क्योंकि उत्पादकता लाभ हाल में श्रम के बजाय पूँजी की ओर भारी मात्रा में बहे हैं।"}]},"es":{"word":"automatización","question":"¿Creará la automatización en última instancia más empleos de los que destruye, o esta vez es diferente?","examples":[{"en":"While history suggests technology creates new occupations to replace obsolete ones, it could be argued that the speed of current automation may outpace retraining entirely.","native":"Aunque la historia sugiere que la tecnología crea nuevas ocupaciones para reemplazar las obsoletas, podría argumentarse que la velocidad de la automatización actual podría superar por completo a la recapacitación."},{"en":"Admittedly, previous industrial revolutions produced more employment, not less; nevertheless, those transitions were measured in generations, whereas algorithmic displacement now happens within single careers.","native":"Es cierto que las revoluciones industriales anteriores produjeron más empleo, no menos; sin embargo, esas transiciones se midieron en generaciones, mientras que el desplazamiento algorítmico ahora ocurre dentro de una sola carrera."},{"en":"On balance, the question seems less whether jobs will exist than who will capture their value, since productivity gains have lately flowed overwhelmingly to capital rather than labour.","native":"En definitiva, la cuestión parece menos si existirán empleos que quién capturará su valor, ya que las ganancias de productividad han fluido últimamente abrumadoramente hacia el capital y no hacia el trabajo."}]},"zh":{"word":"自动化","question":"自动化最终创造的就业岗位会多于它摧毁的吗，还是这一次情况不同？","examples":[{"en":"While history suggests technology creates new occupations to replace obsolete ones, it could be argued that the speed of current automation may outpace retraining entirely.","native":"尽管历史表明技术会创造新职业来取代过时的职业，但可以认为，当前自动化的速度可能会完全超过再培训的能力。"},{"en":"Admittedly, previous industrial revolutions produced more employment, not less; nevertheless, those transitions were measured in generations, whereas algorithmic displacement now happens within single careers.","native":"诚然，以往的工业革命带来的是更多而非更少的就业；然而，那些转型以世代为单位衡量，而算法驱动的岗位替代如今在一个人的职业生涯内就会发生。"},{"en":"On balance, the question seems less whether jobs will exist than who will capture their value, since productivity gains have lately flowed overwhelmingly to capital rather than labour.","native":"总体而言，问题似乎不在于工作是否还会存在，而在于谁能获取其价值——因为生产率收益近来压倒性地流向了资本而非劳动。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'biotechnology', 'Should there be limits on how far biotechnology can alter living organisms?', '{"te":{"word":"జీవసాంకేతికత","question":"జీవసాంకేతికత జీవులను ఎంతవరకు మార్చవచ్చో దానిపై పరిమితులు ఉండాలా?","examples":[{"en":"While biotechnology promises cures for devastating diseases, it could be argued that each advance quietly normalises interventions once considered unthinkable.","native":"జీవసాంకేతికత వినాశకరమైన వ్యాధులకు నయం చేసే హామీని ఇచ్చినప్పటికీ, ప్రతి పురోగతి గతంలో ఆలోచించలేని జోక్యాలను నిశ్శబ్దంగా సాధారణం చేస్తుందని చెప్పవచ్చు."},{"en":"Admittedly, regulating such research risks driving it underground or overseas; nevertheless, the absence of limits assumes a wisdom and restraint that history rarely justifies.","native":"నిజానికి అలాంటి పరిశోధనను నియంత్రించడం దాన్ని నెలక్రిందికి లేదా విదేశాలకు నెట్టే ప్రమాదం ఉంది; అయినప్పటికీ, పరిమితుల లేమి చరిత్ర అరుదుగా సమర్థించే వివేకం, సంయమనం ఊహిస్తుంది."},{"en":"On balance, limits seem unavoidable; the genuine debate concerns who sets them, scientists, governments, or citizens, and through what legitimate process.","native":"మొత్తానికి, పరిమితులు తప్పనిసరిగా అనిపిస్తాయి; నిజమైన చర్చ వాటిని ఎవరు నిర్ణయిస్తారు—శాస్త్రవేత్తలా, ప్రభుత్వాలా, పౌరులా—మరియు ఏ చట్టబద్ధ ప్రక్రియ ద్వారా అనే దాని గురించి."}]},"hi":{"word":"जैव प्रौद्योगिकी","question":"क्या जैव प्रौद्योगिकी जीवों को कितना बदल सकती है, इस पर सीमाएँ होनी चाहिए?","examples":[{"en":"While biotechnology promises cures for devastating diseases, it could be argued that each advance quietly normalises interventions once considered unthinkable.","native":"जबकि जैव प्रौद्योगिकी विनाशकारी रोगों के इलाज का वादा करती है, यह तर्क दिया जा सकता है कि हर प्रगति कभी अकल्पनीय माने गए हस्तक्षेपों को चुपचाप सामान्य बना देती है।"},{"en":"Admittedly, regulating such research risks driving it underground or overseas; nevertheless, the absence of limits assumes a wisdom and restraint that history rarely justifies.","native":"यह स्वीकार करना होगा कि ऐसे शोध को विनियमित करना उसे भूमिगत या विदेशों में धकेलने का जोखिम लाता है; फिर भी, सीमाओं की अनुपस्थिति वह बुद्धि और संयम मान लेती है जिसे इतिहास शायद ही कभी सही ठहराता है।"},{"en":"On balance, limits seem unavoidable; the genuine debate concerns who sets them, scientists, governments, or citizens, and through what legitimate process.","native":"कुल मिलाकर, सीमाएँ अपरिहार्य लगती हैं; असली बहस इस पर है कि उन्हें कौन तय करे—वैज्ञानिक, सरकारें या नागरिक—और किस वैध प्रक्रिया से।"}]},"es":{"word":"biotecnología","question":"¿Debería haber límites sobre hasta dónde puede la biotecnología alterar los organismos vivos?","examples":[{"en":"While biotechnology promises cures for devastating diseases, it could be argued that each advance quietly normalises interventions once considered unthinkable.","native":"Aunque la biotecnología promete curas para enfermedades devastadoras, podría argumentarse que cada avance normaliza silenciosamente intervenciones antes consideradas impensables."},{"en":"Admittedly, regulating such research risks driving it underground or overseas; nevertheless, the absence of limits assumes a wisdom and restraint that history rarely justifies.","native":"Es cierto que regular tal investigación arriesga empujarla a la clandestinidad o al extranjero; sin embargo, la ausencia de límites presupone una sabiduría y una contención que la historia rara vez justifica."},{"en":"On balance, limits seem unavoidable; the genuine debate concerns who sets them, scientists, governments, or citizens, and through what legitimate process.","native":"En definitiva, los límites parecen inevitables; el debate genuino concierne a quién los establece —científicos, gobiernos o ciudadanos— y mediante qué proceso legítimo."}]},"zh":{"word":"生物技术","question":"是否应当对生物技术改造生物体的程度设限？","examples":[{"en":"While biotechnology promises cures for devastating diseases, it could be argued that each advance quietly normalises interventions once considered unthinkable.","native":"尽管生物技术承诺治愈毁灭性的疾病，但可以认为，每一项进步都在悄然把曾经被认为不可想象的干预手段正常化。"},{"en":"Admittedly, regulating such research risks driving it underground or overseas; nevertheless, the absence of limits assumes a wisdom and restraint that history rarely justifies.","native":"诚然，监管此类研究有将其逼入地下或海外的风险；然而，不设限则假定了一种历史上鲜有依据的智慧与克制。"},{"en":"On balance, limits seem unavoidable; the genuine debate concerns who sets them, scientists, governments, or citizens, and through what legitimate process.","native":"总体而言，设限似乎不可避免；真正的争论在于由谁来设定——科学家、政府还是公民——以及通过何种合法程序。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'genetic engineering', 'Is it ethical to edit the genes of future generations who cannot consent?', '{"te":{"word":"జన్యు ఇంజినీరింగ్","question":"సమ్మతి ఇవ్వలేని భవిష్యత్ తరాల జన్యువులను సవరించడం నైతికమేనా?","examples":[{"en":"While eliminating inherited diseases seems obviously compassionate, it could be argued that germline editing crosses a threshold from healing patients to redesigning humanity itself.","native":"వంశపారంపర్య వ్యాధులను తొలగించడం స్పష్టంగా కరుణామయంగా అనిపించినప్పటికీ, జెర్మ్‌లైన్ ఎడిటింగ్ రోగులను నయం చేయడం నుండి మానవతనే పునర్రూపకల్పన చేయడానికి ఒక అడ్డంకిని దాటుతుందని చెప్పవచ్చు."},{"en":"Admittedly, parents already shape children through environment and schooling; nevertheless, genetic choices are irreversible across generations, which arguably demands a far higher standard of caution.","native":"నిజానికి తల్లిదండ్రులు వాతావరణం, విద్య ద్వారా పిల్లలను ఇప్పటికే ఆకారం ఇస్తారు; అయినప్పటికీ, జన్యు ఎంపికలు తరాలవారీగా రద్దు చేయలేనివి, అందుకే చాలా ఎక్కువ జాగ్రత్త ప్రమాణం అవసరమని చెప్పవచ్చు."},{"en":"On balance, the strongest objection seems not technical but social: engineered advantages could harden inequality into biology, making privilege literally hereditary.","native":"మొత్తానికి, అతిబలమైన అభ్యంతరం సాంకేతికం కాదు, సామాజికం: ఇంజినీర్ చేసిన అనుకూలతలు అసమానతను జీవశాస్త్రంలో గట్టిపరచి, ప్రత్యేక హక్కును అక్షరాలా వంశపారంపర్యం చేయవచ్చు."}]},"hi":{"word":"आनुवंशिक अभियांत्रिकी","question":"क्या उन भावी पीढ़ियों के जीन संपादित करना नैतिक है जो सहमति नहीं दे सकतीं?","examples":[{"en":"While eliminating inherited diseases seems obviously compassionate, it could be argued that germline editing crosses a threshold from healing patients to redesigning humanity itself.","native":"जबकि वंशानुगत रोगों को समाप्त करना स्पष्ट रूप से करुणामय लगता है, यह तर्क दिया जा सकता है कि जर्मलाइन संपादन रोगियों के इलाज से मानवता के पुनरडिज़ाइन की दहलीज़ पार कर जाता है।"},{"en":"Admittedly, parents already shape children through environment and schooling; nevertheless, genetic choices are irreversible across generations, which arguably demands a far higher standard of caution.","native":"यह स्वीकार करना होगा कि माता-पिता वातावरण और शिक्षा से बच्चों को पहले से आकार देते हैं; फिर भी, आनुवंशिक चुनाव पीढ़ियों में अपरिवर्तनीय हैं—जो तर्कतः कहीं अधिक सावधानी का मानक माँगता है।"},{"en":"On balance, the strongest objection seems not technical but social: engineered advantages could harden inequality into biology, making privilege literally hereditary.","native":"कुल मिलाकर, सबसे मज़बूत आपत्ति तकनीकी नहीं बल्कि सामाजिक लगती है: अभियांत्रित लाभ असमानता को जीवविज्ञान में गढ़ सकते हैं, विशेषाधिकार को शाब्दिक रूप से वंशानुगत बना सकते हैं।"}]},"es":{"word":"ingeniería genética","question":"¿Es ético editar los genes de generaciones futuras que no pueden dar su consentimiento?","examples":[{"en":"While eliminating inherited diseases seems obviously compassionate, it could be argued that germline editing crosses a threshold from healing patients to redesigning humanity itself.","native":"Aunque eliminar enfermedades hereditarias parece obviamente compasivo, podría argumentarse que la edición de la línea germinal cruza un umbral: de curar pacientes a rediseñar la humanidad misma."},{"en":"Admittedly, parents already shape children through environment and schooling; nevertheless, genetic choices are irreversible across generations, which arguably demands a far higher standard of caution.","native":"Es cierto que los padres ya moldean a los hijos mediante el entorno y la educación; sin embargo, las elecciones genéticas son irreversibles a través de las generaciones, lo que exige posiblemente un estándar de cautela mucho mayor."},{"en":"On balance, the strongest objection seems not technical but social: engineered advantages could harden inequality into biology, making privilege literally hereditary.","native":"En definitiva, la objeción más fuerte no parece técnica sino social: las ventajas diseñadas podrían endurecer la desigualdad hasta convertirla en biología, haciendo el privilegio literalmente hereditario."}]},"zh":{"word":"基因工程","question":"编辑无法表示同意的未来世代的基因是否合乎伦理？","examples":[{"en":"While eliminating inherited diseases seems obviously compassionate, it could be argued that germline editing crosses a threshold from healing patients to redesigning humanity itself.","native":"尽管消除遗传疾病显然富有同情心，但可以认为，生殖系基因编辑跨越了一道门槛——从治愈病人到重新设计人类本身。"},{"en":"Admittedly, parents already shape children through environment and schooling; nevertheless, genetic choices are irreversible across generations, which arguably demands a far higher standard of caution.","native":"诚然，父母早已通过环境和教育塑造孩子；然而，基因选择会跨世代不可逆转，这可以说要求远为更高的谨慎标准。"},{"en":"On balance, the strongest objection seems not technical but social: engineered advantages could harden inequality into biology, making privilege literally hereditary.","native":"总体而言，最有力的反对意见似乎不是技术性的，而是社会性的：人为设计的优势可能把不平等固化为生物学，让特权名副其实地世袭。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'neuroscience', 'How should discoveries in neuroscience influence our understanding of personal responsibility?', '{"te":{"word":"నాడీవిజ్ఞానం","question":"నాడీవిజ్ఞానంలో ఆవిష్కరణలు వ్యక్తిగత బాధ్యతపై మన అవగాహనను ఎలా ప్రభావితం చేయాలి?","examples":[{"en":"Evidence that the brain initiates actions before conscious awareness complicates, but does not necessarily eliminate, the idea of free will.","native":"చేతన అవగాహనకు ముందే మెదడు చర్యలను ప్రారంభిస్తుందనే ఆధారం స్వేచ్ఛా సంకల్ప భావనను సంక్లిష్టం చేస్తుంది, కానీ దాన్ని తప్పనిసరిగా తొలగించదు."},{"en":"Courts may reasonably consider neurological impairments, provided that scientific explanations do not become automatic excuses for harmful conduct.","native":"శాస్త్రీయ వివరణలు హానికర ప్రవర్తనకు స్వయంచాలక సాకులుగా మారకుండా ఉంటే, న్యాయస్థానాలు నాడీ సంబంధిత వైకల్యాలను సముచితంగా పరిగణించవచ్చు."},{"en":"Neuroscience is most valuable when it refines our judgments about capacity and rehabilitation rather than pretending to settle moral questions alone.","native":"నైతిక ప్రశ్నలను తానే పరిష్కరిస్తుందని చెప్పుకోవడం కంటే, సామర్థ్యం మరియు పునరావాసంపై మన నిర్ణయాలను మెరుగుపరిచినప్పుడు నాడీవిజ్ఞానం అత్యంత విలువైనది."}]},"hi":{"word":"तंत्रिका विज्ञान","question":"तंत्रिका विज्ञान की खोजों को व्यक्तिगत उत्तरदायित्व की हमारी समझ को कैसे प्रभावित करना चाहिए?","examples":[{"en":"Evidence that the brain initiates actions before conscious awareness complicates, but does not necessarily eliminate, the idea of free will.","native":"यह प्रमाण कि मस्तिष्क सचेत जागरूकता से पहले ही क्रियाएँ शुरू कर देता है, स्वतंत्र इच्छा की अवधारणा को जटिल बनाता है, लेकिन उसे अनिवार्य रूप से समाप्त नहीं करता।"},{"en":"Courts may reasonably consider neurological impairments, provided that scientific explanations do not become automatic excuses for harmful conduct.","native":"न्यायालय तंत्रिका संबंधी विकारों पर उचित रूप से विचार कर सकते हैं, बशर्ते वैज्ञानिक व्याख्याएँ हानिकारक आचरण के लिए स्वतः बहाना न बन जाएँ।"},{"en":"Neuroscience is most valuable when it refines our judgments about capacity and rehabilitation rather than pretending to settle moral questions alone.","native":"तंत्रिका विज्ञान तब सबसे उपयोगी है जब वह नैतिक प्रश्नों को अकेले सुलझाने का दावा करने के बजाय क्षमता और पुनर्वास पर हमारे निर्णयों को अधिक सूक्ष्म बनाता है।"}]},"es":{"word":"neurociencia","question":"¿Cómo deberían influir los descubrimientos de la neurociencia en nuestra comprensión de la responsabilidad personal?","examples":[{"en":"Evidence that the brain initiates actions before conscious awareness complicates, but does not necessarily eliminate, the idea of free will.","native":"La evidencia de que el cerebro inicia acciones antes de que seamos conscientes complica, pero no elimina necesariamente, la idea del libre albedrío."},{"en":"Courts may reasonably consider neurological impairments, provided that scientific explanations do not become automatic excuses for harmful conduct.","native":"Los tribunales pueden considerar razonablemente las alteraciones neurológicas, siempre que las explicaciones científicas no se conviertan en excusas automáticas para conductas dañinas."},{"en":"Neuroscience is most valuable when it refines our judgments about capacity and rehabilitation rather than pretending to settle moral questions alone.","native":"La neurociencia resulta más valiosa cuando afina nuestros juicios sobre la capacidad y la rehabilitación, en vez de pretender resolver por sí sola cuestiones morales."}]},"zh":{"word":"神经科学","question":"神经科学的发现应当如何影响我们对个人责任的理解？","examples":[{"en":"Evidence that the brain initiates actions before conscious awareness complicates, but does not necessarily eliminate, the idea of free will.","native":"大脑在意识察觉之前便启动行动的证据，使自由意志这一观念变得复杂，但并不必然将其否定。"},{"en":"Courts may reasonably consider neurological impairments, provided that scientific explanations do not become automatic excuses for harmful conduct.","native":"法院可以合理考虑神经功能障碍，前提是科学解释不会自动沦为有害行为的借口。"},{"en":"Neuroscience is most valuable when it refines our judgments about capacity and rehabilitation rather than pretending to settle moral questions alone.","native":"神经科学最有价值之处，在于完善我们对行为能力与康复的判断，而非声称仅凭自身就能解决道德问题。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'quantum computing', 'What opportunities and governance challenges could arise from quantum computing?', '{"te":{"word":"క్వాంటం కంప్యూటింగ్","question":"క్వాంటం కంప్యూటింగ్ వల్ల ఏ అవకాశాలు మరియు పాలనా సవాళ్లు తలెత్తవచ్చు?","examples":[{"en":"Quantum machines could transform drug discovery and materials science by modelling interactions that overwhelm conventional computers.","native":"సాంప్రదాయ కంప్యూటర్ల సామర్థ్యాన్ని మించే పరస్పర చర్యలను నమూనా చేయడం ద్వారా క్వాంటం యంత్రాలు ఔషధ ఆవిష్కరణను మరియు పదార్థ విజ్ఞానాన్ని మార్చగలవు."},{"en":"Their ability to break widely used encryption means governments must modernize digital infrastructure long before the technology becomes commonplace.","native":"విస్తృతంగా ఉపయోగించే సంకేతీకరణను ఛేదించే వాటి సామర్థ్యం కారణంగా, ఈ సాంకేతికత సాధారణమయ్యే చాలా ముందుగానే ప్రభుత్వాలు డిజిటల్ మౌలిక సదుపాయాలను ఆధునీకరించాలి."},{"en":"International standards could prevent a destabilizing race, yet excessive restrictions might concentrate expertise among a handful of powerful states and corporations.","native":"అంతర్జాతీయ ప్రమాణాలు అస్థిరత కలిగించే పోటీని నివారించగలవు, అయితే మితిమీరిన పరిమితులు కొద్దిమంది శక్తివంతమైన దేశాలు మరియు సంస్థల వద్ద నైపుణ్యాన్ని కేంద్రీకరించవచ్చు."}]},"hi":{"word":"क्वांटम कंप्यूटिंग","question":"क्वांटम कंप्यूटिंग से कौन-से अवसर और शासन संबंधी चुनौतियाँ उत्पन्न हो सकती हैं?","examples":[{"en":"Quantum machines could transform drug discovery and materials science by modelling interactions that overwhelm conventional computers.","native":"क्वांटम मशीनें उन अंतःक्रियाओं का मॉडल बनाकर औषधि खोज और पदार्थ विज्ञान को बदल सकती हैं जिन्हें पारंपरिक कंप्यूटर संभाल नहीं पाते।"},{"en":"Their ability to break widely used encryption means governments must modernize digital infrastructure long before the technology becomes commonplace.","native":"व्यापक रूप से प्रयुक्त कूटलेखन को तोड़ने की उनकी क्षमता का अर्थ है कि तकनीक के आम होने से बहुत पहले सरकारों को डिजिटल अवसंरचना आधुनिक बनानी होगी।"},{"en":"International standards could prevent a destabilizing race, yet excessive restrictions might concentrate expertise among a handful of powerful states and corporations.","native":"अंतरराष्ट्रीय मानक अस्थिर करने वाली होड़ को रोक सकते हैं, फिर भी अत्यधिक पाबंदियाँ विशेषज्ञता को कुछ शक्तिशाली देशों और कंपनियों तक सीमित कर सकती हैं।"}]},"es":{"word":"computación cuántica","question":"¿Qué oportunidades y desafíos de gobernanza podría plantear la computación cuántica?","examples":[{"en":"Quantum machines could transform drug discovery and materials science by modelling interactions that overwhelm conventional computers.","native":"Las máquinas cuánticas podrían transformar el descubrimiento de fármacos y la ciencia de materiales al modelar interacciones que desbordan a los ordenadores convencionales."},{"en":"Their ability to break widely used encryption means governments must modernize digital infrastructure long before the technology becomes commonplace.","native":"Su capacidad para vulnerar sistemas de cifrado ampliamente utilizados implica que los gobiernos deben modernizar la infraestructura digital mucho antes de que la tecnología se generalice."},{"en":"International standards could prevent a destabilizing race, yet excessive restrictions might concentrate expertise among a handful of powerful states and corporations.","native":"Las normas internacionales podrían evitar una carrera desestabilizadora, pero unas restricciones excesivas podrían concentrar los conocimientos en unos pocos Estados y empresas poderosos."}]},"zh":{"word":"量子计算","question":"量子计算可能带来哪些机遇与治理挑战？","examples":[{"en":"Quantum machines could transform drug discovery and materials science by modelling interactions that overwhelm conventional computers.","native":"量子计算机能够模拟传统计算机难以处理的相互作用，从而可能彻底改变药物研发与材料科学。"},{"en":"Their ability to break widely used encryption means governments must modernize digital infrastructure long before the technology becomes commonplace.","native":"量子计算破解常用加密方式的能力意味着，各国政府必须在该技术普及之前很久就着手升级数字基础设施。"},{"en":"International standards could prevent a destabilizing race, yet excessive restrictions might concentrate expertise among a handful of powerful states and corporations.","native":"国际标准或可防止破坏稳定的竞赛，但过度限制也可能使专业能力集中在少数强国和大型企业手中。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'energy transition', 'How can societies make the energy transition both rapid and socially fair?', '{"te":{"word":"ఇంధన పరివర్తన","question":"సమాజాలు ఇంధన పరివర్తనను వేగవంతంగానూ సామాజికంగా న్యాయసమ్మతంగానూ ఎలా చేయగలవు?","examples":[{"en":"Carbon pricing can accelerate cleaner investment, but households with low incomes need protection from sudden increases in essential costs.","native":"కార్బన్ ధర నిర్ణయం స్వచ్ఛమైన పెట్టుబడులను వేగవంతం చేయగలదు, కానీ తక్కువ ఆదాయం గల కుటుంబాలకు అవసరమైన ఖర్చుల ఆకస్మిక పెరుగుదల నుంచి రక్షణ అవసరం."},{"en":"Regions dependent on fossil-fuel industries require credible retraining, infrastructure, and long-term employment rather than temporary compensation alone.","native":"శిలాజ ఇంధన పరిశ్రమలపై ఆధారపడిన ప్రాంతాలకు తాత్కాలిక పరిహారం మాత్రమే కాకుండా విశ్వసనీయమైన పునశ్శిక్షణ, మౌలిక సదుపాయాలు మరియు దీర్ఘకాలిక ఉపాధి అవసరం."},{"en":"A fair transition distributes not only its costs but also the ownership and benefits of renewable energy across communities.","native":"న్యాయమైన పరివర్తన దాని ఖర్చులను మాత్రమే కాకుండా పునరుత్పాదక ఇంధన యాజమాన్యాన్ని మరియు ప్రయోజనాలను కూడా సమాజాల మధ్య పంచుతుంది."}]},"hi":{"word":"ऊर्जा संक्रमण","question":"समाज ऊर्जा संक्रमण को तेज़ और सामाजिक रूप से न्यायपूर्ण दोनों कैसे बना सकते हैं?","examples":[{"en":"Carbon pricing can accelerate cleaner investment, but households with low incomes need protection from sudden increases in essential costs.","native":"कार्बन मूल्य निर्धारण स्वच्छ निवेश को तेज़ कर सकता है, लेकिन कम आय वाले परिवारों को आवश्यक खर्चों में अचानक वृद्धि से सुरक्षा चाहिए।"},{"en":"Regions dependent on fossil-fuel industries require credible retraining, infrastructure, and long-term employment rather than temporary compensation alone.","native":"जीवाश्म ईंधन उद्योगों पर निर्भर क्षेत्रों को केवल अस्थायी मुआवज़े के बजाय विश्वसनीय पुनःप्रशिक्षण, बुनियादी ढाँचा और दीर्घकालिक रोज़गार चाहिए।"},{"en":"A fair transition distributes not only its costs but also the ownership and benefits of renewable energy across communities.","native":"न्यायपूर्ण संक्रमण केवल अपनी लागत ही नहीं, बल्कि नवीकरणीय ऊर्जा का स्वामित्व और लाभ भी समुदायों में बाँटता है।"}]},"es":{"word":"transición energética","question":"¿Cómo pueden las sociedades lograr que la transición energética sea rápida y socialmente justa?","examples":[{"en":"Carbon pricing can accelerate cleaner investment, but households with low incomes need protection from sudden increases in essential costs.","native":"Fijar un precio al carbono puede acelerar la inversión limpia, pero los hogares con bajos ingresos necesitan protección frente a aumentos repentinos de los gastos esenciales."},{"en":"Regions dependent on fossil-fuel industries require credible retraining, infrastructure, and long-term employment rather than temporary compensation alone.","native":"Las regiones dependientes de las industrias de combustibles fósiles necesitan reciclaje profesional, infraestructura y empleo duradero creíbles, no solo compensaciones temporales."},{"en":"A fair transition distributes not only its costs but also the ownership and benefits of renewable energy across communities.","native":"Una transición justa distribuye entre las comunidades no solo sus costes, sino también la propiedad y los beneficios de la energía renovable."}]},"zh":{"word":"能源转型","question":"社会如何才能让能源转型既迅速又兼顾社会公平？","examples":[{"en":"Carbon pricing can accelerate cleaner investment, but households with low incomes need protection from sudden increases in essential costs.","native":"碳定价能够加快清洁投资，但低收入家庭需要得到保护，以免基本生活成本突然上涨。"},{"en":"Regions dependent on fossil-fuel industries require credible retraining, infrastructure, and long-term employment rather than temporary compensation alone.","native":"依赖化石燃料产业的地区需要可信的再培训、基础设施和长期就业，而不能只有临时补偿。"},{"en":"A fair transition distributes not only its costs but also the ownership and benefits of renewable energy across communities.","native":"公平转型不仅要分担成本，还要让不同社区共享可再生能源的所有权与收益。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'circular economy', 'Can a circular economy reconcile continued prosperity with ecological limits?', '{"te":{"word":"వలయాకార ఆర్థిక వ్యవస్థ","question":"వలయాకార ఆర్థిక వ్యవస్థ నిరంతర శ్రేయస్సును పర్యావరణ పరిమితులతో సమన్వయం చేయగలదా?","examples":[{"en":"Designing products for repair and reuse can reduce extraction, although it requires manufacturers to abandon profitable planned obsolescence.","native":"మరమ్మత్తు మరియు పునర్వినియోగం కోసం ఉత్పత్తులను రూపొందించడం వనరుల వెలికితీతను తగ్గించగలదు, అయితే లాభదాయకమైన ప్రణాళికాబద్ధ వాడుకకాల పరిమితిని తయారీదారులు వదులుకోవాలి."},{"en":"Recycling alone cannot sustain endless consumption because every material cycle loses quality, energy, or usable volume.","native":"ప్రతి పదార్థ చక్రంలో నాణ్యత, శక్తి లేదా ఉపయోగించగల పరిమాణం తగ్గుతుంది కాబట్టి, పునర్వినియోగ ప్రక్రియ ఒక్కటే అంతులేని వినియోగాన్ని కొనసాగించలేదు."},{"en":"The circular model is persuasive when it changes ownership, incentives, and design, not when it merely gives disposable goods a greener label.","native":"విసిరివేసే వస్తువులకు కేవలం పచ్చని ముద్ర వేయకుండా, యాజమాన్యం, ప్రోత్సాహకాలు మరియు రూపకల్పనను మార్చినప్పుడే వలయాకార నమూనా నమ్మదగినదిగా ఉంటుంది."}]},"hi":{"word":"चक्रीय अर्थव्यवस्था","question":"क्या चक्रीय अर्थव्यवस्था निरंतर समृद्धि को पारिस्थितिक सीमाओं के साथ समेट सकती है?","examples":[{"en":"Designing products for repair and reuse can reduce extraction, although it requires manufacturers to abandon profitable planned obsolescence.","native":"उत्पादों को मरम्मत और पुनःउपयोग योग्य बनाने से संसाधनों का दोहन घट सकता है, हालांकि इसके लिए निर्माताओं को लाभदायक नियोजित अप्रचलन छोड़ना होगा।"},{"en":"Recycling alone cannot sustain endless consumption because every material cycle loses quality, energy, or usable volume.","native":"केवल पुनर्चक्रण अंतहीन उपभोग को बनाए नहीं रख सकता, क्योंकि सामग्री के हर चक्र में गुणवत्ता, ऊर्जा या उपयोग योग्य मात्रा घटती है।"},{"en":"The circular model is persuasive when it changes ownership, incentives, and design, not when it merely gives disposable goods a greener label.","native":"चक्रीय मॉडल तब विश्वसनीय है जब वह स्वामित्व, प्रोत्साहन और डिज़ाइन बदलता है, न कि तब जब वह फेंकने योग्य वस्तुओं पर केवल हरित लेबल लगा देता है।"}]},"es":{"word":"economía circular","question":"¿Puede una economía circular conciliar una prosperidad continuada con los límites ecológicos?","examples":[{"en":"Designing products for repair and reuse can reduce extraction, although it requires manufacturers to abandon profitable planned obsolescence.","native":"Diseñar productos reparables y reutilizables puede reducir la extracción, aunque exige que los fabricantes abandonen la rentable obsolescencia programada."},{"en":"Recycling alone cannot sustain endless consumption because every material cycle loses quality, energy, or usable volume.","native":"El reciclaje por sí solo no puede sostener un consumo infinito, pues cada ciclo de los materiales pierde calidad, energía o volumen aprovechable."},{"en":"The circular model is persuasive when it changes ownership, incentives, and design, not when it merely gives disposable goods a greener label.","native":"El modelo circular resulta convincente cuando cambia la propiedad, los incentivos y el diseño, no cuando se limita a poner una etiqueta más verde a bienes desechables."}]},"zh":{"word":"循环经济","question":"循环经济能否使持续繁荣与生态限度相协调？","examples":[{"en":"Designing products for repair and reuse can reduce extraction, although it requires manufacturers to abandon profitable planned obsolescence.","native":"将产品设计成可维修、可重复使用的形式能够减少资源开采，但这要求制造商放弃有利可图的计划性报废。"},{"en":"Recycling alone cannot sustain endless consumption because every material cycle loses quality, energy, or usable volume.","native":"仅靠回收无法维持无止境的消费，因为材料每循环一次都会损失质量、能量或可用体量。"},{"en":"The circular model is persuasive when it changes ownership, incentives, and design, not when it merely gives disposable goods a greener label.","native":"循环模式只有在改变所有权、激励机制和设计时才有说服力，而不是仅给一次性商品贴上更环保的标签。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'geopolitical tension', 'How can governments manage geopolitical tension without normalizing permanent confrontation?', '{"te":{"word":"భౌగోళిక రాజకీయ ఉద్రిక్తత","question":"శాశ్వత ఘర్షణను సాధారణీకరించకుండా ప్రభుత్వాలు భౌగోళిక రాజకీయ ఉద్రిక్తతను ఎలా నిర్వహించగలవు?","examples":[{"en":"Deterrence may prevent immediate aggression, but unchecked military buildup can make miscalculation more likely and compromise harder.","native":"నిరోధక శక్తి తక్షణ దాడిని అడ్డుకోవచ్చు, కానీ నియంత్రణలేని సైనిక విస్తరణ తప్పుడు అంచనాల అవకాశాన్ని పెంచి రాజీని కష్టతరం చేయగలదు."},{"en":"Reliable crisis hotlines and limited technical agreements preserve communication even when broader political relations have deteriorated.","native":"విస్తృత రాజకీయ సంబంధాలు క్షీణించినప్పటికీ, విశ్వసనీయ సంక్షోభ ప్రత్యక్ష సంప్రదింపు మార్గాలు మరియు పరిమిత సాంకేతిక ఒప్పందాలు సంభాషణను కొనసాగిస్తాయి."},{"en":"Leaders should distinguish genuine security interests from symbolic disputes that domestic politics rewards them for escalating.","native":"దేశీయ రాజకీయాలు తీవ్రతరం చేయడాన్ని ప్రోత్సహించే ప్రతీకాత్మక వివాదాల నుంచి నిజమైన భద్రతా ప్రయోజనాలను నాయకులు వేరు చేయాలి."}]},"hi":{"word":"भू-राजनीतिक तनाव","question":"स्थायी टकराव को सामान्य बनाए बिना सरकारें भू-राजनीतिक तनाव का प्रबंधन कैसे कर सकती हैं?","examples":[{"en":"Deterrence may prevent immediate aggression, but unchecked military buildup can make miscalculation more likely and compromise harder.","native":"प्रतिरोध तत्काल आक्रमण रोक सकता है, लेकिन अनियंत्रित सैन्य विस्तार गलत आकलन की आशंका बढ़ा सकता है और समझौते को कठिन बना सकता है।"},{"en":"Reliable crisis hotlines and limited technical agreements preserve communication even when broader political relations have deteriorated.","native":"विश्वसनीय संकट हॉटलाइन और सीमित तकनीकी समझौते तब भी संवाद बनाए रखते हैं जब व्यापक राजनीतिक संबंध बिगड़ चुके हों।"},{"en":"Leaders should distinguish genuine security interests from symbolic disputes that domestic politics rewards them for escalating.","native":"नेताओं को वास्तविक सुरक्षा हितों और उन प्रतीकात्मक विवादों में अंतर करना चाहिए जिन्हें बढ़ाने पर घरेलू राजनीति उन्हें लाभ देती है।"}]},"es":{"word":"tensión geopolítica","question":"¿Cómo pueden los gobiernos gestionar la tensión geopolítica sin normalizar una confrontación permanente?","examples":[{"en":"Deterrence may prevent immediate aggression, but unchecked military buildup can make miscalculation more likely and compromise harder.","native":"La disuasión puede impedir una agresión inmediata, pero una acumulación militar sin control aumenta el riesgo de errores de cálculo y dificulta los acuerdos."},{"en":"Reliable crisis hotlines and limited technical agreements preserve communication even when broader political relations have deteriorated.","native":"Las líneas directas de crisis fiables y los acuerdos técnicos limitados mantienen la comunicación incluso cuando las relaciones políticas generales se han deteriorado."},{"en":"Leaders should distinguish genuine security interests from symbolic disputes that domestic politics rewards them for escalating.","native":"Los dirigentes deberían distinguir los intereses de seguridad genuinos de las disputas simbólicas cuya escalada les recompensa la política interna."}]},"zh":{"word":"地缘政治紧张局势","question":"各国政府如何在不使长期对抗常态化的前提下管控地缘政治紧张局势？","examples":[{"en":"Deterrence may prevent immediate aggression, but unchecked military buildup can make miscalculation more likely and compromise harder.","native":"威慑或许能阻止眼前的侵略，但不受约束的扩军会增加误判的可能，也会使妥协更加困难。"},{"en":"Reliable crisis hotlines and limited technical agreements preserve communication even when broader political relations have deteriorated.","native":"即使整体政治关系已经恶化，可靠的危机热线和有限的技术协议仍能维持沟通。"},{"en":"Leaders should distinguish genuine security interests from symbolic disputes that domestic politics rewards them for escalating.","native":"领导人应区分真正的安全利益与象征性争端，后者往往因国内政治奖励升级行为而被放大。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'diplomacy', 'What makes diplomacy effective when the parties fundamentally distrust one another?', '{"te":{"word":"దౌత్యం","question":"పక్షాలు ఒకరినొకరు ప్రాథమికంగా అవిశ్వసించినప్పుడు దౌత్యాన్ని ప్రభావవంతంగా చేసేది ఏమిటి?","examples":[{"en":"Successful diplomacy does not require affection; it requires verifiable commitments whose benefits exceed the political cost of cooperation.","native":"విజయవంతమైన దౌత్యానికి పరస్పర అభిమానం అవసరం లేదు; సహకారం వల్ల కలిగే రాజకీయ వ్యయం కంటే ఎక్కువ ప్రయోజనాలు అందించే, ధృవీకరించగల కట్టుబాట్లు అవసరం."},{"en":"Skilled negotiators identify narrow shared interests first, allowing modest agreements to establish a record of predictable behavior.","native":"నైపుణ్యమైన చర్చాకర్తలు ముందుగా పరిమితమైన ఉమ్మడి ప్రయోజనాలను గుర్తించి, చిన్న ఒప్పందాల ద్వారా ఊహించదగిన ప్రవర్తనకు ఒక చరిత్రను ఏర్పరుస్తారు."},{"en":"Private channels can enable candor and compromise, although secrecy becomes corrosive when it excludes those who must implement the outcome.","native":"రహస్య మార్గాలు నిష్కపటతకు మరియు రాజీకి వీలు కల్పించగలవు, అయితే ఫలితాన్ని అమలు చేయాల్సిన వారిని మినహాయించినప్పుడు గోప్యత హానికరంగా మారుతుంది."}]},"hi":{"word":"कूटनीति","question":"जब पक्ष एक-दूसरे पर मूल रूप से अविश्वास करते हों, तब कूटनीति को प्रभावी क्या बनाता है?","examples":[{"en":"Successful diplomacy does not require affection; it requires verifiable commitments whose benefits exceed the political cost of cooperation.","native":"सफल कूटनीति के लिए लगाव नहीं, बल्कि ऐसी सत्यापन योग्य प्रतिबद्धताएँ चाहिए जिनके लाभ सहयोग की राजनीतिक कीमत से अधिक हों।"},{"en":"Skilled negotiators identify narrow shared interests first, allowing modest agreements to establish a record of predictable behavior.","native":"कुशल वार्ताकार पहले सीमित साझा हित पहचानते हैं, जिससे छोटे समझौते पूर्वानुमेय व्यवहार का इतिहास बना सकें।"},{"en":"Private channels can enable candor and compromise, although secrecy becomes corrosive when it excludes those who must implement the outcome.","native":"निजी संवाद स्पष्टवादिता और समझौते को संभव बना सकता है, हालांकि जब गोपनीयता परिणाम लागू करने वालों को बाहर रखती है तो वह हानिकारक हो जाती है।"}]},"es":{"word":"diplomacia","question":"¿Qué hace eficaz a la diplomacia cuando las partes desconfían profundamente unas de otras?","examples":[{"en":"Successful diplomacy does not require affection; it requires verifiable commitments whose benefits exceed the political cost of cooperation.","native":"La diplomacia eficaz no requiere afecto, sino compromisos verificables cuyos beneficios superen el coste político de cooperar."},{"en":"Skilled negotiators identify narrow shared interests first, allowing modest agreements to establish a record of predictable behavior.","native":"Los negociadores hábiles identifican primero intereses compartidos concretos, de modo que acuerdos modestos establezcan un historial de conducta previsible."},{"en":"Private channels can enable candor and compromise, although secrecy becomes corrosive when it excludes those who must implement the outcome.","native":"Los canales privados pueden facilitar la franqueza y el acuerdo, aunque el secreto se vuelve corrosivo cuando excluye a quienes deben aplicar el resultado."}]},"zh":{"word":"外交","question":"当各方从根本上互不信任时，什么能使外交取得成效？","examples":[{"en":"Successful diplomacy does not require affection; it requires verifiable commitments whose benefits exceed the political cost of cooperation.","native":"成功的外交不需要彼此亲近，而需要可核实的承诺，且其收益必须超过合作所付出的政治代价。"},{"en":"Skilled negotiators identify narrow shared interests first, allowing modest agreements to establish a record of predictable behavior.","native":"娴熟的谈判者会先找出范围有限的共同利益，通过适度协议逐步建立行为可预测的记录。"},{"en":"Private channels can enable candor and compromise, although secrecy becomes corrosive when it excludes those who must implement the outcome.","native":"私下渠道可以促成坦诚与妥协，但如果保密将负责落实结果的人排除在外，就会产生破坏作用。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'polarization', 'Why does political polarization persist even when citizens agree on many practical concerns?', '{"te":{"word":"రాజకీయ ధ్రువీకరణ","question":"అనేక ఆచరణాత్మక సమస్యలపై పౌరులు ఏకీభవించినప్పటికీ రాజకీయ ధ్రువీకరణ ఎందుకు కొనసాగుతుంది?","examples":[{"en":"Partisan identity can become a social allegiance, so conceding a policy point feels like betraying one''s community rather than revising an opinion.","native":"పక్షపాత గుర్తింపు సామాజిక విధేయతగా మారవచ్చు, అందువల్ల ఒక విధాన అంశాన్ని అంగీకరించడం అభిప్రాయాన్ని సవరించడం కంటే తన సమాజాన్ని మోసం చేసినట్లుగా అనిపిస్తుంది."},{"en":"Electoral systems and media incentives often reward vivid conflict, while quieter areas of consensus attract little attention or funding.","native":"ఎన్నికల వ్యవస్థలు మరియు మీడియా ప్రోత్సాహకాలు తరచూ తీవ్రమైన ఘర్షణను పురస్కరిస్తాయి, అయితే నిశ్శబ్దంగా ఉన్న ఏకాభిప్రాయ అంశాలకు తక్కువ శ్రద్ధ లేదా నిధులు లభిస్తాయి."},{"en":"Reducing polarization therefore requires repeated cross-group cooperation, not merely exposing people to one more set of facts.","native":"కాబట్టి ధ్రువీకరణను తగ్గించడానికి ప్రజలకు మరొక వాస్తవాల సమాహారాన్ని చూపించడం మాత్రమే కాకుండా, వర్గాల మధ్య పునరావృత సహకారం అవసరం."}]},"hi":{"word":"राजनीतिक ध्रुवीकरण","question":"कई व्यावहारिक चिंताओं पर नागरिकों की सहमति होने के बावजूद राजनीतिक ध्रुवीकरण क्यों बना रहता है?","examples":[{"en":"Partisan identity can become a social allegiance, so conceding a policy point feels like betraying one''s community rather than revising an opinion.","native":"दलगत पहचान सामाजिक निष्ठा बन सकती है, इसलिए किसी नीतिगत बात को स्वीकार करना राय बदलने के बजाय अपने समुदाय से विश्वासघात जैसा लगता है।"},{"en":"Electoral systems and media incentives often reward vivid conflict, while quieter areas of consensus attract little attention or funding.","native":"चुनावी व्यवस्थाएँ और मीडिया के प्रोत्साहन अक्सर तीखे टकराव को पुरस्कृत करते हैं, जबकि सहमति के शांत क्षेत्रों को बहुत कम ध्यान या धन मिलता है।"},{"en":"Reducing polarization therefore requires repeated cross-group cooperation, not merely exposing people to one more set of facts.","native":"इसलिए ध्रुवीकरण घटाने के लिए समूहों के बीच बार-बार सहयोग चाहिए, केवल लोगों के सामने तथ्यों का एक और समूह रख देना पर्याप्त नहीं है।"}]},"es":{"word":"polarización","question":"¿Por qué persiste la polarización política incluso cuando la ciudadanía coincide en muchas cuestiones prácticas?","examples":[{"en":"Partisan identity can become a social allegiance, so conceding a policy point feels like betraying one''s community rather than revising an opinion.","native":"La identidad partidista puede convertirse en una lealtad social, de modo que conceder un punto político parece traicionar a la propia comunidad en vez de revisar una opinión."},{"en":"Electoral systems and media incentives often reward vivid conflict, while quieter areas of consensus attract little attention or funding.","native":"Los sistemas electorales y los incentivos mediáticos suelen premiar el conflicto visible, mientras que los ámbitos discretos de consenso apenas reciben atención o financiación."},{"en":"Reducing polarization therefore requires repeated cross-group cooperation, not merely exposing people to one more set of facts.","native":"Reducir la polarización exige, por tanto, una cooperación reiterada entre grupos, no solo exponer a la gente a otro conjunto de datos."}]},"zh":{"word":"政治极化","question":"即使公民在许多实际问题上意见一致，政治极化为何仍会持续？","examples":[{"en":"Partisan identity can become a social allegiance, so conceding a policy point feels like betraying one''s community rather than revising an opinion.","native":"党派身份可能演变成社会归属，因此在政策观点上让步会让人觉得是在背叛自己的群体，而不是修正看法。"},{"en":"Electoral systems and media incentives often reward vivid conflict, while quieter areas of consensus attract little attention or funding.","native":"选举制度和媒体激励往往奖励鲜明的冲突，而较为平静的共识领域却很少获得关注或资金。"},{"en":"Reducing polarization therefore requires repeated cross-group cooperation, not merely exposing people to one more set of facts.","native":"因此，缓解极化需要不同群体反复合作，而不只是再向人们提供一组事实。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'populism', 'Under what conditions does populism strengthen democracy, and when does it undermine it?', '{"te":{"word":"ప్రజాకర్షకవాదం","question":"ఏ పరిస్థితుల్లో ప్రజాకర్షకవాదం ప్రజాస్వామ్యాన్ని బలోపేతం చేస్తుంది, ఎప్పుడు దాన్ని బలహీనపరుస్తుంది?","examples":[{"en":"Populist movements can force neglected grievances onto the agenda and challenge institutions that have become insulated from ordinary citizens.","native":"ప్రజాకర్షక ఉద్యమాలు నిర్లక్ష్యం చేసిన సమస్యలను కార్యాచరణలోకి తీసుకురాగలవు మరియు సాధారణ పౌరులకు దూరమైన సంస్థలను ప్రశ్నించగలవు."},{"en":"They become dangerous when a leader claims exclusive ownership of the popular will and portrays every institutional restraint as illegitimate.","native":"ఒక నాయకుడు ప్రజాసంకల్పంపై తనకే ప్రత్యేక హక్కు ఉందని ప్రకటించి, ప్రతి సంస్థాగత నియంత్రణను చట్టవిరుద్ధంగా చిత్రించినప్పుడు అవి ప్రమాదకరంగా మారతాయి."},{"en":"Democracies should address the failures that fuel populism while defending pluralism, judicial independence, and the rights of political minorities.","native":"ప్రజాస్వామ్యాలు ప్రజాకర్షకవాదానికి ఊతమిచ్చే వైఫల్యాలను పరిష్కరిస్తూనే బహుళత్వం, న్యాయవ్యవస్థ స్వతంత్రత మరియు రాజకీయ అల్పసంఖ్యాకుల హక్కులను కాపాడాలి."}]},"hi":{"word":"लोकलुभावनवाद","question":"किन परिस्थितियों में लोकलुभावनवाद लोकतंत्र को मज़बूत करता है और कब उसे कमज़ोर करता है?","examples":[{"en":"Populist movements can force neglected grievances onto the agenda and challenge institutions that have become insulated from ordinary citizens.","native":"लोकलुभावन आंदोलन उपेक्षित शिकायतों को कार्यसूची में ला सकते हैं और उन संस्थाओं को चुनौती दे सकते हैं जो आम नागरिकों से कट गई हैं।"},{"en":"They become dangerous when a leader claims exclusive ownership of the popular will and portrays every institutional restraint as illegitimate.","native":"वे तब खतरनाक हो जाते हैं जब कोई नेता जन-इच्छा पर एकाधिकार का दावा करता है और हर संस्थागत अंकुश को अवैध बताता है।"},{"en":"Democracies should address the failures that fuel populism while defending pluralism, judicial independence, and the rights of political minorities.","native":"लोकतंत्रों को लोकलुभावनवाद को बढ़ावा देने वाली विफलताओं का समाधान करते हुए बहुलवाद, न्यायिक स्वतंत्रता और राजनीतिक अल्पसंख्यकों के अधिकारों की रक्षा करनी चाहिए।"}]},"es":{"word":"populismo","question":"¿En qué condiciones fortalece el populismo la democracia y cuándo la debilita?","examples":[{"en":"Populist movements can force neglected grievances onto the agenda and challenge institutions that have become insulated from ordinary citizens.","native":"Los movimientos populistas pueden incorporar agravios desatendidos a la agenda y cuestionar instituciones que se han aislado de la ciudadanía común."},{"en":"They become dangerous when a leader claims exclusive ownership of the popular will and portrays every institutional restraint as illegitimate.","native":"Se vuelven peligrosos cuando un dirigente se atribuye en exclusiva la voluntad popular y presenta todo límite institucional como ilegítimo."},{"en":"Democracies should address the failures that fuel populism while defending pluralism, judicial independence, and the rights of political minorities.","native":"Las democracias deben corregir los fallos que alimentan el populismo a la vez que defienden el pluralismo, la independencia judicial y los derechos de las minorías políticas."}]},"zh":{"word":"民粹主义","question":"民粹主义在什么条件下会巩固民主，又在何时会损害民主？","examples":[{"en":"Populist movements can force neglected grievances onto the agenda and challenge institutions that have become insulated from ordinary citizens.","native":"民粹运动能够迫使被忽视的不满进入公共议程，并挑战那些已与普通公民隔绝的机构。"},{"en":"They become dangerous when a leader claims exclusive ownership of the popular will and portrays every institutional restraint as illegitimate.","native":"当某位领导人声称自己垄断民意，并把一切制度约束都描绘成不合法时，这类运动便会变得危险。"},{"en":"Democracies should address the failures that fuel populism while defending pluralism, judicial independence, and the rights of political minorities.","native":"民主制度应在解决助长民粹主义的失误之余，捍卫多元主义、司法独立与政治少数群体的权利。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'misinformation', 'How should open societies counter misinformation without suppressing legitimate disagreement?', '{"te":{"word":"తప్పుడు సమాచారం","question":"చట్టబద్ధమైన భిన్నాభిప్రాయాన్ని అణచివేయకుండా బహిరంగ సమాజాలు తప్పుడు సమాచారాన్ని ఎలా ఎదుర్కోవాలి?","examples":[{"en":"Rapid corrections matter, but they are more credible when independent experts explain both what is known and where uncertainty remains.","native":"త్వరిత సవరణలు ముఖ్యమైనవి, కానీ స్వతంత్ర నిపుణులు తెలిసిన విషయంతో పాటు అనిశ్చితి ఎక్కడ ఉందో వివరించినప్పుడు అవి మరింత విశ్వసనీయంగా ఉంటాయి."},{"en":"Platforms can reduce algorithmic amplification of demonstrably false claims without appointing themselves the final arbiters of every contested opinion.","native":"వివాదాస్పదమైన ప్రతి అభిప్రాయానికి తామే తుది నిర్ణేతలుగా మారకుండా, స్పష్టంగా తప్పుడు వాదనల అల్గారిథమిక్ వ్యాప్తిని వేదికలు తగ్గించగలవు."},{"en":"Long-term resilience depends on trustworthy institutions and media literacy, since censorship can leave the underlying demand for conspiratorial narratives untouched.","native":"దీర్ఘకాలిక ప్రతిఘటన విశ్వసనీయ సంస్థలు మరియు మీడియా అవగాహనపై ఆధారపడి ఉంటుంది, ఎందుకంటే సెన్సార్‌షిప్ కుట్ర కథనాల పట్ల ఉన్న అంతర్లీన ఆకర్షణను మార్చకపోవచ్చు."}]},"hi":{"word":"भ्रामक सूचना","question":"खुले समाज वैध असहमति को दबाए बिना भ्रामक सूचनाओं का सामना कैसे करें?","examples":[{"en":"Rapid corrections matter, but they are more credible when independent experts explain both what is known and where uncertainty remains.","native":"तुरंत सुधार महत्त्वपूर्ण हैं, लेकिन वे तब अधिक विश्वसनीय होते हैं जब स्वतंत्र विशेषज्ञ यह भी समझाएँ कि क्या ज्ञात है और अनिश्चितता कहाँ बनी हुई है।"},{"en":"Platforms can reduce algorithmic amplification of demonstrably false claims without appointing themselves the final arbiters of every contested opinion.","native":"मंच स्पष्ट रूप से झूठे दावों के एल्गोरिदमिक प्रसार को घटा सकते हैं, बिना स्वयं को हर विवादित राय का अंतिम निर्णायक बनाए।"},{"en":"Long-term resilience depends on trustworthy institutions and media literacy, since censorship can leave the underlying demand for conspiratorial narratives untouched.","native":"दीर्घकालिक दृढ़ता विश्वसनीय संस्थाओं और मीडिया साक्षरता पर निर्भर करती है, क्योंकि सेंसरशिप षड्यंत्रकारी कथाओं की मूल माँग को जस का तस छोड़ सकती है।"}]},"es":{"word":"desinformación","question":"¿Cómo deberían las sociedades abiertas combatir la desinformación sin reprimir el desacuerdo legítimo?","examples":[{"en":"Rapid corrections matter, but they are more credible when independent experts explain both what is known and where uncertainty remains.","native":"Las rectificaciones rápidas importan, pero resultan más creíbles cuando expertos independientes explican tanto lo que se sabe como los aspectos que siguen siendo inciertos."},{"en":"Platforms can reduce algorithmic amplification of demonstrably false claims without appointing themselves the final arbiters of every contested opinion.","native":"Las plataformas pueden reducir la amplificación algorítmica de afirmaciones manifiestamente falsas sin erigirse en árbitros finales de toda opinión controvertida."},{"en":"Long-term resilience depends on trustworthy institutions and media literacy, since censorship can leave the underlying demand for conspiratorial narratives untouched.","native":"La resiliencia a largo plazo depende de instituciones fiables y de la alfabetización mediática, pues la censura puede dejar intacta la demanda subyacente de relatos conspirativos."}]},"zh":{"word":"虚假信息","question":"开放社会应如何在不压制正当异议的情况下应对虚假信息？","examples":[{"en":"Rapid corrections matter, but they are more credible when independent experts explain both what is known and where uncertainty remains.","native":"及时纠错固然重要，但如果独立专家既说明已知事实，也交代仍存在哪些不确定性，纠错会更可信。"},{"en":"Platforms can reduce algorithmic amplification of demonstrably false claims without appointing themselves the final arbiters of every contested opinion.","native":"平台可以减少算法对明显虚假主张的放大，而不必把自己任命为一切争议观点的最终裁判。"},{"en":"Long-term resilience depends on trustworthy institutions and media literacy, since censorship can leave the underlying demand for conspiratorial narratives untouched.","native":"长期韧性取决于值得信赖的机构与媒体素养，因为审查可能丝毫未触及人们对阴谋叙事的深层需求。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'algorithmic bias', 'Who should be accountable when algorithmic bias produces discriminatory outcomes?', '{"te":{"word":"అల్గారిథమిక్ పక్షపాతం","question":"అల్గారిథమిక్ పక్షపాతం వివక్షాపూరిత ఫలితాలను కలిగించినప్పుడు ఎవరు బాధ్యత వహించాలి?","examples":[{"en":"Responsibility should extend beyond the programmer to organizations that select training data, define objectives, and deploy systems in consequential settings.","native":"శిక్షణ డేటాను ఎంచుకునే, లక్ష్యాలను నిర్వచించే మరియు కీలక సందర్భాల్లో వ్యవస్థలను అమలు చేసే సంస్థల వరకు బాధ్యత ప్రోగ్రామర్‌ను దాటి విస్తరించాలి."},{"en":"Regular independent audits can reveal unequal error rates, but affected people also need a practical right to explanation and appeal.","native":"క్రమమైన స్వతంత్ర తనిఖీలు అసమాన దోషాల రేట్లను బయటపెట్టగలవు, కానీ ప్రభావితులైన వారికి వివరణ మరియు అప్పీల్‌కు ఆచరణాత్మక హక్కు కూడా అవసరం."},{"en":"A technically accurate model may still be unjust if it reproduces historical disadvantage or optimizes a poorly chosen social goal.","native":"సాంకేతికంగా ఖచ్చితమైన నమూనా కూడా చారిత్రక వెనుకబాటుతనాన్ని పునరుత్పత్తి చేస్తే లేదా తప్పుగా ఎంచుకున్న సామాజిక లక్ష్యాన్ని అనుకూలపరిస్తే అన్యాయంగా ఉండవచ్చు."}]},"hi":{"word":"एल्गोरिदमिक पक्षपात","question":"जब एल्गोरिदमिक पक्षपात भेदभावपूर्ण परिणाम पैदा करे, तो किसे जवाबदेह ठहराया जाना चाहिए?","examples":[{"en":"Responsibility should extend beyond the programmer to organizations that select training data, define objectives, and deploy systems in consequential settings.","native":"जिम्मेदारी प्रोग्रामर से आगे उन संगठनों तक जानी चाहिए जो प्रशिक्षण डेटा चुनते हैं, उद्देश्य तय करते हैं और महत्त्वपूर्ण परिस्थितियों में प्रणालियाँ लागू करते हैं।"},{"en":"Regular independent audits can reveal unequal error rates, but affected people also need a practical right to explanation and appeal.","native":"नियमित स्वतंत्र जाँच असमान त्रुटि दरें उजागर कर सकती है, लेकिन प्रभावित लोगों को स्पष्टीकरण और अपील का व्यावहारिक अधिकार भी चाहिए।"},{"en":"A technically accurate model may still be unjust if it reproduces historical disadvantage or optimizes a poorly chosen social goal.","native":"तकनीकी रूप से सटीक मॉडल भी अन्यायपूर्ण हो सकता है यदि वह ऐतिहासिक वंचना दोहराता है या गलत चुने गए सामाजिक लक्ष्य को अनुकूलित करता है।"}]},"es":{"word":"sesgo algorítmico","question":"¿Quién debería rendir cuentas cuando el sesgo algorítmico produce resultados discriminatorios?","examples":[{"en":"Responsibility should extend beyond the programmer to organizations that select training data, define objectives, and deploy systems in consequential settings.","native":"La responsabilidad debería ir más allá del programador y alcanzar a las organizaciones que eligen los datos de entrenamiento, definen objetivos e implantan sistemas en contextos trascendentes."},{"en":"Regular independent audits can reveal unequal error rates, but affected people also need a practical right to explanation and appeal.","native":"Las auditorías independientes periódicas pueden revelar tasas de error desiguales, pero las personas afectadas también necesitan un derecho efectivo a recibir explicaciones y recurrir."},{"en":"A technically accurate model may still be unjust if it reproduces historical disadvantage or optimizes a poorly chosen social goal.","native":"Un modelo técnicamente preciso puede seguir siendo injusto si reproduce desventajas históricas u optimiza un objetivo social mal elegido."}]},"zh":{"word":"算法偏见","question":"当算法偏见导致歧视性结果时，应由谁承担责任？","examples":[{"en":"Responsibility should extend beyond the programmer to organizations that select training data, define objectives, and deploy systems in consequential settings.","native":"责任不应止于程序员，还应延伸到选择训练数据、设定目标并在重大场景中部署系统的组织。"},{"en":"Regular independent audits can reveal unequal error rates, but affected people also need a practical right to explanation and appeal.","native":"定期独立审计可以揭示不均等的错误率，但受影响者还需要切实可行的知情与申诉权。"},{"en":"A technically accurate model may still be unjust if it reproduces historical disadvantage or optimizes a poorly chosen social goal.","native":"技术上准确的模型若复制历史劣势，或优化一个选择不当的社会目标，仍可能是不公正的。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'digital divide', 'How has the digital divide evolved beyond simple access to technology?', '{"te":{"word":"డిజిటల్ అంతరం","question":"సాంకేతికతకు కేవలం ప్రాప్యత అనే అంశాన్ని దాటి డిజిటల్ అంతరం ఎలా పరిణామం చెందింది?","examples":[{"en":"Owning a device is insufficient when connections are unreliable, interfaces are inaccessible, or users lack the confidence to evaluate online information.","native":"ఇంటర్నెట్ అనుసంధానం నమ్మదగనిదిగా ఉన్నప్పుడు, అంతర్ముఖాలు అందుబాటులో లేనప్పుడు లేదా ఆన్‌లైన్ సమాచారాన్ని అంచనా వేసే ఆత్మవిశ్వాసం వినియోగదారులకు లేనప్పుడు పరికరం కలిగి ఉండటం మాత్రమే సరిపోదు."},{"en":"As education, employment, and public services move online, unequal digital capability increasingly translates into unequal citizenship.","native":"విద్య, ఉపాధి మరియు ప్రజా సేవలు ఆన్‌లైన్‌కు మారుతున్న కొద్దీ, అసమాన డిజిటల్ సామర్థ్యం పౌరసత్వంలో అసమానతగా మరింతగా మారుతోంది."},{"en":"Effective policy combines affordable infrastructure with accessible design, local-language content, and sustained opportunities to develop critical digital skills.","native":"సమర్థవంతమైన విధానం చవకైన మౌలిక సదుపాయాలతో పాటు అందుబాటులో ఉండే రూపకల్పన, స్థానిక భాషా విషయం మరియు విమర్శనాత్మక డిజిటల్ నైపుణ్యాలను అభివృద్ధి చేసుకునే నిరంతర అవకాశాలను కలుపుతుంది."}]},"hi":{"word":"डिजिटल विभाजन","question":"डिजिटल विभाजन केवल तकनीक तक पहुँच के प्रश्न से आगे किस प्रकार विकसित हुआ है?","examples":[{"en":"Owning a device is insufficient when connections are unreliable, interfaces are inaccessible, or users lack the confidence to evaluate online information.","native":"सिर्फ उपकरण होना पर्याप्त नहीं है यदि कनेक्शन अविश्वसनीय हों, इंटरफ़ेस सुगम न हों या उपयोगकर्ताओं में ऑनलाइन जानकारी परखने का आत्मविश्वास न हो।"},{"en":"As education, employment, and public services move online, unequal digital capability increasingly translates into unequal citizenship.","native":"शिक्षा, रोज़गार और सार्वजनिक सेवाओं के ऑनलाइन होने के साथ असमान डिजिटल क्षमता नागरिकता की असमानता में तेजी से बदल रही है।"},{"en":"Effective policy combines affordable infrastructure with accessible design, local-language content, and sustained opportunities to develop critical digital skills.","native":"प्रभावी नीति किफायती बुनियादी ढाँचे को सुगम डिज़ाइन, स्थानीय भाषाओं की सामग्री और आलोचनात्मक डिजिटल कौशल विकसित करने के निरंतर अवसरों से जोड़ती है।"}]},"es":{"word":"brecha digital","question":"¿Cómo ha evolucionado la brecha digital más allá del simple acceso a la tecnología?","examples":[{"en":"Owning a device is insufficient when connections are unreliable, interfaces are inaccessible, or users lack the confidence to evaluate online information.","native":"Tener un dispositivo no basta cuando las conexiones son poco fiables, las interfaces no son accesibles o los usuarios carecen de confianza para evaluar información en línea."},{"en":"As education, employment, and public services move online, unequal digital capability increasingly translates into unequal citizenship.","native":"A medida que la educación, el empleo y los servicios públicos pasan a internet, la desigual capacidad digital se traduce cada vez más en una ciudadanía desigual."},{"en":"Effective policy combines affordable infrastructure with accessible design, local-language content, and sustained opportunities to develop critical digital skills.","native":"Una política eficaz combina infraestructura asequible con diseño accesible, contenidos en idiomas locales y oportunidades continuas para desarrollar competencias digitales críticas."}]},"zh":{"word":"数字鸿沟","question":"数字鸿沟如何演变为一个超越单纯技术接入的问题？","examples":[{"en":"Owning a device is insufficient when connections are unreliable, interfaces are inaccessible, or users lack the confidence to evaluate online information.","native":"如果网络连接不可靠、界面缺乏无障碍设计，或用户没有信心判断网上信息，那么拥有设备仍远远不够。"},{"en":"As education, employment, and public services move online, unequal digital capability increasingly translates into unequal citizenship.","native":"随着教育、就业和公共服务转移到线上，数字能力的不平等正日益转化为公民参与权的不平等。"},{"en":"Effective policy combines affordable infrastructure with accessible design, local-language content, and sustained opportunities to develop critical digital skills.","native":"有效政策应将可负担的基础设施、无障碍设计、本地语言内容以及持续培养批判性数字技能的机会结合起来。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'intellectual property', 'How should intellectual property rules balance creative incentives with public access to knowledge?', '{"te":{"word":"మేధో సంపత్తి","question":"మేధో సంపత్తి నియమాలు సృజనాత్మక ప్రోత్సాహకాలను జ్ఞానానికి ప్రజా ప్రాప్యతతో ఎలా సమతుల్యం చేయాలి?","examples":[{"en":"Temporary exclusivity can reward costly innovation, yet protection that lasts too long may obstruct research and entrench dominant firms.","native":"తాత్కాలిక ప్రత్యేక హక్కు ఖరీదైన ఆవిష్కరణకు ప్రతిఫలం ఇవ్వగలదు, అయితే అతిగా సాగే రక్షణ పరిశోధనను అడ్డుకుని ఆధిపత్య సంస్థలను స్థిరపరచవచ్చు."},{"en":"Exceptions for education, parody, and essential medicines recognize that ideas create value partly through circulation and adaptation.","native":"విద్య, వ్యంగ్యరచన మరియు అత్యవసర ఔషధాలకు మినహాయింపులు ఇవ్వడం ద్వారా ఆలోచనలు వ్యాప్తి మరియు అనుసరణ ద్వారానే కొంత విలువను సృష్టిస్తాయని గుర్తించబడుతుంది."},{"en":"Reform should distinguish independent creators from powerful intermediaries that often acquire rights without producing the original work.","native":"అసలు కృతిని సృష్టించకుండానే తరచూ హక్కులను పొందే శక్తివంతమైన మధ్యవర్తుల నుంచి స్వతంత్ర సృష్టికర్తలను సంస్కరణ వేరు చేయాలి."}]},"hi":{"word":"बौद्धिक संपदा","question":"बौद्धिक संपदा के नियम रचनात्मक प्रोत्साहनों और ज्ञान तक सार्वजनिक पहुँच के बीच संतुलन कैसे बनाएँ?","examples":[{"en":"Temporary exclusivity can reward costly innovation, yet protection that lasts too long may obstruct research and entrench dominant firms.","native":"अस्थायी विशिष्ट अधिकार महँगे नवाचार को पुरस्कृत कर सकते हैं, फिर भी बहुत लंबी सुरक्षा शोध में बाधा डाल सकती है और प्रभावशाली कंपनियों की स्थिति मज़बूत कर सकती है।"},{"en":"Exceptions for education, parody, and essential medicines recognize that ideas create value partly through circulation and adaptation.","native":"शिक्षा, पैरोडी और आवश्यक दवाओं के लिए अपवाद यह मानते हैं कि विचार प्रसार और अनुकूलन के माध्यम से भी मूल्य पैदा करते हैं।"},{"en":"Reform should distinguish independent creators from powerful intermediaries that often acquire rights without producing the original work.","native":"सुधार में स्वतंत्र रचनाकारों को उन शक्तिशाली मध्यस्थों से अलग समझना चाहिए जो मूल कृति बनाए बिना अक्सर अधिकार हासिल कर लेते हैं।"}]},"es":{"word":"propiedad intelectual","question":"¿Cómo deberían las normas de propiedad intelectual equilibrar los incentivos a la creación y el acceso público al conocimiento?","examples":[{"en":"Temporary exclusivity can reward costly innovation, yet protection that lasts too long may obstruct research and entrench dominant firms.","native":"La exclusividad temporal puede recompensar una innovación costosa, pero una protección demasiado prolongada puede obstaculizar la investigación y afianzar a empresas dominantes."},{"en":"Exceptions for education, parody, and essential medicines recognize that ideas create value partly through circulation and adaptation.","native":"Las excepciones para la educación, la parodia y los medicamentos esenciales reconocen que las ideas crean valor en parte mediante su circulación y adaptación."},{"en":"Reform should distinguish independent creators from powerful intermediaries that often acquire rights without producing the original work.","native":"La reforma debería distinguir a los creadores independientes de los intermediarios poderosos que suelen adquirir derechos sin producir la obra original."}]},"zh":{"word":"知识产权","question":"知识产权规则应如何平衡创作激励与公众获取知识的权利？","examples":[{"en":"Temporary exclusivity can reward costly innovation, yet protection that lasts too long may obstruct research and entrench dominant firms.","native":"临时专有权可以回报成本高昂的创新，但保护期过长可能阻碍研究，并巩固市场支配企业的地位。"},{"en":"Exceptions for education, parody, and essential medicines recognize that ideas create value partly through circulation and adaptation.","native":"为教育、戏仿和基本药物设置例外，承认思想的价值有一部分来自传播与再创造。"},{"en":"Reform should distinguish independent creators from powerful intermediaries that often acquire rights without producing the original work.","native":"改革应区分独立创作者与强势中介机构，后者往往并未创作原作却获得了相关权利。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'scientific literacy', 'What does scientific literacy require beyond remembering scientific facts?', '{"te":{"word":"శాస్త్రీయ అవగాహన","question":"శాస్త్రీయ వాస్తవాలను గుర్తుంచుకోవడాన్ని దాటి శాస్త్రీయ అవగాహనకు ఇంకేమి అవసరం?","examples":[{"en":"A scientifically literate person can interpret probability, question a study''s design, and distinguish correlation from a plausible causal claim.","native":"శాస్త్రీయ అవగాహన ఉన్న వ్యక్తి సంభావ్యతను అర్థం చేసుకోగలడు, అధ్యయన రూపకల్పనను ప్రశ్నించగలడు మరియు సహసంబంధాన్ని సమంజసమైన కారణ వాదన నుంచి వేరు చేయగలడు."},{"en":"Literacy also involves accepting provisional conclusions while remaining willing to revise them when stronger evidence emerges.","native":"బలమైన ఆధారం వెలుగులోకి వచ్చినప్పుడు తాత్కాలిక నిర్ధారణలను సవరించడానికి సిద్ధంగా ఉంటూనే వాటిని అంగీకరించడం కూడా ఈ అవగాహనలో భాగం."},{"en":"Schools should teach how scientific institutions correct errors, because disagreement among researchers is often a feature of inquiry rather than proof of failure.","native":"పరిశోధకుల మధ్య విభేదం తరచూ వైఫల్యానికి రుజువు కాకుండా అన్వేషణలో భాగం కాబట్టి, శాస్త్రీయ సంస్థలు తప్పులను ఎలా సరిదిద్దుతాయో పాఠశాలలు బోధించాలి."}]},"hi":{"word":"वैज्ञानिक साक्षरता","question":"वैज्ञानिक तथ्यों को याद रखने से आगे वैज्ञानिक साक्षरता के लिए क्या आवश्यक है?","examples":[{"en":"A scientifically literate person can interpret probability, question a study''s design, and distinguish correlation from a plausible causal claim.","native":"वैज्ञानिक रूप से साक्षर व्यक्ति प्रायिकता समझ सकता है, अध्ययन की रूपरेखा पर सवाल उठा सकता है और सहसंबंध को संभाव्य कारणात्मक दावे से अलग कर सकता है।"},{"en":"Literacy also involves accepting provisional conclusions while remaining willing to revise them when stronger evidence emerges.","native":"साक्षरता में अस्थायी निष्कर्षों को स्वीकार करना और अधिक मज़बूत प्रमाण मिलने पर उन्हें संशोधित करने को तैयार रहना भी शामिल है।"},{"en":"Schools should teach how scientific institutions correct errors, because disagreement among researchers is often a feature of inquiry rather than proof of failure.","native":"विद्यालयों को सिखाना चाहिए कि वैज्ञानिक संस्थाएँ त्रुटियाँ कैसे सुधारती हैं, क्योंकि शोधकर्ताओं की असहमति अक्सर विफलता का प्रमाण नहीं बल्कि जाँच की विशेषता होती है।"}]},"es":{"word":"alfabetización científica","question":"¿Qué exige la alfabetización científica además de recordar hechos científicos?","examples":[{"en":"A scientifically literate person can interpret probability, question a study''s design, and distinguish correlation from a plausible causal claim.","native":"Una persona con alfabetización científica puede interpretar probabilidades, cuestionar el diseño de un estudio y distinguir la correlación de una afirmación causal verosímil."},{"en":"Literacy also involves accepting provisional conclusions while remaining willing to revise them when stronger evidence emerges.","native":"La alfabetización también implica aceptar conclusiones provisionales y mantener la disposición a revisarlas cuando surjan pruebas más sólidas."},{"en":"Schools should teach how scientific institutions correct errors, because disagreement among researchers is often a feature of inquiry rather than proof of failure.","native":"Las escuelas deberían enseñar cómo corrigen errores las instituciones científicas, porque el desacuerdo entre investigadores suele ser propio de la indagación y no una prueba de fracaso."}]},"zh":{"word":"科学素养","question":"除了记住科学事实，科学素养还要求什么？","examples":[{"en":"A scientifically literate person can interpret probability, question a study''s design, and distinguish correlation from a plausible causal claim.","native":"具备科学素养的人能够理解概率、质疑研究设计，并区分相关性与看似合理的因果主张。"},{"en":"Literacy also involves accepting provisional conclusions while remaining willing to revise them when stronger evidence emerges.","native":"科学素养还包括接受暂时性结论，同时愿意在更有力的证据出现时修正结论。"},{"en":"Schools should teach how scientific institutions correct errors, because disagreement among researchers is often a feature of inquiry rather than proof of failure.","native":"学校应教授科学机构如何纠错，因为研究者之间的分歧往往是探究过程的特征，而不是科学失败的证据。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'public trust', 'How can public institutions rebuild trust after a serious failure?', '{"te":{"word":"ప్రజా విశ్వాసం","question":"తీవ్రమైన వైఫల్యం తర్వాత ప్రజా సంస్థలు విశ్వాసాన్ని ఎలా పునర్నిర్మించగలవు?","examples":[{"en":"A credible apology acknowledges specific harm and responsibility instead of using vague language that protects the institution''s image.","native":"విశ్వసనీయమైన క్షమాపణ సంస్థ ప్రతిష్ఠను కాపాడే అస్పష్టమైన భాషను ఉపయోగించకుండా, నిర్దిష్టమైన హానిని మరియు బాధ్యతను అంగీకరిస్తుంది."},{"en":"Independent investigation matters only if its findings are published and followed by visible changes to personnel, incentives, or procedures.","native":"స్వతంత్ర దర్యాప్తు ఫలితాలు ప్రచురించబడి, సిబ్బంది, ప్రోత్సాహకాలు లేదా విధానాల్లో స్పష్టమైన మార్పులు వచ్చినప్పుడే దానికి ప్రాముఖ్యత ఉంటుంది."},{"en":"Trust returns gradually when institutions make modest promises, report measurable progress, and tolerate scrutiny from those they previously disappointed.","native":"సంస్థలు పరిమితమైన హామీలు ఇచ్చి, కొలవగల పురోగతిని నివేదించి, గతంలో నిరాశపరిచిన వారి పరిశీలనను సహించినప్పుడు విశ్వాసం క్రమంగా తిరిగి వస్తుంది."}]},"hi":{"word":"जन विश्वास","question":"गंभीर विफलता के बाद सार्वजनिक संस्थाएँ विश्वास कैसे फिर से बना सकती हैं?","examples":[{"en":"A credible apology acknowledges specific harm and responsibility instead of using vague language that protects the institution''s image.","native":"विश्वसनीय क्षमा-याचना संस्था की छवि बचाने वाली अस्पष्ट भाषा के बजाय हुए विशिष्ट नुकसान और जिम्मेदारी को स्वीकार करती है।"},{"en":"Independent investigation matters only if its findings are published and followed by visible changes to personnel, incentives, or procedures.","native":"स्वतंत्र जाँच तभी सार्थक है जब उसके निष्कर्ष प्रकाशित हों और उनके बाद कर्मचारियों, प्रोत्साहनों या प्रक्रियाओं में स्पष्ट बदलाव दिखाई दें।"},{"en":"Trust returns gradually when institutions make modest promises, report measurable progress, and tolerate scrutiny from those they previously disappointed.","native":"विश्वास धीरे-धीरे लौटता है जब संस्थाएँ सीमित वादे करती हैं, मापने योग्य प्रगति बताती हैं और उन लोगों की जाँच सहती हैं जिन्हें उन्होंने पहले निराश किया था।"}]},"es":{"word":"confianza pública","question":"¿Cómo pueden las instituciones públicas recuperar la confianza después de un fallo grave?","examples":[{"en":"A credible apology acknowledges specific harm and responsibility instead of using vague language that protects the institution''s image.","native":"Una disculpa creíble reconoce el daño concreto y la responsabilidad, en lugar de emplear un lenguaje vago que proteja la imagen de la institución."},{"en":"Independent investigation matters only if its findings are published and followed by visible changes to personnel, incentives, or procedures.","native":"Una investigación independiente solo importa si se publican sus conclusiones y estas se traducen en cambios visibles de personal, incentivos o procedimientos."},{"en":"Trust returns gradually when institutions make modest promises, report measurable progress, and tolerate scrutiny from those they previously disappointed.","native":"La confianza regresa gradualmente cuando las instituciones hacen promesas modestas, informan de avances medibles y aceptan el escrutinio de quienes decepcionaron."}]},"zh":{"word":"公众信任","question":"公共机构在发生严重失误后应如何重建信任？","examples":[{"en":"A credible apology acknowledges specific harm and responsibility instead of using vague language that protects the institution''s image.","native":"可信的道歉会承认具体伤害与责任，而不是用模糊措辞维护机构形象。"},{"en":"Independent investigation matters only if its findings are published and followed by visible changes to personnel, incentives, or procedures.","native":"独立调查只有在结果公布，并推动人员、激励机制或程序发生可见变化时才有意义。"},{"en":"Trust returns gradually when institutions make modest promises, report measurable progress, and tolerate scrutiny from those they previously disappointed.","native":"当机构作出审慎承诺、报告可衡量的进展，并接受曾被其辜负者的监督时，信任才会逐渐恢复。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'civil disobedience', 'When, if ever, is civil disobedience justified in a constitutional democracy?', '{"te":{"word":"పౌర అవిధేయత","question":"రాజ్యాంగ ప్రజాస్వామ్యంలో పౌర అవిధేయత ఎప్పుడు, అసలు ఎప్పుడైనా, సమర్థనీయమవుతుంది?","examples":[{"en":"Breaking a law may be defensible when the injustice is grave, ordinary remedies have failed, and the action remains proportionate to its aim.","native":"అన్యాయం తీవ్రమై, సాధారణ పరిష్కారాలు విఫలమై, చర్య తన లక్ష్యానికి అనుపాతంగా ఉన్నప్పుడు చట్టాన్ని ఉల్లంఘించడం సమర్థనీయమవచ్చు."},{"en":"Nonviolence and a willingness to accept legal consequences can demonstrate respect for the broader constitutional order while contesting a particular rule.","native":"అహింస మరియు చట్టపరమైన పరిణామాలను స్వీకరించే సిద్ధత ఒక నిర్దిష్ట నియమాన్ని వ్యతిరేకిస్తూనే విస్తృత రాజ్యాంగ వ్యవస్థకు గౌరవాన్ని చూపగలవు."},{"en":"However, romanticizing disobedience ignores the possibility that rival groups will invoke the same principle for profoundly anti-democratic causes.","native":"అయితే, అవిధేయతను ఆదర్శీకరించడం ద్వారా ప్రత్యర్థి వర్గాలు అదే సూత్రాన్ని తీవ్ర ప్రజాస్వామ్య వ్యతిరేక లక్ష్యాలకు ఉపయోగించే అవకాశాన్ని విస్మరిస్తాం."}]},"hi":{"word":"सविनय अवज्ञा","question":"संवैधानिक लोकतंत्र में सविनय अवज्ञा कब, यदि कभी, उचित है?","examples":[{"en":"Breaking a law may be defensible when the injustice is grave, ordinary remedies have failed, and the action remains proportionate to its aim.","native":"कानून तोड़ना तब उचित ठहराया जा सकता है जब अन्याय गंभीर हो, सामान्य उपाय विफल हो चुके हों और कार्रवाई अपने उद्देश्य के अनुपात में हो।"},{"en":"Nonviolence and a willingness to accept legal consequences can demonstrate respect for the broader constitutional order while contesting a particular rule.","native":"अहिंसा और कानूनी परिणाम स्वीकार करने की तत्परता किसी विशेष नियम का विरोध करते हुए व्यापक संवैधानिक व्यवस्था के प्रति सम्मान दिखा सकती है।"},{"en":"However, romanticizing disobedience ignores the possibility that rival groups will invoke the same principle for profoundly anti-democratic causes.","native":"हालाँकि, अवज्ञा का महिमामंडन इस संभावना को अनदेखा करता है कि प्रतिद्वंद्वी समूह उसी सिद्धांत का इस्तेमाल घोर अलोकतांत्रिक उद्देश्यों के लिए करेंगे।"}]},"es":{"word":"desobediencia civil","question":"¿Cuándo, si acaso, está justificada la desobediencia civil en una democracia constitucional?","examples":[{"en":"Breaking a law may be defensible when the injustice is grave, ordinary remedies have failed, and the action remains proportionate to its aim.","native":"Incumplir una ley puede ser defendible cuando la injusticia es grave, las vías ordinarias han fracasado y la acción sigue siendo proporcional a su objetivo."},{"en":"Nonviolence and a willingness to accept legal consequences can demonstrate respect for the broader constitutional order while contesting a particular rule.","native":"La no violencia y la disposición a aceptar consecuencias legales pueden demostrar respeto por el orden constitucional general mientras se impugna una norma concreta."},{"en":"However, romanticizing disobedience ignores the possibility that rival groups will invoke the same principle for profoundly anti-democratic causes.","native":"Sin embargo, idealizar la desobediencia ignora la posibilidad de que grupos rivales invoquen el mismo principio para causas profundamente antidemocráticas."}]},"zh":{"word":"公民不服从","question":"在宪政民主中，公民不服从在何种情况下才具有正当性？","examples":[{"en":"Breaking a law may be defensible when the injustice is grave, ordinary remedies have failed, and the action remains proportionate to its aim.","native":"当不公极其严重、常规救济已经失效，且行动与其目标相称时，违法或许可以得到辩护。"},{"en":"Nonviolence and a willingness to accept legal consequences can demonstrate respect for the broader constitutional order while contesting a particular rule.","native":"坚持非暴力并愿意承担法律后果，可以在反对某项具体规则的同时，表明对整体宪政秩序的尊重。"},{"en":"However, romanticizing disobedience ignores the possibility that rival groups will invoke the same principle for profoundly anti-democratic causes.","native":"然而，把不服从浪漫化，会忽视敌对团体可能以同一原则为极端反民主事业辩护的风险。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'restorative justice', 'What can restorative justice achieve that conventional punishment often cannot?', '{"te":{"word":"పునరుద్ధరణాత్మక న్యాయం","question":"సాంప్రదాయిక శిక్ష తరచూ సాధించలేనిదాన్ని పునరుద్ధరణాత్మక న్యాయం ఏమి సాధించగలదు?","examples":[{"en":"A carefully facilitated process can give victims answers and recognition while requiring offenders to confront the human consequences of their actions.","native":"జాగ్రత్తగా నిర్వహించిన ప్రక్రియ బాధితులకు సమాధానాలు మరియు గుర్తింపును అందిస్తూ, నేరం చేసినవారు తమ చర్యల మానవీయ పరిణామాలను ఎదుర్కొనేలా చేయగలదు."},{"en":"Repair may include apology, restitution, and community service, but participation must be voluntary and never pressure victims into premature forgiveness.","native":"పరిహారంలో క్షమాపణ, నష్టపరిహారం మరియు సమాజ సేవ ఉండవచ్చు, కానీ పాల్గొనడం స్వచ్ఛందంగా ఉండాలి మరియు బాధితులను తొందరపాటి క్షమాపణకు ఎన్నడూ ఒత్తిడి చేయకూడదు."},{"en":"Restorative approaches complement rather than replace formal justice when public safety, power imbalances, or serious coercion make direct dialogue unsafe.","native":"ప్రజా భద్రత, అధికార అసమానతలు లేదా తీవ్రమైన బలవంతం ప్రత్యక్ష సంభాషణను అసురక్షితంగా చేసినప్పుడు, పునరుద్ధరణాత్మక విధానాలు అధికారిక న్యాయాన్ని భర్తీ చేయకుండా దానికి తోడ్పడతాయి."}]},"hi":{"word":"पुनर्स्थापनात्मक न्याय","question":"पुनर्स्थापनात्मक न्याय ऐसा क्या हासिल कर सकता है जो पारंपरिक दंड अक्सर नहीं कर पाता?","examples":[{"en":"A carefully facilitated process can give victims answers and recognition while requiring offenders to confront the human consequences of their actions.","native":"सावधानी से संचालित प्रक्रिया पीड़ितों को उत्तर और मान्यता दे सकती है, साथ ही अपराधियों को अपने कृत्यों के मानवीय परिणामों का सामना करने के लिए बाध्य कर सकती है।"},{"en":"Repair may include apology, restitution, and community service, but participation must be voluntary and never pressure victims into premature forgiveness.","native":"क्षतिपूर्ति में क्षमा-याचना, नुकसान की भरपाई और सामुदायिक सेवा शामिल हो सकती है, लेकिन भागीदारी स्वैच्छिक होनी चाहिए और पीड़ितों पर समय से पहले क्षमा करने का दबाव कभी नहीं पड़ना चाहिए।"},{"en":"Restorative approaches complement rather than replace formal justice when public safety, power imbalances, or serious coercion make direct dialogue unsafe.","native":"जब सार्वजनिक सुरक्षा, शक्ति-असंतुलन या गंभीर दबाव सीधे संवाद को असुरक्षित बनाते हैं, तब पुनर्स्थापनात्मक उपाय औपचारिक न्याय का स्थान लेने के बजाय उसके पूरक होते हैं।"}]},"es":{"word":"justicia restaurativa","question":"¿Qué puede lograr la justicia restaurativa que el castigo convencional a menudo no consigue?","examples":[{"en":"A carefully facilitated process can give victims answers and recognition while requiring offenders to confront the human consequences of their actions.","native":"Un proceso cuidadosamente facilitado puede ofrecer respuestas y reconocimiento a las víctimas, a la vez que exige a los responsables afrontar las consecuencias humanas de sus actos."},{"en":"Repair may include apology, restitution, and community service, but participation must be voluntary and never pressure victims into premature forgiveness.","native":"La reparación puede incluir disculpas, restitución y servicio comunitario, pero la participación debe ser voluntaria y nunca presionar a las víctimas para que perdonen prematuramente."},{"en":"Restorative approaches complement rather than replace formal justice when public safety, power imbalances, or serious coercion make direct dialogue unsafe.","native":"Los enfoques restaurativos complementan, en lugar de sustituir, a la justicia formal cuando la seguridad pública, los desequilibrios de poder o la coacción grave hacen inseguro el diálogo directo."}]},"zh":{"word":"修复性司法","question":"修复性司法能够做到哪些传统惩罚往往做不到的事情？","examples":[{"en":"A carefully facilitated process can give victims answers and recognition while requiring offenders to confront the human consequences of their actions.","native":"精心引导的程序可以让受害者获得答案与认可，同时要求加害者直面其行为给他人造成的后果。"},{"en":"Repair may include apology, restitution, and community service, but participation must be voluntary and never pressure victims into premature forgiveness.","native":"修复可以包括道歉、赔偿与社区服务，但参与必须出于自愿，绝不能迫使受害者过早原谅。"},{"en":"Restorative approaches complement rather than replace formal justice when public safety, power imbalances, or serious coercion make direct dialogue unsafe.","native":"当公共安全、权力失衡或严重胁迫使直接对话变得不安全时，修复性方式应补充而非取代正式司法。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'intergenerational equity', 'What obligations do present generations owe to people who will live in the distant future?', '{"te":{"word":"తరాల మధ్య న్యాయం","question":"సుదూర భవిష్యత్తులో జీవించే ప్రజల పట్ల ప్రస్తుత తరాలకు ఏ బాధ్యతలు ఉన్నాయి?","examples":[{"en":"Future people cannot vote in today''s elections, yet they will inherit the climate, debt, infrastructure, and institutions that current voters shape.","native":"భవిష్యత్ ప్రజలు నేటి ఎన్నికల్లో ఓటు వేయలేరు, అయినప్పటికీ ప్రస్తుత ఓటర్లు రూపుదిద్దే వాతావరణం, అప్పు, మౌలిక సదుపాయాలు మరియు సంస్థలను వారే వారసత్వంగా పొందుతారు."},{"en":"Intergenerational fairness does not demand preserving everything unchanged; it demands leaving comparable opportunities and avoiding irreversible, foreseeable harm.","native":"తరాల మధ్య న్యాయం ప్రతిదానినీ మార్పు లేకుండా కాపాడాలని కోరదు; సమానమైన అవకాశాలను మిగల్చాలని మరియు తిరుగులేని, ముందే ఊహించగల హానిని నివారించాలని కోరుతుంది."},{"en":"Independent future-generations commissioners could scrutinize long-term policy, although elected representatives must remain publicly accountable for final choices.","native":"స్వతంత్ర భవిష్యత్ తరాల కమిషనర్లు దీర్ఘకాలిక విధానాన్ని పరిశీలించగలరు, అయితే తుది ఎంపికలకు ఎన్నికైన ప్రతినిధులే ప్రజలకు జవాబుదారీగా ఉండాలి."}]},"hi":{"word":"अंतरपीढ़ीगत न्याय","question":"वर्तमान पीढ़ियों का दूर भविष्य में रहने वाले लोगों के प्रति क्या दायित्व है?","examples":[{"en":"Future people cannot vote in today''s elections, yet they will inherit the climate, debt, infrastructure, and institutions that current voters shape.","native":"भविष्य के लोग आज के चुनावों में मतदान नहीं कर सकते, फिर भी उन्हें वही जलवायु, ऋण, बुनियादी ढाँचा और संस्थाएँ विरासत में मिलेंगी जिन्हें वर्तमान मतदाता आकार देते हैं।"},{"en":"Intergenerational fairness does not demand preserving everything unchanged; it demands leaving comparable opportunities and avoiding irreversible, foreseeable harm.","native":"अंतरपीढ़ीगत न्याय हर चीज़ को अपरिवर्तित बचाए रखने की माँग नहीं करता; वह तुलनीय अवसर छोड़ने और अपरिवर्तनीय, पूर्वानुमेय नुकसान से बचने की माँग करता है।"},{"en":"Independent future-generations commissioners could scrutinize long-term policy, although elected representatives must remain publicly accountable for final choices.","native":"स्वतंत्र भावी-पीढ़ी आयुक्त दीर्घकालिक नीति की समीक्षा कर सकते हैं, हालांकि अंतिम निर्णयों के लिए निर्वाचित प्रतिनिधियों को जनता के प्रति जवाबदेह रहना चाहिए।"}]},"es":{"word":"equidad intergeneracional","question":"¿Qué obligaciones tienen las generaciones presentes con las personas que vivirán en un futuro lejano?","examples":[{"en":"Future people cannot vote in today''s elections, yet they will inherit the climate, debt, infrastructure, and institutions that current voters shape.","native":"Las personas del futuro no pueden votar en las elecciones actuales, pero heredarán el clima, la deuda, las infraestructuras y las instituciones que modelan los votantes de hoy."},{"en":"Intergenerational fairness does not demand preserving everything unchanged; it demands leaving comparable opportunities and avoiding irreversible, foreseeable harm.","native":"La equidad intergeneracional no exige conservarlo todo sin cambios; exige dejar oportunidades comparables y evitar daños irreversibles y previsibles."},{"en":"Independent future-generations commissioners could scrutinize long-term policy, although elected representatives must remain publicly accountable for final choices.","native":"Comisionados independientes para las generaciones futuras podrían examinar las políticas a largo plazo, aunque los representantes electos deben seguir respondiendo públicamente por las decisiones finales."}]},"zh":{"word":"代际公平","question":"当代人对生活在遥远未来的人负有哪些义务？","examples":[{"en":"Future people cannot vote in today''s elections, yet they will inherit the climate, debt, infrastructure, and institutions that current voters shape.","native":"未来的人无法在今天的选举中投票，却会继承当代选民所塑造的气候、债务、基础设施与制度。"},{"en":"Intergenerational fairness does not demand preserving everything unchanged; it demands leaving comparable opportunities and avoiding irreversible, foreseeable harm.","native":"代际公平并非要求一切维持原样，而是要求为后人留下相当的机会，并避免不可逆且可预见的伤害。"},{"en":"Independent future-generations commissioners could scrutinize long-term policy, although elected representatives must remain publicly accountable for final choices.","native":"独立的未来世代专员可以审查长期政策，但民选代表仍须为最终选择向公众负责。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'social cohesion', 'How can diverse societies strengthen social cohesion without demanding conformity?', '{"te":{"word":"సామాజిక ఐక్యత","question":"ఏకరూపతను కోరుకోకుండా వైవిధ్యభరిత సమాజాలు సామాజిక ఐక్యతను ఎలా బలోపేతం చేయగలవు?","examples":[{"en":"Cohesion grows from fair institutions and shared civic experiences, not from requiring everyone to adopt the same customs or identity.","native":"అందరూ ఒకే ఆచారాలు లేదా గుర్తింపును స్వీకరించాలని కోరడం వల్ల కాకుండా, న్యాయమైన సంస్థలు మరియు ఉమ్మడి పౌర అనుభవాల వల్ల ఐక్యత పెరుగుతుంది."},{"en":"Mixed schools, public spaces, and voluntary associations create routine contact through which unfamiliar groups can become neighbors and collaborators.","native":"మిశ్రమ పాఠశాలలు, బహిరంగ ప్రదేశాలు మరియు స్వచ్ఛంద సంఘాలు సాధారణ పరిచయాన్ని కల్పిస్తాయి; దాని ద్వారా అపరిచిత వర్గాలు పొరుగువారిగా, సహకారులుగా మారగలవు."},{"en":"A compelling common story should acknowledge past exclusions and allow citizens to belong without erasing their multiple loyalties.","native":"అర్థవంతమైన ఉమ్మడి కథనం గత బహిష్కరణలను గుర్తించి, పౌరుల అనేక విధేయతలను చెరపకుండా వారికి చెందిన భావనను కల్పించాలి."}]},"hi":{"word":"सामाजिक एकजुटता","question":"विविध समाज एकरूपता की माँग किए बिना सामाजिक एकजुटता कैसे मज़बूत कर सकते हैं?","examples":[{"en":"Cohesion grows from fair institutions and shared civic experiences, not from requiring everyone to adopt the same customs or identity.","native":"एकजुटता निष्पक्ष संस्थाओं और साझा नागरिक अनुभवों से बढ़ती है, न कि सभी से एक जैसे रीति-रिवाज या पहचान अपनाने की माँग करने से।"},{"en":"Mixed schools, public spaces, and voluntary associations create routine contact through which unfamiliar groups can become neighbors and collaborators.","native":"मिश्रित विद्यालय, सार्वजनिक स्थान और स्वैच्छिक संगठन नियमित संपर्क बनाते हैं, जिसके माध्यम से अपरिचित समूह पड़ोसी और सहयोगी बन सकते हैं।"},{"en":"A compelling common story should acknowledge past exclusions and allow citizens to belong without erasing their multiple loyalties.","native":"एक प्रभावशाली साझा कथा को पिछले बहिष्कार स्वीकार करने चाहिए और नागरिकों की अनेक निष्ठाएँ मिटाए बिना उन्हें अपनापन महसूस करने देना चाहिए।"}]},"es":{"word":"cohesión social","question":"¿Cómo pueden las sociedades diversas reforzar la cohesión social sin exigir conformidad?","examples":[{"en":"Cohesion grows from fair institutions and shared civic experiences, not from requiring everyone to adopt the same customs or identity.","native":"La cohesión nace de instituciones justas y experiencias cívicas compartidas, no de exigir que todos adopten las mismas costumbres o identidad."},{"en":"Mixed schools, public spaces, and voluntary associations create routine contact through which unfamiliar groups can become neighbors and collaborators.","native":"Las escuelas mixtas, los espacios públicos y las asociaciones voluntarias generan un contacto habitual mediante el cual grupos desconocidos pueden convertirse en vecinos y colaboradores."},{"en":"A compelling common story should acknowledge past exclusions and allow citizens to belong without erasing their multiple loyalties.","native":"Un relato común convincente debería reconocer exclusiones pasadas y permitir que los ciudadanos pertenezcan sin borrar sus múltiples lealtades."}]},"zh":{"word":"社会凝聚力","question":"多元社会如何在不要求人人趋同的情况下增强社会凝聚力？","examples":[{"en":"Cohesion grows from fair institutions and shared civic experiences, not from requiring everyone to adopt the same customs or identity.","native":"凝聚力源于公平的制度和共同的公民经历，而不是要求所有人接受相同的习俗或身份。"},{"en":"Mixed schools, public spaces, and voluntary associations create routine contact through which unfamiliar groups can become neighbors and collaborators.","native":"混合生源的学校、公共空间与志愿社团创造日常接触，使陌生群体能够成为邻居与合作者。"},{"en":"A compelling common story should acknowledge past exclusions and allow citizens to belong without erasing their multiple loyalties.","native":"有感召力的共同叙事应承认过去的排斥，并让公民在不抹去多重归属的前提下拥有共同体认同。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'cultural appropriation', 'How can we distinguish cultural appropriation from respectful cultural exchange?', '{"te":{"word":"సాంస్కృతిక స్వాధీనీకరణ","question":"సాంస్కృతిక స్వాధీనీకరణను గౌరవప్రదమైన సాంస్కృతిక మార్పిడి నుంచి ఎలా వేరు చేయగలం?","examples":[{"en":"Borrowing becomes exploitative when powerful outsiders profit from a tradition while its originating community remains stereotyped, excluded, or uncompensated.","native":"ఒక సంప్రదాయం నుంచి శక్తివంతమైన బయటి వ్యక్తులు లాభపడుతూ, దాని మూల సమాజం మూస ధోరణులకు, బహిష్కరణకు లేదా పరిహారం లేకపోవడానికి గురైనప్పుడు ఆ స్వీకరణ దోపిడీగా మారుతుంది."},{"en":"Context matters: sacred symbols, everyday foods, and collaborative art carry different histories and therefore warrant different ethical judgments.","native":"సందర్భం ముఖ్యం: పవిత్ర చిహ్నాలు, రోజువారీ ఆహారాలు మరియు సహకార కళలకు వేర్వేరు చరిత్రలు ఉంటాయి, అందువల్ల వాటికి వేర్వేరు నైతిక నిర్ణయాలు అవసరం."},{"en":"Respectful exchange involves attribution, informed consent where possible, and genuine relationships that let source communities influence how their culture is represented.","native":"గౌరవప్రదమైన మార్పిడిలో మూలాన్ని గుర్తించడం, సాధ్యమైన చోట సమాచారంతో కూడిన సమ్మతి, మరియు తమ సంస్కృతిని ఎలా చూపాలో మూల సమాజాలు ప్రభావితం చేయగల నిజమైన సంబంధాలు ఉంటాయి."}]},"hi":{"word":"सांस्कृतिक विनियोग","question":"हम सांस्कृतिक विनियोग को सम्मानपूर्ण सांस्कृतिक आदान-प्रदान से कैसे अलग कर सकते हैं?","examples":[{"en":"Borrowing becomes exploitative when powerful outsiders profit from a tradition while its originating community remains stereotyped, excluded, or uncompensated.","native":"किसी परंपरा को अपनाना तब शोषणकारी बन जाता है जब शक्तिशाली बाहरी लोग उससे लाभ कमाएँ, जबकि उसका मूल समुदाय रूढ़ धारणाओं, बहिष्कार या बिना मुआवज़े के रह जाए।"},{"en":"Context matters: sacred symbols, everyday foods, and collaborative art carry different histories and therefore warrant different ethical judgments.","native":"संदर्भ महत्त्वपूर्ण है: पवित्र प्रतीकों, रोज़मर्रा के भोजन और सहयोगी कला के इतिहास अलग होते हैं, इसलिए उनके नैतिक आकलन भी अलग होने चाहिए।"},{"en":"Respectful exchange involves attribution, informed consent where possible, and genuine relationships that let source communities influence how their culture is represented.","native":"सम्मानपूर्ण आदान-प्रदान में श्रेय, जहाँ संभव हो सूचित सहमति, और ऐसे वास्तविक संबंध शामिल हैं जिनसे मूल समुदाय अपनी संस्कृति के चित्रण को प्रभावित कर सकें।"}]},"es":{"word":"apropiación cultural","question":"¿Cómo podemos distinguir la apropiación cultural de un intercambio cultural respetuoso?","examples":[{"en":"Borrowing becomes exploitative when powerful outsiders profit from a tradition while its originating community remains stereotyped, excluded, or uncompensated.","native":"La adopción se vuelve explotadora cuando personas externas con poder se lucran con una tradición mientras su comunidad de origen sigue estereotipada, excluida o sin compensación."},{"en":"Context matters: sacred symbols, everyday foods, and collaborative art carry different histories and therefore warrant different ethical judgments.","native":"El contexto importa: los símbolos sagrados, la comida cotidiana y el arte colaborativo tienen historias distintas y, por tanto, merecen juicios éticos diferentes."},{"en":"Respectful exchange involves attribution, informed consent where possible, and genuine relationships that let source communities influence how their culture is represented.","native":"El intercambio respetuoso implica atribución, consentimiento informado cuando sea posible y relaciones genuinas que permitan a las comunidades de origen influir en cómo se representa su cultura."}]},"zh":{"word":"文化挪用","question":"我们应如何区分文化挪用与相互尊重的文化交流？","examples":[{"en":"Borrowing becomes exploitative when powerful outsiders profit from a tradition while its originating community remains stereotyped, excluded, or uncompensated.","native":"当强势的外来者从某项传统中获利，而其源生群体仍遭受刻板印象、排斥或得不到补偿时，这种借用便成为剥削。"},{"en":"Context matters: sacred symbols, everyday foods, and collaborative art carry different histories and therefore warrant different ethical judgments.","native":"语境至关重要：神圣符号、日常食物与合作艺术各有不同历史，因此应接受不同的伦理判断。"},{"en":"Respectful exchange involves attribution, informed consent where possible, and genuine relationships that let source communities influence how their culture is represented.","native":"尊重的交流包括注明来源、尽可能取得知情同意，以及建立真实关系，让源生群体能够影响其文化的呈现方式。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'language preservation', 'What is gained by preserving a language with very few remaining speakers?', '{"te":{"word":"భాషా పరిరక్షణ","question":"చాలా కొద్దిమంది మాత్రమే మాట్లాడే భాషను కాపాడటం వల్ల ఏమి లభిస్తుంది?","examples":[{"en":"A language carries ecological knowledge, oral history, humor, and categories of thought that no dictionary can preserve in isolation.","native":"ఒక భాష పర్యావరణ జ్ఞానం, మౌఖిక చరిత్ర, హాస్యం మరియు ఏ నిఘంటువూ విడిగా సంరక్షించలేని ఆలోచనా వర్గాలను మోస్తుంది."},{"en":"Preservation succeeds when children can use the language in contemporary life, not merely when recordings are stored in an academic archive.","native":"రికార్డులను కేవలం విద్యాసంబంధ భాండాగారంలో ఉంచినప్పుడు కాకుండా, పిల్లలు సమకాలీన జీవితంలో ఆ భాషను ఉపయోగించగలిగినప్పుడు పరిరక్షణ విజయవంతమవుతుంది."},{"en":"Communities themselves should decide whether revitalization, documentation, or bilingual education best serves their priorities and limited resources.","native":"పునరుజ్జీవనం, నమోదు లేదా ద్విభాషా విద్యలో ఏది తమ ప్రాధాన్యాలకు మరియు పరిమిత వనరులకు ఉత్తమంగా ఉపయోగపడుతుందో సమాజాలే నిర్ణయించాలి."}]},"hi":{"word":"भाषा संरक्षण","question":"बहुत कम बचे हुए वक्ताओं वाली भाषा को संरक्षित करने से क्या हासिल होता है?","examples":[{"en":"A language carries ecological knowledge, oral history, humor, and categories of thought that no dictionary can preserve in isolation.","native":"एक भाषा पारिस्थितिक ज्ञान, मौखिक इतिहास, हास्य और विचार की ऐसी श्रेणियाँ संजोती है जिन्हें कोई शब्दकोश अकेले संरक्षित नहीं कर सकता।"},{"en":"Preservation succeeds when children can use the language in contemporary life, not merely when recordings are stored in an academic archive.","native":"संरक्षण तब सफल होता है जब बच्चे समकालीन जीवन में भाषा का उपयोग कर सकें, केवल तब नहीं जब रिकॉर्डिंग किसी शैक्षणिक संग्रह में रख दी जाएँ।"},{"en":"Communities themselves should decide whether revitalization, documentation, or bilingual education best serves their priorities and limited resources.","native":"समुदायों को स्वयं तय करना चाहिए कि पुनर्जीवन, दस्तावेज़ीकरण या द्विभाषी शिक्षा में से क्या उनकी प्राथमिकताओं और सीमित संसाधनों के लिए सर्वोत्तम है।"}]},"es":{"word":"preservación lingüística","question":"¿Qué se gana al preservar una lengua con muy pocos hablantes restantes?","examples":[{"en":"A language carries ecological knowledge, oral history, humor, and categories of thought that no dictionary can preserve in isolation.","native":"Una lengua transmite conocimientos ecológicos, historia oral, humor y categorías de pensamiento que ningún diccionario puede preservar por sí solo."},{"en":"Preservation succeeds when children can use the language in contemporary life, not merely when recordings are stored in an academic archive.","native":"La preservación tiene éxito cuando los niños pueden usar la lengua en la vida contemporánea, no solo cuando se guardan grabaciones en un archivo académico."},{"en":"Communities themselves should decide whether revitalization, documentation, or bilingual education best serves their priorities and limited resources.","native":"Las propias comunidades deberían decidir si la revitalización, la documentación o la educación bilingüe responden mejor a sus prioridades y recursos limitados."}]},"zh":{"word":"语言保护","question":"保护一种仅剩极少数使用者的语言能够带来什么？","examples":[{"en":"A language carries ecological knowledge, oral history, humor, and categories of thought that no dictionary can preserve in isolation.","native":"一种语言承载着生态知识、口述历史、幽默和思维范畴，这些内容绝非一部词典就能孤立保存。"},{"en":"Preservation succeeds when children can use the language in contemporary life, not merely when recordings are stored in an academic archive.","native":"只有当儿童能在当代生活中使用这种语言时，保护才算成功，而不是仅把录音存进学术档案。"},{"en":"Communities themselves should decide whether revitalization, documentation, or bilingual education best serves their priorities and limited resources.","native":"应由社区自身决定语言复兴、资料记录或双语教育，哪一种最符合其优先事项与有限资源。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'emotional intelligence', 'Is emotional intelligence a measurable ability, a learnable skill, or an appealing label for several traits?', '{"te":{"word":"భావోద్వేగ మేధస్సు","question":"భావోద్వేగ మేధస్సు కొలవగల సామర్థ్యమా, నేర్చుకోగల నైపుణ్యమా, లేక అనేక లక్షణాలకు ఆకర్షణీయమైన పేరా?","examples":[{"en":"Recognizing emotion accurately can improve communication, but insight has little value unless a person can regulate impulses and respond constructively.","native":"భావోద్వేగాన్ని ఖచ్చితంగా గుర్తించడం సంభాషణను మెరుగుపరచగలదు, కానీ వ్యక్తి తన ఉద్రేకాలను నియంత్రించి నిర్మాణాత్మకంగా స్పందించలేకపోతే ఆ అవగాహనకు తక్కువ విలువ ఉంటుంది."},{"en":"Training can strengthen perspective-taking and conflict management, although personality, culture, and context make any single score incomplete.","native":"శిక్షణ ఇతరుల దృక్కోణాన్ని గ్రహించడం మరియు ఘర్షణ నిర్వహణను బలోపేతం చేయగలదు, అయితే వ్యక్తిత్వం, సంస్కృతి మరియు సందర్భం ఏ ఒక్క స్కోరునైనా అసంపూర్ణంగా చేస్తాయి."},{"en":"Emotional skill is not inherently benevolent; a perceptive manipulator may understand others exceptionally well and use that knowledge selfishly.","native":"భావోద్వేగ నైపుణ్యం సహజంగానే సద్భావపూర్వకం కాదు; సూక్ష్మగ్రాహి అయిన మోసగాడు ఇతరులను అసాధారణంగా అర్థం చేసుకుని ఆ జ్ఞానాన్ని స్వార్థపూరితంగా ఉపయోగించవచ్చు."}]},"hi":{"word":"भावनात्मक बुद्धिमत्ता","question":"क्या भावनात्मक बुद्धिमत्ता मापने योग्य क्षमता, सीखा जा सकने वाला कौशल या कई गुणों के लिए आकर्षक नाम है?","examples":[{"en":"Recognizing emotion accurately can improve communication, but insight has little value unless a person can regulate impulses and respond constructively.","native":"भावनाओं को सही पहचानना संवाद सुधार सकता है, लेकिन यदि व्यक्ति आवेग नियंत्रित करके रचनात्मक प्रतिक्रिया न दे सके तो इस समझ का बहुत कम मूल्य है।"},{"en":"Training can strengthen perspective-taking and conflict management, although personality, culture, and context make any single score incomplete.","native":"प्रशिक्षण दूसरों का दृष्टिकोण समझने और संघर्ष सँभालने की क्षमता मज़बूत कर सकता है, हालांकि व्यक्तित्व, संस्कृति और संदर्भ किसी एक अंक को अधूरा बना देते हैं।"},{"en":"Emotional skill is not inherently benevolent; a perceptive manipulator may understand others exceptionally well and use that knowledge selfishly.","native":"भावनात्मक कौशल स्वभावतः परोपकारी नहीं होता; एक सूझबूझ वाला छलकर्ता दूसरों को असाधारण रूप से समझकर उस ज्ञान का स्वार्थी उपयोग कर सकता है।"}]},"es":{"word":"inteligencia emocional","question":"¿Es la inteligencia emocional una capacidad medible, una habilidad que se aprende o una etiqueta atractiva para diversos rasgos?","examples":[{"en":"Recognizing emotion accurately can improve communication, but insight has little value unless a person can regulate impulses and respond constructively.","native":"Reconocer las emociones con precisión puede mejorar la comunicación, pero esa comprensión sirve de poco si la persona no regula sus impulsos y responde de forma constructiva."},{"en":"Training can strengthen perspective-taking and conflict management, although personality, culture, and context make any single score incomplete.","native":"La formación puede reforzar la adopción de otras perspectivas y la gestión de conflictos, aunque la personalidad, la cultura y el contexto hacen incompleta cualquier puntuación única."},{"en":"Emotional skill is not inherently benevolent; a perceptive manipulator may understand others exceptionally well and use that knowledge selfishly.","native":"La habilidad emocional no es benévola por naturaleza; un manipulador perceptivo puede comprender excepcionalmente bien a los demás y usar ese conocimiento con egoísmo."}]},"zh":{"word":"情商","question":"情商究竟是一种可测量的能力、一项可习得的技能，还是对多种特质的动听概括？","examples":[{"en":"Recognizing emotion accurately can improve communication, but insight has little value unless a person can regulate impulses and respond constructively.","native":"准确识别情绪能够改善沟通，但如果一个人无法控制冲动并作出建设性回应，这种洞察便价值有限。"},{"en":"Training can strengthen perspective-taking and conflict management, although personality, culture, and context make any single score incomplete.","native":"训练可以增强换位思考与冲突管理能力，但性格、文化和情境决定了任何单一分数都不完整。"},{"en":"Emotional skill is not inherently benevolent; a perceptive manipulator may understand others exceptionally well and use that knowledge selfishly.","native":"情绪能力并非天生善意；善于洞察的操纵者可能极其了解他人，并自私地利用这种认识。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'self-awareness', 'Why can greater self-awareness be uncomfortable as well as beneficial?', '{"te":{"word":"స్వీయ అవగాహన","question":"ఎక్కువ స్వీయ అవగాహన ప్రయోజనకరంగా ఉండటంతో పాటు అసౌకర్యాన్ని ఎందుకు కలిగించగలదు?","examples":[{"en":"Honest reflection exposes the gap between our stated values and habitual conduct, creating an obligation to change rather than merely understand ourselves.","native":"నిష్కపటమైన ఆత్మపరిశీలన మనం ప్రకటించే విలువలకు, అలవాటైన ప్రవర్తనకు మధ్య ఉన్న అంతరాన్ని బయటపెట్టి, మనల్ని కేవలం అర్థం చేసుకోవడం కాకుండా మారాల్సిన బాధ్యతను కలిగిస్తుంది."},{"en":"Feedback from trusted people can reveal blind spots, yet accepting it requires separating a criticism of behavior from a verdict on personal worth.","native":"విశ్వసనీయ వ్యక్తుల అభిప్రాయం మనకు కనిపించని లోపాలను బయటపెట్టగలదు, కానీ దాన్ని అంగీకరించడానికి ప్రవర్తనపై విమర్శను వ్యక్తిగత విలువపై తీర్పు నుంచి వేరు చేయాలి."},{"en":"Self-awareness becomes counterproductive when observation turns into relentless self-monitoring that inhibits spontaneity and magnifies ordinary mistakes.","native":"పరిశీలన నిరంతర స్వీయ పర్యవేక్షణగా మారి సహజత్వాన్ని అడ్డుకుని సాధారణ తప్పులను అతిశయింపజేసినప్పుడు స్వీయ అవగాహన ప్రతికూలమవుతుంది."}]},"hi":{"word":"आत्म-जागरूकता","question":"अधिक आत्म-जागरूकता लाभकारी होने के साथ असहज क्यों हो सकती है?","examples":[{"en":"Honest reflection exposes the gap between our stated values and habitual conduct, creating an obligation to change rather than merely understand ourselves.","native":"ईमानदार आत्मचिंतन हमारे घोषित मूल्यों और आदतन व्यवहार के बीच का अंतर उजागर करता है, जिससे केवल स्वयं को समझने के बजाय बदलने का दायित्व पैदा होता है।"},{"en":"Feedback from trusted people can reveal blind spots, yet accepting it requires separating a criticism of behavior from a verdict on personal worth.","native":"विश्वसनीय लोगों की प्रतिक्रिया अनदेखे पहलू दिखा सकती है, फिर भी उसे स्वीकार करने के लिए व्यवहार की आलोचना को व्यक्तिगत मूल्य पर निर्णय से अलग करना पड़ता है।"},{"en":"Self-awareness becomes counterproductive when observation turns into relentless self-monitoring that inhibits spontaneity and magnifies ordinary mistakes.","native":"आत्म-जागरूकता तब प्रतिकूल हो जाती है जब निरीक्षण निरंतर आत्म-निगरानी बनकर सहजता रोकता है और सामान्य गलतियों को बढ़ा-चढ़ाकर दिखाता है।"}]},"es":{"word":"autoconocimiento","question":"¿Por qué un mayor autoconocimiento puede resultar incómodo además de beneficioso?","examples":[{"en":"Honest reflection exposes the gap between our stated values and habitual conduct, creating an obligation to change rather than merely understand ourselves.","native":"La reflexión honesta revela la distancia entre los valores que proclamamos y nuestra conducta habitual, lo que obliga a cambiar en vez de limitarnos a comprendernos."},{"en":"Feedback from trusted people can reveal blind spots, yet accepting it requires separating a criticism of behavior from a verdict on personal worth.","native":"Los comentarios de personas de confianza pueden revelar puntos ciegos, pero aceptarlos exige separar una crítica al comportamiento de un veredicto sobre el valor personal."},{"en":"Self-awareness becomes counterproductive when observation turns into relentless self-monitoring that inhibits spontaneity and magnifies ordinary mistakes.","native":"El autoconocimiento se vuelve contraproducente cuando la observación deriva en una vigilancia propia implacable que inhibe la espontaneidad y magnifica errores corrientes."}]},"zh":{"word":"自我觉察","question":"为什么更深入的自我觉察既有益处，也会令人不适？","examples":[{"en":"Honest reflection exposes the gap between our stated values and habitual conduct, creating an obligation to change rather than merely understand ourselves.","native":"诚实反思会揭示我们宣称的价值观与习惯行为之间的差距，使我们有义务作出改变，而不只是了解自己。"},{"en":"Feedback from trusted people can reveal blind spots, yet accepting it requires separating a criticism of behavior from a verdict on personal worth.","native":"可信之人的反馈能够揭示盲点，但接受反馈需要把对行为的批评与对个人价值的判决区分开来。"},{"en":"Self-awareness becomes counterproductive when observation turns into relentless self-monitoring that inhibits spontaneity and magnifies ordinary mistakes.","native":"当观察变成无休止的自我监控，压抑自然表现并放大普通错误时，自我觉察就会适得其反。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'adaptability', 'How can people remain adaptable without abandoning stable principles or long-term goals?', '{"te":{"word":"అనుకూలన సామర్థ్యం","question":"స్థిరమైన సూత్రాలను లేదా దీర్ఘకాలిక లక్ష్యాలను వదులుకోకుండా ప్రజలు అనుకూలన సామర్థ్యాన్ని ఎలా కొనసాగించగలరు?","examples":[{"en":"Adaptability means revising methods when evidence changes, whereas opportunism changes declared values whenever a more convenient option appears.","native":"ఆధారాలు మారినప్పుడు పద్ధతులను సవరించడం అనుకూలన సామర్థ్యం; మరింత సౌకర్యవంతమైన ఎంపిక కనిపించినప్పుడల్లా ప్రకటించిన విలువలను మార్చడం అవకాశవాదం."},{"en":"Clear priorities provide a stable direction while experiments, feedback, and contingency plans keep the route flexible.","native":"స్పష్టమైన ప్రాధాన్యాలు స్థిరమైన దిశను అందిస్తాయి, కాగా ప్రయోగాలు, అభిప్రాయాలు మరియు ప్రత్యామ్నాయ ప్రణాళికలు మార్గాన్ని అనువుగా ఉంచుతాయి."},{"en":"Organizations often praise flexibility but punish failed experiments, creating a culture in which employees conceal problems and repeat familiar routines.","native":"సంస్థలు తరచూ సౌలభ్యాన్ని ప్రశంసిస్తూ విఫలమైన ప్రయోగాలను శిక్షిస్తాయి; దీనివల్ల ఉద్యోగులు సమస్యలను దాచిపెట్టి పరిచిత పద్ధతులను పునరావృతం చేసే సంస్కృతి ఏర్పడుతుంది."}]},"hi":{"word":"अनुकूलनशीलता","question":"लोग स्थिर सिद्धांतों या दीर्घकालिक लक्ष्यों को छोड़े बिना अनुकूलनशील कैसे बने रह सकते हैं?","examples":[{"en":"Adaptability means revising methods when evidence changes, whereas opportunism changes declared values whenever a more convenient option appears.","native":"अनुकूलनशीलता का अर्थ प्रमाण बदलने पर तरीके बदलना है, जबकि अवसरवाद अधिक सुविधाजनक विकल्प दिखते ही घोषित मूल्यों को बदल देता है।"},{"en":"Clear priorities provide a stable direction while experiments, feedback, and contingency plans keep the route flexible.","native":"स्पष्ट प्राथमिकताएँ स्थिर दिशा देती हैं, जबकि प्रयोग, प्रतिक्रिया और आकस्मिक योजनाएँ रास्ते को लचीला बनाए रखती हैं।"},{"en":"Organizations often praise flexibility but punish failed experiments, creating a culture in which employees conceal problems and repeat familiar routines.","native":"संगठन अक्सर लचीलेपन की प्रशंसा करते हैं लेकिन असफल प्रयोगों को दंडित करते हैं, जिससे कर्मचारी समस्याएँ छिपाते और परिचित दिनचर्या दोहराते हैं।"}]},"es":{"word":"adaptabilidad","question":"¿Cómo pueden las personas mantener la capacidad de adaptación sin abandonar principios estables u objetivos a largo plazo?","examples":[{"en":"Adaptability means revising methods when evidence changes, whereas opportunism changes declared values whenever a more convenient option appears.","native":"Adaptarse significa revisar los métodos cuando cambia la evidencia, mientras que el oportunismo cambia los valores declarados cada vez que surge una opción más conveniente."},{"en":"Clear priorities provide a stable direction while experiments, feedback, and contingency plans keep the route flexible.","native":"Las prioridades claras proporcionan una dirección estable, mientras que los experimentos, los comentarios y los planes de contingencia mantienen flexible la ruta."},{"en":"Organizations often praise flexibility but punish failed experiments, creating a culture in which employees conceal problems and repeat familiar routines.","native":"Las organizaciones suelen elogiar la flexibilidad pero castigan los experimentos fallidos, creando una cultura en la que los empleados ocultan problemas y repiten rutinas conocidas."}]},"zh":{"word":"适应能力","question":"人们如何在不放弃稳定原则或长期目标的情况下保持适应能力？","examples":[{"en":"Adaptability means revising methods when evidence changes, whereas opportunism changes declared values whenever a more convenient option appears.","native":"适应能力意味着在证据变化时调整方法，而机会主义则是一旦出现更方便的选择，就改变自己宣称的价值观。"},{"en":"Clear priorities provide a stable direction while experiments, feedback, and contingency plans keep the route flexible.","native":"明确的优先事项提供稳定方向，而试验、反馈与应急预案则使实现目标的路径保持灵活。"},{"en":"Organizations often praise flexibility but punish failed experiments, creating a culture in which employees conceal problems and repeat familiar routines.","native":"组织往往口头赞扬灵活性，却惩罚失败的试验，由此形成员工隐瞒问题、重复熟悉做法的文化。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'uncertainty', 'How should leaders communicate uncertainty during a rapidly developing crisis?', '{"te":{"word":"అనిశ్చితి","question":"వేగంగా మారుతున్న సంక్షోభ సమయంలో నాయకులు అనిశ్చితిని ఎలా తెలియజేయాలి?","examples":[{"en":"Leaders should state what is known, what remains disputed, and which new evidence would cause current guidance to change.","native":"ఏది తెలిసిందో, ఏది ఇంకా వివాదాస్పదంగా ఉందో, ఏ కొత్త ఆధారం ప్రస్తుత మార్గదర్శకత్వాన్ని మార్చుతుందో నాయకులు స్పష్టంగా చెప్పాలి."},{"en":"False certainty may secure brief compliance, but later reversals can damage credibility precisely when public cooperation becomes most important.","native":"తప్పుడు నిశ్చితత్వం కొంతకాలం విధేయతను పొందవచ్చు, కానీ తరువాతి మార్పులు ప్రజా సహకారం అత్యంత అవసరమైన సమయంలోనే విశ్వసనీయతను దెబ్బతీయగలవు."},{"en":"Probabilities become meaningful when paired with concrete scenarios and actions, rather than presented as abstract numbers that audiences interpret inconsistently.","native":"ప్రేక్షకులు అసంగతంగా అర్థం చేసుకునే అమూర్త సంఖ్యలుగా చూపించడం కంటే, స్పష్టమైన పరిస్థితులు మరియు చర్యలతో జతచేసినప్పుడు సంభావ్యతలు అర్థవంతమవుతాయి."}]},"hi":{"word":"अनिश्चितता","question":"तेज़ी से बदलते संकट के दौरान नेताओं को अनिश्चितता के बारे में कैसे संवाद करना चाहिए?","examples":[{"en":"Leaders should state what is known, what remains disputed, and which new evidence would cause current guidance to change.","native":"नेताओं को बताना चाहिए कि क्या ज्ञात है, किस पर अभी विवाद है और कौन-सा नया प्रमाण मौजूदा मार्गदर्शन को बदल देगा।"},{"en":"False certainty may secure brief compliance, but later reversals can damage credibility precisely when public cooperation becomes most important.","native":"झूठा विश्वास थोड़े समय के लिए अनुपालन करा सकता है, लेकिन बाद में रुख बदलने से विश्वसनीयता ठीक उसी समय घट सकती है जब जन सहयोग सबसे आवश्यक हो।"},{"en":"Probabilities become meaningful when paired with concrete scenarios and actions, rather than presented as abstract numbers that audiences interpret inconsistently.","native":"प्रायिकताएँ तब सार्थक होती हैं जब उन्हें ठोस परिदृश्यों और कार्रवाइयों से जोड़ा जाए, न कि ऐसे अमूर्त अंकों के रूप में पेश किया जाए जिन्हें श्रोता अलग-अलग समझते हैं।"}]},"es":{"word":"incertidumbre","question":"¿Cómo deberían comunicar los líderes la incertidumbre durante una crisis que evoluciona rápidamente?","examples":[{"en":"Leaders should state what is known, what remains disputed, and which new evidence would cause current guidance to change.","native":"Los dirigentes deberían indicar qué se sabe, qué sigue en discusión y qué nuevas pruebas harían cambiar las recomendaciones actuales."},{"en":"False certainty may secure brief compliance, but later reversals can damage credibility precisely when public cooperation becomes most important.","native":"Una falsa certeza puede lograr obediencia breve, pero los cambios posteriores pueden dañar la credibilidad precisamente cuando más importa la cooperación pública."},{"en":"Probabilities become meaningful when paired with concrete scenarios and actions, rather than presented as abstract numbers that audiences interpret inconsistently.","native":"Las probabilidades adquieren sentido cuando se vinculan a escenarios y acciones concretos, en lugar de presentarse como cifras abstractas que el público interpreta de manera desigual."}]},"zh":{"word":"不确定性","question":"在迅速演变的危机中，领导人应如何传达不确定性？","examples":[{"en":"Leaders should state what is known, what remains disputed, and which new evidence would cause current guidance to change.","native":"领导人应说明哪些事实已经明确、哪些仍有争议，以及何种新证据会促使现行指引改变。"},{"en":"False certainty may secure brief compliance, but later reversals can damage credibility precisely when public cooperation becomes most important.","native":"虚假的确定性或许能换来短暂服从，但日后改口会恰恰在最需要公众合作时损害公信力。"},{"en":"Probabilities become meaningful when paired with concrete scenarios and actions, rather than presented as abstract numbers that audiences interpret inconsistently.","native":"概率只有与具体情境和行动相结合才有意义，而不应只是让受众各自解读的一串抽象数字。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'risk perception', 'Why do people''s perceptions of risk often differ from statistical evidence?', '{"te":{"word":"ప్రమాద అవగాహన","question":"ప్రమాదంపై ప్రజల అవగాహన గణాంక ఆధారాల నుంచి తరచూ ఎందుకు భిన్నంగా ఉంటుంది?","examples":[{"en":"Rare events feel more threatening when they are vivid, involuntary, and heavily reported, even if familiar hazards cause far greater harm overall.","native":"అరుదైన సంఘటనలు స్పష్టంగా, అనైచ్ఛికంగా ఉండి విస్తృతంగా నివేదించబడినప్పుడు మరింత భయంకరంగా అనిపిస్తాయి, పరిచిత ప్రమాదాలు మొత్తంగా చాలా ఎక్కువ హాని చేసినప్పటికీ."},{"en":"Trust changes risk perception because people evaluate not only the probability of harm but also who controls the danger and who benefits.","native":"ప్రజలు హాని సంభావ్యతనే కాకుండా ప్రమాదాన్ని ఎవరు నియంత్రిస్తారు, ఎవరు లాభపడతారు అనే అంశాలను కూడా అంచనా వేస్తారు కాబట్టి విశ్వాసం ప్రమాద అవగాహనను మారుస్తుంది."},{"en":"Effective communication compares like with like and acknowledges emotion, since dismissing fear as irrational usually makes corrective statistics less persuasive.","native":"సమర్థవంతమైన సంభాషణ సారూప్యమైన వాటినే పోల్చి భావోద్వేగాన్ని గుర్తిస్తుంది, ఎందుకంటే భయాన్ని అహేతుకమని తోసిపుచ్చడం సరిదిద్దే గణాంకాల నమ్మకాన్ని సాధారణంగా తగ్గిస్తుంది."}]},"hi":{"word":"जोखिम की धारणा","question":"जोखिम के बारे में लोगों की धारणाएँ अक्सर सांख्यिकीय प्रमाणों से अलग क्यों होती हैं?","examples":[{"en":"Rare events feel more threatening when they are vivid, involuntary, and heavily reported, even if familiar hazards cause far greater harm overall.","native":"दुर्लभ घटनाएँ तब अधिक भयावह लगती हैं जब वे जीवंत, अनैच्छिक और व्यापक रूप से रिपोर्ट की जाती हैं, भले ही परिचित खतरे कुल मिलाकर कहीं अधिक नुकसान करें।"},{"en":"Trust changes risk perception because people evaluate not only the probability of harm but also who controls the danger and who benefits.","native":"विश्वास जोखिम की धारणा बदलता है, क्योंकि लोग केवल नुकसान की संभावना नहीं बल्कि यह भी आँकते हैं कि खतरे को कौन नियंत्रित करता है और लाभ किसे मिलता है।"},{"en":"Effective communication compares like with like and acknowledges emotion, since dismissing fear as irrational usually makes corrective statistics less persuasive.","native":"प्रभावी संवाद समान चीज़ों की तुलना करता है और भावना को स्वीकारता है, क्योंकि डर को अतार्किक बताकर खारिज करने से सुधारात्मक आँकड़े आम तौर पर कम विश्वसनीय लगते हैं।"}]},"es":{"word":"percepción del riesgo","question":"¿Por qué la percepción del riesgo suele diferir de la evidencia estadística?","examples":[{"en":"Rare events feel more threatening when they are vivid, involuntary, and heavily reported, even if familiar hazards cause far greater harm overall.","native":"Los sucesos raros parecen más amenazantes cuando son vívidos, involuntarios y reciben gran cobertura, aunque peligros conocidos causen mucho más daño en conjunto."},{"en":"Trust changes risk perception because people evaluate not only the probability of harm but also who controls the danger and who benefits.","native":"La confianza modifica la percepción del riesgo porque la gente evalúa no solo la probabilidad de daño, sino también quién controla el peligro y quién se beneficia."},{"en":"Effective communication compares like with like and acknowledges emotion, since dismissing fear as irrational usually makes corrective statistics less persuasive.","native":"Una comunicación eficaz compara elementos equivalentes y reconoce la emoción, pues descartar el miedo como irracional suele restar fuerza persuasiva a las estadísticas correctivas."}]},"zh":{"word":"风险感知","question":"为什么人们对风险的感知往往与统计证据不一致？","examples":[{"en":"Rare events feel more threatening when they are vivid, involuntary, and heavily reported, even if familiar hazards cause far greater harm overall.","native":"罕见事件若画面鲜明、非出于自愿且被大量报道，就会显得更具威胁，即使熟悉的危险总体造成的伤害大得多。"},{"en":"Trust changes risk perception because people evaluate not only the probability of harm but also who controls the danger and who benefits.","native":"信任会改变风险感知，因为人们不仅评估伤害概率，也会考虑由谁控制危险、谁从中获益。"},{"en":"Effective communication compares like with like and acknowledges emotion, since dismissing fear as irrational usually makes corrective statistics less persuasive.","native":"有效沟通会比较同类事物并承认情绪，因为把恐惧斥为不理性，通常只会削弱纠偏数据的说服力。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C1', 'decision fatigue', 'How does decision fatigue affect judgment, and how can its influence be reduced?', '{"te":{"word":"నిర్ణయ అలసట","question":"నిర్ణయ అలసట విచక్షణను ఎలా ప్రభావితం చేస్తుంది, దాని ప్రభావాన్ని ఎలా తగ్గించవచ్చు?","examples":[{"en":"After repeated choices, people may default to the easiest option, postpone action, or rely on superficial cues instead of evaluating trade-offs carefully.","native":"పదేపదే ఎంపికలు చేసిన తర్వాత ప్రజలు అత్యంత సులభమైన ఎంపికను ఎంచుకోవచ్చు, చర్యను వాయిదా వేయవచ్చు లేదా లాభనష్టాలను జాగ్రత్తగా అంచనా వేయకుండా పైపై సంకేతాలపై ఆధారపడవచ్చు."},{"en":"Routines and sensible defaults conserve attention for consequential decisions, provided that convenience does not quietly remove meaningful choice.","native":"సౌలభ్యం అర్థవంతమైన ఎంపికను నిశ్శబ్దంగా తొలగించనంత వరకు, దినచర్యలు మరియు సమంజసమైన ముందస్తు ఎంపికలు కీలక నిర్ణయాల కోసం శ్రద్ధను ఆదా చేస్తాయి."},{"en":"Institutions should schedule complex judgments when decision-makers are rested and use structured criteria to limit irrelevant variation across cases.","native":"నిర్ణయకర్తలు విశ్రాంతిగా ఉన్నప్పుడు సంస్థలు సంక్లిష్ట నిర్ణయాలను ఏర్పాటు చేసి, కేసుల మధ్య అసంబద్ధమైన వ్యత్యాసాన్ని పరిమితం చేయడానికి నిర్మిత ప్రమాణాలను ఉపయోగించాలి."}]},"hi":{"word":"निर्णय थकान","question":"निर्णय थकान विवेक को कैसे प्रभावित करती है और उसका असर कैसे घटाया जा सकता है?","examples":[{"en":"After repeated choices, people may default to the easiest option, postpone action, or rely on superficial cues instead of evaluating trade-offs carefully.","native":"लगातार चुनाव करने के बाद लोग सबसे आसान विकल्प अपना सकते हैं, कार्रवाई टाल सकते हैं या लाभ-हानि को ध्यान से परखने के बजाय सतही संकेतों पर निर्भर हो सकते हैं।"},{"en":"Routines and sensible defaults conserve attention for consequential decisions, provided that convenience does not quietly remove meaningful choice.","native":"दिनचर्या और समझदार पूर्वनिर्धारित विकल्प महत्त्वपूर्ण निर्णयों के लिए ध्यान बचाते हैं, बशर्ते सुविधा चुपचाप सार्थक चुनाव को समाप्त न करे।"},{"en":"Institutions should schedule complex judgments when decision-makers are rested and use structured criteria to limit irrelevant variation across cases.","native":"संस्थाओं को जटिल निर्णय तब तय करने चाहिए जब निर्णयकर्ता विश्राम कर चुके हों और मामलों के बीच अप्रासंगिक अंतर सीमित करने के लिए संरचित मानदंड अपनाने चाहिए।"}]},"es":{"word":"fatiga decisoria","question":"¿Cómo afecta la fatiga decisoria al juicio y cómo puede reducirse su influencia?","examples":[{"en":"After repeated choices, people may default to the easiest option, postpone action, or rely on superficial cues instead of evaluating trade-offs carefully.","native":"Tras elegir repetidamente, las personas pueden optar por la alternativa más fácil, posponer la acción o fiarse de indicios superficiales en vez de valorar cuidadosamente las contrapartidas."},{"en":"Routines and sensible defaults conserve attention for consequential decisions, provided that convenience does not quietly remove meaningful choice.","native":"Las rutinas y las opciones predeterminadas sensatas reservan atención para decisiones trascendentes, siempre que la comodidad no elimine silenciosamente una elección significativa."},{"en":"Institutions should schedule complex judgments when decision-makers are rested and use structured criteria to limit irrelevant variation across cases.","native":"Las instituciones deberían programar los juicios complejos cuando quienes deciden estén descansados y usar criterios estructurados para limitar variaciones irrelevantes entre casos."}]},"zh":{"word":"决策疲劳","question":"决策疲劳如何影响判断，又该如何减轻其作用？","examples":[{"en":"After repeated choices, people may default to the easiest option, postpone action, or rely on superficial cues instead of evaluating trade-offs carefully.","native":"连续作出多次选择后，人们可能默认采用最省事的方案、推迟行动，或依赖表面线索，而不再仔细权衡得失。"},{"en":"Routines and sensible defaults conserve attention for consequential decisions, provided that convenience does not quietly remove meaningful choice.","native":"日常惯例与合理的默认选项能为重大决策节省注意力，前提是便利不能悄然剥夺有意义的选择。"},{"en":"Institutions should schedule complex judgments when decision-makers are rested and use structured criteria to limit irrelevant variation across cases.","native":"机构应在决策者精力充沛时安排复杂判断，并采用结构化标准，减少不同案例之间无关的差异。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'ethics', 'When scientific innovation creates benefits that are immediate but risks that are uncertain and irreversible, who should bear the burden of ethical justification?', '{"te":{"word":"నైతికత","question":"శాస్త్రీయ ఆవిష్కరణ తక్షణ ప్రయోజనాలను అందిస్తూ అనిశ్చితమైన, తిరిగి సరిచేయలేని ప్రమాదాలను సృష్టించినప్పుడు నైతిక సమర్థన బాధ్యతను ఎవరు భరించాలి?","examples":[{"en":"Ethical oversight should not demand proof of zero risk, yet innovators who profit from uncertainty owe the public transparent evidence and reversible safeguards.","native":"నైతిక పర్యవేక్షణ ప్రమాదమే లేదని రుజువు చేయాలని కోరరాదు; అయితే అనిశ్చితి నుంచి లాభపడే ఆవిష్కర్తలు ప్రజలకు పారదర్శక సాక్ష్యాలను, వెనక్కి తీసుకోగల రక్షణ చర్యలను అందించాలి."},{"en":"The precautionary principle is defensible when potential harm is catastrophic, but applied indiscriminately it can entrench existing dangers by blocking superior alternatives.","native":"సంభావ్య హాని విపత్కరమైనప్పుడు ముందు జాగ్రత్త సూత్రం సమర్థనీయమే; అయితే విచక్షణ లేకుండా దాన్ని వర్తింపజేస్తే మెరుగైన ప్రత్యామ్నాయాలను అడ్డుకోవడం ద్వారా ఇప్పటికే ఉన్న ప్రమాదాలనే స్థిరపరచవచ్చు."},{"en":"Legitimate limits on research require participation from affected communities, because technical expertise alone cannot decide which losses are morally acceptable.","native":"పరిశోధనపై చట్టబద్ధమైన పరిమితులకు ప్రభావిత సముదాయాల భాగస్వామ్యం అవసరం; ఎందుకంటే ఏ నష్టాలు నైతికంగా ఆమోదయోగ్యమో నిర్ణయించడానికి సాంకేతిక నైపుణ్యం ఒక్కటే సరిపోదు."}]},"hi":{"word":"नैतिकता","question":"जब वैज्ञानिक नवाचार तात्कालिक लाभ के साथ अनिश्चित और अपरिवर्तनीय जोखिम पैदा करे, तब नैतिक औचित्य सिद्ध करने का दायित्व किसे उठाना चाहिए?","examples":[{"en":"Ethical oversight should not demand proof of zero risk, yet innovators who profit from uncertainty owe the public transparent evidence and reversible safeguards.","native":"नैतिक निरीक्षण को शून्य जोखिम का प्रमाण नहीं माँगना चाहिए, फिर भी अनिश्चितता से लाभ कमाने वाले नवप्रवर्तकों का दायित्व है कि वे जनता को पारदर्शी साक्ष्य और वापस लिए जा सकने वाले सुरक्षा उपाय दें।"},{"en":"The precautionary principle is defensible when potential harm is catastrophic, but applied indiscriminately it can entrench existing dangers by blocking superior alternatives.","native":"संभावित हानि विनाशकारी हो तो एहतियाती सिद्धांत उचित है, लेकिन अंधाधुंध प्रयोग किए जाने पर वह बेहतर विकल्पों को रोककर मौजूदा खतरों को स्थायी बना सकता है।"},{"en":"Legitimate limits on research require participation from affected communities, because technical expertise alone cannot decide which losses are morally acceptable.","native":"अनुसंधान पर वैध सीमाओं के लिए प्रभावित समुदायों की भागीदारी आवश्यक है, क्योंकि केवल तकनीकी विशेषज्ञता यह तय नहीं कर सकती कि कौन-सी हानियाँ नैतिक रूप से स्वीकार्य हैं।"}]},"es":{"word":"ética","question":"Cuando la innovación científica produce beneficios inmediatos, pero riesgos inciertos e irreversibles, ¿quién debe asumir la carga de justificarla éticamente?","examples":[{"en":"Ethical oversight should not demand proof of zero risk, yet innovators who profit from uncertainty owe the public transparent evidence and reversible safeguards.","native":"La supervisión ética no debe exigir que se demuestre un riesgo nulo, pero quienes se benefician de la incertidumbre deben a la ciudadanía evidencia transparente y salvaguardias reversibles."},{"en":"The precautionary principle is defensible when potential harm is catastrophic, but applied indiscriminately it can entrench existing dangers by blocking superior alternatives.","native":"El principio de precaución es defendible ante daños potencialmente catastróficos, pero aplicado indiscriminadamente puede afianzar los peligros existentes al bloquear alternativas superiores."},{"en":"Legitimate limits on research require participation from affected communities, because technical expertise alone cannot decide which losses are morally acceptable.","native":"Los límites legítimos a la investigación requieren la participación de las comunidades afectadas, porque el conocimiento técnico no puede decidir por sí solo qué pérdidas son moralmente aceptables."}]},"zh":{"word":"伦理","question":"当科学创新带来即时利益，却产生不确定且不可逆的风险时，应由谁承担伦理论证的责任？","examples":[{"en":"Ethical oversight should not demand proof of zero risk, yet innovators who profit from uncertainty owe the public transparent evidence and reversible safeguards.","native":"伦理监督不应要求证明风险为零，但从不确定性中获利的创新者有责任向公众提供透明证据与可撤回的保障措施。"},{"en":"The precautionary principle is defensible when potential harm is catastrophic, but applied indiscriminately it can entrench existing dangers by blocking superior alternatives.","native":"当潜在伤害可能是灾难性的，预防原则可以得到辩护；但若不加区分地运用，它也会阻碍更优选择，使现有危险固化。"},{"en":"Legitimate limits on research require participation from affected communities, because technical expertise alone cannot decide which losses are morally acceptable.","native":"对研究施加正当限制需要受影响社群参与，因为仅凭技术专长无法决定哪些损失在道德上可以接受。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'democracy', 'Can democracy remain self-correcting when economic power, digital platforms, and partisan institutions shape which voices become politically audible?', '{"te":{"word":"ప్రజాస్వామ్యం","question":"ఆర్థిక అధికారం, డిజిటల్ వేదికలు, పక్షపాత సంస్థలు రాజకీయంగా ఏ గొంతులు వినిపించాలో నిర్దేశిస్తున్నప్పుడు ప్రజాస్వామ్యం తనను తాను సరిదిద్దుకోగలదా?","examples":[{"en":"Competitive elections are necessary but insufficient; citizens also need reliable information, associational freedom, and institutions capable of converting dissent into accountable policy.","native":"పోటీ ఎన్నికలు అవసరమే కానీ సరిపోవు; పౌరులకు విశ్వసనీయ సమాచారం, సంఘటితమయ్యే స్వేచ్ఛ, అసమ్మతిని జవాబుదారీ విధానంగా మార్చగల సంస్థలు కూడా అవసరం."},{"en":"Majority rule gains legitimacy only when minorities retain rights robust enough to contest today''s decision and plausibly become tomorrow''s majority.","native":"నేటి నిర్ణయాన్ని సవాలు చేసి రేపటి మెజారిటీగా మారే వాస్తవిక అవకాశం మైనారిటీలకు ఇచ్చేంత బలమైన హక్కులు ఉన్నప్పుడే మెజారిటీ పాలన చట్టబద్ధతను పొందుతుంది."},{"en":"Democratic delay can frustrate urgent action, yet procedures that slow power may prevent temporary panic from hardening into irreversible coercion.","native":"ప్రజాస్వామ్య జాప్యం అత్యవసర చర్యకు ఆటంకం కలిగించవచ్చు; అయితే అధికారాన్ని నెమ్మదింపజేసే ప్రక్రియలు తాత్కాలిక భయాందోళన తిరుగులేని బలవంతంగా మారకుండా నిరోధించవచ్చు."}]},"hi":{"word":"लोकतंत्र","question":"जब आर्थिक शक्ति, डिजिटल मंच और पक्षपाती संस्थाएँ यह तय करें कि कौन-सी आवाजें राजनीति में सुनाई देंगी, तब क्या लोकतंत्र अपनी त्रुटियाँ सुधार सकता है?","examples":[{"en":"Competitive elections are necessary but insufficient; citizens also need reliable information, associational freedom, and institutions capable of converting dissent into accountable policy.","native":"प्रतिस्पर्धी चुनाव आवश्यक हैं, पर पर्याप्त नहीं; नागरिकों को विश्वसनीय सूचना, संगठन बनाने की स्वतंत्रता और असहमति को जवाबदेह नीति में बदल सकने वाली संस्थाएँ भी चाहिए।"},{"en":"Majority rule gains legitimacy only when minorities retain rights robust enough to contest today''s decision and plausibly become tomorrow''s majority.","native":"बहुमत का शासन तभी वैधता पाता है जब अल्पसंख्यकों के अधिकार इतने मजबूत हों कि वे आज के निर्णय को चुनौती दे सकें और कल बहुमत बनने की वास्तविक संभावना रख सकें।"},{"en":"Democratic delay can frustrate urgent action, yet procedures that slow power may prevent temporary panic from hardening into irreversible coercion.","native":"लोकतांत्रिक विलंब तात्कालिक कार्रवाई में बाधा डाल सकता है, फिर भी सत्ता की गति धीमी करने वाली प्रक्रियाएँ क्षणिक घबराहट को अपरिवर्तनीय दमन में बदलने से रोक सकती हैं।"}]},"es":{"word":"democracia","question":"¿Puede la democracia conservar su capacidad de corregirse cuando el poder económico, las plataformas digitales y las instituciones partidistas determinan qué voces se escuchan políticamente?","examples":[{"en":"Competitive elections are necessary but insufficient; citizens also need reliable information, associational freedom, and institutions capable of converting dissent into accountable policy.","native":"Las elecciones competitivas son necesarias, pero insuficientes; la ciudadanía también necesita información fiable, libertad de asociación e instituciones capaces de convertir el disenso en políticas sujetas a rendición de cuentas."},{"en":"Majority rule gains legitimacy only when minorities retain rights robust enough to contest today''s decision and plausibly become tomorrow''s majority.","native":"El gobierno de la mayoría solo adquiere legitimidad cuando las minorías conservan derechos suficientemente sólidos para impugnar la decisión de hoy y poder convertirse de forma plausible en la mayoría de mañana."},{"en":"Democratic delay can frustrate urgent action, yet procedures that slow power may prevent temporary panic from hardening into irreversible coercion.","native":"La demora democrática puede frustrar medidas urgentes, pero los procedimientos que frenan al poder pueden impedir que un pánico pasajero se consolide como coerción irreversible."}]},"zh":{"word":"民主","question":"当经济权力、数字平台和党派机构塑造哪些声音能在政治上被听见时，民主还能保持自我纠错能力吗？","examples":[{"en":"Competitive elections are necessary but insufficient; citizens also need reliable information, associational freedom, and institutions capable of converting dissent into accountable policy.","native":"竞争性选举必不可少，却并不充分；公民还需要可靠的信息、结社自由，以及能把异议转化为可问责政策的制度。"},{"en":"Majority rule gains legitimacy only when minorities retain rights robust enough to contest today''s decision and plausibly become tomorrow''s majority.","native":"只有当少数群体保有足以挑战今日决定、并有现实可能成为明日多数的权利时，多数统治才获得正当性。"},{"en":"Democratic delay can frustrate urgent action, yet procedures that slow power may prevent temporary panic from hardening into irreversible coercion.","native":"民主程序的迟缓可能妨碍紧急行动，但延缓权力的程序也能防止一时恐慌固化为不可逆的强制。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'identity', 'To what extent is identity authored by the individual when language, recognition, and inherited social categories precede personal choice?', '{"te":{"word":"గుర్తింపు","question":"భాష, ఇతరుల గుర్తింపు, వారసత్వంగా వచ్చిన సామాజిక వర్గాలు వ్యక్తిగత ఎంపికకు ముందే ఉన్నప్పుడు వ్యక్తి తన గుర్తింపును ఎంతవరకు స్వయంగా నిర్మించుకుంటాడు?","examples":[{"en":"Identity is neither a private essence nor a passive social label; it emerges through negotiation between self-interpretation and recognition by others.","native":"గుర్తింపు వ్యక్తిగత అంతఃసారం కాదు, నిష్క్రియ సామాజిక ముద్ర కూడా కాదు; స్వీయ వ్యాఖ్యానం, ఇతరుల గుర్తింపు మధ్య సంప్రదింపుల ద్వారా అది ఉద్భవిస్తుంది."},{"en":"Multilingual speakers may inhabit different emotional and moral registers without possessing fragmented or inauthentic selves.","native":"బహుభాషావేత్తలు విభజితమైన లేదా ప్రామాణికత లేని స్వరూపాలు కలిగి ఉండకుండానే భిన్న భావోద్వేగ, నైతిక పరిధుల్లో జీవించగలరు."},{"en":"Protecting collective identities can repair historical erasure, but it becomes oppressive when membership fixes what individuals are permitted to become.","native":"సామూహిక గుర్తింపులను కాపాడటం చారిత్రక చెరిపివేతను సరిచేయగలదు; అయితే సభ్యులు ఏమిగా మారవచ్చో సభ్యత్వమే స్థిరంగా నిర్ణయించినప్పుడు అది అణచివేతగా మారుతుంది."}]},"hi":{"word":"पहचान","question":"जब भाषा, दूसरों से मिलने वाली मान्यता और विरासत में मिली सामाजिक श्रेणियाँ निजी चुनाव से पहले मौजूद हों, तब व्यक्ति अपनी पहचान का निर्माण किस हद तक स्वयं करता है?","examples":[{"en":"Identity is neither a private essence nor a passive social label; it emerges through negotiation between self-interpretation and recognition by others.","native":"पहचान न तो कोई निजी सार है, न निष्क्रिय सामाजिक ठप्पा; वह आत्म-व्याख्या और दूसरों से मिलने वाली मान्यता के बीच संवाद से उभरती है।"},{"en":"Multilingual speakers may inhabit different emotional and moral registers without possessing fragmented or inauthentic selves.","native":"बहुभाषी वक्ता खंडित या अप्रामाणिक व्यक्तित्व रखे बिना अलग-अलग भावनात्मक और नैतिक अभिव्यक्ति-क्षेत्रों में रह सकते हैं।"},{"en":"Protecting collective identities can repair historical erasure, but it becomes oppressive when membership fixes what individuals are permitted to become.","native":"सामूहिक पहचानों की रक्षा ऐतिहासिक विलोपन की भरपाई कर सकती है, लेकिन जब सदस्यता यह तय कर दे कि व्यक्तियों को क्या बनने की अनुमति है, तब वह दमनकारी हो जाती है।"}]},"es":{"word":"identidad","question":"¿Hasta qué punto construye el individuo su identidad cuando el lenguaje, el reconocimiento y las categorías sociales heredadas preceden a la elección personal?","examples":[{"en":"Identity is neither a private essence nor a passive social label; it emerges through negotiation between self-interpretation and recognition by others.","native":"La identidad no es una esencia privada ni una etiqueta social pasiva; surge de la negociación entre la interpretación propia y el reconocimiento ajeno."},{"en":"Multilingual speakers may inhabit different emotional and moral registers without possessing fragmented or inauthentic selves.","native":"Las personas multilingües pueden habitar registros emocionales y morales distintos sin poseer identidades fragmentadas ni carentes de autenticidad."},{"en":"Protecting collective identities can repair historical erasure, but it becomes oppressive when membership fixes what individuals are permitted to become.","native":"Proteger las identidades colectivas puede reparar un borrado histórico, pero resulta opresivo cuando la pertenencia determina en qué se permite convertirse a cada individuo."}]},"zh":{"word":"身份认同","question":"当语言、他人的承认以及继承而来的社会范畴先于个人选择存在时，身份在多大程度上由个人书写？","examples":[{"en":"Identity is neither a private essence nor a passive social label; it emerges through negotiation between self-interpretation and recognition by others.","native":"身份既不是私密的本质，也不是被动接受的社会标签；它产生于自我诠释与他人承认之间的协商。"},{"en":"Multilingual speakers may inhabit different emotional and moral registers without possessing fragmented or inauthentic selves.","native":"多语言使用者可以置身于不同的情感与道德语域，而不必因此拥有破碎或不真实的自我。"},{"en":"Protecting collective identities can repair historical erasure, but it becomes oppressive when membership fixes what individuals are permitted to become.","native":"保护集体身份可以弥补历史上的抹除，但当成员资格限定个人可以成为什么样的人时，这种保护就会变成压迫。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'inequality', 'Why can inequality persist even when formal discrimination is prohibited and many individuals appear to compete under the same rules?', '{"te":{"word":"అసమానత","question":"లాంఛనప్రాయ వివక్షను నిషేధించి, అనేక మంది ఒకే నియమాల కింద పోటీ పడుతున్నట్లు కనిపించినప్పటికీ అసమానత ఎందుకు కొనసాగగలదు?","examples":[{"en":"Apparently neutral institutions reproduce inequality when inherited wealth, social networks, and exposure to risk determine who can exploit the opportunities on offer.","native":"వారసత్వ సంపద, సామాజిక సంబంధాలు, ప్రమాదానికి గురయ్యే స్థాయి అందుబాటులో ఉన్న అవకాశాలను ఎవరు సద్వినియోగం చేసుకోగలరో నిర్ణయించినప్పుడు పైకి తటస్థంగా కనిపించే సంస్థలు అసమానతను పునరుత్పత్తి చేస్తాయి."},{"en":"Redistribution addresses unequal outcomes, whereas structural reform asks how markets and public policy assign bargaining power before income is distributed.","native":"పునర్వితరణ అసమాన ఫలితాలను పరిష్కరిస్తుంది; నిర్మాణాత్మక సంస్కరణ మాత్రం ఆదాయం పంపిణీ కాకముందే మార్కెట్లు, ప్రజా విధానం బేరసారాల శక్తిని ఎలా కేటాయిస్తాయో ప్రశ్నిస్తుంది."},{"en":"Some inequality may reward contribution, but extreme disparities become self-reinforcing when wealth purchases political influence and insulation from shared institutions.","native":"కొంత అసమానత చేసిన కృషికి ప్రతిఫలం ఇవ్వవచ్చు; అయితే సంపద రాజకీయ ప్రభావాన్ని, ఉమ్మడి సంస్థల నుంచి రక్షణను కొనుగోలు చేసినప్పుడు తీవ్ర వ్యత్యాసాలు తమను తామే బలపరచుకుంటాయి."}]},"hi":{"word":"असमानता","question":"औपचारिक भेदभाव निषिद्ध होने और अनेक लोगों के समान नियमों के तहत प्रतिस्पर्धा करते दिखने पर भी असमानता क्यों बनी रह सकती है?","examples":[{"en":"Apparently neutral institutions reproduce inequality when inherited wealth, social networks, and exposure to risk determine who can exploit the opportunities on offer.","native":"जब विरासत में मिली संपत्ति, सामाजिक संपर्क और जोखिम के प्रति असुरक्षा यह तय करते हैं कि उपलब्ध अवसरों का लाभ कौन उठा सकता है, तब ऊपर से तटस्थ दिखने वाली संस्थाएँ असमानता को दोबारा पैदा करती हैं।"},{"en":"Redistribution addresses unequal outcomes, whereas structural reform asks how markets and public policy assign bargaining power before income is distributed.","native":"पुनर्वितरण असमान परिणामों को संबोधित करता है, जबकि संरचनात्मक सुधार पूछता है कि आय बाँटे जाने से पहले बाजार और सार्वजनिक नीति सौदेबाजी की शक्ति कैसे निर्धारित करते हैं।"},{"en":"Some inequality may reward contribution, but extreme disparities become self-reinforcing when wealth purchases political influence and insulation from shared institutions.","native":"कुछ असमानता योगदान को पुरस्कृत कर सकती है, लेकिन जब संपत्ति राजनीतिक प्रभाव और साझा संस्थाओं से बचाव खरीदने लगे, तब चरम विषमताएँ स्वयं को मजबूत करती जाती हैं।"}]},"es":{"word":"desigualdad","question":"¿Por qué puede persistir la desigualdad aun cuando se prohíbe la discriminación formal y muchas personas parecen competir bajo las mismas reglas?","examples":[{"en":"Apparently neutral institutions reproduce inequality when inherited wealth, social networks, and exposure to risk determine who can exploit the opportunities on offer.","native":"Las instituciones aparentemente neutrales reproducen la desigualdad cuando la riqueza heredada, las redes sociales y la exposición al riesgo determinan quién puede aprovechar las oportunidades disponibles."},{"en":"Redistribution addresses unequal outcomes, whereas structural reform asks how markets and public policy assign bargaining power before income is distributed.","native":"La redistribución aborda resultados desiguales, mientras que la reforma estructural pregunta cómo los mercados y las políticas públicas asignan poder de negociación antes de distribuir los ingresos."},{"en":"Some inequality may reward contribution, but extreme disparities become self-reinforcing when wealth purchases political influence and insulation from shared institutions.","native":"Cierta desigualdad puede recompensar la contribución, pero las disparidades extremas se perpetúan cuando la riqueza compra influencia política y aislamiento frente a las instituciones compartidas."}]},"zh":{"word":"不平等","question":"即使正式歧视已被禁止，而且许多人看似遵循相同规则竞争，不平等为何仍能持续？","examples":[{"en":"Apparently neutral institutions reproduce inequality when inherited wealth, social networks, and exposure to risk determine who can exploit the opportunities on offer.","native":"当继承财富、社会关系与风险暴露程度决定谁能利用现有机会时，看似中立的制度会不断复制不平等。"},{"en":"Redistribution addresses unequal outcomes, whereas structural reform asks how markets and public policy assign bargaining power before income is distributed.","native":"再分配处理的是不平等结果，而结构性改革追问市场与公共政策如何在收入分配之前配置议价能力。"},{"en":"Some inequality may reward contribution, but extreme disparities become self-reinforcing when wealth purchases political influence and insulation from shared institutions.","native":"某种程度的不平等或许能奖励贡献，但当财富可以买到政治影响力并使人脱离共同制度时，极端差距便会自我强化。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'sustainability', 'Can an economy become genuinely sustainable while its stability still depends on expanding consumption and shifting ecological costs beyond its borders?', '{"te":{"word":"సుస్థిరత","question":"వినియోగాన్ని విస్తరించడం, పర్యావరణ వ్యయాలను తన సరిహద్దుల అవతలకు మళ్లించడం పైనే స్థిరత్వం ఆధారపడుతున్నంతకాలం ఒక ఆర్థిక వ్యవస్థ నిజంగా సుస్థిరంగా మారగలదా?","examples":[{"en":"Efficiency gains reduce resource use per unit, yet rebound effects can erase those savings when lower costs stimulate greater overall consumption.","native":"సామర్థ్య మెరుగుదలలు ప్రతి యూనిట్‌కు వనరుల వినియోగాన్ని తగ్గిస్తాయి; అయితే తక్కువ ఖర్చులు మొత్తం వినియోగాన్ని పెంచినప్పుడు రీబౌండ్ ప్రభావాలు ఆ పొదుపును చెరిపివేయగలవు."},{"en":"Green growth is plausible in selected sectors, but claims of absolute decoupling must account for imported emissions, material extraction, and biodiversity loss.","native":"ఎంచుకున్న రంగాల్లో హరిత వృద్ధి సాధ్యమే; అయితే వృద్ధిని పర్యావరణ హాని నుంచి పూర్తిగా వేరు చేశామనే వాదనలు దిగుమతి ఉద్గారాలు, ముడి పదార్థాల వెలికితీత, జీవవైవిధ్య నష్టాన్ని కూడా లెక్కలోకి తీసుకోవాలి."},{"en":"Sustainability requires institutions that treat ecological limits as binding constraints while distributing the costs of transition without deepening poverty.","native":"పేదరికాన్ని మరింత పెంచకుండా పరివర్తన వ్యయాలను పంచుతూనే పర్యావరణ పరిమితులను తప్పనిసరి నియంత్రణలుగా పరిగణించే సంస్థలు సుస్థిరతకు అవసరం."}]},"hi":{"word":"सततता","question":"जब किसी अर्थव्यवस्था की स्थिरता अब भी बढ़ते उपभोग और पर्यावरणीय लागतों को अपनी सीमाओं से बाहर धकेलने पर निर्भर हो, तब क्या वह वास्तव में सतत बन सकती है?","examples":[{"en":"Efficiency gains reduce resource use per unit, yet rebound effects can erase those savings when lower costs stimulate greater overall consumption.","native":"दक्षता में वृद्धि प्रति इकाई संसाधन उपयोग घटाती है, फिर भी कम लागत से कुल उपभोग बढ़ने पर प्रतिक्षेप प्रभाव उस बचत को मिटा सकते हैं।"},{"en":"Green growth is plausible in selected sectors, but claims of absolute decoupling must account for imported emissions, material extraction, and biodiversity loss.","native":"चुनिंदा क्षेत्रों में हरित विकास संभव है, लेकिन विकास और पर्यावरणीय क्षति के पूर्ण पृथक्करण के दावों में आयातित उत्सर्जन, कच्चे माल का निष्कर्षण और जैव विविधता की हानि भी शामिल होनी चाहिए।"},{"en":"Sustainability requires institutions that treat ecological limits as binding constraints while distributing the costs of transition without deepening poverty.","native":"सततता के लिए ऐसी संस्थाएँ चाहिए जो पर्यावरणीय सीमाओं को बाध्यकारी मानें और गरीबी बढ़ाए बिना परिवर्तन की लागतों का वितरण करें।"}]},"es":{"word":"sostenibilidad","question":"¿Puede una economía llegar a ser verdaderamente sostenible si su estabilidad aún depende de ampliar el consumo y trasladar los costes ecológicos más allá de sus fronteras?","examples":[{"en":"Efficiency gains reduce resource use per unit, yet rebound effects can erase those savings when lower costs stimulate greater overall consumption.","native":"Las mejoras de eficiencia reducen el uso de recursos por unidad, pero los efectos rebote pueden borrar ese ahorro cuando los menores costes estimulan un mayor consumo total."},{"en":"Green growth is plausible in selected sectors, but claims of absolute decoupling must account for imported emissions, material extraction, and biodiversity loss.","native":"El crecimiento verde es plausible en ciertos sectores, pero las afirmaciones de desacoplamiento absoluto deben contabilizar las emisiones importadas, la extracción de materiales y la pérdida de biodiversidad."},{"en":"Sustainability requires institutions that treat ecological limits as binding constraints while distributing the costs of transition without deepening poverty.","native":"La sostenibilidad requiere instituciones que traten los límites ecológicos como restricciones vinculantes y distribuyan los costes de la transición sin agravar la pobreza."}]},"zh":{"word":"可持续发展","question":"如果一个经济体的稳定仍依赖扩大消费，并把生态成本转移到境外，它能否实现真正的可持续发展？","examples":[{"en":"Efficiency gains reduce resource use per unit, yet rebound effects can erase those savings when lower costs stimulate greater overall consumption.","native":"效率提升会减少单位产出的资源使用，但当成本降低刺激总体消费增长时，反弹效应可能抵消这些节约。"},{"en":"Green growth is plausible in selected sectors, but claims of absolute decoupling must account for imported emissions, material extraction, and biodiversity loss.","native":"绿色增长在某些行业具有可行性，但宣称实现绝对脱钩时，必须计入进口排放、原料开采与生物多样性损失。"},{"en":"Sustainability requires institutions that treat ecological limits as binding constraints while distributing the costs of transition without deepening poverty.","native":"可持续发展需要制度把生态界限视为具有约束力的限制，同时在不加剧贫困的前提下分担转型成本。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'philosophy', 'What distinctive contribution can philosophy make to public life when empirical sciences supply facts and democratic institutions authorize collective decisions?', '{"te":{"word":"తత్వశాస్త్రం","question":"అనుభవాధారిత శాస్త్రాలు వాస్తవాలను అందిస్తూ, ప్రజాస్వామ్య సంస్థలు సామూహిక నిర్ణయాలకు అధికారాన్ని ఇస్తున్నప్పుడు ప్రజా జీవితానికి తత్వశాస్త్రం ఏ విశిష్ట సహకారం అందించగలదు?","examples":[{"en":"Philosophy clarifies the concepts hidden inside practical disputes, revealing when opponents invoke the same words while defending incompatible standards.","native":"ఆచరణాత్మక వివాదాల్లో దాగి ఉన్న భావనలను తత్వశాస్త్రం స్పష్టం చేస్తుంది; ప్రత్యర్థులు ఒకే పదాలను ఉపయోగిస్తూ పరస్పర విరుద్ధ ప్రమాణాలను సమర్థిస్తున్న సందర్భాలను అది బయటపెడుతుంది."},{"en":"Empirical evidence can predict a policy''s effects, but it cannot by itself determine which risks, rights, or distributions a society ought to accept.","native":"అనుభవాధారిత సాక్ష్యం ఒక విధానం ప్రభావాలను అంచనా వేయగలదు; కానీ ఒక సమాజం ఏ ప్రమాదాలను, హక్కులను లేదా పంపిణీ విధానాలను అంగీకరించాలో నిర్ణయించడానికి అది ఒక్కటే సరిపోదు."},{"en":"Philosophical criticism is publicly useful when it exposes assumptions and enlarges alternatives, not when abstraction becomes a substitute for accountable judgment.","native":"తాత్విక విమర్శ ఊహలను బయటపెట్టి ప్రత్యామ్నాయాలను విస్తరించినప్పుడు ప్రజలకు ఉపయోగపడుతుంది; నైరూప్యత జవాబుదారీ విచక్షణకు ప్రత్యామ్నాయమైనప్పుడు కాదు."}]},"hi":{"word":"दर्शनशास्त्र","question":"जब अनुभवजन्य विज्ञान तथ्य उपलब्ध कराते हैं और लोकतांत्रिक संस्थाएँ सामूहिक निर्णयों को अधिकार देती हैं, तब दर्शन सार्वजनिक जीवन में कौन-सा विशिष्ट योगदान कर सकता है?","examples":[{"en":"Philosophy clarifies the concepts hidden inside practical disputes, revealing when opponents invoke the same words while defending incompatible standards.","native":"दर्शन व्यावहारिक विवादों में छिपी अवधारणाओं को स्पष्ट करता है और दिखाता है कि विरोधी कब उन्हीं शब्दों का प्रयोग करते हुए परस्पर असंगत मानकों का समर्थन कर रहे हैं।"},{"en":"Empirical evidence can predict a policy''s effects, but it cannot by itself determine which risks, rights, or distributions a society ought to accept.","native":"अनुभवजन्य साक्ष्य किसी नीति के प्रभावों का अनुमान लगा सकता है, लेकिन वह अपने आप यह तय नहीं कर सकता कि समाज को कौन-से जोखिम, अधिकार या वितरण स्वीकार करने चाहिए।"},{"en":"Philosophical criticism is publicly useful when it exposes assumptions and enlarges alternatives, not when abstraction becomes a substitute for accountable judgment.","native":"दार्शनिक आलोचना तब सार्वजनिक रूप से उपयोगी होती है जब वह मान्यताओं को उजागर करे और विकल्प बढ़ाए, न कि तब जब अमूर्तन जवाबदेह विवेक का स्थान ले ले।"}]},"es":{"word":"filosofía","question":"¿Qué contribución distintiva puede hacer la filosofía a la vida pública cuando las ciencias empíricas aportan hechos y las instituciones democráticas autorizan decisiones colectivas?","examples":[{"en":"Philosophy clarifies the concepts hidden inside practical disputes, revealing when opponents invoke the same words while defending incompatible standards.","native":"La filosofía aclara los conceptos ocultos en las disputas prácticas y revela cuándo los adversarios invocan las mismas palabras mientras defienden criterios incompatibles."},{"en":"Empirical evidence can predict a policy''s effects, but it cannot by itself determine which risks, rights, or distributions a society ought to accept.","native":"La evidencia empírica puede predecir los efectos de una política, pero no puede determinar por sí sola qué riesgos, derechos o distribuciones debe aceptar una sociedad."},{"en":"Philosophical criticism is publicly useful when it exposes assumptions and enlarges alternatives, not when abstraction becomes a substitute for accountable judgment.","native":"La crítica filosófica resulta públicamente útil cuando revela supuestos y amplía alternativas, no cuando la abstracción sustituye al juicio responsable."}]},"zh":{"word":"哲学","question":"当经验科学提供事实、民主制度授权集体决策时，哲学能为公共生活作出何种独特贡献？","examples":[{"en":"Philosophy clarifies the concepts hidden inside practical disputes, revealing when opponents invoke the same words while defending incompatible standards.","native":"哲学澄清实践争议中隐藏的概念，揭示对立双方何时使用相同词语，却在捍卫彼此不相容的标准。"},{"en":"Empirical evidence can predict a policy''s effects, but it cannot by itself determine which risks, rights, or distributions a society ought to accept.","native":"经验证据可以预测政策的影响，却无法单独决定社会应当接受哪些风险、权利安排或分配方式。"},{"en":"Philosophical criticism is publicly useful when it exposes assumptions and enlarges alternatives, not when abstraction becomes a substitute for accountable judgment.","native":"哲学批判只有在揭示假设并拓展选择时才具有公共价值，而不是让抽象思辨取代可问责的判断。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'ambiguity', 'Discuss how societies differ in their tolerance of ambiguity, and the consequences.', '{"te":{"word":"అస్పష్టత","question":"అస్పష్టత పట్ల సహనంలో సమాజాలు ఎలా భిన్నంగా ఉంటాయి మరియు దాని పరిణామాలు ఏమిటో చర్చించండి.","examples":[{"en":"Cultures that embrace ambiguity tend to foster creativity, whereas those that demand certainty often stifle experimentation and punish honest doubt.","native":"అస్పష్టతను ఆలింగనం చేసుకునే సంస్కృతులు సృజనాత్మకతను ప్రోత్సహిస్తాయి, అయితే ఖచ్చితత్వాన్ని కోరేవి ప్రయోగాలను కుదిపేస్తాయి, నిజాయితీగల సందేహాన్ని శిక్షిస్తాయి."},{"en":"Ambiguity in language is not merely a defect to be eliminated; it is the space in which poetry, diplomacy, and humour become possible.","native":"భాషలోని అస్పష్టత తొలగించవలసిన లోపం మాత్రమే కాదు; కవిత్వం, దౌత్యం మరియు హాస్యం సాధ్యమయ్యే ఖాళీ అది."},{"en":"A person who cannot tolerate ambiguity will grasp at simplistic answers, while the mature mind learns to act decisively without complete information.","native":"అస్పష్టతను సహించలేని వ్యక్తి సరళమైన సమాధానాల వైపు పరుగులు తీస్తాడు, అయితే పరిపక్వమైన మనస్థితి పూర్తి సమాచారం లేకుండానే దృఢంగా నిర్ణయం తీసుకోవడం నేర్చుకుంటుంది."}]},"hi":{"word":"अस्पष्टता","question":"चर्चा कीजिए कि समाज अस्पष्टता के प्रति सहिष्णुता में कैसे भिन्न होते हैं और इसके क्या परिणाम होते हैं।","examples":[{"en":"Cultures that embrace ambiguity tend to foster creativity, whereas those that demand certainty often stifle experimentation and punish honest doubt.","native":"जो संस्कृतियाँ अस्पष्टता को अपनाती हैं, वे रचनात्मकता को बढ़ावा देती हैं, जबकि जो निश्चितता की माँग करती हैं, वे प्रयोग को दबा देती हैं और ईमानदार संदेह को दंडित करती हैं।"},{"en":"Ambiguity in language is not merely a defect to be eliminated; it is the space in which poetry, diplomacy, and humour become possible.","native":"भाषा में अस्पष्टता केवल दूर करने योग्य दोष नहीं है; यह वह स्थान है जहाँ कविता, कूटनीति और हास्य संभव होते हैं।"},{"en":"A person who cannot tolerate ambiguity will grasp at simplistic answers, while the mature mind learns to act decisively without complete information.","native":"जो व्यक्ति अस्पष्टता सहन नहीं कर सकता, वह सरल उत्तरों की ओर दौड़ता है, जबकि परिपक्व मन अधूरी जानकारी के बिना भी निर्णायक रूप से कार्य करना सीखता है।"}]},"es":{"word":"ambigüedad","question":"Analiza cómo difieren las sociedades en su tolerancia a la ambigüedad y cuáles son las consecuencias.","examples":[{"en":"Cultures that embrace ambiguity tend to foster creativity, whereas those that demand certainty often stifle experimentation and punish honest doubt.","native":"Las culturas que abrazan la ambigüedad tienden a fomentar la creatividad, mientras que las que exigen certeza a menudo ahogan la experimentación y castigan la duda honesta."},{"en":"Ambiguity in language is not merely a defect to be eliminated; it is the space in which poetry, diplomacy, and humour become possible.","native":"La ambigüedad en el lenguaje no es solo un defecto que eliminar; es el espacio donde la poesía, la diplomacia y el humor se hacen posibles."},{"en":"A person who cannot tolerate ambiguity will grasp at simplistic answers, while the mature mind learns to act decisively without complete information.","native":"Quien no tolera la ambigüedad se aferra a respuestas simplistas, mientras que la mente madura aprende a actuar con decisión sin información completa."}]},"zh":{"word":"模糊性","question":"请讨论不同社会对模糊性的容忍度有何差异，以及由此带来的后果。","examples":[{"en":"Cultures that embrace ambiguity tend to foster creativity, whereas those that demand certainty often stifle experimentation and punish honest doubt.","native":"拥抱模糊性的文化往往能孕育创造力，而一味追求确定性的文化则常常扼杀尝试，惩罚诚实的怀疑。"},{"en":"Ambiguity in language is not merely a defect to be eliminated; it is the space in which poetry, diplomacy, and humour become possible.","native":"语言中的模糊性并非只是需要消除的缺陷；它是诗歌、外交与幽默得以存在的空间。"},{"en":"A person who cannot tolerate ambiguity will grasp at simplistic answers, while the mature mind learns to act decisively without complete information.","native":"无法容忍模糊的人会抓住简单化的答案不放，而成熟的心智学会在信息不完备时依然果断行动。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'justice', 'Is justice primarily about punishment, fairness, or restoring what was broken?', '{"te":{"word":"న్యాయం","question":"న్యాయం అనేది ప్రధానంగా శిక్ష గురించా, సమానత్వం గురించా, లేదా దెబ్బతిన్న దాన్ని సరిచేయడం గురించా?","examples":[{"en":"Justice that focuses only on punishment may satisfy our anger, yet it often fails to repair the harm suffered by victims and communities.","native":"శిక్షపై మాత్రమే దృష్టి పెట్టే న్యాయం మన కోపాన్ని తీర్చగలదు, అయితే బాధితులకు మరియు సమాజాలకు జరిగిన హానిని సరిచేయడంలో తరచుగా విఫలమవుతుంది."},{"en":"True fairness requires not merely treating everyone identically, but recognizing that people begin from profoundly unequal positions in life.","native":"నిజమైన సమానత్వం అందరితో ఒకేలా ప్రవర్తించడం మాత్రమే కాదు, ప్రజలు జీవితంలో అత్యంత అసమానమైన స్థానాల నుండి ప్రారంభమవుతారని గుర్తించడం కూడా అవసరం."},{"en":"Restorative approaches ask what was broken and who must be healed, whereas retributive systems ask only who broke the rule and how to hurt them.","native":"పునరావాస విధానాలు ఏమి దెబ్బతింది, ఎవరు క్షోభిస్తున్నారు అని అడుగుతాయి, అయితే ప్రతీకార వ్యవస్థలు ఎవరు నియమం ఉల్లంఘించారు, వారిని ఎలా బాధపెట్టాలి అని మాత్రమే అడుగుతాయి."}]},"hi":{"word":"न्याय","question":"क्या न्याय मुख्य रूप से दंड, निष्पक्षता या टूटी हुई चीज़ को सुधारने के बारे में है?","examples":[{"en":"Justice that focuses only on punishment may satisfy our anger, yet it often fails to repair the harm suffered by victims and communities.","native":"जो न्याय केवल दंड पर केंद्रित हो, वह हमारे क्रोध को शांत कर सकता है, फिर भी वह पीड़ितों और समुदायों की हानि की भरपाई में अक्सर असफल रहता है।"},{"en":"True fairness requires not merely treating everyone identically, but recognizing that people begin from profoundly unequal positions in life.","native":"सच्ची निष्पक्षता के लिए सिर्फ़ सबके साथ एक जैसा व्यवहार ही नहीं, बल्कि यह पहचानना भी ज़रूरी है कि लोग जीवन में बेहद असमान स्थितियों से शुरुआत करते हैं।"},{"en":"Restorative approaches ask what was broken and who must be healed, whereas retributive systems ask only who broke the rule and how to hurt them.","native":"पुनर्स्थापनात्मक दृष्टिकोण पूछते हैं कि क्या टूटा और किसे चंगा किया जाना चाहिए, जबकि प्रतिशोधी व्यवस्थाएँ केवल यह पूछती हैं कि नियम किसने तोड़ा और उसे कैसे दर्द दिया जाए।"}]},"es":{"word":"justicia","question":"¿Es la justicia principalmente cuestión de castigo, de equidad o de reparar lo que se ha roto?","examples":[{"en":"Justice that focuses only on punishment may satisfy our anger, yet it often fails to repair the harm suffered by victims and communities.","native":"La justicia centrada solo en el castigo puede satisfacer nuestra ira, pero a menudo no repara el daño sufrido por las víctimas y las comunidades."},{"en":"True fairness requires not merely treating everyone identically, but recognizing that people begin from profoundly unequal positions in life.","native":"La verdadera equidad no consiste únicamente en tratar a todos por igual, sino en reconocer que las personas parten de posiciones profundamente desiguales."},{"en":"Restorative approaches ask what was broken and who must be healed, whereas retributive systems ask only who broke the rule and how to hurt them.","native":"Los enfoques restaurativos preguntan qué se rompió y a quién hay que sanar, mientras que los sistemas retributivos solo preguntan quién infringió la norma y cómo castigarlo."}]},"zh":{"word":"正义","question":"正义主要关乎惩罚、公平，还是修复被破坏的事物？","examples":[{"en":"Justice that focuses only on punishment may satisfy our anger, yet it often fails to repair the harm suffered by victims and communities.","native":"只关注惩罚的正义或许能平息我们的愤怒，却往往无法修复受害者和社群所遭受的伤害。"},{"en":"True fairness requires not merely treating everyone identically, but recognizing that people begin from profoundly unequal positions in life.","native":"真正的公平不仅仅是一视同仁，更在于承认人们的人生起点本就极不平等。"},{"en":"Restorative approaches ask what was broken and who must be healed, whereas retributive systems ask only who broke the rule and how to hurt them.","native":"恢复性司法追问的是什么被破坏、谁需要治愈，而报复性司法只问谁违反了规则、该如何让其付出代价。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'autonomy', 'Should individual autonomy ever be restricted for a person''s own good?', '{"te":{"word":"స్వయం ప్రాధిపత్యం","question":"ఒక వ్యక్తి స్వంత మంచి కోసం అతని స్వయం ప్రాధిపత్యాన్ని ఎప్పుడైనా పరిమితం చేయాలా?","examples":[{"en":"Autonomy is meaningless unless it includes the right to make choices that others consider unwise, provided no one else is harmed by them.","native":"ఇతరులు వివేకహీనమని భావించే ఎంపికలు చేసుకునే హక్కు లేకపోతే స్వయం ప్రాధిపత్యం అర్థరహితం — ఎవరికీ హాని జరగకుండా ఉంటేనే."},{"en":"When the state restricts our freedom for our own protection, it quietly assumes that it knows our interests better than we ever could.","native":"మన రక్షణ కోసం ప్రభుత్వం మన స్వేచ్ఛను పరిమితం చేసినప్పుడు, మన ప్రయోజనాలు మనకంటే తనకు బాగా తెలుసని అది నిశ్శబ్దంగా ఊహిస్తుంది."},{"en":"Children rightly have their autonomy curtailed because their judgment is undeveloped, yet extending the same logic to adults infantilizes citizens.","native":"పిల్లల తీర్పు ఇంకా పరిపక్వం కాకపోవడంతో వారి స్వయం ప్రాధిపత్యాన్ని పరిమితం చేయడం సరైనదే, అయితే అదే తర్కాన్ని పెద్దలకు వర్తింపజేయడం పౌరులను చిన్నపిల్లల్లా చేయడమే."}]},"hi":{"word":"स्वायत्तता","question":"क्या किसी व्यक्ति के अपने हित के लिए उसकी स्वायत्तता पर कभी रोक लगाई जानी चाहिए?","examples":[{"en":"Autonomy is meaningless unless it includes the right to make choices that others consider unwise, provided no one else is harmed by them.","native":"स्वायत्तता तब तक अर्थहीन है जब तक उसमें ऐसे चुनाव करने का अधिकार शामिल न हो जिन्हें दूसरे अनुचित मानते हों, बशर्ते किसी और को उनसे नुकसान न पहुँचे।"},{"en":"When the state restricts our freedom for our own protection, it quietly assumes that it knows our interests better than we ever could.","native":"जब राज्य हमारी रक्षा के लिए हमारी स्वतंत्रता सीमित करता है, तो वह चुपचाप यह मान लेता है कि वह हमारे हित हमसे बेहतर जानता है।"},{"en":"Children rightly have their autonomy curtailed because their judgment is undeveloped, yet extending the same logic to adults infantilizes citizens.","native":"बच्चों की स्वायत्तता पर रोक उचित है क्योंकि उनकी समझ अविकसित होती है, पर यही तर्क वयस्कों पर लागू करना नागरिकों को बच्चा बनाना है।"}]},"es":{"word":"autonomía","question":"¿Debería restringirse alguna vez la autonomía individual por el bien de la propia persona?","examples":[{"en":"Autonomy is meaningless unless it includes the right to make choices that others consider unwise, provided no one else is harmed by them.","native":"La autonomía carece de sentido si no incluye el derecho a tomar decisiones que otros consideran imprudentes, siempre que nadie más resulte perjudicado."},{"en":"When the state restricts our freedom for our own protection, it quietly assumes that it knows our interests better than we ever could.","native":"Cuando el Estado restringe nuestra libertad para protegernos, asume tácitamente que conoce nuestros intereses mejor que nosotros mismos."},{"en":"Children rightly have their autonomy curtailed because their judgment is undeveloped, yet extending the same logic to adults infantilizes citizens.","native":"Es justo limitar la autonomía de los niños porque su juicio es inmaduro, pero aplicar esa misma lógica a los adultos infantiliza a los ciudadanos."}]},"zh":{"word":"自主权","question":"是否应该为了一个人自身的利益而限制其个人自主权？","examples":[{"en":"Autonomy is meaningless unless it includes the right to make choices that others consider unwise, provided no one else is harmed by them.","native":"除非自主包含做出他人认为不明智之选择的权利——只要不伤害他人——否则自主便毫无意义。"},{"en":"When the state restricts our freedom for our own protection, it quietly assumes that it knows our interests better than we ever could.","native":"当国家以保护我们为由限制我们的自由时，它实际上默认自己比我们更了解我们的利益。"},{"en":"Children rightly have their autonomy curtailed because their judgment is undeveloped, yet extending the same logic to adults infantilizes citizens.","native":"限制儿童的自主权是正当的，因为他们的判断力尚未成熟；但把同样的逻辑套用到成年人身上，无异于把公民当作孩童。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'truth', 'Can a society function when its members no longer agree on what is true?', '{"te":{"word":"సత్యం","question":"ఏది సత్యమో దానిపై సభ్యులు ఇక ఏకాభిప్రాయపడనప్పుడు ఒక సమాజం పనిచేయగలదా?","examples":[{"en":"A shared reality is the invisible infrastructure of public life, and when it collapses, every disagreement becomes a war between rival worlds.","native":"పంచుకున్న వాస్తవికత ప్రజా జీవితం యొక్క అదృశ్యమైన మౌలిక సదుపాయం; అది కూలిపోయినప్పుడు, ప్రతి విభేదం ప్రత్యర్థి ప్రపంచాల మధ్య యుద్ధమవుతుంది."},{"en":"Truth is not determined by consensus, yet a community that cannot agree on how to establish facts will soon be unable to govern itself.","native":"సత్యం సర్వసమ్మతితో నిర్ణయించబడదు, అయితే వాస్తవాలను ఎలా స్థాపించాలో ఏకమవ్వలేని సమాజం త్వరలో తమను తాము పాలించుకోలేని స్థితికి చేరుతుంది."},{"en":"Those who declare that truth is whatever power says it is have usually mistaken their own voice for the voice of power.","native":"అధికారం చెప్పిందే సత్యమని ప్రకటించేవారు సాధారణంగా తమ స్వంత గొంతును అధికారం యొక్క గొంతుగా పొరపడతారు."}]},"hi":{"word":"सत्य","question":"जब समाज के सदस्य इस बात पर सहमत न हों कि सत्य क्या है, तो क्या वह समाज कार्य कर सकता है?","examples":[{"en":"A shared reality is the invisible infrastructure of public life, and when it collapses, every disagreement becomes a war between rival worlds.","native":"साझी वास्तविकता सार्वजनिक जीवन की अदृश्य बुनियाद है, और जब वह ढह जाती है, तो हर मतभेद प्रतिद्वंद्वी संसारों के बीच युद्ध बन जाता है।"},{"en":"Truth is not determined by consensus, yet a community that cannot agree on how to establish facts will soon be unable to govern itself.","native":"सत्य आम सहमति से तय नहीं होता, फिर भी जो समुदाय तथ्यों को स्थापित करने के तरीके पर सहमत न हो, वह शीघ्र ही खुद को शासित करने में असमर्थ हो जाता है।"},{"en":"Those who declare that truth is whatever power says it is have usually mistaken their own voice for the voice of power.","native":"जो लोग घोषित करते हैं कि सत्य वही है जो सत्ता कहे, वे प्रायः अपनी ही आवाज़ को सत्ता की आवाज़ समझ बैठते हैं।"}]},"es":{"word":"verdad","question":"¿Puede funcionar una sociedad cuando sus miembros ya no se ponen de acuerdo sobre qué es verdad?","examples":[{"en":"A shared reality is the invisible infrastructure of public life, and when it collapses, every disagreement becomes a war between rival worlds.","native":"Una realidad compartida es la infraestructura invisible de la vida pública, y cuando se derrumba, cada desacuerdo se convierte en una guerra entre mundos rivales."},{"en":"Truth is not determined by consensus, yet a community that cannot agree on how to establish facts will soon be unable to govern itself.","native":"La verdad no se determina por consenso, pero una comunidad incapaz de acordar cómo establecer los hechos pronto será incapaz de gobernarse."},{"en":"Those who declare that truth is whatever power says it is have usually mistaken their own voice for the voice of power.","native":"Quienes declaran que la verdad es lo que dice el poder suelen confundir su propia voz con la voz del poder."}]},"zh":{"word":"真理","question":"当一个社会的成员不再就何为真达成共识时，这个社会还能正常运转吗？","examples":[{"en":"A shared reality is the invisible infrastructure of public life, and when it collapses, every disagreement becomes a war between rival worlds.","native":"共同的现实是公共生活无形的基础设施；一旦它崩塌，每一次分歧都会沦为对立世界之间的战争。"},{"en":"Truth is not determined by consensus, yet a community that cannot agree on how to establish facts will soon be unable to govern itself.","native":"真理不由共识决定，但一个连如何确立事实都无法达成一致的共同体，很快将无力自治。"},{"en":"Those who declare that truth is whatever power says it is have usually mistaken their own voice for the voice of power.","native":"那些宣称权力所言之物即真理的人，往往误把自己的声音当成了权力的声音。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'power', 'Does power inevitably corrupt, or does it merely reveal character?', '{"te":{"word":"అధికారం","question":"అధికారం తప్పనిసరిగా చెడగొట్టుతుందా, లేదా అది కేవలం స్వభావాన్ని బహిర్గతం చేస్తుందా?","examples":[{"en":"Power corrupts not by changing people overnight, but by removing the everyday constraints that once forced them to consider other perspectives.","native":"అధికారం రాత్రికి రాత్రి మనుషుల్ని మార్చివేయడం ద్వారా కాకుండా, ఇతరుల దృక్కోణాలను పరిగణించమని బలవంతం చేసిన రోజువారీ ఆంక్షలను తొలగించడం ద్వారా చెడగొడుతుంది."},{"en":"Perhaps power does not create monstrous desires so much as it grants ordinary desires the means to act without consequence.","native":"బహుశా అధికారం భయంకరమైన కోరికలను సృష్టించడం కంటే, సాధారణ కోరికలకు పర్యవసానాలు లేకుండా ప్రవర్తించే మార్గాన్ని ఇవ్వడమే ఎక్కువ."},{"en":"The truest test of character is not how a person endures weakness, but how they treat those over whom they hold absolute advantage.","native":"స్వభావానికి నిజమైన పరీక్ష ఒక వ్యక్తి బలహీనతను ఎలా భరిస్తాడు అన్నది కాదు, తనకు పూర్తి ఆధిపత్యం ఉన్నవారితో ఎలా ప్రవర్తిస్తాడు అన్నదే."}]},"hi":{"word":"सत्ता","question":"क्या सत्ता अनिवार्य रूप से भ्रष्ट करती है, या वह केवल चरित्र को उजागर करती है?","examples":[{"en":"Power corrupts not by changing people overnight, but by removing the everyday constraints that once forced them to consider other perspectives.","native":"सत्ता रातोंरात लोगों को बदलकर भ्रष्ट नहीं करती, बल्कि उन रोज़मर्रा की बाध्यताओं को हटाकर करती है जो उन्हें कभी दूसरे दृष्टिकोण पर विचार करने को मजबूर करती थीं।"},{"en":"Perhaps power does not create monstrous desires so much as it grants ordinary desires the means to act without consequence.","native":"शायद सत्ता राक्षसी इच्छाएँ पैदा करने की बजाय साधारण इच्छाओं को बिना परिणाम भुगते कार्य करने का साधन दे देती है।"},{"en":"The truest test of character is not how a person endures weakness, but how they treat those over whom they hold absolute advantage.","native":"चरित्र की सबसे सच्ची परीक्षा यह नहीं कि कोई व्यक्ति कमज़ोरी कैसे सहता है, बल्कि यह कि वह उन लोगों के साथ कैसा व्यवहार करता है जिन पर उसका पूर्ण दबदबा है।"}]},"es":{"word":"poder","question":"¿Corrompe el poder inevitablemente o simplemente revela el carácter?","examples":[{"en":"Power corrupts not by changing people overnight, but by removing the everyday constraints that once forced them to consider other perspectives.","native":"El poder corrompe no cambiando a las personas de la noche a la mañana, sino eliminando las restricciones cotidianas que antes las obligaban a considerar otras perspectivas."},{"en":"Perhaps power does not create monstrous desires so much as it grants ordinary desires the means to act without consequence.","native":"Quizá el poder no crea deseos monstruosos, sino que concede a los deseos ordinarios los medios para actuar sin consecuencias."},{"en":"The truest test of character is not how a person endures weakness, but how they treat those over whom they hold absolute advantage.","native":"La prueba más verdadera del carácter no es cómo soporta una persona la debilidad, sino cómo trata a quienes están por completo a su merced."}]},"zh":{"word":"权力","question":"权力必然会腐蚀人，还是仅仅揭示人的本性？","examples":[{"en":"Power corrupts not by changing people overnight, but by removing the everyday constraints that once forced them to consider other perspectives.","native":"权力之腐蚀人，不在于一夜之间改变他们，而在于抽走了那些曾迫使他们顾及他人视角的日常约束。"},{"en":"Perhaps power does not create monstrous desires so much as it grants ordinary desires the means to act without consequence.","native":"或许权力并不制造可怕的欲望，而只是给了寻常欲望一条无需承担后果便可行事的通道。"},{"en":"The truest test of character is not how a person endures weakness, but how they treat those over whom they hold absolute advantage.","native":"对品格最真实的考验，不是看一个人如何忍受弱势，而是看他如何对待那些完全处于其支配之下的人。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'consciousness', 'Will we ever fully explain consciousness, and does the mystery matter?', '{"te":{"word":"చైతన్యం","question":"మనం చైతన్యాన్ని ఎప్పుడైనా పూర్తిగా వివరించగలమా, మరియు ఆ రహస్యం ముఖ్యమా?","examples":[{"en":"Consciousness remains the one phenomenon we know directly from the inside yet cannot observe from the outside, which is precisely why it resists science.","native":"చైతన్యం మనం లోపలి నుండి ప్రత్యక్షంగా తెలుసుకున్న ఏకైక దృగ్విషయం, అయితే బయటి నుండి గమనించలేనిది — శాస్త్రానికి అది ఎదురుగా నిలవడానికి కారణం కచ్చితంగా ఇదే."},{"en":"Even if neuroscience maps every correlation between brain and experience, the question of why experience feels like anything at all would remain.","native":"న్యూరోసైన్స్ మెదడు మరియు అనుభవం మధ్య ప్రతి సంబంధాన్ని మ్యాప్ చేసినా, అనుభవం అసలు ఎందుకు ఏదోగా అనిపిస్తుందనే ప్రశ్న మాత్రం మిగిలే ఉంటుంది."},{"en":"Whether machines could ever be conscious is not merely a technical question; it is a mirror in which we discover what we believe ourselves to be.","native":"యంత్రాలు ఎప్పుడైనా చైతన్యవంతం అవుతాయా అన్నది కేవలం సాంకేతిక ప్రశ్న కాదు; మనం మన గురించి ఏమి నమ్ముతున్నామో మనకు చూపించే అద్దం అది."}]},"hi":{"word":"चेतना","question":"क्या हम कभी चेतना की पूरी व्याख्या कर पाएँगे, और क्या यह रहस्य मायने रखता है?","examples":[{"en":"Consciousness remains the one phenomenon we know directly from the inside yet cannot observe from the outside, which is precisely why it resists science.","native":"चेतना एकमात्र ऐसी घटना है जिसे हम भीतर से प्रत्यक्ष जानते हैं, पर बाहर से देख नहीं सकते — और यही कारण है कि वह विज्ञान का सामना टालती है।"},{"en":"Even if neuroscience maps every correlation between brain and experience, the question of why experience feels like anything at all would remain.","native":"भले ही न्यूरोसाइंस मस्तिष्क और अनुभव के हर संबंध का मानचित्र बना ले, यह प्रश्न बना रहेगा कि अनुभव का महसूस होना ही क्यों होता है।"},{"en":"Whether machines could ever be conscious is not merely a technical question; it is a mirror in which we discover what we believe ourselves to be.","native":"क्या मशीनें कभी चेतन हो सकती हैं — यह केवल तकनीकी प्रश्न नहीं, बल्कि एक ऐसा आईना है जिसमें हम खोजते हैं कि हम खुद को क्या मानते हैं।"}]},"es":{"word":"conciencia","question":"¿Llegaremos a explicar por completo la conciencia, y importa realmente el misterio?","examples":[{"en":"Consciousness remains the one phenomenon we know directly from the inside yet cannot observe from the outside, which is precisely why it resists science.","native":"La conciencia sigue siendo el único fenómeno que conocemos directamente desde dentro pero que no podemos observar desde fuera, y por eso se resiste a la ciencia."},{"en":"Even if neuroscience maps every correlation between brain and experience, the question of why experience feels like anything at all would remain.","native":"Aunque la neurociencia cartografiara cada correlación entre cerebro y experiencia, quedaría la pregunta de por qué la experiencia se siente como algo en absoluto."},{"en":"Whether machines could ever be conscious is not merely a technical question; it is a mirror in which we discover what we believe ourselves to be.","native":"Si las máquinas pudieran ser conscientes no es solo una cuestión técnica; es un espejo en el que descubrimos lo que creemos ser."}]},"zh":{"word":"意识","question":"我们终有一天能彻底解释意识吗？这个谜团重要吗？","examples":[{"en":"Consciousness remains the one phenomenon we know directly from the inside yet cannot observe from the outside, which is precisely why it resists science.","native":"意识是我们唯一能从内部直接知晓、却无法从外部观察的现象，这正是它令科学束手无策的原因。"},{"en":"Even if neuroscience maps every correlation between brain and experience, the question of why experience feels like anything at all would remain.","native":"即便神经科学绘制出大脑与体验之间的每一重关联，“体验为何会有所感受”这个问题依然会悬而未决。"},{"en":"Whether machines could ever be conscious is not merely a technical question; it is a mirror in which we discover what we believe ourselves to be.","native":"机器能否拥有意识，并不只是一个技术问题；它是一面镜子，照出我们究竟认为自己是什么。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'morality', 'Is morality discovered, invented, or inherited — and does the answer change how we should live?', '{"te":{"word":"నీతి","question":"నీతి కనుగొనబడినదా, కల్పించబడినదా, లేదా వారసత్వంగా వచ్చినదా — మరియు ఈ సమాధానం మనం ఎలా జీవించాలో మారుస్తుందా?","examples":[{"en":"If morality is merely inherited custom, then reformers are criminals of convention; if it is discovered truth, then some customs are simply crimes.","native":"నీతి కేవలం వారసత్వ ఆచారం అయితే, సంస్కర్తలు సంప్రదాయం యొక్క నేరస్థులు; అది కనుగొనబడిన సత్యం అయితే, కొన్ని ఆచారాలు కేవలం నేరాలే."},{"en":"The fact that moral codes differ across eras proves less that morality is arbitrary than that our understanding of it matures painfully, like science.","native":"నైతిక సూత్రాలు యుగయుగాలుగా భిన్నంగా ఉండటం నీతి మనస్కుళ్లమని నిరూపించడం కంటే, శాస్త్రంలాగే దానిపై మన అవగాహన బాధాకరంగా పరిపక్వమవుతుందని చూపిస్తుంది."},{"en":"We invent moral rules much as we invent games, yet once invented, they bind us as though they had always existed and always will.","native":"ఆటలను కల్పించినట్లే మనం నైతిక నియమాలను కల్పిస్తాం, అయితే ఒకసారి కల్పించాక, అవి ఎల్లప్పుడూ ఉండినవిగానూ ఎప్పటికీ ఉండేవిగానూ మనల్ని బంధిస్తాయి."}]},"hi":{"word":"नीति","question":"क्या नीति खोजी जाती है, रची जाती है या विरासत में मिलती है — और क्या इसका उत्तर यह बदल देता है कि हमें कैसे जीना चाहिए?","examples":[{"en":"If morality is merely inherited custom, then reformers are criminals of convention; if it is discovered truth, then some customs are simply crimes.","native":"यदि नीति केवल विरासती रिवाज़ है, तो सुधारक परंपरा के अपराधी हैं; यदि वह खोजा हुआ सत्य है, तो कुछ रिवाज़ सीधे-सीधे अपराध हैं।"},{"en":"The fact that moral codes differ across eras proves less that morality is arbitrary than that our understanding of it matures painfully, like science.","native":"हर युग में नैतिक संहिताओं के भिन्न होने से यह कम सिद्ध होता है कि नीति मनमानी है, और यह अधिक कि उसकी हमारी समझ विज्ञान की तरह कष्टपूर्वक परिपक्व होती है।"},{"en":"We invent moral rules much as we invent games, yet once invented, they bind us as though they had always existed and always will.","native":"हम नैतिक नियम ठीक उसी तरह रचते हैं जिस तरह खेल रचते हैं, पर एक बार रचे जाने के बाद वे हमें ऐसे बाँधते हैं मानो वे सदा से थे और सदा रहेंगे।"}]},"es":{"word":"moralidad","question":"¿Se descubre, se inventa o se hereda la moralidad, y cambia la respuesta cómo deberíamos vivir?","examples":[{"en":"If morality is merely inherited custom, then reformers are criminals of convention; if it is discovered truth, then some customs are simply crimes.","native":"Si la moralidad no es más que costumbre heredada, los reformadores son criminales de la convención; si es verdad descubierta, algunas costumbres son simplemente crímenes."},{"en":"The fact that moral codes differ across eras proves less that morality is arbitrary than that our understanding of it matures painfully, like science.","native":"Que los códigos morales difieran entre épocas demuestra menos que la moralidad es arbitraria que el hecho de que nuestra comprensión madura con dolor, como la ciencia."},{"en":"We invent moral rules much as we invent games, yet once invented, they bind us as though they had always existed and always will.","native":"Inventamos las reglas morales como inventamos los juegos, pero una vez inventadas nos atan como si hubieran existido siempre y fueran a existir para siempre."}]},"zh":{"word":"道德","question":"道德是被发现的、被发明的，还是被继承的？这个答案会改变我们应当如何生活吗？","examples":[{"en":"If morality is merely inherited custom, then reformers are criminals of convention; if it is discovered truth, then some customs are simply crimes.","native":"如果道德不过是继承下来的习俗，那么改革者就是习俗的罪人；如果它是被发现的真理，那么某些习俗本身就是罪行。"},{"en":"The fact that moral codes differ across eras proves less that morality is arbitrary than that our understanding of it matures painfully, like science.","native":"道德准则随时代而异，与其说证明了道德是任意的，不如说证明我们对道德的理解像科学一样在阵痛中成熟。"},{"en":"We invent moral rules much as we invent games, yet once invented, they bind us as though they had always existed and always will.","native":"我们发明道德规则，正如我们发明游戏；然而一旦发明出来，它们便仿佛亘古长存、并将永远约束我们。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'language', 'Does the language we speak limit what we are able to think?', '{"te":{"word":"భాష","question":"మనం మాట్లాడే భాష మనం ఆలోచించగలిగిన దాన్ని పరిమితం చేస్తుందా?","examples":[{"en":"Language does not imprison thought so much as it builds the roads along which thought habitually travels, leaving other terrains reachable but rarely visited.","native":"భాష ఆలోచనను ఖైదు చేయడం కంటే, ఆలోచన అలవాటుగా ప్రయాణించే రహదారులను నిర్మిస్తుంది — ఇతర ప్రాంతాలు చేరవచ్చు కానీ అరుదుగా వెళ్తాం."},{"en":"When a language lacks a word for a feeling, its speakers still feel it, though they may struggle to share it, refine it, or even notice it clearly.","native":"ఒక భాషలో ఏదో భావనకు మాట లేకపోయినా, దాని వాడుకర్లు దాన్ని అనుభవిస్తారే, కానీ పంచుకోవడం, రుద్దుకోవడం, స్పష్టంగా గమనించడం కష్టమవుతుంది."},{"en":"Every translation betrays something of the original, which suggests that languages are not interchangeable containers but distinct instruments of attention.","native":"ప్రతి అనువాదం అసలులో ఏదో ఒక దాన్ని తప్పనిసరిగా ద్రోహం చేస్తుంది — భాషలు మార్చుకునే పాత్రలు కావు, వేర్వేరు శ్రద్ధ యంత్రాలు అని ఇది సూచిస్తుంది."}]},"hi":{"word":"भाषा","question":"क्या हमारी बोली जाने वाली भाषा हमारी सोचने की क्षमता को सीमित करती है?","examples":[{"en":"Language does not imprison thought so much as it builds the roads along which thought habitually travels, leaving other terrains reachable but rarely visited.","native":"भाषा सोच को क़ैद करने की बजाय उन सड़कों का निर्माण करती है जिन पर सोच आदतन चलती है; अन्य रास्ते पहुँच में होते हैं, पर कभी-कभी ही देखे जाते हैं।"},{"en":"When a language lacks a word for a feeling, its speakers still feel it, though they may struggle to share it, refine it, or even notice it clearly.","native":"जब किसी भाषा में किसी भावना के लिए शब्द न हो, तब भी उसके वक्ता उसे महसूस करते हैं, पर उसे बाँटने, परिष्कृत करने या स्पष्ट देखने में कठिनाई होती है।"},{"en":"Every translation betrays something of the original, which suggests that languages are not interchangeable containers but distinct instruments of attention.","native":"हर अनुवाद मूल के किसी-न-किसी पहलू की धोखाधड़ी करता है — इससे ज़ाहिर होता है कि भाषाएँ परस्पर बदली जाने योग्य पात्र नहीं, बल्कि ध्यान के भिन्न-भिन्न उपकरण हैं।"}]},"es":{"word":"lenguaje","question":"¿Limita el idioma que hablamos lo que somos capaces de pensar?","examples":[{"en":"Language does not imprison thought so much as it builds the roads along which thought habitually travels, leaving other terrains reachable but rarely visited.","native":"El lenguaje no aprisiona el pensamiento tanto como construye las carreteras por las que este viaja habitualmente, dejando otros terrenos accesibles pero rara vez visitados."},{"en":"When a language lacks a word for a feeling, its speakers still feel it, though they may struggle to share it, refine it, or even notice it clearly.","native":"Cuando una lengua carece de palabra para un sentimiento, sus hablantes aún lo sienten, aunque les cueste compartirlo, refinarlo o incluso advertirlo con claridad."},{"en":"Every translation betrays something of the original, which suggests that languages are not interchangeable containers but distinct instruments of attention.","native":"Toda traducción traiciona algo del original, lo que sugiere que las lenguas no son recipientes intercambiables sino instrumentos distintos de la atención."}]},"zh":{"word":"语言","question":"我们所使用的语言会限制我们的思考能力吗？","examples":[{"en":"Language does not imprison thought so much as it builds the roads along which thought habitually travels, leaving other terrains reachable but rarely visited.","native":"语言与其说囚禁思想，不如说修筑了思想习惯行走的道路——其他疆域虽可抵达，却鲜有人至。"},{"en":"When a language lacks a word for a feeling, its speakers still feel it, though they may struggle to share it, refine it, or even notice it clearly.","native":"当一种语言缺少表达某种感受的词时，使用者依然会感受到它，只是难以分享、提炼，甚至难以清晰地察觉。"},{"en":"Every translation betrays something of the original, which suggests that languages are not interchangeable containers but distinct instruments of attention.","native":"每一次翻译都难免背叛原文的某些东西——这说明语言并非可以互换的容器，而是各具特性的注意力工具。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'memory', 'Are our memories reliable records of the past, or stories we keep rewriting?', '{"te":{"word":"జ్ఞాపకం","question":"మన జ్ఞాపకాలు గతానికి నమ్మదగిన రికార్డులా, లేదా మనం నిరంతరం తిరగరాసుకునే కథలా?","examples":[{"en":"Memory is less an archive than a rehearsal: every time we recall an event, we perform it anew and alter it slightly for the next occasion.","native":"జ్ఞాపకం ఆర్కైవ్ కంటే రిహర్సల్ లాంటిది: ఏ సంఘటననైనా ప్రతిసారీ గుర్తుచేసుకున్నప్పుడు దాన్ని కొత్తగా ప్రదర్శిస్తాం, తదుపరి సారి కొంచెం మార్చేస్తాం."},{"en":"The memories we are most confident about are often the ones we have rehearsed most, and rehearsal polishes a story rather than preserving a fact.","native":"మనం అత్యంత నమ్మకంగా ఉండే జ్ఞాపకాలు తరచుగా మనం అత్యధికంగా రిహర్సల్ చేసినవే — రిహర్సల్ వాస్తవాన్ని కాపాడడం కంటే కథను మెరుగుపెడుతుంది."},{"en":"A person without memory would not merely lose the past; without a sense of having been someone, they would struggle to remain anyone at all.","native":"జ్ఞాపకం లేని వ్యక్తి కేవలం గతాన్నే కోల్పోడు; తాను ఎవరో అయ్యాననే భావన లేకుండా, అసలు ఎవరో అయి ఉండటం కూడా కష్టమవుతుంది."}]},"hi":{"word":"स्मृति","question":"क्या हमारी यादें अतीत के विश्वसनीय अभिलेख हैं, या वे कहानियाँ हैं जिन्हें हम बार-बार फिर से लिखते रहते हैं?","examples":[{"en":"Memory is less an archive than a rehearsal: every time we recall an event, we perform it anew and alter it slightly for the next occasion.","native":"स्मृति अभिलेखागार से कम और पुनरभ्यास से अधिक है: हर बार जब हम किसी घटना को याद करते हैं, हम उसे नए सिरे से प्रस्तुत करते हैं और अगली बार के लिए थोड़ा बदल देते हैं।"},{"en":"The memories we are most confident about are often the ones we have rehearsed most, and rehearsal polishes a story rather than preserving a fact.","native":"जिन यादों पर हमें सबसे अधिक भरोसा होता है, वे अक्सर वही होती हैं जिनका हमने सबसे ज़्यादा अभ्यास किया है — और अभ्यास तथ्य को सहेजने की बजाय कहानी को चमकाता है।"},{"en":"A person without memory would not merely lose the past; without a sense of having been someone, they would struggle to remain anyone at all.","native":"जिस व्यक्ति को स्मृति न हो, वह केवल अतीत नहीं खोता; कभी कोई थे होने की भावना के बिना, वह कोई भी बने रहने में संघर्ष करेगा।"}]},"es":{"word":"memoria","question":"¿Son nuestros recuerdos registros fiables del pasado o relatos que no dejamos de reescribir?","examples":[{"en":"Memory is less an archive than a rehearsal: every time we recall an event, we perform it anew and alter it slightly for the next occasion.","native":"La memoria es menos un archivo que un ensayo: cada vez que recordamos un suceso lo representamos de nuevo y lo alteramos levemente para la próxima ocasión."},{"en":"The memories we are most confident about are often the ones we have rehearsed most, and rehearsal polishes a story rather than preserving a fact.","native":"Los recuerdos de los que más seguros estamos suelen ser los que más hemos ensayado, y el ensayo pule una historia en lugar de preservar un hecho."},{"en":"A person without memory would not merely lose the past; without a sense of having been someone, they would struggle to remain anyone at all.","native":"Quien careciera de memoria no solo perdería el pasado; sin la sensación de haber sido alguien, le costaría seguir siendo cualquiera."}]},"zh":{"word":"记忆","question":"我们的记忆是对过去可靠的记录，还是我们不断重写的叙事？","examples":[{"en":"Memory is less an archive than a rehearsal: every time we recall an event, we perform it anew and alter it slightly for the next occasion.","native":"记忆与其说是档案馆，不如说是排练：每当我们回忆一件事，都在重新演绎它，并为下一次悄然改动些许。"},{"en":"The memories we are most confident about are often the ones we have rehearsed most, and rehearsal polishes a story rather than preserving a fact.","native":"我们最自信的记忆，往往正是排练次数最多的那些——而排练打磨的是故事，不是事实。"},{"en":"A person without memory would not merely lose the past; without a sense of having been someone, they would struggle to remain anyone at all.","native":"失去记忆的人失去的不仅是过去；没有了“自己曾经是某个人”的感觉，他将难以成为任何人。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'progress', 'Is human progress real and inevitable, or a story we tell ourselves?', '{"te":{"word":"పురోగతి","question":"మానవ పురోగతి నిజమైనదా, తప్పనిసరిదా, లేదా మనం మనకు చెప్పుకునే కథనామే?","examples":[{"en":"Progress in technology is undeniable and cumulative, yet moral progress resembles a truce that every generation must renegotiate on worse terms than expected.","native":"సాంకేతిక పురోగతి నిరాకరించలేనిది, సంచితమైనది; అయితే నైతిక పురోగతి ఒక యుద్ధవిరమణ లాంటిది — ప్రతి తరం అనుకున్నదాని కంటే చెత్త నిబంధనలతో తిరిగి చర్చించుకోవాలి."},{"en":"We measure progress by what we can count — lifespans, incomes, connections — while what we cannot count quietly determines whether longer lives are worth living.","native":"ఆయుర్దాయాలు, ఆదాయాలు, అనుసంధానాలు — లెక్కించగలిగినవాటితో మనం పురోగతిని కొలుస్తాం; అయితే లెక్కించలేనిదే దీర్ఘజీవితం విలువైనదా కాదా అనేది నిశ్శబ్దంగా నిర్ణయిస్తుంది."},{"en":"The belief that history bends inevitably toward improvement is comforting, but it licenses complacency in precisely the moments that demand vigilance.","native":"చరిత్ర తప్పనిసరిగా మెరుగు వైపు వంగుతుందనే నమ్మకం ఓర్పునిస్తుంది, కానీ అప్రమత్తత అత్యంత అవసరమైన క్షణాల్లోనే ప్రళోభంగా ఉండడానికి అది అనుమతి ఇస్తుంది."}]},"hi":{"word":"प्रगति","question":"क्या मानवीय प्रगति वास्तविक और अनिवार्य है, या वह एक कहानी है जो हम खुद को सुनाते हैं?","examples":[{"en":"Progress in technology is undeniable and cumulative, yet moral progress resembles a truce that every generation must renegotiate on worse terms than expected.","native":"तकनीकी प्रगति अकाट्य और संचयी है, पर नैतिक प्रगति एक युद्धविराम जैसी है जिसे हर पीढ़ी को उम्मीद से बदतर शर्तों पर फिर से तय करना पड़ता है।"},{"en":"We measure progress by what we can count — lifespans, incomes, connections — while what we cannot count quietly determines whether longer lives are worth living.","native":"हम प्रगति उससे मापते हैं जिसे गिन सकते हैं — आयु, आय, संपर्क — जबकि जिसे गिना नहीं जा सकता, वही चुपचाप तय करता है कि लंबा जीवन जीने लायक़ है या नहीं।"},{"en":"The belief that history bends inevitably toward improvement is comforting, but it licenses complacency in precisely the moments that demand vigilance.","native":"यह विश्वास कि इतिहास अनिवार्य रूप से सुधार की ओर झुकता है, सुखदायक है, पर यह ठीक उन्हीं क्षणों में शिथिलता का लाइसेंस देता है जब सतर्कता सबसे ज़रूरी होती है।"}]},"es":{"word":"progreso","question":"¿Es el progreso humano real e inevitable, o un relato que nos contamos a nosotros mismos?","examples":[{"en":"Progress in technology is undeniable and cumulative, yet moral progress resembles a truce that every generation must renegotiate on worse terms than expected.","native":"El progreso tecnológico es innegable y acumulativo, pero el progreso moral se parece a una tregua que cada generación debe renegociar en condiciones peores de las esperadas."},{"en":"We measure progress by what we can count — lifespans, incomes, connections — while what we cannot count quietly determines whether longer lives are worth living.","native":"Medimos el progreso por lo que podemos contar — vidas, ingresos, conexiones — mientras lo incontable decide en silencio si una vida más larga merece ser vivida."},{"en":"The belief that history bends inevitably toward improvement is comforting, but it licenses complacency in precisely the moments that demand vigilance.","native":"La creencia de que la historia se inclina inevitablemente hacia la mejora reconforta, pero autoriza la complacencia precisamente en los momentos que exigen vigilancia."}]},"zh":{"word":"进步","question":"人类的进步是真实而必然的，还是我们讲给自己听的故事？","examples":[{"en":"Progress in technology is undeniable and cumulative, yet moral progress resembles a truce that every generation must renegotiate on worse terms than expected.","native":"技术进步不可否认、不断累积；而道德进步更像一纸停战协定，每一代人都不得不在比预期更糟的条件下重新谈判。"},{"en":"We measure progress by what we can count — lifespans, incomes, connections — while what we cannot count quietly determines whether longer lives are worth living.","native":"我们用可以量化的东西衡量进步——寿命、收入、连接数——而无法量化的东西却在悄然决定：更长的生命是否值得过。"},{"en":"The belief that history bends inevitably toward improvement is comforting, but it licenses complacency in precisely the moments that demand vigilance.","native":"相信历史必然向善令人宽慰，但它恰恰在最需要警惕的时刻，为自满签发了通行证。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'tradition', 'When should a society preserve its traditions, and when should it abandon them?', '{"te":{"word":"సంప్రదాయం","question":"ఒక సమాజం తన సంప్రదాయాలను ఎప్పుడు కాపాడాలి, ఎప్పుడు వదులుకోవాలి?","examples":[{"en":"Tradition is the democracy of the dead, a way of letting ancestors vote, yet problems arise when their votes outnumber those of the living.","native":"సంప్రదాయం మృతుల ప్రజాస్వామ్యం — పూర్వీకులు ఓటు వేసే ఒక మార్గం; అయితే వారి ఓటులు జీవించి ఉన్నవారివి కంటే ఎక్కువయినప్పుడు సమస్యలు మొదలవుతాయి."},{"en":"A tradition defended merely because it is old confuses survival with wisdom, for slavery too was ancient, and so was smallpox.","native":"పాతది కాబట్టని మాత్రమే సమర్థించే సంప్రదాయం మనుగడను జ్ఞానంతో గందరగోళం చేస్తుంది, ఎందుకంటే బానిసత్వం కూడా పురాతనమే, మశూచి కూడా అంతే."},{"en":"The healthiest cultures treat tradition as a conversation rather than a commandment, keeping what still illuminates and discarding what merely constrains.","native":"ఆరోగ్యకరమైన సంస్కృతులు సంప్రదాయాన్ని ఆజ్ఞ కాకుండా సంభాషణగా చూస్తాయి — ఇంకా వెలుగునిచ్చేది ఉంచుకుని, కేవలం కట్టడి చేసేది వదిలేస్తాయి."}]},"hi":{"word":"परंपरा","question":"किसी समाज को अपनी परंपराओं को कब संरक्षित करना चाहिए और कब त्याग देना चाहिए?","examples":[{"en":"Tradition is the democracy of the dead, a way of letting ancestors vote, yet problems arise when their votes outnumber those of the living.","native":"परंपरा मृतकों का लोकतंत्र है, पूर्वजों को मतदान करने देने का एक तरीका; पर समस्या तब उठती है जब उनके मत जीवितों के मतों से अधिक हो जाते हैं।"},{"en":"A tradition defended merely because it is old confuses survival with wisdom, for slavery too was ancient, and so was smallpox.","native":"जो परंपरा केवल इसलिए बचाई जाती है कि वह पुरानी है, वह अस्तित्व को ज्ञान से भ्रमित करती है, क्योंकि गुलामी भी प्राचीन थी, और चेचक भी।"},{"en":"The healthiest cultures treat tradition as a conversation rather than a commandment, keeping what still illuminates and discarding what merely constrains.","native":"सबसे स्वस्थ संस्कृतियाँ परंपरा को आज्ञा नहीं, संवाद मानती हैं — जो आज भी प्रकाश देती हो उसे रखती हैं, और जो केवल बाँधती हो उसे छोड़ देती हैं।"}]},"es":{"word":"tradición","question":"¿Cuándo debería una sociedad preservar sus tradiciones y cuándo abandonarlas?","examples":[{"en":"Tradition is the democracy of the dead, a way of letting ancestors vote, yet problems arise when their votes outnumber those of the living.","native":"La tradición es la democracia de los muertos, una forma de dejar votar a los antepasados, pero los problemas surgen cuando sus votos superan a los de los vivos."},{"en":"A tradition defended merely because it is old confuses survival with wisdom, for slavery too was ancient, and so was smallpox.","native":"Una tradición defendida solo porque es antigua confunde la supervivencia con la sabiduría, pues la esclavitud también era antigua, y la viruela también."},{"en":"The healthiest cultures treat tradition as a conversation rather than a commandment, keeping what still illuminates and discarding what merely constrains.","native":"Las culturas más sanas tratan la tradición como una conversación y no como un mandamiento, conservando lo que aún ilumina y descartando lo que solo constriñe."}]},"zh":{"word":"传统","question":"一个社会应当何时守护传统，又应当何时抛弃传统？","examples":[{"en":"Tradition is the democracy of the dead, a way of letting ancestors vote, yet problems arise when their votes outnumber those of the living.","native":"传统是逝者的民主，是让祖先参与投票的一种方式；但当他们的票数超过生者时，问题就来了。"},{"en":"A tradition defended merely because it is old confuses survival with wisdom, for slavery too was ancient, and so was smallpox.","native":"仅仅因为古老就为传统辩护，是把存续误当作智慧——奴隶制也曾古老，天花亦然。"},{"en":"The healthiest cultures treat tradition as a conversation rather than a commandment, keeping what still illuminates and discarding what merely constrains.","native":"最健康的文化把传统当作对话而非诫命，留住依然能照亮现实的东西，舍弃只会束缚人的东西。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'meritocracy', 'Is meritocracy a fair ideal, or does it disguise privilege as virtue?', '{"te":{"word":"ప్రతిభా పాలన","question":"ప్రతిభా పాలన న్యాయమైన ఆదర్శమా, లేదా అది ప్రత్యేక హక్కును గుణంగా ముసుగులో దాచుతుందా?","examples":[{"en":"Meritocracy promises that effort and talent will be rewarded, yet it quietly ignores how unequally the chances to develop that talent are distributed.","native":"శ్రమకు, ప్రతిభకు ప్రతిఫలం లభిస్తుందని ప్రతిభా పాలన హామీ ఇస్తుంది, అయితే ఆ ప్రతిభను పెంచుకునే అవకాశాలు ఎంత అసమానంగా పంపిణీ అవుతాయో అది నిశ్శబ్దంగా విస్మరిస్తుంది."},{"en":"When winners believe their success is entirely deserved, gratitude gives way to arrogance, and the unsuccessful are blamed for their own defeat.","native":"విజేతలు తమ విజయం పూర్తిగా తమదే అని నమ్మినప్పుడు, కృతజ్ఞత స్థానం గర్వం పొందుతుంది, మరియు ఓటమి పాలైనవారు తమ ఓటమికి తామే కారణమని నిందించబడతారు."},{"en":"A race in which some runners start far ahead may be fairly timed, but no honest observer would call its results a pure measure of merit.","native":"కొంతమంది పరుగెత్తేవారు చాలా ముందు నుండి ప్రారంభించే రేసును లెక్క నిజాయితీగా పెట్టవచ్చు, కానీ నిజాయితీగల పరిశీలకుడు దాని ఫలితాలను స్వచ్ఛమైన ప్రతిభా కొలమానమని అనడు."}]},"hi":{"word":"योग्यतावाद","question":"क्या योग्यतावाद एक निष्पक्ष आदर्श है, या वह विशेषाधिकार को गुण का वेश पहना देता है?","examples":[{"en":"Meritocracy promises that effort and talent will be rewarded, yet it quietly ignores how unequally the chances to develop that talent are distributed.","native":"योग्यतावाद वादा करता है कि मेहनत और प्रतिभा का फल मिलेगा, पर वह चुपचाप यह नज़रअंदाज़ कर देता है कि उस प्रतिभा को विकसित करने के अवसर कितने असमान रूप से बँटे हैं।"},{"en":"When winners believe their success is entirely deserved, gratitude gives way to arrogance, and the unsuccessful are blamed for their own defeat.","native":"जब विजेता मान लेते हैं कि उनकी सफलता पूरी तरह उनकी कमाई है, तो कृतज्ञता की जगह अहंकार ले लेता है, और असफलों को उनकी हार का दोषी ठहराया जाता है।"},{"en":"A race in which some runners start far ahead may be fairly timed, but no honest observer would call its results a pure measure of merit.","native":"जिस दौड़ में कुछ धावक बहुत आगे से शुरू करें, उसका समय निष्पक्ष हो सकता है, पर कोई ईमानदार दर्शक उसके नतीजों को योग्यता का शुद्ध माप नहीं कहेगा।"}]},"es":{"word":"meritocracia","question":"¿Es la meritocracia un ideal justo o disfraza el privilegio de virtud?","examples":[{"en":"Meritocracy promises that effort and talent will be rewarded, yet it quietly ignores how unequally the chances to develop that talent are distributed.","native":"La meritocracia promete recompensar el esfuerzo y el talento, pero ignora en silencio lo desigualmente que se distribuyen las oportunidades de desarrollar ese talento."},{"en":"When winners believe their success is entirely deserved, gratitude gives way to arrogance, and the unsuccessful are blamed for their own defeat.","native":"Cuando los ganadores creen que su éxito es enteramente merecido, la gratitud cede ante la arrogancia, y a los perdedores se les culpa de su propia derrota."},{"en":"A race in which some runners start far ahead may be fairly timed, but no honest observer would call its results a pure measure of merit.","native":"Una carrera en la que algunos corredores parten muy adelante puede cronometrarse con justicia, pero ningún observador honesto llamaría a sus resultados una medida pura del mérito."}]},"zh":{"word":"精英制度","question":"精英制度（唯才是举）是公平的理想，还是把特权伪装成了美德？","examples":[{"en":"Meritocracy promises that effort and talent will be rewarded, yet it quietly ignores how unequally the chances to develop that talent are distributed.","native":"精英制度许诺努力与才华必有回报，却悄然无视培养才华的机会分配得何等不均。"},{"en":"When winners believe their success is entirely deserved, gratitude gives way to arrogance, and the unsuccessful are blamed for their own defeat.","native":"当赢家深信自己的成功全凭应得，感恩便让位于傲慢，而失败者则被归咎于自己的失败。"},{"en":"A race in which some runners start far ahead may be fairly timed, but no honest observer would call its results a pure measure of merit.","native":"一场有些选手起跑线远在他人之前的比赛，计时或许公正，但任何诚实的旁观者都不会称其结果为才华的纯粹度量。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'freedom', 'Is freedom the absence of constraints, or the capacity to act meaningfully?', '{"te":{"word":"స్వేచ్ఛ","question":"స్వేచ్ఛ అంటే ఆంక్షల లేమినా, లేదా అర్థవంతంగా ప్రవర్తించే సామర్థ్యమా?","examples":[{"en":"A person left alone in a desert enjoys perfect negative freedom, yet without education, health, and community, that freedom is an empty formality.","native":"ఎడారిలో ఒంటరిగా వదిలివేయబడిన వ్యక్తి పరిపూర్ణ ప్రతికూల స్వేచ్ఛను అనుభవిస్తాడు, అయితే విద్య, ఆరోగ్యం, సమాజం లేకుండా ఆ స్వేచ్ఛ ఒక ఖాళీ ఔపచారికత."},{"en":"Freedom from interference matters, but so does freedom to flourish, and the two visions collide whenever governments decide how much to provide.","native":"జోక్యం లేని స్వేచ్ఛ ముఖ్యమే, కానీ వర్ధిల్లే స్వేచ్ఛ కూడా ముఖ్యమే — ప్రభుత్వాలు ఎంత అందించాలో నిర్ణయించినప్పుడల్లా ఈ రెండు దృష్టిసారూప్యాలు ఢీకొంటాయి."},{"en":"We surrender small freedoms daily for safety and convenience, rarely pausing to ask whether the exchange leaves us safer or merely more dependent.","native":"భద్రత కోసం, సౌకర్యం కోసం మనం రోజూ చిన్న చిన్న స్వేచ్ఛలను అప్పగిస్తాం — ఆ మార్పిడి మనల్ని సురక్షితంగా చేస్తుందా లేక కేవలం మరింత ఆధారపడేలా చేస్తుందా అని ఆలోచించడం అరుదు."}]},"hi":{"word":"स्वतंत्रता","question":"क्या स्वतंत्रता बाधाओं का अभाव है, या सार्थक ढंग से कार्य करने की क्षमता?","examples":[{"en":"A person left alone in a desert enjoys perfect negative freedom, yet without education, health, and community, that freedom is an empty formality.","native":"रेगिस्तान में अकेला छोड़ा व्यक्ति पूर्ण नकारात्मक स्वतंत्रता का आनंद लेता है, पर शिक्षा, स्वास्थ्य और समुदाय के बिना वह स्वतंत्रता एक खोखली औपचारिकता है।"},{"en":"Freedom from interference matters, but so does freedom to flourish, and the two visions collide whenever governments decide how much to provide.","native":"हस्तक्षेप से मुक्ति मायने रखती है, पर समृद्धि की स्वतंत्रता भी उतनी ही मायने रखती है — और जब भी सरकारें यह तय करती हैं कि कितना प्रदान करना है, ये दोनों दृष्टि टकराते हैं।"},{"en":"We surrender small freedoms daily for safety and convenience, rarely pausing to ask whether the exchange leaves us safer or merely more dependent.","native":"हम सुरक्षा और सुविधा के लिए रोज़ छोटी-छोटी स्वतंत्रताएँ सौंप देते हैं, और शायद ही कभी रुककर पूछते हैं कि यह सौदा हमें सुरक्षित बनाता है या केवल अधिक निर्भर।"}]},"es":{"word":"libertad","question":"¿Es la libertad la ausencia de restricciones o la capacidad de actuar con sentido?","examples":[{"en":"A person left alone in a desert enjoys perfect negative freedom, yet without education, health, and community, that freedom is an empty formality.","native":"Una persona sola en el desierto goza de perfecta libertad negativa, pero sin educación, salud y comunidad, esa libertad es una formalidad vacía."},{"en":"Freedom from interference matters, but so does freedom to flourish, and the two visions collide whenever governments decide how much to provide.","native":"Importa la libertad frente a la interferencia, pero también la libertad para prosperar, y ambas visiones chocan cada vez que los gobiernos deciden cuánto proveer."},{"en":"We surrender small freedoms daily for safety and convenience, rarely pausing to ask whether the exchange leaves us safer or merely more dependent.","native":"Cada día cedemos pequeñas libertades a cambio de seguridad y comodidad, sin detenernos apenas a preguntar si el trueque nos hace más seguros o solo más dependientes."}]},"zh":{"word":"自由","question":"自由是没有约束，还是能够有意义地行动的能力？","examples":[{"en":"A person left alone in a desert enjoys perfect negative freedom, yet without education, health, and community, that freedom is an empty formality.","native":"被独自留在沙漠中的人享有完美的消极自由，但没有教育、健康与社群，这种自由不过是空洞的形式。"},{"en":"Freedom from interference matters, but so does freedom to flourish, and the two visions collide whenever governments decide how much to provide.","native":"免于干预的自由固然重要，得以蓬勃发展的自由同样重要；每当政府决定该提供多少时，这两种自由观便会相撞。"},{"en":"We surrender small freedoms daily for safety and convenience, rarely pausing to ask whether the exchange leaves us safer or merely more dependent.","native":"我们每天为了安全与便利让渡小小的自由，却很少停下来问一问：这笔交换让我们更安全了，还是只是更依赖了？"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'responsibility', 'How far does personal responsibility extend when choices are shaped by circumstance?', '{"te":{"word":"బాధ్యత","question":"ఎంపికలు పరిస్థితులచే ఆకృత్రిమయ్యేటప్పుడు వ్యక్తిగత బాధ్యత ఎంతదూరం విస్తరిస్తుంది?","examples":[{"en":"Holding people responsible for choices they never freely made feels just only to those who have never had to make choices under such constraints.","native":"ఎప్పుడూ స్వేచ్ఛగా చేసుకోని ఎంపికలకు ప్రజల్ని బాధ్యుల్ని చేయడం, అటువంటి ఆంక్షల క్రింద ఎప్పుడూ ఎంపిక చేయనివారికి మాత్రమే న్యాయంగా అనిపిస్తుంది."},{"en":"Responsibility is the price of agency: a society that excuses everything as circumstance soon finds that no one can be trusted with anything.","native":"బాధ్యత అనేది చర్యాసామర్థ్యానికి చెల్లించే ధర: ప్రతిదాన్ని పరిస్థితిగా క్షమించే సమాజం ఎవరినీ ఏ విషయంతోనూ నమ్మలేని స్థితికి త్వరలో చేరుతుంది."},{"en":"The wisest stance may be to demand full responsibility from ourselves while extending generous understanding to others, though few manage this asymmetry.","native":"మన నుండి మనం పూర్తి బాధ్యతను కోరుకుంటూ, ఇతరులపై ఉదారమైన అవగాహన చూపడం అత్యంత జ్ఞానమైన వైఖరి కావచ్చు — అయితే ఈ అసమానత్వాన్ని కొనసాగించగలిగేవారు కొద్దిమందే."}]},"hi":{"word":"ज़िम्मेदारी","question":"जब चुनाव परिस्थितियों से आकार लेते हैं, तो व्यक्तिगत ज़िम्मेदारी कहाँ तक फैलती है?","examples":[{"en":"Holding people responsible for choices they never freely made feels just only to those who have never had to make choices under such constraints.","native":"उन चुनावों के लिए लोगों को ज़िम्मेदार ठहराना जो उन्होंने कभी स्वतंत्र रूप से नहीं किए, केवल उन्हें ही न्यायसंगत लगता है जिन्हें कभी ऐसी बाध्यताओं में चुनाव करना नहीं पड़ा।"},{"en":"Responsibility is the price of agency: a society that excuses everything as circumstance soon finds that no one can be trusted with anything.","native":"ज़िम्मेदारी कर्तृत्व की कीमत है: जो समाज हर चीज़ को परिस्थिति कहकर क्षमा कर देता है, वह शीघ्र ही पाता है कि किसी पर भी कोई भरोसा नहीं किया जा सकता।"},{"en":"The wisest stance may be to demand full responsibility from ourselves while extending generous understanding to others, though few manage this asymmetry.","native":"सबसे बुद्धिमान रुख़ शायद यही हो कि खुद से पूरी ज़िम्मेदारी माँगें और दूसरों के प्रति उदार समझ दिखाएँ, यद्यपि यह असमानता बहुत कम लोग निभा पाते हैं।"}]},"es":{"word":"responsabilidad","question":"¿Hasta dónde llega la responsabilidad personal cuando las decisiones están moldeadas por las circunstancias?","examples":[{"en":"Holding people responsible for choices they never freely made feels just only to those who have never had to make choices under such constraints.","native":"Hacer responsables a las personas de decisiones que nunca tomaron libremente solo parece justo a quienes jamás tuvieron que decidir bajo tales limitaciones."},{"en":"Responsibility is the price of agency: a society that excuses everything as circumstance soon finds that no one can be trusted with anything.","native":"La responsabilidad es el precio de la agencia: una sociedad que lo excusa todo como circunstancia pronto descubre que no se puede confiar nada a nadie."},{"en":"The wisest stance may be to demand full responsibility from ourselves while extending generous understanding to others, though few manage this asymmetry.","native":"Quizá la actitud más sabia sea exigirnos plena responsabilidad a nosotros mismos mientras extendemos comprensión generosa a los demás, aunque pocos logran esta asimetría."}]},"zh":{"word":"责任","question":"当选择受到环境的塑造时，个人责任的边界应延伸到哪里？","examples":[{"en":"Holding people responsible for choices they never freely made feels just only to those who have never had to make choices under such constraints.","native":"让人们为从未自由做出的选择负责，只有那些从未在此类约束下做过选择的人才会觉得这是公正的。"},{"en":"Responsibility is the price of agency: a society that excuses everything as circumstance soon finds that no one can be trusted with anything.","native":"责任是行动能力的代价：一个把一切都归咎于环境的社会，很快会发现任何人都无法托付任何事。"},{"en":"The wisest stance may be to demand full responsibility from ourselves while extending generous understanding to others, though few manage this asymmetry.","native":"最明智的姿态或许是：对自己要求百分之百的责任，对他人报以宽厚的理解——尽管很少有人能维持这种不对称。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'empathy', 'Can empathy be taught, or is it a fixed trait we are born with?', '{"te":{"word":"సానుభూతి","question":"సానుభూతిని నేర్పించగలమా, లేదా అది మనం పుట్టుకతో పొందే స్థిరమైన లక్షణమా?","examples":[{"en":"Empathy is less a gift than a muscle: it strengthens with deliberate use and atrophies in environments where no one models it for us.","native":"సానుభూతి వరం కంటే కండరం లాంటిది: ఉద్దేశపూర్వక వినియోగంతో బలపడుతుంది, ఎవరూ మనకు మార్గదర్శకంగా చూపని వాతావరణాల్లో క్షీణిస్తుంది."},{"en":"Literature teaches empathy more effectively than lectures, because stories make us inhabit other minds rather than merely hear about them.","native":"సాహిత్యం ఉపన్యాసాల కంటే సానుభూతిని సమర్థంగా నేర్పుతుంది, ఎందుకంటే కథలు ఇతరుల మనసుల గురించి వినిపించడం కాకుండా వాటిలో నివసింపజేస్తాయి."},{"en":"Even the most empathic person has limits, for feeling everyone’s pain without reserve leads not to compassion but to paralysis and burnout.","native":"అత్యంత సానుభూతి గల వ్యక్తికి కూడా పరిమితులు ఉంటాయి, ఎందుకంటే అందరి బాధను అపరిమితంగా అనుభవించడం కరుణకు కాకుండా స్తంభనానికి, క్షయానికి దారితీస్తుంది."}]},"hi":{"word":"समानुभूति","question":"क्या समानुभूति सिखाई जा सकती है, या यह जन्म से मिला एक स्थिर गुण है?","examples":[{"en":"Empathy is less a gift than a muscle: it strengthens with deliberate use and atrophies in environments where no one models it for us.","native":"समानुभूति वरदान से कम और माँसपेशी से अधिक है: सचेतन उपयोग से मज़बूत होती है, और ऐसे वातावरण में क्षीण हो जाती है जहाँ कोई हमें उसका आदर्श नहीं दिखाता।"},{"en":"Literature teaches empathy more effectively than lectures, because stories make us inhabit other minds rather than merely hear about them.","native":"साहित्य व्याख्यानों की तुलना में समानुभूति अधिक प्रभावी ढंग से सिखाता है, क्योंकि कहानियाँ हमें दूसरों के मन के बारे में सुनाने की बजाय उनमें बसा देती हैं।"},{"en":"Even the most empathic person has limits, for feeling everyone’s pain without reserve leads not to compassion but to paralysis and burnout.","native":"सबसे समानुभूतिशील व्यक्ति की भी सीमाएँ होती हैं, क्योंकि सबका दर्द बिना रोक-टोक महसूस करना करुणा की ओर नहीं, बल्कि अवसाद और थकान की ओर ले जाता है।"}]},"es":{"word":"empatía","question":"¿Puede enseñarse la empatía o es un rasgo fijo con el que nacemos?","examples":[{"en":"Empathy is less a gift than a muscle: it strengthens with deliberate use and atrophies in environments where no one models it for us.","native":"La empatía es menos un don que un músculo: se fortalece con el uso deliberado y se atrofia en entornos donde nadie nos la ejemplifica."},{"en":"Literature teaches empathy more effectively than lectures, because stories make us inhabit other minds rather than merely hear about them.","native":"La literatura enseña empatía mejor que las conferencias, porque las historias nos hacen habitar otras mentes en lugar de solo oír hablar de ellas."},{"en":"Even the most empathic person has limits, for feeling everyone’s pain without reserve leads not to compassion but to paralysis and burnout.","native":"Incluso la persona más empática tiene límites, pues sentir el dolor de todos sin reserva no conduce a la compasión, sino a la parálisis y al agotamiento."}]},"zh":{"word":"共情","question":"共情是可以被教会的能力，还是与生俱来的固定特质？","examples":[{"en":"Empathy is less a gift than a muscle: it strengthens with deliberate use and atrophies in environments where no one models it for us.","native":"共情与其说是天赋，不如说是肌肉：刻意运用则增强，在无人示范的环境中则萎缩。"},{"en":"Literature teaches empathy more effectively than lectures, because stories make us inhabit other minds rather than merely hear about them.","native":"文学比说教更能有效地培养共情，因为故事让我们住进他人的心灵，而不是仅仅听人说起。"},{"en":"Even the most empathic person has limits, for feeling everyone’s pain without reserve leads not to compassion but to paralysis and burnout.","native":"即便最具共情力的人也有极限，因为毫无保留地感受所有人的痛苦，通往的不是慈悲，而是瘫痪与耗竭。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'compassion', 'Should compassion guide public policy, or is it too unreliable an emotion?', '{"te":{"word":"కరుణ","question":"కరుణ ప్రజా విధానాలకు మార్గదర్శకం కావాలా, లేదా అది చాలా నమ్మదగని భావోద్వేగమా?","examples":[{"en":"A policy built on compassion alone risks sentimentality, yet a policy built without any compassion risks becoming efficient cruelty with clean paperwork.","native":"కరుణ మీద మాత్రమే నిర్మించిన విధానం భావుకత్వ ప్రమాదాన్ని పొందుతుంది, అయితే కరుణ లేకుండా నిర్మించిన విధానం శుభ్రమైన కాగితాలతో సమర్థమైన క్రూరత్వమవుతుంది."},{"en":"Compassion differs from pity in that it respects the sufferer’s dignity, whereas pity often consoles the giver at the expense of the receiver.","native":"కరుణ బాధపడేవారి గౌరవాన్ని గౌరవిస్తుంది, అయితే దయ తరచుగా పొందేవారి ఖర్చుతో ఇచ్చేవారిని ఓదారుస్తుంది — ఈ విషయంలోనే రెండిటి తేడా ఉంది."},{"en":"Societies reveal their character not by how they reward the strong, but by how their laws and institutions treat those who can offer nothing in return.","native":"బలవంతులను ఎలా సత్కరిస్తాయో కాదు, ప్రతిఫలం ఏమీ ఇవ్వలేనివారితో వారి చట్టాలు, సంస్థలు ఎలా ప్రవర్తిస్తాయో దానితోనే సమాజాలు తమ స్వభావాన్ని వెల్లడిస్తాయి."}]},"hi":{"word":"करुणा","question":"क्या करुणा को लोक नीति का मार्गदर्शक होना चाहिए, या यह बहुत अविश्वसनीय भावना है?","examples":[{"en":"A policy built on compassion alone risks sentimentality, yet a policy built without any compassion risks becoming efficient cruelty with clean paperwork.","native":"केवल करुणा पर बनी नीति भावुकता का जोखिम उठाती है, पर बिना किसी करुणा के बनी नीति साफ़-सुथरे काग़ज़ात के साथ कुशल क्रूरता बनने का जोखिम उठाती है।"},{"en":"Compassion differs from pity in that it respects the sufferer’s dignity, whereas pity often consoles the giver at the expense of the receiver.","native":"करुणा दया से इसलिए भिन्न है कि वह पीड़ित की गरिमा का सम्मान करती है, जबकि दया अक्सर पाने वाले की कीमत पर देने वाले को सांत्वना देती है।"},{"en":"Societies reveal their character not by how they reward the strong, but by how their laws and institutions treat those who can offer nothing in return.","native":"समाज अपना चरित्र इससे नहीं दिखाते कि वे बलवानों को कैसे पुरस्कृत करते हैं, बल्कि इससे कि उनके क़ानून और संस्थाएँ उन लोगों के साथ कैसा व्यवहार करती हैं जो बदले में कुछ नहीं दे सकते।"}]},"es":{"word":"compasión","question":"¿Debería la compasión guiar las políticas públicas, o es una emoción demasiado poco fiable?","examples":[{"en":"A policy built on compassion alone risks sentimentality, yet a policy built without any compassion risks becoming efficient cruelty with clean paperwork.","native":"Una política basada solo en la compasión arriesga el sentimentalismo, pero una política sin ninguna compasión arriesga convertirse en crueldad eficiente con papeleo impecable."},{"en":"Compassion differs from pity in that it respects the sufferer’s dignity, whereas pity often consoles the giver at the expense of the receiver.","native":"La compasión se distingue de la lástima en que respeta la dignidad del que sufre, mientras que la lástima a menudo consuela al que da a costa del que recibe."},{"en":"Societies reveal their character not by how they reward the strong, but by how their laws and institutions treat those who can offer nothing in return.","native":"Las sociedades revelan su carácter no por cómo recompensan a los fuertes, sino por cómo sus leyes e instituciones tratan a quienes no pueden ofrecer nada a cambio."}]},"zh":{"word":"慈悲","question":"公共政策应当以慈悲为导向，还是说慈悲是一种太不可靠的情感？","examples":[{"en":"A policy built on compassion alone risks sentimentality, yet a policy built without any compassion risks becoming efficient cruelty with clean paperwork.","native":"仅靠慈悲构建的政策有沦为多愁善感的风险，而毫无慈悲的政策则可能沦为文书整洁的高效残酷。"},{"en":"Compassion differs from pity in that it respects the sufferer’s dignity, whereas pity often consoles the giver at the expense of the receiver.","native":"慈悲不同于怜悯：慈悲尊重受苦者的尊严，而怜悯往往以受者的代价安慰施者。"},{"en":"Societies reveal their character not by how they reward the strong, but by how their laws and institutions treat those who can offer nothing in return.","native":"一个社会显露出品格，不在于它如何奖赏强者，而在于它的法律与制度如何对待那些无以回报的人。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'integrity', 'Is integrity a fixed core of values, or consistency between what we say and do?', '{"te":{"word":"నిజాయితీ","question":"నిజాయితీ అనేది విలువల స్థిరమైన అంతర్గత భాగమా, లేదా మనం చెప్పేదానికి చేసేదానికి మధ్య స్థిరత్వమా?","examples":[{"en":"Integrity is tested not when principles cost nothing, but when keeping them demands sacrifices that no one would ever discover we refused to make.","native":"సూత్రాలకు ధర ఏమీ లేనప్పుడు కాదు, వాటిని పాటించడం ఎవరూ ఎప్పటికీ తెలుసుకోలేని త్యాగాలను కోరినప్పుడు నిజాయితీ పరీక్షించబడుతుంది."},{"en":"A person of rigid integrity may become incapable of growth, for changing one’s mind honestly requires admitting that yesterday’s convictions were wrong.","native":"కఠినమైన నిజాయితీ గల వ్యక్తి ఎదుగుదలకు అసమర్థుడవుతాడు, ఎందుకంటే నిజాయితీగా అభిప్రాయం మార్చుకోవడం నిన్నటి విశ్వాసాలు తప్పని ఒప్పుకోవడమే."},{"en":"Societies need integrity in institutions more than in heroes, because systems that reward honest behaviour make virtue ordinary instead of exceptional.","native":"సమాజాలకు హీరోల్లో కంటే సంస్థల్లో నిజాయితీ ఎక్కువగా అవసరం, ఎందుకంటే నిజాయితీగల ప్రవర్తనను బహుమతించే వ్యవస్థలు గుణాన్ని అసాధారణం కాకుండా సాధారణం చేస్తాయి."}]},"hi":{"word":"ईमानदारी","question":"क्या ईमानदारी मूल्यों का एक अटल सार है, या हमारे कहने और करने के बीच की एकरूपता?","examples":[{"en":"Integrity is tested not when principles cost nothing, but when keeping them demands sacrifices that no one would ever discover we refused to make.","native":"ईमानदारी की परीक्षा तब नहीं होती जब सिद्धांतों की कोई कीमत नहीं होती, बल्कि तब होती है जब उन्हें निभाने के लिए ऐसे त्याग माँगे जाते हैं जिनसे इनकार किया हुआ कोई कभी जान न पाए।"},{"en":"A person of rigid integrity may become incapable of growth, for changing one’s mind honestly requires admitting that yesterday’s convictions were wrong.","native":"कठोर ईमानदारी वाला व्यक्ति विकास के प्रति असमर्थ हो सकता है, क्योंकि ईमानदारी से अपनी राय बदलने के लिए यह स्वीकारना पड़ता है कि कल की धारणाएँ ग़लत थीं।"},{"en":"Societies need integrity in institutions more than in heroes, because systems that reward honest behaviour make virtue ordinary instead of exceptional.","native":"समाजों को नायकों की तुलना में संस्थाओं में ईमानदारी की अधिक ज़रूरत है, क्योंकि जो व्यवस्थाएँ ईमानदार व्यवहार को पुरस्कृत करती हैं, वे सद्गुण को असाधारण के बजाय साधारण बना देती हैं।"}]},"es":{"word":"integridad","question":"¿Es la integridad un núcleo fijo de valores o la coherencia entre lo que decimos y hacemos?","examples":[{"en":"Integrity is tested not when principles cost nothing, but when keeping them demands sacrifices that no one would ever discover we refused to make.","native":"La integridad se pone a prueba no cuando los principios no cuestan nada, sino cuando mantenerlos exige sacrificios que nadie descubriría jamás que nos negamos a hacer."},{"en":"A person of rigid integrity may become incapable of growth, for changing one’s mind honestly requires admitting that yesterday’s convictions were wrong.","native":"Una persona de integridad rígida puede volverse incapaz de crecer, pues cambiar de opinión con honestidad exige admitir que las convicciones de ayer eran erróneas."},{"en":"Societies need integrity in institutions more than in heroes, because systems that reward honest behaviour make virtue ordinary instead of exceptional.","native":"Las sociedades necesitan integridad en las instituciones más que en los héroes, porque los sistemas que premian la conducta honesta hacen de la virtud algo ordinario y no excepcional."}]},"zh":{"word":"正直","question":"正直是一套固定不变的价值内核，还是言行之间的一以贯之？","examples":[{"en":"Integrity is tested not when principles cost nothing, but when keeping them demands sacrifices that no one would ever discover we refused to make.","native":"正直的考验，不在于坚守原则毫无代价之时，而在于守住原则需要付出无人知晓的牺牲之时。"},{"en":"A person of rigid integrity may become incapable of growth, for changing one’s mind honestly requires admitting that yesterday’s convictions were wrong.","native":"刚直不阿到僵硬的人可能丧失成长的能力，因为诚实地改变看法，意味着承认昨天的信念是错的。"},{"en":"Societies need integrity in institutions more than in heroes, because systems that reward honest behaviour make virtue ordinary instead of exceptional.","native":"社会更需要制度中的正直，而非英雄身上的正直，因为奖赏诚实行为的制度会让美德变得寻常，而非罕见。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'hypocrisy', 'Is hypocrisy the worst vice, or a universal human weakness we exaggerate?', '{"te":{"word":"కపటం","question":"కపటం అత్యంత చెత్త దుర్గుణమా, లేదా మనం పెద్దది చేసే సార్వత్రిక మానవ బలహీనతా?","examples":[{"en":"Hypocrisy offends us not because the act is false, but because it demands from others a standard the speaker quietly exempts himself from meeting.","native":"కపటం మనల్ని బాధపెట్టడానికి కారణం ఆ చర్య అబద్ధం కాబట్టి కాదు, మాట్లాడేవాడు తనను తాను నిశ్శబ్దంగా మినహాయించుకునే ప్రమాణాన్ని ఇతరులను కోరుతాడు కాబట్టి."},{"en":"A hypocrite who preaches virtue still honours virtue in words, and societies need such tribute even from those who cannot pay it in deeds.","native":"గుణం గురించి ప్రబోధించే కపటి కూడా మాటల్లోనైనా గుణాన్ని గౌరవిస్తాడు — చర్యల్లో చెల్లించలేనివారి నుండైనా అటువంటి నివాళి సమాజాలకు అవసరం."},{"en":"We detect hypocrisy in our enemies with precision and excuse it in ourselves as complexity, which is itself the most common form of the vice.","native":"శత్రువుల్లోని కపటాన్ని మనం ఖచ్చితంగా గుర్తిస్తాం, మనలోనిదాన్ని సంక్లిష్టతగా క్షమిస్తాం — ఇదే ఆ దుర్గుణం యొక్క అత్యంత సాధారణ రూపం."}]},"hi":{"word":"पाखंड","question":"क्या पाखंड सबसे बुरा दुर्गुण है, या एक सार्वभौमिक मानवीय कमज़ोरी है जिसे हम बढ़ा-चढ़ाकर देखते हैं?","examples":[{"en":"Hypocrisy offends us not because the act is false, but because it demands from others a standard the speaker quietly exempts himself from meeting.","native":"पाखंड हमें इसलिए नहीं चुभता कि कृत्य झूठा है, बल्कि इसलिए कि वह दूसरों से ऐसा मानक माँगता है जिससे वक्ता खुद को चुपचाप मुक्त रखता है।"},{"en":"A hypocrite who preaches virtue still honours virtue in words, and societies need such tribute even from those who cannot pay it in deeds.","native":"जो पाखंडी सद्गुण का उपदेश देता है, वह शब्दों में तो सद्गुण का सम्मान करता ही है, और समाजों को ऐसी श्रद्धांजलि की ज़रूरत है, भले वह कर्म में अदा न हो।"},{"en":"We detect hypocrisy in our enemies with precision and excuse it in ourselves as complexity, which is itself the most common form of the vice.","native":"हम अपने दुश्मनों में पाखंड को सटीकता से पकड़ते हैं और अपने भीतर के पाखंड को जटिलता कहकर क्षमा कर देते हैं — और यही इस दुर्गुण का सबसे सामान्य रूप है।"}]},"es":{"word":"hipocresía","question":"¿Es la hipocresía el peor de los vicios o una debilidad humana universal que exageramos?","examples":[{"en":"Hypocrisy offends us not because the act is false, but because it demands from others a standard the speaker quietly exempts himself from meeting.","native":"La hipocresía nos ofende no porque el acto sea falso, sino porque exige de los demás una norma de la que el orador se exime discretamente."},{"en":"A hypocrite who preaches virtue still honours virtue in words, and societies need such tribute even from those who cannot pay it in deeds.","native":"El hipócrita que predica la virtud al menos la honra con palabras, y las sociedades necesitan ese tributo incluso de quienes no pueden pagarlo con hechos."},{"en":"We detect hypocrisy in our enemies with precision and excuse it in ourselves as complexity, which is itself the most common form of the vice.","native":"Detectamos la hipocresía en nuestros enemigos con precisión y la excusamos en nosotros como complejidad, lo cual es en sí la forma más común del vicio."}]},"zh":{"word":"虚伪","question":"虚伪是最恶劣的恶行，还是一种被我们夸大的普遍人性弱点？","examples":[{"en":"Hypocrisy offends us not because the act is false, but because it demands from others a standard the speaker quietly exempts himself from meeting.","native":"虚伪之所以刺痛我们，不是因为行为本身虚假，而是因为它要求他人遵守一个言说者自己悄悄豁免的标准。"},{"en":"A hypocrite who preaches virtue still honours virtue in words, and societies need such tribute even from those who cannot pay it in deeds.","native":"宣讲美德的伪君子至少在言辞上仍向美德致敬，而社会需要这种致敬，哪怕它无法以行动兑现。"},{"en":"We detect hypocrisy in our enemies with precision and excuse it in ourselves as complexity, which is itself the most common form of the vice.","native":"我们能精准识破敌人身上的虚伪，却把自己身上的虚伪宽宥为“复杂”——这本身就是这种恶行最常见的形态。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'censorship', 'Can censorship ever be justified in a free society, and who should decide?', '{"te":{"word":"సెన్సార్‌షిప్","question":"స్వేచ్ఛాయుత సమాజంలో సెన్సార్‌షిప్ ఎప్పుడైనా సమర్థనీయమవుతుందా, మరియు ఎవరు నిర్ణయించాలి?","examples":[{"en":"Censorship begins by silencing speech everyone despises and ends by silencing speech the powerful find inconvenient, for the machinery outlives its purpose.","native":"సెన్సార్‌షిప్ అందరూ ద్వేషించే మాటను మౌనపరచడంతో మొదలై, అధికారులకు అసౌకర్యమైన మాటను మౌనపరచడంతో ముగుస్తుంది — యంత్రాంగం తన లక్ష్యాన్ని మించి జీవిస్తుంది."},{"en":"The argument for censoring hatred assumes that suppressed ideas die, when history shows they more often fester underground and return wearing martyrdom.","native":"ద్వేషాన్ని సెన్సార్ చేయాలనే వాదన అణచివేసిన ఆలోచనలు చనిపోతాయని ఊహిస్తుంది, కానీ అవి భూగర్భంలో పుళ్లుపోసి, త్యాగి వేషంలో తిరిగి వస్తాయని చరిత్ర చూపిస్తుంది."},{"en":"Trusting any authority to decide which words we may hear presumes that authority will never itself benefit from our ignorance, a presumption history mocks.","native":"మనం ఏ మాటలు వినవచ్చో నిర్ణయించే హక్కును ఏ అధికారికైనా అప్పగించడం, ఆ అధికారం మన అజ్ఞానం నుండి ఎప్పటికీ ప్రయోజనం పొందదని ఊహించడమే — చరిత్ర ఈ ఊహను ఎగతాళి చేస్తుంది."}]},"hi":{"word":"सेंसरशिप","question":"क्या किसी स्वतंत्र समाज में सेंसरशिप कभी उचित ठहर सकती है, और यह निर्णय किसे लेना चाहिए?","examples":[{"en":"Censorship begins by silencing speech everyone despises and ends by silencing speech the powerful find inconvenient, for the machinery outlives its purpose.","native":"सेंसरशिप की शुरुआत उस वाणी को चुप कराने से होती है जिसे सभी घृणा करते हैं, और अंत उस वाणी को चुप कराने पर होता है जो सत्ताधारियों को असुविधाजनक लगे, क्योंकि मशीनरी अपने उद्देश्य से ज़्यादा जीवित रहती है।"},{"en":"The argument for censoring hatred assumes that suppressed ideas die, when history shows they more often fester underground and return wearing martyrdom.","native":"घृणा को सेंसर करने का तर्क यह मानता है कि दबाए गए विचार मर जाते हैं, जबकि इतिहास दिखाता है कि वे प्रायः भूमिगत होकर सड़ते हैं और शहादत का वेश पहनकर लौटते हैं।"},{"en":"Trusting any authority to decide which words we may hear presumes that authority will never itself benefit from our ignorance, a presumption history mocks.","native":"यह तय करने का अधिकार किसी भी अधिकारी को देना कि हम कौन से शब्द सुन सकते हैं, यह मानना है कि वह अधिकार कभी हमारी अजानता से लाभ नहीं उठाएगा — और इतिहास इस धारणा का मज़ाक उड़ाता है।"}]},"es":{"word":"censura","question":"¿Puede justificarse alguna vez la censura en una sociedad libre, y quién debería decidirlo?","examples":[{"en":"Censorship begins by silencing speech everyone despises and ends by silencing speech the powerful find inconvenient, for the machinery outlives its purpose.","native":"La censura empieza silenciando el discurso que todos desprecian y termina silenciando el que los poderosos encuentran incómodo, pues la maquinaria sobrevive a su propósito."},{"en":"The argument for censoring hatred assumes that suppressed ideas die, when history shows they more often fester underground and return wearing martyrdom.","native":"El argumento de censurar el odio supone que las ideas suprimidas mueren, cuando la historia muestra que más bien se enconan en la clandestinidad y regresan vestidas de martirio."},{"en":"Trusting any authority to decide which words we may hear presumes that authority will never itself benefit from our ignorance, a presumption history mocks.","native":"Confiar a cualquier autoridad decidir qué palabras podemos oír presume que esa autoridad jamás se beneficiará de nuestra ignorancia, presunción que la historia ridiculiza."}]},"zh":{"word":"审查制度","question":"在一个自由社会里，审查制度是否可能有正当性？又该由谁来裁断？","examples":[{"en":"Censorship begins by silencing speech everyone despises and ends by silencing speech the powerful find inconvenient, for the machinery outlives its purpose.","native":"审查始于让所有人都鄙夷的言论噤声，终于让权贵感到不便的言论噤声——因为这部机器的寿命总会超过它最初的目的。"},{"en":"The argument for censoring hatred assumes that suppressed ideas die, when history shows they more often fester underground and return wearing martyrdom.","native":"主张审查仇恨言论的人假设被压制的思想会消亡，而历史表明，它们更多是在地下溃烂，然后披着殉道的外衣归来。"},{"en":"Trusting any authority to decide which words we may hear presumes that authority will never itself benefit from our ignorance, a presumption history mocks.","native":"把“我们能听到什么话”的决定权托付给任何权威，等于假定该权威永远不会从我们的无知中获利——而历史嘲笑这种假定。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'propaganda', 'How does modern propaganda differ from the propaganda of the past?', '{"te":{"word":"ప్రచారం","question":"ఆధునిక ప్రచారం గతకాలపు ప్రచారం నుండి ఎలా భిన్నంగా ఉంది?","examples":[{"en":"Old propaganda shouted one message from a single tower; modern propaganda whispers a thousand tailored messages, each believing itself a private thought.","native":"పాత ప్రచారం ఒకే గోపురం నుండి ఒకే సందేశాన్ని అరిచేది; ఆధునిక ప్రచారం వేలాది అనుకూల సందేశాలను గుసగుసలాడుతుంది — ప్రతిదాన్ని ప్రైవేట్ ఆలోచనగా నమ్మేలా."},{"en":"Where censorship once blocked information, today’s propagandists drown it, flooding every channel until citizens abandon the search for truth from exhaustion.","native":"ఇంతకుముందు సెన్సార్‌షిప్ సమాచారాన్ని అడ్డగించేది; నేటి ప్రచారకర్తలు దాన్ని ముంచెత్తుతారు — పౌరులు అలసిపోయి సత్యం వెతకడం మానేసేంతవరకు ప్రతి ఛానెల్‌ను నింపేస్తారు."},{"en":"The most effective propaganda no longer demands belief; it merely demands cynicism, for a population that believes nothing will resist nothing.","native":"అత్యంత ప్రభావవంతమైన ప్రచారం ఇక నమ్మడాన్ని కోరదు; అది కేవలం నిరాశావాదాన్ని కోరుతుంది — ఎందుకంటే ఏదీ నమ్మని జనాభా దేనికీ ప్రతిఘటించదు."}]},"hi":{"word":"प्रचार-प्रसार","question":"आधुनिक प्रचार-प्रसार अतीत के प्रचार-प्रसार से कैसे भिन्न है?","examples":[{"en":"Old propaganda shouted one message from a single tower; modern propaganda whispers a thousand tailored messages, each believing itself a private thought.","native":"पुराना प्रचार एक ही मीनार से एक ही संदेश चिल्लाता था; आधुनिक प्रचार हज़ारों तैयार किए हुए संदेश फुसफुसाता है, जिनमें से हर एक खुद को निजी सोच समझता है।"},{"en":"Where censorship once blocked information, today’s propagandists drown it, flooding every channel until citizens abandon the search for truth from exhaustion.","native":"जहाँ कभी सेंसरशिप सूचना को रोकती थी, आज के प्रचारक उसे डुबो देते हैं — हर चैनल को इतना भर देते हैं कि नागरिक थककर सत्य की खोज छोड़ दें।"},{"en":"The most effective propaganda no longer demands belief; it merely demands cynicism, for a population that believes nothing will resist nothing.","native":"सबसे प्रभावी प्रचार अब विश्वास की माँग नहीं करता; वह केवल निराशावाद की माँग करता है, क्योंकि जो जनता कुछ नहीं मानती, वह किसी बात का विरोध भी नहीं करती।"}]},"es":{"word":"propaganda","question":"¿En qué se diferencia la propaganda moderna de la del pasado?","examples":[{"en":"Old propaganda shouted one message from a single tower; modern propaganda whispers a thousand tailored messages, each believing itself a private thought.","native":"La propaganda vieja gritaba un solo mensaje desde una única torre; la moderna susurra mil mensajes a medida, cada uno creyéndose un pensamiento privado."},{"en":"Where censorship once blocked information, today’s propagandists drown it, flooding every channel until citizens abandon the search for truth from exhaustion.","native":"Donde antes la censura bloqueaba la información, los propagandistas de hoy la ahogan, inundando cada canal hasta que los ciudadanos abandonan exhaustos la búsqueda de la verdad."},{"en":"The most effective propaganda no longer demands belief; it merely demands cynicism, for a population that believes nothing will resist nothing.","native":"La propaganda más eficaz ya no exige creencia; solo exige cinismo, porque una población que no cree nada no se resiste a nada."}]},"zh":{"word":"宣传","question":"现代宣传与过去的宣传有何不同？","examples":[{"en":"Old propaganda shouted one message from a single tower; modern propaganda whispers a thousand tailored messages, each believing itself a private thought.","native":"旧宣传从一座高塔上高喊同一条信息；现代宣传则低语着千百条量身定制的信息，而每一条都自以为是私人的想法。"},{"en":"Where censorship once blocked information, today’s propagandists drown it, flooding every channel until citizens abandon the search for truth from exhaustion.","native":"昔日审查靠封锁信息，今日的宣传者则靠淹没信息——灌满每一条渠道，直到公民精疲力竭地放弃追寻真相。"},{"en":"The most effective propaganda no longer demands belief; it merely demands cynicism, for a population that believes nothing will resist nothing.","native":"最有效的宣传已不再要求你相信任何东西；它只要求你犬儒——因为什么都不相信的人民，什么都不会反抗。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'surveillance', 'Does constant surveillance make us safer, or does it change who we are?', '{"te":{"word":"నిఘా","question":"నిరంతర నిఘా మనల్ని సురక్షితంగా చేస్తుందా, లేదా మనం ఎవరో మార్చేస్తుందా?","examples":[{"en":"Surveillance changes behaviour even when no one is watching, because the possibility of being seen teaches us to police our own thoughts and gestures.","native":"ఎవరూ చూడకపోయినా నిఘా ప్రవర్తనను మారుస్తుంది, ఎందుకంటే చూడబడే అవకాశం మన స్వంత ఆలోచనలను, సైగలను మనమే పోలీసు చేసుకోవడం నేర్పుతుంది."},{"en":"A government that watches everyone trusts no one, and citizens who know they are watched learn to return the compliment with equal distrust.","native":"అందరినీ గమనించే ప్రభుత్వం ఎవరినీ నమ్మదు; తాము గమనించబడుతున్నామని తెలిసిన పౌరులు అదే అనుమానాన్ని కృతజ్ఞతగా తిరిగి ఇవ్వడం నేర్చుకుంటారు."},{"en":"We accepted surveillance for security after every crisis, yet the cameras remained long after each danger passed, quietly redefining what privacy once meant.","native":"ప్రతి సంక్షోభం తర్వాత భద్రత కోసం మనం నిఘాను అంగీకరించాం, అయితే ప్రతి ప్రమాదం గతించిపోయిన చాలాకాలం తర్వాత కూడా కెమెరాలు మిగిలిపోయి, గోప్యత అంటే ఏమిటో నిశ్శబ్దంగా తిరిగి నిర్వచించాయి."}]},"hi":{"word":"निगरानी","question":"क्या निरंतर निगरानी हमें सुरक्षित बनाती है, या वह हमें बदल देती है कि हम कौन हैं?","examples":[{"en":"Surveillance changes behaviour even when no one is watching, because the possibility of being seen teaches us to police our own thoughts and gestures.","native":"निगरानी तब भी व्यवहार बदल देती है जब कोई देख नहीं रहा होता, क्योंकि देखे जाने की संभावना ही हमें अपने विचारों और इशारों की खुद पुलिसिंग करना सिखा देती है।"},{"en":"A government that watches everyone trusts no one, and citizens who know they are watched learn to return the compliment with equal distrust.","native":"जो सरकार सब पर नज़र रखती है, वह किसी पर भरोसा नहीं करती, और जो नागरिक जानते हैं कि उन पर नज़र है, वे भी उतना ही अविश्वास लौटाना सीख जाते हैं।"},{"en":"We accepted surveillance for security after every crisis, yet the cameras remained long after each danger passed, quietly redefining what privacy once meant.","native":"हर संकट के बाद हमने सुरक्षा के नाम पर निगरानी स्वीकार की, पर हर ख़तरे के बीतने के बहुत बाद भी कैमरे बने रहे, और चुपचाप निजता के अर्थ को फिर से परिभाषित करते रहे।"}]},"es":{"word":"vigilancia","question":"¿Nos hace más seguros la vigilancia constante o cambia quiénes somos?","examples":[{"en":"Surveillance changes behaviour even when no one is watching, because the possibility of being seen teaches us to police our own thoughts and gestures.","native":"La vigilancia cambia el comportamiento incluso cuando nadie mira, porque la posibilidad de ser vistos nos enseña a vigilar nuestros propios pensamientos y gestos."},{"en":"A government that watches everyone trusts no one, and citizens who know they are watched learn to return the compliment with equal distrust.","native":"Un gobierno que vigila a todos no confía en nadie, y los ciudadanos que saben que son observados aprenden a devolver el cumplido con igual desconfianza."},{"en":"We accepted surveillance for security after every crisis, yet the cameras remained long after each danger passed, quietly redefining what privacy once meant.","native":"Aceptamos la vigilancia por seguridad tras cada crisis, pero las cámaras permanecieron mucho después de pasado cada peligro, redefiniendo en silencio lo que significaba la privacidad."}]},"zh":{"word":"监控","question":"无处不在的监控让我们更安全，还是改变了我们是谁？","examples":[{"en":"Surveillance changes behaviour even when no one is watching, because the possibility of being seen teaches us to police our own thoughts and gestures.","native":"即便无人注视，监控也会改变行为，因为被看到的可能性会教会我们自我审查自己的思想和举止。"},{"en":"A government that watches everyone trusts no one, and citizens who know they are watched learn to return the compliment with equal distrust.","native":"监视所有人的政府不信任任何人，而知道自己被监视的公民，也学会以同等的不信任回敬。"},{"en":"We accepted surveillance for security after every crisis, yet the cameras remained long after each danger passed, quietly redefining what privacy once meant.","native":"每次危机之后，我们都以安全之名接受了监控；然而危险过去很久之后，摄像头依然矗立，悄然重新定义着隐私的含义。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'capitalism', 'Does capitalism reward innovation, or does it primarily reward ownership?', '{"te":{"word":"మూలధనవాదం","question":"మూలధనవాదం ఆవిష్కరణకు బహుమతి ఇస్తుందా, లేదా అది ప్రధానంగా యాజమాన్యానికే బహుమతి ఇస్తుందా?","examples":[{"en":"Capitalism excels at generating wealth and innovation, yet it measures everything except what matters most: meaning, belonging, and the health of communities.","native":"సంపదను, ఆవిష్కరణను సృష్టించడంలో మూలధనవాదం అత్యుత్తమం, అయితే అతి ముఖ్యమైనవి — అర్థం, అనుబంధం, సమాజాల ఆరోగ్యం — మినహా ప్రతిదాన్ని అది కొలుస్తుంది."},{"en":"Markets are magnificent servants and terrible masters, for they price everything instantly but understand the value of nothing that cannot be sold.","native":"మార్కెట్లు అద్భుతమైన సేవకులు, భయంకరమైన యజమానులు — అవి ప్రతిదానికి వెంటనే ధర కడతాయి కానీ అమ్మలేని దాని విలువను అర్థం చేసుకోవు."},{"en":"The defender and critic of capitalism often describe different centuries: one recalls poverty defeated, the other observes prosperity that forgot to be shared.","native":"మూలధనవాదం సమర్థకుడూ విమర్శకుడూ తరచుగా వేర్వేరు శతాబ్దాలను వర్ణిస్తారు: ఒకరు ఓడిపోయిన పేదరికాన్ని గుర్తుచేసుకుంటారు, మరొకరు పంచుకోవడం మర్చిపోయిన శ్రేయస్సును గమనిస్తారు."}]},"hi":{"word":"पूंजीवाद","question":"क्या पूंजीवाद नवाचार को पुरस्कृत करता है, या वह मुख्य रूप से स्वामित्व को ही पुरस्कृत करता है?","examples":[{"en":"Capitalism excels at generating wealth and innovation, yet it measures everything except what matters most: meaning, belonging, and the health of communities.","native":"पूंजीवाद धन और नवाचार पैदा करने में माहिर है, पर वह सब कुछ मापता है सिवाय उसके जो सबसे ज़रूरी है: अर्थ, अपनापन और समुदायों का स्वास्थ्य।"},{"en":"Markets are magnificent servants and terrible masters, for they price everything instantly but understand the value of nothing that cannot be sold.","native":"बाज़ार शानदार नौकर हैं और भयानक मालिक, क्योंकि वे हर चीज़ का दाम तुरंत लगा देते हैं, पर जिसे बेचा न जा सके उसकी कीमत समझ नहीं पाते।"},{"en":"The defender and critic of capitalism often describe different centuries: one recalls poverty defeated, the other observes prosperity that forgot to be shared.","native":"पूंजीवाद का समर्थक और आलोचक अक्सर अलग-अलग सदियों का वर्णन करते हैं: एक पराजित ग़रीबी को याद करता है, दूसरा उस समृद्धि को देखता है जो बाँटना भूल गई।"}]},"es":{"word":"capitalismo","question":"¿Recompensa el capitalismo la innovación o premia principalmente la propiedad?","examples":[{"en":"Capitalism excels at generating wealth and innovation, yet it measures everything except what matters most: meaning, belonging, and the health of communities.","native":"El capitalismo sobresale generando riqueza e innovación, pero lo mide todo excepto lo que más importa: el sentido, la pertenencia y la salud de las comunidades."},{"en":"Markets are magnificent servants and terrible masters, for they price everything instantly but understand the value of nothing that cannot be sold.","native":"Los mercados son sirvientes magníficos y amos terribles, pues le ponen precio a todo al instante pero no comprenden el valor de nada que no pueda venderse."},{"en":"The defender and critic of capitalism often describe different centuries: one recalls poverty defeated, the other observes prosperity that forgot to be shared.","native":"El defensor y el crítico del capitalismo suelen describir siglos distintos: uno recuerda la pobreza vencida, el otro observa una prosperidad que olvidó compartirse."}]},"zh":{"word":"资本主义","question":"资本主义奖励的是创新，还是主要奖励所有权？","examples":[{"en":"Capitalism excels at generating wealth and innovation, yet it measures everything except what matters most: meaning, belonging, and the health of communities.","native":"资本主义在创造财富与创新上卓尔不群，但它衡量一切，却唯独漏掉了最重要的东西：意义、归属感与社群的健康。"},{"en":"Markets are magnificent servants and terrible masters, for they price everything instantly but understand the value of nothing that cannot be sold.","native":"市场是极好的仆人，却是可怕的主人——它能瞬间为万物定价，却理解不了任何无法出售之物的价值。"},{"en":"The defender and critic of capitalism often describe different centuries: one recalls poverty defeated, the other observes prosperity that forgot to be shared.","native":"资本主义的捍卫者与批评者往往描述的是不同的世纪：一个记得被击败的贫困，另一个看见的是忘却了分享的繁荣。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'socialism', 'Can socialist ideals be realized without sacrificing individual initiative?', '{"te":{"word":"సామ్యవాదం","question":"వ్యక్తిగత చొరవను త్యాగం చేయకుండా సామ్యవాద ఆదర్శాలను సాకారం చేయగలమా?","examples":[{"en":"Socialism promises solidarity but must answer why central planners should know better than millions of people making their own small decisions daily.","native":"సామ్యవాదం ఐక్యతను వాగ్దానం చేస్తుంది, కానీ రోజూ తమ చిన్న చిన్న నిర్ణయాలు తామే తీసుకునే కోట్లాది మంది కంటే కేంద్ర ప్రణాళికా కర్తలకు ఎందుకు బాగా తెలియాలి అనే ప్రశ్నకు సమాధానం చెప్పాల్సిందే."},{"en":"The deepest question is not whether the state should help the weak, but how much power the helpers may accumulate before help becomes command.","native":"బలహీనులకు రాష్ట్రం సహాయం చేయాలా వద్దా అన్నది లోతైన ప్రశ్న కాదు; సహాయకులు ఎంత అధికారం పేరుకుపోవచ్చు, సహాయం ఆజ్ఞగా మారేలోపు ఎంత అన్నదే అసలు ప్రశ్న."},{"en":"Every society mixes market and collective provision; the honest debate concerns proportions, though ideologues insist on pretending purity is possible.","native":"ప్రతి సమాజం మార్కెట్, సముదాయ సరఫరాను మిళితం చేస్తుంది; నిజాయితీగల చర్చ అనుపాతాల గురించి — అయితే సిద్ధాంతకర్తలు స్వచ్ఛత సాధ్యమన్నట్లు నటిస్తూనే ఉంటారు."}]},"hi":{"word":"समाजवाद","question":"क्या व्यक्तिगत पहल का त्याग किए बिना समाजवादी आदर्शों को साकार किया जा सकता है?","examples":[{"en":"Socialism promises solidarity but must answer why central planners should know better than millions of people making their own small decisions daily.","native":"समाजवाद एकजुटता का वादा करता है, पर उसे यह जवाब देना होगा कि केंद्रीय योजनाकार रोज़ अपने छोटे-छोटे फ़ैसले लेने वाले लाखों लोगों से बेहतर क्यों जानेंगे।"},{"en":"The deepest question is not whether the state should help the weak, but how much power the helpers may accumulate before help becomes command.","native":"सबसे गहरा सवाल यह नहीं कि राज्य को कमज़ोरों की मदद करनी चाहिए या नहीं, बल्कि यह कि मददगार कितनी सत्ता जमा कर लें, इससे पहले कि मदद हुक्म बन जाए।"},{"en":"Every society mixes market and collective provision; the honest debate concerns proportions, though ideologues insist on pretending purity is possible.","native":"हर समाज बाज़ार और सामूहिक प्रबंध का मिश्रण है; ईमानदार बहस अनुपातों पर है, यद्यपि वैचारिक लोग ऐसा दिखावा करने पर अड़े रहते हैं मानो शुद्धता संभव है।"}]},"es":{"word":"socialismo","question":"¿Pueden realizarse los ideales socialistas sin sacrificar la iniciativa individual?","examples":[{"en":"Socialism promises solidarity but must answer why central planners should know better than millions of people making their own small decisions daily.","native":"El socialismo promete solidaridad, pero debe responder por qué los planificadores centrales sabrían más que millones de personas tomando sus propias pequeñas decisiones a diario."},{"en":"The deepest question is not whether the state should help the weak, but how much power the helpers may accumulate before help becomes command.","native":"La cuestión más profunda no es si el Estado debe ayudar a los débiles, sino cuánto poder pueden acumular los ayudantes antes de que la ayuda se vuelva mandato."},{"en":"Every society mixes market and collective provision; the honest debate concerns proportions, though ideologues insist on pretending purity is possible.","native":"Toda sociedad mezcla mercado y provisión colectiva; el debate honesto versa sobre proporciones, aunque los ideólogos insisten en fingir que la pureza es posible."}]},"zh":{"word":"社会主义","question":"能否在不牺牲个人主动性的前提下实现社会主义理想？","examples":[{"en":"Socialism promises solidarity but must answer why central planners should know better than millions of people making their own small decisions daily.","native":"社会主义许诺团结，但它必须回答：为什么中央计划者会比每天各自做出无数小决定的千百万普通人懂得更多？"},{"en":"The deepest question is not whether the state should help the weak, but how much power the helpers may accumulate before help becomes command.","native":"最深刻的问题不是国家该不该扶助弱者，而是扶助者可以积累多少权力，才不会让扶助变成命令。"},{"en":"Every society mixes market and collective provision; the honest debate concerns proportions, though ideologues insist on pretending purity is possible.","native":"每个社会都是市场与集体供给的混合体；诚实的争论关乎比例，尽管意识形态家们偏要装作纯粹是可能的。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'nationalism', 'Is nationalism a source of solidarity, or a recipe for conflict?', '{"te":{"word":"జాతీయవాదం","question":"జాతీయవాదం ఐక్యతకు వనరా, లేదా సంఘర్షణకు వంటకమా?","examples":[{"en":"Nationalism builds solidarity by drawing a circle of belonging, yet every circle that embraces some people necessarily excludes all the others.","native":"జాతీయవాదం అనుబంధం యొక్క వృత్తాన్ని గీయడం ద్వారా ఐక్యతను నిర్మిస్తుంది, అయితే కొంతమందిని ఆలింగనం చేసుకునే ప్రతి వృత్తం తప్పనిసరిగా మిగతా వారందరినీ బహిష్కరిస్తుంది."},{"en":"The nation asks us to love millions we will never meet, which is magnificent when it breeds generosity and catastrophic when it breeds contempt for outsiders.","native":"మనం ఎప్పటికీ కలవని కోట్లాది మందిని ప్రేమించమని దేశం కోరుతుంది — అది ఉదారతను పుట్టించినప్పుడు అద్భుతం, బయటివారిపై తృణీకారాన్ని పుట్టించినప్పుడు విపత్తు."},{"en":"History suggests nationalism is strongest exactly where shared civic life is weakest, filling the void left when institutions fail to inspire loyalty.","native":"పంచుకున్న పౌర జీవితం అత్యంత బలహీనంగా ఉన్న చోట్లే జాతీయవాదం అత్యంత బలంగా ఉంటుందని చరిత్ర సూచిస్తుంది — సంస్థలు నిష్ఠను ప్రేరేపించడంలో విఫలమైనప్పుడు మిగిలే శూన్యాన్ని అది నింపుతుంది."}]},"hi":{"word":"राष्ट्रवाद","question":"क्या राष्ट्रवाद एकजुटता का स्रोत है, या संघर्ष की विधि?","examples":[{"en":"Nationalism builds solidarity by drawing a circle of belonging, yet every circle that embraces some people necessarily excludes all the others.","native":"राष्ट्रवाद अपनेपन का एक घेरा खींचकर एकजुटता बनाता है, पर हर घेरा जो कुछ लोगों को अपनाता है, वह अनिवार्य रूप से बाक़ी सबको बाहर करता है।"},{"en":"The nation asks us to love millions we will never meet, which is magnificent when it breeds generosity and catastrophic when it breeds contempt for outsiders.","native":"राष्ट्र हमसे उन लाखों लोगों से प्रेम करने को कहता है जिनसे हम कभी नहीं मिलेंगे — यह तब भव्य है जब यह उदारता जन्म दे, और तब विनाशकारी जब यह बाहर वालों के प्रति तिरस्कार जन्म दे।"},{"en":"History suggests nationalism is strongest exactly where shared civic life is weakest, filling the void left when institutions fail to inspire loyalty.","native":"इतिहास बताता है कि राष्ट्रवाद ठीक वहीं सबसे मज़बूत होता है जहाँ साझा नागरिक जीवन सबसे कमज़ोर होता है — जब संस्थाएँ निष्ठा प्रेरित करने में असफल होती हैं, तो वह उस रिक्ति को भर देता है।"}]},"es":{"word":"nacionalismo","question":"¿Es el nacionalismo una fuente de solidaridad o una receta para el conflicto?","examples":[{"en":"Nationalism builds solidarity by drawing a circle of belonging, yet every circle that embraces some people necessarily excludes all the others.","native":"El nacionalismo construye solidaridad trazando un círculo de pertenencia, pero todo círculo que abraza a algunos excluye necesariamente a todos los demás."},{"en":"The nation asks us to love millions we will never meet, which is magnificent when it breeds generosity and catastrophic when it breeds contempt for outsiders.","native":"La nación nos pide amar a millones que jamás conoceremos, lo cual es magnífico cuando engendra generosidad y catastrófico cuando engendra desprecio por el de fuera."},{"en":"History suggests nationalism is strongest exactly where shared civic life is weakest, filling the void left when institutions fail to inspire loyalty.","native":"La historia sugiere que el nacionalismo es más fuerte precisamente donde la vida cívica compartida es más débil, llenando el vacío que dejan las instituciones cuando no inspiran lealtad."}]},"zh":{"word":"民族主义","question":"民族主义是凝聚力的源泉，还是冲突的配方？","examples":[{"en":"Nationalism builds solidarity by drawing a circle of belonging, yet every circle that embraces some people necessarily excludes all the others.","native":"民族主义通过画出一个归属的圆圈来建立团结，但每一个拥抱一些人的圆圈，都必然把其余所有人排除在外。"},{"en":"The nation asks us to love millions we will never meet, which is magnificent when it breeds generosity and catastrophic when it breeds contempt for outsiders.","native":"国家要求我们去爱千百万素未谋面的人——当它孕育慷慨时，这很伟大；当它孕育对外人的蔑视时，这便是灾难。"},{"en":"History suggests nationalism is strongest exactly where shared civic life is weakest, filling the void left when institutions fail to inspire loyalty.","native":"历史表明，民族主义恰恰在共同公民生活最薄弱之处最为强大，它填补的是制度无法激发忠诚时留下的真空。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'patriotism', 'How does healthy patriotism differ from blind loyalty to one’s country?', '{"te":{"word":"దేశభక్తి","question":"ఆరోగ్యకరమైన దేశభక్తికి, దేశం పట్ల గుడ్డి నిష్ఠకు మధ్య తేడా ఏమిటి?","examples":[{"en":"The patriot loves his country as an adult loves a parent: with clear eyes about its faults and steady commitment to its better possibilities.","native":"దేశభక్తుడు తన దేశాన్ని పెద్దవాడు తల్లిదండ్రులను ప్రేమించినట్లు ప్రేమిస్తాడు: దాని లోపాలపై స్పష్టమైన దృష్టితో, దాని మెరుగైన అవకాశాలపై స్థిరమైన నిబద్ధతతో."},{"en":"Blind loyalty demands agreement with every policy, whereas genuine patriotism sometimes requires resisting one’s government in the name of one’s country.","native":"గుడ్డి నిష్ఠ ప్రతి విధానంతో ఏకీభవింపను కోరుతుంది, అయితే నిజమైన దేశభక్తి కొన్నిసార్లు దేశం పేరుతో ప్రభుత్వాన్ని ఎదిరించడాన్ని కూడా కోరుతుంది."},{"en":"We should be suspicious of leaders who wrap themselves in flags, for patriotism loudly advertised is usually a product being sold to the trusting.","native":"జెండాల్లో చుట్టుకునే నాయకుల పట్ల మనం అనుమానంగా ఉండాలి, ఎందుకంటే గట్టిగా ప్రకటించబడే దేశభక్తి సాధారణంగా నమ్మేవారికి అమ్మబడే వస్తువే."}]},"hi":{"word":"देशभक्ति","question":"स्वस्थ देशभक्ति और अपने देश के प्रति अंधी निष्ठा में क्या अंतर है?","examples":[{"en":"The patriot loves his country as an adult loves a parent: with clear eyes about its faults and steady commitment to its better possibilities.","native":"देशभक्त अपने देश से वैसे प्रेम करता है जैसे कोई वयस्क अपने माता-पिता से करता है: उसकी कमियों को स्पष्ट देखते हुए और उसकी बेहतर संभावनाओं के प्रति दृढ़ प्रतिबद्धता के साथ।"},{"en":"Blind loyalty demands agreement with every policy, whereas genuine patriotism sometimes requires resisting one’s government in the name of one’s country.","native":"अंधी निष्ठा हर नीति से सहमति माँगती है, जबकि सच्ची देशभक्ति कभी-कभी देश के नाम पर अपनी ही सरकार का विरोध करने की माँग करती है।"},{"en":"We should be suspicious of leaders who wrap themselves in flags, for patriotism loudly advertised is usually a product being sold to the trusting.","native":"हमें उन नेताओं से सावधान रहना चाहिए जो खुद को झंडों में लपेटते हैं, क्योंकि ज़ोर-शोर से विज्ञापित देशभक्ति प्रायः भरोसेमंदों को बेचा जाने वाला माल होती है।"}]},"es":{"word":"patriotismo","question":"¿En qué se diferencia el patriotismo sano de la lealtad ciega al propio país?","examples":[{"en":"The patriot loves his country as an adult loves a parent: with clear eyes about its faults and steady commitment to its better possibilities.","native":"El patriota ama a su país como un adulto ama a un padre: con los ojos claros ante sus defectos y con compromiso firme hacia sus mejores posibilidades."},{"en":"Blind loyalty demands agreement with every policy, whereas genuine patriotism sometimes requires resisting one’s government in the name of one’s country.","native":"La lealtad ciega exige estar de acuerdo con cada política, mientras que el patriotismo genuino a veces exige resistir al propio gobierno en nombre del propio país."},{"en":"We should be suspicious of leaders who wrap themselves in flags, for patriotism loudly advertised is usually a product being sold to the trusting.","native":"Deberíamos desconfiar de los líderes que se envuelven en banderas, porque el patriotismo anunciado a gritos suele ser un producto vendido a los crédulos."}]},"zh":{"word":"爱国主义","question":"健康的爱国主义与对国家的盲目效忠有何区别？","examples":[{"en":"The patriot loves his country as an adult loves a parent: with clear eyes about its faults and steady commitment to its better possibilities.","native":"爱国者爱自己的国家，如同成年人爱父母：看清它的缺点，同时坚定地致力于它更好的可能。"},{"en":"Blind loyalty demands agreement with every policy, whereas genuine patriotism sometimes requires resisting one’s government in the name of one’s country.","native":"盲目的效忠要求赞同每一项政策，而真正的爱国有时要求以国家之名抵制自己的政府。"},{"en":"We should be suspicious of leaders who wrap themselves in flags, for patriotism loudly advertised is usually a product being sold to the trusting.","native":"我们应当警惕那些把自己裹进旗帜里的领导人，因为大声叫卖的爱国主义，通常是卖给轻信者的商品。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'cosmopolitanism', 'Can we be citizens of the world without losing our local attachments?', '{"te":{"word":"విశ్వపౌరత్వం","question":"మన స్థానిక అనుబంధాలను కోల్పోకుండా ప్రపంచ పౌరులుగా ఉండగలమా?","examples":[{"en":"Cosmopolitanism asks us to extend moral concern beyond our borders, yet love of humanity means little if it never touches a single actual neighbour.","native":"సరిహద్దులకు అవతల నైతిక శ్రద్ధను విస్తరించమని విశ్వపౌరత్వం కోరుతుంది, అయితే కనీసం ఒక్క నిజమైన పొరుగువాన్ని కూడా తాకని మానవతాప్రేమకు విలువ లేదు."},{"en":"The risk of global citizenship is not disloyalty but thinness: belonging everywhere can become belonging nowhere, with roots too shallow for sacrifice.","native":"ప్రపంచ పౌరత్వం యొక్క ప్రమాదం అనిష్ఠ కాదు, తెల్లపడడం: ప్రతిచోటా చెందినవారవడం ఎక్కడా చెందనివారవడం కావచ్చు — త్యాగానికి సరిపోనంత తక్కువ వేళ్లతో."},{"en":"Perhaps identity works like concentric circles — family, town, nation, humanity — and wisdom lies in refusing to let any circle erase the others.","native":"బహుశా గుర్తింపు కేంద్రక వృత్తాల్లా పనిచేస్తుంది — కుటుంబం, ఊరు, దేశం, మానవత — ఏ వృత్తం మిగతా వాటిని చెరిపివేయనీయకపోవడమే జ్ఞానం."}]},"hi":{"word":"विश्वनागरिकता","question":"क्या हम अपने स्थानीय लगाव खोए बिना विश्व के नागरिक बन सकते हैं?","examples":[{"en":"Cosmopolitanism asks us to extend moral concern beyond our borders, yet love of humanity means little if it never touches a single actual neighbour.","native":"विश्वनागरिकता हमसे नैतिक चिंता को अपनी सीमाओं से परे बढ़ाने को कहती है, पर मानवता से प्रेम का अर्थ क्या, यदि वह कभी किसी वास्तविक पड़ोसी तक न पहुँचे।"},{"en":"The risk of global citizenship is not disloyalty but thinness: belonging everywhere can become belonging nowhere, with roots too shallow for sacrifice.","native":"वैश्विक नागरिकता का जोखिम बेइमानी नहीं, हल्कापन है: हर जगह का होना कहीं का न होना बन सकता है — जड़ें इतनी उथलीं कि त्याग न हो सके।"},{"en":"Perhaps identity works like concentric circles — family, town, nation, humanity — and wisdom lies in refusing to let any circle erase the others.","native":"शायद पहचान संकेंद्रित वृत्तों की तरह काम करती है — परिवार, कस्बा, राष्ट्र, मानवता — और बुद्धि इसी में है कि कोई वृत्त दूसरों को मिटाने न पाए।"}]},"es":{"word":"cosmopolitismo","question":"¿Podemos ser ciudadanos del mundo sin perder nuestros vínculos locales?","examples":[{"en":"Cosmopolitanism asks us to extend moral concern beyond our borders, yet love of humanity means little if it never touches a single actual neighbour.","native":"El cosmopolitismo nos pide extender la preocupación moral más allá de nuestras fronteras, pero el amor a la humanidad vale poco si nunca alcanza a un vecino real."},{"en":"The risk of global citizenship is not disloyalty but thinness: belonging everywhere can become belonging nowhere, with roots too shallow for sacrifice.","native":"El riesgo de la ciudadanía global no es la deslealtad sino la superficialidad: pertenecer a todas partes puede volverse pertenecer a ninguna, con raíces demasiado débiles para el sacrificio."},{"en":"Perhaps identity works like concentric circles — family, town, nation, humanity — and wisdom lies in refusing to let any circle erase the others.","native":"Quizá la identidad funciona como círculos concéntricos — familia, pueblo, nación, humanidad — y la sabiduría está en no dejar que ningún círculo borre a los demás."}]},"zh":{"word":"世界主义","question":"我们能否在不失去本土牵挂的情况下成为世界公民？","examples":[{"en":"Cosmopolitanism asks us to extend moral concern beyond our borders, yet love of humanity means little if it never touches a single actual neighbour.","native":"世界主义要求我们把道德关怀延伸到国界之外；但若对人类的爱从未触及一个真实的邻人，这份爱便毫无意义。"},{"en":"The risk of global citizenship is not disloyalty but thinness: belonging everywhere can become belonging nowhere, with roots too shallow for sacrifice.","native":"全球公民身份的风险不在于不忠，而在于稀薄：处处归属可能变成无处归属，根扎得太浅，不足以支撑牺牲。"},{"en":"Perhaps identity works like concentric circles — family, town, nation, humanity — and wisdom lies in refusing to let any circle erase the others.","native":"或许身份像同心圆一样运作——家庭、城镇、国家、人类——而智慧在于不让任何一个圆抹去其他圆。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'individualism', 'Has individualism liberated us, or has it left us isolated?', '{"te":{"word":"వ్యక్తివాదం","question":"వ్యక్తివాదం మనల్ని విముక్తి చేసిందా, లేదా ఒంటరిగా వదిలేసిందా?","examples":[{"en":"Individualism freed millions from suffocating traditions, yet in dissolving every obligation it also dissolved the thick relationships that made life bearable.","native":"వ్యక్తివాదం శ్వాస ముట్టించే సంప్రదాయాల నుండి కోట్లాది మందిని విడిపించింది, అయితే ప్రతి బాధ్యతను కరిగించడంలో జీవితాన్ని సహ్యం చేసే గాఢ సంబంధాలను కూడా అది కరిగించింది."},{"en":"The self-made person is a flattering fiction, for each of us arrives already indebted to ancestors, teachers, and strangers whose work sustains our own.","native":"స్వయంకృషితో ఎదిగిన వ్యక్తి అనేది ఆటపట్టించే కల్పన — మనమందరం పూర్వీకులకు, ఉపాధ్యాయులకు, మన పనిని నిలబెట్టే అపరిచితులకు అప్పుపడే ఉంటాం."},{"en":"A society of pure individuals must manufacture belonging artificially, which is why loneliness has become the paradoxical epidemic of the most liberated age.","native":"స్వచ్ఛమైన వ్యక్తుల సమాజం అనుబంధాన్ని కృత్రిమంగా తయారు చేయాల్సి ఉంటుంది — అత్యంత విముక్తి పొందిన యుగంలో ఒంటరితనం విరోధాభాసమైన మహమ్మారి అవడానికి కారణం ఇదే."}]},"hi":{"word":"व्यक्तिवाद","question":"क्या व्यक्तिवाद ने हमें मुक्त किया है, या हमें अलग-थलग छोड़ दिया है?","examples":[{"en":"Individualism freed millions from suffocating traditions, yet in dissolving every obligation it also dissolved the thick relationships that made life bearable.","native":"व्यक्तिवाद ने लाखों लोगों को दमघोंटू परंपराओं से आज़ाद कराया, पर हर बाध्यता को घुलाने में उसने उन गाढ़े रिश्तों को भी घुला दिया जो जीवन को सहनीय बनाते थे।"},{"en":"The self-made person is a flattering fiction, for each of us arrives already indebted to ancestors, teachers, and strangers whose work sustains our own.","native":"स्वनिर्मित व्यक्ति एक चापलूसी भरा काल्पनिक है, क्योंकि हम में से हर कोई पहले से ही पूर्वजों, शिक्षकों और उन अजनबियों का ऋणी होकर आता है जिनका काम हमारे काम को थामे रहता है।"},{"en":"A society of pure individuals must manufacture belonging artificially, which is why loneliness has become the paradoxical epidemic of the most liberated age.","native":"शुद्ध व्यक्तियों के समाज को अपनापन कृत्रिम रूप से बनाना पड़ता है — यही कारण है कि सबसे मुक्त युग में अकेलापन एक विरोधाभासी महामारी बन गया है।"}]},"es":{"word":"individualismo","question":"¿Nos ha liberado el individualismo o nos ha dejado aislados?","examples":[{"en":"Individualism freed millions from suffocating traditions, yet in dissolving every obligation it also dissolved the thick relationships that made life bearable.","native":"El individualismo liberó a millones de tradiciones asfixiantes, pero al disolver toda obligación también disolvió las relaciones densas que hacían soportable la vida."},{"en":"The self-made person is a flattering fiction, for each of us arrives already indebted to ancestors, teachers, and strangers whose work sustains our own.","native":"La persona hecha a sí misma es una ficción halagadora, pues cada uno llega ya endeudado con antepasados, maestros y extraños cuyo trabajo sostiene el nuestro."},{"en":"A society of pure individuals must manufacture belonging artificially, which is why loneliness has become the paradoxical epidemic of the most liberated age.","native":"Una sociedad de individuos puros debe fabricar la pertenencia artificialmente, y por eso la soledad se ha vuelto la epidemia paradójica de la era más liberada."}]},"zh":{"word":"个人主义","question":"个人主义解放了我们，还是让我们陷入了孤立？","examples":[{"en":"Individualism freed millions from suffocating traditions, yet in dissolving every obligation it also dissolved the thick relationships that made life bearable.","native":"个人主义把千百万人从令人窒息的传统中解放出来，但在溶解一切义务的同时，也溶解了那些让生活可以忍受的深厚关系。"},{"en":"The self-made person is a flattering fiction, for each of us arrives already indebted to ancestors, teachers, and strangers whose work sustains our own.","native":"白手起家的人是一种自我奉承的虚构，因为我们每个人降临时都已欠着祖先、师长和陌生人的债——正是他们的工作支撑着我们的工作。"},{"en":"A society of pure individuals must manufacture belonging artificially, which is why loneliness has become the paradoxical epidemic of the most liberated age.","native":"一个由纯粹个人组成的社会，必须人为地制造归属感——这就是为什么孤独成了这个最解放时代的悖论式流行病。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'collectivism', 'What do societies gain and lose when the group takes priority over the individual?', '{"te":{"word":"సమూహవాదం","question":"వ్యక్తి కంటే సమూహానికి ప్రాధాన్యం ఇచ్చినప్పుడు సమాజాలు ఏమి పొందుతాయి, ఏమి కోల్పోతాయి?","examples":[{"en":"Collectivism provides belonging and shared purpose, yet it can demand conformity so complete that dissent becomes indistinguishable from betrayal.","native":"సమూహవాదం అనుబంధాన్ని, పంచుకున్న లక్ష్యాన్ని అందిస్తుంది, అయితే అంత పూర్తిగా ఏకరూపతను కోరగలదు — అసమ్మతి ద్రోహం నుండి వేరుచేయలేనంతగా."},{"en":"The group that always outranks the individual eventually discovers it has protected everyone’s belonging by destroying everything worth belonging to.","native":"ఎల్లప్పుడూ వ్యక్తి కంటే పైన నిలిచే సమూహం చివరకు ఏమి కనుగొంటుందంటే — చెందడానికి విలువైన ప్రతిదాన్ని నాశనం చేసి అందరి అనుబంధాన్ని కాపాడిందని."},{"en":"Healthy communities balance both claims: the individual owes the group loyalty, and the group owes the individual the space to remain a person.","native":"ఆరోగ్యకరమైన సమాజాలు రెండు హక్కులను సమతుల్యం చేస్తాయి: వ్యక్తి సమూహానికి నిష్ఠ పాటించాలి, సమూహం వ్యక్తికి వ్యక్తిగా ఉండే స్థలం ఇవ్వాలి."}]},"hi":{"word":"सामूहिकवाद","question":"जब समूह को व्यक्ति पर प्राथमिकता मिलती है, तो समाज क्या पाते हैं और क्या खोते हैं?","examples":[{"en":"Collectivism provides belonging and shared purpose, yet it can demand conformity so complete that dissent becomes indistinguishable from betrayal.","native":"सामूहिकवाद अपनापन और साझा उद्देश्य देता है, पर वह इतनी पूर्ण एकरूपता माँग सकता है कि असहमति और विश्वासघात में अंतर करना मुश्किल हो जाए।"},{"en":"The group that always outranks the individual eventually discovers it has protected everyone’s belonging by destroying everything worth belonging to.","native":"जो समूह हमेशा व्यक्ति पर भारी पड़ता है, वह अंततः यह पाता है कि उसने सबके अपनेपन की रक्षा तब की, जब अपनाने लायक हर चीज़ को नष्ट कर डाला।"},{"en":"Healthy communities balance both claims: the individual owes the group loyalty, and the group owes the individual the space to remain a person.","native":"स्वस्थ समुदाय दोनों दावों को संतुलित करते हैं: व्यक्ति समूह का निष्ठावान हो, और समूह व्यक्ति को इंसान बने रहने की गुंजाइश दे।"}]},"es":{"word":"colectivismo","question":"¿Qué ganan y qué pierden las sociedades cuando el grupo prima sobre el individuo?","examples":[{"en":"Collectivism provides belonging and shared purpose, yet it can demand conformity so complete that dissent becomes indistinguishable from betrayal.","native":"El colectivismo proporciona pertenencia y propósito compartido, pero puede exigir una conformidad tan completa que el disenso se vuelve indistinguible de la traición."},{"en":"The group that always outranks the individual eventually discovers it has protected everyone’s belonging by destroying everything worth belonging to.","native":"El grupo que siempre prevalece sobre el individuo acaba descubriendo que protegió la pertenencia de todos destruyendo todo aquello a lo que valía la pena pertenecer."},{"en":"Healthy communities balance both claims: the individual owes the group loyalty, and the group owes the individual the space to remain a person.","native":"Las comunidades sanas equilibran ambas exigencias: el individuo debe lealtad al grupo, y el grupo debe al individuo el espacio para seguir siendo persona."}]},"zh":{"word":"集体主义","question":"当集体优先于个人时，社会得到了什么，又失去了什么？","examples":[{"en":"Collectivism provides belonging and shared purpose, yet it can demand conformity so complete that dissent becomes indistinguishable from betrayal.","native":"集体主义给予归属感和共同目标，但它要求的顺从可能彻底到让异议与背叛无从区分。"},{"en":"The group that always outranks the individual eventually discovers it has protected everyone’s belonging by destroying everything worth belonging to.","native":"永远凌驾于个人之上的集体最终会发现：它保住了每个人的归属，却毁掉了一切值得归属的东西。"},{"en":"Healthy communities balance both claims: the individual owes the group loyalty, and the group owes the individual the space to remain a person.","native":"健康的共同体在两种诉求间取得平衡：个人对集体负有忠诚，集体则欠个人一个得以保持为“人”的空间。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'consumerism', 'Does consumerism satisfy our desires, or does it manufacture them?', '{"te":{"word":"వినియోగవాదం","question":"వినియోగవాదం మన కోరికలను తీరుస్తుందా, లేదా అవి తయారుచేస్తుందా?","examples":[{"en":"Consumerism does not merely answer our desires; it engineers new ones faster than the old can be satisfied, keeping appetite permanently ahead of fulfilment.","native":"వినియోగవాదం కేవలం మన కోరికలకు సమాధానం ఇవ్వదు; పాతవి తీరకముందే వాటి కంటే వేగంగా కొత్త కోరికలను రూపొందిస్తుంది — ఆకలిని శాశ్వతంగా తృప్తి కంటే ముందుంచుతూ."},{"en":"We buy objects to express who we are, then discover that identities purchased off a shelf fit millions of strangers exactly as well as they fit us.","native":"మనం ఎవరో వ్యక్తపరచడానికి వస్తువులు కొంటాం, ఆపై అలమారిపై కొనుగోలు చేసిన గుర్తింపులు మనలాగే కోట్లాది అపరిచితులకు కూడా సరిగ్గానే సరిపోతాయని కనుగొంటాం."},{"en":"The promise that the next purchase will finally complete us is consumerism’s oldest trick, and its enduring success reveals how restless the human heart remains.","native":"తదుపరి కొనుగోలు మనల్ని చివరకు పూర్తి చేస్తుందనే హామీ వినియోగవాదం యొక్క అతి పురాతనమైన మాయ — దాని శాశ్వత విజయం మానవ హృదయం ఎంత అశాంతంగా ఉందో వెల్లడిస్తుంది."}]},"hi":{"word":"उपभोक्तावाद","question":"क्या उपभोक्तावाद हमारी इच्छाओं को पूरा करता है, या वह उन्हें निर्मित करता है?","examples":[{"en":"Consumerism does not merely answer our desires; it engineers new ones faster than the old can be satisfied, keeping appetite permanently ahead of fulfilment.","native":"उपभोक्तावाद हमारी इच्छाओं का उत्तर देता ही नहीं; वह पुरानी इच्छाओं के पूरी होने से पहले नई इच्छाएँ तेज़ी से गढ़ता है, और भूख को हमेशा तृप्ति से आगे रखता है।"},{"en":"We buy objects to express who we are, then discover that identities purchased off a shelf fit millions of strangers exactly as well as they fit us.","native":"हम यह बताने के लिए चीज़ें खरीदते हैं कि हम कौन हैं, फिर पाते हैं कि दुकान की शेल्फ़ से खरीदी पहचान लाखों अजनबियों पर भी उतनी ही सटीक बैठती है जितनी हम पर।"},{"en":"The promise that the next purchase will finally complete us is consumerism’s oldest trick, and its enduring success reveals how restless the human heart remains.","native":"यह वादा कि अगली ख़रीद आख़िरकार हमें पूरा कर देगी, उपभोक्तावाद की सबसे पुरानी चाल है, और उसकी स्थायी सफलता बताती है कि मानव हृदय कितना बेचैन बना हुआ है।"}]},"es":{"word":"consumismo","question":"¿Satisface el consumismo nuestros deseos o los fabrica?","examples":[{"en":"Consumerism does not merely answer our desires; it engineers new ones faster than the old can be satisfied, keeping appetite permanently ahead of fulfilment.","native":"El consumismo no se limita a responder a nuestros deseos; fabrica otros nuevos más rápido de lo que se satisfacen los viejos, manteniendo el apetito siempre por delante de la saciedad."},{"en":"We buy objects to express who we are, then discover that identities purchased off a shelf fit millions of strangers exactly as well as they fit us.","native":"Compramos objetos para expresar quiénes somos y luego descubrimos que las identidades compradas en un estante les quedan a millones de extraños tan bien como a nosotros."},{"en":"The promise that the next purchase will finally complete us is consumerism’s oldest trick, and its enduring success reveals how restless the human heart remains.","native":"La promesa de que la próxima compra por fin nos completará es el truco más viejo del consumismo, y su éxito perdurable revela lo inquieto que sigue el corazón humano."}]},"zh":{"word":"消费主义","question":"消费主义是在满足我们的欲望，还是在制造欲望？","examples":[{"en":"Consumerism does not merely answer our desires; it engineers new ones faster than the old can be satisfied, keeping appetite permanently ahead of fulfilment.","native":"消费主义并不只是回应我们的欲望；它制造新欲望的速度远超旧欲望被满足的速度，让胃口永远跑在满足之前。"},{"en":"We buy objects to express who we are, then discover that identities purchased off a shelf fit millions of strangers exactly as well as they fit us.","native":"我们购买物品来表达自我，随后却发现：货架上买来的身份，穿在千百万陌生人身上，和穿在我们身上一样合身。"},{"en":"The promise that the next purchase will finally complete us is consumerism’s oldest trick, and its enduring success reveals how restless the human heart remains.","native":"“下一件商品终将使我们完整”是消费主义最古老的把戏，而它长盛不衰，恰恰揭示了人心何等躁动不安。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'materialism', 'Is materialism a philosophy of honesty about the world, or an impoverished view of it?', '{"te":{"word":"భౌతికవాదం","question":"భౌతికవాదం ప్రపంచం గురించి నిజాయితీగల తత్వమా, లేదా దాని గురించి పేలవమైన దృక్పథమా?","examples":[{"en":"Materialism rightly insists that minds are not ghosts in machines, yet struggles to explain why the machine’s workings should feel like anything from within.","native":"మనస్థితులు యంత్రాల్లోని దెయ్యాలు కావని భౌతికవాదం సరిగ్గానే పట్టుబడుతుంది, అయితే యంత్రం యొక్క పనితీరు లోపలి నుండి ఎందుకు ఏదోగా అనిపించాలి అనేది వివరించడంలో ఇబ్బంది పడుతుంది."},{"en":"A culture that believes only matter matters will measure wealth precisely and wonder endlessly why the wealthy remain so persistently unsatisfied.","native":"పదార్థం మాత్రమే ముఖ్యమని నమ్మే సంస్కృతి సంపదను ఖచ్చితంగా కొలుస్తుంది, మరియు ధనికులు ఎందుకు ఇంత నిరంతర అసంతృప్తిగా ఉంటారో అనంతంగా ఆశ్చర్యపడుతుంది."},{"en":"The materialist sees the brain where the poet sees the soul, and both are looking at the same trembling mystery with different instruments of attention.","native":"కవి ఆత్మను చూసే చోట భౌతికవాది మెదడును చూస్తాడు — ఇద్దరూ వేర్వేరు శ్రద్ధా యంత్రాలతో అదే వణికే రహస్యాన్నే చూస్తున్నారు."}]},"hi":{"word":"भौतिकवाद","question":"क्या भौतिकवाद दुनिया के बारे में ईमानदारी का दर्शन है, या उसके प्रति एक अल्प दृष्टिकोण?","examples":[{"en":"Materialism rightly insists that minds are not ghosts in machines, yet struggles to explain why the machine’s workings should feel like anything from within.","native":"भौतिकवाद ठीक ही जोर देता है कि मन मशीनों में रहने वाले भूत नहीं हैं, पर यह समझाने में संघर्ष करता है कि मशीन की कार्यप्रणाली भीतर से कुछ महसूस क्यों करती है।"},{"en":"A culture that believes only matter matters will measure wealth precisely and wonder endlessly why the wealthy remain so persistently unsatisfied.","native":"जो संस्कृति मानती है कि केवल पदार्थ ही मायने रखता है, वह धन को सटीकता से मापेगी और यह सोचती रह जाएगी कि धनी इतने लगातार असंतुष्ट क्यों रहते हैं।"},{"en":"The materialist sees the brain where the poet sees the soul, and both are looking at the same trembling mystery with different instruments of attention.","native":"जहाँ कवि आत्मा देखता है, वहाँ भौतिकवादी मस्तिष्क देखता है — और दोनों एक ही काँपते रहस्य को ध्यान के अलग-अलग उपकरणों से देख रहे हैं।"}]},"es":{"word":"materialismo","question":"¿Es el materialismo una filosofía honesta sobre el mundo o una visión empobrecida de él?","examples":[{"en":"Materialism rightly insists that minds are not ghosts in machines, yet struggles to explain why the machine’s workings should feel like anything from within.","native":"El materialismo insiste con razón en que las mentes no son fantasmas dentro de máquinas, pero le cuesta explicar por qué el funcionamiento de la máquina debería sentirse como algo desde dentro."},{"en":"A culture that believes only matter matters will measure wealth precisely and wonder endlessly why the wealthy remain so persistently unsatisfied.","native":"Una cultura que cree que solo importa la materia medirá la riqueza con precisión y se preguntará sin fin por qué los ricos siguen tan persistentemente insatisfechos."},{"en":"The materialist sees the brain where the poet sees the soul, and both are looking at the same trembling mystery with different instruments of attention.","native":"El materialista ve el cerebro donde el poeta ve el alma, y ambos contemplan el mismo misterio tembloroso con distintos instrumentos de atención."}]},"zh":{"word":"唯物主义","question":"唯物主义是对世界诚实的哲学，还是一种贫瘠的世界观？","examples":[{"en":"Materialism rightly insists that minds are not ghosts in machines, yet struggles to explain why the machine’s workings should feel like anything from within.","native":"唯物主义坚持心灵并非寄居机器中的幽灵，这没有错；但它难以解释：机器的运转为何会从内部“有所感受”。"},{"en":"A culture that believes only matter matters will measure wealth precisely and wonder endlessly why the wealthy remain so persistently unsatisfied.","native":"一个信奉“唯有物质重要”的文化，会精确地度量财富，然后没完没了地困惑：为什么富人始终如此不满足。"},{"en":"The materialist sees the brain where the poet sees the soul, and both are looking at the same trembling mystery with different instruments of attention.","native":"诗人看见灵魂的地方，唯物主义者看见大脑；二者凝视的是同一个颤抖的谜，只是所用观察的工具不同。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'minimalism', 'Is minimalism a genuine path to freedom, or another form of consumption?', '{"te":{"word":"మినిమలిజం","question":"మినిమలిజం స్వేచ్ఛకు నిజమైన మార్గమా, లేదా వినియోగం యొక్క మరో రూపమా?","examples":[{"en":"Minimalism promises freedom from possessions, yet the pursuit of owning perfectly few things can become as obsessive as collecting many.","native":"వస్తువుల నుండి స్వేచ్ఛను మినిమలిజం వాగ్దానం చేస్తుంది, అయితే పరిపూర్ణంగా కొద్ది వస్తువులను కలిగి ఉండే అన్వేషణ కూడా చాలావాటిని సేకరించడంలాగే వ్యామోహంగా మారవచ్చు."},{"en":"Choosing less is a privilege of those who could have more; the poor practise involuntary minimalism without finding it particularly liberating.","native":"తక్కువను ఎంచుకోవడం ఎక్కువ కలిగి ఉండగలిగినవారి ప్రత్యేక హక్కు; పేదలు అనిచ్ఛతో మినిమలిజం పాటిస్తారు, అది అంతగా విముక్తినిస్తుందని కనుగొకుండానే."},{"en":"The deepest minimalism is not an aesthetic of empty rooms but a discipline of emptying schedules, keeping only what genuinely deserves our hours.","native":"లోతైన మినిమలిజం ఖాళీ గదుల సౌందర్యశాస్త్రం కాదు — షెడ్యూళ్లను ఖాళీ చేసే క్రమశిక్షణ, మన గంటలను నిజంగా అర్హమైనవాటికి మాత్రమే కేటాయించడం."}]},"hi":{"word":"न्यूनतमवाद","question":"क्या न्यूनतमवाद स्वतंत्रता का कोई वास्तविक मार्ग है, या उपभोग का ही एक और रूप?","examples":[{"en":"Minimalism promises freedom from possessions, yet the pursuit of owning perfectly few things can become as obsessive as collecting many.","native":"न्यूनतमवाद सामानों से मुक्ति का वादा करता है, पर बिल्कुल कम चीज़ें रखने की खोज भी कई चीज़ें जमा करने जैसी ही धुन बन सकती है।"},{"en":"Choosing less is a privilege of those who could have more; the poor practise involuntary minimalism without finding it particularly liberating.","native":"कम चुनना उन लोगों का विशेषाधिकार है जो अधिक रख सकते हैं; ग़रीब अनैच्छिक न्यूनतमवाद का पालन करते हैं, बिना यह पाए कि वह कोई मुक्ति देता है।"},{"en":"The deepest minimalism is not an aesthetic of empty rooms but a discipline of emptying schedules, keeping only what genuinely deserves our hours.","native":"सबसे गहरा न्यूनतमवाद खाली कमरों का सौंदर्य नहीं, बल्कि कार्यक्रमों को खाली करने का अनुशासन है — केवल वही रखना जो सचमुच हमारे घंटों का हक़दार हो।"}]},"es":{"word":"minimalismo","question":"¿Es el minimalismo un camino genuino hacia la libertad u otra forma de consumo?","examples":[{"en":"Minimalism promises freedom from possessions, yet the pursuit of owning perfectly few things can become as obsessive as collecting many.","native":"El minimalismo promete libertad de las posesiones, pero perseguir poseer perfectamente pocas cosas puede volverse tan obsesivo como acumular muchas."},{"en":"Choosing less is a privilege of those who could have more; the poor practise involuntary minimalism without finding it particularly liberating.","native":"Elegir menos es un privilegio de quienes podrían tener más; los pobres practican un minimalismo involuntario sin encontrarlo particularmente liberador."},{"en":"The deepest minimalism is not an aesthetic of empty rooms but a discipline of emptying schedules, keeping only what genuinely deserves our hours.","native":"El minimalismo más profundo no es una estética de habitaciones vacías, sino la disciplina de vaciar agendas, quedándose solo con lo que merece de verdad nuestras horas."}]},"zh":{"word":"极简主义","question":"极简主义是通往自由的真路，还是消费的另一种形态？","examples":[{"en":"Minimalism promises freedom from possessions, yet the pursuit of owning perfectly few things can become as obsessive as collecting many.","native":"极简主义许诺从物欲中解脱，但对“拥有完美之少”的追求，也可能变得像囤积一样偏执。"},{"en":"Choosing less is a privilege of those who could have more; the poor practise involuntary minimalism without finding it particularly liberating.","native":"选择更少，是那些本可以拥有更多者的特权；穷人被迫践行极简，却并不觉得它带来了解脱。"},{"en":"The deepest minimalism is not an aesthetic of empty rooms but a discipline of emptying schedules, keeping only what genuinely deserves our hours.","native":"最深的极简不是空房间的美学，而是清空日程的自律——只保留真正值得我们时间的事物。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'perfectionism', 'Does perfectionism drive excellence, or does it quietly destroy it?', '{"te":{"word":"పరిపూర్ణతావాదం","question":"పరిపూర్ణతావాదం శ్రేష్ఠతను నడిపిస్తుందా, లేదా నిశ్శబ్దంగా దాన్ని నాశనం చేస్తుందా?","examples":[{"en":"Perfectionism masquerades as high standards, yet its true function is often fear: the terror of finishing something and being judged for the result.","native":"పరిపూర్ణతావాదం ఉన్నత ప్రమాణాల వేషంలో ఉంటుంది, అయితే దాని నిజమైన ధర్మం తరచుగా భయమే: ఏదో పూర్తిచేసి ఫలితం కోసం తీర్పు పడాల్సిరావచ్చనే భీతి."},{"en":"The perfectionist abandons a hundred promising beginnings rather than risk one imperfect ending, while the merely persistent finish and improve.","native":"పరిపూర్ణతావాది ఒక అసంపూర్ణ ముగింపు అనుభవించే ప్రమాదం కంటే వంద ఆశాజనక ప్రారంభాలను వదిలేస్తాడు, అయితే కేవలం పట్టుదల గలవాడు పూర్తిచేసి మెరుగుపెడతాడు."},{"en":"Excellence grows from iteration, from shipping the flawed version and revising it honestly, whereas perfectionism dies stillborn in endless preparation.","native":"శ్రేష్ఠత పునరావృతం నుండి పుడుతుంది — లోపం ఉన్న కూర్పును విడుదల చేసి నిజాయితీగా సవరించడం నుండి — అయితే పరిపూర్ణతావాదం అంతులేని తయారీలోనే మృతిచెందుతుంది."}]},"hi":{"word":"पूर्णतावाद","question":"क्या पूर्णतावाद उत्कृष्टता को प्रेरित करता है, या वह चुपचाप उसे नष्ट कर देता है?","examples":[{"en":"Perfectionism masquerades as high standards, yet its true function is often fear: the terror of finishing something and being judged for the result.","native":"पूर्णतावाद ऊँचे मानदंडों का वेश धारण करता है, पर उसका असली कार्य प्रायः भय होता है: कुछ पूरा करने और परिणाम के लिए सूने जाने की दहशत।"},{"en":"The perfectionist abandons a hundred promising beginnings rather than risk one imperfect ending, while the merely persistent finish and improve.","native":"पूर्णतावादी एक अपूर्ण अंत का जोखिम उठाने की बजाय सौ होनहार शुरुआतें छोड़ देता है, जबकि केवल दृढ़ रहने वाला पूरा करता है और सुधारता है।"},{"en":"Excellence grows from iteration, from shipping the flawed version and revising it honestly, whereas perfectionism dies stillborn in endless preparation.","native":"उत्कृष्टता पुनरावृत्ति से जन्म लेती है — दोषपूर्ण संस्करण जारी करके उसे ईमानदारी से सुधारने से — जबकि पूर्णतावाद अनंत तैयारी में ही मृत-जन्म पाता है।"}]},"es":{"word":"perfeccionismo","question":"¿Impulsa el perfeccionismo la excelencia o la destruye en silencio?","examples":[{"en":"Perfectionism masquerades as high standards, yet its true function is often fear: the terror of finishing something and being judged for the result.","native":"El perfeccionismo se disfraza de estándares altos, pero su verdadera función suele ser el miedo: el terror a terminar algo y ser juzgado por el resultado."},{"en":"The perfectionist abandons a hundred promising beginnings rather than risk one imperfect ending, while the merely persistent finish and improve.","native":"El perfeccionista abandona cien comienzos prometedores antes que arriesgar un final imperfecto, mientras que el simplemente persistente termina y mejora."},{"en":"Excellence grows from iteration, from shipping the flawed version and revising it honestly, whereas perfectionism dies stillborn in endless preparation.","native":"La excelencia nace de la iteración, de lanzar la versión imperfecta y revisarla con honestidad, mientras que el perfeccionismo muere nonato en una preparación interminable."}]},"zh":{"word":"完美主义","question":"完美主义是在驱动卓越，还是在悄悄摧毁卓越？","examples":[{"en":"Perfectionism masquerades as high standards, yet its true function is often fear: the terror of finishing something and being judged for the result.","native":"完美主义伪装成高标准，但它真正的功能往往是恐惧——害怕完成某件作品并因结果被评判。"},{"en":"The perfectionist abandons a hundred promising beginnings rather than risk one imperfect ending, while the merely persistent finish and improve.","native":"完美主义者宁可放弃一百个有希望的开端，也不愿冒险面对一个不完美的结局；而仅仅有恒心的人却能完成并改进。"},{"en":"Excellence grows from iteration, from shipping the flawed version and revising it honestly, whereas perfectionism dies stillborn in endless preparation.","native":"卓越源于迭代——发布有缺陷的版本并诚实地修改——而完美主义在无尽的准备中胎死腹中。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'pragmatism', 'Should pragmatism govern our ideals, or does it slowly replace them?', '{"te":{"word":"ప్రాయోగికవాదం","question":"ప్రాయోగికవాదం మన ఆదర్శాలను పాలించాలా, లేదా అది నెమ్మదిగా వాటి స్థానం భర్తీ చేస్తుందా?","examples":[{"en":"Pragmatism asks what works, which is a fine question for methods but a dangerous one for values, since many wrongs work wonderfully.","native":"ప్రాయోగికవాదం ఏది పనిచేస్తుందో అడుగుతుంది — పద్ధతులకు ఇది మంచి ప్రశ్న, కానీ విలువలకు ప్రమాదకరమైనది, ఎందుకంటే చాలా తప్పులు అద్భుతంగా పనిచేస్తాయి."},{"en":"The pragmatist who compromises on everything discovers too late that he has become skilled only at surrendering gracefully.","native":"ప్రతిదానిపై రాజీ పడే ప్రాయోగికవాది చాలా ఆలస్యంగా ఏమి కనుగొంటాడంటే, తాను శోభాయమానంగా లొంగిపోవడంలో మాత్రమే నిపుణుడయ్యానని."},{"en":"Yet ideals that refuse all contact with reality become decorative: admired in speeches, useless in the world where people actually suffer and decide.","native":"అయితే వాస్తవంతో సరసం పడటానికి పూర్తిగా తిరస్కరించే ఆదర్శాలు అలంకారమవుతాయి: ప్రసంగాల్లో మెచ్చుకోబడతాయి, ప్రజలు నిజంగా బాధపడి నిర్ణయించే ప్రపంచంలో నిష్ప్రయోజనం."}]},"hi":{"word":"व्यावहारिकतावाद","question":"क्या व्यावहारिकतावाद को हमारे आदर्शों पर शासन करना चाहिए, या वह धीरे-धीरे उनकी जगह ले लेता है?","examples":[{"en":"Pragmatism asks what works, which is a fine question for methods but a dangerous one for values, since many wrongs work wonderfully.","native":"व्यावहारिकतावाद पूछता है कि क्या काम करता है — तरीकों के लिए यह अच्छा सवाल है, पर मूल्यों के लिए ख़तरनाक, क्योंकि बहुत से ग़लत काम बेहतरीन ढंग से चलते हैं।"},{"en":"The pragmatist who compromises on everything discovers too late that he has become skilled only at surrendering gracefully.","native":"जो व्यावहारिकतावादी हर बात पर समझौता करता है, वह बहुत देर से यह पाता है कि वह केवल सुंदर ढंग से हार मानने में माहिर रह गया है।"},{"en":"Yet ideals that refuse all contact with reality become decorative: admired in speeches, useless in the world where people actually suffer and decide.","native":"फिर भी जो आदर्श वास्तविकता से हर संपर्क ठुकरा देते हैं, वे सजावटी बन जाते हैं: भाषणों में सराहे जाते हैं, उस दुनिया में बेकार जहाँ लोग सचमुच दुख भोगते हैं और फ़ैसले करते हैं।"}]},"es":{"word":"pragmatismo","question":"¿Debería el pragmatismo gobernar nuestros ideales, o los va reemplazando poco a poco?","examples":[{"en":"Pragmatism asks what works, which is a fine question for methods but a dangerous one for values, since many wrongs work wonderfully.","native":"El pragmatismo pregunta qué funciona, excelente pregunta para los métodos pero peligrosa para los valores, pues muchas injusticias funcionan de maravilla."},{"en":"The pragmatist who compromises on everything discovers too late that he has become skilled only at surrendering gracefully.","native":"El pragmático que transige en todo descubre demasiado tarde que solo se ha vuelto experto en rendirse con elegancia."},{"en":"Yet ideals that refuse all contact with reality become decorative: admired in speeches, useless in the world where people actually suffer and decide.","native":"Sin embargo, los ideales que rechazan todo contacto con la realidad se vuelven decorativos: admirados en los discursos, inútiles en el mundo donde la gente realmente sufre y decide."}]},"zh":{"word":"实用主义","question":"应当让实用主义支配我们的理想，还是说它正在悄然取代理想本身？","examples":[{"en":"Pragmatism asks what works, which is a fine question for methods but a dangerous one for values, since many wrongs work wonderfully.","native":"实用主义追问“什么行得通”——对方法而言这是好问题，对价值而言却很危险，因为许多错误的事情效果奇佳。"},{"en":"The pragmatist who compromises on everything discovers too late that he has become skilled only at surrendering gracefully.","native":"事事妥协的实用主义者醒悟得太晚：他已精通的，只是如何优雅地投降。"},{"en":"Yet ideals that refuse all contact with reality become decorative: admired in speeches, useless in the world where people actually suffer and decide.","native":"然而，拒绝与现实有任何接触的理想会沦为装饰品：在演说中受人赞美，在人们真正受苦与抉择的世界里毫无用处。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'idealism', 'Are idealists naive dreamers, or the only people who ever change the world?', '{"te":{"word":"ఆదర్శవాదం","question":"ఆదర్శవాదులు అమాయక కలలుగన్నేవారా, లేదా ప్రపంచాన్ని మార్చిన ఏకైక వ్యక్తులా?","examples":[{"en":"Every reform that now seems obvious began as an idealist’s folly, opposed by sensible people who explained patiently why change was impossible.","native":"ఇప్పుడు స్పష్టంగా కనిపించే ప్రతి సంస్కరణ ఒకప్పుడు ఆదర్శవాది వెర్రితనంగా మొదలైంది — మార్పు అసాధ్యమని సహనంగా వివరించిన వివేకవంతుల వ్యతిరేకత మధ్య."},{"en":"Idealism without realism produces martyrs and manifestos; realism without idealism produces managers and ledgers, and history needs the first kind.","native":"యథార్థవాదం లేని ఆదర్శవాదం త్యాగవీరులను, ప్రకటనలను ఇస్తుంది; ఆదర్శం లేని యథార్థవాదం నిర్వాహకులను, ఖాతా పుస్తకాలను ఇస్తుంది — చరిత్రకు కావాల్సింది మొదటివారే."},{"en":"The cynical dismissal of idealists is itself a luxury purchased by generations of dreamers whose impossible demands became our ordinary rights.","native":"ఆదర్శవాదుల పట్ల నిర్లిప్త తృణీకారం స్వయంచాలకంగా ఒక విలాసం — అసాధ్యమైన డిమాండ్లు మన సాధారణ హక్కులుగా మారిన తరతరాల కలలుగన్నేవారు కొనుగోలు చేసినది."}]},"hi":{"word":"आदर्शवाद","question":"क्या आदर्शवादी भोले-भाले ख़्वाब देखने वाले हैं, या वही एकमात्र लोग हैं जिन्होंने कभी दुनिया बदली?","examples":[{"en":"Every reform that now seems obvious began as an idealist’s folly, opposed by sensible people who explained patiently why change was impossible.","native":"हर सुधार जो आज स्पष्ट लगता है, कभी किसी आदर्शवादी की मूर्खता के रूप में शुरू हुआ था — उन समझदार लोगों के विरोध के बीच जिन्होंने धैर्य से समझाया था कि बदलाव असंभव है।"},{"en":"Idealism without realism produces martyrs and manifestos; realism without idealism produces managers and ledgers, and history needs the first kind.","native":"यथार्थवाद के बिना आदर्शवाद शहीद और घोषणापत्र पैदा करता है; आदर्शवाद के बिना यथार्थवाद प्रबंधक और बही-खाते — और इतिहास को पहली क़िस्म की ही ज़रूरत है।"},{"en":"The cynical dismissal of idealists is itself a luxury purchased by generations of dreamers whose impossible demands became our ordinary rights.","native":"आदर्शवादियों का निरादर स्वयं एक विलासिता है — उन सपने देखने वालों की पीढ़ियों ने ख़रीदी है जिनकी असंभव माँगें हमारे साधारण अधिकार बन गईं।"}]},"es":{"word":"idealismo","question":"¿Son los idealistas soñadores ingenuos o las únicas personas que alguna vez cambian el mundo?","examples":[{"en":"Every reform that now seems obvious began as an idealist’s folly, opposed by sensible people who explained patiently why change was impossible.","native":"Toda reforma que hoy parece obvia empezó como una locura de idealista, combatida por personas sensatas que explicaban con paciencia por qué el cambio era imposible."},{"en":"Idealism without realism produces martyrs and manifestos; realism without idealism produces managers and ledgers, and history needs the first kind.","native":"El idealismo sin realismo produce mártires y manifiestos; el realismo sin idealismo produce gestores y libros de cuentas, y la historia necesita a los primeros."},{"en":"The cynical dismissal of idealists is itself a luxury purchased by generations of dreamers whose impossible demands became our ordinary rights.","native":"El desprecio cínico hacia los idealistas es en sí un lujo comprado por generaciones de soñadores cuyas exigencias imposibles se volvieron nuestros derechos cotidianos."}]},"zh":{"word":"理想主义","question":"理想主义者是天真的梦想家，还是唯一真正改变世界的人？","examples":[{"en":"Every reform that now seems obvious began as an idealist’s folly, opposed by sensible people who explained patiently why change was impossible.","native":"每一项如今看来显而易见的改革，起初都是理想主义者的“荒唐事”，遭到明智之士的反对——他们曾耐心地解释为何变革不可能。"},{"en":"Idealism without realism produces martyrs and manifestos; realism without idealism produces managers and ledgers, and history needs the first kind.","native":"没有现实主义的理想主义产出的是殉道者与宣言；没有理想主义的现实主义产出的是经理与账簿——而历史需要的是前者。"},{"en":"The cynical dismissal of idealists is itself a luxury purchased by generations of dreamers whose impossible demands became our ordinary rights.","native":"对理想主义者犬儒式的轻蔑，本身就是一种奢侈品——由一代代梦想家买单，他们那些不可能的要求，成了我们今天寻常的权利。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'realism', 'Is realism clear-eyed wisdom about limits, or an excuse for accepting injustice?', '{"te":{"word":"యథార్థవాదం","question":"యథార్థవాదం పరిమితుల గురించి స్పష్టదృష్టి గల జ్ఞానమా, లేదా అన్యాయాన్ని అంగీకరించడానికి సాకా?","examples":[{"en":"Realism begins as respect for facts and ends, too often, as reverence for them, forgetting that today’s facts were once considered impossible dreams.","native":"యథార్థవాదం వాస్తవాల పట్ల గౌరవంగా మొదలై, చాలామాటకు వాటి పట్ల భక్తిగా ముగుస్తుంది — నేటి వాస్తవాలు ఒకప్పుడు అసాధ్యమైన కలలుగా భావించబడ్డాయని మర్చిపోతూ."},{"en":"The realist accepts the world as it is; the danger is that acceptance ripens into affection, and affection for what is becomes blindness to what could be.","native":"యథార్థవాది ప్రపంచాన్ని ఉన్నట్లుగా అంగీకరిస్తాడు; ప్రమాదం ఏమిటంటే ఆ అంగీకారం మక్కువగా పరిపక్వమవుతుంది, ఉన్నదానిపై మక్కువ ఉండగలిగే దాని పట్ల గుడ్డితనమవుతుంది."},{"en":"Sound judgment requires realist eyes and idealist feet: seeing the terrain exactly as it lies, while still walking toward the country we would prefer.","native":"దృఢమైన తీర్పుకు యథార్థవాదపు కళ్లు, ఆదర్శవాదపు పాదాలు కావాలి: భూమిని ఉన్నట్లుగానే చూస్తూ, మనం కోరుకునే దేశం వైపు నడవడం కొనసాగించడం."}]},"hi":{"word":"यथार्थवाद","question":"क्या यथार्थवाद सीमाओं के बारे में स्पष्ट-दृष्टि वाली बुद्धिमानी है, या अन्याय स्वीकार करने का बहाना?","examples":[{"en":"Realism begins as respect for facts and ends, too often, as reverence for them, forgetting that today’s facts were once considered impossible dreams.","native":"यथार्थवाद की शुरुआत तथ्यों के सम्मान से होती है और अंत प्रायः उनकी भक्ति में — यह भूलकर कि आज के तथ्य कभी असंभव सपने माने जाते थे।"},{"en":"The realist accepts the world as it is; the danger is that acceptance ripens into affection, and affection for what is becomes blindness to what could be.","native":"यथार्थवादी दुनिया को जैसी है वैसी स्वीकार करता है; ख़तरा यह है कि स्वीकृति पककर स्नेह बन जाए, और जो है उससे स्नेह, जो हो सकता है उसके प्रति अंधापन।"},{"en":"Sound judgment requires realist eyes and idealist feet: seeing the terrain exactly as it lies, while still walking toward the country we would prefer.","native":"सही निर्णय के लिए यथार्थवादी आँखें और आदर्शवादी कदम चाहिए: धरती को ठीक वैसा देखना जैसी वह पड़ी है, और फिर भी उस देश की ओर चलना जिसे हम पसंद करते हैं।"}]},"es":{"word":"realismo","question":"¿Es el realismo sabiduría lúcida sobre los límites o una excusa para aceptar la injusticia?","examples":[{"en":"Realism begins as respect for facts and ends, too often, as reverence for them, forgetting that today’s facts were once considered impossible dreams.","native":"El realismo empieza como respeto por los hechos y termina, con demasiada frecuencia, como reverencia ante ellos, olvidando que los hechos de hoy fueron sueños imposibles."},{"en":"The realist accepts the world as it is; the danger is that acceptance ripens into affection, and affection for what is becomes blindness to what could be.","native":"El realista acepta el mundo tal como es; el peligro es que la aceptación madure en cariño, y el cariño por lo que existe se vuelva ceguera ante lo que podría ser."},{"en":"Sound judgment requires realist eyes and idealist feet: seeing the terrain exactly as it lies, while still walking toward the country we would prefer.","native":"El buen juicio requiere ojos de realista y pies de idealista: ver el terreno exactamente como yace, mientras se camina hacia el país que preferiríamos."}]},"zh":{"word":"现实主义","question":"现实主义是对限度的清醒认知，还是接受不公的借口？","examples":[{"en":"Realism begins as respect for facts and ends, too often, as reverence for them, forgetting that today’s facts were once considered impossible dreams.","native":"现实主义始于对事实的尊重，却往往终于对事实的膜拜——忘记了今天的事实，曾被视为不可能的梦想。"},{"en":"The realist accepts the world as it is; the danger is that acceptance ripens into affection, and affection for what is becomes blindness to what could be.","native":"现实主义者接受世界的本来面目；危险在于，接受会熟化为偏爱，而对现状的偏爱，会让人对可能性视而不见。"},{"en":"Sound judgment requires realist eyes and idealist feet: seeing the terrain exactly as it lies, while still walking toward the country we would prefer.","native":"健全的判断需要现实主义者的眼睛和理想主义者的双脚：看清地势的真实模样，同时仍朝我们更向往的国度跋涉。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'cynicism', 'Is cynicism a sign of intelligence, or a failure of courage?', '{"te":{"word":"నిర్లిప్తవాదం","question":"నిర్లిప్తవాదం తెలివికి గుర్తా, లేదా ధైర్యం లోపించడమా?","examples":[{"en":"Cynicism flatters its holder with the sense of having seen through everything, which conveniently excuses him from the risky business of believing anything.","native":"నిర్లిప్తవాదం తన వాడుకరిని అట్టిపెడుతుంది — ప్రతిదీ చూసేసాననే భావనతో — ఏదైనా నమ్మే ప్రమాదకర పని నుండి అతనికి అనుకూలమైన విముఖిని ఇస్తూ."},{"en":"The cynic predicts disappointment and is often right, for expecting nothing from people is a reliable method of helping them deliver exactly that.","native":"నిర్లిప్తవాది నిరాశను అంచనా వేస్తాడు, తరచుగా నిజమూ అవుతుంది — ఎందుకంటే ప్రజల నుండి ఏమీ ఆశించకపోవడం వారు కచ్చితంగా అదే ఇచ్చేలా చేసే నమ్మదగిన పద్ధతి."},{"en":"Beneath most cynicism lies disappointed idealism, and the loudest sneer usually conceals the tenderest hope that was once betrayed in public.","native":"చాలామట్టుకు నిర్లిప్తవాదం అడుగున నిరాశ చెందిన ఆదర్శవాదం ఉంటుంది, మరియు అత్యంత గట్టి ఎగతాళి వెనుక సాధారణంగా బహిరంగంగా ద్రోహం చేయబడిన అతి మెరుకైన ఆశ దాగి ఉంటుంది."}]},"hi":{"word":"तिरस्कारवाद","question":"क्या तिरस्कारवाद बुद्धिमानी की निशानी है, या साहस की हार?","examples":[{"en":"Cynicism flatters its holder with the sense of having seen through everything, which conveniently excuses him from the risky business of believing anything.","native":"तिरस्कारवाद अपने धारक को चापलूसी देता है — यह भ्रम कि उसने सब भेद लिया — जो उसे कुछ भी मानने के जोखिम भरे काम से सुविधाजनक छुटकारा देता है।"},{"en":"The cynic predicts disappointment and is often right, for expecting nothing from people is a reliable method of helping them deliver exactly that.","native":"तिरस्कारवादी निराशा की भविष्यवाणी करता है और अक्सर सही भी होता है, क्योंकि लोगों से कुछ न उम्मीद करना उनसे ठीक वही दिलवाने का भरोसेमंद तरीका है।"},{"en":"Beneath most cynicism lies disappointed idealism, and the loudest sneer usually conceals the tenderest hope that was once betrayed in public.","native":"अधिकतर तिरस्कारवाद के नीचे टूटा हुआ आदर्शवाद छिपा होता है, और सबसे ऊँची हँसी के पीछे प्रायः वह सबसे कोमल आशा होती है जिसका कभी सार्वजनिक रूप से अपमान हुआ था।"}]},"es":{"word":"cinismo","question":"¿Es el cinismo una señal de inteligencia o un fracaso del coraje?","examples":[{"en":"Cynicism flatters its holder with the sense of having seen through everything, which conveniently excuses him from the risky business of believing anything.","native":"El cinismo halaga a quien lo profesa con la sensación de haberlo calado todo, lo que convenientemente lo excusa del arriesgado negocio de creer en algo."},{"en":"The cynic predicts disappointment and is often right, for expecting nothing from people is a reliable method of helping them deliver exactly that.","native":"El cínico predice decepción y a menudo acierta, pues no esperar nada de la gente es un método fiable de ayudarla a entregar exactamente eso."},{"en":"Beneath most cynicism lies disappointed idealism, and the loudest sneer usually conceals the tenderest hope that was once betrayed in public.","native":"Bajo la mayoría del cinismo yace un idealismo decepcionado, y la mueca más estridente suele ocultar la esperanza más tierna que una vez fue traicionada en público."}]},"zh":{"word":"犬儒主义","question":"犬儒是聪明的标志，还是勇气的失败？","examples":[{"en":"Cynicism flatters its holder with the sense of having seen through everything, which conveniently excuses him from the risky business of believing anything.","native":"犬儒主义者以“看透一切”的幻觉自我陶醉，这恰好让他免于从事“相信一些东西”这桩有风险的营生。"},{"en":"The cynic predicts disappointment and is often right, for expecting nothing from people is a reliable method of helping them deliver exactly that.","native":"犬儒者预言失望，而且常常言中——因为对人无所期待，恰恰是促使他们交出“无所作为”的可靠方法。"},{"en":"Beneath most cynicism lies disappointed idealism, and the loudest sneer usually conceals the tenderest hope that was once betrayed in public.","native":"多数犬儒底下埋着破灭的理想主义，而最响亮的讥诮背后，通常藏着那份曾在众目睽睽之下被背叛的最温柔的希望。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'optimism', 'Is optimism a rational stance toward the future, or a pleasant delusion?', '{"te":{"word":"ఆశావాదం","question":"ఆశావాదం భవిష్యత్తు పట్ల తార్కికమైన వైఖరా, లేదా ఆహ్లాదకరమైన భ్రమా?","examples":[{"en":"Optimism is rarely the belief that things will go well; it is the decision to act as though effort matters, which is what makes things go well.","native":"ఆశావాదం అంటే విషయాలు బాగుంటాయనే నమ్మకం అరుదుగా ఉంటుంది; శ్రమకు విలువ ఉన్నట్లు ప్రవర్తించే నిర్ణయం అది — విషయాలు బాగుండేలా చేసేది కూడా అదే."},{"en":"The optimist and the pessimist are often both wrong about the future, but the optimist enjoys the present and gathers allies while being wrong.","native":"ఆశావాది, నిరాశావాది ఇద్దరూ భవిష్యత్తు గురించి తరచుగా తప్పవుతారు, కానీ ఆశావాది తప్పవుతూనే వర్తమానాన్ని ఆస్వాదిస్తాడు, మిత్రులను చేరుస్తాడు."},{"en":"Hope is not a forecast but a discipline, and those who practise it tend to produce the evidence that justifies having practised it.","native":"ఆశ అంచనా కాదు, ఒక క్రమశిక్షణ — దాన్ని సాధన చేసేవారు, దాన్ని సాధన చేయడాన్ని సమర్థించే ఆధారాలను తామే రూపొందించుకుంటారు."}]},"hi":{"word":"आशावाद","question":"क्या आशावाद भविष्य के प्रति एक तार्किक रुख़ है, या एक सुखद भ्रम?","examples":[{"en":"Optimism is rarely the belief that things will go well; it is the decision to act as though effort matters, which is what makes things go well.","native":"आशावाद शायद ही कभी यह विश्वास होता है कि चीज़ें अच्छी होंगी; यह यह फ़ैसला होता है कि ऐसे कार्य करो मानो प्रयास मायने रखता है — और इसीलिए चीज़ें अच्छी होती हैं।"},{"en":"The optimist and the pessimist are often both wrong about the future, but the optimist enjoys the present and gathers allies while being wrong.","native":"आशावादी और निराशावादी दोनों अक्सर भविष्य के बारे में ग़लत होते हैं, पर आशावादी ग़लत होते हुए भी वर्तमान का आनंद लेता है और साथी जुटाता है।"},{"en":"Hope is not a forecast but a discipline, and those who practise it tend to produce the evidence that justifies having practised it.","native":"आशा कोई पूर्वानुमान नहीं, एक अनुशासन है — और जो इसका अभ्यास करते हैं, वे अक्सर वे सबूत पैदा कर देते हैं जो उस अभ्यास को सही ठहराते हैं।"}]},"es":{"word":"optimismo","question":"¿Es el optimismo una postura racional ante el futuro o una agradable ilusión?","examples":[{"en":"Optimism is rarely the belief that things will go well; it is the decision to act as though effort matters, which is what makes things go well.","native":"El optimismo rara vez es la creencia de que las cosas irán bien; es la decisión de actuar como si el esfuerzo importara, que es lo que hace que las cosas vayan bien."},{"en":"The optimist and the pessimist are often both wrong about the future, but the optimist enjoys the present and gathers allies while being wrong.","native":"El optimista y el pesimista suelen equivocarse ambos sobre el futuro, pero el optimista disfruta el presente y reúne aliados mientras se equivoca."},{"en":"Hope is not a forecast but a discipline, and those who practise it tend to produce the evidence that justifies having practised it.","native":"La esperanza no es un pronóstico sino una disciplina, y quienes la practican tienden a producir las pruebas que justifican haberla practicado."}]},"zh":{"word":"乐观主义","question":"乐观是面对未来的理性姿态，还是一种令人愉悦的错觉？","examples":[{"en":"Optimism is rarely the belief that things will go well; it is the decision to act as though effort matters, which is what makes things go well.","native":"乐观很少是“事情会顺利”的信念；它是“当作努力有意义那样去行动”的决定——而这恰恰让事情顺利。"},{"en":"The optimist and the pessimist are often both wrong about the future, but the optimist enjoys the present and gathers allies while being wrong.","native":"乐观者和悲观者对未来的判断常常都错，但乐观者在犯错的同时享受着当下，并聚拢同伴。"},{"en":"Hope is not a forecast but a discipline, and those who practise it tend to produce the evidence that justifies having practised it.","native":"希望不是预测，而是一种修行；践行它的人，往往会亲手造出证明这种修行值得的证据。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'pessimism', 'Does pessimism protect us from disappointment, or guarantee a darker life?', '{"te":{"word":"నిరాశావాదం","question":"నిరాశావాదం మనల్ని నిరాశ నుండి కాపాడుతుందా, లేదా మరింత చీకటి జీవితానికి హామీ ఇస్తుందా?","examples":[{"en":"Pessimism insures against disappointment by pre-paying it: the pessimist suffers every misfortune twice, once in dread and once in fact.","native":"నిరాశావాదం నిరాశను ముందే చెల్లించడం ద్వారా దానికి బీమా ఇస్తుంది: నిరాశావాది ప్రతి విపత్తును రెండుసార్లు భరిస్తాడు — ఒకసారి భయంతో, ఒకసారి వాస్తవంగా."},{"en":"A forecast of doom feels like wisdom because it can never be embarrassed by events, yet it quietly forfeits every victory that required trying.","native":"వినాశన అంచనా జ్ఞానంలా అనిపిస్తుంది ఎందుకంటే సంఘటనల ముందు అది ఎప్పటికీ సిగ్గుపడదు, అయితే ప్రయత్నం కోరిన ప్రతి విజయాన్ని అది నిశ్శబ్దంగా వదులుకుంటుంది."},{"en":"The pessimist calls himself a realist, but despair is no more accurate than hope; both are bets placed on a future no one has seen.","native":"నిరాశావాది తనను యథార్థవాది అని పిలుచుకుంటాడు, కానీ నిరాశ ఆశ కంటే ఖచ్చితమైనది కాదు — రెండూ ఎవరూ చూడని భవిష్యత్తుపై వేసిన పందాలే."}]},"hi":{"word":"निराशावाद","question":"क्या निराशावाद हमें निराशा से बचाता है, या एक और अधिक अंधेरे जीवन की गारंटी देता है?","examples":[{"en":"Pessimism insures against disappointment by pre-paying it: the pessimist suffers every misfortune twice, once in dread and once in fact.","native":"निराशावाद निराशा का पैसा पहले चुकाकर उससे बीमा करता है: निराशावादी हर विपत्ति दो बार झेलता है — एक बार आशंका में, एक बार वास्तव में।"},{"en":"A forecast of doom feels like wisdom because it can never be embarrassed by events, yet it quietly forfeits every victory that required trying.","native":"विनाश की भविष्यवाणी बुद्धिमानी जैसी लगती है क्योंकि घटनाएँ उसे कभी शर्मिंदा नहीं कर सकतीं, पर वह चुपचाप हर उस जीत को गँवा देती है जिसके लिए कोशिश ज़रूरी थी।"},{"en":"The pessimist calls himself a realist, but despair is no more accurate than hope; both are bets placed on a future no one has seen.","native":"निराशावादी खुद को यथार्थवादी कहता है, पर निराशा आशा से ज़्यादा सटीक नहीं है; दोनों उस भविष्य पर लगे दाँव हैं जिसे किसी ने नहीं देखा।"}]},"es":{"word":"pesimismo","question":"¿Nos protege el pesimismo de la decepción o garantiza una vida más oscura?","examples":[{"en":"Pessimism insures against disappointment by pre-paying it: the pessimist suffers every misfortune twice, once in dread and once in fact.","native":"El pesimismo asegura contra la decepción pagándola por adelantado: el pesimista sufre cada desgracia dos veces, una en el temor y otra en los hechos."},{"en":"A forecast of doom feels like wisdom because it can never be embarrassed by events, yet it quietly forfeits every victory that required trying.","native":"Un pronóstico de perdición parece sabiduría porque los acontecimientos jamás pueden avergonzarlo, pero renuncia en silencio a toda victoria que exigiera intentarlo."},{"en":"The pessimist calls himself a realist, but despair is no more accurate than hope; both are bets placed on a future no one has seen.","native":"El pesimista se llama realista, pero la desesperación no es más exacta que la esperanza; ambas son apuestas sobre un futuro que nadie ha visto."}]},"zh":{"word":"悲观主义","question":"悲观能保护我们免于失望，还是注定让生活更加灰暗？","examples":[{"en":"Pessimism insures against disappointment by pre-paying it: the pessimist suffers every misfortune twice, once in dread and once in fact.","native":"悲观通过预付失望来给自己上保险：悲观者把每一次不幸都经受两遍——一遍在忧惧中，一遍在现实里。"},{"en":"A forecast of doom feels like wisdom because it can never be embarrassed by events, yet it quietly forfeits every victory that required trying.","native":"预言厄运听上去像智慧，因为它永远不会被事实打脸；但它悄悄放弃了每一次需要尝试才能赢得的胜利。"},{"en":"The pessimist calls himself a realist, but despair is no more accurate than hope; both are bets placed on a future no one has seen.","native":"悲观者自称现实主义者，但绝望并不比希望更准确——两者都是押在一个无人见过的未来上的赌注。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'nihilism', 'If nothing has inherent meaning, does anything we do matter at all?', '{"te":{"word":"శూన్యవాదం","question":"దేనికీ అంతర్నిహిత అర్థం లేకపోతే, మనం చేసే దేనికైనా అసలు విలువ ఉందా?","examples":[{"en":"Nihilism reasons correctly that the universe assigns no meanings, then errs in concluding that meanings therefore cannot be assigned by us.","native":"విశ్వం అర్థాలను కేటాయించదని శూన్యవాదం సరిగ్గానే తర్కిస్తుంది, తర్వాత అర్థాలను మనం కేటాయించలేమని నిర్ధారించడంలో పొరపడుతుంది."},{"en":"The abyss that the nihilist stares into is real, but so is the choice of what to build on its edge, and building is the braver philosophy.","native":"శూన్యవాది చూస్తున్న అగాధం నిజమే, కానీ దాని అంచున ఏమి నిర్మించాలో ఎంపిక కూడా నిజమే — నిర్మించడమే ధైర్యవంతమైన తత్వం."},{"en":"Meaning was never discovered in the world like gold in a river; it was always minted by people, and nihilism merely notices that the mint is us.","native":"నదిలో బంగారంలా ప్రపంచంలో అర్థం ఎప్పుడూ కనుగొనబడలేదు; అది ఎల్లప్పుడూ మనుషులచేత ముద్రించబడేది — ముద్రణాలయం మనమే అని శూన్యవాదం కేవలం గమనిస్తుంది."}]},"hi":{"word":"शून्यवाद","question":"यदि किसी चीज़ का स्वाभाविक अर्थ नहीं है, तो हमारे किए किसी काम का कुछ मोल है या नहीं?","examples":[{"en":"Nihilism reasons correctly that the universe assigns no meanings, then errs in concluding that meanings therefore cannot be assigned by us.","native":"शून्यवाद ठीक से तर्क करता है कि ब्रह्मांड कोई अर्थ नहीं सौंपता, फिर यह निष्कर्ष निकालने में भूल करता है कि इसलिए अर्थ हम भी नहीं सौंप सकते।"},{"en":"The abyss that the nihilist stares into is real, but so is the choice of what to build on its edge, and building is the braver philosophy.","native":"जिस रसातल में शून्यवादी टकटकी लगाए देखता है, वह वास्तविक है, पर उसके किनारे क्या बनाना है, यह चुनाव भी उतना ही वास्तविक है — और बनाना ही बहादुर दर्शन है।"},{"en":"Meaning was never discovered in the world like gold in a river; it was always minted by people, and nihilism merely notices that the mint is us.","native":"अर्थ दुनिया में कभी नदी के सोने की तरह नहीं मिला; उसे हमेशा लोगों ने ही ढाला है — और शून्यवाद बस इतना देखता है कि टकसाल हम खुद हैं।"}]},"es":{"word":"nihilismo","question":"Si nada tiene un sentido inherente, ¿importa en absoluto lo que hacemos?","examples":[{"en":"Nihilism reasons correctly that the universe assigns no meanings, then errs in concluding that meanings therefore cannot be assigned by us.","native":"El nihilismo razona correctamente que el universo no asigna sentidos, y luego yerra al concluir que por eso los sentidos no pueden ser asignados por nosotros."},{"en":"The abyss that the nihilist stares into is real, but so is the choice of what to build on its edge, and building is the braver philosophy.","native":"El abismo al que mira el nihilista es real, pero también lo es la elección de qué construir a su borde, y construir es la filosofía más valiente."},{"en":"Meaning was never discovered in the world like gold in a river; it was always minted by people, and nihilism merely notices that the mint is us.","native":"El sentido nunca se descubrió en el mundo como oro en un río; siempre fue acuñado por personas, y el nihilismo solo advierte que la casa de moneda somos nosotros."}]},"zh":{"word":"虚无主义","question":"如果万物都没有内在的意义，我们所做的一切还重要吗？","examples":[{"en":"Nihilism reasons correctly that the universe assigns no meanings, then errs in concluding that meanings therefore cannot be assigned by us.","native":"虚无主义正确地论证了宇宙不指派任何意义，却错误地推论：因此意义也无法由我们来指派。"},{"en":"The abyss that the nihilist stares into is real, but so is the choice of what to build on its edge, and building is the braver philosophy.","native":"虚无主义者凝视的深渊是真实的，但在深渊边缘建造什么的选择同样真实——而建造，是更勇敢的哲学。"},{"en":"Meaning was never discovered in the world like gold in a river; it was always minted by people, and nihilism merely notices that the mint is us.","native":"意义从来不是像河里的金子那样在世界上被发现的；它一向由人铸造——虚无主义只是注意到：铸币厂就是我们自己。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'stoicism', 'Is stoicism emotional wisdom, or a denial of what makes us human?', '{"te":{"word":"స్తోయికవాదం","question":"స్తోయికవాదం భావోద్వేగ జ్ఞానమా, లేదా మనల్ని మనుషుల్ని చేసే దాన్ని ఖండనా?","examples":[{"en":"Stoicism teaches the division of the world into what we control and what we do not, and asks us to grieve only for the first, which spares us most of our grief.","native":"ప్రపంచాన్ని మన నియంత్రణలో ఉన్నవిగా, లేనివిగా విభజించమని స్తోయికవాదం నేర్పుతుంది — మొదటివాటి కోసం మాత్రమే దుఃఖించమని అడుగుతుంది, దీంతో మన దుఃఖంలో ఎక్కువ భాగం తగ్గిపోతుంది."},{"en":"Critics call the stoic cold, yet there is a difference between feeling nothing and refusing to be governed by everything one happens to feel.","native":"విమర్శకులు స్తోయికుడిని నిర్దయుడని అంటారు, అయితే ఏమీ అనుభవించకపోవడానికి, తనకు తోచిన ప్రతి భావన చేత పాలించబడడాన్ని తిరస్కరించడానికి మధ్య తేడా ఉంది."},{"en":"The danger is that serenity becomes avoidance: a person untroubled by injustice has not conquered emotion but merely chosen comfortable blindness.","native":"ప్రమాదం ఏమిటంటే ప్రశాంతత పరికావడం కావచ్చు: అన్యాయంతో కలత చెందని వ్యక్తి భావోద్వేగాన్ని జయించలేదు — కేవలం సౌకర్యవంతమైన గుడ్డితనాన్ని ఎంచుకున్నాడు."}]},"hi":{"word":"स्तोइकवाद","question":"क्या स्तोइकवाद भावनात्मक बुद्धिमानी है, या उस चीज़ का इनकार जो हमें इंसान बनाती है?","examples":[{"en":"Stoicism teaches the division of the world into what we control and what we do not, and asks us to grieve only for the first, which spares us most of our grief.","native":"स्तोइकवाद दुनिया को उसमें बाँटना सिखाता है जो हमारे नियंत्रण में है और जो नहीं — और केवल पहले के लिए शोक करने को कहता है, जिससे हमारा ज़्यादातर दुख बच जाता है।"},{"en":"Critics call the stoic cold, yet there is a difference between feeling nothing and refusing to be governed by everything one happens to feel.","native":"आलोचक स्तोइक को बेदर्द कहते हैं, पर कुछ भी महसूस न करने और जो कुछ महसूस हो रहा हो उससे शासित होने से इनकार करने में फ़र्क़ है।"},{"en":"The danger is that serenity becomes avoidance: a person untroubled by injustice has not conquered emotion but merely chosen comfortable blindness.","native":"ख़तरा यह है कि प्रसन्नता बचकर निकलना बन जाए: जो व्यक्ति अन्याय से विचलित नहीं होता, उसने भावना को जीता नहीं है, बस सुविधाजनक अंधता चुनी है।"}]},"es":{"word":"estoicismo","question":"¿Es el estoicismo sabiduría emocional o una negación de lo que nos hace humanos?","examples":[{"en":"Stoicism teaches the division of the world into what we control and what we do not, and asks us to grieve only for the first, which spares us most of our grief.","native":"El estoicismo enseña a dividir el mundo en lo que controlamos y lo que no, y nos pide afligirnos solo por lo primero, lo que nos ahorra la mayor parte de nuestro dolor."},{"en":"Critics call the stoic cold, yet there is a difference between feeling nothing and refusing to be governed by everything one happens to feel.","native":"Los críticos llaman frío al estoico, pero hay diferencia entre no sentir nada y negarse a ser gobernado por todo lo que uno resulta sentir."},{"en":"The danger is that serenity becomes avoidance: a person untroubled by injustice has not conquered emotion but merely chosen comfortable blindness.","native":"El peligro es que la serenidad se vuelva evasión: quien no se perturba ante la injusticia no ha vencido la emoción, solo ha elegido una ceguera cómoda."}]},"zh":{"word":"斯多葛主义","question":"斯多葛主义是情感上的智慧，还是对人性中珍贵部分的否认？","examples":[{"en":"Stoicism teaches the division of the world into what we control and what we do not, and asks us to grieve only for the first, which spares us most of our grief.","native":"斯多葛主义教导我们把世界分为可控与不可控两部分，并只为前者悲伤——这能让我们免于大部分的悲伤。"},{"en":"Critics call the stoic cold, yet there is a difference between feeling nothing and refusing to be governed by everything one happens to feel.","native":"批评者称斯多葛者冷漠，但“毫无感觉”与“拒绝被恰好涌起的每一种感觉所统治”之间，是有区别的。"},{"en":"The danger is that serenity becomes avoidance: a person untroubled by injustice has not conquered emotion but merely chosen comfortable blindness.","native":"危险在于宁静会沦为逃避：对不义无动于衷的人，并没有征服情感，只是选择了舒适的盲目。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'hedonism', 'Is the pursuit of pleasure a worthy goal, or a trap that diminishes life?', '{"te":{"word":"సుఖవాదం","question":"సుఖాన్వేషణ ఒక విలువైన లక్ష్యమా, లేదా జీవితాన్ని తగ్గించే ఉచ్చా?","examples":[{"en":"Pleasure pursued directly has a strange way of receding, whereas pleasure that arrives as a by-product of meaningful work tends to stay.","native":"ప్రత్యక్షంగా వెంటాడే సుఖం వింతగా దూరంగా జరుగుతుంది, అయితే అర్థవంతమైన పని యొక్క ఉపోత్పత్తిగా వచ్చే సుఖం నిలిచిపోతుంది."},{"en":"The hedonist mistakes the menu for the meal: he collects experiences designed to feel good and forgets to ask what they were good for.","native":"సుఖవాది మెనూను భోజనంగా పొరపడతాడు: బాగా అనిపించేలా రూపొందించిన అనుభవాలను సేకరిస్తాడు, అవి దేనికి మంచివో అడగడం మర్చిపోతాడు."},{"en":"A life without pleasure is bleak, but a life organized around pleasure is bleaker, for happiness demands purposes that outlast our moods.","native":"సుఖం లేని జీవితం శోచనీయం, కానీ సుఖం చుట్టూ నిర్మించిన జీవితం మరింత శోచనీయం — ఎందుకంటే ఆనందానికి మన మూడ్ల కంటే నిలిచే లక్ష్యాలు కావాలి."}]},"hi":{"word":"सुखवाद","question":"क्या सुख की खोज एक सार्थक लक्ष्य है, या जीवन को छोटा करने वाला एक जाल?","examples":[{"en":"Pleasure pursued directly has a strange way of receding, whereas pleasure that arrives as a by-product of meaningful work tends to stay.","native":"सीधे पीछा किया गया सुख अजीब तरह से दूर खिसकता जाता है, जबकि सार्थक काम के उप-उत्पाद के रूप में आया सुख टिकता है।"},{"en":"The hedonist mistakes the menu for the meal: he collects experiences designed to feel good and forgets to ask what they were good for.","native":"सुखवादी मेनू को भोजन समझ बैठता है: वह अच्छा महसूस कराने के लिए बनाए गए अनुभवों को इकट्ठा करता है, और यह पूछना भूल जाता है कि वे किस लिए अच्छे थे।"},{"en":"A life without pleasure is bleak, but a life organized around pleasure is bleaker, for happiness demands purposes that outlast our moods.","native":"सुख के बिना जीवन उदास है, पर सुख के इर्द-गिर्द बना जीवन और भी उदास, क्योंकि ख़ुशी को ऐसे उद्देश्य चाहिए जो हमारे मिज़ाज से देर तक टिकें।"}]},"es":{"word":"hedonismo","question":"¿Es la búsqueda del placer una meta digna o una trampa que empobrece la vida?","examples":[{"en":"Pleasure pursued directly has a strange way of receding, whereas pleasure that arrives as a by-product of meaningful work tends to stay.","native":"El placer perseguido directamente tiene la extraña costumbre de alejarse, mientras que el que llega como subproducto de un trabajo significativo tiende a quedarse."},{"en":"The hedonist mistakes the menu for the meal: he collects experiences designed to feel good and forgets to ask what they were good for.","native":"El hedonista confunde el menú con la comida: colecciona experiencias diseñadas para sentirse bien y olvida preguntar para qué eran buenas."},{"en":"A life without pleasure is bleak, but a life organized around pleasure is bleaker, for happiness demands purposes that outlast our moods.","native":"Una vida sin placer es sombría, pero una vida organizada en torno al placer lo es más, pues la felicidad exige propósitos que duren más que nuestros estados de ánimo."}]},"zh":{"word":"享乐主义","question":"追求快乐是值得的目标，还是让生活贬值的陷阱？","examples":[{"en":"Pleasure pursued directly has a strange way of receding, whereas pleasure that arrives as a by-product of meaningful work tends to stay.","native":"被直接追逐的快乐有一种奇特的退避方式；而作为有意义工作副产品到来的快乐，往往留得更久。"},{"en":"The hedonist mistakes the menu for the meal: he collects experiences designed to feel good and forgets to ask what they were good for.","native":"享乐主义者把菜单当成了饭菜：他收集种种为“感觉良好”而设计的体验，却忘了问它们究竟好在哪里。"},{"en":"A life without pleasure is bleak, but a life organized around pleasure is bleaker, for happiness demands purposes that outlast our moods.","native":"没有快乐的人生是凄凉的，但围绕快乐组织起来的人生更加凄凉——因为幸福需要比我们情绪更持久的目标。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'altruism', 'Is pure altruism possible, or is every kind act secretly self-interested?', '{"te":{"word":"పరోపకారం","question":"స్వచ్ఛమైన పరోపకారం సాధ్యమా, లేదా ప్రతి మంచి చర్య రహస్యంగా స్వార్థమేనా?","examples":[{"en":"That helping others feels good proves not that altruism is selfish, but that we are so built that the welfare of others can become our own.","native":"ఇతరులకు సహాయం చేయడం బాగా అనిపించడం పరోపకారం స్వార్థమే అని నిరూపించదు — ఇతరుల శ్రేయస్సు మనది కాగలదన్నట్లు మనం నిర్మించబడ్డామని చూపిస్తుంది."},{"en":"If a rescuer risks his life for a stranger, calling it selfishness because he would have felt guilty otherwise stretches the word until it explains nothing.","native":"అపరిచితుడి కోసం ప్రాణం పణంగా పెట్టిన రక్షకుడి గురించి — లేకపోతే అపరాధ భావన ఉండేది కదా అని — స్వార్థం అనడం ఆ మాటను ఏమీ వివరించలేనంతగా సాగదీయడమే."},{"en":"Perhaps the question dissolves when we see that self and other are not rivals in a zero-sum game, but neighbours whose flourishing is intertwined.","native":"స్వం, పరం పరస్పరం సున్నా-మొత్తం ఆటలో ప్రత్యర్థులు కావని, వర్ధమానం పరస్పరం ముడిపడిన పొరుగువారని చూసినప్పుడు బహుశా ఈ ప్రశ్నే కరిగిపోతుంది."}]},"hi":{"word":"परोपकार","question":"क्या शुद्ध परोपकार संभव है, या हर नेक काम अंदर ही अंदर स्वार्थी होता है?","examples":[{"en":"That helping others feels good proves not that altruism is selfish, but that we are so built that the welfare of others can become our own.","native":"दूसरों की मदद करने में अच्छा लगना यह साबित नहीं करता कि परोपकार स्वार्थी है, बल्कि यह कि हम ऐसे बने हैं कि दूसरों की भलाई हमारी अपनी बन सकती है।"},{"en":"If a rescuer risks his life for a stranger, calling it selfishness because he would have felt guilty otherwise stretches the word until it explains nothing.","native":"यदि कोई बचाने वाला अजनबी के लिए अपनी जान दाँव पर लगा दे, तो उसे स्वार्थी कहना — क्योंकि वरना उसे अपराधबोध होता — शब्द को इतना खींचना है कि वह कुछ समझा न पाए।"},{"en":"Perhaps the question dissolves when we see that self and other are not rivals in a zero-sum game, but neighbours whose flourishing is intertwined.","native":"शायद सवाल तब घुल जाता है जब हम देखते हैं कि स्वयं और दूसरा शून्य-योग के खेल में प्रतिद्वंद्वी नहीं, बल्कि ऐसे पड़ोसी हैं जिनकी बहती आपस में जुड़ी है।"}]},"es":{"word":"altruismo","question":"¿Es posible el altruismo puro, o todo acto amable es secretamente interesado?","examples":[{"en":"That helping others feels good proves not that altruism is selfish, but that we are so built that the welfare of others can become our own.","native":"Que ayudar a otros se sienta bien no prueba que el altruismo sea egoísta, sino que estamos hechos de tal modo que el bienestar ajeno puede volverse el nuestro."},{"en":"If a rescuer risks his life for a stranger, calling it selfishness because he would have felt guilty otherwise stretches the word until it explains nothing.","native":"Si un rescatista arriesga la vida por un extraño, llamarlo egoísmo porque de otro modo se sentiría culpable estira la palabra hasta que no explica nada."},{"en":"Perhaps the question dissolves when we see that self and other are not rivals in a zero-sum game, but neighbours whose flourishing is intertwined.","native":"Quizá la pregunta se disuelve al ver que el yo y el otro no son rivales en un juego de suma cero, sino vecinos cuyo florecimiento está entrelazado."}]},"zh":{"word":"利他主义","question":"纯粹的利他主义可能存在吗？还是说每一个善举背后都暗藏自利？","examples":[{"en":"That helping others feels good proves not that altruism is selfish, but that we are so built that the welfare of others can become our own.","native":"帮助他人感觉良好，并不能证明利他是自私的；它证明的是：我们天生如此——他人的福祉可以成为我们自己的福祉。"},{"en":"If a rescuer risks his life for a stranger, calling it selfishness because he would have felt guilty otherwise stretches the word until it explains nothing.","native":"若有人为陌生人冒生命危险，却说这是自私——因为否则他会内疚——那就是把这个词拉伸到无法解释任何东西的地步。"},{"en":"Perhaps the question dissolves when we see that self and other are not rivals in a zero-sum game, but neighbours whose flourishing is intertwined.","native":"当我们看清自我与他人并非零和博弈中的对手，而是兴衰交织的邻人时，这个问题或许就自行消解了。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'utilitarianism', 'Should we always choose whatever produces the greatest happiness for the greatest number?', '{"te":{"word":"ఉపయోగవాదం","question":"అత్యధిక మందికి అత్యధిక సుఖాన్నిచ్చే దాన్నే మనం ఎల్లప్పుడూ ఎంచుకోవాలా?","examples":[{"en":"Utilitarianism gives morality the clarity of arithmetic, but arithmetic cannot weigh the difference between killing one innocent and letting ten die.","native":"నీతికి ఉపయోగవాదం అంకెల స్పష్టతను ఇస్తుంది, కానీ ఒక అమాయకుడిని చంపడానికి, పది మంది చనిపోవడానికి వదిలేయడానికి మధ్య తేడాను అంకెలు తూలేవు."},{"en":"The greatest happiness principle dignifies everyone’s suffering equally, which is its glory, and it authorizes sacrificing anyone, which is its horror.","native":"అత్యధిక సుఖ సూత్రం అందరి బాధను సమానంగా గౌరవిస్తుంది — అది దాని మహిమ; ఎవరినైనా త్యాగం చేయడానికి అది అనుమతి ఇస్తుంది — అది దాని భయంకరం."},{"en":"Societies need utilitarian reasoning for policy and limits on it for persons, because people are not containers of utility to be traded like coins.","native":"విధానాలకు ఉపయోగవాదపు తర్కం కావాలి, వ్యక్తులకు దానిపై పరిమితులు కావాలి — ఎందుకంటే మనుషులు నాణేల్లా మార్చుకునే ఉపయోగం యొక్క పాత్రలు కాదు."}]},"hi":{"word":"उपयोगितावाद","question":"क्या हमें हमेशा वही चुनना चाहिए जो सबसे अधिक लोगों के लिए सबसे अधिक सुख पैदा करे?","examples":[{"en":"Utilitarianism gives morality the clarity of arithmetic, but arithmetic cannot weigh the difference between killing one innocent and letting ten die.","native":"उपयोगितावाद नैतिकता को अंकगणित जैसी स्पष्टता देता है, पर अंकगणित एक निर्दोष को मारने और दस को मरने देने के बीच का अंतर तौल नहीं सकती।"},{"en":"The greatest happiness principle dignifies everyone’s suffering equally, which is its glory, and it authorizes sacrificing anyone, which is its horror.","native":"सर्वाधिक सुख का सिद्धांत सबके दुख को समान गरिमा देता है — यही उसकी महिमा है; और वह किसी के भी त्याग को अनुमति देता है — यही उसका भय है।"},{"en":"Societies need utilitarian reasoning for policy and limits on it for persons, because people are not containers of utility to be traded like coins.","native":"समाजों को नीति के लिए उपयोगितावादी तर्क चाहिए और व्यक्तियों के लिए उस पर सीमाएँ, क्योंकि इंसान उपयोगिता के पात्र नहीं हैं जिन्हें सिक्कों की तरह बदला जा सके।"}]},"es":{"word":"utilitarismo","question":"¿Debemos elegir siempre lo que produzca la mayor felicidad para el mayor número?","examples":[{"en":"Utilitarianism gives morality the clarity of arithmetic, but arithmetic cannot weigh the difference between killing one innocent and letting ten die.","native":"El utilitarismo da a la moral la claridad de la aritmética, pero la aritmética no puede pesar la diferencia entre matar a un inocente y dejar morir a diez."},{"en":"The greatest happiness principle dignifies everyone’s suffering equally, which is its glory, and it authorizes sacrificing anyone, which is its horror.","native":"El principio de la mayor felicidad dignifica por igual el sufrimiento de todos, que es su gloria, y autoriza a sacrificar a cualquiera, que es su horror."},{"en":"Societies need utilitarian reasoning for policy and limits on it for persons, because people are not containers of utility to be traded like coins.","native":"Las sociedades necesitan razonamiento utilitario para las políticas y límites a él para las personas, porque la gente no es un recipiente de utilidad que se cambia como monedas."}]},"zh":{"word":"功利主义","question":"我们是否应当永远选择能为最大多数人带来最大幸福的选项？","examples":[{"en":"Utilitarianism gives morality the clarity of arithmetic, but arithmetic cannot weigh the difference between killing one innocent and letting ten die.","native":"功利主义赋予道德以算术般的清晰，但算术无法称量“杀死一个无辜者”与“放任十人死去”之间的差别。"},{"en":"The greatest happiness principle dignifies everyone’s suffering equally, which is its glory, and it authorizes sacrificing anyone, which is its horror.","native":"最大幸福原则平等地尊重每个人的苦难，这是它的光辉；它授权牺牲任何一个人，这是它的恐怖。"},{"en":"Societies need utilitarian reasoning for policy and limits on it for persons, because people are not containers of utility to be traded like coins.","native":"社会制定政策需要功利推理，对待个人则需要为它设限——因为人不是可以像硬币一样交换的效用容器。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'relativism', 'Are moral truths relative to culture, or do some things remain wrong everywhere?', '{"te":{"word":"సాపేక్షవాదం","question":"నైతిక సత్యాలు సంస్కృతికి సాపేక్షమా, లేదా కొన్ని విషయాలు ప్రతిచోటా తప్పేగా మిగులుతాయా?","examples":[{"en":"Relativism began as humility — the recognition that our customs are not the universe’s customs — and degenerated into the laziness of judging nothing at all.","native":"సాపేక్షవాదం వినయంగా మొదలైంది — మన ఆచారాలు విశ్వం యొక్క ఆచారాలు కావనే గుర్తింపు — తర్వాత ఏదీ తీర్పు చేయని సోమరితనంగా క్షీణించింది."},{"en":"The person who says all moral views are equal has said something he believes is true for everyone, thereby contradicting himself in a single sentence.","native":"అన్ని నైతిక అభిప్రాయాలు సమానమని చెప్పేవాడు, అందరికీ నిజమని తాను నమ్మే విషయాన్ని చెప్పాడు — ఒకే వాక్యంలో తనకు తానే విరుద్ధమై."},{"en":"Tolerance of other cultures is a virtue precisely because it is not relative: it claims to bind those who disagree with it, in every culture, always.","native":"ఇతర సంస్కృతుల పట్ల సహనం ఒక గుణం ఎందుకంటే కచ్చితంగా అది సాపేక్షం కాదు: దాన్ని ఏకీభవించనివారిని కూడా అది బంధిస్తుందని చెబుతుంది — ప్రతి సంస్కృతిలో, ఎల్లప్పుడూ."}]},"hi":{"word":"सापेक्षवाद","question":"क्या नैतिक सत्य संस्कृति के सापेक्ष होते हैं, या कुछ चीज़ें हर जगह ग़लत ही रहती हैं?","examples":[{"en":"Relativism began as humility — the recognition that our customs are not the universe’s customs — and degenerated into the laziness of judging nothing at all.","native":"सापेक्षवाद की शुरुआत विनम्रता से हुई — यह पहचान कि हमारी रीतियाँ ब्रह्मांड की रीतियाँ नहीं हैं — और फिर वह कुछ भी नापने के आलस्य में क्षीण हो गया।"},{"en":"The person who says all moral views are equal has said something he believes is true for everyone, thereby contradicting himself in a single sentence.","native":"जो कहता है कि सभी नैतिक दृष्टिकोण बराबर हैं, उसने ऐसी बात कही जिसे वह सबके लिए सत्य मानता है — और इस तरह एक ही वाक्य में खुद का खंडन कर दिया।"},{"en":"Tolerance of other cultures is a virtue precisely because it is not relative: it claims to bind those who disagree with it, in every culture, always.","native":"दूसरी संस्कृतियों के प्रति सहिष्णुता इसलिए एक गुण है क्योंकि वह सापेक्ष नहीं है: वह उन लोगों को भी बाँधने का दावा करती है जो उससे असहमत हैं — हर संस्कृति में, हमेशा।"}]},"es":{"word":"relativismo","question":"¿Son las verdades morales relativas a la cultura, o hay cosas que siguen siendo malas en todas partes?","examples":[{"en":"Relativism began as humility — the recognition that our customs are not the universe’s customs — and degenerated into the laziness of judging nothing at all.","native":"El relativismo empezó como humildad — reconocer que nuestras costumbres no son las del universo — y degeneró en la pereza de no juzgar nada en absoluto."},{"en":"The person who says all moral views are equal has said something he believes is true for everyone, thereby contradicting himself in a single sentence.","native":"Quien dice que todas las visiones morales son iguales ha dicho algo que cree verdadero para todos, contradiciéndose así en una sola frase."},{"en":"Tolerance of other cultures is a virtue precisely because it is not relative: it claims to bind those who disagree with it, in every culture, always.","native":"La tolerancia hacia otras culturas es una virtud precisamente porque no es relativa: afirma obligar a quienes discrepan de ella, en toda cultura, siempre."}]},"zh":{"word":"相对主义","question":"道德真理是相对于文化而言的，还是有些事情在任何地方都是错的？","examples":[{"en":"Relativism began as humility — the recognition that our customs are not the universe’s customs — and degenerated into the laziness of judging nothing at all.","native":"相对主义始于谦逊——承认我们的习俗并非宇宙的习俗——却堕落成了对一切都不作评判的懒惰。"},{"en":"The person who says all moral views are equal has said something he believes is true for everyone, thereby contradicting himself in a single sentence.","native":"说一切道德观点都平等的人，说出了一个他相信对所有人皆真的命题——于是用一句话就自相矛盾了。"},{"en":"Tolerance of other cultures is a virtue precisely because it is not relative: it claims to bind those who disagree with it, in every culture, always.","native":"对其他文化的宽容之所以是一种美德，恰恰因为它不是相对的：它宣称约束所有不认同它的人——在每种文化中，永远如此。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'absolutism', 'Do absolute principles protect us, or do they make mercy and judgment impossible?', '{"te":{"word":"నిరపేక్షవాదం","question":"నిరపేక్ష సూత్రాలు మనల్ని కాపాడతాయా, లేదా కరుణను, తీర్పును అసాధ్యం చేస్తాయా?","examples":[{"en":"Absolute rules spare us the exhaustion of deciding case by case, yet they force us to punish the merciful lie as harshly as the malicious one.","native":"నిరపేక్ష నియమాలు ప్రతి సంఘటనను విడివిడిగా నిర్ణయించే అలసట నుండి మనల్ని కాపాడతాయి, అయితే కరుణతో చెప్పిన అబద్ధాన్ని కూడా దురుద్దేశపు అబద్ధంలాగే కఠినంగా శిక్షించేలా చేస్తాయి."},{"en":"The absolutist fears that one exception unravels everything, forgetting that judgment exists precisely to tell principled exceptions from convenient ones.","native":"ఒక మినహాయింపు అంతటినీ విప్పేస్తుందని నిరపేక్షవాది భయపడతాడు — సూత్రబద్ధమైన మినహాయింపులను అనుకూలమైనవాటి నుండి వేరుచేయడానికే తీర్పు ఉందని మర్చిపోతూ."},{"en":"Certainty is a comfort in a shifting world, but principles too rigid to bend tend to break the people they were written to protect.","native":"మారుతున్న ప్రపంచంలో ఖచ్చితత్వం ఒక ఓర్పు, కానీ వంగలేనంత కఠినమైన సూత్రాలు తాము రక్షించడానికి రాయబడిన మనుషులనే విరిచివేస్తాయి."}]},"hi":{"word":"निरपेक्षवाद","question":"क्या निरपेक्ष सिद्धांत हमारी रक्षा करते हैं, या वे दया और विवेक को असंभव बना देते हैं?","examples":[{"en":"Absolute rules spare us the exhaustion of deciding case by case, yet they force us to punish the merciful lie as harshly as the malicious one.","native":"निरपेक्ष नियम हमें मामला-दर-मामला फ़ैसला करने की थकान से बचाते हैं, पर वे हमें दयालु झूठ को भी दुर्भावनापूर्ण झूठ जितनी कठोरता से दंडित करने पर मजबूर करते हैं।"},{"en":"The absolutist fears that one exception unravels everything, forgetting that judgment exists precisely to tell principled exceptions from convenient ones.","native":"निरपेक्षवादी डरता है कि एक अपवाद सब कुछ खोल देगा — यह भूलकर कि विवेक का अस्तित्व ही इसीलिए है कि सिद्धांतयुक्त अपवादों को सुविधाजनक अपवादों से अलग कर सके।"},{"en":"Certainty is a comfort in a shifting world, but principles too rigid to bend tend to break the people they were written to protect.","native":"बदलती दुनिया में निश्चितता एक सुखदायक चीज़ है, पर जो सिद्धांत झुकने से क़तई इनकार करते हैं, वे अक्सर उन्हीं लोगों को तोड़ देते हैं जिनकी रक्षा के लिए वे लिखे गए थे।"}]},"es":{"word":"absolutismo","question":"¿Nos protegen los principios absolutos o hacen imposibles la piedad y el juicio?","examples":[{"en":"Absolute rules spare us the exhaustion of deciding case by case, yet they force us to punish the merciful lie as harshly as the malicious one.","native":"Las reglas absolutas nos ahorran el agotamiento de decidir caso por caso, pero nos obligan a castigar la mentira piadosa tan duramente como la maliciosa."},{"en":"The absolutist fears that one exception unravels everything, forgetting that judgment exists precisely to tell principled exceptions from convenient ones.","native":"El absolutista teme que una excepción lo deshaga todo, olvidando que el juicio existe precisamente para distinguir las excepciones de principio de las convenientes."},{"en":"Certainty is a comfort in a shifting world, but principles too rigid to bend tend to break the people they were written to protect.","native":"La certeza consuela en un mundo cambiante, pero los principios demasiado rígidos para doblarse tienden a romper a las personas que fueron escritos para proteger."}]},"zh":{"word":"绝对主义","question":"绝对的原则是在保护我们，还是让怜悯与判断变得不可能？","examples":[{"en":"Absolute rules spare us the exhaustion of deciding case by case, yet they force us to punish the merciful lie as harshly as the malicious one.","native":"绝对规则使我们免于逐案裁决的疲惫，却也迫使我们把出于仁慈的谎言，惩罚得与恶意谎言一样严厉。"},{"en":"The absolutist fears that one exception unravels everything, forgetting that judgment exists precisely to tell principled exceptions from convenient ones.","native":"绝对主义者害怕一个例外会瓦解一切，却忘了判断力存在的意义，正是区分有原则的例外与图方便的例外。"},{"en":"Certainty is a comfort in a shifting world, but principles too rigid to bend tend to break the people they were written to protect.","native":"在变动不居的世界里，确定性是一种慰藉；但僵硬到不能弯曲的原则，往往会折断那些它本要保护的人。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'determinism', 'If everything is determined by prior causes, can anyone truly be responsible?', '{"te":{"word":"నియతివాదం","question":"ప్రతిదీ పూర్వ కారణాలచే నిర్ణయించబడితే, ఎవరైనా నిజంగా బాధ్యులు కాగలరా?","examples":[{"en":"Determinism may be true of atoms and still be useless for courts, which must treat people as choosers because the alternative dissolves law altogether.","native":"నియతివాదం అణువులకు నిజం కావచ్చు, అయితే న్యాయస్థానాలకు నిష్ప్రయోజనం — వాటి ప్రత్యామ్నాయం చట్టాన్నే కరిగించేస్తుంది కాబట్టి న్యాయస్థానాలు ప్రజల్ని ఎంపిక చేసేవారిగా భావించాల్సిందే."},{"en":"We excuse the criminal by pointing to his causes, yet we praise the hero without asking what caused his courage, revealing how selective our determinism is.","native":"నేరస్థుడి కారణాలను చూపిస్తూ మనం అతన్ని క్షమిస్తాం, అయితే వీరుడి ధైర్యానికి కారణం ఏమిటో అడగకుండానే అతన్ని ప్రశంసిస్తాం — మన నియతివాదం ఎంత ఎంపికగా ఉందో ఇది చూపిస్తుంది."},{"en":"Perhaps freedom is not the absence of causes but the capacity to respond to reasons, and a determined mind can still deliberate, regret, and reform.","native":"బహుశా స్వేచ్ఛ అంటే కారణాల లేమి కాదు, కారణాలకు స్పందించే సామర్థ్యం — నిర్ణయించబడిన మనసు కూడా ఆలోచించగలదు, పశ్చాత్తాపపడగలదు, సంస్కరించుకోగలదు."}]},"hi":{"word":"नियतिवाद","question":"यदि सब कुछ पूर्व कारणों से निर्धारित है, तो क्या कोई सचमुच ज़िम्मेदार हो सकता है?","examples":[{"en":"Determinism may be true of atoms and still be useless for courts, which must treat people as choosers because the alternative dissolves law altogether.","native":"नियतिवाद परमाणुओं के लिए सत्य हो सकता है, फिर भी अदालतों के लिए बेकार है — उन्हें लोगों को चुनने वाले मानना ही होगा, क्योंकि विकल्प क़ानून को ही भंग कर देता है।"},{"en":"We excuse the criminal by pointing to his causes, yet we praise the hero without asking what caused his courage, revealing how selective our determinism is.","native":"हम अपराधी को उसके कारण दिखाकर माफ़ कर देते हैं, पर नायक की प्रशंसा बिना यह पूछे करते हैं कि उसके साहस का कारण क्या था — यह दिखाता है कि हमारा नियतिवाद कितना चुनिंदा है।"},{"en":"Perhaps freedom is not the absence of causes but the capacity to respond to reasons, and a determined mind can still deliberate, regret, and reform.","native":"शायद स्वतंत्रता कारणों की अनुपस्थिति नहीं, बल्कि कारणों का उत्तर देने की क्षमता है — और निर्धारित मन भी विचार, पश्चाताप और सुधार कर सकता है।"}]},"es":{"word":"determinismo","question":"Si todo está determinado por causas anteriores, ¿puede alguien ser verdaderamente responsable?","examples":[{"en":"Determinism may be true of atoms and still be useless for courts, which must treat people as choosers because the alternative dissolves law altogether.","native":"El determinismo puede ser cierto de los átomos y aun así inútil para los tribunales, que deben tratar a las personas como electores porque la alternativa disuelve la ley por completo."},{"en":"We excuse the criminal by pointing to his causes, yet we praise the hero without asking what caused his courage, revealing how selective our determinism is.","native":"Excusamos al criminal señalando sus causas, pero alabamos al héroe sin preguntar qué causó su coraje, revelando lo selectivo que es nuestro determinismo."},{"en":"Perhaps freedom is not the absence of causes but the capacity to respond to reasons, and a determined mind can still deliberate, regret, and reform.","native":"Quizá la libertad no es la ausencia de causas sino la capacidad de responder a razones, y una mente determinada aún puede deliberar, arrepentirse y reformarse."}]},"zh":{"word":"决定论","question":"如果一切都由先前的原因决定，还有人能真正负责吗？","examples":[{"en":"Determinism may be true of atoms and still be useless for courts, which must treat people as choosers because the alternative dissolves law altogether.","native":"决定论对原子或许成立，对法庭却毫无用处——法庭必须把人们当作能做出选择的人，因为另一种可能将彻底瓦解法律。"},{"en":"We excuse the criminal by pointing to his causes, yet we praise the hero without asking what caused his courage, revealing how selective our determinism is.","native":"我们指着罪犯的“成因”为他开脱，赞美英雄时却从不追问其勇气的成因——这暴露了咱们的决定论何其选择性。"},{"en":"Perhaps freedom is not the absence of causes but the capacity to respond to reasons, and a determined mind can still deliberate, regret, and reform.","native":"或许自由并非没有原因，而是回应理由的能力；一颗被决定的心灵依然可以思忖、悔恨与改过。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'free will', 'Do we have free will, and does the answer change how we should judge others?', '{"te":{"word":"స్వేచ్ఛా సంకల్పం","question":"మనకు స్వేచ్ఛా సంకల్పం ఉందా, మరియు ఈ సమాధానం ఇతరులను ఎలా తీర్పు చేయాలో మారుస్తుందా?","examples":[{"en":"Free will may be an illusion, but it is an illusion we cannot step outside of, like a language in which every thought must be phrased.","native":"స్వేచ్ఛా సంకల్పం ఒక భ్రమ కావచ్చు, కానీ మనం దాని బయటకు అడుగుపెట్టలేని భ్రమ అది — ప్రతి ఆలోచన నిబద్ధం చేయవలసిన భాష లాంటిది."},{"en":"The person who denies free will still deliberates before crossing the road, and his hesitation is the theory quietly refuting itself in practice.","native":"స్వేచ్ఛా సంకల్పాన్ని ఖండించే వ్యక్తి కూడా రోడ్డు దాటే ముందు ఆలోచిస్తాడు — అతని ఆ సందిగ్ధతే ఆ సిద్ధాంతం ఆచరణలో నిశ్శబ్దంగా తనను తాను ఖండించుకోవడం."},{"en":"If our choices are made by causes beyond us, compassion becomes more rational and punishment more suspect, yet praise and blame refuse to vanish.","native":"మన ఎంపికలు మనకు అతీతమైన కారణాలచే తీయబడితే, కరుణ మరింత తార్కికమవుతుంది, శిక్ష మరింత అనుమానాస్పదమవుతుంది — అయినా ప్రశంసా-నిందలు అదృశ్యమవడానికి నిరాకరిస్తాయి."}]},"hi":{"word":"स्वतंत्र इच्छा","question":"क्या हमारी स्वतंत्र इच्छा है, और क्या इसका उत्तर यह बदलता है कि हमें दूसरों का फ़ैसला कैसे करना चाहिए?","examples":[{"en":"Free will may be an illusion, but it is an illusion we cannot step outside of, like a language in which every thought must be phrased.","native":"स्वतंत्र इच्छा एक भ्रम हो सकती है, पर ऐसा भ्रम जिसके बाहर हम कदम नहीं रख सकते — जैसे कोई भाषा जिसमें हर सोच को ही ढालना पड़ता है।"},{"en":"The person who denies free will still deliberates before crossing the road, and his hesitation is the theory quietly refuting itself in practice.","native":"जो व्यक्ति स्वतंत्र इच्छा से इनकार करता है, वह भी सड़क पार करने से पहले विचार करता है — और उसकी यह हिचकिचाहट व्यवहार में सिद्धांत का चुपचाप खंडन है।"},{"en":"If our choices are made by causes beyond us, compassion becomes more rational and punishment more suspect, yet praise and blame refuse to vanish.","native":"यदि हमारे चुनाव हमसे परे के कारणों से बनते हैं, तो करुणा अधिक तर्कसंगत और दंड अधिक संदिग्ध हो जाता है, फिर भी प्रशंसा और निंदा मिटने से इनकार करती हैं।"}]},"es":{"word":"libre albedrío","question":"¿Tenemos libre albedrío, y cambia la respuesta cómo deberíamos juzgar a los demás?","examples":[{"en":"Free will may be an illusion, but it is an illusion we cannot step outside of, like a language in which every thought must be phrased.","native":"El libre albedrío puede ser una ilusión, pero es una ilusión de la que no podemos salir, como una lengua en la que debe formularse todo pensamiento."},{"en":"The person who denies free will still deliberates before crossing the road, and his hesitation is the theory quietly refuting itself in practice.","native":"Quien niega el libre albedrío sigue deliberando antes de cruzar la calle, y su vacilación es la teoría refutándose en silencio a sí misma en la práctica."},{"en":"If our choices are made by causes beyond us, compassion becomes more rational and punishment more suspect, yet praise and blame refuse to vanish.","native":"Si nuestras elecciones las hacen causas ajenas a nosotros, la compasión se vuelve más racional y el castigo más sospechoso, y sin embargo la alabanza y la culpa se niegan a desaparecer."}]},"zh":{"word":"自由意志","question":"我们拥有自由意志吗？这个答案会改变我们评判他人的方式吗？","examples":[{"en":"Free will may be an illusion, but it is an illusion we cannot step outside of, like a language in which every thought must be phrased.","native":"自由意志或许是一种幻觉，但它是我们无法抽身其外的幻觉——就像一种语言，每个念头都必须用它来表达。"},{"en":"The person who denies free will still deliberates before crossing the road, and his hesitation is the theory quietly refuting itself in practice.","native":"否认自由意志的人过马路前仍会斟酌再三——而他的这份迟疑，正是那个理论在实践中悄悄自我反驳。"},{"en":"If our choices are made by causes beyond us, compassion becomes more rational and punishment more suspect, yet praise and blame refuse to vanish.","native":"如果我们的选择由超越自身的原因造就，怜悯会更合乎理性，惩罚会更显可疑——然而赞美与责备，却始终拒绝退场。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'destiny', 'Are our lives guided by destiny, or do we write the script as we live?', '{"te":{"word":"విధి","question":"మన జీవితాలు విధిచే నడపబడుతున్నాయా, లేదా మనం జీవిస్తూనే కథానికాన్ని రాసుకుంటున్నామా?","examples":[{"en":"Destiny comforts the suffering by promising design, yet it insults the striving by suggesting their choices were only rehearsals of a finished play.","native":"విధి రూపకల్పన హామీ ఇచ్చి బాధపడేవారిని ఓదారుస్తుంది, అయితే వారి ఎంపికలు పూర్తయిన నాటకం యొక్క రిహర్సళ్లే అని సూచించి శ్రమించేవారిని అవమానిస్తుంది."},{"en":"We speak of destiny only backwards: no one can point to it ahead of time, which suggests it is a story we tell about the past, not a map of the future.","native":"మనం విధి గురించి ఎల్లప్పుడూ వెనక్కి చూస్తూ మాత్రమే మాట్లాడుతాం — ముందుగా ఎవరూ దాన్ని చూపలేరు — అది గతం గురించి మనం చెప్పే కథ అని, భవిష్యత్తు మ్యాపు కాదని ఇది సూచిస్తుంది."},{"en":"A person who believes everything is written still looks both ways before crossing, and in that glance lives the whole practical refutation of fatalism.","native":"అంతా రాసిపెట్టబడిందని నమ్మే వ్యక్తి కూడా రోడ్డు దాటే ముందు రెండు వైపులా చూస్తాడు — ఆ చూపులోనే ఫాటలిజం యొక్క సంపూర్ణ ఆచరణాత్మక ఖండన ఉంది."}]},"hi":{"word":"भाग्य","question":"क्या हमारे जीवन का मार्गदर्शन भाग्य करता है, या हम जीते-जीते खुद ही पटकथा लिखते हैं?","examples":[{"en":"Destiny comforts the suffering by promising design, yet it insults the striving by suggesting their choices were only rehearsals of a finished play.","native":"भाग्य दुखियों को रचना का वादा देकर सांत्वना देता है, पर प्रयत्नशीलों का अपमान करता है — यह सुझाकर कि उनके चुनाव किसी तैयार नाटक के महज़ रिहर्सल थे।"},{"en":"We speak of destiny only backwards: no one can point to it ahead of time, which suggests it is a story we tell about the past, not a map of the future.","native":"हम भाग्य की बात केवल पीछे मुड़कर करते हैं: कोई भी उसे पहले से दिखा नहीं सकता — इससे ज़ाहिर होता है कि वह भविष्य का नक्शा नहीं, अतीत के बारे में हमारी कही कहानी है।"},{"en":"A person who believes everything is written still looks both ways before crossing, and in that glance lives the whole practical refutation of fatalism.","native":"जो मानता है कि सब लिखा हुआ है, वह भी सड़क पार करने से पहले दोनों ओर देखता है — और उसी एक नज़र में नियतिवाद का सम्पूर्ण व्यावहारिक खंडन बसा है।"}]},"es":{"word":"destino","question":"¿Nos guía el destino, o escribimos el guion a medida que vivimos?","examples":[{"en":"Destiny comforts the suffering by promising design, yet it insults the striving by suggesting their choices were only rehearsals of a finished play.","native":"El destino consuela a quien sufre prometiendo un designio, pero insulta a quien lucha al sugerir que sus decisiones eran solo ensayos de una obra ya terminada."},{"en":"We speak of destiny only backwards: no one can point to it ahead of time, which suggests it is a story we tell about the past, not a map of the future.","native":"Solo hablamos del destino mirando hacia atrás: nadie puede señalarlo de antemano, lo que sugiere que es un relato sobre el pasado, no un mapa del futuro."},{"en":"A person who believes everything is written still looks both ways before crossing, and in that glance lives the whole practical refutation of fatalism.","native":"Quien cree que todo está escrito aún mira a ambos lados antes de cruzar, y en esa mirada habita toda la refutación práctica del fatalismo."}]},"zh":{"word":"命运","question":"我们的人生由命运指引，还是我们一边活一边书写剧本？","examples":[{"en":"Destiny comforts the suffering by promising design, yet it insults the striving by suggesting their choices were only rehearsals of a finished play.","native":"命运以“冥冥之中自有安排”的许诺安慰受苦者，却以“你的选择不过是一场已完成剧本的排练”的暗示羞辱奋斗者。"},{"en":"We speak of destiny only backwards: no one can point to it ahead of time, which suggests it is a story we tell about the past, not a map of the future.","native":"我们只在回望时谈论命运——没有人能事先指出它在哪里。这说明它是我们讲给过去的故事，而不是未来的地图。"},{"en":"A person who believes everything is written still looks both ways before crossing, and in that glance lives the whole practical refutation of fatalism.","native":"一个相信一切皆已写定的人，过马路前仍会左右张望——而那一眼里，就住着对宿命论最彻底的实践驳斥。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'fate', 'Should we accept our fate, or rebel against it?', '{"te":{"word":"నియతి","question":"మన నియతిని అంగీకరించాలా, లేదా దానికి వ్యతిరేకంగా తిరుగుబాటు చేయాలా?","examples":[{"en":"Accepting fate dignifies the inevitable but poisons the changeable, teaching resignation precisely where courage was most needed.","native":"నియతిని అంగీకరించడం అనివార్యానికి గౌరవమిస్తుంది కానీ మార్చగలిగిన దాన్ని విషపూరితం చేస్తుంది — ధైర్యం అత్యంత అవసరమైన చోటే విరమణను నేర్పుతూ."},{"en":"The rebel against fate sometimes fails and always suffers, yet every freedom we now possess was won by someone who refused to accept the script.","native":"నియతికి వ్యతిరేకంగా తిరుగుబాటు చేసేవాడు కొన్నిసార్లు ఓడిపోతాడు, ఎల్లప్పుడూ బాధపడతాడు — అయితే ఇప్పుడు మనకున్న ప్రతి స్వేచ్ఛ కథానికాన్ని అంగీకరించడానికి నిరాకరించిన ఎవరో ఒకరు గెలిచినదే."},{"en":"Wisdom may lie in the old prayer: courage to fight what can be altered, serenity to bear what cannot, and judgment to tell one from the other.","native":"బహుశా జ్ఞానం ఆ పురాతన ప్రార్థనలోనే ఉంది: మార్చగలిగిన దానితో పోరాడే ధైర్యం, మార్చలేని దాన్ని భరించే ప్రశాంతత, రెండిటి మధ్య తేడా తెలుసుకునే తీర్పు."}]},"hi":{"word":"नियति","question":"क्या हमें अपनी नियति स्वीकार करनी चाहिए, या उसके विरुद्ध विद्रोह करना चाहिए?","examples":[{"en":"Accepting fate dignifies the inevitable but poisons the changeable, teaching resignation precisely where courage was most needed.","native":"नियति स्वीकार करना अनिवार्य को गरिमा देता है, पर परिवर्तनीय को विषाक्त कर देता है — ठीक वहीं वैराग्य सिखाकर जहाँ साहस की सबसे अधिक ज़रूरत थी।"},{"en":"The rebel against fate sometimes fails and always suffers, yet every freedom we now possess was won by someone who refused to accept the script.","native":"नियति के विरुद्ध विद्रोही कभी-कभी हारता है और हमेशा भुगतता है, पर जो भी स्वतंत्रता आज हमारे पास है, वह किसी ऐसे व्यक्ति ने जीती है जिसने पटकथा मानने से इनकार कर दिया था।"},{"en":"Wisdom may lie in the old prayer: courage to fight what can be altered, serenity to bear what cannot, and judgment to tell one from the other.","native":"बुद्धि शायद उसी पुरानी प्रार्थना में है: जो बदला जा सके उससे लड़ने का साहस, जो न बदला जा सके उसे सहने की प्रसन्नता, और दोनों में अंतर करने का विवेक।"}]},"es":{"word":"hado","question":"¿Debemos aceptar nuestro hado o rebelarnos contra él?","examples":[{"en":"Accepting fate dignifies the inevitable but poisons the changeable, teaching resignation precisely where courage was most needed.","native":"Aceptar el hado dignifica lo inevitable pero envenena lo cambiable, enseñando resignación precisamente donde más se necesitaba coraje."},{"en":"The rebel against fate sometimes fails and always suffers, yet every freedom we now possess was won by someone who refused to accept the script.","native":"El rebelde contra el hado a veces fracasa y siempre sufre, pero cada libertad que hoy poseemos la ganó alguien que se negó a aceptar el guion."},{"en":"Wisdom may lie in the old prayer: courage to fight what can be altered, serenity to bear what cannot, and judgment to tell one from the other.","native":"La sabiduría quizá resida en la vieja oración: coraje para luchar contra lo alterable, serenidad para soportar lo que no lo es, y juicio para distinguir lo uno de lo otro."}]},"zh":{"word":"宿命","question":"我们应当接受宿命，还是奋起反抗？","examples":[{"en":"Accepting fate dignifies the inevitable but poisons the changeable, teaching resignation precisely where courage was most needed.","native":"接受宿命让不可避免之事显得庄严，却毒害了可以改变之事——在最需要勇气的地方，教人听天由命。"},{"en":"The rebel against fate sometimes fails and always suffers, yet every freedom we now possess was won by someone who refused to accept the script.","native":"反抗宿命的人时而失败、永远受苦，但我们今天拥有的每一项自由，都是某个拒绝认命的人赢来的。"},{"en":"Wisdom may lie in the old prayer: courage to fight what can be altered, serenity to bear what cannot, and judgment to tell one from the other.","native":"智慧或许就在那句古老的祷词里：有勇气去改变可改变之事，有宁静去承受不可改变之事，并有判断力去区分二者。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'chance', 'How much of our success and failure do we owe to pure chance?', '{"te":{"word":"యాదృచ్ఛికత","question":"మన విజయాలకు, ఓటములకు మనం ఎంతమట్టుకు స్వచ్ఛమైన యాదృచ్ఛికతకే రుణపడి ఉంటాం?","examples":[{"en":"We rewrite luck as merit after the fact, for the story of deserved success flatters the winner far more than the truth of the fortunate coin toss.","native":"విజయం జరిగాక మనం అదృష్టాన్ని ప్రతిభగా తిరగరాసుకుంటాం — అర్హమైన విజయం యొక్క కథ, అదృష్టమైన నాణేం విసురు యొక్క నిజం కంటే విజేతను బాగా అట్టిపెడుతుంది."},{"en":"Chance deals the cards, but character plays the hand, and over a lifetime the quality of play matters more than any single deal.","native":"యాదృచ్ఛికత పేకముక్కలు పంచుతుంది, కానీ స్వభావం ఆట ఆడుతుంది — జీవితకాలంలో ఏ ఒక్క పంపిణీ కంటే ఆట నాణ్యతే ఎక్కువ ముఖ్యం."},{"en":"Admitting the role of luck makes winners humbler and losers gentler with themselves, which is perhaps why the confession is so rarely made.","native":"అదృష్ట పాత్రను ఒప్పుకోవడం విజేతలను వినమ్రుల్ని చేస్తుంది, ఓటమిపాలైనవారు తమ పట్ల తాము సున్నితంగా ఉండేలా చేస్తుంది — ఈ ఒప్పుకోలు ఎందుకు ఇంత అరుదుగా జరుగుతుందో బహుశా కారణం ఇదే."}]},"hi":{"word":"संयोग","question":"हम अपनी सफलता और असफलता का कितना हिस्सा शुद्ध संयोग को देते हैं?","examples":[{"en":"We rewrite luck as merit after the fact, for the story of deserved success flatters the winner far more than the truth of the fortunate coin toss.","native":"हम बाद में क़िस्मत को योग्यता बना देते हैं, क्योंकि अर्जित सफलता की कहानी विजेता को सच्चे सिक्का-उछाल से कहीं ज़्यादा ख़ुश करती है।"},{"en":"Chance deals the cards, but character plays the hand, and over a lifetime the quality of play matters more than any single deal.","native":"संयोग पत्ते बाँटता है, पर चरित्र पान चलाता है — और जीवन भर में किसी एक बँटवारे से ज़्यादा खेल की गुणवत्ता मायने रखती है।"},{"en":"Admitting the role of luck makes winners humbler and losers gentler with themselves, which is perhaps why the confession is so rarely made.","native":"क़िस्मत की भूमिका स्वीकार करना विजेताओं को विनम्र और असफलों को अपने प्रति कोमल बनाता है — शायद यही वजह है कि यह इकरार इतनी कम होता है।"}]},"es":{"word":"azar","question":"¿Cuánto de nuestro éxito y fracaso se lo debemos al puro azar?","examples":[{"en":"We rewrite luck as merit after the fact, for the story of deserved success flatters the winner far more than the truth of the fortunate coin toss.","native":"Reescribimos la suerte como mérito a posteriori, porque el relato del éxito merecido halaga al ganador mucho más que la verdad del afortunado volado."},{"en":"Chance deals the cards, but character plays the hand, and over a lifetime the quality of play matters more than any single deal.","native":"El azar reparte las cartas, pero el carácter juega la mano, y a lo largo de una vida la calidad del juego importa más que cualquier reparto."},{"en":"Admitting the role of luck makes winners humbler and losers gentler with themselves, which is perhaps why the confession is so rarely made.","native":"Admitir el papel de la suerte hace más humildes a los ganadores y más amables consigo mismos a los perdedores, y quizá por eso la confesión es tan rara."}]},"zh":{"word":"偶然","question":"我们的成败有多少应归因于纯粹的偶然？","examples":[{"en":"We rewrite luck as merit after the fact, for the story of deserved success flatters the winner far more than the truth of the fortunate coin toss.","native":"事成之后，我们总爱把运气改写成实力——因为“应得的成功”这个故事，远比“幸运的掷硬币”更让赢家受用。"},{"en":"Chance deals the cards, but character plays the hand, and over a lifetime the quality of play matters more than any single deal.","native":"偶然发牌，品格打牌；放眼一生，牌技的高低比任何一次发牌都更重要。"},{"en":"Admitting the role of luck makes winners humbler and losers gentler with themselves, which is perhaps why the confession is so rarely made.","native":"承认运气的作用，会让赢家更谦逊，让输家对自己更宽厚——也许正因如此，这种坦白才如此罕见。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'serendipity', 'Can we design our lives to invite fortunate accidents, or is serendipity beyond planning?', '{"te":{"word":"అదృష్ట సంయోగం","question":"అదృష్టవంతమైన యాదృచ్ఛికాలను ఆహ్వానించేలా మన జీవితాలను రూపొందించగలమా, లేదా అదృష్ట సంయోగం ప్రణాళికకు అతీతమా?","examples":[{"en":"Serendipity favours the prepared and the busy: chance meetings convert to fortune only for those whose minds are already stocked with questions.","native":"అదృష్ట సంయోగం సిద్ధులకు, బిజీగా ఉన్నవారికి అనుకూలం: ప్రశ్నలతో నిండిన మనసులున్నవారికే యాదృచ్ఛిక భేటీలు అదృష్టంగా మారుతాయి."},{"en":"The most important discoveries in history arrived uninvited, yet they knocked only at laboratories where someone had left the door thoughtfully open.","native":"చరిత్రలోని అతి ముఖ్యమైన ఆవిష్కరణలు ఆహ్వానం లేకుండా వచ్చాయి, అయితే ఎవరో ఆలోచనాత్మకంగా తలుపు తెరిచి ఉంచిన ప్రయోగశాలల వద్దే అవి తట్టాయి."},{"en":"A life scheduled to the minute eliminates the idle hour in which the unexpected introduction, the stray book, and the lucky error prefer to appear.","native":"నిమిషానికి షెడ్యూల్ చేసిన జీవితం ఖాళీ గంటను తొలగిస్తుంది — ఊహించని పరిచయం, పడిపోయిన పుస్తకం, అదృష్టమైన పొరపాటు కనిపించడానికి ఇష్టపడే అదే ఖాళీ గంటను."}]},"hi":{"word":"सुसंयोग","question":"क्या हम अपना जीवन इस तरह गढ़ सकते हैं कि सौभाग्यपूर्ण संयोग आमंत्रित हों, या सुसंयोग योजना से परे है?","examples":[{"en":"Serendipity favours the prepared and the busy: chance meetings convert to fortune only for those whose minds are already stocked with questions.","native":"सुसंयोग तैयार और व्यस्त लोगों का साथ देता है: बेतरतीब मुलाक़ातें केवल उन्हीं के लिए सौभाग्य बनती हैं जिनके मन पहले से सवालों से भरे हों।"},{"en":"The most important discoveries in history arrived uninvited, yet they knocked only at laboratories where someone had left the door thoughtfully open.","native":"इतिहास की सबसे बड़ी खोजें बिना बुलाए आईं, पर उन्होंने केवल उन्हीं प्रयोगशालाओं का दरवाज़ा खटखटाया जहाँ किसी ने सोच-समझकर दरवाज़ा खुला छोड़ा था।"},{"en":"A life scheduled to the minute eliminates the idle hour in which the unexpected introduction, the stray book, and the lucky error prefer to appear.","native":"मिनट-दर-मिनट बना कार्यक्रम उस खाली घंटे को मिटा देता है जिसमें अनजाना परिचय, बिखरी किताब और सौभाग्यपूर्ण भूल उतरना पसंद करते हैं।"}]},"es":{"word":"serendipia","question":"¿Podemos diseñar nuestras vidas para invitar a los accidentes afortunados, o la serendipia está más allá de toda planificación?","examples":[{"en":"Serendipity favours the prepared and the busy: chance meetings convert to fortune only for those whose minds are already stocked with questions.","native":"La serendipia favorece a los preparados y a los ocupados: los encuentros casuales solo se convierten en fortuna para quienes ya tienen la mente llena de preguntas."},{"en":"The most important discoveries in history arrived uninvited, yet they knocked only at laboratories where someone had left the door thoughtfully open.","native":"Los descubrimientos más importantes de la historia llegaron sin invitación, pero solo llamaron a laboratorios donde alguien había dejado la puerta pensativamente abierta."},{"en":"A life scheduled to the minute eliminates the idle hour in which the unexpected introduction, the stray book, and the lucky error prefer to appear.","native":"Una vida programada al minuto elimina la hora ociosa en la que prefieren aparecer la presentación inesperada, el libro extraviado y el error afortunado."}]},"zh":{"word":"意外之喜","question":"我们能否设计人生来招引幸运的偶然？还是说意外之喜根本无法规划？","examples":[{"en":"Serendipity favours the prepared and the busy: chance meetings convert to fortune only for those whose minds are already stocked with questions.","native":"意外之喜眷顾有准备的忙碌者：只有头脑中早已装满问题的人，萍水相逢才会转化为幸运。"},{"en":"The most important discoveries in history arrived uninvited, yet they knocked only at laboratories where someone had left the door thoughtfully open.","native":"历史上最重要的发现都不请自来，但它们敲开的，只是那些有人用心虚掩着门的实验室。"},{"en":"A life scheduled to the minute eliminates the idle hour in which the unexpected introduction, the stray book, and the lucky error prefer to appear.","native":"把每分钟都排满的人生，消灭了那个无所事事的钟头——而意外的引荐、偶然拾得的书、幸运的失误，偏偏最喜欢在那里现身。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'knowledge', 'Is knowledge power, or has information made that promise obsolete?', '{"te":{"word":"జ్ఞానం","question":"జ్ఞానమే అధికారమా, లేదా సమాచారం ఆ హామీని పాతబడేలా చేసిందా?","examples":[{"en":"Knowledge becomes power only when joined to judgment, for facts without interpretation are a library without a reader.","native":"తీర్పుతో కలిసినప్పుడే జ్ఞానం అధికారమవుతుంది — వివరణ లేని వాస్తవాలు పాఠకుడు లేని గ్రంథాలయమే."},{"en":"We drown in information while starving for knowledge, having confused the abundance of answers with the ability to ask the right questions.","native":"మనం సమాచారంలో మునిగిపోతూ జ్ఞానం కోసం ఆకలితో అలమటిస్తున్నాం — సమాధానాల సమృద్ధిని, సరైన ప్రశ్నలు అడగగలిగే సామర్థ్యంతో గందరగోళం చేసుకున్నాం."},{"en":"What we know doubles faster than what we understand, and the widening gap between the two may be the defining danger of the information age.","native":"మనకు తెలిసినది మనం అర్థం చేసుకున్నదాని కంటే వేగంగా రెట్టింపవుతోంది — ఈ రెండిటి మధ్య పెరుగుతున్న అంతరమే సమాచార యుగం యొక్క నిర్ణయక ప్రమాదం కావచ్చు."}]},"hi":{"word":"ज्ञान","question":"क्या ज्ञान ही शक्ति है, या सूचना ने उस वादे को अप्रचलित कर दिया है?","examples":[{"en":"Knowledge becomes power only when joined to judgment, for facts without interpretation are a library without a reader.","native":"ज्ञान तभी शक्ति बनता है जब वह विवेक से जुड़ता है, क्योंकि बिना व्याख्या के तथ्य ऐसा पुस्तकालय हैं जिसका कोई पाठक नहीं।"},{"en":"We drown in information while starving for knowledge, having confused the abundance of answers with the ability to ask the right questions.","native":"हम सूचना में डूबते हैं और ज्ञान की भूख से तड़पते हैं — उत्तरों की बहुलता को सही सवाल पूछने की क्षमता समझ बैठे हैं।"},{"en":"What we know doubles faster than what we understand, and the widening gap between the two may be the defining danger of the information age.","native":"जो हम जानते हैं, वह उससे कहीं तेज़ दुगना होता है जितना हम समझते हैं — और इन दोनों के बीच बढ़ता अंतर ही सूचना-युग का निर्णायक ख़तरा हो सकता है।"}]},"es":{"word":"conocimiento","question":"¿Es el conocimiento poder, o la información ha dejado obsoleta esa promesa?","examples":[{"en":"Knowledge becomes power only when joined to judgment, for facts without interpretation are a library without a reader.","native":"El conocimiento solo se vuelve poder cuando se une al juicio, pues los hechos sin interpretación son una biblioteca sin lector."},{"en":"We drown in information while starving for knowledge, having confused the abundance of answers with the ability to ask the right questions.","native":"Nos ahogamos en información mientras nos morimos de hambre de conocimiento, habiendo confundido la abundancia de respuestas con la capacidad de hacer las preguntas correctas."},{"en":"What we know doubles faster than what we understand, and the widening gap between the two may be the defining danger of the information age.","native":"Lo que sabemos se duplica más rápido que lo que comprendemos, y la brecha creciente entre ambos puede ser el peligro definitorio de la era de la información."}]},"zh":{"word":"知识","question":"知识就是力量，还是信息时代已让这句承诺过时？","examples":[{"en":"Knowledge becomes power only when joined to judgment, for facts without interpretation are a library without a reader.","native":"知识唯有与判断力结合才成为力量，因为没有解读的事实，不过是一座没有读者的图书馆。"},{"en":"We drown in information while starving for knowledge, having confused the abundance of answers with the ability to ask the right questions.","native":"我们溺于信息，却渴望知识——把答案的泛滥，错当成了提出正确问题的能力。"},{"en":"What we know doubles faster than what we understand, and the widening gap between the two may be the defining danger of the information age.","native":"我们所知翻番的速度，快于我们所理解的速度；两者之间日益拉开的鸿沟，或许正是信息时代最本质的危险。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'wisdom', 'Why can a person be highly educated and still lack wisdom?', '{"te":{"word":"వివేకం","question":"ఒక వ్యక్తి అత్యంత విద్యావంతుడై ఉండి కూడా ఎందుకు వివేకం లోపించవచ్చు?","examples":[{"en":"Wisdom is knowledge digested by experience and seasoned with humility, which is why it cannot be downloaded, only lived into.","native":"వివేకం అనేది అనుభవంతో జీర్ణమై, వినయంతో రుచి పొందిన జ్ఞానం — అందుకే దాన్ని డౌన్‌లోడ్ చేయలేము, జీవిస్తూ మాత్రమే పొందాలి."},{"en":"The clever person knows how to win the argument; the wise person knows whether the argument is worth winning, and what the victory will cost.","native":"తెలివైనవాడు వాదనలో గెలవడం ఎలాగో తెలుసు; వివేకవంతుడికి ఆ వాదన గెలవడానికి విలువైనదా, ఆ విజయం ధర ఎంతో తెలుసు."},{"en":"Education fills the mind with answers, while wisdom teaches the more uncomfortable art of living well among questions that have none.","native":"విద్య మనసును సమాధానాలతో నింపుతుంది, అయితే వివేకం మరింత అసౌకర్యకరమైన కళను నేర్పుతుంది — సమాధానం లేని ప్రశ్నల మధ్య బాగా జీవించే కళను."}]},"hi":{"word":"विवेक","question":"क्यों कोई व्यक्ति अत्यंत शिक्षित होकर भी विवेक से वंचित रह सकता है?","examples":[{"en":"Wisdom is knowledge digested by experience and seasoned with humility, which is why it cannot be downloaded, only lived into.","native":"विवेक वह ज्ञान है जो अनुभव में पचा हो और विनम्रता से सना हो — इसीलिए उसे डाउनलोड नहीं किया जा सकता, केवल जीकर पाया जा सकता है।"},{"en":"The clever person knows how to win the argument; the wise person knows whether the argument is worth winning, and what the victory will cost.","native":"चतुर व्यक्ति जानता है कि बहस कैसे जीती जाए; विवेकी जानता है कि बहस जीतने लायक़ है या नहीं, और उस जीत की कीमत क्या होगी।"},{"en":"Education fills the mind with answers, while wisdom teaches the more uncomfortable art of living well among questions that have none.","native":"शिक्षा मन को उत्तरों से भर देती है, जबकि विवेक उस असहज कला को सिखाता है — उन सवालों के बीच अच्छे से जीने की कला जिनका कोई उत्तर नहीं।"}]},"es":{"word":"sabiduría","question":"¿Por qué puede una persona ser muy culta y carecer aun así de sabiduría?","examples":[{"en":"Wisdom is knowledge digested by experience and seasoned with humility, which is why it cannot be downloaded, only lived into.","native":"La sabiduría es conocimiento digerido por la experiencia y sazonado con humildad, y por eso no puede descargarse: solo se alcanza viviendo."},{"en":"The clever person knows how to win the argument; the wise person knows whether the argument is worth winning, and what the victory will cost.","native":"La persona astuta sabe cómo ganar la discusión; la sabia sabe si la discusión merece ganarse y cuánto costará la victoria."},{"en":"Education fills the mind with answers, while wisdom teaches the more uncomfortable art of living well among questions that have none.","native":"La educación llena la mente de respuestas, mientras que la sabiduría enseña el arte más incómodo de vivir bien entre preguntas que no las tienen."}]},"zh":{"word":"智慧","question":"为什么一个人可以受过高等教育，却仍然缺乏智慧？","examples":[{"en":"Wisdom is knowledge digested by experience and seasoned with humility, which is why it cannot be downloaded, only lived into.","native":"智慧是被经验消化、经谦逊调味的知识——所以它无法下载，只能在活过的岁月里慢慢长成。"},{"en":"The clever person knows how to win the argument; the wise person knows whether the argument is worth winning, and what the victory will cost.","native":"聪明的人知道如何赢得争论；智慧的人知道这场争论值不值得赢，以及胜利要付出什么代价。"},{"en":"Education fills the mind with answers, while wisdom teaches the more uncomfortable art of living well among questions that have none.","native":"教育用答案填满头脑，智慧则教一门更不安的技艺：在没有答案的问题之间，好好地生活。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'ignorance', 'Is ignorance bliss, or is it always a liability?', '{"te":{"word":"అజ్ఞానం","question":"అజ్ఞానం ఆనందమా, లేదా ఎల్లప్పుడూ ఒక అపీచా?","examples":[{"en":"Ignorance can be bliss only where nothing is at stake, and the modern world arranges for almost everything to be at stake.","native":"పందం ఏమీ లేని చోట మాత్రమే అజ్ఞానం ఆనందం కాగలదు — ఆధునిక ప్రపంచం దాదాపు ప్రతిదానిపై పందం ఉండేలా ఏర్పాటు చేసింది."},{"en":"The most dangerous ignorance is not knowing what we do not know, for the confident fool votes, invests, and lectures with equal assurance.","native":"అత్యంత ప్రమాదకరమైన అజ్ఞానం మనకు ఏమి తెలియదో తెలియకపోవడమే — నమ్మకంతో ఉన్న మూర్ఖుడు ఓటు వేస్తాడు, పెట్టుబడి పెడతాడు, ప్రవచనాలు ఇస్తాడు — అంతే ధైర్యంతో."},{"en":"Admitting ignorance is the first step of every discipline that has ever advanced, which is why ''I do not know'' is the most honest sentence in scholarship.","native":"అజ్ఞానాన్ని ఒప్పుకోవడం ఎప్పుడైనా ముందుకు సాగిన ప్రతి శాస్త్రం యొక్క మొదటి అడుగు — ''నాకు తెలియదు'' అనే వాక్యం పండిత్యంలోని అత్యంత నిజాయితీగల వాక్యం అవడానికి కారణం ఇదే."}]},"hi":{"word":"अज्ञान","question":"क्या अज्ञान आनंद है, या वह हमेशा एक बोझ है?","examples":[{"en":"Ignorance can be bliss only where nothing is at stake, and the modern world arranges for almost everything to be at stake.","native":"अज्ञान तभी आनंद हो सकता है जब कुछ दाँव पर न हो — और आधुनिक दुनिया ने इसका इंतज़ाम कर दिया है कि लगभग हर चीज़ दाँव पर हो।"},{"en":"The most dangerous ignorance is not knowing what we do not know, for the confident fool votes, invests, and lectures with equal assurance.","native":"सबसे ख़तरनाक अज्ञान यह न जानना है कि हम क्या नहीं जानते, क्योंकि आत्मविश्वासी मूर्ख उतने ही भरोसे से वोट डालता है, निवेश करता है और उपदेश देता है।"},{"en":"Admitting ignorance is the first step of every discipline that has ever advanced, which is why ''I do not know'' is the most honest sentence in scholarship.","native":"अज्ञान स्वीकारना हर उस शास्त्र का पहला कदम है जो कभी आगे बढ़ा — इसीलिए ''मैं नहीं जानता'' विद्वता का सबसे ईमानदार वाक्य है।"}]},"es":{"word":"ignorancia","question":"¿Es la ignorancia una bendición o siempre una desventaja?","examples":[{"en":"Ignorance can be bliss only where nothing is at stake, and the modern world arranges for almost everything to be at stake.","native":"La ignorancia solo puede ser dicha donde nada está en juego, y el mundo moderno se encarga de que casi todo esté en juego."},{"en":"The most dangerous ignorance is not knowing what we do not know, for the confident fool votes, invests, and lectures with equal assurance.","native":"La ignorancia más peligrosa es no saber lo que no sabemos, pues el necio confiado vota, invierte y da conferencias con idéntica seguridad."},{"en":"Admitting ignorance is the first step of every discipline that has ever advanced, which is why ''I do not know'' is the most honest sentence in scholarship.","native":"Admitir la ignorancia es el primer paso de toda disciplina que ha avanzado, y por eso ''no lo sé'' es la frase más honesta de la erudición."}]},"zh":{"word":"无知","question":"无知是福，还是永远是一种负累？","examples":[{"en":"Ignorance can be bliss only where nothing is at stake, and the modern world arranges for almost everything to be at stake.","native":"只有在毫无利害攸关之处，无知才可能是福；而现代世界的安排，是让几乎一切都利害攸关。"},{"en":"The most dangerous ignorance is not knowing what we do not know, for the confident fool votes, invests, and lectures with equal assurance.","native":"最危险的无知，是不知道自己不知道——因为自信的蠢人投票、投资、讲学，都带着同等的笃定。"},{"en":"Admitting ignorance is the first step of every discipline that has ever advanced, which is why ''I do not know'' is the most honest sentence in scholarship.","native":"承认无知，是每一门曾有进步的学科迈出的第一步——所以“我不知道”是治学中最诚实的一句话。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'doubt', 'Is doubt a weakness to overcome, or the foundation of all inquiry?', '{"te":{"word":"సందేహం","question":"సందేహం అధిగమించవలసిన బలహీనతా, లేదా ప్రతి అన్వేషణకూ పునాదియా?","examples":[{"en":"Doubt is the immune system of the mind: it attacks foreign nonsense, and its disorders — credulity and cynicism — are equally fatal to thought.","native":"సందేహం మనస్సు యొక్క రోగనిరోధక వ్యవస్థ: అది బయటి అబద్ధాలను దాడి చేస్తుంది — దాని రుగ్మతలు, మూఢనమ్మకం, నిర్లిప్తత — ఆలోచనకు సమానంగా ప్రాణాంతకం."},{"en":"Descartes doubted everything and found one thing standing: the doubter. All philosophy since has lived in the room he cleared.","native":"డెకార్ట్ ప్రతిదాన్ని సందేహించి ఒకటి నిలిచిపోవడం కనుగొన్నాడు: సందేహించేవాడు. అతడు శుభ్రం చేసిన గదిలోనే అప్పటినుండి తత్వశాస్త్రం అంతా నివసిస్తోంది."},{"en":"A faith that has never been doubted is merely an inheritance unopened; examined doubt is the only honest doorway to conviction.","native":"ఎప్పుడూ సందేహించబడని విశ్వాసం తెరవని వారసత్వమే; పరీక్షించిన సందేహమే దృఢవిశ్వాసానికి ఏకైక నిజాయితీగల ద్వారం."}]},"hi":{"word":"संदेह","question":"क्या संदेह कोई जीतने वाली कमज़ोरी है, या हर जिज्ञासा की नींव?","examples":[{"en":"Doubt is the immune system of the mind: it attacks foreign nonsense, and its disorders — credulity and cynicism — are equally fatal to thought.","native":"संदेह मन की प्रतिरक्षा प्रणाली है: वह बाहरी बकवास पर हमला करता है — और उसके विकार, अंधविश्वास और तिरस्कारवाद, सोच के लिए समान रूप से घातक हैं।"},{"en":"Descartes doubted everything and found one thing standing: the doubter. All philosophy since has lived in the room he cleared.","native":"देकार्त ने सब कुछ संदेह किया और एक चीज़ को खड़ा पाया: संदेह करने वाले को। तब से का सारा दर्शन उसी कमरे में रहता है जिसे उसने खाली किया था।"},{"en":"A faith that has never been doubted is merely an inheritance unopened; examined doubt is the only honest doorway to conviction.","native":"जो आस्था कभी संदेह से नहीं गुज़री, वह महज़ खोली न गई विरासत है; परखा हुआ संदेह ही दृढ़ विश्वास का एकमात्र ईमानदार द्वार है।"}]},"es":{"word":"duda","question":"¿Es la duda una debilidad que superar o el fundamento de toda indagación?","examples":[{"en":"Doubt is the immune system of the mind: it attacks foreign nonsense, and its disorders — credulity and cynicism — are equally fatal to thought.","native":"La duda es el sistema inmunitario de la mente: ataca el sinsentido foráneo, y sus trastornos — la credulidad y el cinismo — son igualmente fatales para el pensamiento."},{"en":"Descartes doubted everything and found one thing standing: the doubter. All philosophy since has lived in the room he cleared.","native":"Descartes lo dudó todo y halló una cosa en pie: el que duda. Toda la filosofía posterior ha vivido en la habitación que él despejó."},{"en":"A faith that has never been doubted is merely an inheritance unopened; examined doubt is the only honest doorway to conviction.","native":"Una fe nunca dudada es una herencia sin abrir; la duda examinada es la única puerta honesta hacia la convicción."}]},"zh":{"word":"怀疑","question":"怀疑是需要克服的弱点，还是一切探究的根基？","examples":[{"en":"Doubt is the immune system of the mind: it attacks foreign nonsense, and its disorders — credulity and cynicism — are equally fatal to thought.","native":"怀疑是心灵的免疫系统：它攻击外来的谬论；而它的两种失调——轻信与犬儒——对思想同样致命。"},{"en":"Descartes doubted everything and found one thing standing: the doubter. All philosophy since has lived in the room he cleared.","native":"笛卡尔怀疑一切，却发现有一样东西屹立不倒：怀疑者本人。此后的全部哲学，都住在他清空的那间屋子里。"},{"en":"A faith that has never been doubted is merely an inheritance unopened; examined doubt is the only honest doorway to conviction.","native":"从未被怀疑过的信仰，不过是一份未曾拆封的遗产；经过检验的怀疑，才是通往确信唯一诚实的门。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'certainty', 'Why does certainty feel so good, and why is it so often wrong?', '{"te":{"word":"ఖచ్చితత్వం","question":"ఖచ్చితత్వం ఎందుకు అంత బాగా అనిపిస్తుంది, మరియు అది ఎందుకు ఇంత తరచుగా తప్పవుతుంది?","examples":[{"en":"Certainty is the mind’s anaesthetic: it relieves the pain of not knowing, and like all anaesthesia it should be administered with caution.","native":"ఖచ్చితత్వం మనస్సు యొక్క మత్తుమందు: తెలియని బాధను తగ్గిస్తుంది — ప్రతి మత్తుమందులాగే జాగ్రత్తగా ఇవ్వాల్సినదే."},{"en":"The certain man is wrong with confidence, which is more dangerous than being wrong with hesitation, for hesitation at least keeps listening.","native":"ఖచ్చితత్వం గలవాడు నమ్మకంతో తప్పవుతాడు — ఇది సందిగ్ధంగా తప్పవడం కంటే ప్రమాదకరం, ఎందుకంటే సందిగ్ధత అయినా వింటూనే ఉంటుంది."},{"en":"History’s worst harms were rarely committed by doubters; they required believers so certain that the suffering of others became an acceptable price.","native":"చరిత్రలోని అత్యంత భయంకరమైన హానులు అరుదుగా సందేహవాదులచే జరిగాయి — ఇతరుల బాధను అంగీకరించదగిన ధరగా మార్చేంత ఖచ్చితంగా నమ్మేవారు అవి కోరుకున్నాయి."}]},"hi":{"word":"निश्चितता","question":"निश्चितता इतनी अच्छी क्यों महसूस होती है, और वह इतनी बार ग़लत क्यों निकलती है?","examples":[{"en":"Certainty is the mind’s anaesthetic: it relieves the pain of not knowing, and like all anaesthesia it should be administered with caution.","native":"निश्चितता मन की बेहोशी की दवा है: वह न जानने के दर्द को मिटा देती है — और हर ऐसी दवा की तरह उसे सावधानी से देना चाहिए।"},{"en":"The certain man is wrong with confidence, which is more dangerous than being wrong with hesitation, for hesitation at least keeps listening.","native":"निश्चित व्यक्ति भरोसे के साथ ग़लत होता है, जो हिचकिचाहट के साथ ग़लत होने से ज़्यादा ख़तरनाक है, क्योंकि हिचकिचाहट कम से कम सुनती रहती है।"},{"en":"History’s worst harms were rarely committed by doubters; they required believers so certain that the suffering of others became an acceptable price.","native":"इतिहास के सबसे बड़े नुकसान शायद ही कभी संदेह करने वालों ने किए; उनके लिए ऐसे विश्वासी चाहिए थे जो इतने निश्चित हों कि दूसरों का दर्द एक मान्य कीमत बन जाए।"}]},"es":{"word":"certeza","question":"¿Por qué se siente tan bien la certeza, y por qué tan a menudo está equivocada?","examples":[{"en":"Certainty is the mind’s anaesthetic: it relieves the pain of not knowing, and like all anaesthesia it should be administered with caution.","native":"La certeza es el anestésico de la mente: alivia el dolor de no saber, y como toda anestesia debería administrarse con cautela."},{"en":"The certain man is wrong with confidence, which is more dangerous than being wrong with hesitation, for hesitation at least keeps listening.","native":"El hombre certero se equivoca con confianza, lo cual es más peligroso que equivocarse con vacilación, porque la vacilación al menos sigue escuchando."},{"en":"History’s worst harms were rarely committed by doubters; they required believers so certain that the suffering of others became an acceptable price.","native":"Los peores daños de la historia rara vez los cometieron los que dudan; requirieron creyentes tan ciertos que el sufrimiento ajeno se volvió un precio aceptable."}]},"zh":{"word":"确定性","question":"确定性为何让人感觉如此美妙，又为何如此经常地出错？","examples":[{"en":"Certainty is the mind’s anaesthetic: it relieves the pain of not knowing, and like all anaesthesia it should be administered with caution.","native":"确定性是心灵的麻醉剂：它缓解“不知道”的痛苦；而像一切麻醉剂一样，它应当谨慎施用。"},{"en":"The certain man is wrong with confidence, which is more dangerous than being wrong with hesitation, for hesitation at least keeps listening.","native":"笃定的人带着自信犯错，这比带着迟疑犯错更危险——因为迟疑至少还在继续倾听。"},{"en":"History’s worst harms were rarely committed by doubters; they required believers so certain that the suffering of others became an acceptable price.","native":"历史上最严重的伤害，很少出自怀疑者之手；它们需要笃定到如此地步的信者：他人的痛苦，成了可以接受的代价。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'belief', 'Are our beliefs chosen, or do they simply happen to us?', '{"te":{"word":"నమ్మకం","question":"మన నమ్మకాలు మనం ఎంచుకున్నవా, లేదా అవి కేవలం మనకు జరిగిపోయేవేనా?","examples":[{"en":"We do not choose beliefs as we choose clothes; we find ourselves believing, and at best we choose which beliefs to examine and which to feed.","native":"దుస్తులు ఎంచుకున్నట్లు మనం నమ్మకాలు ఎంచుకోము; మనం నమ్ముతూ ఉన్నామని కనుగొంటాం — మనం చేయగలిగినదెంతయినా ఏ నమ్మకాలను పరీక్షించాలో, ఏవాటిని పెంచాలో ఎంచుకోవడమే."},{"en":"A belief held because it is useful is furniture; a belief held because it is true is a commitment, and the difference shows only under pressure.","native":"ఉపయోగమైనది కాబట్టి పట్టుకున్న నమ్మకం ఫర్నిచరు; నిజమైనది కాబట్టి పట్టుకున్న నమ్మకం నిబద్ధత — ఒత్తిడి క్రింద మాత్రమే తేడా కనిపిస్తుంది."},{"en":"People defend their beliefs like property because beliefs are load-bearing: remove the wrong one carelessly and a whole worldview can collapse.","native":"ప్రజలు తమ నమ్మకాలను ఆస్తిలా కాపాడతారు ఎందుకంటే నమ్మకాలు భారం మోపేవి: తప్పు దాన్ని నిర్జాగ్రత్తగా తొలగిస్తే మొత్తం ప్రపంచ వీక్షణే కూలిపోవచ్చు."}]},"hi":{"word":"विश्वास","question":"क्या हमारे विश्वास हमारे चुने हुए होते हैं, या वे बस हमें हो जाते हैं?","examples":[{"en":"We do not choose beliefs as we choose clothes; we find ourselves believing, and at best we choose which beliefs to examine and which to feed.","native":"हम विश्वासों को कपड़ों की तरह नहीं चुनते; हम खुद को विश्वास करता पाते हैं — और अधिक से अधिक हम यही चुन सकते हैं कि किन विश्वासों की परख करनी है और किन्हें पालना है।"},{"en":"A belief held because it is useful is furniture; a belief held because it is true is a commitment, and the difference shows only under pressure.","native":"जो विश्वास उपयोगी होने के कारण पकड़ा गया हो, वह फ़र्नीचर है; जो सत्य होने के कारण पकड़ा गया हो, वह प्रतिबद्धता है — और फ़र्क़ केवल दबाव में दिखता है।"},{"en":"People defend their beliefs like property because beliefs are load-bearing: remove the wrong one carelessly and a whole worldview can collapse.","native":"लोग अपने विश्वासों की रक्षा संपत्ति की तरह करते हैं क्योंकि विश्वास भार वहन करने वाले होते हैं: ग़लत विश्वास को लापरवाही से निकालो तो पूरी विश्वदृष्टि ढह सकती है।"}]},"es":{"word":"creencia","question":"¿Elegimos nuestras creencias o simplemente nos suceden?","examples":[{"en":"We do not choose beliefs as we choose clothes; we find ourselves believing, and at best we choose which beliefs to examine and which to feed.","native":"No elegimos las creencias como elegimos la ropa; nos encontramos creyendo, y a lo sumo elegimos cuáles examinar y cuáles alimentar."},{"en":"A belief held because it is useful is furniture; a belief held because it is true is a commitment, and the difference shows only under pressure.","native":"Una creencia sostenida porque es útil es mobiliario; una sostenida porque es verdadera es un compromiso, y la diferencia solo se nota bajo presión."},{"en":"People defend their beliefs like property because beliefs are load-bearing: remove the wrong one carelessly and a whole worldview can collapse.","native":"La gente defiende sus creencias como propiedades porque las creencias soportan peso: retira descuidadamente la equivocada y toda una visión del mundo puede derrumbarse."}]},"zh":{"word":"信念","question":"我们的信念是选择的结果，还是自然而然降临在我们身上的？","examples":[{"en":"We do not choose beliefs as we choose clothes; we find ourselves believing, and at best we choose which beliefs to examine and which to feed.","native":"我们并不像挑选衣服那样挑选信念；我们发现自己已然相信，充其量只能选择审视哪些信念、滋养哪些信念。"},{"en":"A belief held because it is useful is furniture; a belief held because it is true is a commitment, and the difference shows only under pressure.","native":"因有用而持有的信念是家具；因真实而持有的信念是承诺——两者的差别，只有在压力下才显现。"},{"en":"People defend their beliefs like property because beliefs are load-bearing: remove the wrong one carelessly and a whole worldview can collapse.","native":"人们像捍卫财产一样捍卫信念，因为信念是承重的：若粗心地抽掉错误的那一根，整个世界观都可能坍塌。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'faith', 'Is faith a virtue, a comfort, or a surrender of reason?', '{"te":{"word":"విశ్వాసం","question":"విశ్వాసం ఒక గుణమా, ఓర్పా, లేదా తర్కం యొక్క లొంగుబాటా?","examples":[{"en":"Faith sustains people through evidence-free nights when reason alone would counsel despair, yet the same engine can carry a mind anywhere at all.","native":"తర్కం మాత్రమే నిరాశ సలహా ఇచ్చే సాక్ష్యరహిత రాత్రుల్లో విశ్వాసం ప్రజలను నిలబెడుతుంది, అయితే అదే యంత్రం మనసును ఎక్కడికైనా మోసుకెళ్లగలదు."},{"en":"There is faith in God, faith in people, and faith in tomorrow; what unites them is commitment in advance of proof, which every love requires.","native":"దేవుడిపై విశ్వాసం, మనుషులపై విశ్వాసం, రేపటిపై విశ్వాసం ఉన్నాయి; వాటన్నిటిని ఏకం చేసేది సాక్ష్యానికి ముందే నిబద్ధత — ప్రతి ప్రేమకు అది అవసరం."},{"en":"The question is never whether to have faith — we all trust something — but what deserves it, and what we do when our faith is betrayed.","native":"ప్రశ్న ఎప్పుడూ విశ్వాసం ఉండాలా వద్దా కాదు — మనమందరం ఏదో ఒక దాన్ని నమ్ముతాం — దేనికి అది అర్హమో, మన విశ్వాసం ద్రోహం చేయబడినప్పుడు మనం ఏమి చేస్తామో అదే ప్రశ్న."}]},"hi":{"word":"आस्था","question":"क्या आस्था एक गुण है, एक सांत्वना, या तर्क का समर्पण?","examples":[{"en":"Faith sustains people through evidence-free nights when reason alone would counsel despair, yet the same engine can carry a mind anywhere at all.","native":"आस्था उन साक्ष्य-विहीन रातों में लोगों को थामे रखती है जब अकेला तर्क निराशा की सलाह देता है, फिर भी वही इंजन मन को कहीं भी ले जा सकता है।"},{"en":"There is faith in God, faith in people, and faith in tomorrow; what unites them is commitment in advance of proof, which every love requires.","native":"ईश्वर में आस्था है, लोगों में आस्था है, और कल में आस्था है; तीनों को जोड़ता है प्रमाण से पहले की प्रतिबद्धता — जिसकी ज़रूरत हर प्रेम को होती है।"},{"en":"The question is never whether to have faith — we all trust something — but what deserves it, and what we do when our faith is betrayed.","native":"सवाल कभी यह नहीं कि आस्था रखनी है या नहीं — हम सब किसी न किसी पर भरोसा करते हैं — सवाल यह है कि कौन उसका हक़दार है, और आस्था के टूटने पर हम क्या करते हैं।"}]},"es":{"word":"fe","question":"¿Es la fe una virtud, un consuelo o una rendición de la razón?","examples":[{"en":"Faith sustains people through evidence-free nights when reason alone would counsel despair, yet the same engine can carry a mind anywhere at all.","native":"La fe sostiene a las personas en noches sin evidencia donde la razón sola aconsejaría desesperar, pero el mismo motor puede llevar una mente a cualquier parte."},{"en":"There is faith in God, faith in people, and faith in tomorrow; what unites them is commitment in advance of proof, which every love requires.","native":"Hay fe en Dios, fe en las personas y fe en el mañana; lo que las une es el compromiso antes de la prueba, que todo amor requiere."},{"en":"The question is never whether to have faith — we all trust something — but what deserves it, and what we do when our faith is betrayed.","native":"La cuestión nunca es si tener fe — todos confiamos en algo — sino qué la merece, y qué hacemos cuando nuestra fe es traicionada."}]},"zh":{"word":"信仰","question":"信仰是一种美德、一种慰藉，还是理性的投降？","examples":[{"en":"Faith sustains people through evidence-free nights when reason alone would counsel despair, yet the same engine can carry a mind anywhere at all.","native":"在证据缺席的暗夜里，单凭理性只会劝人绝望，而信仰支撑着人们挺过来——但同一台引擎，也能把心灵载往任何地方。"},{"en":"There is faith in God, faith in people, and faith in tomorrow; what unites them is commitment in advance of proof, which every love requires.","native":"有对神的信仰，有对人的信仰，也有对明天的信仰；将它们连在一起的，是在证明出现之前的托付——而每一份爱都需要这种托付。"},{"en":"The question is never whether to have faith — we all trust something — but what deserves it, and what we do when our faith is betrayed.","native":"问题从来不是要不要有信仰——我们人人都信任着某种东西——问题在于什么配得上它，以及信仰被辜负时我们何去何从。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'reason', 'Can reason alone tell us how to live, or does it only serve our passions?', '{"te":{"word":"తర్కం","question":"ఎలా జీవించాలో తర్కం ఒక్కటే చెప్పగలదా, లేదా అది కేవలం మన కోరికలకు సేవ చేస్తుందా?","examples":[{"en":"Reason is a superb navigator but a poor captain: it can chart any course yet cannot tell us which destination is worth the voyage.","native":"తర్కం అద్భుతమైన నావికుడు కానీ పేలవమైన కెప్టెను: ఏ మార్గాన్నైనా గీయగలదు కానీ ఏ గమ్యం ప్రయాణానికి విలువైనదో చెప్పలేదు."},{"en":"Hume called reason the slave of the passions, and the insult contains a truth: pure logic has never yet told anyone what to want.","native":"తర్కం కోరికలకు బానిస అని హ్యూమ్ అన్నాడు — ఆ అవమానంలో సత్యం ఉంది: స్వచ్ఛమైన తర్కం ఇప్పటివరకు ఎవరికీ ఏమి కోరాలో చెప్పలేదు."},{"en":"Yet reason disciplines our desires, catches our contradictions, and forces honesty upon us; a slave so indispensable becomes a partner in command.","native":"అయినా తర్కం మన కోరికలను క్రమబద్ధం చేస్తుంది, మన వైరుధ్యాలను పట్టుకుంటుంది, మనపై నిజాయితీని బలవంతం చేస్తుంది — అంత అత్యవసరమైన బానిస అధికారంలో భాగస్వామి అవుతుంది."}]},"hi":{"word":"तर्क","question":"क्या अकेला तर्क हमें बता सकता है कि कैसे जीना चाहिए, या वह केवल हमारी भावनाओं की सेवा करता है?","examples":[{"en":"Reason is a superb navigator but a poor captain: it can chart any course yet cannot tell us which destination is worth the voyage.","native":"तर्क शानदार नाविक है पर कमज़ोर कप्तान: वह कोई भी रास्ता बना सकता है, पर यह नहीं बता सकता कि कौन सी मंज़िल सफ़र की क़ाबिल है।"},{"en":"Hume called reason the slave of the passions, and the insult contains a truth: pure logic has never yet told anyone what to want.","native":"ह्यूम ने तर्क को भावनाओं का ग़ुलाम कहा — और उस अपमान में एक सच्चाई छिपी है: शुद्ध तर्क ने आज तक किसी को नहीं बताया कि क्या चाहना चाहिए।"},{"en":"Yet reason disciplines our desires, catches our contradictions, and forces honesty upon us; a slave so indispensable becomes a partner in command.","native":"फिर भी तर्क हमारी इच्छाओं को अनुशासित करता है, हमारे विरोधाभास पकड़ता है और हम पर ईमानदारी थोपता है; इतना अनिवार्य ग़ुलाम क़ाबिल में साझीदार बन जाता है।"}]},"es":{"word":"razón","question":"¿Puede la razón por sí sola decirnos cómo vivir, o solo sirve a nuestras pasiones?","examples":[{"en":"Reason is a superb navigator but a poor captain: it can chart any course yet cannot tell us which destination is worth the voyage.","native":"La razón es una navegante soberbia pero una capitana pobre: puede trazar cualquier rumbo, mas no puede decirnos qué destino merece el viaje."},{"en":"Hume called reason the slave of the passions, and the insult contains a truth: pure logic has never yet told anyone what to want.","native":"Hume llamó a la razón esclava de las pasiones, y el insulto contiene una verdad: la lógica pura jamás le ha dicho a nadie qué desear."},{"en":"Yet reason disciplines our desires, catches our contradictions, and forces honesty upon us; a slave so indispensable becomes a partner in command.","native":"Sin embargo, la razón disciplina nuestros deseos, atrapa nuestras contradicciones y nos impone honestidad; un esclavo tan indispensable se vuelve socio en el mando."}]},"zh":{"word":"理性","question":"单凭理性能告诉我们该如何生活吗？还是说它只为激情服务？","examples":[{"en":"Reason is a superb navigator but a poor captain: it can chart any course yet cannot tell us which destination is worth the voyage.","native":"理性是出色的领航员，却是平庸的船长：它能绘制任何航线，却无法告诉我们哪个目的地值得远航。"},{"en":"Hume called reason the slave of the passions, and the insult contains a truth: pure logic has never yet told anyone what to want.","native":"休谟称理性是激情的奴隶——这句羞辱中含着真理：纯粹的逻辑从未告诉过任何人应当欲求什么。"},{"en":"Yet reason disciplines our desires, catches our contradictions, and forces honesty upon us; a slave so indispensable becomes a partner in command.","native":"然而理性约束我们的欲望，揪出我们的矛盾，迫使我们诚实；如此不可或缺的奴隶，终将成为指挥席上的伙伴。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'intuition', 'When should we trust our intuition, and when does it betray us?', '{"te":{"word":"అంతర్దృష్టి","question":"మన అంతర్దృష్టిని ఎప్పుడు నమ్మాలి, మరియు అది ఎప్పుడు మనల్ని మోసం చేస్తుంది?","examples":[{"en":"Intuition is experience compressed into feeling; it deserves trust exactly where we have logged thousands of hours, and suspicion everywhere else.","native":"అంతర్దృష్టి అనేది భావనలోకి కుదించబడిన అనుభవం; మనం వేలాది గంటలు గడిపిన చోట్లే దాన్ని నమ్మడం, మిగతా చోట్ల సందేహించడం సముచితం."},{"en":"The chess master’s hunch is wisdom because it is memory in disguise, while the novice’s hunch is merely hope wearing the same costume.","native":"చదరంగం పిటామహుడి అంతర్జ్ఞానం జ్ఞానం ఎందుకంటే అది ముసుగులోని జ్ఞాపకం — అయితే నేర్పరి కాని అంతర్జ్ఞానం అదే వేషంలో ఉన్న ఆశ మాత్రమే."},{"en":"Intuition fails most reliably where statistics rule and feedback is slow, which is why gut feelings about markets and strangers so often mislead.","native":"గణాంకాలు పాలించే చోట, ప్రతిస్పందన నెమ్మదిగా వచ్చే చోట అంతర్దృష్టి అత్యంత నమ్మకంగా విఫలమవుతుంది — మార్కెట్ల గురించి, అపరిచితుల గురించి ఉండే అంతర్భావాలు ఎందుకు ఇంత తరచుగా తప్పుదారి పట్టిస్తాయో కారణం ఇదే."}]},"hi":{"word":"अंतर्ज्ञान","question":"हमें अपने अंतर्ज्ञान पर कब भरोसा करना चाहिए, और वह कब हमें धोखा देता है?","examples":[{"en":"Intuition is experience compressed into feeling; it deserves trust exactly where we have logged thousands of hours, and suspicion everywhere else.","native":"अंतर्ज्ञान भावना में संपीड़ित अनुभव है; ठीक वहीं इसका भरोसा किया जाए जहाँ हमने हज़ारों घंटे बिताए हों, और बाक़ी हर जगह संदेह।"},{"en":"The chess master’s hunch is wisdom because it is memory in disguise, while the novice’s hunch is merely hope wearing the same costume.","native":"शतरंज उस्ताद की सूझ बुद्धि है क्योंकि वह छद्मवेशी स्मृति है, जबकि नौसिखिए की सूझ महज़ उसी पोशाक में आशा है।"},{"en":"Intuition fails most reliably where statistics rule and feedback is slow, which is why gut feelings about markets and strangers so often mislead.","native":"अंतर्ज्ञान सबसे भरोसेमंद ढंग से वहाँ असफल होता है जहाँ आँकड़े राज करते हैं और प्रतिक्रिया धीमी होती है — इसीलिए बाज़ारों और अजनबियों के बारे में अंदरूनी भावना अक्सर गुमराह करती है।"}]},"es":{"word":"intuición","question":"¿Cuándo deberíamos confiar en nuestra intuición y cuándo nos traiciona?","examples":[{"en":"Intuition is experience compressed into feeling; it deserves trust exactly where we have logged thousands of hours, and suspicion everywhere else.","native":"La intuición es experiencia comprimida en sentimiento; merece confianza exactamente donde hemos acumulado miles de horas, y sospecha en todas partes demás."},{"en":"The chess master’s hunch is wisdom because it is memory in disguise, while the novice’s hunch is merely hope wearing the same costume.","native":"El pálpito del gran maestro de ajedrez es sabiduría porque es memoria disfrazada, mientras que el del novicio es solo esperanza con el mismo disfraz."},{"en":"Intuition fails most reliably where statistics rule and feedback is slow, which is why gut feelings about markets and strangers so often mislead.","native":"La intuición falla con mayor fiabilidad donde mandan las estadísticas y la retroalimentación es lenta, y por eso las corazonadas sobre mercados y desconocidos tan a menudo engañan."}]},"zh":{"word":"直觉","question":"什么时候应当相信直觉，什么时候直觉会背叛我们？","examples":[{"en":"Intuition is experience compressed into feeling; it deserves trust exactly where we have logged thousands of hours, and suspicion everywhere else.","native":"直觉是被压缩成感觉的经验；恰恰只有在我们投入过数千小时的领域，它才值得信任——其余地方都应存疑。"},{"en":"The chess master’s hunch is wisdom because it is memory in disguise, while the novice’s hunch is merely hope wearing the same costume.","native":"象棋大师的预感是智慧，因为它是乔装的记忆；而新手的预感，不过是穿着同样服装的希望。"},{"en":"Intuition fails most reliably where statistics rule and feedback is slow, which is why gut feelings about markets and strangers so often mislead.","native":"直觉在统计主导、反馈迟缓的领域失败得最为稳定——这就是为什么关于市场和陌生人的“感觉”如此经常地误导人。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'epistemology', 'How should epistemology distinguish justified knowledge from confident error in an age of algorithmic information?', '{"te":{"word":"జ్ఞానమీమాంస","question":"అల్గోరిథమిక్ సమాచార యుగంలో సమర్థించబడిన జ్ఞానాన్ని ఆత్మవిశ్వాసంతో కూడిన తప్పు నుంచి జ్ఞానమీమాంస ఎలా వేరు చేయాలి?","examples":[{"en":"A belief becomes knowledge only when its warrant survives scrutiny, not merely when repetition makes it familiar.","native":"పునరావృతం వల్ల ఒక నమ్మకం సుపరిచితం అయినంత మాత్రాన అది జ్ఞానం కాదు; దాని సమర్థన క్షుణ్ణమైన పరిశీలనను తట్టుకున్నప్పుడే అది జ్ఞానంగా మారుతుంది."},{"en":"Digital abundance magnifies an old epistemic problem: access to claims is not the same as access to reasons.","native":"డిజిటల్ సమృద్ధి ఒక పాత జ్ఞానసంబంధ సమస్యను మరింత పెంచుతుంది: వాదనలు అందుబాటులో ఉండటం, వాటి వెనుక కారణాలు అందుబాటులో ఉండటంతో సమానం కాదు."},{"en":"Intellectual humility is not indecision; it is the discipline of matching confidence to the quality of evidence.","native":"మేధో వినయం అనిర్ణయం కాదు; సాక్ష్యాల నాణ్యతకు తగిన స్థాయిలో ఆత్మవిశ్వాసాన్ని ఉంచే క్రమశిక్షణ అది."}]},"hi":{"word":"ज्ञानमीमांसा","question":"एल्गोरिद्मिक सूचना के युग में ज्ञानमीमांसा को उचित आधार वाले ज्ञान और आत्मविश्वास से भरी भूल के बीच भेद कैसे करना चाहिए?","examples":[{"en":"A belief becomes knowledge only when its warrant survives scrutiny, not merely when repetition makes it familiar.","native":"कोई विश्वास केवल बार-बार दोहराए जाने से परिचित लगने के कारण ज्ञान नहीं बनता; वह तभी ज्ञान बनता है जब उसका औचित्य कठोर जाँच में टिका रहे।"},{"en":"Digital abundance magnifies an old epistemic problem: access to claims is not the same as access to reasons.","native":"डिजिटल प्रचुरता ज्ञान से जुड़ी एक पुरानी समस्या को बढ़ा देती है: दावों तक पहुँच होना उनके कारणों तक पहुँच होने के समान नहीं है।"},{"en":"Intellectual humility is not indecision; it is the discipline of matching confidence to the quality of evidence.","native":"बौद्धिक विनम्रता अनिर्णय नहीं है; वह अपने आत्मविश्वास को साक्ष्य की गुणवत्ता के अनुरूप रखने का अनुशासन है।"}]},"es":{"word":"epistemología","question":"¿Cómo debería distinguir la epistemología entre el conocimiento justificado y el error expresado con seguridad en una era de información algorítmica?","examples":[{"en":"A belief becomes knowledge only when its warrant survives scrutiny, not merely when repetition makes it familiar.","native":"Una creencia se convierte en conocimiento solo cuando su justificación resiste el escrutinio, no simplemente cuando la repetición la vuelve familiar."},{"en":"Digital abundance magnifies an old epistemic problem: access to claims is not the same as access to reasons.","native":"La abundancia digital amplifica un antiguo problema epistémico: tener acceso a afirmaciones no equivale a tener acceso a razones."},{"en":"Intellectual humility is not indecision; it is the discipline of matching confidence to the quality of evidence.","native":"La humildad intelectual no es indecisión; es la disciplina de ajustar la confianza a la calidad de las pruebas."}]},"zh":{"word":"认识论","question":"在算法信息时代，认识论应如何区分有充分依据的知识与自信满满的错误？","examples":[{"en":"A belief becomes knowledge only when its warrant survives scrutiny, not merely when repetition makes it familiar.","native":"一种信念只有在其理据经受住审查时才成为知识，而不是仅仅因为反复出现而让人感到熟悉。"},{"en":"Digital abundance magnifies an old epistemic problem: access to claims is not the same as access to reasons.","native":"数字信息的极大丰富放大了一个古老的认识论难题：接触到主张并不等于接触到支撑它们的理由。"},{"en":"Intellectual humility is not indecision; it is the discipline of matching confidence to the quality of evidence.","native":"智识谦逊并非优柔寡断，而是一种让确信程度与证据质量相匹配的自律。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'existentialism', 'Does existentialism liberate individuals by denying predetermined meaning, or burden them with impossible responsibility?', '{"te":{"word":"అస్తిత్వవాదం","question":"ముందే నిర్ణయించబడిన అర్థాన్ని నిరాకరించడం ద్వారా అస్తిత్వవాదం వ్యక్తులకు విముక్తి కలిగిస్తుందా, లేక అసాధ్యమైన బాధ్యతను వారిపై మోపుతుందా?","examples":[{"en":"Existential freedom is exhilarating precisely because it removes every cosmic excuse for the life one chooses.","native":"మనిషి ఎంచుకునే జీవితానికి సంబంధించిన ప్రతి విశ్వవ్యాప్త సాకును తొలగిస్తుంది కాబట్టే అస్తిత్వ స్వేచ్ఛ ఉల్లాసకరంగా ఉంటుంది."},{"en":"We inherit circumstances we did not select, but our responses gradually turn those constraints into a biography.","native":"మనం ఎంచుకోని పరిస్థితులను వారసత్వంగా పొందుతాం, కానీ మన ప్రతిస్పందనలు క్రమంగా ఆ పరిమితులను మన జీవితకథగా మారుస్తాయి."},{"en":"The absence of predetermined meaning need not imply despair; it can make meaning an achievement rather than a gift.","native":"ముందే నిర్ణయించబడిన అర్థం లేకపోవడం నిరాశను సూచించాల్సిన అవసరం లేదు; అది అర్థాన్ని కానుకగా కాకుండా మనం సాధించేదిగా మార్చగలదు."}]},"hi":{"word":"अस्तित्ववाद","question":"क्या अस्तित्ववाद पूर्वनिर्धारित अर्थ को नकारकर व्यक्तियों को मुक्त करता है, या उन पर असंभव उत्तरदायित्व का बोझ डालता है?","examples":[{"en":"Existential freedom is exhilarating precisely because it removes every cosmic excuse for the life one chooses.","native":"अस्तित्वगत स्वतंत्रता ठीक इसलिए रोमांचक है क्योंकि वह व्यक्ति द्वारा चुने गए जीवन के लिए हर ब्रह्मांडीय बहाने को हटा देती है।"},{"en":"We inherit circumstances we did not select, but our responses gradually turn those constraints into a biography.","native":"हमें वे परिस्थितियाँ विरासत में मिलती हैं जिन्हें हमने नहीं चुना, लेकिन हमारी प्रतिक्रियाएँ धीरे-धीरे उन सीमाओं को हमारी जीवनकथा में बदल देती हैं।"},{"en":"The absence of predetermined meaning need not imply despair; it can make meaning an achievement rather than a gift.","native":"पूर्वनिर्धारित अर्थ का अभाव अनिवार्य रूप से निराशा नहीं लाता; वह अर्थ को उपहार के बजाय एक उपलब्धि बना सकता है।"}]},"es":{"word":"existencialismo","question":"¿Libera el existencialismo a las personas al negar un sentido predeterminado, o las carga con una responsabilidad imposible?","examples":[{"en":"Existential freedom is exhilarating precisely because it removes every cosmic excuse for the life one chooses.","native":"La libertad existencial resulta estimulante precisamente porque elimina toda excusa cósmica para la vida que cada persona elige."},{"en":"We inherit circumstances we did not select, but our responses gradually turn those constraints into a biography.","native":"Heredamos circunstancias que no escogimos, pero nuestras respuestas convierten gradualmente esas limitaciones en una biografía."},{"en":"The absence of predetermined meaning need not imply despair; it can make meaning an achievement rather than a gift.","native":"La ausencia de un sentido predeterminado no tiene por qué implicar desesperación; puede hacer del sentido un logro en vez de un regalo."}]},"zh":{"word":"存在主义","question":"存在主义否定预定的意义，究竟是解放了个人，还是让他们背负了无法承受的责任？","examples":[{"en":"Existential freedom is exhilarating precisely because it removes every cosmic excuse for the life one chooses.","native":"存在主义的自由之所以令人振奋，恰恰是因为它排除了为自己所选生活开脱的一切宇宙性借口。"},{"en":"We inherit circumstances we did not select, but our responses gradually turn those constraints into a biography.","native":"我们继承了并非由自己选择的处境，但我们的回应逐渐将这些限制写成了一部人生传记。"},{"en":"The absence of predetermined meaning need not imply despair; it can make meaning an achievement rather than a gift.","native":"没有预定的意义并不必然意味着绝望；它可以使意义成为一种成就，而不是一份馈赠。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'phenomenology', 'What can phenomenology reveal that third-person scientific description may overlook?', '{"te":{"word":"దృగ్విషయశాస్త్రం","question":"మూడవ వ్యక్తి దృష్టితో చేసే శాస్త్రీయ వర్ణన విస్మరించగల దేనిని దృగ్విషయశాస్త్రం వెల్లడించగలదు?","examples":[{"en":"A neural account of pain can be complete at its own level while omitting what pain feels like to the sufferer.","native":"నొప్పికి సంబంధించిన నాడీశాస్త్ర వివరణ తన స్థాయిలో సంపూర్ణంగా ఉండవచ్చు, అయినప్పటికీ బాధితుడికి నొప్పి ఎలా అనిపిస్తుందో అది వదిలేయవచ్చు."},{"en":"Phenomenology treats lived experience not as noise around reality but as a domain requiring rigorous description.","native":"దృగ్విషయశాస్త్రం జీవించిన అనుభవాన్ని వాస్తవం చుట్టూ ఉన్న అనవసర శబ్దంగా కాకుండా, కచ్చితమైన వర్ణన అవసరమైన అధ్యయన రంగంగా పరిగణిస్తుంది."},{"en":"First-person evidence is fallible, yet excluding it would erase the very consciousness a theory seeks to explain.","native":"ప్రథమ వ్యక్తి సాక్ష్యం తప్పు కావచ్చు; అయినా దానిని మినహాయిస్తే ఒక సిద్ధాంతం వివరించాలని ప్రయత్నించే చైతన్యాన్నే చెరిపివేసినట్లవుతుంది."}]},"hi":{"word":"घटनाविज्ञान","question":"घटनाविज्ञान ऐसा क्या उजागर कर सकता है जिसे तीसरे व्यक्ति के दृष्टिकोण वाला वैज्ञानिक वर्णन अनदेखा कर दे?","examples":[{"en":"A neural account of pain can be complete at its own level while omitting what pain feels like to the sufferer.","native":"पीड़ा का तंत्रिका-विज्ञान संबंधी विवरण अपने स्तर पर पूर्ण हो सकता है, फिर भी वह यह छोड़ सकता है कि पीड़ित को दर्द कैसा महसूस होता है।"},{"en":"Phenomenology treats lived experience not as noise around reality but as a domain requiring rigorous description.","native":"घटनाविज्ञान जिए हुए अनुभव को वास्तविकता के आसपास का शोर नहीं, बल्कि कठोर वर्णन की माँग करने वाला एक क्षेत्र मानता है।"},{"en":"First-person evidence is fallible, yet excluding it would erase the very consciousness a theory seeks to explain.","native":"प्रथम-पुरुष साक्ष्य त्रुटिपूर्ण हो सकता है, फिर भी उसे बाहर रखना उसी चेतना को मिटा देगा जिसे कोई सिद्धांत समझाना चाहता है।"}]},"es":{"word":"fenomenología","question":"¿Qué puede revelar la fenomenología que una descripción científica en tercera persona podría pasar por alto?","examples":[{"en":"A neural account of pain can be complete at its own level while omitting what pain feels like to the sufferer.","native":"Una explicación neuronal del dolor puede ser completa en su propio nivel y, aun así, omitir cómo se siente el dolor para quien lo padece."},{"en":"Phenomenology treats lived experience not as noise around reality but as a domain requiring rigorous description.","native":"La fenomenología considera la experiencia vivida no como ruido alrededor de la realidad, sino como un ámbito que exige una descripción rigurosa."},{"en":"First-person evidence is fallible, yet excluding it would erase the very consciousness a theory seeks to explain.","native":"La evidencia en primera persona es falible, pero excluirla borraría la propia conciencia que una teoría pretende explicar."}]},"zh":{"word":"现象学","question":"现象学能够揭示哪些可能被第三人称的科学描述所忽略的内容？","examples":[{"en":"A neural account of pain can be complete at its own level while omitting what pain feels like to the sufferer.","native":"对疼痛的神经机制解释可以在其自身层面上完整无缺，却仍遗漏疼痛对于承受者而言究竟是什么感受。"},{"en":"Phenomenology treats lived experience not as noise around reality but as a domain requiring rigorous description.","native":"现象学不把切身经验视为现实周围的噪声，而是将其视为一个需要严谨描述的领域。"},{"en":"First-person evidence is fallible, yet excluding it would erase the very consciousness a theory seeks to explain.","native":"第一人称证据可能出错，然而将其排除，就会抹去理论原本试图解释的意识本身。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'postmodernism', 'Has postmodernism sharpened criticism of hidden power, or weakened our capacity to defend shared truth?', '{"te":{"word":"ఉత్తరాధునికవాదం","question":"ఉత్తరాధునికవాదం దాగి ఉన్న అధికారంపై విమర్శను పదును పెట్టిందా, లేక ఉమ్మడి సత్యాన్ని సమర్థించే మన సామర్థ్యాన్ని బలహీనపరిచిందా?","examples":[{"en":"Postmodern critique usefully exposes whose interests masquerade as neutrality, but suspicion cannot itself establish what is true.","native":"ఎవరి ప్రయోజనాలు తటస్థత ముసుగులో కనిపిస్తున్నాయో ఉత్తరాధునిక విమర్శ ఉపయోగకరంగా బయటపెడుతుంది; అయితే అనుమానం ఒక్కటే ఏది సత్యమో నిర్ధారించలేదు."},{"en":"When every claim is reduced to power, the critic’s own claim risks becoming another bid for dominance.","native":"ప్రతి వాదనను అధికారానికి మాత్రమే పరిమితం చేసినప్పుడు, విమర్శకుడి సొంత వాదన కూడా ఆధిపత్యం కోసం చేసే మరో ప్రయత్నంగా మారే ప్రమాదం ఉంది."},{"en":"We can reject absolute foundations without pretending that evidence, coherence, and consequences are interchangeable.","native":"సాక్ష్యం, పొందిక, పరిణామాలు పరస్పరం మార్చుకోదగినవని నటించకుండానే మనం నిరపేక్ష పునాదులను తిరస్కరించవచ్చు."}]},"hi":{"word":"उत्तर-आधुनिकतावाद","question":"क्या उत्तर-आधुनिकतावाद ने छिपी हुई सत्ता की आलोचना को पैना किया है, या साझा सत्य की रक्षा करने की हमारी क्षमता को कमज़ोर किया है?","examples":[{"en":"Postmodern critique usefully exposes whose interests masquerade as neutrality, but suspicion cannot itself establish what is true.","native":"उत्तर-आधुनिक आलोचना उपयोगी ढंग से उजागर करती है कि किसके हित तटस्थता का वेश धारण करते हैं, लेकिन संदेह अपने आप यह स्थापित नहीं कर सकता कि सत्य क्या है।"},{"en":"When every claim is reduced to power, the critic’s own claim risks becoming another bid for dominance.","native":"जब हर दावे को सत्ता तक सीमित कर दिया जाता है, तब आलोचक का अपना दावा भी प्रभुत्व पाने की एक और कोशिश बन जाने का जोखिम उठाता है।"},{"en":"We can reject absolute foundations without pretending that evidence, coherence, and consequences are interchangeable.","native":"हम यह दिखावा किए बिना परम आधारों को अस्वीकार कर सकते हैं कि साक्ष्य, सुसंगति और परिणाम एक-दूसरे के बदले रखे जा सकते हैं।"}]},"es":{"word":"posmodernismo","question":"¿Ha agudizado el posmodernismo la crítica del poder oculto, o ha debilitado nuestra capacidad de defender una verdad compartida?","examples":[{"en":"Postmodern critique usefully exposes whose interests masquerade as neutrality, but suspicion cannot itself establish what is true.","native":"La crítica posmoderna revela de forma útil qué intereses se disfrazan de neutralidad, pero la sospecha por sí sola no puede establecer qué es verdadero."},{"en":"When every claim is reduced to power, the critic’s own claim risks becoming another bid for dominance.","native":"Cuando toda afirmación se reduce al poder, la afirmación del propio crítico corre el riesgo de convertirse en otra apuesta por el dominio."},{"en":"We can reject absolute foundations without pretending that evidence, coherence, and consequences are interchangeable.","native":"Podemos rechazar fundamentos absolutos sin fingir que la evidencia, la coherencia y las consecuencias son intercambiables."}]},"zh":{"word":"后现代主义","question":"后现代主义究竟强化了对隐蔽权力的批判，还是削弱了我们捍卫共同真理的能力？","examples":[{"en":"Postmodern critique usefully exposes whose interests masquerade as neutrality, but suspicion cannot itself establish what is true.","native":"后现代批判有效揭示了究竟是谁的利益伪装成中立，但怀疑本身并不能确立何为真实。"},{"en":"When every claim is reduced to power, the critic’s own claim risks becoming another bid for dominance.","native":"当一切主张都被还原为权力时，批评者自己的主张也可能沦为另一场争夺支配地位的行动。"},{"en":"We can reject absolute foundations without pretending that evidence, coherence, and consequences are interchangeable.","native":"我们可以拒绝绝对基础，却不必假装证据、连贯性与后果可以彼此替换。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'structuralism', 'To what extent does structuralism explain human culture through relations that individuals neither see nor control?', '{"te":{"word":"నిర్మాణవాదం","question":"వ్యక్తులు చూడలేని, నియంత్రించలేని సంబంధాల ద్వారా మానవ సంస్కృతిని నిర్మాణవాదం ఎంతవరకు వివరించగలదు?","examples":[{"en":"Structuralism shifts attention from isolated symbols to the systems of difference that make symbols intelligible.","native":"నిర్మాణవాదం విడివిడిగా ఉన్న సంకేతాల నుంచి, ఆ సంకేతాలను అర్థవంతం చేసే భేదాల వ్యవస్థల వైపు దృష్టిని మళ్లిస్తుంది."},{"en":"Its strength is revealing recurrent patterns; its danger is treating human agents as mere effects of an abstract code.","native":"పునరావృతమయ్యే నమూనాలను వెల్లడించడం దాని బలం; మానవ కర్తలను ఒక అమూర్త సంకేతవ్యవస్థ యొక్క కేవలం ఫలితాలుగా చూడటం దాని ప్రమాదం."},{"en":"A structure can constrain what is thinkable without determining every thought that people actually have.","native":"ప్రజలు నిజంగా కలిగి ఉండే ప్రతి ఆలోచనను నిర్ణయించకుండానే, ఏది ఆలోచించదగినదో ఒక నిర్మాణం పరిమితం చేయగలదు."}]},"hi":{"word":"संरचनावाद","question":"संरचनावाद उन संबंधों के माध्यम से मानव संस्कृति को किस हद तक समझाता है जिन्हें व्यक्ति न तो देख पाते हैं और न नियंत्रित कर पाते हैं?","examples":[{"en":"Structuralism shifts attention from isolated symbols to the systems of difference that make symbols intelligible.","native":"संरचनावाद ध्यान को अलग-अलग प्रतीकों से हटाकर उन भेद-व्यवस्थाओं पर ले जाता है जो प्रतीकों को अर्थवान बनाती हैं।"},{"en":"Its strength is revealing recurrent patterns; its danger is treating human agents as mere effects of an abstract code.","native":"बार-बार उभरने वाले प्रतिरूपों को उजागर करना इसकी शक्ति है; मानव कर्ताओं को किसी अमूर्त संकेत-तंत्र का मात्र प्रभाव मान लेना इसका खतरा है।"},{"en":"A structure can constrain what is thinkable without determining every thought that people actually have.","native":"कोई संरचना इस बात को सीमित कर सकती है कि क्या सोचा जा सकता है, बिना लोगों के हर वास्तविक विचार को निर्धारित किए।"}]},"es":{"word":"estructuralismo","question":"¿Hasta qué punto explica el estructuralismo la cultura humana mediante relaciones que los individuos ni ven ni controlan?","examples":[{"en":"Structuralism shifts attention from isolated symbols to the systems of difference that make symbols intelligible.","native":"El estructuralismo desplaza la atención de los símbolos aislados hacia los sistemas de diferencias que los vuelven inteligibles."},{"en":"Its strength is revealing recurrent patterns; its danger is treating human agents as mere effects of an abstract code.","native":"Su fuerza consiste en revelar patrones recurrentes; su peligro, en tratar a los agentes humanos como meros efectos de un código abstracto."},{"en":"A structure can constrain what is thinkable without determining every thought that people actually have.","native":"Una estructura puede limitar lo que resulta pensable sin determinar cada pensamiento que las personas tienen en realidad."}]},"zh":{"word":"结构主义","question":"结构主义在多大程度上能够通过个人既看不见也无法控制的关系来解释人类文化？","examples":[{"en":"Structuralism shifts attention from isolated symbols to the systems of difference that make symbols intelligible.","native":"结构主义把注意力从孤立的符号转向使符号能够被理解的差异系统。"},{"en":"Its strength is revealing recurrent patterns; its danger is treating human agents as mere effects of an abstract code.","native":"它的长处在于揭示反复出现的模式；它的危险则在于把人的能动主体仅仅视为抽象代码的产物。"},{"en":"A structure can constrain what is thinkable without determining every thought that people actually have.","native":"一种结构可以限制什么是可思考的，却不必决定人们实际产生的每一个想法。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'humanism', 'Can humanism sustain universal dignity without relying on religious or metaphysical foundations?', '{"te":{"word":"మానవతావాదం","question":"మతపరమైన లేదా అధిభౌతిక పునాదులపై ఆధారపడకుండా మానవతావాదం సార్వత్రిక గౌరవాన్ని నిలబెట్టగలదా?","examples":[{"en":"Human dignity may be a moral commitment we construct together rather than a fact discovered in nature.","native":"మానవ గౌరవం ప్రకృతిలో కనుగొనబడిన వాస్తవం కాకుండా, మనం కలిసి నిర్మించుకునే నైతిక నిబద్ధత కావచ్చు."},{"en":"A secular foundation is not necessarily a weak one; promises and laws derive force from collective recognition.","native":"లౌకిక పునాది తప్పనిసరిగా బలహీనమైనది కాదు; వాగ్దానాలు, చట్టాలు సమష్టి గుర్తింపు నుంచి శక్తిని పొందుతాయి."},{"en":"Humanism fails its own standard whenever the category of the human is quietly narrowed to exclude inconvenient lives.","native":"అసౌకర్యంగా భావించే జీవితాలను మినహాయించేందుకు మానవుడు అనే వర్గాన్ని నిశ్శబ్దంగా కుదించినప్పుడల్లా మానవతావాదం తన సొంత ప్రమాణంలో విఫలమవుతుంది."}]},"hi":{"word":"मानवतावाद","question":"क्या मानवतावाद धार्मिक या आध्यात्मिक आधारों पर निर्भर हुए बिना सार्वभौमिक गरिमा को कायम रख सकता है?","examples":[{"en":"Human dignity may be a moral commitment we construct together rather than a fact discovered in nature.","native":"मानवीय गरिमा प्रकृति में खोजा गया कोई तथ्य होने के बजाय ऐसी नैतिक प्रतिबद्धता हो सकती है जिसे हम मिलकर रचते हैं।"},{"en":"A secular foundation is not necessarily a weak one; promises and laws derive force from collective recognition.","native":"धर्मनिरपेक्ष आधार अनिवार्य रूप से कमज़ोर नहीं होता; वादों और कानूनों को सामूहिक मान्यता से शक्ति मिलती है।"},{"en":"Humanism fails its own standard whenever the category of the human is quietly narrowed to exclude inconvenient lives.","native":"जब भी असुविधाजनक जीवनों को बाहर करने के लिए मनुष्य की श्रेणी को चुपचाप संकुचित किया जाता है, मानवतावाद अपने ही मानदंड पर विफल हो जाता है।"}]},"es":{"word":"humanismo","question":"¿Puede el humanismo sostener la dignidad universal sin apoyarse en fundamentos religiosos o metafísicos?","examples":[{"en":"Human dignity may be a moral commitment we construct together rather than a fact discovered in nature.","native":"La dignidad humana puede ser un compromiso moral que construimos juntos, en lugar de un hecho descubierto en la naturaleza."},{"en":"A secular foundation is not necessarily a weak one; promises and laws derive force from collective recognition.","native":"Un fundamento secular no es necesariamente débil; las promesas y las leyes obtienen su fuerza del reconocimiento colectivo."},{"en":"Humanism fails its own standard whenever the category of the human is quietly narrowed to exclude inconvenient lives.","native":"El humanismo incumple su propio criterio cada vez que se restringe discretamente la categoría de lo humano para excluir vidas incómodas."}]},"zh":{"word":"人文主义","question":"人文主义能否不依赖宗教或形而上学基础而维系普遍尊严？","examples":[{"en":"Human dignity may be a moral commitment we construct together rather than a fact discovered in nature.","native":"人的尊严或许不是在自然界中发现的事实，而是我们共同建构的一项道德承诺。"},{"en":"A secular foundation is not necessarily a weak one; promises and laws derive force from collective recognition.","native":"世俗基础并不必然薄弱；承诺与法律的力量来自集体认可。"},{"en":"Humanism fails its own standard whenever the category of the human is quietly narrowed to exclude inconvenient lives.","native":"每当人的范畴被悄然缩窄以排除那些令人不便的生命时，人文主义就违背了自己的标准。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'secularism', 'Should secularism require public institutions to be neutral toward religion, or merely impartial among convictions?', '{"te":{"word":"లౌకికవాదం","question":"ప్రజా సంస్థలు మతం పట్ల తటస్థంగా ఉండాలని లౌకికవాదం కోరాలా, లేక వివిధ విశ్వాసాల పట్ల నిష్పక్షపాతంగా ఉంటే సరిపోతుందా?","examples":[{"en":"Secular government should protect religious exercise while refusing to make citizenship depend on any creed.","native":"లౌకిక ప్రభుత్వం మతాచరణను రక్షిస్తూనే, పౌరసత్వాన్ని ఏ మతవిశ్వాసంపైనా ఆధారపడేలా చేయడాన్ని నిరాకరించాలి."},{"en":"Neutrality is impossible if it means having no values, but impartiality can prevent one doctrine from monopolising power.","native":"ఏ విలువలూ లేకపోవడమే తటస్థతకు అర్థమైతే అది అసాధ్యం; అయితే నిష్పక్షపాతత్వం ఒకే సిద్ధాంతం అధికారాన్ని గుత్తాధిపత్యం చేయకుండా అడ్డుకోగలదు."},{"en":"The hardest cases arise when private conscience collides with equal access to public rights and services.","native":"వ్యక్తిగత మనస్సాక్షి, ప్రజా హక్కులు మరియు సేవలకు సమాన ప్రాప్యతతో ఢీకొన్నప్పుడు అత్యంత క్లిష్టమైన సందర్భాలు తలెత్తుతాయి."}]},"hi":{"word":"धर्मनिरपेक्षता","question":"क्या धर्मनिरपेक्षता को सार्वजनिक संस्थाओं से धर्म के प्रति तटस्थता की माँग करनी चाहिए, या केवल विभिन्न आस्थाओं के बीच निष्पक्षता की?","examples":[{"en":"Secular government should protect religious exercise while refusing to make citizenship depend on any creed.","native":"धर्मनिरपेक्ष सरकार को धार्मिक आचरण की रक्षा करनी चाहिए, साथ ही नागरिकता को किसी भी मत पर निर्भर बनाने से इनकार करना चाहिए।"},{"en":"Neutrality is impossible if it means having no values, but impartiality can prevent one doctrine from monopolising power.","native":"यदि तटस्थता का अर्थ किसी भी मूल्य का न होना है तो वह असंभव है, लेकिन निष्पक्षता किसी एक सिद्धांत को सत्ता पर एकाधिकार करने से रोक सकती है।"},{"en":"The hardest cases arise when private conscience collides with equal access to public rights and services.","native":"सबसे कठिन मामले तब सामने आते हैं जब निजी अंतरात्मा सार्वजनिक अधिकारों और सेवाओं तक समान पहुँच से टकराती है।"}]},"es":{"word":"secularismo","question":"¿Debería el secularismo exigir que las instituciones públicas sean neutrales ante la religión, o solo imparciales entre distintas convicciones?","examples":[{"en":"Secular government should protect religious exercise while refusing to make citizenship depend on any creed.","native":"Un gobierno secular debería proteger la práctica religiosa y, al mismo tiempo, negarse a hacer que la ciudadanía dependa de credo alguno."},{"en":"Neutrality is impossible if it means having no values, but impartiality can prevent one doctrine from monopolising power.","native":"La neutralidad es imposible si significa carecer de valores, pero la imparcialidad puede impedir que una doctrina monopolice el poder."},{"en":"The hardest cases arise when private conscience collides with equal access to public rights and services.","native":"Los casos más difíciles surgen cuando la conciencia privada choca con la igualdad de acceso a los derechos y servicios públicos."}]},"zh":{"word":"世俗主义","question":"世俗主义应要求公共机构对宗教保持中立，还是只需在各种信念之间做到公正无偏？","examples":[{"en":"Secular government should protect religious exercise while refusing to make citizenship depend on any creed.","native":"世俗政府应保护宗教实践，同时拒绝让公民身份取决于任何信条。"},{"en":"Neutrality is impossible if it means having no values, but impartiality can prevent one doctrine from monopolising power.","native":"如果中立意味着不持有任何价值观，那么它不可能实现；但公正无偏可以防止某种教义垄断权力。"},{"en":"The hardest cases arise when private conscience collides with equal access to public rights and services.","native":"最棘手的情形出现在个人良知与平等获得公共权利和服务的要求发生冲突之时。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'pluralism', 'How can pluralism respect deep moral disagreement without sliding into indifference or fragmentation?', '{"te":{"word":"బహుళత్వవాదం","question":"లోతైన నైతిక విభేదాన్ని నిర్లక్ష్యం లేదా విచ్ఛిన్నతలోకి జారకుండా బహుళత్వవాదం ఎలా గౌరవించగలదు?","examples":[{"en":"Pluralism asks citizens to coexist without pretending that their ultimate values can always be reconciled.","native":"తమ అంతిమ విలువలను ఎల్లప్పుడూ సమన్వయపరచవచ్చని నటించకుండా సహజీవనం చేయాలని బహుళత్వవాదం పౌరులను కోరుతుంది."},{"en":"Tolerance is not approval; it is a political discipline bounded by the equal freedom of others.","native":"సహనం ఆమోదం కాదు; అది ఇతరుల సమాన స్వేచ్ఛతో పరిమితమైన రాజకీయ క్రమశిక్షణ."},{"en":"A plural society needs shared procedures robust enough to contain disagreement but flexible enough to remain legitimate.","native":"విభేదాన్ని నిర్వహించగలంత దృఢమైనవీ, చట్టబద్ధతను నిలుపుకునేంత అనువైనవీ అయిన ఉమ్మడి ప్రక్రియలు బహుళ సమాజానికి అవసరం."}]},"hi":{"word":"बहुलतावाद","question":"बहुलतावाद गहरी नैतिक असहमति का सम्मान करते हुए उदासीनता या विखंडन में फिसलने से कैसे बच सकता है?","examples":[{"en":"Pluralism asks citizens to coexist without pretending that their ultimate values can always be reconciled.","native":"बहुलतावाद नागरिकों से यह दिखावा किए बिना साथ रहने को कहता है कि उनके अंतिम मूल्यों में हमेशा सामंजस्य बैठाया जा सकता है।"},{"en":"Tolerance is not approval; it is a political discipline bounded by the equal freedom of others.","native":"सहिष्णुता स्वीकृति नहीं है; वह दूसरों की समान स्वतंत्रता से सीमाबद्ध एक राजनीतिक अनुशासन है।"},{"en":"A plural society needs shared procedures robust enough to contain disagreement but flexible enough to remain legitimate.","native":"एक बहुल समाज को ऐसी साझा प्रक्रियाएँ चाहिए जो असहमति को सँभालने के लिए पर्याप्त मज़बूत और वैध बने रहने के लिए पर्याप्त लचीली हों।"}]},"es":{"word":"pluralismo","question":"¿Cómo puede el pluralismo respetar un profundo desacuerdo moral sin caer en la indiferencia o la fragmentación?","examples":[{"en":"Pluralism asks citizens to coexist without pretending that their ultimate values can always be reconciled.","native":"El pluralismo pide a la ciudadanía que conviva sin fingir que sus valores últimos siempre pueden conciliarse."},{"en":"Tolerance is not approval; it is a political discipline bounded by the equal freedom of others.","native":"La tolerancia no es aprobación; es una disciplina política limitada por la libertad igual de los demás."},{"en":"A plural society needs shared procedures robust enough to contain disagreement but flexible enough to remain legitimate.","native":"Una sociedad plural necesita procedimientos compartidos lo bastante sólidos para encauzar el desacuerdo y lo bastante flexibles para conservar su legitimidad."}]},"zh":{"word":"多元主义","question":"多元主义如何既尊重深刻的道德分歧，又不滑向冷漠或社会割裂？","examples":[{"en":"Pluralism asks citizens to coexist without pretending that their ultimate values can always be reconciled.","native":"多元主义要求公民共同生活，却不假装他们的终极价值总能彼此调和。"},{"en":"Tolerance is not approval; it is a political discipline bounded by the equal freedom of others.","native":"宽容并非赞同，而是一种以他人的平等自由为边界的政治自律。"},{"en":"A plural society needs shared procedures robust enough to contain disagreement but flexible enough to remain legitimate.","native":"多元社会需要一套共同程序，既足够稳健以容纳分歧，又足够灵活以维持正当性。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'sovereignty', 'Is national sovereignty still defensible when crises and supply chains routinely cross borders?', '{"te":{"word":"సార్వభౌమాధికారం","question":"సంక్షోభాలు, సరఫరా గొలుసులు తరచుగా సరిహద్దులను దాటుతున్నప్పుడు జాతీయ సార్వభౌమాధికారం ఇప్పటికీ సమర్థనీయమేనా?","examples":[{"en":"Sovereignty remains vital for democratic accountability, yet absolute autonomy is fiction in an interdependent world.","native":"ప్రజాస్వామ్య జవాబుదారీతనానికి సార్వభౌమాధికారం ఇప్పటికీ కీలకం; అయితే పరస్పరాధారిత ప్రపంచంలో సంపూర్ణ స్వయంప్రతిపత్తి ఒక కల్పన మాత్రమే."},{"en":"Climate change exposes the moral weakness of borders: emissions are territorial, but their consequences are not.","native":"వాతావరణ మార్పు సరిహద్దుల నైతిక బలహీనతను బయటపెడుతుంది: ఉద్గారాలు ఒక భూభాగంలో పుడతాయి, కానీ వాటి పరిణామాలు అక్కడికే పరిమితం కావు."},{"en":"International cooperation becomes legitimate when states share authority transparently rather than surrendering it without consent.","native":"దేశాలు సమ్మతి లేకుండా అధికారాన్ని వదులుకోవడం కాకుండా పారదర్శకంగా పంచుకున్నప్పుడు అంతర్జాతీయ సహకారానికి చట్టబద్ధత లభిస్తుంది."}]},"hi":{"word":"संप्रभुता","question":"जब संकट और आपूर्ति शृंखलाएँ नियमित रूप से सीमाएँ पार करती हैं, तब क्या राष्ट्रीय संप्रभुता अब भी बचाव योग्य है?","examples":[{"en":"Sovereignty remains vital for democratic accountability, yet absolute autonomy is fiction in an interdependent world.","native":"लोकतांत्रिक जवाबदेही के लिए संप्रभुता अब भी अत्यंत आवश्यक है, फिर भी परस्पर निर्भर विश्व में पूर्ण स्वायत्तता एक कल्पना है।"},{"en":"Climate change exposes the moral weakness of borders: emissions are territorial, but their consequences are not.","native":"जलवायु परिवर्तन सीमाओं की नैतिक कमजोरी उजागर करता है: उत्सर्जन किसी भूभाग में होता है, लेकिन उसके परिणाम वहीं तक सीमित नहीं रहते।"},{"en":"International cooperation becomes legitimate when states share authority transparently rather than surrendering it without consent.","native":"अंतरराष्ट्रीय सहयोग तब वैध बनता है जब राज्य बिना सहमति सत्ता त्यागने के बजाय उसे पारदर्शी ढंग से साझा करते हैं।"}]},"es":{"word":"soberanía","question":"¿Sigue siendo defendible la soberanía nacional cuando las crisis y las cadenas de suministro atraviesan fronteras habitualmente?","examples":[{"en":"Sovereignty remains vital for democratic accountability, yet absolute autonomy is fiction in an interdependent world.","native":"La soberanía sigue siendo vital para la rendición de cuentas democrática, aunque la autonomía absoluta es una ficción en un mundo interdependiente."},{"en":"Climate change exposes the moral weakness of borders: emissions are territorial, but their consequences are not.","native":"El cambio climático revela la debilidad moral de las fronteras: las emisiones son territoriales, pero sus consecuencias no lo son."},{"en":"International cooperation becomes legitimate when states share authority transparently rather than surrendering it without consent.","native":"La cooperación internacional se vuelve legítima cuando los Estados comparten autoridad con transparencia en lugar de cederla sin consentimiento."}]},"zh":{"word":"主权","question":"当危机与供应链经常跨越国界时，国家主权是否仍然具有可辩护性？","examples":[{"en":"Sovereignty remains vital for democratic accountability, yet absolute autonomy is fiction in an interdependent world.","native":"主权对于民主问责仍然至关重要，然而在相互依存的世界里，绝对自主只是一种虚构。"},{"en":"Climate change exposes the moral weakness of borders: emissions are territorial, but their consequences are not.","native":"气候变化暴露了边界在道德上的局限：排放发生在特定疆域内，其后果却不受疆域限制。"},{"en":"International cooperation becomes legitimate when states share authority transparently rather than surrendering it without consent.","native":"当国家以透明方式分享权力，而不是未经同意便将其交出时，国际合作才获得正当性。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'legitimacy', 'What makes political authority legitimate when elections, expertise, and public consent point in different directions?', '{"te":{"word":"చట్టబద్ధత","question":"ఎన్నికలు, నిపుణుల జ్ఞానం, ప్రజా సమ్మతి వేర్వేరు దిశలను సూచించినప్పుడు రాజకీయ అధికారానికి చట్టబద్ధతను ఇచ్చేది ఏమిటి?","examples":[{"en":"Elections confer a mandate, but legality and continuing accountability determine how far that mandate can reach.","native":"ఎన్నికలు ఒక ప్రజాదేశాన్ని ఇస్తాయి; అయితే ఆ అధికారం ఎంతవరకు విస్తరించగలదో చట్టానుగుణత, నిరంతర జవాబుదారీతనం నిర్ణయిస్తాయి."},{"en":"Expertise can justify a policy recommendation without granting experts the right to silence affected citizens.","native":"నిపుణుల జ్ఞానం ఒక విధాన సిఫారసును సమర్థించగలదు; కానీ దాని ప్రభావానికి లోనయ్యే పౌరులను మౌనంగా ఉంచే హక్కును నిపుణులకు ఇవ్వదు."},{"en":"Legitimacy erodes when institutions demand obedience while concealing the reasons and interests behind their decisions.","native":"సంస్థలు తమ నిర్ణయాల వెనుక కారణాలు, ప్రయోజనాలను దాచిపెట్టి విధేయతను కోరినప్పుడు వాటి చట్టబద్ధత క్షీణిస్తుంది."}]},"hi":{"word":"वैधता","question":"जब चुनाव, विशेषज्ञता और जन-सहमति अलग-अलग दिशाओं की ओर संकेत करें, तब राजनीतिक सत्ता को वैध क्या बनाता है?","examples":[{"en":"Elections confer a mandate, but legality and continuing accountability determine how far that mandate can reach.","native":"चुनाव जनादेश देते हैं, लेकिन कानूनसम्मतता और निरंतर जवाबदेही तय करती हैं कि वह जनादेश कितनी दूर तक जा सकता है।"},{"en":"Expertise can justify a policy recommendation without granting experts the right to silence affected citizens.","native":"विशेषज्ञता किसी नीतिगत सुझाव को उचित ठहरा सकती है, पर इससे विशेषज्ञों को प्रभावित नागरिकों को चुप कराने का अधिकार नहीं मिल जाता।"},{"en":"Legitimacy erodes when institutions demand obedience while concealing the reasons and interests behind their decisions.","native":"जब संस्थाएँ अपने निर्णयों के पीछे के कारण और हित छिपाते हुए आज्ञापालन माँगती हैं, तब उनकी वैधता क्षीण होती है।"}]},"es":{"word":"legitimidad","question":"¿Qué hace legítima a la autoridad política cuando las elecciones, el conocimiento experto y el consentimiento público apuntan en direcciones distintas?","examples":[{"en":"Elections confer a mandate, but legality and continuing accountability determine how far that mandate can reach.","native":"Las elecciones confieren un mandato, pero la legalidad y la rendición de cuentas continua determinan hasta dónde puede llegar."},{"en":"Expertise can justify a policy recommendation without granting experts the right to silence affected citizens.","native":"El conocimiento experto puede justificar una recomendación de política pública sin otorgar a los expertos el derecho de silenciar a la ciudadanía afectada."},{"en":"Legitimacy erodes when institutions demand obedience while concealing the reasons and interests behind their decisions.","native":"La legitimidad se erosiona cuando las instituciones exigen obediencia y ocultan las razones y los intereses que hay detrás de sus decisiones."}]},"zh":{"word":"正当性","question":"当选举、专业知识与公众同意指向不同方向时，什么能使政治权威获得正当性？","examples":[{"en":"Elections confer a mandate, but legality and continuing accountability determine how far that mandate can reach.","native":"选举赋予执政授权，但合法性与持续问责决定了这项授权究竟能够延伸多远。"},{"en":"Expertise can justify a policy recommendation without granting experts the right to silence affected citizens.","native":"专业知识可以为一项政策建议提供依据，却不能因此赋予专家让受影响公民噤声的权利。"},{"en":"Legitimacy erodes when institutions demand obedience while concealing the reasons and interests behind their decisions.","native":"当制度一边要求服从，一边掩盖其决策背后的理由与利益时，正当性就会遭到侵蚀。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'hegemony', 'How does cultural hegemony make historically contingent values appear natural and universally shared?', '{"te":{"word":"సాంస్కృతిక ఆధిపత్యం","question":"చారిత్రక పరిస్థితుల వల్ల ఏర్పడిన విలువలు సహజమైనవిగా, విశ్వవ్యాప్తంగా అందరూ పంచుకునేవిగా సాంస్కృతిక ఆధిపత్యం ఎలా కనిపించేలా చేస్తుంది?","examples":[{"en":"Hegemony is most durable when dominated groups participate in reproducing the assumptions that constrain them.","native":"ఆధిపత్యానికి లోనైన వర్గాలే తమను పరిమితం చేసే ఊహలను తిరిగి ఉత్పత్తి చేయడంలో పాల్గొన్నప్పుడు ఆ ఆధిపత్యం అత్యంత దీర్ఘకాలం నిలుస్తుంది."},{"en":"Popular culture can normalize a social hierarchy without issuing an explicit command in its defense.","native":"ప్రజాదరణ పొందిన సంస్కృతి ఒక సామాజిక శ్రేణీకరణను సమర్థిస్తూ స్పష్టమైన ఆదేశమేదీ ఇవ్వకుండానే దానిని సాధారణమైనదిగా మార్చగలదు."},{"en":"Counter-hegemonic movements succeed by building a credible common sense, not merely by exposing elite interests.","native":"ప్రతిఆధిపత్య ఉద్యమాలు కేవలం ఉన్నత వర్గాల ప్రయోజనాలను బయటపెట్టడం వల్ల కాకుండా, నమ్మదగిన సామూహిక అవగాహనను నిర్మించడం వల్ల విజయం సాధిస్తాయి."}]},"hi":{"word":"सांस्कृतिक वर्चस्व","question":"सांस्कृतिक वर्चस्व ऐतिहासिक परिस्थितियों से बने मूल्यों को स्वाभाविक और सार्वभौमिक रूप से साझा किए जाने वाले मूल्यों जैसा कैसे दिखाता है?","examples":[{"en":"Hegemony is most durable when dominated groups participate in reproducing the assumptions that constrain them.","native":"वर्चस्व तब सबसे टिकाऊ होता है जब अधीनस्थ समूह स्वयं उन धारणाओं को दोबारा पैदा करने में भाग लेते हैं जो उन्हें सीमित करती हैं।"},{"en":"Popular culture can normalize a social hierarchy without issuing an explicit command in its defense.","native":"लोकप्रिय संस्कृति किसी सामाजिक पदानुक्रम के समर्थन में स्पष्ट आदेश दिए बिना ही उसे सामान्य बना सकती है।"},{"en":"Counter-hegemonic movements succeed by building a credible common sense, not merely by exposing elite interests.","native":"वर्चस्व-विरोधी आंदोलन केवल अभिजात हितों को उजागर करके नहीं, बल्कि एक विश्वसनीय साझा समझ निर्मित करके सफल होते हैं।"}]},"es":{"word":"hegemonía cultural","question":"¿Cómo consigue la hegemonía cultural que valores históricamente contingentes parezcan naturales y universalmente compartidos?","examples":[{"en":"Hegemony is most durable when dominated groups participate in reproducing the assumptions that constrain them.","native":"La hegemonía es más duradera cuando los grupos dominados participan en la reproducción de los supuestos que los limitan."},{"en":"Popular culture can normalize a social hierarchy without issuing an explicit command in its defense.","native":"La cultura popular puede normalizar una jerarquía social sin emitir una orden explícita en su defensa."},{"en":"Counter-hegemonic movements succeed by building a credible common sense, not merely by exposing elite interests.","native":"Los movimientos contrahegemónicos triunfan al construir un sentido común creíble, no solo al revelar los intereses de las élites."}]},"zh":{"word":"文化霸权","question":"文化霸权如何使具有特定历史条件的价值观显得自然，并仿佛为所有人共同接受？","examples":[{"en":"Hegemony is most durable when dominated groups participate in reproducing the assumptions that constrain them.","native":"当受支配群体也参与复制那些限制自身的假设时，霸权最为持久。"},{"en":"Popular culture can normalize a social hierarchy without issuing an explicit command in its defense.","native":"大众文化无需发出明确的维护命令，也能使某种社会等级秩序显得理所当然。"},{"en":"Counter-hegemonic movements succeed by building a credible common sense, not merely by exposing elite interests.","native":"反霸权运动的成功有赖于构建可信的共同认知，而不只是揭露精英利益。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'ideology', 'Can anyone critique ideology from a position entirely free of ideological commitments?', '{"te":{"word":"భావజాలం","question":"భావజాలపరమైన నిబద్ధతలు ఏమాత్రం లేని స్థానం నుంచి ఎవరైనా భావజాలాన్ని విమర్శించగలరా?","examples":[{"en":"Ideology organizes perception by determining which facts seem relevant before argument even begins.","native":"వాదన మొదలుకాకముందే ఏ వాస్తవాలు సంబంధితమైనవిగా కనిపించాలో నిర్ణయించడం ద్వారా భావజాలం మన అవగాహనను క్రమబద్ధీకరిస్తుంది."},{"en":"Calling one''s own framework neutral often conceals the historical interests embedded within it.","native":"తమ సొంత దృక్కోణాన్ని తటస్థమైనదిగా పేర్కొనడం, అందులో నిక్షిప్తమైన చారిత్రక ప్రయోజనాలను తరచుగా దాచిపెడుతుంది."},{"en":"Ideological critique becomes reflexive when it subjects its own categories to the scrutiny it applies elsewhere.","native":"ఇతర వాటిపై ప్రయోగించే పరిశీలనకే తన సొంత వర్గీకరణలను కూడా లోబరచినప్పుడు భావజాల విమర్శ ఆత్మపరిశీలనాత్మకంగా మారుతుంది."}]},"hi":{"word":"विचारधारा","question":"क्या कोई व्यक्ति वैचारिक प्रतिबद्धताओं से पूरी तरह मुक्त स्थिति से विचारधारा की आलोचना कर सकता है?","examples":[{"en":"Ideology organizes perception by determining which facts seem relevant before argument even begins.","native":"तर्क आरंभ होने से पहले ही कौन-से तथ्य प्रासंगिक लगेंगे, यह निर्धारित करके विचारधारा हमारी अनुभूति को व्यवस्थित करती है।"},{"en":"Calling one''s own framework neutral often conceals the historical interests embedded within it.","native":"अपने ही ढाँचे को तटस्थ कहना अक्सर उसमें निहित ऐतिहासिक हितों को छिपा देता है।"},{"en":"Ideological critique becomes reflexive when it subjects its own categories to the scrutiny it applies elsewhere.","native":"वैचारिक आलोचना तब आत्मपरीक्षणशील बनती है जब वह अपनी श्रेणियों को भी उसी जाँच के अधीन करती है जो वह अन्यत्र लागू करती है।"}]},"es":{"word":"ideología","question":"¿Puede alguien criticar la ideología desde una posición completamente libre de compromisos ideológicos?","examples":[{"en":"Ideology organizes perception by determining which facts seem relevant before argument even begins.","native":"La ideología organiza la percepción al determinar qué hechos parecen pertinentes antes incluso de que comience la argumentación."},{"en":"Calling one''s own framework neutral often conceals the historical interests embedded within it.","native":"Calificar de neutral el propio marco suele ocultar los intereses históricos que lleva incorporados."},{"en":"Ideological critique becomes reflexive when it subjects its own categories to the scrutiny it applies elsewhere.","native":"La crítica ideológica se vuelve reflexiva cuando somete sus propias categorías al escrutinio que aplica en otros ámbitos."}]},"zh":{"word":"意识形态","question":"任何人能否站在完全不受意识形态承诺影响的立场上批判意识形态？","examples":[{"en":"Ideology organizes perception by determining which facts seem relevant before argument even begins.","native":"意识形态在论证开始之前就决定哪些事实显得相关，从而组织人们的认知。"},{"en":"Calling one''s own framework neutral often conceals the historical interests embedded within it.","native":"把自己的框架称为中立，往往会掩盖其中蕴含的历史利益。"},{"en":"Ideological critique becomes reflexive when it subjects its own categories to the scrutiny it applies elsewhere.","native":"当意识形态批判也用审视他者的标准检验自身范畴时，它才具有反思性。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'discourse', 'In what ways does public discourse shape the subjects and possibilities it claims merely to describe?', '{"te":{"word":"ప్రజా సంవాదం","question":"కేవలం వర్ణిస్తున్నానని చెప్పుకునే అంశాలను, అవకాశాలను ప్రజా సంవాదం ఏ విధాలుగా రూపుదిద్దుతుంది?","examples":[{"en":"Discourse does not simply name reality; its classifications distribute authority, visibility, and credibility.","native":"సంవాదం వాస్తవానికి కేవలం పేర్లు పెట్టదు; దాని వర్గీకరణలు అధికారం, దృశ్యమానత, విశ్వసనీయతలను పంపిణీ చేస్తాయి."},{"en":"A medical vocabulary can enable treatment while simultaneously narrowing how suffering is understood.","native":"వైద్య పరిభాష చికిత్సను సాధ్యం చేస్తూనే, బాధను అర్థం చేసుకునే విధానాన్ని ఏకకాలంలో పరిమితం చేయగలదు."},{"en":"Changing the terms of debate may transform political possibility more profoundly than winning within the old terms.","native":"పాత నిబంధనల పరిధిలో గెలవడం కంటే చర్చా పదజాలాన్ని మార్చడం రాజకీయ అవకాశాలను మరింత మూలభూతంగా పరివర్తితం చేయవచ్చు."}]},"hi":{"word":"जन-विमर्श","question":"जन-विमर्श उन विषयों और संभावनाओं को किन तरीकों से आकार देता है जिनका वह केवल वर्णन करने का दावा करता है?","examples":[{"en":"Discourse does not simply name reality; its classifications distribute authority, visibility, and credibility.","native":"विमर्श केवल वास्तविकता को नाम नहीं देता; उसकी श्रेणियाँ अधिकार, दृश्यता और विश्वसनीयता का वितरण करती हैं।"},{"en":"A medical vocabulary can enable treatment while simultaneously narrowing how suffering is understood.","native":"चिकित्सकीय शब्दावली उपचार को संभव बनाते हुए पीड़ा को समझने के तरीकों को उसी समय सीमित भी कर सकती है।"},{"en":"Changing the terms of debate may transform political possibility more profoundly than winning within the old terms.","native":"पुरानी शर्तों पर बहस जीतने की तुलना में बहस की शर्तें बदलना राजनीतिक संभावनाओं को कहीं अधिक गहराई से रूपांतरित कर सकता है।"}]},"es":{"word":"discurso público","question":"¿De qué maneras moldea el discurso público los sujetos y las posibilidades que afirma limitarse a describir?","examples":[{"en":"Discourse does not simply name reality; its classifications distribute authority, visibility, and credibility.","native":"El discurso no se limita a nombrar la realidad; sus clasificaciones distribuyen autoridad, visibilidad y credibilidad."},{"en":"A medical vocabulary can enable treatment while simultaneously narrowing how suffering is understood.","native":"Un vocabulario médico puede facilitar el tratamiento y, al mismo tiempo, restringir la manera en que se entiende el sufrimiento."},{"en":"Changing the terms of debate may transform political possibility more profoundly than winning within the old terms.","native":"Cambiar los términos del debate puede transformar la posibilidad política más profundamente que vencer dentro de los términos anteriores."}]},"zh":{"word":"公共话语","question":"公共话语声称自己只是在描述对象和可能性，但它实际上通过哪些方式塑造了二者？","examples":[{"en":"Discourse does not simply name reality; its classifications distribute authority, visibility, and credibility.","native":"话语不只是为现实命名；它的分类也在分配权威、可见性与可信度。"},{"en":"A medical vocabulary can enable treatment while simultaneously narrowing how suffering is understood.","native":"医学词汇可以让治疗成为可能，同时也会收窄人们理解痛苦的方式。"},{"en":"Changing the terms of debate may transform political possibility more profoundly than winning within the old terms.","native":"改变辩论所用的概念框架，可能比在旧框架内取胜更深刻地改变政治可能性。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'narrative', 'When does a unifying national narrative create solidarity, and when does it become an instrument of exclusion?', '{"te":{"word":"జాతీయ కథనం","question":"ఏకీకృత జాతీయ కథనం ఎప్పుడు సంఘీభావాన్ని సృష్టిస్తుంది, ఎప్పుడు అది బహిష్కరణ సాధనంగా మారుతుంది?","examples":[{"en":"Narratives connect scattered events by assigning causes, protagonists, and moral significance.","native":"కారణాలు, ప్రధాన పాత్రలు, నైతిక ప్రాముఖ్యతను నిర్దేశించడం ద్వారా కథనాలు విడివిడిగా ఉన్న సంఘటనలను అనుసంధానిస్తాయి."},{"en":"A shared story can sustain collective sacrifice, yet its silences may erase those who paid the highest price.","native":"ఒక ఉమ్మడి కథ సామూహిక త్యాగాన్ని నిలబెట్టగలదు; అయితే అందులో చెప్పకుండా వదిలేసిన విషయాలు అత్యధిక మూల్యం చెల్లించినవారినే చరిత్ర నుంచి చెరిపివేయవచ్చు."},{"en":"Responsible remembrance preserves narrative coherence without forcing contradictory experiences into artificial consensus.","native":"బాధ్యతాయుతమైన స్మరణ పరస్పర విరుద్ధ అనుభవాలను కృత్రిమ ఏకాభిప్రాయంలోకి బలవంతంగా నెట్టకుండా కథన సమన్వయాన్ని కాపాడుతుంది."}]},"hi":{"word":"राष्ट्रीय आख्यान","question":"एकीकृत राष्ट्रीय आख्यान कब एकजुटता पैदा करता है और कब वह बहिष्कार का साधन बन जाता है?","examples":[{"en":"Narratives connect scattered events by assigning causes, protagonists, and moral significance.","native":"आख्यान कारण, नायक और नैतिक महत्त्व निर्धारित करके बिखरी हुई घटनाओं को आपस में जोड़ते हैं।"},{"en":"A shared story can sustain collective sacrifice, yet its silences may erase those who paid the highest price.","native":"एक साझा कहानी सामूहिक त्याग को बनाए रख सकती है, फिर भी उसकी चुप्पियाँ उन लोगों को मिटा सकती हैं जिन्होंने सबसे बड़ी कीमत चुकाई।"},{"en":"Responsible remembrance preserves narrative coherence without forcing contradictory experiences into artificial consensus.","native":"जिम्मेदार स्मरण परस्पर विरोधी अनुभवों को कृत्रिम सहमति में ढाले बिना आख्यान की सुसंगति बनाए रखता है।"}]},"es":{"word":"narrativa nacional","question":"¿Cuándo crea solidaridad una narrativa nacional unificadora y cuándo se convierte en un instrumento de exclusión?","examples":[{"en":"Narratives connect scattered events by assigning causes, protagonists, and moral significance.","native":"Las narrativas conectan acontecimientos dispersos al asignarles causas, protagonistas y significado moral."},{"en":"A shared story can sustain collective sacrifice, yet its silences may erase those who paid the highest price.","native":"Un relato compartido puede sostener el sacrificio colectivo, pero sus silencios pueden borrar a quienes pagaron el precio más alto."},{"en":"Responsible remembrance preserves narrative coherence without forcing contradictory experiences into artificial consensus.","native":"Una memoria responsable conserva la coherencia narrativa sin forzar experiencias contradictorias a encajar en un consenso artificial."}]},"zh":{"word":"国家叙事","question":"统一的国家叙事何时能够凝聚团结，何时又会成为排斥他者的工具？","examples":[{"en":"Narratives connect scattered events by assigning causes, protagonists, and moral significance.","native":"叙事通过赋予因果关系、主角身份与道德意义，将零散的事件连接起来。"},{"en":"A shared story can sustain collective sacrifice, yet its silences may erase those who paid the highest price.","native":"共同故事能够支撑集体牺牲，但其中的沉默也可能抹去那些付出最大代价的人。"},{"en":"Responsible remembrance preserves narrative coherence without forcing contradictory experiences into artificial consensus.","native":"负责任的纪念既维持叙事的连贯性，也不把相互矛盾的经验强行塞进虚假的共识。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'objectivity', 'Is objectivity best understood as freedom from perspective, or as a disciplined method for testing perspectives against one another?', '{"te":{"word":"నిష్పాక్షికత","question":"నిష్పాక్షికతను ఏ దృక్కోణమూ లేకపోవడంగా అర్థం చేసుకోవాలా, లేక దృక్కోణాలను పరస్పరం పరీక్షించే క్రమబద్ధమైన పద్ధతిగా అర్థం చేసుకోవాలా?","examples":[{"en":"Objectivity requires procedures that make evidence contestable, not an impossible absence of human judgment.","native":"నిష్పాక్షికతకు మానవ విచక్షణ అసలు లేకపోవడం అనే అసాధ్య స్థితి కాదు, సాక్ష్యాన్ని సవాలు చేయగలిగే ప్రక్రియలు అవసరం."},{"en":"Diverse investigators can expose background assumptions that a homogeneous community mistakes for neutral observation.","native":"సజాతీయ పరిశోధక సమూహం తటస్థ పరిశీలనగా పొరబడే నేపథ్య ఊహలను విభిన్న పరిశోధకులు బయటపెట్టగలరు."},{"en":"A claim becomes more reliable when it survives transparent criticism from people positioned to detect different errors.","native":"వేర్వేరు పొరపాట్లను గుర్తించగల స్థానాల్లో ఉన్న వ్యక్తుల పారదర్శక విమర్శను తట్టుకున్నప్పుడు ఒక వాదన మరింత విశ్వసనీయంగా మారుతుంది."}]},"hi":{"word":"वस्तुनिष्ठता","question":"क्या वस्तुनिष्ठता को किसी भी दृष्टिकोण से मुक्ति के रूप में समझना बेहतर है, या दृष्टिकोणों को परस्पर परखने की अनुशासित पद्धति के रूप में?","examples":[{"en":"Objectivity requires procedures that make evidence contestable, not an impossible absence of human judgment.","native":"वस्तुनिष्ठता के लिए ऐसी प्रक्रियाएँ चाहिए जो साक्ष्य को चुनौती के लिए खुला रखें, न कि मानवीय विवेक का असंभव अभाव।"},{"en":"Diverse investigators can expose background assumptions that a homogeneous community mistakes for neutral observation.","native":"विविध शोधकर्ता उन पृष्ठभूमिगत मान्यताओं को उजागर कर सकते हैं जिन्हें एकरूप समुदाय तटस्थ अवलोकन समझ बैठता है।"},{"en":"A claim becomes more reliable when it survives transparent criticism from people positioned to detect different errors.","native":"कोई दावा तब अधिक विश्वसनीय बनता है जब वह अलग-अलग त्रुटियाँ पहचान सकने की स्थिति वाले लोगों की पारदर्शी आलोचना पर खरा उतरता है।"}]},"es":{"word":"objetividad","question":"¿Conviene entender la objetividad como ausencia de perspectiva o como un método disciplinado para contrastar unas perspectivas con otras?","examples":[{"en":"Objectivity requires procedures that make evidence contestable, not an impossible absence of human judgment.","native":"La objetividad exige procedimientos que permitan cuestionar la evidencia, no una ausencia imposible de juicio humano."},{"en":"Diverse investigators can expose background assumptions that a homogeneous community mistakes for neutral observation.","native":"Un grupo diverso de investigadores puede revelar supuestos de fondo que una comunidad homogénea confunde con observación neutral."},{"en":"A claim becomes more reliable when it survives transparent criticism from people positioned to detect different errors.","native":"Una afirmación se vuelve más fiable cuando resiste la crítica transparente de personas situadas para detectar errores distintos."}]},"zh":{"word":"客观性","question":"客观性应被理解为摆脱一切视角，还是一种让不同视角相互检验的严谨方法？","examples":[{"en":"Objectivity requires procedures that make evidence contestable, not an impossible absence of human judgment.","native":"客观性需要让证据可以受到质疑的程序，而不是要求人类判断以不可能的方式彻底缺席。"},{"en":"Diverse investigators can expose background assumptions that a homogeneous community mistakes for neutral observation.","native":"多元的研究者能够揭示同质群体误认为中立观察的背景假设。"},{"en":"A claim becomes more reliable when it survives transparent criticism from people positioned to detect different errors.","native":"一项主张若能经受来自不同位置、能够发现不同错误之人的公开批评，就会变得更加可靠。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'subjectivity', 'Can subjectivity be treated as a source of knowledge rather than merely an obstacle to objective judgment?', '{"te":{"word":"వ్యక్తినిష్ఠత","question":"వ్యక్తినిష్ఠతను నిష్పాక్షిక నిర్ణయానికి కేవలం అడ్డంకిగా కాకుండా జ్ఞానానికి ఒక మూలంగా పరిగణించవచ్చా?","examples":[{"en":"First-person experience reveals dimensions of pain that no external measurement can exhaust.","native":"బాధలోని కొన్ని కోణాలను వ్యక్తిగత ప్రత్యక్ష అనుభవం వెల్లడిస్తుంది; ఏ బాహ్య కొలమానమూ వాటిని సంపూర్ణంగా పట్టుకోలేదు."},{"en":"Subjectivity is socially formed, yet that dependence does not make an individual''s testimony interchangeable with anyone else''s.","native":"వ్యక్తినిష్ఠత సామాజికంగా రూపుదిద్దుకుంటుంది; అయినప్పటికీ ఆ ఆధారపడటం వల్ల ఒక వ్యక్తి సాక్ష్యాన్ని మరెవరి సాక్ష్యంతోనైనా సమానంగా మార్చివేయలేం."},{"en":"Critical inquiry should examine perspective while preserving the situated knowledge that perspective makes possible.","native":"విమర్శనాత్మక పరిశోధన దృక్కోణాన్ని పరిశీలిస్తూనే, ఆ దృక్కోణం సాధ్యం చేసే సందర్భాధారిత జ్ఞానాన్ని కాపాడాలి."}]},"hi":{"word":"व्यक्तिनिष्ठता","question":"क्या व्यक्तिनिष्ठता को वस्तुनिष्ठ निर्णय की केवल एक बाधा के बजाय ज्ञान के स्रोत के रूप में देखा जा सकता है?","examples":[{"en":"First-person experience reveals dimensions of pain that no external measurement can exhaust.","native":"प्रत्यक्ष निजी अनुभव पीड़ा के ऐसे आयाम प्रकट करता है जिन्हें कोई बाहरी माप पूरी तरह नहीं समेट सकता।"},{"en":"Subjectivity is socially formed, yet that dependence does not make an individual''s testimony interchangeable with anyone else''s.","native":"व्यक्तिनिष्ठता सामाजिक रूप से निर्मित होती है, फिर भी यह निर्भरता किसी व्यक्ति की गवाही को किसी और की गवाही से अदला-बदली योग्य नहीं बनाती।"},{"en":"Critical inquiry should examine perspective while preserving the situated knowledge that perspective makes possible.","native":"आलोचनात्मक जाँच को दृष्टिकोण का परीक्षण करते हुए उस संदर्भगत ज्ञान को बचाए रखना चाहिए जिसे वही दृष्टिकोण संभव बनाता है।"}]},"es":{"word":"subjetividad","question":"¿Puede considerarse la subjetividad una fuente de conocimiento en lugar de un mero obstáculo para el juicio objetivo?","examples":[{"en":"First-person experience reveals dimensions of pain that no external measurement can exhaust.","native":"La experiencia en primera persona revela dimensiones del dolor que ninguna medición externa puede agotar."},{"en":"Subjectivity is socially formed, yet that dependence does not make an individual''s testimony interchangeable with anyone else''s.","native":"La subjetividad se forma socialmente, pero esa dependencia no vuelve intercambiable el testimonio de una persona con el de cualquier otra."},{"en":"Critical inquiry should examine perspective while preserving the situated knowledge that perspective makes possible.","native":"La investigación crítica debe examinar la perspectiva y, a la vez, preservar el conocimiento situado que esa perspectiva hace posible."}]},"zh":{"word":"主体性","question":"主体性是否可以被视为知识的来源，而不只是客观判断的障碍？","examples":[{"en":"First-person experience reveals dimensions of pain that no external measurement can exhaust.","native":"第一人称经验能够揭示痛苦的某些维度，而任何外部测量都无法将其穷尽。"},{"en":"Subjectivity is socially formed, yet that dependence does not make an individual''s testimony interchangeable with anyone else''s.","native":"主体性由社会塑造，但这种依赖关系并不意味着一个人的证言可以被任何他人的证言替代。"},{"en":"Critical inquiry should examine perspective while preserving the situated knowledge that perspective makes possible.","native":"批判性探究应当审视视角，同时保留正是该视角所产生的情境化知识。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'paradox', 'What can a genuine paradox reveal about the limits of a conceptual framework rather than the failure of ordinary logic?', '{"te":{"word":"విరోధాభాసం","question":"ఒక నిజమైన విరోధాభాసం సాధారణ తర్కం వైఫల్యాన్ని కాకుండా భావనాత్మక చట్రం పరిమితులను ఎలా వెల్లడించగలదు?","examples":[{"en":"A paradox may expose assumptions that remain invisible while each premise is considered in isolation.","native":"ప్రతి ప్రతిపాదనను విడివిడిగా పరిగణించినప్పుడు కనిపించకుండా ఉండే ఊహలను ఒక విరోధాభాసం బయటపెట్టవచ్చు."},{"en":"Resolving the contradiction sometimes requires revising the categories that made the problem intelligible.","native":"వైరుధ్యాన్ని పరిష్కరించడానికి కొన్నిసార్లు ఆ సమస్యను అర్థం చేసుకునేలా చేసిన వర్గీకరణలనే సవరించాల్సి ఉంటుంది."},{"en":"Political tolerance becomes paradoxical when protecting openness appears to require restricting those committed to destroying it.","native":"బహిరంగతను కాపాడాలంటే దానిని నాశనం చేయడానికి కట్టుబడినవారిని పరిమితం చేయాల్సిందేనని కనిపించినప్పుడు రాజకీయ సహనం విరోధాభాసంగా మారుతుంది."}]},"hi":{"word":"विरोधाभास","question":"कोई वास्तविक विरोधाभास सामान्य तर्क की विफलता के बजाय किसी वैचारिक ढाँचे की सीमाओं के बारे में क्या प्रकट कर सकता है?","examples":[{"en":"A paradox may expose assumptions that remain invisible while each premise is considered in isolation.","native":"जब प्रत्येक आधार-वाक्य पर अलग-अलग विचार किया जाता है, तब अदृश्य रहने वाली मान्यताओं को कोई विरोधाभास उजागर कर सकता है।"},{"en":"Resolving the contradiction sometimes requires revising the categories that made the problem intelligible.","native":"विरोध को सुलझाने के लिए कभी-कभी उन श्रेणियों को ही संशोधित करना पड़ता है जिन्होंने समस्या को समझने योग्य बनाया था।"},{"en":"Political tolerance becomes paradoxical when protecting openness appears to require restricting those committed to destroying it.","native":"जब खुलेपन की रक्षा के लिए उसे नष्ट करने को प्रतिबद्ध लोगों को सीमित करना आवश्यक लगे, तब राजनीतिक सहिष्णुता विरोधाभासी बन जाती है।"}]},"es":{"word":"paradoja","question":"¿Qué puede revelar una paradoja genuina sobre los límites de un marco conceptual, en vez de sobre un fallo de la lógica ordinaria?","examples":[{"en":"A paradox may expose assumptions that remain invisible while each premise is considered in isolation.","native":"Una paradoja puede revelar supuestos que permanecen invisibles cuando cada premisa se considera por separado."},{"en":"Resolving the contradiction sometimes requires revising the categories that made the problem intelligible.","native":"Resolver la contradicción exige a veces revisar las categorías que hicieron inteligible el problema."},{"en":"Political tolerance becomes paradoxical when protecting openness appears to require restricting those committed to destroying it.","native":"La tolerancia política se vuelve paradójica cuando proteger la apertura parece exigir que se restrinja a quienes se proponen destruirla."}]},"zh":{"word":"悖论","question":"真正的悖论如何揭示概念框架的局限，而不只是表明普通逻辑失效？","examples":[{"en":"A paradox may expose assumptions that remain invisible while each premise is considered in isolation.","native":"当每个前提都被孤立考察时，一些假设会隐而不见，而悖论可能将它们揭示出来。"},{"en":"Resolving the contradiction sometimes requires revising the categories that made the problem intelligible.","native":"解决矛盾有时需要修正那些原本使问题变得可理解的范畴。"},{"en":"Political tolerance becomes paradoxical when protecting openness appears to require restricting those committed to destroying it.","native":"当维护开放似乎必须限制那些决意摧毁开放的人时，政治宽容便呈现出悖论。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'causality', 'How should we reason about causality when controlled experiments are impossible and multiple mechanisms interact?', '{"te":{"word":"కారణత్వం","question":"నియంత్రిత ప్రయోగాలు అసాధ్యమైనప్పుడు, అనేక యంత్రాంగాలు పరస్పరం ప్రభావితం చేసుకుంటున్నప్పుడు కారణత్వం గురించి మనం ఎలా తర్కించాలి?","examples":[{"en":"Correlation becomes causally persuasive only when a plausible mechanism survives serious attempts to rule out alternatives.","native":"ప్రత్యామ్నాయ వివరణలను తోసిపుచ్చేందుకు చేసిన గంభీర ప్రయత్నాలను ఒక సంభావ్య యంత్రాంగం తట్టుకున్నప్పుడే సహసంబంధం కారణపరంగా నమ్మదగినదవుతుంది."},{"en":"Historical causes are often conjunctural: no single condition is sufficient, but their configuration produces the outcome.","native":"చారిత్రక కారణాలు తరచుగా సంయుక్తంగా పనిచేస్తాయి: ఏ ఒక్క పరిస్థితీ సరిపోదు, కానీ వాటి అమరిక ఫలితాన్ని ఉత్పత్తి చేస్తుంది."},{"en":"Counterfactual reasoning clarifies causal claims, although imagined alternatives remain constrained by incomplete evidence.","native":"అసంపూర్ణ సాక్ష్యం ఊహించిన ప్రత్యామ్నాయాలను పరిమితం చేసినప్పటికీ, ప్రతివాస్తవిక తర్కం కారణసంబంధ వాదనలను స్పష్టం చేస్తుంది."}]},"hi":{"word":"कारणता","question":"जब नियंत्रित प्रयोग असंभव हों और अनेक तंत्र परस्पर क्रिया करें, तब हमें कारणता के बारे में कैसे तर्क करना चाहिए?","examples":[{"en":"Correlation becomes causally persuasive only when a plausible mechanism survives serious attempts to rule out alternatives.","native":"सहसंबंध तभी कारण की दृष्टि से विश्वसनीय बनता है जब कोई संभाव्य तंत्र वैकल्पिक व्याख्याओं को खारिज करने के गंभीर प्रयासों पर खरा उतरे।"},{"en":"Historical causes are often conjunctural: no single condition is sufficient, but their configuration produces the outcome.","native":"ऐतिहासिक कारण अक्सर संयुक्त होते हैं: कोई एक परिस्थिति पर्याप्त नहीं होती, किंतु उनका विन्यास परिणाम उत्पन्न करता है।"},{"en":"Counterfactual reasoning clarifies causal claims, although imagined alternatives remain constrained by incomplete evidence.","native":"अपूर्ण साक्ष्य कल्पित विकल्पों को सीमित रखते हैं, फिर भी प्रतितथ्यात्मक तर्क कारण-संबंधी दावों को स्पष्ट करता है।"}]},"es":{"word":"causalidad","question":"¿Cómo debemos razonar sobre la causalidad cuando los experimentos controlados son imposibles e interactúan múltiples mecanismos?","examples":[{"en":"Correlation becomes causally persuasive only when a plausible mechanism survives serious attempts to rule out alternatives.","native":"Una correlación solo resulta convincente como causa cuando un mecanismo plausible resiste intentos rigurosos de descartar alternativas."},{"en":"Historical causes are often conjunctural: no single condition is sufficient, but their configuration produces the outcome.","native":"Las causas históricas suelen ser coyunturales: ninguna condición basta por sí sola, pero su configuración produce el resultado."},{"en":"Counterfactual reasoning clarifies causal claims, although imagined alternatives remain constrained by incomplete evidence.","native":"El razonamiento contrafáctico esclarece las afirmaciones causales, aunque las alternativas imaginadas siguen limitadas por evidencia incompleta."}]},"zh":{"word":"因果关系","question":"当受控实验无法进行且多种机制相互作用时，我们应当如何推断因果关系？","examples":[{"en":"Correlation becomes causally persuasive only when a plausible mechanism survives serious attempts to rule out alternatives.","native":"只有当某种合理机制经受住排除其他解释的严谨尝试时，相关性才具有因果说服力。"},{"en":"Historical causes are often conjunctural: no single condition is sufficient, but their configuration produces the outcome.","native":"历史原因往往共同发挥作用：没有任何单一条件足够充分，但它们的组合会产生结果。"},{"en":"Counterfactual reasoning clarifies causal claims, although imagined alternatives remain constrained by incomplete evidence.","native":"反事实推理能够澄清因果主张，尽管想象中的其他可能仍受到不完整证据的限制。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'agency', 'How can human agency remain meaningful if choices are shaped by institutions, habit, and material constraint?', '{"te":{"word":"కర్తృత్వం","question":"ఎంపికలు సంస్థలు, అలవాట్లు, భౌతిక పరిమితుల వల్ల రూపుదిద్దుకుంటే మానవ కర్తృత్వం ఎలా అర్థవంతంగా నిలవగలదు?","examples":[{"en":"Agency need not imply unbounded freedom; it can consist in recognizing and altering the conditions of action.","native":"కర్తృత్వం అపరిమిత స్వేచ్ఛను సూచించాల్సిన అవసరం లేదు; చర్యకు సంబంధించిన పరిస్థితులను గుర్తించి మార్చడంలో అది ఉండవచ్చు."},{"en":"Structures constrain individuals, but they persist only through practices that people may reproduce or contest.","native":"నిర్మాణాలు వ్యక్తులను పరిమితం చేస్తాయి; అయితే ప్రజలు పునరుత్పత్తి చేయగల లేదా సవాలు చేయగల ఆచరణల ద్వారానే అవి కొనసాగుతాయి."},{"en":"Collective agency emerges when dispersed grievances become coordinated commitments and durable institutions.","native":"చెల్లాచెదురుగా ఉన్న అసంతృప్తులు సమన్వయమైన నిబద్ధతలుగా, స్థిరమైన సంస్థలుగా మారినప్పుడు సామూహిక కర్తృత్వం ఉద్భవిస్తుంది."}]},"hi":{"word":"कर्तृत्व","question":"यदि विकल्पों को संस्थाएँ, आदतें और भौतिक सीमाएँ आकार देती हैं, तो मानवीय कर्तृत्व अर्थपूर्ण कैसे बना रह सकता है?","examples":[{"en":"Agency need not imply unbounded freedom; it can consist in recognizing and altering the conditions of action.","native":"कर्तृत्व का अर्थ असीम स्वतंत्रता होना आवश्यक नहीं; वह कार्य करने की परिस्थितियों को पहचानने और बदलने में निहित हो सकता है।"},{"en":"Structures constrain individuals, but they persist only through practices that people may reproduce or contest.","native":"संरचनाएँ व्यक्तियों को सीमित करती हैं, लेकिन वे केवल उन प्रथाओं के माध्यम से बनी रहती हैं जिन्हें लोग दोहरा सकते हैं या चुनौती दे सकते हैं।"},{"en":"Collective agency emerges when dispersed grievances become coordinated commitments and durable institutions.","native":"सामूहिक कर्तृत्व तब उभरता है जब बिखरी शिकायतें समन्वित प्रतिबद्धताओं और टिकाऊ संस्थाओं में बदलती हैं।"}]},"es":{"word":"capacidad de acción","question":"¿Cómo puede conservar sentido la capacidad humana de actuar si las instituciones, los hábitos y las restricciones materiales moldean nuestras elecciones?","examples":[{"en":"Agency need not imply unbounded freedom; it can consist in recognizing and altering the conditions of action.","native":"La capacidad de acción no tiene por qué implicar una libertad ilimitada; puede consistir en reconocer y modificar las condiciones para actuar."},{"en":"Structures constrain individuals, but they persist only through practices that people may reproduce or contest.","native":"Las estructuras limitan a las personas, pero solo persisten mediante prácticas que estas pueden reproducir o impugnar."},{"en":"Collective agency emerges when dispersed grievances become coordinated commitments and durable institutions.","native":"La capacidad de acción colectiva surge cuando agravios dispersos se convierten en compromisos coordinados e instituciones duraderas."}]},"zh":{"word":"能动性","question":"如果选择受到制度、习惯和物质限制的塑造，人的能动性如何仍然具有意义？","examples":[{"en":"Agency need not imply unbounded freedom; it can consist in recognizing and altering the conditions of action.","native":"能动性不必意味着不受限制的自由；它可以体现在认识并改变行动条件的能力上。"},{"en":"Structures constrain individuals, but they persist only through practices that people may reproduce or contest.","native":"结构会限制个人，但它们只能通过人们可能重复或挑战的实践延续下去。"},{"en":"Collective agency emerges when dispersed grievances become coordinated commitments and durable institutions.","native":"当分散的不满转化为协调一致的承诺与持久的制度时，集体能动性便会形成。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'accountability', 'What form should accountability take when harm results from a complex system rather than one clearly culpable individual?', '{"te":{"word":"జవాబుదారీతనం","question":"హాని స్పష్టంగా దోషిగా ఉన్న ఒక వ్యక్తి వల్ల కాకుండా సంక్లిష్ట వ్యవస్థ వల్ల కలిగినప్పుడు జవాబుదారీతనం ఏ రూపం తీసుకోవాలి?","examples":[{"en":"Accountability fails when distributed responsibility becomes an excuse for every participant to deny meaningful control.","native":"బాధ్యత విభజించబడి ఉండటమే ప్రతి భాగస్వామీ తనకు గణనీయమైన నియంత్రణ లేదని చెప్పడానికి సాకుగా మారినప్పుడు జవాబుదారీతనం విఫలమవుతుంది."},{"en":"Repairing harm may require institutional reform, restitution, and public explanation beyond the punishment of one actor.","native":"హానిని సరిచేయడానికి ఒక వ్యక్తిని శిక్షించడంతో పాటు సంస్థాగత సంస్కరణ, నష్టపరిహారం, బహిరంగ వివరణ కూడా అవసరం కావచ్చు."},{"en":"A fair process distinguishes causal contribution from moral blame while refusing to let complexity erase obligation.","native":"సంక్లిష్టత బాధ్యతను చెరిపివేయడానికి వీల్లేకుండా, న్యాయమైన ప్రక్రియ కారణపరమైన వాటాను నైతిక నింద నుంచి వేరు చేస్తుంది."}]},"hi":{"word":"जवाबदेही","question":"जब हानि किसी स्पष्ट रूप से दोषी व्यक्ति के बजाय जटिल व्यवस्था से उत्पन्न हो, तब जवाबदेही का स्वरूप क्या होना चाहिए?","examples":[{"en":"Accountability fails when distributed responsibility becomes an excuse for every participant to deny meaningful control.","native":"जब बँटी हुई जिम्मेदारी प्रत्येक सहभागी के लिए अपने सार्थक नियंत्रण से इनकार करने का बहाना बन जाती है, तब जवाबदेही विफल होती है।"},{"en":"Repairing harm may require institutional reform, restitution, and public explanation beyond the punishment of one actor.","native":"हानि की भरपाई के लिए किसी एक व्यक्ति को दंडित करने से आगे बढ़कर संस्थागत सुधार, प्रतिपूर्ति और सार्वजनिक स्पष्टीकरण की आवश्यकता हो सकती है।"},{"en":"A fair process distinguishes causal contribution from moral blame while refusing to let complexity erase obligation.","native":"एक निष्पक्ष प्रक्रिया कारणगत योगदान को नैतिक दोष से अलग करती है और जटिलता को दायित्व मिटाने का अवसर नहीं देती।"}]},"es":{"word":"rendición de cuentas","question":"¿Qué forma debería adoptar la rendición de cuentas cuando el daño procede de un sistema complejo y no de una persona claramente culpable?","examples":[{"en":"Accountability fails when distributed responsibility becomes an excuse for every participant to deny meaningful control.","native":"La rendición de cuentas fracasa cuando la responsabilidad distribuida sirve de excusa para que cada participante niegue haber ejercido un control significativo."},{"en":"Repairing harm may require institutional reform, restitution, and public explanation beyond the punishment of one actor.","native":"Reparar el daño puede exigir reformas institucionales, restitución y explicaciones públicas, además de castigar a un solo actor."},{"en":"A fair process distinguishes causal contribution from moral blame while refusing to let complexity erase obligation.","native":"Un proceso justo distingue la contribución causal de la culpa moral sin permitir que la complejidad borre la obligación."}]},"zh":{"word":"问责","question":"当伤害源于一个复杂系统，而非某个责任明确的个人时，问责应当采取何种形式？","examples":[{"en":"Accountability fails when distributed responsibility becomes an excuse for every participant to deny meaningful control.","native":"当责任分散成为每位参与者否认自己拥有实质控制力的借口时，问责就会失效。"},{"en":"Repairing harm may require institutional reform, restitution, and public explanation beyond the punishment of one actor.","native":"修复伤害可能不仅要惩罚某一行为者，还需要制度改革、补偿以及向公众作出解释。"},{"en":"A fair process distinguishes causal contribution from moral blame while refusing to let complexity erase obligation.","native":"公正的程序既区分因果贡献与道德过错，也拒绝让复杂性抹去应尽的义务。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'authenticity', 'Is authenticity a matter of discovering a stable inner self, or of taking responsibility for the self one continually creates?', '{"te":{"word":"ప్రామాణికత","question":"ప్రామాణికత అంటే స్థిరమైన అంతరాత్మను కనుగొనడమా, లేక నిరంతరం సృష్టించుకుంటున్న స్వరూపానికి బాధ్యత వహించడమా?","examples":[{"en":"Authenticity cannot mean expressing every impulse, because reflection and restraint may also embody one''s deepest commitments.","native":"ప్రామాణికత అంటే ప్రతి ఆవేశాన్నీ వ్యక్తం చేయడం కాదు; ఎందుకంటే ఆత్మపరిశీలన, సంయమనం కూడా ఒకరి అత్యంత లోతైన నిబద్ధతలను ప్రతిబింబించవచ్చు."},{"en":"A social role becomes inauthentic when it is performed as an excuse to disown the choices the role still permits.","native":"ఒక సామాజిక పాత్ర ఇప్పటికీ అనుమతించే ఎంపికలను తనవి కావని చెప్పడానికి సాకుగా దానిని పోషించినప్పుడు ఆ పాత్ర ప్రామాణికతను కోల్పోతుంది."},{"en":"The pursuit of authenticity is paradoxically shaped by cultural ideals about what an original life should look like.","native":"ఒక విలక్షణమైన జీవితం ఎలా ఉండాలనే సాంస్కృతిక ఆదర్శాలే ప్రామాణికత సాధనను విరోధాభాసంగా రూపుదిద్దుతాయి."}]},"hi":{"word":"प्रामाणिकता","question":"क्या प्रामाणिकता किसी स्थिर अंतर्मन को खोजने का विषय है, या निरंतर रचे जा रहे अपने स्वरूप की जिम्मेदारी लेने का?","examples":[{"en":"Authenticity cannot mean expressing every impulse, because reflection and restraint may also embody one''s deepest commitments.","native":"प्रामाणिकता का अर्थ हर आवेग को व्यक्त करना नहीं हो सकता, क्योंकि आत्मचिंतन और संयम भी किसी की गहनतम प्रतिबद्धताओं को मूर्त रूप दे सकते हैं।"},{"en":"A social role becomes inauthentic when it is performed as an excuse to disown the choices the role still permits.","native":"कोई सामाजिक भूमिका तब अप्रामाणिक बन जाती है जब उसे उन विकल्पों की जिम्मेदारी से बचने के बहाने के रूप में निभाया जाए जिनकी वह भूमिका अब भी अनुमति देती है।"},{"en":"The pursuit of authenticity is paradoxically shaped by cultural ideals about what an original life should look like.","native":"प्रामाणिकता की खोज को इस बारे में सांस्कृतिक आदर्श ही विरोधाभासी ढंग से आकार देते हैं कि एक मौलिक जीवन कैसा दिखना चाहिए।"}]},"es":{"word":"autenticidad","question":"¿Consiste la autenticidad en descubrir un yo interior estable o en responsabilizarse del yo que uno crea continuamente?","examples":[{"en":"Authenticity cannot mean expressing every impulse, because reflection and restraint may also embody one''s deepest commitments.","native":"La autenticidad no puede significar expresar cada impulso, porque la reflexión y la moderación también pueden encarnar los compromisos más profundos de una persona."},{"en":"A social role becomes inauthentic when it is performed as an excuse to disown the choices the role still permits.","native":"Un papel social se vuelve inauténtico cuando se desempeña como excusa para repudiar las elecciones que ese papel todavía permite."},{"en":"The pursuit of authenticity is paradoxically shaped by cultural ideals about what an original life should look like.","native":"La búsqueda de autenticidad está moldeada, paradójicamente, por ideales culturales sobre el aspecto que debe tener una vida original."}]},"zh":{"word":"本真性","question":"本真性是发现一个稳定的内在自我，还是为自己不断塑造的自我承担责任？","examples":[{"en":"Authenticity cannot mean expressing every impulse, because reflection and restraint may also embody one''s deepest commitments.","native":"本真性不能等同于表达每一种冲动，因为反思与克制也可能体现一个人最深层的承诺。"},{"en":"A social role becomes inauthentic when it is performed as an excuse to disown the choices the role still permits.","native":"如果一个人把扮演社会角色当作逃避该角色仍允许之选择的借口，这个角色就变得不再真实。"},{"en":"The pursuit of authenticity is paradoxically shaped by cultural ideals about what an original life should look like.","native":"颇具悖论意味的是，对于独特人生应当呈现何种样貌的文化理想，塑造了人们对本真性的追求。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'alienation', 'How does alienation differ from ordinary dissatisfaction, and what social arrangements make it systemic?', '{"te":{"word":"పరాయీకరణ","question":"పరాయీకరణ సాధారణ అసంతృప్తికి ఎలా భిన్నంగా ఉంటుంది, ఏ సామాజిక ఏర్పాట్లు దానిని వ్యవస్థాగతంగా మారుస్తాయి?","examples":[{"en":"Alienated workers may recognize themselves neither in the product of their labor nor in the purposes it serves.","native":"పరాయీకరణకు లోనైన కార్మికులు తమ శ్రమ ఫలితంలో గానీ, అది నెరవేర్చే లక్ష్యాల్లో గానీ తమను తాము గుర్తించలేకపోవచ్చు."},{"en":"Consumer choice can mask alienation when abundant options leave the underlying terms of participation untouched.","native":"ఎన్నో ప్రత్యామ్నాయాలు ఉన్నప్పటికీ పాల్గొనే ప్రాథమిక షరతులు మారకుండా ఉంటే, వినియోగదారుల ఎంపిక పరాయీకరణను మరుగుపరచగలదు."},{"en":"Overcoming alienation requires more than private well-being; it requires meaningful influence over shared conditions.","native":"పరాయీకరణను అధిగమించడానికి వ్యక్తిగత శ్రేయస్సు మాత్రమే సరిపోదు; ఉమ్మడి పరిస్థితులపై అర్థవంతమైన ప్రభావం కూడా అవసరం."}]},"hi":{"word":"अलगाव","question":"अलगाव सामान्य असंतोष से किस प्रकार भिन्न है और कौन-सी सामाजिक व्यवस्थाएँ इसे प्रणालीगत बनाती हैं?","examples":[{"en":"Alienated workers may recognize themselves neither in the product of their labor nor in the purposes it serves.","native":"अलगावग्रस्त श्रमिक न तो अपने श्रम के उत्पाद में और न ही उसके द्वारा पूरे किए जाने वाले उद्देश्यों में स्वयं को पहचान पाते हैं।"},{"en":"Consumer choice can mask alienation when abundant options leave the underlying terms of participation untouched.","native":"जब प्रचुर विकल्प भागीदारी की बुनियादी शर्तों को जस का तस छोड़ देते हैं, तब उपभोक्ता की पसंद अलगाव को छिपा सकती है।"},{"en":"Overcoming alienation requires more than private well-being; it requires meaningful influence over shared conditions.","native":"अलगाव पर काबू पाने के लिए निजी कल्याण से अधिक चाहिए; साझा परिस्थितियों पर सार्थक प्रभाव भी आवश्यक है।"}]},"es":{"word":"alienación","question":"¿En qué se diferencia la alienación de la insatisfacción corriente y qué estructuras sociales la vuelven sistémica?","examples":[{"en":"Alienated workers may recognize themselves neither in the product of their labor nor in the purposes it serves.","native":"Los trabajadores alienados pueden no reconocerse ni en el producto de su trabajo ni en los fines a los que este sirve."},{"en":"Consumer choice can mask alienation when abundant options leave the underlying terms of participation untouched.","native":"La elección del consumidor puede ocultar la alienación cuando la abundancia de opciones no altera las condiciones subyacentes de participación."},{"en":"Overcoming alienation requires more than private well-being; it requires meaningful influence over shared conditions.","native":"Superar la alienación exige algo más que bienestar privado: requiere una influencia significativa sobre las condiciones compartidas."}]},"zh":{"word":"异化","question":"异化与一般的不满有何区别，哪些社会安排会使它成为一种系统性现象？","examples":[{"en":"Alienated workers may recognize themselves neither in the product of their labor nor in the purposes it serves.","native":"异化的劳动者可能既无法在自己的劳动产品中认出自我，也无法认同产品所服务的目的。"},{"en":"Consumer choice can mask alienation when abundant options leave the underlying terms of participation untouched.","native":"当丰富的选项丝毫未改变参与的根本条件时，消费者选择反而可能掩盖异化。"},{"en":"Overcoming alienation requires more than private well-being; it requires meaningful influence over shared conditions.","native":"克服异化需要的不只是个人福祉，还需要对共同生活条件拥有实质性影响力。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'conformity', 'When is conformity a reasonable basis for coordination, and when does it become a surrender of moral judgment?', '{"te":{"word":"అనుగుణత","question":"అనుగుణత ఎప్పుడు సమన్వయానికి సహేతుకమైన ప్రాతిపదికగా ఉంటుంది, ఎప్పుడు అది నైతిక విచక్షణను వదులుకోవడంగా మారుతుంది?","examples":[{"en":"Conformity reduces the cost of coordination, but it can also prevent a group from recognizing collectively maintained errors.","native":"అనుగుణత సమన్వయ వ్యయాన్ని తగ్గిస్తుంది; అయితే ఒక సమూహం సామూహికంగా కొనసాగిస్తున్న పొరపాట్లను గుర్తించకుండా కూడా అడ్డుకోగలదు."},{"en":"People often comply not because they agree, but because each mistakenly assumes that everyone else does.","native":"ప్రజలు తరచుగా ఏకీభవించడం వల్ల కాకుండా, మిగతా వారందరూ ఏకీభవిస్తున్నారని ప్రతి ఒక్కరూ పొరపాటుగా భావించడం వల్ల అనుసరిస్తారు."},{"en":"Moral courage involves judging which conventions enable mutual trust and which merely protect established power.","native":"ఏ సంప్రదాయాలు పరస్పర విశ్వాసాన్ని సాధ్యం చేస్తాయో, ఏవి కేవలం స్థిరపడిన అధికారాన్ని కాపాడతాయో నిర్ణయించడం నైతిక ధైర్యంలో భాగం."}]},"hi":{"word":"अनुरूपता","question":"अनुरूपता कब समन्वय का उचित आधार होती है और कब वह नैतिक विवेक का समर्पण बन जाती है?","examples":[{"en":"Conformity reduces the cost of coordination, but it can also prevent a group from recognizing collectively maintained errors.","native":"अनुरूपता समन्वय की लागत घटाती है, किंतु वह किसी समूह को सामूहिक रूप से बनाए रखी गई त्रुटियाँ पहचानने से भी रोक सकती है।"},{"en":"People often comply not because they agree, but because each mistakenly assumes that everyone else does.","native":"लोग प्रायः सहमत होने के कारण नहीं, बल्कि इसलिए अनुपालन करते हैं कि हर व्यक्ति गलती से मान लेता है कि बाकी सभी सहमत हैं।"},{"en":"Moral courage involves judging which conventions enable mutual trust and which merely protect established power.","native":"नैतिक साहस में यह परखना शामिल है कि कौन-सी परंपराएँ आपसी विश्वास संभव बनाती हैं और कौन-सी केवल स्थापित सत्ता की रक्षा करती हैं।"}]},"es":{"word":"conformidad","question":"¿Cuándo constituye la conformidad una base razonable para coordinarse y cuándo supone renunciar al juicio moral?","examples":[{"en":"Conformity reduces the cost of coordination, but it can also prevent a group from recognizing collectively maintained errors.","native":"La conformidad reduce el coste de la coordinación, pero también puede impedir que un grupo reconozca errores mantenidos colectivamente."},{"en":"People often comply not because they agree, but because each mistakenly assumes that everyone else does.","native":"La gente suele acatar no porque esté de acuerdo, sino porque cada persona supone erróneamente que las demás sí lo están."},{"en":"Moral courage involves judging which conventions enable mutual trust and which merely protect established power.","native":"El valor moral implica juzgar qué convenciones posibilitan la confianza mutua y cuáles se limitan a proteger el poder establecido."}]},"zh":{"word":"从众","question":"从众何时是实现协调的合理基础，何时又会变成对道德判断的放弃？","examples":[{"en":"Conformity reduces the cost of coordination, but it can also prevent a group from recognizing collectively maintained errors.","native":"从众降低了协调成本，但也可能使群体无法认识到由大家共同维持的错误。"},{"en":"People often comply not because they agree, but because each mistakenly assumes that everyone else does.","native":"人们服从往往并非因为赞同，而是因为每个人都误以为其他人赞同。"},{"en":"Moral courage involves judging which conventions enable mutual trust and which merely protect established power.","native":"道德勇气包括判断哪些惯例促进相互信任，哪些惯例只是维护既有权力。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'dissent', 'What obligations do dissenters owe a democratic community whose decisions they regard as profoundly unjust?', '{"te":{"word":"అసమ్మతి","question":"తీవ్ర అన్యాయమైన నిర్ణయాలు తీసుకుందని భావించే ప్రజాస్వామ్య సమాజం పట్ల అసమ్మతివాదులకు ఎలాంటి బాధ్యతలు ఉంటాయి?","examples":[{"en":"Dissent affirms democratic membership when it appeals to principles the community professes but fails to honor.","native":"సమాజం ప్రకటించే కానీ పాటించడంలో విఫలమయ్యే సూత్రాలనే ప్రస్తావించినప్పుడు అసమ్మతి ప్రజాస్వామ్య సభ్యత్వాన్ని ధ్రువీకరిస్తుంది."},{"en":"Civil disobedience makes a breach of law public and accountable rather than treating private conviction as automatic exemption.","native":"వ్యక్తిగత నమ్మకమే స్వయంచాలక మినహాయింపు అని భావించకుండా, పౌర అవిధేయత చట్ట ఉల్లంఘనను బహిరంగంగా, జవాబుదారీతనంతో చేపడుతుంది."},{"en":"A democracy that tolerates only harmless criticism deprives itself of the warnings most capable of correcting systemic failure.","native":"హానిరహిత విమర్శను మాత్రమే సహించే ప్రజాస్వామ్యం వ్యవస్థాగత వైఫల్యాన్ని సరిచేయగల అత్యంత శక్తివంతమైన హెచ్చరికలను కోల్పోతుంది."}]},"hi":{"word":"असहमति","question":"असहमति रखने वालों के उस लोकतांत्रिक समुदाय के प्रति क्या दायित्व हैं जिसके निर्णयों को वे घोर अन्यायपूर्ण मानते हैं?","examples":[{"en":"Dissent affirms democratic membership when it appeals to principles the community professes but fails to honor.","native":"असहमति तब लोकतांत्रिक सदस्यता की पुष्टि करती है जब वह उन सिद्धांतों की दुहाई देती है जिन्हें समुदाय मानने का दावा तो करता है, पर निभाता नहीं।"},{"en":"Civil disobedience makes a breach of law public and accountable rather than treating private conviction as automatic exemption.","native":"सविनय अवज्ञा निजी विश्वास को स्वतः छूट मानने के बजाय कानून के उल्लंघन को सार्वजनिक और जवाबदेह बनाती है।"},{"en":"A democracy that tolerates only harmless criticism deprives itself of the warnings most capable of correcting systemic failure.","native":"जो लोकतंत्र केवल निरापद आलोचना सहता है, वह स्वयं को उन चेतावनियों से वंचित कर देता है जो प्रणालीगत विफलता सुधारने में सबसे सक्षम हैं।"}]},"es":{"word":"disenso","question":"¿Qué obligaciones tienen los disidentes con una comunidad democrática cuyas decisiones consideran profundamente injustas?","examples":[{"en":"Dissent affirms democratic membership when it appeals to principles the community professes but fails to honor.","native":"El disenso reafirma la pertenencia democrática cuando apela a principios que la comunidad profesa, pero incumple."},{"en":"Civil disobedience makes a breach of law public and accountable rather than treating private conviction as automatic exemption.","native":"La desobediencia civil hace pública y responsable una infracción de la ley, en vez de tratar la convicción privada como una exención automática."},{"en":"A democracy that tolerates only harmless criticism deprives itself of the warnings most capable of correcting systemic failure.","native":"Una democracia que solo tolera críticas inofensivas se priva de las advertencias más capaces de corregir un fallo sistémico."}]},"zh":{"word":"异议","question":"当异议者认为民主共同体的决定极不公正时，他们对这个共同体负有哪些义务？","examples":[{"en":"Dissent affirms democratic membership when it appeals to principles the community professes but fails to honor.","native":"当异议诉诸共同体口头信奉却未能践行的原则时，它肯定了异议者的民主成员身份。"},{"en":"Civil disobedience makes a breach of law public and accountable rather than treating private conviction as automatic exemption.","native":"公民抗命使违法行为公开并接受问责，而不是把个人信念当作自动获得豁免的理由。"},{"en":"A democracy that tolerates only harmless criticism deprives itself of the warnings most capable of correcting systemic failure.","native":"只容忍无害批评的民主制度，会让自己失去最有可能纠正系统性失败的警示。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'reconciliation', 'Can reconciliation be morally credible without full agreement about the past or complete punishment of those responsible?', '{"te":{"word":"సయోధ్య","question":"గతం గురించి పూర్తి ఏకాభిప్రాయం లేకుండా, బాధ్యులందరికీ సంపూర్ణ శిక్ష విధించకుండా సయోధ్య నైతికంగా విశ్వసనీయంగా ఉండగలదా?","examples":[{"en":"Reconciliation is not collective amnesia; it requires an acknowledged record that victims are not compelled to deny.","native":"సయోధ్య సామూహిక విస్మృతి కాదు; బాధితులు తిరస్కరించాల్సిన పరిస్థితి రాని విధంగా అంగీకరించిన చారిత్రక నమోదు దానికి అవసరం."},{"en":"Truth commissions trade some retributive certainty for disclosure, but that compromise is legitimate only with meaningful repair.","native":"సత్య నిర్ధారణ సంఘాలు కొంత ప్రతీకార నిశ్చితత్వానికి బదులుగా వాస్తవ వెల్లడి సాధిస్తాయి; అయితే అర్థవంతమైన పరిహారం ఉన్నప్పుడే ఆ రాజీకి చట్టబద్ధత ఉంటుంది."},{"en":"Former adversaries may share institutions before they share memories, provided those institutions protect equal standing and future contestation.","native":"ఆ సంస్థలు సమాన హోదాను, భవిష్యత్తులో విభేదించే హక్కును కాపాడితే, పూర్వ ప్రత్యర్థులు ఉమ్మడి జ్ఞాపకాలను పంచుకోకముందే సంస్థలను పంచుకోగలరు."}]},"hi":{"word":"मेल-मिलाप","question":"क्या अतीत पर पूर्ण सहमति या जिम्मेदार लोगों को पूरा दंड दिए बिना मेल-मिलाप नैतिक रूप से विश्वसनीय हो सकता है?","examples":[{"en":"Reconciliation is not collective amnesia; it requires an acknowledged record that victims are not compelled to deny.","native":"मेल-मिलाप सामूहिक विस्मृति नहीं है; इसके लिए ऐसा स्वीकृत अभिलेख चाहिए जिसे पीड़ितों को नकारने के लिए विवश न किया जाए।"},{"en":"Truth commissions trade some retributive certainty for disclosure, but that compromise is legitimate only with meaningful repair.","native":"सत्य आयोग कुछ दंडात्मक निश्चितता के बदले तथ्य उजागर करते हैं, पर वह समझौता सार्थक क्षतिपूर्ति के साथ ही वैध होता है।"},{"en":"Former adversaries may share institutions before they share memories, provided those institutions protect equal standing and future contestation.","native":"पूर्व विरोधी साझा स्मृतियों से पहले संस्थाएँ साझा कर सकते हैं, बशर्ते वे संस्थाएँ समान दर्जे और भविष्य में असहमति के अधिकार की रक्षा करें।"}]},"es":{"word":"reconciliación","question":"¿Puede la reconciliación ser moralmente creíble sin un acuerdo pleno sobre el pasado ni un castigo completo de los responsables?","examples":[{"en":"Reconciliation is not collective amnesia; it requires an acknowledged record that victims are not compelled to deny.","native":"La reconciliación no es amnesia colectiva; exige un registro reconocido que las víctimas no se vean obligadas a negar."},{"en":"Truth commissions trade some retributive certainty for disclosure, but that compromise is legitimate only with meaningful repair.","native":"Las comisiones de la verdad intercambian cierta certeza retributiva por revelaciones, pero ese acuerdo solo es legítimo si existe una reparación significativa."},{"en":"Former adversaries may share institutions before they share memories, provided those institutions protect equal standing and future contestation.","native":"Antiguos adversarios pueden compartir instituciones antes que recuerdos, siempre que estas protejan la igualdad de condición y la posibilidad de disentir en el futuro."}]},"zh":{"word":"和解","question":"如果人们未能就过去达成完整共识，也未能彻底惩罚责任者，和解在道德上仍然可信么？","examples":[{"en":"Reconciliation is not collective amnesia; it requires an acknowledged record that victims are not compelled to deny.","native":"和解不是集体失忆；它需要一份得到承认、且受害者不会被迫否认的历史记录。"},{"en":"Truth commissions trade some retributive certainty for disclosure, but that compromise is legitimate only with meaningful repair.","native":"真相委员会以部分惩罚的确定性换取事实披露，但只有伴随实质性修复，这种妥协才具有正当性。"},{"en":"Former adversaries may share institutions before they share memories, provided those institutions protect equal standing and future contestation.","native":"昔日对手或许能在共享记忆之前先共享制度，前提是这些制度保障平等地位与未来提出异议的空间。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'retribution', 'Can retribution justify punishment independently of deterrence, rehabilitation, or protection from future harm?', '{"te":{"word":"ప్రతీకారాత్మక శిక్ష","question":"నిరోధం, పునరావాసం లేదా భవిష్యత్ హాని నుంచి రక్షణతో సంబంధం లేకుండానే ప్రతీకార న్యాయం శిక్షను సమర్థించగలదా?","examples":[{"en":"Retribution treats proportionate punishment as a response owed to wrongdoing, not merely as a tool for producing better consequences.","native":"ప్రతీకార న్యాయం అనుపాతిక శిక్షను కేవలం మెరుగైన పరిణామాలను సాధించే సాధనంగా కాకుండా, తప్పుకు ఇవ్వాల్సిన ప్రతిస్పందనగా పరిగణిస్తుంది."},{"en":"The claim that offenders deserve suffering remains incomplete until a theory explains who may impose it and within what limits.","native":"నేరస్థులు బాధను అనుభవించడానికి అర్హులనే వాదనను ఎవరు, ఏ పరిమితుల్లో ఆ బాధను విధించవచ్చో ఒక సిద్ధాంతం వివరించే వరకు అది అసంపూర్ణంగానే ఉంటుంది."},{"en":"A humane penal system must distinguish public condemnation from the desire to make another person suffer.","native":"మానవీయ శిక్షా వ్యవస్థ బహిరంగ ఖండనను మరొక వ్యక్తిని బాధపెట్టాలనే కోరిక నుంచి వేరు చేయాలి."}]},"hi":{"word":"प्रतिशोधात्मक दंड","question":"क्या प्रतिशोध, निवारण, पुनर्वास या भावी हानि से सुरक्षा से स्वतंत्र रूप से दंड को उचित ठहरा सकता है?","examples":[{"en":"Retribution treats proportionate punishment as a response owed to wrongdoing, not merely as a tool for producing better consequences.","native":"प्रतिशोधात्मक न्याय आनुपातिक दंड को केवल बेहतर परिणाम लाने का साधन नहीं, बल्कि अपराध के लिए देय प्रतिक्रिया मानता है।"},{"en":"The claim that offenders deserve suffering remains incomplete until a theory explains who may impose it and within what limits.","native":"अपराधी पीड़ा के पात्र हैं, यह दावा तब तक अधूरा रहता है जब तक कोई सिद्धांत यह न बताए कि वह पीड़ा कौन और किन सीमाओं में दे सकता है।"},{"en":"A humane penal system must distinguish public condemnation from the desire to make another person suffer.","native":"एक मानवीय दंड व्यवस्था को सार्वजनिक निंदा और किसी अन्य व्यक्ति को पीड़ा पहुँचाने की इच्छा में अंतर करना चाहिए।"}]},"es":{"word":"retribución penal","question":"¿Puede la retribución justificar el castigo con independencia de la disuasión, la rehabilitación o la protección frente a daños futuros?","examples":[{"en":"Retribution treats proportionate punishment as a response owed to wrongdoing, not merely as a tool for producing better consequences.","native":"La retribución considera el castigo proporcional una respuesta debida al delito, no un mero instrumento para producir mejores consecuencias."},{"en":"The claim that offenders deserve suffering remains incomplete until a theory explains who may impose it and within what limits.","native":"Afirmar que los infractores merecen sufrir resulta incompleto mientras una teoría no explique quién puede imponer ese sufrimiento y dentro de qué límites."},{"en":"A humane penal system must distinguish public condemnation from the desire to make another person suffer.","native":"Un sistema penal humano debe distinguir la condena pública del deseo de hacer sufrir a otra persona."}]},"zh":{"word":"报应性惩罚","question":"报应能否独立于威慑、改造或防止未来伤害等目的，为惩罚提供正当理由？","examples":[{"en":"Retribution treats proportionate punishment as a response owed to wrongdoing, not merely as a tool for producing better consequences.","native":"报应论把相称的惩罚视为对不法行为应有的回应，而不只是产生更好后果的工具。"},{"en":"The claim that offenders deserve suffering remains incomplete until a theory explains who may impose it and within what limits.","native":"在理论说明谁可以施加痛苦以及权力边界为何之前，声称违法者应当受苦仍是不完整的。"},{"en":"A humane penal system must distinguish public condemnation from the desire to make another person suffer.","native":"人道的刑罚制度必须区分公开谴责与使他人受苦的欲望。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'proportionality', 'How should proportionality be judged when harms, intentions, and unequal vulnerabilities cannot be measured on one scale?', '{"te":{"word":"అనుపాతికత","question":"హాని, ఉద్దేశాలు, అసమాన దుర్బలతలను ఒకే కొలమానంతో కొలవలేనప్పుడు అనుపాతికతను ఎలా నిర్ణయించాలి?","examples":[{"en":"Proportionality constrains power by requiring both a legitimate aim and the least excessive means capable of achieving it.","native":"చట్టబద్ధమైన లక్ష్యం, దానిని సాధించగల అవసరానికి మించని సాధనం రెండూ అవసరమని నిర్దేశించడం ద్వారా అనుపాతికత అధికారాన్ని నియంత్రిస్తుంది."},{"en":"Equal penalties can be disproportionate when the same sanction imposes radically different burdens on differently situated people.","native":"వేర్వేరు పరిస్థితుల్లో ఉన్న వ్యక్తులపై ఒకే శిక్ష పూర్తిగా భిన్నమైన భారాలను మోపినప్పుడు సమాన దండనలు కూడా అననుపాతికంగా ఉండవచ్చు."},{"en":"In war and law, numerical comparison cannot replace judgment about the moral significance of foreseeable harm.","native":"యుద్ధంలోనూ చట్టంలోనూ ముందుగా ఊహించగల హాని యొక్క నైతిక ప్రాముఖ్యతపై విచక్షణకు సంఖ్యాత్మక పోలిక ప్రత్యామ్నాయం కాలేదు."}]},"hi":{"word":"आनुपातिकता","question":"जब हानि, इरादों और असमान असुरक्षाओं को एक ही पैमाने पर नहीं मापा जा सकता, तब आनुपातिकता का आकलन कैसे किया जाना चाहिए?","examples":[{"en":"Proportionality constrains power by requiring both a legitimate aim and the least excessive means capable of achieving it.","native":"आनुपातिकता वैध लक्ष्य और उसे प्राप्त करने में सक्षम ऐसे साधन, जो आवश्यकता से अधिक कठोर न हो, दोनों की माँग करके सत्ता को सीमित करती है।"},{"en":"Equal penalties can be disproportionate when the same sanction imposes radically different burdens on differently situated people.","native":"जब एक ही दंड अलग परिस्थितियों में रहने वाले लोगों पर बिल्कुल भिन्न बोझ डालता है, तब समान दंड भी अनुपातहीन हो सकते हैं।"},{"en":"In war and law, numerical comparison cannot replace judgment about the moral significance of foreseeable harm.","native":"युद्ध और कानून में संख्यात्मक तुलना, पूर्वानुमेय हानि के नैतिक महत्त्व पर विवेकपूर्ण निर्णय का स्थान नहीं ले सकती।"}]},"es":{"word":"proporcionalidad","question":"¿Cómo debe juzgarse la proporcionalidad cuando los daños, las intenciones y las vulnerabilidades desiguales no pueden medirse en una sola escala?","examples":[{"en":"Proportionality constrains power by requiring both a legitimate aim and the least excessive means capable of achieving it.","native":"La proporcionalidad limita el poder al exigir tanto un fin legítimo como el medio menos excesivo capaz de alcanzarlo."},{"en":"Equal penalties can be disproportionate when the same sanction imposes radically different burdens on differently situated people.","native":"Las penas iguales pueden ser desproporcionadas cuando una misma sanción impone cargas radicalmente distintas a personas en situaciones diferentes."},{"en":"In war and law, numerical comparison cannot replace judgment about the moral significance of foreseeable harm.","native":"En la guerra y en el derecho, la comparación numérica no puede sustituir el juicio sobre la relevancia moral de un daño previsible."}]},"zh":{"word":"比例原则","question":"当伤害、意图和不平等的脆弱处境无法用同一尺度衡量时，应当如何判断是否合乎比例？","examples":[{"en":"Proportionality constrains power by requiring both a legitimate aim and the least excessive means capable of achieving it.","native":"比例原则要求权力既追求正当目的，又采用能够实现目的且不过度的手段，从而约束权力。"},{"en":"Equal penalties can be disproportionate when the same sanction imposes radically different burdens on differently situated people.","native":"当同一制裁给处境不同的人带来截然不同的负担时，形式相同的处罚也可能不合比例。"},{"en":"In war and law, numerical comparison cannot replace judgment about the moral significance of foreseeable harm.","native":"无论在战争还是法律中，数字比较都不能取代对可预见伤害之道德意义的判断。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'universality', 'Can moral principles claim universality without erasing the histories and contexts through which people understand them?', '{"te":{"word":"సార్వత్రికత","question":"ప్రజలు నైతిక సూత్రాలను అర్థం చేసుకునే చరిత్రలను, సందర్భాలను చెరిపివేయకుండానే ఆ సూత్రాలు సార్వత్రికతను ప్రకటించుకోగలవా?","examples":[{"en":"A universal principle gains credibility when those subject to it can contest its interpretation as equals.","native":"ఒక సార్వత్రిక సూత్రానికి లోబడి ఉన్నవారు సమానులుగా దాని వ్యాఖ్యానాన్ని సవాలు చేయగలిగినప్పుడు ఆ సూత్రం విశ్వసనీయతను పొందుతుంది."},{"en":"Human rights aspire to universality, but their application must remain attentive to institutions that make formal rights usable.","native":"మానవ హక్కులు సార్వత్రికతను ఆశిస్తాయి; అయితే లాంఛనప్రాయ హక్కులను ఆచరణలో ఉపయోగించగలిగేలా చేసే సంస్థల పట్ల వాటి అమలు శ్రద్ధ వహించాలి."},{"en":"Universality should identify a common moral floor rather than prescribe one exhaustive model of a good life.","native":"సార్వత్రికత ఒక మంచి జీవితానికి ఏకైక సమగ్ర నమూనాను నిర్దేశించడం కాకుండా, అందరికీ వర్తించే కనీస నైతిక ప్రమాణాన్ని గుర్తించాలి."}]},"hi":{"word":"सार्वभौमिकता","question":"क्या नैतिक सिद्धांत उन इतिहासों और संदर्भों को मिटाए बिना सार्वभौमिकता का दावा कर सकते हैं जिनके माध्यम से लोग उन्हें समझते हैं?","examples":[{"en":"A universal principle gains credibility when those subject to it can contest its interpretation as equals.","native":"कोई सार्वभौमिक सिद्धांत तब विश्वसनीय बनता है जब उसके अधीन लोग समान हैसियत से उसकी व्याख्या को चुनौती दे सकें।"},{"en":"Human rights aspire to universality, but their application must remain attentive to institutions that make formal rights usable.","native":"मानवाधिकार सार्वभौमिकता की आकांक्षा रखते हैं, किंतु उनके प्रयोग में उन संस्थाओं पर ध्यान रहना चाहिए जो औपचारिक अधिकारों को उपयोगी बनाती हैं।"},{"en":"Universality should identify a common moral floor rather than prescribe one exhaustive model of a good life.","native":"सार्वभौमिकता को अच्छे जीवन का एक सर्वसमावेशी नमूना निर्धारित करने के बजाय एक साझा न्यूनतम नैतिक आधार पहचानना चाहिए।"}]},"es":{"word":"universalidad","question":"¿Pueden los principios morales aspirar a la universalidad sin borrar las historias y los contextos mediante los que las personas los comprenden?","examples":[{"en":"A universal principle gains credibility when those subject to it can contest its interpretation as equals.","native":"Un principio universal gana credibilidad cuando quienes están sujetos a él pueden impugnar su interpretación en condiciones de igualdad."},{"en":"Human rights aspire to universality, but their application must remain attentive to institutions that make formal rights usable.","native":"Los derechos humanos aspiran a la universalidad, pero su aplicación debe atender a las instituciones que permiten ejercer los derechos formales."},{"en":"Universality should identify a common moral floor rather than prescribe one exhaustive model of a good life.","native":"La universalidad debe identificar un mínimo moral común en vez de prescribir un único modelo exhaustivo de la buena vida."}]},"zh":{"word":"普遍性","question":"道德原则能否在不抹去人们理解它们所凭借的历史与语境的前提下，主张自身具有普遍性？","examples":[{"en":"A universal principle gains credibility when those subject to it can contest its interpretation as equals.","native":"当受某项普遍原则约束的人能够以平等身份质疑其解释时，这项原则才更为可信。"},{"en":"Human rights aspire to universality, but their application must remain attentive to institutions that make formal rights usable.","native":"人权追求普遍性，但在落实时必须关注那些使形式权利真正可行使的制度。"},{"en":"Universality should identify a common moral floor rather than prescribe one exhaustive model of a good life.","native":"普遍性应确立共同的道德底线，而不是规定一种无所不包的美好生活模式。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'particularism', 'Does moral particularism offer sensitivity to context at the cost of reliable guidance and public justification?', '{"te":{"word":"నైతిక విశిష్టవాదం","question":"నైతిక విశిష్టవాదం నమ్మదగిన మార్గదర్శకత్వం, బహిరంగ సమర్థనలను త్యాగం చేసి సందర్భం పట్ల సున్నితత్వాన్ని అందిస్తుందా?","examples":[{"en":"Particularism holds that a feature counting as a reason in one case may lose or reverse its force in another.","native":"ఒక సందర్భంలో కారణంగా పరిగణించే లక్షణం మరొక సందర్భంలో తన బలాన్ని కోల్పోవచ్చు లేదా వ్యతిరేక బలాన్ని పొందవచ్చని విశిష్టవాదం పేర్కొంటుంది."},{"en":"Attending to context prevents rigid rules from obscuring morally decisive relationships and histories.","native":"సందర్భంపై శ్రద్ధ వహించడం నైతికంగా నిర్ణయాత్మకమైన సంబంధాలను, చరిత్రలను కఠిన నియమాలు మరుగుపరచకుండా అడ్డుకుంటుంది."},{"en":"Without some general commitments, particular judgments risk becoming inaccessible to criticism or consistent public reasoning.","native":"కొన్ని సాధారణ నిబద్ధతలు లేకపోతే, విశిష్ట నిర్ణయాలు విమర్శకు లేదా స్థిరమైన బహిరంగ తర్కానికి అందకుండా పోయే ప్రమాదం ఉంది."}]},"hi":{"word":"नैतिक विशेषवाद","question":"क्या नैतिक विशेषवाद विश्वसनीय मार्गदर्शन और सार्वजनिक औचित्य की कीमत पर संदर्भ के प्रति संवेदनशीलता प्रदान करता है?","examples":[{"en":"Particularism holds that a feature counting as a reason in one case may lose or reverse its force in another.","native":"विशेषवाद मानता है कि किसी एक मामले में कारण मानी जाने वाली विशेषता दूसरे मामले में अपना बल खो सकती है या उलट सकती है।"},{"en":"Attending to context prevents rigid rules from obscuring morally decisive relationships and histories.","native":"संदर्भ पर ध्यान देने से कठोर नियम नैतिक रूप से निर्णायक संबंधों और इतिहासों को ओझल नहीं कर पाते।"},{"en":"Without some general commitments, particular judgments risk becoming inaccessible to criticism or consistent public reasoning.","native":"कुछ सामान्य प्रतिबद्धताओं के बिना विशिष्ट निर्णयों के आलोचना या सुसंगत सार्वजनिक तर्क की पहुँच से बाहर हो जाने का जोखिम रहता है।"}]},"es":{"word":"particularismo moral","question":"¿Ofrece el particularismo moral sensibilidad al contexto a costa de una orientación fiable y una justificación pública?","examples":[{"en":"Particularism holds that a feature counting as a reason in one case may lose or reverse its force in another.","native":"El particularismo sostiene que un rasgo que cuenta como razón en un caso puede perder o invertir su fuerza en otro."},{"en":"Attending to context prevents rigid rules from obscuring morally decisive relationships and histories.","native":"Atender al contexto impide que las reglas rígidas oculten relaciones e historias moralmente decisivas."},{"en":"Without some general commitments, particular judgments risk becoming inaccessible to criticism or consistent public reasoning.","native":"Sin algunos compromisos generales, los juicios particulares corren el riesgo de quedar fuera del alcance de la crítica o del razonamiento público coherente."}]},"zh":{"word":"道德特殊主义","question":"道德特殊主义是否以牺牲可靠指导和公共论证为代价，换取了对具体语境的敏感？","examples":[{"en":"Particularism holds that a feature counting as a reason in one case may lose or reverse its force in another.","native":"特殊主义认为，在一个情形中构成理由的特征，在另一情形中可能失去效力甚至产生相反作用。"},{"en":"Attending to context prevents rigid rules from obscuring morally decisive relationships and histories.","native":"关注语境可以防止僵化规则遮蔽具有道德决定性的关系与历史。"},{"en":"Without some general commitments, particular judgments risk becoming inaccessible to criticism or consistent public reasoning.","native":"如果缺少某些一般承诺，针对具体情形的判断就可能无法接受批评，也难以纳入一致的公共推理。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'anthropocentrism', 'Is anthropocentrism unavoidable in ethical reasoning, or can nonhuman life possess value independent of human interests?', '{"te":{"word":"మానవకేంద్రవాదం","question":"నైతిక తర్కంలో మానవకేంద్రవాదం అనివార్యమా, లేక మానవ ప్రయోజనాలతో సంబంధం లేకుండానే మానవేతర జీవానికి విలువ ఉండగలదా?","examples":[{"en":"Anthropocentrism becomes ethically restrictive when ecosystems matter only insofar as their loss can be priced as human damage.","native":"పర్యావరణ వ్యవస్థల నష్టాన్ని మానవ హానిగా ధర నిర్ణయించగల మేరకే వాటికి ప్రాముఖ్యత ఇచ్చినప్పుడు మానవకేంద్రవాదం నైతికంగా సంకుచితమవుతుంది."},{"en":"Recognizing intrinsic value in nonhuman life does not eliminate human needs; it changes the burden of justifying their priority.","native":"మానవేతర జీవంలోని అంతర్గత విలువను గుర్తించడం మానవ అవసరాలను తొలగించదు; వాటికి ప్రాధాన్యం ఇవ్వడాన్ని సమర్థించాల్సిన బాధ్యతను మారుస్తుంది."},{"en":"Future ecological policy must represent beings that cannot consent, vote, or articulate claims in human institutions.","native":"సమ్మతి తెలపలేని, ఓటు వేయలేని లేదా మానవ సంస్థల్లో తమ హక్కులను వ్యక్తీకరించలేని జీవులకు భవిష్యత్ పర్యావరణ విధానం ప్రాతినిధ్యం వహించాలి."}]},"hi":{"word":"मानवकेंद्रवाद","question":"क्या नैतिक तर्क में मानवकेंद्रवाद अपरिहार्य है, या मानवेतर जीवन का मूल्य मानवीय हितों से स्वतंत्र हो सकता है?","examples":[{"en":"Anthropocentrism becomes ethically restrictive when ecosystems matter only insofar as their loss can be priced as human damage.","native":"जब पारिस्थितिक तंत्र केवल उस सीमा तक महत्त्व रखते हैं जहाँ उनके नुकसान की कीमत मानवीय क्षति के रूप में लगाई जा सके, तब मानवकेंद्रवाद नैतिक रूप से संकीर्ण हो जाता है।"},{"en":"Recognizing intrinsic value in nonhuman life does not eliminate human needs; it changes the burden of justifying their priority.","native":"मानवेतर जीवन के अंतर्निहित मूल्य को स्वीकार करना मानवीय जरूरतों को समाप्त नहीं करता; वह उनकी प्राथमिकता को उचित ठहराने का दायित्व बदल देता है।"},{"en":"Future ecological policy must represent beings that cannot consent, vote, or articulate claims in human institutions.","native":"भावी पर्यावरण नीति को उन जीवों का प्रतिनिधित्व करना होगा जो मानवीय संस्थाओं में सहमति नहीं दे सकते, मतदान नहीं कर सकते या अपने दावे व्यक्त नहीं कर सकते।"}]},"es":{"word":"antropocentrismo","question":"¿Es inevitable el antropocentrismo en el razonamiento ético o puede la vida no humana poseer un valor independiente de los intereses humanos?","examples":[{"en":"Anthropocentrism becomes ethically restrictive when ecosystems matter only insofar as their loss can be priced as human damage.","native":"El antropocentrismo se vuelve éticamente restrictivo cuando los ecosistemas solo importan en la medida en que su pérdida puede valorarse como daño humano."},{"en":"Recognizing intrinsic value in nonhuman life does not eliminate human needs; it changes the burden of justifying their priority.","native":"Reconocer un valor intrínseco en la vida no humana no elimina las necesidades humanas; cambia la carga de justificar su prioridad."},{"en":"Future ecological policy must represent beings that cannot consent, vote, or articulate claims in human institutions.","native":"La futura política ecológica debe representar a seres que no pueden consentir, votar ni formular reivindicaciones en instituciones humanas."}]},"zh":{"word":"人类中心主义","question":"伦理推理是否不可避免地以人类为中心，还是非人类生命能够拥有独立于人类利益的价值？","examples":[{"en":"Anthropocentrism becomes ethically restrictive when ecosystems matter only insofar as their loss can be priced as human damage.","native":"如果生态系统只有在其损失能够折算为人类损害时才受到重视，人类中心主义便会在伦理上变得狭隘。"},{"en":"Recognizing intrinsic value in nonhuman life does not eliminate human needs; it changes the burden of justifying their priority.","native":"承认非人类生命的内在价值并不消除人类需求，而是改变了论证这些需求应获优先地位时的举证责任。"},{"en":"Future ecological policy must represent beings that cannot consent, vote, or articulate claims in human institutions.","native":"未来的生态政策必须代表那些无法在人类制度中表示同意、投票或表达诉求的生命。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'transhumanism', 'Does transhumanism expand human freedom, or does it convert socially defined ideals of ability into technological imperatives?', '{"te":{"word":"మానవాతీతవాదం","question":"మానవాతీతవాదం మానవ స్వేచ్ఛను విస్తరిస్తుందా, లేక సామాజికంగా నిర్వచించిన సామర్థ్య ఆదర్శాలను సాంకేతిక అనివార్యతలుగా మారుస్తుందా?","examples":[{"en":"Enhancement cannot be evaluated as an individual choice when access to it may redefine what institutions treat as normal competence.","native":"మెరుగుదల సాంకేతికతను పొందగల అవకాశం, సంస్థలు సాధారణ సామర్థ్యంగా పరిగణించేదానినే పునర్నిర్వచించవచ్చు కాబట్టి దానిని కేవలం వ్యక్తిగత ఎంపికగా అంచనా వేయలేం."},{"en":"Transhumanism challenges the boundary between therapy and improvement, a boundary already shaped by culture and inequality.","native":"సంస్కృతి, అసమానత ఇప్పటికే రూపుదిద్దిన చికిత్స, మెరుగుదలల మధ్య సరిహద్దును మానవాతీతవాదం సవాలు చేస్తుంది."},{"en":"A just enhancement policy must ask who sets the desired traits and who bears the risks of becoming obsolete.","native":"కోరుకున్న లక్షణాలను ఎవరు నిర్ణయిస్తారు, కాలం చెల్లినవారిగా మారే ప్రమాదాన్ని ఎవరు భరిస్తారు అని న్యాయమైన మానవ మెరుగుదల విధానం ప్రశ్నించాలి."}]},"hi":{"word":"मानवातीतवाद","question":"क्या मानवातीतवाद मानवीय स्वतंत्रता का विस्तार करता है, या क्षमता के सामाजिक रूप से निर्धारित आदर्शों को तकनीकी अनिवार्यताओं में बदल देता है?","examples":[{"en":"Enhancement cannot be evaluated as an individual choice when access to it may redefine what institutions treat as normal competence.","native":"जब संवर्धन तक पहुँच यह पुनर्परिभाषित कर सकती है कि संस्थाएँ किसे सामान्य क्षमता मानती हैं, तब उसका मूल्यांकन केवल व्यक्तिगत पसंद के रूप में नहीं किया जा सकता।"},{"en":"Transhumanism challenges the boundary between therapy and improvement, a boundary already shaped by culture and inequality.","native":"मानवातीतवाद उपचार और संवर्धन के बीच की उस सीमा को चुनौती देता है जिसे संस्कृति और असमानता पहले ही आकार दे चुकी हैं।"},{"en":"A just enhancement policy must ask who sets the desired traits and who bears the risks of becoming obsolete.","native":"एक न्यायपूर्ण संवर्धन नीति को पूछना चाहिए कि वांछित गुण कौन तय करता है और अप्रासंगिक हो जाने का जोखिम कौन उठाता है।"}]},"es":{"word":"transhumanismo","question":"¿Amplía el transhumanismo la libertad humana o convierte ideales de capacidad definidos socialmente en imperativos tecnológicos?","examples":[{"en":"Enhancement cannot be evaluated as an individual choice when access to it may redefine what institutions treat as normal competence.","native":"La mejora no puede evaluarse como una elección individual cuando acceder a ella puede redefinir lo que las instituciones consideran una capacidad normal."},{"en":"Transhumanism challenges the boundary between therapy and improvement, a boundary already shaped by culture and inequality.","native":"El transhumanismo cuestiona la frontera entre terapia y mejora, una frontera ya moldeada por la cultura y la desigualdad."},{"en":"A just enhancement policy must ask who sets the desired traits and who bears the risks of becoming obsolete.","native":"Una política de mejora justa debe preguntar quién determina los rasgos deseables y quién asume el riesgo de quedar obsoleto."}]},"zh":{"word":"超人类主义","question":"超人类主义是在拓展人类自由，还是把由社会定义的能力理想变成技术上的强制要求？","examples":[{"en":"Enhancement cannot be evaluated as an individual choice when access to it may redefine what institutions treat as normal competence.","native":"当能否获得增强技术可能重新定义制度所认可的正常能力时，就不能只把增强视为个人选择。"},{"en":"Transhumanism challenges the boundary between therapy and improvement, a boundary already shaped by culture and inequality.","native":"超人类主义挑战治疗与增强之间的界线，而这条界线早已受到文化和不平等的塑造。"},{"en":"A just enhancement policy must ask who sets the desired traits and who bears the risks of becoming obsolete.","native":"公正的增强政策必须追问：谁来设定理想特征，又由谁承担变得过时的风险。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'mortality', 'How does awareness of mortality shape meaning without proving that either finitude or immortality would make life worthwhile?', '{"te":{"word":"మరణశీలత","question":"పరిమిత జీవితం లేదా అమరత్వం జీవితాన్ని సార్థకం చేస్తాయని రుజువు చేయకుండానే, మరణశీలతపై అవగాహన జీవితార్థాన్ని ఎలా రూపుదిద్దుతుంది?","examples":[{"en":"Mortality gives choices urgency because committing to one path closes possibilities that cannot all be recovered.","native":"ఒక మార్గానికి కట్టుబడటం తిరిగి పొందలేని ఇతర అవకాశాలను మూసివేస్తుంది కాబట్టి మరణశీలత ఎంపికలకు అత్యవసరతను ఇస్తుంది."},{"en":"Fear of death concerns not only nonexistence but also unfinished relationships and the loss of control over one''s story.","native":"మరణ భయం ఉనికి లేకపోవడం గురించి మాత్రమే కాదు; అసంపూర్ణ సంబంధాలు, ఒకరి జీవిత కథపై నియంత్రణ కోల్పోవడం గురించి కూడా ఉంటుంది."},{"en":"An indefinitely extended life might postpone endings while leaving the problem of what deserves devotion unresolved.","native":"అనిర్దిష్టంగా పొడిగించిన జీవితం ముగింపులను వాయిదా వేయవచ్చు; అయితే దేనికి అంకితం కావడం తగినదనే సమస్యను పరిష్కరించకుండానే వదిలివేయవచ్చు."}]},"hi":{"word":"मरणशीलता","question":"मरणशीलता का बोध अर्थ को कैसे आकार देता है, जबकि वह यह सिद्ध नहीं करता कि सीमितता या अमरता में से कोई भी जीवन को सार्थक बना देगी?","examples":[{"en":"Mortality gives choices urgency because committing to one path closes possibilities that cannot all be recovered.","native":"मरणशीलता विकल्पों को तात्कालिकता देती है, क्योंकि किसी एक राह के प्रति प्रतिबद्ध होना उन संभावनाओं को बंद करता है जिन्हें पूरी तरह वापस नहीं पाया जा सकता।"},{"en":"Fear of death concerns not only nonexistence but also unfinished relationships and the loss of control over one''s story.","native":"मृत्यु का भय केवल अस्तित्वहीनता से नहीं, बल्कि अधूरे संबंधों और अपनी कहानी पर नियंत्रण खोने से भी जुड़ा है।"},{"en":"An indefinitely extended life might postpone endings while leaving the problem of what deserves devotion unresolved.","native":"अनिश्चित काल तक बढ़ाया गया जीवन अंत को टाल सकता है, फिर भी यह प्रश्न अनसुलझा छोड़ सकता है कि समर्पण के योग्य क्या है।"}]},"es":{"word":"mortalidad","question":"¿Cómo moldea el sentido la conciencia de la mortalidad sin demostrar que la finitud o la inmortalidad harían que la vida mereciera la pena?","examples":[{"en":"Mortality gives choices urgency because committing to one path closes possibilities that cannot all be recovered.","native":"La mortalidad imprime urgencia a las elecciones porque comprometerse con un camino cierra posibilidades que no pueden recuperarse por completo."},{"en":"Fear of death concerns not only nonexistence but also unfinished relationships and the loss of control over one''s story.","native":"El miedo a la muerte no atañe solo a dejar de existir, sino también a las relaciones inconclusas y a perder el control sobre la propia historia."},{"en":"An indefinitely extended life might postpone endings while leaving the problem of what deserves devotion unresolved.","native":"Una vida prolongada indefinidamente podría aplazar los finales y dejar sin resolver qué merece nuestra entrega."}]},"zh":{"word":"必死性","question":"对必死性的认识如何塑造意义，而又不证明有限生命或永生中的任何一种必然让人生值得度过？","examples":[{"en":"Mortality gives choices urgency because committing to one path closes possibilities that cannot all be recovered.","native":"必死性使选择具有紧迫感，因为投身一条道路会关闭那些无法全部挽回的可能性。"},{"en":"Fear of death concerns not only nonexistence but also unfinished relationships and the loss of control over one''s story.","native":"对死亡的恐惧不仅关乎不复存在，也关乎未完成的关系以及失去对自身故事的掌控。"},{"en":"An indefinitely extended life might postpone endings while leaving the problem of what deserves devotion unresolved.","native":"无限延长的生命或许能推迟终结，却仍未解决什么值得人投入毕生心力的问题。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'transcendence', 'Can transcendence be understood without invoking a supernatural realm, as an orientation beyond immediate self-interest?', '{"te":{"word":"అతీతత్వం","question":"అతీంద్రియ లోకాన్ని ప్రస్తావించకుండా, తక్షణ స్వప్రయోజనాన్ని మించిన దిశానిర్దేశంగా అతీతత్వాన్ని అర్థం చేసుకోవచ్చా?","examples":[{"en":"Transcendence may arise when a person locates private suffering within a purpose that exceeds personal survival.","native":"వ్యక్తిగత మనుగడను మించిన లక్ష్యంలో తన వ్యక్తిగత బాధకు స్థానం కల్పించినప్పుడు ఒకరిలో అతీతత్వం ఉద్భవించవచ్చు."},{"en":"Art can interrupt habitual perception and disclose possibilities that ordinary instrumental reasoning overlooks.","native":"కళ అలవాటైన గ్రహణాన్ని నిలిపివేసి, సాధారణ సాధనాత్మక తర్కం విస్మరించే అవకాశాలను వెల్లడించగలదు."},{"en":"Secular transcendence remains vulnerable to becoming another absolute unless it preserves doubt and plurality.","native":"సందేహాన్ని, బహుళత్వాన్ని కాపాడుకోకపోతే లౌకిక అతీతత్వం మరొక నిరపేక్ష సత్యంగా మారే ప్రమాదంలో ఉంటుంది."}]},"hi":{"word":"अतिक्रमण","question":"क्या किसी अलौकिक लोक का आह्वान किए बिना अतिक्रमण को तात्कालिक स्वार्थ से परे उन्मुखता के रूप में समझा जा सकता है?","examples":[{"en":"Transcendence may arise when a person locates private suffering within a purpose that exceeds personal survival.","native":"अतिक्रमण तब उत्पन्न हो सकता है जब कोई व्यक्ति निजी पीड़ा को व्यक्तिगत अस्तित्व से बड़े किसी उद्देश्य में स्थान देता है।"},{"en":"Art can interrupt habitual perception and disclose possibilities that ordinary instrumental reasoning overlooks.","native":"कला अभ्यस्त अनुभूति को बाधित करके उन संभावनाओं को प्रकट कर सकती है जिन्हें सामान्य साधनपरक तर्क अनदेखा कर देता है।"},{"en":"Secular transcendence remains vulnerable to becoming another absolute unless it preserves doubt and plurality.","native":"यदि वह संदेह और बहुलता को सुरक्षित न रखे, तो लौकिक अतिक्रमण के एक और निरपेक्ष सत्य बन जाने का खतरा रहता है।"}]},"es":{"word":"trascendencia","question":"¿Puede entenderse la trascendencia, sin invocar un ámbito sobrenatural, como una orientación más allá del interés propio inmediato?","examples":[{"en":"Transcendence may arise when a person locates private suffering within a purpose that exceeds personal survival.","native":"La trascendencia puede surgir cuando una persona sitúa su sufrimiento privado dentro de un propósito que excede la supervivencia personal."},{"en":"Art can interrupt habitual perception and disclose possibilities that ordinary instrumental reasoning overlooks.","native":"El arte puede interrumpir la percepción habitual y revelar posibilidades que el razonamiento instrumental ordinario pasa por alto."},{"en":"Secular transcendence remains vulnerable to becoming another absolute unless it preserves doubt and plurality.","native":"La trascendencia secular corre el riesgo de convertirse en otro absoluto si no preserva la duda y la pluralidad."}]},"zh":{"word":"超越","question":"能否不诉诸超自然领域，而把超越理解为一种朝向即时自我利益之外的取向？","examples":[{"en":"Transcendence may arise when a person locates private suffering within a purpose that exceeds personal survival.","native":"当一个人把自身痛苦置于超越个人生存的目标之中时，超越或许由此产生。"},{"en":"Art can interrupt habitual perception and disclose possibilities that ordinary instrumental reasoning overlooks.","native":"艺术可以打断习惯性的感知，并揭示普通工具理性所忽视的可能性。"},{"en":"Secular transcendence remains vulnerable to becoming another absolute unless it preserves doubt and plurality.","native":"世俗的超越若不能保留怀疑与多元性，就仍有可能变成另一种绝对。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
INSERT INTO questions (cefr_level, prompt_word, question_text, translations) VALUES ('C2', 'absurdity', 'If the universe offers no final justification, why need the resulting absurdity entail resignation rather than defiant commitment?', '{"te":{"word":"అసంబద్ధత","question":"విశ్వం అంతిమ సమర్థనను ఇవ్వకపోతే, దాని నుంచి ఉద్భవించే అసంబద్ధత ధిక్కారపూర్వక నిబద్ధతకు బదులుగా నిరాశతో తలవంచడానికే ఎందుకు దారితీయాలి?","examples":[{"en":"The absurd emerges from the collision between the human demand for intelligibility and a world that supplies no final answer.","native":"అర్థం కావాలనే మానవ ఆకాంక్ష, అంతిమ సమాధానం ఇవ్వని ప్రపంచం పరస్పరం ఢీకొన్నప్పుడు అసంబద్ధత ఉద్భవిస్తుంది."},{"en":"Revolt against absurdity consists in living lucidly without disguising uncertainty as cosmic purpose.","native":"అనిశ్చితిని విశ్వ ప్రయోజనంగా ముసుగు వేయకుండా స్పష్టమైన ఎరుకతో జీవించడమే అసంబద్ధతపై తిరుగుబాటు."},{"en":"Shared projects can generate local meaning even when no universal narrative guarantees their ultimate significance.","native":"ఏ సార్వత్రిక కథనమూ వాటి అంతిమ ప్రాముఖ్యతకు హామీ ఇవ్వకపోయినా, ఉమ్మడి ప్రయత్నాలు సందర్భోచిత అర్థాన్ని సృష్టించగలవు."}]},"hi":{"word":"असंगति","question":"यदि ब्रह्मांड कोई अंतिम औचित्य नहीं देता, तो उससे उत्पन्न असंगति को विद्रोही प्रतिबद्धता के बजाय समर्पण ही क्यों आवश्यक बनाना चाहिए?","examples":[{"en":"The absurd emerges from the collision between the human demand for intelligibility and a world that supplies no final answer.","native":"असंगति उस मानवीय माँग और संसार के टकराव से उत्पन्न होती है जिसमें मनुष्य बोधगम्यता चाहता है, पर संसार कोई अंतिम उत्तर नहीं देता।"},{"en":"Revolt against absurdity consists in living lucidly without disguising uncertainty as cosmic purpose.","native":"अनिश्चितता को ब्रह्मांडीय उद्देश्य का मुखौटा पहनाए बिना स्पष्ट चेतना के साथ जीना ही असंगति के विरुद्ध विद्रोह है।"},{"en":"Shared projects can generate local meaning even when no universal narrative guarantees their ultimate significance.","native":"जब कोई सार्वभौमिक आख्यान उनके अंतिम महत्त्व की गारंटी नहीं देता, तब भी साझा प्रयास संदर्भगत अर्थ उत्पन्न कर सकते हैं।"}]},"es":{"word":"absurdo","question":"Si el universo no ofrece una justificación definitiva, ¿por qué el absurdo resultante habría de implicar resignación en vez de un compromiso desafiante?","examples":[{"en":"The absurd emerges from the collision between the human demand for intelligibility and a world that supplies no final answer.","native":"El absurdo surge de la colisión entre la exigencia humana de inteligibilidad y un mundo que no ofrece una respuesta definitiva."},{"en":"Revolt against absurdity consists in living lucidly without disguising uncertainty as cosmic purpose.","native":"La rebelión contra el absurdo consiste en vivir con lucidez sin disfrazar la incertidumbre de propósito cósmico."},{"en":"Shared projects can generate local meaning even when no universal narrative guarantees their ultimate significance.","native":"Los proyectos compartidos pueden generar un sentido local aunque ninguna narrativa universal garantice su significado último."}]},"zh":{"word":"荒诞性","question":"如果宇宙并不提供终极理由，由此产生的荒诞为何必然导向顺从，而不能激发反抗性的投入？","examples":[{"en":"The absurd emerges from the collision between the human demand for intelligibility and a world that supplies no final answer.","native":"荒诞源于人类对可理解性的要求与一个不提供终极答案的世界之间的碰撞。"},{"en":"Revolt against absurdity consists in living lucidly without disguising uncertainty as cosmic purpose.","native":"反抗荒诞意味着清醒地生活，而不把不确定性伪装成宇宙目的。"},{"en":"Shared projects can generate local meaning even when no universal narrative guarantees their ultimate significance.","native":"即使没有普遍叙事保证其终极意义，共同事业仍能产生局部而具体的意义。"}]}}'::jsonb) ON CONFLICT (cefr_level, prompt_word) DO UPDATE SET question_text = EXCLUDED.question_text, translations = EXCLUDED.translations;
